		soa_structs:                           map[string]bool{}
		declared_type_scope_keys:              map[string]bool{}
		struct_error_embeds_shadow_builtin:    map[string]bool{}
		struct_generic_params:                 map[string][]string{}
		struct_implements:                     map[string][]string{}
