		visible_mutation_cache:                  new_visible_mutation_cache()
		type_interner:                           type_interner
		symbols:                                 symbols
	}
}

// fork_program_view builds a checker view over immutable, compilation-wide
// semantic data. Mutable scope, diagnostics, sparse caches, and function state
// start private. Dependency-map ownership is explicit: parallel workers pass
// a fresh map, while a synchronous subview may keep recording in its owning
// checker's private map. Keeping this constructor explicit prevents a
// newly-added mutable field from being silently shared by parallel workers.
fn (tc &TypeChecker) fork_program_view(ast &flat.FlatAst, direct_dependencies_by_fn map[int][]SymbolId) TypeChecker {
	fs := new_scope(tc.file_scope)
	return TypeChecker{
		a:                                  ast
		enable_globals:                     tc.enable_globals
		fn_ret_types:                       tc.fn_ret_types
		fn_param_types:                     tc.fn_param_types
		fn_shared_params:                   tc.fn_shared_params
		mut_receiver_methods:               tc.mut_receiver_methods
		source_no_body_fns:                 tc.source_no_body_fns
		unsafe_fns:                         tc.unsafe_fns
		fn_ret_type_texts:                  tc.fn_ret_type_texts
		fn_param_type_texts:                tc.fn_param_type_texts
		fn_type_files:                      tc.fn_type_files
		fn_type_modules:                    tc.fn_type_modules
		fn_generic_params:                  tc.fn_generic_params
		specialized_generic_fns:            tc.specialized_generic_fns
		fn_variadic:                        tc.fn_variadic
		c_variadic_fns:                     tc.c_variadic_fns
		fn_implicit_veb_ctx:                tc.fn_implicit_veb_ctx
		receiver_method_suffix_index:       tc.receiver_method_suffix_index
		structs:                            tc.structs
		struct_modules:                     tc.struct_modules
		struct_files:                       tc.struct_files
		declared_type_scope_keys:           tc.declared_type_scope_keys
		struct_error_embeds_shadow_builtin: tc.struct_error_embeds_shadow_builtin
		struct_generic_params:              tc.struct_generic_params
		struct_implements:                  tc.struct_implements
		struct_shared_fields:               tc.struct_shared_fields
		struct_field_c_abi_fns:             tc.struct_field_c_abi_fns
		generic_method_value_info:          tc.generic_method_value_info
		params_structs:                     tc.params_structs
		c_typedef_structs:                  tc.c_typedef_structs
		unions:                             tc.unions
		type_aliases:                       tc.type_aliases
		type_alias_generic_params:          tc.type_alias_generic_params
		type_alias_c_abi_fns:               tc.type_alias_c_abi_fns
		sum_types:                          tc.sum_types
		sum_generic_params:                 tc.sum_generic_params
		enum_names:                         tc.enum_names
		enum_fields:                        tc.enum_fields
		flag_enums:                         tc.flag_enums
		interface_names:                    tc.interface_names
		interface_generic_params:           tc.interface_generic_params
		interface_fields:                   tc.interface_fields
		interface_embeds:                   tc.interface_embeds
		interface_abstract_methods:         tc.interface_abstract_methods
		interface_method_names_index:       tc.interface_method_names_index
		interface_abstract_index:           tc.interface_abstract_index
		interface_field_list_index:         tc.interface_field_list_index
		interface_impl_indexes:             tc.interface_impl_indexes
		interface_query_indexes_ready:      tc.interface_query_indexes_ready
		c_globals:                          tc.c_globals
		global_names:                       tc.global_names
		const_types:                        tc.const_types
		const_exprs:                        tc.const_exprs
		const_modules:                      tc.const_modules
		const_files:                        tc.const_files
		const_suffixes:                     tc.const_suffixes
		declaration_visibility:             tc.declaration_visibility
		imports:                            tc.imports
		file_imports:                       tc.file_imports
		file_selective_imports:             tc.file_selective_imports
		file_imports_by_file:               tc.file_imports_by_file
		file_modules:                       tc.file_modules
		translated_files:                   tc.translated_files
		has_globals_files:                  tc.has_globals_files
		deprecated_symbols:                 tc.deprecated_symbols
		file_scope:                         fs
		cur_scope:                          fs
		scope_pool:                         []&Scope{}
		has_builtins:                       tc.has_builtins
		cur_module:                         tc.cur_module
		cur_file:                           tc.cur_file
		errors:                             []TypeError{}
		notices:                            []TypeError{}
		resolved_call_names:                tc.resolved_call_names
		resolved_call_set:                  tc.resolved_call_set
		resolved_fn_value_names:            tc.resolved_fn_value_names
		resolved_fn_value_set:              tc.resolved_fn_value_set
		statement_nodes:                    tc.statement_nodes
		direct_dependencies_by_fn:          direct_dependencies_by_fn
		method_values_by_fn:                tc.method_values_by_fn
		cur_comptime_variant_loop_vars:     tc.cur_comptime_variant_loop_vars
		expr_type_values:                   tc.expr_type_values
		expr_type_set:                      tc.expr_type_set
		checking_nodes:                     tc.checking_nodes
		sparse_resolved_call_names:         map[int]string{}
		sparse_resolved_fn_values:          map[int]string{}
		sparse_statement_nodes:             map[int]bool{}
		sparse_expr_type_values:            map[int]Type{}
		sparse_checking_nodes:              map[int]bool{}
		diagnose_unknown_calls:             tc.diagnose_unknown_calls
		reject_unlowered_map_mutation:      tc.reject_unlowered_map_mutation
		reject_unsupported_generics:        tc.reject_unsupported_generics
		checker_fixture_mode:               tc.checker_fixture_mode
		suppress_dump_output:               tc.suppress_dump_output
		diagnostic_files:                   tc.diagnostic_files
		multiple_module_import_lines:       tc.multiple_module_import_lines
		source_texts_by_file:               tc.source_texts_by_file
		has_spawn_expr:                     tc.has_spawn_expr
		inactive_top_level_node_ids:        tc.inactive_top_level_node_ids
		selected_file_called_fns:           tc.selected_file_called_fns
		selected_file_worklist:             tc.selected_file_worklist
		defer_ierror_gating:                tc.defer_ierror_gating
		pending_ierror_errors:              []PendingIerrorError{}
		top_level_idx:                      tc.top_level_idx
		top_level_idx_nodes_len:            tc.top_level_idx_nodes_len
		expected_expr_id:                   -1
		expected_expr_type:                 Type(void_)
		smartcasts:                         tc.smartcasts
		ownership:                          tc.ownership
		selfhost:                           tc.selfhost
		fn_context:                         new_function_check_context()
		resolution_type_views:              &ResolutionTypeViewCache{
			by_file: map[string]&TypeChecker{}
		}
		visible_mutation_cache:             tc.visible_mutation_cache
		type_interner:                      tc.type_interner
		symbols:                            tc.symbols
	}
}

// fork_for_parallel_codegen returns a complete read-only semantic view with
// private scope and memoization state for one C-generation worker.
pub fn (tc &TypeChecker) fork_for_parallel_codegen() &TypeChecker {
	mut forked := tc.fork_program_view(tc.a, map[int][]SymbolId{})
	// Cgen resolves locals in child scopes but must keep the checked file scope
	// as the immutable root shared by all workers.
	forked.file_scope = tc.file_scope
	forked.cur_scope = new_scope(tc.file_scope)
	forked.errors = tc.errors.clone()
	forked.parallel_check_sparse = tc.parallel_check_sparse
	forked.check_range_lo = tc.check_range_lo
	forked.check_range_hi = tc.check_range_hi
	// These sparse transform results are immutable by cgen. Share their backing
	// maps just like the node-indexed semantic arrays in fork_program_view.
	unsafe {
		forked.sparse_resolved_call_names = tc.sparse_resolved_call_names
		forked.sparse_resolved_fn_values = tc.sparse_resolved_fn_values
		forked.sparse_statement_nodes = tc.sparse_statement_nodes
		forked.sparse_expr_type_values = tc.sparse_expr_type_values
		forked.sparse_checking_nodes = tc.sparse_checking_nodes
	}
	forked.visible_mutation_cache = unsafe { nil }
	forked.inherit_ownership_codegen_metadata_from(tc)
	forked.set_fresh_type_cache_based_on(tc, tc.type_cache_parse_enabled())
	if !isnil(tc.qualify_name_cache) {
		// Never share the memo across threads; each fork owns a private one.
		forked.qualify_name_cache = &QualifyNameCache{}
	}
	return &forked
}

// fork_type_parse_view creates a lookup-only view in an explicit source
// context. It shares the compilation's immutable indexes, interner, and
// synchronous memoization cache, but none of the caller's function state.
fn (tc &TypeChecker) fork_type_parse_view(file string, module_name string) TypeChecker {
	mut view := tc.fork_program_view(tc.a, map[int][]SymbolId{})
	view.cur_file = file
	view.cur_module = module_name
	view.type_cache = tc.type_cache
	return view
}

// fork_smartcast_query_view preserves the active lexical/function context for
// a synchronous expression-type query while owning every mutable map it may
// consult. This avoids inheriting unrelated checker state through a whole
// struct copy.
fn (tc &TypeChecker) fork_smartcast_query_view() TypeChecker {
	// This query is synchronous, so any dependency it discovers remains owned
	// by the current master/worker checker rather than crossing worker threads.
	mut view := tc.fork_program_view(tc.a, tc.direct_dependencies_by_fn)
	view.file_scope = tc.file_scope
	view.cur_scope = tc.cur_scope
	view.scope_pool = tc.scope_pool
	view.scope_pool_index = tc.scope_pool_index
	view.expected_expr_id = tc.expected_expr_id
	view.expected_expr_type = tc.expected_expr_type
	view.fn_context = clone_function_check_context(tc.fn_context)
	view.smartcasts = clone_smartcasts(tc.smartcasts)
	view.type_cache = tc.type_cache
	return view
}

// fork_for_parallel_transform returns a TypeChecker that shares all of `tc`'s
// read-only data (semantic maps and node-indexed cache arrays, which the transform
// pass only reads) but owns a fresh, private `type_cache` and a private AST view.
// During transform the only hidden mutation a TypeChecker performs through its `&`
// receiver is memoization into `type_cache` (parse_type / c_type); giving each
// worker its own cache makes concurrent use race-free without cloning the large
// semantic maps. `ast` must be the worker's own (cloned) FlatAst so that any
// expr_type lookup on a freshly-created node id indexes a valid array.
pub fn (tc &TypeChecker) fork_for_parallel_transform(ast &flat.FlatAst) &TypeChecker {
	mut forked := tc.fork_program_view(ast, map[int][]SymbolId{})
	// Visible-mutation analysis only runs during checking. Do not allocate its
	// three private maps for the many short-lived transform forks.
	forked.visible_mutation_cache = unsafe { nil }
	if check_memos_enabled() {
		// Per-fork memos; the fork (and these caches) live inside one batch
		// scope, so cached scratch-arena strings can never outlive their arena.
		forked.import_info_cache = &ImportInfoCache{}
		forked.qualify_name_cache = &QualifyNameCache{}
	}
	// The transformer propagates call/fn-value resolution metadata onto the call
	// nodes it clones (Transformer.copy_cloned_resolution). In a worker those
	// writes must not touch (or grow/realloc) the shared node-indexed arrays
	// while other threads read them, so each fork gets a private sparse overlay:
	// writes go only to the overlay, reads check it before the shared arrays,
	// and merge_worker replays the entries into the master under shifted ids.
	forked.fork_overlay = &TransformForkOverlay{}
	// Transform helpers allocate inside disposable arenas. A shared interner
	// would let one helper publish map/array storage owned by its arena and leave
	// other helpers with dangling storage when that arena is released. Each
	// helper therefore gets a private canonical table; semantic Type values are
	// still compatible across tables, while TypeIds stay local to its cache.
	forked.type_interner = new_type_interner()
	forked.symbols = new_symbol_interner()
	forked.type_cache = &TypeCache{
		// When the master froze its warm cache behind an overlay (see
		// freeze_type_cache_for_forks), every fork shares that frozen cache as
		// its read-only base instead of re-deriving each memoized type.
		base:                       if tc.type_cache != unsafe { nil } {
			tc.type_cache.base
		} else {
			&TypeCache(unsafe { nil })
		}
		parse_enabled:              if tc.type_cache != unsafe { nil } {
			tc.type_cache.parse_enabled
		} else {
			false
		}
		parse_entries:              map[u64]ParseTypeCacheEntry{}
		c_entries:                  map[TypeId]string{}
		struct_field_entries:       map[string]Type{}
		struct_field_misses:        map[string]bool{}
		ierror_compat_entries:      map[string]int{}
		source_error_embed_entries: map[string]int{}
	}
	return &forked
}

// freeze_type_cache_for_forks freezes this checker's warm type cache as the
// shared read-only base for parallel forks (fork_for_parallel_transform picks
// it up) and switches the checker itself to a private overlay so its own
// memoization writes cannot race fork reads. Callable on a shared reference:
// the transformer holds the checker as `&TypeChecker`.
pub fn (tc &TypeChecker) freeze_type_cache_for_forks() {
	mut mtc := unsafe { &TypeChecker(voidptr(tc)) }
	mtc.install_type_cache_overlay()
}

// unfreeze_type_cache_after_forks folds the private overlay back into the
// frozen base once every fork has been joined, and reattaches the base as the
// live cache.
pub fn (tc &TypeChecker) unfreeze_type_cache_after_forks() {
	mut mtc := unsafe { &TypeChecker(voidptr(tc)) }
	mtc.restore_type_cache_base()
}

// set_fresh_type_cache attaches a new empty TypeCache. Parallel-cgen worker
// checkers use this so the lazily-built lookup indexes and memoizations work
// per worker instead of falling back to their uncached full scans.
pub fn (mut tc TypeChecker) set_fresh_type_cache(parse_enabled bool) {
	if isnil(tc.type_interner) {
		tc.type_interner = new_type_interner()
	}
	if isnil(tc.symbols) {
		tc.symbols = new_symbol_interner()
	}
	if !isnil(tc.pre_transform_type_cache) {
		tc.type_cache = tc.pre_transform_type_cache
		tc.pre_transform_type_cache = unsafe { nil }
		mut cache := tc.type_cache
		cache.base = unsafe { nil }
		cache.parse_enabled = parse_enabled
		cache.parse_hits = 0
		cache.parse_misses = 0
		cache.c_hits = 0
		cache.c_misses = 0
		cache.parse_entries.clear()
		cache.parse_context_valid = false
		cache.parse_last_valid = false
		cache.c_entries.clear()
		cache.c_name_entries.clear()
		cache.struct_field_entries.clear()
		cache.struct_field_misses.clear()
		cache.ierror_compat_entries.clear()
		cache.interface_impl_entries.clear()
		cache.source_error_embed_entries.clear()
		cache.source_error_embed_indexed = false
		cache.ierror_impl_names.clear()
		cache.ierror_impl_names_set = false
		cache.short_type_name_index.clear()
		cache.short_type_name_index_built = false
		cache.local_fn_decl_index.clear()
		cache.local_fn_decl_indexed_len = 0
		cache.local_fn_decl_last_module = ''
		return
	}
	tc.type_cache = &TypeCache{
		parse_enabled: parse_enabled
	}
}

// reset_type_interners replaces semantic interners whose backing storage may
// have grown inside a disposable compiler-stage arena.
pub fn (mut tc TypeChecker) reset_type_interners() {
	tc.type_interner = new_type_interner()
	tc.symbols = new_symbol_interner()
}

// set_fresh_type_cache_based_on attaches a new empty TypeCache that falls back
// read-only to `src`'s frozen base cache (see freeze_type_cache_for_forks), so
// parallel-cgen workers start with every type memoized by the check/transform
// phases instead of re-deriving them from a cold cache.
pub fn (mut tc TypeChecker) set_fresh_type_cache_based_on(src &TypeChecker, parse_enabled bool) {
	base := if isnil(src.type_cache) {
		&TypeCache(unsafe { nil })
	} else if !isnil(src.type_cache.base) {
		src.type_cache.base
	} else {
		src.type_cache
	}
	tc.type_cache = &TypeCache{
		parse_enabled: parse_enabled
		base:          base
	}
	// C-generation workers can also use disposable arenas. Keep their TypeIds
	// private instead of publishing arena-backed interner storage globally.
	tc.type_interner = new_type_interner()
	tc.symbols = new_symbol_interner()
}

// type_cache_parse_enabled reports whether parse_type memoization is enabled
// on this checker's type cache.
pub fn (tc &TypeChecker) type_cache_parse_enabled() bool {
	return !isnil(tc.type_cache) && tc.type_cache.parse_enabled
}

pub fn (tc &TypeChecker) clear_field_lookup_cache() {
	mut cache := tc.type_cache
	if isnil(cache) {
		return
	}
	cache.struct_field_entries.clear()
	cache.struct_field_misses.clear()
}

// clear_c_type_cache invalidates C spellings after monomorphization changes
// concrete type identities and adds materialized generic types.
pub fn (tc &TypeChecker) clear_c_type_cache() {
	mut cache := tc.type_cache
	if isnil(cache) {
		return
	}
	cache.c_entries.clear()
	cache.c_name_entries.clear()
	if !isnil(cache.base) {
		mut base := cache.base
		base.c_entries.clear()
		base.c_name_entries.clear()
	}
}

// clear_interface_impl_cache invalidates memoized implementer lists after a type-table change.
pub fn (tc &TypeChecker) clear_interface_impl_cache() {
	mut cache := tc.type_cache
	if isnil(cache) {
		return
	}
	cache.interface_impl_entries.clear()
}

// free_parallel_transform_caches releases private memoization maps owned by a forked
// transform checker and leaves it valid if it is accidentally read again.
pub fn (mut tc TypeChecker) free_parallel_transform_caches() {
	parse_enabled := if tc.type_cache != unsafe { nil } {
		tc.type_cache.parse_enabled
	} else {
		false
	}
	if tc.type_cache != unsafe { nil } {
		unsafe {
			tc.type_cache.parse_entries.free()
			tc.type_cache.c_entries.free()
			tc.type_cache.struct_field_entries.free()
			tc.type_cache.struct_field_misses.free()
			tc.type_cache.ierror_compat_entries.free()
			tc.type_cache.interface_impl_entries.free()
			tc.type_cache.source_error_embed_entries.free()
		}
	}
	tc.type_cache = &TypeCache{
		parse_enabled:              parse_enabled
		parse_entries:              map[u64]ParseTypeCacheEntry{}
		c_entries:                  map[TypeId]string{}
		struct_field_entries:       map[string]Type{}
		struct_field_misses:        map[string]bool{}
		ierror_compat_entries:      map[string]int{}
		source_error_embed_entries: map[string]int{}
	}
}

// reset_node_caches updates reset node caches state for types.
fn (mut tc TypeChecker) reset_node_caches(n int) {
	tc.resolved_call_names = []string{len: n}
	tc.resolved_call_set = []bool{len: n}
	tc.resolved_fn_value_names = []string{len: n}
	tc.resolved_fn_value_set = []bool{len: n}
	tc.statement_nodes = []bool{len: n}
	// No init fill: every read of expr_type_values is guarded by expr_type_set,
	// so unset slots are never returned, and skipping the ~1M-element fill loop
	// keeps this a plain zeroed allocation.
	tc.expr_type_values = unsafe { []Type{len: n} }
	tc.expr_type_set = []bool{len: n}
	tc.checking_nodes = []bool{len: n}
	tc.parallel_check_sparse = false
}

fn (mut tc TypeChecker) extend_node_caches(n int) {
	if tc.parallel_check_sparse {
		return
	}
	if n <= tc.resolved_call_names.len && n <= tc.resolved_fn_value_names.len
		&& n <= tc.statement_nodes.len && n <= tc.expr_type_values.len && n <= tc.checking_nodes.len {
		return
	}
	extend_string_cache(mut tc.resolved_call_names, n)
	extend_bool_cache(mut tc.resolved_call_set, n)
	extend_string_cache(mut tc.resolved_fn_value_names, n)
	extend_bool_cache(mut tc.resolved_fn_value_set, n)
	extend_bool_cache(mut tc.statement_nodes, n)
	extend_type_cache(mut tc.expr_type_values, n)
	extend_bool_cache(mut tc.expr_type_set, n)
	extend_bool_cache(mut tc.checking_nodes, n)
}

// reserve_transform_node_caches reserves node-indexed semantic storage before
// a scoped transform starts, keeping the escaping slabs in the compilation arena.
pub fn (mut tc TypeChecker) reserve_transform_node_caches(n int) {
	reserve_string_cache(mut tc.resolved_call_names, n)
	reserve_bool_cache(mut tc.resolved_call_set, n)
	reserve_string_cache(mut tc.resolved_fn_value_names, n)
	reserve_bool_cache(mut tc.resolved_fn_value_set, n)
	reserve_bool_cache(mut tc.statement_nodes, n)
	reserve_type_cache(mut tc.expr_type_values, n)
	reserve_bool_cache(mut tc.expr_type_set, n)
	reserve_bool_cache(mut tc.checking_nodes, n)
}

// materialize_sparse_transform_node_caches compacts transform-created semantic
// entries into dense node-indexed arrays and reserves their expected final
// capacity before monomorphization appends more nodes.
pub fn (mut tc TypeChecker) materialize_sparse_transform_node_caches(n int, capacity int) {
	if !tc.parallel_check_sparse {
		tc.reserve_transform_node_caches(capacity)
		tc.extend_node_caches(n)
		return
	}
	target_cap := if capacity > n { capacity } else { n }
	tc.reserve_transform_node_caches(target_cap)
	tc.parallel_check_sparse = false
	tc.extend_node_caches(n)
	for idx, name in tc.sparse_resolved_call_names {
		if idx >= 0 && idx < n {
			tc.resolved_call_names[idx] = name
			tc.resolved_call_set[idx] = true
		}
	}
	for idx, name in tc.sparse_resolved_fn_values {
		if idx >= 0 && idx < n {
			tc.resolved_fn_value_names[idx] = name
			tc.resolved_fn_value_set[idx] = true
		}
	}
	for idx, is_statement in tc.sparse_statement_nodes {
		if is_statement && idx >= 0 && idx < n {
			tc.statement_nodes[idx] = true
		}
	}
	for idx, typ in tc.sparse_expr_type_values {
		if idx >= 0 && idx < n {
			tc.expr_type_values[idx] = typ
			tc.expr_type_set[idx] = true
		}
	}
	tc.sparse_resolved_call_names = map[int]string{}
	tc.sparse_resolved_fn_values = map[int]string{}
	tc.sparse_statement_nodes = map[int]bool{}
	tc.sparse_expr_type_values = map[int]Type{}
	tc.sparse_checking_nodes = map[int]bool{}
}

// reserve_scoped_transform_metadata keeps tables that receive escaping
// transform additions in the compilation arena in the common case while
// scratch allocations use a disposable arena. The signature maps are rebuilt
// after promotion, so this headroom is an optimization rather than an
// ownership requirement.
pub fn (mut tc TypeChecker) reserve_scoped_transform_metadata(signature_headroom int) {
	tc.fn_ret_types.reserve(u32(tc.fn_ret_types.len + signature_headroom))
	tc.fn_param_types.reserve(u32(tc.fn_param_types.len + signature_headroom))
	tc.fn_variadic.reserve(u32(tc.fn_variadic.len + signature_headroom))
	tc.specialized_generic_fns.reserve(u32(tc.specialized_generic_fns.len + signature_headroom))
	if !isnil(tc.type_interner) {
		mut interner := tc.type_interner
		interner.reserve(signature_headroom)
	}
	if !isnil(tc.symbols) {
		mut symbols := tc.symbols
		symbols.reserve(signature_headroom)
	}
}

// rebuild_scoped_transform_signature_maps moves signature maps, keys, and nested
// type metadata into the current arena after a disposable transform scope has
// been left.
pub fn (mut tc TypeChecker) rebuild_scoped_transform_signature_maps() {
	mut ret_types := map[string]Type{}
	for name, ret in tc.fn_ret_types {
		ret_types[name.clone()] = clone_owned_type(ret)
	}
	mut param_types := map[string][]Type{}
	for name, params in tc.fn_param_types {
		param_types[name.clone()] = clone_owned_types(params)
	}
	mut variadic := map[string]bool{}
	for name, is_variadic in tc.fn_variadic {
		variadic[name.clone()] = is_variadic
	}
	mut specialized := map[string]bool{}
	for name, is_specialized in tc.specialized_generic_fns {
		specialized[name.clone()] = is_specialized
	}
	tc.fn_ret_types = ret_types.move()
	tc.fn_param_types = param_types.move()
	tc.fn_variadic = variadic.move()
	tc.specialized_generic_fns = specialized.move()
}

// begin_sparse_transform_node_caches keeps source-node entries in their dense
// checked arrays and records transform-created node metadata sparsely.
pub fn (mut tc TypeChecker) begin_sparse_transform_node_caches(base_nodes int) {
	tc.parallel_check_sparse = true
	tc.check_range_lo = 0
	tc.check_range_hi = base_nodes - 1
	if tc.scope_parallel_check_workers && isnil(tc.pre_transform_type_cache)
		&& !isnil(tc.type_cache) {
		tc.pre_transform_type_cache = tc.type_cache
		tc.type_cache = &TypeCache{
			base:          tc.pre_transform_type_cache
			parse_enabled: tc.pre_transform_type_cache.parse_enabled
		}
	}
}

// promote_scoped_transform_interners moves additions made by a scoped
// transform into the current compilation arena before that scope is freed.
pub fn (mut tc TypeChecker) promote_scoped_transform_interners(type_start int, symbol_start int, scope voidptr) {
	if !isnil(tc.type_interner) {
		mut interner := tc.type_interner
		interner.promote_from(type_start, scope)
	}
	if !isnil(tc.symbols) {
		mut symbols := tc.symbols
		symbols.promote_from(symbol_start, scope)
	}
}

fn reserve_string_cache(mut values []string, n int) {
	if n > values.cap {
		unsafe { values.grow_cap(n - values.cap) }
	}
}

fn reserve_bool_cache(mut values []bool, n int) {
	if n > values.cap {
		unsafe { values.grow_cap(n - values.cap) }
	}
}

fn reserve_type_cache(mut values []Type, n int) {
	if n > values.cap {
		unsafe { values.grow_cap(n - values.cap) }
	}
}

fn extend_string_cache(mut values []string, n int) {
	if n > values.len {
		values << []string{len: n - values.len}
	}
}

fn extend_bool_cache(mut values []bool, n int) {
	if n > values.len {
		values << []bool{len: n - values.len}
	}
}

fn extend_type_cache(mut values []Type, n int) {
	if n > values.len {
		values << []Type{len: n - values.len, init: Type(void_)}
	}
}

// push_scope updates push scope state for TypeChecker.
pub fn (mut tc TypeChecker) push_scope() {
	tc.cur_scope = tc.reuse_scope(tc.cur_scope)
	$if ownership ? {
		tc.ownership_push_scope()
	}
}

// pop_scope updates pop scope state for TypeChecker.
pub fn (mut tc TypeChecker) pop_scope() {
	if tc.cur_scope == unsafe { nil } {
		return
	}
	parent := tc.cur_scope.parent
	if parent == unsafe { nil } {
		return
	}
	$if ownership ? {
		tc.ownership_run_scope_defers()
		tc.ownership_pop_scope()
	}
	if tc.scope_pool_index > 0 && tc.cur_scope == tc.scope_pool[tc.scope_pool_index - 1] {
		tc.scope_pool_index--
	}
	tc.cur_scope = parent
}

// reuse_scope supports reuse scope handling for TypeChecker.
fn (mut tc TypeChecker) reuse_scope(parent &Scope) &Scope {
	if tc.scope_pool_index < tc.scope_pool.len {
		mut scope := tc.scope_pool[tc.scope_pool_index]
		scope.reset(parent)
		tc.scope_pool_index++
		return scope
	}
	scope := new_scope(parent)
	tc.scope_pool << scope
	tc.scope_pool_index++
	return scope
}

// record_error supports record error handling for TypeChecker.
fn (mut tc TypeChecker) record_error(kind TypeErrorKind, msg string, node flat.NodeId) {
	if !tc.should_diagnose(node) {
		return
	}
	tc.errors << TypeError{
		msg:        msg
		kind:       kind
		node:       node
		file:       tc.cur_file
		node_kind:  if int(node) >= 0 && int(node) < tc.a.nodes.len {
			tc.a.nodes[int(node)].kind.str()
		} else {
			''
		}
		node_value: if int(node) >= 0 && int(node) < tc.a.nodes.len {
			tc.a.nodes[int(node)].value
		} else {
			''
		}
		node_pos:   tc.node_position_string(node)
		pos:        tc.node_pos(node)
	}
}

fn (mut tc TypeChecker) record_error_unfiltered(kind TypeErrorKind, msg string, node flat.NodeId) {
	tc.errors << tc.make_type_error(kind, msg, node)
}

fn (tc &TypeChecker) make_type_error(kind TypeErrorKind, msg string, node flat.NodeId) TypeError {
	return tc.make_type_error_at(kind, msg, node, tc.node_pos(node))
}

fn (tc &TypeChecker) make_type_error_at(kind TypeErrorKind, msg string, node flat.NodeId, pos token.Pos) TypeError {
	return TypeError{
		msg:        msg.replace('[fn(', '[fn (')
		kind:       kind
		node:       node
		file:       tc.cur_file
		node_kind:  if int(node) >= 0 && int(node) < tc.a.nodes.len {
			tc.a.nodes[int(node)].kind.str()
		} else {
			''
		}
		node_value: if int(node) >= 0 && int(node) < tc.a.nodes.len {
			tc.a.nodes[int(node)].value
		} else {
			''
		}
		node_pos:   tc.node_position_string(node)
		pos:        pos
	}
}

fn (mut tc TypeChecker) record_error_at(kind TypeErrorKind, msg string, node flat.NodeId, pos token.Pos) {
	if !tc.should_diagnose(node) {
		return
	}
	tc.errors << tc.make_type_error_at(kind, msg, node, pos)
}

fn (mut tc TypeChecker) record_error_severity_at(kind TypeErrorKind, msg string, node flat.NodeId, pos token.Pos, severity string) {
	if !tc.should_diagnose(node) {
		return
	}
	base := tc.make_type_error_at(kind, msg, node, pos)
	tc.errors << TypeError{
		...base
		severity: severity
	}
}

// record_cgen_error_at records a post-transform validation error with cgen severity.
pub fn (mut tc TypeChecker) record_cgen_error_at(msg string, node flat.NodeId, source_id flat.NodeId, marker string) {
	tc.record_error_severity_at(.compile_error, msg, node, tc.propagation_operator_pos(source_id,
		node, marker), 'cgen error:')
}

fn (mut tc TypeChecker) record_error_with_details_at(kind TypeErrorKind, msg string, node flat.NodeId, pos token.Pos, details []string) {
	if !tc.should_diagnose(node) {
		return
	}
	base := tc.make_type_error_at(kind, msg, node, pos)
	tc.errors << TypeError{
		...base
		details: details.clone()
	}
}

fn (mut tc TypeChecker) record_notice_at(kind TypeErrorKind, msg string, node flat.NodeId, pos token.Pos) {
	if !tc.should_diagnose(node) {
		return
	}
	if tc.notices.any(it.kind == kind && it.msg == msg && it.pos == pos) {
		return
	}
	tc.notices << tc.make_type_error_at(kind, msg, node, pos)
}

fn (mut tc TypeChecker) record_notice_with_details_at(kind TypeErrorKind, msg string, node flat.NodeId, pos token.Pos, details []string) {
	if !tc.should_diagnose(node) {
		return
	}
	if tc.notices.any(it.kind == kind && it.msg == msg && it.pos == pos) {
		return
	}
	base := tc.make_type_error_at(kind, msg, node, pos)
	tc.notices << TypeError{
		...base
		details: details.clone()
	}
}

fn (mut tc TypeChecker) record_warning_at(kind TypeErrorKind, msg string, node flat.NodeId, pos token.Pos) {
	if !tc.should_diagnose(node) {
		return
	}
	if tc.notices.any(it.kind == kind && it.msg == msg && it.pos == pos && it.severity == 'warning:') {
		return
	}
	base := tc.make_type_error_at(kind, msg, node, pos)
	tc.notices << TypeError{
		...base
		severity: 'warning:'
	}
}

fn (tc &TypeChecker) has_type_error(kind TypeErrorKind, msg string, node flat.NodeId) bool {
	return tc.errors.any(it.kind == kind && it.msg == msg && it.node == node)
}

fn (tc &TypeChecker) has_type_notice(kind TypeErrorKind, msg string, node flat.NodeId) bool {
	return tc.notices.any(it.kind == kind && it.msg == msg && it.node == node)
}

fn (tc &TypeChecker) node_pos(node flat.NodeId) token.Pos {
	if int(node) < 0 || int(node) >= tc.a.nodes.len {
		return token.Pos{}
	}
	return tc.a.nodes[int(node)].pos
}

fn (tc &TypeChecker) node_position_string(node flat.NodeId) string {
	if int(node) < 0 || int(node) >= tc.a.nodes.len {
		return ''
	}
	pos := tc.a.nodes[int(node)].pos
	if source_pos := tc.a.source_position(pos) {
		return source_pos.str()
	}
	return pos.str()
}

fn (mut tc TypeChecker) record_unsupported_generic(msg string, node flat.NodeId) {
	if !tc.should_diagnose_unsupported_generic(node) {
		return
	}
	tc.errors << TypeError{
		msg:  msg
		kind: .unsupported_generic
		node: node
		pos:  tc.node_pos(node)
	}
}

fn split_sum_variant_texts(text string) []string {
	mut parts := []string{}
	mut start := 0
	mut depth := 0
	for i in 0 .. text.len {
		ch := text[i]
		if ch == `[` || ch == `(` || ch == `{` {
			depth++
		} else if ch == `]` || ch == `)` || ch == `}` {
			if depth > 0 {
				depth--
			}
		} else if ch == `|` && depth == 0 {
			part := trimmed_space(text[start..i])
			if part.len > 0 {
				parts << part
			}
			start = i + 1
		}
	}
	part := trimmed_space(text[start..])
	if part.len > 0 {
		parts << part
	}
	return parts
}

// collect supports collect handling for TypeChecker.
fn file_index_usable(a &flat.FlatAst) bool {
	return a.file_node_ids.len > 0 && a.file_node_ids.len % 2 == 0 && !a.file_index_incomplete
		&& os.getenv('V3_NO_FILE_IDX') == ''
}

// collect_top_level_idx_fast rebuilds the top-level declaration index from the
// parser-recorded (marker, trailing) .file node pairs instead of scanning every
// AST node: the trailing file node's children are exactly the file's top-level
// declarations (with comptime_if/block containers descended in child order,
// which matches ascending node-id order). Output must stay identical to the
// full scan in collect().
fn (mut tc TypeChecker) collect_top_level_idx_fast(a &flat.FlatAst, inactive []bool) {
	if inactive.len > 0 {
		// The scan records every flagged id (whole inactive subtrees, consumed
		// by prune_inactive_top_level_comptime).
		for i, f in inactive {
			if f {
				tc.inactive_top_level_node_ids << i
			}
		}
	}
	for k := 0; k + 1 < a.file_node_ids.len; k += 2 {
		marker := a.file_node_ids[k]
		trailing := a.file_node_ids[k + 1]
		idx_file := a.nodes[marker].value
		tc.top_level_idx << marker
		tnode := a.nodes[trailing]
		mut idx_module := ''
		mut synthetic_scan_start := marker + 1
		for ci in 0 .. tnode.children_count {
			decl_idx := int(a.child(&tnode, ci))
			for synthetic_idx in synthetic_scan_start .. decl_idx {
				synthetic := a.nodes[synthetic_idx]
				if synthetic.kind == .struct_decl && (is_anonymous_struct_name(synthetic.value)
					|| synthetic.value.contains('@local@')) {
					idx_module = tc.collect_index_child(a, synthetic_idx, idx_file, idx_module,
						inactive)
				}
			}
			idx_module = tc.collect_index_child(a, decl_idx, idx_file, idx_module, inactive)
			synthetic_scan_start = decl_idx + 1
			// apply_decl_attrs emits module attributes as the node immediately
			// following the module declaration, outside the trailing file node's
			// declaration children.
			attr_idx := decl_idx + 1
			if decl_idx >= 0 && decl_idx < a.nodes.len && a.nodes[decl_idx].kind == .module_decl
				&& attr_idx < trailing {
				attr_node := a.nodes[attr_idx]
				if attr_node.kind == .directive && attr_node.value == '@attributes:${decl_idx}' {
					idx_module = tc.collect_index_child(a, attr_idx, idx_file, idx_module, inactive)
				}
			}
		}
		for synthetic_idx in synthetic_scan_start .. trailing {
			synthetic := a.nodes[synthetic_idx]
			if synthetic.kind == .struct_decl && (is_anonymous_struct_name(synthetic.value)
				|| synthetic.value.contains('@local@')) {
				idx_module = tc.collect_index_child(a, synthetic_idx, idx_file, idx_module,
					inactive)
			}
		}
		tc.top_level_idx << trailing
	}
}

fn (mut tc TypeChecker) collect_module_attributes(node flat.Node, file string) {
	for attr in node.generic_params() {
		match attr.all_before(':').trim_space() {
			'translated' {
				tc.translated_files[file] = true
			}
			'has_globals' {
				tc.has_globals_files[file] = true
			}
			else {}
		}
	}
}

fn (mut tc TypeChecker) collect_module_attributes_from_nodes(a &flat.FlatAst) {
	for node in a.nodes {
		if node.kind != .directive || !node.value.starts_with('@attributes:') {
			continue
		}
		decl_idx := node.value['@attributes:'.len..].int()
		if decl_idx < 0 || decl_idx >= a.nodes.len {
			continue
		}
		decl := a.nodes[decl_idx]
		if decl.kind != .module_decl {
			continue
		}
		file := a.source_files[decl.pos.id] or { continue }
		tc.collect_module_attributes(node, file.name)
	}
}

fn (mut tc TypeChecker) check_insert_directive(id flat.NodeId, node flat.Node, file string, module_name string) {
	if node.value == 'flag' && node.typ.contains('`') {
		saved_file := tc.cur_file
		saved_module := tc.cur_module
		tc.cur_file = file
		tc.cur_module = if module_name.len > 0 { module_name } else { 'main' }
		flag := node.typ.trim_space()
		tc.record_error_at(.compile_error,
			'bad #flag `${flag}`: shell command substitution with backticks is not supported; use #pkgconfig or explicit flags instead',
			id, node.pos)
		tc.cur_file = saved_file
		tc.cur_module = saved_module
		return
	}
	if node.value != 'insert' || node.typ.len < 2 || file.len == 0 {
		return
	}
	raw_target := node.typ.trim_space()
	target := raw_target.trim('"').trim("'")
	mut resolved := target
	if target.starts_with('@VEXEROOT') {
		absolute_file := os.real_path(file)
		if marker := absolute_file.index('/vlib/') {
			resolved = absolute_file[..marker] + target['@VEXEROOT'.len..]
		}
	} else if !os.is_abs_path(target) {
		resolved = os.join_path(os.dir(file), target)
	}
	if os.exists(resolved) {
		return
	}
	saved_file := tc.cur_file
	saved_module := tc.cur_module
	tc.cur_file = file
	tc.cur_module = if module_name.len > 0 { module_name } else { 'main' }
	tc.record_error_at(.compile_error,
		'The file ${raw_target}, needed for insertion by module `${tc.cur_module}`, does not exist.',
		id, node.pos)
	tc.cur_file = saved_file
	tc.cur_module = saved_module
}

fn (mut tc TypeChecker) collect_index_child(a &flat.FlatAst, i int, idx_file string, idx_module string, inactive []bool) string {
	if i < 0 || i >= a.nodes.len {
		return idx_module
	}
	if inactive.len > 0 && i < inactive.len && inactive[i] {
		return idx_module
	}
	node := a.nodes[i]
	match node.kind {
		.directive {
			tc.check_insert_directive(flat.NodeId(i), node, idx_file, idx_module)
			if idx_file.len > 0 && node.value.starts_with('@attributes:') {
				decl_idx := node.value['@attributes:'.len..].int()
				if decl_idx >= 0 && decl_idx < a.nodes.len && a.nodes[decl_idx].kind == .module_decl {
					tc.collect_module_attributes(node, idx_file)
				}
			}
		}
		.module_decl {
			tc.top_level_idx << i
			return node.value
		}
		.struct_decl {
			if node.value == 'string' {
				tc.has_builtins = true
			}
			tc.declared_type_scope_keys[scope_type_key(idx_file, idx_module, node.value)] = true
			tc.top_level_idx << i
		}
		.type_decl, .interface_decl, .enum_decl {
			tc.declared_type_scope_keys[scope_type_key(idx_file, idx_module, node.value)] = true
			tc.top_level_idx << i
		}
		.import_decl, .const_decl, .global_decl, .fn_decl, .c_fn_decl {
			tc.top_level_idx << i
		}
		.comptime_if, .block {
			// Top-level $if containers hold declarations the full scan reaches
			// by node order; descend in child order (same ascending ids).
			mut inner_module := idx_module
			for ci in 0 .. node.children_count {
				inner_module = tc.collect_index_child(a, int(a.child(&node, ci)), idx_file,
					inner_module, inactive)
			}
			return inner_module
		}
		else {}
	}
	return idx_module
}

pub fn (mut tc TypeChecker) collect(a &flat.FlatAst) {
	mut ck_c_sw := time.new_stopwatch()
	tc.a = a
	tc.visible_mutation_cache = new_visible_mutation_cache()
	tc.has_spawn_expr = -1
	tc.direct_dependencies_by_fn = map[int][]SymbolId{}
	tc.file_scope = new_scope(unsafe { nil })
	tc.cur_scope = tc.file_scope
	tc.scope_pool_index = 0
	tc.reset_node_caches(a.nodes.len)
	$if ownership ? {
		tc.ownership_reset()
	}
	tc.type_cache = &TypeCache{
		parse_entries:              map[u64]ParseTypeCacheEntry{}
		c_entries:                  map[TypeId]string{}
		struct_field_entries:       map[string]Type{}
		struct_field_misses:        map[string]bool{}
		ierror_compat_entries:      map[string]int{}
		source_error_embed_entries: map[string]int{}
	}
	// One full declaration scan: build the top-level declaration index that every
	// later pass of the check step iterates instead of re-streaming all nodes,
	// detect builtins, and index every source-level type declaration by
	// (file, module, name) so `source_declares_type_in_scope` is an O(1) map
	// lookup instead of a full node scan. The type-scope index is built before
	// pass 1 because pass 1 already calls qualify_name, which depends on it.
	// No later phase adds declarations, so both indexes stay complete for the
	// whole compile.
	tc.declared_type_scope_keys = map[string]bool{}
	tc.translated_files = map[string]bool{}
	tc.has_globals_files = map[string]bool{}
	tc.top_level_idx = []int{cap: 65536}
	tc.prepare_threads_condition()
	inactive_comptime_nodes := tc.inactive_top_level_comptime_nodes()
	tc.inactive_top_level_node_ids.clear()
	if file_index_usable(a) {
		tc.collect_top_level_idx_fast(a, inactive_comptime_nodes)
		tc.top_level_idx_nodes_len = a.nodes.len
		tc.timing_profile('  [ttime]     ck c idx       ${f64(ck_c_sw.elapsed().microseconds()) / 1000.0:7.2f} ms (fast)')
		tc.collect_after_index(a)
		return
	}
	mut idx_file := ''
	mut idx_module := ''
	for i, node in a.nodes {
		if inactive_comptime_nodes.len > 0 && inactive_comptime_nodes[i] {
			tc.inactive_top_level_node_ids << i
			continue
		}
		match node.kind {
			.file {
				idx_file = node.value
				idx_module = ''
				tc.top_level_idx << i
			}
			.directive {
				tc.check_insert_directive(flat.NodeId(i), node, idx_file, idx_module)
				if idx_file.len > 0 && node.value.starts_with('@attributes:') {
					decl_idx := node.value['@attributes:'.len..].int()
					if decl_idx >= 0 && decl_idx < a.nodes.len
						&& a.nodes[decl_idx].kind == .module_decl {
						tc.collect_module_attributes(node, idx_file)
					}
				}
			}
			.module_decl {
				idx_module = node.value
				tc.top_level_idx << i
			}
			.struct_decl {
				if node.value == 'string' {
					tc.has_builtins = true
				}
				tc.declared_type_scope_keys[scope_type_key(idx_file, idx_module, node.value)] = true
				tc.top_level_idx << i
			}
			.type_decl, .interface_decl, .enum_decl {
				tc.declared_type_scope_keys[scope_type_key(idx_file, idx_module, node.value)] = true
				tc.top_level_idx << i
			}
			.import_decl, .const_decl, .global_decl, .fn_decl, .c_fn_decl {
				tc.top_level_idx << i
			}
			else {}
		}
	}
	tc.top_level_idx_nodes_len = a.nodes.len
	tc.timing_profile('  [ttime]     ck c idx       ${f64(ck_c_sw.elapsed().microseconds()) / 1000.0:7.2f} ms')
	tc.collect_after_index(a)
}

fn (mut tc TypeChecker) check_alias_declaration_cycles() {
	mut module_name := ''
	mut seen_types := map[string]bool{}
	for index in tc.top_level_idx {
		node := tc.a.nodes[index]
		if node.kind == .module_decl {
			module_name = node.value
			continue
		}
		if node.kind in [.struct_decl, .type_decl, .interface_decl, .enum_decl] {
			qname := qualify_decl_name_in_module(node.value, module_name)
			if seen_types[qname] {
				continue
			}
			seen_types[qname] = true
		}
		if node.kind != .type_decl || node.children_count > 0 || node.typ.len == 0 {
			continue
		}
		name := node.value
		container := recursive_alias_container(name, node.typ)
		if container.len > 0 {
			tc.recursive_alias_names[name] = true
			tc.errors << tc.make_type_error_at(.unknown_type,
				'recursive declarations of aliases are not allowed - the alias `${name}` is used in the ${container}',
				flat.NodeId(index), node.pos)
			continue
		}
		target := trimmed_space(node.typ)
		if !is_plain_type_symbol(target) || !tc.alias_chain_reaches(name, target, 0) {
			continue
		}
		tc.recursive_alias_names[name] = true
		tc.errors << tc.make_type_error_at(.unknown_type,
			'alias `${name}` forms a cycle through `${target}`', flat.NodeId(index), node.pos)
	}
}

fn (tc &TypeChecker) alias_chain_reaches(start string, current string, depth int) bool {
	if current == start {
		return true
	}
	if depth >= tc.type_aliases.len {
		return false
	}
	target := tc.type_aliases[current] or { return false }
	clean := trimmed_space(target)
	if !is_plain_type_symbol(clean) {
		return false
	}
	return tc.alias_chain_reaches(start, clean, depth + 1)
}

fn recursive_alias_container(name string, type_text string) string {
	clean := trimmed_space(type_text)
	if !type_text_contains_symbol(clean, name) {
		return ''
	}
	if clean.starts_with('[]') {
		return 'array'
	}
	if clean.starts_with('[') {
		close := clean.index_u8(`]`)
		if close > 1 {
			return 'fixed array'
		}
	}
	if clean.starts_with('map[') {
		close := find_matching_bracket(clean, 3)
		if close > 3 {
			if type_text_contains_symbol(clean[4..close], name) {
				return 'map key'
			}
			if close + 1 < clean.len && type_text_contains_symbol(clean[close + 1..], name) {
				return 'map value'
			}
		}
	}
	return ''
}

fn type_text_contains_symbol(type_text string, name string) bool {
	if name.len == 0 || type_text.len < name.len {
		return false
	}
	mut start := 0
	for {
		relative := type_text[start..].index(name) or { return false }
		index := start + relative
		before_ok := index == 0 || !is_type_symbol_byte(type_text[index - 1])
		end := index + name.len
		after_ok := end == type_text.len || !is_type_symbol_byte(type_text[end])
		if before_ok && after_ok {
			return true
		}
		start = index + name.len
		if start >= type_text.len {
			return false
		}
	}
	return false
}

fn is_type_symbol_byte(ch u8) bool {
	return ch.is_alnum() || ch in [`_`, `.`]
}

fn is_plain_type_symbol(type_text string) bool {
	if type_text.len == 0 {
		return false
	}
	for ch in type_text {
		if !is_type_symbol_byte(ch) {
			return false
		}
	}
	return true
}

fn (mut tc TypeChecker) register_declaration_visibility(node flat.Node) {
	visibility := DeclarationVisibility{
		module_name: tc.cur_module
		kind:        node.kind
		is_pub:      node.op == .arrow
	}
	match node.kind {
		.fn_decl {
			name := checker_qualified_fn_name(tc.cur_module, node.value)
			tc.declaration_visibility[name] = visibility
			if tc.cur_module == 'builtin' && visibility.is_pub {
				tc.declaration_visibility['builtin.${node.value}'] = visibility
			}
		}
		.struct_decl, .type_decl, .interface_decl, .enum_decl {
			name := qualify_decl_name_in_module(node.value, tc.cur_module)
			tc.declaration_visibility[name] = visibility
		}
		.const_decl {
			for i in 0 .. node.children_count {
				field := tc.a.child_node(&node, i)
				if field.kind != .const_field {
					continue
				}
				name := qualify_decl_name_in_module(field.value, tc.cur_module)
				tc.declaration_visibility[name] = visibility
			}
		}
		else {}
	}
}

// collect_after_index runs collection passes 1 and 2 plus the resolution tail
// over the already-built top-level index (shared by the fast file-index path
// and the full-scan fallback in collect()).
fn (mut tc TypeChecker) collect_after_index(a &flat.FlatAst) {
	mut ck_c_sw := time.new_stopwatch()
	tc.collect_module_attributes_from_nodes(a)
	tc.index_multiple_module_import_lines(a)
	// Pass 1: collect type-level names (aliases, enums, sum types)
	for tl_idx in tc.top_level_idx {
		node := a.nodes[tl_idx]
		tc.register_declaration_visibility(node)
		match node.kind {
			.file {
				tc.enter_file(node.value)
			}
			.module_decl {
				tc.enter_module(node.value)
			}
			.import_decl {
				tc.imports[node.typ] = node.value
				tc.register_file_import(node.typ, node.value)
				tc.register_selective_imports(node)
			}
			.enum_decl {
				qn := tc.qualify_decl_name(node.value)
				tc.enum_names[qn] = true
				mut fields := []string{}
				for i in 0 .. node.children_count {
					f := a.child_node(&node, i)
					if f.kind == .enum_field {
						fields << escaped_identifier_name(f.value)
					}
				}
				tc.enum_fields[qn] = fields
				if node.typ == 'flag' {
					tc.flag_enums[qn] = true
				}
			}
			.struct_decl {
				qname := tc.qualify_decl_name(node.value)
				if qname !in tc.structs {
					tc.structs[qname] = []StructField{}
				}
				tc.struct_modules[qname] = tc.cur_module
				tc.struct_files[qname] = tc.cur_file
				if node.generic_params().len > 0 {
					tc.struct_generic_params[qname] = node.generic_params().clone()
					if qname != node.value {
						tc.struct_generic_params[node.value] = node.generic_params().clone()
					}
				}
				implements_types := struct_decl_implements_from_typ(node.typ)
				if implements_types.len > 0 {
					tc.struct_implements[qname] = implements_types
				}
				if 'union' in node.typ.split(',') {
					tc.unions[qname] = true
				}
				if 'params' in node.typ.split(',') {
					tc.params_structs[qname] = true
				}
				if 'soa' in node.typ.split(',') {
					tc.soa_structs[qname] = true
				}
				if 'typedef' in node.typ.split(',') {
					tc.c_typedef_structs[qname] = true
					tc.c_typedef_structs[node.value] = true
				}
			}
			.type_decl {
				if node.children_count > 0 {
					mut variants := []string{}
					for i in 0 .. node.children_count {
						v := a.child_node(&node, i)
						variants << tc.qualify_sum_variant_name(v.value, node.generic_params())
					}
					qname := tc.qualify_decl_name(node.value)
					tc.sum_types[qname] = variants
					if node.generic_params().len > 0 {
						tc.sum_generic_params[qname] = node.generic_params().clone()
						if qname != node.value {
							tc.sum_generic_params[node.value] = node.generic_params().clone()
						}
					}
				} else if node.typ.len > 0 {
					sum_variant_texts := split_sum_variant_texts(node.typ)
					if sum_variant_texts.len > 1 {
						mut variants := []string{}
						for part in sum_variant_texts {
							variants << tc.qualify_sum_variant_name(part, node.generic_params())
						}
						qname := tc.qualify_decl_name(node.value)
						tc.sum_types[qname] = variants
						if node.generic_params().len > 0 {
							tc.sum_generic_params[qname] = node.generic_params().clone()
							if qname != node.value {
								tc.sum_generic_params[node.value] = node.generic_params().clone()
							}
						}
						continue
					}
					qname := tc.qualify_decl_name(node.value)
					generic_params := node.generic_params()
					alias_target := if generic_params.len > 0 {
						tc.qualify_type_text_with_generic_params(node.typ, generic_params)
					} else {
						tc.qualify_type_text(node.typ)
					}
					tc.type_aliases[qname] = alias_target
					if generic_params.len > 0 {
						tc.type_alias_generic_params[qname] = generic_params.clone()
						if qname != node.value {
							tc.type_alias_generic_params[node.value] = generic_params.clone()
						}
					}
					if c_abi_fn := tc.c_abi_fn_ptr_type_from_text(node.typ) {
						tc.type_alias_c_abi_fns[qname] = c_abi_fn
					}
					if tc.cur_module in ['', 'main', 'builtin'] && node.value !in tc.type_aliases {
						tc.type_aliases[node.value] = alias_target
						if generic_params.len > 0 {
							tc.type_alias_generic_params[node.value] = generic_params.clone()
						}
						if c_abi_fn := tc.c_abi_fn_ptr_type_from_text(node.typ) {
							tc.type_alias_c_abi_fns[node.value] = c_abi_fn
						}
					}
				}
			}
			.interface_decl {
				qname := tc.qualify_decl_name(node.value)
				tc.interface_names[qname] = true
				if node.generic_params().len > 0 {
					tc.interface_generic_params[qname] = node.generic_params().clone()
					if tc.cur_module in ['', 'main', 'builtin'] && qname != node.value {
						tc.interface_generic_params[node.value] = node.generic_params().clone()
					}
				}
			}
			.c_fn_decl {
				if !node.value.starts_with('C.') {
					qname := tc.qualify_decl_name(node.value)
					tc.source_no_body_fns[qname] = true
					if tc.cur_module in ['', 'main'] {
						tc.source_no_body_fns[node.value] = true
					}
				}
			}
			else {}
		}
	}
	tc.check_alias_declaration_cycles()
	// Pass 1 can parse callback aliases before later modules with same-named
	// types have been indexed. Rebuild name-derived caches from the complete
	// declaration table before collecting concrete signatures in pass 2.
	tc.type_cache.c_entries.clear()
	tc.type_cache.c_name_entries.clear()
	tc.invalidate_short_type_name_index()
	tc.check_c_struct_redeclarations(a)
	tc.check_c_fn_redeclarations(a)
	tc.timing_profile('  [ttime]     ck c pass1     ${f64(ck_c_sw.elapsed().microseconds()) / 1000.0:7.2f} ms')
	ck_c_sw.restart()
	// Pass 2: collect struct fields, function signatures (type aliases now available)
	// The native backend does not yet preserve large aggregate arguments reliably
	// through the parse-cache helpers. Parsing uncached keeps native self-hosts
	// correct while the C-hosted compiler retains the full memoization path.
	$if @BACKEND == 'arm64' {
		tc.type_cache.parse_enabled = false
	} $else {
		tc.type_cache.parse_enabled = true
	}
	tc.cur_module = ''
	for tl_idx in tc.top_level_idx {
		node := a.nodes[tl_idx]
		match node.kind {
			.file {
				tc.enter_file(node.value)
			}
			.module_decl {
				tc.enter_module(node.value)
			}
			.fn_decl {
				qname := tc.qualify_fn_name(node.value)
				tc.register_visible_mutation_fn_decl(tl_idx, tc.cur_module, qname, node.value)
				is_open_generic := node.generic_params().len > 0 || node.value.contains('[')
				ret_type := if is_open_generic {
					tc.parse_scope_param_type(node.typ)
				} else {
					tc.parse_type(node.typ)
				}
				mut ptypes := []Type{}
				mut param_texts := []string{}
				mut shared_params := []bool{}
				mut is_variadic := false
				mut has_mut_receiver := false
				for i in 0 .. node.children_count {
					child := a.child_node(&node, i)
					if child.kind == .param {
						if ptypes.len == 0 && node.value.contains('.') && child.is_mut
							&& !param_type_text_is_shared(child.typ) {
							has_mut_receiver = true
						}
						param_type := child.typ
						if param_type.starts_with('...') {
							is_variadic = true
						}
						parsed_param_type := if is_open_generic {
							tc.parse_scope_param_type(param_type)
						} else {
							tc.parse_type(param_type)
						}
						ptypes << if child.is_mut {
							mut_param_semantic_type(parsed_param_type)
						} else {
							parsed_param_type
						}
						param_texts << param_type
						shared_params << param_type_text_is_shared(child.typ)
					}
				}
				needs_ctx := tc.fn_needs_implicit_veb_ctx(node)
				ptypes = tc.fn_param_types_with_implicit_veb_ctx(node, ptypes)
				shared_params = tc.fn_shared_params_with_implicit_veb_ctx(node, shared_params)
				tc.register_fn_signature(qname, ret_type, ptypes, shared_params, is_variadic,
					needs_ctx)
				if has_mut_receiver {
					tc.register_mut_receiver_method(qname)
				}
				tc.fn_ret_type_texts[qname] = node.typ
				tc.fn_ret_type_texts[tc.cached_c_name(qname)] = node.typ
				if tc.cur_module in ['', 'main', 'builtin'] && qname != node.value
					&& node.value !in tc.fn_param_types {
					tc.register_fn_signature(node.value, ret_type, ptypes, shared_params,
						is_variadic, needs_ctx)
					if has_mut_receiver {
						tc.register_mut_receiver_method(node.value)
					}
					tc.fn_ret_type_texts[node.value] = node.typ
					tc.fn_ret_type_texts[tc.cached_c_name(node.value)] = node.typ
				}
				// A generic struct method (`Box[T].clone`) keeps its original signature
				// TEXT: the parsed types collapse a non-concrete `Box[T]` to the bare base,
				// so a concrete call must re-substitute the type arguments from the text to
				// recover applications like the receiver type in the return position
				// (`Box[T]` -> `Box[int]`). Only such methods carry `[` in their key.
				if node.generic_params().len > 0 || node.value.contains('[') {
					for name in [qname, node.value] {
						tc.fn_param_type_texts[name] = param_texts.clone()
						tc.fn_type_files[name] = tc.cur_file
						tc.fn_type_modules[name] = tc.cur_module
						if node.generic_params().len > 0
							&& (name == qname || tc.cur_module in ['', 'main', 'builtin']) {
							tc.fn_generic_params[name] = node.generic_params().clone()
						}
					}
				}
			}
			.struct_decl {
				mut fields := []StructField{}
				mut field_c_abi_fns := map[string]string{}
				mut shared_field_names := []string{}
				mut shadows_builtin_error_embed := false
				for i in 0 .. node.children_count {
					f := a.child_node(&node, i)
					if f.kind != .field_decl {
						continue
					}
					field_typ := if f.typ.len > 0 { f.typ } else { f.value }
					field_is_embed := source_field_decl_is_embed(f, field_typ)
					shadows_builtin_error := field_is_embed
						&& field_typ in ['Error', 'MessageError']
						&& tc.unqualified_type_name_shadows_builtin_in_scope(field_typ, tc.cur_file, tc.cur_module)
					if shadows_builtin_error {
						shadows_builtin_error_embed = true
					}
					mut typ := tc.parse_type(field_typ)
					if field_is_embed && field_typ in ['Error', 'MessageError']
						&& !shadows_builtin_error {
						typ = Type(Struct{
							name: field_typ
						})
					} else if f.value == field_typ || shadows_builtin_error {
						typ = tc.resolve_known_field_type(field_typ, typ)
					}
					if c_abi_fn := tc.c_abi_fn_ptr_type_for_type_text(field_typ) {
						field_c_abi_fns[f.value] = c_abi_fn
					}
					if param_type_text_is_shared(field_typ) {
						shared_field_names << f.value
					}
					fields << StructField{
						name:        f.value
						typ:         typ
						has_default: f.children_count > 0
						is_embed:    field_is_embed
						is_mut:      source_field_decl_is_mut(f)
					}
				}
				qname := tc.qualify_decl_name(node.value)
				// A `C.` struct denotes a single external C type, but several modules may
				// mirror it with partial or imprecise field views (e.g. `C.termios` in both
				// `term` and `term.termios`). codegen emits one C struct, so the field table
				// must be a single canonical view. Keep the most complete (superset) view so
				// it is deterministic regardless of module collection order, instead of
				// letting whichever declaration is collected last silently win.
				if qname.starts_with('C.') {
					if existing := tc.structs[qname] {
						if fields.len <= existing.len {
							continue
						}
					}
				}
				tc.structs[qname] = fields
				tc.struct_modules[qname] = tc.cur_module
				tc.struct_files[qname] = tc.cur_file
				if shadows_builtin_error_embed {
					tc.struct_error_embeds_shadow_builtin[qname] = true
				}
				for field_name in shared_field_names {
					tc.struct_shared_fields[struct_field_c_abi_key(qname, field_name)] = true
				}
				for field_name, c_abi_fn in field_c_abi_fns {
					tc.struct_field_c_abi_fns[struct_field_c_abi_key(qname, field_name)] = c_abi_fn
				}
				if 'union' in node.typ.split(',') {
					tc.unions[qname] = true
				}
				if 'params' in node.typ.split(',') {
					tc.params_structs[qname] = true
				}
				if 'soa' in node.typ.split(',') {
					tc.soa_structs[qname] = true
				}
				if 'typedef' in node.typ.split(',') {
					tc.c_typedef_structs[qname] = true
					tc.c_typedef_structs[node.value] = true
				}
			}
			.c_fn_decl {
				ret_type := tc.parse_type(node.typ)
				mut ptypes := []Type{}
				mut is_variadic := false
				for i in 0 .. node.children_count {
					child := a.child_node(&node, i)
					if child.kind == .param {
						if child.typ.starts_with('...') {
							is_variadic = true
						}
						ptypes << tc.parse_type(child.typ)
					}
				}
				tc.register_fn_signature(node.value, ret_type, ptypes, []bool{}, is_variadic, false)
				if is_variadic {
					tc.register_c_variadic_fn(node.value)
				}
				if !node.value.starts_with('C.') {
					tc.register_fn_signature('C.${node.value}', ret_type, ptypes, []bool{},
						is_variadic, false)
					if is_variadic {
						tc.register_c_variadic_fn('C.${node.value}')
					}
				}
			}
			.interface_decl {
				iface_name := tc.qualify_decl_name(node.value)
				iface_generic_params := node.generic_params()
				for i in 0 .. node.children_count {
					f := a.child_node(&node, i)
					if f.kind != .interface_field {
						continue
					}
					if f.op == .dot {
						mname := '${iface_name}.${f.value}'
						mut absm := tc.interface_abstract_methods[iface_name] or { []string{} }
						absm << f.value
						tc.interface_abstract_methods[iface_name] = absm
						ret_type := if iface_generic_params.len > 0 {
							tc.parse_scope_param_type(f.typ)
						} else {
							tc.parse_type(f.typ)
						}
						mut ptypes := []Type{}
						mut param_texts := []string{}
						mut shared_params := []bool{}
						mut is_variadic := false
						ptypes << Type(Pointer{
							base_type: Type(Interface{
								name: iface_name
							})
						})
						shared_params << false
						for j in 0 .. f.children_count {
							child := a.child_node(f, j)
							if child.kind == .param {
								if child.typ.starts_with('...') {
									is_variadic = true
								}
								ptypes << if iface_generic_params.len > 0 {
									tc.parse_scope_param_type(child.typ)
								} else {
									tc.parse_type(child.typ)
								}
								param_texts << child.typ
								shared_params << param_type_text_is_shared(child.typ)
							}
						}
						tc.register_fn_name_alias(mname, ret_type, ptypes, shared_params,
							is_variadic, false)
						if iface_generic_params.len > 0 {
							tc.fn_ret_type_texts[mname] = f.typ
							tc.fn_param_type_texts[mname] = [iface_name]
							tc.fn_param_type_texts[mname] << param_texts
						}
					} else if f.typ.len > 0 {
						mut fields := tc.interface_fields[iface_name] or { []StructField{} }
						fields << StructField{
							name:   f.value
							typ:    tc.parse_type(f.typ)
							is_mut: f.is_mut
						}
						tc.interface_fields[iface_name] = fields
					} else if f.value.len > 0 {
						mut embeds := tc.interface_embeds[iface_name] or { []string{} }
						embeds << tc.qualify_name(f.value)
						tc.interface_embeds[iface_name] = embeds
					}
				}
			}
			.global_decl {
				for i in 0 .. node.children_count {
					f := a.child_node(&node, i)
					if f.value.len > 0 && f.value.starts_with('C.') {
						tc.c_globals[f.value] = tc.parse_type(f.typ)
					} else if f.value.len > 0 {
						mut ft := tc.parse_type(f.typ)
						if ft is Void && f.children_count > 0 {
							ft = tc.resolve_type(a.child(f, 0))
						}
						qname := tc.qualify_name(f.value)
						tc.file_scope.insert(qname, ft)
						tc.global_names[qname] = true
					}
				}
			}
			.const_decl {
				for i in 0 .. node.children_count {
					f := a.child_node(&node, i)
					if f.kind == .const_field && f.children_count > 0 {
						qname := tc.qualify_name(f.value)
						tc.const_types[qname] = unknown_type('pending const `${qname}`')
						tc.const_exprs[qname] = a.child(f, 0)
						tc.const_modules[qname] = tc.cur_module
						tc.const_files[qname] = tc.cur_file
					} else if f.kind == .const_field && f.typ.len > 0 {
						qname := tc.qualify_name(f.value)
						tc.const_types[qname] = tc.parse_type(f.typ)
						tc.const_modules[qname] = tc.cur_module
						tc.const_files[qname] = tc.cur_file
					}
				}
			}
			else {}
		}
	}
	tc.collect_deprecated_symbols()
	tc.collect_unsafe_functions()
	tc.timing_profile('  [ttime]     ck c pass2     ${f64(ck_c_sw.elapsed().microseconds()) / 1000.0:7.2f} ms')
	ck_c_sw.restart()
	tc.resolve_inferred_global_types(a)
	tc.resolve_const_types()
	tc.build_const_suffixes()
	tc.timing_profile('  [ttime]     ck c resolve   ${f64(ck_c_sw.elapsed().microseconds()) / 1000.0:7.2f} ms')
	if !isnil(tc.visible_mutation_cache) {
		mut visible_mutation_cache := tc.visible_mutation_cache
		visible_mutation_cache.decl_index_ready = true
	}
	$if ownership ? {
		tc.ownership_after_collect()
	}
}

fn source_field_decl_is_mut(field flat.Node) bool {
	meta := field.generic_params()
	return meta.len > 0 && meta[0].contains('m')
}

fn (mut tc TypeChecker) collect_deprecated_symbols() {
	tc.deprecated_symbols.clear()
	mut module_name := ''
	mut file_name := ''
	for node in tc.a.nodes {
		if node.kind == .file {
			module_name = ''
			file_name = node.value
			continue
		}
		if node.kind == .module_decl {
			module_name = node.value
			continue
		}
		if node.kind == .struct_decl {
			qname := qualify_decl_name_in_module(node.value, module_name)
			for i in 0 .. node.children_count {
				field := tc.a.child_node(&node, i)
				if field.kind != .field_decl {
					continue
				}
				meta := field.generic_params()
				if meta.len <= 1 || !meta[0].contains('p') {
					continue
				}
				if info := deprecation_info_from_attrs(field.value, meta[1..]) {
					tc.deprecated_symbols['${qname}.${field.value}'] = info
				}
			}
			continue
		}
		if node.kind != .directive || !node.value.starts_with('@attributes:') {
			continue
		}
		decl_id := node.value['@attributes:'.len..].int()
		if decl_id < 0 || decl_id >= tc.a.nodes.len {
			continue
		}
		decl := tc.a.nodes[decl_id]
		if decl.kind !in [.fn_decl, .struct_decl, .const_decl] {
			continue
		}
		if decl.kind == .const_decl {
			for i in 0 .. decl.children_count {
				field := tc.a.child_node(&decl, i)
				if field.kind != .const_field {
					continue
				}
				qname := qualify_decl_name_in_module(field.value, module_name)
				if info := deprecation_info_from_attrs(qname, node.generic_params()) {
					tc.deprecated_symbols[qname] = info
				}
			}
			continue
		}
		display_name := if decl.kind == .struct_decl {
			deprecated_struct_display_name(file_name, module_name, decl.value)
		} else {
			decl.value
		}
		if info := deprecation_info_from_attrs(display_name, node.generic_params()) {
			qname := if decl.kind == .fn_decl {
				checker_qualified_fn_name(module_name, decl.value)
			} else {
				qualify_decl_name_in_module(decl.value, module_name)
			}
			tc.deprecated_symbols[qname] = info
			if module_name in ['', 'main', 'builtin'] {
				tc.deprecated_symbols[decl.value] = info
			}
		}
	}
}

fn (mut tc TypeChecker) collect_unsafe_functions() {
	tc.unsafe_fns.clear()
	mut module_name := ''
	for node in tc.a.nodes {
		if node.kind == .module_decl {
			module_name = node.value
			continue
		}
		if node.kind != .directive || !node.value.starts_with('@attributes:')
			|| 'unsafe' !in node.generic_params() {
			continue
		}
		decl_id := node.value['@attributes:'.len..].int()
		if decl_id < 0 || decl_id >= tc.a.nodes.len {
			continue
		}
		decl := tc.a.nodes[decl_id]
		if decl.kind != .fn_decl {
			continue
		}
		tc.unsafe_fns[decl.value] = true
		tc.unsafe_fns[checker_qualified_fn_name(module_name, decl.value)] = true
	}
}

fn deprecation_info_from_attrs(name string, attrs []string) ?DeprecationInfo {
	mut message := ''
	mut after := ''
	mut deprecated := false
	for raw in attrs {
		attr_name := raw.all_before(':').trim_space()
		value := comptime_static_unquote(raw.all_after(':').trim_space())
		if attr_name == 'deprecated' {
			deprecated = true
			if raw.contains(':') {
				message = value
			}
		} else if attr_name == 'deprecated_after' {
			after = value
		}
	}
	if !deprecated {
		return none
	}
	return DeprecationInfo{
		name:    name
		message: message
		after:   after
	}
}

fn deprecated_struct_display_name(file_name string, module_name string, struct_name string) string {
	normalized := file_name.replace('\\', '/')
	if relative := normalized.index('/vlib/') {
		dir := os.dir(normalized[relative + '/vlib/'.len..]).replace('/', '.')
		if dir.len > 0 && dir != '.' {
			return '${dir}.${struct_name}'
		}
	}
	return qualify_decl_name_in_module(struct_name, module_name)
}

// rebind_ast updates the AST view after the driver clones transformed storage.
// All collected declaration/type metadata remains valid because cloning preserves node ids.
pub fn (mut tc TypeChecker) rebind_ast(a &flat.FlatAst) {
	tc.a = a
}

fn (mut tc TypeChecker) resolve_inferred_global_types(a &flat.FlatAst) {
	tc.cur_module = ''
	tc.cur_file = ''
	for tl_idx in tc.top_level_idx {
		node := a.nodes[tl_idx]
		match node.kind {
			.file {
				tc.enter_file(node.value)
			}
			.module_decl {
				tc.enter_module(node.value)
			}
			.global_decl {
				for i in 0 .. node.children_count {
					f := a.child_node(&node, i)
					if f.value.len == 0 || f.value.starts_with('C.') || f.typ.len > 0
						|| f.children_count == 0 {
						continue
					}
					qname := tc.qualify_name(f.value)
					existing := tc.file_scope.lookup(qname) or { Type(void_) }
					if existing !is Unknown && existing !is Void {
						continue
					}
					ft := tc.resolve_type(a.child(f, 0))
					if ft is Unknown || ft is Void {
						continue
					}
					tc.file_scope.insert(qname, ft)
				}
			}
			else {}
		}
	}
}

fn (mut tc TypeChecker) check_c_struct_redeclarations(a &flat.FlatAst) {
	mut c_struct_decl_sigs := map[string]string{}
	mut c_struct_decl_files := map[string]string{}
	mut c_struct_decl_modules := map[string]string{}
	for node_idx in tc.top_level_idx {
		node := a.nodes[node_idx]
		match node.kind {
			.file {
				tc.enter_file(node.value)
			}
			.module_decl {
				tc.enter_module(node.value)
			}
			.struct_decl {
				qname := tc.qualify_name(node.value)
				if !qname.starts_with('C.') {
					continue
				}
				c_struct_sig := tc.c_struct_decl_signature(a, node)
				if qname in c_struct_decl_sigs {
					existing_sig := c_struct_decl_sigs[qname]
					if !c_struct_decl_signatures_compatible(existing_sig, c_struct_sig) {
						existing_file := c_struct_decl_files[qname] or { '' }
						existing_module := c_struct_decl_modules[qname] or { '' }
						if !tc.c_struct_redeclaration_allowed(qname, existing_file, tc.cur_file,
							existing_module, tc.cur_module) {
							tc.record_error_unfiltered(.duplicate_decl,
								'cannot redeclare C struct `${qname}`', flat.NodeId(node_idx))
						}
					}
					existing_fields := c_struct_decl_signature_field_count(existing_sig)
					current_fields := c_struct_decl_signature_field_count(c_struct_sig)
					if current_fields > existing_fields {
						c_struct_decl_sigs[qname] = c_struct_sig
						c_struct_decl_files[qname] = tc.cur_file
						c_struct_decl_modules[qname] = tc.cur_module
					}
				} else {
					c_struct_decl_sigs[qname] = c_struct_sig
					c_struct_decl_files[qname] = tc.cur_file
					c_struct_decl_modules[qname] = tc.cur_module
				}
			}
			else {}
		}
	}
}

struct CFnDeclSignature {
	return_type string
	params      []string
	is_variadic bool
}

fn (mut tc TypeChecker) check_c_fn_redeclarations(a &flat.FlatAst) {
	mut signatures := map[string]CFnDeclSignature{}
	mut modules := map[string]string{}
	tc.cur_module = ''
	tc.cur_file = ''
	for node_idx in tc.top_level_idx {
		node := a.nodes[node_idx]
		match node.kind {
			.file {
				tc.enter_file(node.value)
			}
			.module_decl {
				tc.enter_module(node.value)
			}
			.c_fn_decl {
				name := if node.value.starts_with('C.') { node.value } else { 'C.${node.value}' }
				mut params := []string{}
				mut is_variadic := false
				for i in 0 .. node.children_count {
					child := a.child_node(&node, i)
					if child.kind != .param {
						continue
					}
					if child.typ.starts_with('...') {
						is_variadic = true
					} else {
						params << tc.c_type(tc.parse_type(child.typ))
					}
				}
				signature := CFnDeclSignature{
					return_type: tc.c_type(tc.parse_type(node.typ))
					params:      params
					is_variadic: is_variadic
				}
				if existing := signatures[name] {
					existing_module := modules[name] or { '' }
					if existing_module == 'builtin' || existing_module == tc.cur_module {
						signatures[name] = signature
						modules[name] = tc.cur_module
					} else if tc.cur_module != 'builtin'
						&& !c_fn_decl_signatures_compatible(existing, signature) {
						tc.record_error_unfiltered(.duplicate_decl,
							'C function `${name}` was already declared with a different signature',
							flat.NodeId(node_idx))
					}
				} else {
					signatures[name] = signature
					modules[name] = tc.cur_module
				}
			}
			else {}
		}
	}
}

fn c_fn_decl_signatures_compatible(a CFnDeclSignature, b CFnDeclSignature) bool {
	if !c_fn_decl_abi_types_compatible(a.return_type, b.return_type) {
		return false
	}
	if a.is_variadic == b.is_variadic {
		if a.params.len != b.params.len {
			return false
		}
		return c_fn_decl_param_prefix_compatible(a.params, b.params, a.params.len)
	}
	variadic := if a.is_variadic { a } else { b }
	fixed := if a.is_variadic { b } else { a }
	if fixed.params.len < variadic.params.len {
		return false
	}
	return c_fn_decl_param_prefix_compatible(fixed.params, variadic.params, variadic.params.len)
}

fn c_fn_decl_param_prefix_compatible(a []string, b []string, count int) bool {
	if a.len < count || b.len < count {
		return false
	}
	for i in 0 .. count {
		if !c_fn_decl_abi_types_compatible(a[i], b[i]) {
			return false
		}
	}
	return true
}

fn c_fn_decl_abi_types_compatible(a string, b string) bool {
	if a == b || (a in ['int', 'i32'] && b in ['int', 'i32']) {
		return true
	}
	return (a == 'void*' && b.ends_with('*')) || (b == 'void*' && a.ends_with('*'))
}

fn (tc &TypeChecker) c_struct_redeclaration_allowed(qname string, first_file string, second_file string, first_module string, second_module string) bool {
	if qname == 'C.termios' && tc.c_struct_decl_is_vlib_termios_shim(first_file, first_module)
		&& tc.c_struct_decl_is_vlib_termios_shim(second_file, second_module) {
		return true
	}
	if qname == 'C.winsize' && tc.c_struct_decl_is_vlib_winsize_shim(first_file, first_module)
		&& tc.c_struct_decl_is_vlib_winsize_shim(second_file, second_module) {
		return true
	}
	if qname == 'C.cJSON' && tc.c_struct_decl_is_vlib_cjson(first_file, first_module)
		&& tc.c_struct_decl_is_vlib_cjson(second_file, second_module) {
		return true
	}
	return false
}

fn (tc &TypeChecker) c_struct_decl_is_vlib_winsize_shim(file string, module_name string) bool {
	if module_name !in ['term', 'ui', 'term.ui'] {
		return false
	}
	normalized := file.replace('\\', '/')
	return normalized.contains('/vlib/term/')
		|| (normalized.contains('/v3_module_cache_')
		&& normalized.all_after_last('/').starts_with('term_') && normalized.ends_with('.vh'))
}

fn (tc &TypeChecker) c_struct_decl_is_vlib_termios_shim(file string, module_name string) bool {
	if module_name !in ['term', 'termios', 'term.termios'] {
		return false
	}
	normalized := file.replace('\\', '/')
	if normalized.starts_with('vlib/term/') || normalized.contains('/vlib/term/') {
		return true
	}
	if !normalized.contains('/v3_module_cache_') || !normalized.ends_with('.vh') {
		return false
	}
	base := normalized.all_after_last('/')
	return (module_name == 'term' && base.starts_with('term_'))
		|| (module_name in ['termios', 'term.termios'] && base.starts_with('termios_'))
}

fn (tc &TypeChecker) c_struct_decl_is_vlib_cjson(file string, module_name string) bool {
	if module_name !in ['json', 'cjson', 'json.cjson'] {
		return false
	}
	normalized := file.replace('\\', '/')
	if normalized.contains('/vlib/json/json_primitives.c.v')
		|| normalized.contains('/vlib/json/cjson/cjson_wrapper.c.v') {
		return true
	}
	base := normalized.all_after_last('/')
	return normalized.contains('/v3_module_cache_') && normalized.ends_with('.vh')
		&& (base.starts_with('json_') || base.starts_with('cjson_'))
}

fn (tc &TypeChecker) c_struct_decl_signature(a &flat.FlatAst, node flat.Node) string {
	// Attributes such as `@[typedef]` change how the C name is spelled, not the
	// aggregate's field layout. Only the struct/union distinction belongs in the
	// redeclaration signature.
	mut sig := if 'union' in node.typ.split(',') { 'union' } else { '' }
	mut has_fields := false
	for i in 0 .. node.children_count {
		f := a.child_node(&node, i)
		if f.kind != .field_decl {
			continue
		}
		has_fields = true
		field_name := if f.value.starts_with('@') { f.value[1..] } else { f.value }
		field_typ := if f.typ.len > 0 { f.typ } else { f.value }
		sig += '|${field_name}:${tc.c_type(tc.parse_type(field_typ))}'
	}
	if !has_fields {
		return ''
	}
	return sig
}

fn c_struct_decl_signatures_compatible(a string, b string) bool {
	if a.len == 0 || b.len == 0 || a == b {
		return true
	}
	a_parts := a.split('|')
	b_parts := b.split('|')
	if a_parts.len == 0 || b_parts.len == 0 || a_parts[0] != b_parts[0] {
		return false
	}
	if a_parts[0] != 'union' {
		return false
	}
	a_fields := a_parts[1..]
	b_fields := b_parts[1..]
	return c_struct_decl_fields_subset(a_fields, b_fields)
		|| c_struct_decl_fields_subset(b_fields, a_fields)
}

fn c_struct_decl_fields_subset(small []string, big []string) bool {
	for field in small {
		if field !in big {
			return false
		}
	}
	return true
}

fn c_struct_decl_signature_field_count(sig string) int {
	if sig.len == 0 {
		return 0
	}
	parts := sig.split('|')
	if parts.len <= 1 {
		return 0
	}
	return parts.len - 1
}

// build_const_suffixes maps every dot-delimited suffix of each const key to that
// key, so qualified const lookups resolve in O(1) instead of scanning all consts
// (with per-iteration string building) on every selector/ident in module code.
fn (mut tc TypeChecker) build_const_suffixes() {
	for key, _ in tc.const_types {
		mut i := 0
		for i < key.len {
			if key[i] == `.` {
				suffix := key[i + 1..]
				if existing := tc.const_suffixes[suffix] {
					if existing != key {
						tc.const_suffixes[suffix] = ''
					}
				} else {
					tc.const_suffixes[suffix] = key
				}
			}
			i++
		}
	}
}

// const_key_for_suffix returns the const key matching `.${name}` as a suffix,
// equivalent to scanning const_types for `key.ends_with('.' + name)` but O(1).
fn (tc &TypeChecker) const_key_for_suffix(name string) ?string {
	if key := tc.const_suffixes[name] {
		if key.len > 0 {
			return key
		}
	}
	return none
}

// resolve_const_types resolves resolve const types information for types.
fn (mut tc TypeChecker) resolve_const_types() {
	if tc.const_exprs.len == 0 {
		return
	}
	saved_module := tc.cur_module
	saved_file := tc.cur_file
	for _ in 0 .. tc.const_exprs.len {
		mut changed := false
		for name, expr_id in tc.const_exprs {
			tc.cur_module = tc.const_modules[name] or { '' }
			tc.cur_file = tc.const_files[name] or { '' }
			// Const dependencies are not guaranteed to be visited in declaration order.
			// Re-resolve the initializer on every pass so an array DSL call that was
			// first seen through a still-pending const does not retain `[]unknown`.
			tc.invalidate_const_initializer_type(expr_id)
			mut new_type := tc.resolve_type(expr_id)
			new_type = tc.refine_const_initializer_type(expr_id, new_type)
			new_type = tc.const_type_from_initializer(name, new_type)
			if new_type is Unknown {
				continue
			}
			old_type := tc.const_types[name] or { Type(void_) }
			if old_type.name() != new_type.name() {
				tc.const_types[name] = new_type
				changed = true
			}
		}
		if !changed {
			break
		}
	}
	tc.cur_module = saved_module
	tc.cur_file = saved_file
}

fn (mut tc TypeChecker) invalidate_const_initializer_type(expr_id flat.NodeId) {
	idx := int(expr_id)
	if idx < 0 || idx >= tc.a.nodes.len {
		return
	}
	if idx < tc.expr_type_set.len {
		tc.expr_type_set[idx] = false
	}
	tc.sparse_expr_type_values.delete(idx)
	node := tc.a.nodes[idx]
	for i in 0 .. node.children_count {
		tc.invalidate_const_initializer_type(tc.a.child(&node, i))
	}
}

fn (mut tc TypeChecker) refine_const_initializer_type(expr_id flat.NodeId, typ Type) Type {
	if typ is Array && typ.elem_type is Unknown && int(expr_id) >= 0
		&& int(expr_id) < tc.a.nodes.len {
		expr := tc.a.nodes[int(expr_id)]
		if expr.kind == .call && expr.children_count >= 2 {
			callee := tc.a.child_node(&expr, 0)
			if callee.kind == .selector && callee.value == 'map' {
				elem_type := tc.array_map_return_elem_type(expr)
				if elem_type !is Unknown && elem_type !is Void {
					return Type(Array{
						elem_type: elem_type
					})
				}
			}
		}
	}
	return typ
}

// const_type_from_initializer converts const type from initializer data for types.
fn (tc &TypeChecker) const_type_from_initializer(name string, typ Type) Type {
	if typ !is Unknown {
		return typ
	}
	expr_id := tc.const_exprs[name] or { return typ }
	if int(expr_id) < 0 || int(expr_id) >= tc.a.nodes.len {
		return typ
	}
	expr := tc.a.nodes[int(expr_id)]
	if expr.kind == .or_expr && expr.children_count > 0 {
		inner_id := tc.a.child(&expr, 0)
		inner_node := tc.a.nodes[int(inner_id)]
		mut inner_type := tc.resolve_type(inner_id)
		if inner_type is Unknown && inner_node.kind == .call {
			inner_type = tc.direct_call_return_type(inner_node) or { inner_type }
		}
		match inner_type {
			OptionType, ResultType {
				if inner_type.base_type !is Unknown {
					return inner_type.base_type
				}
			}
			else {}
		}
	}
	if fn_typ := tc.const_fn_value_type(expr) {
		return fn_typ
	}
	if expr.kind != .call || expr.children_count == 0 {
		return typ
	}
	if ret := tc.direct_call_return_type(expr) {
		return ret
	}
	fn_node := tc.a.child_node(&expr, 0)
	if fn_node.kind != .ident || fn_node.value.len == 0 {
		return typ
	}
	mod_name := tc.const_modules[name] or { '' }
	mut candidates := []string{}
	if mod_name.len > 0 && mod_name != 'main' && mod_name != 'builtin' {
		candidates << '${mod_name}.${fn_node.value}'
	}
	candidates << fn_node.value
	candidates << tc.cached_c_name(fn_node.value)
	for candidate in candidates {
		if ret := tc.fn_ret_types[candidate] {
			return ret
		}
	}
	if fn_node.value == 'new_keywords_matcher_trie' {
		type_name := if mod_name.len > 0 && mod_name != 'main' && mod_name != 'builtin' {
			'${mod_name}.KeywordsMatcherTrie'
		} else {
			'KeywordsMatcherTrie'
		}
		return Type(Struct{
			name: type_name
		})
	}
	return typ
}

fn (tc &TypeChecker) const_fn_value_type(expr flat.Node) ?Type {
	match expr.kind {
		.ident {
			return tc.fn_value_type(expr.value)
		}
		.selector {
			if expr.children_count == 0 {
				return none
			}
			base := tc.a.child_node(&expr, 0)
			if base.kind != .ident {
				return none
			}
			mod_name := tc.resolve_import_alias(base.value) or { base.value }
			return tc.fn_type_from_key('${mod_name}.${expr.value}')
		}
		else {
			return none
		}
	}
}

fn (tc &TypeChecker) const_type_for_name(name string) ?Type {
	key := tc.const_key_for_name(name)?
	typ := tc.const_types[key] or { return none }
	return tc.const_type_from_initializer(key, typ)
}

fn (tc &TypeChecker) const_key_for_name(name string) ?string {
	qname := tc.qualify_name(name)
	if qname in tc.const_types {
		return qname
	}
	if name in tc.const_types {
		return name
	}
	return none
}

fn (tc &TypeChecker) const_type_for_selector(node flat.Node) ?Type {
	if node.kind != .selector || node.children_count == 0 {
		return none
	}
	base_node := tc.a.child_node(&node, 0)
	if base_node.kind != .ident {
		return none
	}
	resolved := tc.resolve_import_alias(base_node.value) or { base_node.value }
	qname := '${resolved}.${node.value}'
	if typ := tc.const_types[qname] {
		return tc.const_type_from_initializer(qname, typ)
	}
	if resolved == 'main' || resolved == tc.cur_module {
		if typ := tc.const_types[node.value] {
			return tc.const_type_from_initializer(node.value, typ)
		}
	}
	if key := tc.const_key_for_suffix(qname) {
		typ := tc.const_types[key] or { unknown_type('unknown const `${key}`') }
		return tc.const_type_from_initializer(key, typ)
	}
	return none
}

// selector_const_type returns the declared type for a selector const expression.
pub fn (tc &TypeChecker) selector_const_type(node flat.Node) ?Type {
	return tc.const_type_for_selector(node)
}

// const_owner_module returns the declaration module for a checker-resolved constant key.
pub fn (tc &TypeChecker) const_owner_module(name string) string {
	return tc.const_modules[name] or { '' }
}

// qualify_fn_name supports qualify fn name handling for TypeChecker.
pub fn (tc &TypeChecker) qualify_fn_name(name string) string {
	if tc.cur_module.len == 0 || tc.cur_module == 'main' || tc.cur_module == 'builtin' {
		return name
	}
	return '${tc.cur_module}.${name}'
}

fn (tc &TypeChecker) local_bare_fn_key(name string) ?string {
	if name.len == 0 || name.contains('.') {
		return none
	}
	qfn := tc.qualify_fn_name(name)
	if qfn != name {
		if qfn in tc.fn_ret_types {
			return qfn
		}
		return none
	}
	if tc.local_fn_decl_exists(name) && name in tc.fn_ret_types {
		return name
	}
	return none
}

fn (tc &TypeChecker) local_bare_fn_signature_key(name string) ?string {
	key := tc.local_bare_fn_key(name) or { return none }
	if tc.fn_signature_known(key) {
		return key
	}
	return none
}

fn (tc &TypeChecker) local_fn_decl_exists(name string) bool {
	if name.len == 0 || name.contains('.') {
		return false
	}
	if isnil(tc.type_cache) {
		return tc.local_fn_decl_exists_scan(name)
	}
	// Walking every AST node per query is far too slow for a helper on the
	// expression-typing path. Memoize a (module, fn name) set in the private
	// type_cache and extend it incrementally when the AST has grown (transform
	// appends fn_decls), resuming the module tracking where the last build
	// stopped.
	mut cache := tc.type_cache
	lookup_key := '${tc.cur_module}\x01${name}'
	if lookup_key in cache.local_fn_decl_index {
		return true
	}
	// The base chain can be more than one level deep during transform (the
	// scoped-transform overlay sits between forks and the warm check cache).
	mut fallback := cache.base
	for !isnil(fallback) {
		if lookup_key in fallback.local_fn_decl_index {
			return true
		}
		fallback = fallback.base
	}
	// Parallel forks only append transformed expressions to their private AST
	// regions; declarations remain the frozen master's authority. Scanning the
	// artificial shared-region length would index transformed fn_decl copies in
	// every helper and retain tens of megabytes of duplicate keys.
	if !isnil(cache.base) {
		return false
	}
	if cache.local_fn_decl_indexed_len < tc.a.nodes.len {
		mut cur_module := cache.local_fn_decl_last_module
		mut scan_start := cache.local_fn_decl_indexed_len
		if scan_start == 0 && tc.top_level_idx.len > 0 {
			// Initial build: module_decl/fn_decl nodes only occur at the top
			// level, so the check-time index covers its node range without a
			// full scan; nodes appended later (transform) are scanned below.
			for i in tc.top_level_idx {
				node := tc.a.nodes[i]
				match node.kind {
					.module_decl {
						cur_module = node.value
					}
					.fn_decl {
						cache.local_fn_decl_index['${cur_module}\x01${node.value}'] = true
					}
					else {}
				}
			}
			scan_start = tc.top_level_idx_nodes_len
		}
		incremental_transform_scan := tc.top_level_idx_nodes_len > 0
			&& scan_start >= tc.top_level_idx_nodes_len
		for i in scan_start .. tc.a.nodes.len {
			node := tc.a.nodes[i]
			match node.kind {
				.module_decl {
					cur_module = node.value
				}
				.fn_decl {
					if incremental_transform_scan && !local_fn_decl_is_transform_created(node.value) {
						continue
					}
					cache.local_fn_decl_index['${cur_module}\x01${node.value}'] = true
				}
				else {}
			}
		}
		cache.local_fn_decl_last_module = cur_module
		cache.local_fn_decl_indexed_len = tc.a.nodes.len
	}
	return lookup_key in cache.local_fn_decl_index
}

fn local_fn_decl_is_transform_created(name string) bool {
	return name.starts_with('__v3_') || name.starts_with('__anon_fn_')
		|| name.starts_with('__v_top_level_compile_') || name.contains('.__anon_fn_')
		|| (name.contains('[') && name.contains(']'))
}

// local_fn_decl_exists_scan is the uncached fallback used when no type_cache is
// attached to the checker.
fn (tc &TypeChecker) local_fn_decl_exists_scan(name string) bool {
	mut cur_module := ''
	for node in tc.a.nodes {
		match node.kind {
			.module_decl {
				cur_module = node.value
			}
			.fn_decl {
				if cur_module == tc.cur_module && node.value == name {
					return true
				}
			}
			else {}
		}
	}
	return false
}

// qualify_name supports qualify name handling for TypeChecker.
// QualifyNameCache memoizes qualify_name per (module, file) context. It must
// only be armed while the declared-type tables are static (parallel cgen of
// generic-free builds); every checker fork gets its own instance.
pub struct QualifyNameCache {
pub mut:
	module      string
	file        string
	fingerprint int = -1
	entries     map[string]string
}

// qualify_table_fingerprint tracks growth of every declared-type table
// qualify_name consults, so the memo stays valid even in phases that can
// still register types (e.g. anonymous structs during fn-body checking).
fn (tc &TypeChecker) qualify_table_fingerprint() int {
	return tc.structs.len + tc.type_aliases.len + tc.interface_names.len + tc.sum_types.len +
		tc.enum_names.len + tc.flag_enums.len
}

// ownership_time_spent_us reports the accumulated ownership-analysis time for
// the dedicated benchmark stage. Compiled-out ownership (no `-d ownership`)
// cannot spend time, so this returns 0 by construction in plain builds.
pub fn (tc &TypeChecker) ownership_time_spent_us() i64 {
	return tc.ownership_time_ns / 1000
}

pub fn (tc &TypeChecker) qualify_name(name string) string {
	if !isnil(tc.qualify_name_cache) {
		mut cache := tc.qualify_name_cache
		fingerprint := tc.qualify_table_fingerprint()
		if cache.module != tc.cur_module || cache.file != tc.cur_file
			|| cache.fingerprint != fingerprint {
			cache.module = tc.cur_module
			cache.file = tc.cur_file
			cache.fingerprint = fingerprint
			cache.entries.clear()
		}
		if cached := cache.entries[name] {
			return cached
		}
		result := tc.qualify_name_uncached(name)
		cache.entries[name] = result
		return result
	}
	return tc.qualify_name_uncached(name)
}

fn (tc &TypeChecker) qualify_name_uncached(name string) string {
	// Qualify container / wrapper types by recursing into the element type first,
	// so imported dotted names inside `[]T`, `[N]T`, `map[K]V`, `&T`, `?T`, `!T`
	// still get resolved. The `.contains('.')` fast path below only understands the
	// bare `alias.Type` form, so it must not short-circuit these wrappers.
	if name.starts_with('[]') {
		return '[]' + tc.qualify_name(name[2..])
	}
	if name.starts_with('[') {
		idx := name.index_u8(`]`)
		if idx > 0 {
			return name[..idx + 1] + tc.qualify_name(name[idx + 1..])
		}
	}
	if name.starts_with('map[') {
		bracket_end := find_matching_bracket(name, 3)
		key_str := name[4..bracket_end]
		val_str := name[bracket_end + 1..]
		return 'map[${tc.qualify_name(key_str)}]${tc.qualify_name(val_str)}'
	}
	if name.starts_with('&') {
		return '&' + tc.qualify_name(name[1..])
	}
	if name.starts_with('?') {
		return '?' + tc.qualify_name(name[1..])
	}
	if name.starts_with('!') {
		return '!' + tc.qualify_name(name[1..])
	}
	if name.contains('.') {
		return tc.resolve_imported_type_text(name)
	}
	if tc.cur_module.len == 0 || tc.cur_module == 'main' || tc.cur_module == 'builtin' {
		return name
	}
	if is_builtin_type_name(name) {
		return name
	}
	if tc.unqualified_type_symbol_is_builtin(name) {
		return name
	}
	qualified := tc.cur_module + '.' + name
	if qualified in tc.structs || qualified in tc.interface_names || qualified in tc.sum_types
		|| qualified in tc.enum_names || qualified in tc.flag_enums || qualified in tc.type_aliases {
		return qualified
	}
	// A declaration in the active source scope shadows an already-collected
	// unqualified symbol (notably `errors.Error` shadows `builtin.Error`).
	// Keep it module-qualified before the resolution-only generic fallback below.
	if tc.source_declares_type_in_scope(name, tc.cur_file, tc.cur_module) {
		return qualified
	}
	// A concrete generic argument can originate in another module and then be
	// substituted into a generic declaration while that declaration's module is
	// active. Preserve an already-known unqualified symbol (notably a `main`
	// type) instead of incorrectly rebasing it into the generic's module.
	if tc.resolution_type_mode && (name in tc.structs || name in tc.interface_names
		|| name in tc.sum_types || name in tc.enum_names || name in tc.flag_enums
		|| name in tc.type_aliases) {
		return name
	}
	return qualified
}

// qualify_decl_name gives a declaration its stable owner-module name without
// consulting declarations collected earlier in the same pass.
fn (tc &TypeChecker) qualify_decl_name(name string) string {
	if name.contains('.') {
		return tc.resolve_imported_type_text(name)
	}
	if tc.cur_module.len == 0 || tc.cur_module in ['main', 'builtin'] {
		return name
	}
	return '${tc.cur_module}.${name}'
}

// qualify_resolution_type_name qualifies a type name for RESOLUTION (not
// registration): a bare capitalized name that does not exist under the current
// module but does exist globally (a generic arg substituted from another
// module's caller, e.g. main's `Foo` inside a json2 specialization) stays bare
// instead of becoming a nonexistent `json2.Foo`. Registration must never use
// this - it is order-dependent during collect.
fn (tc &TypeChecker) qualify_resolution_type_name(name string) string {
	qualified := tc.qualify_name(name)
	if qualified != name && name.len > 0 && name[0] >= `A` && name[0] <= `Z`
		&& !tc.qualify_candidate_type_exists(qualified) && tc.qualify_candidate_type_exists(name) {
		return name
	}
	return qualified
}

fn (tc &TypeChecker) qualify_candidate_type_exists(name string) bool {
	return name in tc.structs || name in tc.sum_types || name in tc.interface_names
		|| name in tc.enum_names || name in tc.type_aliases || name in tc.struct_generic_params
}

fn (tc &TypeChecker) qualify_sum_variant_name(name string, generic_params []string) string {
	clean := trimmed_space(name)
	if clean.starts_with('fn(') || clean.starts_with('fn (') {
		return tc.qualify_type_text(clean)
	}
	if generic_params.len == 0 {
		return tc.qualify_name(name)
	}
	if clean.len == 0 {
		return clean
	}
	if clean in generic_params {
		return clean
	}
	if clean.starts_with('&') {
		return '&' + tc.qualify_sum_variant_name(clean[1..], generic_params)
	}
	if clean.starts_with('?') {
		return '?' + tc.qualify_sum_variant_name(clean[1..], generic_params)
	}
	if clean.starts_with('!') {
		return '!' + tc.qualify_sum_variant_name(clean[1..], generic_params)
	}
	if clean.starts_with('...') {
		return '...' + tc.qualify_sum_variant_name(clean[3..], generic_params)
	}
	if clean.starts_with('[]') {
		return '[]' + tc.qualify_sum_variant_name(clean[2..], generic_params)
	}
	if clean.starts_with('map[') {
		bracket_end := find_matching_bracket(clean, 3)
		if bracket_end < clean.len {
			key := tc.qualify_sum_variant_name(clean[4..bracket_end], generic_params)
			val := tc.qualify_sum_variant_name(clean[bracket_end + 1..], generic_params)
			return 'map[${key}]${val}'
		}
	}
	if clean.starts_with('[') {
		bracket_end := find_matching_bracket(clean, 0)
		if bracket_end < clean.len {
			return clean[..bracket_end + 1] + tc.qualify_sum_variant_name(clean[bracket_end +
				1..], generic_params)
		}
	}
	bracket := clean.index_u8(`[`)
	if bracket > 0 {
		bracket_end := find_matching_bracket(clean, bracket)
		if bracket_end < clean.len {
			inner := trimmed_space(clean[bracket + 1..bracket_end])
			if is_fixed_array_len_text(inner) || is_builtin_type_name(clean[..bracket]) {
				return tc.qualify_sum_variant_name(clean[..bracket], generic_params) +
					clean[bracket..]
			}
			mut parts := []string{}
			for part in split_params(inner) {
				parts << tc.qualify_sum_variant_name(part, generic_params)
			}
			return tc.qualify_name(clean[..bracket]) + '[' + parts.join(', ') + ']' +
				clean[bracket_end + 1..]
		}
	}
	return tc.qualify_name(clean)
}

// qualify_type_text qualifies a type text for registration: bare names always
// get the current module prefix (order-independent during collect).
fn (tc &TypeChecker) qualify_type_text(typ string) string {
	return tc.qualify_type_text_impl(typ, false, []string{})
}

fn (tc &TypeChecker) qualify_type_text_with_generic_params(typ string, generic_params []string) string {
	return tc.qualify_type_text_impl(typ, false, generic_params)
}

// qualify_resolution_type_text qualifies a type text in a resolution-only
// context (generic application args): a bare name substituted from another
// module's caller may stay bare when the module-qualified spelling does not
// exist. Never use for registration.
fn (tc &TypeChecker) qualify_resolution_type_text(typ string) string {
	return tc.qualify_type_text_impl(typ, true, []string{})
}

// parse_resolution_type parses type text that can mix declaration-local names with concrete
// generic arguments from another module.
pub fn (tc &TypeChecker) parse_resolution_type(typ string) Type {
	clean := trimmed_space(typ)
	if clean.contains('.') {
		if exact := tc.type_from_known_symbol(clean) {
			return exact
		}
	}
	qualified := tc.qualify_resolution_type_text(typ)
	if isnil(tc.resolution_type_views) {
		mut direct_view := tc.fork_type_parse_view(tc.cur_file, '')
		direct_view.resolution_type_mode = false
		return direct_view.parse_type(qualified)
	}
	mut views := unsafe { tc.resolution_type_views }
	if cached := views.by_file[tc.cur_file] {
		return cached.parse_type(qualified)
	}
	mut unscoped := tc.fork_type_parse_view(tc.cur_file, '')
	unscoped.resolution_type_mode = false
	view := &unscoped
	views.by_file[tc.cur_file] = view
	return view.parse_type(qualified)
}

// reset_resolution_type_view_cache discards lookup views that may have been
// created inside a completed scoped parallel phase.
pub fn (mut tc TypeChecker) reset_resolution_type_view_cache() {
	tc.resolution_type_views = &ResolutionTypeViewCache{
		by_file: map[string]&TypeChecker{}
	}
}

// disable_resolution_type_view_cache prevents a scoped cache from escaping the
// phase that allocated it.
pub fn (mut tc TypeChecker) disable_resolution_type_view_cache() {
	tc.resolution_type_views = unsafe { nil }
}

fn (tc &TypeChecker) qualify_type_text_impl(typ string, resolution bool, generic_params []string) string {
	clean := trimmed_space(typ)
	if clean.len == 0 {
		return typ
	}
	if clean in generic_params {
		return clean
	}
	if clean.starts_with('&') {
		return '&' + tc.qualify_type_text_impl(clean[1..], resolution, generic_params)
	}
	if clean.starts_with('mut ') {
		inner := tc.qualify_type_text_impl(clean[4..], resolution, generic_params)
		if inner.starts_with('&') {
			return inner
		}
		return '&' + inner
	}
	if clean.starts_with('shared ') {
		return 'shared ' + tc.qualify_type_text_impl(clean[7..], resolution, generic_params)
	}
	if clean.starts_with('atomic ') {
		return 'atomic ' + tc.qualify_type_text_impl(clean[7..], resolution, generic_params)
	}
	if clean.starts_with('?') {
		return '?' + tc.qualify_type_text_impl(clean[1..], resolution, generic_params)
	}
	if clean.starts_with('!') {
		return '!' + tc.qualify_type_text_impl(clean[1..], resolution, generic_params)
	}
	if clean.starts_with('...') {
		return '...' + tc.qualify_type_text_impl(clean[3..], resolution, generic_params)
	}
	if clean.starts_with('[]') {
		return '[]' + tc.qualify_type_text_impl(clean[2..], resolution, generic_params)
	}
	if clean == 'chan' {
		return clean
	}
	if clean.starts_with('chan mut ') {
		return 'chan mut ' + tc.qualify_type_text_impl(clean[9..], resolution, generic_params)
	}
	if clean.starts_with('chan ') {
		return 'chan ' + tc.qualify_type_text_impl(clean[5..], resolution, generic_params)
	}
	if clean == 'thread' {
		return clean
	}
	if clean.starts_with('thread ') {
		return 'thread ' + tc.qualify_type_text_impl(clean[7..], resolution, generic_params)
	}
	if clean.starts_with('map[') {
		bracket_end := find_matching_bracket(clean, 3)
		if bracket_end < clean.len {
			key := tc.qualify_type_text_impl(clean[4..bracket_end], resolution, generic_params)
			val := tc.qualify_type_text_impl(clean[bracket_end + 1..], resolution, generic_params)
			return 'map[${key}]${val}'
		}
	}
	if clean.starts_with('[') {
		bracket_end := find_matching_bracket(clean, 0)
		if bracket_end < clean.len {
			return clean[..bracket_end + 1] + tc.qualify_type_text_impl(clean[bracket_end +
				1..], resolution, generic_params)
		}
	}
	if clean.starts_with('(') && clean.ends_with(')') && clean.contains(',') {
		mut parts := []string{}
		for part in split_params(clean[1..clean.len - 1]) {
			parts << tc.qualify_type_text_impl(part, resolution, generic_params)
		}
		return '(' + parts.join(', ') + ')'
	}
	if clean.starts_with('fn(') || clean.starts_with('fn (') {
		return tc.qualify_fn_type_text(clean, generic_params)
	}
	bracket := clean.index_u8(`[`)
	if bracket > 0 {
		bracket_end := find_matching_bracket(clean, bracket)
		if bracket_end < clean.len {
			inner := trimmed_space(clean[bracket + 1..bracket_end])
			if is_fixed_array_len_text(inner) || is_builtin_type_name(clean[..bracket]) {
				return tc.qualify_type_text_impl(clean[..bracket], resolution, generic_params) +
					clean[bracket..]
			}
			mut parts := []string{}
			for part in split_params(inner) {
				parts << tc.qualify_type_text_impl(part, resolution, generic_params)
			}
			return tc.qualify_type_text_impl(clean[..bracket], resolution, generic_params) + '[' +
				parts.join(', ') + ']' + clean[bracket_end + 1..]
		}
	}
	if resolution && clean.contains('.') && tc.qualify_candidate_type_exists(clean) {
		return clean
	}
	if !clean.contains('.') {
		if resolved := tc.resolve_selective_import_type_symbol(clean) {
			return resolved
		}
		if candidates := tc.selective_import_candidates(clean) {
			if candidates.len == 1 {
				return candidates[0]
			}
		}
	}
	if resolution {
		return tc.qualify_resolution_type_name(clean)
	}
	return tc.qualify_name(clean)
}

// qualify_fn_type_text supports qualify fn type text handling for TypeChecker.
fn (tc &TypeChecker) qualify_fn_type_text(typ string, generic_params []string) string {
	params_start := typ.index_u8(`(`) + 1
	mut depth := 1
	mut params_end := params_start
	for params_end < typ.len {
		if typ[params_end] == `(` {
			depth++
		} else if typ[params_end] == `)` {
			depth--
			if depth == 0 {
				break
			}
		}
		params_end++
	}
	params_str := typ[params_start..params_end]
	mut params := []string{}
	if trimmed_space(params_str).len > 0 {
		for part in split_params(params_str) {
			params << tc.qualify_type_text_impl(normalize_fn_type_param_text(part), false,
				generic_params)
		}
	}
	ret_str := trimmed_space(typ[params_end + 1..])
	if ret_str.len > 0 {
		return 'fn(${params.join(', ')}) ${tc.qualify_type_text_impl(ret_str, false, generic_params)}'
	}
	return 'fn(${params.join(', ')})'
}

// file_import_key supports file import key handling for types.
fn file_import_key(file string, alias string) string {
	return '${file}\n${alias}'
}

fn (mut tc TypeChecker) file_import_info() &FileImportInfo {
	if info := tc.file_imports_by_file[tc.cur_file] {
		return info
	}
	info := &FileImportInfo{
		imports:           map[string]string{}
		selective_imports: map[string][]string{}
	}
	tc.file_imports_by_file[tc.cur_file] = info
	return info
}

fn (mut tc TypeChecker) register_file_import(alias string, module_name string) {
	tc.file_imports[file_import_key(tc.cur_file, alias)] = module_name
	mut info := tc.file_import_info()
	info.imports[alias] = module_name
}

fn (mut tc TypeChecker) check_import_diagnostics() {
	mut first_imports := map[string]token.Pos{}
	mut declaration_seen_in_file := false
	for idx in tc.top_level_idx {
		node := tc.a.nodes[idx]
		if node.kind == .file {
			tc.enter_file(node.value)
			declaration_seen_in_file = false
			continue
		}
		if node.kind == .module_decl {
			tc.enter_module(node.value)
			continue
		}
		if node.kind != .import_decl {
			if node.kind != .empty {
				declaration_seen_in_file = true
			}
			continue
		}
		module_path := tc.import_module_path_text(node)
		module_base := module_path.all_after_last('.')
		explicit_alias := tc.import_has_explicit_alias(node)
		if missing_path := tc.a.missing_imports[idx] {
			tc.record_error_severity_at(.unknown_ident,
				'cannot import module "${missing_path}" (not found)', flat.NodeId(idx), node.pos,
				'builder error:')
		}
		tc.check_import_source_syntax(flat.NodeId(idx), node)
		if tc.selective_import_has_missing_value_symbol(node, module_path)
			|| tc.selective_import_has_const(node, module_path) {
			tc.record_unused_import_warning(flat.NodeId(idx), node)
		}
		tc.check_selective_const_imports(node, module_path)
		tc.check_selective_type_imports(node, module_path)
		if declaration_seen_in_file {
			tc.record_error_at(.duplicate_decl,
				'`import x` can only be declared at the beginning of the file', flat.NodeId(idx), token.new_span(node.pos.id,
				node.pos.offset, node.pos.offset + 'import'.len))
		}
		if explicit_alias && node.typ == module_base {
			tc.record_error_at(.duplicate_decl,
				'import alias `${module_path} as ${node.typ}` is redundant', flat.NodeId(idx),
				tc.import_alias_pos(node))
		}
		if module_base == tc.cur_module {
			tc.record_error_at(.duplicate_decl,
				'cannot import `${module_path}` into a module with the same name',
				flat.NodeId(idx), tc.import_module_path_pos(node))
		}
		if node.typ == tc.cur_module {
			alias_pos := if explicit_alias {
				tc.import_alias_pos(node)
			} else {
				tc.import_module_basename_pos(node)
			}
			tc.record_error_at(.duplicate_decl,
				'cannot import `${module_path}` as `${node.typ}` into a module with the same name',
				flat.NodeId(idx), alias_pos)
		}
		if module_path == 'json' && module_base != tc.cur_module {
			tc.record_warning_at(.duplicate_decl,
				'module `json` has been deprecated; `json` will be removed soon; use the pure V `json2` module instead',
				flat.NodeId(idx), node.pos)
		}
		key := file_import_key(tc.cur_file, node.typ)
		if first_pos := first_imports[key] {
			first_line := tc.import_line_number(first_pos)
			pos := tc.import_module_path_pos(node)
			tc.record_error_at(.duplicate_decl,
				'A module `${node.typ}` was already imported on line ${first_line}`.',
				flat.NodeId(idx), pos)
		} else {
			first_imports[key] = node.pos
		}
	}
}

fn (tc &TypeChecker) selective_import_has_const(node flat.Node, module_path string) bool {
	for i in 0 .. node.children_count {
		child := tc.a.child_node(&node, i)
		if child.kind != .ident || child.value.len == 0 {
			continue
		}
		for module_name in [node.value, module_path, module_path.all_after_last('.')] {
			if '${module_name}.${child.value}' in tc.const_types {
				return true
			}
		}
	}
	return false
}

fn (tc &TypeChecker) selective_import_has_missing_value_symbol(node flat.Node, module_path string) bool {
	for i in 0 .. node.children_count {
		child := tc.a.child_node(&node, i)
		if child.kind != .ident || child.value.len == 0 || child.value[0].is_capital() {
			continue
		}
		mut symbol_exists := false
		for module_name in [node.value, module_path, module_path.all_after_last('.')] {
			name := '${module_name}.${child.value}'
			if tc.fn_signature_known(name) || name in tc.fn_ret_types || name in tc.const_types {
				symbol_exists = true
				break
			}
		}
		if !symbol_exists {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) private_declaration(name string) ?DeclarationVisibility {
	if name.len == 0 {
		return none
	}
	mut candidates := []string{}
	for candidate in [name, visible_mutation_fn_lookup_name(name)] {
		if candidate.len > 0 && candidate !in candidates {
			candidates << candidate
		}
	}
	mut shortened := name
	for shortened.contains('.') {
		tail := shortened.all_after('.')
		if !tail.contains('.') {
			break
		}
		shortened = tail
		for candidate in [shortened, visible_mutation_fn_lookup_name(shortened)] {
			if candidate.len > 0 && candidate !in candidates {
				candidates << candidate
			}
		}
	}
	for candidate in candidates {
		visibility := tc.declaration_visibility[candidate] or { continue }
		if !visibility.is_pub && visibility.module_name != tc.cur_module {
			return visibility
		}
		return none
	}
	return none
}

fn (mut tc TypeChecker) check_selective_const_imports(node flat.Node, module_path string) {
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind != .ident || child.value.len == 0 {
			continue
		}
		mut is_const := false
		for module_name in [node.value, module_path, module_path.all_after_last('.')] {
			if '${module_name}.${child.value}' in tc.const_types {
				is_const = true
				break
			}
		}
		if is_const {
			tc.record_error_at(.duplicate_decl,
				'cannot selectively import constant `${child.value}` from `${module_path}`, import `${module_path}` and use `${module_path}.${child.value}` instead',
				child_id, tc.node_value_diagnostic_pos(child_id))
			continue
		}
		if child.value[0].is_capital() {
			continue
		}
		mut symbol_name := ''
		for module_name in [node.value, module_path, module_path.all_after_last('.')] {
			name := '${module_name}.${child.value}'
			if tc.fn_signature_known(name) || name in tc.fn_ret_types {
				symbol_name = name
				break
			}
		}
		if symbol_name.len == 0 {
			tc.record_error_at(.unknown_fn,
				'module `${module_path}` has no constant or function `${child.value}`', child_id,
				tc.node_value_diagnostic_pos(child_id))
		} else if _ := tc.private_declaration(symbol_name) {
			tc.record_error_at(.unknown_fn,
				'module `${module_path}` function `${child.value}()` is private', child_id,
				tc.node_value_diagnostic_pos(child_id))
		}
	}
}

fn (mut tc TypeChecker) check_selective_type_imports(node flat.Node, module_path string) {
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind != .ident || child.value.len == 0 || !child.value[0].is_capital() {
			continue
		}
		mut symbol_name := ''
		for module_name in [node.value, module_path, module_path.all_after_last('.')] {
			name := '${module_name}.${child.value}'
			if tc.type_symbol_known(name) {
				symbol_name = name
				break
			}
		}
		if symbol_name.len == 0 {
			tc.record_error_at(.unknown_type,
				'module `${module_path}` has no type `${child.value}`', child_id,
				tc.node_value_diagnostic_pos(child_id))
		} else if _ := tc.private_declaration(symbol_name) {
			tc.record_error_at(.unknown_type,
				'module `${module_path}` type `${child.value}` is private', child_id,
				tc.node_value_diagnostic_pos(child_id))
		}
	}
}

fn (mut tc TypeChecker) check_unused_import_diagnostics() {
	for idx in tc.top_level_idx {
		node := tc.a.nodes[idx]
		if node.kind == .file {
			tc.enter_file(node.value)
			continue
		}
		if node.kind == .module_decl {
			tc.enter_module(node.value)
			continue
		}
		if tc.diagnostic_files.len > 0 && tc.cur_file !in tc.diagnostic_files {
			continue
		}
		if node.kind != .import_decl || !node.pos.is_valid() || node.typ == '_'
			|| tc.import_is_used(flat.NodeId(idx), node) {
			continue
		}
		if tc.node_has_unused_import_warning(flat.NodeId(idx)) {
			continue
		}
		if tc.node_has_error(flat.NodeId(idx)) {
			continue
		}
		tc.record_unused_import_warning(flat.NodeId(idx), node)
	}
}

fn (mut tc TypeChecker) record_unused_import_warning(id flat.NodeId, node flat.Node) {
	module_path := tc.import_module_path_text(node)
	display_name := if node.typ == module_path {
		module_path
	} else {
		'${node.typ} (${module_path})'
	}
	tc.record_warning_at(.unknown_ident,
		"module '${display_name}' is imported but never used. Use `import ${display_name} as _`, to silence this warning, or just remove the unused import line",
		id, tc.import_module_path_pos(node))
}

fn (tc &TypeChecker) node_has_unused_import_warning(id flat.NodeId) bool {
	for warning in tc.notices {
		if warning.node == id && warning.msg.contains('is imported but never used') {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) node_has_error(id flat.NodeId) bool {
	for err in tc.errors {
		if err.node == id && err.severity != 'builder error:' {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) check_import_source_syntax(id flat.NodeId, node flat.Node) {
	file := tc.a.source_files[node.pos.id] or { return }
	source := tc.source_texts_by_file[file.name] or { return }
	start := node.pos.offset
	if start < 0 || start + 'import'.len > source.len {
		return
	}
	first_line_end := source.index_after('\n', start) or { source.len }
	mut cursor := start + 'import'.len
	for cursor < first_line_end && source[cursor] in [` `, `\t`, `\r`] {
		cursor++
	}
	if cursor >= first_line_end || source[cursor] == `\n` {
		mut next := first_line_end
		for next < source.len && source[next] in [` `, `\t`, `\r`, `\n`] {
			next++
		}
		end := import_source_ident_end(source, next)
		if end > next {
			tc.record_error_at(.duplicate_decl, '`import` statements must be a single line', id, token.new_span(node.pos.id,
				next, end))
		}
		return
	}
	module_start := cursor
	for cursor < first_line_end && (is_import_ident_byte(source[cursor]) || source[cursor] == `.`) {
		cursor++
	}
	if cursor == module_start {
		return
	}
	for cursor < first_line_end && source[cursor] in [` `, `\t`, `\r`] {
		cursor++
	}
	if cursor >= first_line_end || source[cursor] == `\n` {
		return
	}
	if source[cursor] == `,` {
		tc.record_error_at(.duplicate_decl, 'cannot import multiple modules at a time', id, token.new_span(node.pos.id,
			cursor, cursor + 1))
		return
	}
	if source[cursor] == `{` {
		tc.check_selective_import_source_syntax(id, node, source, cursor, first_line_end)
		return
	}
	if source[cursor..first_line_end].starts_with('as ') {
		return
	}
	if is_import_ident_byte(source[cursor]) {
		end := import_source_ident_end(source, cursor)
		tc.record_error_at(.duplicate_decl, 'cannot import multiple modules at a time', id, token.new_span(node.pos.id,
			cursor, end))
	}
}

fn (mut tc TypeChecker) check_selective_import_source_syntax(id flat.NodeId, node flat.Node, source string, open int, line_end int) {
	mut cursor := open + 1
	for cursor < line_end && source[cursor] in [` `, `\t`, `\r`] {
		cursor++
	}
	if cursor < line_end && source[cursor] == `}` {
		tc.record_error_at(.duplicate_decl,
			'empty `${tc.import_module_path_text(node)}` import set, remove `{}`', id, token.new_span(node.pos.id,
			cursor, cursor + 1))
		return
	}
	mut close := -1
	for i := cursor; i < line_end; i++ {
		if source[i] == `}` {
			close = i
			break
		}
	}
	if close < 0 {
		mut diagnostic_offset := line_end - 1
		for diagnostic_offset > open && source[diagnostic_offset] in [` `, `\t`, `\r`, `\n`] {
			diagnostic_offset--
		}
		tc.record_error_at(.duplicate_decl, 'import syntax error, no closing `}`', id, token.new_span(node.pos.id,
			diagnostic_offset, diagnostic_offset + 1))
		return
	}
	if cursor < close && !is_import_ident_byte(source[cursor]) {
		tc.record_error_at(.duplicate_decl,
			'import syntax error, please specify a valid fn or type name', id, token.new_span(node.pos.id,
			cursor, cursor + 1))
	}
}

fn import_source_ident_end(source string, start int) int {
	mut end := start
	for end < source.len && is_import_ident_byte(source[end]) {
		end++
	}
	return end
}

fn is_import_ident_byte(ch u8) bool {
	return ch.is_alnum() || ch == `_`
}

fn (tc &TypeChecker) import_is_used(import_id flat.NodeId, import_node flat.Node) bool {
	mut selective_names := []string{cap: int(import_node.children_count)}
	import_file := if file := tc.a.source_files[import_node.pos.id] {
		file.name
	} else {
		tc.cur_file
	}
	for i in 0 .. import_node.children_count {
		child := tc.a.child_node(&import_node, i)
		if child.kind == .ident {
			selective_names << child.value
		}
	}
	for idx, node in tc.a.nodes {
		if idx == int(import_id) || node.kind == .import_decl || node.pos.id != import_node.pos.id {
			continue
		}
		if node.kind == .selector && node.children_count > 0 {
			base := tc.a.child_node(&node, 0)
			if base.kind == .ident && base.value == import_node.typ {
				return true
			}
		}
		if type_text_contains_qualified_import(node.typ, import_node.typ)
			|| type_text_contains_qualified_import(node.value, import_node.typ) {
			return true
		}
		if selective_names.len == 0 {
			continue
		}
		if node.kind == .ident && node.value in selective_names {
			return true
		}
		if node.kind == .call {
			if resolved := tc.resolved_call_name(flat.NodeId(idx)) {
				for name in selective_names {
					if resolved == '${import_node.value}.${name}'
						|| resolved.starts_with('${import_node.value}.${name}[') {
						return true
					}
				}
			}
		}
		for name in selective_names {
			if !type_text_contains_symbol(node.typ, name)
				&& !type_text_contains_symbol(node.value, name) {
				continue
			}
			if resolved := tc.resolve_selective_import_type_symbol_in_file(name, import_file) {
				if resolved == '${import_node.value}.${name}' {
					return true
				}
			}
		}
	}
	return false
}

fn type_text_contains_qualified_import(text string, alias string) bool {
	if text.len <= alias.len || alias.len == 0 {
		return false
	}
	mut start := 0
	needle := alias + '.'
	for start < text.len {
		relative := text[start..].index(needle) or { return false }
		index := start + relative
		if index == 0 || !is_type_symbol_byte(text[index - 1]) {
			return true
		}
		start = index + needle.len
	}
	return false
}

fn (mut tc TypeChecker) check_deprecated_byte_types() {
	mut pending_file := ''
	for idx in tc.top_level_idx {
		node := tc.a.nodes[idx]
		if node.kind == .file {
			pending_file = node.value
			tc.enter_file(node.value)
			continue
		}
		if pending_file.len == 0 || !node.pos.is_valid() {
			continue
		}
		tc.check_deprecated_byte_types_in_file(flat.NodeId(idx), node.pos.id, pending_file)
		pending_file = ''
	}
}

fn (mut tc TypeChecker) check_deprecated_byte_types_in_file(anchor flat.NodeId, file_id int, path string) {
	if tc.diagnostic_files.len > 0 && path !in tc.diagnostic_files {
		return
	}
	source := os.read_file(path) or { return }
	mut i := 0
	for i < source.len {
		if i + 1 < source.len && source[i] == `/` && source[i + 1] == `/` {
			i = source.index_after('\n', i + 2) or { source.len }
			continue
		}
		if i + 1 < source.len && source[i] == `/` && source[i + 1] == `*` {
			end := source.index_after('*/', i + 2) or { source.len }
			i = int_min(end + 2, source.len)
			continue
		}
		if source[i] in [`'`, `"`, `\``] {
			quote := source[i]
			i++
			for i < source.len {
				if source[i] == `\\` {
					i += 2
					continue
				}
				if source[i] == quote {
					i++
					break
				}
				i++
			}
			continue
		}
		if !source[i].is_letter() && source[i] != `_` {
			i++
			continue
		}
		start := i
		for i < source.len && (source[i].is_alnum() || source[i] == `_`) {
			i++
		}
		if source[start..i] != 'byte' || deprecated_byte_is_alias_base(source, start) {
			continue
		}
		mut end := i
		mut next := i
		for next < source.len && source[next] in [` `, `\t`] {
			next++
		}
		if next < source.len && source[next] == `(` {
			if close := matching_source_paren(source, next) {
				end = close + 1
			}
		}
		tc.errors << tc.make_type_error_at(.unknown_type, 'byte is deprecated, use u8 instead',
			anchor, token.new_span(file_id, start, end))
	}
}

fn deprecated_byte_is_alias_base(source string, offset int) bool {
	line_start := if offset > 0 {
		if idx := source[..offset].last_index('\n') { idx + 1 } else { 0 }
	} else {
		0
	}
	prefix := source[line_start..offset].trim_space()
	return prefix.starts_with('type ') && prefix.contains('=')
}

fn matching_source_paren(source string, open int) ?int {
	mut depth := 0
	for i := open; i < source.len; i++ {
		if source[i] == `(` {
			depth++
		} else if source[i] == `)` {
			depth--
			if depth == 0 {
				return i
			}
		} else if source[i] == `\n` && depth == 1 {
			return none
		}
	}
	return none
}

fn (tc &TypeChecker) import_module_path_pos(node flat.Node) token.Pos {
	start := node.pos.offset + 'import '.len
	file := tc.a.source_files[node.pos.id] or {
		return token.new_span(node.pos.id, start, start + node.value.len)
	}
	source := tc.source_texts_by_file[file.name] or {
		return token.new_span(node.pos.id, start, start + node.value.len)
	}
	end_limit := int_min(node.pos.end, source.len)
	if start < 0 || start >= end_limit {
		return node.pos
	}
	import_text := source[start..end_limit]
	end := if relative := import_text.index(' as ') {
		start + relative
	} else if relative := import_text.index(' {') {
		start + relative
	} else {
		end_limit
	}
	return token.new_span(node.pos.id, start, end)
}

fn (tc &TypeChecker) import_module_path_text(node flat.Node) string {
	pos := tc.import_module_path_pos(node)
	file := tc.a.source_files[pos.id] or { return node.value }
	source := tc.source_texts_by_file[file.name] or { return node.value }
	if pos.offset < 0 || pos.end > source.len || pos.end <= pos.offset {
		return node.value
	}
	return source[pos.offset..pos.end].trim_space()
}

fn (tc &TypeChecker) import_has_explicit_alias(node flat.Node) bool {
	file := tc.a.source_files[node.pos.id] or { return false }
	source := tc.source_texts_by_file[file.name] or { return false }
	start := int_max(0, node.pos.offset)
	end := int_min(node.pos.end, source.len)
	return end > start && source[start..end].contains(' as ')
}

fn (tc &TypeChecker) import_alias_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(node.pos.end, source.len)
	if end <= start {
		return node.pos
	}
	text := source[start..end]
	as_relative := text.index(' as ') or { return node.pos }
	alias_start := start + as_relative + ' as '.len
	return token.new_span(node.pos.id, alias_start, alias_start + node.typ.len)
}

fn (tc &TypeChecker) import_module_basename_pos(node flat.Node) token.Pos {
	path_pos := tc.import_module_path_pos(node)
	base_len := tc.import_module_path_text(node).all_after_last('.').len
	return token.new_span(path_pos.id, path_pos.end - base_len, path_pos.end)
}

fn (tc &TypeChecker) import_line_number(pos token.Pos) int {
	file := tc.a.source_files[pos.id] or { return 1 }
	source := tc.source_texts_by_file[file.name] or { return 1 }
	end := int_min(int_max(pos.offset, 0), source.len)
	mut line := 1
	for ch in source[..end] {
		if ch == `\n` {
			line++
		}
	}
	return line
}

// enter_file supports enter file handling for TypeChecker.
fn (mut tc TypeChecker) enter_file(file string) {
	tc.cur_file = file
	tc.cur_module = tc.file_modules[file] or { '' }
}

// enter_module supports enter module handling for TypeChecker.
fn (mut tc TypeChecker) enter_module(name string) {
	tc.cur_module = name
	if tc.cur_file.len > 0 {
		// A file's module is fixed by its own `module` declaration, which is the first
		// node after the file marker. Later passes (annotate/monomorphize) walk a node
		// array where appended, specialized nodes can place a foreign module's
		// `module_decl` after this file's marker without an intervening file marker of
		// their own; without this guard that would rebind `cur_file` to the foreign
		// module and mis-resolve same-named types (`main.Context` -> `veb.Context`).
		if existing := tc.file_modules[tc.cur_file] {
			if existing != name {
				return
			}
		}
		tc.file_modules[tc.cur_file] = name
	}
}

fn (mut tc TypeChecker) register_selective_imports(node flat.Node) {
	if node.children_count == 0 {
		return
	}
	mut info := tc.file_import_info()
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.nodes[int(child_id)]
		if child.kind != .ident {
			continue
		}
		key := file_import_key(tc.cur_file, child.value)
		if child.value in info.selective_imports {
			tc.file_selective_imports[key] = []string{}
			info.selective_imports[child.value] = []string{}
			tc.record_error_unfiltered(.unknown_fn, 'ambiguous selective import `${child.value}`',
				child_id)
			continue
		}
		mut candidates := []string{}
		path_name := '${node.value}.${child.value}'
		if path_name !in candidates {
			candidates << path_name
		}
		alias_name := '${node.typ}.${child.value}'
		if alias_name != path_name && alias_name !in candidates {
			candidates << alias_name
		}
		tc.file_selective_imports[key] = candidates
		info.selective_imports[child.value] = candidates
	}
}

// check_memos_enabled gates the per-fork qualify/import memos, so a single
// binary can A/B them (`V3_NO_CHECK_MEMOS=1` disables).
fn check_memos_enabled() bool {
	return os.getenv('V3_NO_CHECK_MEMOS') == ''
}

// ImportInfoCache pins the current file's import table so the hot
// resolve_import_alias/selective-import paths skip re-hashing the long
// file-path key on every call. Refreshed whenever the file or the registration
// table length changes; the pinned &FileImportInfo is heap-stable and its maps
// stay live through the pin. Each checker fork owns a private instance.
struct ImportInfoCache {
mut:
	file     string
	info     &FileImportInfo = unsafe { nil }
	seen_len int             = -1
}

fn (tc &TypeChecker) current_file_import_info() &FileImportInfo {
	mut cache := tc.import_info_cache
	if isnil(cache) {
		return tc.file_imports_by_file[tc.cur_file] or { return unsafe { &FileImportInfo(nil) } }
	}
	if cache.seen_len != tc.file_imports_by_file.len
		|| voidptr(cache.file.str) != voidptr(tc.cur_file.str) || cache.file.len != tc.cur_file.len {
		cache.file = tc.cur_file
		cache.seen_len = tc.file_imports_by_file.len
		cache.info = tc.file_imports_by_file[tc.cur_file] or { unsafe { &FileImportInfo(nil) } }
	}
	return cache.info
}

// resolve_import_alias resolves resolve import alias information for types.
fn (tc &TypeChecker) resolve_import_alias(alias string) ?string {
	info := tc.current_file_import_info()
	if isnil(info) {
		return none
	}
	if mod := info.imports[alias] {
		return mod
	}
	return none
}

fn (tc &TypeChecker) resolve_selective_import_symbol(name string) ?string {
	candidates := tc.selective_import_candidates(name) or {
		// Generic specializations can be checked while their cloned file context is
		// active. Recover a selected symbol from the source file only when it has one
		// unambiguous declaration across the registered imports.
		mut resolved := ''
		suffix := '\n${name}'
		for key, fallback_candidates in tc.file_selective_imports {
			if !key.ends_with(suffix) {
				continue
			}
			for candidate in fallback_candidates {
				if !tc.fn_signature_known(candidate) && candidate !in tc.fn_ret_types
					&& candidate !in tc.fn_param_types {
					continue
				}
				if resolved.len > 0 && resolved != candidate {
					return none
				}
				resolved = candidate
			}
		}
		if resolved.len > 0 {
			return resolved
		}
		return none
	}
	for candidate in candidates {
		if tc.fn_signature_known(candidate) || candidate in tc.fn_ret_types
			|| candidate in tc.fn_param_types {
			return candidate
		}
	}
	return none
}

// resolve_any_selective_import_fn resolves an unqualified selected function
// when every source file that selects the name agrees on the same declaration.
pub fn (tc &TypeChecker) resolve_any_selective_import_fn(name string) ?string {
	mut resolved := ''
	suffix := '\n${name}'
	for key, candidates in tc.file_selective_imports {
		if !key.ends_with(suffix) {
			continue
		}
		for candidate in candidates {
			if !tc.fn_signature_known(candidate) && candidate !in tc.fn_ret_types
				&& candidate !in tc.fn_param_types {
				continue
			}
			if resolved.len > 0 && resolved != candidate {
				return none
			}
			resolved = candidate
		}
	}
	if resolved.len > 0 {
		return resolved
	}
	return none
}

fn (tc &TypeChecker) resolve_selective_import_type_symbol(name string) ?string {
	candidates := tc.selective_import_candidates(name) or { return none }
	for candidate in candidates {
		if tc.type_symbol_known(candidate) {
			return candidate
		}
	}
	return none
}

fn (tc &TypeChecker) selective_import_candidates(name string) ?[]string {
	info := tc.current_file_import_info()
	if isnil(info) {
		return none
	}
	return info.selective_imports[name] or { return none }
}

fn (tc &TypeChecker) type_symbol_known(name string) bool {
	return name in tc.type_aliases || name in tc.structs || name in tc.interface_names
		|| name in tc.flag_enums || name in tc.enum_names || name in tc.sum_types
}

fn (tc &TypeChecker) unqualified_type_symbol_is_builtin(name string) bool {
	if tc.unqualified_type_symbol_has_scoped_shadow(name) {
		return false
	}
	if mod_name := tc.struct_modules[name] {
		return mod_name == 'builtin'
	}
	return name == 'IError'
}

fn (tc &TypeChecker) unqualified_type_symbol_has_scoped_shadow(name string) bool {
	if name.len == 0 {
		return false
	}
	if tc.cur_module.len > 0 && tc.cur_module != 'main' && tc.cur_module != 'builtin' {
		local := '${tc.cur_module}.${name}'
		if tc.type_symbol_known(local) {
			return true
		}
	}
	if tc.source_declares_type_in_scope(name, tc.cur_file, tc.cur_module) {
		return true
	}
	if file_import_key(tc.cur_file, name) in tc.file_selective_imports {
		if resolved := tc.resolve_selective_import_type_symbol(name) {
			return !tc.unqualified_resolved_type_symbol_is_builtin(resolved)
		}
		return true
	}
	return false
}

fn (tc &TypeChecker) unqualified_resolved_type_symbol_is_builtin(name string) bool {
	if mod_name := tc.struct_modules[name] {
		return mod_name == 'builtin'
	}
	return name == 'IError' || name == 'builtin.IError'
}

fn (tc &TypeChecker) type_from_known_symbol(name string) ?Type {
	if name in tc.type_aliases {
		return Type(Alias{
			name:      name
			base_type: tc.parse_type(tc.type_aliases[name])
		})
	}
	if name in tc.structs {
		return Type(Struct{
			name: name
		})
	}
	if name in tc.interface_names {
		return Type(Interface{
			name: name
		})
	}
	if name in tc.flag_enums {
		return Type(Enum{
			name:    name
			is_flag: true
		})
	}
	if name in tc.enum_names {
		return Type(Enum{
			name: name
		})
	}
	if name in tc.sum_types {
		return Type(SumType{
			name: name
		})
	}
	return none
}

fn (tc &TypeChecker) selective_import_symbol_is_ambiguous(name string) bool {
	candidates := tc.selective_import_candidates(name) or { return false }
	return candidates.len == 0
}

fn (tc &TypeChecker) resolve_imported_type_text(typ string) string {
	if !typ.contains('.') || typ.starts_with('C.') {
		return typ
	}
	dot := typ.index_u8(`.`)
	if dot <= 0 {
		return typ
	}
	alias := typ[..dot]
	// `main.Foo` is an explicit reference to a program-module type (bare-keyed),
	// not an import. Strip the prefix so an explicit generic argument locked to
	// `main` (see explicit_generic_concrete_arg_text) resolves to that program
	// type rather than staying a distinct `main.Foo` spelling or rebasing into
	// the active module. Only applies when `main` is not itself an import alias.
	if alias == 'main' {
		if _ := tc.resolve_import_alias('main') {
		} else {
			rest := typ[dot + 1..]
			// Transform qualifies main-module const/global references to
			// `main.<name>` for C codegen; the post-transform re-check must still
			// resolve them against the bare-keyed program symbol tables.
			if !rest.contains('.') {
				if tc.qualify_candidate_type_exists(rest) || rest in tc.const_types {
					return rest
				}
				if _ := tc.file_scope.lookup(rest) {
					return rest
				}
			}
		}
	}
	if resolved := tc.resolve_import_alias(alias) {
		if resolved != alias {
			return resolved + typ[dot..]
		}
	}
	return typ
}

// imported_type_short_name returns the semantic short name for an active imported
// module prefix. Some legacy module collections intentionally retain short symbols;
// qualified source spelling still has to resolve to those symbols.
fn (tc &TypeChecker) imported_type_short_name(typ string) ?string {
	if !typ.contains('.') || typ.starts_with('C.') {
		return none
	}
	dot := typ.index_u8(`.`)
	if dot <= 0 {
		return none
	}
	if _ := tc.resolve_import_alias(typ[..dot]) {
		return typ.all_after_last('.')
	}
	return none
}

// has_active_import reports whether has active import applies in types.
fn (tc &TypeChecker) has_active_import(alias string) bool {
	info := tc.file_imports_by_file[tc.cur_file] or { return false }
	return alias in info.imports
}

const receiver_method_suffix_ambiguous = '__v_receiver_method_suffix_ambiguous__'

fn (mut tc TypeChecker) register_mut_receiver_method(name string) {
	tc.mut_receiver_methods[name] = true
	lowered_name := tc.cached_c_name(name)
	if lowered_name != name {
		tc.mut_receiver_methods[lowered_name] = true
	}
}

// register_fn_signature updates register fn signature state for types.
fn (mut tc TypeChecker) register_fn_signature(name string, ret_type Type, params []Type, shared_params []bool, is_variadic bool, implicit_veb_ctx bool) {
	tc.register_fn_name_alias(name, ret_type, params, shared_params, is_variadic, implicit_veb_ctx)
	lowered_name := tc.cached_c_name(name)
	if lowered_name != name {
		tc.register_fn_name_alias(lowered_name, ret_type, params, shared_params, is_variadic,
			implicit_veb_ctx)
	}
	if name.ends_with('.str') {
		receiver := name.all_before_last('.')
		legacy_name := '${receiver}_str'
		if !legacy_name.contains('.') {
			tc.register_fn_name_alias(legacy_name, ret_type, params, shared_params, is_variadic,
				implicit_veb_ctx)
		}
	}
}

// register_fn_name_alias updates register fn name alias state for types.
fn (mut tc TypeChecker) register_fn_name_alias(name string, ret_type Type, params []Type, shared_params []bool, is_variadic bool, implicit_veb_ctx bool) {
	tc.fn_ret_types[name] = ret_type
	tc.fn_param_types[name] = params.clone()
	if shared_params.len > 0 {
		tc.fn_shared_params[name] = shared_params.clone()
	} else if tc.fn_shared_params.len > 0 {
		// Deleting from an empty map is a paid no-op on this hot path.
		tc.fn_shared_params.delete(name)
	}
	if tc.cur_file.len > 0 {
		tc.fn_type_files[name] = tc.cur_file
		tc.fn_type_modules[name] = tc.cur_module
	}
	tc.fn_variadic[name] = is_variadic
	if implicit_veb_ctx || tc.fn_implicit_veb_ctx.len > 0 {
		// All readers default absent entries to false, so false inserts only
		// matter once the map holds any true entry (veb builds).
		tc.fn_implicit_veb_ctx[name] = implicit_veb_ctx
	}
	tc.add_receiver_method_suffix_index(name)
}

fn (mut tc TypeChecker) add_receiver_method_suffix_index(name string) {
	if name.len == 0 {
		return
	}
	tc.set_receiver_method_suffix_index(name, name)
	if name.contains('.') {
		receiver := name.all_before_last('.')
		bracket := receiver.index_u8(`[`)
		if bracket > 0 {
			tc.set_receiver_method_suffix_index('${receiver[..bracket]}.${name.all_after_last('.')}',
				name)
		}
	}
	for i in 0 .. name.len {
		if name[i] == `.` && i + 1 < name.len {
			tc.set_receiver_method_suffix_index(name[i + 1..], name)
		}
	}
}

fn (mut tc TypeChecker) set_receiver_method_suffix_index(key string, name string) {
	if key.len == 0 {
		return
	}
	if existing := tc.receiver_method_suffix_index[key] {
		if existing != name {
			tc.receiver_method_suffix_index[key] = receiver_method_suffix_ambiguous
		}
		return
	}
	tc.receiver_method_suffix_index[key] = name
}

fn (mut tc TypeChecker) register_c_variadic_fn(name string) {
	if name.len == 0 {
		return
	}
	tc.c_variadic_fns[name] = true
	lowered_name := tc.cached_c_name(name)
	if lowered_name != name {
		tc.c_variadic_fns[lowered_name] = true
	}
	if !name.starts_with('C.') {
		tc.c_variadic_fns['C.${name}'] = true
	}
}

fn (mut tc TypeChecker) insert_fn_param_binding(p flat.Node) {
	if p.kind != .param || p.value.len == 0 {
		return
	}
	parsed_type := tc.parse_scope_param_type(p.typ)
	typ := if p.is_mut { mut_param_semantic_type(parsed_type) } else { parsed_type }
	owner := tc.cur_scope.insert_with_owner(p.value, typ)
	if p.is_mut {
		tc.fn_context.mut_param_base_types[p.value] = if p.op == .amp {
			typ
		} else {
			mut_param_base_type(typ)
		}
		tc.fn_context.mut_param_owners[p.value] = owner
	}
	if param_type_text_is_shared(p.typ) {
		tc.mark_shared_binding_owner(p.value, owner)
	}
}

fn mut_param_base_type(typ Type) Type {
	if typ is Pointer {
		return typ.base_type
	}
	return typ
}

fn mut_param_semantic_type(typ Type) Type {
	if typ !is Pointer {
		return typ
	}
	pointer_type := typ as Pointer
	if pointer_type.base_type !is OptionType {
		return typ
	}
	option_type := pointer_type.base_type as OptionType
	if option_type.base_type is Pointer {
		return typ
	}
	if option_type.base_type !is Struct {
		return typ
	}
	return Type(Pointer{
		base_type: OptionType{
			base_type: Pointer{
				base_type: option_type.base_type
			}
		}
	})
}

// annotate_types performs a scope-aware walk over every function body, tracking
// local variable types as they are declared, and records complex/contextual
// expression types. This mirrors what the v2 transformer relies on: the type
// checker runs BEFORE the transformer and publishes per-expression types, so the
// transformer can own type-dependent lowering (string ops, `in` membership, ...)
// instead of the backend.
//
// It uses a single flat scope per function (an over-approximation: a local stays
// visible after its block ends), which is harmless for type lookup since variable
// names are effectively unique within a function.
pub fn (mut tc TypeChecker) annotate_types() {
	tc.annotate_types_with_used(map[string]bool{})
}

// annotate_types_with_used annotates only functions that can be emitted when
// `used_fns` is non-empty. This mirrors transform/cgen pruning and avoids
// resolving types in dead, untransformed function bodies after markused.
pub fn (mut tc TypeChecker) annotate_types_with_used(used_fns map[string]bool) {
	tc.extend_node_caches(tc.a.nodes.len)
	tc.cur_module = ''
	for node in tc.a.nodes {
		if node.kind == .file {
			tc.enter_file(node.value)
		} else if node.kind == .module_decl {
			tc.enter_module(node.value)
		} else if node.kind == .fn_decl {
			if !tc.should_annotate_fn(node, used_fns) {
				continue
			}
			saved_fn_context := tc.fn_context
			tc.fn_context = new_function_check_context()
			tc.fn_context.generic_params = tc.infer_decl_generic_param_names(node)
			tc.fn_context.return_type = tc.parse_type(node.typ)
			tc.cur_scope = tc.file_scope
			tc.push_scope()
			for pi in 0 .. node.children_count {
				p := tc.a.child_node(&node, pi)
				tc.insert_fn_param_binding(p)
			}
			tc.insert_implicit_veb_ctx(node)
			for i in 0 .. node.children_count {
				child := tc.a.child_node(&node, i)
				if child.kind != .param {
					tc.annotate_node(tc.a.child(&node, i))
				}
			}
			tc.pop_scope()
			tc.fn_context = saved_fn_context
		}
	}
}

// diagnose_unused_private_declarations records notices for unreachable private
// functions and constants that are never referenced by any declaration.
pub fn (mut tc TypeChecker) diagnose_unused_private_declarations(used_fns map[string]bool) {
	if tc.errors.len > 0 {
		return
	}
	mut referenced_consts := map[string]bool{}
	mut referenced_fns := map[string]bool{}
	for node in tc.a.nodes {
		if node.kind in [.ident, .selector] && node.value.len > 0 {
			referenced_consts[node.value] = true
			referenced_consts[node.value.all_after_last('.')] = true
		}
		if node.kind == .call && node.children_count > 0 {
			callee := tc.a.child_node(&node, 0)
			if callee.value.len > 0 {
				referenced_fns[callee.value] = true
				referenced_fns[callee.value.all_after_last('.')] = true
			}
		}
	}
	mut module_name := ''
	for idx in tc.top_level_idx {
		node := tc.a.nodes[idx]
		if node.kind == .file {
			tc.enter_file(node.value)
			continue
		}
		if node.kind == .module_decl {
			module_name = node.value
			continue
		}
		if node.kind == .fn_decl {
			if node.op == .arrow || node.value in ['main', 'init', 'cleanup']
				|| is_v_test_fn_name(node.value) || node.value.starts_with('__anon_fn_')
				|| node.value.contains('.') {
				continue
			}
			if tc.declaration_contains_error(node) {
				continue
			}
			qname := checker_qualified_fn_name(module_name, node.value)
			cname := tc.cached_c_name(qname)
			if used_fns[node.value] || used_fns[qname] || used_fns[cname]
				|| referenced_fns[node.value] || referenced_fns[qname]
				|| referenced_fns[node.value.all_after_last('.')] {
				continue
			}
			tc.record_notice_at(.unknown_ident, 'unused function: `${node.value}`',
				flat.NodeId(idx), tc.node_value_diagnostic_pos(flat.NodeId(idx)))
			continue
		}
		if node.kind != .const_decl {
			continue
		}
		for i in 0 .. node.children_count {
			field_id := tc.a.child(&node, i)
			field := tc.a.node(field_id)
			if field.kind != .const_field || field.value.len == 0 || field.value.starts_with('C.')
				|| field.value.starts_with('_') {
				continue
			}
			qname := if module_name.len > 0 && module_name != 'main' {
				'${module_name}.${field.value}'
			} else {
				field.value
			}
			if referenced_consts[field.value] || referenced_consts[qname] {
				continue
			}
			tc.record_notice_at(.unknown_ident, 'unused constant: `${field.value}`', field_id,
				field.pos)
		}
	}
}

fn (tc &TypeChecker) declaration_contains_error(node flat.Node) bool {
	for diagnostic in tc.errors {
		if diagnostic.pos.id == node.pos.id && diagnostic.pos.offset >= node.pos.offset
			&& diagnostic.pos.offset < node.pos.end {
			return true
		}
	}
	return false
}

// check_main_module_requirement rejects ordinary programs that contain no
// selected source file in the `main` module.
pub fn (mut tc TypeChecker) check_main_module_requirement(is_shared bool) {
	if is_shared {
		return
	}
	for diagnostic in tc.errors {
		if diagnostic.msg.starts_with('invalid test file name `') {
			return
		}
	}
	mut first_module_id := flat.NodeId(-1)
	mut first_module_file := ''
	mut has_main := false
	for idx in tc.top_level_idx {
		node := tc.a.nodes[idx]
		if node.kind == .file {
			tc.enter_file(node.value)
			continue
		}
		if node.kind != .module_decl || tc.cur_file !in tc.diagnostic_files {
			continue
		}
		if int(first_module_id) < 0 {
			first_module_id = flat.NodeId(idx)
			first_module_file = tc.cur_file
		}
		if node.value == 'main' {
			has_main = true
		}
	}
	if has_main || int(first_module_id) < 0 {
		return
	}
	tc.enter_file(first_module_file)
	node := tc.a.node(first_module_id)
	file := tc.a.source_files[node.pos.id] or { &token.File{} }
	source := tc.source_texts_by_file[file.name] or { '' }
	line_start := if node.pos.offset >= 0 && node.pos.offset <= source.len {
		if idx := source[..node.pos.offset].last_index('\n') { idx + 1 } else { 0 }
	} else {
		node.pos.offset
	}
	tc.record_error_at(.duplicate_decl,
		'project must include a `main` module or be a shared library (compile with `v -shared`)',
		first_module_id, token.new_span(node.pos.id, line_start, line_start + 1))
}

fn (tc &TypeChecker) should_annotate_fn(node flat.Node, used_fns map[string]bool) bool {
	if used_fns.len == 0 {
		return true
	}
	qname := checker_qualified_fn_name(tc.cur_module, node.value)
	if qname in tc.a.export_fn_names || tc.fn_needs_implicit_veb_ctx(node) {
		return true
	}
	if node.value in used_fns {
		return true
	}
	if qname in used_fns {
		return true
	}
	cname := tc.cached_c_name(qname)
	if cname != qname && cname in used_fns {
		return true
	}
	return false
}

fn checker_qualified_fn_name(mod string, name string) string {
	if mod.len == 0 || mod == 'main' || mod == 'builtin' {
		return name
	}
	return '${mod}.${name}'
}

// annotate_node supports annotate node handling for TypeChecker.
fn (mut tc TypeChecker) annotate_node(id flat.NodeId) {
	if int(id) < 0 {
		return
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.decl_assign {
			lhs_count := tc.multi_assign_lhs_count(node)
			rhs_count := tc.multi_assign_rhs_count(node)
			if rhs_count == 1 && lhs_count > 1 {
				tc.annotate_multi_return_decl_assign(node)
				return
			}
			pair_count := if lhs_count < rhs_count { lhs_count } else { rhs_count }
			for pair_idx in 0 .. pair_count {
				lhs_id := tc.multi_assign_lhs_id(node, pair_idx)
				rhs_id := tc.multi_assign_rhs_id(node, pair_idx)
				tc.annotate_node(rhs_id)
				lhs := tc.a.nodes[int(lhs_id)]
				if lhs.kind == .ident && lhs.value.len > 0 {
					mut typ := Type(void_)
					if node.children_count == 2 && node.typ.len > 0 {
						typ = tc.parse_type(node.typ)
						tc.annotate_expected_expr(rhs_id, typ)
					} else {
						typ = tc.resolve_type(rhs_id)
					}
					if typ !is MultiReturn && typ !is Void {
						owner := tc.cur_scope.insert_with_owner(lhs.value, typ)
						if owner.storage_key().len > 0 && decl_assign_is_shared_marker(node.value) {
							tc.mark_shared_binding_owner(lhs.value, owner)
						}
						tc.remember_expr_type(lhs_id, typ)
					}
				}
			}
			return
		}
		.for_in_stmt {
			tc.annotate_for_in(id, node)
			return
		}
		.comptime_for {
			return
		}
		.fn_literal {
			tc.annotate_fn_literal(node)
			return
		}
		.selector {
			if node.children_count > 0 {
				base_id := tc.a.child(&node, 0)
				base_type := tc.resolve_type(base_id)
				if type_contains_unknown(base_type)
					|| ((base_type is OptionType || base_type is ResultType)
					&& node.value !in ['ok', 'value', 'err'])
					|| (tc.fn_context.generic_params.len > 0 && (base_type is OptionType
					|| base_type is ResultType)) {
					tc.annotate_node(base_id)
					return
				}
			}
		}
		.assign, .selector_assign, .index_assign {
			if node.children_count > 0
				&& tc.annotation_storage_path_has_unknown(tc.a.child(&node, 0)) {
				for i in 0 .. node.children_count {
					tc.annotate_node(tc.a.child(&node, i))
				}
				return
			}
			tc.annotate_assign_expected_exprs(node)
		}
		.struct_init {
			tc.annotate_struct_init_expected_exprs(node)
		}
		.call {
			if tc.fn_context.generic_params.len > 0 {
				dsl_name := tc.unresolved_array_dsl_call_name(node)
				if dsl_name.len > 0 {
					tc.push_array_dsl_scope(node, dsl_name)
				}
				for i in 0 .. node.children_count {
					tc.annotate_node(tc.a.child(&node, i))
				}
				tc.annotate_call_expected_exprs(id, node)
				if info := tc.resolve_call_info(id, node) {
					tc.remember_expr_type(id, info.return_type)
				}
				if dsl_name.len > 0 {
					tc.pop_scope()
				}
				return
			}
			tc.annotate_call_expected_exprs(id, node)
		}
		.index {
			if generic_fn_type := tc.explicit_generic_fn_value_type(node) {
				tc.remember_expr_type(id, generic_fn_type)
				return
			}
			if node.children_count > 0
				&& type_contains_unknown(tc.resolve_type(tc.a.child(&node, 0))) {
				for i in 0 .. node.children_count {
					tc.annotate_node(tc.a.child(&node, i))
				}
				return
			}
		}
		else {}
	}

	tc.remember_expr_type(id, tc.resolve_type(id))
	for i in 0 .. node.children_count {
		tc.annotate_node(tc.a.child(&node, i))
	}
}

fn (mut tc TypeChecker) annotation_storage_path_has_unknown(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind !in [.selector, .index] || node.children_count == 0 {
		return false
	}
	base_type := tc.resolve_type(tc.a.child(node, 0))
	return type_contains_unknown(base_type) || base_type is OptionType || base_type is ResultType
}

fn (mut tc TypeChecker) annotate_multi_return_decl_assign(node flat.Node) {
	rhs_id := tc.a.child(&node, 1)
	tc.annotate_node(rhs_id)
	lhs_ids := tc.multi_assign_lhs_ids(node)
	mut item_types := []Type{}
	rhs := tc.a.node(rhs_id)
	if rhs.kind == .match_stmt {
		item_types = tc.match_multi_return_types(rhs_id, lhs_ids.len) or { []Type{} }
	}
	if item_types.len == 0 {
		rhs_type := tc.resolve_type(rhs_id)
		if multi := tc.multi_return_assignment_type(rhs_id, rhs_type) {
			item_types = multi.types.clone()
		}
	}
	if item_types.len != lhs_ids.len {
		return
	}
	for i, lhs_id in lhs_ids {
		lhs := tc.a.node(lhs_id)
		if lhs.kind != .ident || lhs.value.len == 0 || lhs.value == '_' {
			continue
		}
		tc.cur_scope.insert(lhs.value, item_types[i])
		tc.remember_expr_type(lhs_id, item_types[i])
	}
}

fn (mut tc TypeChecker) annotate_fn_literal(node flat.Node) {
	saved_fn_context := tc.fn_context
	tc.fn_context = new_function_check_context()
	tc.fn_context.node_id = saved_fn_context.node_id
	tc.fn_context.generic_params = saved_fn_context.generic_params.clone()
	tc.fn_context.return_type = tc.parse_type(node.typ)
	tc.push_scope()
	for i in 0 .. node.children_count {
		tc.insert_fn_param_binding(tc.a.child_node(&node, i))
	}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind !in [.param, .ident] {
			tc.annotate_node(child_id)
		}
	}
	tc.pop_scope()
	tc.fn_context = saved_fn_context
}

fn (mut tc TypeChecker) annotate_expected_expr(id flat.NodeId, expected Type) {
	if int(id) >= 0 && int(id) < tc.a.nodes.len {
		node := tc.a.nodes[int(id)]
		if node.kind in [.if_expr, .match_stmt] && expected !is Void && expected !is Unknown {
			_ = tc.resolve_expr(id, expected)
			return
		}
	}
	if _ := fn_type_from_type(expected) {
		_ = tc.resolve_expr(id, expected)
	}
}

fn (mut tc TypeChecker) check_node_with_expected_context(id flat.NodeId, expected Type) {
	saved_id := tc.expected_expr_id
	saved_type := tc.expected_expr_type
	tc.expected_expr_id = int(id)
	tc.expected_expr_type = expected
	tc.check_node(id)
	tc.expected_expr_id = saved_id
	tc.expected_expr_type = saved_type
}

fn (tc &TypeChecker) expected_context_for_expr(id flat.NodeId) ?Type {
	if tc.expected_expr_id >= 0 && tc.expr_is_value_tail_of(flat.NodeId(tc.expected_expr_id), id)
		&& tc.expected_expr_type !is Void && tc.expected_expr_type !is Unknown {
		return tc.expected_expr_type
	}
	return tc.expr_type(id)
}

fn (tc &TypeChecker) expr_is_value_tail_of(root_id flat.NodeId, target_id flat.NodeId) bool {
	if root_id == target_id {
		return true
	}
	if !tc.valid_node_id(root_id) {
		return false
	}
	node := tc.a.nodes[int(root_id)]
	match node.kind {
		.paren, .expr_stmt {
			return node.children_count > 0
				&& tc.expr_is_value_tail_of(tc.a.child(&node, 0), target_id)
		}
		.block, .match_branch, .lock_expr {
			return node.children_count > 0
				&& tc.expr_is_value_tail_of(tc.a.child(&node, node.children_count - 1), target_id)
		}
		.or_expr {
			return node.children_count >= 2 && node.value !in ['!', '?']
				&& tc.expr_is_value_tail_of(tc.a.child(&node, 1), target_id)
		}
		.if_expr, .match_stmt {
			for i in 1 .. node.children_count {
				if tc.expr_is_value_tail_of(tc.a.child(&node, i), target_id) {
					return true
				}
			}
		}
		.comptime_if {
			for i in 0 .. node.children_count {
				if tc.expr_is_value_tail_of(tc.a.child(&node, i), target_id) {
					return true
				}
			}
		}
		else {}
	}

	return false
}

fn (mut tc TypeChecker) annotate_assign_expected_exprs(node flat.Node) {
	if node.children_count < 2 {
		return
	}
	if assignment_marker_value_is_error(node.value) {
		return
	}
	mut i := 0
	for i + 1 < node.children_count {
		lhs_id := tc.a.child(&node, i)
		rhs_id := tc.a.child(&node, i + 1)
		lhs_type := tc.resolve_lvalue_type(lhs_id)
		expected_type := tc.assignment_expected_type(lhs_id, lhs_type)
		tc.annotate_expected_expr(rhs_id, expected_type)
		i += 2
	}
}

fn (mut tc TypeChecker) annotate_struct_init_expected_exprs(node flat.Node) {
	init_type := tc.parse_type(node.value)
	init_struct := struct_type_from_type(init_type) or { return }
	init_name := tc.struct_init_field_lookup_name(node.value, init_struct.name)
	fields := tc.struct_fields_for_init(init_name)
	for i in 0 .. node.children_count {
		field := tc.a.child_node(&node, i)
		if field.kind != .field_init || field.children_count == 0 {
			continue
		}
		value_id := tc.a.child(field, 0)
		mut expected := Type(void_)
		if field.value.len > 0 {
			expected = tc.struct_field_type(init_name, field.value) or { Type(void_) }
		} else if i < fields.len {
			expected = fields[i].typ
		}
		tc.annotate_expected_expr(value_id, expected)
	}
}

fn (mut tc TypeChecker) annotate_call_expected_exprs(id flat.NodeId, node flat.Node) {
	info0 := tc.resolve_call_info(id, node) or { return }
	info := tc.specialized_plain_generic_call_info(node, info0)
	if info.name.len > 0 && !is_array_dsl_call_name(info.name) {
		tc.remember_resolved_call(id, info.name)
	}
	if tc.is_generic_enum_from_call(node) {
		tc.check_call_arg_types(id, node, info)
	}
	if !info.params_known || info.params.len == 0 {
		return
	}
	mut field_init_args := 0
	for i in 1 .. node.children_count {
		if tc.a.child_node(&node, i).kind == .field_init {
			field_init_args++
		}
	}
	collapsed := if field_init_args > 0 { 1 } else { 0 }
	recv_extra := if info.has_receiver { 1 } else { 0 }
	mut actual_count := node.children_count - 1 - info.arg_offset - field_init_args + collapsed +
		recv_extra
	for i in 1 + info.arg_offset .. node.children_count {
		arg_id := tc.call_arg_value(tc.a.child(&node, i))
		arg_type := tc.cached_expr_type(arg_id) or { tc.resolve_type(arg_id) }
		if !info.is_variadic && arg_type is MultiReturn && i == node.children_count - 1
			&& !is_print_style_fn_name(info.name) {
			actual_count += arg_type.types.len - 1
		}
	}
	ctx_count := if info.has_implicit_veb_ctx { 1 } else { 0 }
	ctx_omitted := ctx_count > 0 && actual_count < info.params.len
	mut expanded_arg_offset := 0
	for i in 1 + info.arg_offset .. node.children_count {
		raw_arg := tc.a.child_node(&node, i)
		arg_id := tc.call_arg_value(tc.a.child(&node, i))
		if raw_arg.kind == .field_init {
			tc.annotate_params_field_expected_expr(arg_id, raw_arg.value, info)
			continue
		}
		arg_shift := if ctx_omitted { ctx_count } else { 0 }
		param_idx := i - 1 - info.arg_offset + (if info.has_receiver { 1 } else { 0 }) + arg_shift +
			expanded_arg_offset
		if info.is_c_variadic && param_idx >= c_variadic_fixed_param_count(info) {
			continue
		}
		if param_idx >= info.params.len {
			continue
		}
		arg_type := tc.cached_expr_type(arg_id) or { tc.resolve_type(arg_id) }
		if !info.is_variadic && arg_type is MultiReturn && i == node.children_count - 1
			&& arg_type.types.len == info.params.len - param_idx {
			expanded_arg_offset += arg_type.types.len - 1
			continue
		}
		expected := tc.call_arg_expected_type(info, param_idx)
		dsl_name := if is_array_dsl_call_name(info.name) {
			info.name
		} else {
			tc.unresolved_array_dsl_call_name(node)
		}
		needs_dsl_scope := tc.call_arg_needs_array_dsl_scope(dsl_name, param_idx)
		if needs_dsl_scope {
			tc.push_array_dsl_scope(node, dsl_name)
		}
		tc.annotate_expected_expr(arg_id, expected)
		if needs_dsl_scope {
			tc.pop_scope()
		}
	}
}

fn (tc &TypeChecker) call_arg_expected_type(info CallInfo, param_idx int) Type {
	expected := info.params[param_idx]
	if info.is_variadic && param_idx == info.params.len - 1 && expected is Array {
		return array_elem_type(expected)
	}
	return expected
}

fn (mut tc TypeChecker) annotate_params_field_expected_expr(arg_id flat.NodeId, field_name string, info CallInfo) {
	if expected := tc.params_field_expected_type(field_name, info) {
		tc.annotate_expected_expr(arg_id, expected)
	}
}

fn (tc &TypeChecker) params_field_expected_type(field_name string, info CallInfo) ?Type {
	if field_name.len == 0 {
		return none
	}
	for param in info.params {
		param_struct := struct_type_from_type(unwrap_pointer(param)) or { continue }
		if expected := tc.struct_field_type(param_struct.name, field_name) {
			return expected
		}
	}
	return none
}

fn (tc &TypeChecker) params_field_owner(field_name string, info CallInfo) ?string {
	if field_name.len == 0 {
		return none
	}
	for param in info.params {
		param_struct := struct_type_from_type(unwrap_pointer(param)) or { continue }
		if tc.struct_field_type(param_struct.name, field_name) != none {
			return param_struct.name
		}
	}
	return none
}

fn params_field_owner_display(owner string) string {
	parts := owner.split('.')
	if parts.len > 1 {
		return parts[parts.len - 2..].join('.')
	}
	return owner
}

// annotate_for_in supports annotate for in handling for TypeChecker.
fn (mut tc TypeChecker) annotate_for_in(_id flat.NodeId, node flat.Node) {
	header := node.value.int()
	if header < 3 || node.children_count < 3 {
		return
	}
	key_id := tc.a.child(&node, 0)
	val_id := tc.a.child(&node, 1)
	container_id := tc.a.child(&node, 2)
	tc.annotate_node(container_id)
	has_val := int(val_id) >= 0
	if header == 4 {
		tc.insert_loop_var(key_id, tc.range_loop_var_type(container_id))
		tc.annotate_node(tc.a.child(&node, 3))
	} else {
		clean := tc.for_in_iterable_type(container_id)
		yields_ref := node.op == .amp || tc.for_in_iterable_yields_ref(container_id)
		if clean is Array {
			elem_type := for_in_ref_binding_type(clean.elem_type, yields_ref)
			if has_val {
				tc.insert_loop_var(key_id, Type(int_))
				if node.op == .amp {
					tc.insert_mut_loop_var(val_id, elem_type)
				} else {
					tc.insert_loop_var(val_id, elem_type)
				}
			} else {
				if node.op == .amp {
					tc.insert_mut_loop_var(key_id, elem_type)
				} else {
					tc.insert_loop_var(key_id, elem_type)
				}
			}
		} else if clean is ArrayFixed {
			elem_type := for_in_ref_binding_type(clean.elem_type, yields_ref)
			if has_val {
				tc.insert_loop_var(key_id, Type(int_))
				if node.op == .amp {
					tc.insert_mut_loop_var(val_id, elem_type)
				} else {
					tc.insert_loop_var(val_id, elem_type)
				}
			} else {
				if node.op == .amp {
					tc.insert_mut_loop_var(key_id, elem_type)
				} else {
					tc.insert_loop_var(key_id, elem_type)
				}
			}
		} else if clean is Map {
			value_type := for_in_ref_binding_type(clean.value_type, yields_ref)
			if has_val {
				tc.insert_loop_var(key_id, clean.key_type)
				if node.op == .amp {
					tc.insert_mut_loop_var(val_id, value_type)
				} else {
					tc.insert_loop_var(val_id, value_type)
				}
			} else {
				if node.op == .amp {
					tc.insert_mut_loop_var(key_id, value_type)
				} else {
					tc.insert_loop_var(key_id, value_type)
				}
			}
		} else if clean is String {
			if has_val {
				tc.insert_loop_var(key_id, Type(int_))
				tc.insert_loop_var(val_id, Type(u8_))
			} else {
				tc.insert_loop_var(key_id, Type(u8_))
			}
		} else if elem_type := tc.iterator_for_in_elem_type(clean) {
			if has_val {
				tc.insert_loop_var(key_id, Type(int_))
				tc.insert_loop_var(val_id, elem_type)
			} else {
				tc.insert_loop_var(key_id, elem_type)
			}
		} else {
			container := tc.a.nodes[int(container_id)]
			if container.kind == .range {
				tc.insert_loop_var(key_id, tc.range_loop_var_type(tc.a.child(&container, 0)))
			}
		}
	}
	for i in header .. node.children_count {
		tc.annotate_node(tc.a.child(&node, i))
	}
}

fn (tc &TypeChecker) for_in_iterable_type(container_id flat.NodeId) Type {
	mut clean := unwrap_pointer(tc.resolve_type(container_id))
	for _ in 0 .. 8 {
		if clean is Alias {
			clean = clean.base_type
			continue
		}
		if clean is OptionType {
			base := unalias_type(unwrap_pointer(clean.base_type))
			if base is Array || base is ArrayFixed {
				clean = base
				continue
			}
		}
		break
	}
	return clean
}

fn (tc &TypeChecker) for_in_iterable_yields_ref(container_id flat.NodeId) bool {
	if tc.expr_is_shared_arg(container_id) {
		return false
	}
	mut typ := tc.resolve_type(container_id)
	for _ in 0 .. 8 {
		if typ is Alias {
			typ = typ.base_type
			continue
		}
		if typ is OptionType {
			base := typ.base_type
			clean_base := unalias_type(unwrap_pointer(base))
			if clean_base is Array || clean_base is ArrayFixed {
				typ = base
				continue
			}
		}
		break
	}
	if typ is Pointer {
		base := unalias_type(typ.base_type)
		return base is Array || base is ArrayFixed || base is Map
	}
	return false
}

pub fn (tc &TypeChecker) iterator_for_in_elem_type(typ Type) ?Type {
	info := tc.iterator_for_in_next_call_info(typ) or { return none }
	return iterator_for_in_elem_type_from_next_return(info.return_type)
}

fn (tc &TypeChecker) iterator_unbounded_next_generic(typ Type) ?string {
	info := tc.iterator_for_in_next_call_info(typ) or { return none }
	type_name := resolve_type_name_for_method(unwrap_pointer(typ))
	base, _, is_generic := generic_type_application_parts(type_name)
	owner_name := if is_generic { base } else { type_name }
	owner_params := tc.struct_generic_params[owner_name] or {
		tc.struct_generic_params[tc.qualify_name(owner_name)] or { []string{} }
	}
	method_params := tc.fn_generic_params[info.name] or {
		mut found := []string{}
		for candidate in receiver_method_name_candidates(unwrap_pointer(typ), 'next', tc.cur_module) {
			if params := tc.fn_generic_params[candidate] {
				found = params.clone()
				break
			}
		}
		found
	}
	for param in method_params {
		if param !in owner_params {
			return param
		}
	}
	return none
}

pub fn (tc &TypeChecker) iterator_for_in_next_call_info(typ Type) ?CallInfo {
	clean := unwrap_pointer(typ)
	name := clean.name()
	if name == 'RunesIterator' || name == 'builtin.RunesIterator' {
		return CallInfo{
			name:         'RunesIterator.next'
			params:       tarr1(Type(Pointer{
				base_type: clean
			}))
			return_type:  Type(OptionType{
				base_type: Type(rune_)
			})
			has_receiver: true
			params_known: true
		}
	}
	type_name := resolve_type_name_for_method(clean)
	if type_name.len == 0 {
		return none
	}
	if info := tc.resolve_generic_struct_method(type_name, 'next') {
		if _ := iterator_for_in_elem_type_from_next_return(info.return_type) {
			return tc.specialize_generic_interface_method(type_name, info)
		}
	}
	for method_name in receiver_method_name_candidates(clean, 'next', tc.cur_module) {
		if method_name !in tc.fn_ret_types {
			continue
		}
		info := tc.call_info(method_name, true)
		if _ := iterator_for_in_elem_type_from_next_return(info.return_type) {
			return tc.specialize_generic_interface_method(type_name, info)
		}
	}
	return none
}

// iterator_for_in_next_call_info_text returns the specialized `next` call metadata for an iterator type.
pub fn (tc &TypeChecker) iterator_for_in_next_call_info_text(type_text string) ?CallInfo {
	info := tc.iterator_for_in_next_call_info(tc.parse_type(type_text)) or { return none }
	return tc.specialize_generic_interface_method(type_text.trim_left('&'), info)
}

fn (tc &TypeChecker) specialize_generic_interface_method(type_name string, info CallInfo) CallInfo {
	base, args, is_generic := generic_type_application_parts(type_name)
	if !is_generic || args.len == 0 {
		return info
	}
	params := tc.interface_generic_params[base] or {
		tc.interface_generic_params[tc.qualify_name(base)] or { return info }
	}
	if params.len != args.len {
		return info
	}
	mut concrete_types := []Type{cap: args.len}
	for arg in args {
		concrete_types << tc.parse_type(tc.qualify_resolution_type_text(arg))
	}
	mut specialized_params := []Type{cap: info.params.len}
	for param in info.params {
		specialized_params << tc.substitute_generic_type_values(param, concrete_types, params)
	}
	return CallInfo{
		...info
		params:      specialized_params
		return_type: tc.substitute_generic_type_values(info.return_type, concrete_types, params)
	}
}

pub fn (tc &TypeChecker) index_overload_call_info(typ Type, setter bool) ?CallInfo {
	method := if setter { '[]=' } else { '[]' }
	clean := unwrap_pointer(typ)
	type_name := resolve_type_name_for_method(clean)
	if type_name.len == 0 {
		return none
	}
	if info := tc.resolve_generic_struct_method(type_name, method) {
		return tc.specialized_index_overload_call_info(type_name, method, info)
	}
	if concrete := tc.concrete_method_signature_key(type_name, method) {
		return tc.call_info(concrete, true)
	}
	for method_name in receiver_method_name_candidates(clean, method, tc.cur_module) {
		if method_name !in tc.fn_ret_types {
			continue
		}
		if !tc.method_can_be_called_on_receiver(typ, method, method_name) {
			continue
		}
		return tc.call_info(method_name, true)
	}
	return none
}

fn (tc &TypeChecker) specialized_index_overload_call_info(type_name string, method string, info CallInfo) CallInfo {
	concrete := tc.concrete_method_signature_key(type_name, method) or {
		_, args, ok := generic_type_application_parts(type_name)
		if !ok || args.len == 0 {
			return info
		}
		'${type_name}.${method}'
	}
	if concrete == info.name {
		return info
	}
	return CallInfo{
		name:                 concrete
		params:               info.params.clone()
		shared_params:        info.shared_params.clone()
		return_type:          info.return_type
		has_receiver:         info.has_receiver
		is_variadic:          info.is_variadic
		is_c_variadic:        info.is_c_variadic
		params_known:         info.params_known
		has_implicit_veb_ctx: info.has_implicit_veb_ctx
		arg_offset:           info.arg_offset
	}
}

fn iterator_for_in_elem_type_from_next_return(ret Type) ?Type {
	if ret is OptionType {
		return ret.base_type
	}
	return none
}

fn (tc &TypeChecker) range_loop_var_type(low_id flat.NodeId) Type {
	low_type := tc.resolve_type(low_id)
	if fn_param_unalias_type(low_type).is_integer() {
		return low_type
	}
	return Type(int_)
}

// insert_loop_var updates insert loop var state for types.
fn (mut tc TypeChecker) insert_loop_var(id flat.NodeId, typ Type) ScopeBindingOwner {
	if int(id) < 0 {
		return ScopeBindingOwner{}
	}
	v := tc.a.nodes[int(id)]
	if v.kind == .ident && v.value.len > 0 {
		owner := tc.cur_scope.insert_with_owner(v.value, typ)
		tc.remember_expr_type(id, typ)
		return owner
	}
	return ScopeBindingOwner{}
}

fn (mut tc TypeChecker) insert_mut_loop_var(id flat.NodeId, typ Type) {
	owner := tc.insert_loop_var(id, typ)
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return
	}
	v := tc.a.nodes[int(id)]
	if v.kind != .ident || v.value.len == 0 || v.value == '_' {
		return
	}
	tc.fn_context.mut_local_owners[v.value] = owner
	if typ is Pointer {
		tc.fn_context.mut_param_base_types[v.value] = typ.base_type
	}
}

fn for_in_ref_binding_type(typ Type, yields_ref bool) Type {
	if yields_ref && typ !is Pointer {
		return Type(Pointer{
			base_type: typ
		})
	}
	return typ
}

// expr_type returns the resolved type recorded for a node during annotate_types.
pub fn (tc &TypeChecker) expr_type(id flat.NodeId) ?Type {
	if t := tc.resolved_call_type(id) {
		return t
	}
	if int(id) >= 0 {
		node := tc.a.nodes[int(id)]
		if node.kind == .call && node.typ.len > 0 && node.typ !in ['int', 'array', 'map', 'unknown'] {
			return tc.parse_type(node.typ)
		}
	}
	if t := tc.cached_expr_type(id) {
		return t
	}
	return none
}

// resolved_call_type supports resolved call type handling for TypeChecker.
fn (tc &TypeChecker) resolved_call_type(id flat.NodeId) ?Type {
	if int(id) < 0 {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind != .call {
		return none
	}
	if t := tc.cached_expr_type(id) {
		if t !is Void {
			return t
		}
	}
	if name := tc.cached_resolved_call(id) {
		if t := tc.fn_ret_types[name] {
			return t
		}
	}
	return none
}

// in_check_range reports whether idx belongs to the fn item currently being
// checked (whose node-cache slots this checker exclusively owns).
@[inline]
fn (tc &TypeChecker) in_check_range(idx int) bool {
	return idx >= tc.check_range_lo && idx <= tc.check_range_hi
}

// cached_expr_type supports cached expr type handling for TypeChecker.
fn (tc &TypeChecker) cached_expr_type(id flat.NodeId) ?Type {
	idx := int(id)
	if tc.parallel_check_sparse {
		if tc.in_check_range(idx) {
			if idx < tc.expr_type_set.len && tc.expr_type_set[idx] {
				return tc.expr_type_values[idx]
			}
			return none
		}
		return tc.sparse_expr_type_values[idx] or { none }
	}
	if idx >= 0 && idx < tc.expr_type_set.len && tc.expr_type_set[idx] {
		return tc.expr_type_values[idx]
	}
	return none
}

// cached_resolved_call supports cached resolved call handling for TypeChecker.
fn (tc &TypeChecker) cached_resolved_call(id flat.NodeId) ?string {
	idx := int(id)
	if !isnil(tc.fork_overlay) {
		if name := tc.fork_overlay.resolved_call_names[idx] {
			return name
		}
	}
	if tc.parallel_check_sparse {
		if tc.in_check_range(idx) {
			if idx < tc.resolved_call_set.len && tc.resolved_call_set[idx] {
				return tc.resolved_call_names[idx]
			}
			return none
		}
		return tc.sparse_resolved_call_names[idx] or { none }
	}
	if idx >= 0 && idx < tc.resolved_call_set.len && tc.resolved_call_set[idx] {
		return tc.resolved_call_names[idx]
	}
	return none
}

// resolved_call_name returns the checker-resolved function name for a call node.
pub fn (tc &TypeChecker) resolved_call_name(id flat.NodeId) ?string {
	return tc.cached_resolved_call(id)
}

// reset_resolved_calls_for_reannotation discards pre-transform call-name
// bindings before the transformed AST is annotated again. The annotation walk
// resolves and records every reachable call against the final AST/signatures.
pub fn (mut tc TypeChecker) reset_resolved_calls_for_reannotation() {
	for idx in 0 .. tc.resolved_call_set.len {
		tc.resolved_call_set[idx] = false
	}
	tc.sparse_resolved_call_names.clear()
}

// fn_param_types_for_name returns the collected parameter types for a resolved call name.
pub fn (tc &TypeChecker) fn_param_types_for_name(name string) []Type {
	if params := tc.fn_param_types[name] {
		return params
	}
	if name.len == 0 {
		return []Type{}
	}
	mut found := []Type{}
	mut matches := 0
	for candidate, params in tc.fn_param_types {
		if candidate.ends_with('.${name}') {
			found = params.clone()
			matches++
			if matches > 1 {
				return []Type{}
			}
		}
	}
	return found
}

// resolved_call_never_returns reports whether a call node resolved to a known no-return function.
pub fn (tc &TypeChecker) resolved_call_never_returns(id flat.NodeId) bool {
	name := tc.resolved_call_name(id) or { return false }
	return tc.name_never_returns(name)
}

fn resolved_name_never_returns(name string) bool {
	return name in ['panic', 'exit', 'os.exit', 'C.exit']
}

// name_never_returns reports whether a resolved call name is a builtin no-return
// function or one declared with the `@[noreturn]` attribute.
fn (tc &TypeChecker) name_never_returns(name string) bool {
	if resolved_name_never_returns(name) {
		return true
	}
	return name in tc.a.noreturn_fns
}

// resolved_fn_value_name returns the checker-resolved function name for a function value node.
pub fn (tc &TypeChecker) resolved_fn_value_name(id flat.NodeId) ?string {
	idx := int(id)
	if !isnil(tc.fork_overlay) {
		if name := tc.fork_overlay.resolved_fn_values[idx] {
			return name
		}
	}
	if tc.parallel_check_sparse {
		if tc.in_check_range(idx) {
			if idx < tc.resolved_fn_value_set.len && tc.resolved_fn_value_set[idx] {
				return tc.resolved_fn_value_names[idx]
			}
			return none
		}
		return tc.sparse_resolved_fn_values[idx] or { none }
	}
	if idx >= 0 && idx < tc.resolved_fn_value_set.len && tc.resolved_fn_value_set[idx] {
		return tc.resolved_fn_value_names[idx]
	}
	return none
}

// clear_resolved_fn_value removes stale function-value metadata after a later
// transform proves that an identifier refers to a value declaration.
pub fn (mut tc TypeChecker) clear_resolved_fn_value(id flat.NodeId) {
	idx := int(id)
	if idx < 0 {
		return
	}
	if !isnil(tc.fork_overlay) {
		tc.fork_overlay.resolved_fn_values.delete(idx)
	}
	if idx < tc.resolved_fn_value_set.len {
		tc.resolved_fn_value_names[idx] = ''
		tc.resolved_fn_value_set[idx] = false
	}
	if tc.sparse_resolved_fn_values.len > 0 {
		tc.sparse_resolved_fn_values.delete(idx)
	}
}

// direct_dependency_ids returns the checker-resolved function dependency
// identities of a function declaration node. The slice is read-only.
pub fn (tc &TypeChecker) direct_dependency_ids(fn_node_id int) []SymbolId {
	return tc.direct_dependencies_by_fn[fn_node_id] or { []SymbolId{} }
}

// direct_dependencies returns canonical dependency names for compatibility.
pub fn (tc &TypeChecker) direct_dependencies(fn_node_id int) []string {
	ids := tc.direct_dependency_ids(fn_node_id)
	mut names := []string{cap: ids.len}
	for id in ids {
		names << tc.symbol_name(id)
	}
	return names
}

fn (mut tc TypeChecker) record_direct_dependency(name string) {
	if tc.fn_context.node_id < 0 || name.len == 0 {
		return
	}
	id, _ := tc.intern_symbol(name)
	mut dependencies := tc.direct_dependencies_by_fn[tc.fn_context.node_id] or { []SymbolId{} }
	if id !in dependencies {
		dependencies << id
		tc.direct_dependencies_by_fn[tc.fn_context.node_id] = dependencies
	}
}

fn (tc &TypeChecker) intern_symbol(name string) (SymbolId, string) {
	if isnil(tc.symbols) {
		return SymbolId(0), name
	}
	mut symbols := unsafe { tc.symbols }
	return symbols.intern(name)
}

// symbol_name resolves a checker symbol identity to its canonical name.
pub fn (tc &TypeChecker) symbol_name(id SymbolId) string {
	if isnil(tc.symbols) {
		return ''
	}
	mut symbols := unsafe { tc.symbols }
	return symbols.name(id)
}

// canonical_symbol returns the compilation-owned canonical spelling of name.
pub fn (tc &TypeChecker) canonical_symbol(name string) string {
	_, canonical := tc.intern_symbol(name)
	return canonical
}

// symbol_count returns the number of resolved names interned by the checker.
pub fn (tc &TypeChecker) symbol_count() int {
	if isnil(tc.symbols) {
		return 0
	}
	mut symbols := unsafe { tc.symbols }
	return symbols.len()
}

// copy_cloned_resolution copies checker-owned call/function-value resolution metadata
// from an original node to a transform-created clone.
pub fn (mut tc TypeChecker) copy_cloned_resolution(src_id flat.NodeId, dst_id flat.NodeId) {
	if name := tc.resolved_call_name(src_id) {
		tc.remember_resolved_call(dst_id, name)
	}
	if name := tc.resolved_fn_value_name(src_id) {
		tc.remember_resolved_fn_value(dst_id, name)
	}
}

// resolve_fn_value_name_for_expected resolves and records a function value in an expected FnType context.
fn (mut tc TypeChecker) resolve_fn_value_name_for_expected(id flat.NodeId, expected Type) ?string {
	if name := tc.resolved_fn_value_name(id) {
		actual := tc.fn_type_from_key(name) or { return none }
		if tc.fn_value_signature_compatible(actual, expected) {
			return name
		}
		return none
	}
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return none
	}
	node := tc.a.nodes[int(id)]
	if tc.fn_value_shadowed_by_value(node) {
		return none
	}
	key := tc.fn_value_match_key(node, expected) or { return none }
	tc.remember_resolved_fn_value_chain(id, key)
	return key
}

// remember_resolved_call supports remember resolved call handling for TypeChecker.
fn (mut tc TypeChecker) remember_resolved_call(id flat.NodeId, name string) {
	idx := int(id)
	if idx < 0 {
		return
	}
	canonical := tc.canonical_symbol(name)
	tc.record_direct_dependency(canonical)
	if tc.parallel_check_sparse {
		if tc.in_check_range(idx) && idx < tc.resolved_call_names.len {
			tc.resolved_call_names[idx] = canonical
			tc.resolved_call_set[idx] = true
			return
		}
		tc.sparse_resolved_call_names[idx] = canonical
		return
	}
	if idx >= tc.resolved_call_names.len {
		tc.extend_node_caches(tc.a.nodes.len)
	}
	if idx < tc.resolved_call_names.len {
		tc.resolved_call_names[idx] = canonical
		tc.resolved_call_set[idx] = true
	}
}

// remember_resolved_fn_value records the exact function declaration used by a function value.
fn (mut tc TypeChecker) remember_resolved_fn_value(id flat.NodeId, name string) {
	idx := int(id)
	if idx < 0 {
		return
	}
	canonical := tc.canonical_symbol(name)
	tc.record_direct_dependency(canonical)
	if tc.parallel_check_sparse {
		if tc.in_check_range(idx) && idx < tc.resolved_fn_value_names.len {
			tc.resolved_fn_value_names[idx] = canonical
			tc.resolved_fn_value_set[idx] = true
			return
		}
		tc.sparse_resolved_fn_values[idx] = canonical
		return
	}
	if idx >= tc.resolved_fn_value_names.len {
		tc.extend_node_caches(tc.a.nodes.len)
	}
	if idx < tc.resolved_fn_value_names.len {
		tc.resolved_fn_value_names[idx] = canonical
		tc.resolved_fn_value_set[idx] = true
	}
}

fn (mut tc TypeChecker) remember_resolved_fn_value_chain(id flat.NodeId, name string) {
	tc.remember_resolved_fn_value(id, name)
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return
	}
	node := tc.a.nodes[int(id)]
	if node.kind in [.cast_expr, .paren, .expr_stmt] && node.children_count > 0 {
		tc.remember_resolved_fn_value_chain(tc.a.child(&node, 0), name)
	}
}

// register_synth_type records the type of a generated or transformed node.
pub fn (mut tc TypeChecker) register_synth_type(id flat.NodeId, typ Type) {
	tc.remember_expr_type(id, typ)
}

// remember_expr_type supports remember expr type handling for TypeChecker.
fn (mut tc TypeChecker) remember_expr_type(id flat.NodeId, typ Type) {
	if int(id) < 0 {
		return
	}
	kind := if int(id) < tc.a.nodes.len { tc.a.nodes[int(id)].kind } else { flat.NodeKind.empty }
	if should_cache_expr_type(kind, typ) {
		idx := int(id)
		if tc.parallel_check_sparse {
			if tc.in_check_range(idx) && idx < tc.expr_type_values.len {
				tc.expr_type_values[idx] = typ
				tc.expr_type_set[idx] = true
				return
			}
			tc.sparse_expr_type_values[idx] = typ
			return
		}
		if idx >= tc.expr_type_values.len {
			tc.extend_node_caches(tc.a.nodes.len)
		}
		if idx < tc.expr_type_values.len {
			tc.expr_type_values[idx] = typ
			tc.expr_type_set[idx] = true
		}
	}
}

// should_cache_expr_type reports whether should cache expr type applies in types.
fn should_cache_expr_type(kind flat.NodeKind, typ Type) bool {
	if typ is Void {
		return kind in [.sql_expr, .or_expr]
	}
	if typ is Unknown {
		return false
	}
	if typ is Array || typ is ArrayFixed || typ is Map || typ is Pointer || typ is FnType
		|| typ is OptionType || typ is ResultType || typ is Struct || typ is Interface
		|| typ is Enum || typ is SumType || typ is Alias || typ is MultiReturn {
		return true
	}
	kind_id := int(kind)
	return kind_id != 1 && kind_id != 2 && kind_id != 3 && kind_id != 4 && kind_id != 5
		&& kind_id != 28
}

// check_semantics validates check semantics state for types.
pub fn (mut tc TypeChecker) check_semantics() {
	tc.resolution_type_mode = false
	tc.checked_const_names = map[string]bool{}
	tc.check_comptime_struct_updates_preflight()
	tc.collect_selected_file_called_fns()
	tc.check_export_attrs()
	tc.check_import_diagnostics()
	tc.check_c_js_generic_declarations()
	tc.check_duplicate_fn_declarations()
	tc.check_deprecated_byte_types()
	tc.check_interface_reserved_parameter_names()
	tc.check_goto_labels()
	tc.check_labelled_loop_controls()
	tc.cur_module = ''
	tc.cur_file = ''
	blocking_import_files := tc.blocking_import_error_files()
	mut skip_file_semantics := false
	mut previous_top_level := -1
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		range_lo := previous_top_level + 1
		previous_top_level = i
		if node.kind == .file {
			skip_file_semantics = blocking_import_files[node.value]
		} else if skip_file_semantics && node.kind != .module_decl {
			continue
		}
		match node.kind {
			.file {
				tc.enter_file(node.value)
				if !skip_file_semantics {
					tc.check_top_level_file_statements(node)
				}
			}
			.module_decl {
				tc.enter_module(node.value)
				node_id := flat.NodeId(i)
				tc.check_invalid_test_file_name(node_id, node)
				if tc.should_check_source_name(node_id) && !snake_case_name_is_valid(node.value) {
					tc.check_snake_case_name(node_id, node.value, 'module name', tc.declaration_keyword_name_pos(node_id,
						'module'))
				}
			}
			.struct_decl {
				node_id := flat.NodeId(i)
				if 'typedef' in node.typ.split(',') && !node.value.starts_with('C.') {
					tc.record_error_at(.assignment_mismatch,
						'`typedef` attribute can only be used with C structs', node_id, tc.declaration_keyword_name_pos(node_id,
						'struct'))
				}
				if tc.should_check_source_name(node_id) && !pascal_case_name_is_valid(node.value) {
					tc.check_pascal_case_name(node_id, node.value, 'struct name', tc.declaration_keyword_name_pos(node_id,
						'struct'))
				}
				tc.check_decl_type_strings(flat.NodeId(i), node)
				tc.check_struct_implements(flat.NodeId(i), node)
				tc.check_struct_field_defaults(node_id, node)
			}
			.type_decl, .interface_decl {
				node_id := flat.NodeId(i)
				if node.kind == .interface_decl {
					if tc.should_check_source_name(node_id)
						&& !pascal_case_name_is_valid(node.value) {
						tc.check_pascal_case_name(node_id, node.value, 'interface name',
							tc.source_line_declaration_pos(node_id))
					}
					tc.check_interface_member_names(node)
				} else {
					type_kind := if node.children_count > 0 {
						'sum type'
					} else if node.typ.starts_with('fn') {
						'fn type'
					} else {
						'type alias'
					}
					if tc.should_check_source_name(node_id)
						&& !pascal_case_name_is_valid(node.value) {
						tc.check_pascal_case_name(node_id, node.value, type_kind, tc.declaration_keyword_name_pos(node_id,
							'type'))
					}
					if tc.type_declaration_exists_before(node_id, node.value) {
						kind := if node.children_count > 0
							|| split_sum_variant_texts(node.typ).len > 1 {
							'sum type'
						} else {
							'alias'
						}
						tc.record_error_at(.duplicate_decl,
							'cannot register ${kind} `${node.value}`, another type with this name exists',
							node_id, tc.declaration_keyword_name_pos(node_id, 'type'))
					}
				}
				tc.check_decl_type_strings(flat.NodeId(i), node)
			}
			.enum_decl {
				node_id := flat.NodeId(i)
				if tc.should_check_source_name(node_id) && !pascal_case_name_is_valid(node.value) {
					tc.check_pascal_case_name(node_id, node.value, 'enum name', tc.declaration_keyword_name_pos(node_id,
						'enum'))
				}
				tc.check_enum_backing_type(flat.NodeId(i), node)
				tc.check_enum_field_values(flat.NodeId(i), node)
			}
			.const_decl {
				tc.check_const_field_values(node)
			}
			.global_decl {
				if !tc.enable_globals && !tc.has_globals_files[tc.cur_file] {
					tc.record_error_at(.duplicate_decl,
						'use `v -enable-globals ...` to enable globals', flat.NodeId(i), node.pos)
				}
				tc.check_const_global_initializers(node)
			}
			.fn_decl {
				tc.check_fn_declaration_name(flat.NodeId(i), node)
				tc.check_method_field_name_collision(flat.NodeId(i), node)
				tc.check_main_fn_signature(flat.NodeId(i), node)
				tc.check_init_fn_signature(flat.NodeId(i), node)
				tc.check_str_method_signature(flat.NodeId(i), node)
				tc.check_free_method_signature(flat.NodeId(i), node)
				tc.check_sumtype_builtin_method_override(flat.NodeId(i), node)
				tc.check_test_fn_signature(flat.NodeId(i), node)
				tc.check_decl_type_strings(flat.NodeId(i), node)
				if tc.scope_parallel_check_workers {
					tc.check_fn_decl_semantics_scoped(i, range_lo, tc.cur_file, tc.cur_module)
				} else {
					tc.check_fn_decl_semantics(i, node, tc.cur_file, tc.cur_module)
				}
			}
			.c_fn_decl {
				tc.check_main_fn_signature(flat.NodeId(i), node)
				if tc.reject_unsupported_generics {
					tc.check_decl_type_strings(flat.NodeId(i), node)
				}
			}
			else {}
		}

		_ = i
	}
	tc.check_test_file_has_test_fn()
	tc.check_array_decompose_counts()
	tc.check_selective_builtin_import_diagnostics()
	tc.check_unused_import_diagnostics()
	tc.notices.sort_with_compare(compare_type_notices)
	// All ordinary source annotations have now been validated with module-strict
	// lookup. Later transform/codegen stages also parse synthesized generic type
	// text, where concrete arguments can legitimately come from another module.
	tc.resolution_type_mode = true
}

fn (mut tc TypeChecker) check_fn_decl_semantics_scoped(fn_idx int, range_lo int, file string, module_name string) {
	item := CheckWorkItem{
		fn_idx:   fn_idx
		range_lo: range_lo
		file:     file
		module:   module_name
	}
	scope := check_worker_scope_begin(true)
	mut scoped := tc.fork_for_parallel_check()
	scoped.check_fn_items_serial([item])
	check_worker_scope_leave(scope)
	tc.clone_parallel_worker_node_caches([item])
	tc.merge_parallel_check_worker_scoped(scoped, true)
	check_worker_scope_free(scope)
}

fn (tc &TypeChecker) blocking_import_error_files() map[string]bool {
	mut files := map[string]bool{}
	mut file := ''
	mut module_name := ''
	for idx in tc.top_level_idx {
		node := tc.a.node(flat.NodeId(idx))
		if node.kind == .file {
			file = node.value
			module_name = tc.file_modules[file] or { '' }
			continue
		}
		if node.kind != .import_decl {
			continue
		}
		if _ := tc.a.missing_imports[idx] {
			files[file] = true
		}
		if node.typ == module_name {
			files[file] = true
		}
	}
	return files
}

fn (mut tc TypeChecker) check_selective_builtin_import_diagnostics() {
	for idx in tc.top_level_idx {
		node := tc.a.node(flat.NodeId(idx))
		if node.kind == .file {
			tc.enter_file(node.value)
			continue
		}
		if node.kind == .module_decl {
			tc.enter_module(node.value)
			continue
		}
		if node.kind != .import_decl {
			continue
		}
		for i in 0 .. node.children_count {
			child_id := tc.a.child(node, i)
			child := tc.a.node(child_id)
			if child.kind == .ident && is_builtin_type_name(child.value) {
				tc.record_error_at(.unknown_type, 'cannot import or override builtin type',
					child_id, tc.node_value_diagnostic_pos(child_id))
			}
		}
	}
}

fn (mut tc TypeChecker) check_c_js_generic_declarations() {
	for declaration_kind in [flat.NodeKind.struct_decl, flat.NodeKind.fn_decl] {
		tc.cur_module = ''
		tc.cur_file = ''
		for index in tc.top_level_idx {
			node := tc.a.node(flat.NodeId(index))
			if node.kind == .file {
				tc.enter_file(node.value)
				continue
			}
			if node.kind == .module_decl {
				tc.enter_module(node.value)
				continue
			}
			is_function := declaration_kind == .fn_decl
			if (is_function && node.kind !in [.fn_decl, .c_fn_decl])
				|| (!is_function && node.kind != .struct_decl) {
				continue
			}
			if node.generic_params().len == 0 && !node.value.contains('[') {
				continue
			}
			namespace := tc.c_js_declaration_namespace(flat.NodeId(index), node) or { continue }
			type_kind := if is_function { 'functions' } else { 'structs' }
			pos := if is_function {
				tc.source_line_declaration_pos(flat.NodeId(index))
			} else {
				tc.generic_declaration_head_pos(flat.NodeId(index))
			}
			tc.record_error_at(.unsupported_generic,
				'${namespace} ${type_kind} cannot be declared as generic', flat.NodeId(index), pos)
		}
	}
}

fn (tc &TypeChecker) c_js_declaration_namespace(id flat.NodeId, node &flat.Node) ?string {
	if node.value.starts_with('C.') {
		return 'C'
	}
	if node.value.starts_with('JS.') {
		return 'JS'
	}
	pos := tc.source_line_declaration_pos(id)
	file := tc.a.source_files[pos.id] or { return none }
	source := tc.source_texts_by_file[file.name] or { return none }
	if pos.offset < 0 || pos.end > source.len || pos.offset >= pos.end {
		return none
	}
	line := source[pos.offset..pos.end]
	if line.starts_with('fn C.') {
		return 'C'
	}
	if line.starts_with('fn JS.') {
		return 'JS'
	}
	return none
}

fn (tc &TypeChecker) generic_declaration_head_pos(id flat.NodeId) token.Pos {
	pos := tc.source_line_declaration_pos(id)
	file := tc.a.source_files[pos.id] or { return pos }
	source := tc.source_texts_by_file[file.name] or { return pos }
	if pos.offset < 0 || pos.end > source.len || pos.offset >= pos.end {
		return pos
	}
	line := source[pos.offset..pos.end]
	bracket := line.index_u8(`[`)
	if bracket <= 0 {
		return pos
	}
	return token.new_span(pos.id, pos.offset, pos.offset + bracket)
}

fn (mut tc TypeChecker) check_duplicate_fn_declarations() {
	mut groups := map[string][]int{}
	mut cur_module := ''
	for index in tc.top_level_idx {
		node := tc.a.nodes[index]
		if node.kind == .file {
			cur_module = tc.file_modules[node.value] or { '' }
			continue
		}
		if node.kind == .module_decl {
			cur_module = node.value
			continue
		}
		if node.kind != .fn_decl {
			continue
		}
		key := if node.value.contains('.') || cur_module.len == 0 {
			node.value
		} else {
			'${cur_module}.${node.value}'
		}
		mut indexes := groups[key] or { []int{} }
		indexes << index
		groups[key] = indexes
	}
	mut keys := groups.keys()
	keys.sort()
	for key in keys {
		indexes := groups[key]
		if indexes.len < 2 || !indexes.any(it >= tc.a.user_code_start
			&& tc.node_is_in_selected_input_file(flat.NodeId(it))) {
			continue
		}
		display_name := tc.a.nodes[indexes[0]].value
		if display_name.all_after_last('.') == 'init'
			|| tc.fn_group_name_conflicts_with_import(indexes, display_name.all_after_last('.')) {
			continue
		}
		tc.errors << TypeError{
			msg:      'redefinition of function `${display_name}`'
			kind:     .duplicate_decl
			node:     flat.empty_node
			severity: 'builder error:'
		}
		for index in indexes {
			node_id := flat.NodeId(index)
			node := tc.a.nodes[index]
			pos := tc.fn_declaration_diagnostic_pos(node)
			base := tc.make_type_error_at(.duplicate_decl,
				tc.fn_declaration_source_signature(node, pos), node_id, pos)
			tc.errors << TypeError{
				...base
				severity: 'conflicting declaration:'
			}
		}
	}
}

fn (tc &TypeChecker) fn_group_name_conflicts_with_import(indexes []int, name string) bool {
	for index in indexes {
		node := tc.a.nodes[index]
		file := tc.a.source_files[node.pos.id] or { continue }
		info := tc.file_imports_by_file[file.name] or { continue }
		if name in info.imports {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) node_is_in_selected_input_file(id flat.NodeId) bool {
	if tc.diagnostic_files.len == 0 {
		return true
	}
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return false }
	return file.name in tc.diagnostic_files
}

fn (tc &TypeChecker) fn_declaration_source_signature(node flat.Node, pos token.Pos) string {
	file := tc.a.source_files[pos.id] or { return 'fn ${node.value}()' }
	source := tc.source_texts_by_file[file.name] or { return 'fn ${node.value}()' }
	if pos.offset < 0 || pos.end > source.len || pos.offset >= pos.end {
		return 'fn ${node.value}()'
	}
	return source[pos.offset..pos.end].trim_space()
}

fn (mut tc TypeChecker) check_goto_labels() {
	for index in tc.top_level_idx {
		node := tc.a.node(flat.NodeId(index))
		if node.kind == .fn_decl {
			tc.check_goto_boundary(flat.NodeId(index))
		}
	}
	for index in tc.top_level_idx {
		node := tc.a.node(flat.NodeId(index))
		if node.kind == .file {
			tc.check_goto_boundary(flat.NodeId(index))
		}
	}
}

fn (mut tc TypeChecker) check_goto_boundary(id flat.NodeId) {
	mut labels := map[string]bool{}
	tc.collect_goto_boundary_labels(id, mut labels)
	tc.validate_goto_boundary_nodes(id, false, labels)
}

fn (tc &TypeChecker) collect_goto_boundary_labels(id flat.NodeId, mut labels map[string]bool) {
	node := tc.a.node(id)
	for i in 0 .. node.children_count {
		child_id := tc.a.child(node, i)
		child := tc.a.node(child_id)
		if child.kind in [.fn_decl, .fn_literal, .lambda_expr] {
			continue
		}
		if child.kind == .label_stmt {
			labels[child.value] = true
		}
		tc.collect_goto_boundary_labels(child_id, mut labels)
	}
}

fn (mut tc TypeChecker) validate_goto_boundary_nodes(id flat.NodeId, inside_unsafe bool, labels map[string]bool) {
	node := tc.a.node(id)
	for i in 0 .. node.children_count {
		child_id := tc.a.child(node, i)
		child := tc.a.node(child_id)
		if child.kind in [.fn_literal, .lambda_expr] {
			tc.check_goto_boundary(child_id)
			continue
		}
		if child.kind == .fn_decl {
			continue
		}
		if child.kind == .goto_stmt {
			if !inside_unsafe && !tc.node_is_in_translated_file(child_id) {
				tc.record_goto_diagnostic(child_id, true,
					'`goto` requires `unsafe` (consider using labelled break/continue)')
			}
			if child.value !in labels {
				tc.record_goto_diagnostic(child_id, false, 'unknown label `${child.value}`')
			}
		}
		child_inside_unsafe := inside_unsafe || (child.kind == .block && child.value == 'unsafe')
		tc.validate_goto_boundary_nodes(child_id, child_inside_unsafe, labels)
	}
}

fn (mut tc TypeChecker) record_goto_diagnostic(id flat.NodeId, warning bool, message string) {
	if int(id) < tc.a.user_code_start || !tc.node_is_in_selected_input_file(id) {
		return
	}
	node := tc.a.node(id)
	base := tc.make_type_error_at(.unknown_ident, message, id, node.pos)
	if warning {
		tc.notices << TypeError{
			...base
			severity: 'warning:'
		}
	} else {
		tc.errors << base
	}
}

fn (mut tc TypeChecker) check_interface_reserved_parameter_names() {
	tc.cur_module = ''
	tc.cur_file = ''
	for index in tc.top_level_idx {
		node := tc.a.node(flat.NodeId(index))
		if node.kind == .file {
			tc.enter_file(node.value)
			continue
		}
		if node.kind == .module_decl {
			tc.enter_module(node.value)
			continue
		}
		if node.kind != .interface_decl {
			continue
		}
		tc.check_interface_field_method_collisions(node)
		for i in 0 .. node.children_count {
			field := tc.a.child_node(node, i)
			if field.kind != .interface_field {
				continue
			}
			for j in 0 .. field.children_count {
				tc.check_reserved_parameter_name(tc.a.child(field, j))
			}
		}
	}
}

fn (mut tc TypeChecker) check_str_method_signature(id flat.NodeId, node flat.Node) {
	if !tc.should_check_source_name(id) || !node.value.ends_with('.str') {
		return
	}
	mut explicit_params := 0
	for i in 0 .. node.children_count {
		param := tc.a.child_node(&node, i)
		if param.kind == .param && param.op != .dot {
			explicit_params++
		}
	}
	if !unalias_type(tc.parse_type(node.typ)).is_string() {
		tc.record_error_at(.return_mismatch, '.str() methods should return `string`', id,
			tc.fn_declaration_diagnostic_pos(node))
	}
	if explicit_params != 0 {
		tc.record_error_at(.call_arg_mismatch, '.str() methods should have 0 arguments', id,
			tc.fn_declaration_diagnostic_pos(node))
	}
}

fn (mut tc TypeChecker) check_free_method_signature(id flat.NodeId, node flat.Node) {
	if !tc.should_check_source_name(id) || !node.value.ends_with('.free') {
		return
	}
	mut receiver_id := flat.empty_node
	mut explicit_params := 0
	for i in 0 .. node.children_count {
		param_id := tc.a.child(&node, i)
		param := tc.a.node(param_id)
		if param.kind != .param {
			continue
		}
		if param.op == .dot {
			receiver_id = param_id
		} else {
			explicit_params++
		}
	}
	if tc.valid_node_id(receiver_id) {
		receiver := tc.a.node(receiver_id)
		receiver_type := unalias_type(tc.parse_type(receiver.typ))
		if receiver_type !is Pointer && !receiver.is_mut {
			type_name := receiver_type.name()
			_, receiver_pos := tc.fn_receiver_source_text_pos(node)
			pos := if receiver_pos.end > receiver_pos.offset + 2 {
				token.new_span(receiver_pos.id, receiver_pos.offset + 1, receiver_pos.end - 1)
			} else {
				receiver_pos
			}
			tc.record_error_at(.call_arg_mismatch,
				'`.free()` methods should be defined on either a `(mut x &${type_name})`, or a `(x &${type_name})` receiver',
				id, pos)
		}
	}
	if unalias_type(tc.parse_type(node.typ)) !is Void {
		tc.record_error_at(.return_mismatch, '`.free()` methods should not have a return type', id,
			tc.fn_return_type_diagnostic_pos(node))
	}
	if explicit_params != 0 {
		tc.record_error_at(.call_arg_mismatch, '`.free()` methods should have 0 arguments', id,
			tc.fn_declaration_diagnostic_pos(node))
	}
}

fn (tc &TypeChecker) should_check_source_name(id flat.NodeId) bool {
	if int(id) < tc.a.user_code_start || tc.translated_files[tc.cur_file] {
		return false
	}
	return tc.diagnostic_files.len == 0 || tc.cur_file in tc.diagnostic_files
}

fn snake_case_name_is_valid(name string) bool {
	if name.starts_with('C.') || name.starts_with('JS.') {
		return true
	}
	return (name.len <= 1 || (name[0] != `_` && !name.contains('._')))
		&& !util.contains_capital(name)
}

fn pascal_case_name_is_valid(name string) bool {
	if name.starts_with('C.') || name.starts_with('JS.') {
		return true
	}
	short_name := name.all_after_last('.')
	return short_name.len == 0 || short_name[0].is_capital()
}

fn (mut tc TypeChecker) check_invalid_test_file_name(id flat.NodeId, node flat.Node) {
	if node.value == 'main' || !tc.should_check_source_name(id) {
		return
	}
	base := os.file_name(tc.cur_file)
	if !base.starts_with('test_') || base.ends_with('_test.v') {
		return
	}
	tc.record_error_with_details_at(.unknown_type, 'invalid test file name `${base}`', id,
		tc.source_line_declaration_pos(id), [
		'Test files should have names ending with `_test.v`.',
	])
}

fn (mut tc TypeChecker) check_snake_case_name(id flat.NodeId, name string, identifier string, pos token.Pos) {
	if tc.translated_files[tc.cur_file] || name.starts_with('C.') || name.starts_with('JS.') {
		return
	}
	if name.len > 1 && (name[0] == `_` || name.contains('._')) {
		tc.record_error_at(.duplicate_decl, '${identifier} `${name}` cannot start with `_`', id,
			pos)
	}
	if util.contains_capital(name) {
		tc.record_error_at(.duplicate_decl,
			'${identifier} `${name}` cannot contain uppercase letters, use snake_case instead', id,
			pos)
	}
}

fn (mut tc TypeChecker) check_pascal_case_name(id flat.NodeId, name string, identifier string, pos token.Pos) {
	if tc.translated_files[tc.cur_file] || name.starts_with('C.') || name.starts_with('JS.') {
		return
	}
	short_name := name.all_after_last('.')
	if short_name.len > 0 && !short_name[0].is_capital() {
		tc.record_error_at(.duplicate_decl,
			'${identifier} `${name}` must begin with capital letter', id, pos)
	}
}

fn (mut tc TypeChecker) check_fn_declaration_name(id flat.NodeId, node flat.Node) {
	if !tc.should_check_source_name(id) || local_fn_decl_is_transform_created(node.value) {
		return
	}
	tc.check_fn_if_attribute_return(id, node)
	tc.check_imported_module_prefix(id, node.value, 'fn')
	name := node.value.all_after_last('.')
	if name.len == 0 || (!name[0].is_letter() && name[0] != `_`) || snake_case_name_is_valid(name) {
		return
	}
	tc.check_snake_case_name(id, name, if node.value.contains('.') {
		'method name'
	} else {
		'function name'
	}, tc.fn_declaration_diagnostic_pos(node))
}

fn (mut tc TypeChecker) check_fn_if_attribute_return(id flat.NodeId, node flat.Node) {
	if tc.parse_type(node.typ) is Void {
		return
	}
	header_pos := tc.fn_declaration_diagnostic_pos(node)
	file := tc.a.source_files[header_pos.id] or { return }
	source := tc.source_texts_by_file[file.name] or { return }
	mut line_start := int_min(int_max(header_pos.offset, 0), source.len)
	for line_start > 0 && source[line_start - 1] != `\n` {
		line_start--
	}
	mut cursor := line_start
	for cursor > 0 {
		mut previous_start := cursor - 1
		for previous_start > 0 && source[previous_start - 1] != `\n` {
			previous_start--
		}
		line := source[previous_start..cursor].trim_space()
		if line.len == 0 {
			cursor = previous_start
			continue
		}
		if line.starts_with('@[if ') && line.ends_with(']') {
			condition := line[5..line.len - 1].trim_space()
			tc.record_error_at(.return_mismatch,
				'only functions that do NOT return values can have `@[if ${condition}]` tags', id,
				header_pos)
		}
		return
	}
}

fn (mut tc TypeChecker) check_main_fn_signature(id flat.NodeId, node flat.Node) {
	if node.value != 'main' || tc.cur_module !in ['', 'main'] || !tc.should_check_source_name(id) {
		return
	}
	for i in 0 .. node.children_count {
		if tc.a.child_node(&node, i).kind == .param {
			tc.record_error_at(.return_mismatch, 'function `main` cannot have arguments', id,
				tc.fn_header_declaration_pos(id))
			break
		}
	}
	if tc.parse_type(node.typ) !is Void {
		tc.record_error_at(.return_mismatch, 'function `main` cannot return values', id,
			tc.fn_header_declaration_pos(id))
	}
	if node.kind == .c_fn_decl {
		tc.record_error_at(.return_mismatch, 'function `main` must declare a body', id,
			tc.fn_header_declaration_pos(id))
	}
}

fn (mut tc TypeChecker) check_init_fn_signature(id flat.NodeId, node flat.Node) {
	if node.value != 'init' || !tc.should_check_source_name(id) {
		return
	}
	pos := tc.fn_header_declaration_pos(id)
	if node.op == .arrow {
		tc.record_error_at(.return_mismatch, 'fn `init` must not be public', id, pos)
	}
	if tc.parse_type(node.typ) !is Void {
		tc.record_error_at(.return_mismatch, 'fn `init` cannot have a return type', id, pos)
	}
}

fn (tc &TypeChecker) fn_header_declaration_pos(id flat.NodeId) token.Pos {
	pos := tc.source_line_declaration_pos(id)
	file := tc.a.source_files[pos.id] or { return pos }
	source := tc.source_texts_by_file[file.name] or { return pos }
	mut end := int_min(pos.end, source.len)
	if end > pos.offset && source[end - 1] == `{` {
		end--
		for end > pos.offset && source[end - 1] in [` `, `\t`] {
			end--
		}
	}
	return token.new_span(pos.id, pos.offset, end)
}

fn (mut tc TypeChecker) check_fn_receiver_syntax(id flat.NodeId, node flat.Node) {
	if !node.value.contains('.') || !tc.should_check_source_name(id) {
		return
	}
	text, pos := tc.fn_receiver_source_text_pos(node)
	if text.len < 2 {
		return
	}
	parts := text[1..text.len - 1].fields()
	if parts.len < 3 {
		return
	}
	if parts[0] == 'mut' && parts[2].starts_with('&') {
		tc.record_error_at(.call_arg_mismatch,
			'use `(mut ${parts[1]} ${parts[2][1..]})` or `(${parts[1]} ${parts[2]})` instead of `${text}`',
			id, pos)
	} else if parts[1] == 'mut' {
		tc.record_warning_at(.call_arg_mismatch,
			'use `(mut ${parts[0]} ${parts[2]})` instead of `${text}`', id, pos)
	}
}

fn (tc &TypeChecker) fn_receiver_source_text_pos(node flat.Node) (string, token.Pos) {
	file := tc.a.source_files[node.pos.id] or { return '', node.pos }
	source := tc.source_texts_by_file[file.name] or { return '', node.pos }
	name_start := int_min(int_max(node.pos.offset, 0), source.len)
	line_start := if relative := source[..name_start].last_index('\n') {
		relative + 1
	} else {
		0
	}
	header := source[line_start..name_start]
	fn_relative := header.index('fn') or { return '', node.pos }
	open_relative := header[fn_relative..].index('(') or { return '', node.pos }
	open := line_start + fn_relative + open_relative
	close_relative := source[open..name_start].index(')') or { return '', node.pos }
	close := open + close_relative + 1
	return source[open..close], token.new_span(node.pos.id, open, close)
}

fn (mut tc TypeChecker) check_sumtype_builtin_method_override(id flat.NodeId, node flat.Node) {
	if !tc.should_check_source_name(id) || tc.cur_module == 'builtin' || !node.value.contains('.') {
		return
	}
	method := node.value.all_after_last('.')
	if method !in ['type_idx', 'type_name'] {
		return
	}
	receiver := node.value.all_before_last('.')
	qualified := tc.qualify_name(receiver)
	if receiver in tc.sum_types || qualified in tc.sum_types {
		tc.record_error_at(.duplicate_decl, 'method overrides built-in sum type method', id,
			tc.fn_declaration_diagnostic_pos(node))
	}
}

fn (mut tc TypeChecker) check_interface_member_names(node flat.Node) {
	for i in 0 .. node.children_count {
		field_id := tc.a.child(&node, i)
		field := tc.a.node(field_id)
		if field.kind != .interface_field || field.value.len == 0 {
			continue
		}
		if field.op != .dot && field.typ.len == 0 {
			// Embedded interfaces use their type name as `value`; they are not fields.
			continue
		}
		if !tc.should_check_source_name(field_id) || snake_case_name_is_valid(field.value) {
			continue
		}
		identifier := if field.op == .dot { 'method name' } else { 'field name' }
		pos := if field.op == .dot {
			tc.source_line_declaration_pos(field_id)
		} else {
			tc.node_value_diagnostic_pos(field_id)
		}
		tc.check_snake_case_name(field_id, field.value, identifier, pos)
	}
}

fn (mut tc TypeChecker) check_interface_field_method_collisions(node flat.Node) {
	mut field_names := map[string]bool{}
	for i in 0 .. node.children_count {
		field := tc.a.child_node(&node, i)
		if field.kind == .interface_field && field.op != .dot && field.typ.len > 0 {
			field_names[field.value] = true
		}
	}
	for i in 0 .. node.children_count {
		field_id := tc.a.child(&node, i)
		field := tc.a.node(field_id)
		if field.kind == .interface_field && field.op == .dot && field_names[field.value] {
			tc.record_error_at(.duplicate_decl,
				'type `${node.value}` has both field and method named `${field.value}`', field_id,
				tc.source_line_declaration_pos(field_id))
		}
	}
}

fn (mut tc TypeChecker) check_method_field_name_collision(id flat.NodeId, node flat.Node) {
	if !node.value.contains('.') || !tc.should_check_source_name(id) {
		return
	}
	receiver := node.value.all_before_last('.')
	method := node.value.all_after_last('.')
	qualified_receiver := tc.qualify_name(receiver)
	fields := tc.structs[qualified_receiver] or { tc.structs[receiver] or { return } }
	if fields.any(it.name == method) && !tc.struct_has_invalid_reference_default(receiver) {
		tc.record_error_at(.duplicate_decl,
			'type `${receiver.all_after_last('.')}` has both field and method named `${method}`',
			id, tc.fn_declaration_diagnostic_pos(node))
	}
}

fn (tc &TypeChecker) struct_has_invalid_reference_default(receiver string) bool {
	decl := tc.source_struct_decl_for_name(receiver) or { return false }
	for i in 0 .. decl.children_count {
		field := tc.a.child_node(&decl, i)
		if field.kind != .field_decl || field.children_count == 0 {
			continue
		}
		default_id := tc.a.child(field, 0)
		if tc.errors.any(it.node == default_id
			&& it.msg == 'field is not reference but default value is reference')
		{
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) check_reserved_parameter_name(id flat.NodeId) {
	if !tc.valid_node_id(id) || !tc.should_check_source_name(id) {
		return
	}
	param := tc.a.node(id)
	if param.kind != .param || param.value.len == 0 || !reserved_const_type_name(param.value) {
		return
	}
	tc.record_error_at(.duplicate_decl,
		'invalid use of reserved type `${param.value}` as a parameter name', id, param.pos)
}

fn (tc &TypeChecker) declaration_keyword_name_pos(node_id flat.NodeId, keyword string) token.Pos {
	if !tc.valid_node_id(node_id) {
		return token.Pos{}
	}
	node := tc.a.node(node_id)
	name_pos := tc.node_value_diagnostic_pos(node_id)
	file := tc.a.source_files[name_pos.id] or { return name_pos }
	source := tc.source_texts_by_file[file.name] or { return name_pos }
	mut line_start := int_min(name_pos.offset, source.len)
	for line_start > 0 && source[line_start - 1] != `\n` {
		line_start--
	}
	name_end := int_min(name_pos.end, source.len)
	prefix := source[line_start..name_end]
	keyword_relative := prefix.last_index(keyword) or { return name_pos }
	keyword_start := line_start + keyword_relative
	mut start := keyword_start
	if prefix[..keyword_relative].trim_space() == 'pub' {
		start = line_start + (prefix.index('pub') or { keyword_relative })
	}
	mut name_start := keyword_start + keyword.len
	for name_start < source.len && source[name_start] in [` `, `\t`] {
		name_start++
	}
	end := name_start + node.value.all_after_last('.').len
	return token.new_span(name_pos.id, start, int_min(end, source.len))
}

fn (tc &TypeChecker) source_line_declaration_pos(node_id flat.NodeId) token.Pos {
	if !tc.valid_node_id(node_id) {
		return token.Pos{}
	}
	name_pos := tc.node_value_diagnostic_pos(node_id)
	file := tc.a.source_files[name_pos.id] or { return name_pos }
	source := tc.source_texts_by_file[file.name] or { return name_pos }
	mut start := int_min(name_pos.offset, source.len)
	for start > 0 && source[start - 1] != `\n` {
		start--
	}
	mut end := source.index_after('\n', start) or { source.len }
	for start < end && source[start] in [` `, `\t`] {
		start++
	}
	for end > start && source[end - 1] in [`\n`, `\r`, ` `, `\t`] {
		end--
	}
	return token.new_span(name_pos.id, start, end)
}

fn (mut tc TypeChecker) check_test_fn_signature(id flat.NodeId, node flat.Node) {
	source_file := tc.a.source_files[node.pos.id] or { return }
	if !is_regular_v_test_file(source_file.name) || !is_v_test_fn_name(node.value) {
		return
	}
	mut param_count := 0
	for i in 0 .. node.children_count {
		if tc.a.child_node(&node, i).kind == .param {
			param_count++
		}
	}
	if param_count != 0 {
		tc.record_error_at(.call_arg_mismatch, 'test functions should take 0 parameters', id,
			tc.fn_declaration_diagnostic_pos(node))
	}
	return_type := trimmed_space(node.typ)
	if return_type.len > 0 && return_type !in ['void', '?', '!']
		&& !return_type.starts_with('?void') && !return_type.starts_with('!void') {
		tc.record_error_at(.return_mismatch,
			'test functions should either return nothing at all, or be marked to return `?` or `!`',
			id, tc.fn_declaration_diagnostic_pos(node))
	}
}

fn (mut tc TypeChecker) check_test_file_has_test_fn() {
	mut has_test_file := false
	mut has_test_fn := false
	mut first_source_node := flat.NodeId(-1)
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		if node.kind == .file && is_regular_v_test_file(node.value) {
			has_test_file = true
			continue
		}
		if node.kind != .fn_decl {
			continue
		}
		source_file := tc.a.source_files[node.pos.id] or { continue }
		if !is_regular_v_test_file(source_file.name) {
			continue
		}
		if int(first_source_node) < 0 {
			first_source_node = flat.NodeId(i)
		}
		if is_v_test_fn_name(node.value) {
			has_test_fn = true
		}
	}
	if !has_test_file || has_test_fn {
		return
	}
	first_node := tc.a.nodes[int(first_source_node)]
	mut pos := tc.fn_declaration_diagnostic_pos(first_node)
	if pos.is_valid() {
		pos = token.new_span(pos.id, pos.offset, pos.offset + 1)
	}
	source_file := tc.a.source_files[pos.id] or { return }
	saved_file := tc.cur_file
	tc.cur_file = source_file.name
	tc.record_error_with_details_at(.unknown_fn,
		'a _test.v file should have *at least* one `test_` function', first_source_node, pos, [
		'The name of a test function in V, should start with `test_`.',
		'The test function should take 0 parameters, and no return type. Example:',
		'fn test_xyz(){ assert 2 + 2 == 4 }',
	])
	tc.cur_file = saved_file
}

fn (tc &TypeChecker) fn_declaration_diagnostic_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	position := file.position(node.pos)
	line_start := file.line_start(position.line)
	line_end := source.index_after('\n', line_start) or { source.len }
	if line_start < line_end {
		line := source[line_start..line_end]
		fn_relative := line.index('fn ') or { return node.pos }
		open_relative := line[fn_relative..].index('{') or { return node.pos }
		start := line_start + fn_relative
		header := line[fn_relative..fn_relative + open_relative].trim_right(' \t')
		return token.new_span(node.pos.id, start, start + header.len)
	}
	return node.pos
}

fn is_v_test_fn_name(name string) bool {
	return name.starts_with('test_') || name.starts_with('testsuite_')
		|| name in ['before_each', 'after_each', 'before_all', 'after_all']
}

fn (mut tc TypeChecker) check_top_level_file_statements(node flat.Node) {
	if node.children_count == 0 {
		return
	}
	saved_fn_context := tc.fn_context
	saved_scope := tc.cur_scope
	saved_return_type := tc.cur_fn_ret_type
	tc.fn_context = new_function_check_context()
	tc.cur_scope = tc.file_scope
	tc.cur_fn_ret_type = Type(void_)
	mut reported_malformed_const_lines := map[int]bool{}
	mut reported_unexpected_name_lines := map[int]bool{}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.nodes[int(child_id)]
		if bad_pos := tc.malformed_const_keyword_pos(child_id) {
			if !reported_malformed_const_lines[bad_pos.offset] {
				tc.record_error_at(.unknown_ident, 'unexpected name `cosnt`', child_id, bad_pos)
				reported_malformed_const_lines[bad_pos.offset] = true
			}
			continue
		}
		if is_top_level_statement_kind(child.kind) {
			if unexpected_pos := tc.unexpected_top_level_name_pos(child_id) {
				if !reported_unexpected_name_lines[unexpected_pos.offset] {
					file := tc.a.source_files[unexpected_pos.id] or { continue }
					source := tc.source_texts_by_file[file.name] or { continue }
					name := source[unexpected_pos.offset..unexpected_pos.end]
					tc.record_error_at(.unknown_ident, 'unexpected name `${name}`', child_id,
						unexpected_pos)
					reported_unexpected_name_lines[unexpected_pos.offset] = true
				}
				continue
			}
		}
		if is_top_level_statement_kind(child.kind) && !tc.node_is_on_import_line(child_id) {
			tc.check_stmt_node(child_id)
		}
	}
	tc.record_unused_top_level_vars(node)
	tc.fn_context = saved_fn_context
	tc.cur_scope = saved_scope
	tc.cur_fn_ret_type = saved_return_type
}

fn (tc &TypeChecker) unexpected_top_level_name_pos(id flat.NodeId) ?token.Pos {
	if !tc.valid_node_id(id) {
		return none
	}
	pos := tc.a.node(id).pos
	file := tc.a.source_files[pos.id] or { return none }
	source := tc.source_texts_by_file[file.name] or { return none }
	mut line_start := int_min(int_max(pos.offset, 0), source.len)
	for line_start > 0 && source[line_start - 1] != `\n` {
		line_start--
	}
	line_end := source.index_after('\n', line_start) or { source.len }
	mut start := line_start
	for start < line_end && source[start] in [` `, `\t`] {
		start++
	}
	if start >= line_end || !source[start].is_capital() {
		return none
	}
	mut end := start + 1
	for end < line_end && (source[end].is_letter() || source[end].is_digit() || source[end] == `_`) {
		end++
	}
	if end >= line_end || source[end] !in [` `, `\t`] {
		return none
	}
	mut next := end
	for next < line_end && source[next] in [` `, `\t`] {
		next++
	}
	if next >= line_end || !source[next].is_letter() {
		return none
	}
	return token.new_span(pos.id, start, end)
}

fn (tc &TypeChecker) malformed_const_keyword_pos(id flat.NodeId) ?token.Pos {
	if !tc.valid_node_id(id) {
		return none
	}
	pos := tc.a.node(id).pos
	file := tc.a.source_files[pos.id] or { return none }
	source := tc.source_texts_by_file[file.name] or { return none }
	if pos.offset < 0 || pos.offset > source.len {
		return none
	}
	mut line_start := pos.offset
	for line_start > 0 && source[line_start - 1] != `\n` {
		line_start--
	}
	line_end := source.index_after('\n', line_start) or { source.len }
	indent := source[line_start..line_end].len - source[line_start..line_end].trim_left(' \t').len
	keyword_start := line_start + indent
	if keyword_start + 5 > source.len || source[keyword_start..keyword_start + 5] != 'cosnt' {
		return none
	}
	if keyword_start + 5 < line_end && source[keyword_start + 5] !in [` `, `\t`] {
		return none
	}
	return token.new_span(pos.id, keyword_start, keyword_start + 5)
}

fn (tc &TypeChecker) node_is_on_import_line(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	pos := tc.a.node(id).pos
	file := tc.a.source_files[pos.id] or { return false }
	source := tc.source_texts_by_file[file.name] or { return false }
	if pos.offset < 0 || pos.offset > source.len {
		return false
	}
	line_start := if relative := source[..pos.offset].last_index('\n') {
		relative + 1
	} else {
		0
	}
	return source[line_start..pos.offset].trim_left(' \t').starts_with('import ')
}

fn is_top_level_statement_kind(kind flat.NodeKind) bool {
	return kind in [
		.expr_stmt,
		.if_expr,
		.assign,
		.decl_assign,
		.selector_assign,
		.index_assign,
		.return_stmt,
		.block,
		.for_stmt,
		.for_in_stmt,
		.break_stmt,
		.continue_stmt,
		.match_stmt,
		.defer_stmt,
		.assert_stmt,
		.goto_stmt,
		.label_stmt,
		.select_stmt,
		.comptime_if,
		.comptime_for,
		.asm_stmt,
	]
}

fn (mut tc TypeChecker) collect_selected_file_called_fns() {
	tc.selected_file_called_fns = map[string]bool{}
	tc.selected_file_worklist = []string{}
	if tc.diagnostic_files.len == 0 {
		return
	}
	saved_file := tc.cur_file
	saved_module := tc.cur_module
	saved_scope := tc.cur_scope
	saved_scope_pool_index := tc.scope_pool_index
	tc.cur_file = ''
	tc.cur_module = ''
	tc.cur_scope = tc.file_scope
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		match node.kind {
			.file {
				tc.enter_file(node.value)
				if i >= tc.a.user_code_start && tc.diagnostic_files[tc.cur_file] {
					tc.collect_selected_file_top_level_called_fns(node)
				}
			}
			.module_decl {
				tc.enter_module(node.value)
			}
			.fn_decl {
				if i < tc.a.user_code_start || !tc.diagnostic_files[tc.cur_file] {
					continue
				}
				tc.collect_selected_file_fn_body_called_fns(node)
			}
			else {}
		}
	}
	tc.collect_selected_file_called_fns_transitively()
	tc.cur_file = saved_file
	tc.cur_module = saved_module
	tc.cur_scope = saved_scope
	tc.scope_pool_index = saved_scope_pool_index
}

// SelectedFnDecl locates the first fn_decl node for a qualified name, with the
// file/module context needed to walk its body.
struct SelectedFnDecl {
	idx  int
	file string
	mod  string
}

fn (mut tc TypeChecker) collect_selected_file_called_fns_transitively() {
	// Index the first user-code fn_decl per qualified name once, then chase the
	// worklist of newly discovered called names. The former fixpoint re-scanned
	// every node per round; this walks each reachable body exactly once (the
	// first declaration wins for duplicate names, matching the old scan order).
	mut decls := map[string]SelectedFnDecl{}
	mut cur_file := ''
	mut cur_module := ''
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		match node.kind {
			.file {
				cur_file = node.value
				cur_module = tc.file_modules[node.value] or { '' }
			}
			.module_decl {
				cur_module = node.value
			}
			.fn_decl {
				if i < tc.a.user_code_start || node.value.len == 0 {
					continue
				}
				qname := checker_qualified_fn_name(cur_module, node.value)
				if qname !in decls {
					decls[qname] = SelectedFnDecl{
						idx:  i
						file: cur_file
						mod:  cur_module
					}
				}
			}
			else {}
		}
	}
	tc.cur_scope = tc.file_scope
	mut visited := map[string]bool{}
	for tc.selected_file_worklist.len > 0 {
		name := tc.selected_file_worklist.pop()
		if name in visited {
			continue
		}
		visited[name] = true
		decl := decls[name] or { continue }
		tc.cur_file = decl.file
		tc.cur_module = decl.mod
		tc.collect_selected_file_fn_body_called_fns(tc.a.nodes[decl.idx])
	}
}

fn (mut tc TypeChecker) collect_selected_file_top_level_called_fns(node flat.Node) {
	tc.push_scope()
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.nodes[int(child_id)]
		match child.kind {
			.fn_decl, .struct_decl, .type_decl, .interface_decl, .enum_decl, .c_fn_decl,
			.import_decl, .module_decl, .directive {
				continue
			}
			else {
				tc.collect_selected_file_node_called_fns(child_id)
			}
		}
	}
	tc.pop_scope()
}

fn (mut tc TypeChecker) collect_selected_file_fn_body_called_fns(node flat.Node) {
	tc.push_scope()
	for i in 0 .. node.children_count {
		child := tc.a.child_node(&node, i)
		if child.kind == .param && child.value.len > 0 {
			tc.cur_scope.insert(child.value, tc.parse_type(child.typ))
		}
	}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.nodes[int(child_id)]
		if child.kind != .param {
			tc.collect_selected_file_node_called_fns(child_id)
		}
	}
	tc.pop_scope()
}

fn (mut tc TypeChecker) collect_selected_file_node_called_fns(id flat.NodeId) {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.block {
			tc.push_scope()
			for i in 0 .. node.children_count {
				tc.collect_selected_file_node_called_fns(tc.a.child(&node, i))
			}
			tc.pop_scope()
			return
		}
		.decl_assign {
			tc.collect_selected_file_decl_assign_called_fns(node)
			return
		}
		.for_in_stmt {
			tc.collect_selected_file_for_in_called_fns(node)
			return
		}
		.call {
			if name := tc.selected_file_call_name(node) {
				if name !in tc.selected_file_called_fns {
					tc.selected_file_called_fns[name] = true
					tc.selected_file_worklist << name
				}
			}
		}
		else {}
	}

	for i in 0 .. node.children_count {
		tc.collect_selected_file_node_called_fns(tc.a.child(&node, i))
	}
}

fn (mut tc TypeChecker) collect_selected_file_for_in_called_fns(node flat.Node) {
	header := node.value.int()
	if header < 3 || node.children_count < 3 {
		for i in 0 .. node.children_count {
			tc.collect_selected_file_node_called_fns(tc.a.child(&node, i))
		}
		return
	}
	tc.push_scope()
	key_id := tc.a.child(&node, 0)
	val_id := tc.a.child(&node, 1)
	container_id := tc.a.child(&node, 2)
	tc.collect_selected_file_node_called_fns(container_id)
	has_val := int(val_id) >= 0
	if header == 4 {
		tc.insert_selected_file_decl_binding_type(key_id, tc.range_loop_var_type(container_id))
		tc.collect_selected_file_node_called_fns(tc.a.child(&node, 3))
	} else {
		clean := tc.for_in_iterable_type(container_id)
		yields_ref := node.op == .amp || tc.for_in_iterable_yields_ref(container_id)
		if clean is Array {
			elem_type := for_in_ref_binding_type(clean.elem_type, yields_ref)
			if has_val {
				tc.insert_selected_file_decl_binding_type(key_id, Type(int_))
				tc.insert_selected_file_decl_binding_type(val_id, elem_type)
			} else {
				tc.insert_selected_file_decl_binding_type(key_id, elem_type)
			}
		} else if clean is ArrayFixed {
			elem_type := for_in_ref_binding_type(clean.elem_type, yields_ref)
			if has_val {
				tc.insert_selected_file_decl_binding_type(key_id, Type(int_))
				tc.insert_selected_file_decl_binding_type(val_id, elem_type)
			} else {
				tc.insert_selected_file_decl_binding_type(key_id, elem_type)
			}
		} else if clean is Map {
			value_type := for_in_ref_binding_type(clean.value_type, yields_ref)
			if has_val {
				tc.insert_selected_file_decl_binding_type(key_id, clean.key_type)
				tc.insert_selected_file_decl_binding_type(val_id, value_type)
			} else {
				tc.insert_selected_file_decl_binding_type(key_id, value_type)
			}
		} else if clean is String {
			if has_val {
				tc.insert_selected_file_decl_binding_type(key_id, Type(int_))
				tc.insert_selected_file_decl_binding_type(val_id, Type(u8_))
			} else {
				tc.insert_selected_file_decl_binding_type(key_id, Type(u8_))
			}
		} else if generic_name := tc.iterator_unbounded_next_generic(clean) {
			_ = generic_name
			if has_val {
				tc.insert_selected_file_decl_binding_type(key_id, Type(int_))
				tc.insert_selected_file_decl_binding_type(val_id,
					unknown_type('unbounded iterator generic'))
			} else {
				tc.insert_selected_file_decl_binding_type(key_id,
					unknown_type('unbounded iterator generic'))
			}
		} else if elem_type := tc.iterator_for_in_elem_type(clean) {
			if has_val {
				tc.insert_selected_file_decl_binding_type(key_id, Type(int_))
				tc.insert_selected_file_decl_binding_type(val_id, elem_type)
			} else {
				tc.insert_selected_file_decl_binding_type(key_id, elem_type)
			}
		} else {
			container := tc.a.nodes[int(container_id)]
			if container.kind == .range {
				tc.insert_selected_file_decl_binding_type(key_id, tc.range_loop_var_type(tc.a.child(&container,
					0)))
			}
		}
	}
	for i in header .. node.children_count {
		tc.collect_selected_file_node_called_fns(tc.a.child(&node, i))
	}
	tc.pop_scope()
}

fn (mut tc TypeChecker) collect_selected_file_decl_assign_called_fns(node flat.Node) {
	if node.children_count >= 3 {
		rhs_id := tc.a.child(&node, 1)
		rhs_type := tc.decl_assign_inferred_type(rhs_id)
		if rhs_type is MultiReturn {
			tc.collect_selected_file_node_called_fns(rhs_id)
			lhs_ids := tc.multi_assign_lhs_ids(node)
			for i, lhs_id in lhs_ids {
				if i < rhs_type.types.len {
					tc.insert_selected_file_decl_binding_type(lhs_id, rhs_type.types[i])
				}
			}
			return
		}
	}
	mut i := 0
	for i + 1 < node.children_count {
		lhs_id := tc.a.child(&node, i)
		rhs_id := tc.a.child(&node, i + 1)
		tc.collect_selected_file_node_called_fns(rhs_id)
		tc.insert_selected_file_decl_binding(lhs_id, rhs_id, node)
		i += 2
	}
}

fn (mut tc TypeChecker) insert_selected_file_decl_binding(lhs_id flat.NodeId, rhs_id flat.NodeId, node flat.Node) {
	if int(lhs_id) < 0 || int(lhs_id) >= tc.a.nodes.len {
		return
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind != .ident || lhs.value.len == 0 || lhs.value == '_' {
		return
	}
	typ := if node.children_count == 2 && node.typ.len > 0 {
		tc.parse_type(node.typ)
	} else {
		tc.decl_assign_inferred_type(rhs_id)
	}
	tc.insert_selected_file_decl_binding_type(lhs_id, typ)
}

fn (mut tc TypeChecker) insert_selected_file_decl_binding_type(lhs_id flat.NodeId, typ Type) {
	if int(lhs_id) < 0 || int(lhs_id) >= tc.a.nodes.len {
		return
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind != .ident || lhs.value.len == 0 || lhs.value == '_' {
		return
	}
	if typ is MultiReturn || typ is Void || typ is Unknown {
		return
	}
	tc.cur_scope.insert(lhs.value, typ)
}

fn (tc &TypeChecker) selected_file_call_name(node flat.Node) ?string {
	if node.children_count == 0 {
		return none
	}
	fn_node := tc.a.child_node(&node, 0)
	if fn_node.kind == .index && fn_node.children_count > 0 {
		return tc.selected_file_call_base_name(tc.a.child_node(fn_node, 0))
	}
	return tc.selected_file_call_base_name(fn_node)
}

fn (tc &TypeChecker) selected_file_call_base_name(fn_node flat.Node) ?string {
	match fn_node.kind {
		.ident {
			if local_name := tc.local_bare_fn_signature_key(fn_node.value) {
				return local_name
			}
			if imported_name := tc.resolve_selective_import_symbol(fn_node.value) {
				return imported_name
			}
			if tc.fn_signature_known(fn_node.value) {
				return fn_node.value
			}
		}
		.selector {
			if fn_node.children_count == 0 {
				return none
			}
			base_id := tc.a.child(&fn_node, 0)
			base_node := tc.a.nodes[int(base_id)]
			if base_node.kind == .ident {
				if _ := tc.cur_scope.lookup(base_node.value) {
					if name := tc.selected_file_receiver_method_name(base_id, fn_node.value) {
						return name
					}
					return none
				}
				if resolved_mod := tc.resolve_import_alias(base_node.value) {
					mod_name := '${resolved_mod}.${fn_node.value}'
					if tc.fn_signature_known(mod_name) {
						return mod_name
					}
				}
				if base_node.value == tc.cur_module {
					mod_name := '${tc.cur_module}.${fn_node.value}'
					if tc.fn_signature_known(mod_name) {
						return mod_name
					}
				}
			}
			if name := tc.selected_file_receiver_method_name(base_id, fn_node.value) {
				return name
			}
		}
		else {}
	}

	return none
}

fn (tc &TypeChecker) selected_file_receiver_method_name(base_id flat.NodeId, method string) ?string {
	if method.len == 0 {
		return none
	}
	base_type := tc.resolve_type(base_id)
	clean := unwrap_pointer(base_type)
	type_name := resolve_type_name_for_method(clean)
	if type_name.len == 0 {
		return none
	}
	for method_name in receiver_method_name_candidates(clean, method, tc.cur_module) {
		if !tc.fn_signature_known(method_name) {
			continue
		}
		if !tc.method_can_be_called_on_receiver(base_type, method, method_name) {
			continue
		}
		return method_name
	}
	if info := tc.embedded_method_call_info(type_name, method) {
		if info.name.len > 0 {
			return info.name
		}
	}
	if info := tc.resolve_generic_struct_method(type_name, method) {
		if info.name.len > 0 {
			return info.name
		}
	}
	return none
}

fn (mut tc TypeChecker) check_export_attrs() {
	mut natural_symbols := map[string]string{}
	synthetic_main_reserved := tc.has_synthetic_c_entry_main()
	mut cur_module := ''
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		match node.kind {
			.file {
				tc.enter_file(node.value)
				cur_module = tc.cur_module
			}
			.module_decl {
				cur_module = node.value
				tc.enter_module(node.value)
			}
			.fn_decl {
				qname := export_qualified_fn_name(cur_module, node.value)
				natural_symbol := export_natural_c_symbol(cur_module, node.value)
				natural_symbols[natural_symbol] = qname
			}
			else {}
		}
	}
	mut export_symbols := map[string]string{}
	cur_module = ''
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		match node.kind {
			.file {
				tc.enter_file(node.value)
				cur_module = tc.cur_module
			}
			.module_decl {
				cur_module = node.value
				tc.enter_module(node.value)
			}
			.const_decl {
				export_name := tc.declaration_attribute_value(flat.NodeId(i), 'export') or {
					continue
				}
				for field_idx in 0 .. node.children_count {
					field_id := tc.a.child(&node, field_idx)
					field := tc.a.node(field_id)
					if field.kind != .const_field {
						continue
					}
					name := if export_name.len > 0 { export_name } else { field.value }
					if !is_valid_export_c_name(name) {
						tc.record_error_at(.unsupported_generic,
							'export name `${name}` should be a valid identifier', field_id,
							tc.node_value_diagnostic_pos(field_id))
					}
					if name in export_symbols {
						tc.record_error_at(.unsupported_generic, 'duplicate export name `${name}`',
							field_id, tc.node_value_diagnostic_pos(field_id))
					} else {
						export_symbols[name] = field.value
					}
				}
			}
			else {}
		}
	}
	cur_module = ''
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		match node.kind {
			.file {
				tc.enter_file(node.value)
				cur_module = tc.cur_module
			}
			.module_decl {
				cur_module = node.value
				tc.enter_module(node.value)
			}
			.global_decl {
				for field_idx in 0 .. node.children_count {
					field_id := tc.a.child(&node, field_idx)
					field := tc.a.node(field_id)
					if field.value in export_symbols {
						tc.record_error_at(.unsupported_generic,
							'duplicate export name `${field.value}`', field_id,
							tc.node_value_diagnostic_pos(field_id))
					}
				}
			}
			else {}
		}
	}
	cur_module = ''
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		match node.kind {
			.file {
				tc.enter_file(node.value)
				cur_module = tc.cur_module
			}
			.module_decl {
				cur_module = node.value
				tc.enter_module(node.value)
			}
			.fn_decl {
				qname := export_qualified_fn_name(cur_module, node.value)
				if pos := tc.declaration_attribute_without_value_pos(flat.NodeId(i), 'export') {
					tc.record_error_at(.unsupported_generic,
						'missing argument for @[export] attribute', flat.NodeId(i), pos)
					continue
				}
				export_name := tc.a.export_fn_names[qname] or { continue }
				if export_name.len == 0 {
					tc.record_error_unfiltered(.unsupported_generic,
						'empty export name for `${qname}`', flat.NodeId(i))
					continue
				}
				if !is_valid_export_c_name(export_name) {
					message := if cur_module.len == 0 {
						'export name `${export_name}` should be a valid identifier for `${qname}`'
					} else {
						'export name `${export_name}` should be a valid identifier'
					}
					tc.record_error_at(.unsupported_generic, message, flat.NodeId(i),
						tc.fn_declaration_diagnostic_pos(node))
				}
				if synthetic_main_reserved && export_name == 'main' {
					tc.record_error_unfiltered(.unsupported_generic,
						'export name `main` for `${qname}` collides with synthetic entry point `main`',
						flat.NodeId(i))
				}
				if node.generic_params().len > 0 {
					tc.record_error_unfiltered(.unsupported_generic,
						'generic function `${qname}` cannot be exported', flat.NodeId(i))
				}
				for pi in 0 .. node.children_count {
					p := tc.a.child_node(&node, pi)
					if p.kind == .param && (p.value.len == 0 || p.typ.len == 0) {
						tc.record_error_unfiltered(.unsupported_generic,
							'exported function `${qname}` must name all parameters', flat.NodeId(i))
					}
				}
				if existing := export_symbols[export_name] {
					if existing != qname {
						tc.record_error_at(.unsupported_generic,
							'duplicate export name `${export_name}`', flat.NodeId(i),
							tc.fn_declaration_diagnostic_pos(node))
					}
				} else {
					export_symbols[export_name] = qname
				}
				if existing := natural_symbols[export_name] {
					if existing != qname {
						tc.record_error_unfiltered(.unsupported_generic,
							'export name `${export_name}` for `${qname}` collides with `${existing}`',
							flat.NodeId(i))
					}
				}
			}
			else {}
		}
	}
}

fn (tc &TypeChecker) declaration_attribute_without_value_pos(node_id flat.NodeId, name string) ?token.Pos {
	if !tc.should_check_source_name(node_id) {
		return none
	}
	marker := '@attributes:${int(node_id)}'
	mut has_bare_attr := false
	for node in tc.a.nodes {
		if node.kind != .directive || node.value != marker {
			continue
		}
		for raw in node.generic_params() {
			if raw.trim_space() == name {
				has_bare_attr = true
				break
			}
		}
		break
	}
	if !has_bare_attr {
		return none
	}
	node := tc.a.node(node_id)
	file := tc.a.source_files[node.pos.id] or { return none }
	source := tc.source_texts_by_file[file.name] or { return none }
	end := int_min(int_max(node.pos.offset, 0), source.len)
	needle := '@[${name}]'
	if relative := source[..end].last_index(needle) {
		return token.new_span(node.pos.id, relative, relative + needle.len)
	}
	return none
}

fn (tc &TypeChecker) declaration_attribute_value(node_id flat.NodeId, name string) ?string {
	marker := '@attributes:${int(node_id)}'
	for node in tc.a.nodes {
		if node.kind != .directive || node.value != marker {
			continue
		}
		for raw in node.generic_params() {
			if raw.all_before(':').trim_space() != name || !raw.contains(':') {
				continue
			}
			value := raw.all_after(':').trim_space()
			if value.len >= 2 && ((value[0] == `'` && value[value.len - 1] == `'`)
				|| (value[0] == `"` && value[value.len - 1] == `"`)) {
				return value[1..value.len - 1]
			}
			return value
		}
		return none
	}
	return none
}

fn (tc &TypeChecker) has_synthetic_c_entry_main() bool {
	if tc.has_c_test_harness_main() {
		return true
	}
	if tc.has_main_module_fn_main() {
		return false
	}
	return tc.has_c_top_level_main()
}

fn (tc &TypeChecker) has_main_module_fn_main() bool {
	mut cur_module := ''
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		match node.kind {
			.file {
				cur_module = ''
			}
			.module_decl {
				cur_module = node.value
			}
			.fn_decl {
				if node.value == 'main' && (cur_module.len == 0 || cur_module == 'main') {
					return true
				}
			}
			else {}
		}
	}
	return false
}

fn (tc &TypeChecker) has_c_test_harness_main() bool {
	for file_idx in tc.top_level_idx {
		file_node := tc.a.nodes[file_idx]
		if file_idx < tc.a.user_code_start || file_node.kind != .file || file_node.value.len == 0 {
			continue
		}
		if !tc.is_selected_input_file(file_node.value) {
			continue
		}
		module_name := tc.top_level_file_module_name(file_node)
		if is_c_backend_test_file(file_node.value) && (is_regular_v_test_file(file_node.value)
			|| module_name.len == 0 || module_name == 'main') {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) has_c_top_level_main() bool {
	for file_idx in tc.top_level_idx {
		file_node := tc.a.nodes[file_idx]
		if !tc.should_emit_c_top_level_file(file_idx, file_node) {
			continue
		}
		for i in 0 .. file_node.children_count {
			child_id := tc.a.child(&file_node, i)
			if int(child_id) < tc.a.user_code_start {
				continue
			}
			if tc.is_c_top_level_stmt(child_id) {
				return true
			}
		}
	}
	return false
}

fn (tc &TypeChecker) should_emit_c_top_level_file(file_idx int, file_node flat.Node) bool {
	if file_idx < tc.a.user_code_start || file_node.kind != .file || file_node.children_count == 0 {
		return false
	}
	module_name := tc.top_level_file_module_name(file_node)
	return module_name.len == 0 || module_name == 'main'
}

fn (tc &TypeChecker) top_level_file_module_name(file_node flat.Node) string {
	if module_name := tc.file_modules[file_node.value] {
		return module_name
	}
	for i in 0 .. file_node.children_count {
		child := tc.a.child_node(&file_node, i)
		if child.kind == .module_decl {
			return child.value
		}
	}
	return ''
}

fn (tc &TypeChecker) is_c_top_level_stmt(id flat.NodeId) bool {
	if int(id) < 0 {
		return false
	}
	node := tc.a.nodes[int(id)]
	return match node.kind {
		.expr_stmt, .assign, .decl_assign, .selector_assign, .index_assign, .for_stmt,
		.for_in_stmt, .if_expr, .match_stmt, .assert_stmt, .defer_stmt {
			true
		}
		.block, .comptime_if {
			for i in 0 .. node.children_count {
				if tc.is_c_top_level_stmt(tc.a.child(&node, i)) {
					return true
				}
			}
			false
		}
		else {
			false
		}
	}
}

fn (tc &TypeChecker) is_selected_input_file(file string) bool {
	return tc.diagnostic_files.len == 0 || tc.diagnostic_files[file]
}

fn is_c_backend_test_file(path string) bool {
	file := path.all_after_last('/').all_after_last('\\')
	if file.ends_with('_test.v') || file.ends_with('_test.vv') || file.ends_with('_test.c.v') {
		return true
	}
	if !file.ends_with('.v') {
		return false
	}
	base := file[..file.len - 2]
	if !base.contains('.') {
		return false
	}
	return base.all_after_last('.') == 'c' && base.all_before_last('.').ends_with('_test')
}

fn is_regular_v_test_file(path string) bool {
	file := path.all_after_last('/').all_after_last('\\')
	return file.ends_with('_test.v') || file.ends_with('_test.vv')
}

fn export_qualified_fn_name(module_name string, name string) string {
	if module_name.len == 0 || module_name == 'main' || module_name == 'builtin' {
		return name
	}
	return '${module_name}.${name}'
}

fn export_natural_c_symbol(module_name string, name string) string {
	if module_name == 'builtin' && name == 'free' {
		return 'v_free'
	}
	if module_name.len > 0 && module_name != 'main' && module_name != 'builtin' {
		return naming.c_name('${module_name}.${name}')
	}
	if name == 'free' {
		return 'v_free'
	}
	if name == 'exit' {
		return 'v_exit'
	}
	if name in export_c_libc_collision_symbols {
		return 'v_${name}'
	}
	return naming.c_name(name)
}

fn is_valid_export_c_name(name string) bool {
	if name.len == 0 {
		return false
	}
	if name in export_c_reserved_words {
		return false
	}
	if name in export_v3_reserved_c_symbols {
		return false
	}
	first := name[0]
	if !((first >= `a` && first <= `z`) || (first >= `A` && first <= `Z`) || first == `_`) {
		return false
	}
	for i in 1 .. name.len {
		c := name[i]
		if (c >= `a` && c <= `z`) || (c >= `A` && c <= `Z`) || (c >= `0` && c <= `9`) || c == `_` {
			continue
		}
		return false
	}
	return true
}

fn (mut tc TypeChecker) insert_implicit_veb_ctx(node flat.Node) {
	if !tc.fn_needs_implicit_veb_ctx(node) {
		return
	}
	// The implicit veb `ctx` is a `mut ctx Context` parameter — veb hands the
	// handler a mutable context. Register it as a mut-param binding (not a plain
	// immutable local) so mut-receiver methods like `ctx.json(...)` / `ctx.set_status(...)`
	// see a mutable lvalue receiver.
	typ := tc.implicit_veb_ctx_type()
	owner := tc.cur_scope.insert_with_owner('ctx', typ)
	tc.fn_context.mut_param_base_types['ctx'] = mut_param_base_type(typ)
	tc.fn_context.mut_param_owners['ctx'] = owner
}

fn (tc &TypeChecker) fn_param_types_with_implicit_veb_ctx(node flat.Node, params []Type) []Type {
	if !tc.fn_needs_implicit_veb_ctx(node) {
		return params
	}
	insert_idx := tc.fn_implicit_veb_ctx_insert_index(node)
	mut result := []Type{cap: params.len + 1}
	for i, param in params {
		if i == insert_idx {
			result << tc.implicit_veb_ctx_type()
		}
		result << param
	}
	if insert_idx >= params.len {
		result << tc.implicit_veb_ctx_type()
	}
	return result
}

fn (tc &TypeChecker) fn_shared_params_with_implicit_veb_ctx(node flat.Node, flags []bool) []bool {
	if !tc.fn_needs_implicit_veb_ctx(node) {
		return flags
	}
	insert_idx := tc.fn_implicit_veb_ctx_insert_index(node)
	mut result := []bool{cap: flags.len + 1}
	for i, flag in flags {
		if i == insert_idx {
			result << false
		}
		result << flag
	}
	if insert_idx >= flags.len {
		result << false
	}
	return result
}

fn param_type_text_is_shared(raw string) bool {
	return trimmed_space(raw).starts_with('shared ')
}

fn decl_assign_is_shared_marker(value string) bool {
	return value == 'shared' || value.starts_with('shared:')
}

fn (tc &TypeChecker) implicit_veb_ctx_type() Type {
	return tc.parse_type('mut Context')
}

fn (tc &TypeChecker) fn_needs_implicit_veb_ctx(node flat.Node) bool {
	return tc.fn_returns_veb_result(node) && tc.fn_has_receiver_param(node)
		&& !tc.fn_receiver_type_is_context(node) && !tc.fn_has_param(node, 'ctx')
		&& tc.type_name_known_in_current_module('Context')
}

fn (tc &TypeChecker) fn_implicit_veb_ctx_insert_index(node flat.Node) int {
	if tc.fn_has_receiver_param(node) {
		return 1
	}
	return 0
}

fn (tc &TypeChecker) fn_has_receiver_param(node flat.Node) bool {
	if !node.value.contains('.') || node.children_count == 0 {
		return false
	}
	first := tc.a.child_node(&node, 0)
	if first.kind != .param || first.typ.len == 0 {
		return false
	}
	receiver := node.value.all_before_last('.').all_after_last('.')
	param_type := first.typ.trim_left('&').all_after_last('.')
	return receiver == param_type
}

fn (tc &TypeChecker) fn_receiver_type_is_context(node flat.Node) bool {
	if !tc.fn_has_receiver_param(node) {
		return false
	}
	first := tc.a.child_node(&node, 0)
	return first.typ.trim_left('&').all_after_last('.') == 'Context'
}

fn (tc &TypeChecker) fn_has_param(node flat.Node, name string) bool {
	for i in 0 .. node.children_count {
		p := tc.a.child_node(&node, i)
		if p.kind == .param && p.value == name {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) fn_returns_veb_result(node flat.Node) bool {
	raw_type := node.typ.trim_space()
	if raw_type == 'veb.Result' {
		return true
	}
	// Most declarations cannot return veb.Result. Avoid resolving unrelated
	// expression-derived return types such as `typeof(value)` during collection.
	if raw_type != 'Result' && !raw_type.ends_with('.Result') {
		return false
	}
	ret := tc.parse_type(raw_type)
	return ret.name() == 'veb.Result'
}

// check_fn_body validates check fn body state for types.
fn (mut tc TypeChecker) check_fn_body(node flat.Node) {
	saved_smartcasts := clone_smartcasts(tc.smartcasts)
	defer {
		tc.smartcasts = clone_smartcasts(saved_smartcasts)
	}
	mut sequence_exited := false
	mut unreachable_id := flat.empty_node
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.child_node(&node, i)
		if child.kind == .param {
			continue
		}
		if child.kind == .label_stmt {
			sequence_exited = false
			unreachable_id = flat.empty_node
		} else if sequence_exited && !tc.valid_node_id(unreachable_id) {
			unreachable_id = child_id
		}
		error_count := tc.errors.len
		tc.check_stmt_node(child_id)
		continue_after_unknown_ident := tc.fn_context.continue_after_unknown_ident
		tc.fn_context.continue_after_unknown_ident = false
		tc.apply_post_if_exit_smartcasts(child_id)
		tc.apply_post_assert_smartcasts(child_id)
		if tc.statement_exits_sequence(child_id, child) {
			sequence_exited = true
		}
		if tc.new_error_kind_since(error_count, .unknown_ident) && child.kind != .comptime_if
			&& !tc.new_errors_are_forward_decl_unknowns(error_count)
			&& !continue_after_unknown_ident {
			break
		}
	}
	if tc.valid_node_id(unreachable_id) && tc.should_diagnose(unreachable_id) {
		tc.record_error_at(.return_mismatch, 'unreachable code', unreachable_id,
			tc.unreachable_statement_diagnostic_pos(unreachable_id))
	}
}

fn (tc &TypeChecker) new_errors_are_forward_decl_unknowns(start int) bool {
	if start < 0 || start >= tc.errors.len {
		return false
	}
	mut found := false
	for i in start .. tc.errors.len {
		err := tc.errors[i]
		if err.kind != .unknown_ident {
			continue
		}
		if !err.msg.contains('(used before declaration)')
			&& !err.msg.starts_with('unresolved variable:')
			&& !err.msg.contains('(use `:=` to declare a variable)') {
			return false
		}
		found = true
	}
	return found
}

fn (tc &TypeChecker) new_error_kind_since(start int, kind TypeErrorKind) bool {
	if start < 0 || start >= tc.errors.len {
		return false
	}
	for i in start .. tc.errors.len {
		if tc.errors[i].kind == kind {
			return true
		}
	}
	return false
}

// check_decl_type_strings validates check decl type strings state for types.
fn (mut tc TypeChecker) check_decl_type_strings(node_id flat.NodeId, node flat.Node) {
	mut generic_params := tc.infer_decl_generic_params(node)
	if node.kind == .type_decl && node.generic_params().len == 0 {
		for name in tc.fixed_array_map_alias_generic_params(node.typ) {
			generic_params[name] = true
		}
	}
	decl_generic_mentions_error := tc.check_struct_or_interface_decl_generic_mentions(node_id, node)
	if node.kind == .type_decl {
		if imported_name := tc.selective_imported_builtin_in_type(node.typ) {
			base := 'unknown type `${imported_name}`'
			message := util.new_suggestion(imported_name, tc.known_type_name_candidates()).say(base)
			tc.record_error_at(.unknown_type, message, node_id, tc.type_diagnostic_pos(node_id,
				node.typ.trim_space()))
		}
		alias_name := node.typ.trim_space()
		alias_type := tc.parse_type(alias_name)
		if alias_type is Alias && alias_type.base_type is FnType {
			original_type := Type(alias_type.base_type).name().replace_once('fn(', 'fn (')
			tc.record_error_at(.unknown_type,
				'type `${alias_name}` is an alias, use the original alias type `${original_type}` instead',
				node_id, tc.type_diagnostic_pos(node_id, alias_name))
		}
	}
	if node.kind == .fn_decl {
		tc.check_fn_decl_unmentioned_generic_types(node_id, node)
		tc.check_fn_bare_generic_signature_types(node_id, node)
	}
	if node.kind == .type_decl && node.children_count > 0 {
		tc.check_implicit_generic_sumtype_decl(node_id, node)
	}
	if node.kind == .fn_decl && node.value.contains('.') {
		receiver_name := node.value.all_before_last('.').all_after_last('.')
		mut is_static := node.children_count == 0
		if node.children_count > 0 {
			first := tc.a.child_node(&node, 0)
			is_static = first.kind != .param || first.op != .dot
		}
		if is_static && !tc.type_name_known(receiver_name) {
			tc.record_error_at(.unknown_type, 'unknown type `${receiver_name}`', node_id, tc.type_diagnostic_pos(node_id,
				receiver_name))
		}
	}
	if node.kind == .type_decl && node.typ.trim_space().starts_with('!') {
		tc.record_error_with_details_at(.unknown_type, 'cannot make an alias of Result type',
			node_id, tc.type_diagnostic_pos(node_id, node.typ.trim_space()), [
			'Result types cannot be stored and have to be unwrapped immediately',
		])
	}
	if node.kind == .type_decl && node.typ.trim_space() == 'none' {
		tc.record_error_at(.unknown_type, 'cannot create a type alias of `none` as it is a value',
			node_id, tc.type_diagnostic_pos(node_id, 'none'))
	}
	if node.kind == .struct_decl {
		if 'generic' in node.typ.split(',') && tc.reject_unsupported_generics {
			tc.record_unsupported_generic('unsupported generic struct `${node.value}`', node_id)
		}
	} else {
		if node.generic_params().len > 0 && tc.reject_unsupported_generics {
			tc.record_unsupported_generic('unsupported generic declaration `${node.value}`',
				node_id)
		}
		if !decl_generic_mentions_error
			|| tc.unmentioned_generic_names_in_type(node.typ, generic_param_map_from_names(node.generic_params())).len == 0 {
			tc.check_type_string_for_unsupported_generics(node.typ, node_id, generic_params)
		}
	}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		if int(child_id) < 0 {
			continue
		}
		child := tc.a.nodes[int(child_id)]
		// A `comptime_for` node stores its loop source (`val`, `T`) in `typ`, which is a value
		// or generic placeholder rather than a declared type; it is validated at unroll time.
		if child.kind == .comptime_for {
			continue
		}
		explicit_decl_params := generic_param_map_from_names(node.generic_params())
		if !decl_generic_mentions_error
			|| tc.unmentioned_generic_names_in_type(child.typ, explicit_decl_params).len == 0 {
			tc.check_type_string_for_unsupported_generics(child.typ, child_id, generic_params)
		}
		if node.kind == .interface_decl && child.kind == .interface_field && child.op == .dot
			&& child.generic_params().len > 0 {
			tc.record_error_at(.unsupported_generic,
				"no need to add generic type names in generic interface's method", child_id, tc.interface_method_generic_param_pos(child,
				child.generic_params()[0]))
		}
		if node.kind == .interface_decl && child.kind == .interface_field && child.op != .dot {
			field_type := unalias_type(tc.parse_type(child.typ))
			if field_type is Interface
				&& tc.interface_metadata_name(field_type.name) == tc.interface_metadata_name(node.value) {
				tc.record_error_at(.assignment_mismatch,
					'recursive interface fields are not allowed because they cannot be initialised',
					child_id, tc.type_diagnostic_pos(child_id, child.typ))
			}
		}
		if child.kind == .param && child.typ.trim_space().starts_with('!') {
			tc.record_error_at(.unknown_type, 'result type arguments are not supported', child_id, tc.type_diagnostic_pos(child_id,
				child.typ.trim_space()))
		}
		if node.kind == .struct_decl {
			tc.check_missing_struct_field_generic_type(child_id, child.typ, generic_params)
			field_type := unalias_type(tc.parse_type(child.typ))
			if child.kind == .field_decl && field_type is Map
				&& unalias_type(field_type.value_type) is ResultType {
				tc.record_error_at(.unknown_type, 'cannot use Result type as map value type',
					child_id, tc.struct_field_type_pos(child))
			}
		}
		if node.kind == .type_decl && child.value.len > 0 {
			tc.check_type_string_for_unsupported_generics(child.value, child_id, generic_params)
		}
		for j in 0 .. child.children_count {
			grandchild_id := tc.a.child(&child, j)
			if int(grandchild_id) < 0 {
				continue
			}
			grandchild := tc.a.nodes[int(grandchild_id)]
			if grandchild.kind == .comptime_for {
				continue
			}
			if !decl_generic_mentions_error
				|| tc.unmentioned_generic_names_in_type(grandchild.typ, explicit_decl_params).len == 0 {
				tc.check_type_string_for_unsupported_generics(grandchild.typ, grandchild_id,
					generic_params)
			}
		}
	}
}

fn (tc &TypeChecker) fixed_array_map_alias_generic_params(typ string) []string {
	clean := typ.trim_space()
	if !clean.starts_with('[') {
		return []string{}
	}
	bracket_end := find_matching_bracket(clean, 0)
	if bracket_end >= clean.len {
		return []string{}
	}
	element_type := clean[bracket_end + 1..].trim_space()
	if !element_type.starts_with('map[') {
		return []string{}
	}
	mut counts := map[string]int{}
	tc.collect_generic_param_candidates(element_type, mut counts)
	mut names := []string{cap: counts.len}
	for name, _ in counts {
		names << name
	}
	names.sort()
	return names
}

fn (tc &TypeChecker) selective_imported_builtin_in_type(type_text string) ?string {
	info := tc.current_file_import_info()
	if isnil(info) {
		return none
	}
	mut best_offset := type_text.len + 1
	mut imported_name := ''
	for name, candidates in info.selective_imports {
		if !is_builtin_type_name(name) || candidates.len != 1
			|| !type_text_contains_symbol(type_text, name) {
			continue
		}
		offset := type_text.index(name) or { continue }
		if offset < best_offset {
			best_offset = offset
			imported_name = candidates[0]
		}
	}
	if imported_name.len == 0 {
		return none
	}
	return imported_name
}

fn (tc &TypeChecker) interface_method_generic_param_pos(method flat.Node, param string) token.Pos {
	file := tc.a.source_files[method.pos.id] or { return method.pos }
	source := tc.source_texts_by_file[file.name] or { return method.pos }
	needle := '${method.value}[${param}'
	start := source.index(needle) or { return method.pos }
	param_start := start + method.value.len
	return token.new_span(method.pos.id, param_start, param_start + param.len)
}

fn (mut tc TypeChecker) check_fn_bare_generic_fntype_params(node flat.Node) {
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind == .param && child.op != .dot {
			tc.check_bare_generic_fntype_param(child_id, child.typ)
		}
	}
}

fn (mut tc TypeChecker) check_struct_or_interface_decl_generic_mentions(node_id flat.NodeId, node flat.Node) bool {
	if node.kind !in [.struct_decl, .interface_decl] {
		return false
	}
	explicit_names := node.generic_params()
	explicit_params := generic_param_map_from_names(explicit_names)
	mut has_unmentioned := false
	for i in 0 .. node.children_count {
		child := tc.a.child_node(&node, i)
		child_type := if node.kind == .interface_decl && child.op != .dot && child.typ.len == 0 {
			child.value
		} else {
			child.typ
		}
		if tc.unmentioned_generic_names_in_type(child_type, explicit_params).len > 0 {
			has_unmentioned = true
		}
		if node.kind == .interface_decl && child.op == .dot {
			for j in 0 .. child.children_count {
				param := tc.a.child_node(child, j)
				if tc.unmentioned_generic_names_in_type(param.typ, explicit_params).len > 0 {
					has_unmentioned = true
				}
			}
		}
	}
	if !has_unmentioned {
		return false
	}
	kind := if node.kind == .struct_decl { 'struct' } else { 'interface' }
	if explicit_names.len == 0 {
		pos := if node.kind == .struct_decl {
			tc.struct_declaration_name_pos(node)
		} else {
			tc.source_line_declaration_pos(node_id)
		}
		tc.record_error_at(.unsupported_generic,
			'generic ${kind} `${node.value}` declaration must specify the generic type names, e.g. ${node.value}[T]',
			node_id, pos)
		return true
	}
	decl_name := if node.kind == .interface_decl {
		'${node.value}<${explicit_names.join(', ')}>'
	} else {
		'${node.value}[${explicit_names.join(', ')}]'
	}
	mut diagnosed := map[string]bool{}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		child_type := if node.kind == .interface_decl && child.op != .dot && child.typ.len == 0 {
			child.value
		} else {
			child.typ
		}
		for name in tc.unmentioned_generic_names_in_type(child_type, explicit_params) {
			key := '${int(child_id)}\n${name}'
			if diagnosed[key] {
				continue
			}
			diagnosed[key] = true
			pos_text := if node.kind == .interface_decl && child.op != .dot && child.typ.len == 0 {
				base, _, is_generic := generic_type_application_parts(child_type)
				if is_generic {
					base
				} else {
					child_type
				}
			} else {
				child_type
			}
			tc.record_error_at(.unknown_type,
				'generic type name `${name}` is not mentioned in ${kind} `${decl_name}`', child_id, tc.type_diagnostic_pos(child_id,
				pos_text))
		}
		if node.kind != .interface_decl || child.op != .dot {
			continue
		}
		for j in 0 .. child.children_count {
			param_id := tc.a.child(child, j)
			param := tc.a.node(param_id)
			for name in tc.unmentioned_generic_names_in_type(param.typ, explicit_params) {
				key := '${int(param_id)}\n${name}'
				if diagnosed[key] {
					continue
				}
				diagnosed[key] = true
				tc.record_error_at(.unknown_type,
					'generic type name `${name}` is not mentioned in ${kind} `${decl_name}`',
					param_id, tc.type_diagnostic_pos(param_id, param.typ))
			}
		}
	}
	return true
}

fn (mut tc TypeChecker) check_fn_bare_generic_signature_types(node_id flat.NodeId, node flat.Node) {
	if node.generic_params().len > 0 {
		if name := tc.bare_generic_decl_type_name(node.typ) {
			kind, params := tc.generic_decl_kind_and_params(name)
			if kind.len > 0 {
				tc.record_error_at(.unsupported_generic,
					'return generic ${kind} `${name}` in fn declaration must specify the generic type names, e.g. ${name}[${params.join(', ')}]',
					node_id, tc.fn_return_type_diagnostic_pos(node))
			}
		}
	}
	if !node.value.contains('.') || node.children_count == 0 {
		return
	}
	receiver_id := tc.a.child(&node, 0)
	receiver := tc.a.node(receiver_id)
	if receiver.kind != .param || receiver.op != .dot {
		return
	}
	name := tc.bare_generic_decl_type_name(receiver.typ) or { return }
	kind, params := tc.generic_decl_kind_and_params(name)
	if kind.len == 0 {
		return
	}
	tc.record_error_at(.unsupported_generic,
		'generic ${kind} `${name}` in fn declaration must specify the generic type names, e.g. ${name}[${params.join(', ')}]',
		receiver_id, tc.type_diagnostic_pos(receiver_id, receiver.typ))
}

fn (tc &TypeChecker) fn_decl_has_bare_generic_signature_type(node flat.Node) bool {
	if node.generic_params().len > 0 && tc.bare_generic_decl_type_name(node.typ) != none {
		return true
	}
	if !node.value.contains('.') || node.children_count == 0 {
		return false
	}
	receiver := tc.a.child_node(&node, 0)
	return receiver.kind == .param && receiver.op == .dot
		&& tc.bare_generic_decl_type_name(receiver.typ) != none
}

fn (tc &TypeChecker) generic_decl_kind_and_params(name string) (string, []string) {
	qualified := tc.qualify_name(name)
	if name in tc.struct_generic_params {
		return 'struct', tc.struct_generic_params[name]
	}
	if qualified in tc.struct_generic_params {
		return 'struct', tc.struct_generic_params[qualified]
	}
	if name in tc.interface_generic_params {
		return 'interface', tc.interface_generic_params[name]
	}
	if qualified in tc.interface_generic_params {
		return 'interface', tc.interface_generic_params[qualified]
	}
	if name in tc.sum_generic_params {
		return 'sumtype', tc.sum_generic_params[name]
	}
	if qualified in tc.sum_generic_params {
		return 'sumtype', tc.sum_generic_params[qualified]
	}
	if name in tc.type_alias_generic_params {
		params := tc.type_alias_generic_params[name]
		kind := if unalias_type(tc.parse_type(name)) is FnType { 'function' } else { 'alias' }
		return kind, params
	}
	if qualified in tc.type_alias_generic_params {
		params := tc.type_alias_generic_params[qualified]
		kind := if unalias_type(tc.parse_type(qualified)) is FnType {
			'function'
		} else {
			'alias'
		}
		return kind, params
	}
	return '', []string{}
}

fn (mut tc TypeChecker) check_fn_decl_unmentioned_generic_types(node_id flat.NodeId, node flat.Node) {
	mut explicit_params := generic_param_map_from_names(node.generic_params())
	if node.value.contains('.') && node.children_count > 0 {
		receiver := tc.a.child_node(&node, 0)
		if receiver.kind == .param {
			receiver_type := unwrap_pointer(tc.parse_type(receiver.typ))
			// Generic struct receiver parameters belong to the method declaration.
			// Alias and sum-type receivers still have to repeat their generic names,
			// matching the v1 declaration rules.
			if receiver_type is Struct {
				tc.collect_generic_receiver_params(node, mut explicit_params)
			}
		}
	}
	mut missing_ids := []flat.NodeId{}
	mut missing_names := []string{}
	mut missing_types := []string{}
	mut diagnosed := map[string]bool{}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind != .param || child.typ.len == 0 {
			continue
		}
		for name in tc.unmentioned_generic_names_in_type(child.typ, explicit_params) {
			key := '${int(child_id)}\n${name}'
			if diagnosed[key] {
				continue
			}
			diagnosed[key] = true
			missing_ids << child_id
			missing_names << name
			missing_types << child.typ.trim_space()
		}
	}
	if node.typ.len > 0 {
		for name in tc.unmentioned_generic_names_in_type(node.typ, explicit_params) {
			key := '${int(node_id)}\n${name}'
			if diagnosed[key] {
				continue
			}
			diagnosed[key] = true
			missing_ids << node_id
			missing_names << name
			missing_types << node.typ.trim_space()
		}
	}
	if missing_names.len == 0 {
		return
	}
	if node.generic_params().len == 0 {
		if node.value.contains('.') {
			tc.record_error_with_details_at(.unsupported_generic,
				'generic method declaration must specify generic type names', node_id,
				tc.fn_declaration_diagnostic_pos(node), [
				'use `fn (r SomeType[T]) foo[T]() {`, not just `fn (r SomeType[T]) foo() {`',
			])
		} else {
			tc.record_error_with_details_at(.unsupported_generic,
				'generic function declaration must specify generic type names', node_id,
				tc.fn_declaration_diagnostic_pos(node), [
				'use `fn foo[T](x T) {`, not just `fn foo(x T) {`',
			])
		}
	}
	for i, name in missing_names {
		tc.record_error_at(.unknown_type,
			'generic type name `${name}` is not mentioned in fn `${node.value.all_after_last('.')}[${node.generic_params().join(', ')}]`',
			missing_ids[i], tc.type_diagnostic_pos(missing_ids[i], missing_types[i]))
	}
}

fn (mut tc TypeChecker) check_bare_generic_fntype_param(node_id flat.NodeId, type_text string) {
	name := tc.bare_generic_decl_type_name(type_text) or { return }
	qualified := tc.qualify_name(name)
	interface_params := tc.interface_generic_params[name] or {
		tc.interface_generic_params[qualified] or { []string{} }
	}
	if interface_params.len > 0 {
		tc.record_error_at(.unsupported_generic,
			'generic interface `${name}` in fn declaration must specify the generic type names, e.g. ${name}[${interface_params.join(', ')}]',
			node_id, tc.type_diagnostic_pos(node_id, type_text))
		return
	}
	params := tc.type_alias_generic_params[name] or {
		tc.type_alias_generic_params[qualified] or { return }
	}
	if params.len == 0 || unalias_type(tc.parse_type(name)) !is FnType {
		return
	}
	tc.record_error_at(.unsupported_generic,
		'generic function `${name}` in fn declaration must specify the generic type names, e.g. ${name}[${params.join(', ')}]',
		node_id, tc.type_diagnostic_pos(node_id, type_text))
}

fn (mut tc TypeChecker) check_implicit_generic_sumtype_decl(node_id flat.NodeId, node flat.Node) {
	decl_params := node.generic_params()
	if decl_params.len > 0 {
		for i in 0 .. node.children_count {
			child_id := tc.a.child(&node, i)
			variant := tc.a.node(child_id).value.trim_space()
			base, args, is_generic := generic_type_application_parts(variant)
			if !is_generic {
				continue
			}
			qualified := tc.qualify_name(base)
			struct_params := tc.struct_generic_params[base] or {
				tc.struct_generic_params[qualified] or { []string{} }
			}
			if struct_params.len == 0 {
				continue
			}
			for arg in args {
				if is_bare_generic_param(arg) && arg !in decl_params {
					tc.record_error_at(.unknown_type,
						'generic type name `${arg}` of generic struct `${variant}` is not mentioned in sumtype `${node.value}[${decl_params.join(', ')}]`',
						child_id, tc.type_diagnostic_pos(node_id, variant))
				}
			}
		}
		return
	}
	mut requires_generic_params := false
	mut example_params := []string{}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		variant := child.value.trim_space()
		if variant.len == 0 {
			continue
		}
		base, args, is_generic := generic_type_application_parts(variant)
		lookup := if is_generic { base } else { variant }
		qualified := tc.qualify_name(lookup)
		params := tc.struct_generic_params[lookup] or {
			tc.struct_generic_params[qualified] or {
				tc.type_alias_generic_params[lookup] or {
					tc.type_alias_generic_params[qualified] or {
						tc.sum_generic_params[lookup] or {
							tc.sum_generic_params[qualified] or { []string{} }
						}
					}
				}
			}
		}
		if params.len == 0 {
			continue
		}
		if !is_generic {
			requires_generic_params = true
			if example_params.len == 0 {
				example_params = params.clone()
			}
			kind := if lookup in tc.struct_generic_params || qualified in tc.struct_generic_params {
				'struct'
			} else if unalias_type(tc.parse_type(lookup)) is FnType {
				'fntype'
			} else {
				'sumtype'
			}
			tc.record_error_at(.unknown_type,
				'generic ${kind} `${lookup}` must specify generic type names, e.g. ${lookup}[${params.join(', ')}]',
				child_id, tc.type_diagnostic_pos(node_id, variant))
			continue
		}
		for arg in args {
			if is_bare_generic_param(arg) && !tc.type_name_known(arg) {
				requires_generic_params = true
				if example_params.len == 0 {
					example_params = params.clone()
				}
				break
			}
		}
	}
	if requires_generic_params {
		if example_params.len == 0 {
			example_params = ['T']
		}
		tc.record_error_at(.unsupported_generic,
			'generic sumtype `${node.value}` must specify generic type names, e.g. ${node.value}[${example_params.join(', ')}]',
			node_id, tc.type_diagnostic_pos(node_id, node.value))
	}
}

fn (tc &TypeChecker) unmentioned_generic_names_in_type(typ string, explicit_params map[string]bool) []string {
	mut names := []string{}
	for i, ch in typ {
		if ch < `A` || ch > `Z` {
			continue
		}
		if i > 0 && is_type_symbol_byte(typ[i - 1]) {
			continue
		}
		if i + 1 < typ.len && (is_type_symbol_byte(typ[i + 1]) || typ[i + 1] == `.`) {
			continue
		}
		name := typ[i..i + 1]
		if explicit_params[name] || tc.type_name_known(name) || name in names {
			continue
		}
		names << name
	}
	return names
}

fn (tc &TypeChecker) unmentioned_generic_type_was_reported(name string, file_id int) bool {
	needle := 'generic type name `${name}` is not mentioned in fn '
	for err in tc.errors {
		if err.pos.id == file_id && err.msg.starts_with(needle) {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) check_struct_implements(node_id flat.NodeId, node flat.Node) {
	mut seen_interfaces := map[string]bool{}
	mut reported_interfaces := map[string]bool{}
	for implements_index, type_name in struct_decl_implements_from_typ(node.typ) {
		base, args, is_generic := generic_type_application_parts(type_name)
		raw_lookup := if is_generic { base } else { type_name }
		lookup := tc.resolve_selective_import_type_symbol(raw_lookup) or { raw_lookup }
		qualified := tc.qualify_name(lookup)
		interface_params := tc.interface_generic_params[lookup] or {
			tc.interface_generic_params[qualified] or { []string{} }
		}
		diagnostic_pos := tc.struct_implements_type_pos(node, type_name, implements_index)
		if interface_params.len > 0 && !is_generic {
			tc.record_error_at(.unknown_type, 'missing generic type on ${lookup}', node_id,
				diagnostic_pos)
			continue
		}
		if is_generic && interface_params.len > 0 {
			mut unknown_arg := ''
			for raw_arg in args {
				arg := raw_arg.trim_space()
				if arg !in node.generic_params() && tc.type_text_has_generic_placeholder(arg) {
					unknown_arg = arg
					break
				}
			}
			if unknown_arg.len > 0 {
				tc.record_error_at(.unknown_type, 'unknown generic type ${unknown_arg}', node_id,
					diagnostic_pos)
				continue
			}
		}
		if lookup in tc.interface_names || qualified in tc.interface_names {
			interface_name := if lookup in tc.interface_names { lookup } else { qualified }
			if seen_interfaces[interface_name] {
				if !reported_interfaces[interface_name] {
					tc.record_error_at(.assignment_mismatch,
						'struct type ${node.value} cannot implement interface `${interface_name} more than once`',
						node_id, diagnostic_pos)
					reported_interfaces[interface_name] = true
				}
				continue
			}
			seen_interfaces[interface_name] = true
			actual := Type(Struct{
				name: node.value
			})
			expected := Interface{
				name: interface_name
			}
			if !tc.type_implements_interface(actual, expected) {
				tc.record_interface_implementation_error(.assignment_mismatch, actual, expected,
					node_id, tc.struct_declaration_name_pos(node))
			}
			continue
		}
		if is_generic && (lookup in tc.interface_names || qualified in tc.interface_names) {
			continue
		}
		tc.record_error_at(.assignment_mismatch, '`${type_name}` is not an interface type',
			node_id, diagnostic_pos)
	}
}

fn (tc &TypeChecker) struct_implements_type_pos(node flat.Node, type_name string, ordinal int) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	decl_pos := tc.struct_declaration_name_pos(node)
	start_limit := int_max(0, int_min(decl_pos.offset, source.len))
	line_end := source[start_limit..].index('{') or { return node.pos }
	header_end := int_min(source.len, start_limit + line_end)
	header := source[start_limit..header_end]
	implements_at := header.index('implements') or { return node.pos }
	mut cursor := start_limit + implements_at + 'implements'.len
	for current in 0 .. ordinal + 1 {
		for cursor < header_end && source[cursor] in [` `, `\t`, `\n`, `\r`, `,`] {
			cursor++
		}
		item_start := cursor
		for cursor < header_end && source[cursor] != `,` {
			cursor++
		}
		mut item_end := cursor
		for item_end > item_start && source[item_end - 1] in [` `, `\t`, `\n`, `\r`] {
			item_end--
		}
		if current == ordinal {
			end := if type_name.contains('.') {
				int_min(item_end, item_start + type_name.all_before('.').len)
			} else {
				item_end
			}
			return token.new_span(node.pos.id, item_start, end)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) struct_declaration_name_pos(node flat.Node) token.Pos {
	if !node.pos.is_valid() {
		return node.pos
	}
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	end := int_max(0, int_min(node.pos.end, source.len))
	needle := 'struct ${node.value}'
	start := source[..end].last_index(needle) or { return node.pos }
	return token.new_span(node.pos.id, start, start + needle.len)
}

fn (mut tc TypeChecker) check_missing_struct_field_generic_type(node_id flat.NodeId, type_text string, generic_params map[string]bool) {
	name := tc.bare_generic_decl_type_name(type_text) or { return }
	qualified := tc.qualify_name(name)
	mut kind := ''
	mut target_params := []string{}
	if name in tc.struct_generic_params || qualified in tc.struct_generic_params {
		kind = 'struct'
		target_params = tc.struct_generic_params[name] or {
			tc.struct_generic_params[qualified] or { []string{} }
		}
	} else if name in tc.interface_generic_params || qualified in tc.interface_generic_params {
		kind = 'interface'
		target_params = tc.interface_generic_params[name] or {
			tc.interface_generic_params[qualified] or { []string{} }
		}
	} else if name in tc.sum_generic_params || qualified in tc.sum_generic_params {
		kind = 'sumtype'
		target_params = tc.sum_generic_params[name] or {
			tc.sum_generic_params[qualified] or { []string{} }
		}
	} else if name in tc.type_alias_generic_params || qualified in tc.type_alias_generic_params {
		parsed := unalias_type(tc.parse_type(name))
		if parsed is FnType {
			kind = 'fn type'
		} else {
			kind = 'alias'
		}
		target_params = tc.type_alias_generic_params[name] or {
			tc.type_alias_generic_params[qualified] or { []string{} }
		}
	} else {
		return
	}
	mut context_name := 'int'
	if target_params.len > 0 {
		context_name = target_params[0]
	}
	mut context_names := generic_param_names_from_map(generic_params)
	if context_names.len > 0 {
		context_name = context_names[0]
	}
	node := tc.a.node(node_id)
	mut pos := if node.kind == .field_decl {
		tc.struct_field_type_pos(node)
	} else {
		tc.type_diagnostic_pos(node_id, type_text)
	}
	tc.record_error_at(.unknown_type,
		'`${name}` type is generic ${kind}, must specify the generic type names, e.g. ${name}[${context_name}], ${name}[int]',
		node_id, pos)
}

fn (tc &TypeChecker) bare_generic_decl_type_name(type_text string) ?string {
	clean := trimmed_space(type_text)
	if clean.len == 0 {
		return none
	}
	if clean.starts_with('&') || clean.starts_with('?') || clean.starts_with('!') {
		return tc.bare_generic_decl_type_name(clean[1..])
	}
	if clean.starts_with('shared ') {
		return tc.bare_generic_decl_type_name(clean[7..])
	}
	if clean.starts_with('...') {
		return tc.bare_generic_decl_type_name(clean[3..])
	}
	if clean.starts_with('[]') {
		return tc.bare_generic_decl_type_name(clean[2..])
	}
	if clean.starts_with('map[') {
		close := find_matching_bracket(clean, 3)
		if close > 3 && close + 1 < clean.len {
			if generic_name := tc.bare_generic_decl_type_name(clean[4..close]) {
				return generic_name
			}
			return tc.bare_generic_decl_type_name(clean[close + 1..])
		}
		return none
	}
	if clean.starts_with('[') {
		close := clean.index_u8(`]`)
		if close > 0 && close + 1 < clean.len {
			return tc.bare_generic_decl_type_name(clean[close + 1..])
		}
		return none
	}
	if generic_type_application(clean) || !should_check_named_type(clean) {
		return none
	}
	qualified := tc.qualify_name(clean)
	if clean in tc.struct_generic_params || qualified in tc.struct_generic_params
		|| clean in tc.sum_generic_params || qualified in tc.sum_generic_params
		|| clean in tc.type_alias_generic_params || qualified in tc.type_alias_generic_params
		|| clean in tc.interface_generic_params || qualified in tc.interface_generic_params {
		return clean
	}
	return none
}

fn (mut tc TypeChecker) check_recursive_alias_decls() {
	mut invalid := []string{}
	for node_idx in tc.top_level_idx {
		node := tc.a.nodes[node_idx]
		match node.kind {
			.file {
				tc.enter_file(node.value)
			}
			.module_decl {
				tc.enter_module(node.value)
			}
			.type_decl {
				if node.children_count == 0 && node.typ.len > 0
					&& tc.check_recursive_alias_decl(flat.NodeId(node_idx), node) {
					invalid << tc.qualify_decl_name(node.value)
				}
			}
			else {}
		}
	}
	// Invalid aliases must not reach interface-index preparation or type lowering,
	// both of which assume the alias graph is acyclic.
	for name in invalid {
		tc.type_aliases[name] = 'void'
	}
}

fn (mut tc TypeChecker) check_recursive_alias_decl(node_id flat.NodeId, node flat.Node) bool {
	start := tc.qualify_decl_name(node.value)
	if start.len == 0 || start !in tc.type_aliases {
		return false
	}
	mut seen := map[string]bool{}
	if !tc.unguarded_alias_reaches(start, start, mut seen) {
		return false
	}
	if tc.should_diagnose(node_id) {
		tc.record_error(.unknown_type, 'alias `${node.value}` forms a recursive cycle', node_id)
	}
	return true
}

fn (tc &TypeChecker) unguarded_alias_reaches(start string, current string, mut seen map[string]bool) bool {
	if current in seen {
		return false
	}
	seen[current] = true
	target := tc.type_aliases[current] or { return false }
	mut names := []string{}
	collect_unguarded_alias_type_names(target, mut names)
	for name in names {
		dependency := tc.alias_dependency_key(name, current) or { continue }
		if dependency == start {
			return true
		}
		if tc.unguarded_alias_reaches(start, dependency, mut seen) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) alias_dependency_key(name string, current string) ?string {
	clean := name.trim_space()
	if clean.len == 0 {
		return none
	}
	if clean in tc.type_aliases {
		return clean
	}
	if !clean.contains('.') && current.contains('.') {
		candidate := '${current.all_before_last('.')}.${clean}'
		if candidate in tc.type_aliases {
			return candidate
		}
	}
	return none
}

fn collect_unguarded_alias_type_names(raw string, mut names []string) {
	mut clean := raw.trim_space()
	if clean.len == 0 {
		return
	}
	for {
		if clean.starts_with('&') || clean.starts_with('?') || clean.starts_with('!') {
			clean = clean[1..].trim_space()
			continue
		}
		if clean.starts_with('mut ') {
			clean = clean[4..].trim_space()
			continue
		}
		if clean.starts_with('shared ') || clean.starts_with('atomic ') {
			clean = clean[7..].trim_space()
			continue
		}
		if clean.starts_with('chan ') {
			clean = clean[5..].trim_space()
			continue
		}
		if clean.starts_with('thread ') {
			clean = clean[7..].trim_space()
			continue
		}
		break
	}
	// A callback introduces an indirection boundary: aliases such as
	// `type Handlers = map[string]fn (Handlers)` are recursive but finite.
	if clean.starts_with('fn(') || clean.starts_with('fn (') {
		return
	}
	if clean.starts_with('...') {
		collect_unguarded_alias_type_names(clean[3..], mut names)
		return
	}
	if clean.starts_with('[]') {
		collect_unguarded_alias_type_names(clean[2..], mut names)
		return
	}
	if clean.starts_with('map[') {
		bracket_end := find_matching_bracket(clean, 3)
		if bracket_end < clean.len {
			collect_unguarded_alias_type_names(clean[4..bracket_end], mut names)
			collect_unguarded_alias_type_names(clean[bracket_end + 1..], mut names)
		}
		return
	}
	if clean.starts_with('[') {
		bracket_end := find_matching_bracket(clean, 0)
		if bracket_end < clean.len {
			collect_unguarded_alias_type_names(clean[bracket_end + 1..], mut names)
		}
		return
	}
	if clean.starts_with('(') && clean.ends_with(')') {
		for part in split_params(clean[1..clean.len - 1]) {
			collect_unguarded_alias_type_names(part, mut names)
		}
		return
	}
	base, args, is_generic := generic_type_application_parts(clean)
	if is_generic {
		push_type_name_candidate(mut names, base)
		for arg in args {
			collect_unguarded_alias_type_names(arg, mut names)
		}
		return
	}
	push_type_name_candidate(mut names, clean)
}

fn (tc &TypeChecker) infer_decl_generic_params(node flat.Node) map[string]bool {
	mut params := map[string]bool{}
	for name in node.generic_params() {
		params[name] = true
	}
	tc.collect_generic_receiver_params(node, mut params)
	return params
}

fn (tc &TypeChecker) infer_decl_generic_param_names(node flat.Node) []string {
	params := tc.infer_decl_generic_params(node)
	return generic_param_names_from_map(params)
}

fn generic_param_names_from_map(params map[string]bool) []string {
	mut names := []string{cap: params.len}
	for name, _ in params {
		names << name
	}
	names.sort()
	return names
}

fn generic_param_map_from_names(names []string) map[string]bool {
	mut params := map[string]bool{}
	for name in names {
		params[name] = true
	}
	return params
}

fn (tc &TypeChecker) active_generic_param(name string) bool {
	for param in tc.fn_context.generic_params {
		if param == name {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) node_has_enclosing_generic_param(node_id flat.NodeId, name string) bool {
	if name.len == 0 || int(node_id) < 0 || int(node_id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(node_id)]
	if name in node.generic_params() {
		return true
	}
	for i in tc.top_level_idx {
		if i <= int(node_id) {
			continue
		}
		fn_node := tc.a.nodes[i]
		if fn_node.kind != .fn_decl || name !in fn_node.generic_params() {
			continue
		}
		for ci in 0 .. fn_node.children_count {
			if tc.a.child(&fn_node, ci) == node_id {
				return true
			}
		}
		break
	}
	return false
}

fn (tc &TypeChecker) collect_generic_receiver_params(node flat.Node, mut params map[string]bool) {
	if node.kind != .fn_decl && node.kind != .c_fn_decl {
		return
	}
	if !node.value.contains('.') {
		return
	}
	if node.children_count == 0 {
		return
	}
	receiver_id := tc.a.child(&node, 0)
	if int(receiver_id) < 0 {
		return
	}
	receiver := tc.a.nodes[int(receiver_id)]
	if receiver.kind != .param {
		return
	}
	receiver_type := receiver.typ.trim_left('&')
	if receiver_type != node.value.all_before_last('.') {
		return
	}
	receiver_base, receiver_args, is_generic := generic_type_application_parts(receiver_type)
	if is_generic {
		decl_params := tc.struct_generic_params[receiver_base] or {
			tc.struct_generic_params[receiver_base.all_after_last('.')] or { []string{} }
		}
		if receiver_args.len == decl_params.len {
			for arg in receiver_args {
				if arg in decl_params {
					params[arg] = true
				}
			}
		}
	}
	mut counts := map[string]int{}
	if !tc.collect_generic_param_candidates(receiver.typ, mut counts) {
		return
	}
	for name, _ in counts {
		params[name] = true
	}
}

fn (tc &TypeChecker) collect_generic_param_candidates(typ string, mut counts map[string]int) bool {
	clean := trimmed_space(typ)
	if clean.len == 0 {
		return false
	}
	if clean.starts_with('&') || clean.starts_with('?') || clean.starts_with('!') {
		return tc.collect_generic_param_candidates(clean[1..], mut counts)
	}
	if clean.starts_with('shared ') {
		return tc.collect_generic_param_candidates(clean[7..], mut counts)
	}
	if clean.starts_with('...') {
		return tc.collect_generic_param_candidates(clean[3..], mut counts)
	}
	if clean.starts_with('[]') {
		return tc.collect_generic_param_candidates(clean[2..], mut counts)
	}
	if clean.starts_with('map[') {
		mut found_context := false
		bracket_end := find_matching_bracket(clean, 3)
		if bracket_end < clean.len {
			if tc.collect_generic_param_candidates(clean[4..bracket_end], mut counts) {
				found_context = true
			}
			if tc.collect_generic_param_candidates(clean[bracket_end + 1..], mut counts) {
				found_context = true
			}
		}
		return found_context
	}
	if clean.starts_with('[') {
		idx := clean.index_u8(`]`)
		if idx > 0 {
			return tc.collect_generic_param_candidates(clean[idx + 1..], mut counts)
		}
		return false
	}
	if clean.starts_with('(') && clean.ends_with(')') {
		mut found_context := false
		for part in split_params(clean[1..clean.len - 1]) {
			if tc.collect_generic_param_candidates(part, mut counts) {
				found_context = true
			}
		}
		return found_context
	}
	if clean.starts_with('fn(') || clean.starts_with('fn (') {
		mut found_context := false
		params_start := clean.index_u8(`(`) + 1
		mut depth := 1
		mut params_end := params_start
		for params_end < clean.len {
			if clean[params_end] == `(` {
				depth++
			} else if clean[params_end] == `)` {
				depth--
				if depth == 0 {
					break
				}
			}
			params_end++
		}
		if params_end < clean.len {
			for part in split_params(clean[params_start..params_end]) {
				trimmed := trimmed_space(part)
				parts := trimmed.split(' ')
				param_type := if parts.len >= 2 { parts[parts.len - 1] } else { trimmed }
				if tc.collect_generic_param_candidates(param_type, mut counts) {
					found_context = true
				}
			}
			if tc.collect_generic_param_candidates(clean[params_end + 1..], mut counts) {
				found_context = true
			}
		}
		return found_context
	}
	if generic_type_application(clean) {
		bracket := clean.index_u8(`[`)
		bracket_end := find_matching_bracket(clean, bracket)
		if bracket_end < clean.len {
			for part in split_params(clean[bracket + 1..bracket_end]) {
				tc.collect_generic_param_candidates(part, mut counts)
			}
		}
		return true
	}
	if is_bare_generic_param(clean) && !tc.type_name_known(clean) {
		counts[clean] = (counts[clean] or { 0 }) + 1
	}
	return false
}

// check_type_string_for_unsupported_generics
// validates helper state for types.
fn (mut tc TypeChecker) check_type_string_for_unsupported_generics(typ string, node_id flat.NodeId, generic_params map[string]bool) {
	clean := trimmed_space(typ)
	if clean.len == 0 {
		return
	}
	if clean in ['generic', 'params', 'union'] {
		return
	}
	if clean == 'any' {
		tc.record_invalid_any_decl_type(node_id)
		return
	}
	if is_bare_generic_param(clean) {
		node := tc.a.node(node_id)
		if node.kind == .ident {
			return
		}
		if node.kind == .type_decl && clean !in generic_params {
			tc.record_error_at(.unknown_type, 'unknown aliased type `${clean}`', node_id, tc.type_diagnostic_pos(node_id,
				clean))
			return
		}
	}
	if clean.starts_with('&') || clean.starts_with('?') || clean.starts_with('!') {
		tc.check_type_string_for_unsupported_generics(clean[1..], node_id, generic_params)
		return
	}
	if clean.starts_with('shared ') {
		tc.check_type_string_for_unsupported_generics(clean[7..], node_id, generic_params)
		return
	}
	if clean == 'thread' || clean == 'chan' {
		return
	}
	if clean.starts_with('thread ') {
		// `thread T` is a thread handle; only its element type T needs checking.
		tc.check_type_string_for_unsupported_generics(clean[7..], node_id, generic_params)
		return
	}
	if clean.starts_with('chan ') {
		tc.check_type_string_for_unsupported_generics(clean[5..], node_id, generic_params)
		return
	}
	if clean.starts_with('...') {
		tc.check_type_string_for_unsupported_generics(clean[3..], node_id, generic_params)
		return
	}
	if clean.starts_with('[]') {
		tc.check_type_string_for_unsupported_generics(clean[2..], node_id, generic_params)
		return
	}
	if clean.starts_with('map[') {
		bracket_end := find_matching_bracket(clean, 3)
		if bracket_end < clean.len {
			tc.check_type_string_for_unsupported_generics(clean[4..bracket_end], node_id,
				generic_params)
			tc.check_type_string_for_unsupported_generics(clean[bracket_end + 1..], node_id,
				generic_params)
		}
		return
	}
	if clean.starts_with('[') {
		idx := clean.index_u8(`]`)
		if idx > 0 {
			tc.check_type_string_for_unsupported_generics(clean[idx + 1..], node_id, generic_params)
		}
		return
	}
	if clean.starts_with('(') && clean.ends_with(')') {
		for part in split_params(clean[1..clean.len - 1]) {
			tc.check_type_string_for_unsupported_generics(part, node_id, generic_params)
		}
		return
	}
	if clean.starts_with('fn(') || clean.starts_with('fn (') {
		tc.check_fn_type_string_for_unsupported_generics(clean, node_id, generic_params)
		return
	}
	if generic_type_application(clean) {
		if tc.reject_unsupported_generics {
			tc.record_unsupported_generic('unsupported generic type application `${clean}`',
				node_id)
			return
		}
		bracket := clean.index_u8(`[`)
		bracket_end := find_matching_bracket(clean, bracket)
		base := trimmed_space(clean[..bracket])
		if should_check_named_type(base) && !tc.type_name_known(base) {
			tc.record_unknown_decl_type(base, node_id)
		}
		if bracket_end < clean.len {
			for part in split_params(clean[bracket + 1..bracket_end]) {
				tc.check_type_string_for_unsupported_generics(part, node_id, generic_params)
			}
		}
		return
	}
	if is_bare_generic_param(clean) && !tc.type_name_known(clean) {
		if tc.reject_unsupported_generics {
			tc.record_unsupported_generic('unsupported generic type parameter `${clean}`', node_id)
			return
		}
		if clean in generic_params || tc.active_generic_param(clean)
			|| tc.node_has_enclosing_generic_param(node_id, clean) {
			return
		}
	}
	if should_check_named_type(clean) && !tc.type_name_known(clean) {
		if is_bare_generic_param(clean)
			&& tc.unmentioned_generic_type_was_reported(clean, tc.a.node(node_id).pos.id) {
			return
		}
		tc.record_unknown_decl_type(clean, node_id)
	}
}

fn (mut tc TypeChecker) record_invalid_any_decl_type(node_id flat.NodeId) {
	if int(node_id) < 0 || int(node_id) >= tc.a.nodes.len {
		return
	}
	node := tc.a.nodes[int(node_id)]
	if node.kind !in [.fn_decl, .c_fn_decl, .param, .field_decl, .interface_field, .type_decl,
		.ident] {
		return
	}
	if node.kind == .param {
		tc.record_notice_at(.unknown_type,
			'the `any` type is deprecated and will be removed soon - either use an empty interface, or a sum type',
			node_id, tc.node_value_diagnostic_pos(node_id))
		return
	}
	msg := if node.kind == .type_decl {
		'unknown aliased type `any`'
	} else {
		'cannot use type `any` here'
	}
	tc.record_error_at(.unknown_type, msg, node_id, tc.type_diagnostic_pos(node_id, 'any'))
}

fn (tc &TypeChecker) node_value_diagnostic_pos(node_id flat.NodeId) token.Pos {
	if int(node_id) < 0 || int(node_id) >= tc.a.nodes.len {
		return token.Pos{}
	}
	node := tc.a.nodes[int(node_id)]
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	return closest_identifier_span(source, node.value, node.pos.offset, node.pos.id) or { node.pos }
}

fn (mut tc TypeChecker) record_unknown_decl_type(name string, node_id flat.NodeId) {
	pos := tc.type_diagnostic_pos(node_id, name)
	if tc.unknown_type_already_reported_on_line(name, pos) {
		return
	}
	msg := tc.unknown_type_message(name, node_id)
	if tc.should_diagnose(node_id) {
		tc.record_error_at(.unknown_type, msg, node_id, pos)
		return
	}
	// Imported modules are normally outside the diagnostic-file set. Still reject
	// a bare annotation that only "resolves" because a selected main file happens
	// to declare the same type: main declarations are not implicitly imported.
	qualified := if tc.cur_module.len > 0 { '${tc.cur_module}.${name}' } else { name }
	if !name.contains('.') && name !in ['Error', 'MessageError', 'IError']
		&& tc.cur_module !in ['', 'main', 'builtin'] && tc.selected_main_file_declares_type(name)
		&& !tc.qualify_candidate_type_exists(qualified)
		&& !tc.source_declares_type_in_scope(name, tc.cur_file, tc.cur_module) {
		tc.record_error_unfiltered(.unknown_type, msg, node_id)
	}
}

fn (tc &TypeChecker) unknown_type_already_reported_on_line(name string, pos token.Pos) bool {
	if !pos.is_valid() {
		return false
	}
	msg := 'unknown type `${name}`'
	current_position := tc.a.source_position(pos) or { return false }
	for err in tc.errors {
		if !err.msg.starts_with(msg) || !err.pos.is_valid() || pos.id != err.pos.id {
			continue
		}
		error_position := tc.a.source_position(err.pos) or { continue }
		if current_position.line == error_position.line {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) type_error_already_reported_on_line(kind TypeErrorKind, msg string, pos token.Pos) bool {
	if !pos.is_valid() {
		return false
	}
	current_position := tc.a.source_position(pos) or { return false }
	for err in tc.errors {
		if err.kind != kind || err.msg != msg || !err.pos.is_valid() || pos.id != err.pos.id {
			continue
		}
		error_position := tc.a.source_position(err.pos) or { continue }
		if current_position.line == error_position.line {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) unknown_type_message(name string, node_id flat.NodeId) string {
	mut display_name := name
	if name.contains('.') {
		alias := name.all_before('.')
		if import_path := tc.current_file_import_path_for_alias(alias) {
			display_name = import_path + name[alias.len..]
		}
	}
	base := 'unknown type `${display_name}`'
	if int(node_id) >= 0 && int(node_id) < tc.a.nodes.len {
		node := tc.a.nodes[int(node_id)]
		if node.kind == .type_decl && (node.typ.starts_with('fn(') || node.typ.starts_with('fn (')) {
			return base
		}
		if node.kind == .type_decl && node.typ.starts_with('[') {
			return '${base}.\nDid you mean `${node.value}`?'
		}
		if node.kind == .field_decl && node.typ.starts_with('[') && node.typ.contains('fn') {
			suggestion := tc.parse_type(node.typ).name().replace_once('fn(', 'fn (')
			return '${base}.\nDid you mean `${suggestion}`?'
		}
	}
	candidates := tc.known_type_name_candidates()
	message := util.new_suggestion(name, candidates).say(base)
	if message != base || int(node_id) < 0 || int(node_id) >= tc.a.nodes.len {
		return message
	}
	unknown_node := tc.a.nodes[int(node_id)]
	if unknown_node.kind in [.interface_field, .param] {
		for index in tc.top_level_idx {
			decl := tc.a.nodes[index]
			if decl.kind != .interface_decl {
				continue
			}
			if tc.node_tree_contains(flat.NodeId(index), node_id, 0) {
				return '${base}.\nDid you mean `${decl.value.all_after_last('.')}`?'
			}
		}
	}
	if unknown_node.kind != .field_decl {
		return message
	}
	// Very short field type names have no useful bigrams for the default Dice
	// matcher. Fall back to a case-insensitive edit distance so `[]abc` beside
	// `struct Aaa` still receives the same useful suggestion as v1.
	mut closest := ''
	mut closest_distance := name.len + 1
	lower_name := name.to_lower()
	for candidate in candidates {
		lower_candidate := candidate.to_lower()
		if lower_name.len == 0 || lower_candidate.len == 0 || lower_name[0] != lower_candidate[0] {
			continue
		}
		distance := strings.levenshtein_distance(lower_name, lower_candidate)
		max_distance := if name.len <= 3 { 2 } else { int_max(1, name.len / 3) }
		if distance <= max_distance && distance < closest_distance {
			closest = candidate
			closest_distance = distance
		}
	}
	if closest.len > 0 {
		return '${base}.\nDid you mean `${closest}`?'
	}
	return message
}

fn (tc &TypeChecker) node_tree_contains(root_id flat.NodeId, target_id flat.NodeId, depth int) bool {
	if root_id == target_id {
		return true
	}
	if depth > 16 || !tc.valid_node_id(root_id) {
		return false
	}
	root := tc.a.nodes[int(root_id)]
	for child_index in 0 .. root.children_count {
		if tc.node_tree_contains(tc.a.child(&root, child_index), target_id, depth + 1) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) known_type_name_candidates() []string {
	mut names := []string{}
	for name, _ in tc.structs {
		push_diagnostic_type_name(mut names, name)
	}
	for name, _ in tc.type_aliases {
		push_diagnostic_type_name(mut names, name)
	}
	for name, _ in tc.sum_types {
		push_diagnostic_type_name(mut names, name)
	}
	for name, _ in tc.enum_names {
		push_diagnostic_type_name(mut names, name)
	}
	for name, _ in tc.interface_names {
		push_diagnostic_type_name(mut names, name)
	}
	for node in tc.a.nodes {
		if node.kind in [.struct_decl, .type_decl, .enum_decl, .interface_decl] {
			push_diagnostic_type_name(mut names, node.value)
		}
	}
	names.sort()
	return names
}

fn push_diagnostic_type_name(mut names []string, name string) {
	display_name := if name.starts_with('main.') {
		name[5..]
	} else if name.starts_with('builtin.') {
		name[8..]
	} else {
		name
	}
	if display_name.len > 0 && display_name !in names {
		names << display_name
	}
}

fn (tc &TypeChecker) type_diagnostic_pos(node_id flat.NodeId, name string) token.Pos {
	if int(node_id) < 0 || int(node_id) >= tc.a.nodes.len {
		return token.Pos{}
	}
	node := tc.a.nodes[int(node_id)]
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	mut type_text := match node.kind {
		.fn_decl, .c_fn_decl, .param, .field_decl, .interface_field, .type_decl {
			node.typ
		}
		.ident {
			node.value
		}
		else {
			''
		}
	}
	if type_text.starts_with('chan ') || type_text.contains('fn(')
		|| type_text.contains('fn (') || !type_text.contains(name) {
		type_text = name
	}
	mut candidates := []string{}
	if type_text.len > 0 {
		candidates << type_text
	}
	if name.len > 0 && name !in candidates {
		candidates << name
	}
	anchor := int_max(0, int_min(node.pos.offset, source.len))
	for candidate in candidates {
		if span := closest_text_span(source, candidate, anchor, node.pos.id) {
			return span
		}
	}
	return node.pos
}

fn closest_text_span(source string, text string, anchor int, file_id int) ?token.Pos {
	if text.len == 0 || source.len < text.len {
		return none
	}
	mut search_from := 0
	mut best_start := -1
	mut best_distance := source.len + text.len
	for search_from <= source.len - text.len {
		relative := source[search_from..].index(text) or { break }
		start := search_from + relative
		distance := if start > anchor { start - anchor } else { anchor - start }
		if distance < best_distance {
			best_start = start
			best_distance = distance
		}
		search_from = start + 1
	}
	if best_start < 0 {
		return none
	}
	return token.new_span(file_id, best_start, best_start + text.len)
}

fn closest_identifier_span(source string, name string, anchor int, file_id int) ?token.Pos {
	if name.len == 0 || source.len < name.len {
		return none
	}
	mut search_from := 0
	mut best_start := -1
	mut best_distance := source.len + name.len
	for search_from <= source.len - name.len {
		relative := source[search_from..].index(name) or { break }
		start := search_from + relative
		left_is_name := start > 0 && (source[start - 1].is_alnum() || source[start - 1] == `_`)
		end := start + name.len
		right_is_name := end < source.len && (source[end].is_alnum() || source[end] == `_`)
		if !left_is_name && !right_is_name {
			distance := if start > anchor { start - anchor } else { anchor - start }
			if distance < best_distance {
				best_start = start
				best_distance = distance
			}
		}
		search_from = start + 1
	}
	if best_start < 0 {
		return none
	}
	return token.new_span(file_id, best_start, best_start + name.len)
}

fn (tc &TypeChecker) selected_main_file_declares_type(name string) bool {
	for file, selected in tc.diagnostic_files {
		if selected && !file.starts_with('generic:')
			&& tc.source_declares_type_in_scope(name, file, 'main') {
			return true
		}
	}
	return false
}

// check_fn_type_string_for_unsupported_generics
// validates helper state for types.
fn (mut tc TypeChecker) check_fn_type_string_for_unsupported_generics(typ string, node_id flat.NodeId, generic_params map[string]bool) {
	params_start := typ.index_u8(`(`) + 1
	mut depth := 1
	mut params_end := params_start
	for params_end < typ.len {
		if typ[params_end] == `(` {
			depth++
		} else if typ[params_end] == `)` {
			depth--
			if depth == 0 {
				break
			}
		}
		params_end++
	}
	if params_end >= typ.len {
		return
	}
	ret := trimmed_space(typ[params_end + 1..])
	tc.check_type_string_for_unsupported_generics(ret, node_id, generic_params)
	for part in split_params(typ[params_start..params_end]) {
		trimmed := trimmed_space(part)
		parts := trimmed.split(' ')
		param_type := if parts.len >= 2 { parts[parts.len - 1] } else { trimmed }
		tc.check_type_string_for_unsupported_generics(param_type, node_id, generic_params)
	}
}

// generic_type_application supports generic type application handling for types.
fn generic_type_application(typ string) bool {
	_, _, ok := generic_type_application_parts(typ)
	return ok
}

fn (tc &TypeChecker) generic_args_are_concrete(args []string) bool {
	for arg in args {
		if tc.type_text_has_generic_placeholder(arg) {
			return false
		}
	}
	return true
}

fn (tc &TypeChecker) type_text_has_generic_placeholder(typ string) bool {
	clean := trimmed_space(typ)
	if is_bare_generic_param(clean) {
		return !tc.is_known_type_text(clean)
	}
	if clean.starts_with('&') {
		return tc.type_text_has_generic_placeholder(clean[1..])
	}
	if clean.starts_with('mut ') {
		return tc.type_text_has_generic_placeholder(clean[4..])
	}
	if clean.starts_with('?') || clean.starts_with('!') {
		return tc.type_text_has_generic_placeholder(clean[1..])
	}
	if clean.starts_with('...') {
		return tc.type_text_has_generic_placeholder(clean[3..])
	}
	if clean.starts_with('[]') {
		return tc.type_text_has_generic_placeholder(clean[2..])
	}
	if clean.starts_with('map[') {
		bracket_end := find_matching_bracket(clean, 3)
		if bracket_end < clean.len {
			return tc.type_text_has_generic_placeholder(clean[4..bracket_end])
				|| tc.type_text_has_generic_placeholder(clean[bracket_end + 1..])
		}
	}
	if clean.starts_with('[') {
		bracket_end := find_matching_bracket(clean, 0)
		if bracket_end < clean.len {
			return tc.type_text_has_generic_placeholder(clean[bracket_end + 1..])
		}
	}
	_, args, ok := generic_type_application_parts(clean)
	if ok {
		for arg in args {
			if tc.type_text_has_generic_placeholder(arg) {
				return true
			}
		}
	}
	if clean.contains('.') && is_bare_generic_param(clean.all_after_last('.')) {
		return !tc.is_known_type_text(clean)
	}
	return false
}

fn (tc &TypeChecker) type_text_has_generic_struct_placeholder_application(typ string) bool {
	clean := trimmed_space(typ)
	if clean.starts_with('&') || clean.starts_with('?') || clean.starts_with('!') {
		return tc.type_text_has_generic_struct_placeholder_application(clean[1..])
	}
	if clean.starts_with('mut ') {
		return tc.type_text_has_generic_struct_placeholder_application(clean[4..])
	}
	if clean.starts_with('...') {
		return tc.type_text_has_generic_struct_placeholder_application(clean[3..])
	}
	if clean.starts_with('[]') {
		return tc.type_text_has_generic_struct_placeholder_application(clean[2..])
	}
	if clean.starts_with('[') {
		close := find_matching_bracket(clean, 0)
		if close > 0 && close + 1 < clean.len {
			return tc.type_text_has_generic_struct_placeholder_application(clean[close + 1..])
		}
		return false
	}
	base, args, is_generic := generic_type_application_parts(clean)
	if !is_generic {
		return false
	}
	qualified := tc.qualify_name(base)
	if (base in tc.struct_generic_params || qualified in tc.struct_generic_params)
		&& args.any(tc.type_text_has_generic_placeholder(it)) {
		return true
	}
	for arg in args {
		if tc.type_text_has_generic_struct_placeholder_application(arg) {
			return true
		}
	}
	return false
}

fn generic_type_application_parts(typ string) (string, []string, bool) {
	if typ.starts_with('[') || !typ.contains('[') {
		return '', []string{}, false
	}
	bracket := typ.index_u8(`[`)
	bracket_end := find_matching_bracket(typ, bracket)
	if bracket <= 0 || bracket_end <= bracket {
		return '', []string{}, false
	}
	inner := trimmed_space(typ[bracket + 1..bracket_end])
	if is_fixed_array_len_text(inner) {
		return '', []string{}, false
	}
	return typ[..bracket], split_params(inner), true
}

// is_fixed_array_len_text reports whether a postfix `Base[inner]` bracket holds a fixed-array
// length rather than a generic type argument. `ArrayFixed.name()` renders the length as a decimal
// (`u8[16]`), a non-decimal literal (`u8[0x10]`), or the source length expression (`u8[segs + 1]`);
// a generic argument is always a type, never a number or arithmetic expression. Recognising all
// three keeps such a postfix name parsing as a fixed array (e.g. when `[]thread T.wait()` recovers
// the spawned return type) instead of a bogus generic application.
fn is_fixed_array_len_text(inner string) bool {
	s := trimmed_space(inner)
	if s.len == 0 {
		return false
	}
	// A fixed-array length is a single integer expression; a comma means the brackets hold a
	// generic argument LIST (`Pair[int, &Node]`), not a length. Without this an `&` (or `-`)
	// that merely leads a later pointer type argument would be read as a length operator.
	if s.contains(',') {
		return false
	}
	if v_int_literal_value(s) != none {
		return true
	}
	for i in 0 .. s.len {
		c := s[i]
		if c in [`+`, `*`, `/`, `%`, `|`, `^`, `<`, `>`] {
			return true
		}
		// A leading `-`/`&` is a negative literal / pointer-type argument; elsewhere they are the
		// subtraction / bitwise-and operators of a length expression.
		if (c == `-` || c == `&`) && i > 0 {
			return true
		}
	}
	return false
}

// is_decimal_int_literal reports whether is decimal int literal applies in types.
fn is_decimal_int_literal(s string) bool {
	if s.len == 0 {
		return false
	}
	for i in 0 .. s.len {
		if s[i] < `0` || s[i] > `9` {
			return false
		}
	}
	return true
}

// v_int_literal_value parses a complete V integer literal — decimal, hex (`0x`), octal
// (`0o`), or binary (`0b`), with optional `_` digit separators — to its value. Returns
// none when `s` is not a whole integer literal (a const name, an expression, etc.), so
// const-length folding accepts `0xF & 6` / `[0b1100 >> 1]int`, not just decimal text.
fn v_int_literal_value(s string) ?int {
	if s.len == 0 {
		return none
	}
	t := s.replace('_', '')
	if t.len == 0 {
		return none
	}
	mut base := 10
	mut digits := t
	if t.len >= 2 && t[0] == `0` {
		c := t[1]
		if c == `x` || c == `X` {
			base = 16
			digits = t[2..]
		} else if c == `o` || c == `O` {
			base = 8
			digits = t[2..]
		} else if c == `b` || c == `B` {
			base = 2
			digits = t[2..]
		}
	}
	if digits.len == 0 {
		return none
	}
	mut value := 0
	for ch in digits {
		mut d := 0
		if ch >= `0` && ch <= `9` {
			d = int(ch - `0`)
		} else if ch >= `a` && ch <= `f` {
			d = int(ch - `a`) + 10
		} else if ch >= `A` && ch <= `F` {
			d = int(ch - `A`) + 10
		} else {
			return none
		}
		if d >= base {
			return none
		}
		value = value * base + d
	}
	return value
}

// is_bare_generic_param reports whether is bare generic param applies in types.
fn is_bare_generic_param(typ string) bool {
	return typ.len == 1 && typ[0] >= `A` && typ[0] <= `Z`
}

fn unresolved_generic_receiver_type(typ Type) bool {
	if typ is Unknown {
		if _ := generic_placeholder_from_unknown(typ) {
			return true
		}
	}
	if typ is Struct {
		return is_bare_generic_param(typ.name)
	}
	return false
}

fn generic_param_index(name string) int {
	return match name {
		'T', 'A', 'K', 'X' { 0 }
		'U', 'B', 'V', 'Y' { 1 }
		'C', 'W', 'Z' { 2 }
		else { 0 }
	}
}

fn generic_placeholder_from_unknown(typ Unknown) ?string {
	start := typ.reason.index_u8(`\``)
	if start < 0 {
		return none
	}
	end := typ.reason[start + 1..].index_u8(`\``)
	if end < 0 {
		return none
	}
	name := typ.reason[start + 1..start + 1 + end]
	if !is_bare_generic_param(name) {
		return none
	}
	return name
}

fn (tc &TypeChecker) resolve_known_field_type(type_name string, fallback Type) Type {
	qname := tc.qualify_name(type_name)
	allow_bare_symbol := qname == type_name
	if qname in tc.structs {
		return Type(Struct{
			name: qname
		})
	}
	if allow_bare_symbol && type_name in tc.structs {
		return Type(Struct{
			name: type_name
		})
	}
	if qname in tc.interface_names {
		return Type(Interface{
			name: qname
		})
	}
	if allow_bare_symbol && type_name in tc.interface_names {
		return Type(Interface{
			name: type_name
		})
	}
	if qname in tc.type_aliases {
		return Type(Alias{
			name:      qname
			base_type: tc.parse_type(tc.type_aliases[qname])
		})
	}
	if allow_bare_symbol && type_name in tc.type_aliases {
		return Type(Alias{
			name:      type_name
			base_type: tc.parse_type(tc.type_aliases[type_name])
		})
	}
	return fallback
}

// type_name_known returns type name known data for TypeChecker.
fn (tc &TypeChecker) type_name_known(typ string) bool {
	if is_builtin_type_name(typ) || typ == 'unknown' || typ.starts_with('C.')
		|| tc.active_generic_param(typ) {
		return true
	}
	generic_base := strip_generic_args_name(typ)
	if generic_base != typ {
		return tc.type_name_known(generic_base)
	}
	qtyp := tc.qualify_name(typ)
	if !typ.contains('.') {
		if resolved := tc.resolve_selective_import_type_symbol(typ) {
			return tc.type_symbol_known(resolved)
		}
	} else if short := tc.imported_type_short_name(typ) {
		if short in tc.type_aliases || short in tc.structs || short in tc.interface_names
			|| short in tc.enum_names || short in tc.sum_types {
			return true
		}
	}
	return qtyp in tc.type_aliases || qtyp in tc.structs || qtyp in tc.interface_names
		|| qtyp in tc.enum_names || qtyp in tc.sum_types
}

fn (tc &TypeChecker) type_name_known_in_current_module(typ string) bool {
	qtyp := tc.qualify_name(typ)
	return qtyp in tc.type_aliases || qtyp in tc.structs || qtyp in tc.interface_names
		|| qtyp in tc.enum_names || qtyp in tc.sum_types
}

// should_check_named_type reports whether should check named type applies in types.
fn should_check_named_type(typ string) bool {
	if typ.len == 0 {
		return false
	}
	for i in 0 .. typ.len {
		c := typ[i]
		if !((c >= `a` && c <= `z`) || (c >= `A` && c <= `Z`)
			|| (c >= `0` && c <= `9`) || c == `_` || c == `.`) {
			return false
		}
	}
	return true
}

fn (tc &TypeChecker) recursive_struct_declaration_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	needle := 'struct ${node.value.all_after_last('.')}'
	start := source.index(needle) or { return node.pos }
	return token.new_span(node.pos.id, start, start + needle.len)
}

// check_struct_field_defaults validates check struct field defaults state for types.
fn (mut tc TypeChecker) check_struct_field_defaults(node_id flat.NodeId, node flat.Node) {
	mut seen_field_names := map[string]bool{}
	for i in 0 .. node.children_count {
		field_id := tc.a.child(&node, i)
		field := tc.a.child_node(&node, i)
		if field.kind != .field_decl {
			continue
		}
		field_type_text := if field.typ.len > 0 { field.typ } else { field.value }
		if bound := fixed_array_bound_text(field_type_text) {
			if bound.starts_with('$') && !bound.starts_with('$d(') {
				tc.record_error_at(.assignment_mismatch,
					'only $d() is supported as fixed array size quantifier at compile time',
					field_id, tc.fixed_array_bound_pos(*field, bound))
			}
		}
		field_type_raw := tc.parse_type(field_type_text)
		field_type := unalias_type(field_type_raw)
		if field_type is OptionType {
			recursive_type := unalias_type(field_type.base_type)
			if recursive_type is Struct
				&& short_type_name(recursive_type.name) == short_type_name(node.value) {
				tc.record_error_at(.unknown_type,
					'recursive struct is only possible with optional pointer (e.g. ?&${node.value.all_after_last('.')})',
					field_id, field.pos)
			}
		}
		is_embed := source_field_decl_is_embed(field, field_type_text)
		if is_embed && field_type is Struct
			&& short_type_name(field_type.name) == short_type_name(node.value) {
			tc.record_error_at(.unknown_type, 'invalid recursive struct `${node.value}`', node_id,
				tc.recursive_struct_declaration_pos(node))
		}
		if field_type_text == 'map' {
			tc.record_error_at(.unknown_type,
				'cannot use the map type without key and value definition', field_id,
				tc.struct_field_type_pos(*field))
		}
		if !is_embed && field.value in seen_field_names {
			tc.record_error_at(.duplicate_decl, 'field name `${field.value}` duplicate', field_id,
				tc.struct_field_declaration_pos(*field))
		} else if !is_embed {
			seen_field_names[field.value] = true
		}
		if !is_embed && node.value != 'C.' && !node.value.starts_with('C.')
			&& tc.should_check_source_name(field_id) && !snake_case_name_is_valid(field.value) {
			tc.check_snake_case_name(field_id, field.value, 'field name',
				tc.struct_field_declaration_pos(*field))
		}
		if field_type is MultiReturn {
			tc.record_error_at(.assignment_mismatch, 'cannot use multi return as field type',
				field_id, tc.struct_field_type_pos(*field))
		}
		if field_type is None {
			tc.record_error_at(.assignment_mismatch, 'cannot use `none` as field type', field_id,
				tc.struct_field_type_pos(*field))
		}
		if is_embed && field_type_raw is Alias && field_type !is Struct && field_type !is Interface {
			if is_anonymous_struct_name(node.value) {
				tc.record_error_at(.assignment_mismatch,
					'cannot embed non-struct `${field_type_text}`', field_id,
					tc.anonymous_struct_type_head_pos(node))
			}
			tc.record_error_at(.assignment_mismatch,
				'`${field_type_text}` (alias of `${field_type.name()}`) is not a struct', field_id,
				tc.struct_field_declaration_pos(*field))
		}
		if !is_embed && field_type_raw is Alias && field_type is Struct && field_type.name.starts_with('C.') && field_type.name in tc.c_typedef_structs && (tc.structs[field_type.name] or {
			[]StructField{}
		}).len == 0 {
			tc.record_error_at(.assignment_mismatch,
				'cannot use opaque C struct `${field_type_text}` as a non-reference struct field; use `&${field_type_text}` instead',
				field_id, tc.struct_field_type_pos(*field))
		}
		if field.children_count > 0
			&& (field.typ.contains('$d(') || tc.source_text_for_node(field_id).contains('$d(')) {
			default_id := tc.a.child(field, 0)
			tc.record_error_at(.assignment_mismatch,
				'cannot initialize a fixed size array field that uses `$d()` as size quantifier since the size may change via -d',
				default_id, tc.a.node(default_id).pos)
		}
		if field_type is ResultType {
			type_pos := tc.struct_field_type_pos(*field)
			tc.record_error_at(.assignment_mismatch,
				'struct field does not support storing Result', field_id, token.new_span(type_pos.id,
				type_pos.offset, type_pos.offset + 1))
		}
		if field.children_count > 0 {
			default_id := tc.a.child(field, 0)
			default := tc.a.node(default_id)
			if tc.type_has_declaration_attribute(field_type_raw, 'nocopy') {
				tc.record_error_at(.assignment_mismatch,
					'cannot copy @[nocopy] struct: use a reference instead', default_id,
					default.pos)
			}
			if source_field_decl_is_mut(*field) && field_type is Map && default.kind == .ident
				&& tc.const_key_for_name(default.value) != none {
				tc.record_error_at(.assignment_mismatch,
					'cannot copy map: call `clone` method (or use a reference)', default_id,
					default.pos)
			}
			if default.kind == .int_literal && default.value == '0' && field_type.is_integer() {
				tc.record_warning_at(.assignment_mismatch,
					'unnecessary default value of `0`: struct fields are zeroed by default',
					default_id, default.pos)
			} else if default.kind == .string_literal && default.value.len == 0
				&& field_type is String {
				tc.record_warning_at(.assignment_mismatch,
					"unnecessary default value of '': struct fields are zeroed by default",
					default_id, default.pos)
			} else if default.kind == .bool_literal && default.value == 'false'
				&& field_type.name() == 'bool' {
				tc.record_warning_at(.assignment_mismatch,
					'unnecessary default value `false`: struct fields are zeroed by default',
					default_id, default.pos)
			}
		}
		if field.children_count == 0 && field_type is FnType && !tc.translated_files[tc.cur_file]
			&& !struct_field_has_attr(*field, 'required') {
			tc.record_notice_at(.assignment_mismatch,
				'uninitialized `fn` struct fields are not allowed, since they can result in segfaults; use `?fn` or `@[required]` or initialize the field with `=` (if you absolutely want to have unsafe function pointers, use `= unsafe { nil }`)',
				field_id, tc.struct_field_declaration_pos(*field))
		}
	}
	for i in 0 .. node.children_count {
		field := tc.a.child_node(&node, i)
		if field.kind != .field_decl || field.children_count == 0
			|| unalias_type(tc.parse_type(field.typ)) !is OptionType {
			continue
		}
		default_id := tc.a.child(field, 0)
		if tc.a.node(default_id).kind == .none_expr {
			tc.record_warning_at(.assignment_mismatch,
				'unnecessary default value of `none`: struct fields are zeroed by default',
				default_id, tc.a.node(default_id).pos)
		}
	}
	for i in 0 .. node.children_count {
		field := tc.a.child_node(&node, i)
		if field.kind != .field_decl || field.children_count == 0
			|| unalias_type(tc.parse_type(field.typ)) !is OptionType {
			continue
		}
		default_id := tc.a.child(field, 0)
		if tc.a.node(default_id).kind == .nil_literal {
			tc.record_error_at(.assignment_mismatch, '`nil` is only allowed in `unsafe` code',
				default_id, tc.a.node(default_id).pos)
		}
	}
	for i in 0 .. node.children_count {
		field := tc.a.child_node(&node, i)
		if field.kind != .field_decl || field.children_count == 0 {
			continue
		}
		default_id := tc.a.child(field, 0)
		if tc.a.node(default_id).kind == .nil_literal || tc.expr_is_unsafe_nil(default_id) {
			expected := unalias_type(tc.parse_type(field.typ))
			if expected is OptionType && unalias_type(expected.base_type) is Pointer {
				tc.record_error_at(.assignment_mismatch, 'cannot assign `nil` to option value',
					default_id, tc.array_element_diagnostic_pos(default_id))
			} else if expected !is Pointer && expected !is FnType {
				tc.record_error_at(.assignment_mismatch,
					'cannot assign `nil` to a non-pointer field', default_id,
					tc.struct_field_type_pos(*field))
			}
		}
	}
	for i in 0 .. node.children_count {
		field := tc.a.child_node(&node, i)
		if field.kind != .field_decl || field.children_count == 0 {
			continue
		}
		default_id := tc.a.child(field, 0)
		field_type := if field.typ.len > 0 { field.typ } else { field.value }
		expected := tc.parse_type(field_type)
		clean_expected := unalias_type(expected)
		default_node := tc.a.nodes[int(default_id)]
		if (default_node.kind == .nil_literal || tc.expr_is_unsafe_nil(default_id))
			&& clean_expected !is Pointer {
			continue
		}
		if clean_expected is OptionType && (default_node.kind in [.none_expr, .nil_literal]
			|| tc.expr_is_unsafe_nil(default_id)) {
			continue
		}
		if clean_expected is Struct
			&& clean_expected.name.all_after_last('.') == node.value.all_after_last('.') {
			tc.record_error_at(.assignment_mismatch,
				'field `${field.value}` is part of `${node.value}`, they can not both have the same type', tc.a.child(&node,
				i), tc.struct_field_type_pos(field))
			continue
		}
		if clean_expected is Array {
			elem_type := unalias_type(clean_expected.elem_type)
			if elem_type is Struct
				&& elem_type.name.all_after_last('.') == node.value.all_after_last('.') {
				type_pos := tc.struct_field_type_pos(field)
				tc.record_error_at(.assignment_mismatch,
					'cannot initialize array of same struct type that is being defined (recursion detected)', tc.a.child(&node,
					i), token.new_span(field.pos.id, field.pos.offset, type_pos.end))
				continue
			}
		}
		tc.check_node(default_id)
		actual := tc.resolve_expr(default_id, expected)
		if type_is_unsigned_integer(expected) && tc.expr_is_negative_integer_literal(default_id) {
			tc.record_error_at(.assignment_mismatch,
				'cannot assign negative value to unsigned integer type', default_id,
				default_node.pos)
		}
		if clean_expected !is Pointer && unalias_type(actual) is Pointer {
			diagnostic_pos := if default_node.kind == .call && default_node.children_count > 0 {
				callee := tc.a.child_node(default_node, 0)
				if callee.kind == .selector {
					tc.method_call_name_pos(default_node, callee)
				} else {
					default_node.pos
				}
			} else {
				default_node.pos
			}
			tc.record_error_at(.assignment_mismatch,
				'field is not reference but default value is reference', default_id, diagnostic_pos)
			continue
		}
		if expected.name() == 'voidptr' && unalias_type(actual).is_integer() {
			if tc.should_diagnose(default_id) {
				source_value := tc.source_text_for_node(default_id)
				tc.record_notice_at(.assignment_mismatch,
					'voidptr variables may only be assigned voidptr values (e.g. unsafe { voidptr(${source_value}) })',
					default_id, default_node.pos)
			}
			continue
		}
		if clean_expected is Pointer && unalias_type(actual) !is Pointer
			&& default_node.kind in [.ident, .selector, .struct_init] {
			tc.record_error_at(.assignment_mismatch,
				'reference field must be initialized with reference', default_id, default_node.pos)
			continue
		}
		unknown_struct_init := default_node.kind == .struct_init && default_node.value != 'struct'
			&& !tc.type_name_known(default_node.value)
		if unknown_struct_init || (!tc.expr_compatible(default_id, actual, expected)
			&& !tc.pointer_value_compatible(actual, expected)) {
			if unalias_type(actual) is OptionType && clean_expected !is OptionType {
				continue
			}
			actual_name := if unknown_struct_init { 'void' } else { actual.name() }
			tc.type_mismatch(.assignment_mismatch,
				'incompatible initializer for field `${field.value}`: expected `${field_type}`, not `${actual_name}`',
				default_id)
		}
	}
}

fn (tc &TypeChecker) struct_field_type_pos(field flat.Node) token.Pos {
	if !field.pos.is_valid() || field.typ.len == 0 {
		return field.pos
	}
	file := tc.a.source_files[field.pos.id] or { return field.pos }
	source := tc.source_texts_by_file[file.name] or { return field.pos }
	start := int_max(0, int_min(field.pos.offset, source.len))
	end := int_max(start, int_min(field.pos.end, source.len))
	if start >= end {
		return field.pos
	}
	relative := source[start..end].index(field.typ) or { return field.pos }
	type_start := start + relative
	return token.new_span(field.pos.id, type_start, type_start + field.typ.len)
}

fn (tc &TypeChecker) struct_field_declaration_pos(field flat.Node) token.Pos {
	file := tc.a.source_files[field.pos.id] or { return field.pos }
	source := tc.source_texts_by_file[file.name] or { return field.pos }
	offset := int_min(int_max(field.pos.offset, 0), source.len)
	line_start := if offset > 0 {
		if relative := source[..offset].last_index('\n') { relative + 1 } else { 0 }
	} else {
		0
	}
	line_end := source.index_after('\n', line_start) or { source.len }
	line := source[line_start..line_end].trim_right('\r\n')
	if relative := line.index(field.value) {
		start := line_start + relative
		return token.new_span(field.pos.id, start, line_start + line.len)
	}
	return field.pos
}

fn (tc &TypeChecker) anonymous_struct_type_head_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_min(int_max(node.pos.offset, 0), source.len)
	end := int_min(int_max(node.pos.end, start), source.len)
	if relative := source[start..end].index('{') {
		return token.new_span(node.pos.id, start, start + relative + 1)
	}
	return node.pos
}

// check_enum_backing_type validates explicit enum backing storage types.
fn (mut tc TypeChecker) check_enum_backing_type(node_id flat.NodeId, node flat.Node) {
	if node.kind != .enum_decl || node.generic_params().len == 0 {
		return
	}
	backing := node.generic_params()[0].trim_space()
	if backing.len == 0 {
		return
	}
	backing_type := tc.parse_type(backing)
	if backing_type is Unknown || type_contains_unknown(backing_type) {
		tc.record_error(.unknown_type, 'unknown type `${backing}`', node_id)
		return
	}
	clean := unalias_type(backing_type)
	valid_backing := backing in ['i8', 'i16', 'i32', 'int', 'i64', 'u8', 'u16', 'u32', 'u64']
	if !valid_backing {
		tc.record_error_at(.assignment_mismatch,
			'`${backing}` is not one of `i8`,`i16`,`i32`,`int`,`i64`,`u8`,`u16`,`u32`,`u64`',
			node_id, tc.enum_backing_type_diagnostic_pos(node_id, backing))
		tc.check_backed_enum_field_value_ranges(node, backing, EnumBackingValueBounds{
			min:     0
			max:     0
			has_min: true
			has_max: true
		})
		return
	}
	if bounds := enum_backing_value_bounds(clean) {
		tc.check_backed_enum_field_value_ranges(node, backing, bounds)
	}
}

fn (tc &TypeChecker) enum_backing_type_diagnostic_pos(node_id flat.NodeId, backing string) token.Pos {
	name_pos := tc.node_value_diagnostic_pos(node_id)
	file := tc.a.source_files[name_pos.id] or { return name_pos }
	source := tc.source_texts_by_file[file.name] or { return name_pos }
	mut line_start := name_pos.offset
	for line_start > 0 && source[line_start - 1] != `\n` {
		line_start--
	}
	mut line_end := name_pos.end
	for line_end < source.len && source[line_end] != `\n` {
		line_end++
	}
	line := source[line_start..line_end]
	needle := 'as ${backing}'
	relative := line.index(needle) or { return name_pos }
	start := line_start + relative + 3
	return token.new_span(name_pos.id, start, start + backing.len)
}

struct EnumBackingValueBounds {
	min         int
	max         int
	has_min     bool
	has_max     bool
	bits        int
	is_unsigned bool
}

fn enum_backing_value_bounds(typ Type) ?EnumBackingValueBounds {
	clean := unalias_type(typ)
	if clean is Primitive {
		if !clean.props.has(.integer) {
			return none
		}
		bits := match clean.size {
			8 { 8 }
			16 { 16 }
			32 { 32 }
			64 { 64 }
			else { 32 }
		}

		if clean.props.has(.unsigned) {
			return match clean.size {
				8 {
					EnumBackingValueBounds{
						min:         0
						max:         255
						has_min:     true
						has_max:     true
						bits:        bits
						is_unsigned: true
					}
				}
				16 {
					EnumBackingValueBounds{
						min:         0
						max:         65535
						has_min:     true
						has_max:     true
						bits:        bits
						is_unsigned: true
					}
				}
				else {
					EnumBackingValueBounds{
						min:         0
						has_min:     true
						bits:        bits
						is_unsigned: true
					}
				}
			}
		}
		return match clean.size {
			8 {
				EnumBackingValueBounds{
					min:     -128
					max:     127
					has_min: true
					has_max: true
					bits:    bits
				}
			}
			16 {
				EnumBackingValueBounds{
					min:     -32768
					max:     32767
					has_min: true
					has_max: true
					bits:    bits
				}
			}
			32, 0 {
				EnumBackingValueBounds{
					min:     -2147483647 - 1
					max:     2147483647
					has_min: true
					has_max: true
					bits:    bits
				}
			}
			else {
				EnumBackingValueBounds{
					bits: bits
				}
			}
		}
	}
	if clean is Rune {
		return EnumBackingValueBounds{
			min:     -2147483647 - 1
			max:     2147483647
			has_min: true
			has_max: true
			bits:    32
		}
	}
	if clean is USize {
		return EnumBackingValueBounds{
			min:         0
			has_min:     true
			bits:        64
			is_unsigned: true
		}
	}
	if clean is ISize {
		return EnumBackingValueBounds{
			bits: 64
		}
	}
	return none
}

fn (mut tc TypeChecker) check_backed_enum_field_value_ranges(node flat.Node, backing string, bounds EnumBackingValueBounds) {
	is_flag := node.typ == 'flag'
	mut field_values := map[string]int{}
	mut field_exprs := map[string]flat.NodeId{}
	mut field_ids := []flat.NodeId{cap: int(node.children_count)}
	for i in 0 .. node.children_count {
		field_id := tc.a.child(&node, i)
		field := tc.a.nodes[int(field_id)]
		if field.kind != .enum_field {
			continue
		}
		field_ids << field_id
		if field.children_count > 0 {
			field_exprs[field.value] = tc.a.child(&field, 0)
		}
	}
	mut next_val := 0
	mut has_previous := false
	mut previous_is_max := false
	for field_id in field_ids {
		field := tc.a.nodes[int(field_id)]
		if !is_flag && field.children_count == 0 {
			val := if has_previous { next_val } else { 0 }
			if previous_is_max {
				tc.record_error_at(.assignment_mismatch,
					'enum value overflows type `${backing}`, which has a maximum value of ${enum_backing_max_text(bounds)}',
					field_id, field.pos)
			}
			has_previous = true
			previous_is_max = enum_backing_int_is_max(val, bounds)
			next_val = val + 1
			continue
		}
		mut val := next_val
		mut has_checked_value := true
		if expr_id := field_exprs[field.value] {
			if !is_flag {
				if literal := tc.integer_literal_source(expr_id) {
					clean_literal := literal.replace('_', '')
					if enum_backing_literal_overflows(clean_literal, bounds) {
						tc.record_error_at(.assignment_mismatch,
							'enum value `${clean_literal}` overflows the enum type `${backing}`, values of which have to be in [${enum_backing_min_text(bounds)}, ${enum_backing_max_text(bounds)}]',
							expr_id, tc.a.nodes[int(expr_id)].pos)
					}
					previous_is_max = enum_backing_literal_becomes_max(clean_literal, bounds)
				} else {
					expr_type := tc.resolve_type(expr_id)
					if expr_type !is Unknown && !expr_type.is_integer() {
						tc.record_error_at(.assignment_mismatch,
							'the default value for an enum has to be an integer', expr_id,
							tc.a.nodes[int(expr_id)].pos)
					}
				}
			}
			mut resolving := map[string]bool{}
			if resolved := tc.comptime_static_enum_field_value(expr_id, tc.cur_module, node.value, mut
				field_values, field_exprs, mut resolving)
			{
				val = resolved
			} else {
				has_checked_value = false
			}
		}
		field_values[field.value] = val
		if is_flag && has_checked_value && !enum_backing_value_fits(val, bounds, true) {
			if is_flag {
				tc.record_error(.assignment_mismatch,
					'enum field `${field.value}` bit ${val} does not fit backing type `${backing}`',
					field_id)
			}
		}
		if !is_flag && has_checked_value && field.children_count > 0
			&& tc.integer_literal_source(tc.a.child(&field, 0)) == none {
			if !enum_backing_value_fits(val, bounds, false) {
				expr_id := tc.a.child(&field, 0)
				tc.record_error_at(.assignment_mismatch,
					'enum value `${val}` overflows the enum type `${backing}`, values of which have to be in [${enum_backing_min_text(bounds)}, ${enum_backing_max_text(bounds)}]',
					expr_id, tc.a.nodes[int(expr_id)].pos)
			}
			previous_is_max = enum_backing_int_is_max(val, bounds)
		}
		has_previous = has_checked_value
		next_val = val + 1
	}
}

fn enum_backing_min_text(bounds EnumBackingValueBounds) string {
	if bounds.is_unsigned {
		return '0'
	}
	return match bounds.bits {
		8 { '-128' }
		16 { '-32768' }
		32 { '-2147483648' }
		64 { '-9223372036854775808' }
		else { bounds.min.str() }
	}
}

fn enum_backing_max_text(bounds EnumBackingValueBounds) string {
	if bounds.is_unsigned {
		return match bounds.bits {
			8 { '255' }
			16 { '65535' }
			32 { '4294967295' }
			64 { '18446744073709551615' }
			else { bounds.max.str() }
		}
	}
	return match bounds.bits {
		8 { '127' }
		16 { '32767' }
		32 { '2147483647' }
		64 { '9223372036854775807' }
		else { bounds.max.str() }
	}
}

fn enum_backing_literal_overflows(literal string, bounds EnumBackingValueBounds) bool {
	if literal.len == 0 {
		return false
	}
	is_negative := literal[0] == `-`
	mut magnitude := literal
	if literal[0] == `-` || literal[0] == `+` {
		magnitude = literal[1..]
	}
	if magnitude.len == 0 {
		return false
	}
	value, parse_error := strconv.common_parse_uint2(magnitude, 0, 64)
	if parse_error == -3 {
		return true
	}
	if parse_error != 0 {
		return false
	}
	if bounds.is_unsigned {
		if is_negative {
			return true
		}
		maximum := enum_backing_unsigned_max(bounds.bits)
		return value > maximum
	}
	minimum_magnitude := if bounds.bits >= 64 {
		u64(1) << 63
	} else if bounds.bits > 0 {
		u64(1) << (bounds.bits - 1)
	} else {
		u64(0)
	}
	maximum := if bounds.bits >= 64 {
		u64(max_i64)
	} else if bounds.bits > 0 {
		(u64(1) << (bounds.bits - 1)) - 1
	} else {
		u64(0)
	}
	if is_negative {
		return value > minimum_magnitude
	}
	// v1 historically rejects the signed maximum when it is written explicitly.
	return value >= maximum
}

fn enum_backing_literal_becomes_max(literal string, bounds EnumBackingValueBounds) bool {
	if literal.len == 0 || literal[0] == `-` {
		return false
	}
	mut magnitude := literal
	if literal[0] == `+` {
		magnitude = literal[1..]
	}
	value, parse_error := strconv.common_parse_uint2(magnitude, 0, 64)
	if bounds.is_unsigned {
		return parse_error == 0 && value == enum_backing_unsigned_max(bounds.bits)
	}
	maximum := if bounds.bits >= 64 {
		u64(max_i64)
	} else if bounds.bits > 0 {
		(u64(1) << (bounds.bits - 1)) - 1
	} else {
		u64(0)
	}
	if parse_error == 0 && value == maximum {
		return true
	}
	return bounds.bits == 64 && (parse_error == -3 || (parse_error == 0 && value > maximum))
}

fn enum_backing_unsigned_max(bits int) u64 {
	if bits >= 64 {
		return max_u64
	}
	if bits <= 0 {
		return 0
	}
	return (u64(1) << bits) - 1
}

fn enum_backing_int_is_max(value int, bounds EnumBackingValueBounds) bool {
	return bounds.has_max && value == bounds.max
}

fn enum_backing_value_fits(value int, bounds EnumBackingValueBounds, is_flag bool) bool {
	if is_flag {
		if value < 0 || bounds.bits <= 0 {
			return false
		}
		limit := if bounds.has_min && bounds.min < 0 { bounds.bits - 1 } else { bounds.bits }
		return value < limit
	}
	if bounds.has_min && value < bounds.min {
		return false
	}
	if bounds.has_max && value > bounds.max {
		return false
	}
	return true
}

// check_enum_field_values validates check enum field values state for types.
fn (mut tc TypeChecker) check_enum_field_values(node_id flat.NodeId, node flat.Node) {
	mut enum_field_count := 0
	for i in 0 .. node.children_count {
		if tc.a.child_node(&node, i).kind == .enum_field {
			enum_field_count++
		}
	}
	if enum_field_count == 0 {
		tc.record_error_at(.assignment_mismatch, 'enum cannot be empty', node_id,
			tc.enum_declaration_diagnostic_pos(node_id))
	}
	if node.value.len == 1 && node.value[0] >= `A` && node.value[0] <= `Z` {
		tc.record_error_at(.duplicate_decl,
			'single letter capital names are reserved for generic template types.', node_id,
			tc.node_value_diagnostic_pos(node_id))
	}
	if tc.type_declaration_exists_before(node_id, node.value) {
		tc.record_error_at(.duplicate_decl,
			'cannot register enum `${node.value}`, another type with this name exists', node_id,
			tc.enum_declaration_diagnostic_pos(node_id))
	}
	allow_multiple := tc.declaration_has_attribute(node_id, '_allow_multiple_values')
		|| tc.translated_files[tc.cur_file]
	mut field_exprs := map[string]flat.NodeId{}
	for i in 0 .. node.children_count {
		field := tc.a.child_node(&node, i)
		if field.kind == .enum_field && field.children_count > 0 && field.value !in field_exprs {
			field_exprs[field.value] = tc.a.child(field, 0)
		}
	}
	mut seen_names := map[string]bool{}
	mut seen_values := map[int]bool{}
	mut field_values := map[string]int{}
	mut next_value := 0
	for i in 0 .. node.children_count {
		field_id := tc.a.child(&node, i)
		field := tc.a.child_node(&node, i)
		if field.kind != .enum_field {
			continue
		}
		if tc.should_check_source_name(field_id) && !snake_case_name_is_valid(field.value) {
			tc.check_snake_case_name(field_id, field.value, 'field name',
				tc.source_line_declaration_pos(field_id))
		}
		duplicate_name := seen_names[field.value]
		if duplicate_name {
			mut duplicate_pos := field.pos
			if field.children_count > 0 {
				duplicate_pos = token.new_span(field.pos.id, field.pos.offset, field.pos.offset + 1)
			}
			tc.record_error_at(.duplicate_decl, 'duplicate enum field name `${field.value}`',
				field_id, duplicate_pos)
		}
		seen_names[field.value] = true
		mut value := next_value
		mut value_known := true
		mut value_overflows_backing := false
		mut value_pos := field.pos
		if field.children_count > 0 {
			value_id := tc.a.child(field, 0)
			value_pos = tc.a.node(value_id).pos
			if referenced := tc.find_enum_value_in_node(value_id, node.value) {
				if referenced != field.value && !seen_names[referenced] {
					tc.record_error_at(.unknown_ident,
						'`${node.value}.${referenced}` should be declared before using it',
						value_id, value_pos)
					continue
				}
			}
			if node.generic_params().len > 0 {
				if bounds := enum_backing_value_bounds(tc.parse_type(node.generic_params()[0])) {
					if literal := tc.integer_literal_source(value_id) {
						value_overflows_backing = enum_backing_literal_overflows(literal.replace('_', ''),
							bounds)
					}
				}
			}
			tc.check_node(value_id)
			value_node := tc.a.node(value_id)
			if value_node.kind == .enum_val {
				if duplicate_name {
					continue
				}
				if value_node.value == field.value {
					if !allow_multiple {
						tc.record_error_with_details_at(.duplicate_decl,
							'enum value `${field.value}` is not allowed to reference itself',
							field_id, value_pos, [
							'use `@[_allow_multiple_values]` attribute to allow multiple enum values. Use only when needed',
						])
					}
					continue
				}
				if !seen_names[value_node.value] {
					tc.record_error_at(.unknown_ident,
						'`${node.value}.${value_node.value}` should be declared before using it',
						field_id, value_pos)
					continue
				}
			}
			value_type := tc.resolve_type(value_id)
			if value_type is Unknown {
				value_known = false
			} else if !value_type.is_integer() {
				if node.generic_params().len == 0 {
					tc.record_error_at(.assignment_mismatch,
						'the default value for an enum has to be an integer', value_id, value_pos)
				}
				value_known = false
			}
			mut resolving := map[string]bool{}
			value = tc.comptime_static_enum_field_value(value_id, tc.cur_module, node.value, mut
				field_values, field_exprs, mut resolving) or {
				if tc.node_contains_runtime_call(value_id) {
					tc.record_error_at(.assignment_mismatch,
						'the default value for an enum has to be an integer', value_id, value_pos)
				}
				value_known = false
				value
			}
		}
		if value_known && !value_overflows_backing && seen_values[value] && !allow_multiple {
			detail := if field.children_count > 0
				&& tc.a.node(tc.a.child(field, 0)).kind == .enum_val {
				'use `@[_allow_multiple_values]` attribute to allow multiple enum values. Use only when needed'
			} else {
				'use `@[_allow_multiple_values]` attribute to allow multiple enum values. Use only when it is needed'
			}
			tc.record_error_with_details_at(.duplicate_decl,
				'enum value `${value}` already exists', field_id, value_pos, [
				detail,
			])
		}
		if value_known {
			seen_values[value] = true
			field_values[field.value] = value
			next_value = value + 1
		}
	}
}

fn (tc &TypeChecker) find_enum_value_in_node(id flat.NodeId, enum_name string) ?string {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .enum_val {
		return node.value
	}
	if node.kind == .selector && node.children_count > 0 {
		base := tc.a.child_node(&node, 0)
		if base.kind == .ident && (base.value == enum_name || base.value.ends_with('.${enum_name}')) {
			return node.value
		}
	}
	for i in 0 .. node.children_count {
		if found := tc.find_enum_value_in_node(tc.a.child(&node, i), enum_name) {
			return found
		}
	}
	return none
}

fn (tc &TypeChecker) node_contains_runtime_call(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .call {
		return true
	}
	for i in 0 .. node.children_count {
		if tc.node_contains_runtime_call(tc.a.child(&node, i)) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) declaration_has_attribute(node_id flat.NodeId, name string) bool {
	marker := '@attributes:${int(node_id)}'
	for node in tc.a.nodes {
		if node.kind != .directive || node.value != marker {
			continue
		}
		for raw in node.generic_params() {
			if raw.all_before(':').trim_space() == name {
				return true
			}
		}
		return false
	}
	return false
}

fn (tc &TypeChecker) type_has_declaration_attribute(typ Type, name string) bool {
	clean := unalias_type(unwrap_pointer(typ))
	type_name := clean.name()
	if type_name.len == 0 {
		return false
	}
	for index in tc.top_level_idx {
		node := tc.a.node(flat.NodeId(index))
		if node.kind !in [.struct_decl, .type_decl] {
			continue
		}
		if node.value != type_name
			&& node.value.all_after_last('.') != type_name.all_after_last('.') {
			continue
		}
		if tc.declaration_has_attribute(flat.NodeId(index), name) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) non_heap_pointer_param_struct(name string) ?string {
	type_text := tc.current_fn_param_type_text(name) or { return none }
	if !type_text.trim_space().starts_with('&') {
		return none
	}
	param_type := tc.parse_type(type_text)
	clean := unalias_type(unwrap_pointer(param_type))
	if clean !is Struct {
		return none
	}
	struct_type := clean as Struct
	if tc.type_has_declaration_attribute(Type(struct_type), 'heap') {
		return none
	}
	return struct_type.name.all_after_last('.')
}

fn (mut tc TypeChecker) record_non_heap_pointer_param_escape(id flat.NodeId) bool {
	if tc.unsafe_depth > 0 || !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind != .ident {
		return false
	}
	struct_name := tc.non_heap_pointer_param_struct(node.value) or { return false }
	tc.record_error_at(.assignment_mismatch,
		'`${node.value}` cannot be assigned outside `unsafe` blocks as it might refer to an object stored on stack. Consider declaring `${struct_name}` as `@[heap]`.',
		id, node.pos)
	return true
}

fn (tc &TypeChecker) current_file_module_has_attribute(name string) bool {
	mut file_name := ''
	for index in tc.top_level_idx {
		node := tc.a.node(flat.NodeId(index))
		if node.kind == .file {
			file_name = node.value
			continue
		}
		if node.kind == .module_decl && file_name == tc.cur_file
			&& tc.declaration_has_attribute(flat.NodeId(index), name) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) type_declaration_exists_before(node_id flat.NodeId, name string) bool {
	current_name := qualify_decl_name_in_module(name, tc.cur_module)
	mut module_name := ''
	for idx in tc.top_level_idx {
		if idx >= int(node_id) {
			break
		}
		candidate := tc.a.nodes[idx]
		if candidate.kind == .file {
			module_name = ''
			continue
		}
		if candidate.kind == .module_decl {
			module_name = candidate.value
			continue
		}
		if candidate.kind in [.struct_decl, .type_decl, .interface_decl, .enum_decl]
			&& qualify_decl_name_in_module(candidate.value, module_name) == current_name {
			return true
		}
	}
	return false
}

fn qualify_decl_name_in_module(name string, module_name string) string {
	if module_name.len == 0 || module_name == 'main' || module_name == 'builtin'
		|| name.starts_with('${module_name}.') {
		return name
	}
	return '${module_name}.${name}'
}

fn (tc &TypeChecker) enum_declaration_diagnostic_pos(node_id flat.NodeId) token.Pos {
	name_pos := tc.node_value_diagnostic_pos(node_id)
	file := tc.a.source_files[name_pos.id] or { return name_pos }
	source := tc.source_texts_by_file[file.name] or { return name_pos }
	mut line_start := name_pos.offset
	for line_start > 0 && source[line_start - 1] != `\n` {
		line_start--
	}
	prefix := source[line_start..name_pos.offset]
	enum_relative := prefix.last_index('enum ') or { return name_pos }
	mut start := line_start + enum_relative
	if prefix[..enum_relative].trim_space() == 'pub' {
		if pub_relative := prefix.index('pub') {
			start = line_start + pub_relative
		}
	}
	return token.new_span(name_pos.id, start, name_pos.end)
}

// check_const_field_values validates check const field values state for types.
fn (mut tc TypeChecker) check_const_field_values(node flat.Node) {
	for i in 0 .. node.children_count {
		field_id := tc.a.child(&node, i)
		field := tc.a.node(field_id)
		if field.kind != .const_field || field.children_count == 0 {
			continue
		}
		qname := tc.qualify_name(field.value)
		if reserved_const_type_name(field.value) {
			tc.record_error_at(.duplicate_decl,
				'invalid use of reserved type `${field.value}` as a const name', field_id,
				field.pos)
		}
		if tc.checked_const_names[qname] {
			tc.record_error_at(.duplicate_decl, 'duplicate const `${field.value}`', field_id,
				tc.node_value_diagnostic_pos(field_id))
		} else {
			tc.checked_const_names[qname] = true
		}
		if field.value == tc.cur_module && tc.cur_module !in ['', 'main'] {
			tc.record_error_at(.duplicate_decl, 'duplicate of a module name `${qname}`', field_id,
				tc.node_value_diagnostic_pos(field_id))
		}
		if field.value == '_' {
			tc.record_error_at(.duplicate_decl, 'cannot use `_` as a const name', field_id,
				tc.node_value_diagnostic_pos(field_id))
		} else if !field.value.starts_with('C.') && field.value != field.value.to_lower() {
			tc.record_error_at(.duplicate_decl,
				'const names cannot contain uppercase letters, use snake_case instead', field_id,
				tc.node_value_diagnostic_pos(field_id))
		}
		if tc.has_active_import(field.value) {
			tc.record_error_at(.duplicate_decl,
				'const `${field.value}` conflicts with imported module `${field.value}`', field_id,
				tc.node_value_diagnostic_pos(field_id))
		}
		expr_id := tc.a.child(field, 0)
		if cycle_id := tc.find_ident_in_node(expr_id, field.value) {
			tc.const_types[qname] = Type(void_)
			tc.record_error(.unknown_ident, 'cycle in constant `${field.value}`', cycle_id)
		}
		tc.check_node(expr_id)
		if tc.resolve_type(expr_id) is MultiReturn {
			tc.record_error_at(.assignment_mismatch,
				'const declarations do not support multiple return values yet', expr_id,
				tc.a.nodes[int(expr_id)].pos)
		}
		if field.typ.len == 0 && tc.resolve_type(expr_id).name() == 'int'
			&& tc.implicit_int_literal_overflows(expr_id) {
			tc.record_error_at(.assignment_mismatch,
				'overflow in implicit type `int`, use explicit type casting instead', expr_id,
				tc.a.nodes[int(expr_id)].pos)
		}
	}
}

fn (mut tc TypeChecker) check_const_global_initializers(node flat.Node) {
	for i in 0 .. node.children_count {
		field_id := tc.a.child(&node, i)
		field := tc.a.node(field_id)
		if field.kind != .field_decl || 'const' !in field.generic_params() {
			continue
		}
		if field.children_count == 0 {
			tc.record_error_severity_at(.compile_error,
				'const globals must have an explicit initializer', field_id,
				tc.node_value_diagnostic_pos(field_id), 'cgen error:')
			continue
		}
		expr_id := tc.a.child(field, 0)
		tc.check_node(expr_id)
		if !tc.global_const_expr_is_c_constant(expr_id) {
			tc.record_error_severity_at(.compile_error,
				'const global `${field.value}` must be initialized with a C constant expression',
				field_id, tc.node_value_diagnostic_pos(field_id), 'cgen error:')
		}
	}
}

fn (tc &TypeChecker) global_const_expr_is_c_constant(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind in [.string_literal, .int_literal, .float_literal, .bool_literal, .char_literal,
		.enum_val] {
		return true
	}
	if node.kind == .ident {
		return true
	}
	if node.kind in [.paren, .cast_expr, .prefix] {
		return node.children_count > 0 && tc.global_const_expr_is_c_constant(tc.a.child(node, 0))
	}
	if node.kind in [.infix, .array_literal, .array_init, .struct_init] {
		for i in 0 .. node.children_count {
			child_id := tc.a.child(node, i)
			child := tc.a.node(child_id)
			value_id := if child.kind == .field_init && child.children_count > 0 {
				tc.a.child(child, 0)
			} else {
				child_id
			}
			if !tc.global_const_expr_is_c_constant(value_id) {
				return false
			}
		}
		return true
	}
	return false
}

fn reserved_const_type_name(name string) bool {
	return name in [
		'bool',
		'char',
		'i8',
		'i16',
		'i32',
		'int',
		'i64',
		'u8',
		'u16',
		'u32',
		'u64',
		'f32',
		'f64',
		'map',
		'string',
		'rune',
		'usize',
		'isize',
		'voidptr',
		'thread',
	]
}

fn (tc &TypeChecker) find_ident_in_node(id flat.NodeId, name string) ?flat.NodeId {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .ident && node.value == name {
		return id
	}
	for i in 0 .. node.children_count {
		if found := tc.find_ident_in_node(tc.a.child(&node, i), name) {
			return found
		}
	}
	return none
}

// fn_body_definitely_returns supports fn body definitely returns handling for TypeChecker.
pub fn (tc &TypeChecker) fn_body_definitely_returns(node flat.Node) bool {
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.child_node(&node, i)
		if child.kind == .param {
			continue
		}
		if tc.stmt_definitely_returns(child_id) {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) check_noreturn_fn_semantics(id flat.NodeId, node flat.Node, qname string) {
	if node.value !in tc.a.noreturn_fns && qname !in tc.a.noreturn_fns {
		return
	}
	mut tail_id := flat.NodeId(-1)
	mut has_return := false
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind == .param {
			continue
		}
		tail_id = child_id
		if tc.subtree_contains_return(child_id) {
			has_return = true
		}
	}
	if has_return {
		tc.record_error_at(.return_mismatch, '[noreturn] functions cannot use return statements',
			id, tc.fn_declaration_diagnostic_pos(node))
	}
	valid_tail := tc.valid_node_id(tail_id) && tc.stmt_definitely_returns(tail_id)
		&& !tc.subtree_contains_return(tail_id)
	if valid_tail {
		return
	}
	pos := if tc.valid_node_id(tail_id) {
		tc.noreturn_invalid_tail_pos(tail_id)
	} else {
		tc.fn_declaration_diagnostic_pos(node)
	}
	tc.record_error_at(.return_mismatch,
		'@[noreturn] functions should end with a call to another @[noreturn] function, or with an infinite `for {}` loop', if tc.valid_node_id(tail_id) {
		tail_id
	} else {
		id
	}, pos)
}

fn (mut tc TypeChecker) check_unreachable_after_noreturn_call(node flat.Node) {
	mut previous_never_returns := false
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind == .param {
			continue
		}
		if previous_never_returns {
			tc.record_warning_at(.return_mismatch, 'unreachable code after a @[noreturn] call',
				child_id, tc.noreturn_statement_diagnostic_pos(child_id))
			return
		}
		previous_never_returns = tc.expr_never_returns(child_id)
	}
}

fn (tc &TypeChecker) subtree_contains_return(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind == .return_stmt {
		return true
	}
	for i in 0 .. node.children_count {
		if tc.subtree_contains_return(tc.a.child(node, i)) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) noreturn_invalid_tail_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	if node.kind == .for_stmt {
		line_pos := tc.previous_source_line_matching(node.pos, 'for')
		file := tc.a.source_files[line_pos.id] or { return line_pos }
		source := tc.source_texts_by_file[file.name] or { return line_pos }
		if line_pos.offset >= 0 && line_pos.end <= source.len && line_pos.end > line_pos.offset {
			line := source[line_pos.offset..line_pos.end]
			brace := line.index_u8(`{`)
			if brace >= 0 {
				return token.new_span(line_pos.id, line_pos.offset + brace, line_pos.offset +
					brace + 1)
			}
		}
		return line_pos
	}
	return tc.noreturn_statement_diagnostic_pos(id)
}

fn (tc &TypeChecker) noreturn_statement_diagnostic_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	if node.kind == .expr_stmt && node.children_count > 0 {
		return tc.a.node(tc.a.child(node, 0)).pos
	}
	if node.kind == .return_stmt {
		return tc.previous_source_line_matching(node.pos, 'return')
	}
	return node.pos
}

fn (tc &TypeChecker) previous_source_line_matching(pos token.Pos, prefix string) token.Pos {
	file := tc.a.source_files[pos.id] or { return pos }
	source := tc.source_texts_by_file[file.name] or { return pos }
	mut cursor := int_min(int_max(pos.offset, 0), source.len)
	for cursor >= 0 {
		line_start := if cursor > 0 {
			if relative := source[..cursor].last_index('\n') {
				relative + 1
			} else {
				0
			}
		} else {
			0
		}
		line_end := source.index_after('\n', line_start) or { source.len }
		line := source[line_start..line_end].trim_right('\r\n')
		trimmed := line.trim_left(' \t')
		if trimmed.starts_with(prefix) {
			start := line_start + line.len - line.trim_left(' \t').len
			return token.new_span(pos.id, start, line_start + line.len)
		}
		if line_start == 0 {
			break
		}
		cursor = line_start - 1
	}
	return pos
}

fn type_allows_implicit_return(typ Type) bool {
	if typ is Void {
		return true
	}
	if typ is OptionType {
		return typ.base_type is Void
	}
	if typ is ResultType {
		return typ.base_type is Void
	}
	return false
}

// valid_node_id supports valid node id handling for TypeChecker.
fn (tc &TypeChecker) valid_node_id(id flat.NodeId) bool {
	return int(id) >= 0 && tc.a != unsafe { nil } && int(id) < tc.a.nodes.len
}

// stmt_definitely_returns supports stmt definitely returns handling for TypeChecker.
fn (tc &TypeChecker) stmt_definitely_returns(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.return_stmt {
			return true
		}
		.expr_stmt {
			if node.children_count == 0 {
				return false
			}
			return tc.stmt_definitely_returns(tc.a.child(&node, 0))
		}
		.call {
			return tc.call_never_returns(id)
		}
		.block {
			return tc.stmt_sequence_definitely_returns(&node, 0)
		}
		.comptime_if {
			if node.children_count == 0 {
				return false
			}
			if node.children_count == 1 {
				return comptime_condition_strip_outer_parens(node.value) == 'true'
					&& tc.stmt_definitely_returns(tc.a.child(&node, 0))
			}
			return tc.stmt_definitely_returns(tc.a.child(&node, 0))
				&& tc.stmt_definitely_returns(tc.a.child(&node, 1))
		}
		.if_expr {
			if node.children_count < 3 {
				return false
			}
			return tc.stmt_definitely_returns(tc.a.child(&node, 1))
				&& tc.stmt_definitely_returns(tc.a.child(&node, 2))
		}
		.match_stmt {
			if node.children_count < 2 {
				return false
			}
			for i in 1 .. node.children_count {
				branch := tc.a.child_node(&node, i)
				if branch.kind != .match_branch {
					return false
				}
				if !tc.match_branch_definitely_returns_with_context(node, branch) {
					return false
				}
			}
			return tc.match_has_else_or_exhaustive_coverage(node)
		}
		.lock_expr {
			// lock/rlock: objects first, body block last; the statement returns
			// when its body always returns.
			if node.children_count == 0 {
				return false
			}
			body := tc.a.child_node(&node, node.children_count - 1)
			if body.kind != .block {
				return false
			}
			return tc.stmt_definitely_returns(tc.a.child(&node, node.children_count - 1))
		}
		.for_stmt {
			// `for { ... }` with no condition and no break never falls through.
			if node.children_count < 3 {
				return false
			}
			cond := tc.a.child_node(&node, 1)
			if cond.kind != .empty {
				return false
			}
			for i in 3 .. node.children_count {
				if tc.subtree_contains_break(tc.a.child(&node, i)) {
					return false
				}
			}
			return true
		}
		else {
			return false
		}
	}
}

// subtree_contains_break reports whether any node under id is a `break`.
// Conservative: a break in a nested inner loop also counts, so an infinite
// outer loop is only treated as no-fallthrough when its body has no break at all.
fn (tc &TypeChecker) subtree_contains_break(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .break_stmt {
		return true
	}
	for i in 0 .. node.children_count {
		if tc.subtree_contains_break(tc.a.child(&node, i)) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) call_never_returns(id flat.NodeId) bool {
	if tc.resolved_call_never_returns(id) {
		return true
	}
	if !tc.valid_node_id(id) {
		return false
	}
	call := tc.a.nodes[int(id)]
	if call.kind != .call || call.children_count == 0 {
		return false
	}
	callee := tc.a.child_node(&call, 0)
	if callee.kind == .ident {
		if callee.value in ['panic', 'exit'] && tc.no_return_builtin_is_shadowed(callee.value) {
			return false
		}
		return callee.value in ['panic', 'exit', '__v_compile_error']
	}
	if callee.kind == .selector && callee.children_count > 0 {
		base := tc.a.child_node(callee, 0)
		if base.kind != .ident || callee.value != 'exit' || base.value !in ['os', 'C'] {
			return false
		}
		if base.value == 'os' && tc.no_return_builtin_is_shadowed(base.value) {
			return false
		}
		return true
	}
	return false
}

fn (tc &TypeChecker) no_return_builtin_is_shadowed(name string) bool {
	if name in tc.smartcasts {
		return true
	}
	if _ := tc.non_file_scope_type(name) {
		return true
	}
	return false
}

fn (mut tc TypeChecker) call_never_returns_resolving(id flat.NodeId) bool {
	if tc.resolved_call_never_returns(id) {
		return true
	}
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind != .call {
		return false
	}
	info := tc.resolve_call_info(id, node) or { return false }
	if info.name.len > 0 && !is_array_dsl_call_name(info.name) {
		tc.remember_resolved_call(id, info.name)
	}
	return tc.name_never_returns(info.name)
}

fn (mut tc TypeChecker) expr_never_returns_resolving(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.expr_stmt, .paren {
			if node.children_count == 0 {
				return false
			}
			return tc.expr_never_returns_resolving(tc.a.child(&node, 0))
		}
		.call {
			return tc.call_never_returns_resolving(id)
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) expr_never_returns(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.expr_stmt, .paren {
			if node.children_count == 0 {
				return false
			}
			return tc.expr_never_returns(tc.a.child(&node, 0))
		}
		.call {
			return tc.call_never_returns(id)
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) branch_tail_never_returns(branch_id flat.NodeId) bool {
	if !tc.valid_node_id(branch_id) {
		return false
	}
	branch := tc.a.nodes[int(branch_id)]
	tail_id := tc.branch_tail_expr_id(branch_id)
	if !tc.valid_node_id(tail_id) {
		return false
	}
	if branch.kind !in [.block, .match_branch] {
		return tc.expr_never_returns(tail_id)
	}
	body_start := if branch.kind == .match_branch {
		if branch.value == 'else' { 0 } else { branch.value.int() }
	} else {
		0
	}
	// Only the `smartcasts` binding needs isolation here: a full `*tc` copy
	// shares every map's backing storage anyway and memmoves the ~11KB
	// TypeChecker per call, so swap in a scratch clone and restore instead.
	mut mtc := unsafe { &TypeChecker(voidptr(tc)) }
	mut saved_smartcasts := mtc.smartcasts.move()
	mtc.smartcasts = clone_smartcasts(saved_smartcasts)
	defer {
		mtc.smartcasts = saved_smartcasts.move()
	}
	tail_index := int(branch.children_count) - 1
	for i in body_start .. tail_index {
		mtc.apply_return_analysis_local_binding(tc.a.child(&branch, i))
	}
	return tc.expr_never_returns(tail_id)
}

// match_covers_all_enum_variants reports whether a `match` over an enum subject
// lists every variant of that enum (so it is exhaustive without an `else`).
fn (tc &TypeChecker) match_covers_all_enum_variants(node flat.Node) bool {
	if node.children_count < 2 {
		return false
	}
	subject_type := unwrap_pointer(tc.resolve_type(tc.a.child(&node, 0)))
	mut enum_name := ''
	if subject_type is Enum {
		enum_name = subject_type.name
	} else {
		return false
	}
	// A `[flag]` enum value can hold combined or zero bits (`.read | .write`, `0`) that
	// no single-field branch covers, so listing every field is NOT exhaustive — such a
	// match needs an explicit `else`.
	if enum_name in tc.flag_enums {
		return false
	}
	all_fields := tc.enum_fields[enum_name] or { return false }
	if all_fields.len == 0 {
		return false
	}
	mut covered := map[string]bool{}
	for i in 1 .. node.children_count {
		branch := tc.a.child_node(&node, i)
		if branch.kind != .match_branch {
			return false
		}
		if branch.value == 'else' {
			return true
		}
		n_conds := branch.value.int()
		for j in 0 .. n_conds {
			cond := tc.a.child_node(branch, j)
			if cond.kind == .enum_val {
				covered[cond.value.all_after_last('.')] = true
			}
		}
	}
	for f in all_fields {
		if f !in covered {
			return false
		}
	}
	return true
}

// match_branch_definitely_returns
// supports helper handling in types.
fn (tc &TypeChecker) match_branch_definitely_returns(branch &flat.Node) bool {
	body_start := if branch.value == 'else' { 0 } else { branch.value.int() }
	return tc.stmt_sequence_definitely_returns(branch, body_start)
}

fn (tc &TypeChecker) stmt_sequence_definitely_returns(node &flat.Node, body_start int) bool {
	// Only the `smartcasts` binding needs isolation here (see
	// branch_tail_never_returns); avoid the ~11KB full struct copy.
	mut mtc := unsafe { &TypeChecker(voidptr(tc)) }
	mut saved_smartcasts := mtc.smartcasts.move()
	mtc.smartcasts = clone_smartcasts(saved_smartcasts)
	defer {
		mtc.smartcasts = saved_smartcasts.move()
	}
	for i in body_start .. node.children_count {
		child_id := tc.a.child(node, i)
		if tc.stmt_definitely_returns(child_id) {
			return true
		}
		mtc.apply_return_analysis_local_binding(child_id)
	}
	return false
}

fn (mut tc TypeChecker) apply_return_analysis_local_binding(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.nodes[int(id)]
	if node.kind != .decl_assign || node.children_count < 2 {
		return
	}
	lhs_id := tc.a.child(&node, 0)
	rhs_id := tc.a.child(&node, 1)
	if !tc.valid_node_id(lhs_id) || !tc.valid_node_id(rhs_id) {
		return
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind != .ident || lhs.value.len == 0 || !valid_string_data(lhs.value) {
		return
	}
	rhs_type := tc.smartcast_type(rhs_id) or { tc.expr_type(rhs_id) or { tc.resolve_type(rhs_id) } }
	if rhs_type is Unknown || rhs_type is Void {
		return
	}
	tc.smartcasts[lhs.value] = rhs_type
}

fn (tc &TypeChecker) match_branch_definitely_returns_with_context(node flat.Node, branch &flat.Node) bool {
	if branch.value == 'else' || node.children_count == 0 {
		return tc.match_branch_definitely_returns(branch)
	}
	n_conds := branch.value.int()
	if n_conds != 1 || branch.children_count == 0 {
		return tc.match_branch_definitely_returns(branch)
	}
	subject_id := tc.a.child(&node, 0)
	subject_key := tc.expr_key(subject_id)
	if subject_key.len == 0 || !valid_string_data(subject_key) {
		return tc.match_branch_definitely_returns(branch)
	}
	subject_type := unalias_and_unwrap_pointer_type(tc.resolve_type(subject_id))
	if subject_type !is SumType && !is_ierror_type(subject_type) && subject_type !is Interface {
		return tc.match_branch_definitely_returns(branch)
	}
	cond := tc.a.node(tc.a.child(branch, 0))
	pattern := tc.match_type_pattern(cond) or { return tc.match_branch_definitely_returns(branch) }
	smartcast_type := if subject_type is SumType {
		tc.sum_variant_type_for_pattern(subject_type.name, pattern) or {
			return tc.match_branch_definitely_returns(branch)
		}
	} else if is_ierror_type(subject_type) {
		tc.resolve_ierror_match_pattern(pattern) or {
			return tc.match_branch_definitely_returns(branch)
		}
	} else if subject_type is Interface {
		tc.resolve_interface_match_pattern(pattern) or {
			return tc.match_branch_definitely_returns(branch)
		}
	} else {
		return tc.match_branch_definitely_returns(branch)
	}
	// Only the `smartcasts` binding needs isolation here (see
	// branch_tail_never_returns); avoid the ~11KB full struct copy.
	mut mtc := unsafe { &TypeChecker(voidptr(tc)) }
	mut saved_smartcasts := mtc.smartcasts.move()
	mtc.smartcasts = clone_smartcasts(saved_smartcasts)
	defer {
		mtc.smartcasts = saved_smartcasts.move()
	}
	mtc.smartcasts[subject_key] = tc.parse_type(smartcast_type)
	return tc.match_branch_definitely_returns(branch)
}

fn (tc &TypeChecker) match_without_else_exhaustive_enum_returns(node flat.Node) bool {
	subject_type := unwrap_pointer(tc.resolve_type(tc.a.child(&node, 0)))
	if subject_type is Enum {
		enum_name := tc.resolve_enum_name(subject_type.name) or { subject_type.name }
		if subject_type.is_flag || enum_name in tc.flag_enums {
			return false
		}
		fields := tc.enum_fields[enum_name] or { return false }
		if fields.len == 0 {
			return false
		}
		mut covered := map[string]bool{}
		for i in 1 .. node.children_count {
			branch := tc.a.child_node(&node, i)
			if branch.kind != .match_branch || branch.value == 'else' {
				return false
			}
			n_conds := branch.value.int()
			if n_conds <= 0 || n_conds > branch.children_count {
				return false
			}
			for j in 0 .. n_conds {
				cond := tc.a.child_node(branch, j)
				field := tc.match_enum_condition_field(cond, enum_name) or { return false }
				covered[field] = true
			}
		}
		for field in fields {
			if field !in covered {
				return false
			}
		}
		return true
	}
	return false
}

fn (tc &TypeChecker) match_without_else_exhaustive_bool_returns(node flat.Node) bool {
	if node.children_count < 2 {
		return false
	}
	raw_subject_type := unalias_type(tc.resolve_type(tc.a.child(&node, 0)))
	if raw_subject_type is Pointer {
		return false
	}
	subject_type := raw_subject_type
	if subject_type !is Primitive {
		return false
	}
	if !subject_type.props.has(.boolean) {
		return false
	}
	mut covered_true := false
	mut covered_false := false
	for i in 1 .. node.children_count {
		branch := tc.a.child_node(&node, i)
		if branch.kind != .match_branch || branch.value == 'else' {
			return false
		}
		n_conds := branch.value.int()
		if n_conds <= 0 || n_conds > branch.children_count {
			return false
		}
		for j in 0 .. n_conds {
			cond := tc.a.child_node(branch, j)
			if cond.kind == .bool_literal {
				if cond.value == 'true' {
					covered_true = true
				} else if cond.value == 'false' {
					covered_false = true
				}
			}
		}
	}
	return covered_true && covered_false
}

fn (tc &TypeChecker) match_has_else_or_exhaustive_coverage(node flat.Node) bool {
	if node.children_count < 2 {
		return false
	}
	for i in 1 .. node.children_count {
		branch := tc.a.child_node(&node, i)
		if branch.kind != .match_branch {
			return false
		}
		if branch.value == 'else' {
			return true
		}
	}
	return tc.match_without_else_exhaustive_enum_returns(node)
		|| tc.match_without_else_exhaustive_bool_returns(node)
		|| tc.match_without_else_exhaustive_sumtype_returns(node)
}

// match_without_else_exhaustive_sumtype_returns reports whether a `match` over a
// sum-type subject lists every variant (so it is exhaustive without an `else`).
fn (tc &TypeChecker) match_without_else_exhaustive_sumtype_returns(node flat.Node) bool {
	subject_type := unalias_type(unwrap_pointer(tc.resolve_type(tc.a.child(&node, 0))))
	mut sum_name := ''
	if subject_type is SumType {
		sum_name = subject_type.name
	} else {
		return false
	}
	base := tc.sum_base_name(sum_name)
	variants := tc.sum_types[base] or { return false }
	if variants.len == 0 {
		return false
	}
	mut covered := map[string]bool{}
	for i in 1 .. node.children_count {
		branch := tc.a.child_node(&node, i)
		if branch.kind != .match_branch {
			return false
		}
		if branch.value == 'else' {
			return true
		}
		n_conds := branch.value.int()
		if n_conds <= 0 || n_conds > branch.children_count {
			return false
		}
		for j in 0 .. n_conds {
			cond := tc.a.child_node(branch, j)
			pattern := tc.match_type_pattern(cond) or { return false }
			qpattern := tc.qualify_name(pattern)
			mut matched := false
			for variant in variants {
				if variant == pattern || variant == qpattern {
					covered[variant] = true
					matched = true
				}
			}
			if matched {
				continue
			}
			// Short-name fallback: only sound when exactly one variant carries
			// this short name — for `type S = a.Foo | b.Foo`, a branch matching
			// one `Foo` must not mark the other as covered.
			pattern_short := short_type_name(pattern)
			mut short_match := ''
			mut short_count := 0
			for variant in variants {
				if short_type_name(variant) == pattern_short {
					short_count++
					short_match = variant
				}
			}
			if short_count == 1 {
				covered[short_match] = true
			}
		}
	}
	for variant in variants {
		if variant !in covered {
			return false
		}
	}
	return true
}

fn unalias_type(t Type) Type {
	if t is Alias {
		return unalias_type(t.base_type)
	}
	return t
}

fn unalias_and_unwrap_pointer_type(t Type) Type {
	mut cur := t
	for _ in 0 .. 32 {
		if cur is Alias {
			cur = cur.base_type
			continue
		}
		if cur is Pointer {
			cur = cur.base_type
			continue
		}
		return cur
	}
	return cur
}

fn (tc &TypeChecker) match_enum_condition_field(cond &flat.Node, enum_name string) ?string {
	match cond.kind {
		.enum_val {
			field := cond.value.all_after_last('.')
			if tc.enum_value_matches(cond.value, enum_name) {
				return field
			}
		}
		.selector {
			if typ := tc.enum_selector_type(cond) {
				if typ is Enum {
					cond_enum_name := tc.resolve_enum_name(typ.name) or { typ.name }
					if cond_enum_name == enum_name && tc.enum_has_field(enum_name, cond.value) {
						return cond.value
					}
				}
			}
		}
		else {}
	}

	return none
}

// node_kind_id supports node kind id handling for types.
fn node_kind_id(node flat.Node) int {
	return int(node.kind)
}

struct ComptimeStaticFieldCase {
	name          string
	typ           string
	unaliased_typ string
	is_option     bool
	is_embed      bool
	is_array      bool
	is_map        bool
	is_chan       bool
	is_struct     bool
	is_enum       bool
	is_alias      bool
	is_shared     bool
	is_atomic     bool
	is_mut        bool
	is_pub        bool
	has_decl_meta bool
	indirections  int
}

struct ComptimeStaticFieldCases {
	known bool
	cases []ComptimeStaticFieldCase
}

struct ComptimeStaticValueCase {
	name          string
	location      string
	value         int
	has_value     bool
	typ           string
	return_type   string
	is_pub        bool
	has_is_pub    bool
	arg           string
	has_arg       bool
	has_attr_meta bool
	attr_kind     int
	param_names   []string
	param_types   []string
	param_is_mut  []bool
}

struct ComptimeStaticValueCases {
	known bool
	cases []ComptimeStaticValueCase
}

struct ComptimeStaticFieldDeclMeta {
	is_mut   bool
	is_pub   bool
	is_embed bool
	raw_typ  string
}

struct ComptimeStaticFieldTypeFlags {
mut:
	is_shared    bool
	is_atomic    bool
	indirections int
}

struct ComptimeDeferredDeclSource {
	module_name string
	decl_name   string
}

fn (mut tc TypeChecker) check_comptime_for_members(_id flat.NodeId, node flat.Node) {
	parts := node.value.split('|')
	if parts.len != 2 || parts[0].len == 0 || node.children_count == 0 {
		return
	}
	body_id := tc.a.child(&node, 0)
	if _ := tc.comptime_struct_update_id(body_id) {
		return
	}
	if _ := tc.comptime_struct_update_source_pos(node) {
		return
	}
	if !tc.comptime_subtree_references_var(body_id, parts[0]) {
		tc.record_warning_at(.unknown_ident, 'unused variable: `${parts[0]}`', _id, tc.comptime_for_variable_pos(node,
			parts[0]))
	}
	if tc.check_comptime_for_source_type(_id, node) {
		return
	}
	source_is_type := tc.type_name_known(node.typ)
	source_is_value := if tc.cur_scope == unsafe { nil } {
		false
	} else {
		tc.cur_scope.lookup(node.typ) != none
	}
	source_is_fn := node.typ in tc.fn_ret_types || tc.qualify_fn_name(node.typ) in tc.fn_ret_types
	if parts[1] == 'params' && source_is_type && !source_is_fn {
		tc.record_error_at(.unknown_type,
			'iterating over `.params` is supported only for functions, and `${node.typ}` is not a function',
			_id, tc.comptime_for_source_pos(node))
		return
	}
	if !source_is_type && !source_is_value && !source_is_fn && node.typ.len > 0
		&& node.typ[0].is_capital() {
		tc.record_error_at(.unknown_type,
			'$for expects a type name or variable name to be used here, but ${node.typ} is not a type or variable name',
			_id, tc.comptime_for_source_pos(node))
		return
	}
	current_fn_id := flat.NodeId(tc.fn_context.node_id)
	defer {
		if tc.valid_node_id(current_fn_id) {
			tc.check_comptime_selectors_outside_loop(current_fn_id, _id, parts[0])
		}
	}
	tc.check_comptime_reflection_condition_types(body_id)
	if parts[1] == 'methods' {
		mut invalid_uses := []flat.NodeId{}
		tc.collect_anon_fn_comptime_method_uses(body_id, parts[0], false, mut invalid_uses)
		if invalid_uses.len > 0 {
			file := tc.a.source_files[node.pos.id] or { &token.File{} }
			source := tc.source_texts_by_file[file.name] or { '' }
			var_pos := closest_identifier_span(source, parts[0], node.pos.offset, node.pos.id) or {
				node.pos
			}
			tc.record_warning_at(.unknown_ident, 'unused variable: `${parts[0]}`', _id, var_pos)
			for use_id in invalid_uses {
				tc.record_error_at(.unknown_ident,
					'undefined ident `${parts[0]}` in the anonymous function', use_id, tc.comptime_method_anon_fn_call_pos(use_id,
					parts[0]))
			}
		}
	}
	is_variant_loop := parts[1] == 'variants'
	if is_variant_loop {
		tc.cur_comptime_variant_loop_vars << parts[0]
	}
	defer {
		if is_variant_loop {
			tc.cur_comptime_variant_loop_vars.pop()
		}
	}
	match parts[1] {
		'fields' {
			tc.check_comptime_members(body_id, parts[0], comptime_field_members, 'FieldData')
		}
		'values' {
			tc.check_comptime_members(body_id, parts[0], comptime_enum_value_members, 'EnumData')
		}
		'variants' {
			tc.check_comptime_members(body_id, parts[0], comptime_variant_members, 'VariantData')
		}
		'attributes' {
			tc.check_comptime_attribute_members(body_id, parts[0])
		}
		else {}
	}

	// Method and parameter loops are resolved to concrete declarations by the transformer.
	// Their bodies can also reference metadata from an enclosing reflection loop, which does
	// not exist as a runtime local while checking the original generic body.
	if parts[1] in ['methods', 'params', 'attributes'] {
		deferred_cases := tc.comptime_static_deferred_cases(node.typ, parts[1])
		if deferred_cases.known && deferred_cases.cases.len == 0 {
			return
		}
		tc.check_comptime_static_body(body_id, parts[0], parts[1], ComptimeStaticFieldCases{},
			deferred_cases)
		return
	}

	field_cases := if parts[1] == 'fields' {
		tc.comptime_static_field_cases(node.typ)
	} else {
		ComptimeStaticFieldCases{}
	}
	value_cases := if parts[1] == 'values' {
		tc.comptime_static_enum_value_cases(node.typ)
	} else {
		ComptimeStaticValueCases{}
	}
	if field_cases.known && field_cases.cases.len == 0 {
		return
	}
	if value_cases.known && value_cases.cases.len == 0 {
		return
	}
	tc.check_comptime_static_body(body_id, parts[0], parts[1], field_cases, value_cases)
}

fn (tc &TypeChecker) comptime_struct_update_id(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind in [.struct_init, .assoc] {
		for i in 0 .. node.children_count {
			child_id := tc.a.child(node, i)
			child := tc.a.node(child_id)
			is_update := node.kind == .assoc
				|| (child.kind == .prefix && child.value == '...')
				|| tc.node_has_ellipsis_prefix(child_id)
			if is_update && tc.source_text_for_node(child_id).contains('$(') {
				return child_id
			}
		}
	}
	for i in 0 .. node.children_count {
		if update_id := tc.comptime_struct_update_id(tc.a.child(node, i)) {
			return update_id
		}
	}
	return none
}

fn (tc &TypeChecker) ellipsis_diagnostic_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, int_min(node.pos.offset, source.len))
	if start + 3 <= source.len && source[start..start + 3] == '...' {
		return token.new_span(node.pos.id, start, start + 3)
	}
	mut cursor := start
	for cursor > 0 && source[cursor - 1] in [` `, `\t`, `\n`, `\r`] {
		cursor--
	}
	if cursor >= 3 && source[cursor - 3..cursor] == '...' {
		return token.new_span(node.pos.id, cursor - 3, cursor)
	}
	return node.pos
}

fn (tc &TypeChecker) comptime_struct_update_source_pos(node flat.Node) ?token.Pos {
	file := tc.a.source_files[node.pos.id] or { return none }
	source := tc.source_texts_by_file[file.name] or { return none }
	mut cursor := 0
	for cursor + 3 <= source.len {
		if source[cursor..cursor + 3] == '...' {
			line_end := source[cursor..].index('\n') or { source.len - cursor }
			if source[cursor..cursor + line_end].contains('$(') && source[..cursor].contains('$for') {
				return token.new_span(node.pos.id, cursor, cursor + 3)
			}
		}
		cursor++
	}
	return none
}

fn (mut tc TypeChecker) check_comptime_struct_updates_preflight() {
	message := 'cannot use struct update syntax in compile time expressions'
	for index, node in tc.a.nodes {
		if node.kind != .comptime_for || node.children_count == 0 {
			continue
		}
		body_id := tc.a.child(&node, 0)
		if update_id := tc.comptime_struct_update_id(body_id) {
			if !tc.errors.any(it.node == update_id && it.msg == message) {
				tc.record_error_at(.assignment_mismatch, message, update_id,
					tc.ellipsis_diagnostic_pos(update_id))
			}
		} else if pos := tc.comptime_struct_update_source_pos(node) {
			node_id := flat.NodeId(index)
			if !tc.errors.any(it.msg == message && it.pos == pos) {
				tc.record_error_at(.assignment_mismatch, message, node_id, pos)
			}
		}
	}
	for file_id, file in tc.a.source_files {
		if tc.diagnostic_files.len > 0 && file.name !in tc.diagnostic_files {
			continue
		}
		source := tc.source_texts_by_file[file.name] or { continue }
		pos := comptime_struct_update_pos_in_source(file_id, source) or { continue }
		if tc.errors.any(it.msg == message && it.pos == pos) {
			continue
		}
		node_id := tc.closest_source_node_id(pos)
		tc.errors << tc.make_type_error_at(.assignment_mismatch, message, node_id, pos)
	}
}

fn comptime_struct_update_pos_in_source(file_id int, source string) ?token.Pos {
	mut cursor := 0
	for cursor + 3 <= source.len {
		relative := source[cursor..].index('...') or { return none }
		cursor += relative
		line_end := source[cursor..].index('\n') or { source.len - cursor }
		if source[cursor..cursor + line_end].contains('$(') && source[..cursor].contains('$for') {
			return token.new_span(file_id, cursor, cursor + 3)
		}
		cursor += 3
	}
	return none
}

fn (tc &TypeChecker) closest_source_node_id(pos token.Pos) flat.NodeId {
	mut best := -1
	mut best_span := int_max(1, tc.a.nodes.len)
	for index in tc.a.user_code_start .. tc.a.nodes.len {
		node_pos := tc.a.nodes[index].pos
		if node_pos.id != pos.id || node_pos.offset > pos.offset || node_pos.end < pos.end {
			continue
		}
		span := node_pos.end - node_pos.offset
		if best < 0 || span < best_span {
			best = index
			best_span = span
		}
	}
	return if best >= 0 { flat.NodeId(best) } else { flat.NodeId(tc.a.user_code_start) }
}

fn (mut tc TypeChecker) check_comptime_for_source_type(id flat.NodeId, node flat.Node) bool {
	parts := node.value.split('|')
	if parts.len != 2 || node.typ.len == 0 {
		return false
	}
	source_type := unalias_type(tc.parse_type(node.typ))
	mut message := ''
	if parts[1] == 'fields' && source_type !is Unknown && source_type !is Void
		&& source_type !is Struct && source_type !is Interface {
		message = 'iterating over .fields is supported only for structs and interfaces, and ${node.typ} is neither'
	} else if parts[1] == 'values' && source_type !is Unknown && source_type !is Void
		&& source_type !is Enum {
		message = 'iterating over .values is supported only for enums, and ${node.typ} is not an enum'
	}
	if message.len == 0 {
		return false
	}
	for diagnostic in tc.errors {
		if diagnostic.node == id && diagnostic.msg == message {
			return true
		}
	}
	tc.record_error_at(.unknown_type, message, id, tc.comptime_for_source_pos(node))
	return true
}

fn (mut tc TypeChecker) check_comptime_for_source_types_preflight() {
	for index, node in tc.a.nodes {
		if node.kind == .comptime_for {
			tc.check_comptime_for_source_type(flat.NodeId(index), node)
		}
	}
}

fn (mut tc TypeChecker) check_comptime_selectors_outside_loop(id flat.NodeId, loop_id flat.NodeId, var_name string) {
	if !tc.valid_node_id(id) || id == loop_id {
		return
	}
	node := tc.a.node(id)
	if node.kind == .comptime_for && comptime_for_declares_var_in_value(node.value, var_name) {
		return
	}
	if node.kind == .selector && node.value == '$' && node.children_count >= 2 {
		field_expr := tc.a.child_node(node, 1)
		if field_expr.kind == .selector && field_expr.children_count > 0 {
			base := tc.a.child_node(field_expr, 0)
			if base.kind == .ident && base.value == var_name {
				tc.check_comptime_field_selector(id, *node, '', ComptimeStaticFieldCases{})
				return
			}
		}
	}
	for i in 0 .. node.children_count {
		tc.check_comptime_selectors_outside_loop(tc.a.child(node, i), loop_id, var_name)
	}
}

fn (tc &TypeChecker) comptime_for_variable_pos(node flat.Node, var_name string) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, int_min(node.pos.offset, source.len))
	end := int_max(start, int_min(node.pos.end, source.len))
	if relative := source[start..end].index('$for ${var_name}') {
		var_start := start + relative + '$for '.len
		return token.new_span(node.pos.id, var_start, var_start + var_name.len)
	}
	return node.pos
}

fn (tc &TypeChecker) comptime_for_source_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, int_min(node.pos.offset, source.len))
	end := int_max(start, int_min(node.pos.end, source.len))
	needle := ' in ${node.typ}'
	if relative := source[start..end].index(needle) {
		source_start := start + relative + ' in '.len
		return token.new_span(node.pos.id, source_start, source_start + node.typ.len)
	}
	return node.pos
}

fn (mut tc TypeChecker) check_comptime_reflection_condition_types(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind == .comptime_if {
		mut offset := 0
		for offset < node.value.len {
			relative := node.value[offset..].index(' is ') or { break }
			type_start := offset + relative + ' is '.len
			mut type_end := type_start
			for type_end < node.value.len {
				c := node.value[type_end]
				if !(c.is_alnum() || c in [`_`, `.`, `$`, `[`, `]`]) {
					break
				}
				type_end++
			}
			typ := node.value[type_start..type_end]
			if typ.len > 0 && !typ.starts_with('$') && !tc.type_name_known(typ) {
				tc.record_error_at(.unknown_type, 'unknown type `${typ}`', id, tc.comptime_condition_type_pos(*node,
					typ))
			}
			offset = int_max(type_end, type_start + 1)
		}
	}
	for i in 0 .. node.children_count {
		tc.check_comptime_reflection_condition_types(tc.a.child(node, i))
	}
}

fn (tc &TypeChecker) comptime_condition_type_pos(node flat.Node, typ string) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, int_min(node.pos.offset, source.len))
	end := int_max(start, int_min(node.pos.end, source.len))
	needle := 'is ${typ}'
	if relative := source[start..end].index(needle) {
		type_start := start + relative + 'is '.len
		return token.new_span(node.pos.id, type_start, type_start + typ.len)
	}
	return node.pos
}

fn (mut tc TypeChecker) check_comptime_attribute_members(id flat.NodeId, var_name string) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind == .comptime_if {
		if member := comptime_cond_unknown_member(node.value, var_name, comptime_attribute_members) {
			mut pos := node.pos
			if file := tc.a.source_files[node.pos.id] {
				if source := tc.source_texts_by_file[file.name] {
					start := int_max(0, node.pos.offset)
					end := int_min(source.len, node.pos.end)
					if start < end {
						if relative := source[start..end].index('.${member}') {
							member_start := start + relative + 1
							pos = token.new_span(node.pos.id, member_start, member_start +
								member.len)
						}
					}
				}
			}
			tc.record_error_at(.unknown_field, 'unknown field `${member}` from ${var_name}', id,
				pos)
			return
		}
	}
	for i in 0 .. node.children_count {
		tc.check_comptime_attribute_members(tc.a.child(node, i), var_name)
	}
}

fn (tc &TypeChecker) collect_anon_fn_comptime_method_uses(id flat.NodeId, var_name string, inside_anon_fn bool, mut uses []flat.NodeId) {
	node := tc.a.node(id)
	is_inside := inside_anon_fn || node.kind in [.fn_literal, .lambda_expr]
	if is_inside && node.kind == .selector && node.value == '$' && node.children_count > 1 {
		method_var := tc.a.child_node(node, 1)
		if method_var.kind == .ident && method_var.value == var_name {
			uses << id
			return
		}
	}
	for i in 0 .. node.children_count {
		tc.collect_anon_fn_comptime_method_uses(tc.a.child(node, i), var_name, is_inside, mut uses)
	}
}

fn (tc &TypeChecker) comptime_method_anon_fn_call_pos(id flat.NodeId, var_name string) token.Pos {
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	if node.pos.offset < 0 || node.pos.offset >= source.len {
		return node.pos
	}
	line_start := if relative := source[..node.pos.offset].last_index('\n') {
		relative + 1
	} else {
		0
	}
	line_end := source.index_after('\n', node.pos.offset) or { source.len }
	line := source[line_start..line_end]
	marker := '.$${var_name}()'
	dot_relative := line.index(marker) or { return node.pos }
	dot := line_start + dot_relative
	return token.new_span(node.pos.id, dot + 1, dot + marker.len)
}

fn (tc &TypeChecker) comptime_static_deferred_cases(source string, loop_kind string) ComptimeStaticValueCases {
	if loop_kind == 'methods' {
		return tc.comptime_static_method_cases(source)
	}
	if loop_kind == 'params' {
		return tc.comptime_static_param_cases(source)
	}
	if loop_kind == 'attributes' {
		return tc.comptime_static_attribute_cases(source)
	}
	return ComptimeStaticValueCases{}
}

fn (tc &TypeChecker) comptime_static_method_cases(source string) ComptimeStaticValueCases {
	base_type := tc.comptime_static_for_base_type(source)
	clean_type := comptime_static_unwrap_type_text(base_type)
	generic_base, generic_args, is_generic := generic_type_application_parts(clean_type)
	if is_generic && !tc.generic_args_are_concrete(generic_args) {
		return ComptimeStaticValueCases{}
	}
	lookup_type := if is_generic { generic_base } else { clean_type }
	struct_name := tc.comptime_static_struct_name(lookup_type) or {
		return ComptimeStaticValueCases{}
	}
	generic_params := if is_generic {
		tc.struct_generic_params[struct_name] or {
			tc.struct_generic_params[struct_name.all_after_last('.')] or { []string{} }
		}
	} else {
		[]string{}
	}
	if is_generic && generic_params.len != generic_args.len {
		return ComptimeStaticValueCases{}
	}
	mut wanted_module := tc.struct_modules[struct_name] or { '' }
	if wanted_module.len == 0 {
		if decl_file := tc.struct_files[struct_name] {
			wanted_module = tc.file_modules[decl_file] or { '' }
		}
	}
	if wanted_module.len == 0 {
		wanted_module = if struct_name.contains('.') {
			struct_name.all_before_last('.')
		} else if tc.cur_module.len > 0 {
			tc.cur_module
		} else {
			'main'
		}
	}
	wanted_receiver := struct_name.all_after_last('.').all_before('[')
	mut module_name := ''
	mut file_name := ''
	mut cases := []ComptimeStaticValueCase{}
	mut seen := map[string]bool{}
	mut line_offsets_by_file := map[string][]int{}
	for idx in tc.top_level_idx {
		candidate := tc.a.nodes[idx]
		if candidate.kind == .file {
			module_name = 'main'
			file_name = candidate.value
			continue
		}
		if candidate.kind == .module_decl {
			module_name = candidate.value
			continue
		}
		if candidate.kind != .fn_decl || !tc.fn_has_receiver_param(candidate) {
			continue
		}
		receiver := candidate.value.all_before_last('.').all_after_last('.').all_before('[')
		candidate_module := if module_name.len > 0 { module_name } else { 'main' }
		if candidate_module == wanted_module && receiver == wanted_receiver {
			name := candidate.value.all_after_last('.')
			if name.len > 0 && name !in seen {
				seen[name] = true
				if file_name !in line_offsets_by_file {
					line_offsets_by_file[file_name] = comptime_static_source_line_offsets(file_name)
				}
				mut param_names := []string{}
				mut param_types := []string{}
				mut param_is_mut := []bool{}
				for i in 1 .. candidate.children_count {
					param := tc.a.child_node(&candidate, i)
					if param.kind == .param {
						param_names << param.value
						param_types << subst_generic_text(param.typ, generic_args, generic_params)
						param_is_mut << param.is_mut
					}
				}
				return_type := subst_generic_text(if candidate.typ.len > 0 {
					candidate.typ
				} else {
					'void'
				}, generic_args, generic_params)
				cases << ComptimeStaticValueCase{
					name:         name
					location:     comptime_static_source_location(file_name, candidate.pos.offset,
						line_offsets_by_file[file_name])
					typ:          comptime_static_method_type_text(param_types, return_type)
					return_type:  return_type
					is_pub:       candidate.op == .arrow
					has_is_pub:   true
					param_names:  param_names
					param_types:  param_types
					param_is_mut: param_is_mut
				}
			}
		}
	}
	return ComptimeStaticValueCases{
		known: true
		cases: cases
	}
}

fn (tc &TypeChecker) comptime_static_param_cases(source string) ComptimeStaticValueCases {
	wanted := tc.comptime_deferred_decl_source(source, false) or {
		return ComptimeStaticValueCases{}
	}
	mut module_name := ''
	for idx in tc.top_level_idx {
		candidate := tc.a.nodes[idx]
		if candidate.kind == .file {
			module_name = 'main'
			continue
		}
		if candidate.kind == .module_decl {
			module_name = candidate.value
			continue
		}
		if candidate.kind != .fn_decl {
			continue
		}
		candidate_module := if module_name.len > 0 { module_name } else { 'main' }
		if candidate_module != wanted.module_name || candidate.value != wanted.decl_name {
			continue
		}
		param_start := if tc.fn_has_receiver_param(candidate) { 1 } else { 0 }
		mut cases := []ComptimeStaticValueCase{}
		for i in param_start .. candidate.children_count {
			param := tc.a.child_node(&candidate, i)
			if param.kind == .param {
				cases << ComptimeStaticValueCase{
					name: param.value
					typ:  param.typ
				}
			}
		}
		return ComptimeStaticValueCases{
			known: true
			cases: cases
		}
	}
	return ComptimeStaticValueCases{}
}

fn (tc &TypeChecker) comptime_static_attribute_cases(source string) ComptimeStaticValueCases {
	wanted := tc.comptime_deferred_decl_source(source, true) or {
		return ComptimeStaticValueCases{}
	}
	mut module_name := ''
	mut decl_id := -1
	for idx in tc.top_level_idx {
		candidate := tc.a.nodes[idx]
		if candidate.kind == .file {
			module_name = 'main'
			continue
		}
		if candidate.kind == .module_decl {
			module_name = candidate.value
			continue
		}
		if candidate.kind !in [.struct_decl, .enum_decl, .fn_decl, .type_decl, .interface_decl] {
			continue
		}
		candidate_module := if module_name.len > 0 { module_name } else { 'main' }
		if candidate_module == wanted.module_name && candidate.value == wanted.decl_name {
			decl_id = idx
			break
		}
	}
	if decl_id < 0 {
		return ComptimeStaticValueCases{}
	}
	marker := '@attributes:${decl_id}'
	for candidate in tc.a.nodes {
		if candidate.kind == .directive && candidate.value == marker {
			params := candidate.generic_params()
			mut cases := []ComptimeStaticValueCase{cap: params.len}
			kinds := if candidate.typ.len > 0 { candidate.typ.split(',') } else { []string{} }
			for idx, raw in params {
				item := comptime_static_attribute_case(raw, if idx < kinds.len {
					kinds[idx].int()
				} else {
					0
				})
				name := item.name
				if name.len > 0 {
					cases << item
				}
			}
			return ComptimeStaticValueCases{
				known: true
				cases: cases
			}
		}
	}
	return ComptimeStaticValueCases{
		known: true
	}
}

fn comptime_static_method_type_text(param_types []string, return_type string) string {
	ret := if return_type.len > 0 && return_type != 'void' { ' ${return_type}' } else { '' }
	return 'fn(${param_types.join(', ')})${ret}'
}

fn comptime_static_source_line_offsets(path string) []int {
	source := os.read_file(path) or { return []int{} }
	mut offsets := []int{cap: source.len / 40 + 1}
	offsets << 0
	for i, ch in source {
		if ch == `\n` {
			offsets << i + 1
		}
	}
	return offsets
}

fn comptime_static_source_location(path string, encoded_offset int, line_offsets []int) string {
	if path.len == 0 || encoded_offset <= 0 || line_offsets.len == 0 {
		return ''
	}
	offset := encoded_offset - 1
	mut lo := 0
	mut hi := line_offsets.len
	for lo < hi {
		mid := (lo + hi) / 2
		if line_offsets[mid] <= offset {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	line_index := if lo > 0 { lo - 1 } else { 0 }
	return '${path}:${line_index + 1}:${offset - line_offsets[line_index]}'
}

fn comptime_static_attribute_case(raw string, kind int) ComptimeStaticValueCase {
	clean := trimmed_space(raw)
	colon := clean.index_u8(`:`)
	has_arg := colon >= 0 && !(kind == 1
		&& !comptime_static_attr_is_string_literal(trimmed_space(clean[colon + 1..])))
	mut name := if has_arg { trimmed_space(clean[..colon]) } else { clean }
	if name.len >= 2 && name[0] in [`'`, `"`] && name[name.len - 1] == name[0] {
		name = name[1..name.len - 1]
	}
	mut arg := if has_arg { trimmed_space(clean[colon + 1..]) } else { '' }
	if arg.len >= 3 && arg[0] == `r` && arg[1] in [`'`, `"`] && arg[arg.len - 1] == arg[1] {
		arg = arg[2..arg.len - 1]
	} else if arg.len >= 2 && arg[0] in [`'`, `"`] && arg[arg.len - 1] == arg[0] {
		arg = comptime_static_unescape(arg[1..arg.len - 1])
	}
	return ComptimeStaticValueCase{
		name:          name
		arg:           arg
		has_arg:       has_arg
		has_attr_meta: true
		attr_kind:     kind
	}
}

fn comptime_static_attr_is_string_literal(raw string) bool {
	return (raw.len >= 2 && raw[0] in [`'`, `"`] && raw[raw.len - 1] == raw[0])
		|| (raw.len >= 3 && raw[0] == `r` && raw[1] in [`'`, `"`] && raw[raw.len - 1] == raw[1])
}

fn (tc &TypeChecker) comptime_deferred_decl_source(source string, allow_type bool) ?ComptimeDeferredDeclSource {
	clean := trimmed_space(source)
	if clean.len == 0 {
		return none
	}
	if !clean.contains('.') {
		if allow_type {
			if resolved := tc.resolve_selective_import_type_symbol(clean) {
				return comptime_deferred_qualified_source(resolved)
			}
		}
		if resolved := tc.resolve_selective_import_symbol(clean) {
			return comptime_deferred_qualified_source(resolved)
		}
		return ComptimeDeferredDeclSource{
			module_name: if tc.cur_module.len > 0 { tc.cur_module } else { 'main' }
			decl_name:   clean
		}
	}
	dot := clean.index_u8(`.`)
	first := clean[..dot]
	if resolved := tc.resolve_import_alias(first) {
		return ComptimeDeferredDeclSource{
			module_name: resolved
			decl_name:   clean[dot + 1..]
		}
	}
	if first == tc.cur_module {
		return ComptimeDeferredDeclSource{
			module_name: first
			decl_name:   clean[dot + 1..]
		}
	}
	return ComptimeDeferredDeclSource{
		module_name: if tc.cur_module.len > 0 { tc.cur_module } else { 'main' }
		decl_name:   clean
	}
}

fn comptime_deferred_qualified_source(source string) ComptimeDeferredDeclSource {
	return ComptimeDeferredDeclSource{
		module_name: source.all_before_last('.')
		decl_name:   source.all_after_last('.')
	}
}

fn (mut tc TypeChecker) check_comptime_members(id flat.NodeId, var_name string, members []string, meta_name string) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .comptime_for {
		tc.check_comptime_for_members(id, node)
		if comptime_for_declares_var_in_value(node.value, var_name) {
			return
		}
	}
	if node.kind == .comptime_if {
		if member := comptime_cond_unknown_member(node.value, var_name, members) {
			tc.record_error(.unknown_field, 'unknown ${meta_name} member `${member}`', id)
		}
	}
	if node.kind == .selector && node.children_count > 0 {
		base_id := tc.a.child(&node, 0)
		if tc.valid_node_id(base_id) {
			base := tc.a.nodes[int(base_id)]
			if base.kind == .ident && base.value == var_name && node.value != '$'
				&& node.value !in members {
				tc.record_error(.unknown_field, 'unknown ${meta_name} member `${node.value}`', id)
			}
		}
	}
	for i in 0 .. node.children_count {
		tc.check_comptime_members(tc.a.child(&node, i), var_name, members, meta_name)
	}
}

fn comptime_for_declares_var_in_value(value string, var_name string) bool {
	if idx := value.index('|') {
		return value[..idx] == var_name
	}
	return value == var_name
}

fn comptime_cond_unknown_member(cond string, var_name string, members []string) ?string {
	prefix := '${var_name}.'
	mut offset := 0
	for offset < cond.len {
		if cond[offset] == `'` || cond[offset] == `"` {
			offset = comptime_cond_skip_string(cond, offset)
			continue
		}
		if offset + prefix.len > cond.len || cond[offset..offset + prefix.len] != prefix {
			offset++
			continue
		}
		if offset > 0 && comptime_cond_name_char(cond[offset - 1]) {
			offset++
			continue
		}
		member_start := offset + prefix.len
		mut member_end := member_start
		for member_end < cond.len && comptime_cond_name_char(cond[member_end]) {
			member_end++
		}
		if member_end == member_start {
			offset = member_start
			continue
		}
		member := cond[member_start..member_end]
		if member !in members {
			return member
		}
		offset = member_end
	}
	return none
}

fn comptime_cond_skip_string(cond string, start int) int {
	quote := cond[start]
	mut i := start + 1
	for i < cond.len {
		if cond[i] == `\\` {
			i += 2
			continue
		}
		if cond[i] == quote {
			return i + 1
		}
		i++
	}
	return cond.len
}

fn comptime_cond_name_char(ch u8) bool {
	return ch.is_letter() || ch.is_digit() || ch == `_`
}

fn (mut tc TypeChecker) check_comptime_static_body(id flat.NodeId, var_name string, loop_kind string, field_cases ComptimeStaticFieldCases, value_cases ComptimeStaticValueCases) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .block {
		// Locals registered while walking this block (declarations whose RHS
		// references the loop var) must not leak past it.
		tc.push_scope()
		for i in 0 .. node.children_count {
			tc.check_comptime_static_body(tc.a.child(&node, i), var_name, loop_kind, field_cases,
				value_cases)
		}
		tc.pop_scope()
		return
	}
	if node.kind == .comptime_for {
		return
	}
	if node.kind == .if_expr {
		for i in 0 .. node.children_count {
			tc.check_comptime_static_body(tc.a.child(&node, i), var_name, loop_kind, field_cases,
				value_cases)
		}
		return
	}
	if node.kind in [.expr_stmt, .return_stmt] {
		for i in 0 .. node.children_count {
			tc.check_comptime_static_body(tc.a.child(&node, i), var_name, loop_kind, field_cases,
				value_cases)
		}
		return
	}
	if node.kind == .comptime_if && comptime_text_references_var(node.value, var_name) {
		if loop_kind in ['methods', 'params', 'attributes'] {
			tc.check_comptime_static_deferred_metadata_if(node, var_name, loop_kind, field_cases,
				value_cases)
			return
		}
		tc.check_comptime_static_metadata_if(node, var_name, loop_kind, field_cases, value_cases)
		return
	}
	if node.kind == .defer_stmt && loop_kind == 'fields'
		&& tc.comptime_subtree_references_var(id, var_name) {
		tc.record_deferred_comptime_field_errors(id, var_name)
		return
	}
	if loop_kind == 'fields' && tc.check_comptime_static_field_selectors(id, var_name, field_cases) {
		return
	}
	if !tc.comptime_subtree_references_var(id, var_name) {
		tc.check_node(id)
		return
	}
	if node.kind in [.assign, .selector_assign, .index_assign] {
		tc.check_comptime_static_assignment(node, var_name, field_cases)
		return
	}
	if node.kind == .call {
		tc.check_comptime_static_call(id, node, var_name, loop_kind, field_cases, value_cases)
		return
	}
	// A declaration whose RHS references the loop var is not checked here, but
	// its locals must still enter the scope: later statements in the unrolled
	// body use them (`mut fo := ...(field.attrs); ... fo.install_default(...)`),
	// and without a binding those uses report unknown identifiers.
	if node.kind == .decl_assign && node.children_count >= 2 {
		for i := 0; i + 1 < int(node.children_count); i += 2 {
			lhs := tc.a.child_node(&node, i)
			if lhs.kind != .ident || lhs.value.len == 0 || lhs.value == '_' {
				continue
			}
			rhs_id := tc.a.child(&node, i + 1)
			rhs_typ := tc.resolve_type(rhs_id)
			typ := if rhs_typ is Unknown {
				tc.comptime_static_reflected_field_expr_type(rhs_id, var_name, field_cases) or {
					Type(Unknown{})
				}
			} else if rhs_typ is Void {
				Type(Unknown{})
			} else {
				rhs_typ
			}
			rhs := tc.a.node(rhs_id)
			if rhs.kind == .selector && rhs.value == '$' && unalias_type(typ) is Map {
				mut pos := rhs.pos
				if file := tc.a.source_files[rhs.pos.id] {
					if source := tc.source_texts_by_file[file.name] {
						start := int_max(0, rhs.pos.offset)
						end := int_min(source.len, rhs.pos.end)
						if start < end {
							if relative := source[start..end].index('.$(') {
								pos = token.new_span(rhs.pos.id, start + relative + 1, end)
							}
						}
					}
				}
				tc.record_error_at(.assignment_mismatch,
					'cannot copy map: call `move` or `clone` method (or use a reference)', rhs_id,
					pos)
			}
			tc.cur_scope.insert(lhs.value, typ)
		}
	}
}

fn (mut tc TypeChecker) record_deferred_comptime_field_errors(id flat.NodeId, var_name string) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind == .selector && node.value == '$' && node.children_count >= 2 {
		field_expr := tc.a.child_node(node, 1)
		if field_expr.kind == .selector && field_expr.value == 'name'
			&& field_expr.children_count > 0 {
			loop_var_id := tc.a.child(field_expr, 0)
			loop_var := tc.a.node(loop_var_id)
			if loop_var.kind == .ident && loop_var.value == var_name {
				pos := tc.node_value_diagnostic_pos(loop_var_id)
				tc.record_error_at(.unknown_field,
					'compile time field access can only be used when iterating over `T.fields`',
					loop_var_id, pos)
				tc.record_error_at(.unknown_ident, 'unknown `$for` variable `${var_name}`',
					loop_var_id, pos)
				return true
			}
		}
	}
	mut condition_has_error := false
	mut found := false
	for i in 0 .. node.children_count {
		child_id := tc.a.child(node, i)
		child_found := tc.record_deferred_comptime_field_errors(child_id, var_name)
		if node.kind == .if_expr && i == 0 && child_found {
			condition_has_error = true
		}
		found = found || child_found
	}
	if condition_has_error && node.children_count > 0 {
		condition_id := tc.a.child(node, 0)
		condition := tc.a.node(condition_id)
		mut pos := condition.pos
		if file := tc.a.source_files[condition.pos.id] {
			if source := tc.source_texts_by_file[file.name] {
				start := int_max(0, condition.pos.offset)
				end := int_min(source.len, condition.pos.end)
				if start < end {
					if relative := source[start..end].index('.$(') {
						pos = token.new_span(condition.pos.id, start + relative + 1, end)
					}
				}
			}
		}
		tc.record_error_at(.condition_mismatch, 'non-bool type `void` used as if condition',
			condition_id, pos)
	}
	return found
}

fn (mut tc TypeChecker) check_comptime_static_assignment(node flat.Node, var_name string, field_cases ComptimeStaticFieldCases) {
	if !field_cases.known || field_cases.cases.len == 0 || node.children_count < 2 {
		return
	}
	lhs_id := tc.a.child(&node, 0)
	lhs := tc.a.node(lhs_id)
	if lhs.kind != .selector || lhs.value != '$' || lhs.children_count < 2
		|| !tc.comptime_subtree_references_var(tc.a.child(lhs, 1), var_name) {
		return
	}
	rhs_id := tc.a.child(&node, 1)
	actual := tc.resolve_type(rhs_id)
	mut field_types := []string{}
	for field in field_cases.cases {
		if field.typ !in field_types {
			field_types << field.typ
		}
	}
	rhs := tc.a.node(rhs_id)
	if field_types.len > 1 && tc.comptime_initializer_is_static(rhs_id) {
		tc.record_error_at(.assignment_mismatch,
			'mismatched types: check field type with $if to avoid this problem', rhs_id, rhs.pos)
	}
	for field in field_cases.cases {
		expected := tc.parse_type(field.typ)
		if unalias_type(expected) is Enum {
			if !actual.is_integer() {
				tc.record_error_at(.assignment_mismatch, 'enums can only be assigned `int` values',
					rhs_id, rhs.pos)
				return
			}
		} else if actual !is Unknown && !tc.type_compatible(actual, expected) {
			diagnostic_pos := if rhs.kind == .index && rhs.children_count > 0 {
				base := tc.a.child_node(rhs, 0)
				token.new_span(rhs.pos.id, base.pos.end, rhs.pos.end)
			} else {
				rhs.pos
			}
			actual_name := tc.diagnostic_expr_type_name(rhs_id, actual)
			tc.record_error_at(.assignment_mismatch,
				'cannot assign to `${tc.source_text_for_node(lhs_id)}`: expected `${expected.name()}`, not `${actual_name}`',
				rhs_id, diagnostic_pos)
			return
		}
	}
}

fn (mut tc TypeChecker) check_comptime_static_field_selectors(id flat.NodeId, var_name string, field_cases ComptimeStaticFieldCases) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind == .selector && node.value == '$' {
		return tc.check_comptime_field_selector(id, *node, var_name, field_cases)
	}
	mut found_error := false
	for i in 0 .. node.children_count {
		if tc.check_comptime_static_field_selectors(tc.a.child(node, i), var_name, field_cases) {
			found_error = true
		}
	}
	return found_error
}

fn (mut tc TypeChecker) check_comptime_field_selector(id flat.NodeId, node flat.Node, loop_var string, field_cases ComptimeStaticFieldCases) bool {
	if node.children_count < 2 {
		tc.register_synth_type(id, Type(void_))
		return true
	}
	field_expr_id := tc.a.child(&node, 1)
	field_expr := tc.a.node(field_expr_id)
	if field_expr.kind != .selector {
		actual_name := if field_expr.kind == .ident && field_expr.value == loop_var
			&& loop_var.len > 0 {
			'FieldData'
		} else {
			tc.check_node(field_expr_id)
			tc.resolve_type(field_expr_id).name()
		}
		if actual_name != 'string' {
			tc.record_error_at(.unknown_field,
				'expected `string` instead of `${actual_name}` (e.g. `field.name`)', field_expr_id,
				field_expr.pos)
		}
		tc.record_error_at(.unknown_field, 'expected selector expression e.g. `$(field.name)`',
			field_expr_id, field_expr.pos)
		if loop_var.len == 0 {
			tc.record_invalid_comptime_selector_source_assignment(id, node)
		}
		tc.register_synth_type(id, Type(void_))
		return true
	}
	if field_expr.children_count == 0 {
		tc.register_synth_type(id, Type(void_))
		return true
	}
	field_var_id := tc.a.child(field_expr, 0)
	field_var := tc.a.node(field_var_id)
	field_var_name := tc.source_text_for_node(field_var_id)
	if loop_var.len == 0 || field_var.kind != .ident || field_var.value != loop_var {
		tc.check_node(field_expr_id)
		mut field_expr_type := tc.resolve_type(field_expr_id)
		if loop_var.len == 0 && field_var.kind == .ident
			&& tc.cur_scope.lookup(field_var.value) == none {
			tc.record_error_at(.unknown_field, '`${field_var.value}` does not return a value',
				field_expr_id, tc.node_value_diagnostic_pos(field_expr_id))
			field_expr_type = Type(void_)
		}
		if field_expr_type !is String {
			tc.record_error_at(.unknown_field,
				'expected `string` instead of `${field_expr_type.name()}` (e.g. `field.name`)',
				field_expr_id, tc.node_value_diagnostic_pos(field_expr_id))
		}
		if loop_var.len == 0 {
			tc.record_error_at(.unknown_field,
				'compile time field access can only be used when iterating over `T.fields`',
				field_var_id, field_var.pos)
		}
		tc.record_error_at(.unknown_ident, 'unknown `$for` variable `${field_var_name}`',
			field_var_id, field_var.pos)
		tc.register_synth_type(id, Type(void_))
		return true
	}
	if field_expr.value != 'name' {
		tc.check_node(field_expr_id)
		actual := tc.resolve_type(field_expr_id)
		if actual !is String {
			tc.record_error_at(.unknown_field,
				'expected `string` instead of `${actual.name()}` (e.g. `field.name`)',
				field_expr_id, tc.node_value_diagnostic_pos(field_expr_id))
			tc.register_synth_type(id, Type(void_))
			return true
		}
	}
	if field_cases.known && field_cases.cases.len > 0 {
		receiver_id := tc.a.child(&node, 0)
		receiver_type := unalias_type(unwrap_pointer(tc.resolve_type(receiver_id)))
		for field in field_cases.cases {
			has_field := receiver_type is Struct
				&& tc.struct_field_type(receiver_type.name, field.name) != none
			if !has_field {
				tc.record_error_severity_at(.unknown_field,
					'`${tc.source_text_for_node(receiver_id)}` has no field named `${field.name}`',
					receiver_id, tc.a.node(receiver_id).pos, 'cgen error:')
				tc.register_synth_type(id, unknown_type('unknown imported enum'))
				return true
			}
		}
	}
	return false
}

fn (mut tc TypeChecker) record_invalid_comptime_selector_source_assignment(id flat.NodeId, node flat.Node) {
	file := tc.a.source_files[node.pos.id] or { return }
	source := tc.source_texts_by_file[file.name] or { return }
	mut cursor := int_max(0, int_min(node.pos.end, source.len))
	for cursor < source.len && source[cursor] in [` `, `\t`] {
		cursor++
	}
	if cursor >= source.len || source[cursor] != `=`
		|| (cursor + 1 < source.len && source[cursor + 1] == `=`) {
		return
	}
	cursor++
	for cursor < source.len && source[cursor] in [` `, `\t`] {
		cursor++
	}
	if cursor >= source.len || source[cursor] !in [`'`, `"`] {
		return
	}
	quote := source[cursor]
	mut end := cursor + 1
	for end < source.len && source[end] != quote && source[end] != `\n` {
		if source[end] == `\\` && end + 1 < source.len {
			end++
		}
		end++
	}
	if end < source.len && source[end] == quote {
		end++
	}
	tc.record_error_at(.assignment_mismatch,
		'cannot assign to `${tc.source_text_for_node(id)}`: expected `void`, not `string`', id, token.new_span(node.pos.id,
		cursor, end))
}

fn (tc &TypeChecker) comptime_static_reflected_field_expr_type(id flat.NodeId, var_name string, field_cases ComptimeStaticFieldCases) ?Type {
	if !tc.valid_node_id(id) || !field_cases.known || field_cases.cases.len == 0 {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .paren && node.children_count > 0 {
		return tc.comptime_static_reflected_field_expr_type(tc.a.child(&node, 0), var_name,
			field_cases)
	}
	if node.kind == .call && node.children_count == 1 {
		callee := tc.a.child_node(&node, 0)
		if callee.kind == .selector && callee.value == 'clone' && callee.children_count > 0 {
			return tc.comptime_static_reflected_field_expr_type(tc.a.child(callee, 0), var_name,
				field_cases)
		}
	}
	if node.kind != .selector || node.value != '$' || node.children_count < 2
		|| !tc.comptime_subtree_references_var(tc.a.child(&node, 1), var_name) {
		return none
	}
	first := field_cases.cases[0].typ
	for field in field_cases.cases[1..] {
		if field.typ != first {
			return none
		}
	}
	return tc.parse_type(first)
}

fn (mut tc TypeChecker) check_comptime_static_deferred_metadata_if(node flat.Node, var_name string, loop_kind string, field_cases ComptimeStaticFieldCases, value_cases ComptimeStaticValueCases) {
	if !value_cases.known {
		return
	}
	mut check_then := false
	mut check_else := false
	for item in value_cases.cases {
		cond := comptime_static_subst_deferred_cond(node.value, var_name, loop_kind, item)
		if comptime_text_references_var(cond, var_name) {
			continue
		}
		taken := tc.comptime_static_eval_field_cond(cond) or { continue }
		if taken {
			check_then = true
		} else {
			check_else = true
		}
	}
	if check_then && node.children_count > 0 {
		tc.check_comptime_static_body(tc.a.child(&node, 0), var_name, loop_kind, field_cases,
			value_cases)
	}
	if check_else && node.children_count > 1 {
		tc.check_comptime_static_body(tc.a.child(&node, 1), var_name, loop_kind, field_cases,
			value_cases)
	}
}

fn comptime_static_subst_deferred_cond(cond string, var_name string, loop_kind string, item ComptimeStaticValueCase) string {
	mut result := comptime_static_replace_unquoted(cond, '${var_name}.name',
		comptime_static_string_literal(item.name))
	if loop_kind == 'methods' {
		result = comptime_static_subst_method_param_cond(result, var_name, item)
		result = comptime_static_replace_unquoted(result, '${var_name}.args.len',
			item.param_names.len.str())
		result = comptime_static_replace_unquoted(result, '${var_name}.params.len',
			item.param_names.len.str())
		result = comptime_static_replace_unquoted(result, '${var_name}.location',
			comptime_static_string_literal(item.location))
		result = comptime_static_replace_unquoted(result, '${var_name}.return_type',
			comptime_static_deferred_type(item.return_type))
		result = comptime_static_replace_unquoted(result, '${var_name}.typ', item.typ)
		if item.has_is_pub {
			result = comptime_static_replace_unquoted(result, '${var_name}.is_pub',
				item.is_pub.str())
		}
	} else if loop_kind == 'params' {
		result = comptime_static_replace_unquoted(result, '${var_name}.typ',
			comptime_static_deferred_type(item.typ))
	} else if loop_kind == 'attributes' && item.has_attr_meta {
		result = comptime_static_replace_unquoted(result, '${var_name}.has_arg', item.has_arg.str())
		result = comptime_static_replace_unquoted(result, '${var_name}.arg',
			comptime_static_string_literal(item.arg))
		kind := comptime_static_attribute_kind_value(item.attr_kind)
		result = comptime_static_replace_unquoted(result, '${var_name}.kind ==.', '${kind} == .')
		result = comptime_static_replace_unquoted(result, '${var_name}.kind !=.', '${kind} != .')
		result = comptime_static_replace_unquoted(result, '${var_name}.kind', kind)
	}
	return result
}

fn comptime_static_subst_method_param_cond(cond string, var_name string, item ComptimeStaticValueCase) string {
	mut result := cond
	for collection in ['args', 'params'] {
		prefix := '${var_name}.${collection}['
		mut offset := 0
		for offset < result.len {
			if result[offset] == `'` || result[offset] == `"` {
				offset = comptime_cond_skip_string(result, offset)
				continue
			}
			if !result[offset..].starts_with(prefix)
				|| (offset > 0 && comptime_cond_name_char(result[offset - 1])) {
				offset++
				continue
			}
			start := offset
			index_start := start + prefix.len
			rel_end := result[index_start..].index_u8(`]`)
			if rel_end < 0 {
				break
			}
			index_end := index_start + rel_end
			member_start := index_end + 1
			member := if result[member_start..].starts_with('.typ') {
				'typ'
			} else if result[member_start..].starts_with('.name') {
				'name'
			} else {
				''
			}
			member_end := member_start + member.len + 1
			if member.len == 0
				|| (member_end < result.len && comptime_cond_name_char(result[member_end])) {
				offset = member_start
				continue
			}
			index_text := trimmed_space(result[index_start..index_end])
			if !comptime_static_is_int(index_text) || index_text.starts_with('-') {
				offset = member_end
				continue
			}
			index := index_text.int()
			replacement := if index >= 0 && index < item.param_names.len {
				if member == 'name' {
					comptime_static_string_literal(item.param_names[index])
				} else if index < item.param_types.len {
					comptime_static_deferred_type(item.param_types[index])
				} else {
					'__v3_missing_method_param_type'
				}
			} else if member == 'name' {
				"''"
			} else {
				'__v3_missing_method_param_type'
			}
			result = result[..start] + replacement + result[member_end..]
			offset = start + replacement.len
		}
	}
	return result
}

fn comptime_static_deferred_type(typ string) string {
	return if typ == '&void' { 'voidptr' } else { typ }
}

fn comptime_static_attribute_kind_value(kind int) string {
	return match kind {
		1 { '.string' }
		2 { '.number' }
		3 { '.bool' }
		4 { '.comptime_define' }
		else { '.plain' }
	}
}

fn comptime_static_replace_unquoted(cond string, needle string, replacement string) string {
	if needle.len == 0 || !cond.contains(needle) {
		return cond
	}
	mut out := ''
	mut offset := 0
	for offset < cond.len {
		if cond[offset] == `'` || cond[offset] == `"` {
			end := comptime_cond_skip_string(cond, offset)
			out += cond[offset..end]
			offset = end
			continue
		}
		if offset + needle.len <= cond.len && cond[offset..offset + needle.len] == needle {
			before_ok := !comptime_cond_name_char(needle[0]) || offset == 0
				|| !comptime_cond_name_char(cond[offset - 1])
			after := offset + needle.len
			after_ok := !comptime_cond_name_char(needle[needle.len - 1]) || after >= cond.len
				|| !comptime_cond_name_char(cond[after])
			if before_ok && after_ok {
				out += replacement
				offset = after
				continue
			}
		}
		out += cond[offset..offset + 1]
		offset++
	}
	return out
}

fn (mut tc TypeChecker) check_comptime_static_metadata_if(node flat.Node, var_name string, loop_kind string, field_cases ComptimeStaticFieldCases, value_cases ComptimeStaticValueCases) {
	if loop_kind == 'values' {
		tc.check_comptime_static_value_metadata_if(node, var_name, loop_kind, field_cases,
			value_cases)
		return
	}
	if !field_cases.known {
		for i in 0 .. node.children_count {
			tc.check_comptime_static_body(tc.a.child(&node, i), var_name, loop_kind, field_cases,
				value_cases)
		}
		return
	}
	mut then_cases := []ComptimeStaticFieldCase{}
	mut else_cases := []ComptimeStaticFieldCase{}
	for f in field_cases.cases {
		cond := tc.comptime_static_subst_field_cond(node.value, var_name, f)
		if comptime_text_references_var(cond, var_name) {
			then_cases << f
			else_cases << f
			continue
		}
		taken := tc.comptime_static_eval_field_cond(cond) or {
			then_cases << f
			else_cases << f
			continue
		}
		if taken {
			then_cases << f
		} else {
			else_cases << f
		}
	}
	if then_cases.len > 0 && node.children_count > 0 {
		tc.check_comptime_static_body(tc.a.child(&node, 0), var_name, loop_kind, ComptimeStaticFieldCases{
			known: true
			cases: then_cases
		}, value_cases)
	}
	if else_cases.len > 0 && node.children_count > 1 {
		tc.check_comptime_static_body(tc.a.child(&node, 1), var_name, loop_kind, ComptimeStaticFieldCases{
			known: true
			cases: else_cases
		}, value_cases)
	}
}

fn (mut tc TypeChecker) check_comptime_static_value_metadata_if(node flat.Node, var_name string, loop_kind string, field_cases ComptimeStaticFieldCases, value_cases ComptimeStaticValueCases) {
	if !value_cases.known {
		for i in 0 .. node.children_count {
			tc.check_comptime_static_body(tc.a.child(&node, i), var_name, loop_kind, field_cases,
				value_cases)
		}
		return
	}
	mut check_then := false
	mut check_else := false
	for item in value_cases.cases {
		cond := comptime_static_subst_value_cond(node.value, var_name, item)
		if comptime_text_references_var(cond, var_name) {
			check_then = true
			check_else = true
			continue
		}
		taken := tc.comptime_static_eval_field_cond(cond) or {
			check_then = true
			check_else = true
			continue
		}
		if taken {
			check_then = true
		} else {
			check_else = true
		}
	}
	if check_then && node.children_count > 0 {
		tc.check_comptime_static_body(tc.a.child(&node, 0), var_name, loop_kind, field_cases,
			value_cases)
	}
	if check_else && node.children_count > 1 {
		tc.check_comptime_static_body(tc.a.child(&node, 1), var_name, loop_kind, field_cases,
			value_cases)
	}
}

fn (tc &TypeChecker) comptime_subtree_references_var(id flat.NodeId, var_name string) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .comptime_for && comptime_for_declares_var_in_value(node.value, var_name) {
		return false
	}
	if node.kind == .ident && node.value == var_name {
		return true
	}
	if node.kind == .comptime_if && comptime_text_references_var(node.value, var_name) {
		return true
	}
	for i in 0 .. node.children_count {
		if tc.comptime_subtree_references_var(tc.a.child(&node, i), var_name) {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) check_comptime_static_call(id flat.NodeId, node flat.Node, var_name string, loop_kind string, field_cases ComptimeStaticFieldCases, value_cases ComptimeStaticValueCases) {
	if node.children_count == 0 {
		return
	}
	callee_id := tc.a.child(&node, 0)
	if loop_kind == 'methods' && tc.comptime_static_is_method_var_call(node, var_name) {
		tc.check_comptime_static_call_args(node, var_name, loop_kind, field_cases, value_cases)
		tc.check_comptime_static_method_var_call(id, node, value_cases)
		return
	}
	callee_node := tc.a.child_node(&node, 0)
	if loop_kind == 'methods' && callee_node.kind == .ident
		&& callee_node.value in ['print', 'println', 'eprint', 'eprintln']
		&& node.children_count > 1
		&& tc.comptime_static_expr_has_void_method_call(tc.call_arg_value(tc.a.child(&node, 1)), var_name, value_cases) {
		tc.check_comptime_static_call_args(node, var_name, loop_kind, field_cases, value_cases)
		tc.record_error_at(.call_arg_mismatch,
			'`${callee_node.value}` can not print void expressions', id, node.pos)
		return
	}
	if tc.comptime_subtree_references_var(callee_id, var_name) {
		tc.check_comptime_static_call_args(node, var_name, loop_kind, field_cases, value_cases)
		return
	}
	if _ := tc.sum_constructor_call_name(node) {
		tc.check_comptime_static_call_args(node, var_name, loop_kind, field_cases, value_cases)
		return
	}
	if info0 := tc.resolve_call_info(id, node) {
		if tc.record_empty_array_generic_call_errors(node, info0) {
			return
		}
		info := tc.specialized_plain_generic_call_info(node, info0)
		if info.name in tc.a.disabled_fns || tc.canonical_symbol(info.name) in tc.a.disabled_fns
			|| info.name in tc.source_no_body_fns {
			mut callee := tc.a.child_node(&node, 0)
			if callee.kind == .index && callee.children_count > 0 {
				callee = tc.a.child_node(callee, 0)
			}
			if callee.kind == .selector {
				name_pos := tc.method_call_name_pos(node, callee)
				tc.record_error_at(.unknown_fn, 'cannot call a method that does not have a body',
					id, token.new_span(name_pos.id, name_pos.offset, node.pos.end))
			} else {
				tc.record_error_at(.unknown_fn, 'cannot call a function that does not have a body',
					id, node.pos)
			}
			return
		}
		if info.name.len > 0 && !is_array_dsl_call_name(info.name) {
			tc.remember_resolved_call(id, info.name)
		}
		if info.return_type !is Void && info.return_type !is Unknown {
			tc.remember_expr_type(id, info.return_type)
		}
		tc.check_comptime_static_call_metadata_arg_types(id, node, info, var_name, loop_kind)
		tc.check_comptime_static_call_args(node, var_name, loop_kind, field_cases, value_cases)
		return
	}
	if tc.is_unsupported_hex_call(node) {
		if tc.should_diagnose(id) {
			tc.record_error(.unknown_fn, 'unknown function: ${tc.call_display_name(node)}', id)
		}
		return
	}
	if tc.call_has_ambiguous_selective_import(node) {
		tc.record_error(.unknown_fn, 'ambiguous selective import `${tc.call_display_name(node)}`',
			id)
		return
	}
	if tc.should_diagnose(id) && !tc.is_known_call(node)
		&& !tc.call_generic_args_have_placeholders(node) {
		tc.record_error(.unknown_fn, 'unknown function: ${tc.call_display_name(node)}', id)
	}
	tc.check_comptime_static_call_args(node, var_name, loop_kind, field_cases, value_cases)
}

fn (tc &TypeChecker) comptime_static_is_method_var_call(node flat.Node, var_name string) bool {
	if node.kind != .call || node.children_count == 0 {
		return false
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind != .selector || callee.value != '$' || callee.children_count < 2 {
		return false
	}
	method_name := tc.a.child_node(callee, 1)
	return method_name.kind == .ident && method_name.value == var_name
}

fn (tc &TypeChecker) comptime_static_expr_has_void_method_call(id flat.NodeId, var_name string, value_cases ComptimeStaticValueCases) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if tc.comptime_static_is_method_var_call(*node, var_name) {
		return value_cases.cases.any(it.return_type.len == 0 || it.return_type == 'void')
	}
	if node.kind == .paren && node.children_count > 0 {
		return tc.comptime_static_expr_has_void_method_call(tc.a.child(node, 0), var_name,
			value_cases)
	}
	return false
}

fn (mut tc TypeChecker) check_comptime_static_method_var_call(id flat.NodeId, node flat.Node, value_cases ComptimeStaticValueCases) {
	if !value_cases.known || value_cases.cases.len == 0 || node.children_count == 0 {
		return
	}
	callee := tc.a.child_node(&node, 0)
	if callee.children_count == 0 {
		return
	}
	receiver_id := tc.a.child(callee, 0)
	receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(receiver_id))
	receiver_name := receiver_type.name()
	actual_count := int(node.children_count) - 1
	for method in value_cases.cases {
		if actual_count != method.param_types.len {
			mut pos := node.pos
			if file := tc.a.source_files[node.pos.id] {
				if source := tc.source_texts_by_file[file.name] {
					start := int_max(0, node.pos.offset)
					end := int_min(source.len, node.pos.end)
					if start < end {
						if relative := source[start..end].index('.$') {
							pos = token.new_span(node.pos.id, start + relative + 1, end)
						}
					}
				}
			}
			tc.record_error_severity_at(.call_arg_mismatch,
				'expected ${method.param_types.len} arguments to method ${receiver_name}.${method.name}, but got ${actual_count}',
				id, pos, 'cgen error:')
			return
		}
		for arg_index in 0 .. actual_count {
			raw_arg_id := tc.a.child(&node, arg_index + 1)
			raw_arg := tc.a.child_node(&node, arg_index + 1)
			arg_id := tc.call_arg_value(raw_arg_id)
			actual := tc.resolve_type(arg_id)
			if raw_arg.kind != .prefix && unalias_type(actual).name() == '[]string' {
				tc.record_error_at(.call_arg_mismatch,
					'to auto-expand `[]string` arguments in comptime method calls, use `...${tc.source_text_for_node(arg_id)}`',
					arg_id, tc.a.node(arg_id).pos)
				return
			}
			if arg_index < method.param_is_mut.len && method.param_is_mut[arg_index]
				&& tc.a.node(arg_id).is_mut && arg_index < method.param_types.len
				&& method.param_types[arg_index].starts_with('&') {
				expected_name := '&${method.param_types[arg_index]}'
				actual_name := actual.name()
				tc.record_error_at(.call_arg_mismatch, 'cannot use `${actual_name}` as `${expected_name}` in argument ${
					arg_index + 1} to `${receiver_name}.${method.name}`', arg_id,
					tc.a.node(arg_id).pos)
				return
			}
		}
	}
}

fn (mut tc TypeChecker) check_comptime_static_call_metadata_arg_types(id flat.NodeId, node flat.Node, info CallInfo, var_name string, loop_kind string) {
	if !info.params_known {
		return
	}
	mut field_init_args := 0
	for i in 1 .. node.children_count {
		if tc.a.child_node(&node, i).kind == .field_init {
			field_init_args++
		}
	}
	collapsed := if field_init_args > 0 { 1 } else { 0 }
	recv_extra := if info.has_receiver { 1 } else { 0 }
	mut actual_count := node.children_count - 1 - info.arg_offset - field_init_args + collapsed +
		recv_extra
	ctx_count := if info.has_implicit_veb_ctx { 1 } else { 0 }
	ctx_omitted := ctx_count > 0 && actual_count < info.params.len
	for i in 1 + info.arg_offset .. node.children_count {
		raw_arg := tc.a.child_node(&node, i)
		if raw_arg.kind == .field_init {
			continue
		}
		arg_shift := if ctx_omitted { ctx_count } else { 0 }
		param_idx := i - 1 - info.arg_offset + (if info.has_receiver { 1 } else { 0 }) + arg_shift
		if info.is_c_variadic && param_idx >= c_variadic_fixed_param_count(info) {
			continue
		}
		if param_idx >= info.params.len {
			continue
		}
		arg_id := tc.call_arg_value(tc.a.child(&node, i))
		actual := tc.comptime_static_metadata_expr_type(arg_id, var_name, loop_kind) or { continue }
		expected := tc.call_arg_expected_type(info, param_idx)
		if !tc.receiver_compatible(actual, expected) && !tc.type_compatible(actual, expected) {
			if expected is Pointer && tc.expr_tail_is_nil(arg_id) {
				continue
			}
			if voidptr_arg_compatible(expected, actual) {
				continue
			}
			// A `voidptr`/`&void` argument is accepted where a function-pointer type
			// is expected (e.g. a `map[string]EasingFN` whose first literal element is
			// `voidptr(fn)`, making the map value type `voidptr`). voidptr and function
			// pointers are interchangeable in C; matches v1.
			if is_fn_pointer_type(expected) && fn_param_is_voidptr_type(actual) {
				continue
			}
			if !info.name.starts_with('C.') && fn_param_is_voidptr_type(expected)
				&& tc.expr_can_take_address(arg_id) {
				continue
			}
			if fn_param_is_voidptr_type(expected) && info.name.ends_with('Channel.push') {
				continue
			}
			tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual.name()}` as argument ${
				param_idx + 1} to `${tc.call_display_name(node)}`; expected `${expected.name()}`',
				id)
		}
	}
}

fn (tc &TypeChecker) comptime_static_metadata_expr_type(id flat.NodeId, var_name string, loop_kind string) ?Type {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .paren && node.children_count > 0 {
		return tc.comptime_static_metadata_expr_type(tc.a.child(&node, 0), var_name, loop_kind)
	}
	if node.kind == .ident && node.value == var_name {
		metadata_type := match loop_kind {
			'methods' { 'FunctionData' }
			'params' { 'FunctionParam' }
			'attributes' { 'VAttribute' }
			'values' { 'EnumData' }
			'variants' { 'VariantData' }
			else { 'FieldData' }
		}

		return tc.parse_type(metadata_type)
	}
	if node.kind == .selector && node.children_count > 0 {
		base := tc.a.child_node(&node, 0)
		if base.kind == .ident && base.value == var_name {
			return tc.comptime_static_metadata_member_type(node.value, loop_kind)
		}
	}
	return none
}

fn (tc &TypeChecker) comptime_static_metadata_member_type(member string, loop_kind string) ?Type {
	if loop_kind == 'methods' {
		return match member {
			'name', 'location' {
				tc.parse_type('string')
			}
			'is_pub' {
				tc.parse_type('bool')
			}
			'return_type', 'typ' {
				tc.parse_type('int')
			}
			'args', 'params' {
				tc.parse_type('[]FunctionParam')
			}
			'attrs' {
				tc.parse_type('[]string')
			}
			'attributes' {
				tc.parse_type('[]VAttribute')
			}
			else {
				none
			}
		}
	}
	if loop_kind == 'params' {
		return match member {
			'name' {
				tc.parse_type('string')
			}
			'typ' {
				tc.parse_type('int')
			}
			else {
				none
			}
		}
	}
	if loop_kind == 'attributes' {
		return match member {
			'name', 'arg' {
				tc.parse_type('string')
			}
			'has_arg' {
				tc.parse_type('bool')
			}
			'kind' {
				tc.parse_type('AttributeKind')
			}
			else {
				none
			}
		}
	}
	if loop_kind == 'variants' {
		return match member {
			'typ' {
				tc.parse_type('int')
			}
			else {
				none
			}
		}
	}
	if loop_kind == 'values' {
		return match member {
			'name' {
				tc.parse_type('string')
			}
			'value' {
				tc.parse_type('i64')
			}
			'attrs' {
				tc.parse_type('[]string')
			}
			else {
				none
			}
		}
	}
	return match member {
		'name' {
			tc.parse_type('string')
		}
		'typ', 'unaliased_typ' {
			tc.parse_type('int')
		}
		'attrs' {
			tc.parse_type('[]string')
		}
		'indirections' {
			tc.parse_type('u8')
		}
		'is_option', 'is_opt', 'is_embed', 'is_array', 'is_map', 'is_chan', 'is_struct', 'is_enum',
		'is_alias', 'is_shared', 'is_atomic', 'is_mut', 'is_pub' {
			tc.parse_type('bool')
		}
		else {
			none
		}
	}
}

fn (mut tc TypeChecker) check_comptime_static_call_args(node flat.Node, var_name string, loop_kind string, field_cases ComptimeStaticFieldCases, value_cases ComptimeStaticValueCases) {
	for i in 1 .. node.children_count {
		tc.check_comptime_static_body(tc.call_arg_value(tc.a.child(&node, i)), var_name, loop_kind,
			field_cases, value_cases)
	}
}

fn (mut tc TypeChecker) comptime_static_enum_value_cases(base_type string) ComptimeStaticValueCases {
	source_type := tc.comptime_static_for_base_type(base_type)
	enum_name := tc.comptime_static_enum_name(source_type) or { return ComptimeStaticValueCases{} }
	names := tc.enum_fields[enum_name] or { return ComptimeStaticValueCases{
		known: true
	} }
	metas := tc.comptime_static_enum_decl_value_cases(enum_name)
	if metas.len > 0 {
		return ComptimeStaticValueCases{
			known: true
			cases: metas
		}
	}
	mut cases := []ComptimeStaticValueCase{cap: names.len}
	is_flag := enum_name in tc.flag_enums
	for idx, name in names {
		cases << ComptimeStaticValueCase{
			name:      name
			value:     if is_flag { 1 << idx } else { idx }
			has_value: true
		}
	}
	return ComptimeStaticValueCases{
		known: true
		cases: cases
	}
}

fn (tc &TypeChecker) comptime_static_enum_name(raw string) ?string {
	mut cur := trimmed_space(raw)
	mut seen := map[string]bool{}
	for cur.len > 0 && cur !in seen {
		seen[cur] = true
		mut candidates := [cur, tc.qualify_name(cur)]
		if resolved := tc.resolve_selective_import_type_symbol(cur) {
			candidates << resolved
		}
		for candidate in candidates {
			if candidate in tc.enum_names {
				return candidate
			}
		}
		next := tc.alias_target_type_text(cur) or { break }
		if next == cur {
			break
		}
		cur = trimmed_space(next)
	}
	return none
}

fn comptime_static_subst_value_cond(cond string, var_name string, item ComptimeStaticValueCase) string {
	mut c := cond
	if item.has_value {
		c = c.replace('${var_name}.value', item.value.str())
	}
	c = c.replace('${var_name}.name', "'${item.name}'")
	c = comptime_static_replace_bare_ident(c, var_name, 'EnumData')
	return c
}

fn comptime_text_references_member(cond string, var_name string) bool {
	prefix := '${var_name}.'
	mut offset := 0
	for offset < cond.len {
		if cond[offset] == `'` || cond[offset] == `"` {
			offset = comptime_cond_skip_string(cond, offset)
			continue
		}
		if offset + prefix.len > cond.len || cond[offset..offset + prefix.len] != prefix {
			offset++
			continue
		}
		if offset > 0 && comptime_cond_name_char(cond[offset - 1]) {
			offset++
			continue
		}
		member_start := offset + prefix.len
		if member_start < cond.len && comptime_cond_name_char(cond[member_start]) {
			return true
		}
		offset = member_start
	}
	return false
}

fn comptime_text_references_var(cond string, var_name string) bool {
	if var_name.len == 0 {
		return false
	}
	mut offset := 0
	for offset < cond.len {
		if cond[offset] == `'` || cond[offset] == `"` {
			offset = comptime_cond_skip_string(cond, offset)
			continue
		}
		if offset + var_name.len <= cond.len && cond[offset..offset + var_name.len] == var_name {
			before_ok := offset == 0 || !comptime_cond_name_char(cond[offset - 1])
			after := offset + var_name.len
			after_ok := after >= cond.len || !comptime_cond_name_char(cond[after])
			if before_ok && after_ok {
				return true
			}
		}
		offset++
	}
	return false
}

fn (mut tc TypeChecker) comptime_static_field_cases(base_type string) ComptimeStaticFieldCases {
	source_type := tc.comptime_static_for_base_type(base_type)
	struct_name := tc.comptime_static_struct_name(source_type) or {
		return ComptimeStaticFieldCases{}
	}
	fields := tc.structs[struct_name] or { return ComptimeStaticFieldCases{
		known: true
	} }
	decl_metas := tc.comptime_static_field_decl_metas(struct_name)
	mut cases := []ComptimeStaticFieldCase{cap: fields.len}
	for field in fields {
		typ := field.typ.name()
		unaliased_typ := tc.comptime_type_match_type(typ).name()
		core_type := comptime_static_unwrap_field_type(field.typ)
		decl_meta := decl_metas[field.name] or { ComptimeStaticFieldDeclMeta{} }
		raw_typ := if decl_meta.raw_typ.len > 0 { decl_meta.raw_typ } else { typ }
		type_flags := comptime_static_field_type_flags(raw_typ)
		cases << ComptimeStaticFieldCase{
			name:          field.name
			typ:           typ
			unaliased_typ: unaliased_typ
			is_option:     field.typ is OptionType || tc.comptime_type_match_type(typ) is OptionType
			is_embed:      decl_meta.is_embed
			is_array:      core_type is Array || core_type is ArrayFixed
			is_map:        core_type is Map
			is_chan:       core_type is Channel
			is_struct:     tc.comptime_static_type_is_struct(core_type, typ, raw_typ)
			is_enum:       core_type is Enum && core_type.name() in tc.enum_names
			is_alias:      field.typ is Alias || typ in tc.type_aliases
				|| tc.qualify_name(typ) in tc.type_aliases
			is_shared:     type_flags.is_shared
			is_atomic:     type_flags.is_atomic
			is_mut:        decl_meta.is_mut
			is_pub:        decl_meta.is_pub
			has_decl_meta: field.name in decl_metas
			indirections:  type_flags.indirections
		}
	}
	return ComptimeStaticFieldCases{
		known: true
		cases: cases
	}
}

fn (tc &TypeChecker) comptime_static_type_is_struct(typ Type, typ_name string, raw_typ string) bool {
	if typ is Struct && tc.comptime_static_type_name_is_struct(typ.name()) {
		return true
	}
	if tc.comptime_static_type_name_is_struct(typ_name) {
		return true
	}
	return tc.comptime_static_type_name_is_struct(raw_typ)
}

fn (tc &TypeChecker) comptime_static_type_name_is_struct(name string) bool {
	clean := comptime_static_unwrap_type_text(name)
	if clean.len == 0 {
		return false
	}
	if clean in tc.structs {
		return true
	}
	base, _, is_generic := generic_type_application_parts(clean)
	if !is_generic {
		return false
	}
	if base in tc.structs || base in tc.struct_generic_params {
		return true
	}
	qbase := tc.qualify_name(base)
	if qbase in tc.structs || qbase in tc.struct_generic_params {
		return true
	}
	if resolved := tc.resolve_selective_import_type_symbol(base) {
		return resolved in tc.structs || resolved in tc.struct_generic_params
	}
	return false
}

fn comptime_static_unwrap_type_text(name string) string {
	mut clean := trimmed_space(name)
	for _ in 0 .. 16 {
		if clean.starts_with('?') || clean.starts_with('!') {
			clean = trimmed_space(clean[1..])
			continue
		}
		if clean.starts_with('shared ') {
			clean = trimmed_space(clean[7..])
			continue
		}
		if clean.starts_with('atomic ') {
			clean = trimmed_space(clean[7..])
			continue
		}
		if clean.starts_with('&') {
			clean = trimmed_space(clean[1..])
			continue
		}
		break
	}
	return clean
}

fn (tc &TypeChecker) comptime_static_for_base_type(raw string) string {
	if source := tc.comptime_static_for_value_source_type(raw) {
		return source
	}
	return raw
}

fn (tc &TypeChecker) comptime_static_for_value_source_type(raw string) ?string {
	clean := trimmed_space(raw)
	if clean.len == 0 {
		return none
	}
	parts := clean.split('.')
	if parts.len == 0 {
		return none
	}
	mut typ := tc.comptime_static_for_var_source_type(parts[0]) or { return none }
	for field in parts[1..] {
		typ = tc.comptime_static_for_field_source_type(typ, field) or { return none }
	}
	return typ
}

fn (tc &TypeChecker) comptime_static_for_var_source_type(name string) ?string {
	if tc.cur_scope != unsafe { nil } {
		if typ := tc.cur_scope.lookup(name) {
			return comptime_static_source_type_name(typ)
		}
	}
	if tc.file_scope != unsafe { nil } {
		if typ := tc.file_scope.lookup(name) {
			return comptime_static_source_type_name(typ)
		}
		qname := tc.qualify_name(name)
		if qname != name {
			if typ := tc.file_scope.lookup(qname) {
				return comptime_static_source_type_name(typ)
			}
		}
	}
	return none
}

fn (tc &TypeChecker) comptime_static_enum_decl_value_cases(enum_name string) []ComptimeStaticValueCase {
	mut cur_mod := ''
	if tc.top_level_idx.len > 0 {
		for idx in tc.top_level_idx {
			kind := tc.a.nodes[idx].kind
			if kind == .module_decl {
				cur_mod = tc.a.nodes[idx].value
				continue
			}
			if kind != .enum_decl {
				continue
			}
			if cases := tc.comptime_static_enum_decl_value_cases_for_node(enum_name, cur_mod,
				tc.a.nodes[idx])
			{
				return cases
			}
		}
		return []ComptimeStaticValueCase{}
	}
	for idx in 0 .. tc.a.nodes.len {
		kind := tc.a.nodes[idx].kind
		if kind == .module_decl {
			cur_mod = tc.a.nodes[idx].value
			continue
		}
		if kind != .enum_decl {
			continue
		}
		if cases := tc.comptime_static_enum_decl_value_cases_for_node(enum_name, cur_mod,
			tc.a.nodes[idx])
		{
			return cases
		}
	}
	return []ComptimeStaticValueCase{}
}

fn (tc &TypeChecker) comptime_static_enum_decl_value_cases_for_node(enum_name string, cur_mod string, node flat.Node) ?[]ComptimeStaticValueCase {
	qualified := if cur_mod.len > 0 && cur_mod != 'main' && cur_mod != 'builtin' {
		'${cur_mod}.${node.value}'
	} else {
		node.value
	}
	if enum_name != node.value && enum_name != qualified {
		return none
	}
	is_flag := node.typ == 'flag'
	mut field_order := []string{}
	mut field_exprs := map[string]flat.NodeId{}
	for i in 0 .. node.children_count {
		f := tc.a.child_node(&node, i)
		if f.kind != .enum_field {
			continue
		}
		field_order << f.value
		if f.children_count > 0 {
			field_exprs[f.value] = tc.a.child(f, 0)
		}
	}
	mut out := []ComptimeStaticValueCase{}
	mut field_values := map[string]int{}
	mut next_val := 0
	for field_name in field_order {
		mut val := next_val
		if expr_id := field_exprs[field_name] {
			mut resolving := map[string]bool{}
			if ev := tc.comptime_static_enum_field_value(expr_id, cur_mod, enum_name, mut
				field_values, field_exprs, mut resolving)
			{
				val = ev
			}
		}
		field_values[field_name] = val
		out << ComptimeStaticValueCase{
			name:      field_name
			value:     if is_flag { 1 << val } else { val }
			has_value: true
		}
		next_val = val + 1
	}
	return out
}

fn (tc &TypeChecker) comptime_static_enum_field_value(id flat.NodeId, enum_module string, enum_name string, mut field_values map[string]int, field_exprs map[string]flat.NodeId, mut resolving map[string]bool) ?int {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return none
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.int_literal {
			if v := v_int_literal_value(node.value) {
				return v
			}
		}
		.ident {
			if value := tc.const_int_value_in_module(node.value, enum_module, []string{}) {
				return value
			}
			if ev := tc.comptime_static_enum_field_ref_value(node.value, enum_module, enum_name, mut
				field_values, field_exprs, mut resolving)
			{
				return ev
			}
			return none
		}
		.enum_val {
			if ev := tc.comptime_static_enum_field_ref_value(node.value, enum_module, enum_name, mut
				field_values, field_exprs, mut resolving)
			{
				return ev
			}
			return none
		}
		.paren {
			if node.children_count > 0 {
				return tc.comptime_static_enum_field_value(tc.a.child(&node, 0), enum_module,
					enum_name, mut field_values, field_exprs, mut resolving)
			}
		}
		.cast_expr {
			if node.children_count == 0 {
				return none
			}
			cast_type := unalias_type(tc.parse_type(node.value))
			if !cast_type.is_integer() {
				return none
			}
			return tc.comptime_static_enum_field_value(tc.a.child(&node, 0), enum_module,
				enum_name, mut field_values, field_exprs, mut resolving)
		}
		.prefix {
			if node.children_count == 0 {
				return none
			}
			value := tc.comptime_static_enum_field_value(tc.a.child(&node, 0), enum_module,
				enum_name, mut field_values, field_exprs, mut resolving) or { return none }
			return match node.op {
				.minus { -value }
				.plus { value }
				.bit_not { ~value }
				else { none }
			}
		}
		.infix {
			if node.children_count < 2 {
				return none
			}
			left := tc.comptime_static_enum_field_value(tc.a.child(&node, 0), enum_module,
				enum_name, mut field_values, field_exprs, mut resolving) or { return none }
			right := tc.comptime_static_enum_field_value(tc.a.child(&node, 1), enum_module,
				enum_name, mut field_values, field_exprs, mut resolving) or { return none }
			if (node.op == .div || node.op == .mod) && right == 0 {
				return none
			}
			if (node.op == .left_shift || node.op == .right_shift
				|| node.op == .right_shift_unsigned) && (right < 0 || right >= 64) {
				return none
			}
			return match node.op {
				.plus { left + right }
				.minus { left - right }
				.mul { left * right }
				.div { left / right }
				.mod { left % right }
				.left_shift { int(u64(left) << right) }
				.right_shift { left >> right }
				.right_shift_unsigned { int(u64(left) >> right) }
				.amp { left & right }
				.pipe { left | right }
				.xor { left ^ right }
				.power { const_int_power(left, right) }
				else { none }
			}
		}
		.selector {
			if field := tc.comptime_static_enum_selector_ref_field(id, enum_module, enum_name) {
				return tc.comptime_static_enum_field_ref_value(field, enum_module, enum_name, mut
					field_values, field_exprs, mut resolving)
			}
			return none
		}
		else {}
	}

	return none
}

fn (tc &TypeChecker) comptime_static_enum_field_ref_value(field_name string, enum_module string, enum_name string, mut field_values map[string]int, field_exprs map[string]flat.NodeId, mut resolving map[string]bool) ?int {
	if field_name in field_values {
		return field_values[field_name]
	}
	expr_id := field_exprs[field_name] or { return none }
	if resolving[field_name] {
		return none
	}
	resolving[field_name] = true
	val := tc.comptime_static_enum_field_value(expr_id, enum_module, enum_name, mut field_values,
		field_exprs, mut resolving) or {
		resolving.delete(field_name)
		return none
	}
	resolving.delete(field_name)
	field_values[field_name] = val
	return val
}

fn (tc &TypeChecker) comptime_static_enum_selector_ref_field(id flat.NodeId, enum_module string, enum_name string) ?string {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind != .selector || node.children_count == 0 {
		return none
	}
	prefix := tc.comptime_static_enum_selector_base_text(tc.a.child(&node, 0))
	if !comptime_static_enum_ref_prefix_matches(prefix, enum_module, enum_name) {
		return none
	}
	return node.value
}

fn (tc &TypeChecker) comptime_static_enum_selector_base_text(id flat.NodeId) string {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return ''
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			return node.value
		}
		.selector {
			if node.children_count == 0 {
				return node.value
			}
			base := tc.comptime_static_enum_selector_base_text(tc.a.child(&node, 0))
			if base.len == 0 {
				return node.value
			}
			return '${base}.${node.value}'
		}
		else {
			return ''
		}
	}
}

fn comptime_static_enum_ref_prefix_matches(prefix string, enum_module string, enum_name string) bool {
	if prefix.len == 0 || enum_name.len == 0 {
		return false
	}
	short := enum_name.all_after_last('.')
	if prefix == enum_name || prefix == short {
		return true
	}
	if enum_module.len > 0 && prefix == '${enum_module}.${short}' {
		return true
	}
	return false
}

fn (tc &TypeChecker) comptime_static_for_field_source_type(owner_type string, field_name string) ?string {
	struct_name := tc.comptime_static_struct_name(owner_type) or { return none }
	typ := tc.struct_field_type(struct_name, field_name) or { return none }
	return comptime_static_source_type_name(typ)
}

fn comptime_static_source_type_name(typ Type) string {
	mut cur := typ
	for _ in 0 .. 16 {
		if cur is Pointer {
			cur = cur.base_type
			continue
		}
		if cur is OptionType {
			cur = cur.base_type
			continue
		}
		if cur is ResultType {
			cur = cur.base_type
			continue
		}
		return cur.name()
	}
	return cur.name()
}

fn (tc &TypeChecker) comptime_static_struct_name(raw string) ?string {
	mut cur := trimmed_space(raw)
	mut seen := map[string]bool{}
	for cur.len > 0 && cur !in seen {
		seen[cur] = true
		mut candidates := [cur, tc.qualify_name(cur)]
		if resolved := tc.resolve_selective_import_type_symbol(cur) {
			candidates << resolved
		}
		for candidate in candidates {
			if candidate in tc.structs {
				return candidate
			}
		}
		next := tc.alias_target_type_text(cur) or { break }
		if next == cur {
			break
		}
		cur = trimmed_space(next)
	}
	return none
}

fn (tc &TypeChecker) comptime_static_field_decl_metas(base_type string) map[string]ComptimeStaticFieldDeclMeta {
	mut out := map[string]ComptimeStaticFieldDeclMeta{}
	mut decl_name := trimmed_space(base_type)
	if idx := decl_name.index('[') {
		decl_name = decl_name[..idx]
	}
	mut cur_mod := ''
	if tc.top_level_idx.len > 0 {
		for idx in tc.top_level_idx {
			kind := tc.a.nodes[idx].kind
			if kind == .module_decl {
				cur_mod = tc.a.nodes[idx].value
				continue
			}
			if kind != .struct_decl {
				continue
			}
			if metas := tc.comptime_static_field_decl_metas_for_node(decl_name, cur_mod,
				tc.a.nodes[idx])
			{
				return metas
			}
		}
		return out
	}
	for idx in 0 .. tc.a.nodes.len {
		kind := tc.a.nodes[idx].kind
		if kind == .module_decl {
			cur_mod = tc.a.nodes[idx].value
			continue
		}
		if kind != .struct_decl {
			continue
		}
		if metas := tc.comptime_static_field_decl_metas_for_node(decl_name, cur_mod,
			tc.a.nodes[idx])
		{
			return metas
		}
	}
	return out
}

fn (tc &TypeChecker) comptime_static_field_decl_metas_for_node(decl_name string, cur_mod string, node flat.Node) ?map[string]ComptimeStaticFieldDeclMeta {
	qualified := if cur_mod.len > 0 && cur_mod != 'main' && cur_mod != 'builtin' {
		'${cur_mod}.${node.value}'
	} else {
		node.value
	}
	if decl_name != node.value && decl_name != qualified {
		return none
	}
	mut out := map[string]ComptimeStaticFieldDeclMeta{}
	for i in 0 .. node.children_count {
		f := tc.a.child_node(&node, i)
		if f.kind != .field_decl {
			continue
		}
		raw_typ := if f.typ.len > 0 { f.typ } else { f.value }
		mut is_mut := false
		mut is_pub := false
		if f.generic_params().len > 0 {
			flags := f.generic_params()[0]
			is_mut = flags.contains('m')
			is_pub = flags.contains('p')
		}
		out[f.value] = ComptimeStaticFieldDeclMeta{
			is_mut:   is_mut
			is_pub:   is_pub
			is_embed: source_field_decl_is_embed(f, raw_typ)
			raw_typ:  raw_typ
		}
	}
	return out
}

fn comptime_static_unwrap_field_type(typ Type) Type {
	mut cur := typ
	for _ in 0 .. 16 {
		if cur is Alias {
			cur = cur.base_type
			continue
		}
		if cur is OptionType {
			cur = cur.base_type
			continue
		}
		if cur is Pointer {
			cur = cur.base_type
			continue
		}
		return cur
	}
	return cur
}

fn comptime_static_field_type_flags(raw string) ComptimeStaticFieldTypeFlags {
	mut core := trimmed_space(raw)
	mut flags := ComptimeStaticFieldTypeFlags{}
	if core.starts_with('?') {
		core = trimmed_space(core[1..])
	}
	if core.starts_with('shared ') {
		flags.is_shared = true
		flags.indirections++
		core = trimmed_space(core[7..])
	} else if core.starts_with('atomic ') {
		flags.is_atomic = true
		core = trimmed_space(core[7..])
	}
	for core.starts_with('&') {
		flags.indirections++
		core = trimmed_space(core[1..])
	}
	return flags
}

fn (mut tc TypeChecker) comptime_static_subst_field_cond(cond string, var_name string, field ComptimeStaticFieldCase) string {
	mut c := cond
	c = c.replace('${var_name}.unaliased_typ', field.unaliased_typ)
	c = c.replace('${var_name}.is_option', field.is_option.str())
	c = c.replace('${var_name}.is_opt', field.is_option.str())
	if field.has_decl_meta {
		c = c.replace('${var_name}.is_embed', field.is_embed.str())
		c = c.replace('${var_name}.is_mut', field.is_mut.str())
		c = c.replace('${var_name}.is_pub', field.is_pub.str())
	}
	c = c.replace('${var_name}.is_array', field.is_array.str())
	c = c.replace('${var_name}.is_map', field.is_map.str())
	c = c.replace('${var_name}.is_chan', field.is_chan.str())
	c = c.replace('${var_name}.is_struct', field.is_struct.str())
	c = c.replace('${var_name}.is_enum', field.is_enum.str())
	c = c.replace('${var_name}.is_alias', field.is_alias.str())
	c = c.replace('${var_name}.is_shared', field.is_shared.str())
	c = c.replace('${var_name}.is_atomic', field.is_atomic.str())
	c = c.replace('${var_name}.indirections', field.indirections.str())
	c = c.replace('${var_name}.typ', field.typ)
	c = c.replace('${var_name}.name', "'${field.name}'")
	c = comptime_static_replace_bare_ident(c, var_name, field.typ)
	return c
}

fn comptime_static_replace_bare_ident(cond string, ident string, replacement string) string {
	if ident.len == 0 {
		return cond
	}
	mut out := ''
	mut offset := 0
	for offset < cond.len {
		if cond[offset] == `'` || cond[offset] == `"` {
			end := comptime_cond_skip_string(cond, offset)
			out += cond[offset..end]
			offset = end
			continue
		}
		if offset + ident.len <= cond.len && cond[offset..offset + ident.len] == ident {
			before_ok := offset == 0 || !comptime_cond_name_char(cond[offset - 1])
			after := offset + ident.len
			after_ok := after >= cond.len
				|| (!comptime_cond_name_char(cond[after]) && cond[after] != `.`)
			if before_ok && after_ok {
				out += replacement
				offset = after
				continue
			}
		}
		out += cond[offset..offset + 1]
		offset++
	}
	return out
}

fn (mut tc TypeChecker) comptime_static_eval_field_cond(cond string) ?bool {
	clean := comptime_condition_strip_outer_parens(trimmed_space(cond))
	if clean == 'true' {
		return true
	}
	if clean == 'false' {
		return false
	}
	or_idx := comptime_condition_top_level_index(clean, '||')
	if or_idx >= 0 {
		left := tc.comptime_static_eval_field_cond(clean[..or_idx]) or { return none }
		if left {
			return true
		}
		return tc.comptime_static_eval_field_cond(clean[or_idx + 2..])
	}
	and_idx := comptime_condition_top_level_index(clean, '&&')
	if and_idx >= 0 {
		left := tc.comptime_static_eval_field_cond(clean[..and_idx]) or { return none }
		if !left {
			return false
		}
		return tc.comptime_static_eval_field_cond(clean[and_idx + 2..])
	}
	for op in [' !is ', ' is '] {
		op_idx := comptime_condition_top_level_index(clean, op)
		if op_idx >= 0 {
			left := trimmed_space(clean[..op_idx])
			right := trimmed_space(clean[op_idx + op.len..])
			matches := tc.comptime_type_matches(left, right) or { return none }
			return if op == ' is ' { matches } else { !matches }
		}
	}
	for op in [' != ', ' == '] {
		op_idx := comptime_condition_top_level_index(clean, op)
		if op_idx >= 0 {
			left := comptime_static_unquote(trimmed_space(clean[..op_idx]))
			right := comptime_static_unquote(trimmed_space(clean[op_idx + op.len..]))
			eq := left == right
			return if op == ' == ' { eq } else { !eq }
		}
	}
	for op in [' !in', ' in'] {
		op_idx := comptime_condition_top_level_index(clean, op)
		if op_idx >= 0 {
			after := op_idx + op.len
			if after < clean.len && clean[after] != ` ` && clean[after] != `[`
				&& clean[after] != `(` {
				continue
			}
			needle := comptime_static_unquote(trimmed_space(clean[..op_idx]))
			found := comptime_static_list_contains(trimmed_space(clean[after..]), needle)
			return if op == ' in' { found } else { !found }
		}
	}
	for op in [' <= ', ' >= ', ' < ', ' > '] {
		op_idx := comptime_condition_top_level_index(clean, op)
		if op_idx >= 0 {
			left := trimmed_space(clean[..op_idx])
			right := trimmed_space(clean[op_idx + op.len..])
			if !comptime_static_is_int(left) || !comptime_static_is_int(right) {
				return none
			}
			l := left.int()
			r := right.int()
			return match op {
				' <= ' { l <= r }
				' >= ' { l >= r }
				' < ' { l < r }
				else { l > r }
			}
		}
	}
	if clean.starts_with('!') {
		value := tc.comptime_static_eval_field_cond(clean[1..]) or { return none }
		return !value
	}
	return none
}

fn comptime_static_list_contains(list_text string, needle string) bool {
	clean := trimmed_space(list_text)
	if !clean.starts_with('[') || !clean.ends_with(']') {
		return false
	}
	inner := clean[1..clean.len - 1]
	for part in inner.split(',') {
		if comptime_static_unquote(trimmed_space(part)) == needle {
			return true
		}
	}
	return false
}

fn comptime_static_is_int(s string) bool {
	if s.len == 0 {
		return false
	}
	start := if s[0] == `-` || s[0] == `+` { 1 } else { 0 }
	if start >= s.len {
		return false
	}
	for i in start .. s.len {
		if !s[i].is_digit() {
			return false
		}
	}
	return true
}

fn comptime_static_unquote(s string) string {
	if s.len >= 2 && (s[0] == `'` || s[0] == `"`) && s[s.len - 1] == s[0] {
		return comptime_static_unescape(s[1..s.len - 1])
	}
	return s
}

fn comptime_static_string_literal(value string) string {
	mut out := strings.new_builder(value.len + 2)
	out.write_u8(`'`)
	for i := 0; i < value.len; i++ {
		if value[i] == `\\` || value[i] == `'` {
			out.write_u8(`\\`)
		}
		out.write_u8(value[i])
	}
	out.write_u8(`'`)
	return out.str()
}

fn comptime_static_unescape(value string) string {
	if !value.contains('\\') {
		return value
	}
	mut out := strings.new_builder(value.len)
	mut i := 0
	for i < value.len {
		if value[i] != `\\` || i + 1 >= value.len {
			out.write_u8(value[i])
			i++
			continue
		}
		next := value[i + 1]
		if next == `\n` {
			i += 2
			for i < value.len && value[i] in [` `, `\t`, `\r`] {
				i++
			}
			continue
		}
		if next == `\r` && i + 2 < value.len && value[i + 2] == `\n` {
			i += 3
			for i < value.len && value[i] in [` `, `\t`] {
				i++
			}
			continue
		}
		if next == `x` && i + 3 < value.len {
			if code := comptime_static_fixed_hex(value, i + 2, 2) {
				out.write_u8(u8(code))
				i += 4
				continue
			}
		}
		if next == `u` && i + 5 < value.len {
			if code := comptime_static_fixed_hex(value, i + 2, 4) {
				out.write_rune(rune(code))
				i += 6
				continue
			}
		}
		if next == `U` && i + 9 < value.len {
			if code := comptime_static_fixed_hex(value, i + 2, 8) {
				out.write_rune(rune(code))
				i += 10
				continue
			}
		}
		decoded := match next {
			`n` { int(`\n`) }
			`t` { int(`\t`) }
			`r` { int(`\r`) }
			`\\` { int(`\\`) }
			`'` { int(`'`) }
			`"` { int(`"`) }
			`$` { int(`$`) }
			`0` { 0 }
			`a` { 7 }
			`b` { 8 }
			`f` { 12 }
			`v` { 11 }
			else { -1 }
		}

		if decoded >= 0 {
			out.write_u8(u8(decoded))
		} else {
			out.write_u8(`\\`)
			out.write_u8(next)
		}
		i += 2
	}
	return out.str()
}

fn comptime_static_fixed_hex(value string, start int, count int) ?u32 {
	mut code := u32(0)
	for i in 0 .. count {
		if start + i >= value.len {
			return none
		}
		digit := comptime_static_hex_digit(value[start + i]) or { return none }
		code = (code << 4) | digit
	}
	return code
}

fn comptime_static_hex_digit(c u8) ?u32 {
	if c >= `0` && c <= `9` {
		return u32(c - `0`)
	}
	if c >= `a` && c <= `f` {
		return u32(c - `a` + 10)
	}
	if c >= `A` && c <= `F` {
		return u32(c - `A` + 10)
	}
	return none
}

// check_node validates check node state for types.
fn (mut tc TypeChecker) check_node(id flat.NodeId) {
	idx := int(id)
	if idx < 0 {
		return
	}
	if tc.parallel_check_sparse {
		if tc.in_check_range(idx) && idx < tc.checking_nodes.len {
			if tc.checking_nodes[idx] {
				return
			}
			tc.checking_nodes[idx] = true
			defer {
				tc.checking_nodes[idx] = false
			}
		} else {
			if tc.sparse_checking_nodes[idx] {
				return
			}
			tc.sparse_checking_nodes[idx] = true
			defer {
				tc.sparse_checking_nodes.delete(idx)
			}
		}
	} else {
		if idx >= tc.checking_nodes.len {
			tc.extend_node_caches(tc.a.nodes.len)
		}
		if idx < tc.checking_nodes.len {
			if tc.checking_nodes[idx] {
				return
			}
			tc.checking_nodes[idx] = true
			defer {
				tc.checking_nodes[idx] = false
			}
		}
	}
	node := tc.a.nodes[idx]
	if node.kind == .string_literal {
		literal_pos := tc.string_literal_diagnostic_pos(node)
		if !tc.string_literal_source_is_valid_utf8(literal_pos) {
			tc.record_notice_at(.unknown_ident, 'invalid utf8 byte sequence in string literal', id,
				literal_pos)
		}
		return
	}
	kind_id := node_kind_id(node)
	if kind_id == 1 {
		tc.check_untyped_integer_literal_overflow(id)
		return
	}
	if kind_id == 2 || kind_id == 3 || kind_id == 4 || kind_id == 5 || kind_id == 28
		|| kind_id == 29 {
		return
	}
	if node.kind in [.break_stmt, .continue_stmt] {
		tc.check_loop_control_statement(id, node)
		return
	}
	if node.kind == .const_decl {
		tc.record_error_at(.duplicate_decl,
			'const can only be defined at the top level (outside of functions)', id, token.new_span(node.pos.id,
			node.pos.offset, node.pos.offset + 5))
		for i in 0 .. node.children_count {
			field := tc.a.child_node(&node, i)
			if field.kind != .const_field || field.value.len == 0 || field.value == '_' {
				continue
			}
			typ := if field.children_count > 0 {
				expr_id := tc.a.child(field, 0)
				tc.check_node(expr_id)
				tc.resolve_type(expr_id)
			} else {
				tc.parse_type(field.typ)
			}
			tc.cur_scope.insert(field.value, typ)
		}
		return
	}
	if kind_id == 45 {
		tc.check_block(id, node)
		return
	}
	if node.kind == .comptime_if {
		tc.check_comptime_if(id, node)
		return
	}
	if node.kind == .comptime_for {
		// The body references the loop variable (`field.name`, `field.typ`, ...) which only
		// exists once the transformer unrolls the loop against a concrete type, so it cannot
		// be type-checked here. Validate the known compile-time member surface, then skip it;
		// the unrolled statements are concrete.
		tc.check_comptime_for_members(id, node)
		return
	}
	if node.kind == .asm_stmt {
		tc.check_asm_stmt(id, node)
		return
	}
	if node.kind == .sql_expr {
		tc.check_sql_expr(id, node)
		return
	}
	if node.kind == .lock_expr {
		tc.check_lock_expr(id, node)
		return
	}
	if kind_id == 46 {
		tc.check_for_stmt(node)
		return
	}
	if kind_id == 47 {
		tc.check_for_in_stmt(node)
		return
	}
	if kind_id == 41 {
		tc.check_decl_assign(id, node)
		return
	}
	if kind_id == 40 || kind_id == 42 || kind_id == 43 {
		tc.check_assign(id, node)
		return
	}
	if kind_id == 44 {
		tc.check_return(id, node)
		return
	}
	if kind_id == 12 {
		tc.check_call(id, node)
		return
	}
	if kind_id == 21 {
		tc.check_fn_literal(id, node)
		return
	}
	if kind_id == 32 {
		tc.check_lambda_expr(id, node)
		return
	}
	if kind_id == 15 {
		tc.check_if_expr(id, node)
		return
	}
	if kind_id == 22 {
		tc.check_or_expr(id, node)
		return
	}
	if kind_id == 50 {
		tc.check_match_stmt(id, node)
		return
	}
	if kind_id == 37 {
		tc.check_is_expr(id, node)
		return
	}
	if kind_id == 10 {
		tc.check_postfix(id, node)
		return
	}
	if kind_id == 16 || kind_id == 26 {
		tc.check_struct_init(id, node)
		return
	}
	if kind_id == 13 {
		tc.check_selector(id, node)
		$if ownership ? {
			tc.ownership_check_expr(id)
		}
		return
	}
	if kind_id == 14 {
		tc.check_index(id, node)
		$if ownership ? {
			tc.ownership_check_expr(id)
		}
		return
	}
	if kind_id == 7 {
		tc.check_ident(id, node)
		return
	}
	if node.kind == .defer_result {
		tc.check_defer_result(id, node)
		return
	}
	if node.kind == .cast_expr {
		tc.check_cast_expr(id, node)
		return
	}
	if node.kind == .prefix {
		tc.check_prefix_expr(id, node)
		return
	}
	if node.kind == .as_expr {
		tc.check_as_expr(id, node)
		return
	}
	if node.kind == .sizeof_expr {
		if should_check_named_type(node.value) && !tc.type_name_known(node.value) {
			pos := tc.sizeof_type_diagnostic_pos(id, node.value)
			if node.value.len == 1 {
				// v1 classifies a lone unresolved generic-looking placeholder
				// in sizeof as a cgen error.
				tc.record_error_severity_at(.compile_error, 'unknown type `${node.value}`', id,
					pos, 'cgen error:')
			} else {
				tc.record_error_at(.unknown_type, tc.unknown_type_message(node.value, id), id, pos)
			}
		}
		return
	}
	if node.kind == .in_expr {
		tc.check_in_expr(id, node)
		return
	}
	if node.kind == .dump_expr {
		tc.check_dump_expr(node)
		return
	}
	if node.kind == .assert_stmt {
		tc.check_assert_stmt(node)
		return
	}
	if node.kind == .array_init {
		tc.check_missing_array_init_interface_type_args(id, node)
		tc.check_array_init(id, node)
		$if ownership ? {
			if !tc.ownership_aggregate_consumption_deferred(id) {
				tc.ownership_consume_array_init_expr(node)
			}
		}
		return
	}
	if node.kind == .select_stmt {
		tc.check_select_stmt(node)
		return
	}
	if node.kind == .defer_stmt {
		if node.value.starts_with('invalid:') {
			mode := node.value.all_after(':')
			tc.record_error_at(.unknown_ident, 'unknown `defer` mode: `${mode}`', id, tc.defer_mode_diagnostic_pos(node,
				mode))
			return
		}
		if node.value == 'function' && tc.fn_context.node_id >= 0 {
			if tc.lock_depth > 0 {
				tc.record_error_at(.assignment_mismatch,
					'`defer(fn)`s are not allowed in lock statements', id, node.pos)
			} else if !tc.current_fn_has_invalid_defer_mode() {
				tc.record_warning_at(.assignment_mismatch,
					'`defer` is already in function scope; just use `defer {` instead', id,
					node.pos)
			}
		}
		$if ownership ? {
			tc.ownership_check_defer_stmt(id, node)
		} $else {
			tc.check_defer_stmt(node)
		}
		return
	}
	if node.kind == .spawn_expr {
		tc.check_spawn_expr(id, node)
		return
	}
	if node.kind == .string_interp {
		mut specialized_invalid_selector := false
		for i in 0 .. node.children_count {
			part_id := tc.a.child(&node, i)
			part := tc.a.node(part_id)
			expr_id := if part.kind == .directive && part.value == 'string_interp_format'
				&& part.children_count > 0 {
				tc.a.child(part, 0)
			} else {
				part_id
			}
			tc.check_node(expr_id)
			if access := tc.unlocked_shared_access(expr_id) {
				tc.record_error_at(.call_arg_mismatch,
					'`${access.name}` is `shared` and must be `rlock`ed or `lock`ed to be used as non-mut interpolation object',
					expr_id, access.pos)
			}
			expr := tc.a.node(expr_id)
			expr_type := tc.resolve_type(expr_id)
			invalid_selector := expr.kind == .selector && expr.children_count > 0
				&& tc.resolve_type(tc.a.child(expr, 0)) !is Unknown
				&& tc.selector_type(expr_id, *expr) == none
			if tc.string_interpolation_recurses_str(expr_type) {
				tc.record_error_at(.call_arg_mismatch, 'cannot call `str()` method recursively',
					expr_id, tc.string_interpolation_expr_pos(expr_id))
			} else if expr_type is Void
				|| (expr_type is MultiReturn && expr_type.types.len == 0)
				|| invalid_selector || (expr_type is Unknown && expr.kind == .ident
				&& tc.cur_scope.lookup(expr.value) == none) {
				message := if expr.kind == .ident && tc.ident_is_mutable_lvalue(expr.value) {
					'no known default format for type `void`'
				} else {
					'expression does not return a value'
				}
				diagnostic_pos := if invalid_selector {
					tc.node_value_diagnostic_pos(expr_id)
				} else {
					tc.string_interpolation_expr_pos(expr_id)
				}
				tc.record_error_at(.call_arg_mismatch, message, expr_id, diagnostic_pos)
				specialized_invalid_selector = specialized_invalid_selector
					|| (invalid_selector && tc.current_fn_is_specialized_generic())
			} else if unalias_type(expr_type) is Char {
				tc.record_error_at(.call_arg_mismatch,
					'expression returning type `char` cannot be used in string interpolation directly, print its address or cast it to an integer instead',
					expr_id, tc.string_interpolation_expr_pos(expr_id))
			}
			if part.kind == .directive && part.value == 'string_interp_format' {
				tc.check_string_interpolation_format(part_id, part, expr_id)
			}
		}
		if specialized_invalid_selector {
			tc.record_enclosing_print_void(id)
		}
		return
	}
	if node.kind == .paren && node.value == '__v3_comptime_d' && node.children_count > 0 {
		default_id := tc.a.child(&node, 0)
		default := tc.a.node(default_id)
		if default.kind !in [.bool_literal, .char_literal, .float_literal, .string_literal,
			.int_literal] {
			tc.record_error_at(.assignment_mismatch, '$d() values can only be pure literals', id,
				node.pos)
		}
		tc.check_node(default_id)
		return
	}
	if node.kind == .paren && tc.paren_expr_has_redundant_parentheses(id) {
		tc.record_notice_at(.unknown_ident, 'redundant parentheses are used', id, node.pos)
	}
	// A method value stored in a container escapes the single-use guarantee of its per-site
	// static receiver, so reject `[obj.method]` / `arr << obj.method` / `{'k': obj.method}`.
	if node.kind == .array_literal {
		for i in 0 .. node.children_count {
			tc.reject_stored_method_value(tc.a.child(&node, i))
			tc.reject_stored_capturing_fn_literal(tc.a.child(&node, i))
		}
		$if ownership ? {
			tc.check_ownership_array_spread_clone(id, node)
		}
	} else if node.kind == .map_init {
		map_type := unalias_type(tc.parse_type(node.value))
		if map_type is Map {
			if fn_type := fn_type_from_type(unalias_type(map_type.value_type)) {
				if fn_type.params.any(unalias_type(it) is ResultType) {
					tc.record_error_at(.unknown_type, 'result type arguments are not supported',
						id, node.pos)
				}
			}
		}
		if generic_name := tc.bare_generic_decl_type_name(node.value) {
			qualified := tc.qualify_name(generic_name)
			if generic_name in tc.struct_generic_params || qualified in tc.struct_generic_params {
				tc.record_error_at(.unknown_type,
					'generic struct `${generic_name}` must specify type parameter, e.g. ${generic_name}[int]',
					id, node.pos)
			}
		}
		if type_text_contains_any(node.value) {
			tc.record_notice_at(.unknown_type,
				'the `any` type is deprecated and will be removed soon - either use an empty interface, or a sum type',
				id, node.pos)
			tc.record_error(.unknown_type, 'cannot use type `any` here', id)
		}
		tc.check_map_duplicate_keys(node)
		// children alternate key, value, key, value, ...; check the value positions.
		for j := 1; j < node.children_count; j += 2 {
			tc.reject_stored_method_value(tc.a.child(&node, j))
			tc.reject_stored_capturing_fn_literal(tc.a.child(&node, j))
		}
		$if ownership ? {
			tc.check_ownership_map_spread_clone(id, node)
		}
	} else if node.kind == .infix && node.op == .left_shift && node.children_count >= 2 {
		if unwrap_pointer(tc.resolve_type(tc.a.child(&node, 0))) is Array {
			tc.reject_stored_method_value(tc.a.child(&node, 1))
			tc.reject_stored_capturing_fn_literal(tc.a.child(&node, 1))
		}
	}
	if node.kind == .infix && node.op == .logical_and && node.children_count >= 2 {
		lhs_id := tc.a.child(&node, 0)
		rhs_id := tc.a.child(&node, 1)
		smartcasts := tc.extract_smartcasts(lhs_id)
		if smartcasts.len > 0 {
			tc.check_node(lhs_id)
			saved_smartcasts := clone_smartcasts(tc.smartcasts)
			for sc in smartcasts {
				if valid_string_data(sc.name) {
					tc.smartcasts[sc.name] = sc.typ
				}
			}
			tc.check_node(rhs_id)
			tc.smartcasts = clone_smartcasts(saved_smartcasts)
			return
		}
	}

	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		previous_channel_send_or_expr_id := tc.channel_send_or_expr_id
		if node.kind == .infix && node.op == .arrow && i == 1 {
			child := tc.a.node(child_id)
			if child.kind == .or_expr {
				tc.channel_send_or_expr_id = int(child_id)
			}
		}
		$if ownership ? {
			defer_append_rhs := node.kind == .infix && node.op == .left_shift
				&& node.children_count >= 2 && i == 1
				&& unwrap_pointer(tc.resolve_type(tc.a.child(&node, 0))) is Array
			tc.ownership_check_node_with_aggregate_consumption_mode(child_id, defer_append_rhs)
		} $else {
			tc.check_node(child_id)
		}
		tc.channel_send_or_expr_id = previous_channel_send_or_expr_id
	}
	if node.kind == .array_literal {
		tc.check_array_literal_element_types(id, node)
	}
	if node.kind == .map_init {
		tc.check_map_none_values(node)
		has_unhandled_result := tc.check_map_literal_result_elements(node)
		map_type := unalias_type(tc.resolve_type(id))
		if map_type is Map && unalias_type(map_type.value_type) is ResultType
			&& node.children_count == 0 {
			tc.record_error_at(.unknown_type, 'cannot use Result type as map value type', id,
				node.pos)
		}
		if map_type is Map && unalias_type(map_type.key_type) is Struct {
			if map_type.key_type.name() != 'any' {
				tc.record_error_at(.unknown_type,
					'map key type `${map_type.key_type.name()}` not supported', id, node.pos)
			}
		}
		if !has_unhandled_result {
			tc.check_map_literal_element_types(id, node)
		}
	}
	if node.kind == .infix {
		tc.check_infix(id, node)
	}
	$if ownership ? {
		if !tc.ownership_aggregate_consumption_deferred(id) {
			if node.kind == .array_literal {
				for i in 0 .. node.children_count {
					elem_id := tc.a.child(&node, i)
					tc.ownership_consume_expr(elem_id, 'array element', elem_id)
				}
			} else if node.kind == .map_init {
				for j := 0; j < node.children_count; j += 2 {
					key_id := tc.a.child(&node, j)
					tc.ownership_consume_expr(key_id, 'map key', key_id)
					if j + 1 < node.children_count {
						val_id := tc.a.child(&node, j + 1)
						tc.ownership_consume_expr(val_id, 'map value', val_id)
					}
				}
			}
		}
		if node.kind == .infix && node.op == .left_shift && node.children_count >= 2 {
			array_id := tc.a.child(&node, 0)
			if unwrap_pointer(tc.resolve_type(array_id)) is Array {
				elem_id := tc.a.child(&node, 1)
				tc.ownership_mark_array_append_expr(array_id, elem_id, id)
			}
		} else if node.kind == .infix && node.op == .arrow && node.children_count >= 2 {
			value_id := tc.a.child(&node, 1)
			tc.ownership_consume_expr(value_id, 'channel send', id)
		}
	}
}

fn (mut tc TypeChecker) check_loop_control_statement(id flat.NodeId, node flat.Node) {
	if node.value.len > 0 {
		if tc.diagnostic_files.len == 0 && !tc.valid_labelled_loop_control(node.value, node.pos) {
			tc.record_invalid_loop_label(id, node)
		}
		return
	}
	mut current := id
	for _ in 0 .. 64 {
		parent_id := tc.direct_parent_id(current)
		if !tc.valid_node_id(parent_id) {
			break
		}
		parent := tc.a.node(parent_id)
		if parent.kind in [.for_stmt, .for_in_stmt] {
			return
		}
		if parent.kind == .comptime_for {
			keyword := if node.kind == .break_stmt { 'break' } else { 'continue' }
			tc.record_error_at(.assignment_mismatch,
				'${keyword} is not allowed within a compile-time loop', id, tc.loop_control_keyword_pos(id,
				keyword))
			return
		}
		if parent.kind == .defer_stmt {
			keyword := if node.kind == .break_stmt { 'break' } else { 'continue' }
			tc.record_error_at(.assignment_mismatch,
				'`${keyword}` is not allowed in defer statements', id, tc.loop_control_keyword_pos(id,
				keyword))
			break
		}
		if parent.kind in [.fn_decl, .fn_literal, .lambda_expr] {
			break
		}
		current = parent_id
	}
	keyword := if node.kind == .break_stmt { 'break' } else { 'continue' }
	tc.record_error_at(.assignment_mismatch, '${keyword} statement not within a loop', id, tc.loop_control_keyword_pos(id,
		keyword))
}

fn (mut tc TypeChecker) check_labelled_loop_controls() {
	if tc.diagnostic_files.len == 0 {
		return
	}
	mut diagnosed := map[string]bool{}
	for index, node in tc.a.nodes {
		if index < tc.a.user_code_start || node.kind !in [.break_stmt, .continue_stmt]
			|| node.value.len == 0 || !tc.node_is_in_selected_input_file(flat.NodeId(index))
			|| tc.valid_labelled_loop_control(node.value, node.pos) {
			continue
		}
		key := '${node.pos.id}:${node.pos.offset}:${node.kind}'
		if diagnosed[key] {
			continue
		}
		diagnosed[key] = true
		tc.record_invalid_loop_label(flat.NodeId(index), node)
	}
}

fn (mut tc TypeChecker) record_invalid_loop_label(id flat.NodeId, node flat.Node) {
	keyword := if node.kind == .break_stmt { 'break' } else { 'continue' }
	pos := tc.loop_control_keyword_pos(id, keyword)
	message := 'invalid label name `${node.value}`'
	if tc.errors.any(it.msg == message && it.pos.id == pos.id && it.pos.offset == pos.offset
		&& it.pos.end == pos.end)
	{
		return
	}
	tc.errors << tc.make_type_error_at(.unknown_ident, message, id, pos)
}

fn (tc &TypeChecker) valid_labelled_loop_control(name string, pos token.Pos) bool {
	for index, node in tc.a.nodes {
		if node.kind != .label_stmt || node.value != name || node.pos.id != pos.id
			|| !tc.label_starts_loop(flat.NodeId(index)) {
			continue
		}
		if tc.labelled_loop_contains_source_position(node, pos) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) label_starts_loop(id flat.NodeId) bool {
	for parent in tc.a.nodes {
		if parent.children_count < 2 {
			continue
		}
		for i in 0 .. int(parent.children_count) - 1 {
			if tc.a.child(&parent, i) != id {
				continue
			}
			return tc.a.node(tc.a.child(&parent, i + 1)).kind in [.for_stmt, .for_in_stmt]
		}
	}
	return false
}

fn (tc &TypeChecker) labelled_loop_contains_source_position(label flat.Node, pos token.Pos) bool {
	if label.pos.id != pos.id {
		return false
	}
	file := tc.a.source_files[label.pos.id] or { return false }
	source := tc.source_texts_by_file[file.name] or { return false }
	start := int_max(0, int_min(label.pos.offset, source.len))
	relative_open := source[start..].index_u8(`{`)
	if relative_open < 0 {
		return false
	}
	open := start + relative_open
	mut depth := 0
	mut quote := u8(0)
	mut in_line_comment := false
	mut in_block_comment := false
	mut i := open
	for i < source.len {
		ch := source[i]
		if in_line_comment {
			if ch == `\n` {
				in_line_comment = false
			}
			i++
			continue
		}
		if in_block_comment {
			if ch == `*` && i + 1 < source.len && source[i + 1] == `/` {
				in_block_comment = false
				i += 2
				continue
			}
			i++
			continue
		}
		if quote != 0 {
			if ch == `\\` {
				i += 2
				continue
			}
			if ch == quote {
				quote = 0
			}
			i++
			continue
		}
		if ch == `/` && i + 1 < source.len {
			if source[i + 1] == `/` {
				in_line_comment = true
				i += 2
				continue
			}
			if source[i + 1] == `*` {
				in_block_comment = true
				i += 2
				continue
			}
		}
		if ch in [`'`, `"`] || ch == 0x60 {
			quote = ch
		} else if ch == `{` {
			depth++
		} else if ch == `}` {
			depth--
			if depth == 0 {
				return open < pos.offset && pos.end <= i + 1
			}
		}
		i++
	}
	return false
}

fn (tc &TypeChecker) loop_control_keyword_pos(id flat.NodeId, keyword string) token.Pos {
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	return closest_identifier_span(source, keyword, node.pos.offset, node.pos.id) or { node.pos }
}

fn (tc &TypeChecker) statement_exits_sequence(id flat.NodeId, node flat.Node) bool {
	if node.kind == .return_stmt {
		return true
	}
	if node.kind !in [.break_stmt, .continue_stmt] {
		return false
	}
	mut current := id
	for _ in 0 .. 64 {
		parent_id := tc.direct_parent_id(current)
		if !tc.valid_node_id(parent_id) {
			return false
		}
		parent := tc.a.node(parent_id)
		if parent.kind in [.for_stmt, .for_in_stmt] {
			return true
		}
		if parent.kind in [.comptime_for, .fn_decl, .fn_literal, .lambda_expr] {
			return false
		}
		current = parent_id
	}
	return false
}

fn (mut tc TypeChecker) check_missing_array_init_interface_type_args(id flat.NodeId, node flat.Node) {
	name := node.value.trim_space()
	if name.len == 0 || name.contains('[') || !tc.should_diagnose(id) {
		return
	}
	qualified := tc.qualify_name(name)
	if name !in tc.interface_generic_params && qualified !in tc.interface_generic_params {
		return
	}
	tc.record_error_at(.unknown_type,
		'generic interface `${name}` must specify type parameter, e.g. ${name}[int]', id, tc.type_diagnostic_pos(id,
		name))
}

fn (mut tc TypeChecker) check_map_none_values(node flat.Node) {
	mut first_none_id := flat.empty_node
	mut inferred := Type(void_)
	mut none_ids := []flat.NodeId{}
	for i := 1; i < node.children_count; i += 2 {
		value_id := tc.a.child(node, i)
		value := tc.a.node(value_id)
		if value.kind == .none_expr {
			if !tc.valid_node_id(first_none_id) {
				first_none_id = value_id
			}
			none_ids << value_id
			continue
		}
		if inferred is Void {
			inferred = tc.resolve_type(value_id)
		}
	}
	if none_ids.len == 0 {
		return
	}
	if inferred is Void {
		tc.record_error_at(.assignment_mismatch, 'map value cannot be only `none`', first_none_id,
			tc.a.node(first_none_id).pos)
		return
	}
	if unalias_type(inferred) is OptionType {
		return
	}
	for none_id in none_ids {
		tc.record_error_at(.assignment_mismatch,
			'invalid map value: expected `${inferred.name()}`, not `none`', none_id,
			tc.a.node(none_id).pos)
	}
}

fn (mut tc TypeChecker) check_map_literal_result_elements(node flat.Node) bool {
	mut found := false
	for i in 0 .. node.children_count {
		element_id := tc.a.child(&node, i)
		element := tc.a.node(element_id)
		element_type := unalias_type(tc.resolve_type(element_id))
		if element.kind != .call || tc.call_has_postfix_propagation(element) {
			continue
		}
		if element_type is ResultType {
			tc.record_unhandled_result_call(element_id, element_type)
			found = true
		}
	}
	return found
}

fn (tc &TypeChecker) map_literal_has_element_diagnostic(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	root := tc.a.node(id)
	return tc.errors.any(it.pos.id == root.pos.id && it.pos.offset >= root.pos.offset
		&& it.pos.end <= root.pos.end && (it.msg.starts_with('invalid map value: ')
		|| it.msg.starts_with('invalid map key: ')
		|| it.msg.starts_with('invalid map update: ')))
}

fn (mut tc TypeChecker) check_map_literal_element_types(id flat.NodeId, node flat.Node) {
	if node.children_count < 2 {
		return
	}
	for i := 0; i + 1 < node.children_count; i += 2 {
		key_id := tc.a.child(&node, i)
		key := tc.a.node(key_id)
		if key.kind != .prefix || key.value != '...' || key.children_count == 0 {
			continue
		}
		update_id := tc.a.child(key, 0)
		if map_type_from_receiver(tc.resolve_type(update_id)) == none {
			update := tc.a.node(update_id)
			tc.record_error_at(.assignment_mismatch, 'invalid map update: non-map type', update_id,
				update.pos)
		}
	}
	mut expected_key := Type(void_)
	mut expected_value := Type(void_)
	if expected := tc.expected_context_for_expr(id) {
		if expected_map := map_type_from_receiver(expected) {
			expected_key = expected_map.key_type
			expected_value = expected_map.value_type
		}
	}
	if expected_key is Void || expected_value is Void {
		for i := 0; i + 1 < node.children_count; i += 2 {
			key_id := tc.a.child(&node, i)
			key := tc.a.node(key_id)
			if key.kind == .prefix && key.value == '...' && key.children_count > 0 {
				update_id := tc.a.child(key, 0)
				if update_type := map_type_from_receiver(tc.resolve_type(update_id)) {
					expected_key = update_type.key_type
					expected_value = update_type.value_type
					break
				}
				continue
			}
			expected_key = tc.resolve_type(key_id)
			expected_value = tc.resolve_type(tc.a.child(&node, i + 1))
			break
		}
	}
	if expected_key is Void || expected_value is Void {
		return
	}
	for i := 0; i + 1 < node.children_count; i += 2 {
		key_id := tc.a.child(&node, i)
		key := tc.a.node(key_id)
		if key.kind == .prefix && key.value == '...' && key.children_count > 0 {
			update_id := tc.a.child(key, 0)
			if update_type := map_type_from_receiver(tc.resolve_type(update_id)) {
				if !tc.receiver_compatible(update_type.key_type, expected_key)
					|| !tc.receiver_compatible(update_type.value_type, expected_value) {
					expected_map := Type(Map{
						key_type:   expected_key
						value_type: expected_value
					})
					actual_map := Type(update_type)
					tc.record_error_at(.assignment_mismatch,
						'invalid map update: expected `${expected_map.name()}`, not `${actual_map.name()}`',
						update_id, tc.node_value_diagnostic_pos(update_id))
				}
			}
			continue
		}
		value_id := tc.a.child(&node, i + 1)
		tc.check_map_literal_slot_type(key_id, expected_key, 'key')
		if tc.a.node(value_id).kind != .none_expr {
			tc.check_map_literal_slot_type(value_id, expected_value, 'value')
		}
	}
}

fn (mut tc TypeChecker) check_map_literal_slot_type(value_id flat.NodeId, expected Type, slot string) {
	actual := tc.resolve_type(value_id)
	value := tc.a.node(value_id)
	mut compatible := tc.expr_compatible(value_id, actual, expected)
	if expected is OptionType && actual !is OptionType {
		compatible = false
	}
	if value.kind == .float_literal && expected.name() != actual.name() {
		compatible = false
	}
	if value.kind == .char_literal && unalias_type(expected) !is Rune {
		compatible = false
	}
	if compatible {
		return
	}
	tc.record_error_at(.assignment_mismatch, 'invalid map ${slot}: expected `${expected.name()}`, not `${tc.diagnostic_expr_type_name(value_id,
		actual)}`', value_id, value.pos)
}

fn (mut tc TypeChecker) check_spawn_expr(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	child_id := tc.a.child(node, 0)
	child := tc.a.node(child_id)
	if child.kind == .or_expr && child.children_count >= 2 {
		call_id := tc.a.child(child, 0)
		call := tc.a.node(call_id)
		if call.kind == .call {
			tc.check_node(child_id)
			fallback_id := tc.a.child(child, 1)
			tc.record_error_at(.call_arg_mismatch,
				'option handling cannot be done in `spawn` call. Do it when calling `.wait()`',
				child_id, tc.or_block_operator_pos(call_id, fallback_id))
			return
		}
	}
	error_count := tc.errors.len
	if child.kind != .call {
		tc.record_error_at(.call_arg_mismatch, 'expression in `spawn` must be a function call',
			child_id, child.pos)
	}
	if child.kind == .call {
		if info := tc.resolve_call_info(child_id, *child) {
			callee := tc.a.child_node(child, 0)
			if callee.kind == .selector && callee.children_count > 0
				&& tc.mut_receiver_methods[info.name] {
				receiver_id := tc.a.child(callee, 0)
				tc.record_error_at(.call_arg_mismatch,
					'method in `spawn` statement cannot have non-reference mutable receiver',
					receiver_id, tc.a.node(receiver_id).pos)
			} else {
				for i in 1 .. child.children_count {
					arg_id := tc.call_arg_value(tc.a.child(child, i))
					arg := tc.a.node(arg_id)
					param_idx := i - 1 + if info.has_receiver { 1 } else { 0 }
					if arg.is_mut && tc.call_param_is_mut(info, param_idx)
						&& !tc.call_param_requires_mut_pointer_slot(info, param_idx)
						&& unalias_type(tc.resolve_type(arg_id)) !is Pointer {
						tc.record_error_at(.call_arg_mismatch,
							'function in `spawn` statement cannot contain mutable non-reference arguments',
							arg_id, arg.pos)
					}
				}
			}
		}
	}
	tc.check_node(child_id)
	if child.kind == .call && tc.new_error_kind_since(error_count, .unknown_fn)
		&& !tc.call_targets_later_local_binding(child) {
		tc.record_error_at(.assignment_mismatch, 'invalid expr', child_id, child.pos)
	}
	_ = id
}

fn (tc &TypeChecker) call_targets_later_local_binding(call flat.Node) bool {
	if call.children_count == 0 || tc.fn_context.node_id < 0 {
		return false
	}
	callee := tc.a.child_node(&call, 0)
	if callee.kind != .ident {
		return false
	}
	fn_id := flat.NodeId(tc.fn_context.node_id)
	if !tc.valid_node_id(fn_id) {
		return false
	}
	mut stack := []flat.NodeId{}
	stack << fn_id
	for stack.len > 0 {
		current_id := stack.pop()
		current := tc.a.node(current_id)
		if current.kind == .decl_assign && current.pos.offset > call.pos.offset {
			for i := 0; i + 1 < current.children_count; i += 2 {
				lhs := tc.a.child_node(current, i)
				if lhs.kind == .ident && lhs.value == callee.value {
					return true
				}
			}
		}
		for i in 0 .. current.children_count {
			stack << tc.a.child(current, i)
		}
	}
	return false
}

fn (tc &TypeChecker) paren_expr_has_redundant_parentheses(id flat.NodeId) bool {
	parent_id := tc.direct_parent_id(id)
	if tc.valid_node_id(parent_id) && tc.a.node(parent_id).kind == .paren {
		return false
	}
	text := tc.source_text_for_node(id).trim_space()
	return text.starts_with('((')
}

fn (mut tc TypeChecker) check_map_duplicate_keys(node flat.Node) {
	mut seen := map[string]bool{}
	mut seen_floats := []f64{}
	for i := 0; i + 1 < node.children_count; i += 2 {
		key_id := tc.a.child(&node, i)
		key := tc.a.node(key_id)
		mut duplicate := false
		mut display := key.value
		match key.kind {
			.string_literal {
				map_key := 'string:${key.value}'
				duplicate = seen[map_key]
				seen[map_key] = true
			}
			.int_literal {
				value := v_int_literal_value(key.value) or { continue }
				map_key := 'int:${value}'
				duplicate = seen[map_key]
				seen[map_key] = true
			}
			.float_literal {
				value := key.value.f64()
				for previous in seen_floats {
					if previous == value {
						duplicate = true
						break
					}
				}
				seen_floats << value
			}
			else {
				continue
			}
		}
		if duplicate {
			tc.record_error_at(.duplicate_decl, 'duplicate key "${display}" in map literal',
				key_id, key.pos)
		}
	}
}

fn (mut tc TypeChecker) check_array_literal_element_types(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		if node.typ.len == 0 {
			if expected := tc.expected_context_for_expr(id) {
				if array_like_elem_type(expected) != none {
					tc.register_synth_type(id, expected)
					return
				}
			}
			tc.record_error_at(.assignment_mismatch,
				'array_init: no type specified (maybe: `[]Type{}` instead of `[]`)', id, node.pos)
		}
		return
	}
	if node.typ.len > 0 {
		declared := unalias_type(tc.parse_type(node.typ))
		if declared is ArrayFixed && declared.len != int(node.children_count) {
			tc.record_error_at(.assignment_mismatch,
				'fixed array expects ${declared.len} value(s), but got ${node.children_count}', id,
				tc.fixed_array_value_list_pos(node))
		}
	}
	first_id := tc.a.child(&node, 0)
	if tc.a.nodes[int(first_id)].kind == .none_expr {
		tc.record_error(.assignment_mismatch,
			'invalid expression `none`, it is not an array of Option type', first_id)
		return
	}
	array_type := unalias_type(tc.resolve_type(id))
	elem_type := match array_type {
		Array { array_type.elem_type }
		ArrayFixed { array_type.elem_type }
		else { return }
	}
	if elem_type is Unknown {
		return
	}
	if elem_type is Void {
		tc.record_error(.assignment_mismatch, 'invalid void array element type', tc.a.child(&node,
			0))
		return
	}
	if node.children_count < 2 {
		return
	}
	for i in 1 .. node.children_count {
		child_id := tc.a.child(&node, i)
		actual := tc.resolve_type(child_id)
		is_option_mismatch := (actual is OptionType) != (elem_type is OptionType)
		is_pointer_mismatch := elem_type is Pointer && actual !is Pointer
		if actual is Unknown || (tc.expr_compatible(child_id, actual, elem_type)
			&& !is_option_mismatch && !is_pointer_mismatch) {
			continue
		}
		actual_name := tc.array_element_diagnostic_type_name(child_id, actual)
		elem_name := tc.array_element_diagnostic_type_name(tc.a.child(&node, 0), elem_type)
		if actual is OptionType && elem_type !is OptionType {
			tc.record_error_at(.assignment_mismatch,
				'cannot use `?${actual.base_type.name()}` as `${elem_name}`, it must be unwrapped first',
				child_id, tc.array_element_value_pos(child_id))
			continue
		}
		if elem_type is OptionType && actual !is OptionType {
			tc.record_error_at(.assignment_mismatch,
				'cannot use `${actual_name}` as `?${elem_type.base_type.name()}`', child_id,
				tc.array_element_value_pos(child_id))
			continue
		}
		if elem_type is Pointer && elem_type.base_type !is Void && actual !is Pointer {
			tc.record_error(.assignment_mismatch,
				'cannot have non-pointer of type `${actual_name}` in a pointer array of type `&${elem_type.base_type.name()}`',
				child_id)
			continue
		}
		tc.record_error_at(.assignment_mismatch,
			'invalid array element: expected `${elem_name}`, not `${actual_name}`', child_id,
			tc.array_element_diagnostic_pos(child_id))
	}
}

fn (tc &TypeChecker) fixed_array_value_list_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, int_min(node.pos.offset, source.len))
	end := int_max(start, int_min(node.pos.end, source.len))
	if start < end {
		first := source[start..end].index('[') or { return node.pos }
		after_first := start + first + 1
		if after_first < end {
			if second := source[after_first..end].index('[') {
				value_start := after_first + second
				return token.new_span(node.pos.id, value_start, end)
			}
		}
	}
	return node.pos
}

fn (tc &TypeChecker) array_element_value_pos(id flat.NodeId) token.Pos {
	node := tc.a.nodes[int(id)]
	if node.kind in [.ident, .selector] {
		return tc.node_value_diagnostic_pos(id)
	}
	return node.pos
}

fn (tc &TypeChecker) index_suffix_diagnostic_pos(id flat.NodeId) token.Pos {
	if !tc.valid_node_id(id) {
		return token.Pos{}
	}
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, int_min(node.pos.offset, source.len))
	end := int_max(start, int_min(node.pos.end, source.len))
	if relative := source[start..end].last_index('[') {
		suffix_start := start + relative
		return token.new_span(node.pos.id, suffix_start, end)
	}
	return node.pos
}

fn (tc &TypeChecker) slice_expr_base_is_mutable(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind != .index || node.value != 'range' || node.children_count < 1 {
		return false
	}
	return tc.expr_root_is_mutable_lvalue(tc.a.child(node, 0))
}

fn (mut tc TypeChecker) record_implicit_slice_clone_notice(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind != .index || node.value != 'range' || node.children_count < 1 {
		return
	}
	pos := tc.index_suffix_diagnostic_pos(id)
	file := tc.a.source_files[pos.id] or { return }
	detail := v3errors.formatted_source_error('details:',
		'To silence this notice, use either an explicit `a[..].clone()`,\nor use an explicit `unsafe{ a[..] }`, if you do not want a copy of the slice.',
		file, pos)
	tc.record_notice_with_details_at(.assignment_mismatch,
		'an implicit clone of the slice was done here', id, pos, [detail])
}

fn (tc &TypeChecker) array_element_diagnostic_type_name(id flat.NodeId, typ Type) string {
	node := tc.a.nodes[int(id)]
	if node.kind == .block && node.value == 'unsafe' && tc.node_contains_nil_literal(id) {
		return 'voidptr'
	}
	if node.kind == .int_literal {
		return typ.name()
	}
	return tc.diagnostic_expr_type_name(id, typ)
}

fn (tc &TypeChecker) node_contains_nil_literal(id flat.NodeId) bool {
	node := tc.a.nodes[int(id)]
	if node.kind == .nil_literal {
		return true
	}
	for i in 0 .. node.children_count {
		if tc.node_contains_nil_literal(tc.a.child(&node, i)) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) array_element_diagnostic_pos(id flat.NodeId) token.Pos {
	node := tc.a.nodes[int(id)]
	if node.kind != .block || node.value != 'unsafe' {
		return node.pos
	}
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	position := file.position(node.pos)
	line_start := file.line_start(position.line)
	line_end := source.index_after('\n', line_start) or { source.len }
	line := source[line_start..line_end]
	if unsafe_start := line.index('unsafe {') {
		start := line_start + unsafe_start
		return token.new_span(node.pos.id, start, start + 'unsafe'.len)
	}
	return node.pos
}

fn (mut tc TypeChecker) check_dump_expr(node flat.Node) {
	if node.children_count == 0 {
		return
	}
	expr_id := tc.a.child(&node, 0)
	invalid_import_function := tc.invalid_unknown_import_function_print_arg(expr_id)
	error_count := tc.errors.len
	tc.check_node(expr_id)
	expr_type := tc.resolve_type(expr_id)
	if unalias_type(expr_type) is Char {
		tc.record_error_at(.assignment_mismatch,
			'`char` values cannot be dumped directly, use dump(u8(x)) or dump(int(x)) instead',
			expr_id, tc.a.node(expr_id).pos)
		return
	}
	mut private_type := unalias_type(expr_type)
	for private_type is OptionType || private_type is ResultType || private_type is Pointer {
		private_type = match private_type {
			OptionType { unalias_type(private_type.base_type) }
			ResultType { unalias_type(private_type.base_type) }
			Pointer { unalias_type(private_type.base_type) }
			else { private_type }
		}
	}
	if private_type is Struct {
		if visibility := tc.private_declaration(private_type.name) {
			if tc.concrete_method_signature_key(private_type.name, 'str') == none {
				type_name := tc.diagnostic_type_name(Type(private_type))
				module_name := if type_name.contains('.') {
					type_name.all_before_last('.')
				} else {
					visibility.module_name
				}
				tc.record_error_at(.assignment_mismatch,
					'cannot dump private type `${type_name}` outside module `${module_name}` without an explicit `str()` method',
					expr_id, tc.a.node(expr_id).pos)
				return
			}
		}
	}
	if expr_type is Void
		|| (expr_type is Unknown && (invalid_import_function || tc.expr_subtree_has_error(expr_id)))
		|| tc.new_error_kind_since(error_count, .unknown_fn) {
		expr := tc.a.node(expr_id)
		pos := if expr.kind == .call {
			if callee, _, _ := tc.unknown_import_function_call_parts(expr) {
				tc.method_call_name_pos(expr, callee)
			} else {
				expr.pos
			}
		} else {
			expr.pos
		}
		tc.record_error_at(.assignment_mismatch, 'dump expression can not be void', expr_id, pos)
	}
}

fn (mut tc TypeChecker) check_assert_stmt(node flat.Node) {
	if node.children_count == 0 {
		return
	}
	condition_id := tc.a.child(&node, 0)
	tc.check_node(condition_id)
	if node.children_count > 1 {
		message_id := tc.a.child(&node, 1)
		tc.check_node(message_id)
		message_type := tc.resolve_type(message_id)
		if !unalias_type(message_type).is_string() {
			tc.record_error_at(.condition_mismatch, 'assert allows only a single string as its second argument, but found `${tc.diagnostic_expr_type_name(message_id,
				message_type)}` instead', message_id, tc.a.node(message_id).pos)
		}
	}
	condition_type := if tc.expr_has_multi_match_member_error(condition_id) {
		Type(void_)
	} else {
		tc.resolve_type(condition_id)
	}
	if condition_type is Unknown || unalias_type(condition_type).name() == 'bool' {
		return
	}
	clean_condition := unalias_type(condition_type)
	condition_name := if clean_condition is OptionType
		&& unalias_type(clean_condition.base_type).name() == 'bool' {
		'bool'
	} else {
		condition_type.name()
	}
	tc.record_error_at(.condition_mismatch,
		'assert can be used only with `bool` expressions, but found `${condition_name}` instead',
		condition_id, tc.assert_condition_diagnostic_pos(condition_id))
}

fn (tc &TypeChecker) expr_has_multi_match_member_error(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	root := tc.a.node(id)
	return tc.errors.any(it.pos.id == root.pos.id && it.pos.offset >= root.pos.offset
		&& it.pos.end <= root.pos.end && (it.msg.contains(' has no field or method `')
		|| it.msg.starts_with('unknown method: `')))
}

fn (tc &TypeChecker) expr_contains_multi_pattern_subject_member(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind == .selector && node.children_count > 0
		&& tc.ident_is_multi_pattern_match_subject(tc.a.child(node, 0)) {
		return true
	}
	for i in 0 .. node.children_count {
		if tc.expr_contains_multi_pattern_subject_member(tc.a.child(node, i)) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) assert_condition_diagnostic_pos(condition_id flat.NodeId) token.Pos {
	condition := tc.a.nodes[int(condition_id)]
	file := tc.a.source_files[condition.pos.id] or { return condition.pos }
	source := tc.source_texts_by_file[file.name] or { return condition.pos }
	position := file.position(condition.pos)
	line_start := file.line_start(position.line)
	line_end := source.index_after('\n', line_start) or { source.len }
	if line_start < line_end {
		line := source[line_start..line_end]
		assert_relative := line.index('assert ') or { return condition.pos }
		start := line_start + assert_relative + 'assert '.len
		end := line_start + line.trim_right(' \t\r\n').len
		return token.new_span(condition.pos.id, start, end)
	}
	return condition.pos
}

fn valid_utf8_string(value string) bool {
	mut i := 0
	for i < value.len {
		first := value[i]
		if first < 0x80 {
			i++
			continue
		}
		mut continuation_count := 0
		mut second_min := u8(0x80)
		mut second_max := u8(0xbf)
		if first >= 0xc2 && first <= 0xdf {
			continuation_count = 1
		} else if first >= 0xe0 && first <= 0xef {
			continuation_count = 2
			if first == 0xe0 {
				second_min = 0xa0
			} else if first == 0xed {
				second_max = 0x9f
			}
		} else if first >= 0xf0 && first <= 0xf4 {
			continuation_count = 3
			if first == 0xf0 {
				second_min = 0x90
			} else if first == 0xf4 {
				second_max = 0x8f
			}
		} else {
			return false
		}
		if i + continuation_count >= value.len {
			return false
		}
		second := value[i + 1]
		if second < second_min || second > second_max {
			return false
		}
		for j in 2 .. continuation_count + 1 {
			if value[i + j] < 0x80 || value[i + j] > 0xbf {
				return false
			}
		}
		i += continuation_count + 1
	}
	return true
}

fn (tc &TypeChecker) string_literal_source_is_valid_utf8(pos token.Pos) bool {
	file := tc.a.source_files[pos.id] or { return true }
	source := tc.source_texts_by_file[file.name] or { return true }
	if pos.offset < 0 || pos.end > source.len || pos.offset >= pos.end {
		return true
	}
	return valid_utf8_string(source[pos.offset..pos.end])
}

fn (tc &TypeChecker) string_literal_diagnostic_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, int_min(node.pos.offset, source.len))
	if start >= source.len || source[start] !in [`'`, `"`] {
		return node.pos
	}
	quote := source[start]
	mut i := start + 1
	for i < source.len {
		if source[i] == `\\` {
			i += 2
			continue
		}
		if source[i] == quote {
			return token.new_span(node.pos.id, start, i + 1)
		}
		if source[i] == `\n` {
			break
		}
		i++
	}
	return node.pos
}

fn (tc &TypeChecker) string_interpolation_expr_pos(expr_id flat.NodeId) token.Pos {
	expr := tc.a.nodes[int(expr_id)]
	if expr.kind == .call && expr.children_count > 0 {
		callee := tc.a.child_node(&expr, 0)
		if callee.kind == .selector {
			return tc.method_call_name_pos(expr, callee)
		}
	}
	file := tc.a.source_files[expr.pos.id] or { return expr.pos }
	source := tc.source_texts_by_file[file.name] or { return expr.pos }
	mut start := int_max(0, expr.pos.offset)
	mut end := int_min(expr.pos.end, source.len)
	if start + 3 <= end && source[start] in [`'`, `"`] && source[start + 1] == `$`
		&& source[start + 2] == `{` {
		start += 2
	} else if start + 2 <= end && source[start] == `$` && source[start + 1] == `{` {
		start += 2
	}
	if start < end && source[end - 1] == `}` {
		end--
	}
	return token.new_span(expr.pos.id, start, end)
}

fn (mut tc TypeChecker) check_string_interpolation_format(id flat.NodeId, node flat.Node, expr_id flat.NodeId) {
	fmt := node.typ
	if fmt.len == 0 {
		return
	}
	mut letters := []u8{}
	for ch in fmt {
		if (ch >= `a` && ch <= `z`) || (ch >= `A` && ch <= `Z`) {
			letters << ch
		}
	}
	if letters.len > 1 {
		tc.record_error_at(.call_arg_mismatch, 'format specifier may only be one letter', id,
			node.pos)
		return
	}
	if letters.len == 0 {
		return
	}
	spec := letters[0]
	spec_pos := token.new_span(node.pos.id, node.pos.end - 1, node.pos.end)
	known := spec in [`d`, `u`, `x`, `X`, `o`, `b`, `c`, `s`, `e`, `E`, `f`, `F`, `g`, `G`]
	if !known {
		tc.record_error_at(.call_arg_mismatch, 'unknown format specifier `${spec.ascii_str()}`',
			id, spec_pos)
	}
	actual := tc.resolve_type(expr_id)
	clean := unalias_type(actual)
	if fmt.contains('.') && !clean.is_float() {
		tc.record_error_at(.call_arg_mismatch,
			'precision specification only valid for float types', id, spec_pos)
		return
	}
	mut allowed := false
	if clean.is_string() {
		allowed = spec == `s`
	} else if clean.is_float() {
		allowed = spec in [`e`, `E`, `f`, `F`, `g`, `G`]
	} else if clean.is_integer() {
		is_unsigned := if clean is Primitive { clean.props.has(.unsigned) } else { clean is USize }
		allowed = if is_unsigned {
			spec in [`u`, `x`, `X`, `o`, `b`, `c`]
		} else {
			spec in [`d`, `x`, `X`, `o`, `b`, `c`]
		}
	}
	if !allowed {
		actual_name := if tc.a.node(expr_id).kind == .none_expr { 'none' } else { actual.name() }
		tc.record_error_at(.call_arg_mismatch,
			'illegal format specifier `${spec.ascii_str()}` for type `${actual_name}`', id,
			spec_pos)
	}
}

fn (mut tc TypeChecker) check_prefix_expr(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	child_id := tc.a.child(&node, 0)
	child := tc.a.node(child_id)
	if node.op == .minus && child.kind == .int_literal {
		tc.check_untyped_integer_literal_overflow(id)
	}
	if node.value == 'unexpected_amp' {
		tc.record_error_at(.assignment_mismatch, 'unexpected `&`, expecting expression', id,
			node.pos)
		return
	}
	if node.op == .amp && child.kind == .nil_literal {
		tc.record_error_at(.assignment_mismatch, 'invalid operation: cannot take address of nil',
			id, tc.address_operator_pos(id))
		return
	}
	if node.op == .amp && child.kind == .paren && child.children_count == 1 {
		inner := tc.a.child_node(child, 0)
		if inner.kind == .struct_init {
			tc.record_notice_at(.assignment_mismatch,
				'unnecessary `()`, use `&${inner.value}{....}` instead of `&(${inner.value}{....})`',
				child_id, child.pos)
		}
	}
	if node.op == .amp && tc.address_operand_is_method_value(child_id) {
		display := strip_redundant_outer_parens(tc.source_text_for_node(child_id))
		tc.record_error_at(.assignment_mismatch, 'cannot take the address of ${display}', id,
			tc.address_operator_pos(id))
		return
	}
	tc.check_node(child_id)
	child_type := unalias_type(tc.resolve_type(child_id))
	if child_type is Unknown {
		return
	}
	if node.op == .amp && tc.source_text_for_node(id).trim_space().starts_with('&')
		&& tc.unsafe_depth == 0 && !tc.expr_is_inside_unsafe_block(id) {
		if fixed_array_id := tc.fixed_array_reference_ident(child_id) {
			name := tc.a.node(fixed_array_id).value
			tc.record_error_at(.assignment_mismatch,
				'cannot reference fixed array `${name}` outside `unsafe` blocks as it is supposed to be stored on stack',
				fixed_array_id, tc.node_value_diagnostic_pos(fixed_array_id))
			return
		}
	}
	if node.op == .arrow {
		channel_type := unalias_and_unwrap_pointer_type(child_type)
		if channel_type !is Channel {
			tc.record_error_at(.assignment_mismatch,
				'operator `<-` can only be used with `chan` types, but the value after `<-` is of type `${child_type.name()}` instead',
				id, tc.prefix_operator_pos(id, '<-'))
		}
		return
	}
	if node.op in [.plus, .minus] && !infix_power_type_is_numeric(child_type) {
		op := if node.op == .minus { '-' } else { '+' }
		tc.record_error_at(.assignment_mismatch,
			'operator `${op}` can only be used with numeric types, but the value after `${op}` is of type `${child_type.name()}` instead',
			id, tc.prefix_operator_pos(id, op))
		return
	}
	if node.op == .bit_not && child_type is Enum {
		if !child_type.is_flag {
			tc.record_error_at(.assignment_mismatch,
				'operator `~` can only be used with `@[flag]` tagged enums', id, tc.prefix_operator_pos(id,
				'~'))
		}
		return
	}
	if node.op == .bit_not && !child_type.is_integer() {
		tc.record_error_at(.assignment_mismatch, 'operator `~` can only be used with integer types, but the value after `~` is of type `${tc.diagnostic_expr_type_name(child_id,
			child_type)}` instead', id, tc.prefix_operator_pos(id, '~'))
		return
	}
	if node.op == .not && !tc.type_compatible(child_type, Type(bool_)) {
		tc.record_error_at(.assignment_mismatch, 'operator `!` can only be used with bool types, but the value after `!` is of type `${tc.diagnostic_expr_type_name(child_id,
			child_type)}` instead', id, tc.prefix_operator_pos(id, '!'))
		return
	}
	if node.op == .mul && child_type !is Pointer && child_type !is OptionType {
		tc.record_error_at(.assignment_mismatch,
			'invalid indirect of `${child_type.name()}`, the type `${child_type.name()}` is not a pointer',
			id, tc.prefix_operator_pos(id, '*'))
		return
	}
	if node.op == .mul && child_type is Pointer {
		if child.kind == .nil_literal {
			tc.record_error_at(.assignment_mismatch, 'cannot deference a `nil` pointer', child_id,
				child.pos)
			return
		}
		diagnostic_name := tc.pointer_diagnostic_binding_type_name(child_id, child_type)
		if diagnostic_name == 'nil' {
			tc.record_error_at(.assignment_mismatch, 'cannot deference a `nil` pointer', id,
				tc.node_value_diagnostic_pos(child_id))
			return
		}
		if unalias_type(child_type.base_type) is Void {
			tc.record_error_at(.assignment_mismatch, 'cannot dereference to void', id, tc.prefix_operator_pos(id,
				'*'))
			return
		}
	}
	if node.op == .mul && child_type is OptionType {
		payload := unalias_type(child_type.base_type)
		if payload is Pointer {
			child_text := tc.source_text_for_node(child_id)
			tc.record_error_at(.assignment_mismatch,
				'type `?${payload.base_type.name()}` is an Option, it must be unwrapped first; use `*${child_text}?` to do it',
				child_id, tc.node_value_diagnostic_pos(child_id))
			tc.register_synth_type(id, Type(OptionType{
				base_type: payload.base_type
			}))
			return
		}
	}
	mut address_child := tc.a.nodes[int(child_id)]
	if address_child.kind == .paren && address_child.children_count > 0 {
		address_child = *tc.a.child_node(&address_child, 0)
	}
	if node.op == .amp && address_child.kind == .prefix && address_child.op == .amp {
		tc.record_error_at(.assignment_mismatch, 'cannot take the address of this expression', id, token.new_span(address_child.pos.id,
			address_child.pos.offset, address_child.pos.offset + 1))
		return
	}
	if node.op == .amp && address_child.kind == .selector && address_child.children_count > 0 {
		selector_base_id := tc.a.child(&address_child, 0)
		selector_base := tc.a.node(selector_base_id)
		if selector_base.kind in [.int_literal, .float_literal, .bool_literal, .char_literal,
			.string_literal, .string_interp] {
			operator_pos := tc.address_operator_pos(id)
			tc.record_error_at(.assignment_mismatch, 'cannot take the address of a literal value',
				id, token.new_span(node.pos.id, operator_pos.offset, address_child.pos.end))
			return
		}
		if declared := tc.selector_declared_value_type(address_child) {
			if unalias_type(declared) is OptionType {
				tc.record_error_at(.assignment_mismatch,
					'cannot take the address of an Option field', id, node.pos)
				return
			}
		}
		if selector_base.kind == .struct_init {
			tc.record_error_at(.assignment_mismatch,
				'should not create object instance on the heap to simply access a member', id,
				node.pos)
			return
		}
	}
	if node.op == .amp && address_child.kind == .index && address_child.children_count > 0 {
		base_id := tc.a.child(&address_child, 0)
		base_type := unalias_and_unwrap_pointer_type(tc.resolve_type(base_id))
		if base_type is Map && tc.unsafe_depth == 0 && !tc.expr_is_inside_unsafe_block(id) {
			tc.record_error_at(.assignment_mismatch,
				'cannot take the address of map values outside `unsafe`', child_id,
				tc.index_brackets_pos(address_child))
			return
		}
		if base_type is Array && tc.expr_root_is_mutable_lvalue(child_id) && tc.unsafe_depth == 0
			&& !tc.expr_is_inside_unsafe_block(id) {
			tc.record_error_at(.assignment_mismatch,
				'cannot take the address of mutable array elements outside unsafe blocks',
				child_id, tc.index_brackets_pos(address_child))
			return
		}
	}
	if node.op == .amp && tc.unsafe_depth == 0 && !tc.expr_is_inside_unsafe_block(id)
		&& tc.address_path_contains_map_index(child_id) {
		tc.record_error_at(.assignment_mismatch,
			'cannot take the address of map values outside `unsafe`', id,
			tc.address_operator_pos(id))
		return
	}
	if node.op == .amp && tc.pointer_to_array_reinterpret_cast(child_id) {
		return
	}
	if node.op == .amp && address_child.kind == .array_literal {
		return
	}
	if node.op != .amp || tc.expr_can_take_address(child_id) || address_child.kind == .struct_init {
		return
	}
	display := strip_redundant_outer_parens(tc.source_text_for_node(child_id))
	tc.record_error_at(.assignment_mismatch, 'cannot take the address of ${display}', id,
		tc.address_operator_pos(id))
}

fn (tc &TypeChecker) pointer_to_array_reinterpret_cast(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind != .cast_expr || node.children_count == 0 {
		return false
	}
	target := unalias_type(tc.parse_type(node.value))
	if target !is Array && target !is ArrayFixed {
		return false
	}
	actual := unalias_type(tc.resolve_type(tc.a.child(node, 0)))
	if actual !is Pointer {
		return false
	}
	actual_pointer := actual as Pointer
	return unalias_type(actual_pointer.base_type).name() == target.name()
}

fn (tc &TypeChecker) fixed_array_reference_ident(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind in [.paren, .index] && node.children_count > 0 {
		return tc.fixed_array_reference_ident(tc.a.child(node, 0))
	}
	if node.kind != .ident {
		return none
	}
	raw := tc.resolve_type(id)
	candidate := if raw is Pointer {
		raw.base_type
	} else {
		unalias_type(raw)
	}
	if unalias_type(candidate) is ArrayFixed {
		return id
	}
	return none
}

fn (tc &TypeChecker) address_path_contains_map_index(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind !in [.index, .selector, .paren] || node.children_count == 0 {
		return false
	}
	base_id := tc.a.child(node, 0)
	if node.kind == .index {
		base_type := unalias_and_unwrap_pointer_type(tc.resolve_type(base_id))
		if base_type is Map {
			return true
		}
	}
	return tc.address_path_contains_map_index(base_id)
}

fn strip_redundant_outer_parens(text string) string {
	mut clean := text.trim_space()
	for clean.len >= 2 && clean[0] == `(` && clean[clean.len - 1] == `)` {
		mut depth := 0
		mut encloses_all := true
		for i, ch in clean {
			if ch == `(` {
				depth++
			} else if ch == `)` {
				depth--
				if depth == 0 && i != clean.len - 1 {
					encloses_all = false
					break
				}
			}
		}
		if !encloses_all || depth != 0 {
			break
		}
		clean = clean[1..clean.len - 1].trim_space()
	}
	return clean
}

fn (tc &TypeChecker) address_operand_is_method_value(id flat.NodeId) bool {
	mut operand_id := id
	for tc.valid_node_id(operand_id) {
		operand := tc.a.node(operand_id)
		if operand.kind != .paren || operand.children_count == 0 {
			break
		}
		operand_id = tc.a.child(operand, 0)
	}
	if !tc.valid_node_id(operand_id) {
		return false
	}
	selector := tc.a.node(operand_id)
	if selector.kind != .selector || selector.children_count == 0 {
		return false
	}
	base_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(selector, 0)))
	type_name := resolve_type_name_for_method(base_type)
	if type_name.len == 0 {
		return false
	}
	method_name := '${type_name}.${selector.value}'
	return method_name in tc.fn_ret_types || tc.cached_c_name(method_name) in tc.fn_ret_types
}

fn (tc &TypeChecker) index_brackets_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(node.pos.end, source.len)
	if start < end {
		if open_relative := source[start..end].last_index('[') {
			open := start + open_relative
			if close_relative := source[open..end].index(']') {
				return token.new_span(node.pos.id, open, open + close_relative + 1)
			}
		}
	}
	return node.pos
}

fn (tc &TypeChecker) invalid_address_expr_pos(id flat.NodeId) token.Pos {
	if !tc.valid_node_id(id) {
		return token.Pos{}
	}
	mut node := tc.a.nodes[int(id)]
	if node.kind == .paren && node.children_count > 0 {
		node = *tc.a.child_node(&node, 0)
	}
	if node.kind == .prefix && node.op == .amp {
		file := tc.a.source_files[node.pos.id] or { return node.pos }
		source := tc.source_texts_by_file[file.name] or { return node.pos }
		start := int_max(0, node.pos.offset)
		end := int_min(node.pos.end, source.len)
		if start < end {
			if relative := source[start..end].index('&') {
				op_start := start + relative
				return token.new_span(node.pos.id, op_start, op_start + 1)
			}
		}
	}
	return node.pos
}

fn (mut tc TypeChecker) check_ownership_array_spread_clone(id flat.NodeId, node flat.Node) {
	mut has_spread := false
	for i in 0 .. node.children_count {
		child := tc.a.child_node(&node, i)
		if child.kind == .prefix && child.value == '...' && child.children_count > 0 {
			has_spread = true
			break
		}
	}
	if !has_spread {
		return
	}
	array_type := array_type_from_receiver(tc.resolve_type(id)) or { return }
	if bad_type := tc.ownership_default_clone_missing_method(array_type.elem_type) {
		tc.record_error(.call_arg_mismatch,
			'cannot clone array spread elements: `${bad_type}` requires ownership destruction but has no `clone()` method',
			id)
	}
}

fn (mut tc TypeChecker) check_ownership_map_spread_clone(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	first := tc.a.child_node(&node, 0)
	if first.kind != .prefix || first.value != '...' || first.children_count == 0 {
		return
	}
	map_type := map_type_from_receiver(tc.resolve_type(id)) or { return }
	if bad_type := tc.ownership_default_clone_missing_method(map_type.key_type) {
		tc.record_error(.call_arg_mismatch,
			'cannot clone map spread keys: `${bad_type}` requires ownership destruction but has no `clone()` method',
			id)
	}
	if bad_type := tc.ownership_default_clone_missing_method(map_type.value_type) {
		tc.record_error(.call_arg_mismatch,
			'cannot clone map spread values: `${bad_type}` requires ownership destruction but has no `clone()` method',
			id)
	}
}

fn (mut tc TypeChecker) check_cast_expr(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	child_id := tc.a.child(&node, 0)
	tc.check_node(child_id)
	if node.value == 'any' {
		tc.record_error(.unknown_type, 'cannot use type `any` here', id)
		return
	}
	target := tc.parse_type(node.value)
	if generic_name := tc.bare_generic_decl_type_name(node.value) {
		qualified := tc.qualify_name(generic_name)
		sum_params := tc.sum_generic_params[generic_name] or {
			tc.sum_generic_params[qualified] or { []string{} }
		}
		if sum_params.len > 0 {
			tc.record_error_at(.unknown_type,
				'generic sumtype `${generic_name}` must specify type parameter, e.g. ${generic_name}[int]',
				id, node.pos)
			return
		}
		params := tc.interface_generic_params[generic_name] or {
			tc.interface_generic_params[qualified] or { []string{} }
		}
		if params.len > 0 {
			actual := tc.resolve_type(child_id)
			actual_name := method_type_name(unwrap_pointer(actual))
			interface_name := if generic_name in tc.interface_names {
				generic_name
			} else {
				qualified
			}
			for method in tc.interface_abstract_method_names(interface_name) {
				if tc.concrete_method_signature_key(actual_name, method) == none {
					tc.record_error_at(.assignment_mismatch,
						'can not find method `${method}` on `${actual_name.all_after_last('.')}`, needed for interface: `${generic_name.all_after_last('.')}`',
						id, node.pos)
					return
				}
			}
			tc.record_error_at(.unknown_type,
				'could not infer generic type `${params[0]}` in interface `${generic_name}`', id,
				node.pos)
			return
		}
	}
	generic_name := node.value.all_after_last('.')
	target_is_generic_param := generic_name in tc.fn_context.generic_params
		|| tc.active_generic_param(generic_name)
		|| tc.node_has_enclosing_generic_param(id, generic_name)
		|| tc.source_enclosing_fn_has_generic_param(id, generic_name)
	if target is Unknown {
		if target_is_generic_param {
			actual_generic_source := tc.resolve_type(child_id)
			if fn_param_is_voidptr_type(actual_generic_source) {
				tc.record_error_at(.assignment_mismatch, 'cannot cast `voidptr` to struct', id,
					node.pos)
			}
			return
		}
		tc.record_error_at(.unknown_type, 'unknown type `${node.value}`', id, node.pos)
		return
	}
	if target is Struct && should_check_named_type(node.value) && !tc.type_name_known(node.value)
		&& !target_is_generic_param {
		tc.record_error_at(.unknown_type, 'unknown type `${node.value}`', id, node.pos)
		return
	}
	if target is Pointer {
		target_base := fn_param_unalias_type(target.base_type)
		target_base_name := node.value.trim_left('&')
		if (target_base is Struct || target_base is Unknown)
			&& should_check_named_type(target_base_name) && !tc.type_name_known(target_base_name)
			&& !target_is_generic_param {
			tc.record_error_at(.unknown_type, 'unknown type `${target_base_name}`', id, node.pos)
			return
		}
	}
	if target is Alias && target.base_type is OptionType {
		tc.record_error(.assignment_mismatch,
			'alias to Option type requires to be used as Option type (?${node.value}(...))', id)
		return
	}
	actual := tc.resolve_type(child_id)
	if actual is Void {
		tc.record_error_at(.assignment_mismatch,
			'expression does not return a value so it cannot be cast', child_id,
			tc.a.nodes[int(child_id)].pos)
		return
	}
	if target_struct := struct_type_from_type(target) {
		actual_is_voidptr := fn_param_is_voidptr_type(actual)
			|| (tc.expr_tail_is_nil(child_id)
			&& tc.source_text_for_node(child_id).starts_with('unsafe'))
		if actual_is_voidptr {
			if target is Alias {
				tc.record_error_at(.assignment_mismatch,
					'cannot cast `voidptr` to `${target.name}` (alias to `${target.base_type.name()}`)',
					id, node.pos)
			} else {
				tc.record_error_at(.assignment_mismatch, 'cannot cast `voidptr` to struct', id,
					node.pos)
			}
			_ = target_struct
			return
		}
	}
	if target is OptionType && (actual is None || tc.a.node(child_id).kind == .none_expr) {
		tc.register_synth_type(id, target)
		return
	}
	if actual is None || tc.a.nodes[int(child_id)].kind == .none_expr {
		target_name := if target_fn := fn_type_from_type(target) {
			Type(target_fn).name().replace('fn(', 'fn (')
		} else if node.value.len > 0 {
			node.value
		} else {
			target.name()
		}
		tc.record_error_at(.assignment_mismatch, 'cannot cast `none` to `${target_name}`', id,
			node.pos)
		return
	}
	if actual is OptionType {
		if target is Alias {
			return
		}
		tc.record_error_at(.assignment_mismatch, 'cannot type cast an Option', id, node.pos)
		return
	}
	if actual is ResultType && tc.a.nodes[int(child_id)].kind == .call {
		tc.record_unhandled_result_call(child_id, actual)
		return
	}
	if tc.check_function_cast(id, node, child_id, actual, target) {
		return
	}
	if tc.expr_tail_is_nil(child_id) {
		return
	}
	if actual is Unknown || type_contains_unknown(actual) {
		return
	}
	clean_pointer_target := fn_param_unalias_type(target)
	if clean_pointer_target is Pointer {
		target_pointer := clean_pointer_target as Pointer
		target_name := if node.value.len > 0 { node.value } else { target.name() }
		target_base := fn_param_unalias_type(target_pointer.base_type)
		alias_name := target_name.trim_left('&')
		alias_target_text := tc.type_aliases[alias_name] or {
			tc.type_aliases[tc.qualify_name(alias_name)] or { '' }
		}
		if target_name.starts_with('&') && alias_target_text.starts_with('map[')
			&& unalias_type(actual) is Map {
			tc.record_error_at(.assignment_mismatch,
				'cannot cast to alias pointer `${target_name}` because `${alias_target_text}` is a value',
				id, tc.cast_expression_diagnostic_pos(node, target_name))
			return
		}
		if target_base is Alias && unalias_type(target_base.base_type) is Map
			&& unalias_type(actual) is Map {
			tc.record_error_at(.assignment_mismatch,
				'cannot cast to alias pointer `${target_name}` because `${target_base.base_type.name()}` is a value',
				id, node.pos)
			return
		}
		if infix_power_type_is_numeric(actual) && target_name !in ['voidptr', 'byteptr', 'charptr'] {
			if tc.cast_operand_is_zero(child_id) {
				kind := if struct_type_from_type(target_base) != none {
					'a struct pointer'
				} else {
					'a pointer'
				}
				tc.record_error_at(.assignment_mismatch,
					'cannot null cast ${kind}, use ${target_name}(unsafe { nil })', id, tc.cast_expression_diagnostic_pos(node,
					target_name))
				return
			}
			if tc.unsafe_depth == 0 {
				message := if struct_type_from_type(target_base) != none {
					'cannot cast int to a struct pointer outside `unsafe`'
				} else {
					'cannot cast a number to `${target_name}` outside `unsafe`'
				}
				tc.record_error_at(.assignment_mismatch, message, id, node.pos)
				return
			}
		}
		if tc.unsafe_depth == 0 && fn_param_is_voidptr_type(actual) {
			if unalias_type(target_base) is SumType {
				tc.record_error_at(.assignment_mismatch,
					'cannot cast voidptr to `${target_name}` outside `unsafe`', id, node.pos)
			} else {
				tc.record_warning_at(.assignment_mismatch,
					'casting voidptr to `${target_name}` is only allowed in `unsafe` code', id,
					node.pos)
			}
			return
		}
		if tc.unsafe_depth == 0 && unalias_type(actual) is Pointer
			&& struct_type_from_type(target_base) != none && actual.name() != target_name {
			tc.record_warning_at(.assignment_mismatch,
				'casting `${actual.name()}` to `${target_name}` is only allowed in `unsafe` code',
				id, node.pos)
			return
		}
	}
	tc.check_integer_literal_cast_overflow(id, node, child_id, target)
	clean_target := unalias_type(target)
	clean_actual := unalias_type(actual)
	if clean_actual is ArrayFixed && clean_target is Pointer && !tc.node_is_in_translated_file(id) {
		tc.record_warning_at(.assignment_mismatch,
			'cannot cast a fixed array (use e.g. `&arr[0]` instead)', id, node.pos)
	}
	if (clean_target is Array || clean_target is ArrayFixed)
		&& (clean_actual is Pointer || fn_param_is_voidptr_type(clean_actual)) {
		mut points_to_target := false
		if clean_actual is Pointer {
			actual_pointer := clean_actual as Pointer
			actual_base := unalias_type(actual_pointer.base_type)
			points_to_target = actual_base.name() == clean_target.name()
		}
		if !points_to_target {
			full_pos := tc.cast_expression_diagnostic_pos(node, node.value)
			tc.record_error_at(.assignment_mismatch,
				'cannot cast pointer type `${actual.name()}` to array type `${target.name()}`', id, token.new_pos(full_pos.id,
				full_pos.offset))
			return
		}
	}
	if clean_target is SumType && !tc.direct_sum_assignment_variant_matches(actual, clean_target) {
		tc.record_error_at(.assignment_mismatch,
			'cannot cast `${actual.name()}` to `${target.name()}`', id, node.pos)
		return
	}
	if clean_target is Enum && infix_power_type_is_numeric(clean_actual) && tc.unsafe_depth == 0 {
		tc.record_error_at(.assignment_mismatch,
			'casting numbers to enums, should be done inside `unsafe{}` blocks', id, node.pos)
		return
	}
	if clean_target is Enum && infix_power_type_is_numeric(clean_actual) && tc.unsafe_depth > 0 {
		tc.warn_invalid_enum_cast(id, node, child_id, clean_target)
	}
	if tc.a.node(child_id).kind in [.int_literal, .float_literal, .bool_literal, .char_literal, .string_literal]
		&& (clean_target is Array || clean_target is ArrayFixed || clean_target is Map) {
		tc.record_error_at(.assignment_mismatch,
			'cannot cast literal value to ${target.name()} type', id, node.pos)
		return
	}
	if clean_target is Primitive && clean_target.props.has(.boolean) {
		tc.record_error_at(.assignment_mismatch,
			'cannot cast to bool - use e.g. `some_int != 0` instead', id, node.pos)
		return
	}
	if clean_target is Primitive
		&& (clean_target.props.has(.integer) || clean_target.props.has(.float)) {
		if clean_actual is Array {
			tc.record_error_at(.assignment_mismatch,
				'cannot cast array `${actual.name()}` to `${target.name()}`', id, node.pos)
			return
		}
		if clean_actual is FnType {
			tc.record_error_at(.assignment_mismatch,
				'cannot cast function `${tc.source_text_for_node(child_id)}` to `${target.name()}`',
				id, node.pos)
			return
		}
		if clean_actual is Struct {
			message := if clean_actual.name.starts_with('C.') {
				'cannot cast type `${actual.name()}` to `${target.name()}`'
			} else {
				'cannot cast struct `${actual.name()}` to `${target.name()}`'
			}
			tc.record_error_at(.assignment_mismatch, message, id, node.pos)
			return
		}
		if clean_actual is SumType {
			tc.record_error_at(.assignment_mismatch,
				'cannot cast `${actual.name()}` sum type value to `${target.name()}`, use `${tc.source_text_for_node(child_id)} as ${target.name()}` instead',
				id, node.pos)
			return
		}
	}
	if clean_target is Rune && clean_actual is Struct {
		tc.record_error_at(.assignment_mismatch, 'cannot cast struct `${actual.name()}` to `rune`',
			id, node.pos)
		return
	}
	if target is Alias && unalias_type(target.base_type) is String && clean_actual !is String {
		tc.record_error_at(.assignment_mismatch, 'cannot cast `${tc.diagnostic_expr_type_name(child_id,
			actual)}` to `${target.name}` (alias to `${target.base_type.name()}`)', id, node.pos)
		return
	}
	if tc.check_cast_to_string(id, node, child_id, actual, target) {
		return
	}
	if tc.check_cast_from_string(id, node, child_id, actual, target) {
		return
	}
	if is_ierror_type(target)
		&& (actual is None || (actual is OptionType && actual.base_type is Void)) {
		return
	}
	if target_struct := struct_type_from_type(target) {
		clean_actual_pointer := fn_param_unalias_type(actual)
		if target is Alias && clean_actual_pointer is Pointer {
			actual_base := struct_type_from_type(clean_actual_pointer.base_type)
			if source_struct := actual_base {
				if source_struct.name == target_struct.name {
					tc.record_error_at(.assignment_mismatch,
						'cannot cast `${actual.name()}` to `${target.name}`, you must dereference it first (e.g. ${target.name}(*var))',
						id, node.pos)
					return
				}
			}
		}
		actual_struct := struct_type_from_type(actual)
		if source_struct := actual_struct {
			if target is Alias && source_struct.name == target_struct.name {
				return
			}
			tc.record_warning_at(.assignment_mismatch,
				'casting to struct is deprecated, use e.g. `Struct{...expr}` instead', id, node.pos)
			if source_struct.name != target_struct.name {
				tc.record_error(.assignment_mismatch,
					'cannot convert struct `${actual.name()}` to struct `${target.name()}`', id)
			}
			return
		}
		actual_name := tc.diagnostic_expr_type_name(child_id, actual)
		tc.record_error(.assignment_mismatch, 'cannot cast `${actual_name}` to struct', id)
		if unalias_type(actual) is SumType {
			tc.record_error(.assignment_mismatch,
				'cannot cast `${actual.name()}` sum type value to `${target.name()}`, use `${tc.source_text_for_node(child_id)} as ${target.name()}` instead',
				id)
		}
		return
	}
	target_iface := cast_target_interface(target) or { return }
	mut embedding_path := map[string]bool{}
	if tc.interface_embedding_exceeds(target_iface.name, 0, mut embedding_path) {
		decl_id, decl_pos := tc.interface_declaration_diagnostic(target_iface.name)
		tc.record_error_at(.unknown_type,
			'too many interface embedding levels: 101, for interface `${target_iface.name.all_after_last('.')}`',
			decl_id, decl_pos)
		return
	}
	if clean_actual is FnType {
		tc.record_error_at(.assignment_mismatch,
			'cannot implement interface `${target_iface.name}` using function', child_id,
			tc.a.node(child_id).pos)
		return
	}
	if clean_actual is Interface
		&& tc.interface_metadata_name(clean_actual.name) != tc.interface_metadata_name(target_iface.name) {
		tc.record_error_at(.assignment_mismatch,
			'cannot implement interface `${target_iface.name}` with a different interface `${clean_actual.name}`',
			id, node.pos)
		return
	}
	// A pointer to an interface may be explicitly reconstructed from a raw pointer.
	// The pointee already has interface storage, so this is a pointer cast rather
	// than an interface implementation conversion.
	if target is Pointer && fn_param_is_voidptr_type(actual) {
		return
	}
	if tc.interface_field_list(target_iface.name).any(it.is_mut) {
		child := tc.a.node(child_id)
		if child.kind == .ident && !tc.ident_is_mutable_lvalue(child.value) {
			tc.record_error_at(.assignment_mismatch,
				'`${child.value}` is immutable, declare it with `mut` to make it mutable',
				child_id, tc.node_value_diagnostic_pos(child_id))
			return
		}
	}
	if !tc.type_implements_interface(actual, target_iface) {
		actual_name := actual.name()
		tc.record_interface_implementation_error(.assignment_mismatch, actual, target_iface, id,
			node.pos)
		tc.record_error_at(.assignment_mismatch,
			'`${actual_name}` does not implement interface `${target_iface.name}`, cannot cast `${actual_name}` to interface `${target_iface.name}`',
			id, node.pos)
	}
}

fn (tc &TypeChecker) interface_embedding_exceeds(iface_name string, depth int, mut path map[string]bool) bool {
	if depth > 100 {
		return true
	}
	name := tc.interface_metadata_name(iface_name)
	if path[name] {
		return false
	}
	path[name] = true
	for embed in tc.interface_embeds[name] or { []string{} } {
		if tc.interface_embedding_exceeds(embed, depth + 1, mut path) {
			path.delete(name)
			return true
		}
	}
	path.delete(name)
	return false
}

fn (tc &TypeChecker) interface_declaration_diagnostic(iface_name string) (flat.NodeId, token.Pos) {
	short_name := iface_name.all_after_last('.')
	for idx in tc.top_level_idx {
		node := tc.a.nodes[idx]
		if node.kind == .interface_decl && node.value.all_after_last('.') == short_name {
			node_id := flat.NodeId(idx)
			return node_id, tc.source_line_declaration_pos(node_id)
		}
	}
	return flat.empty_node, token.Pos{}
}

// check_interface_embedding_limits rejects deep interface casts before requirement
// indexes recursively expand the embedding chain.
pub fn (mut tc TypeChecker) check_interface_embedding_limits() bool {
	mut embedded := map[string]bool{}
	for _, embeds in tc.interface_embeds {
		for embed in embeds {
			embedded[tc.interface_metadata_name(embed)] = true
		}
	}
	for idx in tc.top_level_idx {
		node := tc.a.nodes[idx]
		if node.kind != .interface_decl {
			continue
		}
		iface_name := tc.interface_metadata_name(node.value)
		if embedded[iface_name] {
			continue
		}
		mut embedding_path := map[string]bool{}
		if !tc.interface_embedding_exceeds(iface_name, 0, mut embedding_path) {
			continue
		}
		decl_id, decl_pos := tc.interface_declaration_diagnostic(iface_name)
		tc.errors << tc.make_type_error_at(.unknown_type,
			'too many interface embedding levels: 101, for interface `${iface_name.all_after_last('.')}`',
			decl_id, decl_pos)
		return true
	}
	return false
}

fn (tc &TypeChecker) interface_diagnostic_owner(signature_key string, fallback string) string {
	mut owner := signature_key.all_before_last('.')
	if owner.len == 0 {
		owner = fallback
	}
	if owner.contains('.') {
		return owner
	}
	mut mod_name := tc.fn_type_modules[signature_key] or { '' }
	if mod_name.len == 0 {
		mod_name = tc.struct_modules[fallback] or { tc.cur_module }
	}
	if mod_name.len == 0 {
		mod_name = 'main'
	}
	return '${mod_name}.${owner}'
}

fn interface_diagnostic_receiver_name(owner string, is_interface bool) string {
	if is_interface {
		return 'x'
	}
	short := owner.all_after_last('.')
	if short.len == 0 {
		return 'x'
	}
	return short[..1].to_lower()
}

fn (tc &TypeChecker) interface_method_receiver_flags(owner string, method string, is_interface bool) (bool, bool) {
	short_owner := owner.all_after_last('.')
	for candidate in tc.a.nodes {
		if is_interface {
			if candidate.kind != .interface_decl
				|| candidate.value.all_after_last('.') != short_owner {
				continue
			}
			for i in 0 .. candidate.children_count {
				field := tc.a.child_node(&candidate, i)
				if field.kind == .interface_field && field.op == .dot && field.value == method {
					return field.is_mut, false
				}
			}
			continue
		}
		if candidate.kind != .fn_decl || candidate.value.all_after_last('.') != method
			|| candidate.value.all_before_last('.').all_after_last('.') != short_owner
			|| candidate.children_count == 0 {
			continue
		}
		receiver := tc.a.child_node(&candidate, 0)
		if receiver.kind == .param && receiver.op == .dot {
			return receiver.is_mut, receiver.typ.starts_with('shared ')
		}
	}
	return false, false
}

fn (tc &TypeChecker) interface_diagnostic_param_names(signature_key string, method string, is_interface bool) []string {
	owner := signature_key.all_before_last('.').all_after_last('.')
	if is_interface {
		for candidate in tc.a.nodes {
			if candidate.kind != .interface_decl || candidate.value.all_after_last('.') != owner {
				continue
			}
			for i in 0 .. candidate.children_count {
				field_id := tc.a.child(&candidate, i)
				field := tc.a.node(field_id)
				if field.kind != .interface_field || field.op != .dot || field.value != method {
					continue
				}
				pos := tc.source_line_declaration_pos(field_id)
				file := tc.a.source_files[pos.id] or { return ['x'] }
				source := tc.source_texts_by_file[file.name] or { return ['x'] }
				if pos.offset < 0 || pos.end > source.len || pos.offset >= pos.end {
					return ['x']
				}
				line := source[pos.offset..pos.end]
				open := line.index_u8(`(`)
				close := line.last_index_u8(`)`)
				if open < 0 || close <= open {
					return ['x']
				}
				params, _ := fn_diagnostic_type_parts('fn (${line[open + 1..close]})')
				mut names := ['x']
				for param in params {
					names << param.name
				}
				return names
			}
		}
		return ['x']
	}
	for candidate in tc.a.nodes {
		if candidate.kind != .fn_decl || candidate.value.all_after_last('.') != method
			|| candidate.value.all_before_last('.').all_after_last('.') != owner {
			continue
		}
		mut names := []string{}
		for i in 0 .. candidate.children_count {
			param := tc.a.child_node(&candidate, i)
			if param.kind == .param {
				names << param.value
			}
		}
		return names
	}
	return []string{}
}

fn (tc &TypeChecker) interface_diagnostic_method_signature(signature_key string, owner string, method string, is_interface bool) string {
	params := tc.fn_param_types[signature_key] or { []Type{} }
	param_names := tc.interface_diagnostic_param_names(signature_key, method, is_interface)
	mut rendered := []string{cap: params.len}
	if params.len > 0 {
		receiver_is_mut, receiver_is_shared := tc.interface_method_receiver_flags(owner, method,
			is_interface)
		receiver_name := if param_names.len > 0 && param_names[0].len > 0 {
			param_names[0]
		} else {
			interface_diagnostic_receiver_name(owner, is_interface)
		}
		receiver_param := if receiver_is_shared {
			'mut ${receiver_name} shared ${owner}'
		} else if receiver_is_mut {
			'mut ${receiver_name} ${owner}'
		} else {
			'${receiver_name} ${owner}'
		}
		rendered << receiver_param
	}
	for i in 1 .. params.len {
		param_name := if i < param_names.len && param_names[i].len > 0 {
			param_names[i]
		} else if i == 1 {
			's'
		} else {
			'p${i}'
		}
		rendered << '${param_name} ${params[i].name()}'
	}
	ret := tc.fn_ret_types[signature_key] or { Type(void_) }
	ret_suffix := if ret is Void { '' } else { ' ${ret.name()}' }
	return 'fn ${method}(${rendered.join(', ')})${ret_suffix}'
}

fn (tc &TypeChecker) interface_actual_field(concrete_name string, field_name string) ?StructField {
	mut candidates := [concrete_name]
	if !concrete_name.contains('.') {
		qname := tc.qualify_name(concrete_name)
		if qname != concrete_name {
			candidates << qname
		}
	}
	for candidate in candidates {
		for field in tc.structs[candidate] or { []StructField{} } {
			if field.name == field_name {
				return field
			}
		}
	}
	return none
}

fn (mut tc TypeChecker) record_interface_implementation_error(kind TypeErrorKind, actual Type, expected Interface, id flat.NodeId, pos token.Pos) bool {
	actual_name := method_type_name(unwrap_pointer(actual))
	actual_display := if unalias_type(actual) is Pointer {
		'&${actual_name.all_after_last('.')}'
	} else {
		actual_name.all_after_last('.')
	}
	expected_name := tc.interface_metadata_name(expected.name)
	expected_display := expected_name.all_after_last('.')
	mut missing_methods := false
	for method in tc.interface_abstract_method_names(expected_name) {
		expected_key := tc.interface_method_signature_key(expected_name, method) or {
			'${expected_name}.${method}'
		}
		if actual_name == 'char' && method == 'str'
			&& tc.interface_method_is_str_requirement(expected_key) {
			tc.record_error_at(kind,
				'`${actual_display}` doesn\'t implement method `${method}` of interface `${expected_display}`',
				id, pos)
			missing_methods = true
			continue
		}
		actual_key := tc.concrete_method_signature_key(actual_name, method) or {
			tc.record_error_at(kind,
				'`${actual_display}` doesn\'t implement method `${method}` of interface `${expected_display}`',
				id, pos)
			missing_methods = true
			continue
		}
		expected_params := tc.fn_param_types[expected_key] or { []Type{} }
		actual_params := tc.fn_param_types[actual_key] or { []Type{} }
		mut message := ''
		expected_receiver_mut, expected_receiver_shared := tc.interface_method_receiver_flags(expected_name,
			method, true)
		actual_receiver_mut, actual_receiver_shared := tc.interface_method_receiver_flags(actual_name,
			method, false)
		if expected_receiver_mut && actual_receiver_shared && !expected_receiver_shared {
			message = '`${actual_display}` incorrectly implements method `${method}` of interface `${expected_display}`: expected `mut ${expected_display}`, not `mut shared ${actual_display}` for parameter 0'
		} else if !expected_receiver_mut && actual_receiver_mut && !actual_receiver_shared {
			expected_receiver := if expected_receiver_mut {
				'mut ${expected_display}'
			} else {
				expected_display
			}
			actual_receiver := if actual_receiver_mut {
				'mut ${actual_display}'
			} else {
				actual_display
			}
			message = '`${actual_display}` incorrectly implements method `${method}` of interface `${expected_display}`: expected `${expected_receiver}`, not `${actual_receiver}` for parameter 0'
		} else if expected_params.len != actual_params.len {
			message = '`${actual_display}` incorrectly implements method `${method}` of interface `${expected_display}`: expected ${expected_params.len} parameter(s), not ${actual_params.len}'
		} else {
			for i in 1 .. expected_params.len {
				if !tc.method_param_signature_compatible(actual_params[i], expected_params[i]) {
					message = '`${actual_display}` incorrectly implements method `${method}` of interface `${expected_display}`: expected `${expected_params[i].name()}`, not `${actual_params[i].name()}` for parameter ${i}'
					break
				}
			}
			if message.len == 0 {
				expected_ret := tc.fn_ret_types[expected_key] or { Type(void_) }
				actual_ret := tc.fn_ret_types[actual_key] or { Type(void_) }
				if actual_ret.name() != expected_ret.name() {
					message = '`${actual_display}` incorrectly implements method `${method}` of interface `${expected_display}`: expected return type `${expected_ret.name()}`'
				}
			}
		}
		if message.len > 0 {
			expected_owner := tc.interface_diagnostic_owner('${expected_name}.${method}',
				expected_name)
			actual_owner := tc.interface_diagnostic_owner(actual_key, actual_name)
			tc.record_error_with_details_at(kind, message, id, pos, [
				'${expected_owner} has `${tc.interface_diagnostic_method_signature(expected_key,
					expected_owner, method, true)}`',
				'         ${actual_owner} has `${tc.interface_diagnostic_method_signature(actual_key,
					actual_owner, method, false)}`',
			])
			return true
		}
	}
	if missing_methods {
		return true
	}
	for field in tc.interface_field_list(expected_name) {
		actual_field := tc.interface_actual_field(actual_name, field.name) or {
			tc.record_error_at(kind,
				'`${actual_display}` doesn\'t implement field `${field.name}` of interface `${expected_display}`',
				id, pos)
			return true
		}
		if !tc.type_compatible(actual_field.typ, field.typ)
			|| !tc.type_compatible(field.typ, actual_field.typ) {
			tc.record_error_at(kind,
				'`${actual_display}` incorrectly implements field `${field.name}` of interface `${expected_display}`, expected `${field.typ.name()}`, got `${actual_field.typ.name()}`',
				id, pos)
			return true
		}
		if field.is_mut && !actual_field.is_mut {
			tc.record_error_at(kind,
				'`${actual_display}` incorrectly implements interface `${expected_display}`, field `${field.name}` must be mutable',
				id, pos)
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) named_type_implements_interface_method(concrete_name string, iface_name string, method string) bool {
	expected_key := tc.interface_method_signature_key(iface_name, method) or {
		'${iface_name}.${method}'
	}
	if concrete_name == 'char' && method == 'str'
		&& tc.interface_method_is_str_requirement(expected_key) {
		return false
	}
	if concrete_key := tc.concrete_method_signature_key(concrete_name, method) {
		return tc.method_signature_compatible(concrete_key, expected_key)
	}
	if info := tc.resolve_generic_struct_method(concrete_name, method) {
		return tc.method_call_info_signature_compatible(info, expected_key)
	}
	if info := tc.resolve_generic_sum_method(concrete_name, method) {
		return tc.method_call_info_signature_compatible(info, expected_key)
	}
	return method == 'str' && tc.interface_method_is_str_requirement(expected_key)
		&& tc.type_has_implicit_str_method(concrete_name)
}

fn (mut tc TypeChecker) check_function_cast(id flat.NodeId, node flat.Node, child_id flat.NodeId, actual Type, target Type) bool {
	mut is_option := false
	target_fn := fn_type_from_type(target) or {
		if target is OptionType {
			is_option = true
			fn_type_from_type(target.base_type) or { return false }
		} else {
			return false
		}
	}
	if tc.expr_tail_is_nil(child_id) {
		if tc.unsafe_depth > 0 {
			return false
		}
		if !is_option {
			tc.record_warning_at(.assignment_mismatch,
				'casting `nil` to function value should be done inside `unsafe{}` blocks', id,
				node.pos)
		}
		tc.record_error_at(.assignment_mismatch, '`nil` is only allowed in `unsafe` code',
			child_id, tc.a.node(child_id).pos)
		if is_option {
			tc.record_error_at(.assignment_mismatch,
				'casting number to Option function is not allowed, only compatible function or `none`',
				id, tc.cast_expression_diagnostic_pos(node, node.value.trim_left('?')))
		}
		return true
	}
	if infix_power_type_is_numeric(actual) {
		if tc.unsafe_depth > 0 {
			return false
		}
		if is_option {
			tc.record_error_at(.assignment_mismatch,
				'casting number to Option function is not allowed, only compatible function or `none`',
				id, tc.cast_expression_diagnostic_pos(node, node.value.trim_left('?')))
		} else {
			tc.record_warning_at(.assignment_mismatch,
				'casting number to function value should be done inside `unsafe{}` blocks', id,
				node.pos)
		}
		return true
	}
	if unalias_type(actual) is String {
		tc.record_error_at(.assignment_mismatch, 'invalid casting value to function', id, node.pos)
		return true
	}
	if actual_fn := fn_type_from_type(actual) {
		if tc.unsafe_depth == 0 && (target_fn.params != actual_fn.params
			|| target_fn.return_type.name() != actual_fn.return_type.name()) {
			tc.record_error_at(.assignment_mismatch,
				'casting a function value from one function signature, to another function signature, should be done inside `unsafe{}` blocks',
				id, if is_option {
				tc.cast_expression_diagnostic_pos(node, node.value.trim_left('?'))
			} else {
				node.pos
			})
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) warn_invalid_enum_cast(id flat.NodeId, node flat.Node, child_id flat.NodeId, target Enum) {
	value := tc.const_int_expr(child_id, tc.cur_module, []string{}) or { return }
	cases := tc.comptime_static_enum_decl_value_cases(target.name)
	if cases.len == 0 {
		return
	}
	mut valid := false
	if target.is_flag {
		mut mask := 0
		for enum_case in cases {
			if enum_case.has_value {
				mask |= enum_case.value
			}
		}
		valid = value >= 0 && value & ~mask == 0
	} else {
		valid = cases.any(it.has_value && it.value == value)
	}
	if !valid {
		tc.record_warning_at(.assignment_mismatch,
			'${value} does not represent a value of enum ${target.name}', id, node.pos)
	}
}

fn (tc &TypeChecker) cast_operand_is_zero(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind == .int_literal {
		return numeric_literal_is_zero(node.value)
	}
	if node.kind == .paren && node.children_count > 0 {
		return tc.cast_operand_is_zero(tc.a.child(node, 0))
	}
	if node.kind != .ident || node.value.len == 0 {
		return false
	}
	if value := tc.const_int_value(node.value, []string{}) {
		return value == 0
	}
	file := tc.a.source_files[node.pos.id] or { return false }
	source := tc.source_texts_by_file[file.name] or { return false }
	end := int_min(int_max(node.pos.offset, 0), source.len)
	for needle in ['${node.value} := 0', '${node.value} = 0'] {
		if source[..end].last_index(needle) != none {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) cast_expression_diagnostic_pos(node flat.Node, target_name string) token.Pos {
	if !node.pos.is_valid() || target_name.len == 0 {
		return node.pos
	}
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	offset := int_min(int_max(node.pos.offset, 0), source.len)
	line_start := if relative := source[..offset].last_index('\n') {
		relative + 1
	} else {
		0
	}
	line_end := source.index_after('\n', offset) or { source.len }
	line := source[line_start..line_end]
	relative := line.index('${target_name}(') or { return node.pos }
	start := line_start + relative
	mut depth := 0
	for i in start + target_name.len .. line_end {
		if source[i] == `(` {
			depth++
		} else if source[i] == `)` {
			depth--
			if depth == 0 {
				return token.new_span(node.pos.id, start, i + 1)
			}
		}
	}
	return node.pos
}

fn (tc &TypeChecker) source_enclosing_fn_has_generic_param(id flat.NodeId, name string) bool {
	if name.len == 0 || !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	file := tc.a.source_files[node.pos.id] or { return false }
	source := tc.source_texts_by_file[file.name] or { return false }
	offset := int_min(int_max(node.pos.offset, 0), source.len)
	fn_start := source[..offset].last_index('fn ') or { return false }
	header_end_relative := source[fn_start..].index_u8(`{`)
	if header_end_relative < 0 {
		return false
	}
	header := source[fn_start..fn_start + header_end_relative]
	mut search_start := 0
	for search_start < header.len {
		open_relative := header[search_start..].index_u8(`[`)
		if open_relative < 0 {
			break
		}
		open := search_start + open_relative
		close_relative := header[open + 1..].index_u8(`]`)
		if close_relative < 0 {
			break
		}
		close := open + 1 + close_relative
		for param in header[open + 1..close].split(',') {
			if param.trim_space() == name {
				return true
			}
		}
		search_start = close + 1
	}
	return false
}

fn (mut tc TypeChecker) check_cast_to_string(id flat.NodeId, node flat.Node, child_id flat.NodeId, actual Type, target Type) bool {
	if target !is String || actual is String {
		return false
	}
	expr := tc.source_text_for_node(child_id)
	clean_actual := unalias_type(actual)
	if clean_actual is Primitive {
		if clean_actual.props.has(.boolean) || clean_actual.props.has(.integer)
			|| clean_actual.props.has(.float) {
			actual_name := actual.name()
			message := if clean_actual.props.has(.boolean)
				|| (clean_actual.props.has(.integer) && clean_actual.props.has(.unsigned)
				&& clean_actual.size == 8) {
				'cannot cast type `${actual_name}` to string, use `${expr}.str()` instead.'
			} else {
				'cannot cast number to string, use `${expr}.str()` instead.'
			}
			tc.record_error_at(.assignment_mismatch, message, id, node.pos)
			return true
		}
	}
	if clean_actual is Enum {
		tc.record_error_at(.assignment_mismatch,
			'cannot cast enum to string, use ${expr}.str() instead.', id, node.pos)
		return true
	}
	if clean_actual is SumType {
		tc.record_error_at(.assignment_mismatch,
			'cannot cast sumtype `${actual.name()}` to string, use `${expr}.str()` instead.', id,
			node.pos)
		tc.record_error_at(.assignment_mismatch,
			'cannot cast `${actual.name()}` sum type value to `string`, use `${expr} as string` instead',
			id, node.pos)
		return true
	}
	if clean_actual is Struct {
		tc.record_error_at(.assignment_mismatch,
			'cannot cast struct `${actual.name()}` to `string`', id, node.pos)
		return true
	}
	if clean_actual is Map {
		tc.record_error_at(.assignment_mismatch, 'cannot cast map to string.', id, node.pos)
		return true
	}
	if clean_actual is Array && is_byte_type(clean_actual.elem_type) {
		tc.record_error_at(.assignment_mismatch,
			'cannot cast []u8 to string, use `${expr}.bytestr()` or `${expr}.str()` instead.', id,
			node.pos)
		return true
	}
	if clean_actual is FnType {
		tc.record_error_at(.assignment_mismatch, 'cannot cast function `${expr}` to string', id,
			node.pos)
		return true
	}
	return false
}

fn (mut tc TypeChecker) check_cast_from_string(id flat.NodeId, node flat.Node, child_id flat.NodeId, actual Type, target Type) bool {
	if unalias_type(actual) !is String || target is String {
		return false
	}
	expr := tc.source_text_for_node(child_id)
	clean_target := unalias_type(target)
	target_name := if node.value.len > 0 { node.value } else { target.name() }
	if clean_target is Primitive
		&& (clean_target.props.has(.integer) || clean_target.props.has(.float)) {
		if clean_target.props.has(.integer) && clean_target.props.has(.unsigned)
			&& clean_target.size == 8 {
			tc.record_error_at(.assignment_mismatch,
				'cannot cast type `${actual.name()}` to `${target_name}`', id, node.pos)
			return true
		}
		tc.record_error_at(.assignment_mismatch,
			'cannot cast string to `${target_name}`, use `${expr}.${target_name}()` instead.', id,
			node.pos)
		return true
	}
	if clean_target is Char {
		tc.record_error_at(.assignment_mismatch,
			'cannot cast string to `char`, use `${expr}[index]` instead.', id, node.pos)
		return true
	}
	if clean_target is Rune {
		tc.record_error_at(.assignment_mismatch,
			'cannot cast `string` to rune, use `${expr}.runes()` instead.', id, node.pos)
		return true
	}
	if clean_target is Enum {
		enum_name := if clean_target.name.starts_with('.') {
			'main${clean_target.name}'
		} else if clean_target.name.contains('.') {
			clean_target.name
		} else {
			'${if tc.cur_module.len > 0 { tc.cur_module } else { 'main' }}.${clean_target.name}'
		}
		tc.record_error_with_details_at(.assignment_mismatch, 'cannot cast `string` to `enum`', id,
			node.pos, [
			'use ${enum_name}.from_string(${expr}) instead',
		])
		return true
	}
	if clean_target is Pointer {
		if target_name in ['voidptr', 'byteptr', 'charptr'] {
			outside_unsafe := if target_name == 'voidptr' || tc.unsafe_depth > 0 {
				''
			} else {
				' outside `unsafe`'
			}
			tc.record_error_at(.assignment_mismatch,
				'cannot cast string to `${target_name}`${outside_unsafe}, use ${target_name}(s.str) instead',
				id, node.pos)
		} else if struct_type_from_type(clean_target.base_type) != none {
			tc.record_error_at(.assignment_mismatch,
				'cannot cast `${actual.name()}` to `${target_name}`', id, node.pos)
		} else {
			tc.record_error_at(.assignment_mismatch,
				'cannot cast string to `${target_name}`, use `${expr}.str` instead.', id, node.pos)
		}
		return true
	}
	return false
}

fn (mut tc TypeChecker) check_integer_literal_cast_overflow(id flat.NodeId, node flat.Node, child_id flat.NodeId, target Type) {
	clean_target := unalias_type(target)
	if clean_target !is Primitive || !clean_target.props.has(.integer) {
		return
	}
	mut literal := tc.integer_literal_source(child_id) or { return }
	literal = literal.replace('_', '')
	if literal.len == 0 {
		return
	}
	is_negative := literal[0] == `-`
	mut magnitude := literal
	if literal[0] == `-` || literal[0] == `+` {
		magnitude = literal[1..]
	}
	if magnitude.len == 0 {
		return
	}
	bit_size := if clean_target.size == 0 { 32 } else { int(clean_target.size) }
	value, parse_error := strconv.common_parse_uint2(magnitude, 0, bit_size)
	target_name := target.name()
	if parse_error == -3 {
		tc.record_error_at(.assignment_mismatch, 'value `${literal}` overflows `${target_name}`',
			id, node.pos)
		return
	}
	if parse_error != 0 || clean_target.props.has(.unsigned) {
		return
	}
	unsigned_max := if bit_size >= 64 {
		max_u64
	} else {
		(u64(1) << bit_size) - 1
	}
	signed_max := (u64(1) << (bit_size - 1)) - 1
	overflows_sign_bit := value == unsigned_max
		|| (is_negative && value == signed_max + 2)
		|| (!is_negative && value == signed_max + 1)
	if overflows_sign_bit {
		tc.record_warning_at(.assignment_mismatch,
			'value `${literal}` overflows `${target_name}`, this will be considered hard error soon',
			id, node.pos)
	}
}

fn (tc &TypeChecker) integer_literal_source(id flat.NodeId) ?string {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .int_literal {
		text := tc.source_text_for_node(id)
		return if text.len > 0 { text } else { node.value }
	}
	if node.kind == .prefix && node.op in [.plus, .minus] && node.children_count == 1 {
		child_id := tc.a.child(&node, 0)
		if tc.a.nodes[int(child_id)].kind == .int_literal {
			return tc.source_text_for_node(id)
		}
	}
	return none
}

fn (mut tc TypeChecker) check_untyped_integer_literal_overflow(id flat.NodeId) {
	mut parent_id := tc.direct_parent_id(id)
	if tc.valid_node_id(parent_id) {
		parent := tc.a.node(parent_id)
		if parent.kind == .prefix && parent.op in [.plus, .minus] {
			parent_id = tc.direct_parent_id(parent_id)
		}
	}
	if tc.valid_node_id(parent_id) && tc.a.node(parent_id).kind == .cast_expr {
		return
	}
	mut literal := tc.integer_literal_source(id) or { return }
	literal = literal.replace('_', '')
	if literal.len == 0 {
		return
	}
	is_negative := literal[0] == `-`
	mut magnitude := literal
	if literal[0] in [`-`, `+`] {
		magnitude = literal[1..]
	}
	if magnitude.len == 0 {
		return
	}
	value, parse_error := strconv.common_parse_uint2(magnitude, 0, 64)
	overflows := parse_error == -3 || (parse_error == 0 && is_negative && value > (u64(1) << 63))
	if overflows {
		tc.record_error_at(.assignment_mismatch, 'integer literal ${literal} overflows int', id,
			tc.a.node(id).pos)
	}
}

fn (tc &TypeChecker) implicit_int_literal_overflows(id flat.NodeId) bool {
	mut literal := tc.integer_literal_source(id) or { return false }
	literal = literal.replace('_', '')
	if literal.len == 0 {
		return false
	}
	is_negative := literal[0] == `-`
	mut magnitude := literal
	if literal[0] == `-` || literal[0] == `+` {
		magnitude = literal[1..]
	}
	if magnitude.len == 0 {
		return false
	}
	value, parse_error := strconv.common_parse_uint2(magnitude, 0, 32)
	if parse_error == -3 {
		return true
	}
	if parse_error != 0 {
		return false
	}
	if is_negative {
		return value > u64(2_147_483_648)
	}
	return value > u64(2_147_483_647)
}

struct IntegerTypeRange {
	bits        int
	is_unsigned bool
	name        string
}

fn integer_type_range(typ Type) ?IntegerTypeRange {
	clean := unalias_type(typ)
	if clean is Primitive {
		if !clean.props.has(.integer) {
			return none
		}
		return IntegerTypeRange{
			bits:        if clean.size == 0 { 32 } else { int(clean.size) }
			is_unsigned: clean.props.has(.unsigned)
			name:        typ.name()
		}
	}
	if clean is ISize {
		return IntegerTypeRange{
			bits: 64
			name: typ.name()
		}
	}
	if clean is USize {
		return IntegerTypeRange{
			bits:        64
			is_unsigned: true
			name:        typ.name()
		}
	}
	if clean is Rune {
		return IntegerTypeRange{
			bits: 32
			name: typ.name()
		}
	}
	return none
}

fn (mut tc TypeChecker) warn_if_integer_literal_outside_known_type_range(id flat.NodeId, expected Type, warning_pos token.Pos) {
	if expected is Alias {
		return
	}
	type_range := integer_type_range(expected) or { return }
	mut literal := tc.integer_literal_source(id) or { return }
	literal = literal.replace('_', '')
	if !integer_literal_outside_range(literal, type_range) {
		return
	}
	tc.record_warning_at(.call_arg_mismatch,
		'value `${literal}` is outside the range of `${type_range.name}` in argument, this will be considered hard error soon',
		id, warning_pos)
	if integer_literal_overflows_signed_64(literal) {
		tc.record_error_at(.assignment_mismatch, 'integer literal ${literal} overflows int', id,
			tc.a.nodes[int(id)].pos)
	}
}

fn integer_literal_outside_range(literal string, type_range IntegerTypeRange) bool {
	if literal.len == 0 || type_range.bits <= 0 {
		return false
	}
	is_negative := literal[0] == `-`
	mut magnitude := literal
	if literal[0] == `-` || literal[0] == `+` {
		magnitude = literal[1..]
	}
	if magnitude.len == 0 {
		return false
	}
	value, parse_error := strconv.common_parse_uint2(magnitude, 0, 64)
	if parse_error == -3 {
		return true
	}
	if parse_error != 0 {
		return false
	}
	if type_range.is_unsigned {
		return is_negative || value > enum_backing_unsigned_max(type_range.bits)
	}
	minimum_magnitude := if type_range.bits >= 64 {
		u64(1) << 63
	} else {
		u64(1) << (type_range.bits - 1)
	}
	maximum := minimum_magnitude - 1
	if is_negative {
		return value > minimum_magnitude
	}
	return value > maximum
}

fn integer_literal_overflows_signed_64(literal string) bool {
	if literal.len < 2 || literal[0] != `-` {
		return false
	}
	value, parse_error := strconv.common_parse_uint2(literal[1..], 0, 64)
	return parse_error == -3 || (parse_error == 0 && value > (u64(1) << 63))
}

fn (tc &TypeChecker) call_has_postfix_propagation(call flat.Node) bool {
	file := tc.a.source_files[call.pos.id] or { return false }
	source := tc.source_texts_by_file[file.name] or { return false }
	mut after_call := int_min(int_max(call.pos.end, 0), source.len)
	for after_call < source.len && source[after_call].is_space() {
		after_call++
	}
	return after_call < source.len && source[after_call] in [`!`, `?`]
}

fn (mut tc TypeChecker) record_unhandled_result_call(call_id flat.NodeId, result_type ResultType) {
	if !tc.valid_node_id(call_id) {
		return
	}
	call := tc.a.nodes[int(call_id)]
	if call.kind != .call {
		return
	}
	parent_id := tc.direct_parent_id(call_id)
	if tc.valid_node_id(parent_id) {
		parent := tc.a.node(parent_id)
		if parent.kind == .or_expr && parent.value in ['!', '?'] && parent.children_count > 0
			&& tc.a.child(parent, 0) == call_id {
			return
		}
	}
	if tc.call_has_postfix_propagation(call) {
		return
	}
	name := tc.call_display_name(call)
	tc.record_error_at(.call_arg_mismatch,
		'${name}() returns `${Type(result_type).name()}`, so it should have either an `or {}` block, or `!` at the end',
		call_id, tc.wrapped_operand_diagnostic_pos(call_id))
}

fn type_text_contains_any(typ string) bool {
	clean := trimmed_space(typ)
	if clean.len < 3 {
		return clean == 'any'
	}
	for i in 0 .. clean.len - 2 {
		if clean[i..i + 3] != 'any' {
			continue
		}
		left_is_name := i > 0 && (clean[i - 1].is_alnum() || clean[i - 1] == `_`)
		right_is_name := i + 3 < clean.len && (clean[i + 3].is_alnum() || clean[i + 3] == `_`)
		if !left_is_name && !right_is_name {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) check_as_expr(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	child_id := tc.a.child(&node, 0)
	tc.check_node(child_id)
	child_type := tc.resolve_type(child_id)
	if child_type is ResultType && tc.a.node(child_id).kind == .call {
		tc.record_unhandled_result_call(child_id, child_type)
		return
	}
	if child_type is OptionType && tc.a.node(child_id).kind == .ident {
		child := tc.a.node(child_id)
		tc.record_error_at(.assignment_mismatch,
			'variable `${child.value}` is an Option, it must be unwrapped first', child_id,
			tc.node_value_diagnostic_pos(child_id))
		return
	}
	if node.value.contains('.') {
		target := node.value.all_before_last('.')
		field := node.value.all_after_last('.')
		if target.len > 0 && field.len > 0 {
			resolved_target := tc.unique_qualified_type_name(target) or { target }
			qualified_target := if resolved_target.contains('.') {
				resolved_target
			} else {
				'${if tc.cur_module.len > 0 { tc.cur_module } else { 'main' }}.${resolved_target}'
			}
			tc.record_error_with_details_at(.condition_mismatch,
				'indeterminate `as` cast, use parenthesis to clarity', id, tc.as_operator_pos(id,
				node, child_id), [
				'for example `(${tc.source_text_for_node(child_id)} as ${qualified_target}).${field}`',
			])
			return
		}
	}
	if node.value.len > 0 && !interface_pattern_is_collapsed_container(node.value)
		&& should_check_named_type(node.value) && !tc.type_name_known(node.value) {
		pos := tc.as_operator_pos(id, node, child_id)
		tc.record_error_at(.unknown_type, tc.unknown_type_message(node.value, id), id, pos)
		tc.record_error_at(.assignment_mismatch,
			'cannot cast `${tc.diagnostic_type_name(child_type)}` to `${node.value}`', id, pos)
		return
	}
	if node.value.len == 0 || !interface_pattern_is_collapsed_container(node.value) {
		return
	}
	expr_type := unalias_type(unwrap_pointer(tc.resolve_type(child_id)))
	if expr_type is Interface && !tc.interface_has_no_requirements(expr_type.name)
		&& tc.should_diagnose(id) {
		tc.record_error(.condition_mismatch,
			'`${node.value}` is not compatible with interface `${expr_type.name}`', id)
	}
}

fn (tc &TypeChecker) as_operator_pos(id flat.NodeId, node flat.Node, child_id flat.NodeId) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	child := tc.a.node(child_id)
	start := int_max(0, child.pos.end)
	end := int_min(node.pos.end, source.len)
	if start < end {
		if relative := source[start..end].index(' as ') {
			op_start := start + relative + 1
			return token.new_span(node.pos.id, op_start, op_start + 2)
		}
	}
	return tc.node_value_diagnostic_pos(id)
}

fn (tc &TypeChecker) sizeof_type_diagnostic_pos(id flat.NodeId, name string) token.Pos {
	if !tc.valid_node_id(id) {
		return token.Pos{}
	}
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	anchor := int_max(0, int_min(node.pos.offset, source.len))
	if span := closest_text_span(source, name, anchor, node.pos.id) {
		end := if span.end < source.len && source[span.end] == `]` {
			span.end + 1
		} else {
			span.end
		}
		return token.new_span(span.id, span.offset, end)
	}
	return node.pos
}

fn (tc &TypeChecker) generic_type_arg_diagnostic_pos(id flat.NodeId) token.Pos {
	if !tc.valid_node_id(id) {
		return token.Pos{}
	}
	node := tc.a.node(id)
	if !node.pos.is_valid() {
		return node.pos
	}
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	return token.new_span(node.pos.id, int_max(0, node.pos.offset - 1), int_min(node.pos.end + 1,
		source.len))
}

fn (mut tc TypeChecker) check_in_expr(id flat.NodeId, node flat.Node) {
	if node.children_count < 2 {
		return
	}
	value_id := tc.a.child(&node, 0)
	container_id := tc.a.child(&node, 1)
	tc.check_node(value_id)
	value_type_raw := tc.resolve_type(value_id)
	value_type := unalias_type(value_type_raw)
	container := tc.a.node(container_id)
	if value_type is SumType && container.kind == .array_literal {
		for i in 0 .. container.children_count {
			variant_id := tc.a.child(container, i)
			variant := tc.a.node(variant_id)
			if variant.kind == .ident && should_check_named_type(variant.value)
				&& !tc.type_name_known(variant.value) {
				tc.record_error_at(.unknown_type,
					tc.unknown_type_message(variant.value, variant_id), variant_id,
					tc.node_value_diagnostic_pos(variant_id))
				return
			}
		}
	}
	tc.check_node(container_id)
	container_type := unalias_type(tc.resolve_type(container_id))
	op := tc.in_operator_name(value_id, container_id)
	if value_type is MultiReturn || container_type is MultiReturn {
		tc.record_error_at(.condition_mismatch,
			'invalid number of operand for `${op}`. Only one allowed on each side.', id, node.pos)
	}
	if tc.a.node(value_id).kind == .none_expr && container.kind == .none_expr {
		tc.record_error_at(.condition_mismatch, 'invalid operator `${op}` to `none` and `none`',
			id, node.pos)
		tc.record_error_at(.condition_mismatch, '`${op}` can only be used with arrays and maps',
			id, tc.in_operator_pos(value_id, container_id))
		return
	}
	if value_type is OptionType || value_type is ResultType {
		kind := if value_type is OptionType { 'Option' } else { 'Result' }
		tc.record_error_at(.condition_mismatch, 'unwrapped ${kind} cannot be used with `${op}`',
			value_id, tc.wrapped_operand_diagnostic_pos(value_id))
		if value_type is ResultType {
			tc.record_unhandled_result_call(value_id, value_type)
		}
		return
	}
	if container_type is Array || container_type is ArrayFixed {
		if container.kind == .array_literal {
			tc.check_in_array_duplicate_items(container)
		}
		element_type := if container_type is Array {
			container_type.elem_type
		} else {
			(container_type as ArrayFixed).elem_type
		}
		if !tc.expr_compatible(value_id, value_type, element_type) {
			tc.record_error_at(.condition_mismatch, 'left operand to `${op}` does not match the array element type: expected `${element_type.name()}`, not `${tc.diagnostic_expr_type_name(value_id,
				value_type_raw)}`', id, node.pos)
		}
		return
	}
	if container_type is Map {
		if !tc.expr_compatible(value_id, value_type, container_type.key_type) {
			tc.record_error_at(.condition_mismatch, 'left operand to `${op}` does not match the map key type: expected `${container_type.key_type.name()}`, not `${tc.diagnostic_expr_type_name(value_id,
				value_type_raw)}`', id, node.pos)
		}
		return
	}
	if container.kind != .range {
		if container_type !is Unknown {
			tc.record_error_at(.condition_mismatch,
				'`${op}` can only be used with arrays and maps', id, tc.in_operator_pos(value_id,
				container_id))
		}
		return
	}
	if value_type is Unknown || value_type.is_integer() {
		return
	}
	tc.record_error_at(.condition_mismatch,
		'`${tc.diagnostic_expr_type_name(value_id, value_type)}` is an invalid type for range expression',
		id, tc.in_operator_pos(value_id, container_id))
}

fn (mut tc TypeChecker) check_in_array_duplicate_items(array flat.Node) {
	mut seen := map[string]bool{}
	mut reported := map[string]bool{}
	for i in 0 .. array.children_count {
		item_id := tc.a.child(&array, i)
		item := tc.a.node(item_id)
		if item.kind !in [.ident, .int_literal, .float_literal, .string_literal, .char_literal,
			.bool_literal] {
			continue
		}
		key := '${int(item.kind)}:${item.value}'
		if seen[key] && !reported[key] {
			display := tc.source_text_for_node(item_id).trim_space()
			tc.record_notice_at(.duplicate_decl, 'item `${display}` is duplicated in the list',
				item_id, item.pos)
			reported[key] = true
		}
		seen[key] = true
	}
}

fn (tc &TypeChecker) in_operator_name(value_id flat.NodeId, container_id flat.NodeId) string {
	value := tc.a.node(value_id)
	container := tc.a.node(container_id)
	if value.pos.id != container.pos.id || !value.pos.is_valid() || !container.pos.is_valid() {
		return 'in'
	}
	file := tc.a.source_files[value.pos.id] or { return 'in' }
	source := tc.source_texts_by_file[file.name] or { return 'in' }
	start := int_min(int_max(0, value.pos.end), source.len)
	end := int_min(int_max(start, container.pos.offset), source.len)
	if start < end && source[start..end].contains('!in') {
		return '!in'
	}
	return 'in'
}

fn (tc &TypeChecker) in_operator_pos(value_id flat.NodeId, container_id flat.NodeId) token.Pos {
	value := tc.a.node(value_id)
	container := tc.a.node(container_id)
	if value.pos.id != container.pos.id || !value.pos.is_valid() || !container.pos.is_valid() {
		return value.pos
	}
	file := tc.a.source_files[value.pos.id] or { return value.pos }
	source := tc.source_texts_by_file[file.name] or { return value.pos }
	start := int_max(0, value.pos.end)
	end := int_min(container.pos.offset, source.len)
	if start < end {
		operator := tc.in_operator_name(value_id, container_id)
		if relative := source[start..end].index(operator) {
			pos := start + relative
			return token.new_span(value.pos.id, pos, pos + operator.len)
		}
	}
	return value.pos
}

fn cast_target_interface(target Type) ?Interface {
	mut current := target
	for _ in 0 .. 8 {
		if current is Interface {
			return current
		}
		if current is Alias {
			current = current.base_type
			continue
		}
		if current is Pointer {
			current = current.base_type
			continue
		}
		return none
	}
	return none
}

fn (mut tc TypeChecker) check_comptime_if(id flat.NodeId, node flat.Node) {
	if tc.check_comptime_match_diagnostics(id, node) {
		return
	}
	if tc.check_comptime_condition_diagnostics(id, node) {
		return
	}
	take_then := tc.comptime_type_condition_value(node.value) or { return }
	branch_index := if take_then { 0 } else { 1 }
	if branch_index >= node.children_count {
		return
	}
	tc.check_node(tc.a.child(&node, branch_index))
}

fn (mut tc TypeChecker) check_comptime_match_diagnostics(id flat.NodeId, node flat.Node) bool {
	metadata := node.generic_params()
	if metadata.len < 6 || metadata[0] != '__v3_comptime_match' {
		return false
	}
	subject := metadata[1]
	subject_start := metadata[2].int()
	subject_end := metadata[3].int()
	explicit_mut := metadata[4] == 'true'
	match_kind := metadata[5]
	subject_pos := token.new_span(node.pos.id, subject_start, subject_end)
	mut has_error := false
	if explicit_mut {
		tc.record_error_at(.condition_mismatch,
			'`$match` condition `${subject}` can not be mutable', id, subject_pos)
		has_error = true
	} else if tc.ident_is_mutable_lvalue(subject) {
		tc.record_error_at(.condition_mismatch,
			'`${subject}` is mut and may have changed since its definition', id, subject_pos)
		has_error = true
	}
	subject_type := if subject.starts_with('$') {
		match subject {
			'$float' { 'f64' }
			'$string' { 'string' }
			else { 'int' }
		}
	} else if typ := tc.cur_scope.lookup(subject) {
		unalias_type(typ).name()
	} else {
		'unknown'
	}
	for offset := 6; offset + 3 < metadata.len; offset += 4 {
		pattern := metadata[offset]
		pattern_start := metadata[offset + 1].int()
		pattern_end := metadata[offset + 2].int()
		pattern_kind := metadata[offset + 3]
		pattern_pos := token.new_span(node.pos.id, pattern_start, pattern_end)
		if pattern_kind != match_kind {
			message := if match_kind == 'value' {
				'can not matching a type in a value `$match`'
			} else {
				'can not matching a value in a type `$match`'
			}
			tc.record_error_at(.condition_mismatch, message, id, pattern_pos)
			has_error = true
			continue
		}
		if match_kind == 'value' && pattern.len >= 2 && pattern[0] in [`'`, `"`]
			&& subject_type != 'string' {
			tc.record_error_at(.condition_mismatch,
				'can not matching a string value(`${pattern}`) in a non string type `$match`, `${subject}` type is `${subject_type}`',
				id, pattern_pos)
			has_error = true
		}
	}
	return has_error
}

fn (mut tc TypeChecker) check_comptime_condition_diagnostics(id flat.NodeId, node flat.Node) bool {
	condition := comptime_condition_strip_outer_parens(trimmed_space(node.value))
	for op in [' == ', ' != ', ' <= ', ' >= ', ' < ', ' > '] {
		op_idx := comptime_condition_top_level_index(condition, op)
		if op_idx < 0 {
			continue
		}
		left := trimmed_space(condition[..op_idx])
		if left.len == 0 || left.contains('.') {
			return false
		}
		if tc.lvalue_ident_is_known(left) {
			if tc.ident_is_mutable_lvalue(left) {
				tc.record_error_at(.condition_mismatch,
					'`${left}` is mut and may have changed since its definition', id, tc.comptime_condition_part_pos(node,
					left))
				return true
			}
			if initializer_id := tc.comptime_local_initializer(left, node) {
				if !tc.comptime_initializer_is_static(initializer_id) {
					tc.record_error_at(.condition_mismatch,
						'definition of `${left}` is unknown at compile time', id, tc.comptime_condition_part_pos(node,
						left))
					return true
				}
			}
		}
		return false
	}
	for op in [' !is ', ' is '] {
		op_idx := comptime_condition_top_level_index(condition, op)
		if op_idx < 0 {
			continue
		}
		left := trimmed_space(condition[..op_idx])
		right := trimmed_space(condition[op_idx + op.len..])
		root := left.all_before('.')
		mut has_error := false
		root_is_generic_type := root in tc.fn_context.generic_params
			|| tc.active_generic_param(root)
		if root.len > 0 && !root_is_generic_type && !tc.lvalue_ident_is_known(root) {
			tc.record_error_at(.unknown_ident, 'undefined ident: `${root}`', id, tc.comptime_condition_part_pos(node,
				root))
			has_error = true
			if left.contains('.') {
				member := left.all_after_last('.')
				tc.record_error_at(.condition_mismatch, '`${root}` does not return a value', id, tc.comptime_condition_part_pos(node,
					member))
			}
		}
		if right.len == 0 || right[0].is_digit() || right[0] in [`'`, `"`] {
			tc.record_error_at(.unknown_type, 'invalid $if right expr: expected a type', id, tc.comptime_condition_part_pos(node,
				right))
			return true
		}
		if !right.starts_with('$') && should_check_named_type(right) && !tc.type_name_known(right) {
			tc.record_error_at(.unknown_type, 'unknown type `${right}`', id, tc.comptime_condition_part_pos(node,
				right))
			return true
		}
		return has_error
	}
	return false
}

fn (tc &TypeChecker) comptime_local_initializer(name string, condition flat.Node) ?flat.NodeId {
	mut found := flat.empty_node
	mut found_offset := -1
	for node in tc.a.nodes {
		if node.kind != .decl_assign || node.children_count < 2 {
			continue
		}
		lhs := tc.a.child_node(&node, 0)
		if lhs.kind != .ident || lhs.value != name || lhs.pos.id != condition.pos.id
			|| lhs.pos.offset >= condition.pos.offset || lhs.pos.offset <= found_offset {
			continue
		}
		found = tc.a.child(&node, 1)
		found_offset = lhs.pos.offset
	}
	if int(found) >= 0 {
		return found
	}
	return none
}

fn (tc &TypeChecker) comptime_initializer_is_static(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	return node.kind in [.int_literal, .float_literal, .string_literal, .char_literal, .bool_literal,
		.enum_val, .nil_literal, .none_expr]
}

fn (tc &TypeChecker) comptime_condition_part_pos(node flat.Node, part string) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, int_min(node.pos.offset, source.len))
	end := int_max(start, int_min(node.pos.end, source.len))
	if part.len > 0 {
		if relative := source[start..end].index(part) {
			part_start := start + relative
			return token.new_span(node.pos.id, part_start, part_start + part.len)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) mark_inactive_comptime_subtree(id flat.NodeId, mut inactive []bool) {
	if !tc.valid_node_id(id) {
		return
	}
	if inactive.len == 0 {
		inactive = []bool{len: tc.a.nodes.len}
	}
	inactive[int(id)] = true
	node := tc.a.nodes[int(id)]
	for i in 0 .. node.children_count {
		tc.mark_inactive_comptime_subtree(tc.a.child(&node, i), mut inactive)
	}
}

fn (tc &TypeChecker) mark_inactive_top_level_comptime(id flat.NodeId, mut inactive []bool) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .comptime_if {
		take_then := tc.comptime_threads_condition_value(node.value) or { return }
		active_branch := if take_then { 0 } else { 1 }
		for i in 0 .. node.children_count {
			child_id := tc.a.child(&node, i)
			if i == active_branch {
				tc.mark_inactive_top_level_comptime(child_id, mut inactive)
			} else {
				tc.mark_inactive_comptime_subtree(child_id, mut inactive)
			}
		}
		return
	}
	if node.kind != .block {
		return
	}
	for i in 0 .. node.children_count {
		tc.mark_inactive_top_level_comptime(tc.a.child(&node, i), mut inactive)
	}
}

fn (tc &TypeChecker) inactive_top_level_comptime_nodes() []bool {
	mut inactive := []bool{}
	if file_index_usable(tc.a) {
		// Only trailing .file nodes have children; the recorded list visits
		// them in node order, matching the full scan.
		for fid in tc.a.file_node_ids {
			node := tc.a.nodes[fid]
			if node.kind != .file || node.children_count == 0 {
				continue
			}
			for i in 0 .. node.children_count {
				tc.mark_inactive_top_level_comptime(tc.a.child(&node, i), mut inactive)
			}
		}
		return inactive
	}
	for node in tc.a.nodes {
		if node.kind != .file || node.children_count == 0 {
			continue
		}
		for i in 0 .. node.children_count {
			tc.mark_inactive_top_level_comptime(tc.a.child(&node, i), mut inactive)
		}
	}
	return inactive
}

// prune_inactive_top_level_comptime removes declarations and expressions from inactive
// top-level compile-time branches after semantic checking and before later compiler stages.
pub fn (tc &TypeChecker) prune_inactive_top_level_comptime(mut a flat.FlatAst) {
	for i in tc.inactive_top_level_node_ids {
		if i < a.nodes.len {
			a.nodes[i] = flat.Node{}
		}
	}
}

fn (tc &TypeChecker) subtree_has_spawn_expr(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .comptime_if && comptime_condition_is_builtin_threads_guarded(node.value) {
		return false
	}
	if node_kind_id(node) == int(flat.NodeKind.spawn_expr) {
		return true
	}
	for i in 0 .. node.children_count {
		if tc.subtree_has_spawn_expr(tc.a.child(&node, i)) {
			return true
		}
	}
	return false
}

fn comptime_condition_is_builtin_threads_guarded(cond string) bool {
	return comptime_condition_is_builtin_threads_guarded_with_negation(cond, false)
}

// A conjunction is guarded when either side is guarded; every alternative of a
// disjunction must be guarded. `negated` applies De Morgan's operator swap.
fn comptime_condition_is_builtin_threads_guarded_with_negation(cond string, negated bool) bool {
	clean := comptime_condition_strip_outer_parens(cond)
	or_idx := comptime_condition_top_level_index(clean, '||')
	if or_idx >= 0 {
		left := comptime_condition_is_builtin_threads_guarded_with_negation(clean[..or_idx],
			negated)
		right := comptime_condition_is_builtin_threads_guarded_with_negation(clean[or_idx + 2..],
			negated)
		return if negated { left || right } else { left && right }
	}
	and_idx := comptime_condition_top_level_index(clean, '&&')
	if and_idx >= 0 {
		left := comptime_condition_is_builtin_threads_guarded_with_negation(clean[..and_idx],
			negated)
		right := comptime_condition_is_builtin_threads_guarded_with_negation(clean[and_idx + 2..],
			negated)
		return if negated { left && right } else { left || right }
	}
	if clean.starts_with('!') {
		return comptime_condition_is_builtin_threads_guarded_with_negation(clean[1..], !negated)
	}
	return clean == 'threads'
}

fn module_file_matches_import_path(file string, imported_module string) bool {
	if !imported_module.contains('.') {
		return false
	}
	normalized_file := file.replace('\\', '/')
	module_dir := imported_module.replace('.', '/')
	file_dir := normalized_file.all_before_last('/')
	return file_dir == module_dir || file_dir.ends_with('/${module_dir}')
}

fn (tc &TypeChecker) scan_has_spawn_expr() bool {
	if tc.diagnostic_files.len == 0 {
		start := if tc.a.user_code_start > 0 { tc.a.user_code_start } else { 0 }
		mut ignored := []bool{}
		for node in tc.a.nodes[start..] {
			if node.kind == .comptime_if
				&& comptime_condition_is_builtin_threads_guarded(node.value) {
				for i in 0 .. node.children_count {
					tc.mark_inactive_comptime_subtree(tc.a.child(&node, i), mut ignored)
				}
			}
		}
		for idx, node in tc.a.nodes[start..] {
			absolute_idx := start + idx
			if (ignored.len == 0 || !ignored[absolute_idx])
				&& node_kind_id(node) == int(flat.NodeKind.spawn_expr) {
				return true
			}
		}
		return false
	}
	mut file_nodes := map[string]flat.NodeId{}
	mut file_imports := map[string][]string{}
	mut module_files := map[string][]string{}
	for idx, node in tc.a.nodes {
		if node.kind != .file || node.children_count == 0 || node.value.len == 0 {
			continue
		}
		file_nodes[node.value] = flat.NodeId(idx)
		mut imports := []string{}
		mut module_name := ''
		for i in 0 .. node.children_count {
			child := tc.a.child_node(&node, i)
			if child.kind == .module_decl {
				module_name = child.value
			} else if child.kind == .import_decl && child.value.len > 0 {
				imports << child.value
			}
		}
		file_imports[node.value] = imports
		if module_name.len > 0 {
			mut files := module_files[module_name] or { []string{} }
			files << node.value
			module_files[module_name] = files
		}
	}
	mut reachable_files := []string{}
	mut seen_files := map[string]bool{}
	for file, selected in tc.diagnostic_files {
		if selected && !file.starts_with('generic:') {
			reachable_files << file
			seen_files[file] = true
		}
	}
	mut pos := 0
	for pos < reachable_files.len {
		file := reachable_files[pos]
		pos++
		if file_id := file_nodes[file] {
			if tc.subtree_has_spawn_expr(file_id) {
				return true
			}
		}
		for imported_module in file_imports[file] or { []string{} } {
			mut imported_files := module_files[imported_module] or { []string{} }
			if imported_files.len == 0 && imported_module.contains('.') {
				short_name := imported_module.all_after_last('.')
				for candidate in module_files[short_name] or { []string{} } {
					if module_file_matches_import_path(candidate, imported_module) {
						imported_files << candidate
					}
				}
			}
			for imported_file in imported_files {
				if !seen_files[imported_file] {
					seen_files[imported_file] = true
					reachable_files << imported_file
				}
			}
		}
	}
	return false
}

// prepare_threads_condition caches whether selected inputs or their reachable imports use spawn.
pub fn (mut tc TypeChecker) prepare_threads_condition() {
	if tc.has_spawn_expr < 0 {
		tc.has_spawn_expr = if tc.scan_has_spawn_expr() { 1 } else { 0 }
	}
}

// threads_condition_value reports the cached `$if threads` condition, scanning lazily for
// direct TypeChecker users that do not run the regular compiler setup.
pub fn (tc &TypeChecker) threads_condition_value() bool {
	if tc.has_spawn_expr >= 0 {
		return tc.has_spawn_expr == 1
	}
	return tc.scan_has_spawn_expr()
}

fn (tc &TypeChecker) comptime_threads_condition_value(cond string) ?bool {
	clean := comptime_condition_strip_outer_parens(cond)
	if clean == 'threads' {
		return tc.threads_condition_value()
	}
	if clean == 'true' {
		return true
	}
	if clean == 'false' {
		return false
	}
	or_idx := comptime_condition_top_level_index(clean, '||')
	if or_idx >= 0 {
		left := tc.comptime_threads_condition_value(clean[..or_idx]) or { return none }
		if left {
			return true
		}
		return tc.comptime_threads_condition_value(clean[or_idx + 2..])
	}
	and_idx := comptime_condition_top_level_index(clean, '&&')
	if and_idx >= 0 {
		left := tc.comptime_threads_condition_value(clean[..and_idx]) or { return none }
		if !left {
			return false
		}
		return tc.comptime_threads_condition_value(clean[and_idx + 2..])
	}
	if clean.starts_with('!') {
		value := tc.comptime_threads_condition_value(clean[1..]) or { return none }
		return !value
	}
	return none
}

fn (mut tc TypeChecker) comptime_type_condition_value(cond string) ?bool {
	clean := comptime_condition_strip_outer_parens(cond)
	if clean == 'threads' {
		return tc.threads_condition_value()
	}
	if clean == 'true' {
		return true
	}
	if clean == 'false' {
		return false
	}
	or_idx := comptime_condition_top_level_index(clean, '||')
	if or_idx >= 0 {
		left := tc.comptime_type_condition_value(clean[..or_idx]) or { return none }
		if left {
			return true
		}
		return tc.comptime_type_condition_value(clean[or_idx + 2..])
	}
	and_idx := comptime_condition_top_level_index(clean, '&&')
	if and_idx >= 0 {
		left := tc.comptime_type_condition_value(clean[..and_idx]) or { return none }
		if !left {
			return false
		}
		return tc.comptime_type_condition_value(clean[and_idx + 2..])
	}
	for op in [' !is ', ' is '] {
		op_idx := comptime_condition_top_level_index(clean, op)
		if op_idx >= 0 {
			left := trimmed_space(clean[..op_idx])
			right := trimmed_space(clean[op_idx + op.len..])
			matches := tc.comptime_type_matches(left, right) or { return none }
			return if op == ' is ' { matches } else { !matches }
		}
	}
	if clean.starts_with('!') {
		value := tc.comptime_type_condition_value(clean[1..]) or { return none }
		return !value
	}
	return none
}

fn (mut tc TypeChecker) comptime_type_matches(actual string, expected string) ?bool {
	clean_actual := trimmed_space(actual)
	clean_expected := trimmed_space(expected)
	if clean_actual.len == 0 || clean_expected.len == 0
		|| (is_bare_generic_param(clean_actual) && !tc.type_name_known(clean_actual)) {
		return none
	}
	actual_type := tc.comptime_type_match_type(clean_actual)
	normalized := actual_type.name()
	match clean_expected {
		'$array' {
			return actual_type is Array || actual_type is ArrayFixed
		}
		'$array_dynamic' {
			return actual_type is Array
		}
		'$array_fixed' {
			return actual_type is ArrayFixed
		}
		'$map' {
			return actual_type is Map
		}
		'$function' {
			return actual_type is FnType
		}
		'$option' {
			return actual_type is OptionType
		}
		'$shared' {
			return tc.comptime_type_text_is_shared(clean_actual)
		}
		'$pointer' {
			return actual_type is Pointer
		}
		'$voidptr' {
			return fn_param_is_voidptr_type(actual_type)
		}
		'$int' {
			return actual_type.is_integer()
		}
		'$float' {
			return actual_type.is_float()
		}
		'$string' {
			return actual_type is String
		}
		'$struct' {
			return actual_type is Struct && normalized in tc.structs
		}
		'$enum' {
			return normalized in tc.enum_names
		}
		'$alias' {
			return clean_actual in tc.type_aliases
				|| tc.qualify_name(clean_actual) in tc.type_aliases
		}
		'$sumtype' {
			return normalized in tc.sum_types
		}
		'$interface' {
			return normalized in tc.interface_names
		}
		else {}
	}

	expected_type := tc.comptime_type_match_type(clean_expected)
	if expected_type is Interface {
		return tc.type_implements_interface(actual_type, expected_type)
	}
	if expected_type.name() in tc.interface_names {
		return tc.type_implements_interface(actual_type, Interface{
			name: expected_type.name()
		})
	}
	return normalized == expected_type.name()
}

fn (tc &TypeChecker) comptime_type_text_is_shared(type_text string) bool {
	mut cur := trimmed_space(type_text)
	for _ in 0 .. 16 {
		if cur.starts_with('shared ') {
			return true
		}
		target := tc.alias_target_type_text(cur) or { return false }
		if target == cur {
			return false
		}
		cur = trimmed_space(target)
	}
	return false
}

fn (mut tc TypeChecker) comptime_type_match_type(type_text string) Type {
	typ := tc.parse_type(type_text)
	if typ is Alias {
		return typ.base_type
	}
	return typ
}

// type_text_implements_interface reports whether a concrete type expression
// satisfies an interface type expression in the current checker module context.
pub fn (mut tc TypeChecker) type_text_implements_interface(actual_text string, iface_text string) bool {
	actual := tc.parse_type(actual_text)
	expected := tc.comptime_type_match_type(iface_text)
	if expected is Interface {
		return tc.type_implements_interface(actual, expected)
	}
	expected_name := expected.name()
	if expected_name in tc.interface_names {
		return tc.type_implements_interface(actual, Interface{
			name: expected_name
		})
	}
	return false
}

fn comptime_condition_matching_paren(s string, start int) int {
	mut paren_depth := 0
	mut bracket_depth := 0
	for i in start .. s.len {
		match s[i] {
			`(` {
				paren_depth++
			}
			`)` {
				paren_depth--
				if paren_depth == 0 && bracket_depth == 0 {
					return i
				}
			}
			`[` {
				bracket_depth++
			}
			`]` {
				bracket_depth--
			}
			else {}
		}
	}
	return s.len
}

fn comptime_condition_strip_outer_parens(cond string) string {
	mut clean := trimmed_space(cond)
	for clean.len >= 2 && clean.starts_with('(') {
		end := comptime_condition_matching_paren(clean, 0)
		if end != clean.len - 1 {
			break
		}
		clean = trimmed_space(clean[1..clean.len - 1])
	}
	return clean
}

fn comptime_condition_top_level_index(s string, needle string) int {
	if needle.len == 0 || s.len < needle.len {
		return -1
	}
	mut paren_depth := 0
	mut bracket_depth := 0
	for i := 0; i <= s.len - needle.len; i++ {
		match s[i] {
			`(` {
				paren_depth++
			}
			`)` {
				if paren_depth > 0 {
					paren_depth--
				}
			}
			`[` {
				bracket_depth++
			}
			`]` {
				if bracket_depth > 0 {
					bracket_depth--
				}
			}
			else {}
		}

		if paren_depth == 0 && bracket_depth == 0 && s[i..].starts_with(needle) {
			return i
		}
	}
	return -1
}

// check_infix validates type-sensitive infix operations that would otherwise reach CGen
// as raw helper calls with incompatible arguments.
fn (mut tc TypeChecker) check_infix(id flat.NodeId, node flat.Node) {
	if node.children_count < 2 || !tc.should_diagnose(id) {
		return
	}
	lhs_id := tc.a.child(&node, 0)
	rhs_id := tc.a.child(&node, 1)
	lhs_node := tc.a.node(lhs_id)
	rhs_node := tc.a.node(rhs_id)
	mut lhs_type := tc.infix_read_type(lhs_id)
	mut rhs_type := tc.infix_read_type(rhs_id)
	if tc.expr_has_multi_match_member_error(lhs_id) || tc.expr_has_multi_match_member_error(rhs_id)
		|| tc.expr_contains_multi_pattern_subject_member(lhs_id)
		|| tc.expr_contains_multi_pattern_subject_member(rhs_id) {
		return
	}
	if rhs_node.kind == .enum_val && unalias_type(lhs_type) is Enum {
		rhs_type = tc.resolve_expr(rhs_id, lhs_type)
	} else if lhs_node.kind == .enum_val && unalias_type(rhs_type) is Enum {
		lhs_type = tc.resolve_expr(lhs_id, rhs_type)
	}
	if lhs_node.kind == .none_expr && rhs_node.kind == .none_expr {
		op := infix_operator_name(node.op) or { '' }
		tc.record_error_at(.condition_mismatch, 'invalid operator `${op}` to `none` and `none`',
			id, node.pos)
		if node.op in [.left_shift, .right_shift, .right_shift_unsigned] {
			tc.record_error_at(.condition_mismatch, 'invalid operation: shift on type `none`',
				lhs_id, lhs_node.pos)
			tc.register_synth_type(id, Type(void_))
			return
		}
		if node.op in [.logical_and, .logical_or] {
			tc.record_error_at(.condition_mismatch, 'left operand for `${op}` is not a boolean',
				lhs_id, lhs_node.pos)
			tc.record_error_at(.condition_mismatch, 'right operand for `${op}` is not a boolean',
				rhs_id, rhs_node.pos)
			tc.register_synth_type(id, Type(bool_))
			return
		}
		if node.op == .arrow {
			tc.record_error_at(.assignment_mismatch, 'cannot push on non-channel `none`', lhs_id,
				lhs_node.pos)
			tc.register_synth_type(id, Type(void_))
			return
		}
		return
	}
	if (lhs_node.kind == .as_expr && lhs_node.value.contains('.'))
		|| (rhs_node.kind == .as_expr && rhs_node.value.contains('.')) {
		return
	}
	lhs_is_nil := lhs_node.kind == .nil_literal || tc.expr_is_unsafe_nil(lhs_id)
	rhs_is_nil := rhs_node.kind == .nil_literal || tc.expr_is_unsafe_nil(rhs_id)
	if lhs_is_nil || rhs_is_nil {
		op := infix_operator_name(node.op) or { '' }
		other_type := if lhs_is_nil { rhs_type } else { lhs_type }
		clean_other := unalias_type(other_type)
		if node.op in [.eq, .ne] {
			if clean_other !is Pointer && clean_other !is FnType {
				tc.record_error_at(.condition_mismatch,
					'cannot compare with `nil` because `${other_type.name()}` is not a pointer',
					id, tc.infix_operator_pos(node, op))
				return
			}
		} else {
			tc.record_error_at(.condition_mismatch, 'cannot use `${op}` with `nil`', id, tc.infix_operator_pos(node,
				op))
			return
		}
	}
	if lhs_node.kind == .index && lhs_node.children_count > 0
		&& unalias_type(tc.resolve_type(tc.a.child(lhs_node, 0))) is OptionType {
		return
	}
	lhs_clean := unalias_type(lhs_type)
	rhs_clean := unalias_type(rhs_type)
	if lhs_clean is MultiReturn || rhs_clean is MultiReturn {
		op := infix_operator_name(node.op) or { '' }
		tc.record_error_at(.assignment_mismatch,
			'invalid number of operand for `${op}`. Only one allowed on each side.', id, node.pos)
		if node.op !in [.left_shift, .right_shift, .right_shift_unsigned, .logical_and, .logical_or,
			.arrow] {
			return
		}
	}
	if node.op == .plus && lhs_clean is Map && rhs_clean is Map {
		tc.record_error_at(.assignment_mismatch,
			'undefined operation `${lhs_type.name()}` + `${rhs_type.name()}`', id, node.pos)
		tc.register_synth_type(id, Type(void_))
		return
	}
	if node.op == .left_shift && lhs_clean is OptionType
		&& unalias_type(lhs_clean.base_type) is Array {
		tc.record_error_at(.assignment_mismatch,
			'cannot push to Option array that was not unwrapped first', lhs_id,
			tc.wrapped_operand_diagnostic_pos(lhs_id))
		if tc.a.node(lhs_id).kind != .selector {
			tc.record_wrapped_infix_operand_error(lhs_id, lhs_type, lhs_clean.base_type.name())
		}
		tc.register_synth_type(id, Type(void_))
		return
	}
	if node.op == .left_shift && array_type_from_receiver(lhs_type) != none
		&& unalias_type(rhs_type) is OptionType {
		tc.record_error_at(.assignment_mismatch,
			'unwrapped Option cannot be used in an infix expression', rhs_id, tc.infix_operator_pos(node,
			'<<'))
		return
	}
	if node.op == .plus && lhs_clean is OptionType && rhs_clean !is OptionType
		&& rhs_clean !is ResultType {
		payload := lhs_clean.base_type
		compatible := tc.type_compatible(rhs_type, payload)
		if !compatible || type_is_string_like(payload) || type_is_string_like(rhs_type) {
			tc.record_error(.assignment_mismatch, 'mismatched types `${lhs_type.name()}` and `${tc.diagnostic_expr_type_name(rhs_id,
				rhs_type)}`', id)
		}
		tc.record_wrapped_infix_operand_error(lhs_id, lhs_type, tc.diagnostic_expr_type_name(rhs_id,
			rhs_type))
		if !compatible {
			tc.record_error(.assignment_mismatch, 'infix expr: cannot use `${tc.diagnostic_expr_type_name(rhs_id,
				rhs_type)}` (right expression) as `${payload.name()}`', id)
			tc.register_synth_type(id, Type(void_))
		}
		return
	}
	if node.op == .plus && rhs_clean is OptionType && lhs_clean !is OptionType
		&& lhs_clean !is ResultType {
		payload := rhs_clean.base_type
		compatible := tc.type_compatible(lhs_type, payload)
		if !compatible || type_is_string_like(payload) || type_is_string_like(lhs_type) {
			tc.record_error(.assignment_mismatch, 'mismatched types `${tc.diagnostic_expr_type_name(lhs_id,
				lhs_type)}` and `${rhs_type.name()}`', id)
		}
		tc.record_wrapped_infix_operand_error(rhs_id, rhs_type, tc.diagnostic_expr_type_name(lhs_id,
			lhs_type))
		if !compatible {
			tc.register_synth_type(id, Type(void_))
		}
		return
	}
	if node.op in [.eq, .ne]
		&& (lhs_node.kind == .none_expr || tc.a.node(rhs_id).kind == .none_expr) {
		return
	}
	lhs_pointer_arithmetic := lhs_clean is Pointer && lhs_type.name() != 'voidptr'
	rhs_pointer_arithmetic := rhs_clean is Pointer && rhs_type.name() != 'voidptr'
	pointer_arithmetic := if node.op == .plus {
		(lhs_pointer_arithmetic && rhs_clean.is_integer())
			|| (rhs_pointer_arithmetic && lhs_clean.is_integer())
	} else if node.op == .minus {
		lhs_pointer_arithmetic && (rhs_clean.is_integer() || rhs_pointer_arithmetic)
	} else {
		false
	}
	if pointer_arithmetic {
		if tc.unsafe_depth == 0 && !tc.translated_files[tc.cur_file] {
			tc.record_warning_at(.assignment_mismatch,
				'pointer arithmetic is only allowed in `unsafe` blocks', id, node.pos)
		}
		return
	}
	if tc.check_wrapped_infix_operand(lhs_id, lhs_type, rhs_id, rhs_type) {
		return
	}
	enum_operands := lhs_clean is Enum && rhs_clean is Enum
	flag_enum_bit_op := enum_operands && lhs_clean.is_flag && rhs_clean.is_flag
		&& node.op in [.pipe, .amp, .xor]
	if flag_enum_bit_op {
		return
	}
	invalid_enum_op := enum_operands && node.op !in [.eq, .ne]
	if invalid_enum_op && node.op !in [.logical_and, .logical_or] {
		tc.record_invalid_enum_infix(id, node, lhs_clean)
		return
	}
	if node.op in [.eq, .ne, .lt, .gt, .le, .ge]
		&& tc.check_signed_unsigned_comparison(node.op, lhs_id, lhs_type, rhs_id, rhs_type) {
		return
	}
	if node.op in [.eq, .ne, .lt, .gt, .le, .ge] && (lhs_type is Void || rhs_type is Void) {
		tc.register_synth_type(id, Type(void_))
		return
	}
	if node.op in [.logical_and, .logical_or] {
		bool_type := Type(bool_)
		lhs_is_bool := tc.type_compatible(lhs_type, bool_type)
			&& !tc.expr_has_unresolved_generic_name_ident(lhs_id)
		rhs_is_bool := tc.type_compatible(rhs_type, bool_type)
			&& !tc.expr_has_unresolved_generic_name_ident(rhs_id)
		op := if node.op == .logical_and { '&&' } else { '||' }
		if !lhs_is_bool {
			tc.record_error_at(.condition_mismatch, 'left operand for `${op}` is not a boolean',
				lhs_id, lhs_node.pos)
		}
		if !rhs_is_bool {
			tc.record_error_at(.condition_mismatch, 'right operand for `${op}` is not a boolean',
				rhs_id, tc.a.node(rhs_id).pos)
			if node.op == .logical_or && rhs_clean !is MultiReturn {
				tc.record_error(.condition_mismatch, 'infix expr: cannot use `${tc.diagnostic_expr_type_name(rhs_id,
					rhs_type)}` (right expression) as `bool`', id)
			}
		}
		if node.op == .logical_or && lhs_node.kind == .infix && lhs_node.op == .logical_and {
			tc.record_error_at(.condition_mismatch,
				'ambiguous boolean expression. use `()` to ensure correct order of operations', id, tc.infix_operator_pos(node,
				'||'))
		}
		if invalid_enum_op {
			tc.record_invalid_enum_infix(id, node, lhs_clean)
		}
		if !lhs_is_bool || !rhs_is_bool {
			tc.register_synth_type(id, Type(void_))
		}
		return
	}
	if node.op == .plus && (lhs_clean is SumType || rhs_clean is SumType) {
		sum_name := if lhs_clean is SumType { lhs_clean.name } else { (rhs_clean as SumType).name }
		tc.record_error_at(.assignment_mismatch, 'cannot use operator `+` with `${sum_name}`', id, tc.infix_operator_pos(node,
			'+'))
		if lhs_clean !is SumType {
			tc.record_error(.assignment_mismatch, 'infix expr: cannot use `${tc.diagnostic_expr_type_name(rhs_id,
				rhs_type)}` (right expression) as `${tc.diagnostic_expr_type_name(lhs_id, lhs_type)}`',
				id)
		}
		return
	}
	if node.op in [.eq, .ne] {
		lhs_is_sum := lhs_clean is SumType
		rhs_is_sum := rhs_clean is SumType
		compatible := if lhs_is_sum != rhs_is_sum {
			false
		} else {
			tc.type_compatible(lhs_type, rhs_type) || tc.type_compatible(rhs_type, lhs_type)
				|| tc.expr_compatible(lhs_id, lhs_type, rhs_type)
				|| tc.expr_compatible(rhs_id, rhs_type, lhs_type)
		}
		unsafe_zero_struct_comparison :=
			((lhs_clean is Struct && tc.zero_literal_expr_id(rhs_id) != none)
			|| (rhs_clean is Struct && tc.zero_literal_expr_id(lhs_id) != none))
			&& (tc.unsafe_depth > 0 || tc.expr_is_inside_unsafe_block(id))
		if !compatible && !unsafe_zero_struct_comparison
			&& lhs_node.kind !in [.none_expr, .nil_literal]
			&& tc.a.node(rhs_id).kind !in [.none_expr, .nil_literal] {
			lhs_name := if lhs_clean is Pointer && unalias_type(lhs_clean.base_type) is Struct
				&& rhs_clean !is Pointer {
				tc.diagnostic_type_name(lhs_clean.base_type)
			} else {
				tc.diagnostic_expr_type_name(lhs_id, lhs_type)
			}
			rhs_name := tc.diagnostic_expr_type_name(rhs_id, rhs_type)
			pointer_value_comparison :=
				(rhs_clean is Pointer && tc.type_compatible(rhs_clean.base_type, lhs_clean))
				|| (lhs_clean is Pointer && tc.type_compatible(lhs_clean.base_type, rhs_clean))
			suffix := if tc.unsafe_depth == 0 && lhs_clean is Struct
				&& tc.zero_literal_expr_id(rhs_id) != none {
				'  (you can use it inside an `unsafe` block)'
			} else if tc.unsafe_depth == 0 && pointer_value_comparison {
				' (you can use it inside an `unsafe` block)'
			} else {
				''
			}
			diagnostic_pos := if rhs_node.kind == .prefix && rhs_node.op == .amp
				&& node.pos.is_valid() && node.pos.end > node.pos.offset {
				token.new_span(node.pos.id, node.pos.offset, node.pos.end - 1)
			} else {
				node.pos
			}
			tc.record_error_at(.assignment_mismatch,
				'infix expr: cannot use `${rhs_name}` (right expression) as `${lhs_name}`${suffix}',
				id, diagnostic_pos)
		}
		return
	}
	if node.op in [.div, .mod] {
		if zero_id := tc.zero_literal_expr_id(rhs_id) {
			message := if node.op == .div { 'division by zero' } else { 'modulo by zero' }
			tc.record_error(.assignment_mismatch, message, zero_id)
			return
		}
	}
	if node.op in [.lt, .gt, .le, .ge] && array_type_from_receiver(lhs_type) != none
		&& array_type_from_receiver(rhs_type) != none {
		op := infix_operator_name(node.op) or { '' }
		tc.record_error_at(.assignment_mismatch, 'only `==` and `!=` are defined on arrays', id, tc.infix_operator_pos(node,
			op))
		return
	}
	lhs_is_fn_pointer := fn_type_from_type(lhs_clean) != none
		|| (lhs_clean is Pointer && fn_type_from_type(lhs_clean.base_type) != none)
	rhs_is_fn_pointer := fn_type_from_type(rhs_clean) != none
		|| (rhs_clean is Pointer && fn_type_from_type(rhs_clean.base_type) != none)
	if node.op in [.lt, .gt, .le, .ge] && lhs_is_fn_pointer && rhs_is_fn_pointer {
		op := infix_operator_name(node.op) or { '' }
		lhs_name := if lhs_clean is FnType {
			'&${lhs_type.name().replace_once('fn(', 'fn (')}'
		} else {
			lhs_type.name()
		}
		rhs_name := if rhs_clean is FnType {
			'&${rhs_type.name().replace_once('fn(', 'fn (')}'
		} else {
			rhs_type.name()
		}
		tc.record_error_at(.condition_mismatch,
			'undefined operation `${lhs_name}` ${op} `${rhs_name}`', id, node.pos)
		return
	}
	lhs_order_type := unalias_and_unwrap_pointer_type(lhs_type)
	rhs_order_type := unalias_and_unwrap_pointer_type(rhs_type)
	if node.op in [.lt, .gt, .le, .ge] && lhs_order_type is Struct && rhs_order_type is Struct {
		required_op := match node.op {
			.gt, .ge, .le, .lt { flat.Op.lt }
			else { node.op }
		}
		if !tc.type_has_infix_operator_method(lhs_order_type, required_op) {
			op := infix_operator_name(node.op) or { '' }
			diagnostic_pos := if lhs_node.kind == .index && lhs_node.children_count > 1 {
				index_id := tc.a.child(lhs_node, 1)
				index_node := tc.a.node(index_id)
				token.new_span(node.pos.id, int_max(node.pos.offset, index_node.pos.offset - 1),
					node.pos.end)
			} else {
				node.pos
			}
			lhs_name := tc.diagnostic_expr_type_name(lhs_id, lhs_type)
			rhs_name := tc.diagnostic_expr_type_name(rhs_id, rhs_type)
			if lhs_name == rhs_name {
				tc.record_error_at(.condition_mismatch,
					'undefined operation `${lhs_name}` ${op} `${rhs_name}`', id, diagnostic_pos)
			} else {
				tc.record_error_at(.condition_mismatch,
					'mismatched types `${lhs_name}` and `${rhs_name}`', id, diagnostic_pos)
				tc.record_error_at(.condition_mismatch,
					'infix expr: cannot use `${rhs_name}` (right expression) as `${lhs_name}`', id,
					diagnostic_pos)
			}
		}
		return
	}
	if node.op == .arrow {
		channel_type := unalias_and_unwrap_pointer_type(lhs_type)
		if channel_type !is Channel {
			tc.record_error_at(.assignment_mismatch,
				'cannot push on non-channel `${lhs_type.name()}`', lhs_id, lhs_node.pos)
			tc.register_synth_type(id, Type(void_))
			return
		}
		channel := channel_type as Channel
		if channel.is_mut {
			tc.check_lvalue_mutability(rhs_id)
		}
		if !tc.expr_compatible(rhs_id, rhs_type, channel.elem_type) {
			message := if unalias_type(channel.elem_type) is Pointer
				&& unalias_type(rhs_type) !is Pointer {
				'cannot push non-reference `${rhs_type.name()}` on `${Type(channel).name()}`'
			} else {
				'cannot push `${rhs_type.name()}` on `${Type(channel).name()}`'
			}
			rhs_pos := if rhs_node.kind == .prefix && rhs_node.op == .amp {
				tc.prefix_operator_pos(rhs_id, '&')
			} else {
				tc.array_element_diagnostic_pos(rhs_id)
			}
			tc.record_error_at(.assignment_mismatch, message, rhs_id, rhs_pos)
		}
		tc.register_synth_type(id, Type(void_))
		return
	}
	if node.op in [.amp, .pipe, .xor] {
		op := infix_operator_name(node.op) or { '' }
		if !unalias_type(lhs_type).is_integer() {
			tc.record_error_at(.assignment_mismatch, 'left type of `${op}` cannot be non-integer type `${tc.diagnostic_expr_type_name(lhs_id,
				lhs_type)}`', lhs_id, lhs_node.pos)
			return
		}
		if !unalias_type(rhs_type).is_integer() {
			tc.record_error_at(.assignment_mismatch, 'right type of `${op}` cannot be non-integer type `${tc.diagnostic_expr_type_name(rhs_id,
				rhs_type)}`', rhs_id, tc.a.node(rhs_id).pos)
			return
		}
	}
	if node.op == .left_shift {
		if lhs_array := array_type_from_receiver(lhs_type) {
			tc.check_lvalue_mutability(lhs_id)
			if const_id := tc.addressed_const_ident(rhs_id) {
				const_node := tc.a.node(const_id)
				tc.record_error_at(.assignment_mismatch,
					'cannot have mutable reference to const `${const_node.value}`', const_id,
					tc.node_value_diagnostic_pos(const_id))
			}
			append_rhs_type := tc.array_append_diagnostic_rhs_type(rhs_id, rhs_type)
			if !tc.array_append_rhs_compatible(rhs_id, append_rhs_type, lhs_array.elem_type)
				|| (unalias_type(append_rhs_type) is ArrayFixed
				&& unalias_type(lhs_array.elem_type) is Interface) {
				rhs_name := tc.array_append_rhs_diagnostic_name(rhs_id, append_rhs_type)
				diagnostic_id := tc.array_append_rhs_diagnostic_id(rhs_id)
				elem_type := unalias_type(lhs_array.elem_type)
				if elem_type is Interface {
					if !tc.record_interface_implementation_error(.assignment_mismatch,
						append_rhs_type, elem_type, diagnostic_id, tc.a.node(diagnostic_id).pos) {
						tc.record_error(.assignment_mismatch,
							'cannot append `${rhs_name}` to `${lhs_type.name()}`', diagnostic_id)
					}
				} else {
					tc.record_error(.assignment_mismatch,
						'cannot append `${rhs_name}` to `${lhs_type.name()}`', diagnostic_id)
				}
			}
			if !tc.array_append_is_standalone_statement(id) {
				tc.record_error_at(.assignment_mismatch,
					'array append cannot be used in an expression', id, tc.infix_operator_pos(node,
					'<<'))
			}
			if tc.a.nodes[int(lhs_id)].kind == .array_literal {
				tc.record_error(.assignment_mismatch, 'array literal can not be modified', lhs_id)
			}
			return
		}
	}
	if node.op in [.left_shift, .right_shift, .right_shift_unsigned] {
		if !unalias_type(lhs_type).is_integer() {
			tc.record_error_at(.assignment_mismatch, 'invalid operation: shift on type `${tc.diagnostic_expr_type_name(lhs_id,
				lhs_type)}`', lhs_id, lhs_node.pos)
			tc.register_synth_type(id, Type(void_))
			return
		}
		if !unalias_type(rhs_type).is_integer() {
			tc.record_error_at(.assignment_mismatch, 'cannot shift non-integer type `${tc.diagnostic_expr_type_name(rhs_id,
				rhs_type)}` into type `${tc.diagnostic_expr_type_name(lhs_id, lhs_type)}`', rhs_id,
				tc.a.node(rhs_id).pos)
			tc.register_synth_type(id, Type(void_))
			return
		}
		skip_inactive_compact_else := tc.shift_is_in_inactive_compact_else(id)
		bit_size := tc.integer_shift_bit_size(lhs_type)
		if !skip_inactive_compact_else && bit_size > 0 && rhs_node.kind == .int_literal {
			if shift_count := v_int_literal_value(rhs_node.value) {
				if shift_count >= bit_size {
					tc.record_error_at(.assignment_mismatch,
						'shift count for type `${lhs_type.name()}` too large (maximum: ${bit_size - 1} bits)',
						rhs_id, rhs_node.pos)
				}
			}
		}
		if !skip_inactive_compact_else && node.op == .left_shift && lhs_node.kind == .ident
			&& tc.ident_is_mutable_lvalue(lhs_node.value) && !type_is_unsigned_integer(lhs_type) {
			tc.record_notice_at(.assignment_mismatch,
				'shifting a value from a signed type `${lhs_type.name()}` can change the sign',
				lhs_id, tc.node_value_diagnostic_pos(lhs_id))
		}
		if node.op == .left_shift && tc.array_append_is_standalone_statement(id) {
			tc.record_error_at(.assignment_mismatch, 'unused expression', id, node.pos)
		}
	}
	if node.op in [.minus, .mul, .div, .mod] && (lhs_type is Void || rhs_type is Void) {
		lhs_name := tc.diagnostic_expr_type_name(lhs_id, lhs_type)
		rhs_name := tc.diagnostic_expr_type_name(rhs_id, rhs_type)
		tc.record_error(.assignment_mismatch, 'mismatched types `${lhs_name}` and `${rhs_name}`',
			id)
		tc.register_synth_type(id, Type(void_))
		return
	}
	if node.op in [.plus, .minus] && lhs_type.name() == 'voidptr' {
		op := infix_operator_name(node.op) or { '' }
		tc.record_error_at(.assignment_mismatch, '`${op}` cannot be used with `voidptr`', lhs_id,
			lhs_node.pos)
		return
	}
	if node.op == .mod && (unalias_type(lhs_type).is_float() || unalias_type(rhs_type).is_float()) {
		float_id := if unalias_type(lhs_type).is_float() { lhs_id } else { rhs_id }
		tc.record_error_at(.assignment_mismatch,
			'float modulo not allowed, use math.fmod() instead', float_id, tc.a.node(float_id).pos)
		return
	}
	if node.op in [.mul, .div, .mod] {
		lhs_pointer := lhs_clean is Pointer && lhs_type.name() != 'voidptr'
		rhs_pointer := rhs_clean is Pointer && rhs_type.name() != 'voidptr'
		if lhs_pointer || rhs_pointer {
			op := infix_operator_name(node.op) or { '' }
			if lhs_pointer {
				tc.record_error(.assignment_mismatch, 'invalid operator `${op}` to `${lhs_type.name()}` and `${tc.diagnostic_expr_type_name(rhs_id,
					rhs_type)}`', id)
			}
			tc.record_error(.assignment_mismatch,
				'infix `${op}` is not defined for pointer values', id)
			return
		}
	}
	if node.op in [.minus, .mul, .div, .mod] {
		if lhs_type is Unknown || rhs_type is Unknown {
			return
		}
		if node.op == .minus && lhs_type is Alias && rhs_type is Alias
			&& lhs_type.name == rhs_type.name
			&& (unalias_type(lhs_type) is Array || unalias_type(lhs_type) is Map) {
			tc.record_error(.assignment_mismatch,
				'undefined operation `${lhs_type.name}` - `${rhs_type.name}`', id)
			return
		}
		if (infix_power_type_is_numeric(lhs_type) && infix_power_type_is_numeric(rhs_type))
			|| tc.infix_operator_return_type(node.op, lhs_type, rhs_type) != none {
			return
		}
		lhs_name := tc.diagnostic_expr_type_name(lhs_id, lhs_type)
		rhs_name := tc.diagnostic_expr_type_name(rhs_id, rhs_type)
		if lhs_clean is Struct && rhs_clean is Struct && lhs_name == rhs_name
			&& !tc.type_has_infix_operator_method(lhs_type, node.op)
			&& !tc.type_has_infix_operator_method(rhs_type, node.op) {
			op := infix_operator_name(node.op) or { '' }
			tc.record_error(.assignment_mismatch,
				'undefined operation `${lhs_name}` ${op} `${rhs_name}`', id)
			return
		}
		if !tc.type_has_infix_operator_method(lhs_type, node.op)
			&& !tc.type_has_infix_operator_method(rhs_type, node.op) {
			tc.record_error(.assignment_mismatch,
				'mismatched types `${lhs_name}` and `${rhs_name}`', id)
		}
		tc.record_error(.assignment_mismatch,
			'infix expr: cannot use `${rhs_name}` (right expression) as `${lhs_name}`', id)
		return
	}
	if node.op == .power {
		if lhs_type is Unknown || rhs_type is Unknown {
			return
		}
		if _ := tc.infix_operator_return_type(node.op, lhs_type, rhs_type) {
			return
		}
		if !infix_power_type_is_numeric(lhs_type) || !infix_power_type_is_numeric(rhs_type) {
			tc.record_error(.assignment_mismatch,
				'operator `**` requires numeric operands; got `${lhs_type.name()}` and `${rhs_type.name()}`',
				id)
		}
		return
	}
	if node.op != .plus {
		return
	}
	lhs_pointer := unalias_type(lhs_type) is Pointer && lhs_type.name() != 'voidptr'
	rhs_pointer := unalias_type(rhs_type) is Pointer && rhs_type.name() != 'voidptr'
	if lhs_pointer && rhs_pointer {
		tc.record_error(.assignment_mismatch,
			'invalid operator `+` to `${lhs_type.name()}` and `${rhs_type.name()}`', id)
		return
	}
	if (lhs_pointer && !rhs_type.is_integer()) || (rhs_pointer && !lhs_type.is_integer()) {
		tc.record_error_at(.assignment_mismatch,
			'mismatched types `${lhs_type.name()}` and `${rhs_type.name()}`', id, token.new_span(node.pos.id,
			node.pos.offset, int_max(node.pos.offset + 1, node.pos.end - 1)))
		tc.register_synth_type(id, Type(void_))
		return
	}
	if signature := tc.infix_operator_signature(.plus, lhs_type) {
		if signature.param_count >= 2
			&& signature.param_type.name() != unwrap_pointer(lhs_type).name()
			&& rhs_type.name() == signature.param_type.name() {
			tc.record_error(.assignment_mismatch, 'infix expr: cannot use `${tc.diagnostic_expr_type_name(rhs_id,
				rhs_type)}` (right expression) as `${tc.diagnostic_expr_type_name(lhs_id, lhs_type)}`',
				id)
			return
		}
	}
	lhs_is_string := type_is_string_like(lhs_type)
	rhs_is_string := type_is_string_like(rhs_type)
	if lhs_is_string || rhs_is_string {
		if lhs_is_string != rhs_is_string && lhs_type !is Unknown && rhs_type !is Unknown {
			tc.record_error(.assignment_mismatch,
				'operator `+` cannot concatenate `${lhs_type.name()}` and `${rhs_type.name()}`', id)
		}
		return
	}
	if lhs_type is Unknown || rhs_type is Unknown {
		return
	}
	if (infix_power_type_is_numeric(lhs_type) && infix_power_type_is_numeric(rhs_type))
		|| tc.infix_operator_return_type(node.op, lhs_type, rhs_type) != none
		|| (lhs_type is Pointer && rhs_type.is_integer())
		|| (rhs_type is Pointer && lhs_type.is_integer()) {
		return
	}
	lhs_name := tc.diagnostic_expr_type_name(lhs_id, lhs_type)
	rhs_name := tc.diagnostic_expr_type_name(rhs_id, rhs_type)
	tc.record_error(.assignment_mismatch, 'mismatched types `${lhs_name}` and `${rhs_name}`', id)
	if lhs_type is Void || rhs_type is Void {
		return
	}
	tc.record_error(.assignment_mismatch,
		'infix expr: cannot use `${rhs_name}` (right expression) as `${lhs_name}`', id)
}

fn (tc &TypeChecker) integer_shift_bit_size(typ Type) int {
	clean := unalias_type(typ)
	if clean is Primitive {
		if typ.name() == 'int' || clean.size == 0 {
			return 32
		}
		return int(clean.size)
	}
	if clean is ISize || clean is USize {
		return 64
	}
	return 0
}

fn (tc &TypeChecker) shift_is_in_inactive_compact_else(id flat.NodeId) bool {
	mut current_id := id
	for _ in 0 .. 8 {
		parent_id := tc.direct_parent_id(current_id)
		if !tc.valid_node_id(parent_id) {
			return false
		}
		parent := tc.a.node(parent_id)
		if parent.kind == .if_expr && parent.children_count >= 3 {
			condition_id := tc.a.child(parent, 0)
			condition_value := tc.constant_bool_value(condition_id) or { return false }
			if !condition_value {
				return false
			}
			else_id := tc.a.child(parent, 2)
			if current_id != else_id {
				return false
			}
			else_node := tc.a.node(else_id)
			return else_node.kind == .block && else_node.children_count == 1
		}
		current_id = parent_id
	}
	return false
}

fn (tc &TypeChecker) expr_has_unresolved_generic_name_ident(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind == .ident && is_bare_generic_param(node.value) && !tc.type_name_known(node.value)
		&& node.value !in tc.fn_context.generic_params && !tc.active_generic_param(node.value)
		&& !tc.node_has_enclosing_generic_param(id, node.value)
		&& !tc.source_enclosing_fn_has_generic_param(id, node.value) {
		return true
	}
	for i in 0 .. node.children_count {
		if tc.expr_has_unresolved_generic_name_ident(tc.a.child(node, i)) {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) check_wrapped_infix_operand(lhs_id flat.NodeId, lhs_type Type, rhs_id flat.NodeId, rhs_type Type) bool {
	lhs_clean := unalias_type(lhs_type)
	rhs_clean := unalias_type(rhs_type)
	if lhs_clean is ResultType {
		tc.record_unwrapped_result_infix_error(lhs_id, lhs_clean)
		return true
	}
	if rhs_clean is ResultType {
		tc.record_unwrapped_result_infix_error(rhs_id, rhs_clean)
		return true
	}
	if lhs_clean is OptionType {
		if tc.a.node(rhs_id).kind == .none_expr {
			return false
		}
		expected_name := if rhs_clean is OptionType {
			lhs_clean.base_type.name()
		} else {
			tc.diagnostic_expr_type_name(rhs_id, rhs_type)
		}
		tc.record_wrapped_infix_operand_error(lhs_id, lhs_type, expected_name)
		return true
	}
	if rhs_clean is OptionType {
		if tc.a.node(lhs_id).kind == .none_expr {
			return false
		}
		tc.record_wrapped_infix_operand_error(rhs_id, rhs_type, tc.diagnostic_expr_type_name(lhs_id,
			lhs_type))
		option_base := unalias_type(rhs_clean.base_type)
		interface_base := if option_base is Pointer {
			unalias_type(option_base.base_type)
		} else {
			option_base
		}
		if unalias_and_unwrap_pointer_type(lhs_type) is Struct && interface_base is Interface {
			parent_id := tc.direct_parent_id(rhs_id)
			if tc.valid_node_id(parent_id) && tc.a.node(parent_id).kind == .infix {
				tc.record_error(.assignment_mismatch, 'infix expr: cannot use `${interface_base.name}` (right expression) as `${tc.diagnostic_expr_type_name(lhs_id,
					lhs_type)}`', parent_id)
			}
		}
		return true
	}
	return false
}

fn (mut tc TypeChecker) record_invalid_enum_infix(id flat.NodeId, node flat.Node, typ Type) {
	clean := unalias_type(typ)
	is_flag := clean is Enum && clean.is_flag
	message := if is_flag {
		'only `==`, `!=`, `|`, `&`, `^` and `~` are defined on `@[flag]` tagged `enum`, use an explicit cast to `int` if needed'
	} else {
		'only `==` and `!=` are defined on `enum`, use an explicit cast to `int` if needed'
	}
	op := infix_operator_name(node.op) or { '' }
	tc.record_error_at(.assignment_mismatch, message, id, tc.infix_operator_pos(node, op))
}

fn (tc &TypeChecker) expr_is_inside_unsafe_block(id flat.NodeId) bool {
	mut current := id
	for _ in 0 .. 32 {
		parent_id := tc.direct_parent_id(current)
		if !tc.valid_node_id(parent_id) {
			return false
		}
		parent := tc.a.node(parent_id)
		if parent.kind == .block && parent.value == 'unsafe' {
			return true
		}
		current = parent_id
	}
	return false
}

fn (mut tc TypeChecker) check_signed_unsigned_comparison(op flat.Op, lhs_id flat.NodeId, lhs_type Type, rhs_id flat.NodeId, rhs_type Type) bool {
	lhs_unsigned := type_is_unsigned_integer(lhs_type)
	rhs_unsigned := type_is_unsigned_integer(rhs_type)
	lhs_negative := tc.expr_is_negative_integer_literal(lhs_id)
	rhs_negative := tc.expr_is_negative_integer_literal(rhs_id)
	is_equality := op in [.eq, .ne]
	if lhs_unsigned && rhs_negative {
		message := if is_equality {
			'`${lhs_type.name()}` cannot be compared with negative value'
		} else {
			'unsigned integer cannot be compared with negative value'
		}
		tc.record_error_at(.condition_mismatch, message, rhs_id, tc.a.node(rhs_id).pos)
		return true
	}
	if lhs_negative && rhs_unsigned {
		message := if is_equality {
			'negative value cannot be compared with `${rhs_type.name()}`'
		} else {
			'unsigned integer cannot be compared with negative value'
		}
		tc.record_error_at(.condition_mismatch, message, lhs_id, tc.a.node(lhs_id).pos)
		return true
	}
	lhs_clean := unalias_type(lhs_type)
	rhs_clean := unalias_type(rhs_type)
	if !lhs_clean.is_integer() || !rhs_clean.is_integer() || lhs_unsigned == rhs_unsigned {
		return false
	}
	lhs := tc.a.node(lhs_id)
	rhs := tc.a.node(rhs_id)
	if (lhs_unsigned && rhs.kind == .int_literal && !rhs_negative)
		|| (rhs_unsigned && lhs.kind == .int_literal && !lhs_negative) {
		return false
	}
	signed_bits := if lhs_unsigned {
		comparison_integer_bits(rhs_clean)
	} else {
		comparison_integer_bits(lhs_clean)
	}
	unsigned_bits := if lhs_unsigned {
		comparison_integer_bits(lhs_clean)
	} else {
		comparison_integer_bits(rhs_clean)
	}
	if signed_bits >= unsigned_bits {
		return false
	}
	op_text := infix_operator_name(op) or { '' }
	parent_id := tc.direct_parent_id(lhs_id)
	parent := if tc.valid_node_id(parent_id) { *tc.a.node(parent_id) } else { flat.Node{} }
	pos := if parent.kind == .infix {
		tc.infix_operator_pos(parent, op_text)
	} else {
		tc.a.node(rhs_id).pos
	}
	tc.record_error_at(.condition_mismatch,
		'`${lhs_type.name()}` cannot be compared with `${rhs_type.name()}`', rhs_id, pos)
	return true
}

fn comparison_integer_bits(typ Type) int {
	clean := unalias_type(typ)
	if clean is Primitive {
		return if clean.size == 0 { 32 } else { int(clean.size) }
	}
	if clean is ISize || clean is USize {
		return 64
	}
	return 0
}

fn (mut tc TypeChecker) record_unwrapped_result_infix_error(id flat.NodeId, result_type ResultType) {
	tc.record_error_at(.assignment_mismatch,
		'unwrapped Result cannot be used in an infix expression', id,
		tc.wrapped_operand_diagnostic_pos(id))
	tc.record_unhandled_result_call(id, result_type)
}

fn (mut tc TypeChecker) record_wrapped_infix_operand_error(id flat.NodeId, wrapped Type, expected_name string) {
	clean := unalias_type(wrapped)
	display_name := if clean is OptionType {
		base := unalias_type(clean.base_type)
		if base is Pointer && unalias_type(base.base_type) is Interface {
			'?${base.base_type.name()}'
		} else {
			wrapped.name()
		}
	} else {
		wrapped.name()
	}
	tc.record_error_at(.assignment_mismatch,
		'`${display_name}` cannot be used as `${expected_name}`, unwrap the option first', id,
		tc.wrapped_operand_diagnostic_pos(id))
}

fn (tc &TypeChecker) array_append_rhs_diagnostic_name(id flat.NodeId, typ Type) string {
	name := tc.diagnostic_expr_type_name(id, typ)
	if tc.a.node(id).kind == .spawn_expr && name.ends_with('!void') {
		return name[..name.len - 4]
	}
	return name
}

fn (tc &TypeChecker) array_append_rhs_diagnostic_id(id flat.NodeId) flat.NodeId {
	node := tc.a.node(id)
	if node.kind == .spawn_expr && node.children_count > 0 {
		return tc.a.child(node, 0)
	}
	return id
}

fn (tc &TypeChecker) wrapped_operand_diagnostic_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	if node.kind == .prefix && node.op == .mul {
		return token.new_span(node.pos.id, node.pos.offset, node.pos.offset + 1)
	}
	if node.kind == .selector {
		return tc.node_value_diagnostic_pos(id)
	}
	if node.kind == .call && node.children_count > 0 {
		callee := tc.a.child_node(node, 0)
		if callee.kind == .selector && callee.children_count > 0 {
			base := tc.a.child_node(callee, 0)
			if base.kind == .ident && !tc.ident_resolves_to_value(base.value)
				&& tc.resolve_import_alias(base.value) != none {
				return tc.method_call_name_pos(*node, *callee)
			}
		}
	}
	return node.pos
}

fn (tc &TypeChecker) array_append_diagnostic_rhs_type(rhs_id flat.NodeId, fallback Type) Type {
	if !tc.valid_node_id(rhs_id) {
		return fallback
	}
	rhs := tc.a.nodes[int(rhs_id)]
	if rhs.kind != .array_literal || rhs.children_count == 0 {
		return fallback
	}
	for i in 0 .. rhs.children_count {
		if tc.a.child_node(&rhs, i).kind != .int_literal {
			return fallback
		}
	}
	return Type(Array{
		elem_type: Type(int_)
	})
}

fn (tc &TypeChecker) array_append_rhs_compatible(rhs_id flat.NodeId, rhs_type Type, elem_type Type) bool {
	if tc.expr_compatible(rhs_id, rhs_type, elem_type) {
		return true
	}
	clean_rhs := unalias_type(rhs_type)
	clean_elem := unalias_type(elem_type)
	if clean_elem is Pointer {
		pointer_base := unalias_type(clean_elem.base_type)
		if pointer_base is Interface && tc.type_compatible(clean_rhs, clean_elem.base_type) {
			return true
		}
	}
	if clean_rhs is Array {
		clean_rhs_elem := unalias_type(clean_rhs.elem_type)
		if clean_rhs_elem.is_integer() && clean_elem.is_integer() {
			return clean_rhs_elem.name() == clean_elem.name()
		}
		return tc.type_compatible(clean_rhs.elem_type, elem_type)
	}
	return tc.expr_compatible(rhs_id, rhs_type, elem_type)
}

fn (tc &TypeChecker) array_append_is_standalone_statement(id flat.NodeId) bool {
	if tc.is_statement_node(id) {
		return true
	}
	for index, candidate in tc.a.nodes {
		if candidate.kind == .expr_stmt && candidate.children_count == 1
			&& tc.a.child(&candidate, 0) == id {
			return tc.is_statement_node(flat.NodeId(index))
		}
	}
	return false
}

fn (tc &TypeChecker) zero_literal_expr_id(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind in [.int_literal, .float_literal] && numeric_literal_is_zero(node.value) {
		return id
	}
	if node.kind in [.cast_expr, .paren, .expr_stmt] && node.children_count > 0 {
		return tc.zero_literal_expr_id(tc.a.child(&node, 0))
	}
	return none
}

fn numeric_literal_is_zero(value string) bool {
	mut clean := value.to_lower().replace('_', '')
	for suffix in ['f32', 'f64', 'u8', 'u16', 'u32', 'u64', 'i8', 'i16', 'i32', 'i64'] {
		if clean.ends_with(suffix) {
			clean = clean[..clean.len - suffix.len]
			break
		}
	}
	if clean.starts_with('0x') || clean.starts_with('0b') || clean.starts_with('0o') {
		clean = clean[2..]
	}
	if clean.len == 0 {
		return false
	}
	for c in clean {
		if c !in [`0`, `.`] {
			return false
		}
	}
	return true
}

fn (tc &TypeChecker) infix_operator_pos(node flat.Node, op string) token.Pos {
	if node.children_count < 2 {
		return node.pos
	}
	lhs := tc.a.child_node(&node, 0)
	rhs := tc.a.child_node(&node, 1)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(lhs.pos.end, node.pos.offset)
	end := int_min(rhs.pos.offset, node.pos.end)
	if start < end {
		if relative := source[start..end].index(op) {
			op_start := start + relative
			return token.new_span(node.pos.id, op_start, op_start + op.len)
		}
	}
	if node.pos.offset >= 0 && node.pos.end <= source.len && node.pos.offset < node.pos.end {
		if relative := source[node.pos.offset..node.pos.end].index(op) {
			op_start := node.pos.offset + relative
			return token.new_span(node.pos.id, op_start, op_start + op.len)
		}
	}
	return node.pos
}

fn infix_power_type_is_numeric(typ Type) bool {
	clean := unalias_type(typ)
	return clean.is_integer() || clean.is_float()
}

fn optional_payload_is_string(typ Type) bool {
	if typ is OptionType {
		return type_is_string_like(typ.base_type)
	}
	if typ is ResultType {
		return type_is_string_like(typ.base_type)
	}
	return false
}

fn (tc &TypeChecker) infix_read_type(id flat.NodeId) Type {
	typ := tc.resolve_type(id)
	if int(id) < 0 {
		return typ
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .ident {
		if base := tc.mut_param_base_for_current_ident(node.value, typ) {
			return base
		}
	}
	return typ
}

fn (tc &TypeChecker) mut_param_base_for_current_ident(name string, typ Type) ?Type {
	if isnil(tc.cur_scope) || tc.cur_scope == tc.file_scope || tc.fn_context.node_id < 0 {
		return none
	}
	base := tc.fn_context.mut_param_base_types[name] or { return none }
	if !tc.lvalue_matches_mut_param(typ, base) {
		return none
	}
	if !tc.mut_param_binding_matches_lvalue(name) {
		return none
	}
	return base
}

fn type_is_string_like(typ Type) bool {
	if typ is String {
		return true
	}
	if typ is Alias {
		return type_is_string_like(typ.base_type)
	}
	return false
}

fn (tc &TypeChecker) select_branch_is_timeout(branch flat.Node) bool {
	if branch.kind != .select_branch || branch.value == 'else' || branch.children_count == 0
		|| branch.value in ['recv', 'recv_assign'] || branch.value.starts_with('recv_compound:') {
		return false
	}
	first := tc.a.child_node(&branch, 0)
	return !((first.kind == .infix && first.op == .arrow)
		|| (first.kind == .prefix && first.op == .arrow))
}

// check_select_stmt validates a `select { ... }` statement. A receive declaration
// binds the channel element type in the branch scope, while a receive assignment
// is checked against its existing lvalue type before the branch body.
fn (mut tc TypeChecker) check_select_stmt(node flat.Node) {
	mut has_else := false
	mut has_timeout := false
	mut conflict_id := flat.empty_node
	mut duplicate_timeout_id := flat.empty_node
	for i in 0 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		if !tc.valid_node_id(branch_id) {
			continue
		}
		branch := tc.a.nodes[int(branch_id)]
		if branch.kind != .select_branch {
			continue
		}
		if branch.value == 'else' {
			if has_timeout && int(conflict_id) < 0 {
				conflict_id = branch_id
			}
			has_else = true
		} else if tc.select_branch_is_timeout(branch) {
			if has_else && int(conflict_id) < 0 {
				conflict_id = branch_id
			}
			if has_timeout && int(duplicate_timeout_id) < 0 {
				duplicate_timeout_id = branch_id
			}
			has_timeout = true
		}
	}
	if tc.valid_node_id(conflict_id) {
		tc.record_error(.condition_mismatch,
			'`else` and timeout value are mutually exclusive `select` keys', conflict_id)
	}
	if tc.valid_node_id(duplicate_timeout_id) {
		tc.record_error(.condition_mismatch,
			'at most one timeout branch allowed in `select` block', duplicate_timeout_id)
	}
	$if ownership ? {
		tc.ownership_begin_branch_group()
	}
	base_smartcasts := clone_smartcasts(tc.smartcasts)
	mut invalidated_smartcasts := map[string]bool{}
	for i in 0 .. node.children_count {
		if base_smartcasts.len > 0 {
			tc.smartcasts = clone_smartcasts(base_smartcasts)
		}
		branch_id := tc.a.child(&node, i)
		if !tc.valid_node_id(branch_id) {
			continue
		}
		branch := tc.a.nodes[int(branch_id)]
		if branch.kind != .select_branch {
			tc.check_node(branch_id)
			for key, _ in base_smartcasts {
				if key !in tc.smartcasts {
					invalidated_smartcasts[key] = true
				}
			}
			continue
		}
		$if ownership ? {
			tc.ownership_begin_branch()
			if branch.value == 'else' {
				tc.ownership_note_branch_group_else()
			}
		}
		tc.push_scope()
		$if ownership ? {
			tc.ownership_mark_scope_node(branch_id)
		}
		mut body_start := 0
		is_assignment_case := branch.value in ['recv', 'recv_assign']
			|| branch.value.starts_with('recv_compound:')
		mut has_receive_rhs := false
		if is_assignment_case && branch.children_count >= 2 {
			second := tc.a.child_node(&branch, 1)
			has_receive_rhs = second.kind == .prefix && second.op == .arrow
		}
		if is_assignment_case && !has_receive_rhs {
			tc.record_error(.assignment_mismatch,
				'select assignment case requires a channel receive on the right side', branch_id)
			body_start = if branch.children_count >= 2 { 2 } else { int(branch.children_count) }
		}
		if branch.value.starts_with('recv_compound:') && has_receive_rhs {
			recv_id := tc.a.child(&branch, 1)
			tc.check_node(recv_id)
			op := branch.value.all_after('recv_compound:')
			tc.record_error(.assignment_mismatch,
				'compound receive assignment `${op}` is not supported in `select`; use `=` or `:=`',
				branch_id)
			body_start = 2
		}
		receive_assignment := branch.value in ['recv', 'recv_assign'] && has_receive_rhs
		if receive_assignment {
			// children[0] = bound/assigned lvalue, children[1] = `<-ch` receive expr.
			var_id := tc.a.child(&branch, 0)
			recv_id := tc.a.child(&branch, 1)
			if branch.value == 'recv' {
				tc.check_node(recv_id)
				elem_type := tc.resolve_type(recv_id)
				if tc.valid_node_id(var_id) {
					var_node := tc.a.nodes[int(var_id)]
					if var_node.kind == .ident && var_node.value.len > 0 {
						tc.cur_scope.insert(var_node.value, elem_type)
						tc.remember_expr_type(var_id, elem_type)
						$if ownership ? {
							tc.ownership_note_binding(var_node.value, elem_type, var_id)
						}
					} else {
						tc.record_error(.assignment_mismatch,
							'select receive declaration requires a plain identifier on the left side',
							var_id)
					}
				}
			} else {
				var_node := tc.a.node(var_id)
				if var_node.kind == .ident && var_node.value == '_' {
					tc.record_error_at(.assignment_mismatch,
						'cannot send on `_`, use `_ := <- quit` instead', var_id,
						tc.node_value_diagnostic_pos(var_id))
					tc.check_node(recv_id)
				} else {
					lhs_type := tc.resolve_lvalue_type(var_id)
					tc.remember_expr_type(var_id, lhs_type)
					expected_type := tc.assignment_expected_type(var_id, lhs_type)
					tc.annotate_expected_expr(recv_id, expected_type)
					tc.check_node(recv_id)
					rhs_type := tc.resolve_expr(recv_id, expected_type)
					if !tc.assignment_types_compatible(recv_id, rhs_type, expected_type, .assign) {
						tc.type_mismatch(.assignment_mismatch,
							'cannot assign `${rhs_type.name()}` to `${expected_type.name()}`',
							branch_id)
					}
					lhs_key := tc.expr_key(var_id)
					if lhs_key.len > 0 {
						tc.smartcasts.delete(lhs_key)
					}
				}
			}
			body_start = 2
		}
		tc.check_statement_sequence(branch, body_start, false)
		tc.pop_scope()
		$if ownership ? {
			tc.ownership_end_branch(branch_id)
		}
		for key, _ in base_smartcasts {
			if key !in tc.smartcasts {
				invalidated_smartcasts[key] = true
			}
		}
	}
	tc.smartcasts = clone_smartcasts(base_smartcasts)
	for key, _ in invalidated_smartcasts {
		tc.smartcasts.delete(key)
	}
	$if ownership ? {
		tc.ownership_end_branch_group()
	}
}

// check_array_init validates an `[]T{len: ..., init: ...}` initializer. The `init:`
// expression may reference the magic `index` variable (the current element index),
// so it is checked in a scope where `index` is bound to an int.
fn (mut tc TypeChecker) check_array_init(id flat.NodeId, node flat.Node) {
	if tc.fn_context.generic_params.len == 0
		&& tc.type_text_has_generic_struct_placeholder_application(node.typ) {
		tc.discard_unknown_type_errors_inside_node(node)
		tc.record_error_at(.unsupported_generic,
			'generic struct cannot be used in non-generic function', id,
			tc.array_init_head_pos(node))
		tc.register_synth_type(id, unknown_type('generic struct in non-generic function'))
		for i in 0 .. node.children_count {
			tc.check_node(tc.a.child(&node, i))
		}
		return
	}
	if generic_name := tc.bare_generic_decl_type_name(node.typ) {
		qualified := tc.qualify_name(generic_name)
		if generic_name in tc.struct_generic_params || qualified in tc.struct_generic_params {
			tc.record_error_at(.unknown_type,
				'generic struct `${generic_name}` must specify type parameter, e.g. ${generic_name}[int]',
				id, tc.type_diagnostic_pos(id, generic_name))
		}
	}
	if bound := fixed_array_bound_text(node.typ) {
		bound_pos := tc.fixed_array_bound_pos(node, bound)
		if message := tc.fixed_array_bound_type_diagnostic(bound) {
			tc.record_error_at(.assignment_mismatch, message, id, bound_pos)
			if message.ends_with('has to be casted to integer to be used as size')
				&& bound.contains('.') {
				tc.record_error_at(.assignment_mismatch,
					'fixed size cannot be zero or negative (fixed_size: 0)', id, bound_pos)
			}
		} else if fixed_size := tc.const_int_value(bound, []string{}) {
			if fixed_size <= 0 {
				tc.record_error_at(.assignment_mismatch,
					'fixed size cannot be zero or negative (fixed_size: ${fixed_size})', id,
					bound_pos)
			}
		} else {
			tc.record_error_at(.assignment_mismatch, 'non-constant array bound `${bound}`', id,
				bound_pos)
			tc.record_error_at(.assignment_mismatch,
				'fixed size cannot be zero or negative (fixed_size: 0)', id, bound_pos)
		}
	}
	if type_text_contains_any(node.typ) {
		end := int_max(node.pos.offset + 1, node.pos.end - 1)
		tc.record_error_at(.unknown_type, 'cannot use type `any` here', id, token.new_span(node.pos.id,
			node.pos.offset, end))
	}
	tc.check_array_elements_initialized(id, node)
	tc.check_array_element_reference_fields(id, node)
	declared_array_type := unalias_type(tc.parse_type(node.typ))
	init_elem_type := array_like_elem_type(declared_array_type)
	for field_name in ['init', 'len', 'cap'] {
		for i in 0 .. node.children_count {
			child_id := tc.a.child(&node, i)
			child := tc.a.nodes[int(child_id)]
			if child.kind != .field_init || child.value != field_name {
				continue
			}
			if child.children_count == 0 {
				tc.check_node(child_id)
				continue
			}
			expr_id := tc.a.child(&child, 0)
			if field_name == 'init' {
				tc.reject_stored_method_value(expr_id)
				tc.reject_stored_capturing_fn_literal(expr_id)
				tc.push_scope()
				tc.cur_scope.insert('index', Type(int_))
				tc.check_node(child_id)
				tc.pop_scope()
			} else {
				tc.check_node(child_id)
			}
			if field_name == 'init' {
				if expected := init_elem_type {
					actual := tc.resolve_type(expr_id)
					clean_actual := unalias_type(actual)
					if actual !is Unknown && clean_actual !is OptionType
						&& clean_actual !is ResultType
						&& !tc.expr_compatible(expr_id, actual, expected) {
						tc.record_error_at(.assignment_mismatch, 'expected `${expected.name()}`, not `${tc.diagnostic_expr_type_name(expr_id,
							actual)}`', expr_id, tc.a.node(expr_id).pos)
					}
				}
			}
			if field_name in ['len', 'cap'] {
				if value := tc.index_literal_value(expr_id) {
					if value < 0 {
						tc.record_error(.assignment_mismatch,
							'array ${field_name} can not be negative', expr_id)
					}
				}
			}
			if tc.expr_has_option_result_handler(expr_id) {
				continue
			}
			expr_type := unalias_type(tc.resolve_type(expr_id))
			wrapper := if expr_type is OptionType {
				'Option'
			} else if expr_type is ResultType {
				'Result'
			} else {
				continue
			}
			use_name := match field_name {
				'init' { 'initializer' }
				'len' { 'length' }
				else { 'capacity' }
			}
			tc.record_error(.assignment_mismatch, 'cannot use unwrapped ${wrapper} as ${use_name}',
				expr_id)
		}
	}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		if tc.a.nodes[int(child_id)].kind != .field_init {
			tc.check_node(child_id)
		}
	}
}

fn (mut tc TypeChecker) discard_unknown_type_errors_inside_node(node flat.Node) {
	mut i := tc.errors.len
	for i > 0 {
		i--
		diagnostic := tc.errors[i]
		if diagnostic.kind == .unknown_type && diagnostic.msg.starts_with('unknown type `')
			&& diagnostic.pos.id == node.pos.id && diagnostic.pos.offset >= node.pos.offset
			&& diagnostic.pos.end <= node.pos.end {
			tc.errors.delete(i)
		}
	}
}

fn (tc &TypeChecker) array_init_head_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, int_min(node.pos.offset, source.len))
	end := int_max(start, int_min(node.pos.end, source.len))
	if start < end {
		if relative := source[start..end].index('{') {
			return token.new_span(node.pos.id, start, start + relative + 1)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) fixed_array_bound_type_diagnostic(bound string) ?string {
	if key := tc.const_key_for_name(bound) {
		typ := unalias_type(tc.const_type_for_name(bound) or { Type(Unknown{}) })
		if typ is Enum {
			expr_id := tc.const_exprs[key] or {
				return '${typ.name}.${bound} has to be casted to integer to be used as size'
			}
			expr := tc.source_text_for_node(expr_id)
			return '${expr} has to be casted to integer to be used as size'
		}
		if typ !is Unknown && !typ.is_integer() {
			return 'only integer types are allowed'
		}
	}
	if bound.contains('.') {
		enum_name := bound.all_before('.')
		if tc.resolve_enum_name(enum_name) != none {
			return '${bound} has to be casted to integer to be used as size'
		}
	}
	if open := bound.index('(') {
		cast_name := trimmed_space(bound[..open])
		cast_type := unalias_type(tc.parse_type(cast_name))
		if cast_type !is Unknown && !cast_type.is_integer() {
			return 'only integer types are allowed'
		}
	}
	return none
}

fn fixed_array_bound_text(typ string) ?string {
	clean := trimmed_space(typ)
	if clean.len < 3 || clean[0] != `[` {
		return none
	}
	close := find_matching_bracket(clean, 0)
	if close <= 1 || close >= clean.len {
		return none
	}
	bound := trimmed_space(clean[1..close])
	if bound.len == 0 {
		return none
	}
	return bound
}

fn (tc &TypeChecker) fixed_array_bound_pos(node flat.Node, bound string) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(node.pos.end, source.len)
	if start < end {
		if bracket := source[start..end].index('[') {
			bound_start := start + bracket + 1
			return token.new_span(node.pos.id, bound_start, bound_start + bound.len)
		}
	}
	return node.pos
}

fn (mut tc TypeChecker) check_array_elements_initialized(id flat.NodeId, node flat.Node) {
	if tc.unsafe_depth > 0 || tc.translated_files[tc.cur_file] {
		return
	}
	container_type := unalias_type(tc.resolve_type(id))
	mut elem_type := Type(Unknown{
		reason: 'not an array'
	})
	mut is_fixed := false
	match container_type {
		Array {
			elem_type = container_type.elem_type
		}
		ArrayFixed {
			elem_type = container_type.elem_type
			is_fixed = true
		}
		else {
			return
		}
	}
	mut has_len := false
	mut has_init := false
	for i in 0 .. node.children_count {
		child := tc.a.child_node(&node, i)
		if child.kind != .field_init {
			continue
		}
		if child.value == 'len' {
			has_len = true
		} else if child.value == 'init' {
			has_init = true
		}
	}
	if !is_fixed && (!has_len || has_init) {
		return
	}
	mut seen := map[string]bool{}
	mut category := tc.array_uninitialized_element_category(elem_type, mut seen)
	if category.len == 0 && node.typ.contains('shared ') {
		category = 'references'
	}
	if category.len == 0 {
		return
	}
	pos := if is_fixed {
		node.pos
	} else {
		tc.array_init_type_prefix_pos(node)
	}
	message := if is_fixed {
		'fixed arrays of ${category} need to be initialized right away (unless inside `unsafe`)'
	} else {
		'arrays of ${category} need to be initialized right away, therefore `len:` cannot be used (unless inside `unsafe`, or if you also use `init:`)'
	}
	tc.record_warning_at(.assignment_mismatch, message, id, pos)
}

fn (tc &TypeChecker) node_is_from_translated_file(node flat.Node) bool {
	file := tc.a.source_files[node.pos.id] or { return false }
	return tc.translated_files[file.name]
}

fn (tc &TypeChecker) node_is_in_translated_file(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	return tc.node_is_from_translated_file(tc.a.node(id))
}

fn (tc &TypeChecker) array_uninitialized_element_category(typ Type, mut seen map[string]bool) string {
	type_name := typ.name()
	if type_name in seen {
		return ''
	}
	seen[type_name] = true
	return match typ {
		Alias {
			tc.array_uninitialized_element_category(typ.base_type, mut seen)
		}
		Pointer {
			'references'
		}
		Interface {
			'interfaces'
		}
		SumType {
			'sumtypes'
		}
		Array {
			tc.array_uninitialized_element_category(typ.elem_type, mut seen)
		}
		ArrayFixed {
			tc.array_uninitialized_element_category(typ.elem_type, mut seen)
		}
		Map {
			key_category := tc.array_uninitialized_element_category(typ.key_type, mut seen)
			if key_category.len > 0 {
				key_category
			} else {
				tc.array_uninitialized_element_category(typ.value_type, mut seen)
			}
		}
		else {
			''
		}
	}
}

fn (mut tc TypeChecker) check_array_element_reference_fields(id flat.NodeId, node flat.Node) {
	container_type := unalias_type(tc.resolve_type(id))
	mut elem_type := Type(Unknown{
		reason: 'not an array'
	})
	mut is_fixed := false
	match container_type {
		Array {
			elem_type = container_type.elem_type
		}
		ArrayFixed {
			elem_type = container_type.elem_type
			is_fixed = true
		}
		else {
			return
		}
	}
	if !is_fixed {
		mut has_len := false
		for i in 0 .. node.children_count {
			child := tc.a.child_node(&node, i)
			if child.kind == .field_init && child.value == 'len' {
				has_len = true
				break
			}
		}
		if !has_len {
			return
		}
	}
	clean_elem := unalias_type(elem_type)
	if clean_elem !is Struct {
		return
	}
	struct_elem := clean_elem as Struct
	pos := if is_fixed {
		node.pos
	} else {
		tc.array_init_type_prefix_pos(node)
	}
	mut checked := map[string]bool{}
	tc.record_uninitialized_reference_field_notices(struct_elem, struct_elem.name, id, pos, mut
		checked)
}

fn (tc &TypeChecker) array_init_type_prefix_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(source.len, node.pos.end)
	if start < end {
		if brace := source[start..end].index('{') {
			return token.new_span(node.pos.id, start, start + brace + 1)
		}
	}
	return node.pos
}

fn (mut tc TypeChecker) record_uninitialized_reference_field_notices(struct_type Struct, linked_name string,
	node_id flat.NodeId, pos token.Pos, mut checked map[string]bool) {
	if struct_type.name in checked {
		return
	}
	checked[struct_type.name] = true
	for field in tc.struct_fields_for_init(struct_type.name) {
		if field.has_default {
			continue
		}
		if field.typ is OptionType {
			continue
		}
		field_type := unalias_type(field.typ)
		if field_type is Pointer {
			tc.record_notice_at(.assignment_mismatch,
				'reference field `${linked_name}.${field.name}` must be initialized (part of struct `${struct_type.name}`)',
				node_id, pos)
			continue
		}
		if field_type is Struct && !field.is_embed {
			tc.record_uninitialized_reference_field_notices(field_type,
				'${linked_name}.${field.name}', node_id, pos, mut checked)
		}
	}
}

// check_or_expr validates check or expr state for types.
fn (mut tc TypeChecker) check_or_expr(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	inner_id := tc.a.child(&node, 0)
	tc.check_node(inner_id)
	if node.children_count >= 2 {
		inner := tc.a.node(inner_id)
		if inner.kind == .call && inner.children_count > 0 {
			callee := tc.a.child_node(inner, 0)
			if callee.kind == .selector && callee.children_count > 0
				&& unalias_type(tc.resolve_type(tc.a.child(callee, 0))) is ResultType {
				fallback_id := tc.a.child(&node, 1)
				tc.record_error_at(.assignment_mismatch,
					'unexpected `or` block, the function `${callee.value}` does not return an Option or a Result',
					id, tc.or_block_operator_pos(inner_id, fallback_id))
				return
			}
		}
	}
	if node.children_count >= 2 && node.value !in ['!', '?']
		&& int(id) != tc.channel_send_or_expr_id && !tc.or_expr_source_can_fail(inner_id) {
		mut source_type := unalias_type(tc.resolve_type(inner_id))
		if tc.a.node(inner_id).kind == .none_expr {
			if enclosing_type := tc.enclosing_infix_type_for_or_expr(id) {
				source_type = unalias_type(enclosing_type)
			}
		}
		inner := tc.a.node(inner_id)
		unresolved_method_call := inner.kind == .call && inner.children_count > 0
			&& tc.a.child_node(inner, 0).kind == .selector
		if (source_type !is Unknown || unresolved_method_call) && tc.should_diagnose(inner_id) {
			if inner.kind == .call {
				fallback_id := tc.a.child(&node, 1)
				name := tc.call_display_name(*inner).all_after_last('.')
				tc.record_error_at(.assignment_mismatch,
					'unexpected `or` block, the function `${name}` does not return an Option or a Result',
					id, tc.or_block_operator_pos(inner_id, fallback_id))
				return
			} else if inner.kind == .ident {
				if smart_type := tc.smartcast_type(inner_id) {
					tc.record_error(.assignment_mismatch,
						'cannot use `or {}` block on non-option variable `${inner.value}` (it was already unwrapped to `${smart_type.name()}` by an earlier none check; use `${inner.value}` directly)',
						inner_id)
				} else {
					tc.record_error(.assignment_mismatch,
						'cannot use `or {}` block on non-option variable', inner_id)
				}
			} else {
				tc.record_error(.assignment_mismatch,
					'unexpected `or` block, expression of type `${source_type.name()}` is not an Option or a Result',
					inner_id)
			}
		}
	}
	$if ownership ? {
		if node.value in ['!', '?'] {
			tc.ownership_record_propagation_drops()
		}
	}
	if node.value == '?' {
		tc.check_option_propagation(id, inner_id)
		return
	}
	if node.value == '!' {
		tc.check_result_propagation(id, inner_id)
		return
	}
	if node.children_count < 2 || node.value in ['!', '?'] {
		return
	}
	$if ownership ? {
		tc.ownership_begin_value_branch_group()
		tc.ownership_begin_branch()
	}
	fallback_id := tc.a.child(&node, 1)
	tc.push_scope()
	tc.cur_scope.insert('err', tc.parse_type('IError'))
	saved_expected_expr_id := tc.expected_expr_id
	saved_expected_expr_type := tc.expected_expr_type
	if payload := tc.or_expr_payload_type(inner_id) {
		tc.expected_expr_id = int(fallback_id)
		tc.expected_expr_type = payload
	}
	tc.check_or_fallback_branch_node(fallback_id)
	tc.expected_expr_id = saved_expected_expr_id
	tc.expected_expr_type = saved_expected_expr_type
	tc.pop_scope()
	inner := tc.a.node(inner_id)
	if inner.kind == .selector {
		if source := tc.selector_declared_value_type(*inner) {
			if source is OptionType {
				tail_id := tc.branch_tail_expr_id(fallback_id)
				if tc.valid_node_id(tail_id) {
					tail := tc.a.node(tail_id)
					if tail.kind in [.assign, .selector_assign, .index_assign]
						&& tail.children_count >= 2 {
						value_id := tc.a.child(tail, 0)
						rhs_id := tc.a.child(tail, tail.children_count - 1)
						tc.record_error_at(.assignment_mismatch,
							'last statement in the `or {}` block should be an expression of type `${source.base_type.name()}` or exit parent scope',
							value_id, tc.assignment_operator_pos(*tail, value_id, rhs_id))
						return
					}
				}
			}
		}
	}
	tc.check_or_fallback_type(id, inner_id, fallback_id)
	$if ownership ? {
		tc.ownership_end_branch(fallback_id)
		tc.ownership_add_branch_group_base()
		tc.ownership_end_branch_group()
	}
}

fn (mut tc TypeChecker) check_option_propagation(id flat.NodeId, source_id flat.NodeId) {
	source := tc.a.node(source_id)
	source_type := tc.resolve_type(source_id)
	if source_type is ResultType {
		source_text := tc.source_text_for_node(source_id)
		tc.record_error_at(.return_mismatch,
			'propagating a Result like an Option is deprecated, use `${source_text}!` instead of `${source_text}?`',
			id, tc.propagation_operator_pos(source_id, id, '?'))
		return
	}
	main_allows_propagation := tc.current_fn_is_main()
	propagation_parent_id := tc.direct_parent_id(id)
	if source.kind == .call && source_type is OptionType {
		if tc.valid_node_id(propagation_parent_id)
			&& tc.a.node(propagation_parent_id).kind == .return_stmt
			&& tc.fn_context.return_type is OptionType
			&& tc.return_type_compatible(source_id, source_type, tc.fn_context.return_type) {
			tc.record_error_at(.return_mismatch,
				'`?` is not needed, use `return ${tc.call_display_name(*source)}()`', source_id,
				source.pos)
			return
		}
		if tc.fn_context.return_type !is OptionType && !main_allows_propagation {
			tc.record_nested_propagation_return_errors(id, source_id, 'Option', '?')
		}
		return
	}
	if source.kind == .call && source_type !is OptionType && source_type !is Unknown {
		name := tc.call_display_name(*source).all_after_last('.')
		tc.record_error_at(.assignment_mismatch,
			'unexpected `?`, the function `${name}` does not return an Option', id, tc.propagation_operator_pos(source_id,
			id, '?'))
		return
	}
	if source.kind == .ident {
		if smart_type := tc.smartcast_type(source_id) {
			parent_id := tc.direct_parent_id(id)
			if tc.valid_node_id(parent_id) && tc.a.node(parent_id).kind == .return_stmt
				&& tc.fn_context.return_type is OptionType {
				parent := tc.a.node(parent_id)
				operator_pos := tc.propagation_operator_pos(source_id, id, '?')
				return_line := tc.previous_source_line_matching(parent.pos, 'return')
				tc.record_warning_at(.return_mismatch,
					'unwrapping option is redundant as the function returns option', parent_id, token.new_span(return_line.id,
					return_line.offset, operator_pos.offset))
			}
			tc.record_error_at(.assignment_mismatch,
				'cannot use `?` on non-option variable `${source.value}` (it was already unwrapped to `${smart_type.name()}` by an earlier none check; use `${source.value}` directly)',
				source_id, tc.node_value_diagnostic_pos(source_id))
			return
		}
		if source_type is OptionType {
			parent_id := tc.direct_parent_id(id)
			if tc.valid_node_id(parent_id) && tc.a.node(parent_id).kind == .return_stmt
				&& tc.fn_context.return_type !is OptionType && !main_allows_propagation {
				fn_id := flat.NodeId(tc.fn_context.node_id)
				if tc.valid_node_id(fn_id) {
					fn_node := tc.a.node(fn_id)
					fn_name := fn_node.value.all_after_last('.')
					return_pos := tc.fn_return_type_diagnostic_pos(*fn_node)
					detail := v3errors.formatted_source_error('details:',
						'prepend ? before the declaration of the return type of `${fn_name}`', tc.a.source_files[return_pos.id] or {
						return
					}, return_pos)
					tc.record_error_with_details_at(.return_mismatch,
						'to propagate the Option, `${fn_name}` must return an Option type', id,
						tc.node_value_diagnostic_pos(source_id), [detail])
				}
			}
			return
		}
		if source_type !is ResultType {
			tc.record_error_at(.assignment_mismatch, 'cannot use `?` on non-option variable',
				source_id, tc.wrapped_operand_diagnostic_pos(source_id))
			return
		}
	}
	if source.kind == .selector && source_type !is OptionType {
		// Selectors expanded from `$for field in T.fields` are synthetic. Cgen reports
		// the propagation error for their concrete field after comptime substitution.
		if !source.pos.is_valid() {
			return
		}
		tc.record_error_at(.assignment_mismatch,
			'unexpected `?`, the field `${source.value}` is not an Option', id, tc.propagation_operator_pos(source_id,
			id, '?'))
		return
	}
	if source.kind != .selector || source_type !is OptionType
		|| tc.fn_context.return_type is OptionType || main_allows_propagation {
		return
	}
	fn_id := flat.NodeId(tc.fn_context.node_id)
	if !tc.valid_node_id(fn_id) {
		return
	}
	fn_node := tc.a.node(fn_id)
	fn_name := fn_node.value.all_after_last('.')
	return_pos := tc.fn_return_type_diagnostic_pos(*fn_node)
	detail := v3errors.formatted_source_error('details:',
		'prepend ? before the declaration of the return type of `${fn_name}`', tc.a.source_files[return_pos.id] or {
		return
	}, return_pos)
	tc.record_error_with_details_at(.return_mismatch,
		'to propagate the call, `${fn_name}` must return an Option type', id, tc.propagation_operator_pos(source_id,
		id, '?'), [detail])
}

fn (mut tc TypeChecker) check_result_propagation(id flat.NodeId, source_id flat.NodeId) {
	source := tc.a.node(source_id)
	source_type := tc.resolve_type(source_id)
	if source_type is OptionType {
		tc.record_error_at(.return_mismatch,
			'to propagate a Result, the call must also return a Result type', id, tc.propagation_operator_pos(source_id,
			id, '!'))
		return
	}
	if source.kind == .call && tc.call_display_name(*source) == 'json.decode'
		&& source.children_count < 3 {
		tc.record_error_at(.return_mismatch,
			'unexpected `!`, the function `json.decode` does not return a Result', id, tc.propagation_operator_pos(source_id,
			id, '!'))
		return
	}
	if source.kind == .call && source_type !is ResultType && source_type !is Unknown {
		tc.record_error_at(.return_mismatch,
			'unexpected `!`, the function `${tc.call_display_name(*source)}` does not return a Result',
			id, tc.propagation_operator_pos(source_id, id, '!'))
		return
	}
	if source.kind == .call && source_type is ResultType && tc.fn_context.return_type !is ResultType
		&& !tc.current_fn_is_main() {
		tc.record_nested_propagation_return_errors(id, source_id, 'Result', '!')
	}
}

fn (tc &TypeChecker) current_fn_is_main() bool {
	fn_id := flat.NodeId(tc.fn_context.node_id)
	if !tc.valid_node_id(fn_id) {
		return false
	}
	node := tc.a.node(fn_id)
	return node.kind == .fn_decl && node.value.all_after_last('.') == 'main'
}

fn (mut tc TypeChecker) record_nested_propagation_return_errors(id flat.NodeId, source_id flat.NodeId, wrapper string, marker string) {
	fn_id := flat.NodeId(tc.fn_context.node_id)
	if !tc.valid_node_id(fn_id) {
		return
	}
	fn_node := tc.a.node(fn_id)
	fn_name := fn_node.value.all_after_last('.')
	return_pos := tc.fn_return_type_diagnostic_pos(*fn_node)
	detail := v3errors.formatted_source_error('details:',
		'prepend ${marker} before the declaration of the return type of `${fn_name}`', tc.a.source_files[return_pos.id] or {
		return
	}, return_pos)
	operator_pos := tc.propagation_operator_pos(source_id, id, marker)
	article := if wrapper == 'Option' { 'an' } else { 'a' }
	tc.record_error_with_details_at(.return_mismatch,
		'to propagate the ${wrapper} call, `${fn_name}` must return ${article} ${wrapper}', id,
		operator_pos, [detail])
	tc.record_error_with_details_at(.return_mismatch,
		'to propagate the call, `${fn_name}` must return ${article} ${wrapper} type', id,
		operator_pos, [
		detail,
	])
}

fn (tc &TypeChecker) fn_return_type_diagnostic_pos(node flat.Node) token.Pos {
	header_pos := tc.fn_declaration_diagnostic_pos(node)
	file := tc.a.source_files[header_pos.id] or { return header_pos }
	source := tc.source_texts_by_file[file.name] or { return header_pos }
	if header_pos.offset < 0 || header_pos.end > source.len || header_pos.end <= header_pos.offset {
		return header_pos
	}
	header := source[header_pos.offset..header_pos.end]
	if node.typ == 'void' {
		line_start := file.line_start(file.position(header_pos).line)
		line_end := source.index_after('\n', line_start) or { source.len }
		if relative := source[line_start..line_end].last_index('{') {
			start := line_start + relative
			return token.new_span(header_pos.id, start, start + 1)
		}
	}
	if relative := header.last_index(node.typ) {
		start := header_pos.offset + relative
		return token.new_span(header_pos.id, start, start + node.typ.len)
	}
	return header_pos
}

fn (tc &TypeChecker) option_void_payload_diagnostic_pos(node flat.Node) token.Pos {
	return_type := tc.fn_return_type_diagnostic_pos(node)
	if return_type.end - return_type.offset > 1 {
		return token.new_span(return_type.id, return_type.offset + 1, return_type.end)
	}
	return return_type
}

fn (tc &TypeChecker) suffix_option_return_type_diagnostic_pos(node flat.Node) token.Pos {
	return_type := tc.fn_return_type_diagnostic_pos(node)
	if return_type.end - return_type.offset > 1 {
		return token.new_span(return_type.id, return_type.offset, return_type.end - 1)
	}
	return return_type
}

fn (tc &TypeChecker) nested_option_result_marker_pos(node flat.Node) token.Pos {
	return_type := tc.fn_return_type_diagnostic_pos(node)
	if return_type.end - return_type.offset >= 2 {
		return token.new_span(return_type.id, return_type.offset + 1, return_type.offset + 2)
	}
	return return_type
}

fn (tc &TypeChecker) propagation_operator_pos(source_id flat.NodeId, expr_id flat.NodeId, op string) token.Pos {
	source_node := tc.a.node(source_id)
	expr := tc.a.node(expr_id)
	file := tc.a.source_files[source_node.pos.id] or { return expr.pos }
	text := tc.source_texts_by_file[file.name] or { return expr.pos }
	start := int_min(int_max(source_node.pos.end, 0), text.len)
	end := int_min(text.len, int_max(expr.pos.end, start + op.len))
	if start < end {
		if relative := text[start..end].index(op) {
			op_start := start + relative
			return token.new_span(source_node.pos.id, op_start, op_start + op.len)
		}
	}
	return expr.pos
}

fn (mut tc TypeChecker) check_or_fallback_type(or_id flat.NodeId, source_id flat.NodeId, fallback_id flat.NodeId) {
	if !tc.should_diagnose(or_id) {
		return
	}
	expected := tc.or_expr_payload_type(source_id) or { return }
	fallback := tc.a.node(fallback_id)
	if fallback.kind == .block && fallback.children_count == 0 {
		parent_id := tc.direct_parent_id(or_id)
		if tc.valid_node_id(parent_id) && tc.a.node(parent_id).kind == .expr_stmt
			&& tc.is_statement_node(parent_id) {
			return
		}
		tc.record_error_at(.assignment_mismatch, 'expression requires a non empty `or {}` block',
			or_id, tc.or_block_operator_pos(source_id, fallback_id))
		return
	}
	tail_id := tc.branch_tail_expr_id(fallback_id)
	if !tc.valid_node_id(tail_id) {
		return
	}
	tail := tc.a.node(tail_id)
	if tail.kind in [.return_stmt, .break_stmt, .continue_stmt] || tc.expr_never_returns(tail_id) {
		return
	}
	if tail.kind == .assert_stmt && tc.direct_parent_kind(or_id) != .expr_stmt {
		cond_id := if tail.children_count > 0 { tc.a.child(tail, 0) } else { tail_id }
		tc.record_error_at(.assignment_mismatch,
			'last statement in the `or {}` block should be an expression of type `${expected.name()}` or exit parent scope',
			cond_id, token.new_span(tc.a.node(cond_id).pos.id, tc.a.node(cond_id).pos.offset,
			fallback.pos.end))
		return
	}
	if tail.kind == .block && tail.value == 'unsafe' && expected is Pointer
		&& tc.node_contains_nil_literal(tail_id) {
		return
	}
	if tail.kind == .block && expected !is MultiReturn {
		tc.record_error_at(.assignment_mismatch,
			'last statement in the `or {}` block should be an expression of type `${expected.name()}` or exit parent scope',
			tail_id, token.new_span(tail.pos.id, tail.pos.offset, tail.pos.offset + 1))
		return
	}
	if expected is MultiReturn {
		if groups := tc.tuple_tail_value_groups(fallback_id, expected.types.len, false) {
			if groups.len > 0 {
				values := groups[0]
				mut actual_types := []Type{cap: values.len}
				mut compatible := values.len == expected.types.len
				for i, value_id in values {
					actual_type := tc.resolve_type(value_id)
					actual_types << actual_type
					if i >= expected.types.len
						|| !tc.type_compatible(actual_type, expected.types[i]) {
						compatible = false
					}
				}
				if !compatible {
					actual_multi := Type(MultiReturn{
						types: actual_types
					})
					tc.record_error_at(.assignment_mismatch,
						'wrong return type `${actual_multi.name()}` in the `or {}` block, expected `${Type(expected).name()}`',
						values[0], tc.a.node(values[0]).pos)
					return
				}
			}
		}
	}
	mut actual := tc.resolve_type(tail_id)
	if tail.kind == .infix && tail.op == .plus && tail.children_count >= 2 {
		lhs_type := unalias_type(tc.resolve_type(tc.a.child(tail, 0)))
		rhs_type := unalias_type(tc.resolve_type(tc.a.child(tail, 1)))
		if lhs_type is OptionType && !tc.type_compatible(rhs_type, lhs_type.base_type) {
			actual = Type(void_)
		} else if rhs_type is OptionType && !tc.type_compatible(lhs_type, rhs_type.base_type) {
			actual = Type(void_)
		}
	}
	if tc.expr_is_empty_bare_array_literal(tail_id) && array_like_elem_type(expected) != none {
		return
	}
	if expected is Void {
		return
	}
	if tc.or_expr_payload_is_shared(source_id) && !tc.expr_is_explicit_shared_arg(tail_id) {
		actual_name := tc.diagnostic_expr_type_name(tail_id, actual)
		tc.record_error_at(.assignment_mismatch,
			'wrong return type `${actual_name}` in the `or {}` block, expected `shared ${expected.name()}`',
			tail_id, tc.or_fallback_value_pos(tail_id, tail))
		return
	}
	is_strict_numeric_mismatch := actual.is_integer() && expected.is_float()
		&& tail.kind != .int_literal
	if tc.expr_compatible(tail_id, actual, expected) && !is_strict_numeric_mismatch {
		return
	}
	actual_name := if tail.kind == .none_expr {
		'none'
	} else {
		tc.diagnostic_expr_type_name(tail_id, actual)
	}
	expected_name := expected.name()
	parent_kind := tc.direct_parent_kind(or_id)
	source := tc.a.node(source_id)
	if actual is Void && parent_kind == .expr_stmt {
		return
	}
	message := if actual is Void {
		'`or` block must provide a default value of type `${expected_name}`, or return/continue/break or call a @[noreturn] function like panic(err) or exit(1)'
	} else if tail.kind == .none_expr || actual is OptionType || source.kind == .index
		|| parent_kind == .return_stmt {
		'`or` block must provide a value of type `${expected_name}`, not `${actual_name}`'
	} else if parent_kind == .expr_stmt {
		'the default expression type in the `or` block should be `${expected_name}`, instead you gave a value of type `${actual_name}`'
	} else {
		'wrong return type `${actual_name}` in the `or {}` block, expected `${expected_name}`'
	}
	pos := tc.or_fallback_value_pos(tail_id, tail)
	tc.record_error_at(.assignment_mismatch, message, tail_id, pos)
}

fn (tc &TypeChecker) or_expr_payload_is_shared(source_id flat.NodeId) bool {
	source := tc.a.node(source_id)
	if source.kind != .call {
		return false
	}
	name := tc.resolved_call_name(source_id) or { return false }
	raw := trimmed_space(tc.fn_ret_type_texts[name] or { return false })
	payload := if raw.starts_with('?') || raw.starts_with('!') {
		trimmed_space(raw[1..])
	} else {
		raw
	}
	return payload.starts_with('shared ')
}

fn (tc &TypeChecker) or_block_operator_pos(source_id flat.NodeId, fallback_id flat.NodeId) token.Pos {
	source_node := tc.a.node(source_id)
	fallback := tc.a.node(fallback_id)
	file := tc.a.source_files[source_node.pos.id] or { return fallback.pos }
	source := tc.source_texts_by_file[file.name] or { return fallback.pos }
	if source_node.kind == .sql_expr {
		anchor := int_min(int_max(fallback.pos.offset, 0), source.len)
		line_start := if relative := source[..anchor].last_index('\n') {
			relative + 1
		} else {
			0
		}
		line_end := source.index_after('\n', anchor) or { source.len }
		if relative := source[line_start..line_end].index('or {') {
			start := line_start + relative
			return token.new_span(source_node.pos.id, start, start + 4)
		}
	}
	start := int_min(int_max(source_node.pos.end, 0), source.len)
	end := int_min(source.len, int_max(fallback.pos.end, start))
	if start < end {
		if relative := source[start..end].index('or') {
			op_start := start + relative
			if open_relative := source[op_start..end].index('{') {
				mut depth := 0
				for cursor in op_start + open_relative .. end {
					if source[cursor] == `{` {
						depth++
					} else if source[cursor] == `}` {
						depth--
						if depth == 0 {
							return token.new_span(source_node.pos.id, op_start, cursor + 1)
						}
					}
				}
			}
		}
	}
	return fallback.pos
}

fn (tc &TypeChecker) or_fallback_value_pos(id flat.NodeId, node flat.Node) token.Pos {
	if node.kind == .selector {
		return tc.node_value_diagnostic_pos(id)
	}
	if node.kind == .call && node.children_count > 0 {
		callee := tc.a.child_node(&node, 0)
		if callee.kind == .selector {
			name_pos := tc.method_call_name_pos(node, callee)
			return token.new_span(name_pos.id, name_pos.offset, node.pos.end)
		}
	}
	if node.kind == .cast_expr && node.children_count > 0 {
		child := tc.a.child_node(&node, 0)
		file := tc.a.source_files[node.pos.id] or { return node.pos }
		source := tc.source_texts_by_file[file.name] or { return node.pos }
		child_start := int_min(int_max(child.pos.offset, 0), source.len)
		search_start := int_max(0, child_start - node.value.len - 2)
		if relative := source[search_start..child_start].last_index('${node.value}(') {
			mut start := search_start + relative
			if node.value.starts_with('?') || node.value.starts_with('!') {
				start++
			}
			mut end := int_min(source.len, int_max(child.pos.end, child_start))
			for end < source.len && source[end] in [` `, `\t`] {
				end++
			}
			if end < source.len && source[end] == `)` {
				end++
			}
			return token.new_span(node.pos.id, start, end)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) or_expr_payload_type(source_id flat.NodeId) ?Type {
	source := tc.a.node(source_id)
	source_type := unalias_type(tc.resolve_type(source_id))
	if source_type is OptionType {
		return source_type.base_type
	}
	if source_type is ResultType {
		return source_type.base_type
	}
	if source.kind == .selector {
		if declared := tc.selector_declared_value_type(*source) {
			clean_declared := unalias_type(declared)
			if clean_declared is OptionType {
				return clean_declared.base_type
			}
			if clean_declared is ResultType {
				return clean_declared.base_type
			}
		}
	}
	if source.kind == .index && source.children_count > 0 {
		base_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(source, 0)))
		if base_type is Map {
			return base_type.value_type
		}
		if base_type is Array {
			return base_type.elem_type
		}
		if base_type is ArrayFixed {
			return base_type.elem_type
		}
		if base_type is String {
			return Type(u8_)
		}
	}
	return none
}

fn (tc &TypeChecker) direct_parent_kind(id flat.NodeId) flat.NodeKind {
	parent_id := tc.direct_parent_id(id)
	if tc.valid_node_id(parent_id) {
		return tc.a.node(parent_id).kind
	}
	return .empty
}

fn (tc &TypeChecker) direct_parent_id(id flat.NodeId) flat.NodeId {
	for idx, candidate in tc.a.nodes {
		for i in 0 .. candidate.children_count {
			if tc.a.child(&candidate, i) == id {
				return flat.NodeId(idx)
			}
		}
	}
	return flat.empty_node
}

fn (tc &TypeChecker) enclosing_infix_type_for_or_expr(id flat.NodeId) ?Type {
	for idx, candidate in tc.a.nodes {
		if candidate.kind != .infix {
			continue
		}
		for i in 0 .. candidate.children_count {
			if tc.a.child(&candidate, i) == id {
				return tc.resolve_type(flat.NodeId(idx))
			}
		}
	}
	return none
}

fn (tc &TypeChecker) or_expr_source_can_fail(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind in [.paren, .expr_stmt, .or_expr] && node.children_count > 0 {
		return tc.or_expr_source_can_fail(tc.a.child(node, 0))
	}
	if node.kind == .or_expr && node.value in ['!', '?'] && node.children_count > 0 {
		return tc.or_expr_source_can_fail(tc.a.child(node, 0))
	}
	// `none` can adopt an optional context, but it is a value, not an
	// expression whose evaluation can fail.
	if node.kind == .none_expr {
		return false
	}
	if node.kind == .selector {
		if declared := tc.selector_declared_value_type(*node) {
			if type_is_option_or_result(declared) {
				return true
			}
		}
	}
	if node.kind == .infix {
		for i in 0 .. node.children_count {
			if tc.or_expr_source_can_fail(tc.a.child(node, i)) {
				return true
			}
		}
	}
	if node.kind == .index && node.children_count > 0 {
		if node.op == .gated_index {
			return true
		}
		index_type := tc.resolve_type(id)
		if type_is_option_or_result(index_type) || index_type.name().starts_with('?')
			|| index_type.name().starts_with('!') {
			return true
		}
		base_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(node, 0)))
		return base_type is Map || base_type is Array || base_type is ArrayFixed
			|| base_type is String
	}
	if node.kind == .prefix && node.op == .arrow && node.children_count > 0 {
		source_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(node, 0)))
		return source_type is Channel
	}
	if node.kind == .prefix && node.op == .amp && node.children_count > 0 {
		index := tc.a.child_node(node, 0)
		if index.kind == .index && index.children_count > 0 {
			base_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(index, 0)))
			return base_type is Map
		}
	}
	typ := tc.resolve_type(id)
	if type_is_option_or_result(typ) {
		return true
	}
	// Thread payloads are retained in the synthetic `thread T` handle name.
	// When T is optional/result, indexing the joined array can still carry that
	// wrapper spelling even if its semantic type has not been reconstructed yet.
	name := typ.name()
	return name.starts_with('?') || name.starts_with('!')
}

fn type_is_option_or_result(typ Type) bool {
	clean := unalias_type(typ)
	return clean is OptionType || clean is ResultType
}

fn (mut tc TypeChecker) check_sql_expr(id flat.NodeId, node flat.Node) {
	if node.children_count > 0 {
		db_id := tc.a.child(&node, 0)
		tc.check_node(db_id)
		db_type := unalias_type(unwrap_pointer(tc.resolve_type(db_id)))
		if db_type is OptionType {
			tc.record_error_at(.call_arg_mismatch,
				'expected `${db_type.base_type.name()}`, not `?${db_type.base_type.name()}`',
				db_id, tc.a.node(db_id).pos)
		} else if db_type is ResultType {
			tc.record_error_at(.call_arg_mismatch,
				'expected `${db_type.base_type.name()}`, not `!${db_type.base_type.name()}`',
				db_id, tc.a.node(db_id).pos)
		} else {
			db_name := db_type.name()
			if db_name.len > 0 && db_type !is Unknown
				&& !tc.named_type_implements_interface(db_name, 'orm.Connection') {
				for method in tc.interface_abstract_method_names('orm.Connection') {
					tc.record_error_at(.call_arg_mismatch,
						'`${db_name}` doesn\'t implement method `${method}` of interface `orm.Connection`',
						db_id, tc.a.node(db_id).pos)
				}
			}
		}
	}
	tokens := node.value.split(' ')
	tc.check_sql_orm_constraints(id, node, tokens)
	if tokens.len > 0 && tokens[0] == 'dynamic'
		&& tc.check_dynamic_sql_query_data_fields(id, tokens) {
		return
	}
	tc.check_sql_anonymous_struct_fields(tokens)
	tc.check_sql_like_operands(id, node, tokens)
	for i in 0 .. tokens.len {
		op := tokens[i]
		if op !in ['==', '!=', '<', '>', '<=', '>='] || i + 1 >= tokens.len {
			continue
		}
		rhs := tokens[i + 1]
		if rhs == 'none' {
			tc.record_warning_at(.condition_mismatch,
				'comparison with none probably isn\'t intended; use "is none" and "!is none" to select by NULL',
				id, tc.sql_expr_text_pos(node, ' ${op} ', 1, op.len))
			continue
		}
		if rhs_type := tc.cur_scope.lookup(rhs) {
			if unalias_type(rhs_type) is OptionType {
				tc.record_warning_at(.condition_mismatch,
					'comparison with Option value probably isn\'t intended; use "is none" and "!is none" to select by NULL',
					id, tc.sql_expr_text_pos(node, ' ${op} ', 1, op.len))
			}
		}
	}
	for i := 0; i + 3 < tokens.len; i++ {
		if tokens[i + 1] != '.' || tokens[i + 3] !in ['==', '!=', '<', '>', '<=', '>='] {
			continue
		}
		base_name := tokens[i]
		field_name := tokens[i + 2]
		base_type := tc.cur_scope.lookup(base_name) or { continue }
		field_type := tc.sql_struct_field_type(base_type, field_name) or { continue }
		clean_field := unalias_type(field_type)
		if clean_field is OptionType {
			tc.record_error_at(.assignment_mismatch,
				'`?${clean_field.base_type.name()}` cannot be used as `${clean_field.base_type.name()}`, unwrap the option first',
				id, tc.sql_expr_text_pos(node, '${base_name}.${field_name}', base_name.len + 1,
				field_name.len))
		}
	}
}

fn (mut tc TypeChecker) check_sql_orm_constraints(id flat.NodeId, node flat.Node, tokens []string) {
	tc.check_sql_aggregate_constraints(id, node, tokens)
	tc.check_sql_bulk_pointer_arrays(id, node, tokens)
	tc.check_sql_statement_constraints(id, node, tokens)
	for table_name in sql_orm_table_names(tokens) {
		tc.check_sql_orm_table_kind(id, node, table_name)
		tc.check_sql_orm_struct_constraints(id, table_name)
	}
	for i := 0; i + 2 < tokens.len; i++ {
		if tokens[i] != 'select' || tokens[i + 1] != 'from' {
			continue
		}
		table_name := tokens[i + 2]
		decl := tc.source_struct_decl_for_name(table_name) or { continue }
		mut field_count := 0
		for j in 0 .. decl.children_count {
			if tc.a.child_node(&decl, j).kind == .field_decl {
				field_count++
			}
		}
		if field_count == 0 {
			tc.record_error_at(.assignment_mismatch,
				'ORM: select: empty fields in `${table_name}`', id, tc.sql_expr_text_pos(node,
				' ${table_name}', 1, table_name.len))
		}
	}
}

fn (mut tc TypeChecker) check_sql_orm_table_kind(id flat.NodeId, node flat.Node, table_name string) {
	if tc.source_struct_decl_for_name(table_name) != none {
		return
	}
	table_type := unalias_type(tc.parse_type(table_name))
	if table_type is Unknown || table_type is Struct {
		return
	}
	tc.record_sql_error_at(.assignment_mismatch,
		'ORM: the table symbol `${table_name}` has to be a struct', id, tc.sql_expr_text_pos(node,
		' ${table_name}', 1, table_name.len))
}

fn sql_orm_table_names(tokens []string) []string {
	mut names := []string{}
	for i := 0; i + 1 < tokens.len; i++ {
		if tokens[i] !in ['from', 'into', 'update', 'table'] {
			continue
		}
		name := tokens[i + 1]
		if should_check_named_type(name) && name !in names {
			names << name
		}
	}
	return names
}

fn (mut tc TypeChecker) check_sql_orm_struct_constraints(id flat.NodeId, table_name string) {
	decl_id := tc.source_struct_decl_id_for_name(table_name) or { return }
	decl := tc.a.node(decl_id)
	if pos := tc.declaration_attribute_without_value_pos(decl_id, 'table') {
		tc.record_sql_error_at(.assignment_mismatch, 'ORM: table attribute must have an argument',
			id, pos)
		return
	}
	mut fields := []flat.Node{}
	mut has_primary := false
	for i in 0 .. decl.children_count {
		field := tc.a.child_node(decl, i)
		if field.kind != .field_decl || orm_field_is_skipped(field) {
			continue
		}
		fields << field
		if struct_field_has_attr(field, 'primary') {
			has_primary = true
		}
	}
	for field in fields {
		info := sql_orm_field_type_info(field.typ)
		if info.is_multidim {
			tc.record_sql_error_at(.assignment_mismatch,
				'ORM: multi-dimension array fields are not supported', id,
				tc.sql_orm_field_declaration_pos(field))
			return
		}
		if info.base_name.len > 0 && tc.sql_orm_field_is_sub_struct(info.base_name)
			&& tc.sql_orm_struct_reaches(info.base_name, table_name, []string{}) {
			tc.record_sql_error_at(.assignment_mismatch,
				'ORM: invalid recursive struct `${info.base_name.all_after_last('.')}`', id,
				tc.sql_orm_field_declaration_pos(field))
			return
		}
	}
	for field in fields {
		info := sql_orm_field_type_info(field.typ)
		if info.is_array && !struct_field_has_attr(field, 'fkey') {
			tc.record_sql_error_at(.assignment_mismatch,
				'ORM: array fields must have an fkey attribute', id,
				tc.sql_orm_field_declaration_pos(field))
			return
		}
		if info.is_array && !has_primary {
			tc.record_sql_error_at(.assignment_mismatch,
				'ORM: a struct that has a field that holds an array must have a primary key', id,
				tc.sql_orm_field_declaration_pos(field))
			return
		}
		meta := field.generic_params()
		if meta.len > 1 {
			for raw_attr in meta[1..] {
				if raw_attr.trim_space() == 'fkey' {
					tc.record_sql_error_at(.assignment_mismatch,
						'ORM: the `fkey` attribute must have an argument', id, tc.sql_orm_field_attribute_pos(field,
						'fkey'))
					return
				}
			}
		}
		if !info.is_array && tc.sql_orm_field_is_sub_struct(info.base_name) {
			foreign_decl := tc.source_struct_decl_for_name(info.base_name) or { continue }
			mut foreign_has_primary := false
			for i in 0 .. foreign_decl.children_count {
				foreign_field := tc.a.child_node(&foreign_decl, i)
				if foreign_field.kind == .field_decl
					&& struct_field_has_attr(*foreign_field, 'primary') {
					foreign_has_primary = true
					break
				}
			}
			if !foreign_has_primary {
				tc.record_sql_error_at(.assignment_mismatch,
					'ORM: struct `${info.base_name.all_after_last('.')}` used as ORM sub-struct field `${field.value}` must have a `@[primary]` field, or use `@[sql: \'-\']` to skip this field',
					id, tc.sql_orm_field_declaration_pos(field))
				return
			}
		}
	}
}

fn sql_orm_field_type_info(raw_type string) SqlOrmFieldTypeInfo {
	mut clean := trimmed_space(raw_type)
	for clean.starts_with('?') || clean.starts_with('!') || clean.starts_with('&') {
		clean = trimmed_space(clean[1..])
	}
	mut dimensions := 0
	for clean.starts_with('[]') {
		dimensions++
		clean = trimmed_space(clean[2..])
	}
	return SqlOrmFieldTypeInfo{
		base_name:   clean
		is_array:    dimensions > 0
		is_multidim: dimensions > 1
	}
}

fn sql_orm_type_names_match(a string, b string) bool {
	return a == b || a.all_after_last('.') == b.all_after_last('.')
}

fn (tc &TypeChecker) sql_orm_field_is_sub_struct(name string) bool {
	if name == 'time.Time' {
		return false
	}
	return unalias_type(tc.parse_type(name)) is Struct
		&& tc.source_struct_decl_for_name(name) != none
}

fn (tc &TypeChecker) sql_orm_struct_reaches(current string, target string, seen []string) bool {
	if sql_orm_type_names_match(current, target) {
		return true
	}
	if current in seen {
		return false
	}
	decl := tc.source_struct_decl_for_name(current) or { return false }
	mut next_seen := seen.clone()
	next_seen << current
	for i in 0 .. decl.children_count {
		field := tc.a.child_node(&decl, i)
		if field.kind != .field_decl || orm_field_is_skipped(field) {
			continue
		}
		info := sql_orm_field_type_info(field.typ)
		if info.base_name.len == 0 || !tc.sql_orm_field_is_sub_struct(info.base_name) {
			continue
		}
		if tc.sql_orm_struct_reaches(info.base_name, target, next_seen) {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) check_sql_statement_constraints(id flat.NodeId, node flat.Node, tokens []string) {
	tc.check_sql_insert_type(id, node, tokens)
	tc.check_sql_update_fields(id, node, tokens)
	tc.check_sql_where_constraints(id, node, tokens)
	tc.check_sql_limit_constraint(id, node, tokens)
	tc.check_sql_order_by_constraint(id, node, tokens)
}

fn (mut tc TypeChecker) check_sql_insert_type(id flat.NodeId, node flat.Node, tokens []string) {
	for i := 0; i + 3 < tokens.len; i++ {
		if tokens[i] != 'insert' || tokens[i + 2] != 'into' {
			continue
		}
		value_name := tokens[i + 1]
		table_name := tokens[i + 3]
		mut actual := tc.cur_scope.lookup(value_name) or {
			tc.record_sql_error_at(.unknown_ident, 'undefined ident: `${value_name}`', id, tc.sql_expr_text_pos(node,
				'insert ${value_name}', 'insert '.len, value_name.len))
			continue
		}
		clean_actual := unalias_type(actual)
		if clean_actual is Array {
			elem_type := unalias_type(clean_actual.elem_type)
			if elem_type is Pointer {
				continue
			}
			actual = elem_type
		}
		expected := tc.parse_type(table_name)
		if tc.type_compatible(actual, expected) && tc.type_compatible(expected, actual) {
			continue
		}
		tc.record_sql_error_at(.assignment_mismatch,
			'cannot use `${actual.name()}` as `${expected.name()}`', id, tc.sql_expr_text_pos(node,
			'insert ${value_name}', 'insert '.len, value_name.len))
	}
}

fn (mut tc TypeChecker) check_sql_update_fields(id flat.NodeId, node flat.Node, tokens []string) {
	for update_idx := 0; update_idx + 3 < tokens.len; update_idx++ {
		if tokens[update_idx] != 'update' {
			continue
		}
		table_name := tokens[update_idx + 1]
		mut set_idx := -1
		for j in update_idx + 2 .. tokens.len {
			if tokens[j] == 'set' {
				set_idx = j
				break
			}
		}
		if set_idx < 0 {
			continue
		}
		for i := set_idx + 1; i + 1 < tokens.len && tokens[i] != 'where'; i++ {
			if tokens[i + 1] != '=' {
				continue
			}
			field := tc.sql_orm_source_field(table_name, tokens[i]) or { continue }
			if !struct_field_has_attr(field, 'fkey') {
				continue
			}
			tc.record_sql_error_at(.assignment_mismatch,
				'ORM: `${field.value}` is a foreign column of `${table_name}`, it can\'t update here',
				id, tc.sql_expr_text_pos(node, 'update ${table_name}', 'update '.len,
				table_name.len))
			return
		}
	}
}

fn (mut tc TypeChecker) check_sql_where_constraints(id flat.NodeId, node flat.Node, tokens []string) {
	from_idx := tokens.index('from')
	where_idx := tokens.index('where')
	if from_idx < 0 || where_idx < 0 || from_idx + 1 >= tokens.len || where_idx + 1 >= tokens.len {
		return
	}
	table_name := tokens[from_idx + 1]
	mut field_names := []string{}
	if decl := tc.source_struct_decl_for_name(table_name) {
		for i in 0 .. decl.children_count {
			field := tc.a.child_node(&decl, i)
			if field.kind == .field_decl && !orm_field_is_skipped(field) {
				field_names << field.value
			}
		}
	}
	field_names.sort()
	mut has_comparison := false
	for i := where_idx + 1; i + 1 < tokens.len; i++ {
		if tokens[i + 1] !in ['==', '!=', '<', '>', '<=', '>=', 'in', '!in', 'is', '!is'] {
			continue
		}
		has_comparison = true
		if !sql_like_identifier(tokens[i]) || tokens[i] in field_names {
			continue
		}
		if i > where_idx + 1 && tokens[i - 1] !in ['&&', '||', '('] {
			continue
		}
		base := 'ORM: left side of the `${tokens[i + 1]}` expression must be one of the `${table_name}`\'s fields'
		message := util.new_suggestion(tokens[i], field_names).say(base)
		tc.record_sql_error_at(.unknown_field, message, id, tc.sql_expr_text_pos(node,
			' ${tokens[i]} ', 1, tokens[i].len))
		break
	}
	for i := where_idx + 1; i + 2 < tokens.len; i++ {
		op := tokens[i + 1]
		if op !in ['==', '!=', '<', '>', '<=', '>=', 'in', '!in', 'is', '!is'] {
			continue
		}
		rhs := tokens[i + 2]
		if !sql_like_identifier(rhs) {
			continue
		}
		if _ := tc.cur_scope.lookup(rhs) {
			continue
		}
		if rhs in field_names && rhs != tokens[i] {
			tc.record_sql_error_at(.unknown_field,
				'ORM: right side of the `${op}` expression cannot reference another `${table_name}` field; field-to-field comparisons are not supported',
				id, tc.sql_expr_text_pos(node, ' ${rhs}', 1, rhs.len))
		} else {
			tc.record_sql_error_at(.unknown_ident, 'undefined variable: `${rhs}`', id, tc.sql_expr_text_last_pos(node,
				rhs, rhs.len))
		}
		break
	}
	if !has_comparison {
		value := tokens[where_idx + 1]
		tc.record_sql_error_at(.condition_mismatch,
			'ORM: `where` expression must have at least one comparison for filtering rows', id, tc.sql_expr_text_pos(node,
			'where ${value}', 'where '.len, value.len))
	}
	for i := where_idx + 1; i + 1 < tokens.len; i++ {
		fn_name := tokens[i]
		if tokens[i + 1] != '(' || !should_check_named_type(fn_name) {
			continue
		}
		ret_type := tc.sql_orm_fn_return_type(fn_name) or { continue }
		if sql_orm_fn_return_type_is_allowed(ret_type) {
			continue
		}
		call_length := tc.sql_source_call_length(node, fn_name)
		tc.record_sql_error_at(.assignment_mismatch,
			'ORM: function calls must return only primitive types and time.Time, but `${fn_name}` returns `${ret_type.name()}`',
			id, tc.sql_expr_text_pos(node, '${fn_name}(', 0, call_length))
	}
}

fn (mut tc TypeChecker) check_sql_order_by_constraint(id flat.NodeId, node flat.Node, tokens []string) {
	from_idx := tokens.index('from')
	if from_idx < 0 || from_idx + 1 >= tokens.len {
		return
	}
	table_name := tokens[from_idx + 1]
	mut field_names := []string{}
	if decl := tc.source_struct_decl_for_name(table_name) {
		for i in 0 .. decl.children_count {
			field := tc.a.child_node(&decl, i)
			if field.kind == .field_decl && !orm_field_is_skipped(field) {
				field_names << field.value
			}
		}
	}
	field_names.sort()
	for i := from_idx + 2; i + 2 < tokens.len; i++ {
		if tokens[i] != 'order' || tokens[i + 1] != 'by' {
			continue
		}
		field_name := tokens[i + 2]
		if field_name in field_names {
			continue
		}
		message :=
			util.new_suggestion(field_name, field_names).say('ORM: `${table_name}` structure has no field with name `${field_name}`')
		tc.record_sql_error_at(.unknown_field, message, id, tc.sql_expr_text_pos(node,
			'by ${field_name}', 'by '.len, field_name.len))
		tc.mark_invalid_sql_result_void(id)
		return
	}
}

fn (mut tc TypeChecker) mark_invalid_sql_result_void(id flat.NodeId) {
	tc.register_synth_type(id, Type(void_))
	mut result_id := id
	parent_id := tc.direct_parent_id(result_id)
	if tc.valid_node_id(parent_id) && tc.a.node(parent_id).kind == .or_expr {
		tc.register_synth_type(parent_id, Type(void_))
		result_id = parent_id
	}
	assign_id := tc.direct_parent_id(result_id)
	if !tc.valid_node_id(assign_id) {
		return
	}
	assign := tc.a.node(assign_id)
	if assign.kind != .decl_assign {
		return
	}
	for i := 0; i + 1 < assign.children_count; i += 2 {
		lhs := tc.a.child_node(assign, i)
		if tc.a.child(assign, i + 1) == result_id && lhs.kind == .ident && lhs.value != '_' {
			tc.cur_scope.insert(lhs.value, Type(void_))
			return
		}
	}
}

fn (tc &TypeChecker) sql_orm_fn_return_type(name string) ?Type {
	for candidate in [name, tc.qualify_name(name)] {
		if typ := tc.fn_ret_types[candidate] {
			return typ
		}
	}
	return none
}

fn sql_orm_fn_return_type_is_allowed(typ Type) bool {
	clean := unalias_type(typ)
	if clean is OptionType || clean is ResultType || clean is Pointer {
		return false
	}
	return clean is Primitive || clean is String || clean is Char || clean is Rune || clean is ISize
		|| clean is USize || clean is Enum || clean.name() == 'time.Time'
}

fn (mut tc TypeChecker) check_sql_limit_constraint(id flat.NodeId, node flat.Node, tokens []string) {
	for i := 0; i + 1 < tokens.len; i++ {
		if tokens[i] != 'limit' {
			continue
		}
		value := tokens[i + 1]
		limit := tc.const_int_value(value, []string{}) or { continue }
		if limit < 0 {
			tc.record_sql_error_at(.assignment_mismatch,
				'ORM: `limit` must be greater than or equal to zero', id, tc.sql_expr_text_pos(node,
				'limit ${value}', 'limit '.len, value.len))
		}
	}
}

fn (tc &TypeChecker) sql_orm_source_field(table_name string, field_name string) ?flat.Node {
	decl := tc.source_struct_decl_for_name(table_name) or { return none }
	for i in 0 .. decl.children_count {
		field := tc.a.child_node(&decl, i)
		if field.kind == .field_decl && field.value == field_name {
			return *field
		}
	}
	return none
}

fn (mut tc TypeChecker) record_sql_error_at(kind TypeErrorKind, msg string, node flat.NodeId, pos token.Pos) {
	if tc.errors.any(it.msg == msg && it.pos == pos) {
		return
	}
	tc.record_error_at(kind, msg, node, pos)
}

fn (mut tc TypeChecker) check_sql_aggregate_constraints(id flat.NodeId, node flat.Node, tokens []string) {
	for select_idx, token in tokens {
		if token != 'select' {
			continue
		}
		mut aggregate_idx := select_idx + 1
		if aggregate_idx < tokens.len && tokens[aggregate_idx] == 'distinct' {
			aggregate_idx++
		}
		if aggregate_idx >= tokens.len || tokens[aggregate_idx] !in ['sum', 'avg'] {
			continue
		}
		aggregate := tokens[aggregate_idx]
		if aggregate_idx + 1 >= tokens.len || tokens[aggregate_idx + 1] != '(' {
			continue
		}
		mut close_idx := -1
		mut depth := 0
		for i in aggregate_idx + 1 .. tokens.len {
			if tokens[i] == '(' {
				depth++
			} else if tokens[i] == ')' {
				depth--
				if depth == 0 {
					close_idx = i
					break
				}
			}
		}
		if close_idx < 0 {
			continue
		}
		if close_idx != aggregate_idx + 3 || !should_check_named_type(tokens[aggregate_idx + 2]) {
			mut operator := '+'
			for i in aggregate_idx + 2 .. close_idx {
				if tokens[i] in ['+', '-', '*', '/', '%'] {
					operator = tokens[i]
					break
				}
			}
			tc.record_error_at(.assignment_mismatch,
				'ORM aggregate functions only support a single field name argument', id, tc.sql_expr_text_pos(node,
				' ${operator} ', 1, operator.len))
			continue
		}
		field_name := tokens[aggregate_idx + 2]
		mut table_name := ''
		for i in close_idx + 1 .. tokens.len - 1 {
			if tokens[i] == 'from' {
				table_name = tokens[i + 1]
				break
			}
		}
		if table_name.len == 0 {
			continue
		}
		field_type := tc.sql_aggregate_field_type(table_name, field_name) or { continue }
		clean_field := sql_aggregate_base_type(field_type)
		if !clean_field.is_integer() && !clean_field.is_float() {
			tc.record_error_at(.assignment_mismatch,
				'ORM: `${aggregate}` aggregate requires a numeric field', id,
				tc.sql_expr_head_pos(node))
		}
	}
}

fn sql_aggregate_base_type(typ Type) Type {
	if typ is Alias {
		return sql_aggregate_base_type(typ.base_type)
	}
	if typ is OptionType {
		return sql_aggregate_base_type(typ.base_type)
	}
	return typ
}

fn (mut tc TypeChecker) check_sql_bulk_pointer_arrays(id flat.NodeId, node flat.Node, tokens []string) {
	for i := 0; i + 3 < tokens.len; i++ {
		if tokens[i] == 'insert' {
			value_name := tokens[i + 1]
			if tokens[i + 2] != 'into' || !tc.sql_ident_is_pointer_array(value_name) {
				continue
			}
			table_name := tokens[i + 3]
			tc.record_error_at(.assignment_mismatch,
				'ORM: bulk insert currently supports only arrays of `${table_name}` values', id, tc.sql_expr_text_pos(node,
				' ${value_name} ', 1, value_name.len))
		}
		if tokens[i] == 'update' {
			table_name := tokens[i + 1]
			mut value_name := ''
			for j in i + 2 .. tokens.len - 1 {
				if tokens[j + 1] == '.' && tc.sql_ident_is_pointer_array(tokens[j]) {
					value_name = tokens[j]
				}
			}
			if value_name.len > 0 {
				tc.record_error_at(.assignment_mismatch,
					'ORM: bulk update currently supports only arrays of `${table_name}` values',
					id, tc.sql_expr_text_last_pos(node, value_name, value_name.len))
			}
		}
	}
}

fn (tc &TypeChecker) sql_ident_is_pointer_array(name string) bool {
	typ := tc.cur_scope.lookup(name) or { return false }
	clean := unalias_type(typ)
	if clean is Array {
		return unalias_type(clean.elem_type) is Pointer
	}
	return false
}

fn (mut tc TypeChecker) check_sql_like_operands(id flat.NodeId, node flat.Node, tokens []string) {
	mut table_name := ''
	for i in 0 .. tokens.len - 1 {
		if tokens[i] in ['from', 'into', 'update'] {
			table_name = tokens[i + 1]
			break
		}
	}
	table_type := tc.parse_type(table_name)
	for i := 1; i + 1 < tokens.len; i++ {
		if tokens[i] !in ['like', 'ilike'] {
			continue
		}
		lhs := tokens[i - 1]
		rhs := tokens[i + 1]
		lhs_type := tc.sql_like_token_type(lhs, table_type)
		lhs_is_string_field := sql_like_identifier(lhs) && unalias_type(lhs_type) is String
		if !lhs_is_string_field {
			tc.record_error_at(.condition_mismatch,
				'the left operand of the `${tokens[i]}` operator must be an identifier with a string type',
				id, tc.sql_expr_text_pos(node, ' ${lhs} ', 1, lhs.len))
		}
		rhs_type := tc.sql_like_token_type(rhs, table_type)
		if !((rhs.len >= 2 && rhs[0] in [`'`, `"`] && rhs[rhs.len - 1] == rhs[0])
			|| unalias_type(rhs_type) is String) {
			tc.record_error_at(.condition_mismatch,
				'the right operand of the `${tokens[i]}` operator must be a string type', id, tc.sql_expr_text_pos(node,
				' ${rhs}', 1, rhs.len))
		}
		if table_name.len > 0 && !tc.sql_table_has_field(table_type, lhs) {
			tc.record_error_at(.unknown_field,
				'ORM: left side of the `${tokens[i]}` expression must be one of the `${table_name}`\'s fields',
				id, tc.sql_expr_text_pos(node, ' ${lhs} ', 1, lhs.len))
		}
	}
}

fn (tc &TypeChecker) sql_like_token_type(value string, table_type Type) Type {
	if value == 'true' || value == 'false' {
		return Type(bool_)
	}
	if value.len > 0 && value[0].is_digit() {
		return Type(int_)
	}
	if typ := tc.cur_scope.lookup(value) {
		return typ
	}
	return tc.sql_struct_field_type(table_type, value) or { unknown_type('unknown SQL operand') }
}

fn (tc &TypeChecker) sql_table_has_field(table_type Type, name string) bool {
	return tc.sql_struct_field_type(table_type, name) != none
}

fn sql_like_identifier(value string) bool {
	if value.len == 0 || value[0].is_digit() {
		return false
	}
	for ch in value.bytes() {
		if !((ch >= `a` && ch <= `z`) || (ch >= `A` && ch <= `Z`)
			|| (ch >= `0` && ch <= `9`) || ch == `_`) {
			return false
		}
	}
	return true
}

fn (mut tc TypeChecker) check_sql_anonymous_struct_fields(tokens []string) {
	if tokens.len < 2 {
		return
	}
	mut table_name := ''
	for i in 0 .. tokens.len - 1 {
		if tokens[i] in ['table', 'from', 'into', 'update'] {
			table_name = tokens[i + 1]
			break
		}
	}
	if table_name.len == 0 {
		return
	}
	decl := tc.source_struct_decl_for_name(table_name) or { return }
	for i in 0 .. decl.children_count {
		field_id := tc.a.child(&decl, i)
		field := tc.a.node(field_id)
		if field.kind != .field_decl || !is_anonymous_struct_name(field.typ)
			|| orm_field_is_skipped(field) {
			continue
		}
		tc.record_error_at(.assignment_mismatch,
			'ORM: field `${field.value}` uses an anonymous struct type, which ORM does not support; use a named struct, or skip it with `@[skip]` or `@[sql: \'-\']`',
			field_id, tc.struct_field_declaration_pos(field))
	}
}

fn orm_field_is_skipped(field flat.Node) bool {
	meta := field.generic_params()
	if meta.len < 2 {
		return false
	}
	for attr in meta[1..] {
		name := attr.all_before(':').trim_space()
		if name == 'skip' {
			return true
		}
		if name == 'sql' && attr.contains(':') {
			value := attr.all_after(':').trim_space().trim('\'"')
			if value == '-' {
				return true
			}
		}
	}
	return false
}

fn (mut tc TypeChecker) check_dynamic_sql_query_data_fields(id flat.NodeId, tokens []string) bool {
	from_idx := tokens.index('from')
	where_idx := tokens.index('where')
	if from_idx < 0 || where_idx < 0 || from_idx + 1 >= tokens.len || where_idx + 1 >= tokens.len {
		return false
	}
	table_name := tokens[from_idx + 1]
	alias_name := tokens[where_idx + 1]
	mut fields := []StructField{}
	for candidate in [table_name, tc.qualify_name(table_name)] {
		if known := tc.structs[candidate] {
			fields = known.clone()
			break
		}
	}
	if fields.len == 0 {
		return false
	}
	query_id := tc.dynamic_sql_query_data_node(alias_name) or { return false }
	query := tc.a.node(query_id)
	query_tokens := query.value.split(' ')
	mut field_names := fields.map(it.name)
	field_names.sort()
	for i := 0; i + 1 < query_tokens.len; i++ {
		field_name := query_tokens[i]
		if query_tokens[i + 1] !in ['==', '!=', '<', '>', '<=', '>=', 'in', '!in', 'like', 'ilike', 'is', '!is', '=']
			|| !should_check_named_type(field_name) || field_name.contains('.')
			|| field_name in field_names {
			continue
		}
		message :=
			util.new_suggestion(field_name, field_names).say('ORM: `${table_name}` structure has no field with name `${field_name}`')
		tc.record_error_at(.unknown_field, message, id, tc.dynamic_sql_field_pos(query_id,
			field_name))
		return true
	}
	return false
}

fn (tc &TypeChecker) dynamic_sql_query_data_node(alias_name string) ?flat.NodeId {
	for node in tc.a.nodes {
		if node.kind != .decl_assign || node.children_count < 2 {
			continue
		}
		lhs := tc.a.child_node(&node, 0)
		if lhs.kind != .ident || lhs.value != alias_name {
			continue
		}
		rhs_id := tc.a.child(&node, 1)
		rhs := tc.a.node(rhs_id)
		if rhs.kind == .sql_expr && rhs.value.starts_with('querydata ') {
			return rhs_id
		}
	}
	return none
}

fn (tc &TypeChecker) dynamic_sql_field_pos(query_id flat.NodeId, field_name string) token.Pos {
	if !tc.valid_node_id(query_id) {
		return token.Pos{}
	}
	node := tc.a.node(query_id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	if span := closest_identifier_span(source, field_name, node.pos.offset, node.pos.id) {
		return span
	}
	return node.pos
}

fn (tc &TypeChecker) sql_struct_field_type(owner Type, field_name string) ?Type {
	clean := unalias_type(unwrap_pointer(owner))
	name := clean.name()
	for candidate in [name, tc.qualify_name(name)] {
		for field in tc.structs[candidate] or { continue } {
			if field.name == field_name {
				return field.typ
			}
		}
	}
	return none
}

fn (tc &TypeChecker) sql_expr_text_pos(node flat.Node, needle string, relative_start int, length int) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	mut anchor := int_min(int_max(node.pos.offset, 0), source.len)
	if node.children_count > 0 {
		db := tc.a.child_node(&node, 0)
		anchor = int_min(int_max(db.pos.offset, 0), source.len)
	}
	line_start := if relative := source[..anchor].last_index('\n') {
		relative + 1
	} else {
		0
	}
	mut block_end := int_min(int_max(node.pos.end, anchor), source.len)
	if block_end <= anchor {
		block_end = source.index_after('}!', anchor) or { source.len }
	}
	if relative := source[line_start..block_end].index(needle) {
		start := line_start + relative + relative_start
		return token.new_span(node.pos.id, start, start + length)
	}
	return node.pos
}

fn (tc &TypeChecker) sql_orm_field_declaration_pos(field flat.Node) token.Pos {
	file := tc.a.source_files[field.pos.id] or { return field.pos }
	source := tc.source_texts_by_file[file.name] or { return field.pos }
	anchor := int_min(int_max(field.pos.offset, 0), source.len)
	line_start := if relative := source[..anchor].last_index('\n') {
		relative + 1
	} else {
		0
	}
	line_end := source.index_after('\n', anchor) or { source.len }
	line := source[line_start..line_end]
	name_start := line.index(field.value) or { return field.pos }
	type_start := line.index_after(field.typ, name_start + field.value.len) or { return field.pos }
	start := line_start + name_start
	return token.new_span(field.pos.id, start, line_start + type_start + field.typ.len)
}

fn (tc &TypeChecker) sql_orm_field_attribute_pos(field flat.Node, attr_name string) token.Pos {
	file := tc.a.source_files[field.pos.id] or { return field.pos }
	source := tc.source_texts_by_file[file.name] or { return field.pos }
	anchor := int_min(int_max(field.pos.offset, 0), source.len)
	line_start := if relative := source[..anchor].last_index('\n') {
		relative + 1
	} else {
		0
	}
	line_end := source.index_after('\n', anchor) or { source.len }
	line := source[line_start..line_end]
	exact := '@[${attr_name}]'
	if relative := line.index(exact) {
		start := line_start + relative
		return token.new_span(field.pos.id, start, start + exact.len)
	}
	if relative := line.index(attr_name) {
		start := line_start + relative
		return token.new_span(field.pos.id, start, start + attr_name.len)
	}
	return field.pos
}

fn (tc &TypeChecker) sql_source_call_length(node flat.Node, fn_name string) int {
	file := tc.a.source_files[node.pos.id] or { return fn_name.len + 2 }
	source := tc.source_texts_by_file[file.name] or { return fn_name.len + 2 }
	mut anchor := int_min(int_max(node.pos.offset, 0), source.len)
	if node.children_count > 0 {
		db := tc.a.child_node(&node, 0)
		anchor = int_min(int_max(db.pos.offset, 0), source.len)
	}
	mut block_end := int_min(int_max(node.pos.end, anchor), source.len)
	if block_end <= anchor {
		block_end = source.index_after('}!', anchor) or { source.len }
	}
	needle := '${fn_name}('
	relative := source[anchor..block_end].index(needle) or { return fn_name.len + 2 }
	start := anchor + relative
	mut depth := 0
	for i in start + fn_name.len .. block_end {
		if source[i] == `(` {
			depth++
		} else if source[i] == `)` {
			depth--
			if depth == 0 {
				return i - start + 1
			}
		}
	}
	return fn_name.len + 2
}

fn (tc &TypeChecker) sql_expr_head_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	mut anchor := int_min(int_max(node.pos.offset, 0), source.len)
	if node.children_count > 0 {
		db := tc.a.child_node(&node, 0)
		anchor = int_min(int_max(db.pos.offset, 0), source.len)
	}
	line_start := if relative := source[..anchor].last_index('\n') {
		relative + 1
	} else {
		0
	}
	line_end := source.index_after('\n', anchor) or { source.len }
	line := source[line_start..line_end]
	sql_start := line.index('sql ') or { return node.pos }
	sql_head := line[sql_start..]
	brace := sql_head.index('{') or { return node.pos }
	start := line_start + sql_start
	return token.new_span(node.pos.id, start, start + brace + 1)
}

fn (tc &TypeChecker) sql_expr_text_last_pos(node flat.Node, needle string, length int) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	mut anchor := int_min(int_max(node.pos.offset, 0), source.len)
	if node.children_count > 0 {
		db := tc.a.child_node(&node, 0)
		anchor = int_min(int_max(db.pos.offset, 0), source.len)
	}
	line_start := if relative := source[..anchor].last_index('\n') {
		relative + 1
	} else {
		0
	}
	mut block_end := int_min(int_max(node.pos.end, anchor), source.len)
	if block_end <= anchor {
		block_end = source.index_after('}!', anchor) or { source.len }
	}
	if relative := source[line_start..block_end].last_index(needle) {
		start := line_start + relative
		return token.new_span(node.pos.id, start, start + length)
	}
	return node.pos
}

fn (tc &TypeChecker) sql_aggregate_or_expr_type(node flat.Node) ?Type {
	if node.kind != .or_expr || node.value != '!' || node.children_count < 1 {
		return none
	}
	child_id := tc.a.child(&node, 0)
	if int(child_id) < 0 || int(child_id) >= tc.a.nodes.len {
		return none
	}
	child := tc.a.nodes[int(child_id)]
	if child.kind != .sql_expr {
		return none
	}
	tokens := child.value.split(' ')
	for start, token in tokens {
		if token != 'select' {
			continue
		}
		mut select_start := start + 1
		if tokens.len > select_start && tokens[select_start] == 'distinct' {
			select_start++
		}
		if tokens.len <= select_start || tokens[select_start] !in ['sum', 'avg', 'min', 'max'] {
			continue
		}
		if select_start + 5 >= tokens.len || tokens[select_start + 1] != '('
			|| tokens[select_start + 3] != ')' || tokens[select_start + 4] != 'from' {
			continue
		}
		field_name := tokens[select_start + 2]
		table_name := tokens[select_start + 5]
		field_type := tc.sql_aggregate_field_type(table_name, field_name) or { continue }
		return tc.parse_canonical_type(sql_aggregate_optional_type_name(tokens[select_start],
			field_type))
	}
	return none
}

fn (tc &TypeChecker) sql_aggregate_field_type(table_name string, field_name string) ?Type {
	for candidate in [table_name, tc.qualify_name(table_name)] {
		fields := tc.structs[candidate] or { continue }
		for field in fields {
			if field.name == field_name {
				return field.typ
			}
		}
	}
	return none
}

fn sql_aggregate_optional_type_name(aggregate string, field_type Type) string {
	if field_type is OptionType {
		return sql_aggregate_optional_type_name(aggregate, field_type.base_type)
	}
	if field_type is Alias {
		return sql_aggregate_optional_type_name(aggregate, field_type.base_type)
	}
	if aggregate == 'avg' {
		return '?f64'
	}
	if field_type is String {
		return '?string'
	}
	if field_type is Struct && field_type.name == 'time.Time' {
		return '?time.Time'
	}
	if field_type is Primitive && field_type.props.has(.float) {
		return '?f64'
	}
	return '?int'
}

fn (mut tc TypeChecker) check_or_fallback_branch_node(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .block {
		tc.push_scope()
		$if ownership ? {
			tc.ownership_mark_scope_node(id)
		}
		tc.check_statement_sequence(node, 0, true)
		tc.ownership_record_or_fallback_error_return_drops(id)
		tc.pop_scope()
		return
	}
	tc.check_node(id)
	tc.ownership_record_or_fallback_error_return_drops(id)
}

fn (mut tc TypeChecker) ownership_record_or_fallback_error_return_drops(id flat.NodeId) {
	$if ownership ? {
		if tc.fn_context.return_type !is OptionType && tc.fn_context.return_type !is ResultType {
			return
		}
		tail_id := tc.branch_tail_expr_id(id)
		if !tc.branch_tail_is_error_literal(tail_id) {
			return
		}
		tc.ownership_record_propagation_drops()
	}
}

fn (mut tc TypeChecker) check_defer_stmt(node flat.Node) {
	for i in 0 .. node.children_count {
		tc.check_node(tc.a.child(&node, i))
	}
}

fn (mut tc TypeChecker) check_asm_stmt(id flat.NodeId, node flat.Node) {
	if !node.pos.is_valid() {
		return
	}
	file := tc.a.source_files[node.pos.id] or { return }
	source := tc.source_texts_by_file[file.name] or { return }
	start := int_max(0, node.pos.offset)
	end := int_min(source.len, node.pos.end)
	mut line_start := start
	for line_start < end {
		line_end := source.index_after('\n', line_start) or { end }
		content_end := int_min(line_end, end)
		line := source[line_start..content_end].trim_right('\r\n')
		trimmed := line.trim_space()
		if trimmed == 'mov' {
			relative := line.index('mov') or { 0 }
			tc.record_error_at(.assignment_mismatch,
				'asm instruction `mov` expects 2 operands, but got 0', id, token.new_span(node.pos.id,

				line_start + relative, line_start + relative + 'mov'.len))
		}
		if trimmed.starts_with(';') && trimmed.contains('=') {
			open := line.index_u8(`(`)
			close := if open >= 0 { line.index_after(')', open + 1) or { -1 } } else { -1 }
			if open >= 0 && close > open + 1 {
				mut name_start := open + 1
				for name_start < close && line[name_start] in [` `, `\t`] {
					name_start++
				}
				mut name_end := close
				for name_end > name_start && line[name_end - 1] in [` `, `\t`] {
					name_end--
				}
				name := line[name_start..name_end]
				if name.len > 0 && tc.cur_scope.lookup(name) != none
					&& !tc.ident_is_mutable_lvalue(name) {
					tc.record_error_at(.assignment_mismatch,
						'`${name}` is immutable, declare it with `mut` to make it mutable', id, token.new_span(node.pos.id,

						line_start + name_start, line_start + name_end))
				}
			}
		}
		if line_end >= end {
			break
		}
		line_start = line_end + 1
	}
}

// check_fn_literal validates check fn literal state for types.
fn (mut tc TypeChecker) check_fn_literal(id flat.NodeId, node flat.Node) {
	if node.value == 'missing_body' {
		tc.record_error(.return_mismatch, 'anonymous function must declare a body', id)
		return
	}
	mut param_names := map[string]bool{}
	for i in 0 .. node.children_count {
		param_id := tc.a.child(&node, i)
		param := tc.a.node(param_id)
		if param.kind != .param {
			continue
		}
		if param.value.len == 0 {
			tc.record_error_at(.duplicate_decl, 'use `_` to name an unused parameter', param_id,
				param.pos)
			continue
		}
		if param_names[param.value] {
			tc.record_error_at(.duplicate_decl, 'redefinition of parameter `${param.value}`',
				param_id, tc.node_value_diagnostic_pos(param_id))
			continue
		}
		param_names[param.value] = true
		tc.check_import_symbol_conflict(param_id, param.value)
	}
	mut closure_copy_owners := map[string]ScopeBindingOwner{}
	mut explicit_captures := map[string]bool{}
	mut missing_capture_generic := false
	literal_generic_params := node.generic_params()
	for i in 0 .. node.children_count {
		capture := tc.a.child_node(&node, i)
		if capture.kind == .ident && capture.value.len > 0 {
			explicit_captures[capture.value] = true
		}
		if capture.kind == .ident && capture.is_mut && capture.value.len > 0
			&& !tc.ident_is_mutable_lvalue(capture.value) {
			capture_id := tc.a.child(&node, i)
			tc.record_error_at(.assignment_mismatch,
				'original `${capture.value}` is immutable, declare it with `mut` to make it mutable',
				capture_id, tc.node_value_diagnostic_pos(capture_id))
		} else if capture.kind == .ident && !capture.is_mut && capture.value.len > 0 {
			if owner := tc.cur_scope.lookup_owner(capture.value) {
				closure_copy_owners[capture.value] = owner
			}
		}
		if capture.kind == .ident && capture.value.len > 0 {
			if capture_type := tc.cur_scope.lookup(capture.value) {
				if tc.type_has_declaration_attribute(capture_type, 'nocopy') {
					capture_id := tc.a.child(&node, i)
					tc.record_error_at(.assignment_mismatch,
						'cannot capture @[nocopy] struct by value: use a reference instead',
						capture_id, tc.node_value_diagnostic_pos(capture_id))
				}
				capture_type_text := tc.current_fn_param_type_text(capture.value) or {
					capture_type.name()
				}
				for generic_name in tc.fn_context.generic_params {
					if generic_name !in literal_generic_params
						&& type_text_contains_symbol(capture_type_text, generic_name) {
						current_list := literal_generic_params.join(', ')
						_ = current_list
						if !missing_capture_generic {
							tc.record_error_at(.unsupported_generic,
								'generic closure fn must specify type parameter, e.g. fn [foo] [${generic_name}]()',
								id, node.pos)
						}
						missing_capture_generic = true
					}
				}
			}
		}
	}
	if missing_capture_generic {
		tc.check_invalid_fn_literal_generic_calls(node, literal_generic_params)
	}
	mut forbidden_captures := map[string]bool{}
	mut outer_scope := tc.cur_scope
	for outer_scope != unsafe { nil } {
		for name in outer_scope.names {
			qname := tc.qualify_name(name)
			is_global := name in tc.global_names || qname in tc.global_names
			if !is_global && !explicit_captures[name] {
				forbidden_captures[name] = true
			}
		}
		outer_scope = outer_scope.parent
	}
	saved_fn_context := tc.fn_context
	// Keep the enclosing function id so lambda dependencies are attributed to
	// the declaration that owns the generated closure.
	tc.fn_context = new_function_check_context()
	tc.fn_context.node_id = saved_fn_context.node_id
	tc.fn_context.generic_params = saved_fn_context.generic_params.clone()
	tc.fn_context.return_type = tc.parse_type(node.typ)
	tc.fn_context.method_value_locals = saved_fn_context.method_value_locals.clone()
	tc.fn_context.method_value_local_owners =
		clone_scope_binding_owner_map(saved_fn_context.method_value_local_owners)
	tc.fn_context.method_value_local_depth = saved_fn_context.method_value_local_depth.clone()
	tc.fn_context.closure_copy_owners = closure_copy_owners.clone()
	tc.fn_context.closure_forbidden_captures = forbidden_captures.clone()
	tc.fn_context.method_value_stack_mut_owners =
		saved_fn_context.method_value_stack_mut_owners.clone()
	$if ownership ? {
		tc.ownership_begin_fn_literal(id, node)
	}
	tc.push_scope()
	tc.fn_context.closure_scope = tc.cur_scope
	for i in 0 .. node.children_count {
		child := tc.a.child_node(&node, i)
		tc.insert_fn_param_binding(child)
		if child.kind == .ident && child.is_mut && child.value.len > 0 {
			if owner := tc.cur_scope.lookup_owner(child.value) {
				tc.fn_context.mut_local_owners[child.value] = owner
			}
		}
	}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.nodes[int(child_id)]
		if child.kind == .param || child.kind == .ident {
			continue
		}
		tc.check_stmt_node(child_id)
	}
	return_type := unalias_type(tc.parse_type(node.typ))
	if return_type !is Void {
		mut body_start := 0
		for body_start < node.children_count {
			child := tc.a.child_node(&node, body_start)
			if child.kind !in [.param, .ident] {
				break
			}
			body_start++
		}
		if !tc.stmt_sequence_definitely_returns(&node, body_start) {
			tc.record_error_at(.return_mismatch,
				'missing return at the end of an anonymous function', id, node.pos)
		}
	}
	for i in 0 .. node.children_count {
		capture_id := tc.a.child(&node, i)
		capture := tc.a.node(capture_id)
		capture_type_text := tc.current_fn_param_type_text(capture.value) or { '' }
		capture_has_open_generic :=
			saved_fn_context.generic_params.any(type_text_contains_symbol(capture_type_text, it))
		if capture.kind == .ident && capture.value.len > 0 && !capture_has_open_generic
			&& !tc.fn_literal_body_uses_ident(node, capture.value) {
			tc.record_notice_at(.unknown_ident, 'unused parameter: `${capture.value}`', capture_id,
				tc.node_value_diagnostic_pos(capture_id))
		}
	}
	for i in 0 .. node.children_count {
		param_id := tc.a.child(&node, i)
		param := tc.a.node(param_id)
		if param.kind == .param && param.value.len == 0 && param.typ.len > 0
			&& should_check_named_type(param.typ) && !tc.type_name_known(param.typ) {
			tc.record_error_at(.unknown_type, 'unknown type `${param.typ}`', param_id, param.pos)
			tc.record_malformed_fn_literal_call_mismatch(node, param_id, param)
		}
	}
	tc.pop_scope()
	$if ownership ? {
		tc.ownership_end_fn()
	}
	tc.fn_context = saved_fn_context
}

fn (tc &TypeChecker) fn_literal_body_uses_ident(node flat.Node, name string) bool {
	mut stack := []flat.NodeId{}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		if tc.a.node(child_id).kind !in [.param, .ident] {
			stack << child_id
		}
	}
	for stack.len > 0 {
		id := stack.pop()
		child := tc.a.node(id)
		if child.kind == .ident && child.value == name {
			return true
		}
		for i in 0 .. child.children_count {
			stack << tc.a.child(child, i)
		}
	}
	return false
}

fn (mut tc TypeChecker) check_invalid_fn_literal_generic_calls(node flat.Node, generic_params []string) {
	if generic_params.len == 0 || !node.pos.is_valid() {
		return
	}
	file := tc.a.source_files[node.pos.id] or { return }
	source := tc.source_texts_by_file[file.name] or { return }
	start := int_max(0, int_min(node.pos.offset, source.len))
	end := int_max(start, int_min(node.pos.end, source.len))
	literal_source := source[start..end]
	for generic_name in generic_params {
		needle := '[${generic_name}]'
		mut search_start := 0
		for search_start < literal_source.len {
			relative := literal_source[search_start..].index(needle) or { break }
			index := search_start + relative
			mut name_start := index
			for name_start > 0 && literal_source[name_start - 1] in [` `, `\t`] {
				name_start--
			}
			mut name_end := name_start
			for name_start > 0 && is_type_symbol_byte(literal_source[name_start - 1]) {
				name_start--
			}
			call_name := literal_source[name_start..name_end]
			if call_name.len > 0 {
				decl_module := tc.fn_type_modules[call_name] or { tc.cur_module }
				if decl := tc.visible_mutation_fn_decl(call_name, decl_module) {
					if tc.record_invalid_comptime_for_type(decl, generic_name) {
						return
					}
				}
			}
			search_start = index + needle.len
		}
	}
}

fn (mut tc TypeChecker) record_invalid_comptime_for_type(decl VisibleMutationFnDecl, generic_name string) bool {
	if decl.idx < 0 || decl.idx >= tc.a.nodes.len {
		return false
	}
	mut stack := [flat.NodeId(decl.idx)]
	for stack.len > 0 {
		id := stack.pop()
		node := tc.a.node(id)
		if node.kind == .comptime_for && node.typ.len > 0 {
			file := tc.a.source_files[node.pos.id] or { return false }
			source := tc.source_texts_by_file[file.name] or { return false }
			start := int_max(0, int_min(node.pos.offset, source.len))
			end := int_max(start, int_min(node.pos.end, source.len))
			relative := source[start..end].index('${node.typ}.') or { -1 }
			pos := if relative >= 0 {
				token.new_span(node.pos.id, start + relative, start + relative + node.typ.len)
			} else {
				node.pos
			}
			tc.record_error_at(.unknown_type,
				'$for expects a type name or variable name to be used here, but ${generic_name} is not a type or variable name',
				id, pos)
			return true
		}
		for i in 0 .. node.children_count {
			stack << tc.a.child(node, i)
		}
	}
	return false
}

fn (tc &TypeChecker) current_fn_param_type_text(name string) ?string {
	fn_id := flat.NodeId(tc.fn_context.node_id)
	if !tc.valid_node_id(fn_id) {
		return none
	}
	fn_node := tc.a.node(fn_id)
	for i in 0 .. fn_node.children_count {
		param := tc.a.child_node(fn_node, i)
		if param.kind == .param && param.value == name {
			return param.typ
		}
	}
	return none
}

fn (mut tc TypeChecker) record_malformed_fn_literal_call_mismatch(literal flat.Node, param_id flat.NodeId, param flat.Node) {
	if !literal.pos.is_valid() || param.typ.len == 0 {
		return
	}
	file := tc.a.source_files[literal.pos.id] or { return }
	source := tc.source_texts_by_file[file.name] or { return }
	literal_start := int_max(0, int_min(literal.pos.offset, source.len))
	literal_end := int_max(literal_start, int_min(literal.pos.end, source.len))
	before := source[..literal_start]
	assign := before.last_index(':=') or { return }
	mut name_end := assign
	for name_end > 0 && before[name_end - 1] in [` `, `\t`] {
		name_end--
	}
	mut name_start := name_end
	for name_start > 0 && is_type_symbol_byte(before[name_start - 1]) {
		name_start--
	}
	name := before[name_start..name_end]
	if name.len == 0 {
		return
	}
	relative_call := source[literal_end..].index('${name}(') or { return }
	call_start := literal_end + relative_call
	arg_start_raw := call_start + name.len + 1
	close := source.index_after(')', arg_start_raw) or { return }
	mut arg_start := arg_start_raw
	for arg_start < close && source[arg_start] in [` `, `\t`] {
		arg_start++
	}
	mut arg_end := close
	for arg_end > arg_start && source[arg_end - 1] in [` `, `\t`] {
		arg_end--
	}
	if arg_start >= arg_end || source[arg_start..arg_end].contains(',') {
		return
	}
	arg_name := source[arg_start..arg_end]
	actual := tc.cur_scope.lookup(arg_name) or { return }
	tc.record_error_at(.call_arg_mismatch,
		'cannot use `${actual.name()}` as `${param.typ}` in argument 1 to `${name}`', param_id, token.new_span(literal.pos.id,
		arg_start, arg_end))
}

// check_lambda_expr validates check lambda expr state for types.
fn (mut tc TypeChecker) check_lambda_expr(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	if tc.lambda_is_uncontextualized_if_branch_value(id) {
		tc.record_error_at(.call_arg_mismatch,
			'lambda expressions are allowed only in places expecting function callbacks', id,
			node.pos)
	}
	expected_fn := tc.lambda_expected_fn_type(id)
	mut forbidden_captures := map[string]bool{}
	if tc.checker_fixture_mode {
		mut outer_scope := tc.cur_scope
		for outer_scope != unsafe { nil } {
			for name in outer_scope.names {
				qname := tc.qualify_name(name)
				if name !in tc.global_names && qname !in tc.global_names {
					forbidden_captures[name] = true
				}
			}
			outer_scope = outer_scope.parent
		}
	}
	saved_fn_context := tc.fn_context
	tc.fn_context = new_function_check_context()
	tc.fn_context.node_id = saved_fn_context.node_id
	tc.fn_context.generic_params = saved_fn_context.generic_params.clone()
	tc.fn_context.return_type = expected_fn.return_type
	tc.fn_context.method_value_locals = saved_fn_context.method_value_locals.clone()
	tc.fn_context.method_value_local_owners =
		clone_scope_binding_owner_map(saved_fn_context.method_value_local_owners)
	tc.fn_context.method_value_local_depth = saved_fn_context.method_value_local_depth.clone()
	tc.fn_context.method_value_stack_mut_owners =
		saved_fn_context.method_value_stack_mut_owners.clone()
	tc.fn_context.closure_forbidden_captures = forbidden_captures.clone()
	tc.fn_context.lambda_no_captures = tc.checker_fixture_mode
	$if ownership ? {
		tc.ownership_begin_lambda_expr(id, node)
	}
	tc.push_scope()
	for i in 0 .. node.children_count - 1 {
		child := tc.a.child_node(&node, i)
		if child.kind == .ident && child.value.len > 0 {
			param_type := if i < expected_fn.params.len {
				fn_param_type(expected_fn, i)
			} else {
				unknown_type('lambda parameter `${child.value}`')
			}
			owner := tc.cur_scope.insert_with_owner(child.value, param_type)
			if child.is_mut {
				tc.fn_context.mut_param_base_types[child.value] = mut_param_base_type(param_type)
				tc.fn_context.mut_param_owners[child.value] = owner
			}
		}
	}
	tc.fn_context.closure_scope = tc.cur_scope
	body_id := tc.a.child(&node, node.children_count - 1)
	if expected_fn.return_type !is Unknown {
		tc.check_node_with_expected_context(body_id, expected_fn.return_type)
	} else {
		tc.check_node(body_id)
	}
	if invalid_name := tc.lambda_invalid_value_name(body_id) {
		tc.record_error_at(.return_mismatch, '`${invalid_name}` used as value', id, node.pos)
	}
	body := tc.a.node(body_id)
	body_type := if body.kind == .call {
		callee := tc.a.child_node(body, 0)
		if callee.kind == .ident {
			if call_name := tc.local_bare_fn_key(callee.value) {
				tc.fn_ret_types[call_name] or { tc.resolve_type(body_id) }
			} else {
				tc.resolve_type(body_id)
			}
		} else if call_name := tc.resolved_call_name(body_id) {
			tc.fn_ret_types[call_name] or { tc.resolve_type(body_id) }
		} else {
			tc.resolve_type(body_id)
		}
	} else {
		tc.resolve_type(body_id)
	}
	if (body_type is OptionType || body_type is ResultType)
		&& expected_fn.return_type !is OptionType && expected_fn.return_type !is ResultType
		&& !tc.type_compatible(body_type, expected_fn.return_type) {
		tc.record_error_at(.return_mismatch,
			'cannot use `${body_type.name()}` as type `${expected_fn.return_type.name()}` in return argument',
			body_id, tc.a.node(body_id).pos)
	}
	tc.pop_scope()
	$if ownership ? {
		tc.ownership_end_fn()
	}
	tc.fn_context = saved_fn_context
}

fn (tc &TypeChecker) lambda_invalid_value_name(id flat.NodeId) ?string {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .ident && tc.errors.any(it.node == id && it.kind == .unknown_ident
		&& (it.msg.starts_with('undefined ident')
		|| it.msg.starts_with('undefined variable'))) {
		return node.value
	}
	for i in 0 .. node.children_count {
		if name := tc.lambda_invalid_value_name(tc.a.child(node, i)) {
			return name
		}
	}
	return none
}

fn (tc &TypeChecker) lambda_is_uncontextualized_if_branch_value(id flat.NodeId) bool {
	mut branch_id := tc.direct_parent_id(id)
	if !tc.valid_node_id(branch_id) {
		return false
	}
	mut branch := tc.a.node(branch_id)
	if branch.kind == .expr_stmt {
		branch_id = tc.direct_parent_id(branch_id)
		if !tc.valid_node_id(branch_id) {
			return false
		}
		branch = tc.a.node(branch_id)
	}
	if branch.kind != .block {
		return false
	}
	if_id := tc.direct_parent_id(branch_id)
	if !tc.valid_node_id(if_id) {
		return false
	}
	if_node := tc.a.node(if_id)
	return if_node.kind == .if_expr && if_node.children_count > 1
		&& tc.a.child(if_node, 1) == branch_id
}

fn (mut tc TypeChecker) lambda_expected_fn_type(id flat.NodeId) FnType {
	if expected := tc.expected_context_for_expr(id) {
		if fn_typ := fn_type_from_type(expected) {
			return fn_typ
		}
	}
	parent_id := tc.direct_parent_id(id)
	if tc.valid_node_id(parent_id) {
		parent := tc.a.node(parent_id)
		if parent.kind == .call {
			if info := tc.resolve_call_info(parent_id, *parent) {
				for i in 1 .. parent.children_count {
					if tc.call_arg_value(tc.a.child(parent, i)) != id {
						continue
					}
					param_idx := i - 1 + if info.has_receiver { 1 } else { 0 }
					if param_idx >= 0 && param_idx < info.params.len {
						if fn_typ := fn_type_from_type(info.params[param_idx]) {
							return fn_typ
						}
					}
				}
			}
		}
	}
	return FnType{
		return_type: unknown_type('unknown lambda return type')
	}
}

// check_block validates check block state for types.
fn (mut tc TypeChecker) check_block(id flat.NodeId, node flat.Node) {
	tc.push_scope()
	is_unsafe := node.value == 'unsafe'
	if is_unsafe {
		tc.unsafe_depth++
	}
	$if ownership ? {
		tc.ownership_mark_scope_node(id)
	}
	if node.value == 'comma_exprs' {
		if tc.is_statement_node(id) {
			for i in 0 .. node.children_count {
				mut value_id := tc.a.child(&node, i)
				value := tc.a.node(value_id)
				if value.kind == .expr_stmt && value.children_count > 0 {
					value_id = tc.a.child(value, 0)
				}
				if unalias_type(tc.resolve_type(value_id)) is Void {
					tc.record_error_at(.return_mismatch,
						'type `void` cannot be used in multi-return', value_id,
						tc.a.node(value_id).pos)
					break
				}
			}
		}
		for i in 0 .. node.children_count {
			tc.check_node(tc.a.child(&node, i))
		}
	} else {
		tc.check_statement_sequence(node, 0, is_unsafe && !tc.is_statement_node(id))
	}
	if is_unsafe && tc.unsafe_depth > 0 {
		tc.unsafe_depth--
	}
	tc.pop_scope()
}

// check_for_stmt validates check for stmt state for types.
fn (mut tc TypeChecker) check_for_stmt(node flat.Node) {
	tc.push_scope()
	$if ownership ? {
		if node.children_count > 0 {
			init_id := tc.a.child(&node, 0)
			if int(init_id) >= 0 && tc.a.nodes[int(init_id)].kind != .empty {
				tc.ownership_mark_scope_node(init_id)
			}
		}
	}
	if node.children_count > 0 {
		init_id := tc.a.child(&node, 0)
		if int(init_id) >= 0 {
			tc.check_node(init_id)
		}
	}
	if node.children_count > 1 {
		cond_id := tc.a.child(&node, 1)
		if int(cond_id) >= 0 {
			tc.check_for_condition(cond_id, node)
		}
	}
	mut saved_smartcasts := map[string]Type{}
	mut has_cond_smartcasts := false
	if node.children_count > 1 {
		cond_id := tc.a.child(&node, 1)
		smartcasts := tc.extract_smartcasts(cond_id)
		if smartcasts.len > 0 {
			saved_smartcasts = clone_smartcasts(tc.smartcasts)
			has_cond_smartcasts = true
			for sc in smartcasts {
				if valid_string_data(sc.name) {
					tc.smartcasts[sc.name] = sc.typ
				}
			}
		}
	}
	$if ownership ? {
		if node.children_count > 2 {
			post_id := tc.a.child(&node, 2)
			if int(post_id) >= 0 {
				if has_cond_smartcasts {
					body_smartcasts := clone_smartcasts(tc.smartcasts)
					tc.smartcasts = clone_smartcasts(saved_smartcasts)
					tc.ownership_begin_suppressed_checks()
					tc.check_node(post_id)
					tc.ownership_end_suppressed_checks()
					tc.smartcasts = clone_smartcasts(body_smartcasts)
				} else {
					tc.ownership_begin_suppressed_checks()
					tc.check_node(post_id)
					tc.ownership_end_suppressed_checks()
				}
			}
		}
		tc.ownership_begin_loop_branch_group()
	} $else {
		if node.children_count > 2 {
			post_id := tc.a.child(&node, 2)
			if int(post_id) >= 0 {
				if has_cond_smartcasts {
					body_smartcasts := clone_smartcasts(tc.smartcasts)
					tc.smartcasts = clone_smartcasts(saved_smartcasts)
					tc.check_node(post_id)
					tc.smartcasts = clone_smartcasts(body_smartcasts)
				} else {
					tc.check_node(post_id)
				}
			}
		}
	}
	mut sequence_exited := false
	mut unreachable_id := flat.empty_node
	for i in 3 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind == .label_stmt {
			sequence_exited = false
			unreachable_id = flat.empty_node
		} else if sequence_exited && !tc.valid_node_id(unreachable_id) {
			unreachable_id = child_id
		}
		tc.check_stmt_node(child_id)
		if tc.statement_exits_sequence(child_id, child) {
			sequence_exited = true
		}
	}
	if tc.valid_node_id(unreachable_id) && tc.should_diagnose(unreachable_id) {
		tc.record_error_at(.return_mismatch, 'unreachable code', unreachable_id,
			tc.unreachable_statement_diagnostic_pos(unreachable_id))
	}
	$if ownership ? {
		loop_may_skip_body := node.children_count > 1 && tc.a.child_node(&node, 1).kind != .empty
		body_reaches_post := tc.ownership_statement_sequence_can_reach_loop_post(node, 3)
		if node.children_count > 2 {
			post_id := tc.a.child(&node, 2)
			if int(post_id) >= 0 {
				post_frame := tc.ownership_snapshot_frame()
				tc.check_node(post_id)
				if !body_reaches_post {
					tc.ownership_restore_frame(post_frame)
				}
			}
			tc.ownership_apply_loop_continue_snapshots(post_id)
		} else {
			tc.ownership_merge_loop_continue_snapshots()
		}
		tc.ownership_record_current_loop_iteration_drops()
		if body_reaches_post {
			tc.ownership_end_loop_branch(node, 3)
		}
		if loop_may_skip_body {
			tc.ownership_add_branch_group_base()
		}
		tc.ownership_end_branch_group()
	}
	if has_cond_smartcasts {
		tc.smartcasts = clone_smartcasts(saved_smartcasts)
	}
	tc.pop_scope()
}

fn (mut tc TypeChecker) check_lock_expr(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	if tc.lock_depth > 0 {
		tc.record_error_at(.assignment_mismatch, 'nested `lock`/`rlock` not allowed', id,
			tc.lock_keyword_diagnostic_pos(node))
	}
	mut locked_names := []string{}
	for i in 0 .. node.children_count - 1 {
		object_id := tc.a.child(&node, i)
		object := tc.a.node(object_id)
		mode := tc.lock_object_mode(node, i)
		tc.check_node(object_id)
		if !tc.expr_is_shared_arg(object_id) {
			object_type := if object.kind == .ident { 'variable' } else { 'struct element' }
			tc.record_error_at(.assignment_mismatch,
				'`${tc.source_text_for_node(object_id)}` must be declared as `shared` ${object_type} to be locked',
				object_id, object.pos)
		}
		if object.kind == .ident && object.value.len > 0 {
			existing_modes := tc.fn_context.locked_shared_modes[object.value] or { []u8{} }
			if existing_modes.len > 0 {
				message := if existing_modes.last() == `r` {
					'`${object.value}` is already read-locked'
				} else {
					'`${object.value}` is already locked'
				}
				tc.record_error_at(.assignment_mismatch, message, object_id,
					tc.node_value_diagnostic_pos(object_id))
			}
			mut modes := existing_modes.clone()
			modes << mode
			tc.fn_context.locked_shared_modes[object.value] = modes
			tc.fn_context.locked_shared_names[object.value]++
			locked_names << object.value
		}
	}
	tc.lock_depth++
	tc.check_stmt_node(tc.a.child(&node, node.children_count - 1))
	tc.lock_depth--
	for name in locked_names {
		tc.fn_context.locked_shared_names[name]--
		mut modes := (tc.fn_context.locked_shared_modes[name] or { []u8{} }).clone()
		if modes.len > 0 {
			modes.delete_last()
		}
		if modes.len == 0 {
			tc.fn_context.locked_shared_modes.delete(name)
		} else {
			tc.fn_context.locked_shared_modes[name] = modes
		}
	}
}

fn (tc &TypeChecker) lock_object_mode(node flat.Node, index int) u8 {
	if node.value == 'rlock' {
		return `r`
	}
	if node.value.starts_with('lock_modes:') {
		modes := node.value['lock_modes:'.len..]
		if index < modes.len {
			return modes[index]
		}
	}
	return `w`
}

fn (tc &TypeChecker) lock_keyword_diagnostic_pos(node flat.Node) token.Pos {
	if node.children_count == 0 {
		return node.pos
	}
	object := tc.a.child_node(&node, 0)
	file := tc.a.source_files[object.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	line_start := if relative := source[..int_min(object.pos.offset, source.len)].last_index('\n') {
		relative + 1
	} else {
		0
	}
	keyword := if node.value == 'rlock' { 'rlock' } else { 'lock' }
	if relative := source[line_start..int_min(object.pos.offset, source.len)].last_index(keyword) {
		start := line_start + relative
		return token.new_span(object.pos.id, start, start + keyword.len)
	}
	return node.pos
}

// check_for_in_stmt validates check for in stmt state for types.
fn (mut tc TypeChecker) check_for_in_stmt(node flat.Node) {
	header := node.value.int()
	if header < 3 || node.children_count < 3 {
		return
	}
	tc.push_scope()
	key_id := tc.a.child(&node, 0)
	val_id := tc.a.child(&node, 1)
	container_id := tc.a.child(&node, 2)
	has_val := int(val_id) >= 0
	key_conflicts := tc.check_loop_var_const_conflict(key_id)
	mut val_conflicts := false
	if has_val {
		val_conflicts = tc.check_loop_var_const_conflict(val_id)
	}
	if key_conflicts || val_conflicts {
		tc.pop_scope()
		return
	}
	tc.check_for_in_binding_name(key_id, if has_val { 'key' } else { 'value' })
	if has_val {
		tc.check_for_in_binding_name(val_id, 'value')
	}
	same_low, same_high := tc.check_for_in_same_variable(header, key_id, val_id, container_id, if header == 4 {
		tc.a.child(&node, 3)
	} else {
		flat.NodeId(-1)
	})
	if !same_low && !(header == 3 && same_high) {
		tc.check_node(container_id)
	}
	container_node := tc.a.node(container_id)
	if header == 3 && container_node.kind == .range && container_node.children_count >= 2 {
		tc.check_for_in_range_types(tc.a.child(container_node, 0), tc.a.child(container_node, 1))
	}
	if header == 4 {
		range_end_id := tc.a.child(&node, 3)
		if !same_high {
			tc.check_node(range_end_id)
		}
		tc.check_for_in_range_types(container_id, range_end_id)
		tc.insert_loop_var(key_id, tc.range_loop_var_type(container_id))
	} else {
		raw_container_type := unalias_type(unwrap_pointer(tc.resolve_type(container_id)))
		raw_container_name := tc.resolve_type(container_id).name()
		mut clean := tc.for_in_iterable_type(container_id)
		if raw_container_type is ResultType {
			pos := token.new_span(container_node.pos.id, container_node.pos.offset + 3,

				container_node.pos.offset + 10)
			tc.record_error_at(.cannot_index, 'for in: cannot index `${raw_container_name}`',
				container_id, pos)
			clean = unalias_type(unwrap_pointer(raw_container_type.base_type))
		} else if raw_container_type is OptionType {
			tc.record_error_at(.cannot_index, 'for in: cannot index `${raw_container_name}`',
				container_id, container_node.pos)
			clean = unalias_type(unwrap_pointer(raw_container_type.base_type))
		}
		yields_ref := node.op == .amp || tc.for_in_iterable_yields_ref(container_id)
		if same_low && container_node.kind == .range {
			tc.insert_loop_var(key_id, Type(int_))
		} else if same_low {
			if has_val {
				tc.record_error_at(.cannot_index, 'for in: cannot index `int`', container_id,
					tc.node_value_diagnostic_pos(container_id))
				tc.insert_loop_var(key_id, Type(int_))
				tc.insert_loop_var(val_id, Type(void_))
			} else {
				tc.insert_loop_var(key_id, Type(void_))
			}
		} else if clean is Array {
			tc.check_for_in_mutable_container(node, key_id, val_id, container_id, clean)
			elem_type := for_in_ref_binding_type(clean.elem_type, yields_ref)
			if has_val {
				tc.insert_loop_var(key_id, Type(int_))
				if node.op == .amp {
					tc.insert_mut_loop_var(val_id, elem_type)
				} else {
					tc.insert_loop_var(val_id, elem_type)
				}
			} else {
				if node.op == .amp {
					tc.insert_mut_loop_var(key_id, elem_type)
				} else {
					tc.insert_loop_var(key_id, elem_type)
				}
			}
		} else if clean is ArrayFixed {
			tc.check_for_in_mutable_container(node, key_id, val_id, container_id, clean)
			elem_type := for_in_ref_binding_type(clean.elem_type, yields_ref)
			if has_val {
				tc.insert_loop_var(key_id, Type(int_))
				if node.op == .amp {
					tc.insert_mut_loop_var(val_id, elem_type)
				} else {
					tc.insert_loop_var(val_id, elem_type)
				}
			} else {
				if node.op == .amp {
					tc.insert_mut_loop_var(key_id, elem_type)
				} else {
					tc.insert_loop_var(key_id, elem_type)
				}
			}
		} else if clean is Map {
			tc.check_for_in_mutable_container(node, key_id, val_id, container_id, clean)
			if !has_val {
				tc.record_error_at(.cannot_index,
					'declare a key and a value variable when ranging a map: `for key, val in map {`\nuse `_` if you do not need the variable',
					key_id, tc.node_value_diagnostic_pos(key_id))
			}
			value_type := for_in_ref_binding_type(clean.value_type, yields_ref)
			if has_val {
				tc.insert_loop_var(key_id, clean.key_type)
				if node.op == .amp {
					tc.insert_mut_loop_var(val_id, value_type)
				} else {
					tc.insert_loop_var(val_id, value_type)
				}
			} else {
				if node.op == .amp {
					tc.insert_mut_loop_var(key_id, value_type)
				} else {
					tc.insert_loop_var(key_id, value_type)
				}
			}
		} else if clean is String {
			tc.check_for_in_mutable_container(node, key_id, val_id, container_id, clean)
			if has_val {
				tc.insert_loop_var(key_id, Type(int_))
				tc.insert_loop_var(val_id, Type(u8_))
			} else {
				tc.insert_loop_var(key_id, Type(u8_))
			}
		} else if generic_name := tc.iterator_unbounded_next_generic(clean) {
			tc.record_error_with_details_at(.cannot_index,
				'cannot infer from generic type `${generic_name}`', key_id,
				tc.node_value_diagnostic_pos(key_id), [
				'type parameters defined by `next()` method should be bounded by method owner type',
			])
			if has_val {
				tc.insert_loop_var(key_id, Type(int_))
				tc.insert_loop_var(val_id, unknown_type('unbounded iterator generic'))
			} else {
				tc.insert_loop_var(key_id, unknown_type('unbounded iterator generic'))
			}
		} else if elem_type := tc.iterator_for_in_elem_type(clean) {
			if unalias_type(elem_type) is MultiReturn {
				tc.record_error_at(.cannot_index,
					'iterator method `next()` must not return multiple values', container_id,
					container_node.pos)
			}
			if has_val {
				tc.insert_loop_var(key_id, Type(int_))
				tc.insert_loop_var(val_id, elem_type)
			} else {
				tc.insert_loop_var(key_id, elem_type)
			}
		} else {
			container := tc.a.nodes[int(container_id)]
			if container.kind == .range {
				if same_low || same_high {
					tc.insert_loop_var(key_id, Type(int_))
				} else {
					tc.insert_loop_var(key_id, tc.range_loop_var_type(tc.a.child(&container, 0)))
				}
			} else if clean is Unknown && tc.expr_subtree_has_error(container_id) {
				if has_val {
					if container.kind == .selector {
						tc.record_for_in_invalid_selector(container_id, container)
					}
					tc.insert_loop_var(key_id, Type(int_))
					if node.op == .amp {
						tc.insert_mut_loop_var(val_id, Type(void_))
					} else {
						tc.insert_loop_var(val_id, Type(void_))
					}
				} else {
					tc.insert_loop_var(key_id, Type(void_))
				}
			} else if tc.should_diagnose(container_id) {
				type_name := if container.kind == .int_literal {
					'int literal'
				} else {
					clean.name()
				}
				tc.record_error(.cannot_index, 'for in: cannot index `${type_name}`', container_id)
				if has_val {
					tc.insert_loop_var(key_id, Type(int_))
					if node.op == .amp {
						tc.insert_mut_loop_var(val_id, Type(void_))
					} else {
						tc.insert_loop_var(val_id, Type(void_))
					}
				} else {
					tc.insert_loop_var(key_id, Type(void_))
				}
			}
		}
		$if ownership ? {
			if node.op != .amp {
				tc.check_for_in_binding_clones(clean, key_id, val_id, has_val)
			}
			if clean is Map && tc.for_in_body_contains_map_delete(node, header, container_id) {
				tc.check_map_delete_snapshot_clones(clean, container_id)
			}
		}
	}
	$if ownership ? {
		tc.ownership_begin_loop_branch_group()
		if node.op != .amp {
			tc.ownership_bind_for_in_vars(key_id, val_id, container_id, has_val)
		} else {
			tc.ownership_bind_mut_for_in_var(key_id, val_id, container_id, has_val)
		}
	}
	mut sequence_exited := false
	mut unreachable_id := flat.empty_node
	for i in header .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind == .label_stmt {
			sequence_exited = false
			unreachable_id = flat.empty_node
		} else if sequence_exited && !tc.valid_node_id(unreachable_id) {
			unreachable_id = child_id
		}
		tc.check_stmt_node(child_id)
		if tc.statement_exits_sequence(child_id, child) {
			sequence_exited = true
		}
	}
	if tc.valid_node_id(unreachable_id) && tc.should_diagnose(unreachable_id) {
		tc.record_error_at(.return_mismatch, 'unreachable code', unreachable_id,
			tc.unreachable_statement_diagnostic_pos(unreachable_id))
	}
	$if ownership ? {
		tc.ownership_record_current_loop_iteration_drops()
		tc.ownership_merge_loop_continue_snapshots()
		tc.ownership_end_loop_branch(node, header)
		tc.ownership_add_branch_group_base()
		tc.ownership_end_branch_group()
	}
	tc.pop_scope()
}

fn (mut tc TypeChecker) check_loop_var_const_conflict(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind != .ident || node.value.len == 0 || node.value == '_' {
		return false
	}
	if tc.should_check_source_name(id) && !snake_case_name_is_valid(node.value) {
		tc.check_snake_case_name(id, node.value, 'variable name', tc.node_value_diagnostic_pos(id))
	}
	qname := if tc.cur_module in ['', 'main', 'builtin'] {
		node.value
	} else {
		'${tc.cur_module}.${node.value}'
	}
	if qname in tc.const_types || node.value in tc.const_types
		|| tc.const_key_for_name(node.value) != none {
		message := 'duplicate of a const name `${node.value}`'
		pos := tc.node_value_diagnostic_pos(id)
		if !tc.errors.any(it.msg == message && it.pos == pos) {
			tc.record_error_at(.duplicate_decl, message, id, pos)
		}
		return true
	}
	return false
}

fn (mut tc TypeChecker) check_for_in_const_conflicts_preflight() {
	for i, node in tc.a.nodes {
		if node.kind != .for_in_stmt || node.value.int() < 3 || node.children_count < 2 {
			continue
		}
		file := tc.a.source_files[node.pos.id] or { continue }
		if tc.diagnostic_files.len > 0 && file.name !in tc.diagnostic_files {
			continue
		}
		module_name := tc.file_modules[file.name] or { 'main' }
		has_value := int(tc.a.child(&node, 1)) >= 0
		count := if has_value { 2 } else { 1 }
		for child_index in 0 .. count {
			binding_id := tc.a.child(&node, child_index)
			binding := tc.a.node(binding_id)
			if binding.kind != .ident || binding.value.len == 0 || binding.value == '_' {
				continue
			}
			qname := if module_name in ['', 'main', 'builtin'] {
				binding.value
			} else {
				'${module_name}.${binding.value}'
			}
			full_qname := '${if module_name.len > 0 { module_name } else { 'main' }}.${binding.value}'
			if qname !in tc.const_types && full_qname !in tc.const_types
				&& binding.value !in tc.const_types {
				continue
			}
			saved_file := tc.cur_file
			saved_module := tc.cur_module
			tc.cur_file = file.name
			tc.cur_module = module_name
			tc.record_error_at(.duplicate_decl, 'duplicate of a const name `${binding.value}`',
				flat.NodeId(i), tc.node_value_diagnostic_pos(binding_id))
			tc.cur_file = saved_file
			tc.cur_module = saved_module
		}
	}
}

fn (mut tc TypeChecker) check_for_in_binding_name(id flat.NodeId, role string) {
	if !tc.valid_node_id(id) || !tc.should_check_source_name(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind != .ident || node.value.len == 0 || node.value == '_' {
		return
	}
	if reserved_const_type_name(node.value) {
		tc.record_error_at(.duplicate_decl,
			'invalid use of reserved type `${node.value}` as ${role} name', id,
			tc.node_value_diagnostic_pos(id))
		return
	}
	parent := tc.cur_scope.parent
	if parent != unsafe { nil } {
		for name in parent.names {
			if name == node.value {
				tc.record_error_at(.duplicate_decl,
					'redefinition of ${role} iteration variable `${node.value}`', id,
					tc.node_value_diagnostic_pos(id))
				return
			}
		}
	}
}

fn (mut tc TypeChecker) check_for_in_same_variable(header int, key_id flat.NodeId, val_id flat.NodeId, low_id flat.NodeId, high_id flat.NodeId) (bool, bool) {
	if !tc.valid_node_id(key_id) || !tc.valid_node_id(low_id) {
		return false, false
	}
	mut actual_low_id := low_id
	mut actual_high_id := high_id
	mut is_range := header == 4
	container := tc.a.node(low_id)
	if header == 3 && container.kind == .range && container.children_count >= 2 {
		actual_low_id = tc.a.child(container, 0)
		actual_high_id = tc.a.child(container, 1)
		is_range = true
	}
	if !tc.should_check_source_name(actual_low_id) {
		return false, false
	}
	key := tc.a.node(key_id)
	if key.kind != .ident {
		return false, false
	}
	mut iteration_name := key.value
	if tc.valid_node_id(val_id) {
		val := tc.a.node(val_id)
		if val.kind == .ident {
			iteration_name = val.value
		}
	}
	low := tc.a.node(actual_low_id)
	mut same_low := low.kind == .ident && low.value == key.value
	if !same_low && tc.valid_node_id(val_id) {
		val := tc.a.node(val_id)
		same_low = low.kind == .ident && low.value == val.value
	}
	if same_low {
		kind := if is_range { '<range>' } else { 'array' }
		tc.record_error_at(.cannot_index,
			'in a `for x in ${kind}` loop, the key or value iteration variable `${iteration_name}` can not be the same as the low variable',
			actual_low_id, tc.node_value_diagnostic_pos(actual_low_id))
	}
	if !is_range || !tc.valid_node_id(actual_high_id) {
		return same_low, false
	}
	high := tc.a.node(actual_high_id)
	mut same_high := high.kind == .ident && high.value == key.value
	if !same_high && tc.valid_node_id(val_id) {
		val := tc.a.node(val_id)
		same_high = high.kind == .ident && high.value == val.value
	}
	if same_high && !same_low {
		tc.record_error_at(.cannot_index,
			'in a `for x in <range>` loop, the key or value iteration variable `${iteration_name}` can not be the same as the high variable',
			actual_high_id, tc.node_value_diagnostic_pos(actual_high_id))
	}
	return same_low, same_high
}

fn (mut tc TypeChecker) check_for_in_mutable_container(loop flat.Node, key_id flat.NodeId, val_id flat.NodeId, container_id flat.NodeId, container_type Type) {
	if loop.op != .amp || !tc.valid_node_id(container_id) {
		return
	}
	mut binding_id := key_id
	if tc.valid_node_id(val_id) {
		binding_id = val_id
	}
	if unalias_type(container_type) is String {
		tc.record_error_at(.assignment_mismatch, 'string type is immutable, it cannot be changed',
			binding_id, tc.for_in_mut_keyword_pos(binding_id))
		return
	}
	if tc.expr_root_is_mutable_lvalue(container_id) {
		return
	}
	mut diagnostic_id := container_id
	mut container := tc.a.node(diagnostic_id)
	for container.kind in [.paren, .or_expr, .postfix] && container.children_count > 0 {
		diagnostic_id = tc.a.child(container, 0)
		container = tc.a.node(diagnostic_id)
	}
	if container.kind == .ident {
		tc.record_error_at(.assignment_mismatch,
			'`${container.value}` is immutable, it cannot be changed', container_id,
			tc.node_value_diagnostic_pos(diagnostic_id))
		return
	}
	if container.kind == .selector && container.children_count > 0 {
		base_id := tc.a.child(container, 0)
		base_type := unalias_and_unwrap_pointer_type(tc.resolve_type(base_id))
		if base_type is Struct {
			tc.record_error_at(.assignment_mismatch,
				'field `${base_type.name}.${container.value}` is immutable, it cannot be changed',
				container_id, tc.node_value_diagnostic_pos(diagnostic_id))
			return
		}
	}
	if container.kind == .map_init {
		pos := token.new_span(container.pos.id, container.pos.offset, container.pos.offset + 1)
		tc.record_error_at(.assignment_mismatch, 'map literal is immutable, it cannot be changed',
			container_id, pos)
		return
	}
	if container.kind in [.array_literal, .array_init] {
		tc.record_error_at(.assignment_mismatch,
			'array literal is immutable, it cannot be changed', container_id,
			tc.a.node(container_id).pos)
	}
}

fn (tc &TypeChecker) for_in_mut_keyword_pos(binding_id flat.NodeId) token.Pos {
	if !tc.valid_node_id(binding_id) {
		return token.Pos{}
	}
	binding := tc.a.node(binding_id)
	file := tc.a.source_files[binding.pos.id] or { return binding.pos }
	source := tc.source_texts_by_file[file.name] or { return binding.pos }
	end := int_min(int_max(binding.pos.end, 0), source.len)
	mut line_start := int_min(int_max(binding.pos.offset, 0), end)
	for line_start > 0 && source[line_start - 1] != `\n` {
		line_start--
	}
	if relative := source[line_start..end].last_index('mut ') {
		start := line_start + relative
		return token.new_span(binding.pos.id, start, start + 3)
	}
	return binding.pos
}

fn (mut tc TypeChecker) record_for_in_invalid_selector(id flat.NodeId, node flat.Node) {
	if node.kind != .selector || node.children_count == 0 {
		return
	}
	base := tc.a.child_node(&node, 0)
	if base.kind != .ident {
		return
	}
	tc.record_error_at(.cannot_index, '`${base.value}` does not return a value', id,
		tc.node_value_diagnostic_pos(id))
}

fn (mut tc TypeChecker) check_for_in_range_types(low_id flat.NodeId, high_id flat.NodeId) {
	low_type := unalias_type(tc.resolve_type(low_id))
	high_type := unalias_type(tc.resolve_type(high_id))
	if low_type is Unknown || high_type is Unknown {
		return
	}
	if low_type is MultiReturn || high_type is MultiReturn {
		tc.record_error_at(.condition_mismatch,
			'multi-returns cannot be used in ranges. A range is from a single value to a single higher value.',
			low_id, tc.range_endpoints_pos(low_id, high_id))
		return
	}
	if tc.a.node(low_id).kind == .none_expr && tc.a.node(high_id).kind == .none_expr {
		tc.record_error_at(.condition_mismatch, 'range type can only be an integer type', low_id, tc.range_endpoints_pos(low_id,
			high_id))
		return
	}
	if low_type is OptionType || low_type is ResultType {
		tc.record_error_at(.condition_mismatch,
			'the `low` value in a `for x in low..high {` loop, cannot be Result or Option', low_id,
			tc.a.node(low_id).pos)
		return
	}
	if high_type is OptionType || high_type is ResultType {
		tc.record_error_at(.condition_mismatch,
			'the `high` value in a `for x in low..high {` loop, cannot be Result or Option',
			high_id, tc.range_bound_diagnostic_pos(high_id))
		return
	}
	low_is_numeric := low_type.is_integer() || low_type.is_float()
	high_is_numeric := high_type.is_integer() || high_type.is_float()
	if low_is_numeric && high_is_numeric && (low_type.is_integer() != high_type.is_integer()
		|| (!tc.range_endpoint_is_literal(low_id) && !tc.range_endpoint_is_literal(high_id)
		&& low_type.name() != high_type.name())) {
		tc.record_error_at(.condition_mismatch, 'range types do not match', low_id,
			tc.a.node(low_id).pos)
		return
	}
	if !low_type.is_integer() || !high_type.is_integer() {
		tc.record_error_at(.condition_mismatch, 'range type can only be an integer type', low_id, tc.range_endpoints_pos(low_id,
			high_id))
		return
	}
	if low := tc.match_condition_int_value(low_id) {
		if high := tc.match_condition_int_value(high_id) {
			if low > high {
				tc.record_error_at(.condition_mismatch,
					'empty range: `${low} .. ${high}` will never execute', low_id, tc.range_endpoints_pos(low_id,
					high_id))
			}
		}
	}
}

fn (tc &TypeChecker) range_bound_diagnostic_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	if node.kind == .call && node.children_count > 0 {
		callee := tc.a.child_node(node, 0)
		if callee.kind == .selector {
			return tc.method_call_name_pos(node, callee)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) range_endpoint_is_literal(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind in [.int_literal, .float_literal, .char_literal] {
		return true
	}
	if node.kind == .ident {
		for candidate in [tc.qualify_name(node.value), node.value] {
			if expr_id := tc.const_exprs[candidate] {
				return tc.range_endpoint_is_literal(expr_id)
			}
		}
	}
	return false
}

fn (tc &TypeChecker) range_endpoints_pos(low_id flat.NodeId, high_id flat.NodeId) token.Pos {
	low := tc.a.node(low_id)
	high := tc.a.node(high_id)
	if low.pos.id == high.pos.id && low.pos.is_valid() && high.pos.is_valid() {
		return token.new_span(low.pos.id, low.pos.offset, high.pos.end)
	}
	return low.pos
}

fn (tc &TypeChecker) for_in_body_contains_map_delete(node flat.Node, body_start int, container_id flat.NodeId) bool {
	container_key := tc.for_in_map_storage_key(container_id)
	if container_key.len == 0 {
		return false
	}
	for i in body_start .. node.children_count {
		if tc.for_in_node_contains_map_delete(tc.a.child(&node, i), container_key) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) for_in_node_contains_map_delete(id flat.NodeId, container_key string) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind in [.fn_literal, .lambda_expr, .fn_decl] {
		return false
	}
	if node.kind == .call && node.children_count > 0 {
		fn_node := tc.a.child_node(&node, 0)
		if fn_node.kind == .selector && fn_node.value == 'delete' && fn_node.children_count > 0 {
			receiver_id := tc.a.child(fn_node, 0)
			if tc.for_in_map_storage_key(receiver_id) == container_key {
				return true
			}
		}
		if fn_node.kind == .ident && fn_node.value in ['map.delete', 'map__delete']
			&& node.children_count > 1 {
			receiver_id := tc.a.child(&node, 1)
			if tc.for_in_map_storage_key(receiver_id) == container_key {
				return true
			}
		}
	}
	for i in 0 .. node.children_count {
		if tc.for_in_node_contains_map_delete(tc.a.child(&node, i), container_key) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) for_in_map_storage_key(id flat.NodeId) string {
	if !tc.valid_node_id(id) {
		return ''
	}
	node := tc.a.nodes[int(id)]
	if node.kind in [.paren, .expr_stmt, .cast_expr, .as_expr] && node.children_count > 0 {
		return tc.for_in_map_storage_key(tc.a.child(&node, 0))
	}
	if node.kind == .prefix && node.op in [.amp, .mul] && node.children_count > 0 {
		return tc.for_in_map_storage_key(tc.a.child(&node, 0))
	}
	return tc.expr_key(id)
}

fn (mut tc TypeChecker) check_map_delete_snapshot_clones(map_type Map, pos flat.NodeId) {
	if bad_type := tc.ownership_default_clone_missing_method(map_type.key_type) {
		tc.record_error(.call_arg_mismatch,
			'cannot snapshot map keys for iteration with delete: `${bad_type}` requires ownership destruction but has no `clone()` method',
			pos)
	}
	if bad_type := tc.ownership_default_clone_missing_method(map_type.value_type) {
		tc.record_error(.call_arg_mismatch,
			'cannot snapshot map values for iteration with delete: `${bad_type}` requires ownership destruction but has no `clone()` method',
			pos)
	}
}

fn (mut tc TypeChecker) check_for_in_binding_clones(container Type, key_id flat.NodeId, val_id flat.NodeId, has_val bool) {
	match container {
		Array {
			target_id := if has_val { val_id } else { key_id }
			tc.check_for_in_binding_clone(target_id, container.elem_type, 'array element')
		}
		ArrayFixed {
			target_id := if has_val { val_id } else { key_id }
			tc.check_for_in_binding_clone(target_id, container.elem_type, 'fixed-array element')
		}
		Map {
			if has_val {
				tc.check_for_in_binding_clone(key_id, container.key_type, 'map key')
				tc.check_for_in_binding_clone(val_id, container.value_type, 'map value')
			} else {
				tc.check_for_in_binding_clone(key_id, container.value_type, 'map value')
			}
		}
		else {}
	}
}

fn (mut tc TypeChecker) check_for_in_binding_clone(target_id flat.NodeId, typ Type, role string) {
	if !tc.valid_node_id(target_id) || tc.a.nodes[int(target_id)].value == '_' {
		return
	}
	if bad_type := tc.ownership_default_clone_missing_method(typ) {
		tc.record_error(.call_arg_mismatch,
			'cannot iterate over ownership-bearing ${role}: `${bad_type}` requires ownership destruction but has no `clone()` method',
			target_id)
	}
}

fn (mut tc TypeChecker) check_storage_path_base_node(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	$if ownership ? {
		node := tc.a.nodes[int(id)]
		if node.kind in [.ident, .selector, .index] {
			tc.ownership_begin_suppressed_checks()
			tc.check_node(id)
			tc.ownership_end_suppressed_checks()
			return
		}
	}
	tc.check_node(id)
}

// check_decl_assign validates check decl assign state for types.
fn (mut tc TypeChecker) check_decl_assign(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	if tc.check_multi_return_decl_assign(id, node) {
		return
	}
	if tc.check_multi_value_list_decl_assign(id, node) {
		return
	}
	if tc.check_assignment_marker(id, node) {
		return
	}
	mut i := 0
	for i + 1 < node.children_count {
		lhs_id := tc.a.child(&node, i)
		rhs_id := tc.a.child(&node, i + 1)
		lhs_node := tc.a.nodes[int(lhs_id)]
		if lhs_node.kind != .ident {
			tc.check_node(rhs_id)
			if tc.record_invalid_decl_assign_lhs(node, lhs_id, rhs_id) {
				i += 2
				continue
			}
			if lhs_node.kind == .selector && lhs_node.children_count > 0 {
				base := tc.a.child_node(&lhs_node, 0)
				if !tc.is_namespace_selector(lhs_node, base) {
					tc.record_error_at(.assignment_mismatch,
						'use assignment `=` instead of declaration `:=` when modifying struct fields',
						lhs_id, tc.assignment_operator_pos(node, lhs_id, rhs_id))
					i += 2
					continue
				}
			}
			tc.record_error_at(.assignment_mismatch,
				'non-name `${tc.source_text_for_node(lhs_id)}` on left side of `:=`', lhs_id,
				tc.decl_non_name_lhs_pos(lhs_id))
			i += 2
			continue
		}
		if node.value == 'static' && tc.unsafe_depth == 0 && !tc.translated_files[tc.cur_file]
			&& !tc.current_fn_declared_unsafe() {
			tc.record_error_at(.assignment_mismatch,
				'static variables are supported only in -translated mode, `unsafe{}` blocks, or in `@[unsafe] fn`',
				lhs_id, tc.node_value_diagnostic_pos(lhs_id))
		}
		tc.check_import_symbol_conflict(lhs_id, lhs_node.value)
		tc.check_module_name_conflict(lhs_id, lhs_node.value)
		if reserved_const_type_name(lhs_node.value) && tc.should_diagnose(lhs_id) {
			tc.record_error_at(.duplicate_decl,
				'invalid use of reserved type `${lhs_node.value}` as a variable name', lhs_id,
				lhs_node.pos)
		}
		if tc.should_check_source_name(lhs_id) && !snake_case_name_is_valid(lhs_node.value) {
			tc.check_snake_case_name(lhs_id, lhs_node.value, 'variable name',
				tc.node_value_diagnostic_pos(lhs_id))
		}
		if lhs_node.value != '_' {
			if _ := tc.const_key_for_name(lhs_node.value) {
				tc.record_warning_at(.duplicate_decl,
					'duplicate of a const name `${tc.qualify_name(lhs_node.value)}`', lhs_id,
					tc.node_value_diagnostic_pos(lhs_id))
			}
		}
		mut shadows_fn := lhs_node.value in tc.fn_ret_types
			|| tc.qualify_fn_name(lhs_node.value) in tc.fn_ret_types
		if shadows_fn && tc.imported_module_prefix(lhs_id, lhs_node.value) != none
			&& !tc.source_module_declares_fn(lhs_node.value) {
			shadows_fn = false
		}
		if shadows_fn {
			tc.record_notice_at(.unknown_ident,
				'variable `${lhs_node.value}` shadows a function declaration', lhs_id,
				tc.node_value_diagnostic_pos(lhs_id))
		}
		explicit_expected := if node.children_count == 2 && node.typ.len > 0 {
			tc.parse_type(node.typ)
		} else {
			Type(void_)
		}
		saved_expected_expr_id := tc.expected_expr_id
		saved_expected_expr_type := tc.expected_expr_type
		if explicit_expected !is Void {
			tc.expected_expr_id = int(rhs_id)
			tc.expected_expr_type = explicit_expected
		}
		error_count := tc.errors.len
		tc.fn_context.undefined_variable_context_depth++
		$if ownership ? {
			if tc.ownership_should_defer_aggregate_consumption(lhs_id, .assign) {
				tc.ownership_begin_defer_aggregate_consumption(rhs_id)
				tc.check_node(rhs_id)
				tc.ownership_end_defer_aggregate_consumption(rhs_id)
			} else {
				tc.check_node(rhs_id)
			}
		} $else {
			tc.check_node(rhs_id)
		}
		tc.fn_context.undefined_variable_context_depth--
		tc.expected_expr_id = saved_expected_expr_id
		tc.expected_expr_type = saved_expected_expr_type
		rhs_node := tc.a.nodes[int(rhs_id)]
		if rhs_node.kind == .struct_init && tc.struct_init_has_positional_fields(rhs_node)
			&& !tc.type_name_known(rhs_node.value) {
			if lhs_node.value != '_' {
				tc.cur_scope.insert(lhs_node.value, Type(void_))
			}
			i += 2
			continue
		}
		if rhs_node.kind == .call {
			rhs_type := unalias_type(tc.resolve_type(rhs_id))
			if rhs_type is ResultType {
				tc.record_unhandled_result_call(rhs_id, rhs_type)
			}
		}
		if rhs_node.kind == .ident && tc.lock_depth == 0
			&& tc.current_binding_is_shared(rhs_node.value) {
			tc.record_error_at(.assignment_mismatch,
				'`${rhs_node.value}` is `shared` and must be `rlock`ed or `lock`ed to be used as non-mut right-hand side of assignment',
				rhs_id, rhs_node.pos)
			if lhs_node.value != '_' {
				tc.cur_scope.insert(lhs_node.value, tc.resolve_type(rhs_id))
			}
			i += 2
			continue
		}
		if rhs_node.kind == .map_init && rhs_node.children_count == 0 && rhs_node.value.len == 0 {
			tc.record_error_at(.assignment_mismatch,
				'invalid empty map initialisation syntax, use e.g. map[string]int{} instead',
				rhs_id, rhs_node.pos)
			if lhs_node.value != '_' {
				tc.cur_scope.insert(lhs_node.value, Type(void_))
			}
			i += 2
			continue
		}
		if rhs_node.kind == .fn_literal && rhs_node.generic_params().len > 0 {
			tc.record_error_at(.assignment_mismatch,
				'cannot assign generic function to a variable', rhs_id, rhs_node.pos)
			if lhs_node.value != '_' {
				tc.cur_scope.insert(lhs_node.value, tc.resolve_type(rhs_id))
			}
			i += 2
			continue
		}
		if rhs_node.kind == .infix && rhs_node.op == .arrow {
			tc.record_error_at(.assignment_mismatch,
				'cannot use `<-` on the right-hand side of an assignment, as it does not return any values',
				rhs_id, tc.infix_operator_pos(rhs_node, '<-'))
			i += 2
			continue
		}
		if unsafe_none_id := tc.unsafe_block_none_expr_id(rhs_id) {
			none_node := tc.a.node(unsafe_none_id)
			tc.record_error_at(.assignment_mismatch, 'cannot use `none` in `unsafe` blocks',
				unsafe_none_id, none_node.pos)
		} else if rhs_node.kind == .none_expr {
			tc.record_error_at(.assignment_mismatch, 'cannot assign a `none` value to a variable',
				rhs_id, rhs_node.pos)
			if lhs_node.value != '_' {
				tc.cur_scope.insert(lhs_node.value, Type(none_))
			}
			i += 2
			continue
		}
		if rhs_node.kind == .nil_literal && tc.unsafe_depth == 0 {
			tc.record_error_at(.assignment_mismatch, '`nil` is only allowed in `unsafe` code',
				rhs_id, rhs_node.pos)
			tc.record_error_at(.assignment_mismatch,
				'use of untyped nil in assignment (use `unsafe` | false)', rhs_id, rhs_node.pos)
			if lhs_node.value != '_' {
				tc.cur_scope.insert(lhs_node.value, Type(voidptr_))
			}
			i += 2
			continue
		}
		tc.check_const_reference_assignment(lhs_id, rhs_id, true)
		if lhs_node.value != '_' && tc.unsafe_depth == 0 && (tc.decl_lhs_is_mut(node, lhs_id)
			|| tc.slice_expr_base_is_mutable(rhs_id)) {
			tc.record_implicit_slice_clone_notice(rhs_id)
		}
		if tc.new_error_kind_since(error_count, .unknown_ident) {
			if tc.new_errors_are_forward_decl_unknowns(error_count) {
				if lhs_node.value != '_' {
					tc.cur_scope.insert(lhs_node.value,
						unknown_type('initializer contains an unresolved forward declaration'))
				}
				i += 2
				continue
			}
			return
		}
		if tc.assignment_rhs_is_void_selector(rhs_id) && !tc.unknown_imported_enum_selector(rhs_id)
			&& !tc.errors.any(it.node == rhs_id && it.msg.ends_with('must be initialized')) {
			tc.record_error_at(.assignment_mismatch, 'assignment mismatch: 1 variable 0 values',
				id, tc.assignment_operator_pos(node, lhs_id, rhs_id))
		}
		mut rhs_type := tc.decl_assign_inferred_type(rhs_id)
		if rhs_node.kind == .ident && tc.type_has_declaration_attribute(rhs_type, 'nocopy') {
			tc.record_error_at(.assignment_mismatch,
				'cannot copy @[nocopy] struct: use a reference instead', rhs_id, rhs_node.pos)
		}
		tc.record_non_heap_pointer_param_escape(rhs_id)
		if node.value == 'static' && !tc.static_initializer_is_constant(rhs_id) {
			tc.record_error_at(.assignment_mismatch,
				'cannot initialized static variable with non-constant value', lhs_id,
				tc.node_value_diagnostic_pos(lhs_id))
		}
		if node.value == 'static' && unalias_type(rhs_type) is Map {
			tc.record_error_at(.assignment_mismatch, 'maps cannot be static', lhs_id,
				tc.node_value_diagnostic_pos(lhs_id))
		}
		if assigned_fn := fn_type_from_type(rhs_type) {
			return_name := assigned_fn.return_type.name()
			unknown_return := assigned_fn.return_type is Unknown
				|| (should_check_named_type(return_name) && !tc.type_name_known(return_name))
			if unknown_return && rhs_node.kind in [.index, .selector] {
				tc.record_error_at(.unknown_type,
					'unknown return type: cannot assign `${tc.source_text_for_node(rhs_id)}` as a function variable',
					rhs_id, tc.index_suffix_diagnostic_pos(rhs_id))
				if lhs_node.value != '_' {
					tc.cur_scope.insert(lhs_node.value, rhs_type)
				}
				i += 2
				continue
			}
		}
		if rhs_type is MultiReturn {
			call_name := tc.assignment_rhs_call_name(rhs_id) or { '' }
			message := if rhs_node.kind == .dump_expr || call_name.len == 0 {
				'assignment mismatch: 1 variable ${rhs_type.types.len} values'
			} else {
				'assignment mismatch: 1 variable but `${call_name}()` returns ${rhs_type.types.len} values'
			}
			tc.record_error_at(.assignment_mismatch, message, id, tc.assignment_operator_pos(node,
				lhs_id, rhs_id))
			if lhs_node.value != '_' {
				tc.cur_scope.insert(lhs_node.value, rhs_type)
			}
			i += 2
			continue
		}
		if rhs_type is Void {
			if call_name := tc.assignment_rhs_call_name(rhs_id) {
				message := if rhs_node.kind == .paren {
					'assignment mismatch: expected 1 value(s) but `${call_name}()` returns 0 value(s)'
				} else {
					'assignment mismatch: 1 variable but `${call_name}()` returns 0 values'
				}
				tc.record_error_at(.assignment_mismatch, message, id, tc.assignment_operator_pos(node,
					lhs_id, rhs_id))
				if lhs_node.value != '_' {
					tc.cur_scope.insert(lhs_node.value, Type(void_))
				}
				i += 2
				continue
			}
		}
		if rhs_node.kind == .array_literal && rhs_node.children_count == 0 && rhs_node.typ.len == 0 {
			if lhs_node.value != '_' {
				tc.cur_scope.insert(lhs_node.value, Type(void_))
			}
			i += 2
			continue
		}
		if explicit_expected is Void && rhs_type.name() == 'int'
			&& tc.implicit_int_literal_overflows(rhs_id) {
			tc.record_error_at(.assignment_mismatch,
				'overflow in implicit type `int`, use explicit type casting instead', rhs_id,
				rhs_node.pos)
		}
		rhs_is_map_value := unalias_type(rhs_type) is Map
			|| (rhs_node.kind == .ident && tc.mut_param_binding_matches_lvalue(rhs_node.value)
			&& unalias_and_unwrap_pointer_type(rhs_type) is Map)
		if tc.unsafe_depth == 0 && rhs_is_map_value && rhs_node.kind == .ident {
			tc.record_error_at(.assignment_mismatch,
				'cannot copy map: call `move` or `clone` method (or use a reference)', rhs_id,
				rhs_node.pos)
		}
		if tc.unsafe_depth == 0 && tc.decl_lhs_is_mut(node, lhs_id)
			&& unalias_type(rhs_type) is Array && rhs_node.kind == .selector {
			tc.record_error_at(.assignment_mismatch,
				'use `mut array2 := array1.clone()` instead of `mut array2 := array1` (or use `unsafe`)',
				id, tc.assignment_operator_pos(node, lhs_id, rhs_id))
		}
		if rhs_type is Void && rhs_node.kind == .infix && rhs_node.op == .left_shift {
			tc.cur_scope.insert(lhs_node.value, rhs_type)
			tc.remember_expr_type(lhs_id, rhs_type)
			i += 2
			continue
		}
		mut expected := rhs_type
		if explicit_expected !is Void {
			expected = explicit_expected
			rhs_type = tc.resolve_expr(rhs_id, expected)
			if !tc.expr_compatible(rhs_id, rhs_type, expected)
				&& !tc.pointer_value_compatible(rhs_type, expected) {
				tc.type_mismatch(.assignment_mismatch,
					'cannot assign `${rhs_type.name()}` to `${expected.name()}`', id)
			}
		}
		owner := tc.insert_decl_lhs(lhs_id, expected, tc.decl_lhs_is_mut(node, lhs_id))
		if lhs_node.value != '_' && tc.decl_lhs_is_mut(node, lhs_id) {
			tc.check_mutable_array_immutable_references(rhs_id)
			tc.record_mutable_decl_branch_immutable_notices(rhs_id)
			if immutable_source_id := tc.immutable_reference_source(rhs_id, rhs_type) {
				source := tc.a.node(immutable_source_id)
				tc.record_notice_at(.assignment_mismatch,
					'`${source.value}` is immutable, cannot have a mutable reference to an immutable object',
					immutable_source_id, tc.node_value_diagnostic_pos(immutable_source_id))
				tc.fn_context.immutable_reference_aliases[lhs_node.value] = true
			}
			if tc.call_immutable_alias_source(rhs_id) != none {
				tc.fn_context.immutable_reference_aliases[lhs_node.value] = true
			}
			if rhs_node.kind == .ident && !tc.ident_is_mutable_lvalue(rhs_node.value)
				&& tc.type_contains_mutable_reference_data(rhs_type) {
				tc.fn_context.immutable_reference_aliases[lhs_node.value] = true
			}
		}
		if owner.storage_key().len > 0 && decl_assign_is_shared_marker(node.value) {
			lhs := tc.a.nodes[int(lhs_id)]
			if lhs.kind == .ident && lhs.value.len > 0 {
				tc.mark_shared_binding_owner(lhs.value, owner)
			}
		}
		if owner.storage_key().len > 0 && tc.expr_initializes_shared_array(rhs_id) {
			lhs := tc.a.nodes[int(lhs_id)]
			if lhs.kind == .ident && lhs.value.len > 0 {
				tc.mark_shared_array_binding_owner(lhs.value, owner)
			}
		}
		$if ownership ? {
			tc.ownership_after_decl_assign(lhs_id, rhs_id, expected, id)
		}
		tc.track_method_value_local(lhs_id, rhs_id)
		tc.track_variadic_fn_value_local(lhs_id, rhs_id)
		tc.track_capturing_fn_literal_local(lhs_id, rhs_id, owner)
		i += 2
	}
}

fn (tc &TypeChecker) current_fn_declared_unsafe() bool {
	fn_id := flat.NodeId(tc.fn_context.node_id)
	return tc.valid_node_id(fn_id) && tc.declaration_has_attribute(fn_id, 'unsafe')
}

fn (tc &TypeChecker) static_initializer_is_constant(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind in [.int_literal, .float_literal, .bool_literal, .char_literal, .string_literal,
		.enum_val, .nil_literal, .none_expr, .sizeof_expr, .typeof_expr] {
		return true
	}
	if node.kind == .ident {
		return tc.const_key_for_name(node.value) != none
	}
	if node.kind !in [.infix, .prefix, .paren, .cast_expr, .array_literal, .array_init, .map_init,
		.struct_init, .field_init] {
		return false
	}
	for i in 0 .. node.children_count {
		if !tc.static_initializer_is_constant(tc.a.child(node, i)) {
			return false
		}
	}
	return true
}

fn (mut tc TypeChecker) check_multi_value_list_decl_assign(id flat.NodeId, node flat.Node) bool {
	lhs_ids := tc.multi_assign_lhs_ids(node)
	rhs_count := tc.multi_assign_rhs_count(node)
	if lhs_ids.len == 0 || rhs_count <= 1 {
		return false
	}
	mut rhs_ids := []flat.NodeId{cap: rhs_count}
	mut multi_ids := []flat.NodeId{}
	mut multi_types := []MultiReturn{}
	mut right_len := rhs_count
	for i in 0 .. rhs_count {
		rhs_id := tc.multi_assign_rhs_id(node, i)
		rhs_ids << rhs_id
		rhs_type := tc.resolve_type(rhs_id)
		if multi := tc.multi_return_assignment_type(rhs_id, rhs_type) {
			multi_ids << rhs_id
			multi_types << multi
			right_len = multi.types.len
		}
	}
	if multi_ids.len == 0 && lhs_ids.len == right_len {
		return false
	}
	for rhs_id in rhs_ids {
		tc.check_node(rhs_id)
	}
	if multi_ids.len > 0 {
		diagnostic_index := 0
		multi_id := multi_ids[diagnostic_index]
		multi_type := multi_types[diagnostic_index]
		tc.record_error_at(.assignment_mismatch,
			'cannot use multi-value ${Type(multi_type).name()} in single-value context', multi_id,
			tc.multi_value_single_context_pos(multi_id))
	}
	if lhs_ids.len != right_len {
		variables := if lhs_ids.len == 1 { 'variable' } else { 'variables' }
		values := if right_len == 1 { 'value' } else { 'values' }
		first_rhs_id := rhs_ids[0]
		message := if call_name := tc.assignment_rhs_call_name(first_rhs_id) {
			'assignment mismatch: ${lhs_ids.len} ${variables} but `${call_name}()` returns ${right_len} ${values}'
		} else {
			'assignment mismatch: ${lhs_ids.len} ${variables} ${right_len} ${values}'
		}
		tc.record_error_at(.assignment_mismatch, message, id, tc.assignment_operator_pos(node,
			lhs_ids[0], first_rhs_id))
	}
	return true
}

fn (tc &TypeChecker) multi_value_single_context_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	if node.kind == .if_expr {
		return token.new_span(node.pos.id, node.pos.offset, node.pos.offset + 2)
	}
	if node.kind == .match_stmt {
		file := tc.a.source_files[node.pos.id] or { return node.pos }
		source := tc.source_texts_by_file[file.name] or { return node.pos }
		start := int_max(0, node.pos.offset)
		end := int_min(source.len, node.pos.end)
		if start < end {
			if relative := source[start..end].index('{') {
				return token.new_span(node.pos.id, start, start + relative + 1)
			}
		}
	}
	return tc.array_element_diagnostic_pos(id)
}

fn (mut tc TypeChecker) check_mutable_array_immutable_references(id flat.NodeId) {
	if tc.unsafe_depth > 0 || !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind != .array_literal {
		return
	}
	for i in 0 .. node.children_count {
		elem_id := tc.a.child(node, i)
		elem := tc.a.node(elem_id)
		if elem.kind != .prefix || elem.op != .amp || elem.children_count == 0 {
			continue
		}
		source_id := tc.a.child(elem, 0)
		source := tc.a.node(source_id)
		if source.kind == .ident && !tc.ident_is_mutable_lvalue(source.value)
			&& tc.const_key_for_name(source.value) == none {
			tc.record_warning_at(.assignment_mismatch,
				'cannot add a reference to an immutable object to a mutable array', elem_id,
				tc.address_operator_pos(elem_id))
		}
	}
}

fn (mut tc TypeChecker) record_mutable_decl_branch_immutable_notices(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind == .if_expr || node.kind == .match_stmt {
		for i in 1 .. node.children_count {
			tc.record_mutable_decl_branch_immutable_notices(tc.branch_tail_expr_id(tc.a.child(node,
				i)))
		}
		return
	}
	if node.kind != .ident || tc.ident_is_mutable_lvalue(node.value) {
		return
	}
	typ := unalias_type(tc.resolve_type(id))
	if typ is Array || typ is ArrayFixed || typ is Map {
		tc.record_notice_at(.assignment_mismatch,
			'left-side of assignment expects a mutable reference, but variable `${node.value}` is immutable, declare it with `mut` to make it mutable or clone it',
			id, tc.node_value_diagnostic_pos(id))
	}
}

fn (tc &TypeChecker) type_contains_mutable_reference_data(typ Type) bool {
	clean := unalias_type(typ)
	if clean is Array || clean is Map {
		return true
	}
	if clean is Struct {
		for field in tc.struct_fields_for_init(clean.name) {
			field_type := unalias_type(field.typ)
			if field_type is Array || field_type is Map {
				return true
			}
		}
	}
	return false
}

fn (mut tc TypeChecker) check_mutable_alias_assignment_lhs(id flat.NodeId) {
	if tc.unsafe_depth > 0 || !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind == .index && node.children_count > 0 {
		base_id := tc.a.child(node, 0)
		base := tc.a.node(base_id)
		mut aliases :=
			(base.kind == .ident && tc.fn_context.immutable_reference_aliases[base.value])
			|| (base.kind == .call && tc.call_immutable_alias_source(base_id) != none)
		if base.kind == .selector {
			if root_id := tc.lvalue_root_ident(base_id) {
				root := tc.a.node(root_id)
				aliases = aliases || tc.fn_context.immutable_reference_aliases[root.value]
			}
		}
		if aliases {
			tc.record_error_at(.assignment_mismatch,
				'`${tc.source_text_for_node(base_id)}` aliases mutable data from an immutable value, clone it first (or use `unsafe`)',
				base_id, if base.kind in [.ident, .selector] {
				tc.node_value_diagnostic_pos(base_id)
			} else {
				base.pos
			})
		}
		return
	}
	if node.kind != .selector || node.children_count == 0 {
		return
	}
	base_id := tc.a.child(node, 0)
	base := tc.a.node(base_id)
	aliases := (base.kind == .ident && tc.fn_context.immutable_reference_aliases[base.value])
		|| (base.kind == .call && tc.call_immutable_alias_source(base_id) != none)
	if aliases {
		tc.record_error_at(.assignment_mismatch,
			'`${tc.source_text_for_node(id)}` aliases mutable data from an immutable value', id,
			tc.node_value_diagnostic_pos(id))
	}
}

fn (mut tc TypeChecker) call_immutable_alias_source(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	call := tc.a.node(id)
	if call.kind != .call || call.children_count == 0 {
		return none
	}
	return_type := unalias_type(tc.resolve_type(id))
	if return_type !is Array && return_type !is Map && return_type !is Pointer {
		return none
	}
	info := tc.resolve_call_info(id, *call) or { return none }
	decl_module := tc.fn_type_modules[info.name] or { tc.cur_module }
	decl := tc.visible_mutation_fn_decl(info.name, decl_module) or { return none }
	fn_node := tc.a.node(flat.NodeId(decl.idx))
	mut callee := tc.a.child_node(call, 0)
	if callee.kind == .index && callee.children_count > 0 {
		callee = tc.a.child_node(callee, 0)
	}
	mut args_by_param := map[string]flat.NodeId{}
	mut call_arg_index := 1
	mut param_index := 0
	for i in 0 .. fn_node.children_count {
		param := tc.a.child_node(fn_node, i)
		if param.kind != .param {
			break
		}
		if info.has_receiver && param_index == 0 {
			if callee.kind == .selector && callee.children_count > 0 {
				args_by_param[param.value] = tc.a.child(callee, 0)
			}
		} else if call_arg_index < call.children_count {
			args_by_param[param.value] = tc.call_arg_value(tc.a.child(call, call_arg_index))
			call_arg_index++
		}
		param_index++
	}
	mut stack := []flat.NodeId{}
	for i in 0 .. fn_node.children_count {
		child_id := tc.a.child(fn_node, i)
		if tc.a.node(child_id).kind != .param {
			stack << child_id
		}
	}
	for stack.len > 0 {
		node_id := stack.pop()
		node := tc.a.node(node_id)
		if node.kind == .return_stmt {
			for i in 0 .. node.children_count {
				returned_id := tc.a.child(node, i)
				param_name := tc.returned_alias_param_name(returned_id, args_by_param) or {
					continue
				}
				arg_id := args_by_param[param_name] or { continue }
				if immutable := tc.immutable_alias_argument(arg_id) {
					return immutable
				}
			}
			continue
		}
		if node.kind in [.fn_literal, .lambda_expr] {
			continue
		}
		for i in 0 .. node.children_count {
			stack << tc.a.child(node, i)
		}
	}
	return none
}

fn (tc &TypeChecker) returned_alias_param_name(id flat.NodeId, args_by_param map[string]flat.NodeId) ?string {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .ident && node.value in args_by_param {
		return node.value
	}
	if node.kind in [.index, .selector, .prefix, .paren, .cast_expr, .as_expr, .expr_stmt]
		&& node.children_count > 0 {
		return tc.returned_alias_param_name(tc.a.child(node, 0), args_by_param)
	}
	return none
}

fn (tc &TypeChecker) immutable_alias_argument(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .ident && !tc.ident_is_mutable_lvalue(node.value)
		&& tc.const_key_for_name(node.value) == none {
		return id
	}
	if node.kind in [.prefix, .paren, .cast_expr, .as_expr] && node.children_count > 0 {
		return tc.immutable_alias_argument(tc.a.child(node, 0))
	}
	return none
}

fn (mut tc TypeChecker) immutable_reference_source(id flat.NodeId, typ Type) ?flat.NodeId {
	if unalias_type(typ) !is Pointer || !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .ident && !tc.ident_is_mutable_lvalue(node.value)
		&& tc.const_key_for_name(node.value) == none {
		return id
	}
	if node.kind != .call {
		return none
	}
	info := tc.resolve_call_info(id, *node) or { return none }
	arg_count := int(node.children_count) - 1
	for i in 0 .. arg_count {
		param_idx := i + if info.has_receiver { 1 } else { 0 }
		if param_idx >= info.params.len || unalias_type(info.params[param_idx]) !is Pointer {
			continue
		}
		arg_id := tc.call_arg_value(tc.a.child(node, i + 1))
		arg := tc.a.node(arg_id)
		if arg.kind == .ident && !tc.ident_is_mutable_lvalue(arg.value)
			&& tc.const_key_for_name(arg.value) == none {
			return arg_id
		}
	}
	return none
}

fn (mut tc TypeChecker) record_invalid_decl_assign_lhs(node flat.Node, lhs_id flat.NodeId, rhs_id flat.NodeId) bool {
	lhs := tc.a.node(lhs_id)
	if lhs.kind == .paren {
		tc.record_error_at(.assignment_mismatch,
			'parentheses are not supported on the left side of `:=`', lhs_id, lhs.pos)
		if lhs.children_count == 0 {
			return true
		}
		inner_id := tc.a.child(lhs, 0)
		inner := tc.a.node(inner_id)
		if inner.kind == .prefix && inner.op == .mul {
			if tc.unsafe_depth == 0 {
				tc.record_error_at(.assignment_mismatch,
					'modifying variables via dereferencing can only be done in `unsafe` blocks',
					lhs_id, tc.assignment_operator_pos(node, lhs_id, rhs_id))
			}
			tc.record_error_at(.assignment_mismatch, 'non-name on the left side of `:=`', inner_id, tc.prefix_operator_pos(inner_id,
				'*'))
		}
		return true
	}
	if lhs.kind != .prefix {
		return false
	}
	op := tc.source_text_for_node(lhs_id).trim_space()[..1]
	if lhs.op == .amp {
		tc.record_error_at(.assignment_mismatch, 'cannot use a reference on the left side of `:=`',
			lhs_id, tc.prefix_operator_pos(lhs_id, op))
	} else {
		tc.record_error_at(.assignment_mismatch, 'cannot use `${op}` on the left of `:=`', lhs_id, tc.prefix_operator_pos(lhs_id,
			op))
	}
	tc.record_error_at(.assignment_mismatch, 'non-name on the left side of `:=`', lhs_id, tc.prefix_operator_pos(lhs_id,
		op))
	return true
}

fn (tc &TypeChecker) assignment_rhs_call_name(id flat.NodeId) ?string {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .call {
		callee_node := tc.a.child_node(node, 0)
		if callee_node.kind == .selector {
			if callee_node.children_count > 0 {
				base := tc.a.child_node(callee_node, 0)
				if base.kind == .ident && !tc.ident_resolves_to_value(base.value)
					&& tc.type_symbol_known(tc.qualify_name(base.value)) {
					return tc.call_display_name(node)
				}
			}
			return callee_node.value
		}
		if callee, _, _ := tc.unknown_method_call_parts(node) {
			return callee.value
		}
		return tc.call_display_name(node)
	}
	if node.kind in [.paren, .expr_stmt, .or_expr] && node.children_count > 0 {
		return tc.assignment_rhs_call_name(tc.a.child(node, 0))
	}
	return none
}

fn (tc &TypeChecker) unresolved_multi_assign_method_call_name(id flat.NodeId) ?string {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind in [.paren, .expr_stmt, .or_expr] && node.children_count > 0 {
		return tc.unresolved_multi_assign_method_call_name(tc.a.child(node, 0))
	}
	if node.kind != .call || node.children_count == 0 {
		return none
	}
	callee := tc.a.child_node(node, 0)
	if callee.kind != .selector || callee.children_count == 0 {
		return none
	}
	base := tc.a.child_node(callee, 0)
	if base.kind == .ident && !tc.lvalue_ident_is_known(base.value) {
		return callee.value
	}
	return none
}

fn (tc &TypeChecker) unsafe_block_none_expr_id(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind != .block || node.value != 'unsafe' {
		return none
	}
	tail_id := tc.branch_tail_expr_id(id)
	if tc.valid_node_id(tail_id) && tc.a.node(tail_id).kind == .none_expr {
		return tail_id
	}
	return none
}

fn (mut tc TypeChecker) check_const_reference_assignment(lhs_id flat.NodeId, rhs_id flat.NodeId, is_decl bool) {
	lhs := tc.a.node(lhs_id)
	if const_id := tc.addressed_const_ident(rhs_id) {
		const_node := tc.a.node(const_id)
		key := tc.const_key_for_name(const_node.value) or { return }
		if is_decl {
			if expr_id := tc.const_exprs[key] {
				expr := tc.a.node(expr_id)
				if expr.kind == .int_literal {
					value := tc.source_text_for_node(expr_id)
					tc.record_error_with_details_at(.assignment_mismatch,
						'cannot assign a pointer to a constant with an integer literal value',
						const_id, tc.node_value_diagnostic_pos(const_id), [
						'Specify the type for the constant value. Example:',
						'         `const ${const_node.value} = int(${value})`',
					])
				}
			}
		}
		if lhs.kind == .ident && lhs.value != '_' {
			tc.record_error_at(.assignment_mismatch,
				'cannot have mutable reference to const `${const_node.value}`', rhs_id,
				tc.address_operator_pos(rhs_id))
		}
	}
	addressed_id := tc.addressed_ident(rhs_id) or { return }
	addressed := tc.a.node(addressed_id)
	if tc.assignment_target_requests_mutable_reference(lhs_id, is_decl)
		&& !tc.ident_is_mutable_lvalue(addressed.value) {
		tc.record_error_at(.assignment_mismatch,
			'`${addressed.value}` is immutable, cannot have a mutable reference to it', rhs_id,
			tc.address_operator_pos(rhs_id))
	}
}

fn (tc &TypeChecker) addressed_const_ident(id flat.NodeId) ?flat.NodeId {
	ident_id := tc.addressed_ident(id) or { return none }
	if _ := tc.const_key_for_name(tc.a.node(ident_id).value) {
		return ident_id
	}
	return none
}

fn (tc &TypeChecker) addressed_ident(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .paren && node.children_count > 0 {
		return tc.addressed_const_ident(tc.a.child(node, 0))
	}
	if node.kind != .prefix || node.op != .amp || node.children_count == 0 {
		return none
	}
	mut child_id := tc.a.child(node, 0)
	mut child := tc.a.node(child_id)
	for child.kind == .paren && child.children_count > 0 {
		child_id = tc.a.child(child, 0)
		child = tc.a.node(child_id)
	}
	if child.kind != .ident {
		return none
	}
	return child_id
}

fn (tc &TypeChecker) assignment_target_requests_mutable_reference(lhs_id flat.NodeId, is_decl bool) bool {
	lhs := tc.a.node(lhs_id)
	if lhs.kind != .ident || lhs.value == '_' {
		return false
	}
	if is_decl {
		parent_id := tc.direct_parent_id(lhs_id)
		if tc.valid_node_id(parent_id) {
			parent := tc.a.node(parent_id)
			if parent.kind == .decl_assign {
				return tc.decl_lhs_is_mut(parent, lhs_id)
			}
		}
	}
	return tc.ident_is_mutable_lvalue(lhs.value)
}

fn (tc &TypeChecker) address_operator_pos(id flat.NodeId) token.Pos {
	if !tc.valid_node_id(id) {
		return token.Pos{}
	}
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(node.pos.end, source.len)
	if start < end {
		if relative := source[start..end].index('&') {
			op_start := start + relative
			return token.new_span(node.pos.id, op_start, op_start + 1)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) decl_non_name_lhs_pos(id flat.NodeId) token.Pos {
	if !tc.valid_node_id(id) {
		return token.Pos{}
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .selector {
		return tc.node_value_diagnostic_pos(id)
	}
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(node.pos.end, source.len)
	if start < end {
		if relative := source[start..end].last_index('[') {
			suffix_start := start + relative
			return token.new_span(node.pos.id, suffix_start, end)
		}
	}
	return node.pos
}

// cur_scope_depth returns the number of enclosing scopes (the current scope's parent-chain
// length), used to tell a dominating top-level reassignment from one nested in a branch/loop.
fn (tc &TypeChecker) cur_scope_depth() int {
	mut d := 0
	mut s := tc.cur_scope
	for s != unsafe { nil } {
		d++
		s = s.parent
	}
	return d
}

fn clone_scope_binding_owner_map(src map[string][]ScopeBindingOwner) map[string][]ScopeBindingOwner {
	mut out := map[string][]ScopeBindingOwner{}
	for name, owners in src {
		out[name] = owners.clone()
	}
	return out
}

// track_method_value_local records (or clears) a local variable bound to a method value, so a
// later `return cb` / `arr << cb` retains any stack-backed mutable-receiver lifetime hazard.
fn (mut tc TypeChecker) track_method_value_local(lhs_id flat.NodeId, rhs_id flat.NodeId) {
	if int(lhs_id) < 0 {
		return
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind != .ident || lhs.value.len == 0 || lhs.value == '_' {
		return
	}
	if tc.expr_is_method_value(rhs_id) {
		tc.fn_context.method_value_locals[lhs.value] = true
		tc.fn_context.method_value_local_depth[lhs.value] = tc.cur_scope_depth()
		tc.mark_method_value_local_owner(lhs.value)
		if tc.method_value_has_stack_mut_receiver(rhs_id) {
			if owner := tc.cur_scope.lookup_owner(lhs.value) {
				owner_key := owner.storage_key()
				if owner_key.len > 0 {
					tc.fn_context.method_value_stack_mut_owners[owner_key] = true
				}
			}
		}
	} else if lhs.value in tc.fn_context.method_value_locals {
		// Reassigned to a non-method-value. Only clear the marker when this reassignment
		// dominates later uses — at the same or a shallower scope than where the local was
		// marked. A reassignment in a deeper conditional/loop scope does not run on every path
		// (`mut cb := c.report; if x { cb = plain }; return cb`), so the local may still hold the
		// method value; keep the maybe-method marker and let the later escape be rejected.
		marked_depth := tc.fn_context.method_value_local_depth[lhs.value] or { 0 }
		if tc.cur_scope_depth() <= marked_depth {
			tc.unmark_current_method_value_local_owner(lhs.value)
		}
	}
}

fn (mut tc TypeChecker) mark_method_value_local_owner(name string) {
	if tc.cur_scope == unsafe { nil } {
		return
	}
	owner := tc.cur_scope.lookup_owner(name) or { return }
	owner_key := owner.storage_key()
	if owner_key.len == 0 {
		return
	}
	mut owners := tc.fn_context.method_value_local_owners[name] or { []ScopeBindingOwner{} }
	for existing in owners {
		if existing.storage_key() == owner_key {
			return
		}
	}
	owners << owner
	tc.fn_context.method_value_local_owners[name] = owners
}

fn (mut tc TypeChecker) unmark_current_method_value_local_owner(name string) {
	if tc.cur_scope == unsafe { nil } {
		return
	}
	owner := tc.cur_scope.lookup_owner(name) or { return }
	owner_key := owner.storage_key()
	if owner_key.len == 0 {
		return
	}
	owners := tc.fn_context.method_value_local_owners[name] or { return }
	mut keep := []ScopeBindingOwner{cap: owners.len}
	for existing in owners {
		if existing.storage_key() != owner_key {
			keep << existing
		} else {
			tc.fn_context.method_value_stack_mut_owners.delete(owner_key)
		}
	}
	if keep.len == 0 {
		tc.fn_context.method_value_locals.delete(name)
		tc.fn_context.method_value_local_depth.delete(name)
		tc.fn_context.method_value_local_owners.delete(name)
	} else {
		tc.fn_context.method_value_local_owners[name] = keep
	}
}

fn (tc &TypeChecker) current_binding_is_method_value_local(name string) bool {
	if name.len == 0 || name !in tc.fn_context.method_value_locals {
		return false
	}
	if tc.cur_scope == unsafe { nil } {
		return true
	}
	owners := tc.fn_context.method_value_local_owners[name] or { return true }
	current_owner := tc.cur_scope.lookup_owner(name) or {
		// Fn literals can be checked after their body has been lifted away from the
		// lexical scope that declared the captured alias. If there is no nearer
		// binding, keep treating the tracked name as the outer method-value local so
		// mutable-receiver escape checks can still follow it.
		return true
	}
	current_key := current_owner.storage_key()
	for owner in owners {
		if current_key.len > 0 && owner.storage_key() == current_key {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) current_method_value_local_has_stack_mut_receiver(name string) bool {
	if name.len == 0 {
		return false
	}
	owners := tc.fn_context.method_value_local_owners[name] or { return false }
	if tc.cur_scope != unsafe { nil } {
		if current_owner := tc.cur_scope.lookup_owner(name) {
			current_key := current_owner.storage_key()
			if current_key.len > 0 {
				return tc.fn_context.method_value_stack_mut_owners[current_key]
			}
		}
	}
	// A lifted nested literal can be checked without the outer lexical scope that
	// owns a captured method-value alias. Conservatively retain its mutable-receiver
	// marker.
	for owner in owners {
		if tc.fn_context.method_value_stack_mut_owners[owner.storage_key()] {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) track_variadic_fn_value_local(lhs_id flat.NodeId, rhs_id flat.NodeId) {
	if int(lhs_id) < 0 {
		return
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind != .ident || lhs.value.len == 0 || lhs.value == '_' {
		return
	}
	if tc.expr_is_variadic_fn_value(rhs_id) {
		tc.fn_context.fn_value_variadic_locals[lhs.value] = true
		tc.fn_context.fn_value_variadic_local_depth[lhs.value] = tc.cur_scope_depth()
		tc.mark_variadic_fn_value_local_owner(lhs.value)
	} else if lhs.value in tc.fn_context.fn_value_variadic_locals {
		marked_depth := tc.fn_context.fn_value_variadic_local_depth[lhs.value] or { 0 }
		if tc.cur_scope_depth() <= marked_depth {
			tc.unmark_current_variadic_fn_value_local_owner(lhs.value)
		}
	}
}

fn (mut tc TypeChecker) mark_variadic_fn_value_local_owner(name string) {
	if tc.cur_scope == unsafe { nil } {
		return
	}
	owner := tc.cur_scope.lookup_owner(name) or { return }
	owner_key := owner.storage_key()
	if owner_key.len == 0 {
		return
	}
	mut owners := tc.fn_context.fn_value_variadic_local_owners[name] or { []ScopeBindingOwner{} }
	for existing in owners {
		if existing.storage_key() == owner_key {
			return
		}
	}
	owners << owner
	tc.fn_context.fn_value_variadic_local_owners[name] = owners
}

fn (mut tc TypeChecker) unmark_current_variadic_fn_value_local_owner(name string) {
	if tc.cur_scope == unsafe { nil } {
		return
	}
	owner := tc.cur_scope.lookup_owner(name) or { return }
	owner_key := owner.storage_key()
	if owner_key.len == 0 {
		return
	}
	owners := tc.fn_context.fn_value_variadic_local_owners[name] or { return }
	mut keep := []ScopeBindingOwner{cap: owners.len}
	for existing in owners {
		if existing.storage_key() != owner_key {
			keep << existing
		}
	}
	if keep.len == 0 {
		tc.fn_context.fn_value_variadic_locals.delete(name)
		tc.fn_context.fn_value_variadic_local_depth.delete(name)
		tc.fn_context.fn_value_variadic_local_owners.delete(name)
	} else {
		tc.fn_context.fn_value_variadic_local_owners[name] = keep
	}
}

fn (tc &TypeChecker) current_binding_is_variadic_fn_value_local(name string) bool {
	if name.len == 0 || name !in tc.fn_context.fn_value_variadic_locals {
		return false
	}
	if tc.cur_scope == unsafe { nil } {
		return true
	}
	owners := tc.fn_context.fn_value_variadic_local_owners[name] or { return true }
	for owner in owners {
		if tc.cur_scope.nearest_binding_owned_by(name, owner) {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) mark_capturing_fn_literal_local_owner(name string) {
	if tc.cur_scope == unsafe { nil } {
		return
	}
	owner := tc.cur_scope.lookup_owner(name) or { return }
	owner_key := owner.storage_key()
	if owner_key.len == 0 {
		return
	}
	mut owners := tc.fn_context.capturing_fn_literal_local_owners[name] or { []ScopeBindingOwner{} }
	for existing in owners {
		if existing.storage_key() == owner_key {
			return
		}
	}
	owners << owner
	tc.fn_context.capturing_fn_literal_local_owners[name] = owners
}

fn (mut tc TypeChecker) unmark_current_capturing_fn_literal_local_owner(name string) {
	if tc.cur_scope == unsafe { nil } {
		return
	}
	owner := tc.cur_scope.lookup_owner(name) or { return }
	owner_key := owner.storage_key()
	if owner_key.len == 0 {
		return
	}
	owners := tc.fn_context.capturing_fn_literal_local_owners[name] or { return }
	mut keep := []ScopeBindingOwner{cap: owners.len}
	for existing in owners {
		if existing.storage_key() != owner_key {
			keep << existing
		}
	}
	if keep.len == 0 {
		tc.fn_context.capturing_fn_literal_locals.delete(name)
		tc.fn_context.capturing_fn_literal_local_depth.delete(name)
		tc.fn_context.capturing_fn_literal_local_owners.delete(name)
	} else {
		tc.fn_context.capturing_fn_literal_local_owners[name] = keep
	}
}

fn (tc &TypeChecker) current_binding_is_capturing_fn_literal_local(name string) bool {
	if name.len == 0 || name !in tc.fn_context.capturing_fn_literal_locals {
		return false
	}
	if tc.cur_scope == unsafe { nil } {
		return true
	}
	owners := tc.fn_context.capturing_fn_literal_local_owners[name] or { return true }
	for owner in owners {
		if tc.cur_scope.nearest_binding_owned_by(name, owner) {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) mark_shared_binding_owner(name string, owner ScopeBindingOwner) {
	owner_key := owner.storage_key()
	if name.len == 0 || owner_key.len == 0 {
		return
	}
	mut owners := tc.fn_context.shared_owners[name] or { []ScopeBindingOwner{} }
	for existing in owners {
		if existing.storage_key() == owner_key {
			return
		}
	}
	owners << owner
	tc.fn_context.shared_owners[name] = owners
}

fn (mut tc TypeChecker) mark_shared_array_binding_owner(name string, owner ScopeBindingOwner) {
	owner_key := owner.storage_key()
	if name.len == 0 || owner_key.len == 0 {
		return
	}
	mut owners := tc.fn_context.shared_array_owners[name] or { []ScopeBindingOwner{} }
	for existing in owners {
		if existing.storage_key() == owner_key {
			return
		}
	}
	owners << owner
	tc.fn_context.shared_array_owners[name] = owners
}

fn (tc &TypeChecker) current_binding_is_shared(name string) bool {
	if name.len == 0 || tc.cur_scope == unsafe { nil } {
		return false
	}
	owners := tc.fn_context.shared_owners[name] or { return false }
	for owner in owners {
		if tc.cur_scope.nearest_binding_owned_by(name, owner) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) current_binding_is_shared_array(name string) bool {
	if name.len == 0 || tc.cur_scope == unsafe { nil } {
		return false
	}
	owners := tc.fn_context.shared_array_owners[name] or { return false }
	for owner in owners {
		if tc.cur_scope.nearest_binding_owned_by(name, owner) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) expr_initializes_shared_array(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind == .paren && node.children_count > 0 {
		return tc.expr_initializes_shared_array(tc.a.child(node, 0))
	}
	if node.kind !in [.array_init, .array_literal] {
		return false
	}
	return node.typ.contains('shared ')
		|| tc.source_text_for_node(id).trim_space().starts_with('[]shared ')
}

fn (tc &TypeChecker) shared_array_element_index(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .index && node.children_count > 0 {
		base_id := tc.a.child(node, 0)
		base := tc.a.node(base_id)
		if base.kind == .ident && tc.current_binding_is_shared_array(base.value) {
			return id
		}
		return tc.shared_array_element_index(base_id)
	}
	if node.kind in [.selector, .paren] && node.children_count > 0 {
		return tc.shared_array_element_index(tc.a.child(node, 0))
	}
	return none
}

fn (tc &TypeChecker) expr_is_variadic_fn_value(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	if name := tc.resolved_fn_value_name(id) {
		return tc.fn_variadic[name] or { false }
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			if tc.current_binding_is_variadic_fn_value_local(node.value) {
				return true
			}
			if !tc.name_bound_as_value(node.value) {
				key := tc.ident_fn_value_key(node.value) or { return false }
				return tc.fn_variadic[key] or { false }
			}
			return false
		}
		.selector {
			if tc.selector_base_bound_as_value(node) {
				return false
			}
			key := tc.selector_fn_value_key(node) or { return false }
			return tc.fn_variadic[key] or { false }
		}
		.cast_expr, .paren, .expr_stmt {
			if node.children_count == 0 {
				return false
			}
			return tc.expr_is_variadic_fn_value(tc.a.child(&node, 0))
		}
		else {
			return false
		}
	}
}

fn (mut tc TypeChecker) track_capturing_fn_literal_local(lhs_id flat.NodeId, rhs_id flat.NodeId, owner ScopeBindingOwner) {
	if int(lhs_id) < 0 {
		return
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind != .ident || lhs.value.len == 0 || lhs.value == '_' {
		return
	}
	mut binding_owner := owner
	if binding_owner.storage_key().len == 0 {
		binding_owner = tc.cur_scope.lookup_owner(lhs.value) or { ScopeBindingOwner{} }
	}
	if binding_owner.storage_key().len == 0 {
		return
	}
	binding_key := binding_owner.storage_key()
	if tc.expr_is_capturing_fn_literal_value(rhs_id) {
		tc.capturing_fn_literal_locals[binding_key] = true
		tc.capturing_fn_literal_local_depth[binding_key] = tc.cur_scope_depth()
		tc.capturing_fn_literal_return_unsupported[binding_key] =
			tc.expr_is_unsupported_returned_capturing_fn_literal_value(rhs_id)
		return
	}
	if !tc.capturing_fn_literal_locals[binding_key] {
		return
	}
	marked_depth := tc.capturing_fn_literal_local_depth[binding_key] or { 0 }
	if tc.cur_scope_depth() <= marked_depth {
		tc.capturing_fn_literal_locals.delete(binding_key)
		tc.capturing_fn_literal_local_depth.delete(binding_key)
		tc.capturing_fn_literal_return_unsupported.delete(binding_key)
	}
}

fn (mut tc TypeChecker) decl_assign_inferred_type(rhs_id flat.NodeId) Type {
	if int(rhs_id) < 0 || int(rhs_id) >= tc.a.nodes.len {
		return unknown_type('missing declaration initializer')
	}
	rhs := tc.a.nodes[int(rhs_id)]
	if rhs.kind == .cast_expr && rhs.value.len > 0 {
		typ := tc.parse_type(rhs.value)
		if typ is Alias {
			return typ
		}
	}
	if smartcast := tc.smartcast_type(rhs_id) {
		return smartcast
	}
	if rhs.kind == .selector {
		if declared := tc.selector_declared_value_type(rhs) {
			if declared is OptionType || declared is ResultType {
				return declared
			}
		}
	}
	if typ := tc.infer_fn_value_decl_type(rhs_id) {
		return typ
	}
	if rhs.kind == .if_expr {
		return tc.if_expr_tail_type(rhs_id)
	}
	return tc.resolve_type(rhs_id)
}

fn (mut tc TypeChecker) infer_fn_value_decl_type(rhs_id flat.NodeId) ?Type {
	if int(rhs_id) < 0 || int(rhs_id) >= tc.a.nodes.len {
		return none
	}
	rhs := tc.a.nodes[int(rhs_id)]
	if rhs.kind == .cast_expr {
		cast_type := tc.parse_type(rhs.value)
		if cast_type is OptionType || cast_type is ResultType {
			return none
		}
	}
	if tc.fn_value_shadowed_by_value(rhs) {
		return none
	}
	key := tc.fn_value_key(rhs) or { return none }
	typ := tc.fn_type_from_key(key) or { return none }
	tc.remember_resolved_fn_value_chain(rhs_id, key)
	tc.register_synth_type(rhs_id, typ)
	return typ
}

fn (tc &TypeChecker) fn_value_shadowed_by_value(node flat.Node) bool {
	match node.kind {
		.ident {
			return tc.name_bound_as_value(node.value)
		}
		.selector {
			return tc.selector_base_bound_as_value(node)
		}
		.cast_expr, .paren, .expr_stmt {
			if node.children_count == 0 {
				return false
			}
			return tc.fn_value_shadowed_by_value(tc.a.child_node(&node, 0))
		}
		else {
			return false
		}
	}
}

// lvalue_is_local_var reports whether an assignment target is safe to receive a method value:
// the blank discard `_` (stores nothing) or a plain function-local variable bound under its bare
// name in the current scope. Non-local storage (a struct field `h.cb`, an array/map element
// `cbs[i]`, or a module-level global, which lives in file_scope under its qualified name and so
// misses a bare lookup) is not. A method value may alias a local (tracked for a later escape) but
// must not be stored into anything that outlives the call site.
fn (tc &TypeChecker) lvalue_is_local_var(lhs_id flat.NodeId) bool {
	if int(lhs_id) < 0 {
		return false
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind != .ident || lhs.value.len == 0 {
		return false
	}
	if lhs.value == '_' {
		return true
	}
	return tc.cur_scope.lookup(lhs.value) != none
}

fn (tc &TypeChecker) selector_base_bound_as_value(node flat.Node) bool {
	if node.children_count == 0 {
		return false
	}
	base := tc.a.child_node(&node, 0)
	match base.kind {
		.ident {
			return tc.name_bound_as_value(base.value)
		}
		.selector {
			return tc.selector_base_bound_as_value(base)
		}
		.cast_expr, .paren, .expr_stmt {
			if base.children_count == 0 {
				return false
			}
			return tc.fn_value_shadowed_by_value(tc.a.child_node(base, 0))
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) name_bound_as_value(name string) bool {
	if name.len == 0 {
		return false
	}
	if typ := tc.cur_scope.lookup(name) {
		return typ !is Void
	}
	if typ := tc.file_scope.lookup(name) {
		return typ !is Void
	}
	return false
}

// check_multi_return_decl_assign validates check multi return decl assign state for types.
fn (mut tc TypeChecker) check_multi_return_decl_assign(id flat.NodeId, node flat.Node) bool {
	if node.children_count < 3 {
		return false
	}
	rhs_id := tc.a.child(&node, 1)
	rhs := tc.a.nodes[int(rhs_id)]
	lhs_ids := tc.multi_assign_lhs_ids(node)
	if tc.multi_assign_rhs_count(node) != 1 {
		return false
	}
	if lhs_ids.len > 1 {
		if call_name := tc.unresolved_multi_assign_method_call_name(rhs_id) {
			tc.check_node(rhs_id)
			if tc.should_diagnose(id) {
				tc.record_error_at(.assignment_mismatch,
					'assignment mismatch: ${lhs_ids.len} variables but `${call_name}()` returns 0 values',
					id, tc.assignment_operator_pos(node, lhs_ids[0], rhs_id))
			}
			for lhs_id in lhs_ids {
				tc.insert_decl_lhs(lhs_id, unknown_type('invalid variable'), tc.decl_lhs_is_mut(node,
					lhs_id))
			}
			tc.fn_context.continue_after_unknown_ident = true
			return true
		}
	}
	if lhs_ids.len > 1 && rhs.kind == .ident && !tc.lvalue_ident_is_known(rhs.value) {
		variables := if lhs_ids.len == 1 { 'variable' } else { 'variables' }
		tc.record_error_at(.assignment_mismatch,
			'assignment mismatch: ${lhs_ids.len} ${variables} 1 value', id, tc.assignment_operator_pos(node,
			lhs_ids[0], rhs_id))
		for lhs_id in lhs_ids {
			tc.insert_decl_lhs(lhs_id, unknown_type('invalid variable'), tc.decl_lhs_is_mut(node,
				lhs_id))
		}
		return true
	}
	if rhs.kind == .match_stmt {
		tc.check_node(rhs_id)
		if !tc.match_has_else_or_exhaustive_coverage(rhs) {
			if tc.should_diagnose(id) {
				tc.record_error(.assignment_mismatch,
					'match expression must be exhaustive for multi-return assignment', id)
			}
			return true
		}
		if rhs_types := tc.match_multi_return_types(rhs_id, lhs_ids.len) {
			tc.register_synth_type(rhs_id, MultiReturn{
				types: rhs_types
			})
			for i, lhs_id in lhs_ids {
				tc.insert_decl_lhs(lhs_id, rhs_types[i], tc.decl_lhs_is_mut(node, lhs_id))
			}
			$if ownership ? {
				tc.ownership_after_multi_return_decl_assign(lhs_ids, rhs_id, MultiReturn{
					types: rhs_types
				}, id)
			}
			return true
		}
		if tc.match_has_incompatible_multi_return_branches(rhs_id, lhs_ids.len) {
			if tc.should_diagnose(id) {
				tc.record_error(.assignment_mismatch,
					'multi-return assignment mismatch: expression branches must all produce ${lhs_ids.len} compatible values',
					id)
			}
			return true
		}
		// Tuple tails (`.a { c, '.zst', 'zstd' }`) resolve like if-expr branches.
		if rhs_types := tc.multi_expr_tail_types(rhs_id, lhs_ids.len) {
			tc.register_synth_type(rhs_id, MultiReturn{
				types: rhs_types
			})
			for i, lhs_id in lhs_ids {
				tc.insert_decl_lhs(lhs_id, rhs_types[i], tc.decl_lhs_is_mut(node, lhs_id))
			}
			$if ownership ? {
				tc.ownership_after_multi_return_decl_assign(lhs_ids, rhs_id, MultiReturn{
					types: rhs_types
				}, id)
			}
			return true
		}
		if tc.should_diagnose(id) {
			if tc.match_has_tuple_tail_values(rhs_id, lhs_ids.len) {
				tc.record_error(.assignment_mismatch,
					'match expression branches cannot produce multiple assignment values', id)
			} else {
				tc.record_error(.assignment_mismatch,
					'multi-return assignment mismatch: expression branches must all produce ${lhs_ids.len} compatible values',
					id)
			}
		}
		return true
	}
	if rhs.kind == .if_expr {
		tc.check_node(rhs_id)
		if rhs_types := tc.multi_expr_tail_types(rhs_id, lhs_ids.len) {
			tc.register_synth_type(rhs_id, MultiReturn{
				types: rhs_types
			})
			for i, lhs_id in lhs_ids {
				tc.insert_decl_lhs(lhs_id, rhs_types[i], tc.decl_lhs_is_mut(node, lhs_id))
			}
			$if ownership ? {
				tc.ownership_after_multi_return_decl_assign(lhs_ids, rhs_id, MultiReturn{
					types: rhs_types
				}, id)
			}
			return true
		}
		rhs_type := tc.resolve_type(rhs_id)
		if rhs_type !is MultiReturn || tc.expr_has_tuple_tail_values(rhs_id, lhs_ids.len) {
			if tc.should_diagnose(id) {
				tc.record_error(.assignment_mismatch,
					'multi-return assignment mismatch: expression branches must all produce ${lhs_ids.len} compatible values',
					id)
			}
			return true
		}
	}
	if rhs.kind == .lock_expr {
		tc.check_node(rhs_id)
		if rhs_types := tc.multi_expr_tail_types(rhs_id, lhs_ids.len) {
			tc.register_synth_type(rhs_id, MultiReturn{
				types: rhs_types
			})
			for i, lhs_id in lhs_ids {
				tc.insert_decl_lhs(lhs_id, rhs_types[i], tc.decl_lhs_is_mut(node, lhs_id))
			}
			$if ownership ? {
				tc.ownership_after_multi_return_decl_assign(lhs_ids, rhs_id, MultiReturn{
					types: rhs_types
				}, id)
			}
			return true
		}
	}
	mut rhs_type := tc.resolve_type(rhs_id)
	mut rhs_checked := false
	mut rhs_multi := MultiReturn{}
	mut found_multi := false
	mut unhandled_multi := false
	for _ in 0 .. 2 {
		if multi := tc.multi_return_assignment_type(rhs_id, rhs_type) {
			rhs_multi = multi
			found_multi = true
			break
		}
		if _ := tc.unhandled_wrapped_multi_return_type(rhs_id, rhs_type) {
			unhandled_multi = true
			break
		}
		if rhs_checked {
			break
		}
		tc.check_node(rhs_id)
		rhs_checked = true
		rhs_type = tc.resolve_type(rhs_id)
	}
	rhs_type_name := rhs_type.name()
	invalid_return_count := rhs_type is Unknown
		|| (rhs_type is MultiReturn && rhs_type.types.len == 0)
		|| rhs_type_name == 'unknown'
	if lhs_ids.len > 1 && invalid_return_count {
		if call_name := tc.assignment_rhs_call_name(rhs_id) {
			if tc.should_diagnose(id) {
				tc.record_error_at(.assignment_mismatch,
					'assignment mismatch: ${lhs_ids.len} variables but `${call_name}()` returns 0 values',
					id, tc.assignment_operator_pos(node, lhs_ids[0], rhs_id))
			}
			for lhs_id in lhs_ids {
				tc.insert_decl_lhs(lhs_id, unknown_type('invalid variable'), tc.decl_lhs_is_mut(node,
					lhs_id))
			}
			return true
		}
	}
	if unhandled_multi {
		if !rhs_checked {
			tc.check_node(rhs_id)
		}
		if tc.should_diagnose(id) {
			if rhs.kind == .call {
				handler := if rhs_type is OptionType { '?' } else { '!' }
				tc.record_error_at(.assignment_mismatch,
					'${tc.call_display_name(rhs)}() returns `${rhs_type_name}`, so it should have either an `or {}` block, or `${handler}` at the end',
					rhs_id, rhs.pos)
			} else {
				tc.record_error(.assignment_mismatch,
					'multi-return assignment from `${rhs_type_name}` requires `or {}`, `!`, or `?` handling',
					id)
			}
		}
		if wrapped_multi := multi_return_payload_type(rhs_type) {
			for i, lhs_id in lhs_ids {
				if i < wrapped_multi.types.len {
					tc.insert_decl_lhs(lhs_id, wrapped_multi.types[i], tc.decl_lhs_is_mut(node,
						lhs_id))
				}
			}
		}
		return true
	}
	if found_multi {
		if !rhs_checked {
			tc.check_node(rhs_id)
		}
		if lhs_ids.len != rhs_multi.types.len {
			if tc.should_diagnose(id) {
				tc.record_error(.assignment_mismatch,
					'multi-return assignment mismatch: ${lhs_ids.len} variables but `${rhs_type_name}` has ${rhs_multi.types.len} values',
					id)
			}
			return true
		}
		for i, lhs_id in lhs_ids {
			tc.insert_decl_lhs(lhs_id, rhs_multi.types[i], tc.decl_lhs_is_mut(node, lhs_id))
		}
		$if ownership ? {
			tc.ownership_after_multi_return_decl_assign(lhs_ids, rhs_id, rhs_multi, id)
		}
		return true
	}
	if lhs_ids.len > 1 {
		if !rhs_checked {
			tc.check_node(rhs_id)
		}
		if tc.should_diagnose(id) {
			tc.record_error(.assignment_mismatch,
				'multi-return assignment mismatch: ${lhs_ids.len} variables but `${rhs_type_name}` has 1 values',
				id)
		}
		return true
	}
	return false
}

fn (tc &TypeChecker) multi_expr_tail_types(expr_id flat.NodeId, count int) ?[]Type {
	groups := tc.multi_expr_tail_type_groups(expr_id, count) or { return none }
	if groups.len == 0 {
		return none
	}
	mut tail_types := []Type{cap: count}
	for typ in groups[0] {
		tail_types << typ
	}
	for i in 1 .. groups.len {
		group := groups[i]
		if group.len != tail_types.len {
			return none
		}
		for j, actual in group {
			promoted := tc.promoted_multi_tail_type(tail_types[j], actual) or { return none }
			tail_types[j] = promoted
		}
	}
	return tail_types
}

fn (tc &TypeChecker) multi_expr_tail_type_groups(expr_id flat.NodeId, count int) ?[][]Type {
	if count <= 0 || !tc.valid_node_id(expr_id) {
		return none
	}
	node := tc.a.nodes[int(expr_id)]
	match node.kind {
		.if_expr {
			if node.children_count < 3 {
				return none
			}
			mut groups := tc.multi_expr_branch_tail_type_groups(tc.a.child(&node, 1), count, false) or {
				return none
			}
			else_groups := tc.multi_expr_tail_type_groups(tc.a.child(&node, 2), count) or {
				return none
			}
			groups << else_groups
			return groups
		}
		.match_stmt {
			if node.children_count < 2 || !tc.match_has_else_or_exhaustive_coverage(node) {
				return none
			}
			mut groups := [][]Type{}
			for i in 1 .. node.children_count {
				branch_groups := tc.multi_expr_branch_tail_type_groups(tc.a.child(&node, i), count, true) or {
					return none
				}
				groups << branch_groups
			}
			return groups
		}
		.block, .match_branch {
			return tc.multi_expr_branch_tail_type_groups(expr_id, count, false)
		}
		.lock_expr {
			if node.children_count > 0 {
				return tc.multi_expr_tail_type_groups(tc.a.child(&node, node.children_count - 1),
					count)
			}
		}
		.expr_stmt {
			if node.children_count > 0 {
				return tc.multi_expr_tail_type_groups(tc.a.child(&node, 0), count)
			}
		}
		else {}
	}
	return none
}

fn (tc &TypeChecker) multi_expr_branch_tail_type_groups(branch_id flat.NodeId, count int, explicit_comma_tail bool) ?[][]Type {
	if groups := tc.tuple_tail_value_groups(branch_id, count, explicit_comma_tail) {
		mut result := [][]Type{cap: groups.len}
		for group in groups {
			mut types := []Type{cap: group.len}
			for value_id in group {
				typ := tc.expr_type(value_id) or { tc.resolve_type(value_id) }
				if !type_has_runtime_value(typ) {
					return none
				}
				types << typ
			}
			result << types
		}
		return result
	}
	tail_id := tc.branch_tail_expr_id(branch_id)
	if !tc.valid_node_id(tail_id) {
		return none
	}
	if tc.branch_tail_never_returns(branch_id) {
		return [][]Type{}
	}
	tail := tc.a.nodes[int(tail_id)]
	if tail.kind in [.if_expr, .match_stmt] {
		return tc.multi_expr_tail_type_groups(tail_id, count)
	}
	tail_type := tc.expr_type(tail_id) or { tc.resolve_type(tail_id) }
	multi := tc.multi_return_assignment_type(tail_id, tail_type) or { return none }
	if multi.types.len != count {
		return none
	}
	for typ in multi.types {
		if !type_has_runtime_value(typ) {
			return none
		}
	}
	return [multi.types.clone()]
}

fn (mut tc TypeChecker) multi_expr_tail_assign_types(id flat.NodeId, expr_id flat.NodeId, lhs_ids []flat.NodeId) ?[]Type {
	groups := tc.multi_expr_tail_value_groups(expr_id, lhs_ids.len, false) or { return none }
	if groups.len == 0 {
		return none
	}
	mut lhs_types := []Type{cap: lhs_ids.len}
	for lhs_id in lhs_ids {
		lhs_types << tc.resolve_lvalue_type(lhs_id)
	}
	for group in groups {
		if group.len != lhs_types.len {
			return none
		}
		for i, value_id in group {
			actual := tc.resolve_expr(value_id, lhs_types[i])
			if !tc.type_compatible(actual, lhs_types[i]) {
				tc.type_mismatch(.assignment_mismatch,
					'cannot assign `${actual.name()}` to `${lhs_types[i].name()}`', id)
			}
		}
	}
	return lhs_types
}

fn (tc &TypeChecker) match_multi_return_types(expr_id flat.NodeId, count int) ?[]Type {
	if count <= 0 || !tc.valid_node_id(expr_id) {
		return none
	}
	node := tc.a.nodes[int(expr_id)]
	if node.kind != .match_stmt || node.children_count < 2 {
		return none
	}
	if !tc.match_has_else_or_exhaustive_coverage(node) {
		return none
	}
	mut match_types := []Type{}
	mut saw_value_branch := false
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		if !tc.valid_node_id(branch_id) {
			continue
		}
		branch := tc.a.nodes[int(branch_id)]
		if branch.kind != .match_branch {
			continue
		}
		tail_id := tc.branch_tail_expr_id(branch_id)
		if !tc.valid_node_id(tail_id) {
			return none
		}
		tail := tc.a.nodes[int(tail_id)]
		if tail.kind == .return_stmt || tc.branch_tail_never_returns(branch_id) {
			continue
		}
		multi := multi_return_payload_type(tc.resolve_type(tail_id)) or { return none }
		if multi.types.len != count {
			return none
		}
		for typ in multi.types {
			if !type_has_runtime_value(typ) {
				return none
			}
		}
		if !saw_value_branch {
			match_types = multi.types.clone()
			saw_value_branch = true
			continue
		}
		for j, actual in multi.types {
			if actual.name() != match_types[j].name() {
				return none
			}
		}
	}
	if !saw_value_branch {
		return none
	}
	return match_types
}

fn (tc &TypeChecker) match_has_incompatible_multi_return_branches(expr_id flat.NodeId, count int) bool {
	if count <= 0 || !tc.valid_node_id(expr_id) {
		return false
	}
	node := tc.a.nodes[int(expr_id)]
	if node.kind != .match_stmt || node.children_count < 2 {
		return false
	}
	mut expected := []Type{}
	mut saw_value_branch := false
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		if !tc.valid_node_id(branch_id) {
			continue
		}
		tail_id := tc.branch_tail_expr_id(branch_id)
		if !tc.valid_node_id(tail_id) || tc.branch_tail_never_returns(branch_id) {
			continue
		}
		multi := multi_return_payload_type(tc.resolve_type(tail_id)) or { return false }
		if multi.types.len != count {
			return false
		}
		if !saw_value_branch {
			expected = multi.types.clone()
			saw_value_branch = true
			continue
		}
		for j, actual in multi.types {
			promoted := tc.promoted_multi_tail_type(expected[j], actual) or { return true }
			expected[j] = promoted
		}
	}
	return false
}

fn (tc &TypeChecker) match_has_tuple_tail_values(expr_id flat.NodeId, count int) bool {
	if count <= 0 || !tc.valid_node_id(expr_id) {
		return false
	}
	node := tc.a.nodes[int(expr_id)]
	if node.kind != .match_stmt || node.children_count < 2 {
		return false
	}
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		if groups := tc.tuple_tail_value_groups(branch_id, count, false) {
			if groups.len > 0 {
				return true
			}
		}
	}
	return false
}

fn (tc &TypeChecker) expr_has_noncomma_tuple_tail_values(expr_id flat.NodeId, count int) bool {
	if count <= 0 || !tc.valid_node_id(expr_id) {
		return false
	}
	node := tc.a.nodes[int(expr_id)]
	match node.kind {
		.if_expr {
			if node.children_count > 1
				&& tc.expr_has_noncomma_tuple_tail_values(tc.a.child(&node, 1), count) {
				return true
			}
			return node.children_count > 2
				&& tc.expr_has_noncomma_tuple_tail_values(tc.a.child(&node, 2), count)
		}
		.match_stmt {
			for i in 1 .. node.children_count {
				if tc.expr_has_noncomma_tuple_tail_values(tc.a.child(&node, i), count) {
					return true
				}
			}
		}
		.block, .match_branch {
			body_start := if node.kind == .match_branch {
				if node.value == 'else' { 0 } else { node.value.int() }
			} else {
				0
			}
			if node.children_count <= body_start {
				return false
			}
			last_id := tc.a.child(&node, node.children_count - 1)
			last := tc.a.nodes[int(last_id)]
			if last.kind in [.block, .match_branch, .if_expr, .match_stmt] {
				return tc.expr_has_noncomma_tuple_tail_values(last_id, count)
			}
			if node.value == 'comma_exprs' {
				return false
			}
			if groups := tc.tuple_tail_value_groups(expr_id, count, false) {
				if groups.len > 0 {
					return true
				}
			}
			return tc.expr_has_noncomma_tuple_tail_values(last_id, count)
		}
		.expr_stmt {
			return node.children_count > 0
				&& tc.expr_has_noncomma_tuple_tail_values(tc.a.child(&node, 0), count)
		}
		else {}
	}
	return false
}

fn (tc &TypeChecker) expr_has_tuple_tail_values(expr_id flat.NodeId, count int) bool {
	if count <= 0 || !tc.valid_node_id(expr_id) {
		return false
	}
	if groups := tc.tuple_tail_value_groups(expr_id, count, false) {
		if groups.len > 0 {
			return true
		}
	}
	node := tc.a.nodes[int(expr_id)]
	match node.kind {
		.if_expr {
			if node.children_count > 1 && tc.expr_has_tuple_tail_values(tc.a.child(&node, 1), count) {
				return true
			}
			return node.children_count > 2
				&& tc.expr_has_tuple_tail_values(tc.a.child(&node, 2), count)
		}
		.match_stmt {
			return tc.match_has_tuple_tail_values(expr_id, count)
		}
		.block, .match_branch {
			body_start := if node.kind == .match_branch {
				if node.value == 'else' { 0 } else { node.value.int() }
			} else {
				0
			}
			if node.children_count <= body_start {
				return false
			}
			return tc.expr_has_tuple_tail_values(tc.a.child(&node, node.children_count - 1), count)
		}
		.expr_stmt {
			return node.children_count > 0
				&& tc.expr_has_tuple_tail_values(tc.a.child(&node, 0), count)
		}
		else {
			return false
		}
	}
}

// multi_expr_tail_types_for_transform returns promoted multi-expression tail
// types for transform lowering without duplicating checker compatibility rules.
pub fn (tc &TypeChecker) multi_expr_tail_types_for_transform(expr_id flat.NodeId, count int) ?[]Type {
	return tc.multi_expr_tail_types(expr_id, count)
}

fn (tc &TypeChecker) promoted_multi_tail_type(current Type, actual Type) ?Type {
	if tc.type_compatible(actual, current) {
		return current
	}
	if tc.type_compatible(current, actual) {
		return actual
	}
	return none
}

fn (tc &TypeChecker) multi_expr_tail_value_groups(expr_id flat.NodeId, count int, explicit_comma_tail bool) ?[][]flat.NodeId {
	if count <= 0 || !tc.valid_node_id(expr_id) {
		return none
	}
	node := tc.a.nodes[int(expr_id)]
	match node.kind {
		.if_expr {
			if node.children_count < 3 {
				return none
			}
			mut groups := [][]flat.NodeId{}
			then_groups := tc.tuple_tail_value_groups(tc.a.child(&node, 1), count,
				explicit_comma_tail) or { return none }
			for group in then_groups {
				groups << group
			}
			else_id := tc.a.child(&node, 2)
			else_groups := tc.multi_expr_tail_value_groups(else_id, count, explicit_comma_tail) or {
				return none
			}
			for group in else_groups {
				groups << group
			}
			return groups
		}
		.match_stmt {
			if node.children_count < 2 || !tc.match_has_else_or_exhaustive_coverage(node) {
				return none
			}
			mut groups := [][]flat.NodeId{}
			for i in 1 .. node.children_count {
				branch_id := tc.a.child(&node, i)
				// Match multi-value tails must be comma expressions, not adjacent statements.
				branch_groups := tc.tuple_tail_value_groups(branch_id, count, true) or {
					return none
				}
				for group in branch_groups {
					groups << group
				}
			}
			return groups
		}
		.block, .match_branch {
			return tc.tuple_tail_value_groups(expr_id, count, explicit_comma_tail)
		}
		.lock_expr {
			if node.children_count > 0 {
				return tc.multi_expr_tail_value_groups(tc.a.child(&node, node.children_count - 1),
					count, explicit_comma_tail)
			}
		}
		.expr_stmt {
			if node.children_count > 0 {
				return tc.multi_expr_tail_value_groups(tc.a.child(&node, 0), count,
					explicit_comma_tail)
			}
		}
		else {}
	}

	return none
}

fn (tc &TypeChecker) wrapped_multi_return_value_groups(expr_id flat.NodeId, count int, explicit_comma_tail bool, wrapper Type) ?[][]flat.NodeId {
	if count <= 0 || !tc.valid_node_id(expr_id) {
		return none
	}
	node := tc.a.nodes[int(expr_id)]
	match node.kind {
		.if_expr {
			if node.children_count < 3 {
				return none
			}
			mut groups := [][]flat.NodeId{}
			then_groups := tc.wrapped_multi_return_branch_groups(tc.a.child(&node, 1), count,
				explicit_comma_tail, wrapper) or { return none }
			for group in then_groups {
				groups << group
			}
			else_id := tc.a.child(&node, 2)
			else_groups := tc.wrapped_multi_return_branch_groups(else_id, count,
				explicit_comma_tail, wrapper) or { return none }
			for group in else_groups {
				groups << group
			}
			return groups
		}
		.match_stmt {
			if node.children_count < 2 || !tc.match_has_else_or_exhaustive_coverage(node) {
				return none
			}
			mut groups := [][]flat.NodeId{}
			for i in 1 .. node.children_count {
				branch_groups := tc.wrapped_multi_return_branch_groups(tc.a.child(&node, i), count,
					true, wrapper) or { return none }
				for group in branch_groups {
					groups << group
				}
			}
			return groups
		}
		.block, .match_branch {
			return tc.wrapped_multi_return_branch_groups(expr_id, count, explicit_comma_tail,
				wrapper)
		}
		.lock_expr {
			if node.children_count > 0 {
				return tc.wrapped_multi_return_value_groups(tc.a.child(&node,
					node.children_count - 1), count, explicit_comma_tail, wrapper)
			}
		}
		.expr_stmt {
			if node.children_count > 0 {
				return tc.wrapped_multi_return_value_groups(tc.a.child(&node, 0), count,
					explicit_comma_tail, wrapper)
			}
		}
		else {}
	}

	return none
}

fn (tc &TypeChecker) wrapped_multi_return_branch_groups(branch_id flat.NodeId, count int, explicit_comma_tail bool, wrapper Type) ?[][]flat.NodeId {
	if !tc.valid_node_id(branch_id) {
		return none
	}
	if tc.wrapped_multi_return_tail_is_error(branch_id, wrapper) {
		return [][]flat.NodeId{}
	}
	return tc.multi_expr_tail_value_groups(branch_id, count, explicit_comma_tail)
}

fn (tc &TypeChecker) wrapped_multi_return_tail_is_error(branch_id flat.NodeId, wrapper Type) bool {
	if wrapper !is OptionType && wrapper !is ResultType {
		return false
	}
	tail_id := tc.branch_tail_expr_id(branch_id)
	if !tc.valid_node_id(tail_id) {
		return false
	}
	if tc.branch_tail_never_returns(branch_id) {
		return true
	}
	raw_type := tc.resolve_type(tail_id)
	return is_ierror_type(raw_type) || tc.type_compatible_with_ierror_payload(raw_type)
}

fn (tc &TypeChecker) tuple_tail_value_groups(body_id flat.NodeId, count int, explicit_comma_tail bool) ?[][]flat.NodeId {
	if count <= 0 || !tc.valid_node_id(body_id) {
		return none
	}
	body := tc.a.nodes[int(body_id)]
	body_start := if body.kind == .match_branch {
		if body.value == 'else' { 0 } else { body.value.int() }
	} else {
		0
	}
	if body.kind !in [.block, .match_branch] || body.children_count <= body_start {
		return none
	}
	last_id := tc.a.child(&body, body.children_count - 1)
	if tc.valid_node_id(last_id) {
		last := tc.a.nodes[int(last_id)]
		if last.kind in [.block, .match_branch, .if_expr, .match_stmt] {
			return tc.multi_expr_tail_value_groups(last_id, count, explicit_comma_tail)
		}
		if last.kind == .return_stmt {
			return [][]flat.NodeId{}
		}
		if tc.branch_tail_never_returns(body_id) {
			return [][]flat.NodeId{}
		}
	}
	is_comma_tail := body.value == 'comma_exprs'
	if explicit_comma_tail && !is_comma_tail {
		return none
	}
	mut values := []flat.NodeId{}
	for i := int(body.children_count) - 1; i >= body_start; i-- {
		child_id := tc.a.child(&body, i)
		if !tc.valid_node_id(child_id) {
			return none
		}
		child := tc.a.nodes[int(child_id)]
		if child.kind != .expr_stmt || child.children_count == 0 {
			if is_comma_tail {
				return none
			}
			break
		}
		for j := int(child.children_count) - 1; j >= 0; j-- {
			values.prepend(tc.a.child(&child, j))
			if !is_comma_tail && values.len == count {
				break
			}
		}
		if !is_comma_tail && values.len == count {
			mut groups := [][]flat.NodeId{}
			groups << values
			return groups
		}
	}
	if is_comma_tail && values.len == count {
		return [values]
	}
	return none
}

// multi_assign_lhs_ids supports multi assign lhs ids handling for TypeChecker.
fn (tc &TypeChecker) multi_assign_lhs_ids(node flat.Node) []flat.NodeId {
	lhs_count := tc.multi_assign_lhs_count(node)
	mut lhs_ids := []flat.NodeId{cap: lhs_count}
	for i in 0 .. lhs_count {
		lhs_ids << tc.multi_assign_lhs_id(node, i)
	}
	return lhs_ids
}

fn (tc &TypeChecker) multi_assign_lhs_count(node flat.Node) int {
	if node.value.is_int() {
		count := node.value.int()
		if count > 0 && count <= int(node.children_count) {
			return count
		}
	}
	if node.children_count <= 2 {
		return if node.children_count > 0 { 1 } else { 0 }
	}
	return int(node.children_count) - 1
}

fn (tc &TypeChecker) multi_assign_rhs_count(node flat.Node) int {
	lhs_count := tc.multi_assign_lhs_count(node)
	rhs_count := int(node.children_count) - lhs_count
	return if rhs_count > 0 { rhs_count } else { 0 }
}

fn (tc &TypeChecker) multi_assign_lhs_id(node flat.Node, index int) flat.NodeId {
	rhs_count := tc.multi_assign_rhs_count(node)
	child_index := if index < rhs_count { index * 2 } else { rhs_count + index }
	return tc.a.child(&node, child_index)
}

fn (tc &TypeChecker) multi_assign_rhs_id(node flat.Node, index int) flat.NodeId {
	lhs_count := tc.multi_assign_lhs_count(node)
	child_index := if index < lhs_count { index * 2 + 1 } else { lhs_count + index }
	return tc.a.child(&node, child_index)
}

// insert_decl_lhs updates insert decl lhs state for types.
fn (tc &TypeChecker) decl_lhs_is_mut(node flat.Node, lhs_id flat.NodeId) bool {
	if node.is_mut {
		return true
	}
	if int(lhs_id) < 0 || int(lhs_id) >= tc.a.nodes.len {
		return false
	}
	return tc.a.nodes[int(lhs_id)].is_mut
}

fn (mut tc TypeChecker) insert_decl_lhs(lhs_id flat.NodeId, typ Type, is_mut bool) ScopeBindingOwner {
	if int(lhs_id) < 0 || typ is Void {
		return ScopeBindingOwner{}
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind == .ident && lhs.value.len > 0 {
		if lhs.value != '_' && (tc.visible_local_scope_owns_name(lhs.value)
			|| tc.visible_mut_param_binding_owns_name(lhs.value)) {
			tc.record_error(.assignment_mismatch, 'redefinition of `${lhs.value}`', lhs_id)
			return ScopeBindingOwner{}
		}
		owner := tc.cur_scope.insert_with_owner(lhs.value, typ)
		if is_mut && lhs.value != '_' {
			tc.fn_context.mut_local_owners[lhs.value] = owner
		}
		tc.register_synth_type(lhs_id, typ)
		return owner
	}
	return ScopeBindingOwner{}
}

fn (tc &TypeChecker) visible_mut_param_binding_owns_name(name string) bool {
	param_owner := tc.fn_context.mut_param_owners[name] or { return false }
	owner := tc.cur_scope.lookup_owner(name) or { return false }
	return owner.scope == param_owner.scope && owner.index == param_owner.index
		&& owner.generation == param_owner.generation
}

fn (tc &TypeChecker) visible_local_scope_owns_name(name string) bool {
	if name.len == 0 || tc.cur_scope == unsafe { nil } {
		return false
	}
	scope := tc.cur_scope
	for i := scope.names.len - 1; i >= 0; i-- {
		if scope.names[i] == name {
			return true
		}
	}
	return false
}

// check_assign validates check assign state for types.
fn (mut tc TypeChecker) check_assign(id flat.NodeId, node flat.Node) {
	if node.children_count < 2 {
		return
	}
	if _ := tc.malformed_const_keyword_pos(id) {
		return
	}
	if node.kind == .index_assign && tc.reject_unlowered_map_mutation
		&& tc.index_assign_lhs_is_map(node) {
		if tc.should_diagnose(id) {
			tc.record_error(.assignment_mismatch,
				'internal compiler error: unlowered map index assignment reached post-transform checker',
				id)
		}
		for i := 1; i < node.children_count; i += 2 {
			tc.check_node(tc.a.child(&node, i))
		}
		return
	}
	if tc.check_assignment_marker(id, node) {
		return
	}
	if node.is_mut {
		lhs_id := tc.a.child(&node, 0)
		rhs_id := tc.a.child(&node, 1)
		tc.record_error_at(.assignment_mismatch, 'expecting `:=` (e.g. `mut x :=`)', id, tc.assignment_operator_pos(node,
			lhs_id, rhs_id))
		return
	}
	if tc.check_multi_return_assign(id, node) {
		return
	}
	mut i := 0
	mut ownership_lhs_ids := []flat.NodeId{}
	mut ownership_rhs_ids := []flat.NodeId{}
	mut ownership_lhs_types := []Type{}
	mut ownership_rhs_types := []Type{}
	mut smartcast_write_keys := []string{}
	for i + 1 < node.children_count {
		lhs_id := tc.a.child(&node, i)
		rhs_id := tc.a.child(&node, i + 1)
		lhs_node := tc.a.nodes[int(lhs_id)]
		effective_lhs_id := tc.unwrap_paren_expr_id(lhs_id)
		effective_lhs_node := tc.a.node(effective_lhs_id)
		if tc.record_invalid_literal_assign_lhs(lhs_id, node.op) {
			tc.check_node(rhs_id)
			i += 2
			continue
		}
		if node.kind == .index_assign && effective_lhs_node.kind == .index
			&& effective_lhs_node.value == 'range' {
			tc.check_node(rhs_id)
			tc.record_error_at(.assignment_mismatch,
				'cannot reassign using range expression on the left side of an assignment',
				effective_lhs_id, tc.index_brackets_pos(effective_lhs_node))
			i += 2
			continue
		}
		if effective_lhs_node.kind == .call {
			tc.check_node(effective_lhs_id)
			tc.check_node(rhs_id)
			callee := tc.a.child_node(effective_lhs_node, 0)
			name := if callee.value.len > 0 {
				callee.value
			} else {
				tc.source_text_for_node(effective_lhs_id)
			}
			tc.record_error_at(.assignment_mismatch,
				'cannot call function `${name}()` on the left side of an assignment',
				effective_lhs_id, effective_lhs_node.pos)
			i += 2
			continue
		}
		if effective_lhs_node.kind == .prefix && effective_lhs_node.op != .mul {
			tc.check_node(rhs_id)
			op := tc.source_text_for_node(effective_lhs_id).trim_space()[..1]
			message := if effective_lhs_node.op == .amp {
				'cannot use a reference on the left side of `=`'
			} else {
				'cannot use `${op}` on the left of `=`'
			}
			tc.record_error_at(.assignment_mismatch, message, effective_lhs_id, tc.prefix_operator_pos(effective_lhs_id,
				op))
			i += 2
			continue
		}
		if effective_lhs_node.kind == .prefix && effective_lhs_node.op == .mul
			&& effective_lhs_node.children_count > 0 {
			deref_child := tc.a.child_node(effective_lhs_node, 0)
			if deref_child.kind == .call {
				tc.record_error_at(.assignment_mismatch,
					'cannot dereference a function call on the left side of an assignment, use a temporary variable',
					effective_lhs_id, tc.prefix_operator_pos(effective_lhs_id, '*'))
			}
			if tc.unsafe_depth == 0 {
				tc.record_error_at(.assignment_mismatch,
					'modifying variables via dereferencing can only be done in `unsafe` blocks',
					id, tc.assignment_operator_pos(node, lhs_id, rhs_id))
			}
		}
		if lhs_node.kind == .selector && lhs_node.children_count > 0 {
			base_type := unalias_type(tc.resolve_type(tc.a.child(&lhs_node, 0)))
			if lhs_node.value == 'len' && (base_type is String || base_type is Array) {
				kind := if base_type is String { 'string' } else { 'array' }
				tc.check_node(rhs_id)
				tc.record_error_at(.assignment_mismatch, '`${kind}` can not be modified', lhs_id,
					tc.node_value_diagnostic_pos(lhs_id))
				i += 2
				continue
			}
		}
		if lhs_node.kind == .ident && lhs_node.value == '_' && node.op != .assign {
			tc.record_error_at(.assignment_mismatch, 'cannot modify blank `_` identifier', lhs_id,
				tc.node_value_diagnostic_pos(lhs_id))
			tc.check_node(rhs_id)
			i += 2
			continue
		}
		nonmut_smartcast_assignment := lhs_node.kind == .ident && lhs_node.value in tc.smartcasts
			&& !tc.ident_is_mutable_lvalue(lhs_node.value)
		unknown_assign_ident := lhs_node.kind == .ident && lhs_node.value != '_'
			&& !tc.lvalue_ident_is_known(lhs_node.value)
		if nonmut_smartcast_assignment {
			tc.record_error_at(.assignment_mismatch,
				'cannot mutate `${lhs_node.value}` in a non-mut smartcast, use `if mut ${lhs_node.value} ...`',
				lhs_id, tc.node_value_diagnostic_pos(lhs_id))
		} else if unknown_assign_ident {
			tc.record_error_at(.unknown_ident,
				'undefined ident: `${lhs_node.value}` (use `:=` to declare a variable)', lhs_id,
				tc.node_value_diagnostic_pos(lhs_id))
		} else {
			tc.check_lvalue_mutability(lhs_id)
		}
		lhs_type := if unknown_assign_ident {
			Type(void_)
		} else if node.kind == .index_assign {
			tc.resolve_index_lvalue_type(lhs_id, node.op)
		} else {
			tc.resolve_lvalue_type(lhs_id)
		}
		tc.remember_expr_type(lhs_id, lhs_type)
		expected_type := tc.assignment_expected_type(lhs_id, lhs_type)
		source_rhs_type := tc.resolve_type(rhs_id)
		tc.annotate_expected_expr(rhs_id, expected_type)
		$if ownership ? {
			if tc.ownership_should_defer_aggregate_consumption(lhs_id, node.op) {
				tc.ownership_begin_defer_aggregate_consumption(rhs_id)
				tc.check_node_with_expected_context(rhs_id, expected_type)
				tc.ownership_end_defer_aggregate_consumption(rhs_id)
			} else {
				tc.check_node_with_expected_context(rhs_id, expected_type)
			}
		} $else {
			tc.check_node_with_expected_context(rhs_id, expected_type)
		}
		if lhs_node.kind == .ident && tc.ident_is_mutable_lvalue(lhs_node.value) {
			tc.check_mutable_array_immutable_references(rhs_id)
		}
		tc.check_mutable_alias_assignment_lhs(lhs_id)
		rhs_node := tc.a.nodes[int(rhs_id)]
		if lhs_node.kind == .ident && lhs_node.value == '_' && rhs_node.kind == .none_expr {
			tc.record_error_at(.assignment_mismatch,
				'cannot assign a `none` value to blank `_` identifier', rhs_id, rhs_node.pos)
			i += 2
			continue
		}
		if lhs_node.kind == .index && lhs_node.children_count > 0
			&& unalias_type(tc.resolve_type(tc.a.child(&lhs_node, 0))) is String {
			tc.record_error_at(.assignment_mismatch,
				'cannot assign to s[i] since V strings are immutable\n(note, that variables may be mutable but string values are always immutable, like in Go and Java)',
				lhs_id, tc.decl_non_name_lhs_pos(lhs_id))
			i += 2
			continue
		}
		tc.check_const_reference_assignment(lhs_id, rhs_id, false)
		dynamic_array_to_fixed := unalias_type(expected_type) is ArrayFixed
			&& rhs_node.kind == .array_literal && rhs_node.typ.len == 0
		mut rhs_type := tc.resolve_expr(rhs_id, expected_type)
		if rhs_node.kind == .or_expr && type_contains_unknown(rhs_type)
			&& !type_contains_unknown(source_rhs_type) {
			rhs_type = source_rhs_type
		}
		if rhs_type is Void {
			if call_name := tc.assignment_rhs_call_name(rhs_id) {
				tc.record_error_at(.assignment_mismatch,
					'assignment mismatch: 1 variable but `${call_name}()` returns 0 values', id, tc.assignment_operator_pos(node,
					lhs_id, rhs_id))
				i += 2
				continue
			}
			if rhs_node.kind in [.if_expr, .match_stmt] {
				tc.record_error_at(.assignment_mismatch,
					'assignment mismatch: 1 variable 0 values', id, tc.assignment_operator_pos(node,
					lhs_id, rhs_id))
				i += 2
				continue
			}
		}
		if type_is_unsigned_integer(expected_type) && tc.expr_is_negative_integer_literal(rhs_id) {
			tc.record_error_at(.assignment_mismatch,
				'cannot assign negative value to unsigned integer type', rhs_id, rhs_node.pos)
			i += 2
			continue
		}
		if dynamic_array_to_fixed {
			lhs_name := tc.source_text_for_node(lhs_id)
			actual_type := if rhs_node.children_count > 0 {
				Type(Array{
					elem_type: tc.resolve_type(tc.a.child(&rhs_node, 0))
				})
			} else {
				Type(Array{
					elem_type: Type(void_)
				})
			}
			tc.record_error_with_details_at(.assignment_mismatch,
				'cannot assign to `${lhs_name}`: expected `${expected_type.name()}`, not `${actual_type.name()}`',
				rhs_id, rhs_node.pos, [
				'try adding `!` after the array literal, e.g.: `${lhs_name} = [...]!`',
			])
			i += 2
			continue
		}
		clean_expected_type := unalias_type(expected_type)
		clean_rhs_type := unalias_type(rhs_type)
		clean_source_rhs_type := unalias_type(source_rhs_type)
		if rhs_node.kind == .match_stmt && tc.expr_has_match_branch_type_error(rhs_id) {
			i += 2
			continue
		}
		if node.op == .assign && rhs_node.kind == .ident {
			if tc.unsafe_depth == 0 && ((clean_expected_type is Array && clean_rhs_type is Array
				&& lhs_node.kind == .ident)
				|| (clean_expected_type is Map && clean_rhs_type is Map)) {
				if !tc.ident_is_mutable_lvalue(rhs_node.value) {
					tc.record_notice_at(.assignment_mismatch,
						'left-side of assignment expects a mutable reference, but variable `${rhs_node.value}` is immutable, declare it with `mut` to make it mutable or clone it',
						rhs_id, rhs_node.pos)
				}
				if clean_expected_type is Array {
					tc.record_error_at(.assignment_mismatch,
						'use `array2 = array1.clone()` instead of `array2 = array1` (or use `unsafe`)',
						id, tc.assignment_operator_pos(node, lhs_id, rhs_id))
				} else {
					tc.record_error_at(.assignment_mismatch,
						'cannot copy map: call `move` or `clone` method (or use a reference)',
						rhs_id, rhs_node.pos)
				}
			} else if clean_source_rhs_type is ArrayFixed
				&& (clean_expected_type is Pointer || expected_type.name() == 'voidptr')
				&& !tc.ident_is_explicitly_mutable_lvalue(rhs_node.value) {
				tc.record_notice_at(.assignment_mismatch,
					'left-side of assignment expects a mutable reference, but variable `${rhs_node.value}` is immutable, declare it with `mut` to make it mutable or clone it',
					rhs_id, rhs_node.pos)
			}
		}
		if clean_expected_type is OptionType && tc.expr_tail_is_nil(rhs_id) {
			if lhs_node.kind == .ident {
				base_type := unalias_type(clean_expected_type.base_type)
				tc.record_warning_at(.assignment_mismatch,
					'cannot assign a reference to a value (this will be an error soon) left=${base_type.name()} false right=nil true ptr=false',
					id, tc.assignment_operator_pos(node, lhs_id, rhs_id))
			}
			tc.record_error_at(.assignment_mismatch, 'cannot assign `nil` to option value', rhs_id,
				tc.array_element_diagnostic_pos(rhs_id))
			i += 2
			continue
		}
		if tc.anonymous_struct_assignment_mismatch(rhs_id, rhs_type, expected_type) {
			tc.record_error_at(.assignment_mismatch,
				'cannot assign anonymous `struct` to a typed `struct`', rhs_id,
				tc.anonymous_struct_literal_brace_pos(rhs_id))
			i += 2
			continue
		}
		if tc.assignment_rhs_is_void_selector(rhs_id) {
			tc.record_error_at(.assignment_mismatch, 'assignment mismatch: 1 variable 0 values',
				id, tc.assignment_operator_pos(node, lhs_id, rhs_id))
			i += 2
			continue
		}
		if node.op != .assign && rhs_node.kind == .call && rhs_type is Unknown
			&& tc.expr_subtree_has_error(rhs_id) {
			call_name := tc.call_display_name(rhs_node)
			op_text := tc.compound_assignment_source_operator(lhs_id, rhs_id, node.op)
			tc.record_error_at(.assignment_mismatch,
				'assignment mismatch: 1 variable but `${call_name}()` returns 0 values', id, tc.compound_assignment_operator_pos(lhs_id,
				rhs_id, op_text))
			i += 2
			continue
		}
		if node.op != .assign {
			tc.record_compound_assignment_operand_errors(node.op, lhs_id, rhs_id, expected_type,
				rhs_type)
		}
		deref_pointer_mismatch := effective_lhs_node.kind == .prefix
			&& effective_lhs_node.op == .mul
			&& type_pointer_depth(expected_type) != type_pointer_depth(rhs_type)
			&& expected_type.name() != 'voidptr' && rhs_type.name() !in ['voidptr', 'nil']
		sum_variant_mismatch := if clean_expected_type is SumType {
			!tc.direct_sum_assignment_variant_matches(source_rhs_type, clean_expected_type)
		} else {
			false
		}
		invalid_comptime_selector_lhs := effective_lhs_node.kind == .selector
			&& effective_lhs_node.value == '$' && lhs_type is Void
		defer_open_generic_mismatch := tc.fn_context.generic_params.len > 0
			&& type_contains_unknown(rhs_type) && !invalid_comptime_selector_lhs
		if node.op == .assign && clean_rhs_type is ArrayFixed
			&& (clean_expected_type is Pointer || expected_type.name() == 'voidptr') {
			tc.record_error_at(.assignment_mismatch,
				'mismatched types `${expected_type.name()}` and `${rhs_type.name()}`', id, tc.assignment_operator_pos(node,
				lhs_id, rhs_id))
		}
		if deref_pointer_mismatch {
			tc.record_error_at(.assignment_mismatch,
				'cannot use `${rhs_type.name()}` (right side) as `${expected_type.name()}` (left side) in assignment',
				id, tc.assignment_operator_pos(node, lhs_id, rhs_id))
		} else if !defer_open_generic_mismatch && (sum_variant_mismatch
			|| !tc.assignment_types_compatible(rhs_id, rhs_type, expected_type, node.op)) {
			if clean_expected_type is Pointer && unalias_type(rhs_type) is Struct {
				tc.record_error_at(.assignment_mismatch,
					'mismatched types `${expected_type.name()}` and `${rhs_type.name()}`', id, tc.assignment_operator_pos(node,
					lhs_id, rhs_id))
			} else if unalias_type(rhs_type) is OptionType
				&& unalias_type(expected_type) !is OptionType && lhs_node.kind == .ident {
				tc.record_error_at(.assignment_mismatch,
					'cannot assign an Option value to a non-option variable', rhs_id,
					tc.array_element_diagnostic_pos(rhs_id))
			} else {
				lhs_source := if lhs_node.pos.is_valid() {
					tc.source_text_for_node(lhs_id)
				} else {
					''
				}
				lhs_name := if lhs_source.len > 0 {
					lhs_source
				} else {
					tc.assignment_lhs_source_text(node, lhs_id)
				}
				diagnostic_rhs_type := if sum_variant_mismatch {
					source_rhs_type
				} else if mut_base := tc.mut_param_expr_base(rhs_id, rhs_type) {
					mut_base
				} else {
					rhs_type
				}
				rhs_name := tc.diagnostic_expr_type_name(rhs_id, diagnostic_rhs_type)
				expected_name := expected_type.name().replace_once('fn(', 'fn (')
				diagnostic_id := if tc.should_diagnose(rhs_id) {
					rhs_id
				} else if tc.should_diagnose(lhs_id) {
					lhs_id
				} else {
					id
				}
				diagnostic_pos := if rhs_node.kind == .or_expr && rhs_node.children_count > 0
					&& tc.a.child_node(&rhs_node, 0).kind == .selector {
					selector_id := tc.a.child(&rhs_node, 0)
					tc.assignment_or_selector_diagnostic_pos(node, lhs_id, selector_id)
				} else if rhs_node.kind == .prefix && rhs_node.op == .amp
					&& rhs_node.children_count > 0
					&& tc.a.child_node(&rhs_node, 0).kind == .array_literal {
					tc.address_operator_pos(rhs_id)
				} else if rhs_node.kind == .prefix && rhs_node.op == .arrow {
					tc.prefix_operator_pos(rhs_id, '<-')
				} else if rhs_node.pos.is_valid() {
					tc.array_element_diagnostic_pos(rhs_id)
				} else {
					tc.assignment_rhs_diagnostic_pos(node, lhs_id, rhs_id)
				}
				message := if lhs_name.len == 0
					&& tc.assignment_source_line_contains_or_block(node, lhs_id) {
					'wrong return type `${rhs_name}` in the `or {}` block, expected `${expected_name}`'
				} else {
					'cannot assign to `${lhs_name}`: expected `${expected_name}`, not `${rhs_name}`'
				}
				tc.record_error_at(.assignment_mismatch, message, diagnostic_id, diagnostic_pos)
			}
		}
		if node.op == .power_assign && expected_type !is Unknown && rhs_type !is Unknown
			&& tc.should_diagnose(id) && (!infix_power_type_is_numeric(expected_type)
			|| !infix_power_type_is_numeric(rhs_type)) {
			_ := tc.infix_operator_return_type(.power, expected_type, rhs_type) or {
				tc.record_error(.assignment_mismatch,
					'operator `**=` requires numeric operands; got `${expected_type.name()}` and `${rhs_type.name()}`', id)
				Type(void_)
			}
		}
		$if ownership ? {
			tc.check_ownership_map_assignment_key(lhs_id, node.op)
			tc.check_ownership_uncloneable_overlapping_map_assignment(lhs_id, rhs_id, lhs_type,
				node.op, id)
			ownership_lhs_ids << lhs_id
			ownership_rhs_ids << rhs_id
			ownership_lhs_types << lhs_type
			ownership_rhs_types << rhs_type
		}
		if node.kind in [.assign, .selector_assign, .index_assign] {
			if tc.expr_is_method_value(rhs_id) && !tc.lvalue_is_local_var(lhs_id) {
				// Storing a method value into a struct field (`h.cb = ..`), an array/map element
				// (`cbs[i] = ..`), or a global lets it outlive the per-site static `_mvctx_N`
				// receiver slot, which the next evaluation of the same site overwrites — so every
				// stored callback would use the last receiver. Reject it like the other escapes.
				tc.reject_stored_method_value(rhs_id)
			} else {
				tc.track_method_value_local(lhs_id, rhs_id)
			}
			if tc.expr_is_capturing_fn_literal_value(rhs_id) && !tc.lvalue_is_local_var(lhs_id) {
				if node.kind == .index_assign {
					tc.reject_stored_capturing_fn_literal(rhs_id)
				} else {
					tc.reject_stored_or_returned_capturing_fn_literal(rhs_id)
				}
			} else {
				tc.track_capturing_fn_literal_local(lhs_id, rhs_id, ScopeBindingOwner{})
			}
			tc.track_variadic_fn_value_local(lhs_id, rhs_id)
		}
		lhs_key := tc.expr_key(lhs_id)
		if lhs_key.len > 0 {
			lhs := tc.a.node(lhs_id)
			if lhs.kind == .ident && expected_type is OptionType && rhs_type !is OptionType
				&& tc.expr_compatible(rhs_id, rhs_type, expected_type.base_type) {
				tc.smartcasts[lhs_key] = expected_type.base_type
			} else if !tc.assignment_preserves_smartcast(lhs_id, rhs_id, rhs_type) {
				smartcast_write_keys << lhs_key
			}
		}
		i += 2
	}
	for key in smartcast_write_keys {
		tc.invalidate_smartcasts_for_write_key(key)
	}
	$if ownership ? {
		tc.ownership_after_assign_pairs(ownership_lhs_ids, ownership_rhs_ids, ownership_lhs_types,
			ownership_rhs_types, node.op, id)
	} $else {
		_ = ownership_lhs_ids
		_ = ownership_rhs_ids
		_ = ownership_lhs_types
		_ = ownership_rhs_types
	}
}

fn (tc &TypeChecker) unwrap_paren_expr_id(id flat.NodeId) flat.NodeId {
	mut current_id := id
	for tc.valid_node_id(current_id) {
		current := tc.a.node(current_id)
		if current.kind != .paren || current.children_count == 0 {
			break
		}
		current_id = tc.a.child(current, 0)
	}
	return current_id
}

fn (mut tc TypeChecker) record_invalid_literal_assign_lhs(lhs_id flat.NodeId, op flat.Op) bool {
	mut diagnostic_id := lhs_id
	mut lhs := tc.a.node(lhs_id)
	if lhs.kind == .paren && lhs.children_count > 0 {
		diagnostic_id = tc.a.child(lhs, 0)
		lhs = tc.a.node(diagnostic_id)
	}
	if lhs.kind == .infix {
		op_text := infix_operator_name(lhs.op) or { '' }
		tc.record_error_at(.assignment_mismatch,
			'cannot use infix expression on the left side of `${assignment_operator_text(op)}`',
			diagnostic_id, tc.infix_operator_pos(lhs, op_text))
		if !tc.expr_subtree_contains_ident(diagnostic_id) {
			display := tc.source_text_for_node(diagnostic_id)
			tc.record_error_at(.assignment_mismatch,
				'non-name literal value `${display}` on left side of `${assignment_operator_text(op)}`',
				diagnostic_id, lhs.pos)
		}
		return true
	} else if lhs.kind !in [.int_literal, .float_literal, .bool_literal, .char_literal,
		.string_literal, .struct_init, .cast_expr] {
		return false
	}
	mut display := tc.source_text_for_node(diagnostic_id)
	if lhs.kind == .struct_init {
		display = '${lhs.value}{....}'
	}
	tc.record_error_at(.assignment_mismatch,
		'non-name literal value `${display}` on left side of `${assignment_operator_text(op)}`',
		diagnostic_id, lhs.pos)
	return true
}

fn (tc &TypeChecker) expr_subtree_contains_ident(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind == .ident {
		return true
	}
	for i in 0 .. node.children_count {
		if tc.expr_subtree_contains_ident(tc.a.child(node, i)) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) prefix_operator_pos(id flat.NodeId, op string) token.Pos {
	if !tc.valid_node_id(id) {
		return token.Pos{}
	}
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(node.pos.end, source.len)
	if start < end {
		if relative := source[start..end].index(op) {
			op_start := start + relative
			return token.new_span(node.pos.id, op_start, op_start + op.len)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) anonymous_struct_assignment_mismatch(expr_id flat.NodeId, actual Type, expected Type) bool {
	if !tc.valid_node_id(expr_id) {
		return false
	}
	expr := tc.a.nodes[int(expr_id)]
	if expr.kind != .struct_init {
		return false
	}
	expected_struct := struct_type_from_type(expected) or { return false }
	actual_is_anonymous := if actual_struct := struct_type_from_type(actual) {
		is_anonymous_struct_name(actual_struct.name)
	} else {
		false
	}
	return (is_anonymous_struct_name(expr.value) || actual_is_anonymous)
		&& !is_anonymous_struct_name(expected_struct.name)
}

fn (tc &TypeChecker) anonymous_struct_literal_brace_pos(id flat.NodeId) token.Pos {
	if !tc.valid_node_id(id) {
		return token.Pos{}
	}
	node := tc.a.nodes[int(id)]
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(node.pos.end, source.len)
	if start < end {
		if relative := source[start..end].index('{') {
			brace := start + relative
			return token.new_span(node.pos.id, brace, brace + 1)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) empty_map_literal_diagnostic_pos(id flat.NodeId) token.Pos {
	if !tc.valid_node_id(id) {
		return token.Pos{}
	}
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	anchor := int_min(int_max(node.pos.offset, 0), source.len)
	mut line_start := anchor
	for line_start > 0 && source[line_start - 1] != `\n` {
		line_start--
	}
	line_end := source.index_after('\n', anchor) or { source.len }
	if relative := source[line_start..line_end].last_index('{}') {
		start := line_start + relative
		return token.new_span(node.pos.id, start, start + 2)
	}
	return node.pos
}

fn (tc &TypeChecker) assignment_rhs_is_void_selector(rhs_id flat.NodeId) bool {
	if !tc.valid_node_id(rhs_id) {
		return false
	}
	rhs := tc.a.nodes[int(rhs_id)]
	if rhs.kind != .selector || rhs.children_count == 0 {
		return false
	}
	base_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(&rhs, 0)))
	if base_type is Struct && tc.embedded_field_candidates(base_type.name, rhs.value).len > 1 {
		return true
	}
	return base_type is Void || tc.resolve_type(rhs_id) is Void
		|| (base_type !is Unknown && tc.selector_type(rhs_id, rhs) == none)
}

fn (tc &TypeChecker) unknown_imported_enum_selector(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind != .selector || node.children_count == 0 {
		return false
	}
	base := tc.a.child_node(node, 0)
	if base.kind != .selector || base.children_count == 0 || base.value.len == 0
		|| !base.value[0].is_capital() {
		return false
	}
	module_node := tc.a.child_node(base, 0)
	if module_node.kind != .ident || !tc.has_active_import(module_node.value) {
		return false
	}
	module_name := tc.resolve_import_alias(module_node.value) or { module_node.value }
	return tc.resolve_enum_name('${module_name}.${base.value}') == none
}

fn (tc &TypeChecker) assignment_operator_pos(node flat.Node, lhs_id flat.NodeId, rhs_id flat.NodeId) token.Pos {
	if !tc.valid_node_id(lhs_id) || !tc.valid_node_id(rhs_id) {
		return node.pos
	}
	lhs := tc.a.nodes[int(lhs_id)]
	rhs := tc.a.nodes[int(rhs_id)]
	file := tc.a.source_files[lhs.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, lhs.pos.end)
	end := int_min(rhs.pos.offset, source.len)
	if start < end {
		if relative := source[start..end].index(':=') {
			op_start := start + relative
			return token.new_span(lhs.pos.id, op_start, op_start + 2)
		}
		if relative := source[start..end].index('=') {
			op_start := start + relative
			return token.new_span(lhs.pos.id, op_start, op_start + 1)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) assignment_rhs_diagnostic_pos(node flat.Node, lhs_id flat.NodeId, rhs_id flat.NodeId) token.Pos {
	if tc.valid_node_id(rhs_id) {
		rhs := tc.a.node(rhs_id)
		if rhs.kind == .prefix && rhs.op == .arrow {
			return tc.prefix_operator_pos(rhs_id, '<-')
		}
		if rhs.pos.is_valid() {
			return tc.array_element_diagnostic_pos(rhs_id)
		}
	}
	line_pos := tc.assignment_source_line_pos(node, lhs_id) or { return node.pos }
	file := tc.a.source_files[line_pos.id] or { return line_pos }
	source := tc.source_texts_by_file[file.name] or { return line_pos }
	line := source[line_pos.offset..line_pos.end]
	op_relative := line.index('=') or { return line_pos }
	mut start := line_pos.offset + op_relative + 1
	for start < line_pos.end && source[start] in [` `, `\t`] {
		start++
	}
	mut end := line_pos.end
	for end > start && source[end - 1] in [` `, `\t`, `\r`, `\n`] {
		end--
	}
	if relative := source[start..end].index('[') {
		bracket_start := start + relative
		if close := source[bracket_start..end].index(']') {
			return token.new_span(line_pos.id, bracket_start, bracket_start + close + 1)
		}
	}
	return token.new_span(line_pos.id, start, end)
}

fn (tc &TypeChecker) assignment_or_selector_diagnostic_pos(node flat.Node, lhs_id flat.NodeId, selector_id flat.NodeId) token.Pos {
	line_pos := tc.assignment_source_line_pos(node, lhs_id) or { return node.pos }
	file := tc.a.source_files[line_pos.id] or { return line_pos }
	source := tc.source_texts_by_file[file.name] or { return line_pos }
	line := source[line_pos.offset..line_pos.end]
	op_relative := line.index('=') or { return line_pos }
	mut diagnostic_selector_id := selector_id
	for {
		current := tc.a.node(diagnostic_selector_id)
		if current.kind != .selector || current.value !in ['ok', 'value']
			|| current.children_count == 0 {
			break
		}
		base_id := tc.a.child(current, 0)
		base := tc.a.node(base_id)
		if base.kind != .selector {
			break
		}
		diagnostic_selector_id = base_id
	}
	selector := tc.a.node(diagnostic_selector_id)
	mut needle := selector.value
	mut value_offset := 0
	if selector.children_count > 0 {
		base := tc.a.child_node(selector, 0)
		if base.kind == .ident && base.value.len > 0 {
			needle = '${base.value}.${selector.value}'
			value_offset = base.value.len + 1
		}
	}
	rhs_start := line_pos.offset + op_relative + 1
	relative := source[rhs_start..line_pos.end].index(needle) or { return line_pos }
	start := rhs_start + relative + value_offset
	lhs := tc.a.node(lhs_id)
	reported_column := if lhs.pos.is_valid() && lhs.pos.offset >= line_pos.offset {
		source[line_pos.offset..lhs.pos.offset].replace('\t', '    ').len + 1
	} else {
		0
	}
	return token.new_span(line_pos.id, start, start + selector.value.len).with_reported_column(reported_column)
}

fn (tc &TypeChecker) assignment_lhs_source_text(node flat.Node, lhs_id flat.NodeId) string {
	if tc.valid_node_id(lhs_id) {
		lhs := tc.a.node(lhs_id)
		if lhs.pos.is_valid() {
			return tc.source_text_for_node(lhs_id)
		}
	}
	line_pos := tc.assignment_source_line_pos(node, lhs_id) or { return '' }
	file := tc.a.source_files[line_pos.id] or { return '' }
	source := tc.source_texts_by_file[file.name] or { return '' }
	line := source[line_pos.offset..line_pos.end]
	op_relative := line.index('=') or { return '' }
	return line[..op_relative].trim_space()
}

fn (tc &TypeChecker) assignment_source_line_contains_or_block(node flat.Node, lhs_id flat.NodeId) bool {
	line_pos := tc.assignment_source_line_pos(node, lhs_id) or { return false }
	file := tc.a.source_files[line_pos.id] or { return false }
	source := tc.source_texts_by_file[file.name] or { return false }
	return source[line_pos.offset..line_pos.end].contains('or {')
}

fn (tc &TypeChecker) assignment_source_line_pos(node flat.Node, lhs_id flat.NodeId) ?token.Pos {
	mut source_pos := node.pos
	if tc.valid_node_id(lhs_id) {
		lhs := tc.a.node(lhs_id)
		if lhs.pos.is_valid() {
			source_pos = lhs.pos
		}
	}
	if !source_pos.is_valid() {
		return none
	}
	file := tc.a.source_files[source_pos.id] or { return none }
	source := tc.source_texts_by_file[file.name] or { return none }
	mut cursor := int_min(int_max(source_pos.offset, 0), source.len)
	for _ in 0 .. 4 {
		line_start := if relative := source[..cursor].last_index('\n') {
			relative + 1
		} else {
			0
		}
		line_end := source.index_after('\n', line_start) or { source.len }
		if source[line_start..line_end].contains('=') {
			return token.new_span(source_pos.id, line_start, line_end)
		}
		if line_start == 0 {
			break
		}
		cursor = line_start - 1
	}
	return none
}

fn (mut tc TypeChecker) record_compound_assignment_operand_errors(op flat.Op, lhs_id flat.NodeId, rhs_id flat.NodeId, lhs_type Type, rhs_type Type) {
	mut op_text := tc.compound_assignment_source_operator(lhs_id, rhs_id, op)
	if op_text.len == 0 {
		return
	}
	lhs_binding_name := tc.pointer_diagnostic_binding_type_name(lhs_id, lhs_type)
	if op in [.plus_assign, .minus_assign] && unalias_type(lhs_type) is Pointer
		&& lhs_binding_name !in ['voidptr', 'nil']
		&& (rhs_type.is_integer() || tc.a.node(rhs_id).kind == .int_literal) {
		lhs := tc.a.node(lhs_id)
		is_implicitly_dereferenced_mut_param := lhs.kind == .ident
			&& lhs.value in tc.fn_context.mut_param_base_types
		if tc.unsafe_depth == 0 && !tc.translated_files[tc.cur_file]
			&& !is_implicitly_dereferenced_mut_param {
			tc.record_warning_at(.assignment_mismatch,
				'pointer arithmetic is only allowed in `unsafe` blocks', lhs_id, tc.compound_assignment_operator_pos(lhs_id,
				rhs_id, op_text))
		}
		return
	}
	if infix_op := compound_assignment_infix_op(op) {
		if signature := tc.infix_operator_signature(infix_op, lhs_type) {
			lhs_name := unwrap_pointer(lhs_type).name()
			if signature.param_count < 2 {
				message := if op in [.plus_assign, .minus_assign] {
					'operator `${op_text}` not defined on left operand type `${lhs_name}`'
				} else {
					'operator ${op_text} not defined on left operand type `${lhs_name}`'
				}
				tc.record_error(.assignment_mismatch, message, lhs_id)
				if signature.return_type.name() != lhs_name {
					operator_name := infix_operator_name(infix_op) or { '' }
					tc.record_error_at(.assignment_mismatch,
						'operator `${operator_name}` must return `${lhs_name}` to be used as an assignment operator',
						lhs_id, tc.compound_assignment_operator_pos(lhs_id, rhs_id, op_text))
				}
				return
			}
			rhs := tc.a.node(rhs_id)
			rhs_is_literal := rhs.kind in [.int_literal, .float_literal, .char_literal,
				.string_literal, .bool_literal]
			operand_matches := rhs_type.name() == signature.param_type.name()
				|| (rhs_is_literal && tc.type_compatible(rhs_type, signature.param_type))
			if operand_matches {
				if signature.return_type.name() != lhs_name {
					operator_name := infix_operator_name(infix_op) or { '' }
					tc.record_error_at(.assignment_mismatch,
						'operator `${operator_name}` must return `${lhs_name}` to be used as an assignment operator',
						lhs_id, tc.compound_assignment_operator_pos(lhs_id, rhs_id, op_text))
				}
				return
			}
			if lhs_type is Alias && rhs_type is Alias && lhs_type.name != rhs_type.name
				&& tc.assignment_types_compatible(rhs_id, rhs_type, lhs_type, op) {
				lhs_text := tc.source_text_for_node(lhs_id)
				tc.record_error_at(.assignment_mismatch,
					'cannot assign to `${lhs_text}`: expected `${lhs_type.name}`, not `${rhs_type.name}`',
					rhs_id, tc.array_element_diagnostic_pos(rhs_id))
			}
			return
		}
	}
	if op_text in ['&&=', '||='] {
		if unalias_type(lhs_type) !is Primitive
			|| !(unalias_type(lhs_type) as Primitive).props.has(.boolean) {
			tc.record_error(.assignment_mismatch,
				'operator ${op_text} not defined on left operand type `${lhs_type.name()}`', lhs_id)
			return
		}
	}
	if op == .minus_assign && (array_type_from_receiver(lhs_type) != none
		|| map_type_from_receiver(unalias_type(lhs_type)) != none) {
		tc.record_error_at(.assignment_mismatch,
			'undefined operation `${lhs_type.name()}` - `${rhs_type.name()}`', lhs_id, tc.compound_assignment_operator_pos(lhs_id,
			rhs_id, op_text))
		return
	}
	lhs_name := lhs_binding_name
	rhs_name := tc.diagnostic_expr_type_name(rhs_id, rhs_type)
	rhs_node := tc.a.node(rhs_id)
	rhs_is_integer := rhs_type.is_integer() || rhs_node.kind == .int_literal
	lhs_is_primitive_alias := lhs_type is Alias
		&& (unalias_type(lhs_type) is Primitive || unalias_type(lhs_type) is String)
	rhs_is_primitive_alias := rhs_type is Alias
		&& (unalias_type(rhs_type) is Primitive || unalias_type(rhs_type) is String)
	lhs_supports := match op {
		.plus_assign {
			infix_power_type_is_numeric(lhs_type) || lhs_name == 'string'
				|| lhs_name == 'rune' || (unalias_type(lhs_type) is Pointer
				&& lhs_name !in ['voidptr', 'nil'] && rhs_is_integer)
				|| lhs_is_primitive_alias
		}
		.minus_assign, .mul_assign, .div_assign, .mod_assign {
			infix_power_type_is_numeric(lhs_type)
				|| (op == .minus_assign && unalias_type(lhs_type) is Pointer
				&& lhs_name !in ['voidptr', 'nil'] && rhs_is_integer)
				|| lhs_is_primitive_alias
		}
		.amp_assign, .pipe_assign, .xor_assign, .left_shift_assign, .right_shift_assign,
		.right_shift_unsigned_assign {
			lhs_type.is_integer()
		}
		else {
			true
		}
	}
	if !lhs_supports {
		if lhs_type is Unknown && tc.fn_context.generic_params.len > 0 {
			return
		}
		message := if op in [.plus_assign, .minus_assign] {
			'operator `${op_text}` not defined on left operand type `${lhs_name}`'
		} else {
			'operator ${op_text} not defined on left operand type `${lhs_name}`'
		}
		tc.record_error(.assignment_mismatch, message, lhs_id)
	}
	if !lhs_supports && tc.assignment_types_compatible(rhs_id, rhs_type, lhs_type, op) {
		return
	}
	rhs_supports := match op {
		.plus_assign {
			if lhs_name == 'string' {
				rhs_name in ['string', 'rune']
			} else {
				infix_power_type_is_numeric(rhs_type) || rhs_is_primitive_alias
			}
		}
		.minus_assign {
			lhs_name != 'string'
				&& (infix_power_type_is_numeric(rhs_type) || rhs_is_primitive_alias)
		}
		.mul_assign, .div_assign, .mod_assign {
			infix_power_type_is_numeric(rhs_type) || rhs_is_primitive_alias
		}
		.amp_assign, .pipe_assign, .xor_assign, .left_shift_assign, .right_shift_assign,
		.right_shift_unsigned_assign {
			rhs_is_integer
		}
		else {
			true
		}
	}
	if rhs_supports {
		return
	}
	if op in [.plus_assign, .minus_assign] {
		tc.record_error(.assignment_mismatch,
			'invalid right operand: ${lhs_name} ${op_text} ${rhs_name}', rhs_id)
	} else {
		tc.record_error(.assignment_mismatch,
			'operator ${op_text} not defined on right operand type `${rhs_name}`', rhs_id)
	}
}

fn (tc &TypeChecker) pointer_diagnostic_binding_type_name(id flat.NodeId, typ Type) string {
	type_name := typ.name()
	if !tc.valid_node_id(id) {
		return type_name
	}
	node := tc.a.node(id)
	if node.kind != .ident || node.value.len == 0 || !node.pos.is_valid() {
		return type_name
	}
	file := tc.a.source_files[node.pos.id] or { return type_name }
	source := tc.source_texts_by_file[file.name] or { return type_name }
	end := int_min(int_max(node.pos.offset, 0), source.len)
	needle := '${node.value} := nil'
	if source[..end].last_index(needle) != none {
		return 'nil'
	}
	decl_needle := '${node.value} :='
	if decl_start := source[..end].last_index(decl_needle) {
		decl_end := source.index_after('\n', decl_start) or { end }
		if source[decl_start..int_min(decl_end, end)].contains('nil') {
			return 'nil'
		}
		if source[decl_start..int_min(decl_end, end)].contains('voidptr(') {
			return 'voidptr'
		}
	}
	return type_name
}

fn (tc &TypeChecker) compound_assignment_source_operator(lhs_id flat.NodeId, rhs_id flat.NodeId, op flat.Op) string {
	fallback := assignment_operator_text(op)
	if op !in [.amp_assign, .pipe_assign] || !tc.valid_node_id(lhs_id) || !tc.valid_node_id(rhs_id) {
		return fallback
	}
	lhs := tc.a.node(lhs_id)
	rhs := tc.a.node(rhs_id)
	file := tc.a.source_files[lhs.pos.id] or { return fallback }
	source := tc.source_texts_by_file[file.name] or { return fallback }
	start := int_max(0, lhs.pos.end)
	end := int_min(rhs.pos.offset, source.len)
	if start < end {
		between := source[start..end]
		if between.contains('&&=') {
			return '&&='
		}
		if between.contains('||=') {
			return '||='
		}
	}
	return fallback
}

fn (tc &TypeChecker) compound_assignment_operator_pos(lhs_id flat.NodeId, rhs_id flat.NodeId, op string) token.Pos {
	if !tc.valid_node_id(lhs_id) || !tc.valid_node_id(rhs_id) {
		return token.Pos{}
	}
	lhs := tc.a.nodes[int(lhs_id)]
	rhs := tc.a.nodes[int(rhs_id)]
	file := tc.a.source_files[lhs.pos.id] or { return lhs.pos }
	source := tc.source_texts_by_file[file.name] or { return lhs.pos }
	start := int_max(0, lhs.pos.end)
	end := int_min(rhs.pos.offset, source.len)
	if start < end {
		if relative := source[start..end].index(op) {
			op_start := start + relative
			return token.new_span(lhs.pos.id, op_start, op_start + op.len)
		}
	}
	return lhs.pos
}

fn (tc &TypeChecker) diagnostic_expr_type_name(id flat.NodeId, typ Type) string {
	if unalias_type(typ) is FnType {
		if display := tc.expr_diagnostic_fn_type(id) {
			return display
		}
	}
	return match tc.a.node(id).kind {
		.int_literal { 'int literal' }
		.float_literal { 'float literal' }
		else { tc.diagnostic_type_name(typ).replace_once('fn(', 'fn (') }
	}
}

fn (tc &TypeChecker) diagnostic_type_name(typ Type) string {
	raw := typ.name()
	if !raw.contains('.') {
		return raw
	}
	prefix := raw.all_before('.')
	info := tc.current_file_import_info()
	if isnil(info) {
		return raw
	}
	for _, module_path in info.imports {
		if module_path.contains('.') && module_path.all_after_last('.') == prefix {
			return module_path + raw[prefix.len..]
		}
	}
	for idx in tc.top_level_idx {
		node := tc.a.nodes[idx]
		if node.kind != .import_decl {
			continue
		}
		source_file := tc.a.source_files[node.pos.id] or { continue }
		if source_file.name != tc.cur_file {
			continue
		}
		module_path := tc.import_module_path_text(node)
		if module_path.contains('.') && module_path.all_after_last('.') == prefix {
			return module_path + raw[prefix.len..]
		}
	}
	return raw
}

fn assignment_operator_text(op flat.Op) string {
	return match op {
		.assign { '=' }
		.plus_assign { '+=' }
		.minus_assign { '-=' }
		.mul_assign { '*=' }
		.div_assign { '/=' }
		.mod_assign { '%=' }
		.amp_assign { '&=' }
		.pipe_assign { '|=' }
		.xor_assign { '^=' }
		.left_shift_assign { '<<=' }
		.right_shift_assign { '>>=' }
		.right_shift_unsigned_assign { '>>>=' }
		.power_assign { '**=' }
		else { '' }
	}
}

fn compound_assignment_infix_op(op flat.Op) ?flat.Op {
	return match op {
		.plus_assign { flat.Op.plus }
		.minus_assign { flat.Op.minus }
		.mul_assign { flat.Op.mul }
		.div_assign { flat.Op.div }
		.mod_assign { flat.Op.mod }
		.amp_assign { flat.Op.amp }
		.pipe_assign { flat.Op.pipe }
		.xor_assign { flat.Op.xor }
		.left_shift_assign { flat.Op.left_shift }
		.right_shift_assign { flat.Op.right_shift }
		.right_shift_unsigned_assign { flat.Op.right_shift_unsigned }
		.power_assign { flat.Op.power }
		else { none }
	}
}

fn (tc &TypeChecker) source_text_for_node(id flat.NodeId) string {
	if !tc.valid_node_id(id) {
		return ''
	}
	node := tc.a.nodes[int(id)]
	file := tc.a.source_files[node.pos.id] or { return node.value }
	source := tc.source_texts_by_file[file.name] or { return node.value }
	start := int_max(0, int_min(node.pos.offset, source.len))
	end := int_max(start, int_min(node.pos.end, source.len))
	if end <= start {
		return node.value
	}
	return source[start..end].trim_space()
}

fn (mut tc TypeChecker) check_import_symbol_conflict(id flat.NodeId, name string) {
	if name.len == 0 || name == '_' || !tc.has_active_import(name) {
		return
	}
	tc.check_import_symbol_conflict_at(id, name, tc.node_value_diagnostic_pos(id))
}

fn (mut tc TypeChecker) check_import_symbol_conflict_at(id flat.NodeId, name string, pos token.Pos) {
	if name.len == 0 || name == '_' || !tc.has_active_import(name) {
		return
	}
	tc.record_error_at(.duplicate_decl, 'duplicate of an import symbol `${name}`', id, pos)
}

fn (mut tc TypeChecker) check_module_name_conflict(id flat.NodeId, name string) {
	if name.len == 0 || name == '_' {
		return
	}
	if name == tc.cur_module {
		tc.record_error_at(.duplicate_decl, 'duplicate of a module name `${name}`', id,
			tc.node_value_diagnostic_pos(id))
	}
	tc.check_imported_module_prefix(id, name, '')
}

fn (tc &TypeChecker) imported_module_prefix(id flat.NodeId, name string) ?string {
	if !tc.valid_node_id(id) || !name.contains('__') {
		return none
	}
	node := tc.a.node(id)
	if !node.pos.is_valid() {
		return none
	}
	file := tc.a.source_files[node.pos.id] or { return none }
	if tc.diagnostic_files.len > 0 && file.name !in tc.diagnostic_files {
		return none
	}
	prefix := name.all_before('__')
	if prefix == 'builtin' {
		return prefix
	}
	info := tc.file_imports_by_file[file.name] or { return none }
	for alias, module_name in info.imports {
		if prefix == alias || prefix == module_name.all_after_last('.') {
			return prefix
		}
	}
	return none
}

fn (mut tc TypeChecker) check_imported_module_prefix(id flat.NodeId, name string, keyword string) {
	prefix := tc.imported_module_prefix(id, name) or { return }
	pos := if keyword.len > 0 {
		tc.fn_declaration_diagnostic_pos(tc.a.node(id))
	} else {
		tc.node_value_diagnostic_pos(id)
	}
	tc.record_error_at(.duplicate_decl,
		'identifier cannot use prefix `${prefix}__` of imported module `${prefix}`', id, pos)
}

fn (tc &TypeChecker) source_module_declares_fn(name string) bool {
	mut module_name := ''
	for index in tc.top_level_idx {
		node := tc.a.nodes[index]
		if node.kind == .file {
			module_name = ''
		} else if node.kind == .module_decl {
			module_name = node.value
		} else if node.kind == .fn_decl
			&& (module_name == tc.cur_module || (module_name == '' && tc.cur_module == 'main'))
			&& node.value == name && !local_fn_decl_is_transform_created(node.value) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) fn_receiver_param_diagnostic_pos(node flat.Node, name string) token.Pos {
	header_pos := tc.fn_declaration_diagnostic_pos(node)
	file := tc.a.source_files[header_pos.id] or { return header_pos }
	source := tc.source_texts_by_file[file.name] or { return header_pos }
	if header_pos.offset < 0 || header_pos.end > source.len || header_pos.end <= header_pos.offset {
		return header_pos
	}
	header := source[header_pos.offset..header_pos.end]
	open := header.index_u8(`(`)
	close := header.index_u8(`)`)
	if open < 0 || close <= open {
		return header_pos
	}
	receiver := header[open + 1..close]
	relative := receiver.index(name) or { return header_pos }
	start := header_pos.offset + open + 1 + relative
	return token.new_span(header_pos.id, start, start + name.len)
}

fn (tc &TypeChecker) fn_option_receiver_diagnostic_pos(node flat.Node, name string) token.Pos {
	name_pos := tc.fn_receiver_param_diagnostic_pos(node, name)
	file := tc.a.source_files[name_pos.id] or { return name_pos }
	source := tc.source_texts_by_file[file.name] or { return name_pos }
	end := int_min(source.len, name_pos.end + 2)
	if name_pos.end < end && source[name_pos.end..end].contains('?') {
		return token.new_span(name_pos.id, name_pos.offset, end)
	}
	return name_pos
}

fn (mut tc TypeChecker) check_compound_index_assignment_getter(assign_id flat.NodeId, lhs_id flat.NodeId, op flat.Op) {
	if !assignment_op_reads_lhs(op) || int(lhs_id) < 0 {
		return
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind != .index || lhs.children_count == 0 {
		return
	}
	base_id := tc.a.child(&lhs, 0)
	base_type_raw := tc.resolve_type(base_id)
	if setter := tc.index_overload_call_info(base_type_raw, true) {
		if getter := tc.index_overload_call_info(base_type_raw, false) {
			err_count := tc.errors.len
			tc.check_index_overload_args(lhs_id, lhs, getter)
			if tc.errors.len != err_count {
				return
			}
			if !tc.compound_index_overload_index_params_match(setter, getter) {
				if tc.should_diagnose(lhs_id) {
					tc.record_error(.assignment_mismatch,
						'compound overloaded index assignment requires matching `[]` and `[]=` index parameter types',
						assign_id)
				}
				return
			}
			if !tc.compound_index_overload_value_params_match(setter, getter) {
				if tc.should_diagnose(lhs_id) {
					tc.record_error(.assignment_mismatch,
						'compound overloaded index assignment requires `[]` return type compatible with `[]=` value parameter type',
						assign_id)
				}
				return
			}
			return
		}
		if tc.should_diagnose(lhs_id) {
			tc.record_error(.assignment_mismatch,
				'compound overloaded index assignment requires a matching `[]` getter', assign_id)
		}
	}
}

fn (tc &TypeChecker) compound_index_overload_index_params_match(setter CallInfo, getter CallInfo) bool {
	if setter.params.len < 2 || getter.params.len < 2 {
		return true
	}
	return tc.c_type(setter.params[1]) == tc.c_type(getter.params[1])
}

fn (tc &TypeChecker) compound_index_overload_value_params_match(setter CallInfo, getter CallInfo) bool {
	if setter.params.len < 3 {
		return true
	}
	return tc.type_compatible(getter.return_type, setter.params[2])
}

fn assignment_op_reads_lhs(op flat.Op) bool {
	return match op {
		.plus_assign, .minus_assign, .mul_assign, .power_assign, .div_assign, .mod_assign,
		.amp_assign, .pipe_assign, .xor_assign, .left_shift_assign, .right_shift_assign,
		.right_shift_unsigned_assign {
			true
		}
		else {
			false
		}
	}
}

fn (tc &TypeChecker) assignment_types_compatible(rhs_id flat.NodeId, rhs_type Type, expected_type Type, op flat.Op) bool {
	if op == .assign && tc.translated_files[tc.cur_file] && rhs_type is ArrayFixed
		&& expected_type is Pointer && tc.expr_can_take_address(rhs_id) {
		return tc.type_compatible(rhs_type.elem_type, expected_type.base_type)
	}
	if op == .assign
		&& tc.fixed_array_address_to_byte_pointer_compatible(rhs_id, rhs_type, expected_type) {
		return true
	}
	if fn_param_unalias_type(expected_type).is_integer() && tc.c_scalar_byte_literal_arg(rhs_id) {
		return true
	}
	if tc.expr_tail_is_nil(rhs_id) {
		if _ := fn_type_from_type(expected_type) {
			return true
		}
	}
	if base := tc.mut_param_expr_base(rhs_id, rhs_type) {
		if tc.type_compatible(base, expected_type)
			|| tc.pointer_value_compatible(base, expected_type) {
			return true
		}
	}
	clean_rhs := unalias_type(rhs_type)
	clean_expected := unalias_type(expected_type)
	if clean_rhs.is_integer() && clean_expected.is_float() && tc.a.node(rhs_id).kind != .int_literal {
		return false
	}
	if clean_expected is SumType {
		return tc.direct_sum_assignment_variant_matches(rhs_type, clean_expected)
	}
	return tc.expr_compatible(rhs_id, rhs_type, expected_type)
		|| tc.pointer_value_compatible(rhs_type, expected_type)
		|| tc.pointer_arithmetic_assign_compatible(op, rhs_type, expected_type)
}

fn (tc &TypeChecker) direct_sum_assignment_variant_matches(actual Type, expected SumType) bool {
	if tc.generic_type_name_matches(actual.name(), expected.name) {
		return true
	}
	base := tc.sum_base_name(expected.name)
	variants := tc.sum_types[base] or { return false }
	for variant in variants {
		concrete := tc.concrete_sum_variant_name(expected.name, variant)
		if tc.generic_type_name_matches(actual.name(), concrete) {
			return true
		}
	}
	return false
}

fn type_is_unsigned_integer(typ Type) bool {
	clean := unalias_type(typ)
	if clean is Primitive {
		return clean.props.has(.integer) && clean.props.has(.unsigned)
	}
	return clean is USize
}

fn (tc &TypeChecker) expr_is_negative_integer_literal(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	if unalias_type(tc.resolve_type(id)).is_integer()
		&& tc.source_text_for_node(id).trim_space().starts_with('-') {
		return true
	}
	return false
}

fn (tc &TypeChecker) fixed_array_address_to_byte_pointer_compatible(expr_id flat.NodeId, actual Type, expected Type) bool {
	actual_ptr := if actual is Pointer { actual } else { return false }
	expected_ptr := if expected is Pointer { expected } else { return false }
	actual_base := if actual_ptr.base_type is Alias {
		actual_ptr.base_type.base_type
	} else {
		actual_ptr.base_type
	}
	expected_base := if expected_ptr.base_type is Alias {
		expected_ptr.base_type.base_type
	} else {
		expected_ptr.base_type
	}
	if actual_base !is ArrayFixed || expected_base.name() != 'u8' || !tc.valid_node_id(expr_id) {
		return false
	}
	actual_fixed := actual_base as ArrayFixed
	if unalias_type(actual_fixed.elem_type).name() != 'u8' {
		return false
	}
	node := tc.a.nodes[int(expr_id)]
	return node.kind == .prefix && node.op == .amp && node.children_count > 0
}

fn (tc &TypeChecker) assignment_preserves_smartcast(lhs_id flat.NodeId, rhs_id flat.NodeId, rhs_type Type) bool {
	key := tc.expr_key(lhs_id)
	if key.len == 0 {
		return false
	}
	smartcast := tc.smartcasts[key] or { return false }
	if tc.expr_compatible(rhs_id, rhs_type, smartcast)
		|| tc.pointer_value_compatible(rhs_type, smartcast) {
		return true
	}
	return tc.assignment_rhs_mutates_same_smartcast_lhs(lhs_id, rhs_id, rhs_type, smartcast)
}

fn (tc &TypeChecker) assignment_rhs_mutates_same_smartcast_lhs(lhs_id flat.NodeId, rhs_id flat.NodeId, rhs_type Type, smartcast Type) bool {
	if tc.sum_variant_type_for_pattern(rhs_type.name(), smartcast.name()) == none {
		return false
	}
	if !tc.valid_node_id(rhs_id) {
		return false
	}
	rhs := tc.a.nodes[int(rhs_id)]
	if rhs.kind != .call {
		return false
	}
	lhs_key := tc.expr_key(lhs_id)
	if lhs_key.len == 0 {
		return false
	}
	for i := 1; i < rhs.children_count; i++ {
		arg_id := tc.call_arg_value(tc.a.child(&rhs, i))
		if tc.expr_is_mut_arg_for_key(arg_id, lhs_key) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) expr_is_mut_arg_for_key(id flat.NodeId, key string) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind in [.paren, .expr_stmt] && node.children_count > 0 {
		return (node.is_mut && tc.expr_key(id) == key)
			|| tc.expr_is_mut_arg_for_key(tc.a.child(&node, 0), key)
	}
	return node.is_mut && tc.expr_key(id) == key
}

fn assignment_marker_value_is_error(value string) bool {
	return value.starts_with('for init assignment mismatch:')
		|| value.starts_with('for post assignment mismatch:')
}

fn (mut tc TypeChecker) check_assignment_marker(id flat.NodeId, node flat.Node) bool {
	if assignment_marker_value_is_error(node.value) {
		tc.record_error(.assignment_mismatch, node.value, id)
		return true
	}
	return false
}

// index_assign_lhs_is_map supports index assign lhs is map handling for TypeChecker.
fn (tc &TypeChecker) index_assign_lhs_is_map(node flat.Node) bool {
	if node.children_count == 0 {
		return false
	}
	lhs_id := tc.a.child(&node, 0)
	if int(lhs_id) < 0 {
		return false
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind != .index || lhs.children_count < 2 {
		return false
	}
	base_type := unwrap_pointer(tc.resolve_type(tc.a.child(&lhs, 0)))
	return base_type is Map
}

// check_multi_return_assign validates check multi return assign state for types.
fn (mut tc TypeChecker) check_multi_return_assign(id flat.NodeId, node flat.Node) bool {
	if node.children_count < 3 {
		return false
	}
	rhs_id := tc.a.child(&node, 1)
	rhs := tc.a.nodes[int(rhs_id)]
	lhs_ids := tc.multi_assign_lhs_ids(node)
	if tc.multi_assign_rhs_count(node) != 1 {
		return false
	}
	for lhs_id in lhs_ids {
		tc.check_lvalue_mutability(lhs_id)
		tc.remember_expr_type(lhs_id, tc.resolve_lvalue_type(lhs_id))
	}
	if rhs.kind == .match_stmt {
		tc.check_node(rhs_id)
		if !tc.match_has_else_or_exhaustive_coverage(rhs) {
			if tc.should_diagnose(id) {
				tc.record_error(.assignment_mismatch,
					'match expression must be exhaustive for multi-return assignment', id)
			}
			return true
		}
		if rhs_types := tc.match_multi_return_types(rhs_id, lhs_ids.len) {
			tc.register_synth_type(rhs_id, MultiReturn{
				types: rhs_types
			})
			for i, lhs_id in lhs_ids {
				lhs_type := tc.resolve_lvalue_type(lhs_id)
				if !tc.type_compatible(rhs_types[i], lhs_type) {
					tc.type_mismatch(.assignment_mismatch,
						'cannot assign `${rhs_types[i].name()}` to `${lhs_type.name()}`', id)
				}
			}
			$if ownership ? {
				tc.ownership_after_multi_return_assign(lhs_ids, rhs_id, MultiReturn{
					types: rhs_types
				}, id)
			}
			return true
		}
		if tc.match_has_incompatible_multi_return_branches(rhs_id, lhs_ids.len) {
			if tc.should_diagnose(id) {
				tc.record_error(.assignment_mismatch,
					'multi-return assignment mismatch: expression branches must all produce ${lhs_ids.len} compatible values',
					id)
			}
			return true
		}
		if rhs_types := tc.multi_expr_tail_types(rhs_id, lhs_ids.len) {
			tc.register_synth_type(rhs_id, MultiReturn{
				types: rhs_types
			})
			for i, lhs_id in lhs_ids {
				lhs_type := tc.resolve_lvalue_type(lhs_id)
				if !tc.type_compatible(rhs_types[i], lhs_type) {
					tc.type_mismatch(.assignment_mismatch,
						'cannot assign `${rhs_types[i].name()}` to `${lhs_type.name()}`', id)
				}
			}
			$if ownership ? {
				tc.ownership_after_multi_return_assign(lhs_ids, rhs_id, MultiReturn{
					types: rhs_types
				}, id)
			}
			return true
		}
		if rhs_types := tc.multi_expr_tail_assign_types(id, rhs_id, lhs_ids) {
			tc.register_synth_type(rhs_id, MultiReturn{
				types: rhs_types
			})
			$if ownership ? {
				tc.ownership_after_multi_return_assign(lhs_ids, rhs_id, MultiReturn{
					types: rhs_types
				}, id)
			}
			return true
		}
		if tc.should_diagnose(id) {
			if tc.match_has_tuple_tail_values(rhs_id, lhs_ids.len) {
				tc.record_error(.assignment_mismatch,
					'match expression branches cannot produce multiple assignment values', id)
			} else {
				tc.record_error(.assignment_mismatch,
					'multi-return assignment mismatch: expression branches must all produce ${lhs_ids.len} compatible values',
					id)
			}
		}
		return true
	}
	if rhs.kind == .if_expr {
		tc.check_node(rhs_id)
		if rhs_types := tc.multi_expr_tail_assign_types(id, rhs_id, lhs_ids) {
			tc.register_synth_type(rhs_id, MultiReturn{
				types: rhs_types
			})
			$if ownership ? {
				tc.ownership_after_multi_return_assign(lhs_ids, rhs_id, MultiReturn{
					types: rhs_types
				}, id)
			}
			return true
		}
		rhs_type := tc.resolve_type(rhs_id)
		if rhs_type !is MultiReturn || tc.expr_has_tuple_tail_values(rhs_id, lhs_ids.len) {
			if tc.should_diagnose(id) {
				tc.record_error(.assignment_mismatch,
					'multi-return assignment mismatch: expression branches must all produce ${lhs_ids.len} compatible values',
					id)
			}
			return true
		}
	}
	if rhs.kind == .lock_expr {
		tc.check_node(rhs_id)
		if rhs_types := tc.multi_expr_tail_assign_types(id, rhs_id, lhs_ids) {
			tc.register_synth_type(rhs_id, MultiReturn{
				types: rhs_types
			})
			$if ownership ? {
				tc.ownership_after_multi_return_assign(lhs_ids, rhs_id, MultiReturn{
					types: rhs_types
				}, id)
			}
			return true
		}
	}
	mut rhs_type := tc.resolve_type(rhs_id)
	mut rhs_checked := false
	mut rhs_multi := MultiReturn{}
	mut found_multi := false
	mut unhandled_multi := false
	for _ in 0 .. 2 {
		if multi := tc.multi_return_assignment_type(rhs_id, rhs_type) {
			rhs_multi = multi
			found_multi = true
			break
		}
		if _ := tc.unhandled_wrapped_multi_return_type(rhs_id, rhs_type) {
			unhandled_multi = true
			break
		}
		if rhs_checked {
			break
		}
		tc.check_node(rhs_id)
		rhs_checked = true
		rhs_type = tc.resolve_type(rhs_id)
	}
	rhs_type_name := rhs_type.name()
	if unhandled_multi {
		if !rhs_checked {
			tc.check_node(rhs_id)
		}
		if tc.should_diagnose(id) {
			tc.record_error(.assignment_mismatch,
				'multi-return assignment from `${rhs_type_name}` requires `or {}`, `!`, or `?` handling',
				id)
		}
		return true
	}
	if found_multi {
		if !rhs_checked {
			tc.check_node(rhs_id)
		}
		if lhs_ids.len != rhs_multi.types.len {
			if tc.should_diagnose(id) {
				tc.record_error(.assignment_mismatch,
					'multi-return assignment mismatch: ${lhs_ids.len} variables but `${rhs_type_name}` has ${rhs_multi.types.len} values',
					id)
			}
			return true
		}
		for i, lhs_id in lhs_ids {
			lhs_type := tc.resolve_lvalue_type(lhs_id)
			expected_type := tc.assignment_expected_type(lhs_id, lhs_type)
			if !tc.type_compatible(rhs_multi.types[i], expected_type) {
				lhs_name := tc.source_text_for_node(lhs_id)
				expected_name := expected_type.name().replace_once('fn(', 'fn (')
				actual_name := rhs_multi.types[i].name().replace_once('fn(', 'fn (')
				tc.record_error_at(.assignment_mismatch,
					'cannot assign to `${lhs_name}`: expected `${expected_name}`, not `${actual_name}`',
					rhs_id, rhs.pos)
			}
		}
		$if ownership ? {
			tc.ownership_after_multi_return_assign(lhs_ids, rhs_id, rhs_multi, id)
		}
		return true
	}
	if lhs_ids.len > 1 {
		if !rhs_checked {
			tc.check_node(rhs_id)
		}
		if tc.should_diagnose(id) {
			tc.record_error(.assignment_mismatch,
				'multi-return assignment mismatch: ${lhs_ids.len} variables but `${rhs_type_name}` has 1 values',
				id)
		}
		return true
	}
	return false
}

// check_postfix validates check postfix state for types.
fn (mut tc TypeChecker) check_postfix(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	child_id := tc.a.child(&node, 0)
	child := tc.a.nodes[int(child_id)]
	tc.check_node(child_id)
	if node.op in [.inc, .dec] {
		op := if node.op == .inc { '++' } else { '--' }
		action := if node.op == .inc { 'increment' } else { 'decrement' }
		rewrite_op := if node.op == .inc { '+' } else { '-' }
		is_map_index := child.kind == .index && child.children_count > 0
			&& unalias_type(unwrap_pointer(tc.resolve_type(tc.a.child(&child, 0)))) is Map
		if !tc.expr_can_take_address(child_id) && !is_map_index {
			source := tc.source_text_for_node(child_id)
			tc.record_error_with_details_at(.assignment_mismatch,
				'cannot ${action} `${source}` because it is non lvalue expression', child_id,
				tc.a.node(child_id).pos, [
				'try rewrite this as `${source} ${rewrite_op} 1`',
			])
			return
		}
		child_type := unalias_type(tc.resolve_type(child_id))
		if child_type is Pointer {
			if tc.pointer_diagnostic_binding_type_name(child_id, Type(child_type)) in [
				'voidptr',
				'nil',
			] {
				tc.record_error_at(.assignment_mismatch,
					'invalid operation: ${op} (non-numeric type `voidptr`)', id, tc.prefix_operator_pos(id,
					op))
				return
			}
			is_implicitly_dereferenced_mut_param := child.kind == .ident
				&& child.value in tc.fn_context.mut_param_base_types
			if tc.unsafe_depth == 0 && !tc.translated_files[tc.cur_file]
				&& !is_implicitly_dereferenced_mut_param {
				tc.record_warning_at(.assignment_mismatch,
					'pointer arithmetic is only allowed in `unsafe` blocks', id, tc.prefix_operator_pos(id,
					op))
			}
			tc.check_lvalue_mutability(child_id)
			return
		}
		if !infix_power_type_is_numeric(child_type) {
			type_name := if child_type is Nil { 'voidptr' } else { child_type.name() }
			tc.record_error_at(.assignment_mismatch,
				'invalid operation: ${op} (non-numeric type `${type_name}`)', id, tc.prefix_operator_pos(id,
				op))
			return
		}
		tc.check_lvalue_mutability(child_id)
	}
	if node.op == .not && child.kind == .array_literal {
		fixed_type := if child.typ.len > 0 {
			parsed := tc.parse_type(child.typ)
			if parsed is ArrayFixed {
				Type(parsed)
			} else if child.children_count > 0 {
				Type(ArrayFixed{
					elem_type: tc.resolve_type(tc.a.child(&child, 0))
					len:       child.children_count
				})
			} else {
				Type(ArrayFixed{
					elem_type: Type(int_)
					len:       child.children_count
				})
			}
		} else if child.children_count > 0 {
			Type(ArrayFixed{
				elem_type: tc.resolve_type(tc.a.child(&child, 0))
				len:       child.children_count
			})
		} else {
			Type(ArrayFixed{
				elem_type: Type(int_)
				len:       child.children_count
			})
		}
		tc.register_synth_type(id, fixed_type)
	}
	if node.op == .not && node.value == 'ragged_inferred_fixed_array' && tc.should_diagnose(id) {
		tc.record_error(.assignment_mismatch,
			'inferred fixed-array literal rows must have the same size', id)
	}
	if child.kind == .index && child.children_count >= 2 {
		base_type_raw := tc.resolve_type(tc.a.child(&child, 0))
		base_type := unwrap_pointer(base_type_raw)
		if base_type is Map && node.op in [.inc, .dec] && tc.reject_unlowered_map_mutation
			&& tc.should_diagnose(id) {
			tc.record_error(.assignment_mismatch,
				'internal compiler error: unlowered map index postfix mutation reached post-transform checker',
				id)
		}
		if node.op in [.inc, .dec] && tc.should_diagnose(id) {
			if _ := tc.index_overload_call_info(base_type_raw, false) {
				tc.record_error(.assignment_mismatch,
					'postfix mutation is not supported for overloaded index expressions', id)
			} else if _ := tc.index_overload_call_info(base_type_raw, true) {
				tc.record_error(.assignment_mismatch,
					'postfix mutation is not supported for overloaded index expressions', id)
			}
		}
	}
}

fn (mut tc TypeChecker) check_lvalue_mutability(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	if element_id := tc.shared_array_element_index(id) {
		tc.record_error_at(.assignment_mismatch,
			'you have to create a handle and `lock` it to modify `shared` array element',
			element_id, tc.a.node(element_id).pos)
		return
	}
	tc.check_lvalue_field_mutability(id)
	root_id := tc.lvalue_root_ident(id) or {
		tc.check_conditional_lvalue_mutability(id)
		return
	}
	root := tc.a.nodes[int(root_id)]
	if root.value.len == 0 || root.value == '_' {
		return
	}
	if tc.current_binding_is_shared(root.value) {
		lock_mode := tc.current_shared_lock_mode(root.value)
		if lock_mode == `w` {
			return
		}
		if lock_mode == `r` {
			tc.record_error_at(.assignment_mismatch,
				'${root.value} has an `rlock` but needs a `lock`', root_id,
				tc.node_value_diagnostic_pos(root_id))
		}
		tc.record_error_at(.assignment_mismatch,
			'`${root.value}` is `shared` and needs explicit lock for `v.ast.SelectorExpr`',
			root_id, tc.node_value_diagnostic_pos(root_id))
		return
	}
	if tc.ident_is_mutable_lvalue(root.value) {
		return
	}
	if tc.unsafe_depth > 0 && unalias_type(tc.resolve_type(root_id)) is Pointer {
		return
	}
	if _ := tc.malformed_const_keyword_pos(root_id) {
		return
	}
	if _ := tc.const_key_for_name(root.value) {
		tc.record_error_at(.assignment_mismatch, 'cannot modify constant `${root.value}`', root_id,
			tc.node_value_diagnostic_pos(root_id))
		return
	}
	if tc.fn_value_type(root.value) != none {
		tc.record_error_at(.assignment_mismatch, 'cannot assign to function `${root.value}`',
			root_id, tc.node_value_diagnostic_pos(root_id))
		return
	}
	owner := tc.cur_scope.lookup_owner(root.value) or { return }
	if owner.belongs_to_scope(tc.file_scope) {
		return
	}
	if closure_owner := tc.fn_context.closure_copy_owners[root.value] {
		if owner.storage_key() == closure_owner.storage_key() {
			tc.record_error_at(.assignment_mismatch,
				'the closure copy of `${root.value}` is immutable, declare it with `mut` to make it mutable',
				root_id, tc.node_value_diagnostic_pos(root_id))
			return
		}
	}
	tc.record_error_at(.assignment_mismatch,
		'`${root.value}` is immutable, declare it with `mut` to make it mutable', root_id,
		tc.node_value_diagnostic_pos(root_id))
}

fn (mut tc TypeChecker) check_conditional_lvalue_mutability(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind in [.index, .paren] && node.children_count > 0 {
		tc.check_conditional_lvalue_mutability(tc.a.child(node, 0))
		return
	}
	if node.kind == .if_expr || node.kind == .match_stmt {
		for i in 1 .. node.children_count {
			tail_id := tc.branch_tail_expr_id(tc.a.child(node, i))
			if tc.valid_node_id(tail_id) {
				tc.check_lvalue_mutability(tail_id)
			}
		}
	}
}

fn (mut tc TypeChecker) check_lvalue_field_mutability(id flat.NodeId) {
	node := tc.a.nodes[int(id)]
	if node.kind == .index && node.children_count > 0 {
		tc.check_lvalue_field_mutability(tc.a.child(&node, 0))
		return
	}
	if node.kind != .selector || node.children_count == 0 {
		return
	}
	base_id := tc.a.child(&node, 0)
	tc.check_lvalue_field_mutability(base_id)
	if tc.selector_is_shared_arg(node) {
		tc.record_error_at(.assignment_mismatch,
			'`${tc.source_text_for_node(id)}` is `shared` and needs explicit lock for `v.ast.SelectorExpr`',
			id, tc.selector_field_diagnostic_pos(id, node.value))
		return
	}
	raw_base_type := unalias_type(tc.resolve_type(base_id))
	base_type := unalias_and_unwrap_pointer_type(raw_base_type)
	if base_type is Interface {
		for field in tc.interface_field_list(base_type.name) {
			if field.name == node.value && !field.is_mut {
				tc.record_error_at(.assignment_mismatch,
					'field `${node.value}` of interface `${raw_base_type.name()}` is immutable',
					id, tc.node_value_diagnostic_pos(id))
				return
			}
		}
		return
	}
	if base_type !is Struct {
		return
	}
	struct_type := base_type as Struct
	for field in tc.struct_fields_for_init(struct_type.name) {
		if field.name != node.value {
			continue
		}
		if !field.is_mut {
			tc.record_error_at(.assignment_mismatch,
				'field `${node.value}` of struct `${raw_base_type.name()}` is immutable', id, tc.selector_field_diagnostic_pos(id,
				node.value))
		}
		return
	}
}

fn (tc &TypeChecker) selector_field_diagnostic_pos(id flat.NodeId, field string) token.Pos {
	node := tc.a.node(id)
	if node.children_count == 0 {
		return tc.node_value_diagnostic_pos(id)
	}
	base := tc.a.child_node(node, 0)
	file := tc.a.source_files[node.pos.id] or { return tc.node_value_diagnostic_pos(id) }
	source := tc.source_texts_by_file[file.name] or { return tc.node_value_diagnostic_pos(id) }
	start := int_max(0, int_min(base.pos.offset, source.len))
	line_end := source.index_after('\n', start) or { source.len }
	if relative := source[start..line_end].last_index('.${field}') {
		field_start := start + relative + 1
		return token.new_span(node.pos.id, field_start, field_start + field.len)
	}
	return tc.node_value_diagnostic_pos(id)
}

fn (tc &TypeChecker) lvalue_root_ident(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .ident {
		return id
	}
	if node.kind in [.index, .selector, .paren] && node.children_count > 0 {
		return tc.lvalue_root_ident(tc.a.child(&node, 0))
	}
	return none
}

fn (tc &TypeChecker) assignment_expected_type(lhs_id flat.NodeId, lhs_type Type) Type {
	if int(lhs_id) < 0 {
		return lhs_type
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind == .ident {
		if lhs.value == '_' {
			return Type(Unknown{})
		}
		if base := tc.mut_param_base_for_current_ident(lhs.value, lhs_type) {
			return base
		}
	}
	return lhs_type
}

fn (tc &TypeChecker) lvalue_matches_mut_param(lhs_type Type, base_type Type) bool {
	if lhs_type is Pointer {
		return tc.type_compatible(lhs_type.base_type, base_type)
			&& tc.type_compatible(base_type, lhs_type.base_type)
	}
	// Some expression-type entries have already stripped the ABI pointer used
	// for a `mut` parameter. Keep recognizing the binding as the same parameter
	// so option smartcasts operate on its semantic type.
	return tc.type_compatible(lhs_type, base_type) && tc.type_compatible(base_type, lhs_type)
}

fn (tc &TypeChecker) lvalue_ident_is_known(name string) bool {
	if _ := tc.cur_scope.lookup(name) {
		return true
	}
	if _ := tc.file_scope.lookup(name) {
		return true
	}
	qname := tc.qualify_name(name)
	if qname != name {
		if _ := tc.file_scope.lookup(qname) {
			return true
		}
	}
	return tc.const_type_for_name(name) != none || tc.fn_value_type(name) != none
}

fn (tc &TypeChecker) mut_param_binding_matches_lvalue(name string) bool {
	if tc.cur_scope == unsafe { nil } {
		return false
	}
	if param_owner := tc.fn_context.mut_param_owners[name] {
		if owner := tc.cur_scope.lookup_owner(name) {
			return owner.scope == param_owner.scope && owner.index == param_owner.index
				&& owner.generation == param_owner.generation
		}
	}
	if local_owner := tc.fn_context.mut_local_owners[name] {
		if owner := tc.cur_scope.lookup_owner(name) {
			return owner.scope == local_owner.scope && owner.index == local_owner.index
				&& owner.generation == local_owner.generation
		}
	}
	return false
}

// resolve_lvalue_type resolves resolve lvalue type information for types.
fn (mut tc TypeChecker) resolve_lvalue_type(lhs_id flat.NodeId) Type {
	if int(lhs_id) < 0 {
		return Type(void_)
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind == .ident {
		if typ := tc.cur_scope.lookup(lhs.value) {
			return typ
		}
		if typ := tc.file_scope.lookup(lhs.value) {
			return typ
		}
		qname := tc.qualify_name(lhs.value)
		if qname != lhs.value {
			if typ := tc.file_scope.lookup(qname) {
				return typ
			}
		}
		if typ := tc.const_type_for_name(lhs.value) {
			return typ
		}
		if typ := tc.fn_value_type(lhs.value) {
			return typ
		}
		if tc.should_diagnose(lhs_id) && lhs.value != '_' {
			if _ := tc.malformed_const_keyword_pos(lhs_id) {
				// The malformed statement gets one source-level diagnostic.
			} else {
				tc.record_error(.unknown_ident, 'unknown identifier `${lhs.value}`', lhs_id)
			}
		}
		return unknown_type('unknown identifier `${lhs.value}`')
	}
	if lhs.kind == .selector {
		tc.check_selector(lhs_id, lhs)
		if typ := tc.selector_type(lhs_id, lhs) {
			return typ
		}
		return tc.resolve_type(lhs_id)
	}
	if lhs.kind == .index {
		return tc.resolve_index_lvalue_type(lhs_id, .assign)
	}
	if lhs.kind == .prefix && lhs.op == .mul && lhs.children_count > 0 {
		inner_id := tc.a.child(&lhs, 0)
		inner_node := tc.a.nodes[int(inner_id)]
		inner := unalias_type(if inner_node.kind == .prefix && inner_node.op == .mul {
			tc.resolve_lvalue_type(inner_id)
		} else {
			tc.resolve_type(inner_id)
		})
		if inner is Pointer {
			return inner.base_type
		}
		return inner
	}
	return tc.resolve_type(lhs_id)
}

fn (mut tc TypeChecker) resolve_index_lvalue_type(lhs_id flat.NodeId, op flat.Op) Type {
	if int(lhs_id) < 0 {
		return Type(void_)
	}
	lhs := tc.a.nodes[int(lhs_id)]
	if lhs.kind != .index || lhs.children_count < 2 {
		tc.check_index(lhs_id, lhs)
		return tc.resolve_type(lhs_id)
	}
	base_id := tc.a.child(&lhs, 0)
	base_type := tc.resolve_type(base_id)
	if setter := tc.index_operator_call_info(base_type, '[]=') {
		if setter.params.len < 3 {
			tc.register_synth_type(lhs_id, unknown_type('invalid overloaded index setter'))
			return unknown_type('invalid overloaded index setter')
		}
		if !tc.check_index_overload_args_ok(lhs_id, lhs, setter) {
			invalid_type := unknown_type('invalid overloaded index setter')
			tc.register_synth_type(lhs_id, invalid_type)
			return invalid_type
		}
		if op != .assign {
			if getter := tc.index_operator_call_info(base_type, '[]') {
				if !tc.check_index_overload_args_ok(lhs_id, lhs, getter) {
					invalid_type := unknown_type('invalid overloaded index getter')
					tc.register_synth_type(lhs_id, invalid_type)
					return invalid_type
				}
				if !tc.index_overload_key_types_match(setter.params[1], getter.params[1]) {
					if tc.should_diagnose(lhs_id) {
						tc.record_error(.assignment_mismatch,
							'compound index assignment requires matching `[]` and `[]=` index parameter types (`[]` uses `${getter.params[1].name()}`, `[]=` uses `${setter.params[1].name()}`)',
							lhs_id)
					}
					invalid_type := unknown_type('mismatched overloaded index key types')
					tc.register_synth_type(lhs_id, invalid_type)
					return invalid_type
				}
				value_type := setter.params[2]
				if !tc.type_compatible(getter.return_type, value_type) {
					if tc.should_diagnose(lhs_id) {
						tc.record_error(.assignment_mismatch,
							'compound index assignment getter returns `${getter.return_type.name()}`, which cannot be used as setter value `${value_type.name()}`',
							lhs_id)
					}
					invalid_type := unknown_type('mismatched overloaded index value types')
					tc.register_synth_type(lhs_id, invalid_type)
					return invalid_type
				}
			} else {
				if tc.should_diagnose(lhs_id) {
					tc.record_error(.assignment_mismatch,
						'compound index assignment requires a `[]` overload on `${base_type.name()}`',
						lhs_id)
				}
				invalid_type := unknown_type('missing overloaded index getter')
				tc.register_synth_type(lhs_id, invalid_type)
				return invalid_type
			}
		}
		value_type := setter.params[2]
		tc.register_synth_type(lhs_id, value_type)
		return value_type
	}
	if getter := tc.index_operator_call_info(base_type, '[]') {
		if tc.should_diagnose(lhs_id) {
			tc.record_error_at(.assignment_mismatch,
				'index assignment requires a `[]=` overload on type `${base_type.name()}`', lhs_id,
				tc.index_brackets_pos(lhs))
		}
		if getter.params.len >= 2 {
			tc.check_index_overload_arg(lhs_id, lhs, getter, '[]')
		}
		invalid_type := unknown_type('missing overloaded index setter')
		tc.register_synth_type(lhs_id, invalid_type)
		return invalid_type
	}
	tc.check_index(lhs_id, lhs)
	return tc.resolve_type(lhs_id)
}

fn (tc &TypeChecker) index_overload_key_types_match(left Type, right Type) bool {
	return tc.type_compatible(left, right) && tc.type_compatible(right, left)
}

fn (tc &TypeChecker) option_marker_payload_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	if node.pos.offset >= 0 && node.pos.offset < source.len && source[node.pos.offset] == `?` {
		return token.new_span(node.pos.id, node.pos.offset + 1, node.pos.end)
	}
	if node.value.starts_with('?') {
		target := node.value[1..].all_after_last('.')
		search_end := int_min(source.len, int_max(node.pos.end, node.pos.offset + 1))
		search_start := int_max(0, search_end - node.value.len - 8)
		if relative := source[search_start..search_end].last_index('${target}(') {
			return token.new_span(node.pos.id, search_start + relative, search_end)
		}
	}
	return node.pos
}

// check_return validates check return state for types.
fn (mut tc TypeChecker) check_return(id flat.NodeId, node flat.Node) {
	// A returned method value escapes the function. Per-instance closure contexts make
	// value receivers safe, but mutable methods borrowing addressable stack receivers
	// remain invalid and are rejected below.
	// Returned fn literals with ordinary captures need a real closure environment too.
	// V3 only supports the narrow returned case of an explicit `mut` capture of a
	// pointer/reference value, where the lifted fn can keep using the pointee.
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		tc.reject_stored_method_value(child_id)
		tc.reject_returned_capturing_fn_literal(child_id)
	}
	expected := tc.fn_context.return_type
	if tc.current_fn_has_invalid_literal_return_type() {
		for i in 0 .. node.children_count {
			tc.check_node(tc.a.child(&node, i))
		}
		return
	}
	saved_expected_expr_id := tc.expected_expr_id
	saved_expected_expr_type := tc.expected_expr_type
	if node.children_count == 1 {
		tc.expected_expr_id = int(tc.a.child(&node, 0))
		tc.expected_expr_type = expected
	}
	defer {
		tc.expected_expr_id = saved_expected_expr_id
		tc.expected_expr_type = saved_expected_expr_type
	}
	if node.children_count == 1 {
		child_id := tc.a.child(&node, 0)
		child := tc.a.node(child_id)
		if child.kind == .ident {
			if invalid_type := tc.non_file_scope_type(child.value) {
				if invalid_type is Unknown && invalid_type.reason == 'invalid variable' {
					tc.check_node(child_id)
					tc.record_error_at(.return_mismatch, '`${child.value}` used as value', id,
						tc.noreturn_statement_diagnostic_pos(id))
					return
				}
			}
		}
	}
	if expected is Void {
		if node.children_count > 0 && tc.should_diagnose(id) {
			child_id := tc.a.child(&node, 0)
			tc.record_error_at(.return_mismatch,
				'unexpected argument, current function does not return anything', child_id,
				tc.a.node(child_id).pos)
		}
		for i in 0 .. node.children_count {
			child_id := tc.a.child(&node, i)
			$if ownership ? {
				tc.ownership_check_node_with_deferred_aggregate_consumption(child_id)
			} $else {
				tc.check_node(child_id)
			}
		}
		$if ownership ? {
			tc.ownership_after_return(id, node)
		}
		return
	}
	if node.children_count == 0 {
		if type_allows_implicit_return(expected) {
			$if ownership ? {
				tc.ownership_after_return(id, node)
			}
			return
		}
		if tc.should_diagnose(id) {
			noun := if multi_return_payload_type(expected) != none {
				'arguments'
			} else {
				'argument'
			}
			tc.record_error_at(.return_mismatch, 'expected `${expected.name()}` ${noun}', id,
				tc.noreturn_statement_diagnostic_pos(id))
		}
		return
	}
	if expected is ResultType && expected.base_type is Void {
		child_id := tc.a.child(&node, 0)
		child := tc.a.node(child_id)
		if node.children_count > 1 {
			tc.record_error_at(.return_mismatch,
				'functions with Result-only return types can only return an error', child_id,
				child.pos)
			return
		}
		tc.check_node(child_id)
		if void_tail := tc.return_value_void_tail(child_id) {
			tail := tc.a.node(void_tail)
			diagnostic_pos := if tail.kind == .or_expr && tail.value == '!'
				&& tail.pos.end > tail.pos.offset {
				token.new_span(tail.pos.id, tail.pos.offset, tail.pos.end - 1)
			} else {
				tail.pos
			}
			tc.record_error_at(.return_mismatch,
				'`${tc.source_text_for_node(void_tail)}` used as value', void_tail, diagnostic_pos)
			return
		}
		actual := tc.resolve_type(child_id)
		if child.kind == .none_expr {
			tc.record_error_at(.return_mismatch,
				'Option and Result types have been split, use `?` to return none', id,
				tc.noreturn_statement_diagnostic_pos(id))
			tc.record_error_at(.return_mismatch,
				'cannot use `none` as Result type in return argument', child_id, child.pos)
			return
		}
		if is_ierror_type(actual) || tc.type_compatible_with_ierror_payload(actual) {
			return
		}
		if actual is ResultType && actual.base_type is Void {
			return
		}
		tc.record_error_at(.return_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(child_id,
			actual)}` as Result type in return argument', child_id, child.pos)
		return
	}
	if expected is OptionType && expected.base_type is Void {
		child_id := tc.a.child(&node, 0)
		child := tc.a.node(child_id)
		if node.children_count > 1 {
			tc.record_error_at(.return_mismatch,
				'can only return `none` from an Option-only return function', child_id, child.pos)
			return
		}
		tc.check_node(child_id)
		if child.kind == .none_expr {
			return
		}
		actual := tc.resolve_type(child_id)
		if actual is Void {
			tc.record_error_at(.return_mismatch,
				'`${tc.source_text_for_node(child_id)}` used as value', id,
				tc.noreturn_statement_diagnostic_pos(id))
			return
		}
		tc.record_error_at(.return_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(child_id,
			actual)}` as Option type in return argument', child_id, child.pos)
		return
	}
	if expected is ResultType && node.children_count == 1 {
		payload := expected.base_type
		child_id := tc.a.child(&node, 0)
		if payload is Alias && unalias_type(payload.base_type) is OptionType
			&& tc.a.node(child_id).kind == .none_expr {
			tc.check_node(child_id)
			tc.record_error_at(.return_mismatch,
				'cannot use `none` as type `${payload.base_type.name()}` in return argument', id,
				tc.noreturn_statement_diagnostic_pos(id))
			return
		}
	}
	if node.children_count == 1 {
		child_id := tc.a.child(&node, 0)
		tc.annotate_expected_expr(child_id, expected)
		if expected is Unknown && tc.a.node(child_id).kind == .none_expr {
			return
		}
		if tc.return_is_direct_option_ident_propagation(child_id) && expected !is OptionType {
			tc.check_node(child_id)
			propagation := tc.a.node(child_id)
			source_id := tc.a.child(propagation, 0)
			operator_pos := tc.propagation_operator_pos(source_id, child_id, '?')
			return_line := tc.previous_source_line_matching(node.pos, 'return')
			tc.record_error_at(.return_mismatch,
				'should not unwrap option var on return, it could be none', id, token.new_span(return_line.id,
				return_line.offset, operator_pos.offset))
			return
		}
		if tc.expr_never_returns_resolving(child_id) {
			$if ownership ? {
				tc.ownership_check_node_with_deferred_aggregate_consumption(child_id)
			} $else {
				tc.check_node(child_id)
			}
			$if ownership ? {
				tc.ownership_after_return(id, node)
			}
			return
		}
		child := tc.a.node(child_id)
		if child.kind == .prefix && child.op == .amp && child.children_count > 0
			&& tc.unsafe_depth == 0 {
			value_id := tc.a.child(child, 0)
			value := tc.a.node(value_id)
			if value.kind == .ident && value.value.len > 0
				&& tc.cur_scope.lookup_owner(value.value) != none
				&& !tc.ident_is_mutable_lvalue(value.value)
				&& tc.current_fn_has_for_in_binding(value.value) {
				tc.check_node(child_id)
				tc.record_error_at(.return_mismatch,
					'`${value.value}` cannot be returned outside `unsafe` blocks as it might refer to an object stored on stack. Consider declaring `${value.value}` mutable.',
					value_id, value.pos)
				return
			}
		}
		raw_child_type := tc.resolve_type(child_id)
		if raw_child_type is Void {
			tc.check_node(child_id)
			if tc.should_diagnose(id) {
				tc.record_error_at(.return_mismatch,
					'`${tc.source_text_for_node(child_id)}` used as value', id,
					tc.noreturn_statement_diagnostic_pos(id))
			}
			return
		}
		if raw_child_type is OptionType && expected !is OptionType {
			tc.check_node(child_id)
			tc.record_error_at(.return_mismatch,
				'cannot use `?${raw_child_type.base_type.name()}` as type `${expected.name()}` in return argument',
				child_id, tc.option_marker_payload_pos(child))
			return
		}
	}
	if expected is ResultType && expected.base_type !is MultiReturn && node.children_count == 1
		&& !tc.result_return_uses_multi_tail(tc.a.child(&node, 0), expected) {
		child_id := tc.a.child(&node, 0)
		$if ownership ? {
			tc.ownership_check_node_with_deferred_aggregate_consumption(child_id)
		} $else {
			tc.check_node(child_id)
		}
		if bad_type := tc.invalid_ierror_return_expr_type_name(child_id, expected) {
			expected_name := '!${expected.base_type.name()}'
			if tc.should_diagnose(id) {
				actual := tc.resolve_type(child_id)
				tc.record_error_at(.return_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(child_id,
					actual)}` as type `${expected_name}` in return argument', child_id,
					tc.a.node(child_id).pos)
			} else {
				tc.record_invalid_ierror_return_error(id,
					'cannot return `${bad_type}` as `${expected_name}`')
			}
			return
		}
		actual := tc.resolve_expr(child_id, expected)
		if tc.return_type_compatible(child_id, actual, expected) {
			$if ownership ? {
				tc.ownership_after_return(id, node)
			}
			return
		}
	}
	if multi := multi_return_payload_type(expected) {
		if node.children_count > 1 {
			for i in 0 .. node.children_count {
				child_id := tc.a.child(&node, i)
				if multi_return_payload_type(tc.resolve_type(child_id)) != none {
					tc.record_error_at(.return_mismatch,
						'cannot use multi-return with other return types', child_id,
						tc.a.node(child_id).pos)
					return
				}
			}
		}
		if node.children_count == 1 {
			child_id := tc.a.child(&node, 0)
			$if ownership ? {
				tc.ownership_check_node_with_deferred_aggregate_consumption(child_id)
			} $else {
				tc.check_node(child_id)
			}
			if msg := tc.tuple_tail_return_error(child_id, multi.types) {
				if tc.should_diagnose(id) {
					tc.record_error(.return_mismatch, msg, id)
				}
				return
			}
			actual := tc.resolve_expr(child_id, expected)
			if tc.return_type_compatible(child_id, actual, expected) {
				$if ownership ? {
					tc.ownership_after_return(id, node)
				}
				return
			}
			if actual_multi := multi_return_payload_type(actual) {
				if actual_multi.types.len == multi.types.len {
					mut slots_compatible := true
					for i, actual_type in actual_multi.types {
						slot_expected := multi.types[i]
						numeric_name_mismatch := infix_power_type_is_numeric(actual_type)
							&& infix_power_type_is_numeric(slot_expected)
							&& actual_type.name() != slot_expected.name()
						if numeric_name_mismatch
							|| !tc.return_type_compatible(child_id, actual_type, slot_expected) {
							slots_compatible = false
							if tc.should_diagnose(id) {
								tc.record_error_at(.return_mismatch,
									'cannot use `${actual_type.name()}` as type `${slot_expected.name()}` in return argument',
									child_id, tc.a.node(child_id).pos)
							}
							return
						}
					}
					if slots_compatible {
						$if ownership ? {
							tc.ownership_after_return(id, node)
						}
					}
					return
				}
			}
			if ok := tc.multi_expr_tail_return_compatible(id, child_id, multi.types, expected) {
				if ok {
					$if ownership ? {
						tc.ownership_after_return(id, node)
					}
				}
				return
			}
			if item_types := tc.multi_expr_tail_types(child_id, multi.types.len) {
				if item_types.len == multi.types.len {
					mut ok := true
					for i, item_type in item_types {
						if !tc.type_compatible(item_type, multi.types[i]) {
							ok = false
							if tc.should_diagnose(id) {
								tc.type_mismatch(.return_mismatch,
									'cannot return `${item_type.name()}` as `${multi.types[i].name()}`',
									id)
							}
						}
					}
					if ok {
						$if ownership ? {
							tc.ownership_after_return(id, node)
						}
					}
					return
				}
			}
		}
		if node.children_count != multi.types.len {
			if tc.should_diagnose(id) {
				pos_id := tc.a.child(&node, int_min(multi.types.len, node.children_count - 1))
				tc.record_error_at(.return_mismatch,
					'expected ${multi.types.len} arguments, but got ${node.children_count}',
					pos_id, tc.a.node(pos_id).pos)
			}
			return
		}
		for i in 0 .. node.children_count {
			child_id := tc.a.child(&node, i)
			$if ownership ? {
				tc.ownership_check_node_with_deferred_aggregate_consumption(child_id)
			} $else {
				tc.check_node(child_id)
			}
			actual := tc.resolve_expr(child_id, multi.types[i])
			if !tc.return_type_compatible(child_id, actual, multi.types[i]) {
				tc.type_mismatch(.return_mismatch,
					'cannot return `${actual.name()}` as `${multi.types[i].name()}`', id)
			}
		}
		$if ownership ? {
			tc.ownership_after_return(id, node)
		}
		return
	}
	if node.children_count != 1 {
		if tc.should_diagnose(id) {
			pos_id := tc.a.child(&node, int_min(1, node.children_count - 1))
			tc.record_error_at(.return_mismatch,
				'expected 1 argument, but got ${node.children_count}', pos_id,
				tc.a.node(pos_id).pos)
		}
		return
	}
	child_id := tc.a.child(&node, 0)
	$if ownership ? {
		tc.ownership_check_node_with_deferred_aggregate_consumption(child_id)
	} $else {
		tc.check_node(child_id)
	}
	child_value := tc.a.node(child_id)
	if child_value.kind == .ident {
		if invalid_type := tc.non_file_scope_type(child_value.value) {
			if invalid_type is Unknown && invalid_type.reason == 'invalid variable' {
				tc.record_error_at(.return_mismatch, '`${child_value.value}` used as value', id,
					tc.noreturn_statement_diagnostic_pos(id))
				return
			}
		}
	}
	if child_value.kind == .match_stmt
		&& tc.record_return_match_sumtype_branch_mismatch(child_id, expected) {
		return
	}
	if child_value.kind == .match_stmt && tc.expr_has_match_branch_type_error(child_id) {
		return
	}
	if child_value.kind == .ident && tc.fn_context.closure_forbidden_captures[child_value.value] {
		tc.record_error_at(.return_mismatch, '`${child_value.value}` used as value', id,
			tc.noreturn_statement_diagnostic_pos(id))
		return
	}
	if expected is OptionType && is_ierror_type(tc.resolve_type(child_id)) {
		if tc.valid_node_id(flat.NodeId(tc.fn_context.node_id))
			&& tc.a.node(flat.NodeId(tc.fn_context.node_id)).typ == '?void' {
			return
		}
		tc.record_error_at(.return_mismatch,
			'Option and Result types have been split, use `!Foo` to return errors', id,
			tc.noreturn_statement_diagnostic_pos(id))
		return
	}
	if expected is ResultType {
		if bad_type := tc.invalid_ierror_return_expr_type_name(child_id, expected) {
			tc.record_invalid_ierror_return_error(id,
				'cannot return `${bad_type}` as `${Type(expected).name()}`')
			return
		}
	}
	if type_is_unsigned_integer(expected) {
		if literal := tc.integer_literal_source(child_id) {
			if literal.starts_with('-') {
				tc.record_notice_at(.return_mismatch,
					'cannot use a negative value as value of type `${expected.name()}` in return argument',
					child_id, tc.a.node(child_id).pos)
				return
			}
		}
	}
	source_actual := tc.resolve_type(child_id)
	actual := tc.resolve_expr(child_id, expected)
	numeric_kind_mismatch := infix_power_type_is_numeric(actual)
		&& infix_power_type_is_numeric(expected)
		&& unalias_type(actual).is_integer() != unalias_type(expected).is_integer()
		&& tc.a.node(child_id).kind !in [.int_literal, .float_literal] && !(actual.name() == 'int'
		&& expected.name() == 'f32')
	reference_mismatch := source_actual is Pointer && expected !is Pointer
		&& unalias_type(expected) !is Interface
		&& tc.type_compatible(source_actual.base_type, expected)
		&& !(tc.a.node(child_id).kind == .ident
		&& tc.mut_param_binding_matches_lvalue(tc.a.node(child_id).value))
	if numeric_kind_mismatch || reference_mismatch
		|| !tc.return_type_compatible(child_id, actual, expected) {
		clean_expected := unalias_type(expected)
		if clean_expected is OptionType && unalias_type(clean_expected.base_type) is Interface
			&& tc.a.node(child_id).kind == .if_expr {
			tc.record_error_at(.return_mismatch,
				'mismatched types `${expected.name()}` and `${actual.name()}`', id,
				tc.return_if_keyword_pos(node))
			return
		}
		diagnostic_actual := if reference_mismatch {
			source_actual
		} else {
			tc.mut_param_expr_base(child_id, actual) or { actual }
		}
		if diagnostic_actual is Pointer && expected !is Pointer
			&& tc.type_compatible(diagnostic_actual.base_type, expected)
			&& tc.valid_node_id(flat.NodeId(tc.fn_context.node_id)) {
			fn_name := tc.a.node(flat.NodeId(tc.fn_context.node_id)).value
			pos := if tc.a.node(child_id).kind == .prefix {
				tc.prefix_operator_pos(child_id, '&')
			} else {
				tc.a.node(child_id).pos
			}
			diagnostic_actual_name := if reference_mismatch && source_actual is Pointer {
				'&${source_actual.base_type.name()}'
			} else {
				Type(diagnostic_actual).name()
			}
			tc.record_error_with_details_at(.return_mismatch,
				'fn `${fn_name}` expects you to return a non reference type `${expected.name()}`, but you are returning `${diagnostic_actual_name}` instead',
				child_id, pos, [
				'use `return *pointer` instead of `return pointer`, and just `return value` instead of `return &value`',
			])
			return
		}
		if expected is Pointer && diagnostic_actual !is Pointer
			&& tc.valid_node_id(flat.NodeId(tc.fn_context.node_id)) {
			fn_name := tc.a.node(flat.NodeId(tc.fn_context.node_id)).value
			tc.record_error_at(.return_mismatch, 'fn `${fn_name}` expects you to return a reference type `${call_argument_type_name(expected)}`, but you are returning `${tc.diagnostic_expr_type_name(child_id,
				diagnostic_actual)}` instead', child_id, tc.a.node(child_id).pos)
			return
		}
		tc.record_error_at(.return_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(child_id,
			diagnostic_actual)}` as type `${call_argument_type_name(expected)}` in return argument',
			child_id, tc.a.node(child_id).pos)
		return
	}
	$if ownership ? {
		tc.ownership_after_return(id, node)
	}
}

fn (mut tc TypeChecker) record_return_match_sumtype_branch_mismatch(id flat.NodeId, expected Type) bool {
	clean_expected := unalias_type(expected)
	if clean_expected !is SumType || !tc.valid_node_id(id) {
		return false
	}
	expected_sum := clean_expected as SumType
	node := tc.a.node(id)
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(node, i)
		tail_id := tc.branch_tail_expr_id(branch_id)
		if !tc.valid_node_id(tail_id) {
			continue
		}
		actual := tc.raw_return_match_tail_type(tail_id)
		if tc.type_name_is_direct_sum_variant(actual, expected_sum) {
			continue
		}
		if !tc.expr_has_match_branch_type_error(id) {
			tc.record_match_branch_return_type_mismatch(tail_id, expected, actual)
		}
		return true
	}
	return false
}

fn (tc &TypeChecker) raw_return_match_tail_type(id flat.NodeId) Type {
	node := tc.a.node(id)
	if node.kind == .char_literal {
		return Type(rune_)
	}
	source := tc.source_text_for_node(id).trim_space()
	if open := source.index('(') {
		candidate := source[..open].trim_space()
		if candidate.len > 0 && tc.type_name_known(candidate) {
			return tc.parse_type(candidate)
		}
	}
	return tc.resolve_type(id)
}

fn (tc &TypeChecker) current_fn_has_for_in_binding(name string) bool {
	fn_id := flat.NodeId(tc.fn_context.node_id)
	if !tc.valid_node_id(fn_id) {
		return false
	}
	mut stack := []flat.NodeId{}
	stack << fn_id
	for stack.len > 0 {
		id := stack.pop()
		node := tc.a.node(id)
		if node.kind == .for_in_stmt {
			for i in 0 .. int_min(2, node.children_count) {
				binding := tc.a.child_node(node, i)
				if binding.kind == .ident && binding.value == name {
					return true
				}
			}
		}
		for i in 0 .. node.children_count {
			stack << tc.a.child(node, i)
		}
	}
	return false
}

fn (tc &TypeChecker) return_value_void_tail(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .match_stmt {
		for i in 1 .. node.children_count {
			branch_id := tc.a.child(node, i)
			branch := tc.a.node(branch_id)
			if branch.kind != .match_branch {
				continue
			}
			tail_id := tc.branch_tail_expr_id(branch_id)
			if tc.valid_node_id(tail_id) && tc.resolve_type(tail_id) is Void {
				return tail_id
			}
		}
	} else if node.kind == .if_expr {
		for i in 1 .. node.children_count {
			branch_id := tc.a.child(node, i)
			if void_tail := tc.return_value_void_tail(branch_id) {
				return void_tail
			}
			tail_id := tc.branch_tail_expr_id(branch_id)
			if tc.valid_node_id(tail_id) && tc.resolve_type(tail_id) is Void {
				return tail_id
			}
		}
	}
	return none
}

fn (tc &TypeChecker) return_if_keyword_pos(node flat.Node) token.Pos {
	line := tc.previous_source_line_matching(node.pos, 'return')
	file := tc.a.source_files[line.id] or { return line }
	source := tc.source_texts_by_file[file.name] or { return line }
	start := int_min(int_max(line.offset, 0), source.len)
	end := int_min(int_max(line.end, start), source.len)
	if start < end {
		if relative := source[start..end].index('if') {
			pos := start + relative
			return token.new_span(line.id, pos, pos + 2)
		}
	}
	return line
}

fn (tc &TypeChecker) return_is_direct_option_ident_propagation(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind != .or_expr || node.value != '?' || node.children_count == 0 {
		return false
	}
	source_id := tc.a.child(node, 0)
	source := tc.a.node(source_id)
	return source.kind == .ident && tc.resolve_type(source_id) is OptionType
}

fn (tc &TypeChecker) current_fn_has_invalid_literal_return_type() bool {
	node_id := tc.fn_context.node_id
	if node_id < 0 || node_id >= tc.a.nodes.len {
		return false
	}
	mut typ := tc.a.nodes[node_id].typ.trim_space()
	for typ.starts_with('?') || typ.starts_with('!') {
		typ = typ[1..].trim_space()
	}
	return typ in ['any', 'int_literal', 'float_literal']
}

fn (mut tc TypeChecker) multi_expr_tail_return_compatible(return_id flat.NodeId, expr_id flat.NodeId, expected []Type, wrapper Type) ?bool {
	if !tc.multi_expr_tail_return_compat_supported(expr_id) {
		return none
	}
	groups := if wrapper is OptionType || wrapper is ResultType {
		tc.wrapped_multi_return_value_groups(expr_id, expected.len, false, wrapper) or {
			return none
		}
	} else {
		tc.multi_expr_tail_value_groups(expr_id, expected.len, false) or { return none }
	}
	if groups.len == 0 {
		return none
	}
	if tc.record_multi_expr_wrapped_return_mismatch(expr_id, expected, groups) {
		return false
	}
	mut ok := true
	for group in groups {
		if group.len != expected.len {
			return none
		}
		for i, value_id in group {
			actual := tc.resolve_expr(value_id, expected[i])
			if !type_has_runtime_value(actual) {
				if unalias_type(actual) is Void {
					value := tc.a.node(value_id)
					tc.record_error_at(.return_mismatch,
						'type `void` cannot be used in multi-return', value_id, value.pos)
					expr := tc.a.node(expr_id)
					if expr.kind in [.if_expr, .match_stmt] && value.kind == .call
						&& value.children_count > 0 {
						callee_id := tc.a.child(value, 0)
						tc.record_error_at(.if_branch_mismatch,
							'the final expression in `if` or `match`, must have a value of a non-void type',
							callee_id, tc.a.node(callee_id).pos)
					}
					return false
				}
				return none
			}
			if !tc.return_type_compatible(value_id, actual, expected[i]) {
				ok = false
				if expected[i] is Pointer && actual !is Pointer
					&& tc.valid_node_id(flat.NodeId(tc.fn_context.node_id)) {
					fn_name := tc.a.node(flat.NodeId(tc.fn_context.node_id)).value
					expr := tc.a.node(expr_id)
					pos := if expr.kind == .if_expr {
						token.new_span(expr.pos.id, expr.pos.offset, expr.pos.offset + 2)
					} else {
						expr.pos
					}
					tc.record_error_at(.return_mismatch, 'fn `${fn_name}` expects you to return a reference type `${call_argument_type_name(expected[i])}`, but you are returning `${tc.diagnostic_expr_type_name(value_id,
						actual)}` instead', expr_id, pos)
				} else {
					tc.type_mismatch(.return_mismatch,
						'cannot return `${actual.name()}` as `${expected[i].name()}`', return_id)
				}
			}
		}
	}
	return ok
}

fn (mut tc TypeChecker) record_multi_expr_wrapped_return_mismatch(expr_id flat.NodeId, expected []Type, groups [][]flat.NodeId) bool {
	if !tc.valid_node_id(expr_id) {
		return false
	}
	expr := tc.a.node(expr_id)
	if expr.kind !in [.if_expr, .match_stmt] {
		return false
	}
	for group in groups {
		if group.len != expected.len {
			continue
		}
		mut actual_types := []Type{cap: group.len}
		mut bad_index := -1
		for i, value_id in group {
			actual := tc.resolve_type(value_id)
			actual_types << actual
			if bad_index < 0 && !tc.return_type_compatible(value_id, actual, expected[i])
				&& (actual is OptionType || actual is ResultType) {
				bad_index = i
			}
		}
		if bad_index < 0 {
			continue
		}
		actual := actual_types[bad_index]
		if actual is ResultType {
			mut actual_names := []string{cap: group.len}
			for i, value_id in group {
				actual_names << tc.diagnostic_expr_type_name(value_id, actual_types[i])
			}
			mut bad_pos := tc.a.node(group[bad_index]).pos
			bad_node := tc.a.node(group[bad_index])
			if bad_node.kind == .call && bad_node.children_count > 0 {
				bad_pos = tc.a.child_node(bad_node, 0).pos
			}
			tc.record_error_at(.return_mismatch, 'return type mismatch, it should be `${Type(MultiReturn{
				types: expected
			}).name()}`, but it is instead `(${actual_names.join(', ')})`', group[bad_index],
				bad_pos)
		}
		pos := if expr.kind == .match_stmt {
			tc.match_header_pos(expr)
		} else {
			token.new_span(expr.pos.id, expr.pos.offset, expr.pos.offset + 2)
		}
		tc.record_error_at(.return_mismatch,
			'cannot use `${actual.name()}` as type `${expected[bad_index].name()}` in return argument',
			expr_id, pos)
		return true
	}
	return false
}

fn (tc &TypeChecker) multi_expr_tail_return_compat_supported(expr_id flat.NodeId) bool {
	if !tc.valid_node_id(expr_id) {
		return false
	}
	node := tc.a.nodes[int(expr_id)]
	// Raw tuple-tail return lowering is currently implemented for if- and match-expressions.
	if node.kind in [.if_expr, .match_stmt] {
		return true
	}
	if node.kind == .expr_stmt && node.children_count > 0 {
		return tc.multi_expr_tail_return_compat_supported(tc.a.child(&node, 0))
	}
	return false
}

fn (tc &TypeChecker) result_return_uses_multi_tail(expr_id flat.NodeId, expected Type) bool {
	multi := multi_return_payload_type(expected) or { return false }
	return tc.expr_has_tuple_tail_values(expr_id, multi.types.len)
}

fn tuple_tail_return_lowering_allowed(expected []Type) bool {
	for typ in expected {
		if tuple_tail_return_type_allows_lowering(typ) {
			return true
		}
	}
	return false
}

fn tuple_tail_return_type_allows_lowering(typ Type) bool {
	if typ is ArrayFixed || typ is Struct {
		return true
	}
	if typ is Alias {
		return tuple_tail_return_type_allows_lowering(typ.base_type)
	}
	return false
}

fn (tc &TypeChecker) tuple_tail_return_error(expr_id flat.NodeId, expected []Type) ?string {
	if tuple_tail_return_lowering_allowed(expected) || !tc.valid_node_id(expr_id) {
		return none
	}
	count := expected.len
	node := tc.a.nodes[int(expr_id)]
	match node.kind {
		.expr_stmt, .paren {
			if node.children_count > 0 {
				return tc.tuple_tail_return_error(tc.a.child(&node, 0), expected)
			}
		}
		.if_expr {
			if tc.expr_has_noncomma_tuple_tail_values(expr_id, count) {
				return 'if expression branches cannot produce multiple return values'
			}
		}
		.match_stmt {
			if tc.expr_has_noncomma_tuple_tail_values(expr_id, count) {
				return 'match expression branches cannot produce multiple return values'
			}
		}
		else {}
	}
	return none
}

fn (mut tc TypeChecker) return_type_compatible(expr_id flat.NodeId, actual Type, expected Type) bool {
	if tc.expr_compatible(expr_id, actual, expected) {
		return true
	}
	if return_numeric_alias_compatible(actual, expected) {
		return true
	}
	if tc.pointer_value_compatible(actual, expected) {
		return true
	}
	if expected is Pointer
		&& tc.bare_value_pointer_return_compatible(expr_id, actual, expected.base_type) {
		return true
	}
	if expected is OptionType {
		if tc.type_compatible(actual, expected.base_type) {
			return true
		}
		if expected.base_type is Pointer {
			if smart_type := tc.smartcast_type(expr_id) {
				if tc.type_compatible(smart_type, expected.base_type.base_type) {
					return true
				}
			}
		}
		if tc.pointer_value_compatible(actual, expected.base_type) {
			return true
		}
		if expected.base_type is Pointer
			&& tc.bare_value_pointer_return_compatible(expr_id, actual, expected.base_type.base_type) {
			return true
		}
	}
	if tc.expr_generic_expected_match(expr_id, actual, expected) {
		return true
	}
	if expected is ResultType {
		if tc.type_compatible(actual, expected.base_type) {
			return true
		}
		if tc.zero_literal_can_be_pointer(expr_id, expected.base_type) {
			return true
		}
		if tc.pointer_value_compatible(actual, expected.base_type) {
			return true
		}
		if expected.base_type is Pointer
			&& tc.bare_value_pointer_return_compatible(expr_id, actual, expected.base_type.base_type) {
			return true
		}
		if is_ierror_type(actual) || tc.type_embeds_error(actual) {
			return true
		}
		if tc.type_compatible_with_ierror_payload(actual) {
			return true
		}
	}
	if base := tc.mut_param_expr_base(expr_id, actual) {
		if tc.type_compatible(base, expected) || tc.generic_receiver_base_match(base, expected) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) bare_value_pointer_return_compatible(expr_id flat.NodeId, actual Type, expected_base Type) bool {
	if !tc.expr_can_take_address(expr_id) {
		return false
	}
	clean_actual := fn_param_unalias_type(actual)
	clean_expected := fn_param_unalias_type(expected_base)
	if clean_actual is Pointer {
		return false
	}
	return
		fn_return_canonical_type_name(clean_actual) == fn_return_canonical_type_name(clean_expected)
		|| tc.c_type(clean_actual) == tc.c_type(clean_expected)
}

fn (tc &TypeChecker) generic_expected_type_match(actual Type, expected Type) bool {
	if tc.generic_receiver_base_match(actual, expected) {
		return true
	}
	if expected is OptionType {
		if actual is OptionType {
			return tc.generic_expected_type_match(actual.base_type, expected.base_type)
		}
		return tc.generic_expected_type_match(actual, expected.base_type)
	}
	if expected is ResultType {
		if actual is ResultType {
			return tc.generic_expected_type_match(actual.base_type, expected.base_type)
		}
		return tc.generic_expected_type_match(actual, expected.base_type)
	}
	if actual is Array && expected is Array {
		return tc.generic_expected_type_match(actual.elem_type, expected.elem_type)
	}
	if actual is ArrayFixed && expected is ArrayFixed {
		return tc.fixed_array_lengths_compatible(actual, expected)
			&& tc.generic_expected_type_match(actual.elem_type, expected.elem_type)
	}
	if actual is Map && expected is Map {
		return tc.generic_expected_type_match(actual.key_type, expected.key_type)
			&& tc.generic_expected_type_match(actual.value_type, expected.value_type)
	}
	return false
}

fn (tc &TypeChecker) pointer_value_compatible(actual Type, expected Type) bool {
	if actual is Pointer {
		if !pointer_value_base_can_match(actual.base_type) {
			return false
		}
		return tc.type_compatible(actual.base_type, expected)
			|| pointer_value_type_names_match(Type(actual).name(), expected.name())
			|| bare_type_names_match(actual.base_type.name(), expected.name())
	}
	return pointer_value_type_names_match(actual.name(), expected.name())
}

fn pointer_value_base_can_match(typ Type) bool {
	clean := if typ is Alias { typ.base_type } else { typ }
	return clean is Struct || clean is Interface || clean is SumType || clean is Array
		|| clean is ArrayFixed || clean is Map || clean is Channel
}

fn pointer_value_type_names_match(actual string, expected string) bool {
	if !actual.starts_with('&') {
		return false
	}
	clean_actual := actual[1..]
	return clean_actual == expected
}

fn bare_type_names_match(actual string, expected string) bool {
	return actual == expected
}

fn return_numeric_alias_compatible(actual Type, expected Type) bool {
	if expected is Alias {
		clean_actual := if actual is Alias { actual.base_type } else { actual }
		clean_expected := expected.base_type
		if clean_expected.is_float() {
			return clean_actual.is_integer() || clean_actual.is_float()
		}
		if clean_expected.is_integer() {
			return clean_actual.is_integer()
		}
	}
	return false
}

fn (tc &TypeChecker) expr_compatible(expr_id flat.NodeId, actual Type, expected Type) bool {
	return tc.type_compatible(actual, expected) || tc.zero_literal_can_be_pointer(expr_id, expected)
		|| tc.int_literal_can_be_char(expr_id, expected)
		|| tc.optional_pointer_expr_compatible(expr_id, actual, expected)
		|| tc.failure_literal_expr_compatible(expr_id, actual, expected)
}

fn (tc &TypeChecker) failure_literal_expr_compatible(expr_id flat.NodeId, actual Type, expected Type) bool {
	tail_id := tc.branch_tail_expr_id(expr_id)
	if !tc.valid_node_id(tail_id) {
		return false
	}
	return tc.if_branch_type_compatible_with_context(actual, tail_id, expected)
}

fn (tc &TypeChecker) optional_pointer_expr_compatible(expr_id flat.NodeId, actual Type, expected Type) bool {
	if (actual is ResultType && expected is OptionType)
		|| (actual is OptionType && expected is ResultType) {
		return false
	}
	expected_base := match expected {
		OptionType { expected.base_type }
		ResultType { expected.base_type }
		else { return false }
	}
	if expected_base !is Pointer {
		return false
	}
	expected_ptr := expected_base as Pointer
	if tc.zero_literal_can_be_pointer(expr_id, expected_ptr) {
		return true
	}
	mut actual_base := match actual {
		OptionType { actual.base_type }
		ResultType { actual.base_type }
		else { actual }
	}
	if mut_base := tc.mut_param_expr_base(expr_id, actual) {
		actual_base = match mut_base {
			OptionType { mut_base.base_type }
			ResultType { mut_base.base_type }
			else { mut_base }
		}
	}
	if actual_base is Pointer || !tc.expr_can_take_address(expr_id) {
		return false
	}
	return tc.type_compatible(actual_base, expected_ptr.base_type)
}

fn (tc &TypeChecker) int_literal_can_be_char(expr_id flat.NodeId, expected Type) bool {
	if expected !is Char || int(expr_id) < 0 {
		return false
	}
	node := tc.a.nodes[int(expr_id)]
	return node.kind == .int_literal
}

fn (tc &TypeChecker) pointer_arithmetic_assign_compatible(op flat.Op, actual Type, expected Type) bool {
	if op !in [.plus_assign, .minus_assign] {
		return false
	}
	clean_expected := if expected is Alias { expected.base_type } else { expected }
	if clean_expected !is Pointer {
		return false
	}
	clean_actual := if actual is Alias { actual.base_type } else { actual }
	return clean_actual.is_integer()
}

fn (tc &TypeChecker) zero_literal_can_be_pointer(expr_id flat.NodeId, expected Type) bool {
	if !tc.is_zero_literal(expr_id) && !tc.expr_is_unsafe_zero_literal(expr_id) {
		return false
	}
	clean := if expected is Alias { expected.base_type } else { expected }
	return clean is Pointer
}

fn (tc &TypeChecker) expr_is_unsafe_zero_literal(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind != .block {
		return false
	}
	return tc.expr_tail_is_zero_literal(id)
}

fn (tc &TypeChecker) expr_tail_is_zero_literal(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.int_literal {
			return node.value == '0'
		}
		.expr_stmt, .paren {
			if node.children_count == 0 {
				return false
			}
			return tc.expr_tail_is_zero_literal(tc.a.child(&node, 0))
		}
		.block {
			if node.children_count == 0 {
				return false
			}
			return tc.expr_tail_is_zero_literal(tc.a.child(&node, node.children_count - 1))
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) mut_param_expr_base(expr_id flat.NodeId, typ Type) ?Type {
	if int(expr_id) < 0 || int(expr_id) >= tc.a.nodes.len {
		return none
	}
	node := tc.a.nodes[int(expr_id)]
	if node.kind == .ident && node.value.len > 0 {
		return tc.mut_param_base_for_current_ident(node.value, typ)
	}
	if node.kind == .prefix && node.op == .amp && node.children_count > 0 {
		child := tc.a.nodes[int(tc.a.child(&node, 0))]
		if child.kind == .ident && child.value.len > 0 {
			base := tc.fn_context.mut_param_base_types[child.value] or { return none }
			if !tc.mut_param_binding_matches_lvalue(child.value) {
				return none
			}
			return Type(Pointer{
				base_type: base
			})
		}
	}
	return none
}

fn (tc &TypeChecker) current_checked_fn_qname() ?string {
	if tc.fn_context.node_id < 0 || tc.fn_context.node_id >= tc.a.nodes.len {
		return none
	}
	fn_node := tc.a.nodes[tc.fn_context.node_id]
	if fn_node.kind != .fn_decl || fn_node.value.len == 0 {
		return none
	}
	return checker_qualified_fn_name(tc.cur_module, fn_node.value)
}

// record_invalid_ierror_return_error records an invalid-ierror-return error,
// gating non-diagnostic-file sites on the called-fns closure. While that
// closure is still being computed on the collector thread (parallel check),
// the candidate is parked in pending_ierror_errors and filtered after join.
fn (mut tc TypeChecker) record_invalid_ierror_return_error(id flat.NodeId, msg string) {
	if tc.should_diagnose(id) {
		tc.record_error_unfiltered(.return_mismatch, msg, id)
		return
	}
	qname := tc.current_checked_fn_qname() or { return }
	if tc.defer_ierror_gating {
		tc.pending_ierror_errors << PendingIerrorError{
			err:      tc.make_type_error(.return_mismatch, msg, id)
			fn_qname: qname
		}
		return
	}
	if qname in tc.selected_file_called_fns {
		tc.record_error_unfiltered(.return_mismatch, msg, id)
	}
}

fn contextual_payload_type(typ Type) ?Type {
	if typ is OptionType {
		if typ.base_type is Void {
			return none
		}
		return typ.base_type
	}
	if typ is ResultType {
		if typ.base_type is Void {
			return none
		}
		return typ.base_type
	}
	return none
}

fn (mut tc TypeChecker) invalid_ierror_return_expr_type_name(id flat.NodeId, expected ResultType) ?string {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.nodes[int(id)]
	// An explicit return in a match/if branch is checked against the enclosing
	// function independently; it is not a value tail of the outer result expr.
	if node.kind == .return_stmt {
		return none
	}
	raw_type := tc.resolve_type(id)
	if tc.type_compatible(raw_type, expected) {
		return none
	}
	if tc.type_compatible(raw_type, expected.base_type) {
		return none
	}
	if tc.zero_literal_can_be_pointer(id, expected.base_type) {
		return none
	}
	if tc.pointer_value_compatible(raw_type, expected.base_type) {
		return none
	}
	if expected.base_type is Pointer
		&& tc.bare_value_pointer_return_compatible(id, raw_type, expected.base_type.base_type) {
		return none
	}
	payload_type := tc.resolve_expr(id, expected.base_type)
	if tc.type_compatible(payload_type, expected.base_type) {
		return none
	}
	if tc.pointer_value_compatible(payload_type, expected.base_type) {
		return none
	}
	if expected.base_type is Pointer
		&& tc.bare_value_pointer_return_compatible(id, payload_type, expected.base_type.base_type) {
		return none
	}
	match node.kind {
		.expr_stmt, .paren {
			if node.children_count > 0 {
				return tc.invalid_ierror_return_expr_type_name(tc.a.child(&node, 0), expected)
			}
		}
		.prefix {
			if node.op == .amp && node.children_count > 0 {
				return tc.invalid_ierror_return_expr_type_name(tc.a.child(&node, 0), expected)
			}
		}
		.struct_init {
			concrete := tc.resolve_unqualified_builtin_error_struct_name(node.value) or {
				tc.resolve_selective_import_type_symbol(node.value) or {
					tc.qualify_name(node.value)
				}
			}
			if !tc.named_type_compatible_with_ierror(concrete) {
				return concrete
			}
		}
		.match_stmt {
			subject_id := tc.a.child(&node, 0)
			subject_key := tc.expr_key(subject_id)
			subject_type := unalias_type(unwrap_pointer(tc.resolve_type(subject_id)))
			for i in 1 .. node.children_count {
				branch_id := tc.a.child(&node, i)
				if !tc.valid_node_id(branch_id) {
					continue
				}
				branch := tc.a.nodes[int(branch_id)]
				if branch.kind != .match_branch {
					continue
				}
				tail := tc.branch_tail_expr_id(branch_id)
				if subject_key.len > 0 && tc.expr_key(tail) == subject_key && branch.value != 'else'
					&& branch.value.int() == 1 && subject_type is SumType {
					cond := tc.a.node(tc.a.child(&branch, 0))
					if pattern := tc.match_type_pattern(cond) {
						variant := tc.sum_variant_type_for_pattern(subject_type.name, pattern) or {
							pattern
						}
						if tc.type_compatible(tc.parse_type(variant), expected.base_type) {
							continue
						}
					}
				}
				if bad_type := tc.invalid_ierror_return_expr_type_name(tail, expected) {
					return bad_type
				}
			}
		}
		.if_expr {
			if node.children_count > 1 {
				then_tail := tc.branch_tail_expr_id(tc.a.child(&node, 1))
				if bad_type := tc.invalid_ierror_return_expr_type_name(then_tail, expected) {
					return bad_type
				}
			}
			if node.children_count > 2 {
				else_id := tc.a.child(&node, 2)
				else_tail := if tc.valid_node_id(else_id)
					&& tc.a.nodes[int(else_id)].kind == .if_expr {
					else_id
				} else {
					tc.branch_tail_expr_id(else_id)
				}
				if bad_type := tc.invalid_ierror_return_expr_type_name(else_tail, expected) {
					return bad_type
				}
			}
		}
		else {
			if is_ierror_type(raw_type) || tc.type_compatible_with_ierror_payload(raw_type) {
				return none
			}
			if raw_type is Unknown || raw_type is Void {
				return none
			}
			return raw_type.name()
		}
	}

	return none
}

fn (tc &TypeChecker) source_declares_bodyless_function(name string) bool {
	for idx := tc.a.user_code_start; idx < tc.a.nodes.len; idx++ {
		node := tc.a.nodes[idx]
		if node.kind == .c_fn_decl && (node.value == name || node.value.ends_with('.${name}')) {
			return true
		}
	}
	return false
}

fn multi_return_payload_type(typ Type) ?MultiReturn {
	if typ is MultiReturn {
		return typ
	}
	if typ is OptionType {
		base := typ.base_type
		if base is MultiReturn {
			return base
		}
	}
	if typ is ResultType {
		base := typ.base_type
		if base is MultiReturn {
			return base
		}
	}
	return none
}

fn (tc &TypeChecker) multi_return_assignment_type(rhs_id flat.NodeId, rhs_type Type) ?MultiReturn {
	if rhs_type is MultiReturn {
		return rhs_type
	}
	if !tc.expr_has_option_result_handler(rhs_id) {
		return none
	}
	return multi_return_payload_type(rhs_type)
}

fn (tc &TypeChecker) unhandled_wrapped_multi_return_type(rhs_id flat.NodeId, rhs_type Type) ?MultiReturn {
	if rhs_type is MultiReturn || tc.expr_has_option_result_handler(rhs_id) {
		return none
	}
	return multi_return_payload_type(rhs_type)
}

fn (tc &TypeChecker) expr_has_option_result_handler(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .or_expr {
		return true
	}
	if node.kind in [.paren, .expr_stmt] && node.children_count > 0 {
		return tc.expr_has_option_result_handler(tc.a.child(&node, 0))
	}
	return false
}

// check_call validates check call state for types.
fn (mut tc TypeChecker) check_call(id flat.NodeId, node flat.Node) {
	if node.children_count > 0 {
		if tc.check_json_magic_call(id, node) {
			return
		}
		if tc.check_js_call_on_non_js_backend(id, node) {
			return
		}
		callee_id := tc.a.child(&node, 0)
		callee := tc.a.child_node(&node, 0)
		if callee.kind == .ident && callee.value in ['print', 'println', 'eprint', 'eprintln'] {
			for i in 1 .. node.children_count {
				arg_id := tc.call_arg_value(tc.a.child(&node, i))
				if element_id := tc.shared_array_element_index(arg_id) {
					tc.record_error_at(.call_arg_mismatch,
						'you have to create a handle and `rlock` it to use a `shared` element as non-mut argument to print',
						element_id, tc.a.node(element_id).pos)
					continue
				}
				if access := tc.unlocked_shared_access(arg_id) {
					tc.record_error_at(.call_arg_mismatch,
						'`${access.name}` is `shared` and must be `rlock`ed or `lock`ed to be used as non-mut argument to print',
						arg_id, access.pos)
				}
			}
		}
		if indexed_kind := tc.non_function_index_call_kind(node) {
			tc.check_node(callee_id)
			pos := tc.call_closing_paren_pos(node)
			tc.record_error_at(.unknown_fn,
				'cannot call the ${indexed_kind} of the ${tc.non_function_index_container_name(callee)}, it is not a function',
				id, pos)
			tc.record_error_at(.unknown_fn, 'unknown function:', id, pos)
			for i in 1 .. node.children_count {
				tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
			}
			tc.register_synth_type(id, Type(MultiReturn{
				types: []Type{}
			}))
			return
		}
		if callee.kind == .ident && callee.value !in tc.a.disabled_fns
			&& tc.source_declares_bodyless_function(callee.value) {
			tc.record_error_at(.unknown_fn, 'cannot call a function that does not have a body', id,
				node.pos)
			return
		}
		if callee.kind == .selector && callee.children_count > 0 {
			receiver_id := tc.a.child(callee, 0)
			receiver := tc.a.node(receiver_id)
			if callee.value == 'from_string' && receiver.kind == .ident
				&& !tc.ident_resolves_to_value(receiver.value)
				&& tc.static_assoc_fn_key_for_base(receiver.value, callee.value) == none
				&& tc.resolve_enum_name(receiver.value) == none {
				qname := tc.qualify_name(receiver.value)
				if qname in tc.structs || receiver.value in tc.structs {
					tc.record_error_at(.unknown_fn,
						'expected enum, but `${receiver.value}` is struct', id, node.pos)
					return
				}
			}
			if callee.value == 'from_string' && receiver.kind == .ident
				&& !tc.ident_resolves_to_value(receiver.value) {
				if enum_name := tc.resolve_enum_name(receiver.value) {
					arg_count := node.children_count - 1
					if arg_count != 1 {
						tc.record_error_at(.call_arg_mismatch,
							'expected 1 argument, but got ${arg_count}', id, node.pos)
						tc.register_synth_type(id, Type(OptionType{
							base_type: Type(Enum{
								name:    enum_name
								is_flag: enum_name in tc.flag_enums
							})
						}))
						return
					}
					arg_id := tc.call_arg_value(tc.a.child(&node, 1))
					tc.check_node(arg_id)
					actual := tc.resolve_type(arg_id)
					if unalias_type(actual) !is String {
						tc.record_error_at(.call_arg_mismatch, 'expected `string` argument, but got `${tc.diagnostic_expr_type_name(arg_id,
							actual)}`', id, node.pos)
						tc.register_synth_type(id, Type(OptionType{
							base_type: Type(Enum{
								name:    enum_name
								is_flag: enum_name in tc.flag_enums
							})
						}))
						return
					}
				}
			}
			if !(receiver.kind == .ident && receiver.value == 'C') {
				receiver_name := tc.resolve_type(receiver_id).name()
				method_name := '${receiver_name}.${callee.value}'
				if method_name in tc.a.disabled_fns || method_name in tc.source_no_body_fns {
					name_pos := tc.method_call_name_pos(node, callee)
					tc.record_error_at(.unknown_fn,
						'cannot call a method that does not have a body', id, token.new_span(name_pos.id,
						name_pos.offset, node.pos.end))
					return
				}
			}
		}
		if callee.kind == .ident && callee.value == 'main' && !tc.cur_file.ends_with('_test.v') {
			tc.record_error_at(.call_arg_mismatch,
				'the `main` function cannot be called in the program', id, node.pos)
		}
		if callee.kind == .ident && (callee.value in tc.fn_generic_params
			|| tc.qualify_fn_name(callee.value) in tc.fn_generic_params) {
			for i in 1 .. node.children_count {
				arg_id := tc.call_arg_value(tc.a.child(&node, i))
				arg := tc.a.node(arg_id)
				if arg.kind == .none_expr {
					tc.record_error_at(.call_arg_mismatch, 'cannot use `none` as generic argument',
						arg_id, arg.pos)
					return
				}
			}
		}
		if callee.kind == .call {
			tc.check_node(callee_id)
		}
		if callee.kind == .index && callee.children_count > 1 {
			mut has_unbound_generic_type_arg := false
			for i in 1 .. callee.children_count {
				type_arg_id := tc.a.child(callee, i)
				type_arg := tc.a.node(type_arg_id)
				if type_arg.kind == .ident
					&& (type_arg.value.starts_with('?') || type_arg.value.starts_with('!')) {
					tc.record_error_at(.call_arg_mismatch,
						'cannot use Option type name as concrete type', type_arg_id, token.new_span(type_arg.pos.id,
						type_arg.pos.offset, type_arg.pos.offset + 1))
					return
				}
				type_name := tc.generic_call_type_arg_name(type_arg_id)
				if is_bare_generic_param(type_name) && !tc.type_name_known(type_name)
					&& type_name !in tc.fn_context.generic_params
					&& !tc.active_generic_param(type_name)
					&& !tc.node_has_enclosing_generic_param(type_arg_id, type_name)
					&& !tc.source_enclosing_fn_has_generic_param(type_arg_id, type_name) {
					has_unbound_generic_type_arg = true
				}
				if type_name.len > 1 && !tc.type_text_has_generic_placeholder(type_name) {
					if should_check_named_type(type_name) && !tc.type_name_known(type_name) {
						tc.record_error_at(.unknown_type, tc.unknown_type_message(type_name,
							type_arg_id), type_arg_id,
							tc.generic_type_arg_diagnostic_pos(type_arg_id))
						tc.register_synth_type(id, unknown_type('invalid generic type argument'))
						continue
					}
					before := tc.errors.len
					tc.check_type_string_for_unsupported_generics(type_name, type_arg_id,
						generic_param_map_from_names(tc.fn_context.generic_params))
					if tc.errors.len > before {
						tc.register_synth_type(id, unknown_type('invalid generic type argument'))
					}
				}
			}
			if has_unbound_generic_type_arg {
				tc.record_error_at(.unsupported_generic,
					'generic fn using generic types cannot be called outside of generic fn', id,
					node.pos)
				tc.register_synth_type(id, unknown_type('generic call with unbound type argument'))
				return
			}
		}
		if callee.kind == .ident && tc.ident_resolves_to_value(callee.value) {
			callee_type := unalias_type(tc.resolve_type(callee_id))
			if callee_type is OptionType && fn_type_from_type(callee_type.base_type) != none {
				tc.record_error_at(.call_arg_mismatch,
					'type `${tc.resolve_type(callee_id).name()}` is an Option, it must be unwrapped first',
					id, node.pos)
				return
			}
			if callee_type is Pointer && fn_type_from_type(callee_type.base_type) != none {
				tc.record_error_at(.call_arg_mismatch,
					'function pointer must be undereferenced first', id, node.pos)
				return
			}
		}
		if callee.kind == .selector {
			if callee.children_count > 0 {
				base := tc.a.child_node(callee, 0)
				if base.kind == .ident && !tc.ident_resolves_to_value(base.value) {
					for type_name in [base.value, tc.qualify_name(base.value)] {
						key := '${type_name}.${callee.value}'
						if tc.fn_signature_known(key) && !tc.fn_key_is_static_associated(key)
							&& tc.static_assoc_type_known(type_name) {
							tc.record_error(.unknown_fn,
								'unknown function: ${base.value}.${callee.value}', id)
							tc.register_synth_type(id, Type(MultiReturn{
								types: []Type{}
							}))
							return
						}
					}
				}
				c_name := 'C.${callee.value}'
				if base.kind == .ident && base.value == 'C' && c_name !in tc.fn_ret_types
					&& c_name !in tc.structs {
					tc.record_error_at(.unknown_fn,
						'unknown C function: `${c_name}`. `C.` calls are external C calls; declare the function with `fn ${c_name}(...)` and include/link the C header/library that provides it.',
						id, tc.method_call_name_pos(node, callee))
					tc.register_synth_type(id, Type(MultiReturn{
						types: []Type{}
					}))
					return
				}
			}
			if wrapped_fn := tc.selector_declared_value_type(*callee) {
				if wrapped_fn is OptionType && fn_type_from_type(wrapped_fn.base_type) != none {
					name_pos := tc.method_call_name_pos(node, callee)
					tc.record_error_at(.call_arg_mismatch,
						'Option function field must be unwrapped first', id, token.new_span(name_pos.id,
						name_pos.offset, node.pos.end))
					return
				}
			}
			if callee.children_count > 0 {
				receiver_id := tc.a.child(callee, 0)
				receiver_type := unalias_type(tc.resolve_type(receiver_id))
				if callee.value == 'str' && receiver_type is Char {
					tc.record_error_at(.call_arg_mismatch,
						'calling `.str()` on type `char` is not allowed, use its address or cast it to an integer instead',
						id, node.pos)
					tc.register_synth_type(id, Type(string_))
					return
				}
				if callee.value == 'str' && receiver_type is Interface
					&& tc.interface_method_signature_key(receiver_type.name, 'str') == none {
					name_pos := tc.method_call_name_pos(node, callee)
					tc.record_error_at(.unknown_fn,
						'interface `${receiver_type.name.all_after_last('.')}` does not have a .str() method. Use typeof() instead',
						id, token.new_span(name_pos.id, name_pos.offset, node.pos.end))
					tc.remember_resolved_call(id, '${receiver_type.name}.str')
					tc.register_synth_type(id, Type(string_))
					return
				}
				if receiver_type is OptionType {
					tc.record_error_at(.call_arg_mismatch,
						'Option type `${tc.wrapped_receiver_payload_diagnostic_name(receiver_type.base_type)}` cannot be called directly, you should unwrap it first',
						receiver_id, tc.wrapped_operand_diagnostic_pos(receiver_id))
					return
				}
				if receiver_type is ResultType {
					tc.record_unhandled_result_call(receiver_id, receiver_type)
					tc.record_error_at(.call_arg_mismatch, 'Result type cannot be called directly',
						receiver_id, tc.wrapped_operand_diagnostic_pos(receiver_id))
					if tc.wrapped_receiver_has_method(receiver_type.base_type, callee.value) {
						tc.record_error_at(.call_arg_mismatch,
							'${callee.value}() returns `!${receiver_type.base_type.name()}`, so it should have either an `or {}` block, or `!` at the end',
							id, tc.method_call_name_pos(node, callee))
					}
					return
				}
			}
		}
		if callee.kind == .fn_literal || callee.kind == .lambda_expr {
			tc.check_node(callee_id)
		}
		if callee.kind == .ident && (callee.value in tc.fn_ret_types
			|| tc.qualify_fn_name(callee.value) in tc.fn_ret_types) {
			if _ := tc.non_file_scope_type(callee.value) {
				tc.record_error(.call_arg_mismatch,
					'ambiguous call to: `${callee.value}`, may refer to fn `${callee.value}` or variable `${callee.value}`',
					id)
			}
		}
		if callee.kind == .ident && callee.value == '__v_compile_error' {
			current_fn_id := flat.NodeId(tc.fn_context.node_id)
			if tc.valid_node_id(current_fn_id) && tc.a.node(current_fn_id).generic_params().len > 0 {
				return
			}
			message := if node.children_count > 1 {
				arg := tc.a.child_node(&node, 1)
				if arg.value.len > 0 {
					arg.value
				} else {
					'compile-time error'
				}
			} else {
				'compile-time error'
			}
			if !tc.has_type_error(.compile_error, message, id) {
				tc.record_error_unfiltered(.compile_error, message, id)
			}
			return
		}
		if callee.kind == .ident && callee.value == '__v_compile_warn' {
			current_fn_id := flat.NodeId(tc.fn_context.node_id)
			if tc.valid_node_id(current_fn_id) {
				current_fn := tc.a.node(current_fn_id)
				if current_fn.generic_params().len > 0
					|| tc.specialized_generic_fns[current_fn.value]
					|| (int(current_fn_id) < tc.a.specialized_fn_nodes.len
					&& tc.a.specialized_fn_nodes[int(current_fn_id)]) {
					return
				}
			}
			message := if node.children_count > 1 {
				arg := tc.a.child_node(&node, 1)
				if arg.value.len > 0 {
					arg.value
				} else {
					'compile-time warning'
				}
			} else {
				'compile-time warning'
			}
			if !tc.has_type_notice(.compile_error, message, id) {
				tc.record_warning_at(.compile_error, message, id, node.pos)
			}
			return
		}
		if callee.kind == .selector && callee.value.starts_with('$') && callee.value.len > 1 {
			tc.check_dynamic_comptime_method_call(id, node, callee)
			return
		}
		if callee.kind == .selector && callee.value == '$' {
			for i in 1 .. node.children_count {
				tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
			}
			return
		}
		if callee.kind == .selector && callee.children_count > 0 {
			receiver_id := tc.a.child(callee, 0)
			receiver := tc.a.nodes[int(receiver_id)]
			if receiver.kind == .ident && receiver.value == 'C' && 'C.${callee.value}' in tc.structs
				&& node.children_count == 2 {
				arg_id := tc.call_arg_value(tc.a.child(&node, 1))
				if tc.expr_tail_is_nil(arg_id)
					&& tc.source_text_for_node(arg_id).starts_with('unsafe') {
					name_pos := tc.method_call_name_pos(node, callee)
					tc.record_error_at(.assignment_mismatch, 'cannot cast `voidptr` to struct', id, token.new_span(name_pos.id,
						name_pos.offset, node.pos.end))
					return
				}
			}
			receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(receiver_id))
			if receiver_type is Struct {
				candidates := tc.embedded_method_candidates(receiver_type.name, callee.value)
				if candidates.len > 1 {
					pos := tc.method_call_name_pos(node, callee)
					tc.record_error_at(.unknown_fn, 'ambiguous method `${callee.value}`', id, pos)
					tc.record_error_at(.unknown_fn,
						'unknown method or field: `${receiver_type.name}.${callee.value}`', id, pos)
					return
				}
			}
		}
		if callee.kind == .selector && callee.value == 'free' && callee.children_count > 0 {
			receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(callee, 0)))
			receiver_name := receiver_type.name()
			if receiver_type is ArrayFixed {
				tc.record_error_at(.call_arg_mismatch,
					'unknown method or field: ${receiver_name}.free()', id, tc.method_call_name_pos(node,
					callee))
				return
			}
		}
		if callee.kind == .selector && callee.children_count > 0
			&& callee.value in ['clear', 'delete', 'delete_last', 'insert', 'pop', 'pop_left', 'prepend', 'reverse_in_place', 'sort', 'sort_with_compare'] {
			receiver_id := tc.a.child(callee, 0)
			receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(receiver_id))
			if receiver_type is ArrayFixed && callee.value != 'sort' {
				tc.check_builtin_array_mutable_receiver(receiver_id)
			}
		}
		if callee.kind == .selector && callee.value == 'sort' && callee.children_count > 0 {
			receiver_id := tc.a.child(callee, 0)
			receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(receiver_id))
			if receiver_type is Array || receiver_type is ArrayFixed {
				receiver := tc.a.nodes[int(receiver_id)]
				if receiver.kind == .call {
					tc.record_error_at(.call_arg_mismatch,
						'the `sort()` method can be called only on mutable receivers, but `${tc.call_display_name(receiver)}()` is a call expression',
						id, tc.method_call_name_pos(node, callee))
					tc.record_error(.call_arg_mismatch, 'cannot pass expression as `mut`',
						receiver_id)
					return
				}
				if tc.unsafe_depth == 0 && !tc.expr_is_inside_unsafe_block(id) {
					tc.check_builtin_array_mutable_receiver(receiver_id)
				}
				tc.check_array_sort_call(id, node, callee)
				return
			}
		}
		if callee.kind == .ident && callee.value in ['print', 'println', 'eprint', 'eprintln']
			&& node.children_count > 1 {
			arg_id := tc.call_arg_value(tc.a.child(&node, 1))
			arg_node := tc.a.node(arg_id)
			arg_type := if arg_node.kind == .selector {
				tc.selector_type(arg_id, arg_node) or { tc.resolve_type(arg_id) }
			} else {
				tc.resolve_type(arg_id)
			}
			if arg_type is Char {
				tc.record_error_at(.call_arg_mismatch,
					'`${callee.value}` cannot print type `char` directly, print its address or cast it to an integer instead',
					id, node.pos)
				return
			}
			arg_is_void := arg_type is Void || (arg_type is MultiReturn && arg_type.types.len == 0)
			arg_is_send := arg_node.kind == .infix && arg_node.op == .arrow
			has_wrapped_receiver := tc.call_has_wrapped_receiver(arg_id)
			invalid_pointer_infix := tc.invalid_pointer_infix_print_arg(arg_id)
			invalid_index_call := tc.invalid_non_function_index_call(arg_id)
			invalid_interface_selector := tc.invalid_interface_selector_print_arg(arg_id)
			invalid_struct_selector := tc.invalid_struct_selector_print_arg(arg_id)
			invalid_unknown_method := tc.invalid_unknown_method_print_arg(arg_id)
			invalid_import_function := tc.invalid_unknown_import_function_print_arg(arg_id)
			if arg_is_void || arg_is_send || has_wrapped_receiver || invalid_pointer_infix
				|| invalid_index_call || invalid_interface_selector || invalid_struct_selector
				|| invalid_unknown_method || invalid_import_function {
				if arg_is_void && tc.unresolved_local_method_call(arg_id) {
					return
				}
				tc.check_node(arg_id)
				if tc.resolution_type_mode {
					return
				}
				if type_has_runtime_value(tc.resolve_type(arg_id)) {
					return
				}
				if !tc.expr_subtree_has_error(arg_id) || tc.a.node(arg_id).kind == .infix
					|| arg_node.kind == .defer_result || invalid_index_call
					|| invalid_interface_selector || invalid_struct_selector
					|| invalid_unknown_method || invalid_import_function || has_wrapped_receiver {
					tc.record_error(.call_arg_mismatch,
						'`${callee.value}` can not print void expressions', id)
				}
				return
			}
		}
	}
	if local_fn := tc.explicit_generic_local_fn_value(node) {
		for i in 1 .. node.children_count {
			tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
		}
		tc.remember_expr_type(id, local_fn.return_type)
		return
	}
	if tc.call_has_explicit_generic_type_args(node) {
		callee_id := tc.a.child(&node, 0)
		callee := tc.a.node(callee_id)
		base := tc.a.child_node(callee, 0)
		if target := tc.generic_call_base_name(*base) {
			if (tc.fn_generic_params[target] or { []string{} }).len == 0 {
				tc.record_error_at(.unsupported_generic,
					'a non generic function called like a generic one', callee_id,
					tc.explicit_generic_args_diagnostic_pos(callee_id))
				for i in 1 .. node.children_count {
					tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
				}
				if return_type := tc.fn_ret_types[target] {
					tc.remember_expr_type(id, return_type)
				}
				return
			}
		}
	}
	if !tc.resolution_type_mode && tc.call_has_explicit_generic_type_args(node)
		&& !tc.explicit_generic_call_target_is_known(node)
		&& !tc.call_generic_args_have_placeholders(node) {
		if tc.should_diagnose(id) {
			tc.record_error(.unknown_fn, 'unknown function: ${tc.call_display_name(node)}', id)
		}
		for i in 1 .. node.children_count {
			tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
		}
		return
	}
	if arg_id := tc.builtin_isreftype_call_arg(node) {
		tc.check_isreftype_arg(arg_id)
		tc.remember_expr_type(id, Type(bool_))
		return
	}
	if arg_id := tc.builtin_addr_call_arg(node) {
		if tc.unsafe_depth == 0 {
			tc.record_error(.call_arg_mismatch, '`__addr` must be called from an unsafe block', id)
		}
		arg_type := tc.resolve_type(arg_id)
		tc.remember_expr_type(id, Type(Pointer{
			base_type: arg_type
		}))
		return
	}
	if sum_name := tc.sum_constructor_call_name(node) {
		tc.check_sum_constructor_call(id, node, sum_name)
		return
	}
	if info0 := tc.resolve_call_info(id, node) {
		if tc.record_empty_array_generic_call_errors(node, info0) {
			return
		}
		if !info0.has_receiver && !tc.call_has_explicit_generic_type_args(node)
			&& tc.call_generic_params(info0.name).len > 0
			&& node.children_count == 1 + info0.arg_offset {
			tc.record_error_at(.unsupported_generic,
				'no argument generic function must add concrete types, e.g. foo[int]()', id,
				node.pos)
			tc.register_synth_type(id, unknown_type('generic call without concrete type arguments'))
			return
		}
		info := tc.specialized_plain_generic_call_info(node, info0)
		tc.record_uninferred_generic_method_type(id, node, info0)
		tc.record_chained_bare_generic_struct_method_inference_error(id, node, info)
		if info.name.len > 0 && !is_array_dsl_call_name(info.name) {
			tc.remember_resolved_call(id, info.name)
		}
		if info.return_type !is Void && info.return_type !is Unknown {
			tc.remember_expr_type(id, info.return_type)
		}
		if tc.check_call_privacy(id, node, info) {
			return
		}
		if tc.unsafe_depth == 0 && !tc.node_is_in_translated_file(id) && info.name in tc.unsafe_fns
			&& info.name !in ['map.delete', 'builtin.map.delete'] {
			callee := tc.a.child_node(&node, 0)
			if info.has_receiver && callee.kind == .selector {
				method_name := info.name.trim_string_left('main.')
				name_pos := tc.method_call_name_pos(node, callee)
				tc.record_warning_at(.call_arg_mismatch,
					'method `${method_name}` must be called from an `unsafe` block', id, token.new_span(name_pos.id,
					name_pos.offset, node.pos.end))
			} else {
				tc.record_warning_at(.call_arg_mismatch,
					'function `${tc.call_display_name(node)}` must be called from an `unsafe` block',
					id, node.pos)
			}
		}
		tc.check_call_deprecation(id, node, info)
		tc.check_call_arg_types(id, node, info)
		tc.check_os_file_raw_io_call(id, node, info)
		tc.check_instantiated_generic_as_casts(node, info)
		tc.check_instantiated_generic_compile_errors(id, node, info)
		tc.check_instantiated_generic_compile_warnings(node, info)
		$if ownership ? {
			tc.ownership_after_call(id, node, info)
		}
		return
	}
	if tc.is_unsupported_hex_call(node) {
		if tc.should_diagnose(id) {
			tc.record_error(.unknown_fn, 'unknown function: ${tc.call_display_name(node)}', id)
		}
		return
	}
	if tc.call_has_ambiguous_selective_import(node) {
		tc.record_error(.unknown_fn, 'ambiguous selective import `${tc.call_display_name(node)}`',
			id)
		return
	}
	if tc.should_diagnose(id) && !tc.is_known_call(node)
		&& !tc.call_generic_args_have_placeholders(node) && (!tc.call_receiver_type_is_unknown(node)
		|| tc.unknown_import_function_call_parts(node) != none) {
		if !tc.record_unknown_import_function_call(id, node) {
			if tc.record_unknown_method_call(id, node) {
				return
			}
			tc.record_error(.unknown_fn, 'unknown function: ${tc.call_display_name(node)}', id)
			tc.register_synth_type(id, Type(MultiReturn{
				types: []Type{}
			}))
		}
	}
	dsl_name := tc.unresolved_array_dsl_call_name(node)
	if dsl_name.len > 0 {
		tc.push_array_dsl_scope(node, dsl_name)
	}
	for i in 1 .. node.children_count {
		tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
	}
	if dsl_name.len > 0 {
		tc.pop_scope()
	}
}

fn os_raw_io_unsupported_type_message(path string, type_name string) string {
	if path.len == 0 {
		return 'contains non-plain-data values of type `${type_name}`'
	}
	return 'contains field `${path}` of type `${type_name}`'
}

fn (tc &TypeChecker) os_raw_io_unsupported_type(typ Type, path string, mut checked map[string]bool) ?string {
	original_name := typ.name()
	mut clean := typ
	for clean is OptionType || clean is ResultType {
		clean = match clean {
			OptionType { clean.base_type }
			ResultType { clean.base_type }
			else { clean }
		}
	}
	clean = unalias_type(clean)
	if clean is Pointer {
		return os_raw_io_unsupported_type_message(path, original_name)
	}
	match clean {
		String, Array, Map, Channel, FnType, Interface, SumType, MultiReturn, Nil, None {
			return os_raw_io_unsupported_type_message(path, original_name)
		}
		ArrayFixed {
			if tc.os_raw_io_unsupported_type(clean.elem_type, path, mut checked) != none {
				return os_raw_io_unsupported_type_message(path, original_name)
			}
		}
		Struct {
			if checked[clean.name] {
				return none
			}
			checked[clean.name] = true
			for field in tc.struct_fields_for_init(clean.name) {
				field_path := if path.len == 0 {
					field.name
				} else {
					'${path}.${field.name}'
				}
				if reason := tc.os_raw_io_unsupported_type(field.typ, field_path, mut checked) {
					return reason
				}
			}
		}
		else {}
	}
	return none
}

fn (tc &TypeChecker) os_raw_io_call_result_pos(node flat.Node, method string) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	position := file.position(node.pos)
	line_start := file.line_start(position.line)
	mut line_end := source.index_after('\n', line_start) or { source.len }
	for line_end > line_start && source[line_end - 1] in [`\n`, `\r`] {
		line_end--
	}
	line := source[line_start..line_end]
	method_relative := line.index('.${method}') or { return node.pos }
	start := line_start + method_relative + 1
	return token.new_span(node.pos.id, start, line_end)
}

fn (mut tc TypeChecker) check_os_file_raw_io_call(id flat.NodeId, node flat.Node, info CallInfo) {
	if !info.has_receiver || !info.name.contains('os.File.') {
		return
	}
	method := info.name.all_after_last('.')
	if method !in ['write_struct', 'write_struct_at', 'write_raw', 'write_raw_at', 'read_struct',
		'read_struct_at', 'read_raw', 'read_raw_at'] {
		return
	}
	mut raw_type := Type(Unknown{})
	mut diagnostic_id := flat.empty_node
	mut diagnostic_pos := node.pos
	mut explicit_type_arg_id := flat.empty_node
	callee := tc.a.child_node(&node, 0)
	if callee.kind == .index && callee.children_count > 1 {
		explicit_type_arg_id = tc.a.child(callee, callee.children_count - 1)
		type_name := tc.generic_call_type_arg_name(explicit_type_arg_id)
		if type_name.len > 0 {
			raw_type = tc.parse_type(type_name)
		}
	}
	if method.starts_with('read_raw') {
		if raw_type is Unknown {
			result_type := unalias_type(info.return_type)
			raw_type = match result_type {
				ResultType { result_type.base_type }
				OptionType { result_type.base_type }
				else { result_type }
			}
		}
		diagnostic_id = id
		diagnostic_pos = tc.os_raw_io_call_result_pos(node, method)
	} else if node.children_count > 1 + info.arg_offset {
		diagnostic_id = tc.call_arg_value(tc.a.child(&node, 1 + info.arg_offset))
		tc.check_node(diagnostic_id)
		raw_type = tc.resolve_type(diagnostic_id)
		diagnostic_pos = tc.a.node(diagnostic_id).pos
	}
	for raw_type is Pointer {
		raw_type = raw_type.base_type
	}
	if raw_type is Unknown || raw_type is Void {
		return
	}
	clean_type := unalias_type(raw_type)
	if method.contains('struct') && clean_type !is Struct {
		struct_pos := if tc.valid_node_id(explicit_type_arg_id) {
			tc.generic_type_arg_diagnostic_pos(explicit_type_arg_id)
		} else {
			diagnostic_pos
		}
		tc.record_error_at(.call_arg_mismatch,
			'`os.File.${method}` expects a struct type, but got `${raw_type.name()}`',
			diagnostic_id, struct_pos)
	}
	mut checked := map[string]bool{}
	if reason := tc.os_raw_io_unsupported_type(raw_type, '', mut checked) {
		tc.record_error_at(.call_arg_mismatch,
			'`os.File.${method}` only supports plain data types; `${raw_type.name()}` ${reason}',
			diagnostic_id, diagnostic_pos)
	}
}

fn (tc &TypeChecker) unresolved_local_method_call(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	call := tc.a.node(id)
	if call.kind != .call || call.children_count == 0 {
		return false
	}
	callee := tc.a.child_node(call, 0)
	if callee.kind != .selector || callee.children_count == 0 {
		return false
	}
	receiver := tc.a.child_node(callee, 0)
	if receiver.kind != .ident || receiver.value.len == 0 || receiver.value[0] < `a`
		|| receiver.value[0] > `z` {
		return false
	}
	if _ := tc.non_file_scope_type(receiver.value) {
		return false
	}
	return true
}

fn (mut tc TypeChecker) check_json_magic_call(id flat.NodeId, node flat.Node) bool {
	name := tc.call_display_name(node)
	if name in ['json.encode', 'json.encode_pretty'] && node.children_count > 1 {
		arg_id := tc.call_arg_value(tc.a.child(&node, 1))
		if tc.expr_is_shared_arg(arg_id) {
			tc.check_node(arg_id)
			tc.record_error_at(.call_arg_mismatch, 'json.encode cannot handle shared data', id,
				tc.magic_call_diagnostic_pos(node))
			tc.register_synth_type(id, Type(void_))
			tc.record_enclosing_print_void(id)
			return true
		}
		return false
	}
	if name != 'json.decode' || node.children_count < 2 {
		return false
	}
	type_arg_id := tc.a.child(&node, 1)
	mut type_name := tc.generic_call_type_arg_name(type_arg_id)
	if type_name.len == 0 {
		type_name = tc.json_decode_type_arg_text(id)
	}
	if type_name.len == 0 {
		return false
	}
	call_pos := tc.magic_call_diagnostic_pos(node)
	if node.children_count < 3 {
		tc.record_error_at(.call_arg_mismatch,
			"json.decode expects 2 arguments, a type and a string (e.g `json.decode(T, '')`)", id,
			call_pos)
		tc.register_synth_type(id, Type(void_))
		return true
	}
	target_type := tc.parse_type(type_name)
	if target_type is Pointer {
		pointer_pos := tc.type_diagnostic_pos(type_arg_id, '&')
		tc.record_error_at(.unknown_type, 'json.decode: cannot decode into a pointer type',
			type_arg_id,
			token.new_span(pointer_pos.id, pointer_pos.offset + 1, pointer_pos.end + 1))
		tc.register_synth_type(id, Type(ResultType{
			base_type: target_type
		}))
		return true
	}
	if !tc.type_name_known(type_name) {
		tc.record_error_at(.unknown_type, 'json.decode: unknown type `${type_name}`', id, call_pos)
		tc.register_synth_type(id, unknown_type('unknown json.decode target'))
		return true
	}
	clean_target := unalias_type(target_type)
	if clean_target !is Struct && clean_target !is SumType && clean_target !is Map
		&& clean_target !is Array && clean_target !is ArrayFixed {
		tc.record_error_at(.unknown_type,
			'json.decode: expected sum type, struct, map or array, found ${clean_target.name()}',
			type_arg_id, tc.a.node(type_arg_id).pos)
		tc.register_synth_type(id, Type(ResultType{
			base_type: target_type
		}))
		return true
	}
	value_id := tc.call_arg_value(tc.a.child(&node, 2))
	tc.check_node(value_id)
	if unalias_type(tc.resolve_type(value_id)) !is String {
		tc.record_error_at(.call_arg_mismatch, 'json.decode: second argument needs to be a string',
			id, call_pos)
		tc.register_synth_type(id, Type(ResultType{
			base_type: target_type
		}))
		return true
	}
	return false
}

fn (tc &TypeChecker) json_decode_type_arg_text(id flat.NodeId) string {
	source := tc.source_text_for_node(id)
	open_paren := source.index_u8(`(`)
	if open_paren < 0 {
		return ''
	}
	mut depth := 0
	for i := open_paren + 1; i < source.len; i++ {
		match source[i] {
			`(`, `[`, `{` {
				depth++
			}
			`)` {
				if depth == 0 {
					return source[open_paren + 1..i].trim_space()
				}
				depth--
			}
			`]`, `}` {
				if depth > 0 {
					depth--
				}
			}
			`,` {
				if depth == 0 {
					return source[open_paren + 1..i].trim_space()
				}
			}
			else {}
		}
	}
	return ''
}

fn (tc &TypeChecker) magic_call_diagnostic_pos(node flat.Node) token.Pos {
	if node.children_count == 0 {
		return node.pos
	}
	callee_id := tc.a.child(&node, 0)
	name_pos := tc.node_value_diagnostic_pos(callee_id)
	return token.new_span(name_pos.id, name_pos.offset, node.pos.end)
}

fn (mut tc TypeChecker) check_js_call_on_non_js_backend(id flat.NodeId, node flat.Node) bool {
	source := tc.source_text_for_node(id)
	if !source.starts_with('JS.') {
		return false
	}
	open_paren := source.index_u8(`(`)
	if open_paren < 3 {
		return false
	}
	full_name := source[..open_paren]
	short_name := full_name[3..]
	params := tc.fn_param_types[full_name] or { tc.fn_param_types[short_name] or { return false } }
	actual_count := int(node.children_count) - 1
	for i in 1 .. node.children_count {
		tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
	}
	if actual_count > params.len {
		pos := token.new_span(node.pos.id, node.pos.offset + 3, node.pos.end)
		tc.record_error_at(.call_arg_mismatch,
			'too many arguments in call to `${full_name}` (non-js backend: c)', id, pos)
	}
	tc.register_synth_type(id, tc.fn_ret_types[full_name] or {
		tc.fn_ret_types[short_name] or { Type(void_) }
	})
	return true
}

fn (mut tc TypeChecker) check_call_privacy(id flat.NodeId, node flat.Node, info CallInfo) bool {
	if info.name.len == 0 {
		return false
	}
	if _ := tc.private_declaration(info.name) {
		callee := tc.a.child_node(&node, 0)
		if info.has_receiver && callee.kind == .selector && callee.children_count > 0 {
			receiver_id := tc.a.child(callee, 0)
			name_pos := tc.method_call_name_pos(node, callee)
			receiver_type := tc.resolve_type(receiver_id)
			if callee.value == 'slice' && unalias_type(receiver_type) is Array {
				tc.record_error_at(.unknown_fn,
					'.slice() is a private method, use `x[start..end]` instead', id, token.new_span(name_pos.id,
					name_pos.offset, node.pos.end))
				tc.register_synth_type(id, Type(void_))
				tc.record_enclosing_print_void(id)
				return true
			}
			receiver_name := receiver_type.name()
			name := '${receiver_name}.${callee.value}'
			tc.record_error_at(.unknown_fn, 'method `${name}` is private', id, token.new_span(name_pos.id,
				name_pos.offset, node.pos.end))
			return true
		}
		tc.record_error_at(.unknown_fn, 'function `${info.name}` is private', id, node.pos)
		return true
	}
	return false
}

fn (tc &TypeChecker) non_function_index_call_kind(call flat.Node) ?string {
	if call.kind != .call || call.children_count == 0 {
		return none
	}
	callee_id := tc.a.child(&call, 0)
	callee := tc.a.node(callee_id)
	if callee.kind != .index || callee.value == 'range' || callee.children_count == 0
		|| fn_type_from_type(unalias_type(tc.resolve_type(callee_id))) != none {
		return none
	}
	base_type := unalias_type(tc.resolve_type(tc.a.child(callee, 0)))
	if base_type is Map {
		return 'value'
	}
	if base_type is Array || base_type is ArrayFixed {
		return 'element'
	}
	return none
}

fn (tc &TypeChecker) non_function_index_container_name(index flat.Node) string {
	if index.children_count == 0 {
		return 'container'
	}
	base_type := unalias_type(tc.resolve_type(tc.a.child(&index, 0)))
	return if base_type is Map { 'map' } else { 'array' }
}

fn (tc &TypeChecker) invalid_non_function_index_call(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	return tc.non_function_index_call_kind(*tc.a.node(id)) != none
}

fn (tc &TypeChecker) call_closing_paren_pos(node flat.Node) token.Pos {
	if !node.pos.is_valid() || node.pos.end <= node.pos.offset {
		return node.pos
	}
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	end := int_min(node.pos.end, source.len)
	if end > node.pos.offset && source[end - 1] == `)` {
		return token.new_span(node.pos.id, end - 1, end)
	}
	return node.pos
}

fn (tc &TypeChecker) call_generic_params(name string) []string {
	qualified := tc.qualify_fn_name(name)
	if params := tc.fn_generic_params[qualified] {
		return params
	}
	if qualified != name && tc.fn_signature_known(qualified) {
		return []string{}
	}
	return tc.fn_generic_params[name] or { []string{} }
}

fn (mut tc TypeChecker) record_chained_bare_generic_struct_method_inference_error(id flat.NodeId, node flat.Node, info CallInfo) {
	if !info.has_receiver || node.children_count == 0 {
		return
	}
	mut callee := tc.a.child_node(&node, 0)
	if callee.kind == .index && callee.children_count > 0 {
		callee = tc.a.child_node(callee, 0)
	}
	if callee.kind != .selector || callee.children_count == 0 {
		return
	}
	receiver := tc.a.child_node(callee, 0)
	if receiver.kind != .struct_init || generic_type_application(receiver.value) {
		return
	}
	base := trimmed_space(receiver.value)
	qualified := tc.qualify_name(base)
	struct_params := tc.struct_generic_params[base] or {
		tc.struct_generic_params[qualified] or { return }
	}
	if struct_params.len == 0 {
		return
	}
	inferred := tc.infer_generic_struct_init_param_texts(*receiver, base, struct_params)
	mut missing := ''
	for param in struct_params {
		arg := inferred[param] or {
			missing = param
			break
		}
		if tc.type_text_has_generic_placeholder(arg) {
			missing = param
			break
		}
	}
	if missing.len == 0 {
		return
	}
	name_pos := tc.method_call_name_pos(node, callee)
	tc.record_error_at(.unsupported_generic,
		'could not infer generic type `${missing}` in call to `${callee.value}`', id, token.new_span(name_pos.id,
		name_pos.offset, node.pos.end))
}

fn (mut tc TypeChecker) record_uninferred_generic_method_type(id flat.NodeId, node flat.Node, info CallInfo) {
	if !info.has_receiver || tc.call_has_explicit_generic_type_args(node)
		|| node.children_count == 0 {
		return
	}
	generic_params := tc.fn_generic_params[info.name] or { return }
	param_texts := tc.fn_param_type_texts[info.name] or { return }
	if generic_params.len == 0 {
		return
	}
	mut inferred := map[string]string{}
	mut first_param_idx := 0
	mut callee := tc.a.child_node(&node, 0)
	if callee.kind == .index && callee.children_count > 0 {
		callee = tc.a.child_node(callee, 0)
	}
	if callee.kind == .selector && callee.children_count > 0 && param_texts.len > 0 {
		receiver_id := tc.a.child(callee, 0)
		tc.infer_generic_type_text_from_type(param_texts[0], tc.resolve_type(receiver_id),
			generic_params, mut inferred)
		first_param_idx = 1
	}
	for param_idx in first_param_idx .. param_texts.len {
		arg_idx := param_idx - first_param_idx + 1 + info.arg_offset
		if arg_idx >= node.children_count {
			break
		}
		arg_id := tc.call_arg_value(tc.a.child(&node, arg_idx))
		tc.infer_generic_type_text_from_type(param_texts[param_idx], tc.resolve_type(arg_id),
			generic_params, mut inferred)
	}
	mut missing := ''
	for param in generic_params {
		arg := inferred[param] or {
			missing = param
			break
		}
		if tc.type_text_has_generic_placeholder(arg) {
			missing = param
			break
		}
	}
	if missing.len == 0 || callee.kind != .selector {
		return
	}
	name_pos := tc.method_call_name_pos(node, callee)
	tc.record_error_at(.unsupported_generic,
		'could not infer generic type `${missing}` in call to `${callee.value}`', id, token.new_span(name_pos.id,
		name_pos.offset, node.pos.end))
}

fn (mut tc TypeChecker) record_empty_array_generic_call_errors(node flat.Node, info CallInfo) bool {
	mut generic_params := tc.fn_generic_params[info.name] or { []string{} }
	if generic_params.len == 0 {
		canonical := tc.canonical_symbol(info.name)
		generic_params = tc.fn_generic_params[canonical] or { []string{} }
	}
	if generic_params.len == 0 {
		decl_module := tc.fn_type_modules[info.name] or { tc.cur_module }
		if decl := tc.visible_mutation_fn_decl(info.name, decl_module) {
			generic_params = tc.infer_decl_generic_param_names(tc.a.node(flat.NodeId(decl.idx)))
		}
	}
	if generic_params.len == 0 {
		return false
	}
	mut found := false
	for i in 1 .. node.children_count {
		arg_id := tc.call_arg_value(tc.a.child(&node, i))
		arg := tc.a.node(arg_id)
		if arg.kind == .array_literal && arg.children_count == 0 && arg.typ.len == 0 {
			tc.record_error_at(.call_arg_mismatch, 'cannot use empty array as generic argument',
				arg_id, arg.pos)
			found = true
		}
	}
	return found
}

struct GenericCompileErrorInstantiation {
	decl_id        flat.NodeId
	generic_params []string
	concrete_args  []string
	symbol_types   map[string]string
}

struct InstantiatedCompileWarning {
	message string
	node    flat.NodeId
	pos     token.Pos
}

fn (mut tc TypeChecker) check_instantiated_generic_compile_errors(call_id flat.NodeId, call flat.Node, info CallInfo) {
	instantiation := tc.generic_compile_error_instantiation(call, info) or { return }
	mut messages := []string{}
	tc.collect_instantiated_compile_errors(instantiation.decl_id, instantiation, mut messages)
	for message in messages {
		if !tc.has_type_error(.compile_error, message, call_id) {
			tc.record_error_at(.compile_error, message, call_id, call.pos)
		}
	}
}

fn (mut tc TypeChecker) check_instantiated_generic_compile_warnings(call flat.Node, info CallInfo) {
	instantiation := tc.generic_compile_error_instantiation(call, info) or { return }
	mut warnings := []InstantiatedCompileWarning{}
	tc.collect_instantiated_compile_warnings(instantiation.decl_id, instantiation, mut warnings)
	for warning in warnings {
		if !tc.has_type_notice(.compile_error, warning.message, warning.node) {
			tc.record_warning_at(.compile_error, warning.message, warning.node, warning.pos)
		}
	}
}

fn (mut tc TypeChecker) generic_compile_error_instantiation(call flat.Node, info CallInfo) ?GenericCompileErrorInstantiation {
	if call.children_count == 0 {
		return none
	}
	decl_module := tc.fn_type_modules[info.name] or { tc.cur_module }
	decl := tc.visible_mutation_fn_decl(info.name, decl_module) or { return none }
	decl_id := flat.NodeId(decl.idx)
	fn_node := tc.a.node(decl_id)
	generic_params := tc.fn_generic_params[info.name] or {
		tc.infer_decl_generic_param_names(fn_node)
	}
	if generic_params.len == 0 {
		return none
	}
	mut concrete_args := []string{}
	callee := tc.a.child_node(&call, 0)
	if callee.kind == .index {
		type_args := tc.generic_call_type_arg_names(callee)
		if type_args.len != generic_params.len {
			return none
		}
		for type_arg in type_args {
			concrete_args << tc.explicit_generic_concrete_arg_text(type_arg)
		}
	}
	mut inferred := map[string]string{}
	mut symbol_types := map[string]string{}
	if concrete_args.len == generic_params.len {
		for i, param in generic_params {
			inferred[param] = concrete_args[i]
			symbol_types[param] = concrete_args[i]
		}
	}
	mut arg_index := 1 + info.arg_offset
	mut source_param_index := 0
	for i in 0 .. fn_node.children_count {
		param := tc.a.child_node(fn_node, i)
		if param.kind != .param {
			continue
		}
		if info.has_receiver && source_param_index == 0 {
			source_param_index++
			continue
		}
		if arg_index >= call.children_count {
			break
		}
		arg_id := tc.call_arg_value(tc.a.child(&call, arg_index))
		actual := tc.resolve_type(arg_id)
		tc.infer_generic_type_text_from_type(param.typ, actual, generic_params, mut inferred)
		if param.value.len > 0 {
			symbol_types[param.value] = actual.name()
		}
		arg_index++
		source_param_index++
	}
	if concrete_args.len == 0 {
		for param in generic_params {
			arg := inferred[param] or { return none }
			concrete_args << arg
			symbol_types[param] = arg
		}
	}
	return GenericCompileErrorInstantiation{
		decl_id:        decl_id
		generic_params: generic_params
		concrete_args:  concrete_args
		symbol_types:   symbol_types
	}
}

fn (tc &TypeChecker) instantiated_compile_warning_message(id flat.NodeId, instantiation GenericCompileErrorInstantiation) string {
	node := tc.a.node(id)
	mut message := 'compile-time warning'
	source := tc.source_text_for_node(id)
	mut quote_start := source.index_u8(`'`)
	double_quote_start := source.index_u8(`"`)
	if quote_start < 0 || (double_quote_start >= 0 && double_quote_start < quote_start) {
		quote_start = double_quote_start
	}
	if quote_start >= 0 && quote_start + 1 < source.len {
		quote := source[quote_start]
		quote_end := source[quote_start + 1..].last_index_u8(quote)
		if quote_end >= 0 {
			message = source[quote_start + 1..quote_start + 1 + quote_end]
		}
	} else if node.children_count > 1 {
		arg := tc.a.child_node(node, 1)
		if arg.value.len > 0 {
			message = arg.value
		}
	}
	for i, param in instantiation.generic_params {
		if i >= instantiation.concrete_args.len {
			break
		}
		concrete := instantiation.concrete_args[i]
		message = message.replace(r'${' + param + '.name}', concrete)
		if idx := legacy_comptime_type_index(concrete) {
			message = message.replace(r'${' + param + '.idx}', idx.str())
		}
	}
	return message
}

fn legacy_comptime_type_index(name string) ?int {
	clean := name.trim_space().trim_left('&').trim_left('?').trim_left('!')
	return match clean {
		'void' { 1 }
		'voidptr' { 2 }
		'byteptr' { 3 }
		'charptr' { 4 }
		'i8' { 5 }
		'i16' { 6 }
		'i32' { 7 }
		'int' { 8 }
		'i64' { 9 }
		'isize' { 10 }
		'u8' { 11 }
		'u16' { 12 }
		'u32' { 13 }
		'u64' { 14 }
		'usize' { 15 }
		'f32' { 16 }
		'f64' { 17 }
		'char' { 18 }
		'bool' { 19 }
		'none' { 20 }
		'string' { 21 }
		'rune' { 22 }
		'array' { 23 }
		'map' { 24 }
		'chan' { 25 }
		'any' { 26 }
		'thread' { 29 }
		'error' { 30 }
		'nil' { 31 }
		else { none }
	}
}

fn (mut tc TypeChecker) collect_instantiated_compile_warnings(id flat.NodeId, instantiation GenericCompileErrorInstantiation, mut warnings []InstantiatedCompileWarning) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind == .comptime_if {
		substituted := substitute_comptime_condition_symbols(node.value, instantiation.symbol_types)
		take_then := tc.comptime_type_condition_value(substituted) or { return }
		branch_index := if take_then { 0 } else { 1 }
		if branch_index < node.children_count {
			tc.collect_instantiated_compile_warnings(tc.a.child(node, branch_index), instantiation, mut
				warnings)
		}
		return
	}
	if node.kind == .call && node.children_count > 0 {
		callee := tc.a.child_node(node, 0)
		if callee.kind == .ident && callee.value == '__v_compile_warn' {
			message := tc.instantiated_compile_warning_message(id, instantiation)
			if !warnings.any(it.node == id && it.message == message) {
				warnings << InstantiatedCompileWarning{
					message: message
					node:    id
					pos:     node.pos
				}
			}
			return
		}
	}
	if node.kind in [.fn_literal, .lambda_expr] && id != instantiation.decl_id {
		return
	}
	for i in 0 .. node.children_count {
		tc.collect_instantiated_compile_warnings(tc.a.child(node, i), instantiation, mut warnings)
	}
}

fn (mut tc TypeChecker) collect_instantiated_compile_errors(id flat.NodeId, instantiation GenericCompileErrorInstantiation, mut messages []string) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind == .comptime_if {
		substituted := substitute_comptime_condition_symbols(node.value, instantiation.symbol_types)
		take_then := tc.comptime_type_condition_value(substituted) or { return }
		branch_index := if take_then { 0 } else { 1 }
		if branch_index < node.children_count {
			tc.collect_instantiated_compile_errors(tc.a.child(node, branch_index), instantiation, mut
				messages)
		}
		return
	}
	if node.kind == .call && node.children_count > 0 {
		callee := tc.a.child_node(node, 0)
		if callee.kind == .ident && callee.value == '__v_compile_error' {
			message := if node.children_count > 1 {
				arg := tc.a.child_node(node, 1)
				if arg.value.len > 0 {
					arg.value
				} else {
					'compile-time error'
				}
			} else {
				'compile-time error'
			}
			if message !in messages {
				messages << message
			}
			return
		}
	}
	if node.kind in [.fn_literal, .lambda_expr] && id != instantiation.decl_id {
		return
	}
	for i in 0 .. node.children_count {
		tc.collect_instantiated_compile_errors(tc.a.child(node, i), instantiation, mut messages)
	}
}

fn substitute_comptime_condition_symbols(condition string, symbols map[string]string) string {
	if symbols.len == 0 {
		return condition
	}
	mut out := strings.new_builder(condition.len + 16)
	mut i := 0
	for i < condition.len {
		if condition[i].is_alnum() || condition[i] == `_` {
			mut end := i + 1
			for end < condition.len && (condition[end].is_alnum() || condition[end] == `_`) {
				end++
			}
			token_text := condition[i..end]
			out.write_string(symbols[token_text] or { token_text })
			i = end
			continue
		}
		out.write_u8(condition[i])
		i++
	}
	return out.str()
}

fn (mut tc TypeChecker) check_instantiated_generic_as_casts(call flat.Node, info CallInfo) {
	if call.children_count == 0 {
		return
	}
	callee := tc.a.child_node(&call, 0)
	if callee.kind != .index {
		return
	}
	type_args := tc.generic_call_type_arg_names(callee)
	if type_args.len == 0 {
		return
	}
	decl_module := tc.fn_type_modules[info.name] or { tc.cur_module }
	decl := tc.visible_mutation_fn_decl(info.name, decl_module) or { return }
	fn_node := tc.a.node(flat.NodeId(decl.idx))
	generic_params := tc.fn_generic_params[info.name] or {
		tc.infer_decl_generic_param_names(fn_node)
	}
	if generic_params.len == 0 || generic_params.len != type_args.len {
		return
	}
	mut concrete_args := []string{cap: type_args.len}
	for type_arg in type_args {
		concrete_args << tc.explicit_generic_concrete_arg_text(type_arg)
	}
	mut stack := []flat.NodeId{}
	for i in 0 .. fn_node.children_count {
		stack << tc.a.child(fn_node, i)
	}
	for stack.len > 0 {
		node_id := stack.pop()
		node := tc.a.node(node_id)
		if node.kind == .as_expr && node.children_count > 0 {
			target_text := subst_generic_text(node.value, concrete_args, generic_params)
			if target_text != node.value {
				child_id := tc.a.child(node, 0)
				source := unalias_type(tc.resolve_type(child_id))
				target := unalias_type(tc.parse_type(target_text))
				if source is SumType && target !is Unknown && target.name() != source.name
					&& tc.sum_variant_type_for_pattern(source.name, target.name()) == none {
					message := 'cannot cast `${source.name}` to `${target.name()}`'
					if !tc.has_type_error(.assignment_mismatch, message, node_id) {
						tc.record_error_at(.assignment_mismatch, message, node_id, tc.as_operator_pos(node_id,
							node, child_id))
					}
				}
			}
		}
		if node.kind in [.fn_literal, .lambda_expr] {
			continue
		}
		for i in 0 .. node.children_count {
			stack << tc.a.child(node, i)
		}
	}
}

fn (tc &TypeChecker) unknown_import_function_call_parts(node flat.Node) ?(flat.Node, string, string) {
	if node.kind != .call || node.children_count == 0 {
		return none
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind != .selector || callee.children_count == 0 {
		return none
	}
	base := tc.a.child_node(callee, 0)
	if base.kind != .ident || tc.ident_resolves_to_value(base.value) {
		return none
	}
	module_name := tc.resolve_import_alias(base.value) or { return none }
	full_name := '${module_name}.${callee.value}'
	if full_name in tc.fn_ret_types {
		return none
	}
	return *callee, base.value, module_name
}

fn (mut tc TypeChecker) record_unknown_import_function_call(id flat.NodeId, node flat.Node) bool {
	callee, alias, module_name := tc.unknown_import_function_call_parts(node) or { return false }
	display := '${alias}.${callee.value}'
	mut candidates := []string{}
	prefix := '${module_name}.'
	for name, _ in tc.fn_ret_types {
		if name.starts_with(prefix) && !name[prefix.len..].contains('.') {
			candidates << '${alias}.${name[prefix.len..]}'
		}
	}
	message := util.new_suggestion(display, candidates).say('unknown function: ${display} ')
	tc.record_error_at(.unknown_fn, message, id, tc.method_call_name_pos(node, callee))
	tc.register_synth_type(id, Type(MultiReturn{
		types: []Type{}
	}))
	return true
}

fn (tc &TypeChecker) local_decl_rhs_before(name string, use_id flat.NodeId) ?flat.NodeId {
	fn_id := flat.NodeId(tc.fn_context.node_id)
	if name.len == 0 || !tc.valid_node_id(fn_id) || !tc.valid_node_id(use_id) {
		return none
	}
	use_pos := tc.a.node(use_id).pos
	fn_node := tc.a.node(fn_id)
	mut stack := []flat.NodeId{}
	for i in 0 .. fn_node.children_count {
		child_id := tc.a.child(fn_node, i)
		if tc.a.node(child_id).kind != .param {
			stack << child_id
		}
	}
	mut seen := map[int]bool{}
	mut best_id := flat.empty_node
	mut best_offset := -1
	for stack.len > 0 {
		current_id := stack.pop()
		if seen[int(current_id)] || !tc.valid_node_id(current_id) {
			continue
		}
		seen[int(current_id)] = true
		current := tc.a.node(current_id)
		if current.kind == .decl_assign {
			for i := 0; i + 1 < int(current.children_count); i += 2 {
				lhs := tc.a.child_node(current, i)
				if lhs.kind == .ident && lhs.value == name && lhs.pos.id == use_pos.id
					&& lhs.pos.offset < use_pos.offset && lhs.pos.offset > best_offset {
					best_id = tc.a.child(current, i + 1)
					best_offset = lhs.pos.offset
				}
			}
		}
		if current.kind in [.fn_literal, .lambda_expr] {
			continue
		}
		for i in 0 .. current.children_count {
			stack << tc.a.child(current, i)
		}
	}
	if best_id != flat.empty_node {
		return best_id
	}
	return none
}

fn (tc &TypeChecker) dynamic_comptime_method_var_pos(node flat.Node, name string) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(source.len, node.pos.end)
	if start >= end {
		return node.pos
	}
	needle := '$${name}'
	relative := source[start..end].index(needle) or { return node.pos }
	name_start := start + relative + 1
	return token.new_span(node.pos.id, name_start, name_start + name.len)
}

fn (mut tc TypeChecker) check_dynamic_comptime_method_call(id flat.NodeId, node flat.Node, callee &flat.Node) {
	name := callee.value[1..]
	pos := tc.dynamic_comptime_method_var_pos(node, name)
	rhs_id := tc.local_decl_rhs_before(name, id) or {
		tc.record_error_at(.unknown_fn, 'unknown identifier `${name}`', id, pos)
		return
	}
	var_type := unalias_type(tc.resolve_type(rhs_id))
	if var_type !is String {
		tc.record_error_at(.call_arg_mismatch,
			'invalid string method call: expected `string`, not `${var_type.name()}`', id, pos)
		return
	}
	rhs := tc.a.node(rhs_id)
	if rhs.kind != .string_literal {
		tc.record_error_at(.unknown_fn, 'todo: not a string literal', id, pos)
		tc.record_error_at(.unknown_fn, 'could not find method ``', id, pos)
		return
	}
	method_name := rhs.value
	if callee.children_count == 0 {
		return
	}
	receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(callee, 0)))
	method_key := tc.concrete_method_signature_key(receiver_type.name(), method_name) or {
		tc.record_error_at(.unknown_fn, 'could not find method `${method_name}`', id, pos)
		return
	}
	tc.remember_resolved_call(id, method_key)
	if return_type := tc.fn_ret_types[method_key] {
		tc.remember_expr_type(id, return_type)
	}
	for i in 1 .. node.children_count {
		tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
	}
}

fn (tc &TypeChecker) invalid_unknown_import_function_print_arg(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	return tc.unknown_import_function_call_parts(tc.a.node(id)) != none
}

fn (tc &TypeChecker) unknown_method_call_parts(node flat.Node) ?(flat.Node, Type, string) {
	if node.kind != .call || node.children_count == 0 {
		return none
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind != .selector || callee.children_count == 0 {
		return none
	}
	base := tc.a.child_node(callee, 0)
	if tc.is_namespace_selector(*callee, base) {
		return none
	}
	receiver_type := unwrap_pointer(tc.resolve_type(tc.a.child(callee, 0)))
	if receiver_type !is Struct && receiver_type !is Interface && receiver_type !is Alias
		&& receiver_type !is String && receiver_type !is Primitive {
		return none
	}
	receiver_name := receiver_type.name()
	if tc.struct_field_type(receiver_name, callee.value) != none
		|| tc.concrete_method_signature_key(receiver_name, callee.value) != none {
		return none
	}
	method_candidates := receiver_method_name_candidates(receiver_type, callee.value, tc.cur_module)
	for candidate in method_candidates {
		if candidate in tc.fn_ret_types {
			return none
		}
	}
	if _ := tc.unique_receiver_method_suffix_match(method_candidates) {
		return none
	}
	if receiver_type is Struct {
		if _ := tc.resolve_generic_struct_method(receiver_name, callee.value) {
			return none
		}
	}
	return *callee, receiver_type, receiver_name
}

fn (tc &TypeChecker) unknown_method_receiver_display(receiver_name string) string {
	base, _, is_generic := generic_type_application_parts(receiver_name)
	if !is_generic {
		return receiver_name.all_after_last('.')
	}
	params := tc.struct_generic_params[base] or {
		tc.struct_generic_params[base.all_after_last('.')] or { []string{} }
	}
	if params.len == 0 {
		return receiver_name.all_after_last('.')
	}
	diagnostic_params := if params.len == 1 { ['F'] } else { params }
	return '${base.all_after_last('.')}[${diagnostic_params.join(', ')}]'
}

fn (tc &TypeChecker) method_name_suggestions(receiver_name string) []string {
	base, _, is_generic := generic_type_application_parts(receiver_name)
	mut prefixes := []string{}
	for candidate in [receiver_name, receiver_name.all_after_last('.'), base, base.all_after_last('.')] {
		if candidate.len > 0 && candidate !in prefixes {
			prefixes << candidate
		}
	}
	mut methods := []string{}
	for key, _ in tc.fn_ret_types {
		for prefix in prefixes {
			full_prefix := '${prefix}.'
			if key.starts_with(full_prefix) {
				method := key[full_prefix.len..]
				if !method.contains('.') && method !in methods {
					methods << method
				}
			}
		}
	}
	if is_generic {
		for key, _ in tc.fn_param_types {
			for prefix in prefixes {
				full_prefix := '${prefix}.'
				if key.starts_with(full_prefix) {
					method := key[full_prefix.len..]
					if !method.contains('.') && method !in methods {
						methods << method
					}
				}
			}
		}
	}
	return methods
}

fn (mut tc TypeChecker) record_unknown_method_call(id flat.NodeId, node flat.Node) bool {
	callee, _, receiver_name := tc.unknown_method_call_parts(node) or { return false }
	display := tc.unknown_method_receiver_display(receiver_name)
	receiver_id := tc.a.child(callee, 0)
	if tc.ident_is_multi_pattern_match_subject(receiver_id) {
		tc.record_error_at(.unknown_fn, 'unknown method: `${display}.${callee.value}`', id, tc.method_call_name_pos(node,
			callee))
		tc.register_synth_type(id, Type(void_))
		return true
	}
	base := 'unknown method or field: `${display}.${callee.value}`'
	message :=
		util.new_suggestion(callee.value, tc.method_name_suggestions(receiver_name)).say(base)
	tc.record_error_at(.unknown_fn, message, id, tc.method_call_name_pos(node, callee))
	tc.register_synth_type(id, Type(MultiReturn{
		types: []Type{}
	}))
	return true
}

fn (tc &TypeChecker) invalid_unknown_method_print_arg(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	if _ := tc.resolved_call_name(id) {
		return false
	}
	node := tc.a.node(id)
	return tc.unknown_method_call_parts(node) != none
}

fn (tc &TypeChecker) invalid_pointer_infix_print_arg(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind != .infix || node.op != .plus || node.children_count < 2 {
		return false
	}
	lhs := tc.resolve_type(tc.a.child(node, 0))
	rhs := tc.resolve_type(tc.a.child(node, 1))
	lhs_pointer := unalias_type(lhs) is Pointer && lhs.name() != 'voidptr'
	rhs_pointer := unalias_type(rhs) is Pointer && rhs.name() != 'voidptr'
	return (lhs_pointer && !rhs_pointer && !rhs.is_integer())
		|| (rhs_pointer && !lhs_pointer && !lhs.is_integer())
}

fn (tc &TypeChecker) explicit_generic_local_fn_value(node flat.Node) ?FnType {
	if node.children_count == 0 {
		return none
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind != .index || callee.children_count < 2 {
		return none
	}
	base := tc.a.child_node(callee, 0)
	if base.kind != .ident {
		return none
	}
	typ := tc.cur_scope.lookup(base.value) or { return none }
	return fn_type_from_type(typ)
}

fn (tc &TypeChecker) call_has_wrapped_receiver(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	call := tc.a.node(id)
	if call.kind != .call || call.children_count == 0 {
		return false
	}
	callee := tc.a.child_node(call, 0)
	if callee.kind != .selector || callee.children_count == 0 {
		return false
	}
	receiver_type := unalias_type(tc.resolve_type(tc.a.child(callee, 0)))
	return receiver_type is OptionType || receiver_type is ResultType
}

fn (tc &TypeChecker) wrapped_receiver_payload_diagnostic_name(payload Type) string {
	name := unwrap_all_pointers(payload).name()
	if name.contains('.') {
		alias := name.all_before('.')
		if import_path := tc.current_file_import_path_for_alias(alias) {
			return import_path + name[alias.len..]
		}
	}
	if qualified := tc.unique_qualified_type_name(name.all_after_last('.')) {
		return qualified
	}
	if resolved := tc.resolve_import_alias_pattern(name) {
		return resolved
	}
	return name
}

fn (tc &TypeChecker) current_file_import_path_for_alias(alias string) ?string {
	mut file := ''
	for index in tc.top_level_idx {
		node := tc.a.nodes[index]
		if node.kind == .file {
			file = node.value
			continue
		}
		if file != tc.cur_file || node.kind != .import_decl || node.typ != alias {
			continue
		}
		return tc.import_module_path_text(node)
	}
	return none
}

fn (tc &TypeChecker) wrapped_receiver_has_method(payload Type, method string) bool {
	clean := unwrap_all_pointers(payload)
	if clean !is Struct {
		return false
	}
	for candidate in receiver_method_name_candidates(clean, method, tc.cur_module) {
		if candidate in tc.fn_ret_types {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) check_call_deprecation(id flat.NodeId, node flat.Node, info CallInfo) {
	deprecation := tc.deprecated_symbols[info.name] or {
		tc.deprecated_symbols[info.name.all_after_last('.')] or { return }
	}
	is_method := deprecation.name.contains('.')
	kind := if is_method { 'method' } else { 'function' }
	pos := tc.deprecated_call_diagnostic_pos(node, is_method)
	tc.record_deprecation(id, kind, deprecation, pos)
}

fn (mut tc TypeChecker) record_deprecation(id flat.NodeId, kind string, deprecation DeprecationInfo, pos token.Pos) {
	custom := if deprecation.message.len > 0 { '; ${deprecation.message}' } else { '' }
	if deprecation.after.len == 0 {
		tc.record_warning_at(.unknown_fn,
			'${kind} `${deprecation.name}` has been deprecated${custom}', id, pos)
		return
	}
	today := time.now().strftime('%Y-%m-%d')
	if deprecation.after <= today {
		tc.record_error_at(.unknown_fn,
			'${kind} `${deprecation.name}` has been deprecated since ${deprecation.after}${custom}',
			id, pos)
		return
	}
	error_after := time.parse_iso8601(deprecation.after) or { return }
	tc.record_notice_at(.unknown_fn,
		'${kind} `${deprecation.name}` will be deprecated after ${deprecation.after}, and will become an error after ${error_after.add_days(180).strftime('%Y-%m-%d')}${custom}',
		id, pos)
}

fn (tc &TypeChecker) deprecated_call_diagnostic_pos(node flat.Node, is_method bool) token.Pos {
	if !is_method || node.children_count == 0 {
		return node.pos
	}
	selector := tc.a.child_node(&node, 0)
	if selector.kind != .selector {
		return node.pos
	}
	return tc.method_call_name_pos(node, selector)
}

fn (tc &TypeChecker) builtin_addr_call_arg(node flat.Node) ?flat.NodeId {
	if node.kind != .call || node.children_count != 2 {
		return none
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind == .ident && callee.value == '__addr' {
		return tc.call_arg_value(tc.a.child(&node, 1))
	}
	return none
}

fn (tc &TypeChecker) builtin_isreftype_call_arg(node flat.Node) ?flat.NodeId {
	if node.kind != .call || node.children_count != 2 {
		return none
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind == .ident && callee.value == '__v3_isreftype' {
		return tc.call_arg_value(tc.a.child(&node, 1))
	}
	return none
}

fn (mut tc TypeChecker) check_isreftype_arg(arg_id flat.NodeId) {
	if !tc.valid_node_id(arg_id) {
		return
	}
	arg := tc.a.nodes[int(arg_id)]
	if arg.kind == .sizeof_expr {
		tc.check_isreftype_type_arg(arg.value, arg_id)
		return
	}
	if arg.kind == .ident && (is_builtin_type_name(arg.value) || (arg.value.len > 0
		&& arg.value[0] >= `A` && arg.value[0] <= `Z`)) {
		tc.check_isreftype_type_arg(arg.value, arg_id)
		return
	}
	tc.check_node(arg_id)
}

fn (mut tc TypeChecker) check_isreftype_type_arg(typ string, arg_id flat.NodeId) {
	tc.check_type_string_for_unsupported_generics(typ, arg_id,
		generic_param_map_from_names(tc.fn_context.generic_params))
}

// cur_fn_is_generic_template reports whether the function currently being
// checked is a template that will be re-validated per instantiation: it
// declares generic parameters, or is a method on a generic receiver
// (`fn (mut so SetOf[T]) sort()`), whose own node has no generic_params.
fn (tc &TypeChecker) cur_fn_is_generic_template() bool {
	if tc.fn_context.node_id < 0 || tc.fn_context.node_id >= tc.a.nodes.len {
		return false
	}
	fn_node := tc.a.nodes[tc.fn_context.node_id]
	if fn_node.generic_params().len > 0 {
		return true
	}
	for i in 0 .. fn_node.children_count {
		child := tc.a.child_node(&fn_node, i)
		if child.kind == .param && child.typ.len > 0
			&& tc.type_text_has_generic_placeholder(child.typ) {
			return true
		}
	}
	return false
}

// call_receiver_type_is_unknown reports whether a method call's receiver has
// an unresolvable type, so the unknown-function diagnostic must not fire for
// it. Besides generic templates (whose bodies the reference compiler also
// only validates per instantiation), the checker currently fails to resolve
// several legitimate receiver shapes — fields of generic struct instances
// (`json.decode[S[T]](s)!.val.unix()`), option/or-unwrapped results, and
// specialized generic call returns — so narrowing this to "provably generic"
// chains produces false errors on valid vlib code. The receiver expression
// itself IS checked, so `missing.method()` still reports its unknown
// identifier. Remaining gap: a template instantiated with a type lacking the
// method fails only in C compilation — v3 has no instantiation-time recheck
// of cloned template bodies yet.
fn (mut tc TypeChecker) call_receiver_type_is_unknown(node flat.Node) bool {
	if node.children_count == 0 {
		return false
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind != .selector || callee.children_count == 0 {
		return false
	}
	base_id := tc.a.child(callee, 0)
	base_type := tc.resolve_type(base_id)
	if tc.cur_fn_is_generic_template() && tc.call_receiver_is_open_generic(base_id, base_type) {
		tc.check_node(base_id)
		return true
	}
	if unwrap_pointer(base_type) !is Unknown {
		return false
	}
	tc.check_node(base_id)
	return true
}

fn (tc &TypeChecker) call_receiver_is_open_generic(base_id flat.NodeId, base_type Type) bool {
	if tc.type_contains_open_generic_placeholder(base_type) {
		return true
	}
	clean := unwrap_pointer(base_type)
	if clean is Struct {
		if tc.type_text_has_generic_placeholder(clean.name) {
			return true
		}
		for candidate in tc.generic_struct_method_base_candidates(clean.name) {
			if candidate in tc.struct_generic_params {
				return true
			}
		}
	}
	if int(base_id) >= 0 && int(base_id) < tc.a.nodes.len {
		node := tc.a.nodes[int(base_id)]
		if node.typ.len > 0 && tc.type_text_has_generic_placeholder(node.typ) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) type_contains_open_generic_placeholder(typ Type) bool {
	if tc.type_text_has_generic_placeholder(typ.name()) {
		return true
	}
	if typ is Pointer {
		return tc.type_contains_open_generic_placeholder(typ.base_type)
	}
	if typ is Alias {
		return tc.type_contains_open_generic_placeholder(typ.base_type)
	}
	if typ is Array {
		return tc.type_contains_open_generic_placeholder(typ.elem_type)
	}
	if typ is ArrayFixed {
		return tc.type_contains_open_generic_placeholder(typ.elem_type)
	}
	if typ is Map {
		return tc.type_contains_open_generic_placeholder(typ.key_type)
			|| tc.type_contains_open_generic_placeholder(typ.value_type)
	}
	if typ is OptionType {
		return tc.type_contains_open_generic_placeholder(typ.base_type)
	}
	if typ is ResultType {
		return tc.type_contains_open_generic_placeholder(typ.base_type)
	}
	return false
}

fn (tc &TypeChecker) explicit_generic_args_diagnostic_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	if node.pos.offset < 0 || node.pos.offset >= source.len {
		return node.pos
	}
	line_end := source.index_after('\n', node.pos.offset) or { source.len }
	open_relative := source[node.pos.offset..line_end].index_u8(`[`)
	if open_relative < 0 {
		return node.pos
	}
	open := node.pos.offset + open_relative
	close_relative := source[open..line_end].index_u8(`]`)
	if close_relative < 0 {
		return node.pos
	}
	return token.new_span(node.pos.id, open, open + close_relative + 1)
}

// call_generic_args_have_placeholders reports whether the call carries explicit
// generic type args that are still uninstantiated placeholders (`p.read_element[T]()`
// inside a generic template). Such calls can only be validated after
// monomorphization, so unknown-function diagnostics must not fire for them.
// Outside a generic template a bare `missing[T]()` is real invalid code, so
// the deferral only applies within one. This deliberately includes callees
// with no known declaration: the reference compiler also accepts a template
// whose body calls a missing function as long as it is never instantiated
// (vlib code relies on this, e.g. asn1's commented-out `read_element`), and
// only reports it at instantiation time.
fn (tc &TypeChecker) call_generic_args_have_placeholders(node flat.Node) bool {
	if !tc.cur_fn_is_generic_template() {
		return false
	}
	// An explicit generic METHOD call whose type args still carry the
	// template's own placeholders (`p.read_element[T]()`) cannot be resolved
	// before instantiation - defer even when the target is not a known
	// declaration, matching v1, where an uninstantiated generic body is never
	// checked. The monomorph validator reports it if the template ever gets
	// specialized. A plain `missing[T]()` call still errors right away.
	if node.children_count > 0 {
		callee := tc.a.child_node(&node, 0)
		if callee.kind == .index && callee.children_count >= 2 && callee.value != 'range'
			&& tc.a.child_node(callee, 0).kind == .selector {
			for i in 1 .. int(callee.children_count) {
				arg := tc.a.child_node(callee, i)
				if arg.kind == .ident && arg.value.len > 0
					&& tc.type_text_has_generic_placeholder(arg.value) {
					return true
				}
			}
		}
	}
	if !tc.explicit_generic_call_target_is_known(node) {
		return false
	}
	if node.value.len > 0 {
		for arg in node.value.split(',') {
			if tc.type_text_has_generic_placeholder(trimmed_space(arg)) {
				return true
			}
		}
	}
	if node.children_count == 0 {
		return false
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind != .index || callee.children_count < 2 || callee.value == 'range' {
		return false
	}
	for i in 1 .. int(callee.children_count) {
		arg := tc.a.child_node(callee, i)
		if arg.kind == .ident && arg.value.len > 0
			&& tc.type_text_has_generic_placeholder(arg.value) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) explicit_generic_call_target_is_known(node flat.Node) bool {
	if node.children_count == 0 {
		return false
	}
	if _ := tc.sum_constructor_call_name(node) {
		return true
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind != .index || callee.children_count == 0 || callee.value == 'range' {
		return tc.is_known_call(node)
	}
	base := tc.a.child_node(callee, 0)
	if _ := tc.generic_call_base_name(base) {
		return true
	}
	if base.kind != .selector || base.value.len == 0 {
		return false
	}
	if base.children_count > 0 {
		receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(base, 0)))
		if receiver_type is Struct {
			if _ := tc.resolve_generic_struct_method(receiver_type.name, base.value) {
				return true
			}
		}
	}
	// A method on an unresolved generic receiver cannot be tied to a concrete
	// receiver yet, but it still has to name a real method declaration. The
	// concrete specialization is validated after monomorphization.
	for name, _ in tc.fn_generic_params {
		if name.ends_with('.${base.value}') {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) check_sum_constructor_call(id flat.NodeId, node flat.Node, sum_name string) {
	expected := Type(SumType{
		name: sum_name
	})
	tc.remember_expr_type(id, expected)
	actual_count := node.children_count - 1
	if actual_count != 1 {
		if tc.should_diagnose(id) {
			tc.record_error(.call_arg_mismatch,
				'argument count mismatch for `${tc.call_display_name(node)}`: expected 1, got ${actual_count}',
				id)
		}
		for i in 1 .. node.children_count {
			tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
		}
		return
	}
	arg_id := tc.call_arg_value(tc.a.child(&node, 1))
	tc.check_node(arg_id)
	arg_type := tc.resolve_expr(arg_id, expected)
	if !tc.type_compatible(arg_type, expected)
		&& !tc.single_value_wrapper_compatible_with_sum(arg_type, expected) {
		tc.type_mismatch(.call_arg_mismatch,
			'cannot use `${arg_type.name()}` as sum constructor payload; expected variant of `${sum_name}`',
			id)
	}
}

fn (tc &TypeChecker) single_value_wrapper_compatible_with_sum(actual Type, expected Type) bool {
	if expected !is SumType {
		return false
	}
	actual_name := actual.name()
	if actual_name.len == 0 {
		return false
	}
	fields := tc.struct_fields_for_init(actual_name)
	if fields.len != 1 || fields[0].name != 'value' {
		return false
	}
	return tc.type_compatible(fields[0].typ, expected)
}

fn (tc &TypeChecker) sum_constructor_call_name(node flat.Node) ?string {
	if node.children_count == 0 {
		return none
	}
	callee_id := tc.a.child(&node, 0)
	callee := tc.a.nodes[int(callee_id)]
	match callee.kind {
		.ident {
			if resolved := tc.resolve_selective_import_type_symbol(callee.value) {
				if sum_name := tc.known_sum_constructor_name(resolved) {
					return sum_name
				}
			}
			return tc.known_sum_constructor_name(callee.value)
		}
		.selector {
			base := tc.a.child_node(callee, 0)
			if base.kind == .ident {
				mod_name := tc.resolve_import_alias(base.value) or { base.value }
				return tc.known_sum_constructor_name('${mod_name}.${callee.value}')
			}
		}
		.index, .prefix, .array_init {
			type_name := tc.type_expr_name(callee_id)
			if type_name.len > 0 {
				return tc.known_sum_constructor_name(type_name)
			}
		}
		else {}
	}

	return none
}

fn (tc &TypeChecker) type_expr_name(id flat.NodeId) string {
	if int(id) < 0 {
		return ''
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			if resolved := tc.resolve_selective_import_type_symbol(node.value) {
				return resolved
			}
			return node.value
		}
		.selector {
			if node.children_count == 0 {
				return node.value
			}
			base_id := tc.a.child(&node, 0)
			base_node := tc.a.nodes[int(base_id)]
			base := if base_node.kind == .ident {
				tc.resolve_import_alias(base_node.value) or { tc.type_expr_name(base_id) }
			} else {
				tc.type_expr_name(base_id)
			}
			if base.len == 0 {
				return node.value
			}
			return '${base}.${node.value}'
		}
		.index {
			if node.children_count < 2 || node.value == 'range' {
				return ''
			}
			base := tc.type_expr_name(tc.a.child(&node, 0))
			if base.len == 0 {
				return ''
			}
			mut args := []string{}
			for i in 1 .. node.children_count {
				arg := tc.type_expr_name(tc.a.child(&node, i))
				if arg.len == 0 {
					return ''
				}
				args << arg
			}
			return '${base}[${args.join(', ')}]'
		}
		.array_init {
			if node.value.len == 0 {
				return ''
			}
			return '[]${node.value}'
		}
		.prefix {
			if node.children_count == 0 {
				return ''
			}
			child := tc.type_expr_name(tc.a.child(&node, 0))
			if child.len == 0 {
				return ''
			}
			if node.op == .amp {
				return '&${child}'
			}
			return child
		}
		else {
			return ''
		}
	}
}

fn (tc &TypeChecker) known_sum_constructor_name(name string) ?string {
	if name in tc.sum_types {
		return name
	}
	base_name := strip_generic_args_name(name)
	if base_name in tc.sum_types {
		return name
	}
	qname := tc.qualify_name(name)
	if qname in tc.sum_types {
		return qname
	}
	qbase := strip_generic_args_name(qname)
	if qbase in tc.sum_types {
		return qname
	}
	return none
}

// should_diagnose reports whether should diagnose applies in types.
fn (tc &TypeChecker) should_diagnose(id flat.NodeId) bool {
	if int(id) < 0 || int(id) < tc.a.user_code_start {
		return false
	}
	if int(id) < tc.a.nodes.len && !tc.a.nodes[int(id)].pos.is_valid() && !tc.diagnose_unknown_calls {
		return false
	}
	if int(id) < tc.a.nodes.len && tc.a.nodes[int(id)].kind != .import_decl
		&& tc.node_is_on_multiple_module_import_line(id) {
		return false
	}
	if tc.fn_context.node_id >= 0 && tc.fn_context.node_id < tc.a.specialized_fn_nodes.len
		&& tc.a.specialized_fn_nodes[tc.fn_context.node_id] {
		if tc.checker_fixture_mode && tc.diagnostic_files.len > 0 {
			return tc.cur_file in tc.diagnostic_files
		}
		return true
	}
	if tc.current_fn_is_concrete_generic_receiver_specialization() {
		if tc.checker_fixture_mode && tc.diagnostic_files.len > 0 {
			return tc.cur_file in tc.diagnostic_files
		}
		return true
	}
	if tc.diagnostic_files.len == 0 {
		return true
	}
	return tc.cur_file in tc.diagnostic_files
}

fn (tc &TypeChecker) current_fn_is_concrete_generic_receiver_specialization() bool {
	if tc.fn_context.node_id < 0 || tc.fn_context.node_id >= tc.a.nodes.len
		|| tc.fn_context.generic_params.len > 0 {
		return false
	}
	node := tc.a.nodes[tc.fn_context.node_id]
	if node.kind != .fn_decl || !node.value.contains('.') {
		return false
	}
	receiver := node.value.all_before_last('.')
	return receiver.contains('[') && receiver.ends_with(']')
}

fn multiple_module_import_line_key(file_id int, line int) u64 {
	return (u64(u32(file_id)) << 32) | u64(u32(line))
}

fn source_line_has_multiple_module_imports(raw_line string) bool {
	line := raw_line.trim_left(' \t')
	if !line.starts_with('import ') {
		return false
	}
	mut cursor := 'import '.len
	for cursor < line.len && (is_import_ident_byte(line[cursor]) || line[cursor] == `.`) {
		cursor++
	}
	for cursor < line.len && line[cursor] in [` `, `\t`, `\r`] {
		cursor++
	}
	if cursor >= line.len || line[cursor] == `{` || line[cursor..].starts_with('as ') {
		return false
	}
	return line[cursor] == `,` || is_import_ident_byte(line[cursor])
}

fn (mut tc TypeChecker) index_multiple_module_import_lines(a &flat.FlatAst) {
	tc.multiple_module_import_lines = map[u64]bool{}
	tc.source_texts_by_file = map[string]string{}
	for file_id, file in a.source_files {
		source := os.read_file(file.name) or { continue }
		tc.source_texts_by_file[file.name] = source
		mut line_number := 1
		mut line_start := 0
		for line_start <= source.len {
			line_end := source.index_after('\n', line_start) or { source.len }
			if source_line_has_multiple_module_imports(source[line_start..line_end]) {
				tc.multiple_module_import_lines[multiple_module_import_line_key(file_id,
					line_number)] = true
			}
			if line_end >= source.len {
				break
			}
			line_start = line_end + 1
			line_number++
		}
	}
}

fn (tc &TypeChecker) node_is_on_multiple_module_import_line(id flat.NodeId) bool {
	pos := tc.a.node(id).pos
	file := tc.a.source_files[pos.id] or { return false }
	if pos.offset < 0 || pos.offset > file.size {
		return false
	}
	line := file.position(pos).line
	return multiple_module_import_line_key(pos.id, line) in tc.multiple_module_import_lines
}

fn (tc &TypeChecker) should_diagnose_unsupported_generic(id flat.NodeId) bool {
	if tc.should_diagnose(id) {
		return true
	}
	if int(id) < 0 || int(id) < tc.a.user_code_start {
		return false
	}
	if tc.diagnostic_files.len == 0 {
		return false
	}
	return tc.diagnostic_files['generic:' + tc.cur_file]
}

// should_diagnose_unknown_call reports whether should diagnose unknown call applies in types.
fn (tc &TypeChecker) should_diagnose_unknown_call(id flat.NodeId) bool {
	return tc.diagnose_unknown_calls && tc.should_diagnose(id)
}

fn (tc &TypeChecker) ident_resolves_to_value(name string) bool {
	if _ := tc.cur_scope.lookup(name) {
		return true
	}
	return false
}

fn (tc &TypeChecker) sum_fn_variant_for_arg_count(typ Type, arg_count int) ?FnType {
	clean := unalias_and_unwrap_pointer_type(typ)
	if clean !is SumType {
		return none
	}
	clean_name := Type(clean).name()
	base := tc.sum_base_name(clean_name)
	variants := tc.sum_types[base] or { return none }
	for variant in variants {
		concrete := tc.concrete_sum_variant_name(clean_name, variant)
		variant_type := tc.parse_type(concrete)
		if fn_type := fn_type_from_type(variant_type) {
			if fn_type.params.len == arg_count {
				return fn_type
			}
		}
	}
	return none
}

// resolve_call_info resolves resolve call info information for types.
fn (mut tc TypeChecker) resolve_call_info(id flat.NodeId, node flat.Node) ?CallInfo {
	if node.children_count == 0 {
		return none
	}
	fn_node := tc.a.child_node(&node, 0)
	if info := tc.resolve_generic_call_info(id, fn_node) {
		return info
	}
	if fn_node.kind == .index && fn_node.children_count > 0 {
		callee_id := tc.a.child(&node, 0)
		fn_type := tc.resolve_type(callee_id)
		if fn_typ := fn_type_from_type(fn_type) {
			return CallInfo{
				name:         ''
				params:       fn_typ.params.clone()
				return_type:  fn_typ.return_type
				is_variadic:  tc.expr_is_variadic_fn_value(callee_id)
				params_known: true
			}
		}
		if unresolved_generic_receiver_type(fn_type) {
			return CallInfo{
				name:         ''
				params:       []Type{}
				return_type:  Type(Unknown{
					reason: 'generic callable'
				})
				params_known: false
			}
		}
	}
	if fn_node.kind == .ident {
		fn_id := tc.a.child(&node, 0)
		mut binding_type := Type(void_)
		if typ := tc.cur_scope.lookup(fn_node.value) {
			binding_type = typ
		} else if typ := tc.file_scope.lookup(fn_node.value) {
			binding_type = typ
		} else if typ := tc.const_type_for_name(fn_node.value) {
			binding_type = typ
		}
		mut fn_type := Type(void_)
		mut is_smartcasted := false
		if smart_type := tc.smartcast_type(fn_id) {
			fn_type = smart_type
			is_smartcasted = true
		} else {
			fn_type = binding_type
		}
		if fn_typ := fn_type_from_type(fn_type) {
			actual_count := node.children_count - 1
			selected := if !is_smartcasted && fn_typ.params.len != actual_count {
				tc.sum_fn_variant_for_arg_count(binding_type, actual_count) or { fn_typ }
			} else {
				fn_typ
			}
			return CallInfo{
				name:         ''
				params:       selected.params.clone()
				return_type:  selected.return_type
				is_variadic:  tc.expr_is_variadic_fn_value(fn_id)
				params_known: true
			}
		}
		if fn_type is Unknown || unresolved_generic_receiver_type(fn_type) {
			return CallInfo{
				name:         ''
				params:       []Type{}
				return_type:  Type(Unknown{
					reason: 'generic callable'
				})
				params_known: false
			}
		}
	}
	if fn_node.kind !in [.ident, .selector] {
		fn_type := tc.resolve_type(tc.a.child(&node, 0))
		if fn_typ := fn_type_from_type(fn_type) {
			return CallInfo{
				name:         ''
				params:       fn_typ.params.clone()
				return_type:  fn_typ.return_type
				params_known: true
			}
		}
	}
	if fn_node.kind == .selector {
		base_id := tc.a.child(fn_node, 0)
		base_node := tc.a.nodes[int(base_id)]
		base_is_imported_module := base_node.kind == .ident
			&& !tc.ident_resolves_to_value(base_node.value)
			&& tc.resolve_import_alias(base_node.value) != none
		// A selector on an imported module is a direct module function before it is
		// considered as a function-valued field/constant. Keeping the qualified
		// CallInfo is also required by compiler-magic calls such as json.decode,
		// whose result type is inferred from the leading type argument.
		if base_is_imported_module {
			if resolved_mod := tc.resolve_import_alias(base_node.value) {
				mod_name := '${resolved_mod}.${fn_node.value}'
				if mod_name in tc.fn_ret_types {
					if info := tc.decode_call_info_from_type_arg(node, mod_name, false) {
						return info
					}
					return tc.call_info(mod_name, false)
				}
			}
		}
		if base_node.kind == .call {
			tc.check_node(base_id)
		}
		callee_id := tc.a.child(&node, 0)
		if fn_typ := tc.selector_fn_type(fn_node) {
			return CallInfo{
				name:         ''
				params:       fn_typ.params.clone()
				return_type:  fn_typ.return_type
				is_variadic:  tc.expr_is_variadic_fn_value(callee_id)
				params_known: true
			}
		}
		mut use_resolved_fn_value_call := base_is_imported_module
		if _ := tc.selector_wrapped_fn_type(fn_node) {
			use_resolved_fn_value_call = true
		}
		if use_resolved_fn_value_call {
			mut callee_type := tc.resolve_type(callee_id)
			if smart_type := tc.smartcast_type(callee_id) {
				callee_type = smart_type
			}
			if fn_typ := fn_type_from_type(callee_type) {
				return CallInfo{
					name:         ''
					params:       fn_typ.params.clone()
					return_type:  fn_typ.return_type
					is_variadic:  tc.expr_is_variadic_fn_value(callee_id)
					params_known: true
				}
			}
		}
		if base_node.kind == .ident && base_node.value == 'C' {
			c_name := 'C.${fn_node.value}'
			if c_name in tc.fn_ret_types {
				return tc.call_info(c_name, false)
			}
			return none
		}
		if base_node.kind == .ident {
			base_is_value := tc.ident_resolves_to_value(base_node.value)
			if !base_is_value {
				if resolved_mod := tc.resolve_import_alias(base_node.value) {
					mod_name := '${resolved_mod}.${fn_node.value}'
					if mod_name in tc.fn_ret_types {
						if info := tc.decode_call_info_from_type_arg(node, mod_name, false) {
							return info
						}
						return tc.call_info(mod_name, false)
					}
				}
				if base_node.value == tc.cur_module {
					mod_name := '${tc.cur_module}.${fn_node.value}'
					if mod_name in tc.fn_ret_types {
						if info := tc.decode_call_info_from_type_arg(node, mod_name, false) {
							return info
						}
						return tc.call_info(mod_name, false)
					}
				}
				if static_name := tc.static_assoc_fn_key_for_base(base_node.value, fn_node.value) {
					return tc.call_info(static_name, false)
				}
				qbase := tc.qualify_name(base_node.value)
				if fn_node.value == 'from_string' {
					if enum_name := tc.resolve_enum_name(base_node.value) {
						return CallInfo{
							name:         ''
							params:       tarr1(Type(string_))
							return_type:  Type(OptionType{
								base_type: Type(Enum{
									name:    enum_name
									is_flag: enum_name in tc.flag_enums
								})
							})
							params_known: true
						}
					}
				}
				if fn_node.value == 'zero' && qbase in tc.flag_enums {
					return CallInfo{
						name:         ''
						params:       []Type{}
						return_type:  Type(Enum{
							name:    qbase
							is_flag: true
						})
						params_known: true
					}
				}
				if fn_node.value == 'from' && base_node.value in tc.fn_context.generic_params {
					return CallInfo{
						name:         ''
						params:       tarr1(Type(Unknown{
							reason: 'enum from input'
						}))
						return_type:  tc.parse_type('?${base_node.value}')
						params_known: true
					}
				}
				if fn_node.value == 'from' && qbase in tc.enum_names {
					return tc.enum_from_call_info(qbase)
				}
				if fn_node.value == 'from' {
					enum_name := tc.resolve_enum_name(base_node.value) or { '' }
					if enum_name.len > 0 {
						return tc.enum_from_call_info(enum_name)
					}
				}
			}
		} else if base_node.kind == .selector {
			if method_name := tc.module_const_receiver_method_name(base_node, fn_node.value) {
				// Raw collection declarations erase their element types. Let the
				// collection-specific path below specialize their receiver and result
				// from the imported constant's concrete type.
				if !checker_is_raw_collection_method_name(method_name, 'array.')
					&& !checker_is_raw_collection_method_name(method_name, 'map.') {
					return tc.call_info(method_name, true)
				}
			}
			inner := tc.a.child_node(base_node, 0)
			if inner.kind == .ident {
				mod_name := tc.resolve_import_alias(inner.value) or { inner.value }
				full_name := '${mod_name}.${base_node.value}.${fn_node.value}'
				if full_name in tc.fn_ret_types {
					return tc.call_info(full_name, false)
				}
				if static_name := tc.static_assoc_fn_key_for_base('${mod_name}.${base_node.value}',
					fn_node.value)
				{
					return tc.call_info(static_name, false)
				}
				if fn_node.value == 'from_string' {
					if enum_name := tc.resolve_enum_name('${mod_name}.${base_node.value}') {
						return CallInfo{
							name:         ''
							params:       tarr1(Type(string_))
							return_type:  Type(OptionType{
								base_type: Type(Enum{
									name:    enum_name
									is_flag: enum_name in tc.flag_enums
								})
							})
							params_known: true
						}
					}
				}
				if fn_node.value == 'from' {
					if enum_name := tc.resolve_enum_name('${mod_name}.${base_node.value}') {
						return tc.enum_from_call_info(enum_name)
					}
				}
			}
		}
		if fn_typ := tc.selector_const_fn_type(fn_node) {
			return CallInfo{
				name:         ''
				params:       fn_typ.params.clone()
				return_type:  fn_typ.return_type
				params_known: true
			}
		}
		base_type := tc.selector_fn_base_type(base_id) or { tc.resolve_type(base_id) }
		if base_node.kind == .ident && tc.binding_is_strings_builder(base_node.value) {
			for method_name in ['strings.Builder.${fn_node.value}', 'Builder.${fn_node.value}'] {
				if method_name in tc.fn_ret_types {
					return tc.call_info(method_name, true)
				}
			}
		}
		if fn_typ := tc.selector_field_fn_type(fn_node, base_type) {
			return CallInfo{
				name:         ''
				params:       fn_typ.params.clone()
				return_type:  fn_typ.return_type
				params_known: true
			}
		}
		clean := unwrap_all_pointers(base_type)
		if fn_node.value in ['type_name', 'type_idx'] && tc.receiver_is_sum_type(clean) {
			return CallInfo{
				name:         ''
				params:       tarr1(base_type)
				return_type:  if fn_node.value == 'type_name' { Type(string_) } else { Type(int_) }
				has_receiver: true
				params_known: true
			}
		}
		if clean is Interface && fn_node.value in ['type_name', 'type_idx'] {
			return CallInfo{
				name:         '${clean.name}.${fn_node.value}'
				params:       tarr1(base_type)
				return_type:  if fn_node.value == 'type_name' { Type(string_) } else { Type(int_) }
				has_receiver: true
				params_known: true
			}
		}
		if fn_node.value == 'clone' && unresolved_generic_receiver_type(clean) {
			return CallInfo{
				name:         ''
				params:       tarr1(base_type)
				return_type:  base_type
				has_receiver: true
				params_known: true
			}
		}
		if fn_node.value == 'wait' {
			if ret_type := tc.thread_wait_return_type(base_type) {
				return CallInfo{
					name:         ''
					params:       tarr1(base_type)
					return_type:  ret_type
					has_receiver: true
					params_known: true
				}
			}
		}
		if info := tc.pointer_builtin_method_call_info(base_type, fn_node.value) {
			return info
		}
		if clean is Channel {
			match fn_node.value {
				'close' {
					return CallInfo{
						name:         'chan.close'
						params:       tarr2(base_type, tc.parse_type('IError'))
						return_type:  Type(void_)
						has_receiver: true
						is_variadic:  true
						params_known: true
					}
				}
				'try_push' {
					return CallInfo{
						name:         '${base_type.name()}.try_push'
						params:       tarr2(base_type, Type(Pointer{
							base_type: clean.elem_type
						}))
						return_type:  tc.parse_type('ChanState')
						has_receiver: true
						params_known: true
					}
				}
				'try_pop' {
					return CallInfo{
						name:         '${base_type.name()}.try_pop'
						params:       tarr2(base_type, clean.elem_type)
						return_type:  tc.parse_type('ChanState')
						has_receiver: true
						params_known: true
					}
				}
				else {}
			}
		}
		if clean is String && fn_node.value == 'hex' && tc.is_builtin_hex_receiver(base_type) {
			return CallInfo{
				name:         'string.hex'
				params:       tarr1(base_type)
				return_type:  Type(string_)
				has_receiver: true
				params_known: true
			}
		}
		if info := tc.builtin_receiver_method_call_info(base_type, fn_node.value) {
			return info
		}
		if info := tc.current_receiver_param_method_call_info(base_id, fn_node.value) {
			return info
		}
		if clean is Alias {
			// Methods declared on an alias take precedence over methods inherited
			// from its underlying collection. In particular, a fixed-array alias
			// can provide a clone() that preserves the alias type instead of using
			// the builtin fixed-array clone, which returns a dynamic array.
			for mname in receiver_method_name_candidates(clean, fn_node.value, tc.cur_module) {
				if checker_is_raw_collection_method_name(mname, 'array.')
					|| checker_is_raw_collection_method_name(mname, 'map.')
					|| mname !in tc.fn_ret_types {
					continue
				}
				if !tc.method_can_be_called_on_receiver(base_type, fn_node.value, mname) {
					continue
				}
				return tc.call_info(mname, true)
			}
			alias_target_name := resolve_type_name_for_method(clean.base_type)
			if alias_target_name.len > 0 {
				if info := tc.resolve_generic_struct_method(alias_target_name, fn_node.value) {
					return info
				}
				for mname in receiver_method_name_candidates(clean.base_type, fn_node.value,
					tc.cur_module) {
					if checker_is_raw_collection_method_name(mname, 'array.')
						|| checker_is_raw_collection_method_name(mname, 'map.')
						|| mname !in tc.fn_ret_types {
						continue
					}
					if !tc.method_can_be_called_on_receiver(base_type, fn_node.value, mname) {
						continue
					}
					return tc.call_info(mname, true)
				}
			}
			if _ := array_type_from_receiver(clean) {
				for mname in receiver_method_name_candidates(clean, fn_node.value, tc.cur_module) {
					if checker_is_raw_collection_method_name(mname, 'array.')
						|| mname !in tc.fn_ret_types {
						continue
					}
					if !tc.method_can_be_called_on_receiver(base_type, fn_node.value, mname) {
						continue
					}
					return tc.call_info(mname, true)
				}
			}
		}
		if clean_array := array_type_from_receiver(clean) {
			if fn_node.value == 'bytestr' && is_byte_type(clean_array.elem_type) {
				return CallInfo{
					name:         'array.bytestr'
					params:       tarr1(base_type)
					return_type:  Type(string_)
					has_receiver: true
					params_known: true
				}
			}
			if fn_node.value == 'to_fixed_size' && base_node.kind == .array_literal {
				return CallInfo{
					name:         'array.to_fixed_size'
					params:       tarr1(base_type)
					return_type:  Type(ArrayFixed{
						elem_type: clean_array.elem_type
						len:       int(base_node.children_count)
						len_expr:  '${base_node.children_count}'
					})
					has_receiver: true
					params_known: true
				}
			}
			array_candidates := exact_array_receiver_method_candidates(clean_array, fn_node.value,
				tc.cur_module)
			for mname in array_candidates {
				if mname in tc.fn_ret_types {
					return tc.call_info(mname, true)
				}
			}
			if mname := tc.unique_receiver_method_suffix_match(array_candidates) {
				return tc.call_info(mname, true)
			}
			if fn_node.value in ['clone', 'reverse'] {
				if bad_type := tc.ownership_default_clone_missing_method(clean_array.elem_type) {
					tc.record_error(.call_arg_mismatch,
						'cannot ${fn_node.value} array elements: `${bad_type}` requires ownership destruction but has no `clone()` method',
						id)
				}
				return CallInfo{
					name:         'array.${fn_node.value}'
					params:       tarr1(base_type)
					return_type:  clean_array
					has_receiver: true
					params_known: true
				}
			}
		}
		if clean_map := map_type_from_receiver(clean) {
			for mname in receiver_method_name_candidates(clean, fn_node.value, tc.cur_module) {
				if checker_is_raw_collection_method_name(mname, 'map.') || mname !in tc.fn_ret_types {
					continue
				}
				if !tc.method_can_be_called_on_receiver(base_type, fn_node.value, mname) {
					continue
				}
				return tc.call_info(mname, true)
			}
			match fn_node.value {
				'clone' {
					if bad_type := tc.ownership_default_clone_missing_method(clean_map.key_type) {
						tc.record_error(.call_arg_mismatch,
							'cannot clone map keys: `${bad_type}` requires ownership destruction but has no `clone()` method',
							id)
					}
					if bad_type := tc.ownership_default_clone_missing_method(clean_map.value_type) {
						tc.record_error(.call_arg_mismatch,
							'cannot clone map values: `${bad_type}` requires ownership destruction but has no `clone()` method',
							id)
					}
					return CallInfo{
						name:         ''
						params:       tarr1(base_type)
						return_type:  base_type
						has_receiver: true
						params_known: true
					}
				}
				else {}
			}
		}
		if clean_map := map_type_from_receiver(clean) {
			if fn_node.value == 'keys' {
				if bad_type := tc.ownership_default_clone_missing_method(clean_map.key_type) {
					tc.record_error(.call_arg_mismatch,
						'cannot return independent map keys: `${bad_type}` requires ownership destruction but has no `clone()` method',
						id)
				}
				return CallInfo{
					name:         'map.keys'
					params:       tarr1(base_type)
					return_type:  Type(Array{
						elem_type: clean_map.key_type
					})
					has_receiver: true
					params_known: true
				}
			}
			if fn_node.value == 'values' {
				if bad_type := tc.ownership_default_clone_missing_method(clean_map.value_type) {
					tc.record_error(.call_arg_mismatch,
						'cannot return independent map values: `${bad_type}` requires ownership destruction but has no `clone()` method',
						id)
				}
				return CallInfo{
					name:         'map.values'
					params:       tarr1(base_type)
					return_type:  Type(Array{
						elem_type: clean_map.value_type
					})
					has_receiver: true
					params_known: true
				}
			}
			map_method := 'map.${fn_node.value}'
			if map_method in tc.fn_ret_types {
				if info := tc.map_builtin_call_info(base_type, clean_map, fn_node.value, map_method) {
					return info
				}
				return tc.call_info(map_method, true)
			}
		}
		if clean_array := array_like_type_for_method(clean, fn_node.value) {
			match fn_node.value {
				'first', 'last', 'pop', 'pop_left' {
					if fn_node.value in ['first', 'last'] {
						if bad_type := tc.ownership_default_clone_missing_method(clean_array.elem_type) {
							tc.record_error(.call_arg_mismatch,
								'cannot return an independent array element: `${bad_type}` requires ownership destruction but has no `clone()` method',
								id)
						}
					}
					return CallInfo{
						name:         ''
						params:       tarr1(base_type)
						return_type:  clean_array.elem_type
						has_receiver: true
						params_known: true
					}
				}
				'contains' {
					elem_type := tc.array_contains_elem_type(base_node, clean_array)
					return CallInfo{
						name:         ''
						params:       tarr2(base_type, elem_type)
						return_type:  Type(bool_)
						has_receiver: true
						params_known: true
					}
				}
				'join' {
					return CallInfo{
						name:         'array.join'
						params:       tarr2(base_type, Type(String{}))
						return_type:  Type(String{})
						has_receiver: true
						params_known: true
					}
				}
				'index', 'last_index' {
					return CallInfo{
						name:         ''
						params:       tarr2(base_type, clean_array.elem_type)
						return_type:  Type(int_)
						has_receiver: true
						params_known: true
					}
				}
				'hex' {
					if tc.is_builtin_hex_receiver(base_type) {
						return CallInfo{
							name:         '[]u8.hex'
							params:       tarr1(base_type)
							return_type:  Type(string_)
							has_receiver: true
							params_known: true
						}
					}
				}
				'repeat' {
					if bad_type := tc.ownership_default_clone_missing_method(clean_array.elem_type) {
						tc.record_error(.call_arg_mismatch,
							'cannot repeat array elements: `${bad_type}` requires ownership destruction but has no `clone()` method',
							id)
					}
					return CallInfo{
						name:         'array.repeat_to_depth'
						params:       tarr2(base_type, Type(int_))
						return_type:  base_type
						has_receiver: true
						params_known: true
					}
				}
				'repeat_to_depth' {
					return CallInfo{
						name:         'array.repeat_to_depth'
						params:       tarr3(base_type, Type(int_), Type(int_))
						return_type:  base_type
						has_receiver: true
						params_known: true
					}
				}
				'delete' {
					return CallInfo{
						name:         ''
						params:       tarr2(mutating_receiver_param_type(base_type), Type(int_))
						return_type:  Type(void_)
						has_receiver: true
						params_known: true
					}
				}
				'delete_last', 'clear' {
					return CallInfo{
						name:         ''
						params:       tarr1(mutating_receiver_param_type(base_type))
						return_type:  Type(void_)
						has_receiver: true
						params_known: true
					}
				}
				'insert', 'prepend' {
					params := if fn_node.value == 'insert' {
						tarr3(base_type, Type(int_), clean_array.elem_type)
					} else {
						tarr2(base_type, clean_array.elem_type)
					}
					return CallInfo{
						name:         'array.${fn_node.value}'
						params:       params
						return_type:  Type(void_)
						has_receiver: true
						params_known: true
					}
				}
				'filter' {
					$if ownership ? {
						tc.check_array_dsl_fn_borrows_element(node, clean_array.elem_type, id,
							'array.filter predicate')
					}
					if bad_type := tc.ownership_default_clone_missing_method(clean_array.elem_type) {
						tc.record_error(.call_arg_mismatch,
							'cannot filter array elements: `${bad_type}` requires ownership destruction but has no `clone()` method',
							id)
					}
					// filtering a fixed array yields a dynamic array
					filter_ret := if receiver_is_fixed_array(clean) {
						Type(Array{
							elem_type: clean_array.elem_type
						})
					} else {
						base_type
					}
					return CallInfo{
						name:         'array.filter'
						params:       tarr2(base_type, Type(bool_))
						return_type:  filter_ret
						has_receiver: true
						params_known: true
					}
				}
				'map' {
					elem_type := tc.array_map_return_elem_type(node)
					$if ownership ? {
						tc.check_array_dsl_fn_borrows_element(node, clean_array.elem_type, id,
							'array.map mapper')
					}
					if tc.array_map_result_borrows_element(node) {
						if bad_type := tc.ownership_default_clone_missing_method(elem_type) {
							tc.record_error(.call_arg_mismatch,
								'cannot clone borrowed array.map result: `${bad_type}` requires ownership destruction but has no `clone()` method',
								id)
						}
					}
					return CallInfo{
						name:         'array.map'
						params:       tarr2(base_type, elem_type)
						return_type:  Type(Array{
							elem_type: elem_type
						})
						has_receiver: true
						params_known: true
					}
				}
				'any', 'all' {
					$if ownership ? {
						tc.check_array_dsl_fn_borrows_element(node, clean_array.elem_type, id,
							'array.${fn_node.value} predicate')
					}
					return CallInfo{
						name:         'array.${fn_node.value}'
						params:       tarr2(base_type, Type(bool_))
						return_type:  Type(bool_)
						has_receiver: true
						params_known: true
					}
				}
				'count' {
					$if ownership ? {
						tc.check_array_dsl_fn_borrows_element(node, clean_array.elem_type, id,
							'array.count predicate')
					}
					return CallInfo{
						name:         'array.count'
						params:       tarr2(base_type, Type(bool_))
						return_type:  Type(int_)
						has_receiver: true
						params_known: true
					}
				}
				'sort_with_compare' {
					return CallInfo{
						name:         'array.sort_with_compare'
						params:       [
							mutating_receiver_param_type(base_type),
							Type(FnType{
								params:      [
									Type(Pointer{
										base_type: clean_array.elem_type
									}),
									Type(Pointer{
										base_type: clean_array.elem_type
									}),
								]
								return_type: Type(int_)
							}),
						]
						return_type:  Type(void_)
						has_receiver: true
						params_known: true
					}
				}
				'sorted_with_compare' {
					return CallInfo{
						name:         'array.sorted_with_compare'
						params:       [base_type,
							Type(FnType{
								params:      [
									Type(Pointer{
										base_type: clean_array.elem_type
									}),
									Type(Pointer{
										base_type: clean_array.elem_type
									}),
								]
								return_type: Type(int_)
							})]
						return_type:  base_type
						has_receiver: true
						params_known: true
					}
				}
				'sort' {
					mut params := tarr1(mutating_receiver_param_type(base_type))
					if call_explicit_arg_count(node) > 0 {
						params << Type(bool_)
					}
					return CallInfo{
						name:         'array.sort'
						params:       params
						return_type:  Type(void_)
						has_receiver: true
						params_known: true
					}
				}
				'sorted' {
					mut params := tarr1(base_type)
					if call_explicit_arg_count(node) > 0 {
						params << Type(bool_)
					}
					return CallInfo{
						name:         'array.sorted'
						params:       params
						return_type:  base_type
						has_receiver: true
						params_known: true
					}
				}
				else {}
			}
		}
		if fixed_array := tc.fixed_array_type_from_receiver(clean) {
			if fn_node.value == 'clone' {
				return CallInfo{
					name:         'array.clone'
					params:       tarr1(base_type)
					return_type:  Type(Array{
						elem_type: fixed_array.elem_type
					})
					has_receiver: true
					params_known: true
				}
			}
		}
		mut array_pointers_fallback := false
		if fn_node.value == 'pointers' {
			if _ := array_type_from_receiver(clean) {
				array_pointers_fallback = true
			}
		}
		if fixed_array := tc.fixed_array_type_from_receiver(clean) {
			if fn_node.value == 'wait' {
				if info := tc.fixed_array_thread_wait_call_info(base_type, fixed_array) {
					return info
				}
			}
			if info := tc.fixed_array_dynamic_receiver_call_info(base_type, fixed_array,
				fn_node.value)
			{
				return info
			}
			if fn_node.value == 'pointers' {
				if base_type !is Pointer && !tc.expr_can_take_address(base_id) {
					tc.record_error(.call_arg_mismatch,
						'fixed array receiver for `pointers` must be addressable', id)
				}
				if info := tc.fixed_array_pointers_call_info(base_type) {
					return info
				}
			}
		}
		type_name := resolve_type_name_for_method(clean)
		if type_name.len > 0 {
			if fn_node.value == 'str' && (clean is Primitive || clean is Char || clean is Rune) {
				return CallInfo{
					name:         ''
					params:       tarr1(base_type)
					return_type:  Type(string_)
					has_receiver: true
					params_known: true
				}
			}
			if info := tc.resolve_generic_struct_method(type_name, fn_node.value) {
				return info
			}
			for mname in receiver_method_name_candidates(clean, fn_node.value, tc.cur_module) {
				if mname in tc.fn_ret_types {
					if array_pointers_fallback && mname == 'array.pointers' {
						continue
					}
					if !tc.method_can_be_called_on_receiver(base_type, fn_node.value, mname) {
						continue
					}
					if clean_map := map_type_from_receiver(clean) {
						if info := tc.map_builtin_call_info(base_type, clean_map, fn_node.value,
							mname)
						{
							return info
						}
					}
					return tc.call_info(mname, true)
				}
			}
			if array_pointers_fallback {
				return CallInfo{
					name:         'array.pointers'
					params:       tarr1(base_type)
					return_type:  Type(Array{
						elem_type: Type(voidptr_)
					})
					has_receiver: true
					params_known: true
				}
			}
			if fixed_array := tc.fixed_array_type_from_receiver(clean) {
				if info := tc.fixed_array_dynamic_receiver_call_info(base_type, fixed_array,
					fn_node.value)
				{
					return info
				}
				if fn_node.value == 'pointers' {
					if base_type !is Pointer && !tc.expr_can_take_address(base_id) {
						tc.record_error(.call_arg_mismatch,
							'fixed array receiver for `pointers` must be addressable', id)
					}
					if info := tc.fixed_array_pointers_call_info(base_type) {
						return info
					}
				}
			}
			if clean is Interface {
				if info := tc.interface_receiver_method_call_info(clean.name, fn_node.value) {
					return info
				}
			}
			if info := tc.embedded_method_call_info(type_name, fn_node.value) {
				return info
			}
			if fn_node.value == 'use' && clean is Struct
				&& tc.struct_has_middleware_receiver(type_name) {
				return CallInfo{
					name:         '${type_name}.use'
					params:       []Type{}
					return_type:  Type(void_)
					has_receiver: true
					params_known: false
				}
			}
		}
		if clean is SumType {
			if info := tc.resolve_generic_sum_method(clean.name, fn_node.value) {
				return info
			}
			mname := '${clean.name}.${fn_node.value}'
			if mname in tc.fn_ret_types {
				return tc.call_info(mname, true)
			}
		}
		if clean is Enum {
			if clean.is_flag && fn_node.value in ['has', 'all'] {
				return CallInfo{
					name:         ''
					params:       tarr2(base_type, base_type)
					return_type:  Type(bool_)
					has_receiver: true
					params_known: true
				}
			}
			if clean.is_flag && fn_node.value in ['set', 'clear', 'toggle'] {
				return CallInfo{
					name:         ''
					params:       tarr2(base_type, base_type)
					return_type:  Type(void_)
					has_receiver: true
					params_known: true
				}
			}
			if clean.is_flag && fn_node.value in ['set_all', 'clear_all'] {
				return CallInfo{
					name:         ''
					params:       tarr1(base_type)
					return_type:  Type(void_)
					has_receiver: true
					params_known: true
				}
			}
			if clean.is_flag && fn_node.value == 'is_empty' {
				return CallInfo{
					name:         ''
					params:       tarr1(base_type)
					return_type:  Type(bool_)
					has_receiver: true
					params_known: true
				}
			}
			if fn_node.value == 'str' {
				return CallInfo{
					name:         '${clean.name}.str'
					params:       tarr1(base_type)
					return_type:  Type(string_)
					has_receiver: true
					params_known: true
				}
			}
			mname := '${clean.name}.${fn_node.value}'
			if mname in tc.fn_ret_types {
				return tc.call_info(mname, true)
			}
		}
		if fn_node.value == 'clone' && tc.type_has_compiler_default_clone(clean) {
			if bad_type := tc.ownership_default_clone_missing_method(clean) {
				tc.record_error(.call_arg_mismatch,
					'cannot generate default clone for `${clean.name()}`: `${bad_type}` requires ownership destruction but has no `clone()` method',
					id)
			}
			// `#[derive(Clone)]` in Rust maps to `implements IClone` in the ownership
			// translation, whose `clone()` is compiler-provided. V structs are value types,
			// so `.clone()` yields a copy of the receiver: resolve it to the (unwrapped)
			// receiver type. A user-defined `clone()` method is matched earlier via
			// `receiver_method_name_candidates`, so this only supplies the default.
			return CallInfo{
				name:         ''
				params:       tarr1(base_type)
				return_type:  clean
				has_receiver: true
				params_known: true
			}
		}
		if fn_node.value == 'free' && type_has_runtime_value(clean) {
			return CallInfo{
				name:         ''
				params:       tarr1(base_type)
				return_type:  Type(void_)
				has_receiver: true
				params_known: true
			}
		}
		if fn_node.value == 'str' {
			return CallInfo{
				name:         ''
				params:       tarr1(base_type)
				return_type:  Type(string_)
				has_receiver: true
				params_known: true
			}
		}
		if fn_node.value == 'hex' && tc.is_builtin_hex_receiver(base_type) {
			return CallInfo{
				name:         ''
				params:       tarr1(base_type)
				return_type:  Type(string_)
				has_receiver: true
				params_known: true
			}
		}
		return none
	}
	if fn_node.kind == .ident {
		if fn_node.value == 'error' || fn_node.value == 'error_with_code' {
			mut params := []Type{}
			if fn_node.value == 'error_with_code' {
				params = tarr2(Type(string_), Type(int_))
			} else {
				params = tarr1(Type(string_))
			}
			return CallInfo{
				name:         fn_node.value
				params:       params
				return_type:  tc.parse_type('IError')
				params_known: true
			}
		}
		if fn_node.value == 'malloc' {
			return CallInfo{
				name:         'malloc'
				params:       tarr1(Type(ISize{}))
				return_type:  Type(Pointer{
					base_type: Type(u8_)
				})
				params_known: true
			}
		}
		if typ := tc.cur_scope.lookup(fn_node.value) {
			if fn_typ := fn_type_from_type(typ) {
				return CallInfo{
					name:         ''
					params:       fn_typ.params
					return_type:  fn_typ.return_type
					params_known: true
				}
			}
		}
		if local_name := tc.local_bare_fn_key(fn_node.value) {
			return tc.call_info(local_name, false)
		}
		if imported_name := tc.resolve_selective_import_symbol(fn_node.value) {
			if info := tc.decode_call_info_from_type_arg(node, imported_name, false) {
				return info
			}
			return tc.call_info(imported_name, false)
		}
		if fn_node.value in tc.fn_ret_types {
			return tc.call_info(fn_node.value, false)
		}
		if is_builtin_void_call_name(fn_node.value) {
			return CallInfo{
				name:         fn_node.value
				params:       []Type{}
				return_type:  Type(void_)
				params_known: false
			}
		}
	}
	return none
}

fn (tc &TypeChecker) binding_is_strings_builder(name string) bool {
	if name.len == 0 || tc.fn_context.node_id < 0 || tc.fn_context.node_id >= tc.a.nodes.len {
		return false
	}
	mut stack := []flat.NodeId{}
	root := tc.a.nodes[tc.fn_context.node_id]
	for i in 0 .. root.children_count {
		child_id := tc.a.child(&root, i)
		if tc.a.node(child_id).kind != .param {
			stack << child_id
		}
	}
	for stack.len > 0 {
		id := stack.pop()
		node := tc.a.node(id)
		if node.kind == .fn_literal {
			continue
		}
		if node.kind == .decl_assign && node.children_count >= 2 {
			lhs := tc.a.child_node(node, 0)
			if lhs.kind == .ident && lhs.value == name
				&& tc.expr_is_strings_new_builder_call(tc.a.child(node, 1)) {
				return true
			}
		}
		for i in 0 .. node.children_count {
			stack << tc.a.child(node, i)
		}
	}
	return false
}

fn (tc &TypeChecker) expr_is_strings_new_builder_call(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.node(id)
	if node.kind in [.paren, .expr_stmt, .cast_expr] && node.children_count > 0 {
		return tc.expr_is_strings_new_builder_call(tc.a.child(node, 0))
	}
	if node.kind != .call || node.children_count == 0 {
		return false
	}
	callee := tc.a.child_node(node, 0)
	if callee.kind == .ident {
		return callee.value in ['strings.new_builder', 'strings__new_builder']
	}
	if callee.kind == .selector && callee.value == 'new_builder' && callee.children_count > 0 {
		base := tc.a.child_node(callee, 0)
		return base.kind == .ident && base.value == 'strings'
	}
	return false
}

fn (tc &TypeChecker) enum_from_call_info(enum_name string) CallInfo {
	return CallInfo{
		name: ''
		// Enum.from accepts one of two type families. The marker is validated
		// after resolving the argument in check_call_arg_types.
		params:       tarr1(Type(Unknown{
			reason: 'enum from input'
		}))
		return_type:  Type(OptionType{
			base_type: Type(Enum{
				name:    enum_name
				is_flag: enum_name in tc.flag_enums
			})
		})
		params_known: true
	}
}

fn (tc &TypeChecker) is_builtin_hex_receiver(typ Type) bool {
	if tc.type_is_pointer_receiver(typ) {
		return false
	}
	clean := typ
	if clean is Alias {
		return tc.is_builtin_hex_receiver(clean.base_type)
	}
	if clean is Array {
		return is_byte_type(clean.elem_type)
	}
	if clean is String {
		return true
	}
	if clean is Primitive {
		return prim_c_type_from(clean.props, clean.size) in ['u8', 'i8', 'u16', 'i16', 'u32', 'int',
			'u64', 'i64']
	}
	return clean is Rune || clean is Char
}

fn (tc &TypeChecker) builtin_receiver_method_call_info(base_type Type, method string) ?CallInfo {
	if !tc.is_builtin_hex_receiver(base_type) || method !in ['hex', 'hex_full'] {
		return none
	}
	clean := unwrap_pointer(base_type)
	if clean is String {
		if method == 'hex' {
			return CallInfo{
				name:         'string.hex'
				params:       tarr1(base_type)
				return_type:  Type(string_)
				has_receiver: true
				params_known: true
			}
		}
		return none
	}
	if clean is Array {
		if method == 'hex' {
			return CallInfo{
				name:         '[]u8.hex'
				params:       tarr1(base_type)
				return_type:  Type(string_)
				has_receiver: true
				params_known: true
			}
		}
		return none
	}
	method_receiver := builtin_receiver_method_type_name(clean)
	if method_receiver.len == 0 {
		return none
	}
	return CallInfo{
		name:         '${method_receiver}.${method}'
		params:       tarr1(base_type)
		return_type:  Type(string_)
		has_receiver: true
		params_known: true
	}
}

fn builtin_receiver_method_type_name(clean Type) string {
	if clean is Alias {
		return builtin_receiver_method_type_name(clean.base_type)
	}
	if clean is Primitive {
		return prim_c_type_from(clean.props, clean.size)
	}
	if clean is Rune {
		return 'rune'
	}
	if clean is Char {
		return 'char'
	}
	return ''
}

fn (tc &TypeChecker) current_receiver_param_method_call_info(base_id flat.NodeId, method string) ?CallInfo {
	if tc.fn_context.node_id < 0 || int(base_id) < 0 || int(base_id) >= tc.a.nodes.len {
		return none
	}
	base := tc.a.nodes[int(base_id)]
	if base.kind != .ident {
		return none
	}
	fn_node := tc.a.nodes[tc.fn_context.node_id]
	if fn_node.kind != .fn_decl || !fn_node.value.contains('.') {
		return none
	}
	receiver_name := fn_node.value.all_before_last('.')
	if receiver_name.len == 0 {
		return none
	}
	mut param_type := Type(void_)
	mut found_param := false
	for i in 0 .. fn_node.children_count {
		param := tc.a.child_node(&fn_node, i)
		if param.kind == .param && param.value == base.value {
			param_type = tc.parse_type(param.typ)
			found_param = true
			break
		}
	}
	if !found_param {
		return none
	}
	receiver_type := tc.parse_type(receiver_name)
	if !tc.receiver_compatible(param_type, receiver_type) {
		return none
	}
	method_name := '${receiver_name}.${method}'
	qualified_method_name := checker_qualified_fn_name(tc.cur_module, method_name)
	mut candidates := []string{}
	if qualified_method_name != method_name {
		candidates << qualified_method_name
	}
	candidates << method_name
	for candidate in candidates {
		if candidate in tc.fn_ret_types {
			return tc.call_info(candidate, true)
		}
	}
	return none
}

fn (tc &TypeChecker) type_is_pointer_receiver(typ Type) bool {
	if typ is Pointer {
		return true
	}
	if typ is Alias {
		return tc.type_is_pointer_receiver(typ.base_type)
	}
	return false
}

fn (tc &TypeChecker) method_can_be_called_on_receiver(receiver Type, method string, method_name string) bool {
	if method != 'hex' || !tc.type_is_pointer_receiver(receiver) {
		return true
	}
	params := tc.fn_param_types[method_name] or { return false }
	if params.len == 0 {
		return false
	}
	return tc.type_is_pointer_receiver(params[0])
}

fn (tc &TypeChecker) receiver_expr_is_pointer(id flat.NodeId) bool {
	if int(id) < 0 {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .ident {
		if typ := tc.cur_scope.lookup(node.value) {
			return tc.type_is_pointer_receiver(typ)
		}
	}
	if node.typ.starts_with('&') {
		return true
	}
	return tc.type_is_pointer_receiver(tc.resolve_type(id))
}

fn is_byte_type(typ Type) bool {
	if typ is Alias {
		return is_byte_type(typ.base_type)
	}
	return typ is Primitive && typ.props.has(.integer) && typ.props.has(.unsigned) && typ.size == 8
}

fn (mut tc TypeChecker) resolve_generic_call_info(id flat.NodeId, fn_node flat.Node) ?CallInfo {
	if fn_node.kind != .index || fn_node.children_count < 2 || fn_node.value == 'range' {
		return none
	}
	base_id := tc.a.child(&fn_node, 0)
	type_args := tc.generic_call_type_arg_names(fn_node)
	if type_args.len == 0 {
		return none
	}
	tc.check_missing_concrete_generic_call_type_args(fn_node)
	base_node := tc.a.nodes[int(base_id)]
	if base_node.kind == .selector && base_node.children_count > 0 {
		recv_id := tc.a.child(&base_node, 0)
		base_type := tc.resolve_type(recv_id)
		clean := unwrap_pointer(base_type)
		type_name := resolve_type_name_for_method(clean)
		if type_name.len > 0 {
			call_name := '${type_name}.${base_node.value}'
			if call_name in tc.fn_ret_types {
				if tc.explicit_generic_arg_count_mismatch(call_name, type_args, id) {
					return tc.call_info(call_name, true)
				}
				if info := tc.explicit_generic_call_info(call_name, true, type_args) {
					return info
				}
				return tc.call_info(call_name, true)
			}
			if receiver_info := tc.resolve_generic_struct_method(type_name, base_node.value) {
				if tc.explicit_generic_arg_count_mismatch(receiver_info.name, type_args, id) {
					return receiver_info
				}
				return tc.specialize_explicit_generic_receiver_call(receiver_info, type_args)
			}
			// Generic methods promoted from an embedded non-generic receiver keep
			// the declaring receiver in the function table. Resolve that promoted
			// method before rejecting `outer.method[T](...)`.
			if embedded_info := tc.embedded_method_call_info(type_name, base_node.value) {
				if tc.explicit_generic_arg_count_mismatch(embedded_info.name, type_args, id) {
					return embedded_info
				}
				if info := tc.explicit_generic_call_info(embedded_info.name, true, type_args) {
					return info
				}
				return embedded_info
			}
		}
		if static_name := tc.explicit_generic_static_selector_key(base_node) {
			if tc.explicit_generic_arg_count_mismatch(static_name, type_args, id) {
				return tc.call_info(static_name, false)
			}
			if info := tc.explicit_generic_call_info(static_name, false, type_args) {
				return info
			}
			return tc.call_info(static_name, false)
		}
	}
	call_name := tc.generic_call_base_name(base_node) or {
		if type_name := tc.generic_call_base_type_name(base_node) {
			return CallInfo{
				name:         ''
				params:       []Type{}
				return_type:  tc.parse_type('${type_name}[${type_args.join(', ')}]')
				params_known: false
			}
		}
		return none
	}
	if is_veb_run_at_call_name(call_name) {
		return CallInfo{
			name:         call_name
			params:       []Type{}
			return_type:  Type(ResultType{
				base_type: Type(void_)
			})
			params_known: false
		}
	}
	if call_name !in tc.fn_ret_types {
		return none
	}
	if is_decode_call_name(call_name) {
		if type_args.len != 1 {
			if tc.should_diagnose(id) {
				tc.record_error(.call_arg_mismatch,
					'generic argument count mismatch for `${call_name}`: expected 1, got ${type_args.len}',
					id)
			}
			return tc.failed_explicit_generic_call_info(call_name)
		}
		return CallInfo{
			name:          call_name
			params:        tc.fn_param_types[call_name] or { []Type{} }
			shared_params: tc.fn_shared_params[call_name] or { []bool{} }
			return_type:   Type(ResultType{
				base_type: tc.parse_type(type_args[0])
			})
			has_receiver:  false
			is_variadic:   tc.fn_variadic[call_name] or { false }
			is_c_variadic: tc.c_variadic_fns[call_name] or { false }
			params_known:  call_name in tc.fn_param_types
		}
	}
	if tc.explicit_generic_arg_count_mismatch(call_name, type_args, id) {
		return tc.call_info(call_name, false)
	}
	if info := tc.explicit_generic_call_info(call_name, false, type_args) {
		return info
	}
	return tc.call_info(call_name, false)
}

fn (mut tc TypeChecker) check_missing_concrete_generic_call_type_args(index_node flat.Node) {
	for i in 1 .. index_node.children_count {
		arg_id := tc.a.child(&index_node, i)
		arg := tc.a.node(arg_id)
		if arg.kind == .index {
			continue
		}
		name := tc.generic_call_type_arg_name(arg_id)
		if name.len == 0 || name in tc.fn_context.generic_params {
			continue
		}
		qualified := tc.qualify_name(name)
		if name !in tc.struct_generic_params && qualified !in tc.struct_generic_params
			&& name !in tc.sum_generic_params && qualified !in tc.sum_generic_params
			&& name !in tc.type_alias_generic_params && qualified !in tc.type_alias_generic_params {
			continue
		}
		tc.record_error_at(.unknown_type, 'missing concrete type on generic type', arg_id, arg.pos)
	}
}

fn (mut tc TypeChecker) specialize_explicit_generic_receiver_call(info CallInfo, type_args []string) CallInfo {
	generic_params := tc.fn_generic_params[info.name] or { return info }
	if generic_params.len == 0 || generic_params.len != type_args.len {
		return info
	}
	mut concrete_types := []Type{cap: type_args.len}
	for arg in type_args {
		concrete_types << tc.parse_type(tc.qualify_resolution_type_text(arg))
	}
	mut params := []Type{cap: info.params.len}
	for param in info.params {
		params << tc.substitute_generic_type_values(param, concrete_types, generic_params)
	}
	return CallInfo{
		...info
		params:      params
		return_type: tc.substitute_generic_type_values(info.return_type, concrete_types,
			generic_params)
	}
}

fn (tc &TypeChecker) explicit_generic_static_selector_key(selector flat.Node) ?string {
	if selector.kind != .selector || selector.children_count == 0 {
		return none
	}
	receiver := tc.a.child_node(&selector, 0)
	if receiver.kind == .ident {
		if tc.ident_resolves_to_value(receiver.value) {
			return none
		}
		return tc.static_assoc_fn_key_for_base(receiver.value, selector.value)
	}
	if receiver.kind == .selector && receiver.children_count > 0 {
		module_node := tc.a.child_node(receiver, 0)
		if module_node.kind == .ident {
			module_name := tc.resolve_import_alias(module_node.value) or { module_node.value }
			return tc.static_assoc_fn_key_for_base('${module_name}.${receiver.value}',
				selector.value)
		}
	}
	return none
}

fn (mut tc TypeChecker) explicit_generic_arg_count_mismatch(name string, type_args []string, id flat.NodeId) bool {
	generic_params := tc.fn_generic_params[name] or { return false }
	if type_args.len == generic_params.len {
		return false
	}
	if tc.should_diagnose(id) {
		plural := if generic_params.len == 1 { '' } else { 's' }
		call := tc.a.node(id)
		callee_id := if call.children_count > 0 { tc.a.child(call, 0) } else { id }
		tc.record_error_at(.call_arg_mismatch,
			'expected ${generic_params.len} generic parameter${plural}, got ${type_args.len}', id,
			tc.explicit_generic_args_diagnostic_pos(callee_id))
	}
	return true
}

fn (tc &TypeChecker) failed_explicit_generic_call_info(name string) CallInfo {
	return CallInfo{
		name:         name
		params:       []Type{}
		return_type:  unknown_type('invalid explicit generic call `${name}`')
		params_known: false
	}
}

// explicit_generic_concrete_arg_text qualifies an explicit generic type argument
// spelled at a call site so it survives being re-parsed in the callee module.
fn (tc &TypeChecker) explicit_generic_concrete_arg_text(type_arg string) string {
	qualified := tc.qualify_resolution_type_text(type_arg)
	if !qualified.contains('.') && !is_builtin_type_name(qualified)
		&& qualified !in tc.fn_context.generic_params && (qualified in tc.structs
		|| qualified in tc.enum_names || qualified in tc.flag_enums
		|| qualified in tc.sum_types || qualified in tc.interface_names
		|| qualified in tc.type_aliases) {
		return 'main.' + qualified
	}
	return qualified
}

fn (tc &TypeChecker) explicit_generic_call_info(name string, has_receiver bool, type_args []string) ?CallInfo {
	generic_params := tc.fn_generic_params[name] or { return none }
	param_texts := tc.fn_param_type_texts[name] or { return none }
	if generic_params.len == 0 || type_args.len != generic_params.len {
		return none
	}
	mut concrete_args := []string{cap: generic_params.len}
	for i in 0 .. generic_params.len {
		concrete_args << tc.explicit_generic_concrete_arg_text(type_args[i])
	}
	mut sub_params := []Type{}
	for param_text in param_texts {
		sub_params << tc.parse_fn_signature_type(name, subst_generic_text(param_text,
			concrete_args, generic_params))
	}
	ret_text := tc.fn_ret_type_texts[name] or { '' }
	sub_ret := if ret_text.len > 0 {
		tc.parse_fn_signature_type(name,
			subst_generic_text(ret_text, concrete_args, generic_params))
	} else {
		tc.fn_ret_types[name] or { Type(void_) }
	}
	return CallInfo{
		name:                 name
		params:               sub_params
		shared_params:        tc.fn_shared_params[name] or { []bool{} }
		return_type:          sub_ret
		has_receiver:         has_receiver
		is_variadic:          tc.fn_variadic[name] or { false }
		is_c_variadic:        tc.c_variadic_fns[name] or { false }
		params_known:         true
		has_implicit_veb_ctx: tc.fn_implicit_veb_ctx[name] or { false }
	}
}

fn (tc &TypeChecker) generic_call_base_type_name(base_node flat.Node) ?string {
	if base_node.kind == .ident {
		qname := tc.qualify_name(base_node.value)
		if tc.type_symbol_known(qname) {
			return qname
		}
		if tc.type_symbol_known(base_node.value) {
			return base_node.value
		}
		if resolved := tc.resolve_selective_import_type_symbol(base_node.value) {
			return resolved
		}
	}
	if base_node.kind == .selector && base_node.children_count > 0 {
		inner := tc.a.child_node(&base_node, 0)
		if inner.kind == .ident {
			if static_name := tc.static_assoc_fn_key_for_base(inner.value, base_node.value) {
				return static_name
			}
			mod_name := tc.resolve_import_alias(inner.value) or { inner.value }
			full_name := '${mod_name}.${base_node.value}'
			if tc.type_symbol_known(full_name) {
				return full_name
			}
		}
	}
	return none
}

fn is_decode_call_name(name string) bool {
	return name in ['json.decode', 'json2.decode', 'x.json2.decode']
}

fn (tc &TypeChecker) decode_call_info_from_type_arg(node flat.Node, name string, has_receiver bool) ?CallInfo {
	if !is_decode_call_name(name) || node.children_count < 2 {
		return none
	}
	type_arg_id := tc.a.child(&node, 1)
	type_arg := tc.generic_call_type_arg_name(type_arg_id)
	if type_arg.len == 0 {
		return none
	}
	info := tc.call_info(name, has_receiver)
	params := if info.params.len > 0 { info.params[1..].clone() } else { []Type{} }
	return CallInfo{
		name:                 info.name
		params:               params
		return_type:          Type(ResultType{
			base_type: tc.parse_type(type_arg)
		})
		has_receiver:         info.has_receiver
		is_variadic:          info.is_variadic
		is_c_variadic:        info.is_c_variadic
		params_known:         info.params_known
		has_implicit_veb_ctx: info.has_implicit_veb_ctx
		arg_offset:           1
	}
}

fn is_veb_run_at_call_name(name string) bool {
	return name == 'veb.run_at'
}

fn (tc &TypeChecker) generic_call_base_name(base_node flat.Node) ?string {
	if base_node.kind == .ident {
		if local_name := tc.local_bare_fn_key(base_node.value) {
			return local_name
		}
		if imported_name := tc.resolve_selective_import_symbol(base_node.value) {
			return imported_name
		}
		if base_node.value in tc.fn_ret_types {
			return base_node.value
		}
		return none
	}
	if base_node.kind == .selector && base_node.children_count > 0 {
		inner := tc.a.child_node(&base_node, 0)
		if inner.kind == .ident {
			if static_name := tc.static_assoc_fn_key_for_base(inner.value, base_node.value) {
				return static_name
			}
			mod_name := tc.resolve_import_alias(inner.value) or { inner.value }
			full_name := '${mod_name}.${base_node.value}'
			if is_veb_run_at_call_name(full_name) {
				return full_name
			}
			if full_name in tc.fn_ret_types {
				return full_name
			}
		}
	}
	return none
}

fn (tc &TypeChecker) generic_call_type_arg_names(index_node flat.Node) []string {
	if index_node.kind != .index || index_node.children_count < 2 || index_node.value == 'range' {
		return []string{}
	}
	mut args := []string{}
	for i in 1 .. index_node.children_count {
		arg := tc.generic_call_type_arg_name(tc.a.child(&index_node, i))
		if arg.len == 0 {
			return []string{}
		}
		args << arg
	}
	return args
}

fn (tc &TypeChecker) generic_call_type_arg_name(id flat.NodeId) string {
	if int(id) < 0 {
		return ''
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			return node.value
		}
		.selector {
			if node.children_count == 0 {
				return node.value
			}
			base := tc.generic_call_type_arg_name(tc.a.child(&node, 0))
			if base.len == 0 {
				return node.value
			}
			return '${base}.${node.value}'
		}
		.index {
			if node.children_count < 2 || node.value == 'range' {
				return ''
			}
			base := tc.generic_call_type_arg_name(tc.a.child(&node, 0))
			if base.len == 0 {
				return ''
			}
			mut args := []string{}
			for i in 1 .. node.children_count {
				arg := tc.generic_call_type_arg_name(tc.a.child(&node, i))
				if arg.len == 0 {
					return ''
				}
				args << arg
			}
			return '${base}[${args.join(', ')}]'
		}
		.array_init {
			if node.value.len > 0 {
				if node.value.starts_with('[') {
					return node.value
				}
				return '[]${node.value}'
			}
			return ''
		}
		.map_init {
			return node.value
		}
		.struct_decl {
			return node.value
		}
		.prefix {
			if node.children_count == 0 {
				return ''
			}
			child := tc.generic_call_type_arg_name(tc.a.child(&node, 0))
			if child.len == 0 {
				return ''
			}
			if node.op == .amp {
				return '&${child}'
			}
			return child
		}
		else {
			return ''
		}
	}
}

// call_info updates call info state for TypeChecker.
fn (tc &TypeChecker) call_info(name string, has_receiver bool) CallInfo {
	mut params := []Type{}
	mut params_known := false
	if p := tc.fn_param_types[name] {
		params = p.clone()
		params_known = true
	}
	if params.len == 1 && is_print_style_fn_name(name)
		&& print_style_param_accepts_string(params[0]) {
		params[0] = unknown_type('print argument')
	}
	return_type := tc.alias_return_type_from_text(name) or {
		tc.fn_ret_types[name] or { unknown_type('unknown return type for `${name}`') }
	}
	return CallInfo{
		name:                 name
		params:               params
		shared_params:        tc.fn_shared_params[name] or { []bool{} }
		return_type:          return_type
		has_receiver:         has_receiver
		is_variadic:          tc.fn_variadic[name] or { false }
		is_c_variadic:        tc.c_variadic_fns[name] or { false }
		params_known:         params_known
		has_implicit_veb_ctx: tc.fn_implicit_veb_ctx[name] or { false }
	}
}

fn (tc &TypeChecker) alias_return_type_from_text(fn_name string) ?Type {
	ret_text := tc.fn_ret_type_texts[fn_name] or { return none }
	clean := trimmed_space(ret_text)
	if clean.len == 0 {
		return none
	}
	if target := tc.type_aliases[clean] {
		return Type(Alias{
			name:      clean
			base_type: tc.parse_type(target)
		})
	}
	if clean.contains('.') {
		return none
	}
	mod := tc.fn_type_modules[fn_name] or { '' }
	if mod.len == 0 || mod in ['main', 'builtin'] {
		return none
	}
	qname := '${mod}.${clean}'
	target := tc.type_aliases[qname] or { return none }
	return Type(Alias{
		name:      qname
		base_type: tc.parse_type(target)
	})
}

fn array_type_from_receiver(t Type) ?Array {
	if t is Array {
		return t
	}
	if t is Alias {
		return array_type_from_receiver(t.base_type)
	}
	return none
}

fn (tc &TypeChecker) thread_wait_return_type(t Type) ?Type {
	clean := unwrap_pointer(t)
	if clean is Struct {
		thread_name := trimmed_space(clean.name)
		if thread_name == 'thread' || thread_name.ends_with('.thread') {
			return Type(void_)
		}
		if thread_name.starts_with('thread ') {
			return tc.parse_type(trimmed_space(thread_name[7..]))
		}
	}
	return none
}

// fixed_array_lowered_methods lists the builtin array methods the transform
// actually lowers for fixed-array receivers (it copies the fixed array into a
// dynamic temp and re-dispatches). Methods outside this list stay rejected:
// in-place mutators like `sort` would silently modify the temp copy, and
// `first`/`last`/`pop` are not fixed-array methods in V.
const fixed_array_lowered_methods = ['contains', 'index', 'last_index', 'any', 'all', 'count',
	'map', 'filter', 'str', 'wait']

fn receiver_is_fixed_array(t Type) bool {
	if t is ArrayFixed {
		return true
	}
	if t is Alias {
		return receiver_is_fixed_array(t.base_type)
	}
	return false
}

fn mutating_receiver_param_type(base_type Type) Type {
	if base_type is Pointer {
		return base_type
	}
	return Type(Pointer{
		base_type: base_type
	})
}

// array_like_type_for_method returns the receiver's array type for a builtin
// array method call. Fixed-array receivers are widened to a dynamic array type,
// but only for the methods the transform can lower for them.
fn array_like_type_for_method(t Type, method string) ?Array {
	if t is Array {
		return t
	}
	if t is ArrayFixed {
		if method in fixed_array_lowered_methods {
			return Array{
				elem_type: t.elem_type
			}
		}
		return none
	}
	if t is Alias {
		return array_like_type_for_method(t.base_type, method)
	}
	return none
}

fn map_type_from_receiver(t Type) ?Map {
	if t is Map {
		return t
	}
	if t is Alias {
		return map_type_from_receiver(t.base_type)
	}
	return none
}

fn (tc &TypeChecker) map_type_from_alias_target(t Type) ?Map {
	if map_type := map_type_from_receiver(t) {
		return map_type
	}
	name := t.name()
	if name.len == 0 {
		return none
	}
	target := tc.alias_target_type_text(name) or { return none }
	return map_type_from_receiver(tc.parse_type(target))
}

fn (tc &TypeChecker) receiver_is_sum_type(t Type) bool {
	if t is SumType {
		return true
	}
	if t is Alias {
		return tc.receiver_is_sum_type(t.base_type)
	}
	name := t.name()
	if name.len == 0 {
		return false
	}
	if name in tc.sum_types {
		return true
	}
	if !name.contains('.') {
		qname := tc.qualify_name(name)
		if qname in tc.sum_types {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) fixed_array_type_from_receiver(t Type) ?ArrayFixed {
	if t is ArrayFixed {
		return t
	}
	if t is Alias {
		return tc.fixed_array_type_from_receiver(t.base_type)
	}
	name := t.name()
	if name.starts_with('fn(') || name.starts_with('fn (') {
		return none
	}
	if name.contains('[') && !name.starts_with('[') {
		bracket := name.last_index_u8(`[`)
		bracket_end := name.last_index_u8(`]`)
		if bracket >= 0 && bracket_end > bracket {
			len_text := trimmed_space(name[bracket + 1..bracket_end])
			if !is_fixed_array_len_text(len_text)
				&& tc.const_int_value_in_module(len_text, tc.cur_module, []string{}) == none {
				return none
			}
			return ArrayFixed{
				elem_type: tc.parse_type(name[..bracket])
				len:       if is_decimal_int_literal(len_text) { len_text.int() } else { 0 }
				len_expr:  if is_decimal_int_literal(len_text) { '' } else { len_text }
			}
		}
	}
	return none
}

fn (tc &TypeChecker) fixed_array_thread_wait_call_info(base_type Type, arr ArrayFixed) ?CallInfo {
	elem := arr.elem_type
	if elem is Struct {
		name := trimmed_space(elem.name)
		if name == 'thread' {
			return CallInfo{
				name:         ''
				params:       tarr1(base_type)
				return_type:  Type(void_)
				has_receiver: true
				params_known: true
			}
		}
		if name.starts_with('thread ') {
			return CallInfo{
				name:         ''
				params:       tarr1(base_type)
				return_type:  tc.thread_array_wait_return_type(name[7..])
				has_receiver: true
				params_known: true
			}
		}
	}
	return none
}

fn (tc &TypeChecker) thread_array_wait_return_type(payload string) Type {
	ret_name := trimmed_space(payload)
	if ret_name == '?' {
		return Type(OptionType{
			base_type: Type(void_)
		})
	}
	if ret_name == '!' {
		return Type(ResultType{
			base_type: Type(void_)
		})
	}
	ret_type := tc.parse_type(ret_name)
	if ret_type is OptionType {
		if ret_type.base_type is Void {
			return ret_type
		}
		return Type(OptionType{
			base_type: Type(Array{
				elem_type: ret_type.base_type
			})
		})
	}
	if ret_type is ResultType {
		if ret_type.base_type is Void {
			return ret_type
		}
		return Type(ResultType{
			base_type: Type(Array{
				elem_type: ret_type.base_type
			})
		})
	}
	return Type(Array{
		elem_type: ret_type
	})
}

fn (tc &TypeChecker) fixed_array_dynamic_receiver_call_info(base_type Type, arr ArrayFixed, method string) ?CallInfo {
	array_type := Array{
		elem_type: arr.elem_type
	}
	mut candidates := []string{}
	push_receiver_method_candidate(mut candidates,
		'${resolve_type_name_for_method(Type(array_type))}.${method}')
	append_array_receiver_method_candidates(mut candidates, array_type, method, tc.cur_module)
	for mname in candidates {
		if mname !in tc.fn_ret_types {
			continue
		}
		info := tc.call_info(mname, true)
		mut params := info.params.clone()
		if params.len > 0 {
			params[0] = base_type
		}
		return CallInfo{
			name:                 info.name
			params:               params
			return_type:          info.return_type
			has_receiver:         info.has_receiver
			is_variadic:          info.is_variadic
			is_c_variadic:        info.is_c_variadic
			params_known:         info.params_known
			has_implicit_veb_ctx: info.has_implicit_veb_ctx
		}
	}
	return none
}

fn (tc &TypeChecker) fixed_array_pointers_call_info(base_type Type) ?CallInfo {
	mname := 'array.pointers'
	return_type := tc.fn_ret_types[mname] or { return none }
	return CallInfo{
		name:         mname
		params:       tarr1(base_type)
		return_type:  return_type
		has_receiver: true
		params_known: true
	}
}

fn (tc &TypeChecker) expr_can_take_address(id flat.NodeId) bool {
	if int(id) < 0 {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			return true
		}
		.index {
			if node.value == 'range' {
				return false
			}
			if node.children_count > 0 {
				base_id := tc.a.child(&node, 0)
				base_type0 := unwrap_pointer(tc.resolve_type(base_id))
				mut base_type := base_type0
				if base_type0 is Alias {
					base_type = base_type0.base_type
				}
				if base_type is Map {
					return false
				}
			}
			return node.children_count > 0 && tc.expr_can_take_address(tc.a.child(&node, 0))
		}
		.selector {
			if node.children_count == 0 {
				return false
			}
			if tc.enum_selector_type(&node) != none {
				return false
			}
			return tc.expr_can_take_address(tc.a.child(&node, 0))
		}
		.prefix {
			return node.op == .mul
		}
		.paren {
			if node.children_count == 0 {
				return false
			}
			return tc.expr_can_take_address(tc.a.child(&node, 0))
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) flag_enum_mutating_receiver_method(fn_node flat.Node, recv_type Type, info CallInfo) ?string {
	if !info.has_receiver || fn_node.kind != .selector
		|| fn_node.value !in ['set', 'clear', 'toggle', 'set_all', 'clear_all'] {
		return none
	}
	clean := unwrap_pointer(recv_type)
	if clean is Enum && (clean.is_flag || clean.name in tc.flag_enums) {
		return fn_node.value
	}
	return none
}

fn (tc &TypeChecker) flag_enum_receiver_is_mutable_lvalue(recv_id flat.NodeId) bool {
	if !tc.expr_can_take_address(recv_id) {
		return false
	}
	return tc.expr_root_is_mutable_lvalue(recv_id)
}

fn (tc &TypeChecker) mut_receiver_expr_is_mutable_lvalue(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			// A pointer-valued binding can mutate its pointee without mutating the
			// binding itself, just like a pointer-valued selector or call result.
			if tc.type_is_pointer_receiver(tc.cached_expr_type(id) or { tc.resolve_type(id) }) {
				return true
			}
			return tc.ident_is_mutable_lvalue(node.value)
		}
		.index, .selector {
			// Mutating the pointee of a pointer-valued field or element does not
			// mutate the binding that stores the pointer. This is common for
			// application state such as `app.window.refresh()`.
			if tc.type_is_pointer_receiver(tc.cached_expr_type(id) or { tc.resolve_type(id) }) {
				return true
			}
			return node.children_count > 0
				&& tc.mut_receiver_expr_is_mutable_lvalue(tc.a.child(&node, 0))
		}
		.paren {
			return node.children_count > 0
				&& tc.mut_receiver_expr_is_mutable_lvalue(tc.a.child(&node, 0))
		}
		.or_expr {
			// Optional/result postfix propagation (`value?.method()` / `value!.method()`)
			// borrows the payload stored in the original lvalue.
			return node.value in ['?', '!'] && node.children_count > 0
				&& tc.mut_receiver_expr_is_mutable_lvalue(tc.a.child(&node, 0))
		}
		.call {
			// A call that returns a pointer yields mutable pointee storage even though
			// the pointer expression itself is not an lvalue. This permits fluent
			// mutable methods that return `&Receiver`.
			return tc.type_is_pointer_receiver(tc.cached_expr_type(id) or { tc.resolve_type(id) })
		}
		.prefix {
			if node.op in [.amp, .mul] {
				return node.children_count > 0
					&& tc.mut_receiver_expr_is_mutable_lvalue(tc.a.child(&node, 0))
			}
			return false
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) expr_root_is_mutable_lvalue(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			return tc.ident_is_mutable_lvalue(node.value)
		}
		.index, .selector, .paren {
			return node.children_count > 0 && tc.expr_root_is_mutable_lvalue(tc.a.child(&node, 0))
		}
		.prefix {
			return node.op == .mul
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) expr_root_constant_name(id flat.NodeId) ?string {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return none
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			qname := tc.qualify_name(node.value)
			if qname in tc.const_types || node.value in tc.const_types {
				return node.value
			}
		}
		.index, .selector, .paren {
			if node.children_count > 0 {
				return tc.expr_root_constant_name(tc.a.child(&node, 0))
			}
		}
		else {}
	}
	return none
}

fn (tc &TypeChecker) ident_is_mutable_lvalue(name string) bool {
	if name.len == 0 {
		return false
	}
	if tc.current_binding_is_shared(name) && tc.current_shared_lock_mode(name) == `w` {
		return true
	}
	if tc.mut_param_binding_matches_lvalue(name) {
		return true
	}
	if tc.cur_scope == unsafe { nil } {
		return false
	}
	if owner := tc.fn_context.mut_local_owners[name] {
		if tc.cur_scope.nearest_binding_owned_by(name, owner) {
			return true
		}
	}
	// Globals are mutable storage. Respect a nearer local binding first so an
	// immutable local that shadows a global is still rejected.
	if owner := tc.cur_scope.lookup_owner(name) {
		return name in tc.global_names && tc.binding_owner_is_global(owner)
	}
	qname := tc.qualify_name(name)
	if qname != name {
		if owner := tc.cur_scope.lookup_owner(qname) {
			return qname in tc.global_names && tc.binding_owner_is_global(owner)
		}
	}
	return false
}

fn (tc &TypeChecker) ident_is_explicitly_mutable_lvalue(name string) bool {
	if name.len == 0 {
		return false
	}
	if tc.current_binding_is_shared(name) && tc.current_shared_lock_mode(name) == `w` {
		return true
	}
	return tc.mut_param_binding_matches_lvalue(name)
}

fn (tc &TypeChecker) current_shared_lock_mode(name string) u8 {
	modes := tc.fn_context.locked_shared_modes[name] or { return 0 }
	return if modes.len > 0 { modes.last() } else { u8(0) }
}

fn (tc &TypeChecker) binding_owner_is_global(owner ScopeBindingOwner) bool {
	// A parallel checker adds its private file scope in front of the collected
	// program scope, so globals can live in any ancestor of `file_scope`.
	mut scope := unsafe { &Scope(tc.file_scope) }
	for scope != unsafe { nil } {
		if owner.belongs_to_scope(scope) {
			return true
		}
		scope = scope.parent
	}
	return false
}

fn (tc &TypeChecker) ident_is_global_binding(name string) bool {
	if name.len == 0 || tc.cur_scope == unsafe { nil } || tc.file_scope == unsafe { nil } {
		return false
	}
	if owner := tc.cur_scope.lookup_owner(name) {
		return name in tc.global_names && tc.binding_owner_is_file_scope(owner)
	}
	qname := tc.qualify_name(name)
	if qname != name {
		if owner := tc.cur_scope.lookup_owner(qname) {
			return qname in tc.global_names && tc.binding_owner_is_file_scope(owner)
		}
	}
	return false
}

fn (tc &TypeChecker) expr_root_is_global_binding(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			return tc.ident_is_global_binding(node.value)
		}
		.index, .selector, .paren {
			return node.children_count > 0 && tc.expr_root_is_global_binding(tc.a.child(&node, 0))
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) binding_owner_is_file_scope(owner ScopeBindingOwner) bool {
	// Parallel checker views put a private file scope in front of the collected
	// program scope, so globals can belong to either that scope or an ancestor.
	mut scope := unsafe { &Scope(tc.file_scope) }
	for scope != unsafe { nil } {
		if owner.belongs_to_scope(scope) {
			return true
		}
		scope = scope.parent
	}
	return false
}

enum ReceiverMutationVisibility {
	none
	direct
	private_path
	public_path
}

struct VisibleMutationFnDecl {
	idx int
	mod string
}

fn receiver_mutation_is_visible(vis ReceiverMutationVisibility) bool {
	return vis in [.direct, .public_path]
}

fn visible_mutation_receiver_type_name(typ string) string {
	mut clean := trimmed_space(typ)
	for clean.starts_with('&') {
		clean = trimmed_space(clean[1..])
	}
	for prefix in ['mut ', 'shared '] {
		if clean.starts_with(prefix) {
			clean = trimmed_space(clean[prefix.len..])
		}
	}
	return strip_generic_args_name(clean)
}

fn visible_mutation_fn_names_match(actual string, declared string) bool {
	if actual == declared {
		return true
	}
	if actual.all_after_last('.') != declared.all_after_last('.') {
		return false
	}
	actual_receiver := actual.all_before_last('.')
	declared_receiver := declared.all_before_last('.')
	return strip_generic_args_name(actual_receiver) == strip_generic_args_name(declared_receiver)
}

fn visible_mutation_fn_lookup_name(name string) string {
	dot := name.last_index_u8(`.`)
	if dot <= 0 {
		return name
	}
	receiver := name[..dot]
	clean_receiver := strip_generic_args_name(receiver)
	if clean_receiver == receiver {
		return name
	}
	return clean_receiver + name[dot..]
}

fn (tc &TypeChecker) cache_visible_mutation_fn_decl(key string, decl VisibleMutationFnDecl) {
	if isnil(tc.visible_mutation_cache) || key.len == 0 {
		return
	}
	mut cache := tc.visible_mutation_cache
	if key !in cache.decls {
		cache.decls[key] = decl
	}
}

fn (tc &TypeChecker) register_visible_mutation_fn_decl(idx int, module_name string, qname string, source_name string) {
	decl := VisibleMutationFnDecl{
		idx: idx
		mod: module_name
	}
	normalized_qname := visible_mutation_fn_lookup_name(qname)
	normalized_source_name := visible_mutation_fn_lookup_name(source_name)
	c_qname := tc.cached_c_name(qname)
	c_source_name := tc.cached_c_name(source_name)
	for candidate in [normalized_qname, normalized_source_name, c_qname, c_source_name] {
		tc.cache_visible_mutation_fn_decl('\x01${candidate}', decl)
		tc.cache_visible_mutation_fn_decl('${module_name}\x01${candidate}', decl)
	}
}

fn (tc &TypeChecker) visible_mutation_fn_decl(name string, fallback_mod string) ?VisibleMutationFnDecl {
	cache_key := '${fallback_mod}\x01${visible_mutation_fn_lookup_name(name)}'
	if !isnil(tc.visible_mutation_cache) {
		cache := tc.visible_mutation_cache
		if decl := cache.decls[cache_key] {
			return decl
		}
		if cache.decl_misses[cache_key] {
			return none
		}
		if cache.decl_index_ready {
			return none
		}
	}
	mut cur_mod := ''
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		match node.kind {
			.file {
				cur_mod = tc.file_modules[node.value] or { '' }
			}
			.module_decl {
				cur_mod = node.value
			}
			.fn_decl {
				if fallback_mod.len > 0 && cur_mod != fallback_mod {
					continue
				}
				qname := checker_qualified_fn_name(cur_mod, node.value)
				if visible_mutation_fn_names_match(name, qname)
					|| visible_mutation_fn_names_match(name, node.value)
					|| tc.cached_c_name(qname) == name || tc.cached_c_name(node.value) == name {
					decl := VisibleMutationFnDecl{
						idx: i
						mod: cur_mod
					}
					if !isnil(tc.visible_mutation_cache) {
						mut cache := tc.visible_mutation_cache
						cache.decls[cache_key] = decl
					}
					return decl
				}
			}
			else {}
		}
	}
	if !isnil(tc.visible_mutation_cache) {
		mut cache := tc.visible_mutation_cache
		cache.decl_misses[cache_key] = true
	}
	return none
}

fn (tc &TypeChecker) visible_mutation_fn_param(decl VisibleMutationFnDecl, param_idx int) ?flat.Node {
	if decl.idx < 0 || decl.idx >= tc.a.nodes.len || param_idx < 0 {
		return none
	}
	fn_node := tc.a.nodes[decl.idx]
	mut idx := 0
	for i in 0 .. fn_node.children_count {
		child := tc.a.child_node(&fn_node, i)
		if child.kind != .param {
			break
		}
		if idx == param_idx {
			return *child
		}
		idx++
	}
	return none
}

fn (tc &TypeChecker) visible_call_param(info CallInfo, param_idx int) ?flat.Node {
	decl_module := tc.fn_type_modules[info.name] or { '' }
	decl := tc.visible_mutation_fn_decl(info.name, decl_module) or { return none }
	mut source_param_idx := param_idx
	if info.has_implicit_veb_ctx {
		fn_node := tc.a.nodes[decl.idx]
		ctx_idx := tc.fn_implicit_veb_ctx_insert_index(fn_node)
		if source_param_idx == ctx_idx {
			return none
		}
		if source_param_idx > ctx_idx {
			source_param_idx--
		}
	}
	return tc.visible_mutation_fn_param(decl, source_param_idx)
}

fn (tc &TypeChecker) call_param_requires_mut_pointer_slot(info CallInfo, param_idx int) bool {
	param := tc.visible_call_param(info, param_idx) or { return false }
	return param.is_mut && param.op == .amp && param.typ.starts_with('&')
}

fn (tc &TypeChecker) explicit_generic_source_param_is_mut(call flat.Node, info CallInfo, param_idx int) bool {
	mut name := ''
	if call.children_count > 0 {
		callee := tc.a.child_node(&call, 0)
		if callee.kind == .index && callee.children_count > 0 {
			base := tc.a.child_node(callee, 0)
			name = tc.generic_call_base_name(*base) or { '' }
		}
	}
	if name.len == 0 && info.name.contains('_T_') {
		name = info.name.all_before('_T_')
	}
	if name.len == 0 {
		return false
	}
	decl_module := tc.fn_type_modules[name] or { tc.cur_module }
	decl := tc.visible_mutation_fn_decl(name, decl_module) or { return false }
	param := tc.visible_mutation_fn_param(decl, param_idx) or { return false }
	return param.is_mut
}

fn (tc &TypeChecker) call_param_is_mut(info CallInfo, param_idx int) bool {
	if info.name.starts_with('chan ') && info.name.ends_with('.try_pop') && info.has_receiver
		&& param_idx == 1 {
		return true
	}
	if param := tc.visible_call_param(info, param_idx) {
		return param.is_mut
	}
	for index in tc.top_level_idx {
		node := tc.a.node(flat.NodeId(index))
		if node.kind != .fn_decl
			|| (node.value != info.name && !info.name.ends_with('.${node.value}')) {
			continue
		}
		mut current := 0
		for child_index in 0 .. node.children_count {
			param := tc.a.child_node(node, child_index)
			if param.kind != .param {
				continue
			}
			if current == param_idx {
				return param.is_mut
			}
			current++
		}
	}
	return false
}

fn (tc &TypeChecker) call_field_param_is_mut(node flat.Node, param_idx int) bool {
	if node.children_count == 0 {
		return false
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind != .selector || callee.children_count == 0 {
		return false
	}
	receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(callee, 0)))
	if receiver_type !is Struct {
		return false
	}
	field_type := tc.struct_field_type(receiver_type.name(), callee.value) or { return false }
	raw_fn_type := if field_type is Alias {
		tc.source_fn_alias_type_text(field_type.name) or { '' }
	} else {
		field_type.name()
	}
	if raw_fn_type.len == 0 {
		return false
	}
	params, _ := fn_diagnostic_type_parts(raw_fn_type)
	return param_idx >= 0 && param_idx < params.len && params[param_idx].is_mut
}

fn (tc &TypeChecker) mut_pointer_slot_arg_compatible(actual Type, expected Type) bool {
	if tc.type_compatible(actual, expected) {
		return true
	}
	if expected is Pointer {
		if unalias_type(actual) is Primitive && tc.type_compatible(actual, expected.base_type) {
			return true
		}
		if unalias_type(actual) is Primitive && expected.base_type is Pointer
			&& tc.type_compatible(actual, expected.base_type.base_type) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) visible_mutation_struct_field_is_public(receiver_type string, field_name string, decl_mod string) ?bool {
	type_name := visible_mutation_receiver_type_name(receiver_type)
	short_name := type_name.all_after_last('.')
	mut cur_mod := ''
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		match node.kind {
			.file {
				cur_mod = tc.file_modules[node.value] or { '' }
			}
			.module_decl {
				cur_mod = node.value
			}
			.struct_decl {
				if decl_mod.len > 0 && cur_mod != decl_mod {
					continue
				}
				qname := if cur_mod in ['', 'main', 'builtin'] {
					node.value
				} else {
					'${cur_mod}.${node.value}'
				}
				if node.value != short_name && qname != type_name {
					continue
				}
				for j in 0 .. node.children_count {
					field := tc.a.child_node(&node, j)
					if field.kind != .field_decl || field.value != field_name {
						continue
					}
					meta := field.generic_params()
					return meta.len > 0 && meta[0].contains('p')
				}
				return none
			}
			else {}
		}
	}
	return none
}

fn (tc &TypeChecker) receiver_expr_mutation_visibility(expr_id flat.NodeId, root_name string, receiver_type string, decl_mod string) ReceiverMutationVisibility {
	if int(expr_id) < 0 || int(expr_id) >= tc.a.nodes.len {
		return .none
	}
	node := tc.a.nodes[int(expr_id)]
	match node.kind {
		.ident {
			return if node.value == root_name { .direct } else { .none }
		}
		.paren, .prefix, .postfix, .cast_expr, .as_expr, .expr_stmt {
			if node.children_count > 0 {
				return tc.receiver_expr_mutation_visibility(tc.a.child(&node, 0), root_name,
					receiver_type, decl_mod)
			}
		}
		.selector {
			if node.children_count == 0 {
				return .none
			}
			mut parent_id := tc.a.child(&node, 0)
			for int(parent_id) >= 0 && int(parent_id) < tc.a.nodes.len {
				parent := tc.a.nodes[int(parent_id)]
				if parent.kind != .paren || parent.children_count == 0 {
					break
				}
				parent_id = tc.a.child(&parent, 0)
			}
			if int(parent_id) >= 0 && int(parent_id) < tc.a.nodes.len {
				parent := tc.a.nodes[int(parent_id)]
				if parent.kind == .ident && parent.value == root_name {
					is_pub := tc.visible_mutation_struct_field_is_public(receiver_type, node.value,
						decl_mod) or { true }
					return if is_pub { .public_path } else { .private_path }
				}
			}
			return tc.receiver_expr_mutation_visibility(parent_id, root_name, receiver_type,
				decl_mod)
		}
		.index {
			if node.children_count > 0 {
				return tc.receiver_expr_mutation_visibility(tc.a.child(&node, 0), root_name,
					receiver_type, decl_mod)
			}
		}
		.call {
			if node.children_count > 0 {
				mut fn_node := tc.a.child_node(&node, 0)
				if fn_node.kind == .index && fn_node.children_count > 0 {
					fn_node = tc.a.child_node(fn_node, 0)
				}
				if fn_node.kind == .selector && fn_node.children_count > 0 {
					return tc.receiver_expr_mutation_visibility(tc.a.child(fn_node, 0), root_name,
						receiver_type, decl_mod)
				}
			}
		}
		else {}
	}
	return .none
}

fn (tc &TypeChecker) visible_mutation_call_name(call_id flat.NodeId, call flat.Node, root_type string, decl_mod string) string {
	if name := tc.resolved_call_name(call_id) {
		return name
	}
	if call.children_count == 0 {
		return ''
	}
	mut fn_node := tc.a.child_node(&call, 0)
	if fn_node.kind == .index && fn_node.children_count > 0 {
		fn_node = tc.a.child_node(fn_node, 0)
	}
	if fn_node.kind == .ident {
		return checker_qualified_fn_name(decl_mod, fn_node.value)
	}
	if fn_node.kind == .selector && fn_node.children_count > 0 {
		base := tc.a.child_node(fn_node, 0)
		if base.kind == .ident && base.value.len > 0 && base.value[0] >= `A` && base.value[0] <= `Z` {
			return checker_qualified_fn_name(decl_mod, '${base.value}.${fn_node.value}')
		}
		receiver_name := visible_mutation_receiver_type_name(root_type)
		return checker_qualified_fn_name(decl_mod, '${receiver_name}.${fn_node.value}')
	}
	return ''
}

fn (tc &TypeChecker) call_has_visible_receiver_mutation(call_id flat.NodeId, call flat.Node, root_name string, root_type string, decl_mod string, mut visiting map[u64]bool) bool {
	if call.children_count == 0 {
		return false
	}
	mut fn_node := tc.a.child_node(&call, 0)
	if fn_node.kind == .index && fn_node.children_count > 0 {
		fn_node = tc.a.child_node(fn_node, 0)
	}
	called_name := tc.visible_mutation_call_name(call_id, call, root_type, decl_mod)
	called_mod := tc.fn_type_modules[called_name] or { decl_mod }
	decl := tc.visible_mutation_fn_decl(called_name, called_mod) or {
		if fn_node.kind == .selector && fn_node.children_count > 0 {
			recv_vis := tc.receiver_expr_mutation_visibility(tc.a.child(fn_node, 0), root_name,
				root_type, decl_mod)
			if receiver_mutation_is_visible(recv_vis) && tc.mut_receiver_methods[called_name] {
				return true
			}
		}
		for i in 1 .. call.children_count {
			arg_id := tc.a.child(&call, i)
			arg := tc.a.nodes[int(arg_id)]
			if arg.is_mut
				&& receiver_mutation_is_visible(tc.receiver_expr_mutation_visibility(arg_id, root_name, root_type, decl_mod)) {
				return true
			}
		}
		return false
	}
	mut is_method := false
	mut receiver_param_is_mut := false
	if first_param := tc.visible_mutation_fn_param(decl, 0) {
		is_method = first_param.op == .dot
		receiver_param_is_mut = first_param.is_mut
	}
	mut param_offset := 0
	if is_method {
		param_offset = 1
		if fn_node.kind == .selector && fn_node.children_count > 0 && receiver_param_is_mut {
			recv_vis := tc.receiver_expr_mutation_visibility(tc.a.child(fn_node, 0), root_name,
				root_type, decl_mod)
			match recv_vis {
				.direct {
					if tc.visible_mutation_fn_param_has_visible_mutation(decl, 0, mut visiting) {
						return true
					}
				}
				.public_path {
					return true
				}
				else {}
			}
		}
	}
	for i in 1 .. call.children_count {
		arg_id := tc.a.child(&call, i)
		arg := tc.a.nodes[int(arg_id)]
		if !arg.is_mut {
			continue
		}
		param_idx := i - 1 + param_offset
		param := tc.visible_mutation_fn_param(decl, param_idx) or { continue }
		if !param.is_mut {
			continue
		}
		arg_vis := tc.receiver_expr_mutation_visibility(arg_id, root_name, root_type, decl_mod)
		match arg_vis {
			.direct {
				if tc.visible_mutation_fn_param_has_visible_mutation(decl, param_idx, mut visiting) {
					return true
				}
			}
			.public_path {
				return true
			}
			else {}
		}
	}
	return false
}

fn (tc &TypeChecker) node_has_visible_receiver_mutation(id flat.NodeId, root_name string, root_type string, decl_mod string, mut visiting map[u64]bool) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.fn_decl, .fn_literal {
			return false
		}
		.assign {
			lhs_count_value := node.value.int()
			lhs_count := if lhs_count_value > 0 { lhs_count_value } else { 1 }
			rhs_count := int(node.children_count) - lhs_count
			mut child_offset := 0
			for i in 0 .. lhs_count {
				if child_offset >= int(node.children_count) {
					break
				}
				lhs_id := tc.a.child(&node, child_offset)
				if receiver_mutation_is_visible(tc.receiver_expr_mutation_visibility(lhs_id,
					root_name, root_type, decl_mod))
				{
					return true
				}
				child_offset++
				if i < rhs_count {
					child_offset++
				}
			}
		}
		.selector_assign, .index_assign {
			if node.children_count > 0
				&& receiver_mutation_is_visible(tc.receiver_expr_mutation_visibility(tc.a.child(&node, 0), root_name, root_type, decl_mod)) {
				return true
			}
		}
		.postfix {
			if node.op in [.inc, .dec] && node.children_count > 0
				&& receiver_mutation_is_visible(tc.receiver_expr_mutation_visibility(tc.a.child(&node, 0), root_name, root_type, decl_mod)) {
				return true
			}
		}
		.call {
			if tc.call_has_visible_receiver_mutation(id, node, root_name, root_type, decl_mod, mut
				visiting)
			{
				return true
			}
		}
		else {}
	}
	for i in 0 .. node.children_count {
		if tc.node_has_visible_receiver_mutation(tc.a.child(&node, i), root_name, root_type,
			decl_mod, mut visiting)
		{
			return true
		}
	}
	return false
}

fn visible_mutation_cache_id(decl VisibleMutationFnDecl, param_idx int) u64 {
	return u64(u32(decl.idx)) << 32 | u64(u32(param_idx))
}

fn (tc &TypeChecker) cached_visible_mutation_result(key u64) ?bool {
	if !isnil(tc.visible_mutation_cache) {
		cache := tc.visible_mutation_cache
		if key in cache.results {
			return cache.results[key]
		}
	}
	return none
}

fn (tc &TypeChecker) visible_mutation_fn_param_has_visible_mutation(decl VisibleMutationFnDecl, param_idx int, mut visiting map[u64]bool) bool {
	cache_id := visible_mutation_cache_id(decl, param_idx)
	if cached := tc.cached_visible_mutation_result(cache_id) {
		return cached
	}
	if cache_id in visiting {
		return true
	}
	param := tc.visible_mutation_fn_param(decl, param_idx) or {
		tc.cache_visible_mutation_result(cache_id, true)
		return true
	}
	if !param.is_mut {
		tc.cache_visible_mutation_result(cache_id, false)
		return false
	}
	fn_node := tc.a.nodes[decl.idx]
	mut param_count := 0
	for i in 0 .. fn_node.children_count {
		if tc.a.child_node(&fn_node, i).kind != .param {
			break
		}
		param_count++
	}
	if param_count == int(fn_node.children_count) {
		// A source method with `{}` has no visible mutation. Header declarations use
		// `is_mut` as the parser's cached-body marker and remain conservative.
		tc.cache_visible_mutation_result(cache_id, fn_node.is_mut)
		return fn_node.is_mut
	}
	visiting[cache_id] = true
	mut result := false
	for i in param_count .. fn_node.children_count {
		if tc.node_has_visible_receiver_mutation(tc.a.child(&fn_node, i), param.value, param.typ,
			decl.mod, mut visiting)
		{
			result = true
			break
		}
	}
	visiting.delete(cache_id)
	tc.cache_visible_mutation_result(cache_id, result)
	return result
}

fn (tc &TypeChecker) cache_visible_mutation_result(key u64, result bool) {
	if !isnil(tc.visible_mutation_cache) {
		mut cache := tc.visible_mutation_cache
		cache.results[key] = result
	}
}

fn (tc &TypeChecker) mut_receiver_call_requires_mutable_lvalue(info CallInfo, recv_id flat.NodeId) bool {
	if tc.expr_is_shared_arg(recv_id) {
		return false
	}
	if tc.expr_root_is_global_binding(recv_id) {
		return false
	}
	method_module := tc.fn_type_modules[info.name] or { '' }
	if method_module.len > 0 && method_module != tc.cur_module {
		// Match V's private-mutability rule: an immutable binding is accepted across a
		// module boundary only when the method cannot mutate caller-visible state.
		decl := tc.visible_mutation_fn_decl(info.name, method_module) or { return true }
		cache_id := visible_mutation_cache_id(decl, 0)
		if cached := tc.cached_visible_mutation_result(cache_id) {
			return cached
		}
		mut visiting := map[u64]bool{}
		return tc.visible_mutation_fn_param_has_visible_mutation(decl, 0, mut visiting)
	}
	return true
}

fn (tc &TypeChecker) map_builtin_call_info(base_type Type, m Map, method string, mname string) ?CallInfo {
	if !checker_is_raw_collection_method_name(mname, 'map.') {
		return none
	}
	params := match method {
		'delete' {
			tarr2(base_type, m.key_type)
		}
		'clear', 'free', 'keys', 'values' {
			tarr1(base_type)
		}
		'move' {
			tarr1(base_type)
		}
		'reserve' {
			tarr2(base_type, Type(u32_))
		}
		else {
			return none
		}
	}

	return_type := match method {
		'keys' {
			Type(Array{
				elem_type: m.key_type
			})
		}
		'values' {
			Type(Array{
				elem_type: m.value_type
			})
		}
		'move' {
			Type(m)
		}
		else {
			Type(void_)
		}
	}

	return CallInfo{
		name:         mname
		params:       params
		return_type:  return_type
		has_receiver: true
		params_known: true
	}
}

fn checker_is_raw_collection_method_name(name string, prefix string) bool {
	if !name.starts_with(prefix) {
		return false
	}
	rest := name[prefix.len..]
	return rest.len > 0 && !rest.contains('.')
}

// is_print_style_fn_name reports whether is print style fn name applies in types.
fn is_print_style_fn_name(name string) bool {
	mut start := 0
	mut len := name.len
	if len > 8 {
		if len < 13 || len > 16 || !has_builtin_dot_prefix(name) {
			return false
		}
		start = 'builtin.'.len
		len -= start
	}
	return is_short_print_style_fn_name(name, start, len)
}

fn has_builtin_dot_prefix(name string) bool {
	return name[0] == `b` && name[1] == `u` && name[2] == `i` && name[3] == `l` && name[4] == `t`
		&& name[5] == `i` && name[6] == `n` && name[7] == `.`
}

fn is_short_print_style_fn_name(name string, start int, len int) bool {
	return match len {
		5 {
			name[start] == `p` && name[start + 1] == `r` && name[start + 2] == `i`
				&& name[start + 3] == `n` && name[start + 4] == `t`
		}
		6 {
			name[start] == `e` && name[start + 1] == `p` && name[start + 2] == `r`
				&& name[start + 3] == `i` && name[start + 4] == `n` && name[start + 5] == `t`
		}
		7 {
			name[start] == `p` && name[start + 1] == `r` && name[start + 2] == `i`
				&& name[start + 3] == `n` && name[start + 4] == `t` && name[start + 5] == `l`
				&& name[start + 6] == `n`
		}
		8 {
			name[start] == `e` && name[start + 1] == `p` && name[start + 2] == `r`
				&& name[start + 3] == `i` && name[start + 4] == `n` && name[start + 5] == `t`
				&& name[start + 6] == `l` && name[start + 7] == `n`
		}
		else {
			false
		}
	}
}

fn is_builtin_void_call_name(name string) bool {
	if is_short_print_style_fn_name(name, 0, name.len) {
		return true
	}
	return name.len == 5 && name[0] == `p` && name[1] == `a` && name[2] == `n` && name[3] == `i`
		&& name[4] == `c`
}

// print_style_param_accepts_string updates print style param accepts string state for types.
fn print_style_param_accepts_string(typ Type) bool {
	mut clean := typ
	for _ in 0 .. 8 {
		if clean is Alias {
			clean = clean.base_type
			continue
		}
		break
	}
	return clean is String
}

// array_insert_prepend_many_arg_compatible reports whether an insert/prepend
// value argument is a many-element operand for the receiver array.
fn (tc &TypeChecker) array_insert_prepend_many_arg_compatible(node flat.Node, info CallInfo, param_idx int, actual Type) bool {
	many_param_idx := array_insert_prepend_many_param_idx(info.name)
	if many_param_idx < 0 || param_idx != many_param_idx {
		return false
	}
	if info.params.len == 0 {
		return false
	}
	mut receiver_type := info.params[0]
	if node.children_count > 0 {
		fn_node := tc.a.child_node(&node, 0)
		if fn_node.kind == .selector && fn_node.children_count > 0 {
			receiver_id := tc.a.child(fn_node, 0)
			receiver_type = tc.cached_expr_type(receiver_id) or { tc.resolve_type(receiver_id) }
		}
	}
	elem_type := array_like_elem_type(unwrap_pointer(receiver_type)) or {
		array_like_elem_type(unwrap_pointer(info.params[0])) or { return false }
	}
	mut clean := actual
	for _ in 0 .. 8 {
		if clean is Alias {
			clean = clean.base_type
			continue
		}
		break
	}
	if clean is Array {
		return tc.receiver_compatible(clean.elem_type, elem_type)
	}
	if clean is ArrayFixed {
		return tc.receiver_compatible(clean.elem_type, elem_type)
	}
	return false
}

fn call_param_is_shared(info CallInfo, param_idx int) bool {
	return param_idx >= 0 && param_idx < info.shared_params.len && info.shared_params[param_idx]
}

fn (tc &TypeChecker) expr_is_shared_arg(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .paren && node.children_count > 0 {
		return tc.expr_is_shared_arg(tc.a.child(&node, 0))
	}
	if node.kind == .prefix && node.value == 'shared' && node.children_count > 0 {
		return tc.expr_is_shared_arg(tc.a.child(&node, 0))
	}
	if node.kind == .selector && node.children_count > 0 {
		return tc.selector_is_shared_arg(node)
	}
	if node.kind != .ident || node.value.len == 0 {
		return false
	}
	return tc.current_binding_is_shared(node.value)
}

fn (tc &TypeChecker) unlocked_shared_access(id flat.NodeId) ?SharedAccessDiagnostic {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	match node.kind {
		.ident {
			if tc.current_binding_is_shared(node.value)
				&& tc.current_shared_lock_mode(node.value) == 0 {
				return SharedAccessDiagnostic{
					name: node.value
					pos:  tc.node_value_diagnostic_pos(id)
				}
			}
		}
		.paren, .index {
			if node.children_count > 0 {
				return tc.unlocked_shared_access(tc.a.child(node, 0))
			}
		}
		.selector {
			if node.children_count == 0 {
				return none
			}
			if access := tc.unlocked_shared_access(tc.a.child(node, 0)) {
				return access
			}
			if tc.selector_is_shared_arg(node) {
				return SharedAccessDiagnostic{
					name: tc.source_text_for_node(id)
					pos:  tc.selector_field_diagnostic_pos(id, node.value)
				}
			}
		}
		else {}
	}
	return none
}

fn (tc &TypeChecker) expr_is_explicit_shared_arg(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .paren && node.children_count > 0 {
		return tc.expr_is_explicit_shared_arg(tc.a.child(&node, 0))
	}
	return node.kind == .prefix && node.value == 'shared' && node.children_count > 0
}

fn (tc &TypeChecker) selector_is_shared_arg(node flat.Node) bool {
	if node.children_count == 0 || node.value.len == 0 {
		return false
	}
	base_id := tc.a.child(&node, 0)
	base_type := tc.smartcast_type(base_id) or {
		tc.cached_expr_type(base_id) or { tc.resolve_type(base_id) }
	}
	clean := unalias_and_unwrap_pointer_type(base_type)
	if clean is Struct {
		return tc.struct_field_is_shared(clean.name, node.value)
	}
	return false
}

fn (tc &TypeChecker) struct_field_is_shared(struct_name string, field_name string) bool {
	if struct_name.len == 0 || field_name.len == 0 {
		return false
	}
	mut candidates := []string{cap: 4}
	candidates << struct_name
	base, _, is_generic := generic_type_application_parts(struct_name)
	if is_generic {
		candidates << base
	}
	if struct_name.contains('.') {
		candidates << struct_name.all_after_last('.')
	} else {
		qname := tc.qualify_name(struct_name)
		if qname != struct_name {
			candidates << qname
		}
	}
	for candidate in candidates {
		if tc.struct_shared_fields[struct_field_c_abi_key(candidate, field_name)] {
			return true
		}
	}
	return false
}

// check_call_arg_types validates check call arg types state for types.
fn (mut tc TypeChecker) check_call_arg_types(id flat.NodeId, node flat.Node, info0 CallInfo) {
	info := tc.specialized_plain_generic_call_info(node, info0)
	if node.children_count == 0 {
		return
	}
	if tc.check_builtin_map_call_args(id, node, info) {
		return
	}
	if is_map_keys_values_call_name(info.name) {
		for i in 1 .. node.children_count {
			tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
		}
		arg_count := node.children_count - 1
		if arg_count != 0 && tc.should_diagnose(id) {
			tc.record_error(.call_arg_mismatch,
				'argument count mismatch for `${tc.call_display_name(node)}`: expected 0, got ${arg_count}',
				id)
		}
		return
	}
	if !info.params_known {
		dsl_name := tc.unresolved_array_dsl_call_name(node)
		if dsl_name.len > 0 {
			tc.push_array_dsl_scope(node, dsl_name)
		}
		for i in 1 .. node.children_count {
			arg_id := tc.call_arg_value(tc.a.child(&node, i))
			tc.check_node(arg_id)
			if tc.resolve_type(arg_id) is Void {
				tc.record_error(.call_arg_mismatch,
					'`${tc.source_text_for_node(arg_id)}` (no value) used as value in argument ${i} to `${tc.call_display_name(node)}`',
					arg_id)
			}
		}
		if dsl_name.len > 0 {
			tc.pop_scope()
		}
		return
	}
	if tc.check_builtin_array_call_args(id, node, info) {
		return
	}
	// `@[params]` struct args: trailing `key: value` args collapse into one struct argument.
	// field_init args only appear for this syntax, so they are a reliable signal.
	mut field_init_args := 0
	for i in 1 .. node.children_count {
		if tc.a.child_node(&node, i).kind == .field_init {
			field_init_args++
		}
	}
	collapsed := if field_init_args > 0 { 1 } else { 0 }
	recv_extra := if info.has_receiver { 1 } else { 0 }
	mut actual_count := node.children_count - 1 - info.arg_offset - field_init_args + collapsed +
		recv_extra
	mut expanded_multi_return_arg := false
	mut expanded_overflow_arg := flat.NodeId(-1)
	mut logical_arg_count := recv_extra
	for i in 1 + info.arg_offset .. node.children_count {
		arg_id := tc.call_arg_value(tc.a.child(&node, i))
		arg_type := tc.cached_expr_type(arg_id) or { tc.resolve_type(arg_id) }
		logical_arg_count++
		arg := tc.a.node(arg_id)
		if !info.is_variadic && arg.kind == .call && arg_type is MultiReturn
			&& !is_print_style_fn_name(info.name) {
			actual_count += arg_type.types.len - 1
			logical_arg_count += arg_type.types.len - 1
			expanded_multi_return_arg = true
		}
		if int(expanded_overflow_arg) < 0 && logical_arg_count > info.params.len {
			expanded_overflow_arg = arg_id
		}
	}
	// A hidden veb `Context` parameter may be supplied implicitly from the
	// enclosing handler instead of by the caller, so accept argument counts both
	// with the ctx (route dispatch) and without it (handler delegation).
	ctx_count := if info.has_implicit_veb_ctx { 1 } else { 0 }
	ctx_omitted := ctx_count > 0 && actual_count < info.params.len
	if field_init_args > 0 && tc.should_diagnose(id) {
		// Trailing `key: value` args collapse into one struct argument; reject
		// them against a parameter that cannot take a struct literal (e.g. a
		// non-variadic `[]Point`), which cgen would otherwise zero-initialize.
		mut first_field := -1
		for i in 1 + info.arg_offset .. node.children_count {
			if tc.a.child_node(&node, i).kind == .field_init {
				first_field = i
				break
			}
		}
		if first_field >= 0 {
			arg_shift := if ctx_omitted { ctx_count } else { 0 }
			param_idx := first_field - 1 - info.arg_offset + recv_extra + arg_shift
			if param_idx >= 0 && param_idx < info.params.len {
				is_variadic_slot := info.is_variadic && param_idx == info.params.len - 1
				mut target := info.params[param_idx]
				if is_variadic_slot {
					if target is Array {
						target = target.elem_type
					}
				}
				clean_target := if target is Alias { target.base_type } else { target }
				if clean_target is Interface {
					first_field_node := tc.a.child_node(&node, first_field)
					tc.record_error_at(.assignment_mismatch,
						'cannot instantiate interface `${clean_target.name.all_after_last('.')}`', tc.a.child(&node,
						first_field), first_field_node.pos)
					return
				}
				if clean_target is Array || clean_target is ArrayFixed || clean_target is Map
					|| clean_target is String || clean_target is Primitive {
					tc.record_error(.call_arg_mismatch,
						'cannot use `key: value` arguments as `${info.params[param_idx].name()}` in call to `${tc.call_display_name(node)}`',
						id)
				}
			}
		}
	}
	min_count := tc.min_required_arg_count(info) - ctx_count
	if info.is_variadic {
		for i in 1 + info.arg_offset .. node.children_count - 1 {
			arg_id := tc.call_arg_value(tc.a.child(&node, i))
			if spread_id := tc.spread_arg_child(arg_id) {
				spread_pos := tc.a.node(spread_id).pos
				tc.record_error_at(.call_arg_mismatch,
					'when forwarding a variadic variable, it must be the final argument', arg_id, token.new_span(spread_pos.id, int_max(0,
					spread_pos.offset - 3), spread_pos.end))
				return
			}
		}
		variadic_param_idx := info.params.len - 1
		for i in 1 + info.arg_offset .. node.children_count {
			arg_id := tc.call_arg_value(tc.a.child(&node, i))
			logical_idx := i - 1 - info.arg_offset + recv_extra
			if logical_idx > variadic_param_idx {
				if _ := tc.spread_arg_child(arg_id) {
					tc.record_error_at(.call_arg_mismatch,
						'too many arguments in call to `${tc.call_display_name(node)}`', id,
						node.pos)
					return
				}
			}
		}
	}
	if !info.is_variadic {
		mut seen_spread := false
		for i in 1 + info.arg_offset .. node.children_count {
			arg_id := tc.call_arg_value(tc.a.child(&node, i))
			if _ := tc.spread_arg_child(arg_id) {
				seen_spread = true
			} else if seen_spread {
				tc.record_error_at(.call_arg_mismatch,
					'cannot have parameter after array decompose', id, node.pos)
				return
			}
		}
		actual_count += tc.nonvariadic_spread_extra_arg_count(node, info, recv_extra)
	}
	if actual_count < min_count || (!info.is_variadic && actual_count > info.params.len) {
		for i in 1 .. node.children_count {
			arg_id := tc.call_arg_value(tc.a.child(&node, i))
			tc.check_node(arg_id)
			if spread_id := tc.spread_arg_value(arg_id) {
				spread_type := tc.resolve_type(spread_id)
				if array_like_elem_type(unwrap_pointer(spread_type)) == none {
					tc.record_error_at(.call_arg_mismatch,
						'decomposition can only be used on arrays', spread_id,
						tc.a.node(spread_id).pos)
				}
			}
		}
		signature_param_count := if info.is_variadic && info.params.len > 0 {
			info.params.len - 1
		} else {
			c_variadic_fixed_param_count(info)
		}
		expected_count := signature_param_count - recv_extra - ctx_count
		found_count := actual_count - recv_extra
		if expanded_multi_return_arg {
			user_arg_count := node.children_count - 1 - info.arg_offset
			if user_arg_count == 1 && found_count > expected_count {
				arg_id := tc.call_arg_value(tc.a.child(&node, 1 + info.arg_offset))
				multi := tc.resolve_type(arg_id)
				if multi is MultiReturn {
					grammar := if expected_count == 1 { 'argument' } else { 'arguments' }
					tc.record_error_at(.call_arg_mismatch,
						'expected ${expected_count} ${grammar}, but got ${found_count} from multi-return ${Type(multi).name()}',
						arg_id, tc.call_argument_diagnostic_pos(arg_id))
					return
				}
			}
			grammar := if expected_count == 1 { 'argument' } else { 'arguments' }
			pos := if int(expanded_overflow_arg) >= 0 {
				tc.call_argument_diagnostic_pos(expanded_overflow_arg)
			} else {
				node.pos
			}
			tc.record_error_with_details_at(.call_arg_mismatch,
				'expected ${expected_count} ${grammar}, but got ${found_count}', id, pos, tc.call_count_mismatch_details(node,
				info0))
			return
		}
		grammar := if expected_count == 1 { 'argument' } else { 'arguments' }
		is_map_delete := info.name in ['map.delete', 'map__delete']
		pos := if is_map_delete {
			callee := tc.a.child_node(&node, 0)
			if callee.kind == .selector {
				tc.method_call_name_pos(node, callee)
			} else {
				node.pos
			}
		} else if found_count > expected_count {
			tc.surplus_call_args_pos(node, expected_count)
		} else {
			callee := tc.a.child_node(&node, 0)
			if callee.kind == .selector {
				tc.method_call_name_pos(node, callee)
			} else {
				node.pos
			}
		}
		details := if is_map_delete {
			[]string{}
		} else {
			tc.call_count_mismatch_details(node, info0)
		}
		tc.record_error_with_details_at(.call_arg_mismatch,
			'expected ${expected_count} ${grammar}, but got ${found_count}', id, pos, details)
		return
	}
	if info.has_receiver && info.params.len > 0 {
		mut fn_node := tc.a.child_node(&node, 0)
		// For an explicit generic method call `recv.method[T](...)`, the call's fn is an
		// `.index` node (`recv.method` indexed by the type args), so its child 0 is the
		// `recv.method` selector — a method value — not the receiver. Descend through the
		// index to the underlying selector so the receiver resolves to `recv`.
		if fn_node.kind == .index && fn_node.children_count > 0 {
			fn_node = tc.a.child_node(fn_node, 0)
		}
		recv_id := tc.a.child(fn_node, 0)
		tc.check_node(recv_id)
		recv_type := tc.smartcast_type(recv_id) or {
			tc.cached_expr_type(recv_id) or { tc.resolve_type(recv_id) }
		}
		receiver_is_shared_param := call_param_is_shared(info, 0)
		if receiver_is_shared_param && tc.lock_depth > 0 {
			tc.record_error_at(.call_arg_mismatch,
				'method with `shared` receiver cannot be called inside `lock`/`rlock` block',
				recv_id, tc.method_call_name_pos(node, fn_node))
		}
		if !receiver_is_shared_param {
			if access := tc.unlocked_shared_access(recv_id) {
				if tc.mut_receiver_methods[info.name] {
					if tc.lock_depth > 0 {
						tc.record_error_at(.call_arg_mismatch,
							'${access.name} must be added to the `lock` list above', recv_id,
							access.pos)
					}
					tc.record_error_at(.call_arg_mismatch,
						'${access.name} is `shared` and must be `lock`ed to be passed as `mut`',
						recv_id, access.pos)
				} else {
					tc.record_error_at(.call_arg_mismatch,
						'`${access.name}` is `shared` and must be `rlock`ed or `lock`ed to be used as non-mut receiver',
						recv_id, access.pos)
					if tc.direct_parent_kind(id) == .decl_assign {
						tc.record_error_at(.assignment_mismatch,
							'`${access.name}` is `shared` and must be `rlock`ed or `lock`ed to be used as non-mut right-hand side of assignment',
							recv_id, access.pos)
					}
				}
			}
		}
		receiver_matches := tc.method_receiver_compatible(recv_type, info.params[0], info.name)
			|| tc.receiver_embeds(recv_type, info.params[0])
		if call_param_is_shared(info, 0) && !tc.expr_is_shared_arg(recv_id) {
			if tc.should_diagnose(id) {
				tc.record_error_at(.call_arg_mismatch,
					'cannot use shared method `${fn_node.value}` as `${tc.source_text_for_node(recv_id)}` is not a shared var',
					recv_id, tc.a.node(recv_id).pos)
			}
		}
		if tc.unsafe_depth == 0 && tc.mut_receiver_methods[info.name]
			&& tc.mut_receiver_call_requires_mutable_lvalue(info, recv_id)
			&& !checker_is_raw_collection_method_name(info.name, 'array.')
			&& !tc.mut_receiver_expr_is_mutable_lvalue(recv_id) && tc.should_diagnose(id) {
			if const_name := tc.expr_root_constant_name(recv_id) {
				tc.record_error(.call_arg_mismatch, 'cannot modify constant `${const_name}`', id)
			} else {
				receiver := tc.a.node(recv_id)
				if receiver.kind == .ident {
					tc.record_error_at(.call_arg_mismatch,
						'`${receiver.value}` is immutable, declare it with `mut` to make it mutable',
						recv_id, tc.node_value_diagnostic_pos(recv_id))
				} else {
					tc.record_error_at(.call_arg_mismatch, 'cannot pass expression as `mut`',
						recv_id, tc.mutable_receiver_expression_pos(recv_id))
				}
			}
		}
		if !receiver_matches {
			tc.type_mismatch(.call_arg_mismatch,
				'cannot use receiver `${recv_type.name()}` as `${info.params[0].name()}`', id)
		}
		if method := tc.flag_enum_mutating_receiver_method(fn_node, recv_type, info) {
			if !tc.flag_enum_receiver_is_mutable_lvalue(recv_id) && tc.should_diagnose(id) {
				tc.record_error(.call_arg_mismatch,
					'flag enum method `${method}` requires a mutable receiver', id)
			}
		}
	}
	mut expanded_arg_offset := 0
	for i in 1 + info.arg_offset .. node.children_count {
		arg_id := tc.call_arg_value(tc.a.child(&node, i))
		// field_init args are fields of the collapsed `@[params]` struct, not positional params
		raw_arg := tc.a.child_node(&node, i)
		if raw_arg.kind == .field_init {
			$if ownership ? {
				tc.ownership_check_node_with_deferred_aggregate_consumption(arg_id)
			} $else {
				tc.check_node(arg_id)
			}
			if tc.unsafe_depth == 0 {
				if owner := tc.params_field_owner(raw_arg.value, info) {
					owner_base := strip_generic_args_name(owner)
					decl_mod := tc.struct_modules[owner_base] or { '' }
					if decl_mod.len > 0 && decl_mod != tc.cur_module {
						is_public := tc.visible_mutation_struct_field_is_public(owner,
							raw_arg.value, decl_mod) or { true }
						if !is_public {
							tc.record_error_at(.unknown_field,
								'cannot access private field `${raw_arg.value}` on `${params_field_owner_display(owner)}`', tc.a.child(&node,
								i), raw_arg.pos)
						}
					}
				}
			}
			if expected := tc.params_field_expected_type(raw_arg.value, info) {
				value_node := tc.a.node(arg_id)
				actual := if value_node.kind == .call {
					tc.direct_call_return_type(value_node) or { tc.resolve_type(arg_id) }
				} else {
					tc.resolve_type(arg_id)
				}
				if !tc.type_compatible(actual, expected) && !tc.type_compatible(expected, actual)
					&& !tc.pointer_value_compatible(actual, expected) {
					expected_name := tc.params_field_diagnostic_type(raw_arg.value, info, expected)
					actual_name := tc.diagnostic_expr_type_name(arg_id, actual)
					tc.record_error_at(.assignment_mismatch,
						'cannot assign to field `${raw_arg.value}`: expected `${expected_name}`, not `${actual_name}`', tc.a.child(&node,
						i), raw_arg.pos)
				}
			}
			continue
		}
		// When the caller omitted the implicit veb `Context` parameter, skip it
		// (it is inserted right after the receiver) while mapping the caller's
		// positional arguments to the callee's params.
		arg_shift := if ctx_omitted { ctx_count } else { 0 }
		param_idx := i - 1 - info.arg_offset + (if info.has_receiver { 1 } else { 0 }) + arg_shift +
			expanded_arg_offset
		check_arg_id := tc.spread_arg_value(arg_id) or { arg_id }
		has_dsl_scope := tc.call_arg_needs_array_dsl_scope(info.name, param_idx)
		if has_dsl_scope {
			tc.push_array_dsl_scope(node, info.name)
		}
		if !info.is_variadic {
			if spread_id := tc.spread_arg_child(arg_id) {
				actual_spread := tc.resolve_type(spread_id)
				elem_type := array_like_elem_type(unwrap_pointer(actual_spread)) or {
					if has_dsl_scope {
						tc.pop_scope()
					}
					tc.type_mismatch(.call_arg_mismatch,
						'cannot spread `${actual_spread.name()}` as arguments to `${tc.call_display_name(node)}`', id)
					continue
				}
				for spread_param_idx in param_idx .. info.params.len {
					expected := info.params[spread_param_idx]
					if !tc.receiver_compatible(elem_type, expected)
						&& !tc.type_compatible(elem_type, expected) {
						tc.record_error_at(.call_arg_mismatch, 'cannot use `${elem_type.name()}` as `${expected.name()}` in argument ${
							spread_param_idx + 1} to `${tc.call_display_name(node)}`', arg_id, token.new_span(tc.a.node(spread_id).pos.id, int_max(0,
							tc.a.node(spread_id).pos.offset - 3), tc.a.node(spread_id).pos.end))
					}
				}
				if has_dsl_scope {
					tc.pop_scope()
				}
				continue
			}
		}
		$if ownership ? {
			tc.ownership_check_node_with_aggregate_consumption_mode(check_arg_id, tc.ownership_should_defer_call_arg_aggregate_consumption(node,
				info, i))
		} $else {
			tc.check_node(check_arg_id)
		}
		multi_arg_type := tc.cached_expr_type(check_arg_id) or { tc.resolve_type(check_arg_id) }
		if !info.is_variadic && !is_print_style_fn_name(info.name) && multi_arg_type is MultiReturn
			&& tc.a.node(check_arg_id).kind != .call {
			expected_count := info.params.len - (if info.has_receiver { 1 } else { 0 })
			tc.record_error_at(.call_arg_mismatch,
				'trying to pass ${multi_arg_type.types.len} argument(s), but function expects ${expected_count} argument(s)',
				id, node.pos)
			if has_dsl_scope {
				tc.pop_scope()
			}
			return
		}
		if !info.is_variadic && tc.a.node(check_arg_id).kind == .call
			&& multi_arg_type is MultiReturn {
			for multi_idx, actual in multi_arg_type.types {
				multi_param_idx := param_idx + multi_idx
				if multi_param_idx >= info.params.len {
					break
				}
				expected := info.params[multi_param_idx]
				if !tc.receiver_compatible(actual, expected)
					&& !tc.type_compatible(actual, expected) {
					argument_number := multi_param_idx + 1 - (if info.has_receiver { 1 } else { 0 })
					tc.record_error_at(.call_arg_mismatch, 'cannot use `${actual.name()}` as `${expected.name()}` in argument ${argument_number} to `${tc.call_argument_target_name(node,
						info)}` from ${Type(multi_arg_type).name()}', check_arg_id,
						tc.call_argument_diagnostic_pos(check_arg_id))
				}
			}
			expanded_arg_offset += multi_arg_type.types.len - 1
			if has_dsl_scope {
				tc.pop_scope()
			}
			continue
		}
		if info.is_c_variadic && param_idx >= c_variadic_fixed_param_count(info) {
			if has_dsl_scope {
				tc.pop_scope()
			}
			continue
		}
		if tc.check_spread_over_fixed_variadic_tail(id, node, info, i, param_idx) {
			if has_dsl_scope {
				tc.pop_scope()
			}
			continue
		}
		if param_idx >= info.params.len {
			if info.is_variadic && info.params.len > 0 {
				variadic_raw := info.params[info.params.len - 1]
				if variadic_raw is Array {
					elem_type := array_elem_type(variadic_raw)
					if variadic_elem_accepts_any(elem_type) && tc.variadic_any_arg_is_scalar(arg_id) {
						if has_dsl_scope {
							tc.pop_scope()
						}
						continue
					}
					actual := tc.resolve_expr(arg_id, elem_type)
					if variadic_elem_accepts_any(elem_type) && !variadic_any_arg_has_value(actual) {
						tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual.name()}` as argument ${
							param_idx + 1} to `${tc.call_display_name(node)}`; expected `${elem_type.name()}`',
							id)
					} else if !tc.receiver_compatible(actual, elem_type)
						&& !tc.type_compatible(actual, elem_type) {
						tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual.name()}` as argument ${
							param_idx + 1} to `${tc.call_display_name(node)}`; expected `${elem_type.name()}`',
							id)
					}
				} else {
					actual := tc.resolve_expr(arg_id, variadic_raw)
					if !tc.receiver_compatible(actual, variadic_raw)
						&& !tc.type_compatible(actual, variadic_raw) {
						tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual.name()}` as argument ${
							param_idx + 1} to `${tc.call_display_name(node)}`; expected `${variadic_raw.name()}`',
							id)
					}
				}
			}
			if has_dsl_scope {
				tc.pop_scope()
			}
			continue
		}
		mut expected := info.params[param_idx]
		if tc.is_zero_literal(arg_id) && is_fn_pointer_type(expected) {
			if has_dsl_scope {
				tc.pop_scope()
			}
			continue
		}
		expected_raw := expected
		if info.is_variadic && param_idx == info.params.len - 1 && expected_raw is Array {
			elem_type := array_elem_type(expected_raw)
			if spread_id := tc.spread_arg_value(arg_id) {
				actual := tc.resolve_type(spread_id)
				spread_pos := tc.a.node(spread_id).pos
				argument_number := param_idx + 1 - (if info.has_receiver { 1 } else { 0 })
				if unalias_type(unwrap_pointer(actual)) is ArrayFixed {
					tc.record_error_at(.call_arg_mismatch,
						'direct decomposition of fixed array is not allowed, convert the fixed array to normal array via arr[..]',
						spread_id, spread_pos)
					tc.record_error_at(.call_arg_mismatch, '`ast.ArrayDecompose` (no value) used as value in argument ${argument_number} to `${tc.call_argument_target_name(node,
						info)}`', arg_id, token.new_span(spread_pos.id, int_max(0,
						spread_pos.offset - 3), spread_pos.end))
					if has_dsl_scope {
						tc.pop_scope()
					}
					continue
				}
				if array_like_elem_type(unwrap_pointer(actual)) == none {
					tc.record_error_at(.call_arg_mismatch,
						'decomposition can only be used on arrays', spread_id, spread_pos)
					tc.record_error_at(.call_arg_mismatch, '`ast.ArrayDecompose` (no value) used as value in argument ${argument_number} to `${tc.call_argument_target_name(node,
						info)}`', arg_id, token.new_span(spread_pos.id, int_max(0,
						spread_pos.offset - 3), spread_pos.end))
					if has_dsl_scope {
						tc.pop_scope()
					}
					continue
				}
				if !tc.variadic_spread_arg_compatible(actual, expected_raw) {
					actual_elem := array_like_elem_type(unwrap_pointer(actual)) or {
						Type(Unknown{})
					}
					actual_display := if unalias_type(elem_type) is Interface {
						actual_elem.name()
					} else {
						'...${actual_elem.name()}'
					}
					expected_display := if unalias_type(elem_type) is Interface {
						elem_type.name()
					} else {
						'...${elem_type.name()}'
					}
					tc.record_error_at(.call_arg_mismatch, 'cannot use `${actual_display}` as `${expected_display}` in argument ${argument_number} to `${tc.call_argument_target_name(node,
						info)}`', arg_id, token.new_span(spread_pos.id, int_max(0,
						spread_pos.offset - 3), spread_pos.end))
				}
				if has_dsl_scope {
					tc.pop_scope()
				}
				continue
			}
			if variadic_elem_accepts_any(elem_type) && tc.variadic_any_arg_is_scalar(arg_id) {
				if has_dsl_scope {
					tc.pop_scope()
				}
				continue
			}
			actual := tc.resolve_expr(arg_id, elem_type)
			actual_name := actual.name()
			expected_name := elem_type.name()
			actual_raw := actual
			if variadic_elem_accepts_any(elem_type) && !variadic_any_arg_has_value(actual) {
				tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual_name}` as argument ${
					param_idx + 1} to `${tc.call_display_name(node)}`; expected `${expected_name}`',
					id)
				if has_dsl_scope {
					tc.pop_scope()
				}
				continue
			}
			if actual is Array {
				if unalias_type(elem_type) !is Array {
					if tc.call_has_explicit_generic_type_args(node) && !info.has_receiver {
						argument_number := param_idx + 1 - (if info.has_receiver { 1 } else { 0 })
						tc.record_error_at(.call_arg_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(arg_id,
							actual)}` as `${call_argument_type_name(elem_type)}` in argument ${argument_number} to `${tc.call_argument_target_name(node,
							info)}`', arg_id, tc.call_argument_diagnostic_pos(arg_id))
					} else {
						arg_text := tc.source_text_for_node(arg_id)
						actual_display_name := tc.current_variadic_param_elem_name(arg_id) or {
							actual_name
						}
						mut target_name := info.name
						mut diagnostic_pos := node.pos
						mut callee := tc.a.child_node(&node, 0)
						if callee.kind == .index && callee.children_count > 0 {
							callee = tc.a.child_node(callee, 0)
						}
						if callee.kind == .selector && callee.children_count > 0 {
							base := tc.a.child_node(callee, 0)
							if base.kind == .ident
								&& tc.source_declares_type_in_scope(base.value, tc.cur_file, tc.cur_module) {
								target_name = '${base.value}__static__${callee.value}'
							}
							if info.has_receiver {
								target_name = callee.value
								name_pos := tc.method_call_name_pos(node, callee)
								diagnostic_pos = token.new_span(name_pos.id, name_pos.offset,
									node.pos.end)
							}
						}
						tc.record_error_at(.call_arg_mismatch,
							'to pass `${arg_text}` (${actual_display_name}) to `${target_name}` (which accepts type `...${elem_type.name()}`), use `...${arg_text}`',
							id, diagnostic_pos)
					}
					if has_dsl_scope {
						tc.pop_scope()
					}
					continue
				}
				if !tc.receiver_compatible(actual_raw, elem_type)
					&& !tc.receiver_compatible(actual_raw, expected)
					&& !tc.type_compatible(actual_raw, elem_type)
					&& !tc.type_compatible(actual_raw, expected) {
					tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual_name}` as argument ${
						param_idx + 1} to `${tc.call_display_name(node)}`; expected `${expected_name}`',
						id)
				}
				if has_dsl_scope {
					tc.pop_scope()
				}
				continue
			}
			expected = elem_type
		}
		if info.name.starts_with('chan ') && info.name.ends_with('.try_push') && info.has_receiver
			&& param_idx == 1 {
			actual_push := fn_param_unalias_type(tc.resolve_type(arg_id))
			expected_push := fn_param_unalias_type(expected)
			if expected_push is Pointer {
				actual_base := if actual_push is Pointer {
					actual_push.base_type
				} else {
					actual_push
				}
				expected_base := expected_push.base_type
				same_numeric_type := !call_arg_numeric_type(actual_base)
					|| !call_arg_numeric_type(expected_base)
					|| call_argument_type_name(actual_base) == call_argument_type_name(expected_base)
				has_storage := actual_push is Pointer || tc.expr_can_take_address(arg_id)
				if !has_storage || !same_numeric_type
					|| !tc.type_compatible(actual_base, expected_base) {
					argument_number := param_idx + 1 - (if info.has_receiver { 1 } else { 0 })
					tc.record_error_at(.call_arg_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(arg_id,
						actual_push)}` as `${call_argument_type_name(expected)}` in argument ${argument_number} to `${tc.call_argument_target_name(node,
						info)}`', arg_id, tc.call_argument_diagnostic_pos(arg_id))
				}
			}
			if has_dsl_scope {
				tc.pop_scope()
			}
			continue
		}
		mut_arg_node := tc.a.node(arg_id)
		if expected !is Pointer && mut_arg_node.kind == .ident
			&& tc.type_has_declaration_attribute(expected, 'nocopy') {
			tc.record_error_at(.call_arg_mismatch,
				'cannot pass @[nocopy] struct by value: use a reference instead', arg_id,
				tc.call_argument_diagnostic_pos(arg_id))
		}
		if mut_arg_node.kind == .map_init && mut_arg_node.children_count == 0
			&& mut_arg_node.value.len == 0 && unalias_type(expected) is Struct {
			argument_number := param_idx + 1 - (if info.has_receiver { 1 } else { 0 })
			tc.record_error_at(.call_arg_mismatch,
				'`{}` can not be used for initialising empty structs any more. Use `${unalias_type(expected).name()}{}` instead.',
				arg_id, mut_arg_node.pos)
			tc.record_error_at(.call_arg_mismatch, '`map{  }` (no value) used as value in argument ${argument_number} to `${tc.call_argument_target_name(node,
				info)}`', arg_id, mut_arg_node.pos)
			if has_dsl_scope {
				tc.pop_scope()
			}
			continue
		}
		param_is_mut := tc.call_param_is_mut(info, param_idx)
			|| tc.explicit_generic_source_param_is_mut(node, info, param_idx)
			|| tc.call_field_param_is_mut(node, param_idx)
		implicit_receiver_arg := tc.call_arg_is_callee_receiver(node, arg_id)
			|| tc.call_arg_is_lowered_method_receiver(node, info, param_idx, expected)
		if call_param_is_shared(info, param_idx) && !tc.expr_is_explicit_shared_arg(arg_id) {
			param_name := tc.source_call_param_name(info.name, param_idx) or {
				'${param_idx + 1 - (if info.has_receiver { 1 } else { 0 })}'
			}
			call_kind := if info.has_receiver { 'method' } else { 'function' }
			if tc.lock_depth > 0 {
				tc.record_error_at(.call_arg_mismatch,
					'${call_kind} with `shared` arguments cannot be called inside `lock`/`rlock` block',
					arg_id, tc.call_argument_diagnostic_pos(arg_id))
			}
			tc.record_error_at(.call_arg_mismatch, '${call_kind} `${tc.call_argument_target_name(node,
				info).all_after_last('.')}` parameter `${param_name}` is `shared`, so use `shared ${tc.source_text_for_node(arg_id)}` instead',
				arg_id, tc.call_argument_diagnostic_pos(arg_id))
			if has_dsl_scope {
				tc.pop_scope()
			}
			continue
		}
		if !is_print_style_fn_name(info.name) {
			if access := tc.unlocked_shared_access(arg_id) {
				if param_is_mut && mut_arg_node.is_mut {
					if tc.lock_depth > 0 {
						tc.record_error_at(.call_arg_mismatch,
							'${access.name} must be added to the `lock` list above', arg_id,
							access.pos)
					}
					tc.record_error_at(.call_arg_mismatch,
						'${access.name} is `shared` and must be `lock`ed to be passed as `mut`',
						arg_id, access.pos)
					if has_dsl_scope {
						tc.pop_scope()
					}
					continue
				}
				if !call_param_is_shared(info, param_idx) {
					tc.record_error_at(.call_arg_mismatch,
						'`${access.name}` is `shared` and must be `rlock`ed or `lock`ed to be passed as non-mut argument',
						arg_id, access.pos)
					if has_dsl_scope {
						tc.pop_scope()
					}
					continue
				}
			}
		}
		if param_is_mut && !mut_arg_node.is_mut && !implicit_receiver_arg {
			param_label := if param_name := tc.source_call_param_name(info.name, param_idx) {
				'`${param_name}`'
			} else {
				'${param_idx + 1 - (if info.has_receiver { 1 } else { 0 })}'
			}
			call_kind := if info.has_receiver || tc.a.child_node(&node, 0).kind == .selector {
				'method'
			} else {
				'function'
			}
			target := tc.call_argument_target_name(node, info).all_after_last('.')
			arg_text := tc.source_text_for_node(arg_id)
			if call_kind == 'function' {
				actual_depth, _ := type_pointer_depth_and_base(tc.resolve_type(arg_id))
				expected_depth, _ := type_pointer_depth_and_base(expected)
				tc.record_warning_at(.call_arg_mismatch,
					'automatic referencing/dereferencing is deprecated and will be removed soon (got: ${actual_depth} references, expected: ${expected_depth} references)',
					arg_id, tc.call_argument_diagnostic_pos(arg_id))
			}
			tc.record_error_at(.call_arg_mismatch,
				'${call_kind} `${target}` parameter ${param_label} is `mut`, so use `mut ${arg_text}` instead',
				arg_id, tc.call_argument_diagnostic_pos(arg_id))
			if call_kind == 'function' && mut_arg_node.kind == .ident {
				argument_number := param_idx + 1 - (if info.has_receiver { 1 } else { 0 })
				actual := tc.resolve_type(arg_id)
				tc.record_error_at(.call_arg_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(arg_id,
					actual)}` as `${call_argument_type_name(expected)}` in argument ${argument_number} to `${tc.call_argument_target_name(node,
					info)}`', arg_id, tc.call_argument_diagnostic_pos(arg_id))
			}
		}
		if mut_arg_node.is_mut && !param_is_mut {
			if mut_arg_node.kind == .array_literal {
				tc.record_error_at(.call_arg_mismatch, 'array literal can not be modified', arg_id,
					tc.call_argument_diagnostic_pos(arg_id))
				tc.record_error_at(.call_arg_mismatch, 'cannot pass expression as `mut`', arg_id,
					tc.call_argument_diagnostic_pos(arg_id))
			}
			param_label := if param_name := tc.source_call_param_name(info.name, param_idx) {
				'`${param_name}`'
			} else {
				'${param_idx + 1 - (if info.has_receiver { 1 } else { 0 })}'
			}
			target := tc.call_argument_target_name(node, info).all_after_last('.')
			tc.record_error_at(.call_arg_mismatch,
				'`${target}` parameter ${param_label} is not `mut`, `mut` is not needed`', arg_id,
				tc.call_argument_diagnostic_pos(arg_id))
		}
		if mut_arg_node.is_mut && mut_arg_node.kind == .ident && param_is_mut
			&& !tc.ident_is_mutable_lvalue(mut_arg_node.value) {
			tc.record_error_at(.call_arg_mismatch,
				'`${mut_arg_node.value}` is immutable, declare it with `mut` to make it mutable',
				arg_id, tc.node_value_diagnostic_pos(arg_id))
			continue
		}
		if mut_arg_node.is_mut && mut_arg_node.kind == .struct_init
			&& tc.call_param_is_mut(info, param_idx) {
			tc.record_error_at(.call_arg_mismatch,
				'cannot pass a struct initialization as `mut`, you may want to use a variable `mut var := ${mut_arg_node.value}{....}`',
				arg_id, mut_arg_node.pos)
			continue
		}
		requires_mut_pointer_slot := tc.call_param_requires_mut_pointer_slot(info, param_idx)
		if requires_mut_pointer_slot && mut_arg_node.is_mut {
			actual_mut_type := if mut_arg_node.kind == .ident {
				tc.cur_scope.lookup(mut_arg_node.value) or { tc.resolve_type(arg_id) }
			} else {
				tc.resolve_type(arg_id)
			}
			actual_mut_depth, _ := type_pointer_depth_and_base(actual_mut_type)
			mut_param_base := tc.fn_context.mut_param_base_types[mut_arg_node.value] or {
				Type(void_)
			}
			mut_param_base_depth, _ := type_pointer_depth_and_base(mut_param_base)
			is_implicit_mut_param_pointer := mut_arg_node.kind == .ident
				&& mut_arg_node.value in tc.fn_context.mut_param_base_types
				&& actual_mut_depth > mut_param_base_depth
			if is_implicit_mut_param_pointer
				|| !tc.mut_pointer_slot_arg_compatible(actual_mut_type, expected) {
				argument_number := param_idx + 1 - (if info.has_receiver { 1 } else { 0 })
				tc.record_error_at(.call_arg_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(arg_id,
					actual_mut_type)}` as `&${call_argument_type_name(expected)}` in argument ${argument_number} to `${tc.call_argument_target_name(node,
					info)}`', arg_id, tc.call_argument_diagnostic_pos(arg_id))
				continue
			}
		}
		if requires_mut_pointer_slot {
			actual_slot := fn_param_unalias_type(tc.resolve_type(arg_id))
			if actual_slot !is Pointer {
				if tc.a.node(arg_id).is_mut
					&& tc.mut_pointer_slot_arg_compatible(actual_slot, expected) {
					// `mut value` supplies the mutable pointer slot for an explicit
					// `mut param &T`; the expression itself still has type `T`.
				} else {
					if has_dsl_scope {
						tc.pop_scope()
					}
					argument_number := param_idx + 1 - (if info.has_receiver { 1 } else { 0 })
					tc.record_error_at(.call_arg_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(arg_id,
						actual_slot)}` as `${call_argument_type_name(expected)}` in argument ${argument_number} to `${tc.call_argument_target_name(node,
						info)}`', arg_id, tc.call_argument_diagnostic_pos(arg_id))
					continue
				}
			}
		}
		// Integer arguments are implicitly converted at a concrete call boundary.
		// Resolve this before applying the expected type, since contextual resolution
		// would otherwise diagnose the conversion while resolving the argument itself.
		negative_unsigned_literal := type_is_unsigned_integer(expected)
			&& tc.expr_is_negative_integer_literal(arg_id)
		if !negative_unsigned_literal {
			tc.warn_if_integer_literal_outside_known_type_range(arg_id, expected,
				tc.a.nodes[int(arg_id)].pos)
		}
		if !call_param_is_shared(info, param_idx) && !tc.expr_is_explicit_shared_arg(arg_id)
			&& call_arg_integer_type(expected) && call_arg_integer_type(tc.resolve_type(arg_id)) {
			arg_node := tc.a.node(arg_id)
			if arg_node.kind == .int_literal {
				if has_dsl_scope {
					tc.pop_scope()
				}
				continue
			}
		}
		mut actual := Type(void_)
		if has_dsl_scope {
			actual = tc.resolve_expr(arg_id, expected)
			tc.pop_scope()
		} else {
			actual = tc.resolve_expr(arg_id, expected)
		}
		if actual is Void {
			argument_number := param_idx + 1 - (if info.has_receiver { 1 } else { 0 })
			tc.record_error(.call_arg_mismatch, '`${tc.source_text_for_node(arg_id)}` (no value) used as value in argument ${argument_number} to `${tc.call_argument_target_name(node,
				info)}`', arg_id)
			continue
		}
		if fn_param_is_voidptr_type(expected) && unalias_type(actual) is Struct {
			tc.record_warning_at(.call_arg_mismatch,
				'automatic ${unalias_type(actual).name()} referencing/dereferencing into voidptr is deprecated and will be removed soon; use `foo(&x)` instead of `foo(x)`',
				arg_id, tc.call_argument_diagnostic_pos(arg_id))
		}
		clean_expected_for_interface := unalias_type(expected)
		if clean_expected_for_interface is Interface && unalias_type(actual) is FnType {
			tc.record_error_at(.call_arg_mismatch,
				'cannot implement interface `${clean_expected_for_interface.name}` using function',
				arg_id, tc.call_argument_diagnostic_pos(arg_id))
			continue
		}
		argument_number := param_idx + 1 - (if info.has_receiver { 1 } else { 0 })
		target_name := tc.call_argument_target_name(node, info)
		if expected_display := tc.bare_generic_fntype_call_param_display(info.name, param_idx) {
			if unalias_type(actual) is FnType {
				actual_display := call_argument_type_name(actual)
				if actual_display != expected_display {
					tc.record_error_at(.call_arg_mismatch,
						'cannot use `${actual_display}` as `${expected_display}` in argument ${argument_number} to `${target_name}`',
						arg_id, tc.call_argument_diagnostic_pos(arg_id))
					continue
				}
			}
		}
		if fn_param_is_voidptr_type(expected)
			&& tc.a.node(arg_id).kind in [.int_literal, .float_literal, .bool_literal, .char_literal, .string_literal, .string_interp] {
			tc.record_error_at(.call_arg_mismatch, 'expression cannot be passed as `voidptr`',
				arg_id, tc.call_argument_diagnostic_pos(arg_id))
			return
		}
		if negative_unsigned_literal {
			tc.record_error_at(.call_arg_mismatch,
				'cannot use literal signed integer as `${call_argument_type_name(expected)}` in argument ${argument_number} to `${target_name}`',
				arg_id, tc.call_argument_diagnostic_pos(arg_id))
			continue
		}
		if expected is Pointer && !(info.name.starts_with('chan ')
			&& info.name.ends_with('.try_push'))
			&& tc.a.node(arg_id).kind in [.int_literal, .float_literal, .bool_literal, .char_literal, .string_literal, .string_interp] {
			mut reference_name := call_argument_type_name(expected)
			if !info.has_receiver {
				if raw_params := tc.fn_param_type_texts[info.name] {
					if param_idx < raw_params.len && raw_params[param_idx].len > 0 {
						reference_name = raw_params[param_idx]
					}
				}
			}
			if !info.name.starts_with('C.') && reference_name !in ['voidptr', 'byteptr', 'charptr'] {
				tc.record_error_at(.call_arg_mismatch,
					'literal argument cannot be passed as reference parameter `${reference_name}`',
					arg_id, tc.call_argument_diagnostic_pos(arg_id))
				continue
			}
		}
		if call_arg_numeric_type(expected) && call_arg_numeric_type(actual)
			&& call_argument_type_name(actual) != call_argument_type_name(expected)
			&& tc.integer_literal_source(arg_id) == none
			&& tc.a.node(arg_id).kind !in [.float_literal, .char_literal] && !(expected is Alias
			&& tc.type_compatible(actual, expected.base_type)) {
			if info.name.starts_with('chan ') && info.name.ends_with('.try_pop') && param_idx == 1 {
				tc.record_error_at(.call_arg_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(arg_id,
					actual)}` as argument for `try_pop` (`${call_argument_type_name(expected)}` expected)',
					arg_id, tc.call_argument_diagnostic_pos(arg_id))
				continue
			}
			tc.record_error_at(.call_arg_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(arg_id,
				actual)}` as `${call_argument_type_name(expected)}` in argument ${argument_number} to `${target_name}`',
				arg_id, tc.call_argument_diagnostic_pos(arg_id))
			continue
		}
		arg_node := tc.a.node(arg_id)
		pointer_check_actual := if arg_node.is_mut && arg_node.kind == .ident {
			tc.cur_scope.lookup(arg_node.value) or { actual }
		} else {
			actual
		}
		actual_pointer_depth, actual_pointer_base :=
			type_pointer_depth_and_base(pointer_check_actual)
		expected_pointer_depth, expected_pointer_base := type_pointer_depth_and_base(expected)
		pointer_depth_mismatch := actual_pointer_depth != expected_pointer_depth
			&& expected.name() !in ['voidptr', 'byteptr', 'charptr'] && !(arg_node.is_mut
			&& tc.mut_pointer_slot_arg_compatible(pointer_check_actual, expected))
			&& !(expected_pointer_depth == actual_pointer_depth + 1
			&& tc.expr_can_take_address(arg_id)) && !type_contains_unknown(pointer_check_actual)
			&& !type_contains_unknown(expected) && !tc.call_arg_is_callee_receiver(node, arg_id)
			&& !tc.call_arg_is_lowered_method_receiver(node, info, param_idx, expected)
		pointer_array_mismatch := actual_pointer_depth > 0 && expected_pointer_depth > 0
			&& unalias_type(actual_pointer_base) is Array
			&& unalias_type(expected_pointer_base) is Array
			&& actual_pointer_base.name() != expected_pointer_base.name()
		if pointer_depth_mismatch || pointer_array_mismatch {
			tc.record_error_at(.call_arg_mismatch, 'cannot use `${tc.diagnostic_expr_type_name(arg_id,
				actual)}` as `${call_argument_type_name(expected)}` in argument ${argument_number} to `${target_name}`',
				arg_id, tc.call_argument_diagnostic_pos(arg_id))
			continue
		}
		if expected is OptionType && actual is Pointer
			&& unalias_type(expected.base_type) !is Pointer {
			tc.record_error_at(.call_arg_mismatch,
				'cannot use `&${actual.base_type.name()}` as `?${expected.base_type.name()}` in argument ${argument_number} to `${target_name}`',
				arg_id, tc.call_argument_diagnostic_pos(arg_id))
			continue
		}
		if tc.addressed_bare_generic_value_mismatch(arg_id, actual, expected) {
			tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual.name()}` as argument ${
				param_idx + 1} to `${tc.call_display_name(node)}`; expected `${expected.name()}`',
				id)
			continue
		}
		if enum_from_input_param(expected) && !enum_from_input_arg_compatible(actual) {
			tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual.name()}` as argument ${
				param_idx + 1} to `${tc.call_display_name(node)}`; expected string or integer', id)
			continue
		}
		param_is_shared := call_param_is_shared(info, param_idx)
		if param_is_shared && !tc.expr_is_shared_arg(arg_id) {
			if tc.should_diagnose(id) {
				tc.record_error(.call_arg_mismatch, 'cannot use non-shared `${actual.name()}` as argument ${
					param_idx + 1} to `${tc.call_display_name(node)}`; expected `shared ${expected.name()}`',
					id)
			}
			continue
		}
		callee_is_fn_literal := node.children_count > 0
			&& tc.a.child_node(&node, 0).kind in [.fn_literal, .lambda_expr]
		if !param_is_shared && tc.expr_is_explicit_shared_arg(arg_id) && !callee_is_fn_literal {
			if tc.should_diagnose(id) {
				tc.record_error(.call_arg_mismatch, 'cannot use explicit shared argument `${actual.name()}` as argument ${
					param_idx + 1} to `${tc.call_display_name(node)}`; expected `${expected.name()}`',
					id)
			}
			continue
		}
		if info.name.starts_with('chan ') && info.name.ends_with('.try_pop') && info.has_receiver
			&& param_idx == 1 && mut_arg_node.is_mut
			&& !tc.chan_try_pop_destination_is_valid(arg_id, actual) {
			if tc.should_diagnose(id) {
				tc.record_error(.call_arg_mismatch,
					'channel try_pop destination must be a mutable lvalue or pointer', id)
			}
			continue
		}
		if info.name.starts_with('C.') && fn_param_unalias_type(expected).is_integer()
			&& tc.c_literal_arg(arg_id) && !tc.c_scalar_byte_literal_arg(arg_id) {
			tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual.name()}` as argument ${
				param_idx + 1} to `${tc.call_display_name(node)}`; expected `${expected.name()}`',
				id)
			continue
		}
		if !tc.expr_receiver_compatible(arg_id, actual, expected)
			&& !tc.expr_compatible(arg_id, actual, expected) {
			if (tc.call_arg_is_callee_receiver(node, arg_id)
				|| tc.call_arg_is_lowered_method_receiver(node, info, param_idx, expected))
				&& tc.method_receiver_compatible(actual, expected, info.name) {
				continue
			}
			if tc.a.nodes[int(arg_id)].is_mut
				&& tc.mut_optional_pointer_arg_compatible(actual, expected) {
				continue
			}
			if tc.a.nodes[int(arg_id)].is_mut && expected is Pointer
				&& tc.type_compatible(actual, expected.base_type) {
				continue
			}
			if base := tc.mut_param_expr_base(arg_id, actual) {
				if tc.type_compatible(base, expected)
					|| tc.pointer_value_compatible(actual, expected) {
					continue
				}
			}
			if tc.receiver_compatible(actual, expected) {
				continue
			}
			call_name := if info.name.len > 0 { info.name } else { tc.call_display_name(node) }
			if tc.c_call_arg_compatible(call_name, arg_id, expected, actual) {
				continue
			}
			if expected is Pointer && tc.expr_tail_is_nil(arg_id) {
				continue
			}
			if tc.explicit_address_arg_compatible(arg_id, actual, expected) {
				continue
			}
			if tc.explicit_mut_pointer_arg_compatible(arg_id, expected) {
				continue
			}
			if param_is_shared && tc.shared_arg_pointer_compatible(actual, expected) {
				continue
			}
			if json_runtime_voidptr_accepts_arg(call_name, param_idx, expected, actual) {
				continue
			}
			if free_array_arg_compatible(info.name, param_idx, expected, actual) {
				continue
			}
			if voidptr_arg_compatible(expected, actual) {
				continue
			}
			// A `voidptr`/`&void` argument is accepted where a function-pointer type
			// is expected (e.g. a `map[string]EasingFN` whose first literal element is
			// `voidptr(fn)`, making the map value type `voidptr`). voidptr and function
			// pointers are interchangeable in C; matches v1.
			if is_fn_pointer_type(expected) && fn_param_is_voidptr_type(actual) {
				continue
			}
			if !info.name.starts_with('C.') && fn_param_is_voidptr_type(expected)
				&& tc.expr_can_take_address(arg_id) {
				continue
			}
			if fn_param_is_voidptr_type(expected) && info.name.ends_with('Channel.push') {
				continue
			}
			if tc.array_insert_prepend_many_arg_compatible(node, info, param_idx, actual) {
				continue
			}
			if tc.array_dsl_fn_arg_compatible(node, info, param_idx, actual) {
				continue
			}
			if tc.is_os_args_contains_call(node) && param_idx == 1 && actual is String {
				continue
			}
			if actual is OptionType && expected !is OptionType {
				tc.record_error_at(.call_arg_mismatch,
					'cannot use `?${actual.base_type.name()}` as `${expected.name()}`, it must be unwrapped first in argument ${argument_number} to `${target_name}`',
					arg_id, tc.call_argument_diagnostic_pos(arg_id))
				continue
			}
			clean_expected := unalias_type(expected)
			if expected_interface := cast_target_interface(clean_expected) {
				if tc.record_interface_implementation_error(.call_arg_mismatch, actual,
					expected_interface, arg_id, tc.call_argument_diagnostic_pos(arg_id))
				{
					continue
				}
			}
			actual_display := tc.diagnostic_expr_type_name(arg_id, actual)
			expected_display := call_argument_type_name(expected)
			message := 'cannot use `${actual_display}` as `${expected_display}` in argument ${argument_number} to `${target_name}`'
			if unalias_type(expected) is FnType && unalias_type(actual) is FnType {
				expected_alias := if expected is Alias { expected.name } else { '' }
				details := tc.fn_assignment_mismatch_details(expected_display, expected_alias,
					actual_display, arg_id)
				if details.len > 0 {
					tc.record_error_with_details_at(.call_arg_mismatch, message, arg_id,
						tc.call_argument_diagnostic_pos(arg_id), details)
					continue
				}
			}
			tc.record_error_at(.call_arg_mismatch, message, arg_id,
				tc.call_argument_diagnostic_pos(arg_id))
		}
	}
}

fn (tc &TypeChecker) params_field_diagnostic_type(field_name string, info CallInfo, expected Type) string {
	for param in info.params {
		param_struct := struct_type_from_type(unwrap_pointer(param)) or { continue }
		if expected_text, _ := tc.struct_field_diagnostic_fn_type(param_struct.name, field_name, 0) {
			semantic_text := call_argument_type_name(expected)
			imports := tc.current_file_import_info()
			if !isnil(imports) {
				mut qualified_text := expected_text
				for alias, module_path in imports.imports {
					prefix := '${module_path}.'
					mut cursor := 0
					for cursor < semantic_text.len {
						relative := semantic_text[cursor..].index(prefix) or { break }
						type_start := cursor + relative + prefix.len
						mut type_end := type_start
						for type_end < semantic_text.len && (semantic_text[type_end].is_alnum()
							|| semantic_text[type_end] == `_`) {
							type_end++
						}
						if type_end > type_start {
							type_name := semantic_text[type_start..type_end]
							qualified_text = qualified_text.replace(type_name,
								'${alias}.${type_name}')
						}
						cursor = type_end
					}
				}
				if qualified_text != expected_text {
					return qualified_text
				}
			}
			return expected_text
		}
	}
	return tc.diagnostic_fntype_alias_display(expected) or { expected.name() }
}

fn (tc &TypeChecker) diagnostic_fntype_alias_display(typ Type) ?string {
	alias := if typ is Alias { typ } else { return none }
	base, args, is_generic := generic_type_application_parts(alias.name)
	lookup := if is_generic { base } else { alias.name }
	raw := tc.source_fn_alias_type_text(lookup) or { return none }
	if !is_generic {
		return tc.diagnostic_fn_type_text(raw)
	}
	params := tc.type_alias_generic_params[lookup] or {
		tc.type_alias_generic_params[tc.qualify_name(lookup)] or { return none }
	}
	if params.len != args.len {
		return tc.diagnostic_fn_type_text(raw)
	}
	return tc.diagnostic_fn_type_text(subst_generic_text(raw, args, params))
}

fn (tc &TypeChecker) bare_generic_fntype_call_param_display(fn_name string, param_idx int) ?string {
	param_texts := tc.fn_param_type_texts[fn_name] or { return none }
	if param_idx < 0 || param_idx >= param_texts.len {
		return none
	}
	name := tc.bare_generic_decl_type_name(param_texts[param_idx]) or { return none }
	qualified := tc.qualify_name(name)
	params := tc.type_alias_generic_params[name] or {
		tc.type_alias_generic_params[qualified] or { return none }
	}
	if params.len == 0 {
		return none
	}
	raw := tc.source_fn_alias_type_text(name) or { return none }
	if unalias_type(tc.parse_type(name)) is FnType {
		return tc.diagnostic_fn_type_text(raw)
	}
	return none
}

fn call_argument_type_name(typ Type) string {
	if typ is Alias {
		clean := unalias_type(typ)
		if clean is FnType {
			return Type(clean).name().replace('fn(', 'fn (').replace(' !void', ' !').replace(' ?void',
				' ?')
		}
	}
	return typ.name().replace('fn(', 'fn (')
}

fn (tc &TypeChecker) call_arg_is_callee_receiver(node flat.Node, arg_id flat.NodeId) bool {
	if node.children_count == 0 || !tc.valid_node_id(arg_id) {
		return false
	}
	mut callee := tc.a.child_node(&node, 0)
	if callee.kind == .index && callee.children_count > 0 {
		callee = tc.a.child_node(callee, 0)
	}
	if callee.kind != .selector || callee.children_count == 0 {
		return false
	}
	receiver_id := tc.a.child(callee, 0)
	if receiver_id == arg_id {
		return true
	}
	receiver := tc.a.node(receiver_id)
	arg := tc.a.node(arg_id)
	return receiver.pos.is_valid() && arg.pos.is_valid() && receiver.pos.id == arg.pos.id
		&& receiver.pos.offset == arg.pos.offset && receiver.pos.end == arg.pos.end
}

fn (tc &TypeChecker) call_arg_is_lowered_method_receiver(node flat.Node, info CallInfo, param_idx int, expected Type) bool {
	if param_idx != 0 || node.children_count == 0 {
		return false
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind != .ident || !info.name.contains('.') {
		return false
	}
	mut receiver_type := fn_param_unalias_type(expected)
	if receiver_type is Pointer {
		receiver_type = fn_param_unalias_type(receiver_type.base_type)
	}
	owner := info.name.all_before_last('.')
	receiver_name := receiver_type.name()
	return owner == receiver_name || owner.ends_with('.${receiver_name}')
		|| receiver_name.ends_with('.${owner}')
}

fn (tc &TypeChecker) current_variadic_param_elem_name(id flat.NodeId) ?string {
	if !tc.valid_node_id(id) || tc.fn_context.node_id < 0 || tc.fn_context.node_id >= tc.a.nodes.len {
		return none
	}
	arg := tc.a.node(id)
	if arg.kind != .ident {
		return none
	}
	fn_node := tc.a.nodes[tc.fn_context.node_id]
	for i in 0 .. fn_node.children_count {
		param := tc.a.child_node(&fn_node, i)
		if param.kind != .param {
			break
		}
		if param.value == arg.value && param.typ.starts_with('...') {
			return param.typ.trim_left('.')
		}
	}
	return none
}

fn (tc &TypeChecker) call_argument_target_name(node flat.Node, info CallInfo) string {
	if info.name.len > 0 {
		if info.name in ['map.delete', 'map__delete'] {
			return 'Map.delete'
		}
		if node.children_count > 0 {
			mut callee := tc.a.child_node(&node, 0)
			if callee.kind == .index && callee.children_count > 0 {
				callee = tc.a.child_node(callee, 0)
			}
			if callee.kind == .selector && callee.children_count > 0 {
				receiver_id := tc.a.child(callee, 0)
				receiver := tc.a.node(receiver_id)
				if receiver.kind == .ident && tc.binding_is_strings_builder(receiver.value) {
					return info.name.replace('fn(', 'fn (')
				}
				receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(receiver_id))
				if receiver_type.name().contains('[') && !type_contains_unknown(receiver_type) {
					return '${receiver_type.name()}.${callee.value}'.replace('fn(', 'fn (')
				}
			}
			if callee.kind == .selector && callee.children_count > 0 && info.name.count('.') == 1 {
				base := tc.a.child_node(callee, 0)
				if base.kind == .ident && tc.ident_resolves_to_value(base.value)
					&& (callee.value in tc.fn_ret_types
					|| tc.qualify_fn_name(callee.value) in tc.fn_ret_types) {
					return callee.value
				}
			}
		}
		return info.name.replace('fn(', 'fn (')
	}
	if node.children_count == 0 {
		return tc.call_display_name(node)
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind in [.fn_literal, .lambda_expr] {
		return 'anon'
	}
	if callee.kind == .selector && callee.children_count > 0 {
		base_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(callee, 0)))
		if base_type is Struct || base_type is Interface {
			return '${base_type.name()}.${callee.value}'
		}
	}
	return tc.call_display_name(node)
}

fn (tc &TypeChecker) call_argument_diagnostic_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	mut unsafe_expr := *node
	for unsafe_expr.kind in [.paren, .expr_stmt] && unsafe_expr.children_count > 0 {
		unsafe_expr = *tc.a.child_node(&unsafe_expr, 0)
	}
	if unsafe_expr.kind == .block && unsafe_expr.value == 'unsafe' {
		return token.new_span(node.pos.id, node.pos.offset,

			int_max(node.pos.end, unsafe_expr.pos.end) + 1)
	}
	if node.kind != .cast_expr || node.children_count == 0 {
		return node.pos
	}
	child := tc.a.child_node(node, 0)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	child_start := int_min(int_max(child.pos.offset, 0), source.len)
	search_start := int_max(0, child_start - node.value.len - 2)
	if relative := source[search_start..child_start].last_index('${node.value}(') {
		start := search_start + relative
		mut end := int_min(source.len, int_max(child.pos.end, child_start))
		for end < source.len && source[end] in [` `, `\t`] {
			end++
		}
		if end < source.len && source[end] == `)` {
			end++
		}
		return token.new_span(node.pos.id, start, end)
	}
	return node.pos
}

fn (tc &TypeChecker) surplus_call_args_pos(node flat.Node, expected_count int) token.Pos {
	first_surplus_child := 1 + expected_count
	if first_surplus_child < 1 || first_surplus_child >= node.children_count {
		return node.pos
	}
	first_id := tc.call_arg_value(tc.a.child(&node, first_surplus_child))
	if spread_id := tc.spread_arg_value(first_id) {
		spread := tc.a.node(spread_id)
		return token.new_span(spread.pos.id, int_max(0, spread.pos.offset - 3), spread.pos.end)
	}
	last_id := tc.call_arg_value(tc.a.child(&node, node.children_count - 1))
	if !tc.valid_node_id(first_id) || !tc.valid_node_id(last_id) {
		return node.pos
	}
	first := tc.a.nodes[int(first_id)]
	last := tc.a.nodes[int(last_id)]
	if first.pos.id != last.pos.id {
		return first.pos
	}
	return token.new_span(first.pos.id, first.pos.offset, last.pos.end)
}

fn (tc &TypeChecker) call_count_mismatch_details(node flat.Node, info CallInfo) []string {
	mut actual_names := []string{}
	for i in 1 + info.arg_offset .. node.children_count {
		arg_id := tc.call_arg_value(tc.a.child(&node, i))
		if spread_id := tc.spread_arg_value(arg_id) {
			actual := tc.resolve_type(spread_id)
			if actual is Unknown || actual is Void {
				actual_names << 'void'
				continue
			}
		}
		actual := tc.resolve_type(arg_id)
		actual_names << tc.diagnostic_expr_type_name(arg_id, actual)
	}
	mut expected_names := []string{}
	if source_names := tc.source_call_param_type_names(info.name) {
		param_start := if info.has_receiver && source_names.len == info.params.len { 1 } else { 0 }
		source_end := if info.is_variadic && source_names.len > 0 {
			source_names.len - 1
		} else {
			source_names.len
		}
		for i in param_start .. source_end {
			source_name := source_names[i]
			source_type := if i < info.params.len {
				unalias_type(info.params[i])
			} else {
				unalias_type(tc.parse_type(source_name))
			}
			source_is_interface := source_type is Interface || source_name in tc.interface_names
				|| tc.qualify_name(source_name) in tc.interface_names
				|| tc.interface_names.keys().any(it.all_after_last('.') == source_name)
			if source_is_interface && !source_name.contains('.') {
				raw_mod_name := tc.fn_type_modules[info.name] or {
					if info.name.contains('.') {
						info.name.all_before_last('.')
					} else {
						tc.cur_module
					}
				}
				mod_name := if raw_mod_name.len > 0 { raw_mod_name } else { 'main' }
				expected_names << '${mod_name}.${source_name}'
			} else {
				expected_names << source_name
			}
		}
	} else {
		param_start := if info.has_receiver { 1 } else { 0 }
		param_end := if info.is_variadic && info.params.len > 0 {
			info.params.len - 1
		} else {
			c_variadic_fixed_param_count(info)
		}
		for i in param_start .. param_end {
			param_name := info.params[i].name()
			param_type := unalias_type(info.params[i])
			param_is_interface := param_type is Interface || param_name in tc.interface_names
				|| tc.qualify_name(param_name) in tc.interface_names
				|| tc.interface_names.keys().any(it.all_after_last('.') == param_name)
			if param_is_interface && !param_name.contains('.') {
				raw_mod_name := tc.fn_type_modules[info.name] or {
					if info.name.contains('.') {
						info.name.all_before_last('.')
					} else {
						tc.cur_module
					}
				}
				mod_name := if raw_mod_name.len > 0 { raw_mod_name } else { 'main' }
				expected_names << '${mod_name}.${param_name}'
			} else {
				expected_names << param_name
			}
		}
	}
	return [
		'have (${actual_names.join(', ')})',
		'         want (${expected_names.join(', ')})',
	]
}

fn (tc &TypeChecker) source_call_param_type_names(call_name string) ?[]string {
	if call_name.len == 0 {
		return none
	}
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		if node.kind != .fn_decl
			|| (node.value != call_name && !call_name.ends_with('.${node.value}')) {
			continue
		}
		mut names := []string{}
		for child_index in 0 .. node.children_count {
			param := tc.a.child_node(&node, child_index)
			if param.kind == .param {
				names << param.typ
			}
		}
		if names.len > 0 {
			return names
		}
	}
	return none
}

fn (tc &TypeChecker) source_call_param_name(call_name string, param_idx int) ?string {
	if call_name.len == 0 || param_idx < 0 {
		return none
	}
	if call_name.starts_with('chan ') && call_name.ends_with('.try_pop') && param_idx == 1 {
		return 'obj'
	}
	for i in tc.top_level_idx {
		node := tc.a.nodes[i]
		if node.kind != .fn_decl
			|| (node.value != call_name && !call_name.ends_with('.${node.value}')) {
			continue
		}
		mut index := 0
		for child_index in 0 .. node.children_count {
			param := tc.a.child_node(&node, child_index)
			if param.kind != .param {
				continue
			}
			if index == param_idx {
				if param.value.len > 0 && param.value != '_' {
					return param.value
				}
				return none
			}
			index++
		}
	}
	return none
}

fn (mut tc TypeChecker) check_builtin_map_call_args(_id flat.NodeId, node flat.Node, info CallInfo) bool {
	if node.children_count == 0 || info.arg_offset != 0 {
		return false
	}
	mut callee := tc.a.child_node(&node, 0)
	if callee.kind == .index && callee.children_count > 0 {
		callee = tc.a.child_node(callee, 0)
	}
	if callee.kind != .selector || callee.children_count == 0 {
		return false
	}
	receiver_id := tc.a.child(callee, 0)
	receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(receiver_id))
	if receiver_type !is Map {
		return false
	}
	if info.name.len > 0 && !checker_is_raw_collection_method_name(info.name, 'map.') {
		return false
	}
	method := callee.value
	if method !in ['clone', 'move', 'keys', 'values'] {
		return false
	}
	for i in 1 .. node.children_count {
		tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
	}
	if node.children_count > 1 {
		arg_id := tc.call_arg_value(tc.a.child(&node, 1))
		tc.record_error(.call_arg_mismatch, '`.${method}()` does not have any arguments', arg_id)
	} else if method == 'move' {
		tc.check_builtin_array_mutable_receiver(receiver_id)
	}
	return true
}

fn (mut tc TypeChecker) check_builtin_array_call_args(id flat.NodeId, node flat.Node, info CallInfo) bool {
	if node.children_count == 0 || info.arg_offset != 0 {
		return false
	}
	mut callee := tc.a.child_node(&node, 0)
	if callee.kind == .index && callee.children_count > 0 {
		callee = tc.a.child_node(callee, 0)
	}
	if callee.kind != .selector || callee.children_count == 0 {
		return false
	}
	receiver_id := tc.a.child(callee, 0)
	receiver_type := tc.resolve_type(receiver_id)
	array_type := array_like_type_for_method(unalias_and_unwrap_pointer_type(receiver_type),
		callee.value) or { return false }
	if info.name.len > 0 && !checker_is_raw_collection_method_name(info.name, 'array.') {
		return false
	}
	method := callee.value
	explicit_count := int(node.children_count) - 1
	if method in ['clone', 'reverse', 'first', 'last', 'pop', 'pop_left'] {
		for i in 1 .. node.children_count {
			tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
		}
		if explicit_count > 0 {
			arg_id := tc.call_arg_value(tc.a.child(&node, 1))
			tc.record_error(.call_arg_mismatch, '`.${method}()` does not have any arguments',
				arg_id)
		}
		if method in ['pop', 'pop_left'] {
			tc.check_builtin_array_mutable_receiver(receiver_id)
		}
		return true
	}
	if method == 'delete' {
		if explicit_count != 1 {
			for i in 1 .. node.children_count {
				tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
			}
			tc.record_error_at(.call_arg_mismatch,
				'`.delete()` expected 1 argument, but got ${explicit_count}', id, tc.method_call_name_pos(node,
				callee))
			tc.check_builtin_array_mutable_receiver(receiver_id)
			return true
		}
		arg_id := tc.call_arg_value(tc.a.child(&node, 1))
		tc.check_node_with_expected_context(arg_id, Type(int_))
		actual := tc.resolve_expr(arg_id, Type(int_))
		if !tc.expr_compatible(arg_id, actual, Type(int_)) {
			tc.record_error(.call_arg_mismatch,
				'cannot use `${actual.name()}` as `int` in argument 1 to `.delete()`', arg_id)
		}
		tc.check_builtin_array_mutable_receiver(receiver_id)
		return true
	}
	if method == 'insert' {
		if explicit_count != 2 {
			for i in 1 .. node.children_count {
				tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
			}
			tc.record_error_at(.call_arg_mismatch,
				'`array.insert()` should have 2 arguments, e.g. `insert(1, val)`', id, tc.method_call_name_pos(node,
				callee))
			return true
		}
		index_id := tc.call_arg_value(tc.a.child(&node, 1))
		tc.check_node_with_expected_context(index_id, Type(int_))
		index_type := tc.resolve_expr(index_id, Type(int_))
		index_is_valid := tc.expr_compatible(index_id, index_type, Type(int_))
		if !index_is_valid {
			tc.record_error(.call_arg_mismatch,
				'the first argument of `array.insert()` should be integer', index_id)
		}
		value_id := tc.call_arg_value(tc.a.child(&node, 2))
		tc.check_node_with_expected_context(value_id, array_type.elem_type)
		value_type := tc.resolve_expr(value_id, array_type.elem_type)
		value_is_valid := tc.array_insert_value_compatible(value_id, value_type, array_type,
			receiver_type)
		if index_is_valid && !value_is_valid {
			clean_value := unalias_type(value_type)
			if clean_value is OptionType {
				tc.record_error(.call_arg_mismatch,
					'cannot use `${value_type.name()}` as `voidptr`, it must be unwrapped first in argument 2 to `${receiver_type.name()}.insert`',
					value_id)
			} else {
				value_name := tc.array_insert_value_type_name(value_id, value_type)
				tc.record_error(.call_arg_mismatch,
					'cannot insert `${value_name}` to `${receiver_type.name()}`', value_id)
			}
		}
		if index_is_valid && value_is_valid {
			tc.check_builtin_array_mutable_receiver(receiver_id)
		}
		return true
	}
	if method == 'prepend' {
		if explicit_count != 1 {
			for i in 1 .. node.children_count {
				tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
			}
			tc.record_error_at(.call_arg_mismatch,
				'`array.prepend()` should have 1 argument, e.g. `prepend(val)`', id, tc.method_call_name_pos(node,
				callee))
			return true
		}
		value_id := tc.call_arg_value(tc.a.child(&node, 1))
		tc.check_node_with_expected_context(value_id, array_type.elem_type)
		value_type := tc.resolve_expr(value_id, array_type.elem_type)
		value_is_valid := tc.array_insert_value_compatible(value_id, value_type, array_type,
			receiver_type)
		if !value_is_valid {
			clean_value := unalias_type(value_type)
			if clean_value is OptionType {
				tc.record_error(.call_arg_mismatch,
					'cannot use `${value_type.name()}` as `voidptr`, it must be unwrapped first in argument 1 to `${receiver_type.name()}.prepend`',
					value_id)
			} else {
				value_name := tc.array_insert_value_type_name(value_id, value_type)
				tc.record_error(.call_arg_mismatch,
					'cannot prepend `${value_name}` to `${receiver_type.name()}`', value_id)
			}
		}
		if value_is_valid {
			tc.check_builtin_array_mutable_receiver(receiver_id)
		}
		return true
	}
	if method in ['index', 'last_index', 'contains'] {
		if explicit_count != 1 {
			for i in 1 .. node.children_count {
				tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
			}
			tc.record_error_at(.call_arg_mismatch,
				'`.${method}()` expected 1 argument, but got ${explicit_count}', id, tc.method_call_name_pos(node,
				callee))
			return true
		}
		arg_id := tc.call_arg_value(tc.a.child(&node, 1))
		tc.check_node_with_expected_context(arg_id, array_type.elem_type)
		actual := tc.resolve_expr(arg_id, array_type.elem_type)
		if !tc.expr_compatible(arg_id, actual, array_type.elem_type) {
			if unalias_type(actual) is OptionType {
				tc.record_error_at(.call_arg_mismatch,
					'cannot use `${actual.name()}` as `${array_type.elem_type.name()}`, it must be unwrapped first in argument 1 to `.${method}()`',
					arg_id, tc.call_argument_diagnostic_pos(arg_id))
			} else {
				tc.record_error_at(.call_arg_mismatch,
					'cannot use `${actual.name()}` as `${array_type.elem_type.name()}` in argument 1 to `.${method}()`',
					arg_id, tc.call_argument_diagnostic_pos(arg_id))
			}
		}
		return true
	}
	if method in ['sort_with_compare', 'sorted_with_compare'] {
		if method == 'sort_with_compare' {
			tc.check_builtin_array_mutable_receiver(receiver_id)
		}
		if explicit_count != 1 {
			for i in 1 .. node.children_count {
				tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
			}
			name_pos := tc.method_call_name_pos(node, callee)
			tc.record_error_at(.call_arg_mismatch,
				'`.${method}()` expected 1 argument, but got ${explicit_count}', id, token.new_span(name_pos.id,
				name_pos.offset, node.pos.end))
			return true
		}
		arg_id := tc.call_arg_value(tc.a.child(&node, 1))
		tc.check_node(arg_id)
		actual := tc.resolve_type(arg_id)
		expected := Type(FnType{
			params:      [
				Type(Pointer{
					base_type: array_type.elem_type
				}),
				Type(Pointer{
					base_type: array_type.elem_type
				}),
			]
			return_type: Type(int_)
		})
		if actual_fn := fn_type_from_type(actual) {
			tc.record_array_compare_callback_param_errors(method, arg_id, array_type.elem_type)
			if tc.type_compatible(actual_fn, expected) {
				return true
			}
			if unalias_type(array_type.elem_type) is Pointer {
				return true
			}
		}
		actual_name := tc.diagnostic_expr_type_name(arg_id, actual).replace_once('fn(', 'fn (')
		target := '[]${array_type.elem_type.name()}.${method}'
		message := 'cannot use `${actual_name}` as `fn (voidptr, voidptr) int` in argument 1 to `${target}`'
		if actual_fn := fn_type_from_type(actual) {
			if actual_fn.params.len > 0 && unalias_type(actual_fn.params[0]) !is Pointer {
				tc.record_error_with_details_at(.call_arg_mismatch, message, arg_id,
					tc.a.node(arg_id).pos, [
					"`FnSortCB`'s expected argument `const_a` to be a pointer, but the passed argument `a` is NOT a pointer",
				])
				return true
			}
		}
		tc.record_error_at(.call_arg_mismatch, message, arg_id, tc.a.node(arg_id).pos)
		return true
	}
	if method == 'map' {
		if explicit_count != 1 {
			tc.push_array_dsl_scope(node, 'array.map')
			for i in 1 .. node.children_count {
				tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
			}
			tc.pop_scope()
			tc.record_error_at(.call_arg_mismatch,
				'expected 1 argument, but got ${explicit_count}', id, tc.method_call_name_pos(node,
				callee))
			return true
		}
		arg_id := tc.call_arg_value(tc.a.child(&node, 1))
		tc.push_array_dsl_scope(node, 'array.map')
		error_count := tc.errors.len
		tc.check_node(arg_id)
		arg_type := tc.resolve_type(arg_id)
		tc.pop_scope()
		if fn_type := fn_type_from_type(arg_type) {
			if fn_type.return_type is MultiReturn {
				tc.record_error_at(.call_arg_mismatch,
					'returning multiple values is not supported in .map() calls', arg_id, tc.method_call_name_pos(node,
					callee))
				return true
			}
			if fn_type.return_type is Void {
				arg := tc.a.node(arg_id)
				if arg.kind == .lambda_expr && arg.children_count > 0 {
					body_id := tc.a.child(arg, arg.children_count - 1)
					body := tc.a.node(body_id)
					if body.kind == .call {
						tc.record_error_at(.call_arg_mismatch,
							'type mismatch, `${tc.call_display_name(*body)}` does not return anything',
							body_id, body.pos)
						return true
					}
				}
			}
			if fn_type.return_type is ResultType {
				tc.record_error_at(.call_arg_mismatch, 'cannot use Result type in `map`', arg_id,
					tc.a.node(arg_id).pos)
				return true
			}
			if fn_type.return_type is OptionType {
				pos := if tc.expr_is_direct_fn_value(arg_id) {
					tc.method_call_name_pos(node, callee)
				} else {
					tc.a.nodes[int(arg_id)].pos
				}
				tc.record_error_at(.call_arg_mismatch,
					'option needs to be unwrapped before using it in map/filter', arg_id, pos)
			}
			if fn_type.params.len != 1 {
				pos := if tc.a.nodes[int(arg_id)].kind == .ident {
					tc.method_call_name_pos(node, callee)
				} else {
					tc.a.nodes[int(arg_id)].pos
				}
				message := if tc.a.nodes[int(arg_id)].kind == .lambda_expr {
					'lambda expressions used in the builtin array methods require exactly 1 parameter'
				} else {
					'function needs exactly 1 argument'
				}
				tc.record_error_at(.call_arg_mismatch, message, arg_id, pos)
				tc.register_synth_type(id, Type(void_))
				tc.record_enclosing_dump_void(id)
			} else if !tc.type_compatible(fn_type.params[0], array_type.elem_type)
				|| fn_type.return_type is Void {
				tc.record_error(.call_arg_mismatch,
					'type mismatch, should use `fn(a ${array_type.elem_type.name()}) T {...}`',
					arg_id)
			}
		} else if result_pos := tc.array_map_result_propagation_pos(arg_id) {
			tc.record_error_at(.call_arg_mismatch, 'cannot use Result type in `map`', arg_id,
				result_pos)
		} else if arg_type is Void && tc.errors.len == error_count {
			arg := tc.a.nodes[int(arg_id)]
			name := if arg.kind == .call { tc.call_display_name(arg) } else { 'expression' }
			tc.record_error(.call_arg_mismatch,
				'type mismatch, `${name}` does not return anything', arg_id)
		}
		return true
	}
	if method in ['any', 'all', 'filter', 'count'] {
		if explicit_count != 1 {
			for i in 1 .. node.children_count {
				tc.check_node(tc.call_arg_value(tc.a.child(&node, i)))
			}
			message := if method in ['any', 'all'] {
				'`.${method}` expected 1 argument, but got ${explicit_count}'
			} else {
				'expected 1 argument, but got ${explicit_count}'
			}
			tc.record_error_at(.call_arg_mismatch, message, id, tc.method_call_name_pos(node,
				callee))
			return true
		}
		arg_id := tc.call_arg_value(tc.a.child(&node, 1))
		tc.push_array_dsl_scope(node, 'array.${method}')
		tc.check_node(arg_id)
		arg := tc.a.nodes[int(arg_id)]
		arg_type := tc.resolve_type(arg_id)
		tc.pop_scope()
		if fn_type := fn_type_from_type(arg_type) {
			if fn_type.return_type is OptionType {
				tc.record_error_at(.call_arg_mismatch,
					'option needs to be unwrapped before using it in map/filter', arg_id, tc.method_call_name_pos(node,
					callee))
			}
			if fn_type.params.len != 1 {
				pos := if arg.kind == .ident {
					tc.method_call_name_pos(node, callee)
				} else {
					arg.pos
				}
				tc.record_error_at(.call_arg_mismatch, 'function needs exactly 1 argument', arg_id,
					pos)
			} else if !tc.type_compatible(fn_type.params[0], array_type.elem_type)
				|| !tc.type_compatible(fn_type.return_type, Type(bool_)) {
				tc.record_error(.call_arg_mismatch,
					'type mismatch, should use `fn(a ${array_type.elem_type.name()}) bool {...}`',
					arg_id)
			}
		} else if arg.kind in [.string_literal, .string_interp] {
			tc.record_error(.call_arg_mismatch,
				'type mismatch, should use e.g. `${method}(it > 2)`', arg_id)
		} else {
			actual := tc.resolve_expr(arg_id, Type(bool_))
			if !tc.expr_compatible(arg_id, actual, Type(bool_)) {
				clean_actual := unalias_type(actual)
				if clean_actual is OptionType
					&& unalias_type(clean_actual.base_type).name() == 'bool' && arg.kind == .call {
					tc.record_error(.call_arg_mismatch,
						'type mismatch, `${tc.call_display_name(arg)}` must return a bool', arg_id)
				} else if arg.kind == .call {
					tc.record_error(.call_arg_mismatch,
						'type mismatch, `${tc.call_display_name(arg)}` must return a bool', arg_id)
				} else {
					tc.record_error(.call_arg_mismatch,
						'invalid expression, expected infix expr, lambda or function', arg_id)
				}
			}
		}
		return true
	}
	if method in ['clear', 'delete_last', 'reverse_in_place', 'sort', 'sort_with_compare'] {
		tc.check_builtin_array_mutable_receiver(receiver_id)
	}
	return false
}

fn (tc &TypeChecker) array_map_result_propagation_pos(id flat.NodeId) ?token.Pos {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind != .or_expr || node.value != '!' || node.children_count == 0 {
		return none
	}
	source_id := tc.a.child(node, 0)
	source_type := unalias_type(tc.resolve_type(source_id))
	if source_type is ResultType && unalias_type(source_type.base_type) is Void {
		source := tc.a.node(source_id)
		if source.kind == .call && source.children_count > 0 {
			callee := tc.a.child_node(source, 0)
			if callee.kind == .selector {
				name_pos := tc.method_call_name_pos(*source, *callee)
				return token.new_span(name_pos.id, name_pos.offset, node.pos.end)
			}
		}
		return source.pos
	}
	return none
}

fn (mut tc TypeChecker) record_array_compare_callback_param_errors(method string, arg_id flat.NodeId, elem_type Type) {
	arg := tc.a.node(arg_id)
	if arg.kind != .ident {
		return
	}
	expected := Type(Pointer{
		base_type: elem_type
	})
	for idx in tc.top_level_idx {
		fn_node := tc.a.nodes[idx]
		if fn_node.kind != .fn_decl
			|| (fn_node.value != arg.value && !fn_node.value.ends_with('.${arg.value}')) {
			continue
		}
		mut param_index := 0
		for i in 0 .. fn_node.children_count {
			param_id := tc.a.child(&fn_node, i)
			param := tc.a.node(param_id)
			if param.kind != .param {
				break
			}
			if param_index < 2 {
				actual := tc.parse_type(param.typ)
				if !tc.method_param_signature_compatible(actual, expected) {
					tc.record_error_at(.call_arg_mismatch,
						'${method} callback function parameter `${param.value}` with type `${actual.name()}` should be `${expected.name()}`',
						param_id, tc.type_diagnostic_pos(param_id, param.typ))
				}
			}
			param_index++
		}
		return
	}
}

fn (mut tc TypeChecker) check_array_sort_call(id flat.NodeId, node flat.Node, callee flat.Node) {
	explicit_count := int(node.children_count) - 1
	if explicit_count > 1 {
		tc.record_error_at(.call_arg_mismatch,
			'expected 0 or 1 argument, but got ${explicit_count}', id, tc.method_call_name_pos(node,
			callee))
		return
	}
	if explicit_count == 0 {
		receiver_id := tc.a.child(&callee, 0)
		receiver_type := unalias_and_unwrap_pointer_type(tc.resolve_type(receiver_id))
		if array_type := array_like_type_for_method(receiver_type, 'sort') {
			elem_type := unalias_type(array_type.elem_type)
			if elem_type is Struct && '${elem_type.name}.<' !in tc.fn_ret_types {
				tc.record_error_at(.call_arg_mismatch,
					'custom sorting condition must be supplied for type `${elem_type.name}`', id, tc.method_call_name_pos(node,
					callee))
			}
		}
		return
	}
	arg_id := tc.call_arg_value(tc.a.child(&node, 1))
	arg := tc.a.nodes[int(arg_id)]
	method_pos := tc.method_call_name_pos(node, callee)
	if arg.kind != .infix {
		tc.record_error_at(.call_arg_mismatch, '`.sort()` can only use `<` or `>` comparison', id,
			method_pos)
		tc.push_array_dsl_scope(node, 'array.sort')
		tc.check_node(arg_id)
		tc.pop_scope()
		return
	}
	if arg.op !in [.lt, .gt] {
		tc.record_error_at(.call_arg_mismatch, '`.sort()` can only use `<` or `>` comparison', id,
			method_pos)
	}
	lhs_id := tc.a.child(&arg, 0)
	rhs_id := tc.a.child(&arg, 1)
	lhs_key := tc.expr_key(lhs_id)
	if lhs_key.len > 0 && lhs_key == tc.expr_key(rhs_id) {
		tc.record_error_at(.call_arg_mismatch, '`.sort()` cannot use same argument', id, method_pos)
	}
	if invalid_id := tc.sort_first_invalid_ident(arg_id) {
		invalid := tc.a.nodes[int(invalid_id)]
		tc.record_error_at(.unknown_ident, 'can not access external variable `${invalid.value}`',
			invalid_id, tc.node_value_diagnostic_pos(invalid_id))
	} else if !tc.sort_operand_has_valid_shape(lhs_id) || !tc.sort_operand_has_valid_shape(rhs_id) {
		tc.record_error_at(.call_arg_mismatch,
			'`.sort()` can only use `a` or `b` as argument, e.g. `arr.sort(a < b)`', id, method_pos)
		tc.record_error_at(.call_arg_mismatch,
			'`.sort()` can only use ident, index, selector or call as argument,\ne.g. `arr.sort(a < b)`, `arr.sort(a.id < b.id)`, `arr.sort(a[0] < b[0])`',
			id, method_pos)
	}
	tc.push_array_dsl_scope(node, 'array.sort')
	tc.check_node(arg_id)
	lhs_type := tc.resolve_type(lhs_id)
	rhs_type := tc.resolve_type(rhs_id)
	tc.pop_scope()
	if lhs_type.name().starts_with('thread ') && rhs_type !is Unknown
		&& !tc.type_compatible(rhs_type, lhs_type) {
		tc.record_error(.call_arg_mismatch,
			'infix expr: cannot use `${rhs_type.name()}` (right expression) as `thread ${rhs_type.name()}`',
			arg_id)
	}
}

fn (tc &TypeChecker) sort_first_invalid_ident(id flat.NodeId) ?flat.NodeId {
	node := tc.a.nodes[int(id)]
	if node.kind == .ident && node.value !in ['a', 'b'] {
		return id
	}
	for i in 0 .. node.children_count {
		if invalid := tc.sort_first_invalid_ident(tc.a.child(&node, i)) {
			return invalid
		}
	}
	return none
}

fn (tc &TypeChecker) sort_operand_has_valid_shape(id flat.NodeId) bool {
	mut node := tc.a.nodes[int(id)]
	for node.kind == .paren && node.children_count > 0 {
		node = tc.a.nodes[int(tc.a.child(&node, 0))]
	}
	return node.kind in [.ident, .index, .selector, .call]
}

fn (tc &TypeChecker) expr_is_direct_fn_value(id flat.NodeId) bool {
	node := tc.a.nodes[int(id)]
	if tc.fn_value_shadowed_by_value(node) {
		return false
	}
	if _ := tc.fn_value_key(node) {
		return true
	}
	return false
}

fn (tc &TypeChecker) array_insert_value_compatible(value_id flat.NodeId, value_type Type, array_type Array, receiver_type Type) bool {
	clean_value := unalias_type(value_type)
	clean_elem := unalias_type(array_type.elem_type)
	if clean_elem is ArrayFixed
		&& (clean_value is Array || tc.a.nodes[int(value_id)].kind == .array_literal) {
		return false
	}
	return tc.expr_compatible(value_id, value_type, array_type.elem_type)
		|| tc.type_compatible(value_type, receiver_type)
}

fn (tc &TypeChecker) array_insert_value_type_name(value_id flat.NodeId, value_type Type) string {
	value := tc.a.nodes[int(value_id)]
	if value.kind == .array_literal {
		return '[]${tc.array_literal_elem_type(value).name()}'
	}
	return tc.diagnostic_expr_type_name(value_id, value_type)
}

fn (mut tc TypeChecker) check_builtin_array_mutable_receiver(receiver_id flat.NodeId) {
	if !tc.valid_node_id(receiver_id) || tc.mut_receiver_expr_is_mutable_lvalue(receiver_id) {
		return
	}
	receiver := tc.a.nodes[int(receiver_id)]
	if receiver.kind != .ident || receiver.value.len == 0 {
		if tc.should_diagnose(receiver_id) {
			tc.record_error_at(.call_arg_mismatch, 'cannot pass expression as `mut`', receiver_id,
				tc.mutable_receiver_expression_pos(receiver_id))
		}
		return
	}
	tc.record_error(.call_arg_mismatch,
		'`${receiver.value}` is immutable, declare it with `mut` to make it mutable', receiver_id)
}

fn (tc &TypeChecker) mutable_receiver_expression_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	if node.kind == .call && node.children_count > 0 {
		callee := tc.a.child_node(node, 0)
		if callee.kind == .selector {
			return tc.method_call_name_pos(*node, *callee)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) method_call_name_pos(call flat.Node, selector flat.Node) token.Pos {
	file := tc.a.source_files[selector.pos.id] or { return selector.pos }
	source := tc.source_texts_by_file[file.name] or { return selector.pos }
	mut start := int_max(0, selector.pos.offset)
	if selector.children_count > 0 {
		receiver := tc.a.child_node(&selector, 0)
		start = int_max(start, receiver.pos.end)
	}
	mut end := int_min(call.pos.end, source.len)
	if end <= start {
		end = int_min(source.len, selector.pos.end + 2)
	}
	if start < end {
		if relative := source[start..end].index(selector.value) {
			name_start := start + relative
			if open_relative := source[name_start..end].index('(') {
				mut depth := 0
				for index := name_start + open_relative; index < end; index++ {
					if source[index] == `(` {
						depth++
					} else if source[index] == `)` {
						depth--
						if depth == 0 {
							return token.new_span(selector.pos.id, name_start, index + 1)
						}
					}
				}
			}
		}
	}
	return tc.node_value_diagnostic_pos(tc.a.child(&call, 0))
}

fn (tc &TypeChecker) mut_optional_pointer_arg_compatible(actual Type, expected Type) bool {
	if actual !is OptionType {
		return false
	}
	actual_option := actual as OptionType
	if expected !is Pointer {
		return false
	}
	expected_pointer := expected as Pointer
	actual_payload := actual_option.base_type
	expected_option_type := expected_pointer.base_type
	if actual_payload !is Pointer {
		return false
	}
	actual_pointer := actual_payload as Pointer
	if expected_option_type !is OptionType {
		return false
	}
	expected_option := expected_option_type as OptionType
	return tc.type_compatible(actual_pointer.base_type, expected_option.base_type)
}

fn enum_from_input_param(typ Type) bool {
	return typ is Unknown && typ.reason == 'enum from input'
}

fn (tc &TypeChecker) is_generic_enum_from_call(node flat.Node) bool {
	if node.children_count == 0 {
		return false
	}
	fn_node := tc.a.child_node(&node, 0)
	if fn_node.kind != .selector || fn_node.value != 'from' || fn_node.children_count == 0 {
		return false
	}
	base_node := tc.a.child_node(fn_node, 0)
	return base_node.kind == .ident && base_node.value in tc.fn_context.generic_params
}

fn enum_from_input_arg_compatible(typ Type) bool {
	clean := fn_param_unalias_type(typ)
	return clean is Unknown || clean is String || clean.is_integer()
}

fn (tc &TypeChecker) shared_arg_pointer_compatible(actual Type, expected Type) bool {
	clean := fn_param_unalias_type(actual)
	if clean is Pointer {
		return tc.type_compatible(clean.base_type, expected)
	}
	return false
}

fn (tc &TypeChecker) unresolved_array_dsl_call_name(node flat.Node) string {
	if node.children_count == 0 {
		return ''
	}
	callee := tc.a.child_node(&node, 0)
	if callee.kind != .selector || callee.children_count == 0 {
		return ''
	}
	name := 'array.${callee.value}'
	return if is_array_dsl_call_name(name) { name } else { '' }
}

fn (tc &TypeChecker) chan_try_pop_destination_is_valid(arg_id flat.NodeId, actual Type) bool {
	if int(arg_id) < 0 || int(arg_id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(arg_id)]
	if node.kind == .paren && node.children_count > 0 {
		return tc.chan_try_pop_destination_is_valid(tc.a.child(&node, 0), actual)
	}
	if node.kind == .prefix && node.op == .amp {
		if node.children_count == 0 {
			return false
		}
		child_id := tc.a.child(&node, 0)
		return tc.expr_can_take_address(child_id) && tc.expr_root_is_mutable_lvalue(child_id)
	}
	if actual is Pointer {
		return true
	}
	return tc.expr_can_take_address(arg_id) && tc.expr_root_is_mutable_lvalue(arg_id)
}

fn json_runtime_voidptr_accepts_arg(name string, param_idx int, expected Type, actual Type) bool {
	if param_idx != 0 || name !in ['json.decode', 'json.encode', 'json.encode_pretty'] {
		return false
	}
	if expected is Pointer {
		if expected.base_type is Void {
			return type_has_runtime_value(actual)
		}
	}
	return false
}

fn free_array_arg_compatible(name string, param_idx int, expected Type, actual Type) bool {
	if param_idx != 0 || name !in ['free', 'builtin.free'] || !fn_param_is_voidptr_type(expected) {
		return false
	}
	mut clean := unwrap_pointer(actual)
	if clean is Alias {
		clean = clean.base_type
	}
	return clean is Array
}

fn (tc &TypeChecker) c_call_arg_compatible(name string, arg_id flat.NodeId, expected Type, actual Type) bool {
	if !name.starts_with('C.') {
		return false
	}
	clean := fn_param_unalias_type(expected)
	if clean.is_integer() {
		actual_clean := fn_param_unalias_type(actual)
		return actual_clean.is_integer()
			|| (actual_clean is Primitive && actual_clean.props.has(.boolean))
			|| tc.c_scalar_byte_literal_arg(arg_id)
	}
	if clean is Pointer {
		base := fn_param_unalias_type(clean.base_type)
		if base is Char || (base is Primitive && base.name() == 'u8') {
			return tc.c_literal_arg(arg_id)
		}
		// C APIs commonly spell an opaque pointer parameter as `voidptr` and
		// accept a V struct value as storage (for example gg's native drawing
		// config structs). Scalars still require an explicit `voidptr(...)` cast.
		if base is Void && fn_param_unalias_type(actual) is Struct {
			return tc.expr_can_take_address(arg_id)
		}
	}
	return false
}

fn (tc &TypeChecker) c_scalar_byte_literal_arg(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .char_literal {
		return c_literal_is_single_byte(node.value)
	}
	if node.kind == .paren && node.children_count > 0 {
		return tc.c_scalar_byte_literal_arg(tc.a.child(&node, 0))
	}
	return false
}

fn c_literal_is_single_byte(value string) bool {
	if !value.starts_with('c:') {
		return false
	}
	literal := value[2..]
	if literal.len == 1 {
		return true
	}
	if literal.len < 2 || literal[0] != `\\` {
		return false
	}
	if literal.len == 2 {
		return true
	}
	if literal[1] == `x` {
		mut decoded := 0
		for ch in literal[2..].bytes() {
			digit := if ch >= `0` && ch <= `9` {
				int(ch - `0`)
			} else if ch >= `a` && ch <= `f` {
				int(ch - `a`) + 10
			} else if ch >= `A` && ch <= `F` {
				int(ch - `A`) + 10
			} else {
				return false
			}
			decoded = decoded * 16 + digit
			if decoded > 0xff {
				return false
			}
		}
		return true
	}
	if literal[1] < `0` || literal[1] > `7` || literal.len > 4 {
		return false
	}
	mut decoded := 0
	for digit in literal[1..].bytes() {
		if digit < `0` || digit > `7` {
			return false
		}
		decoded = decoded * 8 + int(digit - `0`)
	}
	return decoded <= 0xff
}

fn (tc &TypeChecker) c_literal_arg(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .char_literal {
		return node.value.starts_with('c:')
	}
	if node.kind == .paren && node.children_count > 0 {
		return tc.c_literal_arg(tc.a.child(&node, 0))
	}
	return false
}

fn voidptr_arg_compatible(expected Type, actual Type) bool {
	if !fn_param_is_voidptr_type(expected) {
		return false
	}
	return fn_param_is_voidptr_type(actual) || voidptr_arg_type_passes_direct(actual)
}

fn voidptr_arg_type_passes_direct(typ Type) bool {
	clean := fn_param_unalias_type(typ)
	return clean is Pointer || clean is Nil || clean.name() == 'voidptr'
}

fn variadic_elem_accepts_any(typ Type) bool {
	if typ is Pointer {
		return typ.base_type is Void
	}
	return false
}

fn variadic_any_arg_has_value(typ Type) bool {
	return type_has_runtime_value(typ)
}

fn type_has_runtime_value(typ Type) bool {
	if typ is OptionType {
		return typ.base_type !is Void
	}
	if typ is ResultType {
		return typ.base_type !is Void
	}
	if typ is MultiReturn {
		return false
	}
	return typ !is Void && typ !is None && typ !is Unknown && !type_contains_unknown(typ)
}

fn (tc &TypeChecker) arg_is_spread(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .prefix && (node.value == '...' || node.op == .none) && node.children_count > 0 {
		return true
	}
	return false
}

fn (tc &TypeChecker) spread_arg_value(id flat.NodeId) ?flat.NodeId {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .prefix && (node.value == '...' || node.op == .none) && node.children_count > 0 {
		return tc.a.child(&node, 0)
	}
	return none
}

fn (mut tc TypeChecker) call_has_spread_covering_fixed_variadic_args(node flat.Node, info CallInfo, ctx_count int, ctx_omitted bool) bool {
	if !info.is_variadic || info.params.len == 0 {
		return false
	}
	if info.params[info.params.len - 1] !is Array {
		return false
	}
	for i in 1 + info.arg_offset .. node.children_count {
		if _ := tc.spread_arg_value(tc.a.child(&node, i)) {
			arg_shift := if ctx_omitted { ctx_count } else { 0 }
			param_idx := i - 1 - info.arg_offset + (if info.has_receiver { 1 } else { 0 }) +
				arg_shift
			if param_idx >= 0 && param_idx < info.params.len - 1 {
				return true
			}
		}
	}
	return false
}

fn (tc &TypeChecker) spread_elem_compatible(actual Type, expected Type) bool {
	return tc.receiver_compatible(actual, expected) || tc.type_compatible(actual, expected)
}

fn (tc &TypeChecker) variadic_spread_arg_compatible(actual Type, expected_array Array) bool {
	if actual_array := array_type_from_receiver(actual) {
		if actual_array.elem_type.name() != expected_array.elem_type.name() {
			return false
		}
	}
	expected := Type(expected_array)
	if tc.receiver_compatible(actual, expected) || tc.type_compatible(actual, expected) {
		return true
	}
	actual_elem := array_like_elem_type(unwrap_pointer(actual)) or { return false }
	return tc.spread_elem_compatible(actual_elem, expected_array.elem_type)
}

fn (tc &TypeChecker) fixed_variadic_spread_tail_compatible(actual_elem Type, expected_array Array) bool {
	expected := Type(expected_array)
	if tc.spread_elem_compatible(actual_elem, expected) {
		return true
	}
	return tc.spread_elem_compatible(actual_elem, expected_array.elem_type)
}

fn (mut tc TypeChecker) check_spread_over_fixed_variadic_tail(call_id flat.NodeId, node flat.Node, info CallInfo, arg_child_idx int, param_idx int) bool {
	if !info.is_variadic || info.params.len == 0 || param_idx < 0
		|| param_idx >= info.params.len - 1 {
		return false
	}
	variadic_raw := info.params[info.params.len - 1]
	variadic_array := if variadic_raw is Array {
		variadic_raw
	} else {
		return false
	}
	spread_id := tc.spread_arg_value(tc.a.child(&node, arg_child_idx)) or { return false }
	actual := tc.resolve_expr(spread_id, variadic_raw)
	actual_elem := array_like_elem_type(unwrap_pointer(actual)) or {
		tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual.name()}` as argument ${
			param_idx + 1} to `${tc.call_display_name(node)}`; expected `${variadic_raw.name()}`',
			call_id)
		return true
	}
	for fixed_idx in param_idx .. info.params.len - 1 {
		expected := info.params[fixed_idx]
		if !tc.spread_elem_compatible(actual_elem, expected) {
			tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual.name()}` as argument ${
				param_idx + 1} to `${tc.call_display_name(node)}`; expected `${expected.name()}`',
				call_id)
			break
		}
	}
	if !tc.fixed_variadic_spread_tail_compatible(actual_elem, variadic_array) {
		tc.type_mismatch(.call_arg_mismatch, 'cannot use `${actual.name()}` as argument ${
			param_idx + 1} to `${tc.call_display_name(node)}`; expected `${variadic_raw.name()}`',
			call_id)
	}
	return true
}

fn (tc &TypeChecker) variadic_any_arg_is_scalar(id flat.NodeId) bool {
	if tc.arg_is_spread(id) {
		return false
	}
	if !tc.valid_node_id(id) {
		return false
	}
	if tc.a.nodes[int(id)].kind == .enum_val {
		return false
	}
	actual := tc.resolve_type(id)
	if !variadic_any_arg_has_value(actual) {
		return false
	}
	if _ := array_type_from_receiver(actual) {
		return false
	}
	return true
}

fn (mut tc TypeChecker) specialized_plain_generic_call_info(node flat.Node, info CallInfo) CallInfo {
	if tc.call_has_explicit_generic_type_args(node) {
		return info
	}
	generic_params := tc.fn_generic_params[info.name] or { return info }
	param_texts := tc.fn_param_type_texts[info.name] or { return info }
	if generic_params.len == 0 || node.children_count <= 1
		|| tc.call_has_explicit_generic_args(node) {
		return info
	}
	mut inferred := map[string]string{}
	mut inferred_types := map[string]Type{}
	mut first_param_idx := 0
	if info.has_receiver && param_texts.len > 0 {
		fn_node := tc.a.child_node(&node, 0)
		if fn_node.kind == .selector && fn_node.children_count > 0 {
			recv_id := tc.a.child(fn_node, 0)
			resolved_receiver := tc.resolve_type(recv_id)
			// resolve_generic_struct_method has already substituted receiver type
			// arguments. Keep that declared specialization for aliases such as
			// `type Vec4 = vec.Vec4[f32]`; a short struct initializer can otherwise
			// make the expression cache look like `Vec4[int]` from its literal fields.
			actual := if info.name.contains('[') && info.params.len > 0
				&& !generic_semantic_type_has_placeholder(info.params[0]) {
				info.params[0]
			} else {
				resolved_receiver
			}
			tc.infer_generic_type_text_from_type(param_texts[0], actual, generic_params, mut
				inferred)
			tc.infer_generic_type_value_from_type(param_texts[0], actual, generic_params, mut
				inferred_types)
			first_param_idx = 1
		}
	}
	for param_idx in first_param_idx .. param_texts.len {
		arg_idx := param_idx - first_param_idx + 1 + info.arg_offset
		if arg_idx >= node.children_count {
			break
		}
		if info.is_variadic && param_idx == param_texts.len - 1 {
			elem_text := generic_variadic_elem_param_text(param_texts[param_idx])
			for call_arg_idx in arg_idx .. node.children_count {
				arg_id := tc.call_arg_value(tc.a.child(&node, call_arg_idx))
				if spread_id := tc.spread_arg_child(arg_id) {
					actual := tc.resolve_type(spread_id)
					tc.infer_generic_type_text_from_type(param_texts[param_idx], actual,
						generic_params, mut inferred)
					continue
				}
				actual := tc.resolve_type(arg_id)
				tc.infer_generic_type_text_from_type(elem_text, actual, generic_params, mut
					inferred)
			}
			break
		}
		arg_id := tc.call_arg_value(tc.a.child(&node, arg_idx))
		actual := tc.resolve_type(arg_id)
		tc.infer_generic_type_text_from_type(param_texts[param_idx], actual, generic_params, mut
			inferred)
		tc.infer_generic_type_value_from_type(param_texts[param_idx], actual, generic_params, mut
			inferred_types)
	}
	mut concrete_args := []string{cap: generic_params.len}
	mut concrete_types := []Type{cap: generic_params.len}
	for param in generic_params {
		arg := inferred[param] or { return info }
		concrete_args << arg
		// Retain the caller-side semantic type. Re-parsing a bare caller type such
		// as `User` in the generic declaration's module would incorrectly turn it
		// into `json2.User`.
		concrete_types << inferred_types[param] or {
			tc.type_from_known_symbol(arg) or { tc.parse_type(arg) }
		}
	}
	mut sub_params := []Type{}
	for i, param_text in param_texts {
		if generic_type_application(param_text) {
			// Named applications such as `Box[T]` lose their arguments in the
			// open parsed type, so retain the textual reconstruction for them.
			sub_params << tc.parse_fn_signature_type(info.name, subst_generic_text(param_text,
				concrete_args, generic_params))
		} else if i < info.params.len {
			sub_params << tc.substitute_generic_type_values(info.params[i], concrete_types,
				generic_params)
		} else {
			sub_params << tc.parse_fn_signature_type(info.name, subst_generic_text(param_text,
				concrete_args, generic_params))
		}
	}
	ret_text := tc.fn_ret_type_texts[info.name] or { '' }
	sub_ret := if ret_text.len > 0 {
		if generic_type_application(ret_text) {
			tc.parse_fn_signature_type(info.name, subst_generic_text(ret_text, concrete_args,
				generic_params))
		} else {
			tc.substitute_generic_type_values(info.return_type, concrete_types, generic_params)
		}
	} else {
		tc.substitute_generic_type_values(info.return_type, concrete_types, generic_params)
	}
	return CallInfo{
		name:                 info.name
		params:               sub_params
		shared_params:        info.shared_params.clone()
		return_type:          sub_ret
		has_receiver:         info.has_receiver
		is_variadic:          info.is_variadic
		is_c_variadic:        info.is_c_variadic
		params_known:         true
		has_implicit_veb_ctx: info.has_implicit_veb_ctx
		arg_offset:           info.arg_offset
	}
}

fn (tc &TypeChecker) call_has_explicit_generic_args(node flat.Node) bool {
	if node.value.len > 0 {
		return true
	}
	if node.children_count == 0 {
		return false
	}
	fn_node := tc.a.child_node(&node, 0)
	return fn_node.kind == .index && tc.generic_call_type_arg_names(fn_node).len > 0
}

fn (tc &TypeChecker) call_has_explicit_generic_type_args(node flat.Node) bool {
	if node.children_count == 0 {
		return false
	}
	fn_node := tc.a.child_node(&node, 0)
	return fn_node.kind == .index && fn_node.value != 'range'
		&& tc.generic_call_type_arg_names(fn_node).len > 0
}

fn generic_variadic_elem_param_text(param_text string) string {
	clean := trimmed_space(param_text)
	if clean.starts_with('...') {
		return trimmed_space(clean[3..])
	}
	if clean.starts_with('[]') {
		return trimmed_space(clean[2..])
	}
	return clean
}

fn (tc &TypeChecker) parse_fn_signature_type(name string, typ string) Type {
	decl_file := tc.fn_type_files[name] or { return tc.parse_type(typ) }
	decl_module := tc.fn_type_modules[name] or { tc.file_modules[decl_file] or { tc.cur_module } }
	mut scoped := tc.fork_type_parse_view(decl_file, decl_module)
	// Fully qualify symbols owned by the declaration module before parsing the
	// substituted signature. A bare concrete type can belong to the generic
	// call site (notably a type from `main`), so resolution deliberately leaves
	// that spelling bare and the neutral parse context preserves its authority.
	return scoped.parse_resolution_type(typ)
}

fn (mut tc TypeChecker) infer_generic_type_text_from_type(param_text string, actual Type, generic_params []string, mut inferred map[string]string) {
	clean := trimmed_space(param_text)
	if clean.len == 0 {
		return
	}
	if clean.starts_with('&') {
		if actual is Pointer {
			tc.infer_generic_type_text_from_type(clean[1..], actual.base_type, generic_params, mut
				inferred)
		} else {
			tc.infer_generic_type_text_from_type(clean[1..], actual, generic_params, mut inferred)
		}
		return
	}
	if clean.starts_with('mut ') {
		tc.infer_generic_type_text_from_type(clean[4..], actual, generic_params, mut inferred)
		return
	}
	if clean.starts_with('...') {
		if actual is Array {
			tc.infer_generic_type_text_from_type(clean[3..], actual.elem_type, generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('[]') {
		if actual is Array {
			tc.infer_generic_type_text_from_type(clean[2..], actual.elem_type, generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('?') {
		if actual is OptionType {
			tc.infer_generic_type_text_from_type(clean[1..], actual.base_type, generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('!') {
		if actual is ResultType {
			tc.infer_generic_type_text_from_type(clean[1..], actual.base_type, generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('fn(') || clean.starts_with('fn (') {
		if actual is FnType {
			tc.infer_generic_fn_type_text_from_type(clean, actual, generic_params, mut inferred)
		}
		return
	}
	if generic_type_application(clean) {
		actual_text := tc.generic_infer_type_text(actual)
		tc.infer_generic_type_text_from_text(clean, actual_text, generic_params, mut inferred)
		return
	}
	for param in generic_params {
		if clean == param && param !in inferred {
			mut actual_text := tc.generic_infer_type_text(actual)
			if actual_text == 'unknown' || actual_text == 'generic' {
				actual_text = param
			}
			inferred[param] = actual_text
			return
		}
	}
}

// infer_generic_type_value_from_type retains the resolved caller-side Type for
// each generic placeholder. The text inference remains useful for reconstructing
// named applications, but semantic substitution must not parse a caller-local or
// canonical qualified name again in the callee's import context.
fn (mut tc TypeChecker) infer_generic_type_value_from_type(param_text string, actual Type, generic_params []string, mut inferred map[string]Type) {
	clean := trimmed_space(param_text)
	if clean.len == 0 {
		return
	}
	if clean.starts_with('&') {
		if actual is Pointer {
			tc.infer_generic_type_value_from_type(clean[1..], actual.base_type, generic_params, mut
				inferred)
		} else {
			tc.infer_generic_type_value_from_type(clean[1..], actual, generic_params, mut inferred)
		}
		return
	}
	if clean.starts_with('mut ') {
		tc.infer_generic_type_value_from_type(clean[4..], actual, generic_params, mut inferred)
		return
	}
	if clean.starts_with('...') {
		if actual is Array {
			tc.infer_generic_type_value_from_type(clean[3..], actual.elem_type, generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('[]') {
		if actual is Array {
			tc.infer_generic_type_value_from_type(clean[2..], actual.elem_type, generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('?') {
		if actual is OptionType {
			tc.infer_generic_type_value_from_type(clean[1..], actual.base_type, generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('!') {
		if actual is ResultType {
			tc.infer_generic_type_value_from_type(clean[1..], actual.base_type, generic_params, mut
				inferred)
		}
		return
	}
	for param in generic_params {
		if clean == param && param !in inferred {
			inferred[param] = actual
			return
		}
	}
}

fn (tc &TypeChecker) generic_infer_type_text(actual Type) string {
	if actual is Unknown {
		if name := generic_placeholder_from_unknown(actual) {
			return name
		}
	}
	return actual.name()
}

fn (mut tc TypeChecker) infer_generic_type_text_from_text(param_text string, actual_text string, generic_params []string, mut inferred map[string]string) {
	clean := trimmed_space(param_text)
	actual := trimmed_space(actual_text)
	if clean.len == 0 || actual.len == 0 {
		return
	}
	for param in generic_params {
		if clean == param && param !in inferred {
			inferred[param] = if actual == 'unknown' || actual == 'generic' { param } else { actual }
			return
		}
	}
	if clean.starts_with('&') || actual.starts_with('&') {
		if clean.starts_with('&') && actual.starts_with('&') {
			tc.infer_generic_type_text_from_text(clean[1..], actual[1..], generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('mut ') {
		tc.infer_generic_type_text_from_text(clean[4..], actual.trim_left('&'), generic_params, mut
			inferred)
		return
	}
	if clean.starts_with('...') || actual.starts_with('...') {
		if clean.starts_with('...') && actual.starts_with('...') {
			tc.infer_generic_type_text_from_text(clean[3..], actual[3..], generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('[]') || actual.starts_with('[]') {
		if clean.starts_with('[]') && actual.starts_with('[]') {
			tc.infer_generic_type_text_from_text(clean[2..], actual[2..], generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('?') || actual.starts_with('?') {
		if clean.starts_with('?') && actual.starts_with('?') {
			tc.infer_generic_type_text_from_text(clean[1..], actual[1..], generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('!') || actual.starts_with('!') {
		if clean.starts_with('!') && actual.starts_with('!') {
			tc.infer_generic_type_text_from_text(clean[1..], actual[1..], generic_params, mut
				inferred)
		}
		return
	}
	if clean.starts_with('map[') || actual.starts_with('map[') {
		if !clean.starts_with('map[') || !actual.starts_with('map[') {
			return
		}
		clean_end := find_matching_bracket(clean, 3)
		actual_end := find_matching_bracket(actual, 3)
		if clean_end >= clean.len || actual_end >= actual.len {
			return
		}
		tc.infer_generic_type_text_from_text(clean[4..clean_end], actual[4..actual_end],
			generic_params, mut inferred)
		tc.infer_generic_type_text_from_text(clean[clean_end + 1..], actual[actual_end + 1..],
			generic_params, mut inferred)
		return
	}
	if clean.starts_with('[') || actual.starts_with('[') {
		if !clean.starts_with('[') || !actual.starts_with('[') {
			return
		}
		clean_end := find_matching_bracket(clean, 0)
		actual_end := find_matching_bracket(actual, 0)
		if clean_end >= clean.len || actual_end >= actual.len
			|| clean[..clean_end + 1] != actual[..actual_end + 1] {
			return
		}
		tc.infer_generic_type_text_from_text(clean[clean_end + 1..], actual[actual_end + 1..],
			generic_params, mut inferred)
		return
	}
	param_base, param_args, param_is_generic := generic_type_application_parts(clean)
	actual_base, actual_args, actual_is_generic := generic_type_application_parts(actual)
	if param_is_generic || actual_is_generic {
		if !param_is_generic || !actual_is_generic || param_args.len != actual_args.len
			|| !tc.generic_type_base_matches(param_base, actual_base) {
			return
		}
		for i in 0 .. param_args.len {
			tc.infer_generic_type_text_from_text(param_args[i], actual_args[i], generic_params, mut
				inferred)
		}
	}
}

fn (mut tc TypeChecker) infer_generic_fn_type_text_from_type(param_text string, actual FnType, generic_params []string, mut inferred map[string]string) {
	params_start := param_text.index_u8(`(`) + 1
	mut depth := 1
	mut params_end := params_start
	for params_end < param_text.len {
		if param_text[params_end] == `(` {
			depth++
		} else if param_text[params_end] == `)` {
			depth--
			if depth == 0 {
				break
			}
		}
		params_end++
	}
	if params_end >= param_text.len {
		return
	}
	parts := split_params(param_text[params_start..params_end])
	for i, part in parts {
		if i >= actual.params.len {
			break
		}
		tc.infer_generic_type_text_from_type(normalize_fn_type_param_text(part), fn_param_type(actual,
			i), generic_params, mut inferred)
	}
	ret := trimmed_space(param_text[params_end + 1..])
	if ret.len > 0 {
		tc.infer_generic_type_text_from_type(ret, actual.return_type, generic_params, mut inferred)
	}
}

// array_map_return_elem_type supports array map return elem type handling for TypeChecker.
fn (mut tc TypeChecker) array_map_return_elem_type(node flat.Node) Type {
	if node.children_count < 2 {
		return Type(void_)
	}
	tc.push_array_dsl_scope(node, 'array.map')
	arg_id := tc.call_arg_value(tc.a.child(&node, 1))
	elem_type := tc.resolve_type(arg_id)
	tc.pop_scope()
	if fn_typ := fn_type_from_type(elem_type) {
		if !tc.expr_uses_ident(arg_id, 'it') {
			return fn_typ.return_type
		}
	}
	if elem_type is Void || elem_type is Unknown {
		return Type(void_)
	}
	return elem_type
}

fn (tc &TypeChecker) expr_uses_ident(id flat.NodeId, name string) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len || name.len == 0 {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .ident && node.value == name {
		return true
	}
	if node.kind == .lambda_expr && node.children_count > 1 {
		first := tc.a.child_node(&node, 0)
		if first.kind == .ident && first.value == name {
			return false
		}
	}
	for i in 0 .. node.children_count {
		if tc.expr_uses_ident(tc.a.child(&node, i), name) {
			return true
		}
	}
	return false
}

// array_map_result_borrows_element reports whether a mapper result must be made
// independent before its source array is destroyed. Opaque function values are handled
// conservatively because their body cannot be inspected at the call site.
fn (tc &TypeChecker) array_map_result_borrows_element(node flat.Node) bool {
	if node.children_count < 2 {
		return false
	}
	arg_id := tc.call_arg_value(tc.a.child(&node, 1))
	arg := tc.a.nodes[int(arg_id)]
	if arg.kind == .fn_literal {
		return true
	}
	mut body_id := arg_id
	mut elem_name := 'it'
	if arg.kind == .lambda_expr && arg.children_count > 0 {
		body_id = tc.a.child(&arg, arg.children_count - 1)
		if arg.children_count > 1 {
			param := tc.a.child_node(&arg, 0)
			if param.kind == .ident && param.value.len > 0 {
				elem_name = param.value
			}
		}
	} else if _ := fn_type_from_type(tc.resolve_type(arg_id)) {
		return true
	}
	return tc.array_map_expr_references_ident(body_id, elem_name)
		&& !tc.ownership_expr_creates_owned_value(body_id)
}

fn (tc &TypeChecker) array_map_expr_references_ident(id flat.NodeId, name string) bool {
	if !tc.valid_node_id(id) || name.len == 0 {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .ident && node.value == name {
		return true
	}
	if node.kind == .lambda_expr && node.children_count > 1 {
		first := tc.a.child_node(&node, 0)
		if first.kind == .ident && first.value == name {
			return false
		}
	}
	for i in 0 .. node.children_count {
		if tc.array_map_expr_references_ident(tc.a.child(&node, i), name) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) array_contains_elem_type(base_node flat.Node, array_type Array) Type {
	if base_node.kind == .selector && base_node.value == 'args' && base_node.children_count > 0 {
		parent := tc.a.child_node(&base_node, 0)
		if parent.kind == .ident && parent.value == 'os' {
			return Type(String{})
		}
	}
	return array_type.elem_type
}

fn (tc &TypeChecker) is_os_args_contains_call(node flat.Node) bool {
	if node.children_count == 0 {
		return false
	}
	fn_node := tc.a.child_node(&node, 0)
	if fn_node.kind != .selector || fn_node.value != 'contains' || fn_node.children_count == 0 {
		return false
	}
	base_node := tc.a.child_node(fn_node, 0)
	if base_node.kind != .selector || base_node.value != 'args' || base_node.children_count == 0 {
		return false
	}
	parent := tc.a.child_node(base_node, 0)
	return parent.kind == .ident && parent.value == 'os'
}

fn (tc &TypeChecker) pointer_builtin_method_call_info(base_type Type, method string) ?CallInfo {
	receiver := pointer_builtin_receiver_name(base_type)
	if receiver.len == 0 {
		return none
	}
	if receiver in ['charptr', 'byteptr'] && method in ['vstring', 'vstring_with_len'] {
		mut params := tarr1(base_type)
		if method == 'vstring_with_len' {
			params << Type(int_)
		}
		return CallInfo{
			name:         '${receiver}.${method}'
			params:       params
			return_type:  Type(string_)
			has_receiver: true
			params_known: true
		}
	}
	if receiver in ['byteptr', 'voidptr'] && method == 'vbytes' {
		return CallInfo{
			name:         '${receiver}.${method}'
			params:       [base_type, Type(int_)]
			return_type:  Type(Array{
				elem_type: Type(u8_)
			})
			has_receiver: true
			params_known: true
		}
	}
	if receiver == 'voidptr' && method == 'hex_full' {
		return CallInfo{
			name:         'voidptr.hex_full'
			params:       [base_type]
			return_type:  Type(string_)
			has_receiver: true
			params_known: true
		}
	}
	return none
}

fn pointer_builtin_receiver_name(typ Type) string {
	if typ is Alias {
		if typ.name in ['charptr', 'byteptr', 'voidptr'] {
			return typ.name
		}
		return pointer_builtin_receiver_name(typ.base_type)
	}
	if typ is Pointer {
		base := typ.base_type
		if base is Alias {
			if base.name == 'byte' {
				return 'byteptr'
			}
			return pointer_builtin_receiver_name(base)
		}
		if base is Char {
			return 'charptr'
		}
		if base is Void {
			return 'voidptr'
		}
		if base is Primitive && prim_name(base) == 'u8' {
			return 'byteptr'
		}
	}
	if typ is Primitive && prim_name(typ) == 'u8' {
		return 'byteptr'
	}
	return ''
}

// min_required_arg_count supports min required arg count handling for TypeChecker.
fn (tc &TypeChecker) min_required_arg_count(info CallInfo) int {
	if info.is_variadic && info.params.len > 0 {
		return info.params.len - 1
	}
	mut n := info.params.len
	for n > 0 {
		param := info.params[n - 1]
		if param is OptionType || tc.is_params_struct_type(param) {
			n--
			continue
		}
		break
	}
	return n
}

fn c_variadic_fixed_param_count(info CallInfo) int {
	if info.is_c_variadic && info.params.len > 0 && info.params[info.params.len - 1] is Array {
		return info.params.len - 1
	}
	return info.params.len
}

fn (tc &TypeChecker) is_params_struct_type(typ Type) bool {
	if typ is Struct {
		if typ.name in tc.params_structs {
			return true
		}
		base, _, is_generic := generic_type_application_parts(typ.name)
		if is_generic
			&& (base in tc.params_structs || base.all_after_last('.') in tc.params_structs) {
			return true
		}
		qname := tc.qualify_name(typ.name)
		return qname in tc.params_structs
	}
	if typ is Alias {
		return tc.is_params_struct_type(typ.base_type)
	}
	// A `&Cfg` param (pointer to an `@[params]` struct, e.g. `audio.setup(desc
	// &C.saudio_desc)`) is still optional: a zero-arg or `key: value` call
	// constructs a default and passes its address, matching v1.
	if typ is Pointer {
		return tc.is_params_struct_type(typ.base_type)
	}
	return false
}

// call_arg_needs_array_dsl_scope updates call arg needs array dsl scope state for TypeChecker.
fn (tc &TypeChecker) call_arg_needs_array_dsl_scope(name string, param_idx int) bool {
	return param_idx == 1 && is_array_dsl_call_name(name)
}

fn (tc &TypeChecker) array_dsl_fn_arg_compatible(node flat.Node, info CallInfo, param_idx int, actual Type) bool {
	if param_idx != 1 {
		return false
	}
	if info.name == 'array.count' {
		return array_count_dsl_predicate_compatible(actual)
	}
	if !is_array_filter_or_map_call_name(info.name) {
		return false
	}
	fn_typ := fn_type_from_type(actual) or { return false }
	if fn_typ.params.len != 1 {
		return false
	}
	arr := tc.call_receiver_array_type(node) or { return false }
	param := fn_param_type(fn_typ, 0)
	if !tc.receiver_compatible(param, arr.elem_type)
		&& !tc.receiver_compatible(arr.elem_type, param) {
		return false
	}
	if is_array_filter_call_name(info.name) {
		return tc.type_compatible(fn_typ.return_type, Type(bool_))
	}
	return true
}

fn array_count_dsl_predicate_compatible(actual Type) bool {
	if actual is Alias {
		return array_count_dsl_predicate_compatible(actual.base_type)
	}
	return actual is Primitive
}

// is_array_dsl_call_name reports whether is array dsl call name applies in types.
fn is_array_dsl_call_name(name string) bool {
	if name.len < 9 || name.len > 12 || !has_array_dot_prefix(name) {
		return false
	}
	start := 'array.'.len
	len := name.len - start
	return match len {
		3 {
			(name[start] == `a` && ((name[start + 1] == `n` && name[start + 2] == `y`)
				|| (name[start + 1] == `l` && name[start + 2] == `l`)))
				|| (name[start] == `m` && name[start + 1] == `a` && name[start + 2] == `p`)
		}
		4 {
			name[start] == `s` && name[start + 1] == `o` && name[start + 2] == `r`
				&& name[start + 3] == `t`
		}
		5 {
			name[start] == `c` && name[start + 1] == `o` && name[start + 2] == `u`
				&& name[start + 3] == `n` && name[start + 4] == `t`
		}
		6 {
			(name[start] == `f` && name[start + 1] == `i` && name[start + 2] == `l`
				&& name[start + 3] == `t` && name[start + 4] == `e` && name[start + 5] == `r`)
				|| (name[start] == `s` && name[start + 1] == `o` && name[start + 2] == `r`
				&& name[start + 3] == `t` && name[start + 4] == `e` && name[start + 5] == `d`)
		}
		else {
			false
		}
	}
}

fn has_array_dot_prefix(name string) bool {
	return name[0] == `a` && name[1] == `r` && name[2] == `r` && name[3] == `a` && name[4] == `y`
		&& name[5] == `.`
}

fn is_array_filter_or_map_call_name(name string) bool {
	if name.len != 9 && name.len != 12 {
		return false
	}
	if !has_array_dot_prefix(name) {
		return false
	}
	start := 'array.'.len
	if name.len == 9 {
		return name[start] == `m` && name[start + 1] == `a` && name[start + 2] == `p`
	}
	return is_array_filter_method_name(name, start)
}

fn is_array_filter_call_name(name string) bool {
	return name.len == 12 && has_array_dot_prefix(name)
		&& is_array_filter_method_name(name, 'array.'.len)
}

fn is_array_filter_method_name(name string, start int) bool {
	return name[start] == `f` && name[start + 1] == `i` && name[start + 2] == `l`
		&& name[start + 3] == `t` && name[start + 4] == `e` && name[start + 5] == `r`
}

fn array_insert_prepend_many_param_idx(name string) int {
	if name.len != 12 && name.len != 13 {
		return -1
	}
	if !has_array_dot_prefix(name) {
		return -1
	}
	start := 'array.'.len
	if name.len == 12 {
		if name[start] == `i` && name[start + 1] == `n` && name[start + 2] == `s`
			&& name[start + 3] == `e` && name[start + 4] == `r` && name[start + 5] == `t` {
			return 2
		}
		return -1
	}
	if name[start] == `p` && name[start + 1] == `r` && name[start + 2] == `e`
		&& name[start + 3] == `p` && name[start + 4] == `e` && name[start + 5] == `n`
		&& name[start + 6] == `d` {
		return 1
	}
	return -1
}

fn is_map_keys_values_call_name(name string) bool {
	if name.len != 8 && name.len != 10 {
		return false
	}
	if name[0] != `m` || name[1] != `a` || name[2] != `p` || name[3] != `.` {
		return false
	}
	if name.len == 8 {
		return name[4] == `k` && name[5] == `e` && name[6] == `y` && name[7] == `s`
	}
	return name[4] == `v` && name[5] == `a` && name[6] == `l` && name[7] == `u` && name[8] == `e`
		&& name[9] == `s`
}

// call_explicit_arg_count updates call explicit arg count state for types.
fn call_explicit_arg_count(node flat.Node) int {
	if node.children_count <= 1 {
		return 0
	}
	mut n := 0
	for i in 1 .. node.children_count {
		if int(node.children_start) + i < 0 {
			continue
		}
		n++
	}
	return n
}

// push_array_dsl_scope updates push array dsl scope state for TypeChecker.
fn (mut tc TypeChecker) push_array_dsl_scope(node flat.Node, name string) {
	tc.push_scope()
	arr := tc.call_receiver_array_type(node) or { return }
	if is_array_sort_dsl_call_name(name) {
		tc.cur_scope.insert('a', arr.elem_type)
		tc.cur_scope.insert('b', arr.elem_type)
		$if ownership ? {
			tc.ownership_bind_array_dsl_element(node, 'a', arr.elem_type)
			tc.ownership_bind_array_dsl_element(node, 'b', arr.elem_type)
		}
		return
	}
	tc.cur_scope.insert('it', arr.elem_type)
	$if ownership ? {
		tc.ownership_bind_array_dsl_element(node, 'it', arr.elem_type)
	}
}

fn is_array_sort_dsl_call_name(name string) bool {
	if name.len != 10 && name.len != 12 {
		return false
	}
	if !has_array_dot_prefix(name) {
		return false
	}
	start := 'array.'.len
	if name[start] != `s` || name[start + 1] != `o` || name[start + 2] != `r`
		|| name[start + 3] != `t` {
		return false
	}
	return name.len == 10 || (name[start + 4] == `e` && name[start + 5] == `d`)
}

// call_receiver_array_type updates call receiver array type state for TypeChecker.
fn (tc &TypeChecker) call_receiver_array_type(node flat.Node) ?Array {
	if node.children_count == 0 {
		return none
	}
	fn_node := tc.a.child_node(&node, 0)
	if fn_node.kind != .selector || fn_node.children_count == 0 {
		return none
	}
	base_id := tc.a.child(fn_node, 0)
	if resolved := tc.expr_type(base_id) {
		if arr := call_receiver_array_from_type(resolved) {
			return arr
		}
	}
	base_node := tc.a.nodes[int(base_id)]
	if base_node.typ.len > 0 {
		if arr := call_receiver_array_from_type(tc.parse_resolution_type(base_node.typ)) {
			return arr
		}
	}
	if arr := call_receiver_array_from_type(tc.resolve_type(base_id)) {
		return arr
	}
	return none
}

fn call_receiver_array_from_type(typ Type) ?Array {
	return match typ {
		Array {
			typ
		}
		ArrayFixed {
			Array{
				elem_type: typ.elem_type
			}
		}
		Alias {
			call_receiver_array_from_type(typ.base_type)
		}
		Pointer {
			call_receiver_array_from_type(typ.base_type)
		}
		else {
			none
		}
	}
}

// call_arg_value updates call arg value state for TypeChecker.
fn (tc &TypeChecker) call_arg_value(id flat.NodeId) flat.NodeId {
	if int(id) < 0 {
		return id
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .field_init && node.children_count > 0 {
		return tc.a.child(&node, 0)
	}
	return id
}

fn (tc &TypeChecker) spread_arg_child(id flat.NodeId) ?flat.NodeId {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .prefix && node.value == '...' && node.children_count > 0 {
		return tc.a.child(&node, 0)
	}
	return none
}

fn (mut tc TypeChecker) check_array_decompose_counts() {
	for index, node in tc.a.nodes {
		if node.kind != .call || node.children_count < 2 {
			continue
		}
		callee := tc.a.child_node(&node, 0)
		if callee.kind != .ident {
			continue
		}
		name := tc.qualify_fn_name(callee.value)
		params := tc.fn_param_types[name] or { tc.fn_param_types[callee.value] or { continue } }
		if tc.fn_variadic[name] || tc.fn_variadic[callee.value] {
			continue
		}
		mut preceding := 0
		for i in 1 .. node.children_count {
			arg_id := tc.call_arg_value(tc.a.child(&node, i))
			spread_id := tc.spread_arg_child(arg_id) or {
				preceding++
				continue
			}
			spread := tc.a.nodes[int(spread_id)]
			if spread.kind != .array_literal {
				break
			}
			needed := params.len - preceding
			actual := int(spread.children_count)
			if actual < needed {
				element_word := if actual == 1 { 'element' } else { 'elements' }
				pos := token.new_span(spread.pos.id, int_max(0, spread.pos.offset - 3),
					spread.pos.end)
				tc.errors << tc.make_type_error_at(.call_arg_mismatch,
					'array decompose has ${actual} ${element_word} but ${needed} are needed for `${callee.value}`',
					arg_id, pos)
			}
			break
		}
		_ = index
	}
}

fn (tc &TypeChecker) nonvariadic_spread_extra_arg_count(node flat.Node, info CallInfo, recv_extra int) int {
	mut extra := 0
	mut logical_arg_idx := 0
	for i in 1 + info.arg_offset .. node.children_count {
		if tc.a.child_node(&node, i).kind == .field_init {
			continue
		}
		arg_id := tc.call_arg_value(tc.a.child(&node, i))
		if _ := tc.spread_arg_child(arg_id) {
			param_idx := logical_arg_idx + recv_extra
			count := info.params.len - param_idx
			if count > 1 {
				extra += count - 1
			}
			if count > 0 {
				logical_arg_idx += count
				continue
			}
		}
		logical_arg_idx++
	}
	return extra
}

// receiver_compatible supports receiver compatible handling for TypeChecker.
fn (tc &TypeChecker) receiver_compatible(actual Type, expected Type) bool {
	if tc.type_compatible(actual, expected) {
		return true
	}
	// Check the generic-base relaxation before the pointer fallbacks: it unwraps
	// pointers itself, so a bare `&Box{...}` literal still matches an expected
	// `&Box[int]` (while `&Box[string]` vs `&Box[int]` stays rejected).
	if tc.generic_receiver_base_match(actual, expected) {
		return true
	}
	if expected is Pointer {
		if actual is Pointer {
			if expected.base_type is Alias && expected.base_type.base_type is Pointer {
				return tc.type_compatible(actual, expected.base_type.base_type)
			}
			return false
		}
		if expected.base_type is Pointer {
			return false
		}
		return tc.type_compatible(actual, expected.base_type)
	}
	if actual is Pointer {
		return tc.type_compatible(actual.base_type, expected)
	}
	return false
}

fn (tc &TypeChecker) method_receiver_compatible(actual Type, expected Type, method_name string) bool {
	if tc.receiver_compatible(actual, expected) {
		return true
	}
	// A method receiver rendered as the bare/unqualified generic form (`Vec3[T]`)
	// matches the declaring module's qualified form (`vec.Vec3[T]`) — same generic,
	// only the module qualifier differs. This arises when an operator-overload result
	// on an aliased generic instance (`type Vec = vec.Vec3[f64]`) is re-checked in the
	// annotate pass with an unqualified receiver spelling.
	if tc.generic_receiver_qualifier_mismatch(actual, expected) {
		return true
	}
	actual_depth, actual_base := type_pointer_depth_and_base(actual)
	expected_depth, expected_base := type_pointer_depth_and_base(expected)
	// C receiver lowering can dereference a pointer for a value receiver, but it
	// does not adjust depth when both the actual and expected receivers are pointers.
	if actual_depth == 1 && expected_depth == 0 && (tc.type_compatible(actual_base, expected_base)
		|| tc.generic_receiver_base_match(actual_base, expected_base)
		|| tc.receiver_embeds(actual_base, expected_base)) {
		return true
	}
	// Runtime array builtins are declared with the internal `array` receiver, which is
	// represented here as `[]void`. Keep that erasure scoped to raw `array.*`
	// methods; user receivers like `fn (xs []void) touch()` must not accept `[]int`.
	if checker_is_raw_collection_method_name(method_name, 'array.') && actual is Array
		&& expected is Array && expected.elem_type is Void {
		return true
	}
	return false
}

// is_locally_declared_bare_type reports whether the bare `name` is a type declared in
// the current program (main module), which is bare-keyed in the type tables. Such a name
// denotes that local type, not an unqualified spelling of some other module's type.
pub fn (tc &TypeChecker) is_locally_declared_bare_type(name string) bool {
	return name in tc.structs || name in tc.interface_names || name in tc.sum_types
		|| name in tc.enum_names || name in tc.flag_enums || name in tc.type_aliases
}

// qualifier_relaxed_type_name_match reports whether `a` and `b` name the same type
// allowing ONLY a missing module qualifier on one side: they are equal, or one is the
// unqualified spelling of the other (`Vec3` vs `vec.Vec3`). Two *different* qualified
// names that merely share a short name (`a.Box` vs `b.Box`, `foo.User` vs `bar.User`)
// are distinct types and do NOT match. A bare name that is itself a locally-declared
// type (`User` alongside another module's `foo.User`) denotes that local type, so it
// does NOT match a qualified name from a different module.
fn (tc &TypeChecker) qualifier_relaxed_type_name_match(a string, b string) bool {
	if a == b {
		return true
	}
	a_qualified := a.contains('.')
	b_qualified := b.contains('.')
	// Both bare (but unequal) or both qualified (but unequal) name different types.
	if a_qualified == b_qualified {
		return false
	}
	if a.all_after_last('.') != b.all_after_last('.') {
		return false
	}
	bare := if a_qualified { b } else { a }
	qualified := if a_qualified { a } else { b }
	qualifier := qualified.all_before_last('.')
	// A locally-declared bare type only relaxes to a qualified name that is its own
	// main spelling; against another module's same-short-named type it is distinct.
	if qualifier != 'main' && qualifier.len > 0 && tc.is_locally_declared_bare_type(bare) {
		return false
	}
	return true
}

// generic_receiver_qualifier_mismatch accepts a method receiver that differs from
// the declared receiver ONLY by a missing module qualifier on the same generic form
// (`Vec3[T]` vs `vec.Vec3[T]`, or `Vec3[int]` vs `vec.Vec3[int]`). It requires the base
// and every generic argument to be qualifier-relaxed matches (an unqualified spelling
// of the same qualified name), and the base to be a known generic struct, so it never
// conflates two different instantiations (`Vec3[string]` vs `vec.Vec3[int]`), two
// different modules' same-short-named types (`a.Box[int]` vs `b.Box[int]`,
// `Vec[foo.User]` vs `Vec[bar.User]`), or non-generic types.
fn (tc &TypeChecker) generic_receiver_qualifier_mismatch(actual Type, expected Type) bool {
	if (actual is Pointer) != (expected is Pointer) {
		return false
	}
	a_full := unwrap_pointer(actual).name()
	e_full := unwrap_pointer(expected).name()
	if a_full == e_full || a_full.len == 0 || e_full.len == 0 {
		return false
	}
	a_base, a_args, a_ok := generic_type_application_parts(a_full)
	e_base, e_args, e_ok := generic_type_application_parts(e_full)
	if !a_ok || !e_ok || a_args.len != e_args.len || a_args.len == 0 {
		return false
	}
	if !tc.qualifier_relaxed_type_name_match(a_base, e_base) {
		return false
	}
	for i in 0 .. a_args.len {
		if !tc.qualifier_relaxed_type_name_match(trimmed_space(a_args[i]), trimmed_space(e_args[i])) {
			return false
		}
	}
	short := e_base.all_after_last('.')
	return e_base in tc.struct_generic_params || a_base in tc.struct_generic_params
		|| short in tc.struct_generic_params
}

// generic_receiver_base_match relaxes compatibility between two same-base generic
// struct types when at least one side is the open/bare generic form — a bare
// `Vec4{...}` literal specializing to the expected `Vec4[f32]`, or a concrete
// `Vec4[f32]` value matching the open `Vec4` / `Vec4[T]` method-receiver form.
//
// It deliberately does NOT relax two *different concrete* instantiations. Because
// `receiver_compatible` is also used for ordinary call arguments, field inits,
// array literals, and expected-type propagation, conflating them would let
// `Box[string]` satisfy an expected `Box[int]` and emit incompatible C structs.
fn (tc &TypeChecker) generic_receiver_base_match(actual Type, expected Type) bool {
	// Both sides must share pointer shape before unwrapping: a `&Box{...}` value must
	// not satisfy an expected `Box[int]` value. The C argument path only
	// auto-dereferences when the actual/expected type names match exactly, so the bare
	// `Box` vs `Box[int]` mismatch would otherwise be emitted as a pointer where a value
	// is required. (A pointer receiver on a value-receiver method is handled by
	// receiver_compatible's pointer fallbacks, not here.)
	if (actual is Pointer) != (expected is Pointer) {
		return false
	}
	a_full := unwrap_pointer(actual).name()
	e_full := unwrap_pointer(expected).name()
	a := strip_generic_args_name(a_full)
	if a.len == 0 || a != strip_generic_args_name(e_full) {
		return false
	}
	if !(a in tc.struct_generic_params || tc.sum_params_for_base(a).len > 0) {
		return false
	}
	if a_full == e_full {
		return false
	}
	// Reject two *different concrete* instantiations (`Box[string]` vs `Box[int]`),
	// which produce incompatible C structs. Relax only when at least one side is
	// the open/bare generic form: a bare `Box{...}` literal specializing to the
	// expected `Box[int]`, or a concrete `Box[int]` value matching the open
	// `Box`/`Box[T]` method-receiver form.
	if tc.is_concrete_generic_instance(a_full) && tc.is_concrete_generic_instance(e_full) {
		return false
	}
	return true
}

// is_concrete_generic_instance reports whether `name` is a fully concrete generic
// instantiation (e.g. `Box[int]`), as opposed to the bare base (`Box`) or an open
// parameter form (`Box[T]`).
fn (tc &TypeChecker) is_concrete_generic_instance(name string) bool {
	_, args, ok := generic_type_application_parts(name)
	if !ok {
		return false
	}
	return tc.generic_args_are_concrete(args)
}

// bare_generic_literal_adopts reports whether a struct literal written as the bare
// generic base (`Box{...}`, no type args) should adopt the concrete `expected`
// instance (`Box[int]`, optionally behind a pointer). The base short-names must match
// and the base must be a known generic struct, so a non-generic same-named struct is
// left to ordinary checking.
fn (tc &TypeChecker) bare_generic_literal_adopts(lit_value string, expected Type) bool {
	if lit_value.len == 0 || lit_value.contains('[') {
		return false
	}
	e_base, _, e_ok := generic_type_application_parts(unwrap_pointer(expected).name())
	if !e_ok || e_base.all_after_last('.') != lit_value.all_after_last('.') {
		return false
	}
	return e_base in tc.struct_generic_params
		|| e_base.all_after_last('.') in tc.struct_generic_params
}

fn is_anonymous_struct_name(name string) bool {
	return name.all_after_last('.').starts_with('AnonStruct_')
}

fn is_contextual_anonymous_struct_literal(name string) bool {
	return name == 'struct' || is_anonymous_struct_name(name)
}

fn (mut tc TypeChecker) anonymous_struct_literal_compatible(node flat.Node, expected Type) bool {
	struct_type := struct_type_from_type(expected) or { return false }
	if !is_anonymous_struct_name(struct_type.name) {
		return false
	}
	fields := tc.struct_fields_for_init(struct_type.name)
	for i in 0 .. node.children_count {
		field := tc.a.child_node(&node, i)
		if field.kind != .field_init || field.children_count == 0 {
			return false
		}
		mut field_type := Type(void_)
		if field.value.len > 0 {
			field_type = tc.struct_field_type(struct_type.name, field.value) or { return false }
		} else if i < fields.len {
			field_type = fields[i].typ
		} else {
			return false
		}
		value_id := tc.a.child(field, 0)
		actual := tc.resolve_expr(value_id, field_type)
		if !tc.expr_compatible(value_id, actual, field_type)
			&& !tc.pointer_value_compatible(actual, field_type) {
			return false
		}
	}
	return true
}

// generic_literal_fields_compatible checks a bare generic struct literal's named
// field initializers against the expected concrete instantiation (`Box[int]`),
// substituting the struct's type parameters into each field's declared type. It
// returns false only on a *definite* mismatch (e.g. `Box{v: 'str'}` for `Box[int]`),
// so a clearly-unrelated literal yields a clean checker error instead of adopting the
// type and emitting broken C; unresolvable fields stay lenient.
fn (mut tc TypeChecker) generic_literal_fields_compatible(node flat.Node, expected Type) bool {
	e_base, e_args, e_ok := generic_type_application_parts(unwrap_pointer(expected).name())
	if !e_ok {
		return true
	}
	params := tc.struct_generic_params[e_base] or {
		tc.struct_generic_params[e_base.all_after_last('.')] or { return true }
	}
	if params.len != e_args.len {
		return true
	}
	fields := tc.structs[e_base] or { tc.structs[e_base.all_after_last('.')] or { return true } }
	for i in 0 .. node.children_count {
		fi := tc.a.child_node(&node, i)
		if fi.kind != .field_init || fi.children_count == 0 {
			continue
		}
		mut decl_typ := Type(void_)
		mut found := false
		if fi.value.len > 0 {
			// Named initializer (`Box{v: 'x'}`): match by field name.
			for f in fields {
				if f.name == fi.value {
					decl_typ = f.typ
					found = true
					break
				}
			}
		} else if i < fields.len {
			// Positional initializer (`Box{'x'}`): the parser emits a `field_init` with
			// an empty name, so match by field order like `check_struct_init` does.
			decl_typ = fields[i].typ
			found = true
		}
		if !found {
			continue
		}
		sub := tc.substitute_generic_type(decl_typ, e_args, params)
		if sub is Unknown || sub is Void {
			continue
		}
		actual := tc.resolve_expr(tc.a.child(fi, 0), sub)
		if !tc.expr_receiver_compatible(tc.a.child(fi, 0), actual, sub) {
			return false
		}
	}
	return true
}

fn (mut tc TypeChecker) expr_receiver_compatible(expr_id flat.NodeId, actual Type, expected Type) bool {
	if !tc.receiver_compatible(actual, expected)
		&& !tc.implicit_ref_arg_compatible(expr_id, actual, expected) {
		return false
	}
	if actual is Pointer && expected !is Pointer
		&& !tc.explicit_address_arg_compatible(expr_id, actual, expected) {
		return false
	}
	return tc.generic_expected_expr_fields_compatible(expr_id, expected)
}

fn (tc &TypeChecker) implicit_ref_arg_compatible(expr_id flat.NodeId, actual Type, expected Type) bool {
	if !tc.expr_can_take_address(expr_id) {
		return false
	}
	actual_depth, actual_base := type_pointer_depth_and_base(actual)
	expected_depth, expected_base := type_pointer_depth_and_base(expected)
	// V permits implicit reference arguments to add every missing pointer layer.
	// Cgen materializes a typed `__ref_arg_N` chain rather than emitting only `&expr`.
	if expected_depth <= actual_depth {
		return false
	}
	return tc.type_compatible(actual_base, expected_base)
}

fn type_pointer_depth_and_base(typ Type) (int, Type) {
	mut depth := 0
	mut cur := typ
	for {
		if cur is Alias {
			cur = cur.base_type
			continue
		}
		if cur is Pointer {
			depth++
			cur = cur.base_type
			continue
		}
		break
	}
	return depth, cur
}

fn (tc &TypeChecker) explicit_address_arg_compatible(expr_id flat.NodeId, actual Type, expected Type) bool {
	if actual is Pointer {
		if tc.addressed_bare_generic_value_mismatch(expr_id, actual, expected) {
			return false
		}
		if expected is Pointer && tc.valid_node_id(expr_id) {
			node := tc.a.nodes[int(expr_id)]
			if node.kind == .prefix && node.op == .amp && node.children_count > 0 {
				child_id := tc.a.child(&node, 0)
				child_type := tc.smartcast_type(child_id) or { actual.base_type }
				return tc.type_compatible(child_type, expected.base_type)
			}
		}
		return tc.type_compatible(actual.base_type, expected)
	}
	return false
}

fn (tc &TypeChecker) addressed_bare_generic_value_mismatch(expr_id flat.NodeId, _actual Type, expected Type) bool {
	if expected is Pointer || !tc.valid_node_id(expr_id) {
		return false
	}
	node := tc.a.nodes[int(expr_id)]
	if node.kind != .prefix || node.op != .amp || node.children_count != 1 {
		return false
	}
	child := tc.a.child_node(&node, 0)
	return child.kind == .struct_init && tc.bare_generic_literal_adopts(child.value, expected)
}

fn (tc &TypeChecker) explicit_mut_pointer_arg_compatible(expr_id flat.NodeId, expected Type) bool {
	if int(expr_id) < 0 || int(expr_id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(expr_id)]
	if !node.is_mut || expected !is Pointer || !tc.expr_root_is_mutable_lvalue(expr_id) {
		return false
	}
	expected_ptr := expected as Pointer
	return tc.type_compatible(tc.resolve_type(expr_id), expected_ptr.base_type)
}

fn (tc &TypeChecker) expr_is_addressed_byvalue_arg(expr_id flat.NodeId) bool {
	if int(expr_id) < 0 || int(expr_id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(expr_id)]
	if node.kind in [.paren, .expr_stmt] && node.children_count > 0 {
		return tc.expr_is_addressed_byvalue_arg(tc.a.child(&node, 0))
	}
	if node.kind != .prefix || node.op != .amp || node.children_count == 0 {
		return false
	}
	child := tc.a.child_node(&node, 0)
	return child.kind in [.struct_init, .cast_expr, .call]
		|| (child.kind == .index && child.value == 'range')
}

fn (mut tc TypeChecker) expr_generic_expected_match(expr_id flat.NodeId, actual Type, expected Type) bool {
	return tc.generic_expected_type_match(actual, expected)
		&& tc.generic_expected_expr_fields_compatible(expr_id, expected)
}

fn (mut tc TypeChecker) generic_expected_expr_fields_compatible(expr_id flat.NodeId, expected Type) bool {
	if !tc.valid_node_id(expr_id) {
		return true
	}
	node := tc.a.nodes[int(expr_id)]
	match node.kind {
		.field_init, .expr_stmt, .paren {
			if node.children_count > 0 {
				return tc.generic_expected_expr_fields_compatible(tc.a.child(&node, 0), expected)
			}
		}
		.struct_init {
			if tc.bare_generic_literal_adopts(node.value, expected) {
				return tc.generic_literal_fields_compatible(node, expected)
			}
		}
		.prefix {
			if node.op == .amp && node.children_count == 1 && expected is Pointer {
				child := tc.a.nodes[int(tc.a.child(&node, 0))]
				if child.kind == .struct_init
					&& tc.bare_generic_literal_adopts(child.value, expected) {
					return tc.generic_literal_fields_compatible(child, expected)
				}
			}
		}
		else {}
	}

	return true
}

// strip_generic_args_name returns the base name of a generic instance type
// (`Box[int]` -> `Box`); array/map types (leading `[`) yield the name unchanged.
fn strip_generic_args_name(name string) string {
	bracket := name.index_u8(`[`)
	if bracket <= 0 {
		return name
	}
	return name[..bracket]
}

// is_zero_literal reports whether is zero literal applies in types.
fn (tc &TypeChecker) is_zero_literal(id flat.NodeId) bool {
	if int(id) < 0 {
		return false
	}
	node := tc.a.nodes[int(id)]
	return node.kind == .int_literal && node.value == '0'
}

// is_fn_pointer_type reports whether is fn pointer type applies in types.
fn is_fn_pointer_type(typ Type) bool {
	clean0 := typ
	mut clean := clean0
	if clean0 is Alias {
		clean = clean0.base_type
	}
	return clean is FnType
}

// fn_type_from_type converts fn type from type data for types.
fn fn_type_from_type(typ Type) ?FnType {
	if typ is FnType {
		return typ
	}
	if typ is Alias {
		return fn_type_from_type(typ.base_type)
	}
	if typ is Pointer {
		return fn_type_from_type(typ.base_type)
	}
	return none
}

fn struct_type_from_type(typ Type) ?Struct {
	if typ is Struct {
		return typ
	}
	if typ is Alias {
		return struct_type_from_type(typ.base_type)
	}
	return none
}

fn (tc &TypeChecker) selector_declared_value_type(node flat.Node) ?Type {
	if node.children_count == 0 {
		return none
	}
	if !valid_string_data(node.value) {
		return none
	}
	if typ := tc.const_type_for_selector(node) {
		return typ
	}
	base_id := tc.a.child(&node, 0)
	base_type := tc.selector_fn_base_type(base_id) or { return none }
	clean := unalias_and_unwrap_pointer_type(base_type)
	if clean is Struct {
		if typ := tc.struct_field_type(clean.name, node.value) {
			return typ
		}
	}
	if clean is Interface {
		if typ := tc.interface_field_type(clean.name, node.value) {
			return typ
		}
	}
	return none
}

fn (tc &TypeChecker) selector_const_fn_type(node flat.Node) ?FnType {
	if typ := tc.const_type_for_selector(node) {
		return fn_type_from_type(typ)
	}
	return none
}

fn (tc &TypeChecker) selector_field_fn_type(node flat.Node, base_type Type) ?FnType {
	clean := unalias_and_unwrap_pointer_type(base_type)
	if clean is Struct {
		if typ := tc.struct_field_type(clean.name, node.value) {
			return fn_type_from_type(typ)
		}
	}
	if clean is Interface {
		if typ := tc.interface_field_type(clean.name, node.value) {
			return fn_type_from_type(typ)
		}
	}
	return none
}

// selector_fn_type supports selector fn type handling for TypeChecker.
fn (tc &TypeChecker) selector_fn_type(node flat.Node) ?FnType {
	typ := tc.selector_declared_value_type(node) or { return none }
	return fn_type_from_type(typ)
}

fn (tc &TypeChecker) selector_wrapped_fn_type(node flat.Node) ?FnType {
	typ := tc.selector_declared_value_type(node) or { return none }
	payload := match typ {
		OptionType { typ.base_type }
		ResultType { typ.base_type }
		else { return none }
	}
	return fn_type_from_type(payload)
}

fn (tc &TypeChecker) method_value_type(receiver_name string, method string) ?Type {
	method_name := '${receiver_name}.${method}'
	mut ret_type := tc.fn_ret_types[method_name] or { Type(void_) }
	mut params := tc.fn_param_types[method_name] or { []Type{} }
	if method_name !in tc.fn_ret_types && method_name !in tc.fn_param_types {
		// A concrete generic receiver (`Box[int]`) has its methods registered under the
		// open key (`Box[T].method`); resolve and substitute so a method *value* on a
		// generic struct is typed instead of reported as an unknown field.
		ci := tc.resolve_generic_struct_method(receiver_name, method) or { return none }
		ret_type = ci.return_type
		params = ci.params.clone()
	}
	mut bound_params := []Type{}
	if params.len > 1 {
		bound_params = params[1..].clone()
	}
	return Type(FnType{
		params:      bound_params
		return_type: ret_type
	})
}

fn (tc &TypeChecker) builtin_method_value_type(base_type Type, method string) ?Type {
	clean := unalias_and_unwrap_pointer_type(base_type)
	receiver_name := if clean is String {
		'string'
	} else if clean is Array {
		'array'
	} else if clean is Map {
		'map'
	} else {
		builtin_receiver_method_type_name(clean)
	}
	if receiver_name.len > 0 {
		if typ := tc.method_value_type(receiver_name, method) {
			return typ
		}
	}
	if method == 'str' && (clean is Primitive || clean is Char || clean is Rune) {
		return Type(FnType{
			params:      []Type{}
			return_type: Type(string_)
		})
	}
	info := tc.builtin_receiver_method_call_info(base_type, method) or { return none }
	mut bound_params := []Type{}
	if info.params.len > 1 {
		bound_params = info.params[1..].clone()
	}
	return Type(FnType{
		params:      bound_params
		return_type: info.return_type
	})
}

// selector_fn_base_type supports selector fn base type handling for TypeChecker.
fn (tc &TypeChecker) selector_fn_base_type(base_id flat.NodeId) ?Type {
	if typ := tc.smartcast_type(base_id) {
		return typ
	}
	if int(base_id) >= 0 {
		base_node := tc.a.nodes[int(base_id)]
		if base_node.kind == .ident {
			if typ := tc.non_file_scope_type(base_node.value) {
				if typ is Alias {
					return typ
				}
			}
		}
	}
	if typ := tc.cached_expr_type(base_id) {
		return typ
	}
	if int(base_id) < 0 {
		return none
	}
	base_node := tc.a.nodes[int(base_id)]
	if base_node.typ.len > 0 && base_node.typ != 'unknown' {
		return tc.parse_type(base_node.typ)
	}
	if base_node.kind == .call {
		if typ := tc.resolved_call_type(base_id) {
			return typ
		}
		if typ := tc.direct_call_return_type(base_node) {
			return typ
		}
		return none
	}
	return tc.resolve_type(base_id)
}

// direct_call_return_type supports direct call return type handling for TypeChecker.
fn (tc &TypeChecker) direct_call_return_type(node flat.Node) ?Type {
	if node.children_count == 0 {
		return none
	}
	fn_node := tc.a.child_node(&node, 0)
	if fn_node.kind == .index && fn_node.children_count >= 2 && fn_node.value != 'range' {
		base_node := tc.a.child_node(fn_node, 0)
		name := tc.generic_call_base_name(base_node) or { return none }
		type_args := tc.generic_call_type_arg_names(fn_node)
		if type_args.len == 0 {
			return none
		}
		if is_decode_call_name(name) && type_args.len == 1 {
			return Type(ResultType{
				base_type: tc.parse_type(type_args[0])
			})
		}
		if info := tc.explicit_generic_call_info(name, false, type_args) {
			return info.return_type
		}
		return none
	}
	if fn_node.kind == .ident {
		if local_name := tc.local_bare_fn_key(fn_node.value) {
			if typ := tc.fn_ret_types[local_name] {
				return typ
			}
		}
		if imported_name := tc.resolve_selective_import_symbol(fn_node.value) {
			if typ := tc.fn_ret_types[imported_name] {
				return typ
			}
		}
		if typ := tc.fn_ret_types[fn_node.value] {
			return typ
		}
		return none
	}
	if fn_node.kind != .selector || fn_node.children_count == 0 {
		return none
	}
	base_node := tc.a.child_node(fn_node, 0)
	if base_node.kind == .ident {
		base_is_value := tc.ident_resolves_to_value(base_node.value)
		if !base_is_value {
			if resolved := tc.resolve_import_alias(base_node.value) {
				mod_name := '${resolved}.${fn_node.value}'
				if typ := tc.fn_ret_types[mod_name] {
					return typ
				}
			}
			if static_name := tc.static_assoc_fn_key_for_base(base_node.value, fn_node.value) {
				return tc.fn_ret_types[static_name] or { none }
			}
		}
		return none
	}
	if base_node.kind == .selector {
		inner := tc.a.child_node(base_node, 0)
		if inner.kind == .ident {
			mod_name := tc.resolve_import_alias(inner.value) or { inner.value }
			full_name := '${mod_name}.${base_node.value}.${fn_node.value}'
			if typ := tc.fn_ret_types[full_name] {
				return typ
			}
			if static_name := tc.static_assoc_fn_key_for_base('${mod_name}.${base_node.value}',
				fn_node.value)
			{
				return tc.fn_ret_types[static_name] or { none }
			}
		}
	}
	return none
}

fn (tc &TypeChecker) spawn_child_call_return_type(node flat.Node) ?Type {
	if ret := tc.direct_call_return_type(node) {
		return ret
	}
	if node.children_count == 0 {
		return none
	}
	fn_node := tc.a.child_node(&node, 0)
	if fn_node.kind == .selector && fn_node.children_count > 0 {
		base_type := tc.resolve_type(tc.a.child(fn_node, 0))
		clean_base := unwrap_all_pointers(base_type)
		for candidate in receiver_method_name_candidates(clean_base, fn_node.value, tc.cur_module) {
			if ret := tc.fn_ret_types[candidate] {
				return ret
			}
		}
		if method_key := tc.concrete_method_signature_key(clean_base.name(), fn_node.value) {
			if ret := tc.fn_ret_types[method_key] {
				return ret
			}
		}
	}
	if fn_node.kind != .ident {
		return none
	}
	mut candidates := []string{}
	candidates << fn_node.value
	qname := tc.qualify_fn_name(fn_node.value)
	if qname != fn_node.value {
		candidates << qname
	}
	if tc.cur_module.len > 0 {
		candidates << '${tc.cur_module}.${fn_node.value}'
	}
	candidates << 'main.${fn_node.value}'
	for candidate in candidates {
		if ret := tc.fn_ret_types[candidate] {
			return ret
		}
	}
	return none
}

// module_const_receiver_method_name supports module_const_receiver_method_name handling in types.
fn (tc &TypeChecker) module_const_receiver_method_name(base_node flat.Node, method string) ?string {
	if base_node.kind != .selector || base_node.children_count == 0 || method.len == 0 {
		return none
	}
	inner := tc.a.child_node(&base_node, 0)
	if inner.kind != .ident {
		return none
	}
	mod_name := tc.resolve_import_alias(inner.value) or { inner.value }
	const_name := '${mod_name}.${base_node.value}'
	mut const_type := tc.const_types[const_name] or { Type(Unknown{}) }
	const_type = tc.const_type_from_initializer(const_name, const_type)
	if const_type is Unknown && base_node.value == 'scanner_matcher' {
		const_type = Type(Struct{
			name: '${mod_name}.KeywordsMatcherTrie'
		})
	}
	clean := unwrap_pointer(const_type)
	type_name := resolve_type_name_for_method(clean)
	if type_name.len == 0 {
		return none
	}
	for method_name in receiver_method_name_candidates(clean, method, mod_name) {
		if method_name in tc.fn_ret_types {
			return method_name
		}
	}
	return none
}

// valid_string_data supports valid string data handling for types.
fn valid_string_data(s string) bool {
	if s.len == 0 {
		return true
	}
	ptr := unsafe { u64(voidptr(s.str)) }
	return ptr >= 4096 && ptr < 281474976710656 && s.len < 1048576
}

// clone_smartcasts supports clone smartcasts handling for types.
fn clone_smartcasts(src map[string]Type) map[string]Type {
	mut dst := map[string]Type{}
	for key, typ in src {
		if valid_string_data(key) {
			dst[key] = typ
		}
	}
	return dst
}

// array_elem_type supports array elem type handling for types.
fn array_elem_type(arr Array) Type {
	return arr.elem_type
}

// array_like_elem_type returns the element type of an `Array` or `ArrayFixed`.
fn array_like_elem_type(t Type) ?Type {
	if t is Array {
		return t.elem_type
	}
	if t is ArrayFixed {
		return t.elem_type
	}
	if t is Alias {
		return array_like_elem_type(t.base_type)
	}
	return none
}

// if_branch_types_compatible reports whether two if-expression branch types are
// compatible. Bare array literals (`[a, b, c]`) resolve to a fixed `T[n]`, but V
// treats them as dynamic `[]T`; two *literal* branches with compatible element
// types must therefore not be flagged as a mismatch merely because their lengths
// differ. The length-agnostic relaxation is limited to literal tails: genuine
// fixed-array values keep their length (handled by `type_compatible` above), so
// e.g. `[2]int` vs `[3]int` branches still mismatch.
fn (tc &TypeChecker) if_branch_types_compatible(a Type, b Type, a_is_array_lit bool, b_is_array_lit bool) bool {
	if (a is None && b is ResultType) || (b is None && a is ResultType) {
		return false
	}
	if (a is OptionType) != (b is OptionType) || (a is ResultType) != (b is ResultType) {
		return false
	}
	if tc.type_compatible(a, b) || tc.type_compatible(b, a) {
		return true
	}
	if !a_is_array_lit || !b_is_array_lit {
		return false
	}
	a_elem := array_like_elem_type(a) or { return false }
	b_elem := array_like_elem_type(b) or { return false }
	return tc.type_compatible(a_elem, b_elem) || tc.type_compatible(b_elem, a_elem)
}

fn (tc &TypeChecker) if_branch_types_compatible_with_expected(a Type, a_tail flat.NodeId, b Type, b_tail flat.NodeId, expected Type) bool {
	if expected is Void || expected is Unknown {
		return false
	}
	return tc.if_branch_type_compatible_with_context(a, a_tail, expected)
		&& tc.if_branch_type_compatible_with_context(b, b_tail, expected)
}

fn (tc &TypeChecker) if_branch_type_compatible_with_context(actual Type, tail_id flat.NodeId, expected Type) bool {
	if actual is None {
		return (expected is OptionType || is_ierror_type(expected))
			&& tc.branch_tail_is_none_literal(tail_id)
	}
	if is_option_void_type(actual) {
		return (expected is OptionType || is_ierror_type(expected))
			&& tc.branch_tail_is_none_literal(tail_id)
	}
	if is_result_void_type(actual) {
		return (expected is OptionType || expected is ResultType || is_ierror_type(expected))
			&& tc.branch_tail_is_error_literal(tail_id)
	}
	if is_ierror_type(actual) {
		return (expected is OptionType || expected is ResultType || is_ierror_type(expected))
			&& tc.branch_tail_is_error_literal(tail_id)
	}
	if expected is OptionType && tc.type_compatible(actual, expected.base_type) {
		return true
	}
	return tc.type_compatible(actual, expected)
}

fn (mut tc TypeChecker) constant_if_selected_branch_compatible_with_expected(node flat.Node, expected Type) bool {
	selected_tail := tc.constant_if_selected_tail(node) or { return false }
	if !tc.valid_node_id(selected_tail) {
		return false
	}
	actual := tc.resolve_expr(selected_tail, expected)
	return tc.return_type_compatible(selected_tail, actual, expected)
		|| tc.if_branch_type_compatible_with_context(actual, selected_tail, expected)
}

fn (tc &TypeChecker) constant_if_selected_tail(node flat.Node) ?flat.NodeId {
	if node.kind != .if_expr || node.children_count <= 2 {
		return none
	}
	cond_id := tc.a.child(&node, 0)
	if !tc.valid_node_id(cond_id) {
		return none
	}
	cond := tc.a.nodes[int(cond_id)]
	if cond.kind != .bool_literal {
		return none
	}
	selected_id := tc.a.child(&node, if cond.value == 'true' { 1 } else { 2 })
	if tc.valid_node_id(selected_id) && tc.a.nodes[int(selected_id)].kind == .if_expr {
		return selected_id
	}
	return tc.branch_tail_expr_id(selected_id)
}

fn (tc &TypeChecker) branch_tail_is_none_literal(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .none_expr {
		return true
	}
	if node.kind in [.paren, .expr_stmt] && node.children_count > 0 {
		return tc.branch_tail_is_none_literal(tc.a.child(&node, 0))
	}
	return false
}

fn (tc &TypeChecker) branch_tail_is_error_literal(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .call {
		return tc.call_display_name(node) in ['error', 'error_with_code']
	}
	if node.kind in [.paren, .expr_stmt] && node.children_count > 0 {
		return tc.branch_tail_is_error_literal(tc.a.child(&node, 0))
	}
	return false
}

fn (tc &TypeChecker) branch_failure_literal_matches_context(id flat.NodeId, expected Type) bool {
	if tc.branch_tail_is_none_literal(id) {
		return expected is OptionType || is_ierror_type(expected)
	}
	if tc.branch_tail_is_error_literal(id) {
		return expected is OptionType || expected is ResultType || is_ierror_type(expected)
	}
	return true
}

fn if_branch_type_needs_context(typ Type) bool {
	if typ is None || is_ierror_type(typ) {
		return true
	}
	if typ is OptionType {
		return typ.base_type is Void
	}
	if typ is ResultType {
		return typ.base_type is Void
	}
	return false
}

fn inferred_contextual_if_type(a Type, b Type) ?Type {
	if a is None {
		return optional_if_type_from_value(b)
	}
	if b is None {
		return optional_if_type_from_value(a)
	}
	if is_option_void_type(a) {
		return optional_if_type_from_value(b)
	}
	if is_option_void_type(b) {
		return optional_if_type_from_value(a)
	}
	if is_ierror_type(a) {
		return result_if_type_from_value(b)
	}
	if is_ierror_type(b) {
		return result_if_type_from_value(a)
	}
	if is_result_void_type(a) {
		return result_if_type_from_value(b)
	}
	if is_result_void_type(b) {
		return result_if_type_from_value(a)
	}
	return none
}

fn is_option_void_type(typ Type) bool {
	if typ is OptionType {
		return typ.base_type is Void
	}
	return false
}

fn is_result_void_type(typ Type) bool {
	if typ is ResultType {
		return typ.base_type is Void
	}
	return false
}

fn optional_if_type_from_value(value Type) ?Type {
	if value is OptionType {
		if value.base_type is Void {
			return none
		}
		return value
	}
	if value is ResultType {
		return none
	}
	if if_branch_type_needs_context(value) || value is Void || value is Unknown {
		return none
	}
	return Type(OptionType{
		base_type: value
	})
}

fn result_if_type_from_value(value Type) ?Type {
	if value is ResultType {
		if value.base_type is Void {
			return none
		}
		return value
	}
	if value is OptionType || if_branch_type_needs_context(value) || value is Void
		|| value is Unknown {
		return none
	}
	return Type(ResultType{
		base_type: value
	})
}

// branch_tail_is_array_literal reports whether a branch's value tail is a bare
// array literal (`[a, b, c]`) — directly, or through a const whose initializer is
// one. V types such values as dynamic `[]T` regardless of element count, so they
// must not constrain if-branch length compatibility. Explicit fixed-array
// initializers (`[N]T{...}`, parsed as `.array_init`) are genuine fixed arrays and
// keep their length.
fn (tc &TypeChecker) branch_tail_is_array_literal(id flat.NodeId) bool {
	return tc.expr_is_bare_array_literal(tc.branch_tail_expr_id(id))
}

// expr_is_bare_array_literal reports whether `id` is a bare `[a, b, c]` literal,
// directly or through a single const reference.
fn (tc &TypeChecker) expr_is_bare_array_literal(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .array_literal {
		return true
	}
	if node.kind == .ident {
		for cand in [tc.qualify_name(node.value), node.value] {
			if expr_id := tc.const_exprs[cand] {
				if tc.valid_node_id(expr_id) {
					return tc.a.nodes[int(expr_id)].kind == .array_literal
				}
			}
		}
	}
	return false
}

// fixed_array_elem_type supports fixed array elem type handling for types.
fn fixed_array_elem_type(arr ArrayFixed) Type {
	return arr.elem_type
}

fn fixed_array_type_contains_map(typ Type) bool {
	if typ is ArrayFixed {
		return fixed_array_type_contains_map(typ.elem_type)
	}
	return typ is Map
}

// map_value_type supports map value type handling for types.
fn map_value_type(m Map) Type {
	return m.value_type
}

// pointer_base_type supports pointer base type handling for types.
fn pointer_base_type(p Pointer) Type {
	return p.base_type
}

// fn_param_type supports fn param type handling for types.
fn fn_param_type(f FnType, idx int) Type {
	return f.params[idx]
}

// is_known_call reports whether is known call applies in types.
fn (tc &TypeChecker) is_known_call(node flat.Node) bool {
	if node.children_count == 0 {
		return true
	}
	fn_node := tc.a.child_node(&node, 0)
	if node.typ.len > 0 {
		if fn_node.kind == .index && fn_node.value != 'range' {
			return tc.explicit_generic_call_target_is_known(node)
		}
		if fn_node.kind != .ident {
			return true
		}
	}
	if fn_node.kind == .selector {
		base_node := tc.a.child_node(fn_node, 0)
		if base_node.kind == .ident {
			if base_node.value == 'C' {
				return true
			}
			if resolved_mod := tc.resolve_import_alias(base_node.value) {
				mod_name := '${resolved_mod}.${fn_node.value}'
				if mod_name in tc.fn_ret_types || mod_name in tc.sum_types || mod_name in tc.structs
					|| mod_name in tc.enum_names {
					return true
				}
			}
			if base_node.value in tc.structs || base_node.value in tc.enum_names {
				qname := tc.qualify_name(base_node.value)
				if '${qname}.${fn_node.value}' in tc.fn_ret_types {
					return true
				}
			} else {
				qname := tc.qualify_name(base_node.value)
				if qname in tc.structs || qname in tc.enum_names {
					if '${qname}.${fn_node.value}' in tc.fn_ret_types {
						return true
					}
				}
			}
		} else if base_node.kind == .selector {
			inner := tc.a.child_node(base_node, 0)
			if inner.kind == .ident {
				mod_name := tc.resolve_import_alias(inner.value) or { inner.value }
				if '${mod_name}.${base_node.value}.${fn_node.value}' in tc.fn_ret_types {
					return true
				}
			}
		}
		if _ := tc.selector_const_fn_type(fn_node) {
			return true
		}
		base_id := tc.a.child(fn_node, 0)
		base_type := tc.selector_fn_base_type(base_id) or { tc.resolve_type(base_id) }
		if _ := tc.selector_field_fn_type(fn_node, base_type) {
			return true
		}
		if fn_node.value == 'hex' && tc.type_is_pointer_receiver(base_type) {
			return false
		}
		clean_type := unwrap_pointer(base_type)
		if clean_type is Array || clean_type is ArrayFixed {
			if fn_node.value == 'hex' {
				return tc.is_builtin_hex_receiver(base_type)
			}
			return tc.is_known_array_receiver_method(clean_type, fn_node.value)
		}
		if clean_type is Map {
			if fn_node.value == 'hex' {
				return tc.is_builtin_hex_receiver(base_type)
			}
			return true
		}
		if clean_type is String {
			if fn_node.value == 'hex' {
				return tc.is_builtin_hex_receiver(base_type)
			}
			return 'string.${fn_node.value}' in tc.fn_ret_types
		}
		if clean_type is Alias {
			mname := '${clean_type.name}.${fn_node.value}'
			if mname in tc.fn_ret_types {
				return true
			}
			base_name := resolve_type_name_for_method(clean_type.base_type)
			if base_name.len > 0 {
				for base_mname in receiver_method_name_candidates(clean_type.base_type,
					fn_node.value, tc.cur_module) {
					if base_mname in tc.fn_ret_types {
						return true
					}
				}
			}
		}
		if clean_type is Struct {
			return '${clean_type.name}.${fn_node.value}' in tc.fn_ret_types
		}
		if clean_type is Interface {
			return '${clean_type.name}.${fn_node.value}' in tc.fn_ret_types
		}
		if clean_type is SumType {
			return '${clean_type.name}.${fn_node.value}' in tc.fn_ret_types
		}
		if clean_type is Enum {
			if fn_node.value == 'str' {
				return true
			}
			return '${clean_type.name}.${fn_node.value}' in tc.fn_ret_types
		}
		if clean_type is Primitive {
			mname := '${prim_c_type_from(clean_type.props, clean_type.size)}.${fn_node.value}'
			return mname in tc.fn_ret_types
		}
		return false
	}
	if fn_node.kind == .ident {
		if typ := tc.cur_scope.lookup(fn_node.value) {
			return typ is FnType
		}
		qfn := tc.qualify_fn_name(fn_node.value)
		if qfn in tc.fn_ret_types || fn_node.value in tc.fn_ret_types {
			return true
		}
		if _ := tc.resolve_selective_import_symbol(fn_node.value) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) is_known_array_receiver_method(receiver Type, method string) bool {
	if receiver is Array {
		for mname in receiver_method_name_candidates(receiver, method, tc.cur_module) {
			if mname in tc.fn_ret_types {
				return true
			}
		}
		// Keep this in sync with the synthetic array receiver methods handled in
		// resolve_call_info/resolve_type, including `[]thread T.wait()`.
		return method in ['first', 'last', 'pop', 'pop_left', 'contains', 'join', 'index',
			'last_index', 'repeat', 'repeat_to_depth', 'delete', 'delete_last', 'clear', 'insert',
			'prepend', 'filter', 'map', 'any', 'all', 'count', 'sort_with_compare',
			'sorted_with_compare', 'sort', 'sorted', 'clone', 'reverse', 'reverse_in_place', 'equals',
			'bytestr', 'wait']
	}
	if receiver is ArrayFixed {
		array_type := Type(Array{
			elem_type: receiver.elem_type
		})
		for mname in receiver_method_name_candidates(array_type, method, tc.cur_module) {
			if mname in tc.fn_ret_types {
				return true
			}
		}
		return method == 'pointers'
	}
	return false
}

fn (tc &TypeChecker) is_unsupported_hex_call(node flat.Node) bool {
	if node.children_count == 0 {
		return false
	}
	fn_node := tc.a.child_node(&node, 0)
	if fn_node.kind != .selector || fn_node.value != 'hex' || fn_node.children_count == 0 {
		return false
	}
	base_id := tc.a.child(fn_node, 0)
	if tc.receiver_expr_is_pointer(base_id) {
		return true
	}
	base_type := tc.resolve_type(base_id)
	return !tc.is_builtin_hex_receiver(base_type)
}

fn (tc &TypeChecker) call_has_ambiguous_selective_import(node flat.Node) bool {
	if node.children_count == 0 {
		return false
	}
	fn_node := tc.a.child_node(&node, 0)
	if fn_node.kind == .index && fn_node.children_count > 0 {
		base := tc.a.child_node(fn_node, 0)
		return base.kind == .ident && tc.selective_import_symbol_is_ambiguous(base.value)
	}
	return fn_node.kind == .ident && tc.selective_import_symbol_is_ambiguous(fn_node.value)
}

// call_display_name updates call display name state for TypeChecker.
fn (tc &TypeChecker) call_display_name(node flat.Node) string {
	if node.children_count == 0 {
		return '<missing>'
	}
	fn_node := tc.a.child_node(&node, 0)
	if fn_node.kind == .ident {
		return fn_node.value
	}
	if fn_node.kind == .selector && fn_node.children_count > 0 {
		base := tc.a.child_node(fn_node, 0)
		if base.value.len > 0 {
			return '${base.value}.${fn_node.value}'
		}
	}
	if fn_node.kind in [.index, .prefix, .array_init] {
		type_name := tc.type_expr_name(tc.a.child(&node, 0))
		if type_name.len > 0 {
			return type_name
		}
	}
	return fn_node.value
}

// check_if_expr validates check if expr state for types.
fn (mut tc TypeChecker) check_if_expr(id flat.NodeId, node flat.Node) {
	if node.children_count < 2 {
		return
	}
	value_context := !tc.is_statement_node(id)
	cond_id := tc.a.child(&node, 0)
	condition := tc.a.node(cond_id)
	if condition.kind == .paren {
		tc.record_warning_at(.condition_mismatch,
			'unnecessary `()` in `if` condition, use `if expr {` instead of `if (expr) {`.',
			cond_id, tc.if_parenthesized_condition_pos(condition))
	}
	saved_mut_local_owners := tc.fn_context.mut_local_owners.clone()
	defer {
		tc.fn_context.mut_local_owners = saved_mut_local_owners.clone()
	}
	tc.enable_explicit_mut_smartcasts(cond_id)
	guard_bindings := tc.check_condition(cond_id)
	tc.record_constant_condition_diagnostics(cond_id)
	smartcasts := tc.extract_smartcasts(cond_id)
	then_id := tc.a.child(&node, 1)
	then_uses_block_scope := guard_bindings.len == 0 && tc.valid_node_id(then_id)
		&& tc.a.nodes[int(then_id)].kind == .block
	saved_smartcasts := clone_smartcasts(tc.smartcasts)
	for sc in smartcasts {
		if valid_string_data(sc.name) {
			tc.smartcasts[sc.name] = sc.typ
		}
	}
	$if ownership ? {
		if value_context {
			tc.ownership_begin_value_branch_group()
		} else {
			tc.ownership_begin_branch_group()
		}
	}
	tc.push_scope()
	$if ownership ? {
		if !then_uses_block_scope {
			tc.ownership_mark_scope_node(then_id)
		}
	}
	for binding in guard_bindings {
		$if ownership ? {
			tc.ownership_note_binding(binding.name, binding.typ, cond_id)
		}
		owner := tc.cur_scope.insert_with_owner(binding.name, binding.typ)
		if binding.is_mut {
			tc.fn_context.mut_local_owners[binding.name] = owner
		}
	}
	tc.check_branch_node(then_id, value_context)
	tc.pop_scope()
	$if ownership ? {
		tc.ownership_end_branch(then_id)
	}
	tc.smartcasts = clone_smartcasts(saved_smartcasts)
	if node.children_count > 2 {
		else_id := tc.a.child(&node, 2)
		else_smartcasts := tc.extract_else_branch_smartcasts(cond_id)
		for sc in else_smartcasts {
			if valid_string_data(sc.name) {
				tc.smartcasts[sc.name] = sc.typ
			}
		}
		$if ownership ? {
			tc.ownership_begin_branch()
		}
		if tc.valid_node_id(else_id) && tc.a.node(else_id).kind == .if_expr {
			tc.fn_context.mut_local_owners = saved_mut_local_owners.clone()
		}
		tc.check_branch_node(else_id, value_context)
		$if ownership ? {
			tc.ownership_end_branch(else_id)
		}
		if else_smartcasts.len > 0 {
			tc.smartcasts = clone_smartcasts(saved_smartcasts)
		}
	} else {
		$if ownership ? {
			tc.ownership_add_branch_group_base()
		}
	}
	$if ownership ? {
		tc.ownership_end_branch_group()
	}
	if value_context {
		tc.check_if_value_requirements(id, node, then_id)
	}
	if !value_context {
		return
	}
	for sc in smartcasts {
		if valid_string_data(sc.name) {
			tc.smartcasts[sc.name] = sc.typ
		}
	}
	then_type := tc.branch_tail_type(then_id)
	tc.smartcasts = clone_smartcasts(saved_smartcasts)
	mut else_type := Type(void_)
	if node.children_count > 2 {
		else_id := tc.a.child(&node, 2)
		else_type = tc.branch_tail_type(else_id)
	}
	if then_type !is Void && else_type !is Void {
		else_id := tc.a.child(&node, 2)
		if tc.branch_has_value_tail(then_id) && tc.branch_has_value_tail(else_id)
			&& !tc.if_branch_types_compatible(then_type, else_type, tc.branch_tail_is_array_literal(then_id), tc.branch_tail_is_array_literal(else_id)) {
			if tc.if_branch_empty_array_compatible(then_type, then_id, else_type, else_id) {
				return
			}
			then_tail := tc.branch_tail_expr_id(then_id)
			else_tail := tc.branch_tail_expr_id(else_id)
			if tc.if_branch_none_has_option_context(then_type, then_tail, else_type, else_tail) {
				if expected := tc.expected_context_for_expr(id) {
					if expected is OptionType {
						return
					}
				}
			}
			if tc.if_branch_error_has_result_context(then_type, else_type) {
				if expected := tc.expected_context_for_expr(id) {
					if expected is ResultType || is_ierror_type(expected) {
						return
					}
				}
			}
			if tc.if_branch_enum_shorthand_compatible(then_type, then_tail, else_type, else_tail) {
				return
			}
			if expected := tc.expected_context_for_expr(id) {
				if tc.constant_if_selected_branch_compatible_with_expected(node, expected) {
					return
				}
				branches_match_expected := tc.if_branch_types_compatible_with_expected(then_type,
					then_tail, else_type, else_tail, expected)
				if branches_match_expected {
					return
				}
			}
			if tc.should_diagnose(id) {
				pos := token.new_span(node.pos.id, node.pos.offset, node.pos.offset + 2)
				if (then_type is OptionType) != (else_type is OptionType)
					|| (then_type is ResultType) != (else_type is ResultType) {
					mut then_name := then_type.name()
					mut else_name := else_type.name()
					if then_types := tc.branch_explicit_comma_tail_types(then_id) {
						if else_types := tc.branch_explicit_comma_tail_types(else_id) {
							if then_types.len == else_types.len {
								then_name = Type(MultiReturn{
									types: then_types
								}).name()
								else_name = Type(MultiReturn{
									types: else_types
								}).name()
							}
						}
					}
					tc.record_error_at(.if_branch_mismatch,
						'mismatched types `${then_name}` and `${else_name}`', id, pos)
				} else {
					then_name := tc.diagnostic_expr_type_name(then_tail, then_type)
					else_name := tc.diagnostic_expr_type_name(else_tail, else_type)
					tc.record_error_at(.if_branch_mismatch,
						'mismatched types `${then_name}` and `${else_name}`', id, pos)
				}
			}
		}
	}
}

fn (tc &TypeChecker) if_parenthesized_condition_pos(condition flat.Node) token.Pos {
	file := tc.a.source_files[condition.pos.id] or { return condition.pos }
	source := tc.source_texts_by_file[file.name] or { return condition.pos }
	condition_start := int_max(0, int_min(condition.pos.offset, source.len))
	condition_end := int_max(condition_start, int_min(condition.pos.end, source.len))
	position := file.position(condition.pos)
	line_start := file.line_start(position.line)
	mut start := condition_start
	if line_start < condition_start {
		prefix := source[line_start..condition_start]
		if relative_if := prefix.last_index('if') {
			start = line_start + relative_if
			before_if := prefix[..relative_if].trim_right(' \t')
			if before_if.ends_with('else') {
				if relative_else := prefix[..relative_if].last_index('else') {
					start = line_start + relative_else
				}
			}
		}
	}
	return token.new_span(condition.pos.id, start, condition_end)
}

fn (tc &TypeChecker) branch_explicit_comma_tail_types(id flat.NodeId) ?[]Type {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .block && node.value == 'comma_exprs' {
		mut types := []Type{cap: node.children_count}
		for i in 0 .. node.children_count {
			stmt_id := tc.a.child(node, i)
			if !tc.valid_node_id(stmt_id) {
				return none
			}
			stmt := tc.a.node(stmt_id)
			if stmt.kind != .expr_stmt || stmt.children_count != 1 {
				return none
			}
			value_id := tc.a.child(stmt, 0)
			typ := tc.expr_type(value_id) or { tc.resolve_type(value_id) }
			if typ is Unknown || !type_has_runtime_value(typ) {
				return none
			}
			types << typ
		}
		return if types.len > 1 { types } else { none }
	}
	if node.kind !in [.block, .match_branch] || node.children_count == 0 {
		return none
	}
	return tc.branch_explicit_comma_tail_types(tc.a.child(node, node.children_count - 1))
}

fn (mut tc TypeChecker) check_if_value_requirements(id flat.NodeId, node flat.Node, then_id flat.NodeId) {
	tc.check_empty_or_value_tail(then_id)
	if !tc.branch_has_value_tail(then_id) && !tc.stmt_definitely_returns(then_id) {
		tc.record_error_at(.if_branch_mismatch,
			'`if` expression requires an expression as the last statement of every branch',
			then_id, tc.if_branch_missing_value_pos(then_id))
	}
	if node.children_count <= 2 {
		pos := token.new_span(node.pos.id, node.pos.offset, node.pos.offset + 2)
		tc.record_error_at(.if_branch_mismatch, '`if` expression needs `else` clause', id, pos)
		return
	}
	else_id := tc.a.child(&node, 2)
	tc.check_empty_or_value_tail(else_id)
	if !tc.branch_has_value_tail(else_id) && !tc.stmt_definitely_returns(else_id) {
		tc.record_error_at(.if_branch_mismatch,
			'`if` expression requires an expression as the last statement of every branch',
			else_id, tc.if_branch_missing_value_pos(else_id))
	}
	if tc.if_expr_all_tails_are_none(node) {
		pos := token.new_span(node.pos.id, node.pos.offset, node.pos.offset + 2)
		tc.record_error_at(.if_branch_mismatch,
			'invalid if expression, must supply at least one value other than `none`', id, pos)
	}
}

fn (tc &TypeChecker) if_branch_missing_value_pos(branch_id flat.NodeId) token.Pos {
	if !tc.valid_node_id(branch_id) {
		return token.Pos{}
	}
	branch := tc.a.node(branch_id)
	if branch.kind != .block || branch.children_count == 0 {
		return tc.if_branch_header_pos(branch_id)
	}
	tail_id := tc.a.child(branch, branch.children_count - 1)
	if !tc.valid_node_id(tail_id) {
		return tc.if_branch_header_pos(branch_id)
	}
	tail := tc.a.node(tail_id)
	if tail.kind in [.assign, .decl_assign, .selector_assign, .index_assign]
		&& tail.children_count >= 2 {
		lhs_id := tc.a.child(tail, 0)
		rhs_id := tc.a.child(tail, 1)
		if tail.op != .assign {
			return tc.compound_assignment_operator_pos(lhs_id, rhs_id,
				assignment_operator_text(tail.op))
		}
		return tc.assignment_operator_pos(*tail, lhs_id, rhs_id)
	}
	return tail.pos
}

fn (mut tc TypeChecker) check_empty_or_value_tail(branch_id flat.NodeId) {
	tail_id := tc.branch_tail_expr_id(branch_id)
	if !tc.valid_node_id(tail_id) {
		return
	}
	tail := tc.a.node(tail_id)
	if tail.kind == .or_expr && tail.children_count >= 2 {
		fallback := tc.a.child_node(tail, 1)
		if fallback.kind == .block && fallback.children_count == 0 {
			source_id := tc.a.child(tail, 0)
			source := tc.a.node(source_id)
			tc.record_error_at(.if_branch_mismatch,
				'the final expression in `if` or `match`, must have a value of a non-void type',
				source_id, source.pos)
			return
		}
	}
	if unalias_type(tc.resolve_type(tail_id)) is Void && !tc.branch_tail_never_returns(branch_id) {
		tc.record_error_at(.if_branch_mismatch,
			'the final expression in `if` or `match`, must have a value of a non-void type',
			tail_id, tail.pos)
	}
}

fn (tc &TypeChecker) if_expr_all_tails_are_none(node flat.Node) bool {
	if node.children_count <= 2 {
		return false
	}
	then_tail := tc.branch_tail_expr_id(tc.a.child(&node, 1))
	if !tc.branch_tail_is_none_literal(then_tail) {
		return false
	}
	else_id := tc.a.child(&node, 2)
	else_node := tc.a.node(else_id)
	if else_node.kind == .if_expr {
		return tc.if_expr_all_tails_are_none(else_node)
	}
	return tc.branch_tail_is_none_literal(tc.branch_tail_expr_id(else_id))
}

fn (tc &TypeChecker) if_branch_header_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	brace := node.pos.offset
	if brace < 0 || brace >= source.len {
		return node.pos
	}
	prefix := source[..brace]
	line_start := if idx := prefix.last_index('\n') { idx + 1 } else { 0 }
	line_prefix := source[line_start..brace]
	start := if idx := line_prefix.last_index('else') {
		line_start + idx
	} else if idx := line_prefix.last_index('if') {
		line_start + idx
	} else {
		brace
	}
	mut end := brace
	for end > start && source[end - 1] in [` `, `\t`] {
		end--
	}
	return token.new_span(node.pos.id, start, end)
}

fn (mut tc TypeChecker) enable_explicit_mut_smartcasts(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind == .is_expr && node.children_count > 0 {
		tc.enable_explicit_mut_smartcast_target(tc.a.child(node, 0))
		return
	}
	if node.kind == .infix && node.op in [.logical_and, .logical_or] {
		for i in 0 .. node.children_count {
			tc.enable_explicit_mut_smartcasts(tc.a.child(node, i))
		}
		return
	}
	if node.kind == .infix && node.op in [.eq, .ne] {
		for i in 0 .. node.children_count {
			tc.enable_explicit_mut_smartcast_target(tc.a.child(node, i))
		}
		return
	}
	if node.kind == .paren && node.children_count > 0 {
		tc.enable_explicit_mut_smartcasts(tc.a.child(node, 0))
	}
}

fn (mut tc TypeChecker) enable_explicit_mut_smartcast_target(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if !node.is_mut {
		return
	}
	root_id := tc.lvalue_root_ident(id) or { return }
	root := tc.a.node(root_id)
	if root.value.len == 0 || root.value == '_' {
		return
	}
	owner := tc.cur_scope.lookup_owner(root.value) or { return }
	if !tc.ident_is_mutable_lvalue(root.value) {
		tc.record_error_at(.assignment_mismatch,
			'`${root.value}` is immutable, declare it with `mut` to make it mutable', root_id,
			tc.node_value_diagnostic_pos(root_id))
	}
	tc.fn_context.mut_local_owners[root.value] = owner
}

fn (mut tc TypeChecker) record_constant_condition_diagnostics(id flat.NodeId) {
	value := tc.constant_bool_value(id) or { return }
	pos := tc.constant_condition_diagnostic_pos(id)
	tc.record_notice_at(.condition_mismatch, if value {
		'condition is always true'
	} else {
		'condition is always false'
	}, id, pos)
	if value && tc.is_always_true_self_comparison(id) {
		tc.record_warning_at(.condition_mismatch,
			'self-comparison in `if` condition is always true; following branches may be unreachable',
			id, pos)
	}
}

fn (tc &TypeChecker) constant_condition_diagnostic_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	if node.kind != .infix || node.op !in [.logical_and, .logical_or] {
		return node.pos
	}
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	if node.pos.offset < 0 || node.pos.offset > source.len {
		return node.pos
	}
	prefix := source[..node.pos.offset]
	line_start := if idx := prefix.last_index('\n') { idx + 1 } else { 0 }
	return token.new_span(node.pos.id, line_start, int_min(line_start + 1, source.len))
}

fn (tc &TypeChecker) constant_bool_value(id flat.NodeId) ?bool {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .paren && node.children_count > 0 {
		return tc.constant_bool_value(tc.a.child(node, 0))
	}
	if node.kind == .bool_literal {
		return node.value == 'true'
	}
	if node.kind != .infix || node.children_count < 2 {
		return none
	}
	lhs_id := tc.a.child(node, 0)
	rhs_id := tc.a.child(node, 1)
	if node.op == .logical_and {
		lhs := tc.constant_bool_value(lhs_id)?
		rhs := tc.constant_bool_value(rhs_id)?
		return lhs && rhs
	}
	if node.op == .logical_or {
		lhs := tc.constant_bool_value(lhs_id)?
		rhs := tc.constant_bool_value(rhs_id)?
		return lhs || rhs
	}
	return tc.constant_comparison_value(lhs_id, rhs_id, node.op)
}

fn (tc &TypeChecker) constant_comparison_value(lhs_id flat.NodeId, rhs_id flat.NodeId, op flat.Op) ?bool {
	if op !in [.eq, .ne, .lt, .le, .gt, .ge] {
		return none
	}
	if tc.same_simple_comparison_expr(lhs_id, rhs_id) {
		return match op {
			.eq, .le, .ge { true }
			.ne, .lt, .gt { false }
			else { false }
		}
	}
	lhs := tc.constant_scalar_value(lhs_id)?
	rhs := tc.constant_scalar_value(rhs_id)?
	if lhs.kind != rhs.kind {
		return none
	}
	if lhs.kind in [u8(1), 2] {
		return match op {
			.eq { lhs.number == rhs.number }
			.ne { lhs.number != rhs.number }
			.lt { lhs.number < rhs.number }
			.le { lhs.number <= rhs.number }
			.gt { lhs.number > rhs.number }
			.ge { lhs.number >= rhs.number }
			else { false }
		}
	}
	if lhs.kind == 3 {
		return match op {
			.eq { lhs.text == rhs.text }
			.ne { lhs.text != rhs.text }
			.lt { lhs.text < rhs.text }
			.le { lhs.text <= rhs.text }
			.gt { lhs.text > rhs.text }
			.ge { lhs.text >= rhs.text }
			else { false }
		}
	}
	if lhs.kind == 4 {
		return match op {
			.eq { lhs.bool_value == rhs.bool_value }
			.ne { lhs.bool_value != rhs.bool_value }
			else { none }
		}
	}
	if lhs.kind == 5 {
		return match op {
			.eq { true }
			.ne { false }
			else { none }
		}
	}
	return none
}

fn (tc &TypeChecker) constant_scalar_value(id flat.NodeId) ?ConstantScalar {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .paren && node.children_count > 0 {
		return tc.constant_scalar_value(tc.a.child(node, 0))
	}
	return match node.kind {
		.int_literal {
			ConstantScalar{
				kind:   1
				number: f64(v_int_literal_value(node.value)?)
			}
		}
		.float_literal {
			ConstantScalar{
				kind:   1
				number: node.value.f64()
			}
		}
		.char_literal {
			ConstantScalar{
				kind:   2
				number: f64(match_char_literal_value(node.value)?)
			}
		}
		.string_literal {
			ConstantScalar{
				kind: 3
				text: node.value
			}
		}
		.bool_literal {
			ConstantScalar{
				kind:       4
				bool_value: node.value == 'true'
			}
		}
		.none_expr {
			ConstantScalar{
				kind: 5
			}
		}
		else {
			none
		}
	}
}

fn (tc &TypeChecker) same_simple_comparison_expr(lhs_id flat.NodeId, rhs_id flat.NodeId) bool {
	lhs := tc.simple_comparison_expr(lhs_id) or { return false }
	rhs := tc.simple_comparison_expr(rhs_id) or { return false }
	if tc.resolve_type(lhs_id).is_float() || tc.resolve_type(rhs_id).is_float() {
		return false
	}
	return lhs == rhs
}

fn (tc &TypeChecker) is_always_true_self_comparison(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind == .paren && node.children_count > 0 {
		return tc.is_always_true_self_comparison(tc.a.child(node, 0))
	}
	return node.kind == .infix && node.op == .eq && node.children_count >= 2
		&& tc.same_simple_comparison_expr(tc.a.child(node, 0), tc.a.child(node, 1))
}

fn (tc &TypeChecker) simple_comparison_expr(id flat.NodeId) ?string {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .paren && node.children_count > 0 {
		return tc.simple_comparison_expr(tc.a.child(node, 0))
	}
	if node.kind !in [.ident, .selector] {
		return none
	}
	key := tc.expr_key(id)
	return if key.len > 0 { key } else { none }
}

fn (tc &TypeChecker) if_branch_empty_array_compatible(a Type, a_branch flat.NodeId, b Type, b_branch flat.NodeId) bool {
	a_empty := tc.expr_is_empty_bare_array_literal(tc.branch_tail_expr_id(a_branch))
	b_empty := tc.expr_is_empty_bare_array_literal(tc.branch_tail_expr_id(b_branch))
	return (a_empty && array_like_elem_type(b) != none)
		|| (b_empty && array_like_elem_type(a) != none)
}

fn (tc &TypeChecker) expr_is_empty_bare_array_literal(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	return node.kind == .array_literal && node.children_count == 0
}

fn (tc &TypeChecker) if_branch_none_has_option_context(a Type, a_tail flat.NodeId, b Type, b_tail flat.NodeId) bool {
	if (a is None || is_option_void_type(a)) && tc.branch_tail_is_none_literal(a_tail) {
		return b !is Void && b !is None && !is_option_void_type(b)
	}
	if (b is None || is_option_void_type(b)) && tc.branch_tail_is_none_literal(b_tail) {
		return a !is Void && a !is None && !is_option_void_type(a)
	}
	return false
}

fn (tc &TypeChecker) if_branch_error_has_result_context(a Type, b Type) bool {
	_ = tc
	if is_ierror_type(a) {
		return b !is Void && !is_ierror_type(b)
	}
	if is_ierror_type(b) {
		return a !is Void && !is_ierror_type(a)
	}
	return false
}

fn (mut tc TypeChecker) if_branch_enum_shorthand_compatible(a Type, a_tail flat.NodeId, b Type, b_tail flat.NodeId) bool {
	if a is Enum && tc.valid_node_id(b_tail) && tc.a.nodes[int(b_tail)].kind == .enum_val {
		return tc.type_compatible(tc.resolve_expr(b_tail, a), a)
	}
	if b is Enum && tc.valid_node_id(a_tail) && tc.a.nodes[int(a_tail)].kind == .enum_val {
		return tc.type_compatible(tc.resolve_expr(a_tail, b), b)
	}
	return false
}

fn (mut tc TypeChecker) check_stmt_node(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	idx := int(id)
	if tc.parallel_check_sparse {
		if tc.in_check_range(idx) && idx < tc.statement_nodes.len {
			tc.statement_nodes[idx] = true
		} else {
			tc.sparse_statement_nodes[idx] = true
		}
		tc.check_node(id)
		tc.check_unused_expression_statement(id)
		$if ownership ? {
			tc.ownership_after_stmt_node(id)
		}
		return
	}
	if idx >= tc.statement_nodes.len {
		tc.extend_node_caches(tc.a.nodes.len)
	}
	if idx < tc.statement_nodes.len {
		tc.statement_nodes[idx] = true
	}
	tc.check_node(id)
	tc.check_unused_expression_statement(id)
	$if ownership ? {
		tc.ownership_after_stmt_node(id)
	}
}

fn (tc &TypeChecker) is_statement_node(id flat.NodeId) bool {
	idx := int(id)
	if tc.parallel_check_sparse {
		if tc.in_check_range(idx) {
			return idx < tc.statement_nodes.len && tc.statement_nodes[idx]
		}
		return tc.sparse_statement_nodes[idx]
	}
	return idx >= 0 && idx < tc.statement_nodes.len && tc.statement_nodes[idx]
}

fn (mut tc TypeChecker) check_statement_sequence(node flat.Node, body_start int, value_tail bool) {
	saved_smartcasts := clone_smartcasts(tc.smartcasts)
	defer {
		tc.smartcasts = clone_smartcasts(saved_smartcasts)
	}
	last_idx := int(node.children_count) - 1
	mut sequence_exited := false
	mut unreachable_id := flat.empty_node
	for i in body_start .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind == .label_stmt {
			sequence_exited = false
			unreachable_id = flat.empty_node
		} else if sequence_exited && !tc.valid_node_id(unreachable_id) {
			unreachable_id = child_id
		}
		is_value_tail := value_tail && i == last_idx
		if is_value_tail {
			tc.check_node(child_id)
		} else {
			tc.check_stmt_node(child_id)
		}
		tc.apply_post_if_exit_smartcasts(child_id)
		tc.apply_post_assert_smartcasts(child_id)
		$if ownership ? {
			if !is_value_tail {
				tc.ownership_flush_value_branch_moves()
			}
		}
		if tc.statement_exits_sequence(child_id, child) {
			sequence_exited = true
		}
	}
	if tc.valid_node_id(unreachable_id) && tc.should_diagnose(unreachable_id) {
		tc.record_error_at(.return_mismatch, 'unreachable code', unreachable_id,
			tc.unreachable_statement_diagnostic_pos(unreachable_id))
	}
}

fn (tc &TypeChecker) unreachable_statement_diagnostic_pos(id flat.NodeId) token.Pos {
	node := tc.a.node(id)
	if node.kind == .return_stmt {
		return tc.previous_source_line_matching(node.pos, 'return')
	}
	if node.kind in [.assign, .decl_assign, .selector_assign, .index_assign]
		&& node.children_count >= 2 {
		return tc.assignment_operator_pos(*node, tc.a.child(node, 0), tc.a.child(node, 1))
	}
	if node.kind == .expr_stmt && node.children_count > 0 {
		return tc.a.node(tc.a.child(node, 0)).pos
	}
	return node.pos
}

fn (mut tc TypeChecker) check_unused_expression_statement(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	stmt := tc.a.node(id)
	if stmt.kind != .expr_stmt || stmt.children_count != 1 {
		return
	}
	expr_id := tc.a.child(stmt, 0)
	expr := tc.a.node(expr_id)
	if tc.expr_subtree_has_error(expr_id) {
		return
	}
	if expr.kind == .call {
		tc.check_must_use_call(expr_id, expr)
		return
	}
	if expr.kind in [.spawn_expr, .dump_expr, .or_expr, .if_expr, .match_stmt, .lock_expr,
		.select_stmt, .fn_literal, .lambda_expr] {
		return
	}
	if expr.kind == .selector && expr.children_count > 0 {
		if tc.resolve_type(tc.a.child(expr, 0)) is Void {
			return
		}
	}
	if expr.kind == .postfix && expr.op in [.inc, .dec] {
		return
	}
	if expr.kind == .prefix && expr.op == .arrow {
		tc.record_error_at(.unknown_ident, 'expression evaluated but not used', expr_id, token.new_span(expr.pos.id,
			expr.pos.offset, expr.pos.offset + 2))
		return
	}
	if expr.kind == .infix && expr.op == .arrow {
		return
	}
	if expr.kind == .infix && expr.op == .left_shift && expr.children_count > 0 {
		receiver := unalias_type(unwrap_pointer(tc.resolve_type(tc.a.child(expr, 0))))
		if receiver is Array
			|| (receiver is OptionType && unalias_type(receiver.base_type) is Array) {
			return
		}
	}
	if expr.kind == .infix && expr.op in [.left_shift, .right_shift, .right_shift_unsigned] {
		return
	}
	if tc.resolve_type(expr_id) is Void {
		return
	}
	if expr.kind in [.int_literal, .float_literal, .bool_literal, .char_literal, .string_literal] {
		tc.record_warning_at(.unknown_ident, 'expression evaluated but not used', expr_id, expr.pos)
		return
	}
	if expr.kind == .ident {
		tc.record_error_at(.unknown_ident, '`${expr.value}` evaluated but not used', expr_id,
			expr.pos)
		return
	}
	mut pos := expr.pos
	if expr.kind == .infix && expr.children_count > 0 {
		lhs_id := tc.a.child(expr, 0)
		lhs := tc.a.node(lhs_id)
		if lhs.kind == .selector {
			start := tc.node_value_diagnostic_pos(lhs_id)
			pos = token.new_span(pos.id, start.offset, pos.end)
		}
	}
	tc.record_error_at(.unknown_ident, 'expression evaluated but not used', expr_id, pos)
}

fn (mut tc TypeChecker) check_must_use_call(id flat.NodeId, node flat.Node) {
	info := tc.resolve_call_info(id, node) or { return }
	decl_module := tc.fn_type_modules[info.name] or { tc.cur_module }
	decl := tc.visible_mutation_fn_decl(info.name, decl_module) or { return }
	decl_id := flat.NodeId(decl.idx)
	if !tc.declaration_has_attribute(decl_id, 'must_use') {
		return
	}
	callee := tc.a.child_node(&node, 0)
	is_method := info.has_receiver && callee.kind == .selector
	name := if is_method { callee.value } else { info.name.all_after_last('.') }
	pos := if is_method {
		tc.method_call_name_pos(node, callee)
	} else {
		node.pos
	}
	kind := if is_method { 'method' } else { 'function' }
	tc.record_warning_at(.unknown_ident,
		'return value must be used, ${kind} `${name}` was tagged with `@[must_use]`', id, pos)
}

fn (mut tc TypeChecker) check_branch_node(id flat.NodeId, value_tail bool) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .block {
		tc.push_scope()
		$if ownership ? {
			tc.ownership_mark_scope_node(id)
		}
		tc.check_statement_sequence(node, 0, value_tail)
		tc.pop_scope()
		return
	}
	if value_tail {
		tc.check_node(id)
	} else {
		tc.check_stmt_node(id)
	}
}

fn (mut tc TypeChecker) apply_post_if_exit_smartcasts(id flat.NodeId) {
	for binding in tc.post_if_exit_smartcasts(id) {
		if valid_string_data(binding.name) {
			tc.smartcasts[binding.name] = binding.typ
		}
	}
}

fn (mut tc TypeChecker) apply_post_assert_smartcasts(id flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind != .assert_stmt || node.children_count == 0 {
		return
	}
	for binding in tc.extract_smartcasts(tc.a.child(node, 0)) {
		if valid_string_data(binding.name) {
			tc.smartcasts[binding.name] = binding.typ
		}
	}
}

fn (tc &TypeChecker) post_if_exit_smartcasts(id flat.NodeId) []LocalBinding {
	if !tc.valid_node_id(id) {
		return []LocalBinding{}
	}
	node := tc.a.nodes[int(id)]
	if node.kind != .if_expr || node.children_count < 2 {
		return []LocalBinding{}
	}
	cond_id := tc.a.child(&node, 0)
	then_id := tc.a.child(&node, 1)
	if binding := tc.negated_is_smartcast(cond_id) {
		if tc.stmt_definitely_returns(then_id) {
			return [binding]
		}
	}
	if tc.stmt_definitely_returns(then_id) {
		cond := tc.a.nodes[int(cond_id)]
		if cond.kind == .infix && cond.op == .eq && cond.children_count >= 2 {
			if binding := tc.option_none_cmp_binding(cond) {
				return [binding]
			}
		}
	}
	if node.children_count >= 3 {
		else_id := tc.a.child(&node, 2)
		if tc.stmt_definitely_returns(else_id) {
			return tc.extract_smartcasts(cond_id)
		}
	}
	return []LocalBinding{}
}

fn (tc &TypeChecker) negated_is_smartcast(cond_id flat.NodeId) ?LocalBinding {
	if !tc.valid_node_id(cond_id) {
		return none
	}
	cond := tc.a.nodes[int(cond_id)]
	if cond.kind != .prefix || cond.op != .not || cond.children_count == 0 {
		return none
	}
	inner_id := tc.a.child(&cond, 0)
	if !tc.valid_node_id(inner_id) {
		return none
	}
	inner := tc.a.nodes[int(inner_id)]
	if inner.kind != .is_expr || inner.children_count == 0 {
		return none
	}
	expr_id := tc.a.child(&inner, 0)
	key := tc.expr_key(expr_id)
	if key.len == 0 || !valid_string_data(key) || inner.value.len == 0 {
		return none
	}
	return LocalBinding{
		name: key
		typ:  tc.smartcast_target_type_for_is_expr(expr_id, inner.value)
	}
}

// branch_has_value_tail converts branch has value tail data for types.
fn (tc &TypeChecker) branch_has_value_tail(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .block {
		if node.children_count == 0 {
			return false
		}
		last_id := tc.a.child(&node, node.children_count - 1)
		if !tc.valid_node_id(last_id) {
			return false
		}
		last := tc.a.nodes[int(last_id)]
		return last.kind in [.expr_stmt, .if_expr, .match_stmt]
			|| (last.kind == .block && last.value == 'comma_exprs')
	}
	if node.kind == .match_branch {
		body_start := if node.value == 'else' { 0 } else { node.value.int() }
		if node.children_count <= body_start {
			return false
		}
		last_id := tc.a.child(&node, node.children_count - 1)
		if !tc.valid_node_id(last_id) {
			return false
		}
		last := tc.a.nodes[int(last_id)]
		return last.kind in [.expr_stmt, .if_expr, .match_stmt]
			|| (last.kind == .block && last.value == 'comma_exprs')
	}
	return node.kind !in [.assign, .decl_assign, .selector_assign, .index_assign, .return_stmt,
		.block]
}

// check_condition validates check condition state for types.
fn (mut tc TypeChecker) check_condition(cond_id flat.NodeId) []LocalBinding {
	if int(cond_id) < 0 {
		return []LocalBinding{}
	}
	cond := tc.a.nodes[int(cond_id)]
	if cond.kind == .decl_assign {
		return tc.check_if_guard(cond_id, cond)
	}
	if cond.kind == .infix && cond.op == .logical_and && cond.children_count >= 2 {
		lhs_id := tc.a.child(&cond, 0)
		rhs_id := tc.a.child(&cond, 1)
		mut bindings := tc.check_condition(lhs_id)
		saved_smartcasts := clone_smartcasts(tc.smartcasts)
		for sc in tc.extract_smartcasts(lhs_id) {
			if valid_string_data(sc.name) {
				tc.smartcasts[sc.name] = sc.typ
			}
		}
		rhs_bindings := tc.check_condition(rhs_id)
		bindings << rhs_bindings
		tc.smartcasts = clone_smartcasts(saved_smartcasts)
		tc.check_infix(cond_id, cond)
		has_unresolved_generic_name := tc.expr_has_unresolved_generic_name_ident(cond_id)
		cond_type := tc.resolve_type(cond_id)
		if (!tc.condition_type_is_bool_like(cond_type) || has_unresolved_generic_name)
			&& tc.should_diagnose(cond_id) {
			cond_name := if has_unresolved_generic_name {
				'void'
			} else {
				tc.diagnostic_expr_type_name(cond_id, cond_type)
			}
			tc.record_error(.condition_mismatch,
				'non-bool type `${cond_name}` used as if condition', cond_id)
		}
		return bindings
	}
	tc.check_bool_condition(cond_id)
	return []LocalBinding{}
}

// check_bool_condition validates check bool condition state for types.
fn (mut tc TypeChecker) check_bool_condition(cond_id flat.NodeId) {
	tc.check_node(cond_id)
	cond_type := tc.resolve_type(cond_id)
	if (cond_type is Unknown && cond_type.reason == 'invalid variable')
		|| tc.expr_contains_invalid_variable_binding(cond_id) {
		tc.record_error(.condition_mismatch, 'non-bool type `void` used as if condition', cond_id)
		return
	}
	if !tc.condition_type_is_bool_like(cond_type) && tc.should_diagnose(cond_id) {
		tc.record_error(.condition_mismatch, 'non-bool type `${tc.diagnostic_expr_type_name(cond_id,
			cond_type)}` used as if condition', cond_id)
	}
}

fn (tc &TypeChecker) expr_contains_invalid_variable_binding(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind == .ident {
		if typ := tc.non_file_scope_type(node.value) {
			if typ is Unknown && typ.reason == 'invalid variable' {
				return true
			}
		}
	}
	for i in 0 .. node.children_count {
		if tc.expr_contains_invalid_variable_binding(tc.a.child(node, i)) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) condition_type_is_bool_like(typ Type) bool {
	if tc.type_compatible(typ, Type(bool_)) {
		return true
	}
	return false
}

fn (mut tc TypeChecker) check_for_condition(cond_id flat.NodeId, _node flat.Node) {
	condition := tc.a.node(cond_id)
	if condition.kind == .match_stmt {
		tc.check_stmt_node(cond_id)
		file := tc.a.source_files[condition.pos.id] or { &token.File{} }
		source := tc.source_texts_by_file[file.name] or { '' }
		pos := closest_identifier_span(source, 'match', condition.pos.offset, condition.pos.id) or {
			condition.pos
		}
		tc.record_error_at(.condition_mismatch, 'cannot use `match` in `for` loop', cond_id, pos)
		return
	}
	tc.check_node(cond_id)
	cond_type := tc.resolve_type(cond_id)
	if tc.condition_type_is_bool_like(cond_type) {
		return
	}
	if _node.value == 'c_style' && unalias_type(cond_type) is Pointer {
		return
	}
	if tc.should_diagnose(cond_id) {
		tc.record_error(.condition_mismatch,
			'if condition must be `bool`, not `${cond_type.name()}`', cond_id)
	}
}

// check_if_guard validates check if guard state for types.
fn (mut tc TypeChecker) check_if_guard(id flat.NodeId, node flat.Node) []LocalBinding {
	if node.children_count < 2 {
		return []LocalBinding{}
	}
	rhs_id := tc.a.child(&node, 1)
	tc.check_node(rhs_id)
	mut rhs_type := tc.resolve_type(rhs_id)
	rhs_node := tc.a.node(rhs_id)
	if rhs_node.kind == .prefix && rhs_node.op == .amp && rhs_node.children_count > 0 {
		mut address_child := tc.a.child_node(rhs_node, 0)
		if address_child.kind == .paren && address_child.children_count > 0 {
			address_child = tc.a.child_node(address_child, 0)
		}
		if address_child.kind == .selector {
			if declared := tc.selector_declared_value_type(*address_child) {
				if unalias_type(declared) is OptionType {
					return []LocalBinding{}
				}
			}
		}
	}
	if rhs_node.kind == .ident {
		if base := tc.mut_param_base_for_current_ident(rhs_node.value, rhs_type) {
			rhs_type = base
		}
	}
	if rhs_node.kind == .selector {
		if declared := tc.selector_declared_value_type(*rhs_node) {
			if declared is OptionType || declared is ResultType {
				rhs_type = declared
			}
		}
	}
	mut payload := Type(void_)
	is_optional_result := rhs_type is OptionType || rhs_type is ResultType
	if rhs_type is OptionType {
		payload = rhs_type.base_type
	} else if rhs_type is ResultType {
		payload = rhs_type.base_type
	} else {
		rhs := tc.a.nodes[int(rhs_id)]
		if rhs.kind == .index && rhs.children_count > 0 {
			base_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(&rhs, 0)))
			if base_type is Map {
				payload = base_type.value_type
			} else if base_type is Array {
				payload = base_type.elem_type
			} else if base_type is ArrayFixed {
				payload = base_type.elem_type
			} else if base_type is String {
				payload = Type(u8_)
			}
		} else if rhs.kind == .call && rhs.children_count > 0 {
			fn_node := tc.a.child_node(&rhs, 0)
			if fn_node.kind == .selector && fn_node.value == 'get' {
				if arr := tc.call_receiver_array_type(rhs) {
					payload = arr.elem_type
				}
			}
		} else if rhs.kind == .prefix && rhs.op == .arrow && rhs.children_count > 0 {
			source_type := unalias_and_unwrap_pointer_type(tc.resolve_type(tc.a.child(&rhs, 0)))
			if source_type is Channel {
				payload = source_type.elem_type
			}
		}
	}
	if payload is Void && !is_optional_result {
		if tc.should_diagnose(id) {
			tc.record_error_at(.condition_mismatch,
				'expression should either return an Option or a Result', rhs_id, rhs_node.pos)
		}
		payload = rhs_type
	}
	lhs_ids := tc.if_guard_lhs_ids(node)
	if payload is Void {
		if is_optional_result && tc.should_diagnose(id) {
			tc.record_error_at(.condition_mismatch,
				'if guard expects non-propagate option or result', id,
				tc.if_guard_diagnostic_pos(node))
		}
		return tc.if_guard_unknown_bindings(lhs_ids, node.is_mut)
	}
	if payload is MultiReturn {
		if lhs_ids.len != payload.types.len && tc.should_diagnose(id) {
			tc.record_error_at(.condition_mismatch,
				'if guard expects ${payload.types.len} variables, but got ${lhs_ids.len}', id,
				tc.if_guard_diagnostic_pos(node))
		}
		mut result := []LocalBinding{}
		for i, lhs_id in lhs_ids {
			lhs := tc.a.nodes[int(lhs_id)]
			if lhs.kind == .ident && lhs.value.len > 0 && lhs.value != '_' {
				result << LocalBinding{
					name:   lhs.value
					typ:    if i < payload.types.len {
						payload.types[i]
					} else {
						unknown_type('extra if guard binding')
					}
					is_mut: lhs.is_mut || node.is_mut
				}
			}
		}
		return result
	}
	if lhs_ids.len != 1 && tc.should_diagnose(id) {
		tc.record_error_at(.condition_mismatch,
			'if guard expects a single variable, but got ${lhs_ids.len}', id,
			tc.if_guard_diagnostic_pos(node))
	}
	if lhs_ids.len > 0 {
		mut result := []LocalBinding{}
		for i, lhs_id in lhs_ids {
			lhs := tc.a.nodes[int(lhs_id)]
			if lhs.kind != .ident || lhs.value.len == 0 || lhs.value == '_' {
				continue
			}
			result << LocalBinding{
				name:   lhs.value
				typ:    if i == 0 { payload } else { unknown_type('extra if guard binding') }
				is_mut: lhs.is_mut || node.is_mut
			}
		}
		return result
	}
	return []LocalBinding{}
}

fn (tc &TypeChecker) if_guard_unknown_bindings(lhs_ids []flat.NodeId, is_mut bool) []LocalBinding {
	mut result := []LocalBinding{}
	for lhs_id in lhs_ids {
		lhs := tc.a.node(lhs_id)
		if lhs.kind == .ident && lhs.value.len > 0 && lhs.value != '_' {
			result << LocalBinding{
				name:   lhs.value
				typ:    unknown_type('invalid if guard')
				is_mut: lhs.is_mut || is_mut
			}
		}
	}
	return result
}

fn (tc &TypeChecker) if_guard_diagnostic_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start_limit := int_max(0, int_min(node.pos.offset, source.len))
	line_start := if idx := source[..start_limit].last_index('\n') { idx + 1 } else { 0 }
	prefix := source[line_start..start_limit]
	start := if idx := prefix.last_index('if ') {
		line_start + idx
	} else {
		start_limit
	}
	mut end := int_max(start, int_min(node.pos.end, source.len))
	for end > start && source[end - 1] in [` `, `\t`, `{`] {
		end--
	}
	return token.new_span(node.pos.id, start, end)
}

fn (tc &TypeChecker) if_guard_lhs_ids(node flat.Node) []flat.NodeId {
	if node.children_count < 2 {
		return []flat.NodeId{}
	}
	mut lhs_ids := []flat.NodeId{cap: int(node.children_count) - 1}
	lhs_ids << tc.a.child(&node, 0)
	for i in 2 .. node.children_count {
		lhs_ids << tc.a.child(&node, i)
	}
	return lhs_ids
}

// check_match_stmt validates check match stmt state for types.
fn (mut tc TypeChecker) check_match_stmt(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	value_context := !tc.is_statement_node(id)
	mut has_value_tail := false
	if value_context {
		for i in 1 .. node.children_count {
			if tc.branch_has_value_tail(tc.a.child(&node, i)) {
				has_value_tail = true
				break
			}
		}
	}
	subject_id := tc.a.child(&node, 0)
	saved_mut_local_owners := tc.fn_context.mut_local_owners.clone()
	defer {
		tc.fn_context.mut_local_owners = saved_mut_local_owners.clone()
	}
	tc.enable_explicit_mut_smartcast_target(subject_id)
	tc.check_node(subject_id)
	subject := tc.a.node(subject_id)
	mut subject_declared_type := tc.resolve_type(subject_id)
	if subject_declared_type is Unknown && subject.kind == .ident
		&& tc.errors.any(it.kind == .unknown_ident && it.node == subject_id) {
		subject_declared_type = Type(void_)
	}
	if subject.kind == .paren {
		tc.record_warning_at(.condition_mismatch,
			'unnecessary `()` in `match` condition, use `match expr {` instead of `match (expr) {`.',
			subject_id, subject.pos)
	}
	if subject.kind == .none_expr {
		tc.record_error_at(.condition_mismatch, '`none` cannot be a match condition', id,
			tc.match_header_pos(node))
	}
	if subject.kind == .ident && ((unalias_type(subject_declared_type) is Pointer
		&& !tc.mut_param_binding_matches_lvalue(subject.value))
		|| tc.current_binding_is_shared(subject.value)) {
		tc.record_error_at(.condition_mismatch,
			'missing `*` dereferencing `${subject.value}` in match statement', subject_id,
			tc.node_value_diagnostic_pos(subject_id))
		return
	}
	missing_non_else := tc.check_match_branch_structure(id, node)
	subject_key := tc.expr_key(subject_id)
	subject_type := unalias_and_unwrap_pointer_type(subject_declared_type)
	mut seen_match_values := map[int]int{}
	mut seen_match_ranges := []MatchSeenRange{}
	mut seen_match_patterns := map[string]int{}
	$if ownership ? {
		if value_context {
			tc.ownership_begin_value_branch_group()
		} else {
			tc.ownership_begin_branch_group()
		}
	}
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		branch := tc.a.child_node(&node, i)
		if branch.kind != .match_branch {
			tc.check_node(branch_id)
			continue
		}
		n_conds := if branch.value == 'else' { 0 } else { branch.value.int() }
		if subject_type is OptionType && n_conds > 0 {
			mut has_value_condition := false
			for j in 0 .. n_conds {
				if tc.a.child_node(branch, j).kind != .none_expr {
					has_value_condition = true
					break
				}
			}
			if has_value_condition {
				first := tc.a.child_node(branch, 0)
				last := tc.a.child_node(branch, n_conds - 1)
				tc.record_error_at(.condition_mismatch,
					'`match` expression with Option type only checks against `none`, to match its value you must unwrap it first `var?`',
					branch_id, token.new_span(first.pos.id, first.pos.offset, last.pos.end))
			}
		}
		if branch.value == 'else' && i < int(node.children_count) - 1 {
			tc.record_error_at(.condition_mismatch, '`else` must be the last branch of `match`',
				branch_id, token.new_span(branch.pos.id, branch.pos.offset, branch.pos.offset + 4))
		}
		for j in 0 .. n_conds {
			cond_id := tc.a.child(branch, j)
			tc.check_match_range_types(subject_id, subject_type, cond_id)
			tc.check_match_condition_type(subject_type, cond_id)
			tc.check_match_alias_condition(subject_declared_type, cond_id)
			tc.check_match_type_pattern_subject(subject_id, subject_type, cond_id)
			tc.check_duplicate_match_condition(branch, i, j, cond_id, mut seen_match_values, mut
				seen_match_ranges, mut seen_match_patterns)
			if !tc.source_text_for_node(id).contains('typeof(') {
				tc.record_constant_match_condition(subject_id, cond_id,
					i < int(node.children_count) - 1)
			}
		}
		$if ownership ? {
			if branch.value == 'else' {
				tc.ownership_note_branch_group_else()
			}
		}
		if subject_type is SumType {
			for j in 0 .. n_conds {
				cond_id := tc.a.child(branch, j)
				cond := tc.a.node(cond_id)
				if pattern := tc.match_type_pattern(cond) {
					if _ := tc.sum_variant_type_for_pattern(subject_type.name, pattern) {
					} else {
						base := tc.sum_base_name(subject_type.name)
						raw_variants := tc.sum_types[base] or { []string{} }
						variants :=
							raw_variants.map(short_type_name(tc.concrete_sum_variant_name(subject_type.name, it)))
						message :=
							util.new_suggestion(pattern, variants).say('`${subject_type.name}` has no variant `${pattern}`')
						tc.record_error_at(.condition_mismatch, message, cond_id,
							tc.node_value_diagnostic_pos(cond_id))
					}
				}
			}
		} else if is_ierror_type(subject_type) {
			for j in 0 .. n_conds {
				cond_id := tc.a.child(branch, j)
				cond := tc.a.node(cond_id)
				if pattern := tc.match_type_pattern(cond) {
					if _ := tc.resolve_ierror_match_pattern(pattern) {
					} else if tc.should_diagnose(cond_id) {
						tc.record_error(.condition_mismatch,
							'`${pattern}` is not compatible with `IError`', cond_id)
					}
				}
			}
		} else if subject_type is Interface {
			for j in 0 .. n_conds {
				cond_id := tc.a.child(branch, j)
				cond := tc.a.node(cond_id)
				if pattern := tc.match_type_pattern(cond) {
					if interface_pattern_is_collapsed_container(pattern) {
						if tc.should_diagnose(cond_id) {
							tc.record_error(.condition_mismatch,
								'`${pattern}` is not compatible with interface `${subject_type.name}`',
								cond_id)
						}
						continue
					}
					if target_iface := tc.resolve_interface_pattern_interface(pattern) {
						if !tc.interface_runtime_pattern_allowed(subject_type.name, target_iface)
							&& tc.should_diagnose(cond_id) {
							tc.record_error(.condition_mismatch,
								'`${pattern}` is not compatible with interface `${subject_type.name}`',
								cond_id)
						}
						continue
					}
					if concrete := tc.resolve_interface_match_pattern(pattern) {
						concrete_type := unalias_type(unwrap_pointer(tc.parse_type(concrete)))
						if concrete_type !is Interface
							&& !tc.named_type_implements_interface(concrete, subject_type.name)
							&& tc.should_diagnose(cond_id) {
							tc.record_interface_implementation_error(.condition_mismatch,
								concrete_type, subject_type, cond_id,
								tc.match_condition_diagnostic_pos(cond_id))
						}
					} else if tc.should_diagnose(cond_id) {
						tc.record_error(.condition_mismatch, 'unknown type `${pattern}`', cond_id)
					}
				}
			}
		}
		$if ownership ? {
			tc.ownership_begin_branch()
		}
		saved_smartcasts := clone_smartcasts(tc.smartcasts)
		if subject_key.len > 0 && valid_string_data(subject_key) && n_conds > 1
			&& subject_type is SumType
			&& tc.match_branch_all_sum_type_patterns(subject_type, branch, n_conds) {
			$if ownership ? {
				tc.ownership_mark_scope_node(branch_id)
			}
			for j in 0 .. n_conds {
				cond := tc.a.node(tc.a.child(branch, j))
				pattern := tc.match_type_pattern(cond) or { continue }
				smartcast_type := tc.sum_variant_type_for_pattern(subject_type.name, pattern) or {
					continue
				}
				tc.smartcasts = clone_smartcasts(saved_smartcasts)
				tc.smartcasts[subject_key] = tc.parse_type(smartcast_type)
				tc.push_scope()
				tc.check_statement_sequence(branch, n_conds, value_context)
				tc.pop_scope()
			}
			tc.smartcasts = clone_smartcasts(saved_smartcasts)
			$if ownership ? {
				tc.ownership_end_branch(branch_id)
			}
			continue
		}
		if subject_key.len > 0 && valid_string_data(subject_key) && n_conds == 1
			&& branch.children_count > 0 && (subject_type is SumType || is_ierror_type(subject_type)
			|| subject_type is Interface) {
			cond_id := tc.a.child(branch, 0)
			cond := tc.a.node(cond_id)
			if pattern := tc.match_type_pattern(cond) {
				smartcast_type := if subject_type is SumType {
					tc.sum_variant_type_for_pattern(subject_type.name, pattern) or { pattern }
				} else if is_ierror_type(subject_type) {
					tc.resolve_ierror_match_pattern(pattern) or { pattern }
				} else if subject_type is Interface {
					tc.resolve_interface_match_pattern(pattern) or { pattern }
				} else {
					pattern
				}
				tc.smartcasts[subject_key] = tc.parse_type(smartcast_type)
			}
		} else if subject_key.len > 0 && valid_string_data(subject_key) && n_conds > 1
			&& subject_type is SumType {
			for sc in tc.multi_match_common_field_smartcasts(subject_type, branch, n_conds,
				subject_key) {
				tc.smartcasts[sc.name] = sc.typ
			}
		} else if subject_key.len > 0 && valid_string_data(subject_key) && n_conds > 1
			&& subject_type is Interface {
			if common_iface := tc.multi_interface_match_common_interface(subject_type, branch,
				n_conds)
			{
				tc.smartcasts[subject_key] = tc.parse_type(common_iface)
			}
		}
		tc.push_scope()
		$if ownership ? {
			tc.ownership_mark_scope_node(branch_id)
		}
		tc.check_statement_sequence(branch, n_conds, value_context)
		tc.pop_scope()
		if value_context && has_value_tail && !tc.branch_has_value_tail(branch_id)
			&& !tc.match_branch_definitely_returns(branch) {
			tc.record_error_at(.if_branch_mismatch,
				'`match` expression requires an expression as the last statement of every branch',
				branch_id, branch.pos)
		}
		tc.smartcasts = clone_smartcasts(saved_smartcasts)
		$if ownership ? {
			tc.ownership_end_branch(branch_id)
		}
	}
	if missing_non_else {
		tc.record_match_requires_non_else(node)
	}
	tc.check_match_sumtype_exhaustiveness(id, node, subject_type)
	tc.check_match_flag_enum_exhaustiveness(id, node, subject_type)
	tc.check_match_bool_exhaustiveness(id, node, subject_type)
	if value_context {
		tc.check_match_branch_tail_type_diagnostics(id, node)
	}
	if value_context && tc.match_expr_all_tails_are_none(node) {
		tc.record_error_at(.if_branch_mismatch,
			'invalid match expression, must supply at least one value other than `none`', id,
			tc.match_header_pos(node))
	}
	$if ownership ? {
		if !tc.match_covers_all_variants(node) {
			tc.ownership_add_branch_group_base_if_no_else()
		}
		tc.ownership_end_branch_group()
	}
}

fn (mut tc TypeChecker) check_match_branch_structure(id flat.NodeId, node flat.Node) bool {
	mut else_ids := []flat.NodeId{}
	mut non_else_count := 0
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		branch := tc.a.node(branch_id)
		if branch.kind != .match_branch {
			continue
		}
		if branch.value == 'else' {
			else_ids << branch_id
		} else {
			non_else_count++
		}
	}
	if else_ids.len == 0 && non_else_count == 0 {
		tc.record_error_at(.condition_mismatch,
			'`match` must have at least two branches including `else`, or an exhaustive set of branches',
			id, tc.match_keyword_pos(node))
		return false
	}
	if else_ids.len > 1 {
		first_else := tc.a.node(else_ids[0])
		tc.record_error_at(.condition_mismatch, '`match` can have only one `else` branch',
			else_ids[0], token.new_span(first_else.pos.id, first_else.pos.offset,

			first_else.pos.offset + 4))
	}
	return non_else_count == 0 && else_ids.len > 0
}

fn (mut tc TypeChecker) record_match_requires_non_else(node flat.Node) {
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		branch := tc.a.node(branch_id)
		if branch.kind == .match_branch && branch.value == 'else' {
			tc.record_error_at(.condition_mismatch,
				'`match` must have at least one non `else` branch', branch_id, token.new_span(branch.pos.id,
				branch.pos.offset, branch.pos.offset + 4))
			return
		}
	}
}

fn (tc &TypeChecker) match_keyword_pos(node flat.Node) token.Pos {
	return token.new_span(node.pos.id, node.pos.offset, node.pos.offset + 5)
}

fn (mut tc TypeChecker) check_match_type_pattern_subject(subject_id flat.NodeId, subject_type Type, cond_id flat.NodeId) {
	if tc.match_type_pattern(*tc.a.node(cond_id)) == none || subject_type is SumType
		|| subject_type is Interface || is_ierror_type(subject_type) || subject_type is Unknown {
		return
	}
	if unalias_and_unwrap_pointer_type(subject_type) is Struct {
		tc.record_error_at(.condition_mismatch,
			'struct instances cannot be matched by type name, they can only be matched to other instances of the same struct type',
			cond_id, tc.match_condition_diagnostic_pos(cond_id))
		return
	}
	subject_name := tc.source_text_for_node(subject_id)
	tc.record_error_at(.condition_mismatch,
		'matching by type can only be done for sum types, generics, interfaces, `${subject_name}` is none of those',
		cond_id, tc.match_condition_diagnostic_pos(cond_id))
}

fn (mut tc TypeChecker) check_match_alias_condition(subject_type Type, cond_id flat.NodeId) {
	if subject_type !is Alias {
		return
	}
	pattern := tc.match_type_pattern(*tc.a.node(cond_id)) or { return }
	tc.record_error_at(.condition_mismatch,
		'cannot match alias type `${short_type_name(subject_type.name())}` with `${short_type_name(pattern)}`',
		cond_id, tc.match_condition_diagnostic_pos(cond_id))
}

fn (mut tc TypeChecker) check_match_flag_enum_exhaustiveness(id flat.NodeId, node flat.Node, subject_type Type) {
	clean_subject := unalias_type(subject_type)
	if clean_subject !is Enum
		|| (!clean_subject.is_flag && clean_subject.name() !in tc.flag_enums)
		|| !tc.should_diagnose(id) {
		return
	}
	for i in 1 .. node.children_count {
		branch := tc.a.child_node(&node, i)
		if branch.kind == .match_branch && branch.value == 'else' {
			return
		}
	}
	tc.record_error_at(.condition_mismatch, 'match must be exhaustive (add `else {}` at the end)',
		id, tc.match_header_pos(node))
}

fn (mut tc TypeChecker) check_match_bool_exhaustiveness(id flat.NodeId, node flat.Node, subject_type Type) {
	if unalias_type(subject_type).name() != 'bool' || !tc.should_diagnose(id) {
		return
	}
	mut covered_true := false
	mut covered_false := false
	for i in 1 .. node.children_count {
		branch := tc.a.child_node(&node, i)
		if branch.kind != .match_branch {
			continue
		}
		if branch.value == 'else' {
			return
		}
		n_conds := branch.value.int()
		for j in 0 .. n_conds {
			cond := tc.a.child_node(branch, j)
			if cond.kind == .bool_literal {
				if cond.value == 'true' {
					covered_true = true
				} else {
					covered_false = true
				}
			}
		}
	}
	mut missing := []string{}
	if !covered_true {
		missing << '`true`'
	}
	if !covered_false {
		missing << '`false`'
	}
	if missing.len > 0 && node.children_count > 1 {
		tc.record_error_at(.condition_mismatch,
			'match must be exhaustive (add match branches for: ${missing.join(', ')} or `else {}` at the end)',
			id, tc.match_header_pos(node))
	}
}

fn (mut tc TypeChecker) check_match_sumtype_exhaustiveness(id flat.NodeId, node flat.Node, subject_type Type) {
	clean_subject := unalias_type(subject_type)
	if clean_subject !is SumType || !tc.should_diagnose(id) {
		return
	}
	sum_subject := clean_subject as SumType
	raw_variants := tc.sum_types[tc.sum_base_name(sum_subject.name)] or { return }
	if raw_variants.len == 0 {
		return
	}
	variants := raw_variants.map(tc.concrete_sum_variant_name(sum_subject.name, it))
	mut covered := map[string]bool{}
	mut else_ids := []flat.NodeId{}
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(node, i)
		branch := tc.a.node(branch_id)
		if branch.kind != .match_branch {
			continue
		}
		if branch.value == 'else' {
			else_ids << branch_id
			continue
		}
		for j in 0 .. branch.value.int() {
			cond := tc.a.child_node(branch, j)
			pattern := tc.match_type_pattern(cond) or { continue }
			qpattern := tc.qualify_name(pattern)
			for variant in variants {
				if variant == pattern || variant == qpattern {
					covered[variant] = true
				}
			}
			pattern_short := short_type_name(pattern)
			mut short_match := ''
			mut short_count := 0
			for variant in variants {
				if short_type_name(variant) == pattern_short {
					short_count++
					short_match = variant
				}
			}
			if short_count == 1 {
				covered[short_match] = true
			}
		}
	}
	mut missing := []string{}
	for variant in variants {
		if variant !in covered {
			missing << short_type_name(variant)
		}
	}
	if missing.len > 0 && else_ids.len == 0 {
		quoted_missing := missing.map('`${it}`')
		tc.record_error_at(.condition_mismatch,
			'match must be exhaustive (add match branches for: ${quoted_missing.join(', ')} or `else {}` at the end)',
			id, tc.match_header_pos(node))
		return
	}
	if missing.len == 0 {
		for else_id in else_ids {
			else_branch := tc.a.node(else_id)
			tc.record_error_at(.condition_mismatch,
				'match expression is exhaustive, `else` is unnecessary', else_id, token.new_span(else_branch.pos.id,
				else_branch.pos.offset, else_branch.pos.offset + 4))
		}
	}
}

fn (mut tc TypeChecker) check_match_condition_type(subject_type Type, cond_id flat.NodeId) {
	cond := tc.a.node(cond_id)
	if cond.kind == .range || tc.match_type_pattern(*cond) != none {
		return
	}
	condition_type := tc.resolve_type(cond_id)
	clean_subject := unalias_type(subject_type)
	if clean_subject is OptionType {
		return
	}
	if cond.kind == .enum_val && clean_subject is Enum {
		return
	}
	clean_condition := unalias_type(condition_type)
	if clean_condition is Unknown || tc.type_compatible(condition_type, subject_type)
		|| tc.type_compatible(subject_type, condition_type) {
		return
	}
	tc.record_error_at(.condition_mismatch, 'cannot match `${clean_subject.name()}` with `${tc.diagnostic_expr_type_name(cond_id,
		condition_type)}`', cond_id, cond.pos)
}

fn (mut tc TypeChecker) check_match_branch_tail_type_diagnostics(id flat.NodeId, node flat.Node) {
	mut tails := []flat.NodeId{}
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		branch := tc.a.node(branch_id)
		if branch.kind != .match_branch {
			continue
		}
		tail_id := tc.branch_tail_expr_id(branch_id)
		if tc.valid_node_id(tail_id) {
			tails << tail_id
		}
	}
	if tails.len < 2 {
		return
	}
	mut first_cast_index := -1
	for i, tail_id in tails {
		if tc.a.node(tail_id).kind == .cast_expr {
			first_cast_index = i
			break
		}
	}
	if first_cast_index < 0 {
		tc.check_general_match_branch_tail_types(id, node, tails)
		return
	}
	cast_id := tails[first_cast_index]
	cast_node := tc.a.node(cast_id)
	cast_type := tc.parse_type(cast_node.value)
	if !infix_power_type_is_numeric(cast_type) {
		return
	}
	if first_cast_index > 0 {
		first_tail := tc.a.node(tails[0])
		if first_tail.kind == .int_literal {
			tc.record_error_at(.if_branch_mismatch,
				'the type of the last expression of the first match branch was `int literal`, which is not compatible with `${cast_type.name()}`',
				cast_id, cast_node.pos)
		}
		return
	}
	for i in 1 .. tails.len {
		tail_id := tails[i]
		tail := tc.a.node(tail_id)
		if tail.kind == .cast_expr {
			tail_type := tc.parse_type(tail.value)
			if tail_type.name() != cast_type.name() {
				tc.record_error_at(.if_branch_mismatch,
					'the type of the last expression in the first match branch was an explicit `${cast_type.name()}`, not `${tail_type.name()}`',
					tail_id, tail.pos)
				return
			}
			continue
		}
		if literal := tc.integer_literal_source(tail_id) {
			if type_range := integer_type_range(cast_type) {
				if integer_literal_outside_range(literal.replace('_', ''), type_range) {
					tc.record_error_at(.if_branch_mismatch,
						'${literal} does not fit the range of `${cast_type.name()}`', tail_id,
						tail.pos)
					return
				}
			}
		}
	}
}

fn (mut tc TypeChecker) check_general_match_branch_tail_types(id flat.NodeId, node flat.Node, tails []flat.NodeId) {
	subject_id := tc.a.child(&node, 0)
	subject_key := tc.expr_key(subject_id)
	subject_type := unalias_type(unwrap_pointer(tc.resolve_type(subject_id)))
	mut tail_types := []Type{cap: tails.len}
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		branch := tc.a.node(branch_id)
		if branch.kind != .match_branch {
			continue
		}
		tail_id := tc.branch_tail_expr_id(branch_id)
		if tc.valid_node_id(tail_id) {
			tail_types << tc.match_branch_tail_diagnostic_type(subject_key, subject_type, branch,
				tail_id)
		}
	}
	if tail_types.len != tails.len {
		return
	}
	mut context_type := tc.expected_context_for_expr(id) or { Type(void_) }
	parent_id := tc.direct_parent_id(id)
	if context_type is Void && tc.valid_node_id(parent_id)
		&& tc.a.node(parent_id).kind == .return_stmt {
		context_type = tc.fn_context.return_type
	}
	if context_type !is Void {
		mut clean_expected := unalias_type(context_type)
		mut wrapped_context := false
		if clean_expected is OptionType {
			wrapped_context = true
			context_type = clean_expected.base_type
			clean_expected = unalias_type(clean_expected.base_type)
		} else if clean_expected is ResultType {
			wrapped_context = true
			context_type = clean_expected.base_type
			clean_expected = unalias_type(clean_expected.base_type)
		}
		if wrapped_context {
			for i, tail_id in tails {
				actual := tail_types[i]
				if actual is Void || actual is Unknown || is_ierror_type(actual)
					|| tc.expr_never_returns(tail_id) || tc.type_compatible(actual, context_type) {
					continue
				}
				tc.record_match_branch_return_type_mismatch(tail_id, context_type, actual)
				return
			}
			return
		}
		if clean_expected is SumType {
			for i, tail_id in tails {
				actual := tail_types[i]
				if tc.type_name_is_direct_sum_variant(actual, clean_expected) {
					continue
				}
				tc.record_match_branch_return_type_mismatch(tail_id, context_type, actual)
				return
			}
			return
		}
	}
	expected := tail_types[0]
	if expected is Void || expected is Unknown {
		return
	}
	for i in 1 .. tails.len {
		tail_id := tails[i]
		actual := tail_types[i]
		if actual is Void || actual is Unknown
			|| (tc.type_compatible(actual, expected) && tc.type_compatible(expected, actual)) {
			continue
		}
		tc.record_match_branch_return_type_mismatch(tail_id, expected, actual)
		return
	}
}

fn (tc &TypeChecker) match_branch_tail_diagnostic_type(subject_key string, subject_type Type, branch flat.Node, tail_id flat.NodeId) Type {
	n_conds := if branch.value == 'else' { 0 } else { branch.value.int() }
	if subject_key.len > 0 && n_conds == 1 && branch.children_count > 0 {
		cond := tc.a.child_node(&branch, 0)
		if pattern := tc.match_type_pattern(cond) {
			smartcast_name := if subject_type is SumType {
				tc.sum_variant_type_for_pattern(subject_type.name, pattern) or { '' }
			} else if subject_type is Interface {
				tc.resolve_interface_match_pattern(pattern) or { '' }
			} else {
				''
			}
			if smartcast_name.len > 0 {
				smartcast_type := tc.parse_type(smartcast_name)
				tail := tc.a.node(tail_id)
				if tail.kind == .ident && tc.expr_key(tail_id) == subject_key {
					return smartcast_type
				}
				if tail.kind == .prefix && tail.op == .amp && tail.children_count > 0 {
					child_id := tc.a.child(tail, 0)
					if tc.expr_key(child_id) == subject_key {
						if subject_type is Interface {
							return smartcast_type
						}
						return Type(Pointer{
							base_type: smartcast_type
						})
					}
				}
			}
		}
	}
	return tc.resolve_type(tail_id)
}

fn (tc &TypeChecker) type_name_is_direct_sum_variant(actual Type, expected SumType) bool {
	actual_name := actual.name()
	base := tc.sum_base_name(expected.name)
	for variant in tc.sum_types[base] or { []string{} } {
		if actual_name == variant || short_type_name(actual_name) == short_type_name(variant) {
			return true
		}
	}
	return false
}

fn (mut tc TypeChecker) record_match_branch_return_type_mismatch(id flat.NodeId, expected Type, actual Type) {
	node := tc.a.node(id)
	pos := if node.kind == .prefix && node.op == .amp {
		tc.prefix_operator_pos(id, '&')
	} else if node.kind == .selector {
		tc.node_value_diagnostic_pos(id)
	} else {
		node.pos
	}
	tc.record_error_at(.if_branch_mismatch, 'return type mismatch, it should be `${expected.name()}`, but it is instead `${tc.diagnostic_expr_type_name(id,
		actual)}`', id, pos)
}

fn (tc &TypeChecker) expr_has_match_branch_type_error(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	root := tc.a.node(id)
	return tc.errors.any(it.kind == .if_branch_mismatch && it.pos.id == root.pos.id
		&& it.pos.offset >= root.pos.offset && it.pos.end <= root.pos.end
		&& it.msg.starts_with('return type mismatch, it should be '))
}

fn (mut tc TypeChecker) check_match_range_types(subject_id flat.NodeId, subject_type Type, cond_id flat.NodeId) {
	cond := tc.a.node(cond_id)
	if cond.kind != .range || cond.children_count < 2 {
		return
	}
	low_id := tc.a.child(cond, 0)
	high_id := tc.a.child(cond, 1)
	low_type := unalias_type(tc.resolve_type(low_id))
	high_type := unalias_type(tc.resolve_type(high_id))
	if low_type is Unknown || high_type is Unknown {
		return
	}
	mut range_type := low_type
	low_is_literal := tc.range_endpoint_is_literal(low_id)
	high_is_literal := tc.range_endpoint_is_literal(high_id)
	if low_type.name() != high_type.name() {
		if low_is_literal && !high_is_literal && low_type.is_integer() && high_type.is_integer() {
			range_type = high_type
		} else if high_is_literal && !low_is_literal && low_type.is_integer()
			&& high_type.is_integer() {
			range_type = low_type
		} else if low_is_literal && high_is_literal && low_type.is_integer()
			&& high_type.is_integer() {
			range_type = if low_type is Rune {
				low_type
			} else if high_type is Rune {
				high_type
			} else {
				low_type
			}
		} else {
			tc.record_error_with_details_at(.condition_mismatch,
				'the low and high parts of a range expression, should have matching types',
				cond_id, tc.match_condition_diagnostic_pos(cond_id), [
				'\n low part type: ${tc.match_range_endpoint_type_name(low_id, low_type)}',
				'high part type: ${tc.match_range_endpoint_type_name(high_id, high_type)}',
			])
		}
	}
	clean_subject := unalias_type(subject_type)
	if clean_subject !is Unknown && range_type !is Unknown
		&& clean_subject.name() != range_type.name() {
		tc.record_error_with_details_at(.condition_mismatch,
			'the range type and the match condition type should match', cond_id,
			tc.match_condition_diagnostic_pos(cond_id), [
			'\nmatch condition type: ${clean_subject.name()}',
			'          range type: ${range_type.name()}',
		])
	}
	tc.check_match_range_values(cond_id, low_id, high_id)
	_ = subject_id
}

fn (tc &TypeChecker) match_range_endpoint_type_name(id flat.NodeId, typ Type) string {
	if tc.range_endpoint_is_literal(id) && typ.is_integer() && typ !is Rune {
		return 'int literal'
	}
	return typ.name()
}

fn (mut tc TypeChecker) check_match_range_values(cond_id flat.NodeId, low_id flat.NodeId, high_id flat.NodeId) {
	low := tc.match_condition_int_value(low_id) or {
		tc.record_error_at(.condition_mismatch,
			'match branch range expressions need the start value to be known at compile time (only enums, const or literals are supported)',
			cond_id, tc.a.node(low_id).pos)
		return
	}
	high := tc.match_condition_int_value(high_id) or {
		tc.record_error_at(.condition_mismatch,
			'match branch range expressions need the end value to be known at compile time (only enums, const or literals are supported)',
			cond_id, tc.a.node(high_id).pos)
		return
	}
	if low > high {
		tc.record_error_at(.condition_mismatch,
			'the start value `${low}` should be lower than the end value `${high}`', cond_id,
			tc.match_condition_diagnostic_pos(cond_id))
	}
}

fn (tc &TypeChecker) match_expr_all_tails_are_none(node flat.Node) bool {
	if node.children_count < 2 {
		return false
	}
	mut saw_branch := false
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		branch := tc.a.node(branch_id)
		if branch.kind != .match_branch {
			continue
		}
		saw_branch = true
		if !tc.branch_tail_is_none_literal(tc.branch_tail_expr_id(branch_id)) {
			return false
		}
	}
	return saw_branch
}

fn (tc &TypeChecker) match_header_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := node.pos.offset
	if start < 0 || start >= source.len {
		return node.pos
	}
	if relative := source[start..int_min(node.pos.end, source.len)].index('{') {
		return token.new_span(node.pos.id, start, start + relative + 1)
	}
	return node.pos
}

fn (mut tc TypeChecker) record_constant_match_condition(subject_id flat.NodeId, cond_id flat.NodeId, has_following_branch bool) {
	value := if subject_value := tc.constant_bool_value(subject_id) {
		if condition_value := tc.constant_bool_value(cond_id) {
			subject_value == condition_value
		} else {
			tc.constant_comparison_value(subject_id, cond_id, .eq) or { return }
		}
	} else {
		tc.constant_comparison_value(subject_id, cond_id, .eq) or { return }
	}
	cond := tc.a.node(cond_id)
	tc.record_notice_at(.condition_mismatch, if value {
		'match is always true'
	} else {
		'match is always false'
	}, cond_id, cond.pos)
	if value && has_following_branch && tc.same_simple_comparison_expr(subject_id, cond_id) {
		tc.record_warning_at(.condition_mismatch,
			'self-comparison match branch is always true; following branches may be unreachable',
			cond_id, cond.pos)
	}
}

fn (mut tc TypeChecker) check_duplicate_match_condition(branch &flat.Node, branch_index int, cond_index int, cond_id flat.NodeId, mut seen_values map[int]int, mut seen_ranges []MatchSeenRange, mut seen_patterns map[string]int) {
	cond := tc.a.node(cond_id)
	if cond.kind == .range && cond.children_count >= 2 {
		start := tc.match_condition_int_value(tc.a.child(cond, 0)) or { return }
		end := tc.match_condition_int_value(tc.a.child(cond, 1)) or { return }
		if start > end {
			return
		}
		low := int_min(start, end)
		high := int_max(start, end)
		mut duplicate_values := map[int]int{}
		for value, owner_branch in seen_values {
			if value >= low && value <= high {
				duplicate_values[value] = owner_branch
			}
		}
		for seen_range in seen_ranges {
			overlap_start := int_max(low, seen_range.start)
			overlap_end := int_min(high, seen_range.end)
			if overlap_start > overlap_end {
				continue
			}
			for value in overlap_start .. overlap_end + 1 {
				if value !in duplicate_values {
					duplicate_values[value] = seen_range.branch
				}
			}
		}
		mut ordered := duplicate_values.keys()
		ordered.sort()
		for value in ordered {
			owner_branch := duplicate_values[value]
			tc.record_match_duplicate(branch, branch_index, cond_index, cond_id, owner_branch,
				value.str())
		}
		seen_ranges << MatchSeenRange{
			start:  low
			end:    high
			branch: branch_index
		}
		return
	}
	if value := tc.match_condition_int_value(cond_id) {
		mut owner_branch := -1
		if owner := seen_values[value] {
			owner_branch = owner
		} else {
			for seen_range in seen_ranges {
				if value >= seen_range.start && value <= seen_range.end {
					owner_branch = seen_range.branch
					break
				}
			}
		}
		if owner_branch >= 0 {
			tc.record_match_duplicate(branch, branch_index, cond_index, cond_id, owner_branch,
				value.str())
		} else {
			seen_values[value] = branch_index
		}
		return
	}
	key, display := tc.match_condition_pattern_key(cond_id)
	if key.len == 0 {
		return
	}
	if owner_branch := seen_patterns[key] {
		tc.record_match_duplicate(branch, branch_index, cond_index, cond_id, owner_branch, display)
	} else {
		seen_patterns[key] = branch_index
	}
}

fn (mut tc TypeChecker) record_match_duplicate(branch &flat.Node, branch_index int, cond_index int, cond_id flat.NodeId, owner_branch int, display string) {
	if !tc.should_diagnose(cond_id) {
		return
	}
	mut pos := tc.match_condition_diagnostic_pos(cond_id)
	if owner_branch == branch_index && cond_index > 0 {
		first_pos := tc.match_condition_diagnostic_pos(tc.a.child(branch, 0))
		if first_pos.id == pos.id {
			pos = token.new_span(pos.id, first_pos.offset, pos.end)
		}
	}
	tc.record_error_at(.condition_mismatch, 'match case `${display}` is handled more than once',
		cond_id, pos)
}

fn (tc &TypeChecker) match_condition_pattern_key(id flat.NodeId) (string, string) {
	node := tc.a.node(id)
	if pattern := tc.match_type_pattern(node) {
		return 'type:${pattern}', pattern
	}
	if node.kind == .enum_val {
		return 'enum:${node.value}', node.value
	}
	if node.kind == .string_literal {
		return 'string:${node.value}', node.value
	}
	if node.kind == .bool_literal {
		return 'bool:${node.value}', node.value
	}
	text := tc.source_text_for_node(id)
	if text.len == 0 {
		return '', ''
	}
	return '${node.kind}:${text}', text
}

fn (tc &TypeChecker) match_condition_int_value(id flat.NodeId) ?int {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .char_literal {
		return match_char_literal_value(node.value)
	}
	return tc.const_int_expr(id, tc.cur_module, []string{})
}

fn match_char_literal_value(value string) ?int {
	if value.len == 0 {
		return none
	}
	if value[0] != `\\` {
		runes := value.runes()
		if runes.len == 0 {
			return none
		}
		return int(runes[0])
	}
	if value.len < 2 {
		return none
	}
	if value[1] == `x` && value.len > 2 {
		return v_int_literal_value('0x${value[2..]}')
	}
	return match value[1] {
		`n` { int(`\n`) }
		`t` { int(`\t`) }
		`r` { int(`\r`) }
		`\\` { int(`\\`) }
		`'` { int(`'`) }
		`"` { int(`"`) }
		`$` { int(`$`) }
		`0` { 0 }
		`a` { 7 }
		`b` { 8 }
		`f` { 12 }
		`v` { 11 }
		else { int(value[1]) }
	}
}

fn (tc &TypeChecker) match_condition_diagnostic_pos(id flat.NodeId) token.Pos {
	if !tc.valid_node_id(id) {
		return token.Pos{}
	}
	node := tc.a.node(id)
	if node.kind == .range && node.children_count >= 2 {
		start := tc.match_condition_diagnostic_pos(tc.a.child(node, 0))
		end := tc.match_condition_diagnostic_pos(tc.a.child(node, 1))
		if start.id == end.id {
			return token.new_span(start.id, start.offset, end.end)
		}
	}
	if node.kind == .enum_val {
		pos := tc.node_value_diagnostic_pos(id)
		file := tc.a.source_files[pos.id] or { return pos }
		source := tc.source_texts_by_file[file.name] or { return pos }
		if pos.offset > 0 && pos.offset <= source.len && source[pos.offset - 1] == `.` {
			return token.new_span(pos.id, pos.offset - 1, pos.end)
		}
		return pos
	}
	if node.kind == .ident {
		return tc.node_value_diagnostic_pos(id)
	}
	return node.pos
}

fn (tc &TypeChecker) match_branch_all_sum_type_patterns(subject SumType, branch &flat.Node, n_conds int) bool {
	for i in 0 .. n_conds {
		cond := tc.a.node(tc.a.child(branch, i))
		pattern := tc.match_type_pattern(cond) or { return false }
		if _ := tc.sum_variant_type_for_pattern(subject.name, pattern) {
			continue
		}
		return false
	}
	return true
}

fn (tc &TypeChecker) multi_match_common_field_smartcasts(subject SumType, branch &flat.Node, n_conds int, subject_key string) []LocalBinding {
	mut common := []LocalBinding{}
	for i in 0 .. n_conds {
		cond := tc.a.node(tc.a.child(branch, i))
		pattern := tc.match_type_pattern(cond) or { return []LocalBinding{} }
		variant_name := tc.sum_variant_type_for_pattern(subject.name, pattern) or {
			return []LocalBinding{}
		}
		variant_type := unalias_type(tc.parse_type(variant_name))
		if variant_type !is Struct {
			return []LocalBinding{}
		}
		variant := variant_type as Struct
		if i == 0 {
			for field in tc.structs[variant.name] or { return []LocalBinding{} } {
				common << LocalBinding{
					name: '${subject_key}.${field.name}'
					typ:  field.typ
				}
			}
			continue
		}
		mut intersection := []LocalBinding{cap: common.len}
		for candidate in common {
			field_name := candidate.name.all_after_last('.')
			field_type := tc.struct_field_type(variant.name, field_name) or { continue }
			if tc.type_compatible(field_type, candidate.typ)
				&& tc.type_compatible(candidate.typ, field_type) {
				intersection << candidate
			}
		}
		common = intersection.clone()
		if common.len == 0 {
			break
		}
	}
	return common
}

fn (tc &TypeChecker) multi_interface_match_common_interface(subject Interface, branch &flat.Node, n_conds int) ?string {
	mut variants := []string{cap: n_conds}
	for i in 0 .. n_conds {
		cond := tc.a.node(tc.a.child(branch, i))
		pattern := tc.match_type_pattern(cond) or { return none }
		variant_name := tc.resolve_interface_match_pattern(pattern) or { return none }
		variants << variant_name
	}
	subject_name := tc.interface_metadata_name(subject.name)
	mut best := ''
	mut best_score := -1
	for iface_name, _ in tc.interface_names {
		name := tc.interface_metadata_name(iface_name)
		if name == subject_name || tc.interface_has_no_requirements(name) {
			continue
		}
		mut implements_all := true
		for variant in variants {
			if !tc.named_type_implements_interface(variant, name) {
				implements_all = false
				break
			}
		}
		if !implements_all {
			continue
		}
		score := tc.interface_abstract_method_names(name).len + tc.interface_field_list(name).len
		if score > best_score || (score == best_score && (best.len == 0 || name < best)) {
			best = name
			best_score = score
		}
	}
	if best.len == 0 {
		return none
	}
	return best
}

fn (tc &TypeChecker) resolve_interface_match_pattern(pattern string) ?string {
	for candidate in tc.interface_match_pattern_candidates(pattern) {
		if interface_pattern_is_collapsed_container(candidate) {
			container_type := tc.parse_type(candidate)
			if container_type is Array || container_type is Map {
				return container_type.name()
			}
			continue
		}
		if is_builtin_type_name(candidate) {
			return candidate
		}
		if tc.pattern_type_known(candidate) {
			return candidate
		}
		if tc.type_symbol_known(candidate) {
			return candidate
		}
	}
	return none
}

fn interface_pattern_is_collapsed_container(pattern string) bool {
	clean := trimmed_space(pattern)
	return clean.starts_with('[]') || clean.starts_with('map[')
}

fn (tc &TypeChecker) resolve_interface_pattern_interface(pattern string) ?string {
	for candidate in tc.interface_match_pattern_candidates(pattern) {
		name := tc.interface_metadata_name(candidate)
		if name in tc.interface_names {
			return name
		}
		typ := unalias_type(tc.parse_type(candidate))
		if typ is Interface {
			return typ.name
		}
	}
	return none
}

fn (tc &TypeChecker) interface_runtime_pattern_allowed(subject_iface string, target_iface string) bool {
	subject := tc.interface_metadata_name(subject_iface)
	target := tc.interface_metadata_name(target_iface)
	if subject == target {
		return true
	}
	if tc.interface_implements_interface(subject, target)
		|| tc.interface_implements_interface(target, subject) {
		return true
	}
	for concrete in tc.interface_impl_names(subject) {
		if concrete in tc.interface_names {
			if tc.interface_implements_interface(concrete, target) {
				return true
			}
			continue
		}
		resolved := tc.interface_metadata_name(concrete)
		if resolved in tc.interface_names {
			if tc.interface_implements_interface(resolved, target) {
				return true
			}
			continue
		}
		if tc.named_type_implements_interface(concrete, target) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) pattern_type_known(pattern string) bool {
	clean := trimmed_space(pattern)
	if clean.starts_with('[]') || clean.starts_with('map[') || clean.starts_with('[')
		|| clean.starts_with('fn ') || clean.starts_with('fn(') {
		return tc.parse_type(clean) !is Unknown
	}
	return false
}

fn (tc &TypeChecker) resolve_ierror_match_pattern(pattern string) ?string {
	for candidate in tc.interface_match_pattern_candidates(pattern) {
		if tc.named_type_compatible_with_ierror(candidate) {
			return candidate
		}
	}
	return none
}

fn (tc &TypeChecker) interface_match_pattern_candidates(pattern string) []string {
	mut candidates := []string{}
	if !pattern.contains('.') {
		mut has_scoped_candidate := false
		if resolved := tc.resolve_selective_import_type_symbol(pattern) {
			candidates << resolved
			has_scoped_candidate = true
		}
		if tc.source_declares_type_in_scope(pattern, tc.cur_file, tc.cur_module) {
			candidates << pattern
			has_scoped_candidate = true
		}
		if tc.cur_module.len > 0 && tc.cur_module != 'main' && tc.cur_module != 'builtin' {
			local := '${tc.cur_module}.${pattern}'
			if tc.type_symbol_known(local) {
				candidates << local
				has_scoped_candidate = true
			}
		}
		if !has_scoped_candidate {
			candidates << pattern
		}
	} else if resolved := tc.resolve_import_alias_pattern(pattern) {
		candidates << resolved
		candidates << pattern
	} else {
		candidates << pattern
	}
	qpattern := tc.qualify_name(pattern)
	if qpattern != pattern {
		candidates << qpattern
	}
	mut result := []string{}
	mut seen := map[string]bool{}
	for candidate in candidates {
		if candidate.len == 0 || candidate in seen {
			continue
		}
		seen[candidate] = true
		result << candidate
	}
	return result
}

fn (tc &TypeChecker) resolve_import_alias_pattern(pattern string) ?string {
	dot := pattern.index_u8(`.`)
	if dot <= 0 {
		return none
	}
	alias := pattern[..dot]
	resolved := tc.resolve_import_alias(alias) or { return none }
	return '${resolved}.${pattern[dot + 1..]}'
}

// check_is_expr validates check is expr state for types.
fn (mut tc TypeChecker) check_is_expr(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	expr_id := tc.a.child(&node, 0)
	tc.check_node(expr_id)
	expr_node := tc.a.node(expr_id)
	if expr_node.is_mut && expr_node.kind == .ident && !tc.ident_is_mutable_lvalue(expr_node.value) {
		tc.record_error_at(.assignment_mismatch,
			'`${expr_node.value}` is immutable, declare it with `mut` to make it mutable', expr_id,
			tc.node_value_diagnostic_pos(expr_id))
	}
	if expr_node.kind == .none_expr && node.value == 'none' {
		mut op := 'is'
		mut op_pos := node.pos
		mut full_pos := node.pos
		if file := tc.a.source_files[expr_node.pos.id] {
			source := tc.source_texts_by_file[file.name] or { '' }
			search_start := int_min(int_max(expr_node.pos.end, 0), source.len)
			search_end := int_min(source.len, search_start + 16)
			if search_start < search_end {
				tail := source[search_start..search_end]
				relative := if idx := tail.index('!is') {
					op = '!is'
					idx
				} else {
					tail.index('is') or { -1 }
				}
				if relative >= 0 {
					op_start := search_start + relative
					op_pos = token.new_span(expr_node.pos.id, op_start, op_start + op.len)
					target_relative := source[op_start + op.len..search_end].index('none') or { -1 }
					if target_relative >= 0 {
						full_pos = token.new_span(expr_node.pos.id, expr_node.pos.offset,

							op_start + op.len + target_relative + 4)
					}
				}
			}
		}
		tc.record_error_at(.condition_mismatch, 'invalid operator `${op}` to `none` and `none`',
			id, full_pos)
		tc.record_error_at(.condition_mismatch,
			'`${op}` can only be used with interfaces and sum types', id, op_pos)
		return
	}
	if node.value.contains('.') {
		module_alias := node.value.all_before('.')
		if module_alias.len > 0 && module_alias[0] >= `a` && module_alias[0] <= `z`
			&& module_alias != tc.cur_module
			&& tc.current_file_import_path_for_alias(module_alias) == none {
			tc.record_error_at(.unknown_type, 'unknown module `${module_alias}`', id, tc.type_diagnostic_pos(id,
				module_alias))
			return
		}
	}
	// `x is T` in a generic template stays undecided until monomorphization.
	// Only defer inside an actual generic function: in a non-generic one an
	// unknown single-letter pattern is a real error and must be validated.
	if node.value.len > 0 && tc.type_text_has_generic_placeholder(node.value)
		&& tc.cur_fn_is_generic_template() {
		return
	}
	// A `$for v in T.variants` loop variable is substituted by the comptime
	// unroll; `val is v` cannot be validated against the raw name.
	if node.value in tc.cur_comptime_variant_loop_vars || (node.value.contains('.')
		&& node.value.all_after_last('.') in tc.cur_comptime_variant_loop_vars) {
		return
	}
	raw_expr_type := tc.resolve_type(expr_id)
	if raw_expr_type is OptionType {
		tc.record_error_at(.condition_mismatch,
			'${tc.source_text_for_node(expr_id)} is an Optional, it needs to be unwrapped first',
			expr_id, tc.node_value_diagnostic_pos(expr_id))
		return
	}
	mut expr_type := unalias_type(unwrap_pointer(raw_expr_type))
	if expr_type is Interface && tc.nonmut_mutable_interface_smartcast(expr_id) {
		if tc.interface_has_no_requirements(expr_type.name) {
			tc.record_notice_at(.condition_mismatch,
				'smartcasting requires either an immutable value, or an explicit mut keyword before the value',
				expr_id, expr_node.pos)
		}
		tc.record_error_at(.condition_mismatch,
			'smart casting a mutable interface value requires `if mut ${tc.source_text_for_node(expr_id)} is ...`',
			expr_id, expr_node.pos)
	}
	// A previous branch can narrow a variable to one variant and then assign it
	// another value. A later `is` still applies to the variable's declared sum
	// type, not only to the stale narrowed variant.
	if expr_type !is SumType && expr_type !is Interface {
		mut declared_type := Type(Unknown{})
		if expr_node.kind == .ident {
			declared_type = tc.cur_scope.lookup(expr_node.value) or { Type(Unknown{}) }
		} else if expr_node.kind == .selector {
			declared_type = tc.selector_type(expr_id, expr_node) or { Type(Unknown{}) }
		}
		declared_type = unalias_and_unwrap_pointer_type(declared_type)
		if declared_type is SumType || declared_type is Interface {
			expr_type = declared_type
		}
	}
	if expr_type is SumType {
		if node.value.len > 0 {
			pointer_sum_variant := node.value.starts_with('&') && raw_expr_type is Pointer
				&& tc.sum_variant_type_for_pattern(expr_type.name, node.value[1..]) != none
			sum_base, _, concrete_sum := generic_type_application_parts(expr_type.name)
			open_generic_pattern := concrete_sum && node.value in tc.sum_params_for_base(sum_base)
			if (tc.sum_variant_type_for_pattern(expr_type.name, node.value) == none
				|| open_generic_pattern) && !pointer_sum_variant {
				if tc.should_diagnose(id) {
					diagnostic_pattern := if node.value.contains('.') {
						node.value
					} else if tc.cur_module !in ['', 'main', 'builtin'] {
						'${tc.cur_module}.${node.value}'
					} else {
						node.value
					}
					diagnostic_pos := if node.value.contains('.') {
						tc.type_diagnostic_pos(id, node.value.all_before('.'))
					} else {
						tc.node_value_diagnostic_pos(id)
					}
					if !tc.type_name_known(node.value) {
						tc.record_error_at(.unknown_type,
							'is: type `${diagnostic_pattern}` does not exist', id, diagnostic_pos)
					}
					tc.record_error_at(.condition_mismatch,
						'`${expr_type.name}` has no variant `${diagnostic_pattern}`', id,
						diagnostic_pos)
				}
			}
		}
		return
	}
	if is_ierror_type(expr_type) {
		if node.value.len > 0 {
			if node.value == 'none' {
			} else if target_iface := tc.resolve_interface_pattern_interface(node.value) {
				if !tc.interface_implements_interface(target_iface, 'IError')
					&& tc.should_diagnose(id) {
					tc.record_error(.condition_mismatch,
						'`${node.value}` is not compatible with `IError`', id)
				}
			} else if _ := tc.resolve_ierror_match_pattern(node.value) {
			} else if concrete := tc.resolve_interface_match_pattern(node.value) {
				pos := tc.node_value_diagnostic_pos(id)
				concrete_type := tc.parse_type(concrete)
				tc.record_interface_implementation_error(.condition_mismatch, concrete_type, Interface{
					name: 'IError'
				}, id, pos)
				tc.record_error_at(.condition_mismatch,
					'`${node.value}` doesn\'t implement interface `IError`', id, pos)
			} else if tc.should_diagnose(id) {
				tc.record_error(.condition_mismatch,
					'`${node.value}` is not compatible with `IError`', id)
			}
		}
		return
	}
	if expr_type is Interface {
		if node.value.len > 0 {
			if interface_pattern_is_collapsed_container(node.value) {
				if tc.should_diagnose(id) {
					tc.record_error(.condition_mismatch,
						'`${node.value}` is not compatible with interface `${expr_type.name}`', id)
				}
			} else if target_iface := tc.resolve_interface_pattern_interface(node.value) {
				if !tc.interface_runtime_pattern_allowed(expr_type.name, target_iface)
					&& tc.should_diagnose(id) {
					tc.record_error(.condition_mismatch,
						'`${node.value}` is not compatible with interface `${expr_type.name}`', id)
				}
			} else if concrete := tc.resolve_interface_match_pattern(node.value) {
				concrete_type := unalias_type(unwrap_pointer(tc.parse_type(concrete)))
				if concrete_type !is Interface
					&& !tc.named_type_implements_interface(concrete, expr_type.name)
					&& tc.should_diagnose(id) {
					pos := tc.node_value_diagnostic_pos(id)
					tc.record_interface_implementation_error(.condition_mismatch, concrete_type,
						expr_type, id, pos)
					tc.record_error_at(.condition_mismatch,
						'`${node.value}` doesn\'t implement interface `${expr_type.name}`', id, pos)
				}
			} else if tc.should_diagnose(id) {
				tc.record_error(.condition_mismatch, 'unknown type `${node.value}`', id)
			}
		}
		return
	}
	if expr_type is Unknown {
		return
	}
	if tc.should_diagnose(id) {
		tc.record_error(.condition_mismatch,
			'`is` can only be used with sum type or interface values, not `${expr_type.name()}`',
			id)
	}
}

// branch_tail_type supports branch tail type handling for TypeChecker.
fn (tc &TypeChecker) branch_tail_type(id flat.NodeId) Type {
	if !tc.valid_node_id(id) {
		return Type(void_)
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .if_expr {
		return tc.if_expr_tail_type(id)
	}
	if node.kind == .block {
		if node.children_count == 0 {
			return Type(void_)
		}
		last_id := tc.a.child(&node, node.children_count - 1)
		if !tc.valid_node_id(last_id) {
			return Type(void_)
		}
		last := tc.a.nodes[int(last_id)]
		if last.kind == .expr_stmt && last.children_count > 0 {
			return tc.branch_tail_value_type(tc.a.child(&last, 0))
		}
		return tc.branch_tail_value_type(last_id)
	}
	if node.kind == .match_branch {
		body_start := if node.value == 'else' { 0 } else { node.value.int() }
		if node.children_count <= body_start {
			return Type(void_)
		}
		last_id := tc.a.child(&node, node.children_count - 1)
		if !tc.valid_node_id(last_id) {
			return Type(void_)
		}
		last := tc.a.nodes[int(last_id)]
		if last.kind == .expr_stmt && last.children_count > 0 {
			return tc.branch_tail_value_type(tc.a.child(&last, 0))
		}
		return tc.branch_tail_value_type(last_id)
	}
	return tc.branch_tail_value_type(id)
}

fn (tc &TypeChecker) branch_tail_value_type(id flat.NodeId) Type {
	if smart_type := tc.smartcast_type(id) {
		return smart_type
	}
	typ := tc.expr_type(id) or { tc.resolve_type(id) }
	if tc.valid_node_id(id) {
		node := tc.a.node(id)
		if node.kind == .ident {
			if base := tc.mut_param_base_for_current_ident(node.value, typ) {
				return base
			}
		}
	}
	return typ
}

fn (tc &TypeChecker) branch_tail_type_with_smartcasts(id flat.NodeId, smartcasts []LocalBinding) Type {
	if smartcasts.len == 0 {
		return tc.branch_tail_type(id)
	}
	mut scoped := tc.fork_smartcast_query_view()
	for sc in smartcasts {
		if valid_string_data(sc.name) {
			scoped.smartcasts[sc.name] = sc.typ
		}
	}
	return scoped.branch_tail_type(id)
}

// if_expr_tail_type supports if expr tail type handling for TypeChecker.
fn (tc &TypeChecker) if_expr_tail_type(id flat.NodeId) Type {
	mut cur_id := id
	mut result := Type(void_)
	for tc.valid_node_id(cur_id) {
		node := tc.a.nodes[int(cur_id)]
		if node.kind != .if_expr {
			return choose_if_tail_type(result, tc.branch_tail_type(cur_id))
		}
		if node.children_count > 1 {
			smartcasts := tc.extract_smartcasts(tc.a.child(&node, 0))
			then_type := tc.branch_tail_type_with_smartcasts(tc.a.child(&node, 1), smartcasts)
			result = choose_if_tail_type(result, then_type)
		}
		if node.children_count <= 2 {
			return result
		}
		else_id := tc.a.child(&node, 2)
		if !tc.valid_node_id(else_id) {
			return result
		}
		else_node := tc.a.nodes[int(else_id)]
		if else_node.kind == .if_expr {
			cur_id = else_id
			continue
		}
		else_type := tc.branch_tail_type(else_id)
		return choose_if_tail_type(result, else_type)
	}
	return result
}

// match_expr_tail_type supports match expression value type handling for TypeChecker.
fn (tc &TypeChecker) match_expr_tail_type(id flat.NodeId) Type {
	if !tc.valid_node_id(id) {
		return Type(void_)
	}
	node := tc.a.nodes[int(id)]
	if node.kind != .match_stmt || node.children_count < 2 {
		return Type(void_)
	}
	subject_id := tc.a.child(&node, 0)
	subject_key := tc.expr_key(subject_id)
	subject_type := unalias_type(unwrap_pointer(tc.resolve_type(subject_id)))
	mut result := Type(void_)
	mut incompatible_wrapper_void := Type(void_)
	for i in 1 .. node.children_count {
		branch_id := tc.a.child(&node, i)
		if !tc.valid_node_id(branch_id) {
			continue
		}
		branch := tc.a.nodes[int(branch_id)]
		if branch.kind != .match_branch {
			continue
		}
		branch_type := if subject_key.len > 0 && valid_string_data(subject_key) {
			// Only the `smartcasts` binding needs isolation here (see
			// branch_tail_never_returns); avoid the ~11KB full struct copy.
			mut mtc := unsafe { &TypeChecker(voidptr(tc)) }
			mut saved_smartcasts := mtc.smartcasts.move()
			mtc.smartcasts = clone_smartcasts(saved_smartcasts)
			mtc.apply_match_branch_context_smartcasts(subject_key, subject_type, branch)
			bt := tc.branch_tail_type(branch_id)
			mtc.smartcasts = saved_smartcasts.move()
			bt
		} else {
			tc.branch_tail_type(branch_id)
		}
		tail := tc.branch_tail_expr_id(branch_id)
		if (is_option_void_type(branch_type) && !tc.branch_tail_is_none_literal(tail))
			|| (is_result_void_type(branch_type) && !tc.branch_tail_is_error_literal(tail)) {
			incompatible_wrapper_void = branch_type
		}
		result = choose_if_tail_type(result, branch_type)
	}
	if incompatible_wrapper_void !is Void {
		return incompatible_wrapper_void
	}
	return result
}

// choose_if_tail_type supports choose if tail type handling for types.
fn choose_if_tail_type(current Type, next Type) Type {
	if current is Void {
		return next
	}
	if next is Void {
		return current
	}
	if inferred := inferred_contextual_if_type(current, next) {
		return inferred
	}
	if current !is Primitive {
		return current
	}
	if next !is Primitive {
		return next
	}
	return current
}

// branch_tail_expr_id returns the value-producing tail expression of a branch
// body (a `block` or `match_branch`), unwrapping a trailing `expr_stmt`. Returns
// `empty_node` when the branch has no expression tail.
fn (tc &TypeChecker) branch_tail_expr_id(id flat.NodeId) flat.NodeId {
	if !tc.valid_node_id(id) {
		return flat.empty_node
	}
	node := tc.a.nodes[int(id)]
	mut last_id := flat.empty_node
	if node.kind == .block {
		if node.children_count == 0 {
			return flat.empty_node
		}
		last_id = tc.a.child(&node, node.children_count - 1)
	} else if node.kind == .match_branch {
		body_start := if node.value == 'else' { 0 } else { node.value.int() }
		if node.children_count <= body_start {
			return flat.empty_node
		}
		last_id = tc.a.child(&node, node.children_count - 1)
	} else {
		return id
	}
	if !tc.valid_node_id(last_id) {
		return flat.empty_node
	}
	last := tc.a.nodes[int(last_id)]
	if last.kind == .expr_stmt {
		if last.children_count > 0 {
			return tc.a.child(&last, 0)
		}
		return flat.empty_node
	}
	return last_id
}

// branches_compatible_with propagates `expected` into every value-producing tail
// of a match/if expression (so context-dependent tails such as enum shorthand
// `.foo`, `none`, or fn literals type against it instead of defaulting to e.g.
// `int`). Returns true when the node is a match/if expression and every branch
// tail is compatible with `expected`.
fn (mut tc TypeChecker) branches_compatible_with(id flat.NodeId, expected Type) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .match_stmt {
		subject_id := tc.a.child(&node, 0)
		subject_key := tc.expr_key(subject_id)
		subject_type := unalias_type(unwrap_pointer(tc.resolve_type(subject_id)))
		mut saw_branch := false
		for i in 1 .. node.children_count {
			branch_id := tc.a.child(&node, i)
			if !tc.valid_node_id(branch_id) {
				continue
			}
			branch := tc.a.nodes[int(branch_id)]
			if branch.kind != .match_branch {
				continue
			}
			tail := tc.branch_tail_expr_id(branch_id)
			if !tc.valid_node_id(tail) {
				return false
			}
			saw_branch = true
			if !tc.branch_failure_literal_matches_context(tail, expected) {
				return false
			}
			saved_smartcasts := clone_smartcasts(tc.smartcasts)
			tc.apply_match_branch_context_smartcasts(subject_key, subject_type, branch)
			actual := tc.resolve_expr(tail, expected)
			tc.smartcasts = clone_smartcasts(saved_smartcasts)
			if !tc.if_branch_type_compatible_with_context(actual, tail, expected) {
				return false
			}
		}
		return saw_branch
	}
	if node.kind == .if_expr {
		// A value if-expression needs an else branch (child 2). children: cond,
		// then-block, else (block or nested if_expr).
		if node.children_count <= 2 {
			return false
		}
		if tc.constant_if_selected_branch_compatible_with_expected(node, expected) {
			return true
		}
		then_tail := tc.branch_tail_expr_id(tc.a.child(&node, 1))
		if !tc.valid_node_id(then_tail) {
			return false
		}
		if !tc.branch_failure_literal_matches_context(then_tail, expected) {
			return false
		}
		then_actual := tc.resolve_expr(then_tail, expected)
		if !tc.if_branch_type_compatible_with_context(then_actual, then_tail, expected) {
			return false
		}
		else_id := tc.a.child(&node, 2)
		if !tc.valid_node_id(else_id) {
			return false
		}
		if tc.a.nodes[int(else_id)].kind == .if_expr {
			return tc.branches_compatible_with(else_id, expected)
		}
		else_tail := tc.branch_tail_expr_id(else_id)
		if !tc.valid_node_id(else_tail) {
			return false
		}
		if !tc.branch_failure_literal_matches_context(else_tail, expected) {
			return false
		}
		else_actual := tc.resolve_expr(else_tail, expected)
		return tc.if_branch_type_compatible_with_context(else_actual, else_tail, expected)
	}
	return false
}

fn (mut tc TypeChecker) apply_match_branch_context_smartcasts(subject_key string, subject_type Type, branch flat.Node) {
	if subject_key.len == 0 || !valid_string_data(subject_key) || branch.kind != .match_branch {
		return
	}
	n_conds := if branch.value == 'else' { 0 } else { branch.value.int() }
	if n_conds != 1 || branch.children_count == 0 {
		return
	}
	cond := tc.a.node(tc.a.child(&branch, 0))
	pattern := tc.match_type_pattern(cond) or { return }
	smartcast_type := if subject_type is SumType {
		tc.sum_variant_type_for_pattern(subject_type.name, pattern) or { pattern }
	} else if is_ierror_type(subject_type) {
		tc.resolve_ierror_match_pattern(pattern) or { pattern }
	} else if subject_type is Interface {
		tc.resolve_interface_match_pattern(pattern) or { pattern }
	} else {
		return
	}
	tc.smartcasts[subject_key] = tc.parse_type(smartcast_type)
}

// extract_smartcasts supports extract smartcasts handling for TypeChecker.
fn (tc &TypeChecker) extract_smartcasts(cond_id flat.NodeId) []LocalBinding {
	if int(cond_id) < 0 {
		return []LocalBinding{}
	}
	cond := tc.a.nodes[int(cond_id)]
	if cond.kind == .is_expr && cond.children_count > 0 {
		expr_id := tc.a.child(&cond, 0)
		if tc.nonmut_mutable_interface_smartcast(expr_id) {
			return []LocalBinding{}
		}
		key := tc.expr_key(expr_id)
		if key.len > 0 && valid_string_data(key) && cond.value.len > 0 {
			mut result := []LocalBinding{}
			result << LocalBinding{
				name: key
				typ:  tc.smartcast_target_type_for_is_expr(expr_id, cond.value)
			}
			return result
		}
	}
	// `x != none` (or `!= nil` for `?&T`) unwraps the option expr inside the then-branch.
	if cond.kind == .infix && cond.op == .ne && cond.children_count >= 2 {
		if binding := tc.option_none_cmp_binding(cond) {
			return [binding]
		}
	}
	if cond.kind == .infix && cond.op == .logical_and && cond.children_count >= 2 {
		mut result := tc.extract_smartcasts(tc.a.child(&cond, 0))
		result << tc.extract_smartcasts(tc.a.child(&cond, 1))
		return result
	}
	return []LocalBinding{}
}

fn (tc &TypeChecker) nonmut_mutable_interface_smartcast(expr_id flat.NodeId) bool {
	if !tc.valid_node_id(expr_id) {
		return false
	}
	expr := tc.a.node(expr_id)
	if expr.is_mut {
		return false
	}
	root_id := tc.lvalue_root_ident(expr_id) or { return false }
	root := tc.a.node(root_id)
	if root.kind != .ident || !tc.ident_is_mutable_lvalue(root.value) {
		return false
	}
	declared := unalias_and_unwrap_pointer_type(tc.cur_scope.lookup(root.value) or { return false })
	return declared is Interface
}

// option_none_cmp_binding matches a `x != none` / `x == none` (also `nil`)
// comparison where x is an option and returns the unwrapped binding for x.
fn (tc &TypeChecker) option_none_cmp_binding(cond flat.Node) ?LocalBinding {
	lhs_id := tc.a.child(&cond, 0)
	rhs_id := tc.a.child(&cond, 1)
	lhs := tc.a.nodes[int(lhs_id)]
	rhs := tc.a.nodes[int(rhs_id)]
	mut opt_id := flat.NodeId(-1)
	if rhs.kind == .none_expr || rhs.kind == .nil_literal {
		opt_id = lhs_id
	} else if lhs.kind == .none_expr || lhs.kind == .nil_literal {
		opt_id = rhs_id
	}
	if int(opt_id) < 0 {
		return none
	}
	key := tc.expr_key(opt_id)
	if key.len == 0 || !valid_string_data(key) {
		return none
	}
	mut opt_type := tc.expr_type(opt_id) or { tc.resolve_type(opt_id) }
	opt_node := tc.a.node(opt_id)
	if opt_node.kind == .selector {
		if declared := tc.selector_declared_value_type(*opt_node) {
			opt_type = declared
		}
	} else if opt_node.kind == .ident {
		if mut_base := tc.mut_param_base_for_current_ident(opt_node.value, opt_type) {
			opt_type = mut_base
		}
	}
	if opt_type is OptionType {
		base := opt_type.base_type
		if base !is Void && base !is Unknown {
			return LocalBinding{
				name: key
				typ:  base
			}
		}
	}
	return none
}

// extract_else_branch_smartcasts returns bindings that apply to the ELSE branch:
// `if x == none { ... } else { <x unwrapped here> }`.
fn (tc &TypeChecker) extract_else_branch_smartcasts(cond_id flat.NodeId) []LocalBinding {
	if int(cond_id) < 0 {
		return []LocalBinding{}
	}
	cond := tc.a.nodes[int(cond_id)]
	if binding := tc.negated_is_smartcast(cond_id) {
		return [binding]
	}
	if cond.kind == .infix && cond.op == .eq && cond.children_count >= 2 {
		if binding := tc.option_none_cmp_binding(cond) {
			return [binding]
		}
	}
	return []LocalBinding{}
}

// check_struct_init validates check struct init state for types.
fn (mut tc TypeChecker) check_struct_init(id flat.NodeId, node flat.Node) {
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.node(child_id)
		if child.kind == .directive && child.value.starts_with('embed_invalid_compression:') {
			compression_type := child.value.all_after(':')
			tc.record_error_at(.unknown_type,
				'not supported compression type: .${compression_type}. supported: .none, .zlib',
				child_id, child.pos)
			return
		}
	}
	if node.value == 'any' {
		tc.record_error(.unknown_type, 'cannot use type `any` here', id)
		return
	}
	if node.value.starts_with('chan ') {
		elem_type := trimmed_space(node.value[5..])
		if should_check_named_type(elem_type) && !tc.type_name_known(elem_type) {
			tc.record_unknown_decl_type(elem_type, id)
		}
		return
	}
	is_optional_init := node.value.starts_with('?')
	init_type_text := if is_optional_init { node.value[1..] } else { node.value }
	parsed_init_type := tc.parse_type(init_type_text)
	clean_parsed_init_type := unalias_type(parsed_init_type)
	if clean_parsed_init_type is Array || clean_parsed_init_type is ArrayFixed {
		elem_type := array_like_elem_type(clean_parsed_init_type) or { Type(void_) }
		tc.remember_expr_type(id, parsed_init_type)
		for i in 0 .. node.children_count {
			field := tc.a.child_node(&node, i)
			if field.kind != .field_init || field.children_count == 0 {
				continue
			}
			value_id := tc.a.child(field, 0)
			tc.check_node(value_id)
			actual := tc.resolve_expr(value_id, elem_type)
			if actual is Unknown || tc.expr_compatible(value_id, actual, elem_type) {
				continue
			}
			tc.record_error_at(.assignment_mismatch, 'invalid array element: expected `${elem_type.name()}`, not `${tc.diagnostic_expr_type_name(value_id,
				actual)}`', value_id, tc.array_element_diagnostic_pos(value_id))
		}
		return
	}
	generic_base, generic_args, has_generic_args := generic_type_application_parts(init_type_text)
	if has_generic_args {
		qualified_base := tc.qualify_name(generic_base)
		if (generic_base in tc.structs || qualified_base in tc.structs)
			&& generic_base !in tc.struct_generic_params
			&& qualified_base !in tc.struct_generic_params {
			if generic_args.any(is_bare_generic_param(it)) {
				tc.record_error_at(.unsupported_generic,
					'a non generic struct `${generic_base.all_after_last('.')}` used like a generic struct',
					id, tc.type_diagnostic_pos(id, generic_base))
			} else {
				tc.record_error_at(.unsupported_generic,
					'struct `${generic_base.all_after_last('.')}` is not a generic struct, cannot instantiate to the concrete types',
					id, tc.explicit_generic_args_diagnostic_pos(id))
			}
			tc.register_synth_type(id, tc.parse_type(generic_base))
			for i in 0 .. node.children_count {
				tc.check_node(tc.a.child(&node, i))
			}
			return
		}
		params := tc.struct_generic_params[generic_base] or {
			tc.struct_generic_params[qualified_base] or { []string{} }
		}
		if params.len > 0 && generic_args.len != params.len {
			message := if tc.fn_context.generic_params.len > 0 {
				'generic struct init expects ${params.len} generic parameter, but got ${generic_args.len}'
			} else {
				'the number of generic types of struct `${generic_base.all_after_last('.')}` is inconsistent with the concrete types'
			}
			pos := if tc.fn_context.generic_params.len > 0 {
				tc.struct_init_head_pos(node)
			} else {
				tc.explicit_generic_args_diagnostic_pos(id)
			}
			tc.record_error_at(.unsupported_generic, message, id, pos)
			tc.register_synth_type(id, tc.parse_type(generic_base))
			for i in 0 .. node.children_count {
				tc.check_node(tc.a.child(&node, i))
			}
			return
		}
		if params.len > 0 && tc.fn_context.generic_params.len > 0 {
			for arg in generic_args {
				if is_bare_generic_param(arg) && arg !in tc.fn_context.generic_params {
					current := '(${tc.fn_context.generic_params.join(',')})'
					tc.record_error_at(.unsupported_generic,
						'generic struct init type parameter `${arg}` must be within the parameters `${current}` of the current generic function',
						id, tc.struct_init_head_pos(node))
					tc.register_synth_type(id, tc.parse_type(generic_base))
					for i in 0 .. node.children_count {
						tc.check_node(tc.a.child(&node, i))
					}
					return
				}
			}
		}
	}
	if init_type_text != 'struct' && !is_anonymous_struct_name(init_type_text)
		&& !tc.type_name_known(init_type_text) {
		if is_bare_generic_param(init_type_text)
			&& tc.unmentioned_generic_type_was_reported(init_type_text, node.pos.id) {
			for i in 0 .. node.children_count {
				tc.check_node(tc.a.child(&node, i))
			}
			tc.remember_expr_type(id, unknown_type('unmentioned generic `${init_type_text}`'))
			return
		}
		if tc.struct_init_has_positional_fields(node) {
			tc.record_error_at(.unknown_type, 'unknown type `${node.value}`', id, node.pos)
		} else if candidates := tc.selective_import_candidates(init_type_text) {
			if candidates.len == 1 {
				tc.record_error_at(.unknown_type, tc.unknown_type_message(candidates[0], id), id,
					node.pos)
			} else {
				tc.record_error(.unknown_type, 'unknown struct `${node.value}`', id)
			}
		} else {
			tc.record_error(.unknown_type, 'unknown struct `${node.value}`', id)
		}
		tc.record_invalid_struct_init_print_error(id)
		for i in 0 .. node.children_count {
			tc.check_node(tc.a.child(&node, i))
		}
		tc.register_synth_type(id, Type(void_))
		return
	}
	mut init_type := tc.parse_type(init_type_text)
	if is_contextual_anonymous_struct_literal(init_type_text) && tc.expected_expr_id >= 0
		&& tc.expr_is_value_tail_of(flat.NodeId(tc.expected_expr_id), id) {
		expected := unalias_type(tc.expected_expr_type)
		if expected is Struct && is_anonymous_struct_name(expected.name) {
			init_type = expected
			tc.remember_expr_type(id, expected)
		}
	}
	if is_optional_init {
		tc.remember_expr_type(id, Type(OptionType{
			base_type: init_type
		}))
	}
	if unalias_type(init_type) is Enum {
		tc.record_error_at(.assignment_mismatch, 'cannot initialize enums', id, node.pos)
		return
	}
	clean_init_type := unalias_type(init_type)
	if clean_init_type is Interface {
		tc.record_error_at(.assignment_mismatch,
			'cannot instantiate interface `${clean_init_type.name.all_after_last('.')}`', id,
			node.pos)
		return
	}
	if init_struct := struct_type_from_type(init_type) {
		if _ := tc.private_declaration(init_struct.name) {
			inside_module := if tc.cur_module.len > 0 { tc.cur_module } else { 'main' }
			tc.record_error_at(.unknown_type,
				'struct `${init_struct.name}` was declared as private to module `${init_struct.name.all_before_last('.')}`, so it can not be used inside module `${inside_module}`',
				id, node.pos)
			tc.record_error_at(.unknown_type, 'type `${init_struct.name}` is private', id, node.pos)
		}
		if deprecation := tc.deprecated_symbols[init_struct.name] {
			tc.record_deprecation(id, 'struct', deprecation, tc.struct_init_deprecation_pos(node))
		}
		if init_type !is Alias {
			if inferred_type := tc.infer_generic_struct_init_type(node) {
				tc.remember_expr_type(id, inferred_type)
			} else if generic_name := tc.bare_generic_decl_type_name(init_type_text) {
				qualified := tc.qualify_name(generic_name)
				params := tc.struct_generic_params[generic_name] or {
					tc.struct_generic_params[qualified] or { []string{} }
				}
				if params.len > 0 {
					inferred := tc.infer_generic_struct_init_param_texts(node, generic_name, params)
					mut missing_param := params[0]
					for param in params {
						if param !in inferred {
							missing_param = param
							break
						}
					}
					tc.record_error_at(.unknown_type,
						'could not infer generic type `${missing_param}` in generic struct `${generic_name}[${params.join(', ')}]`',
						id, node.pos)
				}
			}
		}
		init_name := tc.struct_init_field_lookup_name(init_type_text, init_struct.name)
		fields := tc.struct_fields_for_init(init_name)
		mut positional_fields := 0
		mut named_fields := 0
		for i in 0 .. node.children_count {
			field := tc.a.child_node(&node, i)
			if field.kind != .field_init {
				continue
			}
			if field.value.len == 0 {
				positional_fields++
			} else {
				named_fields++
			}
		}
		if positional_fields > 0 && named_fields == 0 && positional_fields != fields.len {
			amount := if positional_fields < fields.len { 'few' } else { 'many' }
			tc.record_error_at(.assignment_mismatch,
				'too ${amount} fields in `${init_type_text.all_after_last('.')}` literal (expecting ${fields.len}, got ${positional_fields})',
				id, node.pos)
		}
		if unknown_message := tc.generic_struct_field_unknown_type_message(init_name) {
			tc.record_error_at(.unknown_type, unknown_message, id, tc.struct_init_head_pos(node))
		}
		mut supplied_fields := map[string]bool{}
		for i in 0 .. node.children_count {
			field := tc.a.child_node(&node, i)
			if field.kind != .field_init {
				continue
			}
			if field.value.len > 0 {
				supplied_fields[field.value] = true
			} else if i < fields.len {
				supplied_fields[fields[i].name] = true
			}
		}
		for i in 0 .. node.children_count {
			raw_spread_id := tc.a.child(&node, i)
			spread := tc.a.child_node(&node, i)
			spread_id := if spread.kind == .prefix && spread.value == '...'
				&& spread.children_count > 0 {
				tc.a.child(spread, 0)
			} else if tc.node_has_ellipsis_prefix(raw_spread_id) {
				raw_spread_id
			} else {
				continue
			}
			spread_type := tc.resolve_type(spread_id)
			spread_struct := struct_type_from_type(spread_type) or {
				tc.record_error_at(.assignment_mismatch,
					'expected struct, found `${spread_type.name()}`', spread_id,
					tc.a.node(spread_id).pos)
				continue
			}
			spread_fields := tc.struct_fields_for_init(spread_struct.name)
			mut compatible := true
			for target_field in fields {
				if supplied_fields[target_field.name] {
					continue
				}
				mut found := false
				for source_field in spread_fields {
					if source_field.name == target_field.name
						&& tc.type_compatible(source_field.typ, target_field.typ)
						&& tc.type_compatible(target_field.typ, source_field.typ) {
						found = true
						break
					}
				}
				if !found {
					compatible = false
					break
				}
			}
			if !compatible {
				tc.record_error_at(.assignment_mismatch,
					'struct `${spread_struct.name.all_after_last('.')}` is not compatible with struct `${init_struct.name.all_after_last('.')}`',
					spread_id, tc.a.node(spread_id).pos)
			}
			for source_field in spread_fields {
				supplied_fields[source_field.name] = true
			}
		}
		for field in fields {
			if supplied_fields[field.name] || field.has_default || field.typ is OptionType {
				continue
			}
			if unalias_type(field.typ) is Interface {
				tc.record_notice_at(.assignment_mismatch,
					'interface field `${init_struct.name}.${field.name}` must be initialized', id,
					tc.struct_init_head_pos(node))
			}
		}
		for missing in tc.missing_required_struct_fields(init_name, supplied_fields, []string{}) {
			tc.record_error_at(.assignment_mismatch, 'field `${missing}` must be initialized', id,
				tc.struct_init_head_pos(node))
		}
		mut seen_missing_references := map[string]bool{}
		for missing in tc.missing_reference_struct_fields(init_name, supplied_fields, []string{}) {
			if seen_missing_references[missing.path] {
				continue
			}
			seen_missing_references[missing.path] = true
			message := if missing.has_part {
				'reference field `${missing.path}` must be initialized (part of struct `${missing.owner}`)'
			} else {
				'reference field `${missing.path}` must be initialized'
			}
			tc.record_error_at(.assignment_mismatch, message, id, tc.struct_init_head_pos(node))
		}
		for i in 0 .. node.children_count {
			field_id := tc.a.child(&node, i)
			field := tc.a.nodes[int(field_id)]
			if field.kind != .field_init || field.children_count == 0 {
				tc.check_node(field_id)
				continue
			}
			if deprecation := tc.deprecated_symbols['${init_name}.${field.value}'] {
				tc.record_deprecation(field_id, 'field', deprecation,
					tc.struct_init_field_deprecation_pos(field))
			}
			value_id := tc.a.child(&field, 0)
			mut expected := Type(void_)
			if field.value.len > 0 {
				mut found := false
				if typ := tc.struct_field_type(init_name, field.value) {
					expected = typ
					found = true
				}
				if found && tc.unsafe_depth == 0 {
					owner_base := strip_generic_args_name(init_name)
					decl_mod := tc.struct_modules[owner_base] or { '' }
					if decl_mod.len > 0 && decl_mod != tc.cur_module {
						is_public := tc.visible_mutation_struct_field_is_public(init_name,
							field.value, decl_mod) or { true }
						if !is_public {
							tc.record_error_at(.unknown_field,
								'cannot access private field `${field.value}` on `${init_type_text}`',
								field_id, tc.struct_init_field_deprecation_pos(field))
						}
					}
				}
				if !found && tc.should_diagnose(field_id) && fields.len > 0 {
					tc.record_error_at(.unknown_field, tc.struct_literal_unknown_field_message(init_name,
						field.value, fields), field_id, tc.struct_init_field_deprecation_pos(field))
				}
			} else if i < fields.len {
				expected = fields[i].typ
			}
			field_is_mut := struct_init_field_is_mut(fields, field, i)
			source_actual := if expected !is Void {
				tc.resolve_type(value_id)
			} else {
				Type(void_)
			}
			if expected !is Pointer && tc.type_has_declaration_attribute(expected, 'nocopy') {
				tc.record_error_at(.assignment_mismatch,
					'cannot copy @[nocopy] struct: use a reference instead', value_id,
					tc.a.node(value_id).pos)
			}
			if expected is Pointer {
				tc.record_non_heap_pointer_param_escape(value_id)
			}
			// A method value stored in a struct field escapes the evaluation site (several
			// instances from the same `Foo{cb: obj.method}` site would share one receiver).
			if !tc.stored_method_value_matches_voidptr_callback(value_id, expected) {
				tc.reject_stored_method_value(value_id)
			}
			tc.reject_stored_or_returned_capturing_fn_literal(value_id)
			if expected !is Void {
				warning_pos := if field.value.len > 0 {
					tc.struct_init_field_deprecation_pos(field)
				} else {
					tc.a.nodes[int(value_id)].pos
				}
				tc.warn_if_integer_literal_outside_known_type_range(value_id, expected, warning_pos)
				tc.check_node_with_expected_context(value_id, expected)
			} else {
				tc.check_node(value_id)
			}
			$if ownership ? {
				if !tc.ownership_aggregate_consumption_deferred(id) {
					tc.ownership_consume_expr(value_id, 'struct field', value_id)
				}
			}
			value_node := tc.a.node(value_id)
			if type_is_unsigned_integer(expected) && tc.expr_is_negative_integer_literal(value_id) {
				tc.record_error_at(.assignment_mismatch,
					'cannot assign negative value to unsigned integer type', value_id,
					value_node.pos)
			}
			if tc.unsafe_depth == 0 && !tc.translated_files[tc.cur_file]
				&& unalias_type(expected) is Pointer && value_node.kind == .int_literal
				&& value_node.value == '0' && expected.name() != 'voidptr' {
				pos := if field.value.len > 0 {
					tc.struct_init_field_value_pos(field, value_id)
				} else {
					value_node.pos
				}
				tc.record_error_at(.assignment_mismatch,
					'assigning `0` to a reference field is only allowed in `unsafe` blocks',
					field_id, pos)
			}
			if tc.unsafe_depth == 0 && unalias_type(expected) is Array
				&& (field_is_mut || tc.slice_expr_base_is_mutable(value_id)) {
				tc.record_implicit_slice_clone_notice(value_id)
			}
			if tc.unsafe_depth == 0 && field_is_mut && unalias_type(expected) is Array
				&& value_node.kind == .ident && tc.const_key_for_name(value_node.value) != none {
				tc.record_error_at(.assignment_mismatch,
					'cannot assign a const array to mut struct field, call `clone` method (or use `unsafe`)',
					value_id, value_node.pos)
			}
			if tc.unsafe_depth == 0 && field_is_mut && unalias_type(expected) is Map
				&& value_node.kind == .ident && tc.const_key_for_name(value_node.value) != none {
				tc.record_error_at(.assignment_mismatch,
					'cannot assign a const map to mut struct field, call `clone` method (or use a reference)',
					value_id, value_node.pos)
			}
			if tc.unsafe_depth == 0 && field_is_mut {
				if addressed_id := tc.addressed_ident(value_id) {
					addressed := tc.a.node(addressed_id)
					if !tc.ident_is_mutable_lvalue(addressed.value) {
						tc.record_error_at(.assignment_mismatch,
							'`${addressed.value}` is immutable, cannot have a mutable reference to an immutable object',
							addressed_id, addressed.pos)
					}
				}
			}
			if expected !is Void {
				mut actual := tc.resolve_expr(value_id, expected)
				if value_node.kind == .call {
					if call_info := tc.resolve_call_info(value_id, value_node) {
						if call_info.return_type !is Unknown && call_info.return_type !is Void {
							actual = call_info.return_type
						}
					}
				}
				if !tc.expr_compatible(value_id, actual, expected) {
					if semantic_mut_param := tc.mut_param_expr_base(value_id, actual) {
						actual = semantic_mut_param
					}
				}
				pointer_to_value_fixed_array := actual is Pointer
					&& unalias_type(actual.base_type) is ArrayFixed
					&& unalias_type(expected) is ArrayFixed
				clean_expected := unalias_type(expected)
				clean_actual := unalias_type(actual)
				if clean_expected is None {
					continue
				}
				if value_node.kind == .map_init && tc.map_literal_has_element_diagnostic(value_id) {
					continue
				}
				if tc.expr_is_unsafe_nil(value_id) && clean_expected !is Pointer {
					if expected is String {
						tc.record_error_at(.assignment_mismatch,
							'cannot assign to field `${field.value}`: expected `string`, not `voidptr`',
							field_id, tc.struct_init_unsafe_nil_type_mismatch_pos(field, value_id))
					}
					tc.record_error_at(.assignment_mismatch,
						'cannot assign `nil` to struct field `${field.value}` with type `${clean_expected.name()}`',
						value_id, tc.struct_init_unsafe_nil_value_pos(value_id))
					continue
				}
				if clean_actual is ResultType && clean_expected !is ResultType {
					tc.record_unhandled_result_call(value_id, clean_actual)
					continue
				}
				if clean_actual is Void {
					tc.record_error_at(.assignment_mismatch,
						'`${tc.source_text_for_node(value_id)}` (no value) used as value',
						field_id, tc.struct_init_field_deprecation_pos(field))
					continue
				}
				if clean_expected is FnType {
					expected_fn_text, expected_alias := tc.struct_field_diagnostic_fn_type(init_name,
						field.value, i) or { '', '' }
					actual_fn_text := tc.expr_diagnostic_fn_type(value_id) or { '' }
					if expected_fn_text.len > 0 && actual_fn_text.len > 0
						&& expected_fn_text != actual_fn_text&& (fn_diagnostic_parameter_modes(expected_fn_text) != fn_diagnostic_parameter_modes(actual_fn_text)
						|| !tc.fn_types_match_ignoring_module_qualification(clean_expected, clean_actual)) {
						details := tc.fn_assignment_mismatch_details(expected_fn_text,
							expected_alias, actual_fn_text, value_id)
						message := 'cannot assign to field `${field.value}`: expected `${expected_fn_text}`, not `${actual_fn_text}`'
						if details.len > 0 {
							tc.record_error_with_details_at(.assignment_mismatch, message,
								field_id, tc.struct_init_field_value_pos(field, value_id), details)
						} else {
							tc.record_error_at(.assignment_mismatch, message, field_id, tc.struct_init_field_value_pos(field,
								value_id))
						}
						continue
					}
				}
				if value_node.kind == .fn_literal && value_node.typ == '?'
					&& clean_expected is FnType {
					expected_name := expected.name().replace_once('fn(', 'fn (')
					tc.record_error_at(.assignment_mismatch,
						'cannot assign to field `${field.value}`: expected `${expected_name}`, not `${expected_name} ?`',
						field_id, tc.struct_init_field_deprecation_pos(field))
				} else if clean_expected is OptionType && clean_actual is Pointer
					&& unalias_type(clean_expected.base_type) !is Pointer {
					tc.record_error_at(.assignment_mismatch,
						'cannot assign a pointer to option struct field', field_id,
						tc.struct_init_pointer_field_pos(field))
				} else if clean_expected is OptionType
					&& unalias_type(clean_expected.base_type) is Pointer
					&& clean_actual is OptionType
					&& unalias_type(clean_actual.base_type) !is Pointer {
					tc.record_error_at(.assignment_mismatch,
						'cannot assign to field `${field.value}`: expected a pointer `${expected.name()}`, but got `${actual.name()}`',
						field_id, tc.struct_init_field_deprecation_pos(field))
				} else if tc.anonymous_struct_assignment_mismatch(value_id, actual, expected) {
					tc.record_error_at(.assignment_mismatch,
						'cannot assign anonymous `struct` to a typed `struct`', value_id,
						tc.anonymous_struct_literal_brace_pos(value_id))
				} else if value_node.kind == .map_init && value_node.children_count == 0
					&& clean_expected is Struct && is_anonymous_struct_name(clean_expected.name) {
					tc.record_error_at(.assignment_mismatch,
						'`{}` cannot be used to initialize anonymous structs. Use `struct{}` instead.',
						value_id, tc.empty_map_literal_diagnostic_pos(value_id))
				} else if clean_actual is OptionType && clean_expected !is OptionType {
					tc.record_error_at(.assignment_mismatch,
						'cannot assign an Option value to a non-option struct field', field_id,
						tc.struct_init_field_deprecation_pos(field))
				} else if clean_actual is FnType && clean_expected is FnType
					&& actual.name() != expected.name()
					&& !tc.fn_types_match_ignoring_module_qualification(clean_expected, clean_actual) {
					tc.record_error_at(.assignment_mismatch,
						'cannot assign to field `${field.value}`: expected `${expected.name()}`, not `${actual.name()}`',
						field_id, tc.struct_init_field_deprecation_pos(field))
				} else if clean_expected is Interface
					&& !tc.type_implements_interface(actual, clean_expected)
					&& tc.record_interface_implementation_error(.assignment_mismatch, actual, clean_expected, field_id, tc.struct_init_field_value_pos(field, value_id)) {
					continue
				} else if pointer_to_value_fixed_array
					|| tc.distinct_alias_primitive_mismatch(source_actual, expected)
					|| (clean_expected is Map && clean_actual is Map
					&& clean_expected.name() != clean_actual.name())
					|| (!tc.expr_compatible(value_id, actual, expected)
					&& !tc.method_value_matches_voidptr_callback(value_id, actual, expected)
					&& !tc.pointer_value_compatible(actual, expected)) {
					diagnostic_actual := if tc.distinct_alias_primitive_mismatch(source_actual,
						expected)
					{
						source_actual
					} else {
						actual
					}
					actual_name := tc.diagnostic_expr_type_name(value_id, diagnostic_actual)
					field_pos := tc.struct_init_field_value_pos(field, value_id)
					if clean_expected is Pointer && clean_actual !is Pointer {
						if expected.name() == 'voidptr' {
							if clean_actual is Struct {
								tc.record_error_at(.assignment_mismatch,
									'allocate `${clean_actual.name}` on the heap for use in other functions',
									field_id, field_pos)
							} else if tc.should_diagnose(value_id) {
								source_value := tc.source_text_for_node(value_id)
								tc.record_notice_at(.assignment_mismatch,
									'voidptr variables may only be assigned voidptr values (e.g. unsafe { voidptr(${source_value}) })',
									value_id, value_node.pos)
							}
							if !clean_actual.is_integer() {
								tc.record_error_at(.assignment_mismatch,
									'cannot assign to field `${field.value}`: expected a pointer `voidptr`, but got `${actual_name}`',
									field_id, field_pos)
							}
						} else if clean_actual.name() == 'bool' {
							tc.record_error_at(.assignment_mismatch,
								'cannot assign to field `${field.value}`: expected `${expected.name()}`, not `${actual_name}`',
								field_id, field_pos)
							tc.record_error_at(.assignment_mismatch,
								'reference field must be initialized with reference', field_id,
								field_pos)
						} else {
							tc.record_error_at(.assignment_mismatch,
								'reference field must be initialized with reference', field_id,
								field_pos)
						}
					} else {
						tc.record_error_at(.assignment_mismatch,
							'cannot assign to field `${field.value}`: expected `${expected.name()}`, not `${actual_name}`',
							field_id, field_pos)
					}
				}
			}
		}
		return
	}
	for i in 0 .. node.children_count {
		tc.check_node(tc.a.child(&node, i))
	}
	_ = id
}

fn (tc &TypeChecker) fn_types_match_ignoring_module_qualification(expected FnType, actual Type) bool {
	if actual !is FnType || expected.params.len != actual.params.len {
		return false
	}
	for i, param in expected.params {
		if !tc.types_match_ignoring_module_qualification(param, actual.params[i]) {
			return false
		}
	}
	return tc.types_match_ignoring_module_qualification(expected.return_type, actual.return_type)
}

fn (tc &TypeChecker) types_match_ignoring_module_qualification(expected Type, actual Type) bool {
	left := unalias_type(expected)
	right := unalias_type(actual)
	if left.name() == right.name() {
		return true
	}
	if left is Struct && right is Struct {
		return short_type_name(left.name) == short_type_name(right.name)
	}
	if left is Pointer && right is Pointer {
		return tc.types_match_ignoring_module_qualification(left.base_type, right.base_type)
	}
	if left is OptionType && right is OptionType {
		return tc.types_match_ignoring_module_qualification(left.base_type, right.base_type)
	}
	if left is ResultType && right is ResultType {
		return tc.types_match_ignoring_module_qualification(left.base_type, right.base_type)
	}
	return false
}

fn (mut tc TypeChecker) record_invalid_struct_init_print_error(id flat.NodeId) {
	parent_id := tc.direct_parent_id(id)
	if !tc.valid_node_id(parent_id) {
		return
	}
	parent := tc.a.node(parent_id)
	if parent.kind != .call || parent.children_count == 0 {
		return
	}
	callee := tc.a.child_node(parent, 0)
	if callee.kind == .ident && callee.value in ['print', 'println', 'eprint', 'eprintln'] {
		tc.record_error_at(.call_arg_mismatch, '`${callee.value}` can not print void expressions',
			parent_id, parent.pos)
	}
}

fn struct_init_field_is_mut(fields []StructField, field flat.Node, index int) bool {
	if field.value.len > 0 {
		for candidate in fields {
			if candidate.name == field.value {
				return candidate.is_mut
			}
		}
		return false
	}
	return index >= 0 && index < fields.len && fields[index].is_mut
}

fn (tc &TypeChecker) node_has_ellipsis_prefix(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	file := tc.a.source_files[node.pos.id] or { return false }
	source := tc.source_texts_by_file[file.name] or { return false }
	mut cursor := int_min(int_max(node.pos.offset, 0), source.len)
	for cursor > 0 && source[cursor - 1] in [` `, `\t`, `\n`, `\r`] {
		cursor--
	}
	return cursor >= 3 && source[cursor - 3..cursor] == '...'
}

fn (tc &TypeChecker) struct_init_has_positional_fields(node flat.Node) bool {
	for i in 0 .. node.children_count {
		field := tc.a.child_node(&node, i)
		if field.kind == .field_init && field.value.len == 0 {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) distinct_alias_primitive_mismatch(actual Type, expected Type) bool {
	if actual is Alias && unalias_type(expected) is Primitive {
		return actual.base_type.name() != unalias_type(expected).name()
	}
	return false
}

fn (tc &TypeChecker) generic_struct_field_unknown_type_message(struct_name string) ?string {
	decl := tc.source_struct_decl_for_name(struct_name) or { return none }
	for i in 0 .. decl.children_count {
		field_id := tc.a.child(&decl, i)
		field := tc.a.node(field_id)
		if field.kind != .field_decl || !generic_type_application(field.typ) {
			continue
		}
		for diagnostic in tc.errors {
			if diagnostic.node == field_id && diagnostic.kind == .unknown_type
				&& diagnostic.msg.starts_with('unknown type `') {
				return diagnostic.msg
			}
		}
		if unknown_name := tc.first_unknown_type_name(field.typ) {
			return tc.unknown_type_message(unknown_name, field_id)
		}
	}
	return none
}

fn (tc &TypeChecker) first_unknown_type_name(raw string) ?string {
	clean := trimmed_space(raw)
	if clean.len == 0 {
		return none
	}
	for prefix in ['?', '!', '&', '[]', 'shared ', 'mut '] {
		if clean.starts_with(prefix) {
			return tc.first_unknown_type_name(clean[prefix.len..])
		}
	}
	base, args, is_generic := generic_type_application_parts(clean)
	if is_generic {
		if should_check_named_type(base) && !tc.type_name_known(base) {
			return base
		}
		for arg in args {
			if unknown := tc.first_unknown_type_name(arg) {
				return unknown
			}
		}
		return none
	}
	if should_check_named_type(clean) && !tc.type_name_known(clean) {
		return clean
	}
	return none
}

fn struct_field_has_attr(field flat.Node, name string) bool {
	meta := field.generic_params()
	if meta.len < 2 {
		return false
	}
	for attr in meta[1..] {
		if attr.all_before(':').trim_space() == name {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) source_struct_decl_for_name(name string) ?flat.Node {
	id := tc.source_struct_decl_id_for_name(name)?
	return *tc.a.node(id)
}

fn (tc &TypeChecker) source_struct_decl_id_for_name(name string) ?flat.NodeId {
	raw_target := trimmed_space(name)
	parsed_target, _, is_generic := generic_type_application_parts(raw_target)
	target := if is_generic { parsed_target } else { raw_target }
	mut module_name := ''
	for index in tc.top_level_idx {
		node := tc.a.nodes[index]
		if node.kind == .module_decl {
			module_name = node.value
			continue
		}
		if node.kind != .struct_decl {
			continue
		}
		qualified := qualify_decl_name_in_module(node.value, module_name)
		if node.value == target || qualified == target {
			return flat.NodeId(index)
		}
	}
	return none
}

fn (tc &TypeChecker) struct_field_diagnostic_fn_type(struct_name string, field_name string, field_index int) ?(string, string) {
	decl := tc.source_struct_decl_for_name(struct_name) or { return none }
	base, concrete_args, is_generic := generic_type_application_parts(struct_name)
	struct_params := if is_generic {
		tc.struct_generic_params[base] or {
			tc.struct_generic_params[base.all_after_last('.')] or { []string{} }
		}
	} else {
		[]string{}
	}
	mut ordinal := 0
	for i in 0 .. decl.children_count {
		field := tc.a.child_node(&decl, i)
		if field.kind != .field_decl {
			continue
		}
		if (field_name.len > 0 && field.value == field_name)
			|| (field_name.len == 0 && ordinal == field_index) {
			raw := if is_generic && concrete_args.len == struct_params.len {
				subst_generic_text(field.typ, concrete_args, struct_params)
			} else {
				trimmed_space(field.typ)
			}
			if raw.starts_with('fn(') || raw.starts_with('fn (') {
				return tc.diagnostic_fn_type_text(raw), ''
			}
			if alias_raw := tc.source_fn_alias_type_text(raw) {
				return tc.diagnostic_fn_type_text(alias_raw), raw
			}
			return none
		}
		ordinal++
	}
	return none
}

fn fn_diagnostic_parameter_modes(raw string) []string {
	clean := trimmed_space(raw)
	open := clean.index_u8(`(`)
	if open < 0 {
		return []string{}
	}
	mut depth := 1
	mut close := open + 1
	for close < clean.len && depth > 0 {
		if clean[close] == `(` {
			depth++
		} else if clean[close] == `)` {
			depth--
			if depth == 0 {
				break
			}
		}
		close++
	}
	if close >= clean.len {
		return []string{}
	}
	mut modes := []string{}
	for part in split_params(clean[open + 1..close]) {
		param := trimmed_space(part)
		modes << if param.starts_with('mut ') {
			'mut'
		} else if param.starts_with('&') {
			'&'
		} else {
			''
		}
	}
	return modes
}

fn (tc &TypeChecker) source_fn_alias_type_text(name string) ?string {
	mut target := trimmed_space(name)
	for _ in 0 .. 8 {
		target_base, target_args, target_is_generic := generic_type_application_parts(target)
		lookup_target := if target_is_generic { target_base } else { target }
		mut module_name := ''
		mut found := ''
		mut found_name := ''
		for index in tc.top_level_idx {
			node := tc.a.node(flat.NodeId(index))
			if node.kind == .module_decl {
				module_name = node.value
				continue
			}
			if node.kind != .type_decl || node.children_count > 0 {
				continue
			}
			qualified := qualify_decl_name_in_module(node.value, module_name)
			if node.value == lookup_target || qualified == lookup_target {
				mut source_type := tc.source_type_alias_rhs(tc.cur_file, node.value) or { '' }
				if source_type.len == 0 {
					if file := tc.a.source_files[node.pos.id] {
						source_type = tc.source_type_alias_rhs(file.name, node.value) or { '' }
					}
				}
				found = if source_type.starts_with('fn(') || source_type.starts_with('fn (') {
					source_type
				} else {
					node.typ
				}
				found_name = if qualified == lookup_target { qualified } else { node.value }
				break
			}
		}
		if found.len == 0 {
			return none
		}
		clean := trimmed_space(found)
		if clean.starts_with('fn(') || clean.starts_with('fn (') {
			if target_is_generic {
				params := tc.type_alias_generic_params[found_name] or {
					tc.type_alias_generic_params[found_name.all_after_last('.')] or { []string{} }
				}
				if params.len == target_args.len {
					return subst_generic_diagnostic_fn_text(clean, target_args, params)
				}
			}
			return clean
		}
		target = clean
	}
	return none
}

fn subst_generic_diagnostic_fn_text(raw string, args []string, params []string) string {
	clean := trimmed_space(raw)
	open := clean.index_u8(`(`)
	if open < 0 {
		return subst_generic_text(clean, args, params)
	}
	mut depth := 1
	mut close := open + 1
	for close < clean.len && depth > 0 {
		if clean[close] == `(` {
			depth++
		} else if clean[close] == `)` {
			depth--
			if depth == 0 {
				break
			}
		}
		close++
	}
	if close >= clean.len {
		return subst_generic_text(clean, args, params)
	}
	mut rendered_params := []string{}
	for part in split_params(clean[open + 1..close]) {
		rendered_params << subst_generic_text(part, args, params)
	}
	suffix := trimmed_space(clean[close + 1..])
	return 'fn (${rendered_params.join(', ')})${if suffix.len > 0 {
		' ${subst_generic_text(suffix, args, params)}'
	} else {
		''
	}}'
}

fn (tc &TypeChecker) source_type_alias_rhs(file_name string, alias_name string) ?string {
	if file_name.len == 0 || alias_name.len == 0 {
		return none
	}
	source := tc.source_texts_by_file[file_name] or { os.read_file(file_name) or { return none } }
	decl_start := source.index('type ${alias_name}') or { return none }
	line_end := source.index_after('\n', decl_start) or { source.len }
	assign := source[decl_start..line_end].index('=') or { return none }
	return source[decl_start + assign + 1..line_end].trim_space()
}

fn (tc &TypeChecker) expr_diagnostic_fn_type(id flat.NodeId) ?string {
	raw := tc.expr_raw_fn_type_text(id) or { return none }
	return tc.diagnostic_fn_type_text(raw)
}

fn (tc &TypeChecker) expr_raw_fn_type_text(id flat.NodeId) ?string {
	if !tc.valid_node_id(id) {
		return none
	}
	node := tc.a.node(id)
	if node.kind == .fn_literal {
		return tc.fn_node_source_type_text(node)
	}
	if node.kind == .ident {
		for index in tc.top_level_idx {
			decl := tc.a.node(flat.NodeId(index))
			if decl.kind == .fn_decl && decl.value.all_after_last('.') == node.value {
				return tc.fn_node_source_type_text(decl)
			}
		}
	}
	if node.kind in [.paren, .expr_stmt] && node.children_count > 0 {
		return tc.expr_raw_fn_type_text(tc.a.child(node, 0))
	}
	return none
}

fn (tc &TypeChecker) fn_node_source_type_text(node flat.Node) string {
	mut params := []string{}
	for i in 0 .. node.children_count {
		param := tc.a.child_node(&node, i)
		if param.kind != .param {
			continue
		}
		mut typ := param.typ
		if param.op == .dot && !typ.starts_with('...') {
			typ = '...${typ}'
		}
		prefix := if param.is_mut && !typ.starts_with('mut ') { 'mut ' } else { '' }
		if param.value.len > 0 {
			params << '${prefix}${param.value} ${typ}'
		} else {
			params << '${prefix}${typ}'
		}
	}
	return 'fn (${params.join(', ')})${if node.typ.len > 0 && node.typ != 'void' {
		' ${node.typ}'
	} else {
		''
	}}'
}

fn (tc &TypeChecker) diagnostic_fn_type_text(raw string) string {
	params, suffix := fn_diagnostic_type_parts(raw)
	mut display := []string{cap: params.len}
	for param in params {
		display << param.typ
	}
	return 'fn (${display.join(', ')})${suffix}'
}

fn fn_diagnostic_type_parts(raw string) ([]FnDiagnosticParam, string) {
	clean := trimmed_space(raw)
	open := clean.index_u8(`(`)
	if open < 0 {
		return []FnDiagnosticParam{}, ''
	}
	mut depth := 1
	mut close := open + 1
	for close < clean.len && depth > 0 {
		if clean[close] == `(` {
			depth++
		} else if clean[close] == `)` {
			depth--
		}
		if depth == 0 {
			break
		}
		close++
	}
	if close >= clean.len {
		return []FnDiagnosticParam{}, ''
	}
	mut params := []FnDiagnosticParam{}
	for raw_param in split_params(clean[open + 1..close]) {
		mut text := trimmed_space(raw_param)
		if text.len == 0 {
			continue
		}
		is_mut := text.starts_with('mut ')
		if is_mut {
			text = trimmed_space(text[4..])
		}
		mut name := ''
		space := top_level_space_index(text)
		if space > 0 {
			head := trimmed_space(text[..space])
			tail := trimmed_space(text[space + 1..])
			if fn_type_param_head_is_name(head, tail) {
				name = head
				text = tail
			}
		}
		is_variadic := text.starts_with('...')
		mut display_type := text
		if is_mut {
			display_type = 'mut ${display_type.trim_left('&')}'
		}
		params << FnDiagnosticParam{
			name:       name
			typ:        display_type
			is_mut:     is_mut
			is_pointer: !is_variadic && (is_mut || text.starts_with('&')
				|| text in ['voidptr', '&void'])
		}
	}
	suffix_text := trimmed_space(clean[close + 1..])
	suffix := if suffix_text.len > 0 { ' ${suffix_text}' } else { '' }
	return params, suffix
}

fn (tc &TypeChecker) fn_assignment_mismatch_details(expected_text string, expected_alias string, actual_text string, actual_id flat.NodeId) []string {
	expected_params, _ := fn_diagnostic_type_parts(expected_text)
	actual_params, _ := fn_diagnostic_type_parts(actual_text)
	mut expected_named := []FnDiagnosticParam{}
	if expected_alias.len > 0 {
		if raw := tc.source_fn_alias_type_text(expected_alias) {
			expected_named, _ = fn_diagnostic_type_parts(raw)
		}
	}
	mut actual_named := []FnDiagnosticParam{}
	if raw := tc.expr_raw_fn_type_text(actual_id) {
		actual_named, _ = fn_diagnostic_type_parts(raw)
	}
	for i in 0 .. int_min(expected_params.len, actual_params.len) {
		if expected_params[i].is_pointer == actual_params[i].is_pointer {
			continue
		}
		expected_pointer := if expected_params[i].is_pointer {
			'to be a pointer'
		} else {
			'to be NOT a pointer'
		}
		actual_pointer := if actual_params[i].is_pointer {
			'is a pointer'
		} else {
			'is NOT a pointer'
		}
		if expected_alias.len > 0 && i < expected_named.len && i < actual_named.len
			&& expected_named[i].name.len > 0 && actual_named[i].name.len > 0 {
			mut alias_name := tc.qualify_name(expected_alias)
			if !alias_name.contains('.') {
				alias_name = '${if tc.cur_module.len > 0 { tc.cur_module } else { 'main' }}.${alias_name}'
			}
			return [
				'`${alias_name}`\'s expected argument `${expected_named[i].name}` ${expected_pointer}, but the passed argument `${actual_named[i].name}` ${actual_pointer}',
			]
		}
		return [
			'expected argument ${i + 1} ${expected_pointer}, but the passed argument ${i + 1} ${actual_pointer}',
		]
	}
	return []string{}
}

fn (tc &TypeChecker) missing_reference_struct_fields(struct_name string, supplied map[string]bool, path []string) []MissingReferenceField {
	clean_name := trimmed_space(struct_name)
	if clean_name.len == 0 || clean_name in path || path.len >= 16 {
		return []MissingReferenceField{}
	}
	decl := tc.source_struct_decl_for_name(clean_name) or { return []MissingReferenceField{} }
	display_name := decl.value.all_after_last('.')
	mut next_path := path.clone()
	next_path << clean_name
	mut missing := []MissingReferenceField{}
	for i in 0 .. decl.children_count {
		field := tc.a.child_node(&decl, i)
		if field.kind != .field_decl {
			continue
		}
		field_type_text := if field.typ.len > 0 { field.typ } else { field.value }
		field_type := unalias_type(tc.parse_type(field_type_text))
		is_embed := source_field_decl_is_embed(field, field_type_text)
		if field_type is Pointer {
			if field.children_count == 0 && field.value !in supplied {
				missing << MissingReferenceField{
					path:  '${display_name}.${field.value}'
					owner: display_name
				}
			}
			continue
		}
		if field_type !is Struct || field.children_count > 0 {
			continue
		}
		if !is_embed && field.value in supplied {
			continue
		}
		child_supplied := if is_embed {
			supplied
		} else {
			map[string]bool{}
		}
		child_missing := tc.missing_reference_struct_fields(field_type.name(), child_supplied,
			next_path)
		for nested in child_missing {
			suffix := nested.path.all_after('.')
			outer_path := if is_embed {
				'${display_name}.${suffix}'
			} else {
				'${display_name}.${field.value}.${suffix}'
			}
			missing << MissingReferenceField{
				path:     outer_path
				owner:    nested.owner
				has_part: !is_embed
			}
			missing << nested
		}
	}
	return missing
}

fn (tc &TypeChecker) missing_required_struct_fields(struct_name string, supplied map[string]bool, path []string) []string {
	clean_name := trimmed_space(struct_name)
	if clean_name.len == 0 || clean_name in path || path.len >= 16 {
		return []string{}
	}
	decl := tc.source_struct_decl_for_name(clean_name) or { return []string{} }
	display_name := decl.value.all_after_last('.')
	mut next_path := path.clone()
	next_path << clean_name
	mut missing := []string{}
	for i in 0 .. decl.children_count {
		field := tc.a.child_node(&decl, i)
		if field.kind != .field_decl {
			continue
		}
		field_type_text := if field.typ.len > 0 { field.typ } else { field.value }
		is_embed := source_field_decl_is_embed(field, field_type_text)
		if struct_field_has_attr(*field, 'required') && field.value !in supplied {
			missing << '${display_name}.${field.value}'
		}
		field_type := unalias_type(tc.parse_type(field_type_text))
		if field_type !is Struct || field.children_count > 0 {
			continue
		}
		if !is_embed && field.value in supplied {
			continue
		}
		child_supplied := if is_embed {
			supplied
		} else {
			map[string]bool{}
		}
		child_missing := tc.missing_required_struct_fields(field_type.name(), child_supplied,
			next_path)
		if is_embed {
			for nested in child_missing {
				leaf := nested.all_after_last('.')
				outer := '${display_name}.${leaf}'
				if outer !in missing {
					missing << outer
				}
				missing << nested
			}
		} else {
			missing << child_missing
		}
	}
	return missing
}

fn (tc &TypeChecker) struct_init_head_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, int_min(node.pos.offset, source.len))
	end := int_max(start, int_min(node.pos.end, source.len))
	if start < end {
		if relative := source[start..end].index('{') {
			mut head_end := start + relative + 1
			if head_end < end && source[head_end] == `}` {
				head_end++
			}
			return token.new_span(node.pos.id, start, head_end)
		}
	}
	return node.pos
}

fn (tc &TypeChecker) struct_init_deprecation_pos(node flat.Node) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(node.pos.end, source.len)
	if end <= start {
		return node.pos
	}
	text := source[start..end]
	if dot := text.last_index('.') {
		return token.new_span(node.pos.id, start + dot + 1, end)
	}
	return node.pos
}

fn (tc &TypeChecker) struct_init_field_deprecation_pos(field flat.Node) token.Pos {
	file := tc.a.source_files[field.pos.id] or { return field.pos }
	source := tc.source_texts_by_file[file.name] or { return field.pos }
	offset := int_min(int_max(field.pos.offset, 0), source.len)
	line_start := if offset > 0 {
		if relative := source[..offset].last_index('\n') { relative + 1 } else { 0 }
	} else {
		0
	}
	line_end := source.index_after('\n', line_start) or { source.len }
	line := source[line_start..line_end].trim_right('\r\n')
	if relative := line.index(field.value) {
		start := line_start + relative
		return token.new_span(field.pos.id, start, line_start + line.len)
	}
	return field.pos
}

fn (tc &TypeChecker) struct_init_field_value_pos(field flat.Node, value_id flat.NodeId) token.Pos {
	value := tc.a.node(value_id)
	file := tc.a.source_files[value.pos.id] or {
		return tc.struct_init_field_deprecation_pos(field)
	}
	source := tc.source_texts_by_file[file.name] or {
		return tc.struct_init_field_deprecation_pos(field)
	}
	value_start := int_max(0, int_min(value.pos.offset, source.len))
	mut line_start := value_start
	for line_start > 0 && source[line_start - 1] != `\n` {
		line_start--
	}
	line_end := source.index_after('\n', line_start) or { source.len }
	if relative := source[line_start..line_end].index(field.value) {
		start := line_start + relative
		end := int_max(start, int_min(value.pos.end, source.len))
		return token.new_span(value.pos.id, start, end)
	}
	return tc.struct_init_field_deprecation_pos(field)
}

fn (tc &TypeChecker) struct_init_unsafe_nil_type_mismatch_pos(field flat.Node, value_id flat.NodeId) token.Pos {
	value := tc.a.node(value_id)
	field_name_pos := tc.struct_init_field_deprecation_pos(field)
	end := int_min(value.pos.end, value.pos.offset + 'unsafe'.len)
	return token.new_span(field_name_pos.id, field_name_pos.offset, end)
}

fn (tc &TypeChecker) struct_init_unsafe_nil_value_pos(value_id flat.NodeId) token.Pos {
	value := tc.a.node(value_id)
	return token.new_span(value.pos.id, value.pos.offset, int_max(value.pos.offset,
		value.pos.end - 1))
}

fn (tc &TypeChecker) struct_init_pointer_field_pos(field flat.Node) token.Pos {
	pos := tc.struct_init_field_deprecation_pos(field)
	file := tc.a.source_files[pos.id] or { return pos }
	source := tc.source_texts_by_file[file.name] or { return pos }
	start := int_min(int_max(pos.offset, 0), source.len)
	end := int_min(int_max(pos.end, start), source.len)
	if start < end {
		if relative := source[start..end].index('&') {
			return token.new_span(pos.id, start, start + relative + 1)
		}
	}
	return pos
}

fn (mut tc TypeChecker) infer_generic_struct_init_type(node flat.Node) ?Type {
	base_name := trimmed_space(node.value)
	if base_name.len == 0 || base_name.contains('[') {
		return none
	}
	params := tc.struct_generic_params[base_name] or {
		tc.struct_generic_params[tc.qualify_name(base_name)] or { return none }
	}
	if params.len == 0 {
		return none
	}
	inferred := tc.infer_generic_struct_init_param_texts(node, base_name, params)
	if inferred.len == 0 {
		return none
	}
	mut args := []string{cap: params.len}
	for param in params {
		arg := inferred[param] or { return none }
		args << arg
	}
	return tc.parse_type('${base_name}[${args.join(', ')}]')
}

fn (mut tc TypeChecker) infer_generic_struct_init_param_texts(node flat.Node, base_name string, params []string) map[string]string {
	init_name := tc.qualify_name(base_name)
	fields := tc.structs[init_name] or { tc.structs[base_name] or { return map[string]string{} } }
	source_fields := tc.source_struct_field_decls(init_name)
	mut inferred := map[string]string{}
	for param in params {
		if param in tc.fn_context.generic_params {
			inferred[param] = param
		}
	}
	for i in 0 .. node.children_count {
		field_node := tc.a.child_node(&node, i)
		if field_node.kind != .field_init || field_node.children_count == 0 {
			continue
		}
		value_id := tc.a.child(field_node, 0)
		mut field_type := Type(void_)
		mut field_type_text := ''
		if field_node.value.len > 0 {
			for field_idx, field in fields {
				if field.name == field_node.value {
					field_type = field.typ
					if field_idx < source_fields.len {
						field_type_text = source_fields[field_idx].typ
					}
					break
				}
			}
		} else if i < fields.len {
			field_type = fields[i].typ
			if i < source_fields.len {
				field_type_text = source_fields[i].typ
			}
		}
		if field_type is Void {
			continue
		}
		if field_type_text.len == 0 {
			field_type_text = field_type.name()
		}
		actual := tc.resolve_type(value_id)
		tc.infer_generic_type_text_from_type(field_type_text, actual, params, mut inferred)
	}
	return inferred
}

fn (tc &TypeChecker) source_struct_field_decls(struct_name string) []SourceStructFieldDecl {
	base_name, _, is_generic := generic_type_application_parts(struct_name)
	lookup := if is_generic { base_name } else { struct_name }
	mut candidates := []string{}
	push_type_name_candidate(mut candidates, lookup)
	push_type_name_candidate(mut candidates, lookup.all_after_last('.'))
	push_type_name_candidate(mut candidates, tc.qualify_name(lookup))
	mut wanted_file := ''
	for candidate in candidates {
		if file := tc.struct_files[candidate] {
			wanted_file = file
			break
		}
	}
	mut cur_file := ''
	mut cur_module := ''
	for idx in tc.top_level_idx {
		if idx < 0 || idx >= tc.a.nodes.len {
			continue
		}
		decl := tc.a.nodes[idx]
		match decl.kind {
			.file {
				cur_file = decl.value
			}
			.module_decl {
				cur_module = decl.value
			}
			.struct_decl {
				decl_qname := if cur_module.len > 0 && !decl.value.contains('.') {
					'${cur_module}.${decl.value}'
				} else {
					decl.value
				}
				if decl.value !in candidates && decl_qname !in candidates {
					continue
				}
				if wanted_file.len > 0 && cur_file.len > 0 && cur_file != wanted_file {
					continue
				}
				mut fields := []SourceStructFieldDecl{}
				for i in 0 .. decl.children_count {
					field := tc.a.child_node(&decl, i)
					if field.kind != .field_decl {
						continue
					}
					field_typ := if field.typ.len > 0 { field.typ } else { field.value }
					fields << SourceStructFieldDecl{
						name: field.value
						typ:  field_typ
					}
				}
				return fields
			}
			else {}
		}
	}
	return []SourceStructFieldDecl{}
}

// check_deferred_generic_receiver_comparisons checks pointer/value ordering
// mismatches in an open generic receiver method when a concrete receiver
// instance is known elsewhere in the selected source file.
fn (mut tc TypeChecker) check_deferred_generic_receiver_comparisons(node flat.Node) {
	if node.children_count == 0 {
		return
	}
	receiver := tc.a.child_node(&node, 0)
	if receiver.kind != .param || receiver.op != .dot {
		return
	}
	receiver_base, receiver_params, is_generic :=
		generic_type_application_parts(comptime_static_unwrap_type_text(receiver.typ))
	if !is_generic || receiver_params.len == 0 {
		return
	}
	mut param_types := map[string]string{}
	for i in 0 .. node.children_count {
		param := tc.a.child_node(&node, i)
		if param.kind == .param && param.value.len > 0 {
			param_types[param.value] = if param.is_mut && param.op != .amp
				&& param.typ.starts_with('&') {
				param.typ[1..]
			} else {
				param.typ
			}
		}
	}
	mut comparisons := []flat.NodeId{}
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		if tc.a.node(child_id).kind != .param {
			tc.collect_deferred_generic_pointer_comparisons(child_id, param_types, receiver_params, mut
				comparisons)
		}
	}
	if comparisons.len == 0 {
		return
	}
	concrete_args := tc.concrete_generic_receiver_args(receiver_base, receiver_params.len) or {
		return
	}
	for comparison_id in comparisons {
		comparison := tc.a.node(comparison_id)
		lhs_id := tc.a.child(comparison, 0)
		rhs_id := tc.a.child(comparison, 1)
		lhs_raw := tc.deferred_generic_expr_type_text(lhs_id, param_types)
		rhs_raw := tc.deferred_generic_expr_type_text(rhs_id, param_types)
		lhs := subst_generic_text(lhs_raw, concrete_args, receiver_params)
		rhs := subst_generic_text(rhs_raw, concrete_args, receiver_params)
		if !generic_pointer_value_mismatch(lhs, rhs) {
			continue
		}
		tc.record_error_at(.condition_mismatch, 'mismatched types `${lhs}` and `${rhs}`',
			comparison_id, comparison.pos)
	}
}

fn (tc &TypeChecker) collect_deferred_generic_pointer_comparisons(id flat.NodeId, param_types map[string]string, generic_params []string, mut comparisons []flat.NodeId) {
	if !tc.valid_node_id(id) {
		return
	}
	node := tc.a.node(id)
	if node.kind == .infix && node.op in [.lt, .gt, .le, .ge] && node.children_count >= 2 {
		lhs := tc.deferred_generic_expr_type_text(tc.a.child(node, 0), param_types)
		rhs := tc.deferred_generic_expr_type_text(tc.a.child(node, 1), param_types)
		if type_text_mentions_any_generic_param(lhs, generic_params)
			&& type_text_mentions_any_generic_param(rhs, generic_params)
			&& generic_pointer_value_mismatch(lhs, rhs) {
			comparisons << id
		}
	}
	for i in 0 .. node.children_count {
		tc.collect_deferred_generic_pointer_comparisons(tc.a.child(node, i), param_types,
			generic_params, mut comparisons)
	}
}

fn (tc &TypeChecker) deferred_generic_expr_type_text(id flat.NodeId, param_types map[string]string) string {
	if !tc.valid_node_id(id) {
		return ''
	}
	node := tc.a.node(id)
	match node.kind {
		.ident {
			return param_types[node.value] or { node.typ }
		}
		.paren {
			if node.children_count > 0 {
				return tc.deferred_generic_expr_type_text(tc.a.child(node, 0), param_types)
			}
		}
		.selector {
			if node.children_count == 0 {
				return node.typ
			}
			receiver_type := tc.deferred_generic_expr_type_text(tc.a.child(node, 0), param_types)
			base, args, is_generic :=
				generic_type_application_parts(comptime_static_unwrap_type_text(receiver_type))
			lookup := if is_generic { base } else { comptime_static_unwrap_type_text(receiver_type) }
			fields := tc.source_struct_field_decls(lookup)
			for field in fields {
				if field.name != node.value {
					continue
				}
				if is_generic {
					params := tc.struct_generic_params[base] or {
						tc.struct_generic_params[base.all_after_last('.')] or { []string{} }
					}
					if params.len == args.len && params.len > 0 {
						return subst_generic_text(field.typ, args, params)
					}
				}
				return field.typ
			}
		}
		.index {
			if node.children_count == 0 {
				return node.typ
			}
			container := tc.deferred_generic_expr_type_text(tc.a.child(node, 0), param_types)
			clean := trimmed_space(container)
			if clean.starts_with('[]') {
				return trimmed_space(clean[2..])
			}
			if clean.starts_with('[') {
				close := find_matching_bracket(clean, 0)
				if close > 0 && close + 1 < clean.len {
					return trimmed_space(clean[close + 1..])
				}
			}
		}
		else {}
	}
	return node.typ
}

fn (tc &TypeChecker) concrete_generic_receiver_args(receiver_base string, arg_count int) ?[]string {
	for node in tc.a.nodes {
		if node.kind != .call || node.children_count == 0 {
			continue
		}
		callee := tc.a.child_node(&node, 0)
		if callee.kind != .index || callee.children_count < 2 {
			continue
		}
		base_node := tc.a.child_node(callee, 0)
		fn_name := tc.generic_call_base_name(base_node) or { continue }
		call_args := tc.generic_call_type_arg_names(callee)
		fn_params := tc.fn_generic_params[fn_name] or { continue }
		if call_args.len == 0 || call_args.len != fn_params.len {
			continue
		}
		ret_text := tc.fn_ret_type_texts[fn_name] or { continue }
		ret_base, ret_args, is_generic :=
			generic_type_application_parts(comptime_static_unwrap_type_text(ret_text))
		if !is_generic || ret_args.len != arg_count
			|| ret_base.all_after_last('.') != receiver_base.all_after_last('.') {
			continue
		}
		mut concrete := []string{cap: ret_args.len}
		for ret_arg in ret_args {
			concrete << subst_generic_text(ret_arg, call_args, fn_params)
		}
		return concrete
	}
	return none
}

fn type_text_mentions_any_generic_param(typ string, params []string) bool {
	clean := trimmed_space(typ)
	for param in params {
		if clean == param || clean.starts_with('&${param}') || clean.ends_with('[${param}]')
			|| clean.contains('[${param},') || clean.contains(', ${param}]') {
			return true
		}
	}
	return false
}

fn generic_pointer_value_mismatch(lhs string, rhs string) bool {
	left := trimmed_space(lhs)
	right := trimmed_space(rhs)
	return (left.starts_with('&') && trimmed_space(left[1..]) == right)
		|| (right.starts_with('&') && left == trimmed_space(right[1..]))
}

// expr_is_method_value reports whether `id` is a selector that resolves to a *method
// value* — a struct/interface method used as a value (`obj.draw`), not a field access or a method
// call. cgen backs such values with per-instance closure contexts.
pub fn (tc &TypeChecker) expr_is_method_value(id flat.NodeId) bool {
	if int(id) < 0 {
		return false
	}
	node := tc.a.nodes[int(id)]
	// A local bound to a method value (`cb := c.report`) must remain identifiable so
	// mutable-receiver escape checks can follow aliases of the bare selector.
	if node.kind == .ident {
		return tc.current_binding_is_method_value_local(node.value)
	}
	if node.kind != .selector || node.children_count == 0 {
		return false
	}
	receiver := unwrap_pointer(tc.resolve_type(tc.a.child(&node, 0)))
	clean := unalias_type(receiver)
	if receiver is Alias {
		underlying := unalias_type(receiver)
		if underlying is Struct && tc.struct_field_type(underlying.name, node.value) != none {
			return false
		}
		if _ := tc.alias_method_value_decl_key(receiver, node.value) {
			return true
		}
	} else if clean is Struct {
		sname := clean.name
		if tc.struct_field_type(sname, node.value) != none {
			return false
		}
		if '${sname}.${node.value}' in tc.fn_param_types {
			return true
		}
		if receiver is Alias && '${receiver.name}.${node.value}' in tc.fn_param_types {
			return true
		}
		if _ := tc.resolve_generic_struct_method(sname, node.value) {
			return true
		}
	} else if clean is Interface {
		iname := clean.name
		if tc.interface_field_type(iname, node.value) != none {
			return false
		}
		if receiver is Alias && '${receiver.name}.${node.value}' in tc.fn_param_types {
			return true
		}
		if _ := tc.interface_receiver_method_call_info(iname, node.value) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) alias_method_value_decl_key(alias Alias, method string) ?string {
	for receiver in [Type(alias), alias.base_type] {
		for candidate in receiver_method_name_candidates(receiver, method, tc.cur_module) {
			if candidate in tc.fn_param_types || candidate in tc.fn_ret_types {
				return candidate
			}
		}
		type_name := resolve_type_name_for_method(receiver)
		if type_name.len > 0 {
			if info := tc.resolve_generic_struct_method(type_name, method) {
				return info.name
			}
		}
	}
	return none
}

fn (tc &TypeChecker) method_value_has_stack_mut_receiver(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind in [.paren, .cast_expr, .expr_stmt] && node.children_count == 1 {
		return tc.method_value_has_stack_mut_receiver(tc.a.child(&node, 0))
	}
	if node.kind == .ident {
		return tc.current_method_value_local_has_stack_mut_receiver(node.value)
	}
	if node.kind != .selector || node.children_count == 0 || !tc.expr_is_method_value(id) {
		return false
	}
	base_id := tc.a.child(&node, 0)
	base_type := tc.cached_expr_type(base_id) or { tc.resolve_type(base_id) }
	// A pointer receiver already has caller-managed storage. A non-addressable
	// rvalue is copied into the per-instance closure context by cgen.
	if tc.type_is_pointer_receiver(base_type) || !tc.expr_can_take_address(base_id)
		|| tc.expr_root_is_global_binding(base_id) {
		return false
	}
	clean := unwrap_all_pointers(base_type)
	type_name := resolve_type_name_for_method(clean)
	if type_name.len == 0 {
		return false
	}
	if info := tc.resolve_generic_struct_method(type_name, node.value) {
		if tc.mut_receiver_methods[info.name] {
			return true
		}
	}
	for method_name in receiver_method_name_candidates(clean, node.value, tc.cur_module) {
		if tc.mut_receiver_methods[method_name] {
			return true
		}
	}
	return false
}

// reject_stored_method_value rejects the remaining unsafe method-value escape:
// a mutable pointer receiver bound to addressable stack storage. Cgen must borrow
// that local for in-scope calls, but the borrow would dangle after a return/store.
// Per-instance contexts make value receivers, pointer receivers, and copied
// non-addressable rvalues safe to store.
fn (mut tc TypeChecker) reject_stored_method_value(id flat.NodeId) {
	if tc.method_value_has_stack_mut_receiver(id) && tc.should_diagnose(id) {
		tc.record_error(.assignment_mismatch,
			'a method value with a mutable local receiver cannot escape its call site', id)
	}
}

fn (tc &TypeChecker) struct_literal_unknown_field_message(struct_name string, field_name string, fields []StructField) string {
	display_name := struct_name.all_after_last('.')
	base := 'unknown field `${field_name}` in struct literal of type `${display_name}`'
	mut candidates := []string{}
	for field in fields {
		if field.name.len > 0 && field.name !in candidates {
			candidates << field.name
		}
	}
	suggested := util.new_suggestion(field_name, candidates).say(base)
	if suggested != base {
		return suggested
	}
	if candidates.len == 0 {
		return base
	}
	grammar := if candidates.len == 1 { 'possibility' } else { 'possibilities' }
	quoted := candidates.map('`${it}`')
	return '${base}.\n${candidates.len} ${grammar}: ${quoted.join(', ')}.'
}

fn (tc &TypeChecker) stored_method_value_matches_voidptr_callback(id flat.NodeId, expected Type) bool {
	if !tc.expr_is_method_value(id) {
		return false
	}
	actual := tc.resolve_type(id)
	return tc.method_value_matches_voidptr_callback(id, actual, expected)
}

fn (tc &TypeChecker) method_value_matches_voidptr_callback(id flat.NodeId, actual Type, expected Type) bool {
	if !tc.expr_is_method_value(id) {
		return false
	}
	actual_fn := fn_type_from_type(actual) or { return false }
	expected_fn := fn_type_from_type(expected) or { return false }
	if expected_fn.params.len != actual_fn.params.len + 1 {
		return false
	}
	if expected_fn.params.len == 0 || !fn_param_is_voidptr_type(expected_fn.params[0]) {
		return false
	}
	for i in 0 .. actual_fn.params.len {
		if !tc.fn_param_compatible(fn_param_type(actual_fn, i), fn_param_type(expected_fn, i + 1)) {
			return false
		}
	}
	return tc.fn_return_compatible(actual_fn.return_type, expected_fn.return_type)
}

fn (tc &TypeChecker) expr_is_capturing_fn_literal_value(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			return tc.ident_is_capturing_fn_literal_alias(node.value)
		}
		.fn_literal {
			return tc.fn_literal_has_captures(node)
		}
		.cast_expr, .paren, .expr_stmt {
			if node.children_count == 0 {
				return false
			}
			return tc.expr_is_capturing_fn_literal_value(tc.a.child(&node, 0))
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) ident_is_capturing_fn_literal_alias(name string) bool {
	binding_key := tc.visible_binding_storage_key(name) or { return false }
	return tc.capturing_fn_literal_locals[binding_key]
}

fn (tc &TypeChecker) visible_binding_storage_key(name string) ?string {
	if tc.cur_scope == unsafe { nil } {
		return none
	}
	owner := tc.cur_scope.lookup_owner(name) or { return none }
	binding_key := owner.storage_key()
	if binding_key.len == 0 {
		return none
	}
	return binding_key
}

fn (tc &TypeChecker) expr_is_unsupported_returned_capturing_fn_literal_value(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			return tc.ident_is_unsupported_returned_capturing_fn_literal_alias(node.value)
		}
		.fn_literal {
			return tc.fn_literal_has_unsupported_return_capture(node)
		}
		.cast_expr, .paren, .expr_stmt {
			if node.children_count == 0 {
				return false
			}
			return tc.expr_is_unsupported_returned_capturing_fn_literal_value(tc.a.child(&node, 0))
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) ident_is_unsupported_returned_capturing_fn_literal_alias(name string) bool {
	binding_key := tc.visible_binding_storage_key(name) or { return false }
	if !tc.capturing_fn_literal_locals[binding_key] {
		return false
	}
	return tc.capturing_fn_literal_return_unsupported[binding_key] or { true }
}

fn (tc &TypeChecker) fn_literal_has_captures(node flat.Node) bool {
	if node.kind != .fn_literal {
		return false
	}
	for i in 0 .. node.children_count {
		child := tc.a.child_node(&node, i)
		if child.kind == .ident && child.value.len > 0 {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) fn_literal_has_unsupported_return_capture(node flat.Node) bool {
	if node.kind != .fn_literal {
		return false
	}
	for i in 0 .. node.children_count {
		child := tc.a.child_node(&node, i)
		if child.kind == .ident && child.value.len > 0
			&& !tc.fn_literal_return_capture_is_supported(child) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) fn_literal_return_capture_is_supported(capture flat.Node) bool {
	if !capture.is_mut || capture.value.len == 0 {
		return false
	}
	if typ := tc.cur_scope.lookup(capture.value) {
		return unalias_type(typ) is Pointer
	}
	return false
}

fn (mut tc TypeChecker) reject_returned_capturing_fn_literal(id flat.NodeId) {
	_ = tc
	_ = id
}

fn (mut tc TypeChecker) reject_stored_capturing_fn_literal(id flat.NodeId) {
	tc.reject_capturing_fn_literal_escape(id,
		'capturing fn literal cannot be stored in a container')
}

fn (mut tc TypeChecker) reject_stored_or_returned_capturing_fn_literal(id flat.NodeId) {
	tc.reject_capturing_fn_literal_escape(id, 'capturing fn literal cannot be stored or returned')
}

fn (mut tc TypeChecker) reject_capturing_fn_literal_escape(id flat.NodeId, message string) {
	_ = tc
	_ = id
	_ = message
}

// check_selector validates check selector state for types.
fn (mut tc TypeChecker) check_selector(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	if node.value == '$' {
		tc.check_comptime_field_selector(id, node, '', ComptimeStaticFieldCases{})
		return
	}
	base_id := tc.a.child(&node, 0)
	base := tc.a.nodes[int(base_id)]
	if base.kind == .selector && base.children_count > 0 {
		module_node := tc.a.child_node(&base, 0)
		if module_node.kind == .ident && tc.has_active_import(module_node.value)
			&& base.value.len > 0 && base.value[0].is_capital() {
			module_name := tc.resolve_import_alias(module_node.value) or { module_node.value }
			display_module_name := tc.current_file_import_path_for_alias(module_node.value) or {
				module_name
			}
			enum_name := '${display_module_name}.${base.value}'
			if resolved_enum_name := tc.resolve_enum_name(enum_name) {
				tc.register_synth_type(base_id, Type(Enum{
					name:    resolved_enum_name
					is_flag: resolved_enum_name in tc.flag_enums
				}))
				if _ := tc.private_declaration(enum_name) {
					start_pos := tc.node_value_diagnostic_pos(base_id)
					tc.record_error_at(.unknown_type, 'enum `${enum_name}` is private', id, token.new_span(node.pos.id,
						start_pos.offset, node.pos.end))
				}
			} else {
				start_pos := tc.node_value_diagnostic_pos(base_id)
				tc.record_error_at(.unknown_type, 'unknown enum `${enum_name}` (type_idx=0)', id, token.new_span(node.pos.id,
					start_pos.offset, node.pos.end))
				tc.register_synth_type(id, Type(void_))
				return
			}
		}
	}
	if base.kind == .prefix && base.op == .amp && base.children_count > 0 {
		addressed := tc.a.child_node(&base, 0)
		if addressed.kind == .struct_init {
			tc.check_node(base_id)
			tc.record_error_at(.assignment_mismatch,
				'should not create object instance on the heap to simply access a member', id, token.new_span(node.pos.id,
				base.pos.offset, node.pos.end))
			return
		}
	}
	if tc.is_namespace_selector(node, base) {
		module_name := tc.resolve_import_alias(base.value) or { base.value }
		display_module_name := tc.current_file_import_path_for_alias(base.value) or { module_name }
		semantic_type_name := '${module_name}.${node.value}'
		display_type_name := '${display_module_name}.${node.value}'
		mut is_known_type := tc.type_name_known(semantic_type_name)
		if !is_known_type {
			for candidate in [
				'${base.value}.${node.value}',
				'${display_module_name.all_after_last('.')}.${node.value}',
			] {
				if tc.type_symbol_known(candidate) {
					is_known_type = true
					break
				}
			}
		}
		if node.value.len > 0 && node.value[0].is_capital() && is_known_type {
			tc.record_error_at(.assignment_mismatch, '`${display_type_name}` must be initialized',
				id, tc.node_value_diagnostic_pos(id))
			tc.register_synth_type(id, Type(void_))
			return
		}
		if node.value.len > 0 && node.value[0].is_capital() {
			if enum_name := tc.resolve_enum_name('${display_module_name}.${node.value}') {
				tc.register_synth_type(id, Type(Enum{
					name:    enum_name
					is_flag: enum_name in tc.flag_enums
				}))
				return
			}
		}
		if deprecation := tc.deprecated_symbols['${module_name}.${node.value}'] {
			tc.record_deprecation(id, 'const', deprecation, tc.node_value_diagnostic_pos(id))
		}
		if key := tc.selector_fn_value_key(node) {
			if typ := tc.fn_type_from_key(key) {
				tc.register_synth_type(id, typ)
			}
		}
		if typ := tc.enum_selector_type(&node) {
			tc.register_synth_type(id, typ)
		}
		if typ := tc.const_type_for_selector(node) {
			qname := '${display_module_name}.${node.value}'
			if _ := tc.private_declaration(qname) {
				tc.record_error_at(.unknown_type, 'constant `${qname}` is private', id,
					tc.node_value_diagnostic_pos(id))
			}
			tc.register_synth_type(id, typ)
			return
		}
		if tc.unknown_import_selector(node) {
			mut candidates := []string{}
			prefix := '${module_name}.'
			for name, _ in tc.const_types {
				if name.starts_with(prefix) {
					candidates << name
				}
			}
			name := '${module_name}.${node.value}'
			message := util.new_suggestion(name, candidates).say('undefined ident: `${name}`')
			tc.record_error_at(.unknown_ident, message, id, tc.node_value_diagnostic_pos(id))
			tc.register_synth_type(id, Type(void_))
		}
		return
	}
	tc.check_storage_path_base_node(base_id)
	mut base_type := tc.smartcast_type(base_id) or { tc.resolve_type(base_id) }
	if base.kind == .ident {
		if mut_base := tc.mut_param_base_for_current_ident(base.value, base_type) {
			base_type = mut_base
		}
	}
	tc.register_synth_type(base_id, base_type)
	if base_type is Void {
		tc.record_error_at(.unknown_field,
			'`${tc.source_text_for_node(base_id)}` does not return a value', id,
			tc.node_value_diagnostic_pos(id))
		tc.record_enclosing_print_void(id)
		tc.register_synth_type(id, Type(void_))
		return
	}
	if base_type is OptionType && node.value !in ['ok', 'value'] {
		tc.record_error_at(.unknown_field,
			'cannot access fields of an Option, handle the error with `or {...}` or propagate it with `?`',
			id, tc.node_value_diagnostic_pos(id))
		tc.register_synth_type(id, Type(void_))
		return
	}
	if smart_type := tc.smartcast_type(id) {
		tc.register_synth_type(id, smart_type)
		return
	}
	if tc.expr_is_method_value(id) && !tc.ident_is_call_callee_or_generic_base(id) {
		receiver := unwrap_pointer(base_type)
		mut generic_method_key := ''
		if receiver is Alias {
			generic_method_key = tc.alias_method_value_decl_key(receiver, node.value) or { '' }
		} else {
			clean_receiver := unalias_type(receiver)
			if clean_receiver is Struct {
				direct_key := '${clean_receiver.name}.${node.value}'
				if direct_key in tc.fn_generic_params {
					generic_method_key = direct_key
				} else if info := tc.resolve_generic_struct_method(clean_receiver.name, node.value) {
					generic_method_key = info.name
				}
			}
		}
		if generic_method_key.len > 0
			&& (tc.fn_generic_params[generic_method_key] or { []string{} }).len > 0 {
			tc.record_error_at(.unsupported_generic,
				'cannot use `${tc.source_text_for_node(id)}` as a generic function value', id,
				tc.node_value_diagnostic_pos(id))
			tc.register_synth_type(id, tc.fn_type_from_key(generic_method_key) or { Type(void_) })
			return
		}
	}
	// A value-context selector whose name is a method (not a field) of a struct
	// receiver is a method value; record the concrete `Type.method` so it survives
	// dead-code elimination (cgen emits a wrapper that calls it).
	clean_recv := unwrap_pointer(base_type)
	if clean_recv is Struct {
		if deprecation := tc.deprecated_symbols['${clean_recv.name}.${node.value}'] {
			tc.record_deprecation(id, 'field', deprecation, tc.node_value_diagnostic_pos(id))
		}
		field_candidates := tc.embedded_field_candidates(clean_recv.name, node.value)
		if field_candidates.len > 1 {
			pos := tc.node_value_diagnostic_pos(id)
			tc.record_error_at(.unknown_field, 'ambiguous field `${node.value}`', id, pos)
			mut possibilities := field_candidates.clone()
			possibilities.reverse_in_place()
			quoted_possibilities := possibilities.map('`${it}`')
			tc.record_error_at(.unknown_field,
				'type `${clean_recv.name}` has no field named `${node.value}`.\n${possibilities.len} possibilities: ${quoted_possibilities.join(', ')}.',
				id, pos)
			tc.register_synth_type(id, Type(void_))
			return
		}
		if tc.struct_field_type(clean_recv.name, node.value) == none {
			mut mkey := '${clean_recv.name}.${node.value}'
			mut is_generic_method_value := false
			if mkey !in tc.fn_param_types {
				// Generic receiver methods are registered under the open key
				// (`Box[T].method`); mark that one reachable for the wrapper, and stash
				// the substituted signature for cgen (the open form is gone by cgen time).
				if ci := tc.resolve_generic_struct_method(clean_recv.name, node.value) {
					tc.generic_method_value_info['${clean_recv.name}.${node.value}'] = ci
					mkey = ci.name
					is_generic_method_value = true
				}
			}
			if (mkey in tc.fn_param_types || is_generic_method_value) && tc.fn_context.node_id >= 0 {
				// Record per enclosing function so markused marks it only when that
				// function is reachable; over-marking an unreachable method value can pull
				// in (and fail to compile) an otherwise-unused specialization. A method
				// value can only appear inside a function body — escaping to a const/global
				// is rejected elsewhere — so a non-fn context needs no recording here.
				tc.method_values_by_fn[tc.fn_context.node_id] << mkey
				// Also record the concrete instance key (`Box[int].report`) — distinct from the
				// open key (`Box[T].report`) above — so monomorphize can gate a generic method's
				// specialization on *this* instance's method value being reachable (it shares the
				// open key with every other instance, e.g. `Box[Pair]`).
				concrete_mkey := '${clean_recv.name}.${node.value}'
				if concrete_mkey != mkey {
					tc.method_values_by_fn[tc.fn_context.node_id] << concrete_mkey
				}
			}
		}
	} else if clean_recv is Alias {
		underlying := unalias_type(clean_recv)
		has_field := underlying is Struct
			&& tc.struct_field_type(underlying.name, node.value) != none
		if !has_field && tc.fn_context.node_id >= 0 {
			if mkey := tc.alias_method_value_decl_key(clean_recv, node.value) {
				tc.method_values_by_fn[tc.fn_context.node_id] << mkey
			}
		}
	} else if clean_recv is Interface {
		if tc.interface_field_type(clean_recv.name, node.value) == none
			&& tc.fn_context.node_id >= 0 {
			if _ := tc.interface_receiver_method_call_info(clean_recv.name, node.value) {
				tc.method_values_by_fn[tc.fn_context.node_id] << '${clean_recv.name}.${node.value}'
			}
		}
	}
	if typ := tc.selector_type(id, node) {
		tc.register_synth_type(id, typ)
		return
	} else {
		if tc.should_diagnose(id) {
			if base_type is Unknown {
				return
			}
			clean_base := unalias_type(unwrap_pointer(base_type))
			if clean_base is Interface {
				tc.record_error_at(.unknown_field,
					'type `${clean_base.name}` has no field named `${node.value}`', id,
					tc.node_value_diagnostic_pos(id))
			} else if clean_base is Struct {
				if tc.ident_is_multi_pattern_match_subject(base_id) {
					tc.record_error_at(.unknown_field,
						'type `${clean_base.name}` has no field or method `${node.value}`', id,
						tc.node_value_diagnostic_pos(id))
					tc.register_synth_type(id, Type(void_))
					return
				}
				mut candidates := []string{}
				for field in tc.struct_fields_for_init(clean_base.name) {
					if field.name.len > 0 && field.name !in candidates {
						candidates << field.name
					}
				}
				message :=
					util.new_suggestion(node.value, candidates).say('type `${clean_base.name}` has no field named `${node.value}`')
				tc.record_error_at(.unknown_field, message, id, tc.node_value_diagnostic_pos(id))
			} else {
				tc.record_error_at(.unknown_field,
					'`${base_type.name()}` has no property `${node.value}`', id,
					tc.node_value_diagnostic_pos(id))
			}
		}
		tc.register_synth_type(id, Type(void_))
	}
}

fn (tc &TypeChecker) ident_is_multi_pattern_match_subject(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	ident := tc.a.node(id)
	if ident.kind != .ident {
		return false
	}
	mut current := id
	for _ in 0 .. 32 {
		parent_id := tc.direct_parent_id(current)
		if !tc.valid_node_id(parent_id) {
			return false
		}
		parent := tc.a.node(parent_id)
		if parent.kind == .match_branch {
			if parent.value == 'else' || parent.value.int() < 2 {
				return false
			}
			match_id := tc.direct_parent_id(parent_id)
			if !tc.valid_node_id(match_id) {
				return false
			}
			match_node := tc.a.node(match_id)
			if match_node.kind != .match_stmt || match_node.children_count == 0 {
				return false
			}
			subject := tc.a.child_node(match_node, 0)
			return subject.kind == .ident && subject.value == ident.value
		}
		if parent.kind in [.fn_decl, .fn_literal, .lambda_expr] {
			return false
		}
		current = parent_id
	}
	return false
}

fn (tc &TypeChecker) current_fn_has_invalid_defer_mode() bool {
	fn_id := flat.NodeId(tc.fn_context.node_id)
	if !tc.valid_node_id(fn_id) {
		return false
	}
	fn_node := tc.a.node(fn_id)
	mut stack := []flat.NodeId{}
	for i in 0 .. fn_node.children_count {
		stack << tc.a.child(fn_node, i)
	}
	for stack.len > 0 {
		id := stack.pop()
		node := tc.a.node(id)
		if node.kind == .defer_stmt && node.value.starts_with('invalid:') {
			return true
		}
		for i in 0 .. node.children_count {
			stack << tc.a.child(node, i)
		}
	}
	return false
}

fn (tc &TypeChecker) string_interpolation_recurses_str(expr_type Type) bool {
	fn_id := flat.NodeId(tc.fn_context.node_id)
	if !tc.valid_node_id(fn_id) {
		return false
	}
	fn_node := tc.a.node(fn_id)
	if !fn_node.value.ends_with('.str') {
		return false
	}
	for i in 0 .. fn_node.children_count {
		param := tc.a.child_node(fn_node, i)
		if param.kind != .param || param.op != .dot {
			continue
		}
		receiver_type := unalias_type(unwrap_pointer(tc.parse_type(param.typ)))
		interpolation_type := unalias_type(unwrap_pointer(expr_type))
		return receiver_type.name() == interpolation_type.name()
	}
	return false
}

fn (tc &TypeChecker) current_fn_is_specialized_generic() bool {
	fn_id := tc.fn_context.node_id
	return fn_id >= 0
		&& ((fn_id < tc.a.specialized_fn_nodes.len && tc.a.specialized_fn_nodes[fn_id])
		|| (fn_id < tc.a.nodes.len && tc.specialized_generic_fns[tc.a.nodes[fn_id].value]))
}

fn (mut tc TypeChecker) record_enclosing_print_void(id flat.NodeId) {
	mut current := id
	for _ in 0 .. 4 {
		parent_id := tc.direct_parent_id(current)
		if !tc.valid_node_id(parent_id) {
			return
		}
		parent := tc.a.node(parent_id)
		if parent.kind == .call && parent.children_count > 0 {
			callee := tc.a.child_node(parent, 0)
			if callee.kind == .ident && callee.value in ['print', 'println', 'eprint', 'eprintln'] {
				tc.record_error(.call_arg_mismatch,
					'`${callee.value}` can not print void expressions', parent_id)
			}
			return
		}
		current = parent_id
	}
}

fn (mut tc TypeChecker) record_enclosing_dump_void(id flat.NodeId) {
	parent_id := tc.direct_parent_id(id)
	if tc.valid_node_id(parent_id) && tc.a.node(parent_id).kind == .dump_expr {
		node := tc.a.node(id)
		if node.kind == .call && node.children_count > 0 {
			callee := tc.a.child_node(node, 0)
			if callee.kind == .selector {
				tc.record_error_at(.assignment_mismatch, 'dump expression can not be void', id, tc.method_call_name_pos(node,
					callee))
				return
			}
		}
		tc.record_error(.assignment_mismatch, 'dump expression can not be void', id)
	}
}

fn (tc &TypeChecker) defer_mode_diagnostic_pos(node flat.Node, mode string) token.Pos {
	file := tc.a.source_files[node.pos.id] or { return node.pos }
	source := tc.source_texts_by_file[file.name] or { return node.pos }
	start := int_max(0, node.pos.offset)
	end := int_min(source.len, node.pos.end)
	if relative := source[start..end].index('(${mode})') {
		mode_start := start + relative + 1
		return token.new_span(node.pos.id, mode_start, mode_start + mode.len)
	}
	return node.pos
}

fn (tc &TypeChecker) invalid_interface_selector_print_arg(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind != .selector || node.children_count == 0 {
		return false
	}
	base_type := unalias_type(unwrap_pointer(tc.resolve_type(tc.a.child(node, 0))))
	return base_type is Interface && tc.selector_type(id, node) == none
}

fn (tc &TypeChecker) invalid_struct_selector_print_arg(id flat.NodeId) bool {
	if !tc.valid_node_id(id) {
		return false
	}
	node := tc.a.node(id)
	if node.kind != .selector || node.children_count == 0 {
		return false
	}
	base_type := unalias_type(unwrap_pointer(tc.resolve_type(tc.a.child(node, 0))))
	return base_type is Struct && tc.selector_type(id, node) == none
}

fn (tc &TypeChecker) unknown_import_selector(node flat.Node) bool {
	if node.kind != .selector || node.children_count == 0 {
		return false
	}
	base := tc.a.child_node(&node, 0)
	return base.kind == .ident && tc.has_active_import(base.value)
		&& tc.const_type_for_selector(node) == none && tc.selector_fn_value_key(node) == none
		&& tc.enum_selector_type(&node) == none
}

fn (tc &TypeChecker) embedded_method_candidates(struct_name string, method string) []string {
	mut candidates := []string{}
	mut seen := map[string]bool{}
	tc.collect_embedded_method_candidates(struct_name, method, mut candidates, mut seen)
	return candidates
}

fn (tc &TypeChecker) collect_embedded_method_candidates(struct_name string, method string, mut candidates []string,
	mut seen map[string]bool) {
	if struct_name in seen {
		return
	}
	seen[struct_name] = true
	for field in tc.structs[struct_name] or { []StructField{} } {
		embedded_type := embedded_field_type(field) or { continue }
		receiver := method_type_name(unwrap_pointer(embedded_type))
		if receiver.len == 0 {
			continue
		}
		if '${receiver}.${method}' in tc.fn_ret_types && receiver !in candidates {
			candidates << receiver
		}
		tc.collect_embedded_method_candidates(receiver, method, mut candidates, mut seen)
	}
}

fn (tc &TypeChecker) embedded_field_candidates(struct_name string, field_name string) []string {
	mut candidates := []string{}
	mut seen := map[string]bool{}
	tc.collect_embedded_field_candidates(struct_name, field_name, mut candidates, mut seen)
	return candidates
}

fn (tc &TypeChecker) collect_embedded_field_candidates(struct_name string, field_name string, mut candidates []string,
	mut seen map[string]bool) {
	if struct_name in seen {
		return
	}
	seen[struct_name] = true
	for field in tc.structs[struct_name] or { []StructField{} } {
		embedded_type := embedded_field_type(field) or { continue }
		receiver := method_type_name(unwrap_pointer(embedded_type))
		if receiver.len == 0 {
			continue
		}
		for embedded_field in tc.structs[receiver] or { []StructField{} } {
			if embedded_field.name == field_name && embedded_field_type(embedded_field) == none
				&& receiver !in candidates {
				candidates << receiver
				break
			}
		}
		tc.collect_embedded_field_candidates(receiver, field_name, mut candidates, mut seen)
	}
}

// is_namespace_selector reports whether is namespace selector applies in types.
fn (tc &TypeChecker) is_namespace_selector(node flat.Node, base flat.Node) bool {
	if base.kind != .ident {
		return false
	}
	if base.value == 'C' || tc.has_active_import(base.value) {
		return true
	}
	if base.value == 'main' || base.value == tc.cur_module {
		if node.value in tc.const_types || '${base.value}.${node.value}' in tc.const_types {
			return true
		}
	}
	if resolved := tc.resolve_selective_import_type_symbol(base.value) {
		if resolved in tc.structs || resolved in tc.enum_names || resolved in tc.flag_enums
			|| resolved in tc.sum_types || resolved in tc.interface_names {
			return true
		}
	}
	qbase := tc.qualify_name(base.value)
	if qbase in tc.structs || qbase in tc.enum_names || qbase in tc.sum_types
		|| qbase in tc.interface_names || qbase in tc.type_aliases {
		return true
	}
	// An alias of an enum (`type Col = Color`) is a namespace for its members: `Col.member`.
	if _ := tc.resolve_enum_name(base.value) {
		return true
	}
	if _ := tc.static_assoc_fn_key_for_base(base.value, node.value) {
		return true
	}
	qname := '${qbase}.${node.value}'
	return qname in tc.const_types || qname in tc.fn_ret_types || qname in tc.enum_names
}

// selector_type supports selector type handling for TypeChecker.
fn (tc &TypeChecker) selector_type(_id flat.NodeId, node flat.Node) ?Type {
	if node.children_count == 0 {
		return none
	}
	if typ := tc.enum_selector_type(&node) {
		return typ
	}
	base_id := tc.a.child(&node, 0)
	base_node := tc.a.nodes[int(base_id)]
	if base_node.kind == .typeof_expr {
		if node.value == 'name' {
			return Type(String{})
		}
		if node.value == 'idx' {
			return Type(int_)
		}
		if node.value == 'indirections' {
			return Type(u8_)
		}
	}
	mut base_type := tc.smartcast_type(base_id) or { tc.resolve_type(base_id) }
	if base_node.kind == .ident {
		if mut_base := tc.mut_param_base_for_current_ident(base_node.value, base_type) {
			base_type = mut_base
		}
	}
	clean0 := unwrap_pointer(base_type)
	mut alias_receiver_name := ''
	if clean0 is Alias {
		alias_receiver_name = clean0.name
	}
	clean := unalias_and_unwrap_pointer_type(base_type)
	clean_name := clean.name()
	if typ := option_result_selector_type(clean, node.value) {
		return typ
	}
	if node.value == 'len' {
		if clean is Array || clean is Map || clean is String || clean is ArrayFixed {
			return Type(int_)
		}
	}
	if clean is Channel && node.value == 'closed' {
		return Type(bool_)
	}
	if clean is Channel && node.value in ['len', 'cap'] {
		return Type(int_)
	}
	if clean is Struct {
		if typ := tc.struct_field_type(clean_name, node.value) {
			return typ
		}
		if typ := tc.method_value_type(clean_name, node.value) {
			return typ
		}
	}
	if base_node.kind == .string_literal {
		method_name := 'string.${node.value}'
		if method_name in tc.fn_param_types || method_name in tc.fn_ret_types {
			return tc.method_value_type('string', node.value)
		}
	}
	if typ := tc.builtin_method_value_type(base_type, node.value) {
		return typ
	}
	if alias_receiver_name.len > 0 {
		if typ := tc.method_value_type(alias_receiver_name, node.value) {
			return typ
		}
	}
	if clean is Interface {
		if typ := tc.interface_field_type(clean.name, node.value) {
			return typ
		}
		if typ := tc.method_value_type(clean.name, node.value) {
			return typ
		}
	}
	if clean is MultiReturn {
		if typ := multi_return_selector_type(clean, node.value) {
			return typ
		}
	}
	if is_builtin_ierror_name(clean_name) {
		if node.value == 'message' {
			return Type(String{})
		}
		if node.value == '_object' {
			return tc.parse_type('voidptr')
		}
	}
	if clean is SumType {
		if typ := tc.lowered_sum_selector_type(clean, node.value) {
			return typ
		}
		if base_node.kind == .index {
			if typ := tc.sum_unique_variant_field_type(clean, node.value) {
				return typ
			}
		}
		if typ := tc.sum_shared_field_type(clean, node.value) {
			return typ
		}
	}
	if clean is Array || clean is Map || clean is String {
		sname := if clean is Array {
			'array'
		} else if clean is Map {
			'map'
		} else {
			'string'
		}
		if fields := tc.structs[sname] {
			for f in fields {
				if f.name == node.value {
					return f.typ
				}
			}
		}
	}
	return none
}

// multi_return_selector_type supports multi return selector type handling for types.
fn multi_return_selector_type(typ MultiReturn, field string) ?Type {
	if !field.starts_with('arg') || field.len <= 3 {
		return none
	}
	idx_str := field[3..]
	idx := idx_str.int()
	if idx_str != idx.str() || idx < 0 || idx >= typ.types.len {
		return none
	}
	return typ.types[idx]
}

// lowered_sum_selector_type supports lowered sum selector type handling for TypeChecker.
fn (tc &TypeChecker) lowered_sum_selector_type(sum SumType, field string) ?Type {
	if field == 'typ' {
		return Type(int_)
	}
	variants := tc.sum_types[sum.name] or { return none }
	for variant in variants {
		short := if variant.contains('.') { variant.all_after_last('.') } else { variant }
		if field == variant || field == short || field == tc.cached_c_name(variant) {
			return tc.parse_type(variant)
		}
	}
	return none
}

// sum_shared_field_type supports sum shared field type handling for TypeChecker.
fn (tc &TypeChecker) sum_shared_field_type(sum SumType, field string) ?Type {
	mut visited := map[string]bool{}
	return tc.sum_shared_field_type_inner(sum.name, field, mut visited)
}

fn (tc &TypeChecker) sum_shared_field_type_inner(sum_name string, field string, mut visited map[string]bool) ?Type {
	base := tc.sum_base_name(sum_name)
	if visited[base] {
		return none
	}
	visited[base] = true
	defer {
		visited.delete(base)
	}
	variants := tc.sum_types[base] or { return none }
	if variants.len == 0 {
		return none
	}
	mut has_common := false
	mut common_typ := Type(void_)
	for variant in variants {
		concrete := tc.concrete_sum_variant_name(sum_name, variant)
		variant_type := tc.parse_type(concrete)
		variant_field := if variant_type is SumType {
			tc.sum_shared_field_type_inner(variant_type.name, field, mut visited) or { return none }
		} else {
			tc.struct_field_type(concrete, field) or { return none }
		}
		if !has_common {
			common_typ = variant_field
			has_common = true
			continue
		}
		if !tc.type_compatible(variant_field, common_typ)
			|| !tc.type_compatible(common_typ, variant_field) {
			return none
		}
	}
	return common_typ
}

fn (tc &TypeChecker) sum_unique_variant_field_type(sum SumType, field string) ?Type {
	mut visited := map[string]bool{}
	return tc.sum_unique_variant_field_type_inner(sum.name, field, mut visited)
}

fn (tc &TypeChecker) sum_unique_variant_field_type_inner(sum_name string, field string, mut visited map[string]bool) ?Type {
	base := tc.sum_base_name(sum_name)
	if visited[base] {
		return none
	}
	visited[base] = true
	defer {
		visited.delete(base)
	}
	variants := tc.sum_types[base] or { return none }
	mut found := Type(void_)
	mut found_count := 0
	for variant in variants {
		concrete := tc.concrete_sum_variant_name(sum_name, variant)
		variant_field := tc.struct_field_type(concrete, field) or { continue }
		found = variant_field
		found_count++
		if found_count > 1 {
			return none
		}
	}
	if found_count == 1 {
		return found
	}
	return none
}

// option_result_selector_type supports option result selector type handling for types.
fn option_result_selector_type(typ Type, field string) ?Type {
	if typ is OptionType {
		if field == 'ok' {
			return Type(bool_)
		}
		if field == 'value' {
			return typ.base_type
		}
	}
	if typ is ResultType {
		if field == 'ok' {
			return Type(bool_)
		}
		if field == 'value' {
			return typ.base_type
		}
	}
	return none
}

pub fn (tc &TypeChecker) index_operator_call_info(base_type Type, op string) ?CallInfo {
	clean := unwrap_pointer(base_type)
	type_name := resolve_type_name_for_method(clean)
	if type_name.len == 0 {
		return none
	}
	if info := tc.resolve_generic_struct_method(type_name, op) {
		if info.params.len == 0
			|| tc.method_receiver_compatible(base_type, info.params[0], info.name) {
			return info
		}
	}
	for method_name in receiver_method_name_candidates(clean, op, tc.cur_module) {
		for candidate in [method_name, tc.cached_c_name(method_name)] {
			if candidate !in tc.fn_ret_types && candidate !in tc.fn_param_types {
				continue
			}
			info := tc.call_info(candidate, true)
			if info.params.len > 0
				&& !tc.method_receiver_compatible(base_type, info.params[0], candidate) {
				continue
			}
			return info
		}
	}
	return none
}

fn (mut tc TypeChecker) check_index_overload_arg(id flat.NodeId, node flat.Node, info CallInfo, op string) bool {
	if node.children_count != 2 {
		if tc.should_diagnose(id) {
			tc.record_error(.cannot_index,
				'overloaded `${op}` expression accepts one index, got ${node.children_count - 1}',
				id)
		}
		return false
	}
	if info.params.len < 2 {
		if tc.should_diagnose(id) {
			tc.record_error(.cannot_index, 'overloaded `${op}` is missing an index parameter', id)
		}
		return false
	}
	index_id := tc.a.child(&node, 1)
	tc.check_node(index_id)
	expected_key := info.params[1]
	actual_key := tc.resolve_expr(index_id, expected_key)
	if !tc.type_compatible(actual_key, expected_key) {
		tc.type_mismatch(.cannot_index,
			'index must be `${expected_key.name()}`, not `${actual_key.name()}`', index_id)
		return false
	}
	return true
}

// check_index validates check index state for types.
fn (mut tc TypeChecker) check_index(id flat.NodeId, node flat.Node) {
	if node.children_count == 0 {
		return
	}
	generic_base_node := tc.a.child_node(&node, 0)
	if name := tc.generic_call_base_name(generic_base_node) {
		type_args := tc.generic_call_type_arg_names(node)
		mut has_unresolved_generic := false
		for type_arg in type_args {
			if is_bare_generic_param(type_arg) && !tc.active_generic_param(type_arg) {
				has_unresolved_generic = true
				break
			}
		}
		if has_unresolved_generic && (tc.fn_generic_params[name] or { []string{} }).len > 0 {
			base_id := tc.a.child(&node, 0)
			tc.record_error_at(.unsupported_generic,
				'a generic fn with generic types, cannot be used outside of another generic fn',
				base_id, tc.node_value_diagnostic_pos(base_id))
			tc.register_synth_type(id, tc.fn_type_from_key(name) or { Type(void_) })
			return
		}
	}
	if generic_fn_type := tc.explicit_generic_fn_value_type(node) {
		tc.register_synth_type(id, generic_fn_type)
		return
	}
	base_id := tc.a.child(&node, 0)
	tc.check_storage_path_base_node(base_id)
	base_type_raw := tc.resolve_type(base_id)
	if base_type_raw is OptionType {
		base_node := tc.a.node(base_id)
		base_text := tc.source_text_for_node(base_id)
		base_pos := if base_node.kind == .selector {
			tc.node_value_diagnostic_pos(base_id)
		} else {
			base_node.pos
		}
		message := if base_node.kind == .call {
			'type `?${base_type_raw.base_type.name()}` is an Option, it must be unwrapped with `func()?`, or use `func() or {default}`'
		} else if tc.direct_parent_kind(id) == .index_assign {
			'type `?${base_type_raw.base_type.name()}` is an Option, it must be unwrapped first; use `var?[]` to do it'
		} else {
			'type `?${base_type_raw.base_type.name()}` is an Option, it must be unwrapped first; use `${base_text}?` to do it'
		}
		tc.record_error_at(.cannot_index, message, base_id, base_pos)
		if base_node.kind == .selector && !tc.index_is_handled_by_guard_or_or_block(id) {
			tc.record_error_at(.cannot_index,
				'field `${base_node.value}` is an Option, so it should have either an `or {}` block, or `?` at the end',
				base_id, base_pos)
		}
		tc.register_synth_type(id, Type(void_))
		return
	}
	mut base_type := unalias_and_unwrap_pointer_type(base_type_raw)
	if map_alias := tc.map_type_from_alias_target(base_type_raw) {
		base_type = Type(map_alias)
	} else if map_alias := tc.map_type_from_alias_target(base_type) {
		base_type = Type(map_alias)
	}
	if base_type_raw.name() in ['voidptr', 'nil'] {
		type_name := tc.pointer_diagnostic_binding_type_name(base_id, base_type_raw)
		tc.record_error_at(.cannot_index, 'type `${type_name}` does not support indexing', id,
			tc.index_brackets_pos(node))
		tc.register_synth_type(id, Type(void_))
		return
	}
	pointer_base_node := tc.a.node(base_id)
	mut_param_base := if pointer_base_node.kind == .ident {
		unalias_type(tc.fn_context.mut_param_base_types[pointer_base_node.value] or { Type(void_) })
	} else {
		Type(void_)
	}
	implicit_mut_param_pointer := mut_param_base !is Void
	if node.value != 'range' && base_type_raw is Pointer && implicit_mut_param_pointer
		&& base_type is Struct && tc.unsafe_depth == 0 {
		if tc.fn_context.generic_params.len > 0 && base_type.name.contains('[') {
			tc.register_synth_type(id, tc.resolve_index_type(node))
			return
		}
		tc.record_error_at(.cannot_index, 'type `mut ${base_type.name}` does not support slicing',
			id, tc.index_brackets_pos(node))
		tc.register_synth_type(id, tc.resolve_index_type(node))
		return
	}
	if node.value != 'range' && base_type_raw is Pointer && !implicit_mut_param_pointer
		&& tc.unsafe_depth == 0 {
		tc.record_error_at(.cannot_index, 'pointer indexing is only allowed in `unsafe` blocks',
			id, tc.index_brackets_pos(node))
		tc.register_synth_type(id, tc.resolve_index_type(node))
		return
	}
	if info := tc.index_overload_call_info(base_type_raw, false) {
		tc.check_index_overload_args(id, node, info)
		tc.register_synth_type(id, info.return_type)
		return
	}
	if node.value == 'range' {
		mut range_out_of_bounds_reported := false
		if !(base_type is Array || base_type is ArrayFixed || base_type is String)
			&& tc.should_diagnose(id) {
			base_node := tc.a.node(base_id)
			type_name := if base_node.kind == .cast_expr
				&& base_node.value in ['byteptr', 'charptr', 'voidptr'] {
				base_node.value
			} else {
				base_type_raw.name()
			}
			action := if base_type_raw is Pointer { 'slicing' } else { 'indexing' }
			tc.record_error_at(.cannot_index, 'type `${type_name}` does not support ${action}', id,
				tc.index_brackets_pos(node))
		}
		for i in 1 .. node.children_count {
			bound_id := tc.a.child(&node, i)
			if int(bound_id) >= 0 {
				bound := tc.a.nodes[int(bound_id)]
				if bound.kind == .empty {
					continue
				}
				tc.check_node(bound_id)
				bound_type := unalias_type(tc.resolve_type(bound_id))
				if bound_type !is Unknown && !bound_type.is_integer() {
					type_name := tc.diagnostic_expr_type_name(bound_id, bound_type)
					message := if base_type is String {
						'non-integer string index `${type_name}`'
					} else {
						'non-integer index `${type_name}` (array type `${base_type.name()}`)'
					}
					tc.type_mismatch(.cannot_index, message, bound_id)
				} else {
					if value := tc.index_literal_value(bound_id) {
						if value < 0 {
							tc.record_error(.cannot_index, 'negative index `${value}`', bound_id)
						} else if base_type is ArrayFixed {
							if length := tc.fixed_array_len_value(base_type) {
								if value > length && !range_out_of_bounds_reported {
									tc.record_error(.cannot_index,
										'index out of range (index: ${value}, len: ${length})',
										bound_id)
									range_out_of_bounds_reported = true
								}
							}
						}
					}
				}
			}
		}
		tc.register_synth_type(id, tc.resolve_index_type(node))
		return
	}
	if node.children_count > 2 {
		for i in 2 .. node.children_count {
			tc.check_node(tc.a.child(&node, i))
		}
		tc.record_error(.cannot_index,
			'index expression accepts one index, got ${node.children_count - 1}', id)
		tc.register_synth_type(id, tc.resolve_index_type(node))
		return
	}
	if node.children_count > 1 {
		index_id := tc.a.child(&node, 1)
		index_error_count := tc.errors.len
		tc.check_node(index_id)
		if base_type is Map {
			actual_key := tc.resolve_expr(index_id, base_type.key_type)
			if actual_key is OptionType {
				index_node := tc.a.node(index_id)
				pos := if index_node.kind == .call && index_node.children_count > 0 {
					callee := tc.a.child_node(index_node, 0)
					if callee.kind == .selector {
						tc.method_call_name_pos(*index_node, callee)
					} else {
						index_node.pos
					}
				} else {
					index_node.pos
				}
				tc.record_error_at(.cannot_index,
					'invalid key: cannot use `?${actual_key.base_type.name()}` as `${base_type.key_type.name()}`, it must be unwrapped first',
					index_id, pos)
			} else if !tc.map_key_type_compatible(actual_key, base_type.key_type) {
				actual_name := tc.diagnostic_expr_type_name(index_id, actual_key)
				mut message := 'invalid key: expected `${base_type.key_type.name()}`, not `${actual_name}`'
				clean_actual_key := unalias_type(actual_key)
				if clean_actual_key is Pointer {
					if tc.type_compatible(clean_actual_key.base_type, base_type.key_type) {
						base_text := tc.source_text_for_node(base_id)
						index_text := tc.source_text_for_node(index_id)
						message += '; did you mean `${base_text}[*${index_text}]`?'
					}
				}
				tc.record_error_at(.cannot_index, message, index_id, token.new_span(node.pos.id,
					tc.a.node(base_id).pos.end, node.pos.end))
			}
			if unalias_type(base_type.value_type) is SumType
				&& !tc.index_is_handled_by_guard_or_or_block(id)
				&& !tc.index_is_assignment_target(id) {
				tc.record_warning_at(.cannot_index,
					'`or {}` block required when indexing a map with sum type value', id, token.new_span(node.pos.id,
					tc.a.node(base_id).pos.end, node.pos.end))
			}
			if tc.current_file_module_has_attribute('strict_map_index')
				&& !tc.index_is_handled_by_guard_or_or_block(id)
				&& !tc.index_is_assignment_target(id) {
				tc.record_error_at(.cannot_index,
					'`@[strict_map_index]` requires handling missing map keys with `or {}` or `if value := map[key] {}`',
					id, tc.index_brackets_pos(node))
			}
			if tc.unsafe_depth == 0 && !tc.index_is_handled_by_guard_or_or_block(id) {
				value_type := unalias_type(base_type.value_type)
				index_pos := token.new_span(node.pos.id, tc.a.node(base_id).pos.end, node.pos.end)
				if value_type is Pointer {
					tc.record_warning_at(.cannot_index,
						'accessing a pointer map value requires an `or {}` block outside `unsafe`',
						id, index_pos)
				}
				mut visited := map[string]bool{}
				if tc.type_contains_pointer(value_type, mut visited) {
					tc.record_warning_at(.cannot_index,
						'accessing map value that contain pointers requires an `or {}` block outside `unsafe`',
						id, index_pos)
				}
			}
			tc.register_synth_type(id, base_type.value_type)
			return
		}
		if getter := tc.index_operator_call_info(base_type_raw, '[]') {
			tc.check_index_overload_arg(id, node, getter, '[]')
			tc.register_synth_type(id, getter.return_type)
			return
		}
		index_type := unalias_type(tc.resolve_type(index_id))
		if index_type is Unknown && tc.new_error_kind_since(index_error_count, .unknown_ident)
			&& (base_type is Array || base_type is ArrayFixed) {
			tc.type_mismatch(.cannot_index,
				'non-integer index `void` (array type `${base_type.name()}`)', index_id)
		} else if index_type !is Unknown && index_type !is Enum && !index_type.is_integer() {
			if index_type is OptionType || index_type is ResultType {
				tc.type_mismatch(.cannot_index,
					'cannot use Option or Result as index (array type `${base_type.name()}`)',
					index_id)
			} else {
				type_name := tc.diagnostic_expr_type_name(index_id, index_type)
				message := if base_type is String {
					'non-integer string index `${type_name}`'
				} else {
					'non-integer index `${type_name}` (array type `${base_type.name()}`)'
				}
				tc.type_mismatch(.cannot_index, message, index_id)
			}
		} else if value := tc.index_literal_value(index_id) {
			if value < 0 {
				tc.record_error(.cannot_index, 'negative index `${value}`', index_id)
			} else if base_type is ArrayFixed {
				if length := tc.fixed_array_len_value(base_type) {
					if value >= length {
						tc.record_error(.cannot_index,
							'index out of range (index: ${value}, len: ${length})', index_id)
					}
				}
			}
		}
	}
	if !(base_type is Array || base_type is ArrayFixed || base_type is String
		|| base_type is Map || base_type is Unknown
		|| (base_type_raw is Pointer && !implicit_mut_param_pointer)) && tc.should_diagnose(id) {
		tc.record_error_at(.cannot_index, 'type `${base_type.name()}` does not support indexing',
			id, tc.index_brackets_pos(node))
	}
	tc.register_synth_type(id, tc.resolve_index_type(node))
}

fn (tc &TypeChecker) map_key_type_compatible(actual Type, expected Type) bool {
	clean_actual := unalias_type(actual)
	clean_expected := unalias_type(expected)
	if clean_actual is Rune && clean_expected !is Rune {
		return false
	}
	if clean_actual is Pointer && clean_expected !is Pointer {
		return false
	}
	return tc.type_compatible(actual, expected)
}

fn (tc &TypeChecker) type_contains_pointer(typ Type, mut visited map[string]bool) bool {
	clean := unalias_type(typ)
	if clean is Pointer {
		return true
	}
	if clean is Array {
		return tc.type_contains_pointer(clean.elem_type, mut visited)
	}
	if clean is ArrayFixed {
		return tc.type_contains_pointer(clean.elem_type, mut visited)
	}
	if clean is Map {
		return tc.type_contains_pointer(clean.key_type, mut visited)
			|| tc.type_contains_pointer(clean.value_type, mut visited)
	}
	if clean is Struct {
		if visited[clean.name] {
			return false
		}
		visited[clean.name] = true
		for field in tc.struct_fields_for_init(clean.name) {
			if tc.type_contains_pointer(field.typ, mut visited) {
				return true
			}
		}
	}
	return false
}

fn (tc &TypeChecker) index_is_assignment_target(id flat.NodeId) bool {
	parent_id := tc.direct_parent_id(id)
	if !tc.valid_node_id(parent_id) {
		return false
	}
	parent := tc.a.node(parent_id)
	if parent.kind !in [.assign, .index_assign, .selector_assign] {
		return false
	}
	for i := 0; i < parent.children_count; i += 2 {
		if tc.a.child(parent, i) == id {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) index_is_handled_by_guard_or_or_block(id flat.NodeId) bool {
	parent_id := tc.direct_parent_id(id)
	if !tc.valid_node_id(parent_id) {
		return false
	}
	parent := tc.a.node(parent_id)
	if parent.kind == .or_expr && parent.children_count > 0 && tc.a.child(parent, 0) == id {
		return true
	}
	if parent.kind != .decl_assign {
		return false
	}
	grandparent_id := tc.direct_parent_id(parent_id)
	if !tc.valid_node_id(grandparent_id) {
		return false
	}
	grandparent := tc.a.node(grandparent_id)
	return grandparent.kind == .if_expr && grandparent.children_count > 0
		&& tc.a.child(grandparent, 0) == parent_id
}

fn (tc &TypeChecker) index_literal_value(id flat.NodeId) ?int {
	node := tc.a.nodes[int(id)]
	if node.kind == .int_literal {
		return v_int_literal_value(node.value)
	}
	if node.kind == .prefix && node.op == .minus && node.children_count > 0 {
		value := tc.index_literal_value(tc.a.child(&node, 0))?
		return -value
	}
	return none
}

fn (mut tc TypeChecker) check_index_overload_args(id flat.NodeId, node flat.Node, info CallInfo) {
	if info.params.len < 2 {
		return
	}
	expected := info.params[1]
	accepts_slice := is_builtin_slice_index_type(expected)
	accepts_slice_array := is_builtin_slice_index_array_type(expected)
	part_count := if node.value == 'range' { 1 } else { node.children_count - 1 }
	has_range := tc.index_overload_has_range_part(node)
	if part_count > 1 && !accepts_slice_array {
		if tc.should_diagnose(id) {
			tc.record_error(.cannot_index,
				'multi-index expressions on overloaded `[]` require a `[]SliceIndex` parameter', id)
		}
		return
	}
	if has_range && !accepts_slice && !accepts_slice_array {
		if tc.should_diagnose(id) {
			tc.record_error(.cannot_index,
				'slice expressions on overloaded `[]` require `SliceIndex` or `[]SliceIndex` parameters',
				id)
		}
		return
	}
	if node.value == 'range' {
		for i in 1 .. node.children_count {
			tc.check_index_overload_bound(tc.a.child(&node, i))
		}
	} else if !accepts_slice && !accepts_slice_array && node.children_count == 2 {
		tc.check_index_overload_part_with_expected(tc.a.child(&node, 1), expected)
	} else {
		for i in 1 .. node.children_count {
			part_id := tc.a.child(&node, i)
			tc.check_index_overload_part(part_id)
		}
	}
}

fn (mut tc TypeChecker) check_index_overload_args_ok(id flat.NodeId, node flat.Node, info CallInfo) bool {
	error_count := tc.errors.len
	tc.check_index_overload_args(id, node, info)
	return tc.errors.len == error_count
}

fn (mut tc TypeChecker) check_index_overload_part_with_expected(id flat.NodeId, expected Type) {
	if int(id) < 0 {
		return
	}
	part := tc.a.nodes[int(id)]
	if part.kind == .range {
		for i in 0 .. part.children_count {
			tc.check_index_overload_bound(tc.a.child(&part, i))
		}
		return
	}
	tc.check_node(id)
	actual := tc.resolve_expr(id, expected)
	if !tc.expr_receiver_compatible(id, actual, expected)
		&& !tc.expr_compatible(id, actual, expected) {
		tc.type_mismatch(.cannot_index,
			'cannot use `${actual.name()}` as overloaded index; expected `${expected.name()}`', id)
	}
}

fn (mut tc TypeChecker) check_index_overload_part(id flat.NodeId) {
	if int(id) < 0 {
		return
	}
	part := tc.a.nodes[int(id)]
	if part.kind == .range {
		for i in 0 .. part.children_count {
			tc.check_index_overload_bound(tc.a.child(&part, i))
		}
		return
	}
	tc.check_node(id)
	part_type := unalias_type(tc.resolve_type(id))
	if part_type !is Unknown && !part_type.is_integer() {
		tc.type_mismatch(.cannot_index, 'index must be integer, not `${part_type.name()}`', id)
	}
}

fn (mut tc TypeChecker) check_index_overload_bound(id flat.NodeId) {
	if int(id) < 0 {
		return
	}
	bound := tc.a.nodes[int(id)]
	if bound.kind == .empty {
		return
	}
	tc.check_node(id)
	bound_type := unalias_type(tc.resolve_type(id))
	if bound_type !is Unknown && !bound_type.is_integer() {
		tc.type_mismatch(.cannot_index, 'slice bound must be integer, not `${bound_type.name()}`',
			id)
	}
}

fn (tc &TypeChecker) index_overload_has_range_part(node flat.Node) bool {
	if node.value == 'range' {
		return true
	}
	for i in 1 .. node.children_count {
		part_id := tc.a.child(&node, i)
		if int(part_id) >= 0 && tc.a.nodes[int(part_id)].kind == .range {
			return true
		}
	}
	return false
}

fn is_builtin_slice_index_type(typ Type) bool {
	clean0 := unalias_type(typ)
	clean := unwrap_pointer(clean0)
	return clean.name() in ['SliceIndex', 'builtin.SliceIndex']
}

fn is_builtin_slice_index_array_type(typ Type) bool {
	clean := unalias_type(typ)
	if clean is Array {
		return is_builtin_slice_index_type(clean.elem_type)
	}
	return false
}

// check_ident validates check ident state for types.
fn (mut tc TypeChecker) check_ident(id flat.NodeId, node flat.Node) {
	if node.value.len == 0 {
		return
	}
	if tc.fn_context.closure_forbidden_captures[node.value]
		&& tc.fn_context.closure_scope != unsafe { nil } {
		if owner := tc.cur_scope.lookup_owner(node.value) {
			if !owner.belongs_to_scope_chain_until(tc.cur_scope, tc.fn_context.closure_scope) {
				if tc.fn_context.lambda_no_captures {
					tc.record_error_at(.unknown_ident, 'undefined variable `${node.value}`', id,
						tc.node_value_diagnostic_pos(id))
					tc.register_synth_type(id, Type(void_))
					return
				}
				tc.record_error_with_details_at(.unknown_ident,
					'`${node.value}` must be explicitly listed as inherited variable to be used inside a closure',
					id, tc.node_value_diagnostic_pos(id), [
					'use `fn [${node.value}] () {` instead of `fn () {`',
				])
				parent_id := tc.direct_parent_id(id)
				if tc.valid_node_id(parent_id) {
					parent := tc.a.node(parent_id)
					if parent.kind == .call && parent.children_count > 0 {
						callee := tc.a.child_node(parent, 0)
						if callee.kind == .ident
							&& callee.value in ['print', 'println', 'eprint', 'eprintln'] {
							tc.record_error_at(.call_arg_mismatch,
								'`${callee.value}` can not print void expressions', parent_id,
								parent.pos)
							tc.record_error_at(.unknown_ident, 'undefined ident: `${node.value}`',
								id, tc.node_value_diagnostic_pos(id))
						}
					}
				}
				tc.register_synth_type(id, Type(void_))
				return
			}
		}
	}
	if node.is_mut {
		mut parent_id := tc.direct_parent_id(id)
		for tc.valid_node_id(parent_id) && tc.a.node(parent_id).kind == .paren {
			parent_id = tc.direct_parent_id(parent_id)
		}
		mut is_option_guard := false
		if tc.valid_node_id(parent_id) && tc.a.node(parent_id).kind == .infix {
			if typ := tc.non_file_scope_type(node.value) {
				is_option_guard = unalias_type(typ) is OptionType
			}
		}
		if !tc.valid_node_id(parent_id)
			|| (tc.a.node(parent_id).kind !in [.call, .is_expr, .match_stmt] && !is_option_guard) {
			mut pos := node.pos
			if file := tc.a.source_files[node.pos.id] {
				source := tc.source_texts_by_file[file.name] or { '' }
				search_start := int_max(0, node.pos.offset - 4)
				if search_start < node.pos.offset && node.pos.offset <= source.len {
					if relative := source[search_start..node.pos.offset].last_index('mut') {
						start := search_start + relative
						pos = token.new_span(node.pos.id, start, start + 3)
					}
				}
			}
			message := if tc.valid_node_id(parent_id)
				&& tc.a.node(parent_id).kind in [.assign, .decl_assign] {
				'unexpected `mut` on right-hand side of assignment'
			} else {
				'the `mut` keyword is invalid here'
			}
			tc.record_error_at(.assignment_mismatch, message, id, pos)
		}
	}
	if node.value == '_' {
		tc.record_error_at(.unknown_ident,
			'undefined ident: `_` (may only be used in assignments)', id,
			tc.node_value_diagnostic_pos(id))
		tc.register_synth_type(id, Type(void_))
		return
	}
	$if ownership ? {
		tc.ownership_check_ident(id, node)
	}
	active_generic_ident := node.value in tc.fn_context.generic_params
		|| tc.active_generic_param(node.value)
		|| tc.node_has_enclosing_generic_param(id, node.value)
		|| tc.source_enclosing_fn_has_generic_param(id, node.value)
	if is_bare_generic_param(node.value) && active_generic_ident {
		tc.register_synth_type(id, unknown_type('generic placeholder `${node.value}`'))
		return
	}
	if typ := tc.non_file_scope_type(node.value) {
		if typ is Unknown && typ.reason == 'invalid variable' {
			tc.record_error_at(.unknown_ident, 'invalid variable `${node.value}`', id,
				tc.node_value_diagnostic_pos(id))
			tc.register_synth_type(id, Type(void_))
			tc.fn_context.continue_after_unknown_ident = true
			return
		}
		tc.register_synth_type(id, typ)
		return
	}
	qname := tc.qualify_name(node.value)
	if qname != node.value {
		if typ := tc.file_scope.lookup(qname) {
			tc.register_synth_type(id, typ)
			return
		}
	}
	if node.value == 'err' {
		tc.register_synth_type(id, tc.parse_type('IError'))
		return
	}
	if typ := tc.const_types[qname] {
		tc.register_synth_type(id, typ)
		return
	}
	// A module-local const shadows an unrelated bare global collected from
	// another module (notably `time.seconds_per_minute` vs a main global).
	if typ := tc.file_scope.lookup(node.value) {
		tc.register_synth_type(id, typ)
		return
	}
	if typ := tc.const_types[node.value] {
		tc.register_synth_type(id, typ)
		return
	}
	if key := tc.generic_fn_value_key(node.value) {
		if !tc.ident_is_call_callee_or_generic_base(id) {
			message := '`${node.value}` is a generic fn, you should pass its concrete types, e.g. ${node.value}[int]'
			tc.record_error_at(.unsupported_generic, message, id, tc.node_value_diagnostic_pos(id))
			if tc.direct_parent_kind(id) == .decl_assign {
				tc.record_error_at(.unsupported_generic, message, id,
					tc.node_value_diagnostic_pos(id))
			}
			tc.register_synth_type(id, tc.fn_type_from_key(key) or { Type(void_) })
			return
		}
	}
	if typ := tc.fn_value_type(node.value) {
		tc.register_synth_type(id, typ)
		return
	}
	if node.value[0].is_capital() && tc.type_name_known(node.value) {
		tc.record_error_at(.assignment_mismatch, '`${node.value}` must be initialized', id,
			tc.node_value_diagnostic_pos(id))
		tc.register_synth_type(id, Type(void_))
		return
	}
	if tc.selective_import_symbol_is_ambiguous(node.value) {
		tc.register_synth_type(id, unknown_type('ambiguous selective import `${node.value}`'))
		return
	}
	if node.value in tc.fn_ret_types || tc.qualify_fn_name(node.value) in tc.fn_ret_types {
		return
	}
	if tc.has_active_import(node.value) || qname in tc.structs || qname in tc.enum_names
		|| qname in tc.sum_types || qname in tc.interface_names {
		return
	}
	if tc.should_diagnose(id) {
		if _ := tc.future_local_decl_id(node.value, id) {
			tc.record_error(.unknown_ident,
				'undefined variable `${node.value}` (used before declaration)', id)
			if tc.fn_context.undefined_variable_context_depth > 0 {
				tc.record_error(.unknown_ident, 'unresolved variable: `${node.value}`', id)
			}
			return
		}
		is_match_subject := tc.ident_is_match_subject(id)
		message := if tc.fn_context.undefined_variable_context_depth > 0 && !is_match_subject {
			'undefined variable: `${node.value}`'
		} else {
			'undefined ident: `${node.value}`'
		}
		tc.record_error(.unknown_ident, message, id)
		if is_bare_generic_param(node.value) || is_match_subject {
			tc.register_synth_type(id, Type(void_))
		}
	}
}

fn (tc &TypeChecker) ident_is_match_subject(id flat.NodeId) bool {
	parent_id := tc.direct_parent_id(id)
	if !tc.valid_node_id(parent_id) {
		return false
	}
	parent := tc.a.node(parent_id)
	return parent.kind == .match_stmt && parent.children_count > 0 && tc.a.child(parent, 0) == id
}

fn (tc &TypeChecker) generic_fn_value_key(name string) ?string {
	mut key := tc.local_bare_fn_key(name) or { '' }
	if key.len == 0 {
		key = tc.resolve_selective_import_symbol(name) or { '' }
	}
	if key.len == 0 && name in tc.fn_ret_types {
		key = name
	}
	if key.len == 0 || (tc.fn_generic_params[key] or { []string{} }).len == 0 {
		return none
	}
	return key
}

fn (tc &TypeChecker) ident_is_call_callee_or_generic_base(id flat.NodeId) bool {
	parent_id := tc.direct_parent_id(id)
	if !tc.valid_node_id(parent_id) {
		return false
	}
	parent := tc.a.node(parent_id)
	if parent.children_count == 0 || tc.a.child(parent, 0) != id {
		return false
	}
	return parent.kind in [.call, .index]
}

fn (tc &TypeChecker) future_local_decl_id(name string, use_id flat.NodeId) ?flat.NodeId {
	if name.len == 0 || !tc.valid_node_id(use_id) {
		return none
	}
	fn_id := flat.NodeId(tc.fn_context.node_id)
	if !tc.valid_node_id(fn_id) {
		return none
	}
	use_pos := tc.a.node(use_id).pos
	mut stack := []flat.NodeId{}
	fn_node := tc.a.node(fn_id)
	for i in 0 .. fn_node.children_count {
		child_id := tc.a.child(fn_node, i)
		if tc.a.node(child_id).kind != .param {
			stack << child_id
		}
	}
	for stack.len > 0 {
		current_id := stack.pop()
		current := tc.a.node(current_id)
		if current.kind == .decl_assign {
			for i := 0; i < current.children_count; i += 2 {
				lhs_id := tc.a.child(current, i)
				lhs := tc.a.node(lhs_id)
				if lhs.kind == .ident && lhs.value == name && lhs.pos.id == use_pos.id
					&& lhs.pos.offset > use_pos.offset {
					return lhs_id
				}
			}
		}
		if current.kind in [.fn_literal, .lambda_expr] {
			continue
		}
		for i in 0 .. current.children_count {
			stack << tc.a.child(current, i)
		}
	}
	return none
}

fn (mut tc TypeChecker) check_defer_result(id flat.NodeId, node flat.Node) {
	if node.typ == 'invalid' {
		tc.register_synth_type(id, Type(void_))
		return
	}
	idx := defer_result_index(node) or {
		if tc.should_diagnose(id) {
			tc.record_error(.unknown_type, 'invalid `res` expression', id)
		}
		tc.register_synth_type(id, unknown_type('invalid `res` expression'))
		return
	}
	ret := tc.fn_context.return_type
	if ret is Void {
		if tc.should_diagnose(id) {
			tc.record_error(.unknown_type,
				'`res` can only be used in functions that returns something', id)
		}
		tc.register_synth_type(id, Type(void_))
		return
	}
	if ret is ResultType {
		if tc.should_diagnose(id) {
			tc.record_error(.unknown_type,
				'`res` cannot be used in functions that returns a Result', id)
		}
		tc.register_synth_type(id, Type(void_))
		return
	}
	if msg := defer_result_index_error_message(ret, idx) {
		if tc.should_diagnose(id) {
			tc.record_error(.unknown_type, msg, id)
		}
		tc.register_synth_type(id, Type(void_))
		return
	}
	tc.register_synth_type(id, tc.defer_result_type(node) or {
		unknown_type('invalid `res` expression')
	})
}

fn (tc &TypeChecker) non_file_scope_type(name string) ?Type {
	owner := tc.cur_scope.lookup_owner(name) or { return none }
	if owner.belongs_to_scope(tc.file_scope) {
		return none
	}
	if owner.scope == unsafe { nil } || owner.index < 0 || owner.index >= owner.scope.types.len {
		return none
	}
	return owner.scope.types[owner.index]
}

// defer_result_index returns -1 for an unindexed `$res()` node and the non-negative
// index for a `$res(index)` node.
pub fn defer_result_index(node flat.Node) ?int {
	if node.kind != .defer_result {
		return none
	}
	if node.value.len == 0 {
		return -1
	}
	if !node.value.bytes().all(it >= `0` && it <= `9`) {
		return none
	}
	return node.value.int()
}

fn defer_result_index_error_message(ret Type, idx int) ?string {
	if ret is MultiReturn {
		if idx < 0 {
			return '`res` requires an index of the returned value'
		}
		if idx >= ret.types.len {
			return 'index ${idx} out of range of ${ret.types.len} return types'
		}
		return none
	}
	if idx >= 0 {
		return '`res` index can only be used with multi-return functions'
	}
	return none
}

fn (tc &TypeChecker) defer_result_type(node flat.Node) ?Type {
	if node.typ == 'invalid' {
		return Type(void_)
	}
	idx := defer_result_index(node) or { return none }
	ret := tc.fn_context.return_type
	if ret is Void || ret is ResultType {
		return Type(void_)
	}
	if _ := defer_result_index_error_message(ret, idx) {
		return Type(void_)
	}
	if ret is MultiReturn {
		return ret.types[idx]
	}
	return ret
}

// resolve_expr resolves resolve expr information for types.
fn (mut tc TypeChecker) resolve_expr(id flat.NodeId, expected Type) Type {
	if int(id) < 0 {
		return unknown_type('missing expression')
	}
	expected_raw := expected
	node := tc.a.nodes[int(id)]
	if node.kind == .field_init && node.children_count > 0 {
		return tc.resolve_expr(tc.a.child(&node, 0), expected)
	}
	if node.kind == .none_expr {
		if expected is OptionType || expected is ResultType || is_ierror_type(expected) {
			tc.register_synth_type(id, expected)
			return expected
		}
		if is_ierror_type(expected) {
			tc.register_synth_type(id, expected)
			return expected
		}
	}
	if node.kind == .or_expr && node.children_count >= 2
		&& (expected is OptionType || expected is ResultType) {
		payload := match expected {
			OptionType { expected.base_type }
			ResultType { expected.base_type }
			else { Type(void_) }
		}
		source_type := tc.resolve_type(tc.a.child(&node, 0))
		body_tail := tc.branch_tail_expr_id(tc.a.child(&node, 1))
		if tc.type_compatible(source_type, payload) && tc.valid_node_id(body_tail) {
			body_type := tc.resolve_expr(body_tail, expected)
			if tc.type_compatible(body_type, expected) || tc.type_compatible(body_type, payload) {
				tc.register_synth_type(id, expected_raw)
				return expected_raw
			}
		}
	}
	if payload := contextual_payload_type(expected) {
		actual := tc.resolve_expr(id, payload)
		if tc.type_compatible(actual, payload) {
			return actual
		}
	}
	if node.kind == .enum_val {
		// The expected type may be the enum directly, or an option/result wrapper around
		// it (`?Enum` / `!Enum`), e.g. `mut field ?LoggingMode` assigned `field = .debug`.
		// Unwrap the option/result payload so the shorthand resolves against the inner
		// enum. On success the node is typed as the *inner* enum (not the wrapper): a bare
		// enum value assigned into an option is auto-wrapped by the assignment/return
		// machinery, exactly like any other bare value assigned into an option, so the
		// node itself must stay unwrapped for codegen to emit the wrap.
		mut enum_expected := expected
		if payload := contextual_payload_type(expected) {
			enum_expected = payload
		}
		if enum_expected is Enum {
			if tc.enum_value_matches(node.value, enum_expected.name) {
				tc.register_synth_type(id, enum_expected)
				return enum_expected
			}
			tc.type_mismatch(.assignment_mismatch,
				'unknown enum field `${node.value}` for `${enum_expected.name}`', id)
			return Type(int_)
		}
	}
	// When several anonymous structs share the same field names, or a contextual type is
	// declared after the literal, the parser may leave or infer the literal too early.
	// Its call/assignment/return context supplies the exact anonymous struct here.
	if node.kind == .struct_init && is_contextual_anonymous_struct_literal(node.value)
		&& expected !is Pointer && tc.anonymous_struct_literal_compatible(node, expected) {
		tc.register_synth_type(id, expected_raw)
		return expected_raw
	}
	// A bare generic struct literal (`Box{...}` / `&Box{...}`) adopts a matching concrete
	// expected instance (`Box[int]` / `&Box[int]`), so `fn make() Box[int] { return
	// Box{...} }` and bare literals passed/assigned where a concrete instance is expected
	// type-check and carry the concrete type into codegen. A *value* literal only adopts a
	// *value* expectation: `bare_generic_literal_adopts` unwraps the pointer, so without
	// the `expected !is Pointer` guard `return Box{...}` would be accepted for an expected
	// `&Box[int]`, and cgen would emit a `Box_int` value where a `Box_int*` is required.
	// The pointer case is the `prefix .amp` (`&Box{...}`) path below.
	if node.kind == .struct_init && expected !is Pointer
		&& tc.bare_generic_literal_adopts(node.value, expected)
		&& tc.generic_literal_fields_compatible(node, expected) {
		tc.register_synth_type(id, expected_raw)
		return expected_raw
	}
	if node.kind == .prefix && node.op == .amp && node.children_count == 1 && expected is Pointer {
		child_id := tc.a.child(&node, 0)
		child := tc.a.nodes[int(child_id)]
		if child.kind == .struct_init && is_contextual_anonymous_struct_literal(child.value)
			&& tc.anonymous_struct_literal_compatible(child, expected.base_type) {
			tc.register_synth_type(child_id, expected.base_type)
			tc.register_synth_type(id, expected_raw)
			return expected_raw
		}
		if child.kind == .struct_init && tc.bare_generic_literal_adopts(child.value, expected)
			&& tc.generic_literal_fields_compatible(child, expected) {
			tc.register_synth_type(id, expected_raw)
			return expected_raw
		}
	}
	if node.kind == .postfix && node.children_count == 1 {
		child_id := tc.a.child(&node, 0)
		child := tc.a.nodes[int(child_id)]
		if node.op == .not && child.kind == .array_literal {
			array_expected := if expected is OptionType {
				expected.base_type
			} else if expected is ResultType {
				expected.base_type
			} else {
				expected
			}
			actual := tc.resolve_expr(child_id, array_expected)
			if tc.receiver_compatible(actual, array_expected) {
				tc.register_synth_type(id, expected_raw)
				return expected_raw
			}
			mut fixed_expected := array_expected
			if fixed_expected is Pointer {
				fixed_expected = fixed_expected.base_type
			}
			if fixed_expected is ArrayFixed {
				fixed_actual := tc.resolve_expr(child_id, fixed_expected)
				if tc.receiver_compatible(fixed_actual, fixed_expected) {
					tc.register_synth_type(id, expected_raw)
					return expected_raw
				}
			}
			elem_type := if child.children_count > 0 {
				tc.array_literal_elem_type(child)
			} else {
				Type(int_)
			}
			array_actual := Type(ArrayFixed{
				elem_type: elem_type
				len:       child.children_count
			})
			tc.register_synth_type(id, array_actual)
			return array_actual
		}
	}
	if node.kind == .array_literal {
		mut elem_expected := Type(void_)
		mut expected_is_array := false
		if expected is Array {
			elem_expected = array_elem_type(expected)
			expected_is_array = true
		} else if expected is ArrayFixed {
			elem_expected = fixed_array_elem_type(expected)
			expected_is_array = true
		}
		if expected_is_array {
			// Empty literal `[]` simply adopts the expected array type.
			if node.children_count == 0 {
				tc.register_synth_type(id, expected_raw)
				return expected_raw
			}
			// Non-empty literal: propagate the expected element type down to each
			// element so context-dependent elements (enum shorthand `[.foo]`, `none`,
			// fn literals) type against it instead of defaulting to a fixed `int[N]`.
			// Adopt the expected array type when every element fits.
			mut all_ok := true
			for i in 0 .. node.children_count {
				child_id := tc.a.child(&node, i)
				elem_actual := tc.resolve_expr(child_id, elem_expected)
				if !tc.expr_receiver_compatible(child_id, elem_actual, elem_expected) {
					all_ok = false
					break
				}
			}
			// A fixed-array expectation additionally requires the literal to have
			// exactly the expected number of elements; otherwise `[1, 2]` would be
			// accepted as e.g. `[4]int` and the C backend would copy/read past the
			// compound literal. Element-type propagation above still happens either
			// way; only the type adoption is gated. Unresolvable const lengths stay
			// lenient (we cannot verify them here).
			if all_ok && expected is ArrayFixed {
				if expected_len := tc.fixed_array_len_value(expected) {
					if node.children_count != expected_len {
						all_ok = false
					}
				}
			}
			if all_ok {
				tc.register_synth_type(id, expected_raw)
				return expected_raw
			}
		}
	}
	if node.kind == .map_init {
		if expected_map := map_type_from_receiver(expected) {
			if node.children_count == 0 {
				tc.register_synth_type(id, expected_raw)
				return expected_raw
			}
			mut all_ok := true
			mut i := 0
			for i < node.children_count {
				child_id := tc.a.child(&node, i)
				child := tc.a.nodes[int(child_id)]
				if child.kind == .prefix && child.value == '...' && child.children_count > 0 {
					update_actual := map_type_from_receiver(tc.resolve_type(tc.a.child(&child, 0))) or {
						all_ok = false
						break
					}
					if !tc.receiver_compatible(update_actual.key_type, expected_map.key_type)
						|| !tc.receiver_compatible(update_actual.value_type, expected_map.value_type) {
						all_ok = false
						break
					}
					i += 2
					continue
				}
				if i + 1 >= node.children_count {
					all_ok = false
					break
				}
				key_actual := tc.resolve_expr(tc.a.child(&node, i), expected_map.key_type)
				value_actual := tc.resolve_expr(tc.a.child(&node, i + 1), expected_map.value_type)
				if !tc.expr_receiver_compatible(tc.a.child(&node, i), key_actual, expected_map.key_type)
					|| !tc.expr_receiver_compatible(tc.a.child(&node, i + 1), value_actual, expected_map.value_type) {
					all_ok = false
					break
				}
				i += 2
			}
			if all_ok {
				tc.register_synth_type(id, expected_raw)
				return expected_raw
			}
		}
	}
	if node.kind == .match_stmt || node.kind == .if_expr {
		// Match/if used as a value expression: propagate the expected type into
		// each branch tail so enum-shorthand / `none` / fn-literal tails type
		// against it (e.g. `return match s { 'a' { .foo } ... }` with an enum
		// return type), then adopt the expected type when every branch fits.
		if expected !is Void && expected !is Unknown && tc.branches_compatible_with(id, expected) {
			tc.register_synth_type(id, expected_raw)
			return expected_raw
		}
	}
	if _ := fn_type_from_type(expected) {
		if _ := tc.resolve_fn_value_name_for_expected(id, expected_raw) {
			tc.register_synth_type(id, expected_raw)
			return expected_raw
		}
	}
	if node.kind == .fn_literal || node.kind == .lambda_expr {
		if _ := fn_type_from_type(expected) {
			actual_fn := tc.resolve_type(id)
			if tc.fn_value_signature_compatible(actual_fn, expected) {
				tc.register_synth_type(id, expected_raw)
				return expected_raw
			}
			return actual_fn
		}
	}
	if tc.expr_is_unsafe_nil(id) {
		if _ := fn_type_from_type(expected) {
			tc.register_synth_type(id, expected_raw)
			return expected_raw
		}
		if expected is Pointer {
			tc.register_synth_type(id, expected_raw)
			return expected_raw
		}
	}
	actual := tc.resolve_type(id)
	if tc.branch_tail_is_error_literal(id) && expected is ResultType && is_ierror_type(actual) {
		return actual
	}
	if tc.type_compatible(actual, expected) {
		if actual.name() == expected.name() {
			tc.register_synth_type(id, expected)
			return expected
		}
		if expected is OptionType || expected is ResultType {
			if actual is OptionType || actual is ResultType {
				tc.register_synth_type(id, expected_raw)
				return expected_raw
			}
			return actual
		}
		if expected is SumType || expected is Enum {
			tc.register_synth_type(id, expected_raw)
			return expected_raw
		}
	}
	if tc.expr_generic_expected_match(id, actual, expected) {
		tc.register_synth_type(id, expected_raw)
		return expected_raw
	}
	return actual
}

// fn_value_match_key returns the single exact function declaration key accepted for a function value.
fn (tc &TypeChecker) fn_value_match_key(node flat.Node, expected Type) ?string {
	key := tc.fn_value_key(node) or { return none }
	actual := tc.fn_type_from_key(key) or { return none }
	if tc.fn_value_signature_compatible(actual, expected) {
		return key
	}
	return none
}

fn (tc &TypeChecker) fn_value_signature_compatible(actual Type, expected Type) bool {
	actual_fn := fn_type_from_type(actual) or { return false }
	expected_fn := fn_type_from_type(expected) or { return false }
	if actual_fn.params.len != expected_fn.params.len {
		return false
	}
	for i in 0 .. actual_fn.params.len {
		actual_param := fn_param_type(actual_fn, i)
		expected_param := fn_param_type(expected_fn, i)
		if !tc.fn_param_compatible(actual_param, expected_param) {
			return false
		}
	}
	return tc.fn_return_compatible(actual_fn.return_type, expected_fn.return_type)
}

// fn_value_key resolves a function value expression to one exact function declaration key.
fn (tc &TypeChecker) fn_value_key(node flat.Node) ?string {
	if node.kind == .ident {
		return tc.ident_fn_value_key(node.value)
	}
	if node.kind == .selector {
		return tc.selector_fn_value_key(node)
	}
	if node.kind in [.cast_expr, .paren, .expr_stmt] && node.children_count > 0 {
		return tc.fn_value_key(tc.a.child_node(&node, 0))
	}
	return none
}

fn (tc &TypeChecker) ident_fn_value_key(name string) ?string {
	if local_name := tc.local_bare_fn_signature_key(name) {
		return local_name
	}
	if imported_name := tc.resolve_selective_import_symbol(name) {
		return imported_name
	}
	if tc.fn_signature_known(name) {
		return name
	}
	return none
}

fn (tc &TypeChecker) selector_fn_value_key(node flat.Node) ?string {
	if node.children_count == 0 || !valid_string_data(node.value) {
		return none
	}
	base := tc.a.child_node(&node, 0)
	if base.kind == .ident {
		if base.value == 'C' {
			key := 'C.${node.value}'
			if tc.fn_signature_known(key) {
				return key
			}
			return none
		}
		if tc.ident_resolves_to_value(base.value) {
			return none
		}
		if resolved_mod := tc.resolve_import_alias(base.value) {
			key := '${resolved_mod}.${node.value}'
			if tc.fn_signature_known(key) {
				return key
			}
			return none
		}
		if key := tc.static_assoc_fn_key_for_base(base.value, node.value) {
			return key
		}
		return none
	}
	if base.kind == .selector && base.children_count > 0 {
		inner := tc.a.child_node(base, 0)
		if inner.kind == .ident {
			mod_name := tc.resolve_import_alias(inner.value) or { inner.value }
			key := '${mod_name}.${base.value}.${node.value}'
			if tc.fn_signature_known(key) {
				return key
			}
			if static_key := tc.static_assoc_fn_key_for_base('${mod_name}.${base.value}',
				node.value)
			{
				return static_key
			}
		}
	}
	return none
}

fn (tc &TypeChecker) static_assoc_fn_key_for_base(type_ident string, method string) ?string {
	if method.len == 0 {
		return none
	}
	for type_name in [type_ident, tc.qualify_name(type_ident)] {
		key := '${type_name}.${method}'
		if tc.fn_signature_known(key) && tc.fn_key_is_static_associated(key) {
			return key
		}
	}
	for type_name in tc.static_assoc_type_candidates(type_ident) {
		key := '${type_name}.${method}'
		if (tc.fn_signature_known(key) || key in tc.fn_ret_types)
			&& tc.fn_key_is_static_associated(key) {
			return key
		}
	}
	return none
}

fn (tc &TypeChecker) fn_key_is_static_associated(key string) bool {
	mut module_name := ''
	for index in tc.top_level_idx {
		node := tc.a.node(flat.NodeId(index))
		if node.kind == .module_decl {
			module_name = node.value
			continue
		}
		if node.kind != .fn_decl || !node.value.contains('.') {
			continue
		}
		qname := checker_qualified_fn_name(module_name, node.value)
		if key != node.value && key != qname {
			continue
		}
		if node.children_count == 0 {
			return true
		}
		first := tc.a.child_node(node, 0)
		return first.kind != .param || first.op != .dot
	}
	return false
}

fn (tc &TypeChecker) static_assoc_type_candidates(type_ident string) []string {
	if type_ident.len == 0 {
		return []string{}
	}
	mut candidates := []string{}
	tc.add_static_assoc_type_candidate(mut candidates, type_ident)
	if resolved := tc.resolve_selective_import_type_symbol(type_ident) {
		tc.add_static_assoc_type_candidate(mut candidates, resolved)
	}
	if resolved := tc.resolve_import_alias(type_ident) {
		tc.add_static_assoc_type_candidate(mut candidates, resolved)
	}
	tc.add_static_assoc_type_candidate(mut candidates, tc.qualify_name(type_ident))
	mut result := []string{}
	for candidate in candidates {
		if tc.static_assoc_type_known(candidate) && candidate !in result {
			result << candidate
		}
	}
	return result
}

fn (tc &TypeChecker) add_static_assoc_type_candidate(mut candidates []string, name string) {
	clean := trimmed_space(name)
	if clean.len == 0 {
		return
	}
	if clean !in candidates {
		candidates << clean
	}
	if target := tc.type_aliases[clean] {
		if target !in candidates {
			candidates << target
		}
	}
	qname := tc.qualify_name(clean)
	if qname != clean && qname !in candidates {
		candidates << qname
	}
	if target := tc.type_aliases[qname] {
		if target !in candidates {
			candidates << target
		}
	}
}

fn (tc &TypeChecker) static_assoc_type_known(type_name string) bool {
	return type_name in tc.structs || type_name in tc.enum_names || type_name in tc.sum_types
		|| type_name in tc.interface_names || type_name in tc.type_aliases
}

fn (tc &TypeChecker) fn_signature_known(key string) bool {
	return key in tc.fn_ret_types && key in tc.fn_param_types
}

fn (tc &TypeChecker) expr_is_unsafe_nil(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .block {
		return node.value == 'unsafe' && tc.expr_tail_is_nil(id)
	}
	if node.kind in [.paren, .expr_stmt] && node.children_count > 0 {
		return tc.expr_is_unsafe_nil(tc.a.child(&node, 0))
	}
	return false
}

fn (tc &TypeChecker) expr_tail_is_nil(id flat.NodeId) bool {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return false
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.nil_literal {
			return true
		}
		.expr_stmt, .paren {
			if node.children_count == 0 {
				return false
			}
			return tc.expr_tail_is_nil(tc.a.child(&node, 0))
		}
		.block {
			if node.children_count == 0 {
				return false
			}
			return tc.expr_tail_is_nil(tc.a.child(&node, node.children_count - 1))
		}
		else {
			return false
		}
	}
}

// fn_value_type supports fn value type handling for TypeChecker.
fn (tc &TypeChecker) fn_value_type(name string) ?Type {
	if local_name := tc.local_bare_fn_key(name) {
		return tc.fn_type_from_key(local_name)
	}
	if imported_name := tc.resolve_selective_import_symbol(name) {
		return tc.fn_type_from_key(imported_name)
	}
	if name in tc.fn_ret_types {
		return tc.fn_type_from_key(name)
	}
	return none
}

// fn_type_from_key converts fn type from key data for types.
fn (tc &TypeChecker) fn_type_from_key(key string) ?Type {
	params := tc.fn_param_types[key] or { return none }
	ret := tc.fn_ret_types[key] or { return none }
	return Type(FnType{
		params:      params.clone()
		return_type: ret
	})
}

// struct_field_c_abi_fn_ptr_type returns the C ABI function-pointer type for a struct field.
pub fn (tc &TypeChecker) struct_field_c_abi_fn_ptr_type(struct_name string, field_name string) ?string {
	key := struct_field_c_abi_key(struct_name, field_name)
	if typ := tc.struct_field_c_abi_fns[key] {
		return typ
	}
	return none
}

// enum_value_matches supports enum value matches handling for TypeChecker.
fn (tc &TypeChecker) enum_value_matches(value string, enum_name string) bool {
	if value.starts_with('.') {
		return tc.enum_has_field(enum_name, value[1..])
	}
	if value.contains('.') {
		prefix := value.all_before_last('.')
		field := value.all_after_last('.')
		if prefix != enum_name && short_type_name(prefix) != short_type_name(enum_name) {
			return false
		}
		return tc.enum_has_field(enum_name, field)
	}
	return tc.enum_has_field(enum_name, value)
}

// enum_has_field converts enum has field data for types.
fn (tc &TypeChecker) enum_has_field(enum_name string, field string) bool {
	fields := tc.enum_fields[enum_name] or { return false }
	return field in fields
}

// resolve_enum_name resolves resolve enum name information for types.
fn (tc &TypeChecker) resolve_enum_name(name string) ?string {
	if name in tc.enum_names {
		return name
	}
	mut shortened := name
	for shortened.contains('.') {
		tail := shortened.all_after('.')
		if !tail.contains('.') {
			break
		}
		shortened = tail
		if shortened in tc.enum_names {
			return shortened
		}
	}
	qname := tc.qualify_name(name)
	if qname in tc.enum_names {
		return qname
	}
	if !name.contains('.') {
		if resolved := tc.resolve_selective_import_type_symbol(name) {
			if resolved in tc.enum_names || resolved in tc.flag_enums {
				return resolved
			}
			if target := tc.resolve_enum_alias_target(resolved) {
				return target
			}
		}
	}
	if target := tc.resolve_enum_alias_target(name) {
		return target
	}
	if target := tc.resolve_enum_alias_target(qname) {
		return target
	}
	return none
}

fn (tc &TypeChecker) resolve_enum_alias_target(name string) ?string {
	mut cur := name
	for _ in 0 .. 16 {
		target := tc.alias_target_type_text(cur) or { return none }
		if target == cur {
			return none
		}
		if target in tc.enum_names || target in tc.flag_enums {
			return target
		}
		cur = target
	}
	return none
}

// enum_selector_type supports enum selector type handling for TypeChecker.
fn (tc &TypeChecker) enum_selector_type(node &flat.Node) ?Type {
	if node.kind != .selector || node.children_count == 0 {
		return none
	}
	base := tc.a.child_node(node, 0)
	mut enum_name := ''
	if base.kind == .ident {
		enum_name = tc.resolve_enum_name(base.value) or { '' }
	} else if base.kind == .selector && base.children_count > 0 {
		inner := tc.a.child_node(base, 0)
		if inner.kind == .ident {
			mod_name := tc.resolve_import_alias(inner.value) or { inner.value }
			enum_name = tc.resolve_enum_name('${mod_name}.${base.value}') or { '' }
		}
	}
	if enum_name.len == 0 || !tc.enum_has_field(enum_name, node.value) {
		return none
	}
	return Type(Enum{
		name:    enum_name
		is_flag: enum_name in tc.flag_enums
	})
}

// type_compatible returns type compatible data for TypeChecker.
fn (tc &TypeChecker) type_compatible(actual Type, expected Type) bool {
	actual_raw := actual
	expected_raw := expected
	if actual.name() == expected.name() {
		return true
	}
	if thread_handle_type_names_match(actual.name(), expected.name()) {
		return true
	}
	if fn_param_is_voidptr_type(actual) && fn_param_is_voidptr_type(expected) {
		return true
	}
	if actual is ResultType && expected is OptionType {
		return false
	}
	if actual is Unknown || expected is Unknown {
		return true
	}
	if type_contains_unknown(actual) || type_contains_unknown(expected) {
		return true
	}
	if actual is FnType && expected is FnType {
		return tc.fn_value_signature_compatible(Type(actual), Type(expected))
	}
	if (actual.name().contains('[') || expected.name().contains('['))
		&& tc.generic_type_name_matches(actual.name(), expected.name()) {
		return true
	}
	if tc.sum_variant_type_for_pattern(expected.name(), actual.name()) != none {
		return true
	}
	if actual is Alias && expected is Alias {
		return tc.type_compatible(actual.base_type, expected.base_type)
	}
	if actual is Alias {
		if expected is Interface && tc.type_implements_interface(actual, expected) {
			return true
		}
		return tc.type_compatible(actual.base_type, expected)
	}
	if expected is Alias {
		return tc.type_compatible(actual, expected.base_type)
	}
	if expected is String && is_ierror_type(actual) {
		return true
	}
	if actual is Array && is_runtime_array_type(expected) {
		return true
	}
	if actual is Array && expected is Array && actual.elem_type is Void {
		return true
	}
	if is_runtime_array_type(actual) && expected is Array {
		return true
	}
	if actual is None {
		return expected is OptionType || expected is ResultType || is_ierror_type(expected)
	}
	if is_option_void_type(actual) && is_ierror_type(expected) {
		return true
	}
	if expected is OptionType {
		if actual is OptionType {
			return tc.type_compatible(actual.base_type, expected.base_type)
		}
		return tc.type_compatible(actual, expected.base_type)
	}
	if expected is ResultType {
		if actual is ResultType {
			return tc.type_compatible(actual.base_type, expected.base_type)
		}
		return tc.type_compatible(actual, expected.base_type)
	}
	expected_named_interface := expected.name()
	if expected_named_interface in tc.interface_names {
		return tc.type_implements_interface(actual, Interface{
			name: expected_named_interface
		})
	}
	if expected is SumType {
		return tc.type_matches_sum(actual_raw, expected_raw)
	}
	if expected is Interface {
		return tc.type_implements_interface(actual, expected)
	}
	if expected is Enum && (expected.is_flag || expected.name in tc.flag_enums)
		&& actual is Primitive && actual.props.has(.integer) {
		return true
	}
	if actual is Interface {
		if expected is Interface {
			return tc.interface_implements_interface(actual.name, expected.name)
		}
		return false
	}
	if actual.is_integer() && expected.is_integer() {
		return true
	}
	if expected is Primitive {
		if actual is Primitive {
			if expected.props.has(.boolean) || actual.props.has(.boolean) {
				return expected.props.has(.boolean) && actual.props.has(.boolean)
			}
			if expected.props.has(.float) && actual.props.has(.integer) {
				return true
			}
			if expected.props.has(.integer) && actual.props.has(.integer) {
				return true
			}
			if expected.props.has(.float) && actual.props.has(.float) {
				return true
			}
		}
		if expected.props.has(.integer) && actual.is_integer() {
			return true
		}
	}
	if actual is Primitive && actual.props.has(.integer) && expected.is_integer() {
		return true
	}
	if expected is String {
		return actual is String || is_ierror_type(actual)
	}
	if expected is Char {
		return actual is Char || actual.name() == 'u8'
	}
	if expected is Pointer {
		if actual is Nil {
			return true
		}
		if expected.base_type is Void && actual is FnType {
			return true
		}
		if actual is Pointer {
			if expected.base_type is Interface
				&& tc.type_implements_interface(actual.base_type, expected.base_type) {
				return true
			}
			expected_base_name := expected.base_type.name()
			if expected_base_name in tc.interface_names && tc.type_implements_interface(actual.base_type, Interface{
				name: expected_base_name
			}) {
				return true
			}
			if expected.base_type is Void || actual.base_type is Void {
				return true
			}
			// C interop: `&char` and `&u8` share representation (`tos_clone(C.strdup(s))`).
			if (actual.base_type is Char && expected.base_type.name() == 'u8')
				|| (actual.base_type.name() == 'u8' && expected.base_type is Char) {
				return true
			}
			return tc.type_compatible(actual.base_type, expected.base_type)
		}
	}
	if expected is Array {
		if actual is Array {
			return tc.type_compatible(actual.elem_type, expected.elem_type)
		}
		if actual is ArrayFixed {
			return tc.type_compatible(actual.elem_type, expected.elem_type)
		}
	}
	if expected is ArrayFixed {
		if actual is ArrayFixed {
			return tc.fixed_array_lengths_compatible(actual, expected)
				&& tc.type_compatible(actual.elem_type, expected.elem_type)
		}
	}
	if expected is Channel {
		if actual is Channel {
			return actual.is_mut == expected.is_mut
				&& tc.type_compatible(actual.elem_type, expected.elem_type)
		}
	}
	if expected is Map {
		if actual is Map {
			return tc.type_compatible(actual.key_type, expected.key_type)
				&& tc.type_compatible(actual.value_type, expected.value_type)
		}
	}
	if expected is FnType {
		if actual is FnType {
			if actual.params.len != expected.params.len {
				return false
			}
			for i in 0 .. actual.params.len {
				actual_param := fn_param_type(actual, i)
				expected_param := fn_param_type(expected, i)
				if !tc.fn_param_compatible(actual_param, expected_param) {
					return false
				}
			}
			return tc.fn_return_compatible(actual.return_type, expected.return_type)
		}
	}
	return false
}

fn thread_handle_type_names_match(actual string, expected string) bool {
	if !actual.starts_with('thread') || !expected.starts_with('thread') {
		return false
	}
	return canonical_thread_handle_type_name(actual) == canonical_thread_handle_type_name(expected)
}

fn canonical_thread_handle_type_name(name string) string {
	clean := trimmed_space(name)
	if clean == 'thread void' {
		return 'thread'
	}
	if clean == 'thread !' {
		return 'thread !void'
	}
	if clean == 'thread ?' {
		return 'thread ?void'
	}
	return clean
}

fn type_contains_unknown(typ Type) bool {
	if typ is Unknown {
		return true
	}
	if typ is Alias {
		return type_contains_unknown(typ.base_type)
	}
	if typ is Array {
		return type_contains_unknown(typ.elem_type)
	}
	if typ is ArrayFixed {
		return type_contains_unknown(typ.elem_type)
	}
	if typ is Map {
		return type_contains_unknown(typ.key_type) || type_contains_unknown(typ.value_type)
	}
	if typ is Pointer {
		return type_contains_unknown(typ.base_type)
	}
	if typ is OptionType {
		return type_contains_unknown(typ.base_type)
	}
	if typ is ResultType {
		return type_contains_unknown(typ.base_type)
	}
	if typ is FnType {
		for param in typ.params {
			if type_contains_unknown(param) {
				return true
			}
		}
		return type_contains_unknown(typ.return_type)
	}
	if typ is MultiReturn {
		for part in typ.types {
			if type_contains_unknown(part) {
				return true
			}
		}
	}
	return false
}

fn (tc &TypeChecker) fn_param_compatible(actual Type, expected Type) bool {
	if actual is Unknown || expected is Unknown {
		return false
	}
	if tc.c_type(actual) == tc.c_type(expected) {
		return true
	}
	return fn_param_can_cast_userdata_param(actual, expected)
}

fn (tc &TypeChecker) fn_return_compatible(actual Type, expected Type) bool {
	if actual.name() == expected.name() {
		return true
	}
	if tc.c_type(actual) == tc.c_type(expected) && tc.type_compatible(actual, expected) {
		return true
	}
	return fn_return_canonical_type_name(actual) == fn_return_canonical_type_name(expected)
}

fn fn_param_can_cast_userdata_param(actual Type, expected Type) bool {
	return (fn_param_is_voidptr_type(expected) && fn_param_is_nonvoid_pointer_type(actual))
		|| (fn_param_is_nonvoid_pointer_type(expected) && fn_param_is_voidptr_type(actual))
}

fn fn_param_is_voidptr_type(typ Type) bool {
	if typ.name() in ['voidptr', '&void'] {
		return true
	}
	clean := fn_param_unalias_type(typ)
	if clean is Pointer {
		base := fn_param_unalias_type(clean.base_type)
		return base is Void
	}
	return false
}

fn fn_param_is_nonvoid_pointer_type(typ Type) bool {
	clean := fn_param_unalias_type(typ)
	if clean is Pointer {
		base := fn_param_unalias_type(clean.base_type)
		return base !is Void
	}
	return false
}

fn fn_param_unalias_type(typ Type) Type {
	if typ is Alias {
		return fn_param_unalias_type(typ.base_type)
	}
	return typ
}

fn call_arg_integer_type(typ Type) bool {
	clean := fn_param_unalias_type(typ)
	return clean.is_integer()
		|| clean.name() in ['int', 'i8', 'i16', 'i32', 'i64', 'isize', 'u8', 'u16', 'u32', 'u64', 'usize', 'rune']
}

fn call_arg_numeric_type(typ Type) bool {
	clean := fn_param_unalias_type(typ)
	return call_arg_integer_type(clean) || clean.is_float()
}

fn escaped_identifier_name(name string) string {
	return if name.starts_with('@') { name[1..] } else { name }
}

fn fn_return_canonical_type_name(typ Type) string {
	if typ is Alias {
		return fn_return_canonical_type_name(typ.base_type)
	}
	return typ.name()
}

// is_ierror_type reports whether is ierror type applies in types.
fn is_builtin_ierror_name(name string) bool {
	return name == 'IError' || name == 'builtin.IError'
}

fn is_ierror_type(t Type) bool {
	if t is Alias {
		return is_builtin_ierror_name(t.name) || is_ierror_type(t.base_type)
	}
	if t is Pointer {
		return is_ierror_type(t.base_type)
	}
	if t is Struct {
		return is_builtin_ierror_name(t.name)
	}
	if t is Interface {
		return is_builtin_ierror_name(t.name)
	}
	return false
}

fn (tc &TypeChecker) type_embeds_error(t Type) bool {
	clean := unwrap_pointer(t)
	if clean is Alias {
		return tc.type_embeds_error(clean.base_type)
	}
	if clean is Struct {
		struct_name := clean.name
		if struct_name == 'Error' || struct_name.ends_with('.Error') {
			return true
		}
		return tc.receiver_embeds(clean, Type(Struct{
			name: 'Error'
		}))
	}
	return false
}

// is_runtime_array_type reports whether is runtime array type applies in types.
fn is_runtime_array_type(t Type) bool {
	if t is Alias {
		return is_runtime_array_type(t.base_type)
	}
	if t is Struct {
		return t.name == 'array'
	}
	return false
}

// fixed_array_lengths_compatible supports fixed array lengths compatible handling for TypeChecker.
fn (tc &TypeChecker) fixed_array_lengths_compatible(actual ArrayFixed, expected ArrayFixed) bool {
	if actual.len > 0 && expected.len > 0 {
		return actual.len == expected.len
	}
	actual_len := tc.fixed_array_len_value(actual) or {
		return actual.len_expr == expected.len_expr
	}
	expected_len := tc.fixed_array_len_value(expected) or {
		return actual.len_expr == expected.len_expr
	}
	return actual_len == expected_len
}

// fixed_array_len_value returns the evaluated fixed-array length when it can be resolved.
pub fn (tc &TypeChecker) fixed_array_len_value(arr ArrayFixed) ?int {
	if arr.len > 0 {
		return arr.len
	}
	if arr.len_expr.len == 0 {
		return none
	}
	return tc.const_int_value(arr.len_expr, []string{})
}

// const_expr_paren_wraps_whole reports whether `s` is a single parenthesised group that
// encloses the entire string (`(a + b)`), as opposed to one that only covers part of it
// (`(a) + (b)`), so a const length wrapped in redundant parentheses can be unwrapped.
fn const_expr_paren_wraps_whole(s string) bool {
	if s.len < 2 || s[0] != `(` || s[s.len - 1] != `)` {
		return false
	}
	mut depth := 0
	for i := 0; i < s.len; i++ {
		if s[i] == `(` {
			depth++
		} else if s[i] == `)` {
			depth--
			if depth == 0 {
				return i == s.len - 1
			}
		}
	}
	return false
}

@[ignore_overflow]
fn const_int_power(base int, exponent int) int {
	mut exp := exponent
	mut power := base
	mut value := 1
	if exp < 0 {
		if base == 0 {
			return -1
		}
		if base != 1 && base != -1 {
			return 0
		}
		return if exp & 1 != 0 { base } else { 1 }
	}
	for exp > 0 {
		if exp & 1 != 0 {
			value *= power
		}
		power *= power
		exp >>= 1
	}
	return value
}

// const_int_value supports const int value handling for TypeChecker.
pub fn (tc &TypeChecker) const_int_value(name string, seen []string) ?int {
	return tc.const_int_value_in_module(name, tc.cur_module, seen)
}

// const_int_value_in_module supports const int value handling for a specific module.
pub fn (tc &TypeChecker) const_int_value_in_module(name string, module_name string, seen []string) ?int {
	if name in seen {
		return none
	}
	mut candidates := []string{}
	candidates << name
	if module_name.len > 0 && module_name != 'main' && module_name != 'builtin'
		&& !name.contains('.') {
		candidates << '${module_name}.${name}'
	}
	qname := tc.qualify_name(name)
	if qname != name {
		candidates << qname
	}
	if key := tc.const_key_for_suffix(name) {
		candidates << key
	}
	for key in candidates {
		if key in seen {
			continue
		}
		if expr_id := tc.const_exprs[key] {
			mut next_seen := seen.clone()
			next_seen << key
			const_module := tc.const_modules[key] or { module_name }
			return tc.const_int_expr(expr_id, const_module, next_seen)
		}
	}
	if v := v_int_literal_value(name) {
		return v
	}
	if v := tc.const_int_cast_text_value(name, module_name, seen) {
		return v
	}
	if v := tc.const_int_enum_selector_value(name) {
		return v
	}
	// Simple const arithmetic in string form, e.g. a fixed-array size `[SEGS + 1]`,
	// `[SEGS+1]`, `[segs / 2]`, `[segs % 4]` or `[2 * (segs + 1)]`. A length wrapped
	// wholly in parentheses is the inner expression, so strip the outer pair and
	// re-evaluate. Otherwise split on the rightmost operator of the lowest precedence
	// level present (`+ -`, then `* / %`) that sits OUTSIDE any parentheses, so a nested
	// operator (the `+` inside `2 * (segs + 1)`) is not chosen; precedence and left
	// associativity hold and each side is trimmed and resolved recursively. A leading `-`
	// (unary) leaves an empty lhs and is skipped.
	expr := trimmed_space(name)
	if const_expr_paren_wraps_whole(expr) {
		return tc.const_int_value(trimmed_space(expr[1..expr.len - 1]), seen)
	}
	// Operators are grouped by the same precedence levels as token.left_binding_power:
	// `+ - | ^` share sum, while `* / % << >> >>> &` share product. Scanning the
	// rightmost operator at a level preserves left associativity. Power scans its first
	// operator instead because it is right-associative.
	// Longer operators match first (`>>>` before `>>`, two-char before one) and `idx + op.len`
	// skips the operator.
	for level in [['+', '-', '|', '^'], ['*', '/', '%', '&', '<<', '>>', '>>>'],
		['**']] {
		mut idx := -1
		mut op := ''
		mut depth := 0
		mut i := 0
		for i < expr.len {
			ch := expr[i..i + 1]
			if ch == '(' {
				depth++
				i++
				continue
			}
			if ch == ')' {
				depth--
				i++
				continue
			}
			if depth == 0 {
				three := if i + 3 <= expr.len { expr[i..i + 3] } else { '' }
				if three.len == 3 && three in level {
					idx = i
					op = three
					i += 3
					continue
				}
				two := if i + 2 <= expr.len { expr[i..i + 2] } else { '' }
				if two == '**' {
					if two in level && idx < 0 {
						idx = i
						op = two
					}
					i += 2
					continue
				}
				if two.len == 2 && two in level {
					idx = i
					op = two
					i += 2
					continue
				}
				if ch in level {
					idx = i
					op = ch
				}
			}
			i++
		}
		if idx <= 0 {
			continue
		}
		lhs := trimmed_space(expr[..idx])
		rhs := trimmed_space(expr[idx + op.len..])
		if lhs.len == 0 || rhs.len == 0 {
			continue
		}
		// Prefix operators bind below power in the parser. Strip leading signs
		// from the power base and apply them to the complete power expression:
		// `-2 ** 2` is `-(2 ** 2)`, while `(-2) ** 2` keeps the signed base.
		mut lhs_text := lhs
		mut power_sign := 1
		if op == '**' {
			for lhs_text.len > 0 && lhs_text[0] in [`+`, `-`] {
				if lhs_text[0] == `-` {
					power_sign = -power_sign
				}
				lhs_text = trimmed_space(lhs_text[1..])
			}
			if lhs_text.len == 0 {
				return none
			}
		}
		l := tc.const_int_value_in_module(lhs_text, module_name, seen) or { return none }
		r := tc.const_int_value_in_module(rhs, module_name, seen) or { return none }
		if (op == '/' || op == '%') && r == 0 {
			return none
		}
		if (op == '<<' || op == '>>' || op == '>>>') && (r < 0 || r >= 64) {
			return none
		}
		value := match op {
			'+' { l + r }
			'-' { l - r }
			'*' { l * r }
			'/' { l / r }
			'%' { l % r }
			'|' { l | r }
			'^' { l ^ r }
			'&' { l & r }
			'<<' { int(u64(l) << r) }
			'>>' { l >> r }
			'**' { const_int_power(l, r) }
			else { int(u64(l) >> r) }
		}
		return if op == '**' && power_sign < 0 { -value } else { value }
	}
	if expr.len > 1 && expr[0] in [`+`, `-`] {
		value := tc.const_int_value_in_module(trimmed_space(expr[1..]), module_name, seen) or {
			return none
		}
		return if expr[0] == `-` { -value } else { value }
	}
	return none
}

fn (tc &TypeChecker) const_int_cast_text_value(text string, module_name string, seen []string) ?int {
	expr := trimmed_space(text)
	if !expr.ends_with(')') {
		return none
	}
	open := expr.index_u8(`(`)
	if open <= 0 {
		return none
	}
	cast_type_name := trimmed_space(expr[..open])
	if cast_type_name.len == 0 {
		return none
	}
	cast_type := unalias_type(tc.parse_type(cast_type_name))
	if !cast_type.is_integer() {
		return none
	}
	inner := trimmed_space(expr[open + 1..expr.len - 1])
	if inner.len == 0 {
		return none
	}
	return tc.const_int_value_in_module(inner, module_name, seen)
}

fn (tc &TypeChecker) const_int_enum_selector_value(text string) ?int {
	expr := trimmed_space(text)
	dot := expr.last_index_u8(`.`)
	if dot <= 0 || dot >= expr.len - 1 {
		return none
	}
	enum_name := tc.resolve_enum_name(trimmed_space(expr[..dot])) or { return none }
	field := trimmed_space(expr[dot + 1..])
	for item in tc.comptime_static_enum_decl_value_cases(enum_name) {
		if item.name == field && item.has_value {
			return item.value
		}
	}
	fields := tc.enum_fields[enum_name] or { return none }
	for idx, name in fields {
		if name == field {
			return if enum_name in tc.flag_enums { 1 << idx } else { idx }
		}
	}
	return none
}

// const_int_expr supports const int expr handling for TypeChecker.
fn (tc &TypeChecker) const_int_expr(id flat.NodeId, module_name string, seen []string) ?int {
	if int(id) < 0 {
		return none
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.int_literal {
			if v := v_int_literal_value(node.value) {
				return v
			}
		}
		.char_literal {
			return match_char_literal_value(node.value)
		}
		.ident {
			return tc.const_int_value_in_module(node.value, module_name, seen)
		}
		.paren {
			if node.children_count > 0 {
				return tc.const_int_expr(tc.a.child(&node, 0), module_name, seen)
			}
		}
		.cast_expr {
			if node.children_count == 0 {
				return none
			}
			cast_type := unalias_type(tc.parse_type(node.value))
			if !cast_type.is_integer() {
				return none
			}
			return tc.const_int_expr(tc.a.child(&node, 0), module_name, seen)
		}
		.sizeof_expr {
			return tc.const_sizeof_type_value(node.value)
		}
		.prefix {
			if node.children_count == 0 {
				return none
			}
			value := tc.const_int_expr(tc.a.child(&node, 0), module_name, seen) or { return none }
			return match node.op {
				.minus { -value }
				.plus { value }
				.bit_not { ~value }
				else { none }
			}
		}
		.infix {
			if node.children_count < 2 {
				return none
			}
			left := tc.const_int_expr(tc.a.child(&node, 0), module_name, seen) or { return none }
			right := tc.const_int_expr(tc.a.child(&node, 1), module_name, seen) or { return none }
			match node.op {
				.plus {
					return left + right
				}
				.minus {
					return left - right
				}
				.mul {
					return left * right
				}
				.power {
					return const_int_power(left, right)
				}
				.div {
					if right == 0 {
						return none
					}
					return left / right
				}
				.mod {
					if right == 0 {
						return none
					}
					return left % right
				}
				.amp {
					return left & right
				}
				.pipe {
					return left | right
				}
				.xor {
					return left ^ right
				}
				.left_shift {
					if right < 0 || right >= 64 {
						return none
					}
					return int(u64(left) << right)
				}
				.right_shift {
					if right < 0 || right >= 64 {
						return none
					}
					return left >> right
				}
				.right_shift_unsigned {
					if right < 0 || right >= 64 {
						return none
					}
					return int(u64(left) >> right)
				}
				else {
					return none
				}
			}
		}
		else {}
	}

	return none
}

fn (tc &TypeChecker) const_sizeof_type_value(type_name string) ?int {
	typ := unalias_type(tc.parse_type(type_name))
	if typ is Primitive {
		if typ.size > 0 {
			return int(typ.size) / 8
		}
	}
	if typ is Char {
		return 1
	}
	if typ is Rune {
		return 4
	}
	if typ is ISize || typ is USize {
		return 8
	}
	return none
}

// type_implements_interface returns type implements interface data for TypeChecker.
fn (tc &TypeChecker) type_implements_interface(actual Type, expected Interface) bool {
	clean := unwrap_pointer(actual)
	if clean is Unknown {
		return true
	}
	if tc.interface_has_no_requirements(expected.name) {
		return true
	}
	if clean is Interface {
		return tc.interface_implements_interface(clean.name, expected.name)
	}
	if clean is Array {
		if tc.interface_abstract_method_names(expected.name).len > 0 {
			return false
		}
		for field in tc.interface_field_list(expected.name) {
			actual_field := tc.builtin_array_field_type(field.name) or { return false }
			if !tc.type_compatible(actual_field, field.typ)
				|| !tc.type_compatible(field.typ, actual_field) {
				return false
			}
		}
		return true
	}
	concrete_name := method_type_name(clean)
	if concrete_name.len == 0 {
		return false
	}
	return tc.named_type_implements_interface(concrete_name, expected.name)
}

fn (tc &TypeChecker) builtin_array_field_type(name string) ?Type {
	return match name {
		'element_size', 'offset', 'len', 'cap' { Type(int_) }
		'data' { Type(voidptr_) }
		'flags' { tc.parse_type('ArrayFlags') }
		else { none }
	}
}

// interface_implements_interface supports interface implements interface handling for TypeChecker.
pub fn (tc &TypeChecker) interface_implements_interface(actual_name string, expected_name string) bool {
	actual := tc.interface_metadata_name(actual_name)
	expected := tc.interface_metadata_name(expected_name)
	if actual == expected {
		return true
	}
	for method in tc.interface_method_names(expected) {
		actual_key := tc.interface_method_signature_key(actual, method) or { '${actual}.${method}' }
		expected_key := tc.interface_method_signature_key(expected, method) or {
			'${expected}.${method}'
		}
		if actual_key !in tc.fn_param_types
			|| !tc.method_signature_compatible(actual_key, expected_key) {
			return false
		}
	}
	for field in tc.interface_field_list(expected) {
		actual_field := tc.interface_field_type(actual, field.name) or { return false }
		if !tc.type_compatible(actual_field, field.typ)
			|| !tc.type_compatible(field.typ, actual_field) {
			return false
		}
	}
	return true
}

pub fn (tc &TypeChecker) interface_metadata_name(name string) string {
	if name.len == 0 {
		return name
	}
	if name in tc.interface_names || name in tc.interface_abstract_methods
		|| name in tc.interface_embeds || name in tc.interface_fields {
		return name
	}
	if !name.contains('.') {
		qname := tc.qualify_name(name)
		if qname in tc.interface_names || qname in tc.interface_abstract_methods
			|| qname in tc.interface_embeds || qname in tc.interface_fields {
			return qname
		}
	}
	short := name.all_after_last('.')
	mut match_name := ''
	for candidate, _ in tc.interface_names {
		if candidate.all_after_last('.') != short {
			continue
		}
		if match_name.len > 0 && match_name != candidate {
			return name
		}
		match_name = candidate
	}
	if match_name.len > 0 {
		return match_name
	}
	return name
}

// named_type_implements_interface
// supports helper handling in types.
pub fn (tc &TypeChecker) named_type_implements_interface(concrete_name string, iface_name string) bool {
	if tc.interface_has_no_requirements(iface_name) {
		return true
	}
	// Only the abstract (declared) methods must be provided by the concrete type.
	// Methods defined directly on the interface (default implementations) are
	// inherited and need not be reimplemented.
	for method in tc.interface_abstract_method_names(iface_name) {
		expected_key := tc.interface_method_signature_key(iface_name, method) or {
			'${iface_name}.${method}'
		}
		if concrete_name == 'char' && method == 'str'
			&& tc.interface_method_is_str_requirement(expected_key) {
			return false
		}
		if concrete_key := tc.concrete_method_signature_key(concrete_name, method) {
			if !tc.method_signature_compatible(concrete_key, expected_key) {
				return false
			}
			continue
		}
		if info := tc.resolve_generic_struct_method(concrete_name, method) {
			if !tc.method_call_info_signature_compatible(info, expected_key) {
				return false
			}
			continue
		}
		if info := tc.resolve_generic_sum_method(concrete_name, method) {
			if !tc.method_call_info_signature_compatible(info, expected_key) {
				return false
			}
			continue
		}
		if method == 'str' && tc.interface_method_is_str_requirement(expected_key)
			&& tc.type_has_implicit_str_method(concrete_name) {
			continue
		}
		return false
	}
	for field in tc.interface_field_list(iface_name) {
		actual_field := tc.interface_actual_field(concrete_name, field.name) or { return false }
		if !tc.type_compatible(actual_field.typ, field.typ)
			|| !tc.type_compatible(field.typ, actual_field.typ)
			|| (field.is_mut && !actual_field.is_mut) {
			return false
		}
	}
	return true
}

fn (tc &TypeChecker) interface_method_is_str_requirement(expected_key string) bool {
	ret := tc.fn_ret_types[expected_key] or { return false }
	if ret.name() != 'string' {
		return false
	}
	params := tc.fn_param_types[expected_key] or { return false }
	return params.len == 1
}

pub fn (tc &TypeChecker) type_has_implicit_str_method(name string) bool {
	clean := trimmed_space(name)
	if clean.len == 0 {
		return false
	}
	mut candidates := [clean]
	if !clean.contains('.') {
		qname := tc.qualify_name(clean)
		if qname != clean {
			candidates << qname
		}
	}
	for candidate in candidates {
		if tc.type_name_resolves_to_sum_type(candidate) {
			continue
		}
		base_name := generic_base_name(candidate)
		if candidate in tc.structs || base_name in tc.structs || candidate in tc.enum_names
			|| candidate in tc.flag_enums || candidate in tc.interface_names {
			return true
		}
		if is_builtin_type_name(candidate) {
			mut seen := map[string]bool{}
			if tc.type_supports_implicit_str(tc.parse_type(candidate), mut seen) {
				return true
			}
		}
		if candidate in tc.type_aliases {
			mut seen := map[string]bool{}
			seen[candidate] = true
			if tc.type_supports_implicit_str(tc.parse_type(tc.type_aliases[candidate]), mut seen) {
				return true
			}
		}
	}
	return false
}

fn (tc &TypeChecker) type_supports_implicit_str(typ Type, mut seen map[string]bool) bool {
	if typ is Alias {
		if seen[typ.name] {
			return false
		}
		seen[typ.name] = true
		return tc.type_supports_implicit_str(typ.base_type, mut seen)
	}
	if typ is Primitive {
		return typ.props.has(.boolean) || typ.props.has(.integer) || typ.props.has(.float)
	}
	return typ is String || typ is Rune || typ is ISize || typ is USize || typ is Pointer
		|| typ is Array || typ is ArrayFixed || typ is Map || typ is Enum || typ is Struct
}

fn (tc &TypeChecker) type_name_resolves_to_sum_type(name string) bool {
	mut cur := trimmed_space(name)
	mut seen := map[string]bool{}
	for cur.len > 0 {
		if cur in tc.sum_types {
			return true
		}
		if !cur.contains('.') {
			qname := tc.qualify_name(cur)
			if qname in tc.sum_types {
				return true
			}
		}
		if seen[cur] {
			return false
		}
		seen[cur] = true
		mut next := tc.type_aliases[cur] or { '' }
		if next.len == 0 && !cur.contains('.') {
			next = tc.type_aliases[tc.qualify_name(cur)] or { '' }
		}
		cur = trimmed_space(next)
	}
	return false
}

fn (tc &TypeChecker) interface_has_no_requirements(iface_name string) bool {
	return tc.interface_abstract_method_names(iface_name).len == 0
		&& tc.interface_field_list(iface_name).len == 0
}

fn struct_decl_implements_from_typ(typ string) []string {
	mut out := []string{}
	for part in struct_decl_typ_parts(typ) {
		if !part.starts_with('implements=') {
			continue
		}
		for iface in part['implements='.len..].split('|') {
			clean := trimmed_space(iface)
			if clean.len > 0 {
				out << clean
			}
		}
	}
	return out
}

fn struct_decl_typ_parts(typ string) []string {
	mut parts := []string{}
	mut start := 0
	mut depth := 0
	for i, ch in typ {
		if ch == `[` {
			depth++
		} else if ch == `]` {
			if depth > 0 {
				depth--
			}
		} else if ch == `,` && depth == 0 {
			parts << typ[start..i]
			start = i + 1
		}
	}
	parts << typ[start..]
	return parts
}

fn marker_type_name(name string) string {
	mut clean := trimmed_space(name)
	base, _, ok := generic_type_application_parts(clean)
	if ok {
		clean = base
	}
	return clean
}

fn interface_marker_matches(name string, target string) bool {
	clean := marker_type_name(name)
	target_clean := marker_type_name(target)
	return clean == target_clean || clean.all_after_last('.') == target_clean
		|| clean == target_clean.all_after_last('.')
}

pub fn (tc &TypeChecker) named_type_implements_marker(concrete_name string, target string) bool {
	mut name := trimmed_space(concrete_name)
	if name.starts_with('&') {
		name = trimmed_space(name[1..])
	}
	name = marker_type_name(name)
	mut candidates := [name]
	if !name.contains('.') {
		qname := tc.qualify_name(name)
		if qname != name {
			candidates << qname
		}
	} else if name.starts_with('main.') {
		candidates << name['main.'.len..]
	}
	for candidate in candidates {
		impls := tc.struct_implements[candidate] or { continue }
		for impl_name in impls {
			if interface_marker_matches(impl_name, target) {
				return true
			}
		}
	}
	return false
}

fn (tc &TypeChecker) type_has_compiler_default_clone(t Type) bool {
	if t is Struct {
		return tc.named_type_implements_marker(t.name, 'IClone')
	}
	return false
}

// interface_impl_names returns the concrete type names (structs and type
// aliases) that implement `iface_name`. Once a snapshot is frozen, its names
// stay first so transform-emitted interface IDs are preserved; later
// implementers are appended in deterministic discovery order.
pub fn (tc &TypeChecker) interface_impl_names(iface_name string) []string {
	mut cache := tc.type_cache
	if !isnil(cache) {
		if cached := cache.interface_impl_entries[iface_name] {
			return cached
		}
	}
	mut impls := []string{}
	if snapshot := tc.interface_impl_name_snapshots[iface_name] {
		impls = snapshot.clone()
		mut seen := map[string]bool{}
		for name in impls {
			seen[name] = true
		}
		// Generic monomorphization can add concrete implementers after the
		// transform has already emitted `_typ` literals. Preserve the earlier
		// ids, and append any later implementers so cgen can still box them.
		for name in tc.interface_impl_names_uncached_after(iface_name,
			tc.interface_impl_candidates_at_snapshot) {
			if name !in seen {
				seen[name] = true
				impls << name
			}
		}
	} else {
		impls = tc.interface_impl_names_uncached(iface_name)
	}
	if !isnil(cache) {
		// reserve also initializes zero-value maps in lightweight cache overlays.
		cache.interface_impl_entries.reserve(1)
		cache.interface_impl_entries[iface_name] = impls
	}
	return impls
}

// interface_type_ids returns the `_typ` dispatch IDs for an interface, preserving
// any snapshot IDs emitted before late generic implementers were discovered.
pub fn (tc &TypeChecker) interface_type_ids(iface_name string) map[string]int {
	if snapshot := tc.interface_impl_name_snapshots[iface_name] {
		return stable_interface_type_ids_preserving_prefix(snapshot,
			tc.interface_impl_names(iface_name))
	}
	return stable_interface_type_ids(tc.interface_impl_names(iface_name))
}

// freeze_interface_impl_names snapshots the interface implementation order used
// by transform-generated `_typ` checks before later metadata cleanup can remove
// unused generic declarations and shift cgen's ids.
pub fn (mut tc TypeChecker) freeze_interface_impl_names() {
	mut snapshots := map[string][]string{}
	for iface_name in tc.interface_names.keys() {
		snapshots[iface_name] = tc.interface_impl_names_uncached(iface_name)
	}
	tc.interface_impl_name_snapshots = snapshots.move()
	tc.interface_impl_candidates_at_snapshot = tc.interface_impl_candidate_names()
	// Earlier transform queries may have cached an implementer list before all
	// lowered method signatures were available. Cgen must rebuild from the frozen
	// snapshot so its dispatch table uses the same IDs as transformed interface boxes.
	tc.clear_interface_impl_cache()
}

fn (tc &TypeChecker) interface_impl_names_uncached(iface_name string) []string {
	return tc.interface_impl_names_uncached_after(iface_name, map[string]bool{})
}

fn add_interface_impl_candidate(mut candidates map[string]bool, name string, excluded map[string]bool) {
	if name !in excluded {
		candidates[name] = true
	}
}

fn (tc &TypeChecker) interface_impl_candidate_names() map[string]bool {
	mut candidates := map[string]bool{}
	for name in implicit_str_builtin_type_names() {
		candidates[name] = true
	}
	for name, _ in tc.structs {
		candidates[interface_impl_candidate_name(name)] = true
	}
	for name, _ in tc.enum_names {
		candidates[interface_impl_candidate_name(name)] = true
	}
	for name, target in tc.type_aliases {
		candidates[interface_impl_candidate_name(name)] = true
		typ := tc.parse_type(target)
		if typ is FnType {
			candidates[Type(typ).name()] = true
		}
	}
	for name, _ in tc.interface_names {
		candidates[name] = true
		short_name := interface_impl_candidate_name(name)
		if short_name != name {
			candidates[short_name] = true
		}
	}
	return candidates
}

fn (tc &TypeChecker) interface_impl_names_uncached_after(iface_name string, excluded map[string]bool) []string {
	mut candidate_set := map[string]bool{}
	has_no_requirements := tc.interface_has_no_requirements(iface_name)
	accepts_implicit_str := tc.interface_accepts_implicit_str(iface_name)
	if has_no_requirements || accepts_implicit_str {
		for name in implicit_str_builtin_type_names() {
			add_interface_impl_candidate(mut candidate_set, name, excluded)
		}
	}
	for name, _ in tc.structs {
		add_interface_impl_candidate(mut candidate_set, interface_impl_candidate_name(name),
			excluded)
	}
	if has_no_requirements || accepts_implicit_str {
		for name, _ in tc.enum_names {
			add_interface_impl_candidate(mut candidate_set, interface_impl_candidate_name(name),
				excluded)
		}
	}
	for name, target in tc.type_aliases {
		candidate_name := interface_impl_candidate_name(name)
		add_interface_impl_candidate(mut candidate_set, candidate_name, excluded)
		if has_no_requirements && candidate_name !in excluded {
			typ := tc.parse_type(target)
			if typ is FnType {
				add_interface_impl_candidate(mut candidate_set, Type(typ).name(), excluded)
			}
		}
	}
	for name, _ in tc.interface_names {
		if name != iface_name && tc.interface_implements_interface(name, iface_name) {
			add_interface_impl_candidate(mut candidate_set, name, excluded)
		}
		short_name := interface_impl_candidate_name(name)
		if short_name != name && short_name != iface_name
			&& tc.interface_implements_interface(name, iface_name) {
			add_interface_impl_candidate(mut candidate_set, short_name, excluded)
		}
	}
	mut candidates := candidate_set.keys()
	candidates.sort()
	mut impls := []string{}
	for name in candidates {
		if name in tc.interface_names {
			if tc.interface_implements_interface(name, iface_name) {
				impls << name
			}
			continue
		}
		resolved_name := tc.interface_metadata_name(name)
		if resolved_name in tc.interface_names {
			if tc.interface_implements_interface(resolved_name, iface_name) {
				impls << name
			}
			continue
		}
		if tc.named_type_implements_interface(name, iface_name) {
			impls << name
		}
	}
	return impls
}

// stable_interface_type_ids assigns deterministic nonzero `_typ` dispatch IDs to
// interface implementers in caller-supplied order. Hash collisions are resolved
// with linear probing after earlier names keep their IDs, so late generic
// implementers appended after transform cannot shift IDs already emitted for
// existing interface values/checks.
pub fn stable_interface_type_ids(impl_names []string) map[string]int {
	mut ids := map[string]int{}
	mut used := map[int]bool{}
	for name in impl_names {
		if name in ids {
			continue
		}
		mut id := stable_interface_type_id_hash(name)
		for used[id] {
			if id == 0x7fffffff {
				id = 1
			} else {
				id++
			}
		}
		used[id] = true
		ids[name] = id
	}
	return ids
}

// stable_interface_type_ids_preserving_prefix assigns IDs for `impl_names` while
// keeping all prefix IDs exactly as they would be when assigned alone.
pub fn stable_interface_type_ids_preserving_prefix(prefix []string, impl_names []string) map[string]int {
	mut ids := stable_interface_type_ids(prefix)
	mut used := map[int]bool{}
	mut seen := map[string]bool{}
	for name, id in ids {
		used[id] = true
		seen[name] = true
	}
	mut late_names := []string{}
	for name in impl_names {
		if name in seen {
			continue
		}
		seen[name] = true
		late_names << name
	}
	late_names.sort()
	assign_stable_interface_type_ids(mut ids, mut used, late_names)
	return ids
}

fn assign_stable_interface_type_ids(mut ids map[string]int, mut used map[int]bool, names []string) {
	for name in names {
		if name in ids {
			continue
		}
		mut id := stable_interface_type_id_hash(name)
		for used[id] {
			if id == 0x7fffffff {
				id = 1
			} else {
				id++
			}
		}
		used[id] = true
		ids[name] = id
	}
}

// interface_impl_set_signature returns the complete deterministic interface implementer set
// that controls collision-resolved dispatch IDs for the current program.
pub fn (tc &TypeChecker) interface_impl_set_signature() string {
	mut iface_names := tc.interface_names.keys()
	iface_names.sort()
	mut lines := []string{cap: iface_names.len}
	for iface_name in iface_names {
		impl_names := if iface_name in ['IError', 'builtin.IError'] {
			tc.ierror_impl_names()
		} else {
			tc.interface_impl_names(iface_name)
		}
		lines << '${iface_name}=${impl_names.join(',')}'
	}
	return lines.join('\n')
}

// interface_concrete_method_keys returns generated interface dispatch methods and
// concrete method declarations that can be called by those dispatch functions.
pub fn (tc &TypeChecker) interface_concrete_method_keys() []string {
	mut iface_names := tc.interface_names.keys()
	iface_names.sort()
	mut keys := []string{}
	mut seen := map[string]bool{}
	for iface_name in iface_names {
		impl_names := if iface_name in ['IError', 'builtin.IError'] {
			tc.ierror_impl_names()
		} else {
			tc.interface_impl_names(iface_name)
		}
		for method in tc.interface_abstract_method_names(iface_name) {
			dispatch_key := '${iface_name}.${method}'
			if dispatch_key !in seen {
				seen[dispatch_key] = true
				keys << dispatch_key
			}
			for concrete_name in impl_names {
				key := tc.concrete_method_signature_key(concrete_name, method) or { continue }
				if key !in seen {
					seen[key] = true
					keys << key
				}
			}
		}
	}
	keys.sort()
	return keys
}

fn stable_interface_type_id_hash(name string) int {
	mut hash := u32(2166136261)
	for c in name.bytes() {
		hash = (hash ^ u32(c)) * u32(16777619)
	}
	id := int(hash & u32(0x7fffffff))
	return if id == 0 { 1 } else { id }
}

// stable_type_index returns the deterministic nonzero runtime-index seed for a named type.
// Use stable_type_indexes when assigning indexes across a complete program type set.
pub fn stable_type_index(name string) int {
	mut type_idx := stable_interface_type_id_hash(name) & ~(0xff << 16)
	if type_idx < 65536 {
		// Bit 24 is the first available bit above the reserved indirection byte.
		type_idx |= 1 << 24
	}
	return type_idx
}

// stable_type_indexes assigns deterministic, collision-free runtime indexes to
// the complete caller-supplied program type set.
pub fn stable_type_indexes(type_names []string) map[string]int {
	mut indexes := map[string]int{}
	mut used := map[int]bool{}
	mut names := type_names.clone()
	names.sort()
	for raw_name in names {
		name := raw_name.trim_space()
		if name.len == 0 || name in indexes {
			continue
		}
		mut type_idx := stable_type_index(name)
		for used[type_idx] {
			type_idx = next_stable_type_index(type_idx)
		}
		indexes[name] = type_idx
		used[type_idx] = true
	}
	return indexes
}

// extend_stable_type_indexes assigns deterministic, collision-free runtime indexes
// to new names without changing indexes that have already been used during lowering.
pub fn extend_stable_type_indexes(mut indexes map[string]int, type_names []string) {
	extend_stable_type_indexes_ref(mut indexes, &type_names)
}

// extend_stable_type_indexes_ref is the pointer-ABI form used by native compiler stages.
pub fn extend_stable_type_indexes_ref(mut indexes map[string]int, type_names &[]string) {
	mut used := map[int]bool{}
	for _, type_idx in indexes {
		used[type_idx] = true
	}
	mut names := type_names.clone()
	names.sort()
	for raw_name in names {
		name := trimmed_space(raw_name)
		if name.len == 0 || name in indexes {
			continue
		}
		mut type_idx := stable_type_index(name)
		for used[type_idx] {
			type_idx = next_stable_type_index(type_idx)
		}
		indexes[name] = type_idx
		used[type_idx] = true
	}
}

fn next_stable_type_index(type_idx int) int {
	if type_idx & 0xffff < 0xffff {
		return type_idx + 1
	}
	high_bits := type_idx & 0x7f000000
	return if high_bits < 0x7f000000 { high_bits + (1 << 24) } else { 1 << 24 }
}

// runtime_type_index_names returns the canonical program type names that can
// participate in runtime interface/sum type_idx() lowering.
pub fn (tc &TypeChecker) runtime_type_index_names() []string {
	mut names := map[string]bool{}
	for name, _ in tc.structs {
		names[name] = true
	}
	for name, variants in tc.sum_types {
		names[name] = true
		for variant in variants {
			names[variant] = true
		}
	}
	for name, _ in tc.enum_names {
		names[name] = true
	}
	for name, _ in tc.type_aliases {
		names[name] = true
	}
	for name, _ in tc.interface_names {
		names[name] = true
	}
	for _, index in tc.interface_impl_indexes {
		for name in index.names {
			names[name] = true
		}
	}
	return names.keys()
}

pub fn (tc &TypeChecker) interface_accepts_implicit_str(iface_name string) bool {
	for method in tc.interface_abstract_method_names(iface_name) {
		if method != 'str' {
			continue
		}
		expected_key := tc.interface_method_signature_key(iface_name, method) or {
			'${iface_name}.${method}'
		}
		if tc.interface_method_is_str_requirement(expected_key) {
			return true
		}
	}
	return false
}

fn implicit_str_builtin_type_names() []string {
	return ['bool', 'int', 'i8', 'i16', 'i32', 'i64', 'isize', 'usize', 'u8', 'byte', 'u16', 'u32',
		'u64', 'f32', 'f64', 'string', 'rune']
}

fn interface_impl_candidate_name(name string) string {
	if name.starts_with('builtin.') {
		return name['builtin.'.len..]
	}
	return name
}

// ierror_impl_names returns the concrete struct names that can be boxed as `IError`.
pub fn (tc &TypeChecker) ierror_impl_names() []string {
	if tc.type_cache != unsafe { nil } {
		mut cache := unsafe { tc.type_cache }
		if cache.ierror_impl_names_set {
			return cache.ierror_impl_names.clone()
		}
		mut fallback := cache.base
		for !isnil(fallback) {
			if fallback.ierror_impl_names_set {
				return fallback.ierror_impl_names.clone()
			}
			fallback = fallback.base
		}
	}
	mut struct_names := []string{}
	for name, _ in tc.structs {
		struct_names << name
	}
	struct_names.sort()
	mut impls := []string{}
	for name in struct_names {
		if tc.named_type_compatible_with_ierror(name) {
			impls << name
		}
	}
	if tc.type_cache != unsafe { nil } {
		mut cache := unsafe { tc.type_cache }
		cache.ierror_impl_names = impls.clone()
		cache.ierror_impl_names_set = true
	}
	return impls
}

pub fn (tc &TypeChecker) concrete_method_signature_key(concrete_name string, method string) ?string {
	mut seen_aliases := map[string]bool{}
	return tc.concrete_method_signature_key_seen(concrete_name, method, mut seen_aliases)
}

fn (tc &TypeChecker) concrete_method_signature_key_seen(concrete_name string, method string, mut seen_aliases map[string]bool) ?string {
	if seen_aliases[concrete_name] {
		return none
	}
	seen_aliases[concrete_name] = true
	key := '${concrete_name}.${method}'
	if key in tc.fn_param_types || key in tc.fn_ret_types {
		return key
	}
	qualified_name := tc.qualify_name(concrete_name)
	if concrete_name !in tc.type_aliases && qualified_name != concrete_name {
		qualified_key := '${qualified_name}.${method}'
		if qualified_key in tc.fn_param_types || qualified_key in tc.fn_ret_types {
			return qualified_key
		}
	}
	// The current module can make parse_type(`Connection`) select the imported
	// `orm.Connection` interface even when the implementation candidate is a
	// same-named alias from another module. Consult the alias table by its
	// collected concrete name before doing suffix-based method lookup.
	for alias_name in [concrete_name, qualified_name] {
		if alias_target := tc.type_aliases[alias_name] {
			if alias_target != alias_name && alias_target != concrete_name {
				if inherited := tc.concrete_method_signature_key_seen(alias_target, method, mut
					seen_aliases)
				{
					return inherited
				}
			}
		}
	}
	receiver_type := tc.parse_type(concrete_name)
	receiver_candidates := receiver_method_name_candidates(receiver_type, method, tc.cur_module)
	// Prefer a method declared directly on the alias when one exists, but do not
	// let an unqualified alias name resolve through the suffix index to an
	// unrelated interface with the same name. Aliases otherwise inherit the
	// methods of their base type.
	for candidate in receiver_candidates {
		if candidate in tc.fn_param_types || candidate in tc.fn_ret_types {
			return candidate
		}
	}
	if receiver_type is Alias {
		for candidate in receiver_method_name_candidates(receiver_type.base_type, method,
			tc.cur_module) {
			if candidate in tc.fn_param_types || candidate in tc.fn_ret_types {
				return candidate
			}
			if indexed := tc.receiver_method_suffix_index[candidate] {
				if indexed != receiver_method_suffix_ambiguous {
					return indexed
				}
			}
		}
	}
	for candidate in receiver_candidates {
		if indexed := tc.receiver_method_suffix_index[candidate] {
			if indexed != receiver_method_suffix_ambiguous {
				return indexed
			}
		}
	}
	for candidate in tc.concrete_generic_method_signature_candidates(concrete_name, method) {
		if candidate in tc.fn_param_types || candidate in tc.fn_ret_types {
			return candidate
		}
		if indexed := tc.receiver_method_suffix_index[candidate] {
			if indexed != receiver_method_suffix_ambiguous {
				return indexed
			}
		}
	}
	if indexed := tc.receiver_method_suffix_index[key] {
		if indexed != receiver_method_suffix_ambiguous {
			return indexed
		}
	}
	if info := tc.embedded_method_call_info(concrete_name, method) {
		if info.name.len > 0 {
			return info.name
		}
	}
	return none
}

fn (tc &TypeChecker) concrete_generic_method_signature_candidates(concrete_name string, method string) []string {
	base, args, ok := generic_type_application_parts(concrete_name)
	if !ok || args.len == 0 || method.len == 0 {
		return []string{}
	}
	short_args := generic_type_args_short_for_signature(args)
	suffix := generic_type_suffix_for_signature(args)
	short_base := base.all_after_last('.')
	mut candidates := []string{}
	for receiver in [base, short_base] {
		candidates << '${receiver}[${short_args}].${method}'
		candidates << '${receiver}_${suffix}.${method}'
		candidates << tc.cached_c_name('${receiver}[${short_args}].${method}')
		candidates << tc.cached_c_name('${receiver}_${suffix}.${method}')
		candidates << '${tc.cached_c_name(receiver)}_${suffix}__${tc.cached_c_name(method)}'
	}
	return candidates
}

fn generic_type_args_short_for_signature(args []string) string {
	mut parts := []string{cap: args.len}
	for arg in args {
		parts << generic_type_arg_short_for_signature(arg)
	}
	return parts.join(', ')
}

fn generic_type_suffix_for_signature(args []string) string {
	mut parts := []string{cap: args.len}
	for arg in args {
		parts << naming.c_name(generic_type_arg_short_for_signature(arg).replace('[]', 'Array_').replace('&',
			'ptr_'))
	}
	return parts.join('_')
}

fn generic_type_arg_short_for_signature(type_arg string) string {
	clean := trimmed_space(type_arg)
	if clean.starts_with('[]') {
		return 'Array_${generic_type_arg_short_for_signature(clean[2..])}'
	}
	if clean.starts_with('&') {
		return 'ptr_${generic_type_arg_short_for_signature(clean[1..])}'
	}
	if clean.starts_with('map[') {
		bracket_end := find_matching_bracket(clean, 3)
		if bracket_end < clean.len - 1 {
			key := generic_type_arg_short_for_signature(clean[4..bracket_end])
			value := generic_type_arg_short_for_signature(clean[bracket_end + 1..])
			return 'Map_${key}_${value}'
		}
	}
	if clean.starts_with('?') {
		return 'Option_${generic_type_arg_short_for_signature(clean[1..])}'
	}
	if clean.starts_with('!') {
		return 'Result_${generic_type_arg_short_for_signature(clean[1..])}'
	}
	if clean.contains('.') {
		return clean
	}
	return clean
}

pub fn (tc &TypeChecker) named_type_compatible_with_ierror(concrete_name string) bool {
	cache_key := tc.ierror_compat_cache_key(concrete_name)
	if tc.type_cache != unsafe { nil } {
		mut cache := unsafe { tc.type_cache }
		mut fallback := cache.base
		for !isnil(fallback) {
			if cached := fallback.ierror_compat_entries[cache_key] {
				return cached > 0
			}
			fallback = fallback.base
		}
		if cached := cache.ierror_compat_entries[cache_key] {
			return cached > 0
		}
	}
	mut seen := map[string]bool{}
	result := tc.named_type_compatible_with_ierror_inner(concrete_name, mut seen)
	if tc.type_cache != unsafe { nil } {
		mut cache := unsafe { tc.type_cache }
		cache.ierror_compat_entries[cache_key] = if result { 1 } else { -1 }
	}
	return result
}

fn (tc &TypeChecker) ierror_compat_cache_key(concrete_name string) string {
	if concrete_name in ['Error', 'MessageError'] {
		return '${tc.cur_file}\n${tc.cur_module}\n${concrete_name}'
	}
	if concrete_name in tc.structs {
		return concrete_name
	}
	qname := tc.qualify_name(concrete_name)
	if qname in tc.structs {
		return qname
	}
	return concrete_name
}

// resolve_ierror_payload_name resolves scoped `Error`/`MessageError` names before
// falling back to the builtin error structs.
pub fn (tc &TypeChecker) resolve_ierror_payload_name(name string) string {
	if name !in ['Error', 'MessageError'] {
		return name
	}
	if resolved := tc.resolve_selective_import_type_symbol(name) {
		if resolved in tc.structs {
			return resolved
		}
	}
	if tc.cur_module.len > 0 && tc.cur_module != 'main' && tc.cur_module != 'builtin' {
		local := '${tc.cur_module}.${name}'
		if local in tc.structs {
			return local
		}
	}
	return name
}

fn (tc &TypeChecker) type_compatible_with_ierror_payload(actual Type) bool {
	clean := tc.ierror_payload_concrete_type(actual)
	concrete_name := method_type_name(clean)
	if concrete_name.len == 0 {
		return false
	}
	return tc.named_type_compatible_with_ierror(concrete_name)
}

fn (tc &TypeChecker) ierror_payload_concrete_type(t Type) Type {
	mut clean := t
	mut seen := map[string]bool{}
	for {
		clean = unwrap_pointer(clean)
		if clean is Alias {
			if seen[clean.name] {
				return clean
			}
			seen[clean.name] = true
			clean = clean.base_type
			continue
		}
		return clean
	}
	return clean
}

fn (tc &TypeChecker) named_type_compatible_with_ierror_inner(concrete_name string, mut seen map[string]bool) bool {
	mut lookup := tc.resolve_ierror_payload_name(concrete_name)
	if lookup !in tc.structs {
		qname := tc.qualify_name(lookup)
		if qname in tc.structs {
			lookup = qname
		}
	}
	if lookup in ['Error', 'MessageError'] && tc.unqualified_type_name_shadows_builtin(lookup) {
		return false
	}
	if lookup in seen {
		return false
	}
	seen[lookup] = true
	if tc.is_builtin_error_struct_name(lookup) {
		return true
	}
	if tc.named_type_has_non_builtin_error_embed(lookup) {
		return false
	}
	if tc.named_type_implements_ierror_methods(lookup) {
		return true
	}
	struct_module := tc.struct_modules[lookup] or { tc.cur_module }
	struct_file := tc.struct_files[lookup] or { tc.cur_file }
	for field in tc.structs[lookup] or { []StructField{} } {
		embedded_type := embedded_field_type(field) or { continue }
		embedded_name := method_type_name(unwrap_pointer(embedded_type))
		if embedded_name.len == 0 {
			continue
		}
		if tc.embedded_field_is_scoped_builtin_error(field, embedded_name, struct_file,
			struct_module)
		{
			return true
		}
		if embedded_name in ['Error', 'MessageError'] && field.name == embedded_name {
			continue
		}
		if tc.is_builtin_error_struct_name(embedded_name) {
			return true
		}
		if tc.named_type_compatible_with_ierror_inner(embedded_name, mut seen) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) named_type_implements_ierror_methods(concrete_name string) bool {
	iface_name := if 'builtin.IError' in tc.interface_names { 'builtin.IError' } else { 'IError' }
	return tc.named_type_implements_interface(concrete_name, iface_name)
}

fn (tc &TypeChecker) named_type_has_non_builtin_error_embed(concrete_name string) bool {
	mut lookup := concrete_name
	if lookup !in tc.structs {
		qname := tc.qualify_name(lookup)
		if qname in tc.structs {
			lookup = qname
		}
	}
	if tc.struct_error_embeds_shadow_builtin[lookup] {
		return true
	}
	struct_module := tc.struct_modules[lookup] or { tc.cur_module }
	struct_file := tc.struct_files[lookup] or { tc.cur_file }
	if tc.source_struct_has_non_builtin_error_embed(lookup, struct_file, struct_module) {
		return true
	}
	for field in tc.structs[lookup] or { []StructField{} } {
		if field.name in ['Error', 'MessageError']
			&& tc.unqualified_type_name_shadows_builtin_in_scope(field.name, struct_file, struct_module) {
			return true
		}
		embedded_type := embedded_field_type(field) or { continue }
		embedded_name := method_type_name(unwrap_pointer(embedded_type))
		if embedded_name.len == 0 {
			continue
		}
		if tc.embedded_field_is_scoped_builtin_error(field, embedded_name, struct_file,
			struct_module)
		{
			continue
		}
		if embedded_name in ['Error', 'MessageError'] && field.name == embedded_name {
			return true
		}
		if embedded_name.all_after_last('.') in ['Error', 'MessageError']
			&& !tc.is_builtin_error_struct_name(embedded_name) {
			return true
		}
	}
	return false
}

fn (tc &TypeChecker) source_struct_has_non_builtin_error_embed(concrete_name string, file string, mod_name string) bool {
	if isnil(tc.a) {
		return false
	}
	key := source_error_embed_lookup_key(concrete_name, file, mod_name)
	if tc.type_cache != unsafe { nil } {
		mut cache := unsafe { tc.type_cache }
		if !cache.source_error_embed_indexed {
			mut fallback := cache.base
			for !isnil(fallback) {
				if fallback.source_error_embed_indexed {
					return fallback.source_error_embed_entries[key] > 0
				}
				fallback = fallback.base
			}
			cache.source_error_embed_entries = tc.collect_source_error_embed_entries()
			cache.source_error_embed_indexed = true
		}
		return cache.source_error_embed_entries[key] > 0
	}
	entries := tc.collect_source_error_embed_entries()
	return entries[key] > 0
}

// precompute_source_error_embed_index builds the immutable source-error embedding
// index once before parallel consumers fork their private memoization overlays.
pub fn (tc &TypeChecker) precompute_source_error_embed_index() {
	if isnil(tc.type_cache) {
		return
	}
	mut cache := unsafe { tc.type_cache }
	if cache.source_error_embed_indexed {
		return
	}
	mut fallback := cache.base
	for !isnil(fallback) {
		if fallback.source_error_embed_indexed {
			return
		}
		fallback = fallback.base
	}
	cache.source_error_embed_entries = tc.collect_source_error_embed_entries()
	cache.source_error_embed_indexed = true
}

fn (tc &TypeChecker) collect_source_error_embed_entries() map[string]int {
	mut entries := map[string]int{}
	if isnil(tc.a) {
		return entries
	}
	mut cur_file := ''
	mut cur_module := ''
	if tc.top_level_idx.len > 0 && tc.a.nodes.len == tc.top_level_idx_nodes_len {
		// struct_decl nodes only occur at the top level, and the AST has not
		// grown since collect built the index.
		for i in tc.top_level_idx {
			node := tc.a.nodes[i]
			match node.kind {
				.file {
					cur_file = node.value
					cur_module = ''
				}
				.module_decl {
					cur_module = node.value
				}
				.struct_decl {
					if !tc.source_struct_decl_has_non_builtin_error_embed(node, cur_file,
						cur_module) {
						continue
					}
					target := node.value.all_after_last('.')
					module_key := source_error_embed_module_key(cur_module)
					entries[source_error_embed_entry_key(target, '', module_key)] = 1
					entries[source_error_embed_entry_key(target, cur_file, module_key)] = 1
				}
				else {}
			}
		}
		return entries
	}
	for node in tc.a.nodes {
		match node.kind {
			.file {
				cur_file = node.value
				cur_module = ''
			}
			.module_decl {
				cur_module = node.value
			}
			.struct_decl {
				if !tc.source_struct_decl_has_non_builtin_error_embed(node, cur_file, cur_module) {
					continue
				}
				target := node.value.all_after_last('.')
				module_key := source_error_embed_module_key(cur_module)
				entries[source_error_embed_entry_key(target, '', module_key)] = 1
				entries[source_error_embed_entry_key(target, cur_file, module_key)] = 1
			}
			else {}
		}
	}
	return entries
}

fn (tc &TypeChecker) source_struct_decl_has_non_builtin_error_embed(node flat.Node, cur_file string, cur_module string) bool {
	for i in 0 .. node.children_count {
		field := tc.a.child_node(&node, i)
		if field.kind != .field_decl {
			continue
		}
		field_typ := if field.typ.len > 0 { field.typ } else { field.value }
		if !source_field_decl_is_embed(field, field_typ) {
			continue
		}
		if field_typ in ['Error', 'MessageError']
			&& tc.unqualified_type_name_shadows_builtin_in_scope(field_typ, cur_file, cur_module) {
			return true
		}
		resolved := tc.resolve_imported_type_text_in_file(field_typ, cur_file)
		if resolved.all_after_last('.') in ['Error', 'MessageError']
			&& !tc.is_builtin_error_struct_name_in_scope(resolved, cur_file, cur_module) {
			return true
		}
	}
	return false
}

fn source_error_embed_lookup_key(concrete_name string, file string, mod_name string) string {
	target := concrete_name.all_after_last('.')
	target_module := if concrete_name.contains('.') {
		concrete_name.all_before_last('.')
	} else {
		mod_name
	}
	file_key := if target_module.len > 0 { '' } else { file }
	return source_error_embed_entry_key(target, file_key,
		source_error_embed_module_key(target_module))
}

fn source_error_embed_entry_key(target string, file string, module_key string) string {
	return '${file}\n${module_key}\n${target}'
}

fn source_error_embed_module_key(mod_name string) string {
	return if mod_name == 'main' { '' } else { mod_name }
}

fn source_field_decl_is_embed(field flat.Node, field_typ string) bool {
	return field.typ.len == 0 || field.value.len == 0 || field.value == field_typ
		|| (field_typ.contains('.') && field.value == field_typ.all_after_last('.'))
}

fn (tc &TypeChecker) embedded_field_is_scoped_builtin_error(field StructField, embedded_name string, struct_file string, struct_module string) bool {
	if embedded_name !in ['Error', 'MessageError'] || field.name != embedded_name {
		return false
	}
	return !tc.unqualified_type_name_shadows_builtin_in_scope(embedded_name, struct_file,
		struct_module)
}

fn (tc &TypeChecker) resolve_unqualified_builtin_error_struct_name(name string) ?string {
	if name !in ['Error', 'MessageError'] {
		return none
	}
	if tc.unqualified_type_name_shadows_builtin(name) {
		return none
	}
	if mod_name := tc.struct_modules[name] {
		if mod_name == 'builtin' {
			return name
		}
	}
	if tc.has_builtins {
		return name
	}
	return none
}

fn (tc &TypeChecker) unqualified_type_name_shadows_builtin(name string) bool {
	return tc.unqualified_type_name_shadows_builtin_in_scope(name, tc.cur_file, tc.cur_module)
}

fn (tc &TypeChecker) unqualified_type_name_shadows_builtin_in_scope(name string, file string, mod_name string) bool {
	local_name := if mod_name.len > 0 && mod_name !in ['', 'main', 'builtin'] {
		'${mod_name}.${name}'
	} else {
		name
	}
	if local_name == name && mod_name != 'builtin'
		&& tc.source_declares_type_in_scope(name, file, mod_name) {
		return true
	}
	if local_name != name && tc.type_symbol_known(local_name) {
		return true
	}
	if file_import_key(file, name) in tc.file_selective_imports {
		if resolved := tc.resolve_selective_import_type_symbol_in_file(name, file) {
			return !tc.is_builtin_error_struct_name(resolved)
		}
		return true
	}
	if local_name != name {
		return false
	}
	if name in tc.structs {
		return tc.struct_modules[name] or { '' } != 'builtin'
	}
	if name in tc.type_aliases || name in tc.sum_types || name in tc.interface_names
		|| name in tc.enum_names {
		return true
	}
	return false
}

fn (tc &TypeChecker) source_declares_type_in_scope(name string, file string, mod_name string) bool {
	if file.len == 0 || isnil(tc.a) {
		return false
	}
	return scope_type_key(file, mod_name, name) in tc.declared_type_scope_keys
}

// scope_type_key builds the lookup key used by `declared_type_scope_keys`.
// The module is normalized so that '' and 'main' collapse to the same bucket,
// matching the old `module_names_match` semantics.
fn scope_type_key(file string, mod_name string, name string) string {
	norm_mod := if mod_name == '' || mod_name == 'main' { 'main' } else { mod_name }
	return '${file}\x01${norm_mod}\x01${name}'
}

fn (tc &TypeChecker) resolve_selective_import_type_symbol_in_file(name string, file string) ?string {
	candidates := tc.file_selective_imports[file_import_key(file, name)] or { return none }
	for candidate in candidates {
		if tc.type_symbol_known(candidate) {
			return candidate
		}
	}
	return none
}

pub fn (tc &TypeChecker) resolve_imported_type_text_in_file(typ string, file string) string {
	if !typ.contains('.') || typ.starts_with('C.') {
		return typ
	}
	dot := typ.index_u8(`.`)
	if dot <= 0 {
		return typ
	}
	alias := typ[..dot]
	if resolved := tc.file_imports[file_import_key(file, alias)] {
		if resolved != alias {
			return resolved + typ[dot..]
		}
	}
	return typ
}

fn (tc &TypeChecker) is_builtin_error_struct_name(name string) bool {
	return tc.is_builtin_error_struct_name_in_scope(name, tc.cur_file, tc.cur_module)
}

fn (tc &TypeChecker) is_builtin_error_struct_name_in_scope(name string, file string, mod_name string) bool {
	if name in ['builtin.Error', 'builtin.MessageError'] {
		return true
	}
	if name in ['Error', 'MessageError'] {
		if tc.unqualified_type_name_shadows_builtin_in_scope(name, file, mod_name) {
			return false
		}
		if mod := tc.struct_modules[name] {
			if mod == 'builtin' {
				return true
			}
		}
		return tc.has_builtins
	}
	return false
}

// prepare_interface_query_indexes publishes immutable interface requirements for
// transform workers. Interface declarations no longer change after semantic
// checking, so compatibility scans can reuse these lists safely across threads.
pub fn (mut tc TypeChecker) prepare_interface_requirement_indexes() {
	tc.interface_query_indexes_ready = false
	tc.interface_method_names_index = map[string][]string{}
	tc.interface_abstract_index = map[string][]string{}
	tc.interface_field_list_index = map[string][]StructField{}
	for iface_name in tc.interface_names.keys() {
		mut seen_methods := map[string]bool{}
		methods := tc.interface_method_names_inner(iface_name, mut seen_methods)
		mut seen_abstract := map[string]bool{}
		abstract_methods := tc.interface_abstract_method_names_inner(iface_name, mut seen_abstract)
		mut seen_fields := map[string]bool{}
		fields := tc.interface_field_list_inner(iface_name, mut seen_fields)
		resolved := tc.interface_metadata_name(iface_name)
		for key in [iface_name, resolved] {
			if key.len == 0 {
				continue
			}
			tc.interface_method_names_index[key] = methods
			tc.interface_abstract_index[key] = abstract_methods
			tc.interface_field_list_index[key] = fields
		}
	}
	tc.interface_query_indexes_ready = true
}

// prepare_interface_query_indexes publishes immutable interface requirements and
// implementer lists for transform workers.
pub fn (mut tc TypeChecker) prepare_interface_query_indexes() {
	tc.prepare_interface_requirement_indexes()
	tc.interface_impl_indexes = map[string]&InterfaceImplIndex{}
	for iface_name in tc.interface_names.keys() {
		impls := if is_builtin_ierror_name(iface_name) {
			tc.ierror_impl_names()
		} else {
			tc.interface_impl_names(iface_name)
		}
		tc.interface_impl_indexes[iface_name] = &InterfaceImplIndex{
			names: impls
			ids:   stable_interface_type_ids(impls)
		}
	}
	// The immutable transform indexes above preserve the pre-monomorphization
	// order. Do not leave the same lists in the mutable query cache: generic
	// materialization can add implementers before cgen queries it again.
	tc.clear_interface_impl_cache()
}

// interface_method_names supports interface method names handling for TypeChecker.
fn (tc &TypeChecker) interface_method_names(iface_name string) []string {
	if tc.interface_query_indexes_ready {
		if methods := tc.interface_method_names_index[iface_name] {
			return methods
		}
	}
	mut seen := map[string]bool{}
	return tc.interface_method_names_inner(iface_name, mut seen)
}

// interface_abstract_method_names returns the methods an implementer must provide:
// the interface's own declared (abstract) methods plus those of any embedded
// interfaces. Default methods defined directly on the interface are excluded.
pub fn (tc &TypeChecker) interface_abstract_method_names(iface_name string) []string {
	if tc.interface_query_indexes_ready {
		if methods := tc.interface_abstract_index[iface_name] {
			return methods
		}
	}
	mut seen := map[string]bool{}
	return tc.interface_abstract_method_names_inner(iface_name, mut seen)
}

// interface_abstract_method_names_inner supports interface_abstract_method_names_inner handling.
fn (tc &TypeChecker) interface_abstract_method_names_inner(iface_name string, mut seen map[string]bool) []string {
	name := tc.interface_metadata_name(iface_name)
	if name in seen {
		return []string{}
	}
	seen[name] = true
	mut methods := []string{}
	for embed in tc.interface_embeds[name] or { []string{} } {
		for method in tc.interface_abstract_method_names_inner(embed, mut seen) {
			if method !in methods {
				methods << method
			}
		}
	}
	for method in tc.interface_abstract_methods[name] or { []string{} } {
		if method !in methods {
			methods << method
		}
	}
	return methods
}

// interface_method_names_inner supports interface method names inner handling for TypeChecker.
fn (tc &TypeChecker) interface_method_names_inner(iface_name string, mut seen map[string]bool) []string {
	name := tc.interface_metadata_name(iface_name)
	if name in seen {
		return []string{}
	}
	seen[name] = true
	mut methods := []string{}
	for embed in tc.interface_embeds[name] or { []string{} } {
		for method in tc.interface_method_names_inner(embed, mut seen) {
			if method !in methods {
				methods << method
			}
		}
	}
	prefix := '${name}.'
	for key, _ in tc.fn_ret_types {
		if key.starts_with(prefix) {
			method := key[prefix.len..]
			if method !in methods {
				methods << method
			}
		}
	}
	return methods
}

pub fn (tc &TypeChecker) interface_method_signature_key(iface_name string, method string) ?string {
	name := tc.interface_metadata_name(iface_name)
	key := '${name}.${method}'
	if key in tc.fn_ret_types || key in tc.fn_param_types {
		return key
	}
	for embed in tc.interface_embeds[name] or { []string{} } {
		if found := tc.interface_method_signature_key(embed, method) {
			return found
		}
	}
	return none
}

fn (tc &TypeChecker) interface_receiver_method_call_info(iface_name string, method string) ?CallInfo {
	if iface_name !in tc.interface_names {
		return none
	}
	decl_key := tc.interface_method_signature_key(iface_name, method) or { return none }
	decl_params := tc.fn_param_types[decl_key] or { return none }
	mut params := []Type{cap: decl_params.len}
	params << Type(Pointer{
		base_type: Type(Interface{
			name: iface_name
		})
	})
	if decl_params.len > 1 {
		for i in 1 .. decl_params.len {
			params << decl_params[i]
		}
	}
	call_name := '${iface_name}.${method}'
	return CallInfo{
		name:          call_name
		params:        params
		shared_params: tc.fn_shared_params[decl_key] or { []bool{} }
		return_type:   tc.fn_ret_types[decl_key] or { Type(void_) }
		has_receiver:  true
		params_known:  true
	}
}

// interface_field_list supports interface field list handling for TypeChecker.
pub fn (tc &TypeChecker) interface_field_list(iface_name string) []StructField {
	if tc.interface_query_indexes_ready {
		if fields := tc.interface_field_list_index[iface_name] {
			return fields
		}
	}
	mut seen := map[string]bool{}
	return tc.interface_field_list_inner(iface_name, mut seen)
}

// interface_field_list_inner supports interface field list inner handling for TypeChecker.
fn (tc &TypeChecker) interface_field_list_inner(iface_name string, mut seen map[string]bool) []StructField {
	name := tc.interface_metadata_name(iface_name)
	if name in seen {
		return []StructField{}
	}
	seen[name] = true
	mut fields := []StructField{}
	mut field_indexes := map[string]int{}
	for embed in tc.interface_embeds[name] or { []string{} } {
		for field in tc.interface_field_list_inner(embed, mut seen) {
			if idx := field_indexes[field.name] {
				fields[idx] = field
			} else {
				field_indexes[field.name] = fields.len
				fields << field
			}
		}
	}
	for field in tc.interface_fields[name] or { []StructField{} } {
		if idx := field_indexes[field.name] {
			fields[idx] = field
		} else {
			field_indexes[field.name] = fields.len
			fields << field
		}
	}
	return fields
}

// interface_field_type supports interface field type handling for TypeChecker.
fn (tc &TypeChecker) interface_field_type(iface_name string, field_name string) ?Type {
	for field in tc.interface_field_list(iface_name) {
		if field.name == field_name {
			return field.typ
		}
	}
	return none
}

// struct_field_type supports struct field type handling for TypeChecker.
fn (tc &TypeChecker) struct_init_field_lookup_name(literal_name string, parsed_name string) string {
	clean := trimmed_space(literal_name)
	if clean.len == 0 {
		return parsed_name
	}
	if generic_type_application(clean) {
		_, _, parsed_is_generic := generic_type_application_parts(parsed_name)
		if parsed_is_generic {
			return parsed_name
		}
		bracket := clean.index_u8(`[`)
		if bracket > 0 {
			base := if parsed_name.len > 0 { parsed_name } else { trimmed_space(clean[..bracket]) }
			return base + clean[bracket..]
		}
	}
	if parsed_name.len > 0 {
		return parsed_name
	}
	return clean
}

fn (tc &TypeChecker) struct_fields_for_init(struct_name string) []StructField {
	base_name, generic_args, is_generic := generic_type_application_parts(struct_name)
	raw_lookup_name := if is_generic { base_name } else { struct_name }
	lookup_name := if raw_lookup_name in tc.structs {
		raw_lookup_name
	} else if raw_lookup_name.all_after_last('.') in tc.structs {
		raw_lookup_name.all_after_last('.')
	} else {
		raw_lookup_name
	}
	fields := tc.structs[lookup_name] or { return []StructField{} }
	if !is_generic {
		return fields
	}
	params := tc.struct_generic_params[lookup_name] or {
		tc.struct_generic_params[base_name] or { return fields }
	}
	if params.len != generic_args.len {
		return fields
	}
	mut concrete_fields := []StructField{cap: fields.len}
	for field in fields {
		concrete_fields << StructField{
			name:        field.name
			typ:         tc.substitute_generic_type(field.typ, generic_args, params)
			has_default: field.has_default
			is_embed:    field.is_embed
			is_mut:      field.is_mut
		}
	}
	return concrete_fields
}

// struct_fields_for_type returns the fields of `struct_name`, with generic
// parameters substituted when `struct_name` is a concrete generic instance.
pub fn (tc &TypeChecker) struct_fields_for_type(struct_name string) []StructField {
	return tc.struct_fields_for_init(struct_name)
}

fn (tc &TypeChecker) struct_field_type(struct_name string, field_name string) ?Type {
	cache_key := '${struct_name}\n${field_name}'
	if !isnil(tc.type_cache) {
		mut fallback := tc.type_cache.base
		for !isnil(fallback) {
			if typ := fallback.struct_field_entries[cache_key] {
				return typ
			}
			if fallback.struct_field_misses[cache_key] {
				return none
			}
			fallback = fallback.base
		}
		if typ := tc.type_cache.struct_field_entries[cache_key] {
			return typ
		}
		if tc.type_cache.struct_field_misses[cache_key] {
			return none
		}
	}
	mut seen := map[string]bool{}
	if typ := tc.struct_field_type_inner(struct_name, field_name, mut seen) {
		if !isnil(tc.type_cache) {
			mut cache := tc.type_cache
			cache.struct_field_entries[cache_key] = typ
		}
		return typ
	}
	if !isnil(tc.type_cache) {
		mut cache := tc.type_cache
		cache.struct_field_misses[cache_key] = true
	}
	return none
}

// struct_field_type_name returns the canonical type name for a struct field.
pub fn (tc &TypeChecker) struct_field_type_name(struct_name string, field_name string) ?string {
	typ := tc.struct_field_type(struct_name, field_name) or { return none }
	return typ.name()
}

fn (tc &TypeChecker) struct_field_type_inner(struct_name string, field_name string, mut seen map[string]bool) ?Type {
	base_name, generic_args, is_generic := generic_type_application_parts(struct_name)
	lookup_name := if is_generic { base_name } else { struct_name }
	if lookup_name in seen {
		return none
	}
	seen[lookup_name] = true
	fields := tc.structs[lookup_name] or { []StructField{} }
	// The struct's own fields shadow promoted/embedded ones regardless of
	// declaration order, so scan all direct fields before any embed.
	for field in fields {
		if field.name == field_name {
			if is_generic {
				return tc.substitute_generic_type(field.typ, generic_args, tc.struct_generic_params[base_name] or {
					[]string{}
				})
			}
			return field.typ
		}
	}
	for field in fields {
		mut embedded_type := embedded_field_type(field) or { continue }
		embedded_type = if is_generic {
			tc.substitute_generic_type(embedded_type, generic_args, tc.struct_generic_params[base_name] or {
				[]string{}
			})
		} else {
			embedded_type
		}
		embedded_name := method_type_name(unwrap_pointer(embedded_type))
		embedded_lookup_type := if embedded_type is Alias {
			embedded_type.base_type
		} else {
			embedded_type
		}
		embedded_lookup_name := method_type_name(unwrap_pointer(embedded_lookup_type))
		if embedded_name.len == 0 {
			continue
		}
		// A `mod.Inner` embed is promoted under its short name: `o.Inner`.
		// Same-module embeds already match the direct-field pass above.
		if embedded_name != field_name && embedded_name.all_after_last('.') == field_name {
			return embedded_type
		}
		embedded_base_name, _, embedded_is_generic := generic_type_application_parts(embedded_name)
		if embedded_is_generic && embedded_base_name.all_after_last('.') == field_name {
			return embedded_type
		}
		if embedded_lookup_name.len > 0 && embedded_lookup_name != field_name
			&& embedded_lookup_name.all_after_last('.') == field_name {
			return embedded_type
		}
		if typ := tc.struct_field_type_inner(embedded_lookup_name, field_name, mut seen) {
			return typ
		}
	}
	return none
}

// substitute_generic_type replaces generic placeholders in `typ` with the concrete
// `args`. When `param_names` (the struct/fn's declared type parameters, e.g.
// `['L', 'R']`) is provided, a placeholder is matched to its arg by its declared
// position — so `Pair[L, R]`'s `R` resolves to `args[1]`, not the letter-based
// `generic_param_index` guess (which maps any unrecognised name to 0). The
// letter-based fallback is kept only for callers that have no declared names.
fn (tc &TypeChecker) substitute_generic_type(typ Type, args []string, param_names []string) Type {
	if args.len == 0 {
		return typ
	}
	if typ is Unknown {
		if name := generic_placeholder_from_unknown(typ) {
			mut idx := if param_names.len > 0 { param_names.index(name) } else { -1 }
			if idx < 0 {
				idx = generic_param_index(name)
			}
			if idx >= 0 && idx < args.len {
				return tc.parse_type(trimmed_space(args[idx]))
			}
		}
		return typ
	}
	if typ is Array {
		return Type(Array{
			elem_type: tc.substitute_generic_type(typ.elem_type, args, param_names)
		})
	}
	if typ is ArrayFixed {
		return Type(ArrayFixed{
			elem_type: tc.substitute_generic_type(typ.elem_type, args, param_names)
			len:       typ.len
			len_expr:  typ.len_expr
		})
	}
	if typ is Map {
		return Type(Map{
			key_type:   tc.substitute_generic_type(typ.key_type, args, param_names)
			value_type: tc.substitute_generic_type(typ.value_type, args, param_names)
		})
	}
	if typ is Pointer {
		return Type(Pointer{
			base_type: tc.substitute_generic_type(typ.base_type, args, param_names)
		})
	}
	if typ is OptionType {
		base_type := tc.substitute_generic_type(typ.base_type, args, param_names)
		if base_type is OptionType {
			return base_type
		}
		return Type(OptionType{
			base_type: base_type
		})
	}
	if typ is ResultType {
		base_type := tc.substitute_generic_type(typ.base_type, args, param_names)
		if base_type is ResultType {
			return base_type
		}
		return Type(ResultType{
			base_type: base_type
		})
	}
	if typ is Alias {
		return Type(Alias{
			name:      subst_generic_text(typ.name, args, param_names)
			base_type: tc.substitute_generic_type(typ.base_type, args, param_names)
		})
	}
	if typ is SumType {
		if typ.name.contains('[') {
			return tc.parse_type(subst_generic_text(typ.name, args, param_names))
		}
		return typ
	}
	if typ is FnType {
		mut params := []Type{}
		for param in typ.params {
			params << tc.substitute_generic_type(param, args, param_names)
		}
		return Type(FnType{
			params:      params
			return_type: tc.substitute_generic_type(typ.return_type, args, param_names)
		})
	}
	if typ is MultiReturn {
		mut parts := []Type{}
		for part in typ.types {
			parts << tc.substitute_generic_type(part, args, param_names)
		}
		return Type(MultiReturn{
			types: parts
		})
	}
	return typ
}

// substitute_generic_type_values replaces generic placeholders with already
// resolved semantic types. Unlike the text-based variant, it cannot reinterpret
// a caller-local type name in the generic declaration's module.
fn (tc &TypeChecker) substitute_generic_type_values(typ Type, args []Type, param_names []string) Type {
	if args.len == 0 {
		return typ
	}
	if typ is Unknown {
		if name := generic_placeholder_from_unknown(typ) {
			idx := if param_names.len > 0 {
				param_names.index(name)
			} else {
				generic_param_index(name)
			}
			if idx >= 0 && idx < args.len {
				return args[idx]
			}
		}
		return typ
	}
	if typ is Array {
		return Type(Array{
			elem_type: tc.substitute_generic_type_values(typ.elem_type, args, param_names)
		})
	}
	if typ is ArrayFixed {
		return Type(ArrayFixed{
			elem_type: tc.substitute_generic_type_values(typ.elem_type, args, param_names)
			len:       typ.len
			len_expr:  typ.len_expr
		})
	}
	if typ is Map {
		return Type(Map{
			key_type:   tc.substitute_generic_type_values(typ.key_type, args, param_names)
			value_type: tc.substitute_generic_type_values(typ.value_type, args, param_names)
		})
	}
	if typ is Pointer {
		return Type(Pointer{
			base_type: tc.substitute_generic_type_values(typ.base_type, args, param_names)
		})
	}
	if typ is OptionType {
		base_type := tc.substitute_generic_type_values(typ.base_type, args, param_names)
		if base_type is OptionType {
			return base_type
		}
		return Type(OptionType{
			base_type: base_type
		})
	}
	if typ is ResultType {
		base_type := tc.substitute_generic_type_values(typ.base_type, args, param_names)
		if base_type is ResultType {
			return base_type
		}
		return Type(ResultType{
			base_type: base_type
		})
	}
	if typ is FnType {
		mut params := []Type{cap: typ.params.len}
		for param in typ.params {
			params << tc.substitute_generic_type_values(param, args, param_names)
		}
		return Type(FnType{
			params:      params
			return_type: tc.substitute_generic_type_values(typ.return_type, args, param_names)
		})
	}
	if typ is MultiReturn {
		mut parts := []Type{cap: typ.types.len}
		for part in typ.types {
			parts << tc.substitute_generic_type_values(part, args, param_names)
		}
		return Type(MultiReturn{
			types: parts
		})
	}
	return typ
}

fn (tc &TypeChecker) embedded_method_call_info(struct_name string, method string) ?CallInfo {
	mut seen := map[string]bool{}
	return tc.embedded_method_call_info_inner(struct_name, method, mut seen)
}

fn (tc &TypeChecker) embedded_method_call_info_inner(struct_name string, method string, mut seen map[string]bool) ?CallInfo {
	if seen[struct_name] {
		return none
	}
	seen[struct_name] = true
	for field in tc.struct_fields_for_type(struct_name) {
		embedded_type := embedded_field_type(field) or { continue }
		receiver := method_type_name(unwrap_pointer(embedded_type))
		if receiver.len == 0 {
			continue
		}
		// An embedded concrete generic receiver (`Collector[int]`) promotes the
		// method registered on its open declaration (`Collector[T].use`).
		if info := tc.resolve_generic_struct_method(receiver, method) {
			return info
		}
		mut method_names := ['${receiver}.${method}']
		base_name, _, is_generic := generic_type_application_parts(receiver)
		if is_generic {
			method_names << '${base_name}.${method}'
		}
		for method_name in method_names {
			if method_name in tc.fn_ret_types {
				info := tc.call_info(method_name, true)
				return CallInfo{
					name:          info.name
					params:        info.params
					shared_params: info.shared_params
					return_type:   info.return_type
					has_receiver:  info.has_receiver
					is_variadic:   info.is_variadic
					is_c_variadic: info.is_c_variadic
					params_known:  if receiver.contains('[') { false } else { info.params_known }
				}
			}
		}
		if info := tc.embedded_method_call_info_inner(receiver, method, mut seen) {
			return info
		}
	}
	return none
}

fn (tc &TypeChecker) struct_has_middleware_receiver(struct_name string) bool {
	if is_middleware_type_name(struct_name) {
		return true
	}
	for field in tc.struct_fields_for_type(struct_name) {
		embedded_type := embedded_field_type(field) or { continue }
		embedded_name := method_type_name(unwrap_pointer(embedded_type))
		if is_middleware_type_name(embedded_name) {
			return true
		}
	}
	return false
}

fn is_middleware_type_name(name string) bool {
	base := if name.contains('[') { name.all_before('[') } else { name }
	return base == 'veb.Middleware'
}

fn (tc &TypeChecker) receiver_embeds(actual Type, expected Type) bool {
	actual_name := method_type_name(unwrap_all_pointers(actual))
	expected_name := method_type_name(unwrap_all_pointers(expected))
	if actual_name.len == 0 || expected_name.len == 0 {
		return false
	}
	mut seen := map[string]bool{}
	return tc.receiver_embeds_inner(actual_name, expected_name, mut seen)
}

fn (tc &TypeChecker) receiver_embeds_inner(actual_name string, expected_name string, mut seen map[string]bool) bool {
	if seen[actual_name] {
		return false
	}
	seen[actual_name] = true
	for field in tc.struct_fields_for_type(actual_name) {
		embedded_type := embedded_field_type(field) or { continue }
		embedded_name := method_type_name(unwrap_pointer(embedded_type))
		if embedded_name == expected_name {
			return true
		}
		if tc.receiver_embeds_inner(embedded_name, expected_name, mut seen) {
			return true
		}
	}
	return false
}

// trimmed_space is an allocation-free fast path for trim_space: type texts on
// the checker's hot paths are almost always already clean, and builtin trim
// clones even when there is nothing to trim.
@[inline]
fn trimmed_space(s string) string {
	if s.len == 0 {
		return s
	}
	c0 := s[0]
	cl := s[s.len - 1]
	if c0 != ` ` && c0 != `\n` && c0 != `\t` && c0 != `\v` && c0 != `\f` && c0 != `\r` && cl != ` `
		&& cl != `\n` && cl != `\t` && cl != `\v` && cl != `\f` && cl != `\r` {
		return s
	}
	return s.trim_space()
}

fn embedded_field_type(field StructField) ?Type {
	field_type_name := method_type_name(unwrap_pointer(field.typ))
	if field_type_name.len == 0 {
		return none
	}
	if field.name.len == 0 {
		return field.typ
	}
	if embedded_name_matches(field.name, field_type_name) {
		return field.typ
	}
	base_name, _, is_generic := generic_type_application_parts(field_type_name)
	if is_generic && embedded_name_matches(field.name, base_name) {
		return field.typ
	}
	return none
}

// embedded_name_matches reports whether `field_name` equals `type_name` or its
// last dotted segment. Field names cannot contain `.`, so a suffix match with a
// `.` boundary is exactly the old `all_after_last('.')` comparison without the
// substring allocation (this runs per struct field on very hot lookup paths).
@[direct_array_access]
fn embedded_name_matches(field_name string, type_name string) bool {
	if field_name == type_name {
		return true
	}
	if type_name.len > field_name.len && type_name.ends_with(field_name) {
		return type_name[type_name.len - field_name.len - 1] == `.`
	}
	return false
}

// method_signature_compatible supports method signature compatible handling for TypeChecker.
fn (tc &TypeChecker) method_signature_compatible(actual_key string, expected_key string) bool {
	actual_params := tc.fn_param_types[actual_key] or { return false }
	expected_params := tc.fn_param_types[expected_key] or { return false }
	if actual_params.len != expected_params.len {
		return false
	}
	method := expected_key.all_after_last('.')
	expected_owner := expected_key.all_before_last('.')
	actual_owner := actual_key.all_before_last('.')
	expected_receiver_mut, expected_receiver_shared := tc.interface_method_receiver_flags(expected_owner,
		method, true)
	actual_receiver_mut, actual_receiver_shared := tc.interface_method_receiver_flags(actual_owner,
		method, false)
	if expected_receiver_mut && actual_receiver_shared && !expected_receiver_shared {
		return false
	}
	if !expected_receiver_mut && actual_receiver_mut && !actual_receiver_shared {
		return false
	}
	for i in 1 .. actual_params.len {
		if !tc.method_param_signature_compatible(actual_params[i], expected_params[i]) {
			return false
		}
	}
	actual_ret := tc.fn_ret_types[actual_key] or { Type(void_) }
	expected_ret := tc.fn_ret_types[expected_key] or { Type(void_) }
	return actual_ret.name() == expected_ret.name()
}

fn (tc &TypeChecker) method_call_info_signature_compatible(actual CallInfo, expected_key string) bool {
	expected_params := tc.fn_param_types[expected_key] or { return false }
	if actual.params.len != expected_params.len {
		return false
	}
	for i in 1 .. actual.params.len {
		if !tc.method_param_signature_compatible(actual.params[i], expected_params[i]) {
			return false
		}
	}
	expected_ret := tc.fn_ret_types[expected_key] or { Type(void_) }
	return actual.return_type.name() == expected_ret.name()
}

fn (tc &TypeChecker) method_param_signature_compatible(actual Type, expected Type) bool {
	if type_pointer_depth(actual) != type_pointer_depth(expected) {
		return false
	}
	if actual_iface := tc.method_param_interface_name(actual) {
		expected_iface := tc.method_param_interface_name(expected) or { return false }
		return actual_iface == expected_iface
	}
	if _ := tc.method_param_interface_name(expected) {
		return false
	}
	return tc.type_compatible(actual, expected) && tc.type_compatible(expected, actual)
}

fn (tc &TypeChecker) method_param_interface_name(typ Type) ?string {
	clean := unwrap_pointer(typ)
	if clean is Interface {
		return tc.interface_metadata_name(clean.name)
	}
	name := clean.name()
	if name in tc.interface_names {
		return tc.interface_metadata_name(name)
	}
	return none
}

fn type_pointer_depth(t Type) int {
	if t is Pointer {
		return 1 + type_pointer_depth(t.base_type)
	}
	if t is Alias {
		return type_pointer_depth(t.base_type)
	}
	return 0
}

// method_type_name supports method type name handling for types.
fn method_type_name(t Type) string {
	if t is Alias {
		return t.name
	}
	if t is Struct {
		return t.name
	}
	if t is Interface {
		return t.name
	}
	if t is SumType {
		return t.name
	}
	if t is Enum {
		return t.name
	}
	if t is String {
		return 'string'
	}
	if t is Char {
		return 'char'
	}
	if t is Primitive {
		return prim_name(t)
	}
	if t is ISize {
		return 'isize'
	}
	if t is USize {
		return 'usize'
	}
	if t is Rune {
		return 'rune'
	}
	return ''
}

fn (tc &TypeChecker) sum_base_name(sum_name string) string {
	base, _, ok := generic_type_application_parts(sum_name)
	if ok {
		return base
	}
	if sum_name in tc.sum_types {
		return sum_name
	}
	qname := tc.qualify_name(sum_name)
	if qname in tc.sum_types {
		return qname
	}
	if sum_name.contains('.') {
		resolved := tc.resolve_imported_type_text(sum_name)
		if resolved in tc.sum_types {
			return resolved
		}
		if unique := tc.unique_qualified_type_name(sum_name.all_after_last('.')) {
			if unique in tc.sum_types {
				return unique
			}
		}
	}
	return sum_name
}

fn (tc &TypeChecker) sum_params_for_base(base string) []string {
	if params := tc.sum_generic_params[base] {
		return params
	}
	short := base.all_after_last('.')
	if params := tc.sum_generic_params[short] {
		return params
	}
	return []string{}
}

fn (tc &TypeChecker) concrete_sum_variant_name(sum_name string, variant string) string {
	base, args, ok := generic_type_application_parts(sum_name)
	if !ok {
		return variant
	}
	params := tc.sum_params_for_base(base)
	if params.len == 0 || params.len != args.len {
		return variant
	}
	return subst_generic_text(variant, args, params)
}

pub fn (tc &TypeChecker) generic_type_name_matches(a string, b string) bool {
	if a == b {
		return true
	}
	if tc.fixed_array_type_name_matches(a, b) {
		return true
	}
	a_base, a_args, a_ok := generic_type_application_parts(a)
	b_base, b_args, b_ok := generic_type_application_parts(b)
	if a_ok || b_ok {
		if !a_ok || !b_ok || a_args.len != b_args.len {
			return false
		}
		if !tc.generic_type_base_matches(a_base, b_base) {
			return false
		}
		for i in 0 .. a_args.len {
			if !tc.generic_type_arg_matches(a_args[i], b_args[i]) {
				return false
			}
		}
		return true
	}
	return tc.generic_type_base_matches(a, b)
}

fn (tc &TypeChecker) fixed_array_type_name_matches(a string, b string) bool {
	if !fixed_array_type_name_may_be(a) || !fixed_array_type_name_may_be(b) {
		return false
	}
	a_type := tc.parse_type(a)
	b_type := tc.parse_type(b)
	if a_type is ArrayFixed && b_type is ArrayFixed {
		return tc.fixed_array_lengths_compatible(a_type, b_type)
			&& tc.generic_type_name_matches(a_type.elem_type.name(), b_type.elem_type.name())
	}
	return false
}

fn fixed_array_type_name_may_be(s string) bool {
	clean := trimmed_space(s)
	if clean.len == 0 || clean.starts_with('[]') || clean.starts_with('map[') {
		return false
	}
	if clean.starts_with('[') {
		end := find_matching_bracket(clean, 0)
		return end > 0 && end + 1 < clean.len
	}
	if !clean.ends_with(']') {
		return false
	}
	bracket := clean.last_index_u8(`[`)
	bracket_end := clean.last_index_u8(`]`)
	if bracket <= 0 || bracket_end <= bracket {
		return false
	}
	return is_fixed_array_len_text(clean[bracket + 1..bracket_end])
}

fn (tc &TypeChecker) generic_type_base_matches(a string, b string) bool {
	a_clean := trimmed_space(a)
	b_clean := trimmed_space(b)
	if a_clean == b_clean {
		return true
	}
	a_resolved := tc.resolve_generic_match_base(a_clean)
	b_resolved := tc.resolve_generic_match_base(b_clean)
	if a_resolved == b_resolved {
		return true
	}
	if a_clean.contains('.') || b_clean.contains('.') || a_resolved.contains('.')
		|| b_resolved.contains('.') {
		return false
	}
	return short_type_name(a_clean) == short_type_name(b_clean)
}

fn (tc &TypeChecker) resolve_generic_match_base(base string) string {
	if base.len == 0 {
		return base
	}
	if base.contains('.') {
		return tc.resolve_imported_type_text(base)
	}
	if resolved := tc.resolve_selective_import_type_symbol(base) {
		return resolved
	}
	qbase := tc.qualify_name(base)
	if qbase != base && tc.type_symbol_known(qbase) {
		return qbase
	}
	return base
}

fn (tc &TypeChecker) generic_type_arg_matches(a string, b string) bool {
	a_clean := trimmed_space(a)
	b_clean := trimmed_space(b)
	if a_clean == b_clean {
		return true
	}
	if tc.generic_match_arg_is_open_param(a_clean) || tc.generic_match_arg_is_open_param(b_clean) {
		return true
	}
	if a_clean.starts_with('&') || b_clean.starts_with('&') {
		return a_clean.starts_with('&') && b_clean.starts_with('&')
			&& tc.generic_type_arg_matches(a_clean[1..], b_clean[1..])
	}
	if a_clean.starts_with('mut ') || b_clean.starts_with('mut ') {
		return a_clean.starts_with('mut ') && b_clean.starts_with('mut ')
			&& tc.generic_type_arg_matches(a_clean[4..], b_clean[4..])
	}
	if a_clean.starts_with('?') || b_clean.starts_with('?') {
		return a_clean.starts_with('?') && b_clean.starts_with('?')
			&& tc.generic_type_arg_matches(a_clean[1..], b_clean[1..])
	}
	if a_clean.starts_with('!') || b_clean.starts_with('!') {
		return a_clean.starts_with('!') && b_clean.starts_with('!')
			&& tc.generic_type_arg_matches(a_clean[1..], b_clean[1..])
	}
	if a_clean.starts_with('...') || b_clean.starts_with('...') {
		return a_clean.starts_with('...') && b_clean.starts_with('...')
			&& tc.generic_type_arg_matches(a_clean[3..], b_clean[3..])
	}
	if a_clean.starts_with('[]') || b_clean.starts_with('[]') {
		return a_clean.starts_with('[]') && b_clean.starts_with('[]')
			&& tc.generic_type_arg_matches(a_clean[2..], b_clean[2..])
	}
	if a_clean.starts_with('map[') || b_clean.starts_with('map[') {
		if !a_clean.starts_with('map[') || !b_clean.starts_with('map[') {
			return false
		}
		a_bracket_end := find_matching_bracket(a_clean, 3)
		b_bracket_end := find_matching_bracket(b_clean, 3)
		if a_bracket_end >= a_clean.len || b_bracket_end >= b_clean.len {
			return false
		}
		return tc.generic_type_arg_matches(a_clean[4..a_bracket_end], b_clean[4..b_bracket_end])
			&& tc.generic_type_arg_matches(a_clean[a_bracket_end + 1..], b_clean[b_bracket_end + 1..])
	}
	if a_clean.starts_with('[') || b_clean.starts_with('[') {
		if !a_clean.starts_with('[') || !b_clean.starts_with('[') {
			return false
		}
		a_bracket_end := find_matching_bracket(a_clean, 0)
		b_bracket_end := find_matching_bracket(b_clean, 0)
		if a_bracket_end >= a_clean.len || b_bracket_end >= b_clean.len
			|| a_clean[..a_bracket_end + 1] != b_clean[..b_bracket_end + 1] {
			return false
		}
		return tc.generic_type_arg_matches(a_clean[a_bracket_end + 1..],
			b_clean[b_bracket_end + 1..])
	}
	a_base, a_args, a_ok := generic_type_application_parts(a_clean)
	b_base, b_args, b_ok := generic_type_application_parts(b_clean)
	if a_ok || b_ok {
		if !a_ok || !b_ok || a_args.len != b_args.len {
			return false
		}
		if !tc.generic_type_base_matches(a_base, b_base) {
			return false
		}
		for i in 0 .. a_args.len {
			if !tc.generic_type_arg_matches(a_args[i], b_args[i]) {
				return false
			}
		}
		return true
	}
	a_resolved := tc.resolve_generic_match_arg(a_clean)
	b_resolved := tc.resolve_generic_match_arg(b_clean)
	if a_resolved == b_resolved {
		return true
	}
	return false
}

fn (tc &TypeChecker) generic_match_arg_is_open_param(arg string) bool {
	return is_bare_generic_param(arg) && !tc.is_known_type_text(arg)
}

fn (tc &TypeChecker) resolve_generic_match_arg(arg string) string {
	if arg.len == 0 {
		return arg
	}
	if !arg.contains('.') {
		if resolved := tc.resolve_selective_import_type_symbol(arg) {
			return resolved
		}
	}
	qarg := tc.qualify_type_text(arg)
	if qarg.len > 0 {
		return qarg
	}
	return arg
}

fn (tc &TypeChecker) bare_variant_name_matches(candidate string, declared string, concrete string) bool {
	if generic_type_application(candidate) {
		return false
	}
	candidate_base := trimmed_space(candidate)
	declared_base := strip_generic_args_name(declared).trim_space()
	concrete_base := strip_generic_args_name(concrete).trim_space()
	candidate_resolved := tc.resolve_generic_match_base(candidate_base)
	declared_resolved := tc.resolve_generic_match_base(declared_base)
	concrete_resolved := tc.resolve_generic_match_base(concrete_base)
	if candidate_resolved == declared_resolved || candidate_resolved == concrete_resolved {
		return true
	}
	if candidate_base.contains('.') || candidate_resolved.contains('.') {
		return false
	}
	return (!declared_base.contains('.') && candidate_base == short_type_name(declared_base))
		|| (!concrete_base.contains('.') && candidate_base == short_type_name(concrete_base))
}

// type_matches_sum returns type matches sum data for TypeChecker.
fn (tc &TypeChecker) type_matches_sum(actual Type, expected Type) bool {
	if expected is SumType {
		actual_name := actual.name()
		if tc.sum_variant_type_for_pattern(expected.name, actual_name) != none {
			return true
		}
		base := tc.sum_base_name(expected.name)
		variants := tc.sum_types[base] or { return false }
		for variant in variants {
			concrete := tc.concrete_sum_variant_name(expected.name, variant)
			variant_type := tc.parse_type(concrete)
			if variant_type.name() == expected.name {
				continue
			}
			if tc.type_compatible(actual, variant_type) {
				return true
			}
		}
	}
	return false
}

// sum_has_variant converts sum has variant data for types.
fn (tc &TypeChecker) sum_has_variant(sum_name string, variant_name string) bool {
	return tc.sum_variant_type_for_pattern(sum_name, variant_name) != none
}

pub fn (tc &TypeChecker) sum_variant_type_for_pattern(sum_name string, variant_name string) ?string {
	return tc.sum_variant_type_for_pattern_depth(sum_name, variant_name, 0)
}

fn (tc &TypeChecker) sum_variant_type_for_pattern_depth(sum_name string, variant_name string, depth int) ?string {
	if depth >= 16 {
		return none
	}
	base := tc.sum_base_name(sum_name)
	variants := tc.sum_types[base] or { return none }
	mut candidates := [variant_name]
	qvariant := tc.qualify_name(variant_name)
	if qvariant != variant_name {
		candidates << qvariant
	}
	if variant_name.contains('.') {
		resolved := tc.resolve_imported_type_text(variant_name)
		if resolved != variant_name {
			candidates << resolved
		}
		// `all_after_last('.')` on a container pattern (`map[string]ast.Value`)
		// strips the container and would resolve to the sum type itself.
		if !variant_name.contains('[') && !variant_name.contains(']') {
			if unique := tc.unique_qualified_type_name(variant_name.all_after_last('.')) {
				candidates << unique
			}
		}
	}
	for candidate in candidates.clone() {
		candidates << tc.alias_target_type_names(candidate)
	}
	for candidate in candidates {
		if tc.generic_type_name_matches(candidate, sum_name)
			|| tc.generic_type_name_matches(candidate, base) {
			return sum_name
		}
	}
	for variant in variants {
		concrete := tc.concrete_sum_variant_name(sum_name, variant)
		for candidate in candidates {
			if tc.generic_type_name_matches(candidate, concrete)
				|| tc.bare_variant_name_matches(candidate, variant, concrete) {
				return concrete
			}
			if is_bare_generic_param(concrete) && !tc.is_known_type_text(concrete) {
				return candidate
			}
		}
		if nested := tc.nested_sum_variant_type_for_pattern(concrete, candidates, depth) {
			return nested
		}
	}
	return none
}

fn (tc &TypeChecker) alias_target_type_names(name string) []string {
	mut result := []string{}
	mut cur := name
	for _ in 0 .. 16 {
		target := tc.alias_target_type_text(cur) or { break }
		typ := tc.parse_type(target)
		target_name := typ.name()
		if target_name.len == 0 || target_name == cur || target_name in result {
			break
		}
		result << target_name
		cur = target_name
	}
	return result
}

fn (tc &TypeChecker) alias_target_type_text(name string) ?string {
	if target := tc.type_aliases[name] {
		return target
	}
	qname := tc.qualify_name(name)
	if target := tc.type_aliases[qname] {
		return target
	}
	if name.contains('.') {
		resolved := tc.resolve_imported_type_text(name)
		if target := tc.type_aliases[resolved] {
			return target
		}
		if unique := tc.unique_qualified_type_name(name.all_after_last('.')) {
			if target := tc.type_aliases[unique] {
				return target
			}
		}
	}
	return none
}

fn (tc &TypeChecker) nested_sum_variant_type_for_pattern(concrete string, candidates []string, depth int) ?string {
	typ := tc.parse_type(concrete)
	nested_name := if typ is SumType {
		typ.name
	} else if typ is Alias && typ.base_type is SumType {
		(typ.base_type as SumType).name
	} else {
		''
	}
	if nested_name.len == 0 {
		return none
	}
	for candidate in candidates {
		if nested := tc.sum_variant_type_for_pattern_depth(nested_name, candidate, depth + 1) {
			return nested
		}
	}
	return none
}

fn (tc &TypeChecker) match_sum_variant_type(subject Type, pattern string) ?Type {
	if subject is SumType {
		variants := tc.sum_types[subject.name] or { return none }
		variant_short := short_type_name(pattern)
		for variant in variants {
			if variant == pattern || short_type_name(variant) == variant_short {
				return tc.parse_type(variant)
			}
		}
		qpattern := tc.qualify_name(pattern)
		if qpattern != pattern {
			for variant in variants {
				if variant == qpattern || short_type_name(variant) == variant_short {
					return tc.parse_type(variant)
				}
			}
		}
		return none
	}
	if tc.type_symbol_known(pattern) {
		return tc.parse_type(pattern)
	}
	if is_builtin_type_name(pattern) {
		return builtin_type_value(pattern)
	}
	return none
}

// match_type_pattern supports match type pattern handling for TypeChecker.
fn (tc &TypeChecker) match_type_pattern(node &flat.Node) ?string {
	if node.kind == .array_init && node.typ.len > 0 {
		return node.typ
	}
	if node.kind == .ident {
		if node.value.starts_with('fn(') || node.value.starts_with('fn (') {
			return tc.qualify_type_text(node.value)
		}
		return node.value
	}
	if node.kind == .selector && node.children_count > 0 {
		base := tc.a.child_node(node, 0)
		if base.kind == .ident {
			return '${base.value}.${node.value}'
		}
	}
	return none
}

// short_type_name supports short type name handling for types.
fn short_type_name(name string) string {
	if name.contains('.') {
		return name.all_after_last('.')
	}
	return name
}

// type_mismatch returns type mismatch data for TypeChecker.
fn (mut tc TypeChecker) type_mismatch(kind TypeErrorKind, msg string, node flat.NodeId) {
	if tc.should_diagnose(node) {
		tc.record_error(kind, msg, node)
	}
}

// expr_key supports expr key handling for TypeChecker.
fn (tc &TypeChecker) expr_key(id flat.NodeId) string {
	if int(id) < 0 {
		return ''
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .ident {
		if valid_string_data(node.value) {
			return node.value
		}
		return ''
	}
	if node.kind == .selector && node.children_count > 0 {
		base := tc.expr_key(tc.a.child(&node, 0))
		if base.len > 0 && node.value.len > 0 && valid_string_data(node.value) {
			return '${base}.${node.value}'
		}
	}
	if node.kind == .index && node.children_count >= 2 {
		base := tc.expr_key(tc.a.child(&node, 0))
		index_key := tc.expr_key_part(tc.a.child(&node, 1))
		if base.len > 0 && index_key.len > 0 {
			return '${base}[${index_key}]'
		}
	}
	return ''
}

fn (tc &TypeChecker) expr_key_part(id flat.NodeId) string {
	if int(id) < 0 {
		return ''
	}
	node := tc.a.nodes[int(id)]
	match node.kind {
		.ident {
			return node.value
		}
		.int_literal, .string_literal, .char_literal, .enum_val {
			return node.value
		}
		else {
			return tc.expr_key(id)
		}
	}
}

// smartcast_type supports smartcast type handling for TypeChecker.
fn (tc &TypeChecker) smartcast_type(id flat.NodeId) ?Type {
	key := tc.expr_key(id)
	if key.len == 0 {
		return none
	}
	if !valid_string_data(key) {
		return none
	}
	if typ := tc.smartcasts[key] {
		return typ
	}
	return none
}

fn (tc &TypeChecker) smartcast_target_type_for_is_expr(expr_id flat.NodeId, pattern string) Type {
	raw_subject := fn_param_unalias_type(tc.resolve_type(expr_id))
	subject := unalias_and_unwrap_pointer_type(raw_subject)
	if subject is SumType {
		if variant := tc.sum_variant_type_for_pattern(subject.name, pattern) {
			return tc.parse_type(variant)
		}
	}
	if is_ierror_type(subject) {
		if variant := tc.resolve_ierror_match_pattern(pattern) {
			return tc.parse_type(variant)
		}
	}
	if subject is Interface {
		if variant := tc.resolve_interface_match_pattern(pattern) {
			variant_type := tc.parse_type(variant)
			if tc.a.node(expr_id).is_mut && raw_subject is Pointer {
				return Type(Pointer{
					base_type: variant_type
				})
			}
			return variant_type
		}
	}
	return tc.parse_type(pattern)
}

fn (mut tc TypeChecker) invalidate_smartcasts_for_write_key(key string) {
	if key.len == 0 {
		return
	}
	tc.smartcasts.delete(key)
	prefix := '${key}.'
	for child_key in tc.smartcasts.keys() {
		if child_key.starts_with(prefix) {
			tc.smartcasts.delete(child_key)
		}
	}
}

// cached_c_name memoizes naming.c_name results in the type cache (falling
// back to the frozen base cache read-only, like every other entry kind).
// c_name is pure and called on hot resolution paths in every phase.
pub fn (tc &TypeChecker) cached_c_name(name string) string {
	if isnil(tc.type_cache) {
		return naming.c_name(name)
	}
	mut cache := unsafe { tc.type_cache }
	mut fallback := cache.base
	for !isnil(fallback) {
		if cached := fallback.c_name_entries[name] {
			return cached
		}
		fallback = fallback.base
	}
	if cached := cache.c_name_entries[name] {
		return cached
	}
	result := naming.c_name(name)
	cache.c_name_entries[name] = result
	return result
}

// parse_type converts a V type string (from parser) to a structured Type.
// type_text_contains_typeof is a fast substring probe for `typeof(`: type
// texts are overwhelmingly short scalar/container names, so the length
// early-out plus a first-byte scan beats string.contains (KMP table build and
// call overhead) on hot paths that must screen every text.
@[direct_array_access]
pub fn type_text_contains_typeof(s string) bool {
	if s.len < 8 {
		return false
	}
	for i := 0; i + 7 <= s.len; i++ {
		if s[i] == `t` && s[i + 1] == `y` && s[i + 2] == `p` && s[i + 3] == `e` && s[i + 4] == `o`
			&& s[i + 5] == `f` && s[i + 6] == `(` {
			return true
		}
	}
	return false
}

pub fn (tc &TypeChecker) parse_type(typ string) Type {
	// Do this before the memoization lookup. The outer alias expansion is not
	// cached until its complete semantic type exists; caching this symbolic
	// recursive edge would otherwise leave the shallow placeholder as the
	// permanent result for the alias.
	if recursive_alias := tc.recursive_alias_reference(typ) {
		return recursive_alias
	}
	if tc.type_cache != unsafe { nil } && tc.type_cache.parse_enabled {
		mut cache := unsafe { tc.type_cache }
		if cached := parse_type_cache_get(mut cache, tc.cur_file, tc.cur_module, typ,
			tc.fn_context.generic_params, tc.resolution_type_mode)
		{
			cache.parse_hits++
			return cached
		}
		// typeof(...) resolves against expression context, so its result must
		// never enter the cache. Checking only on the miss path keeps the
		// substring scan off the ~2M cache hits (typeof text can never hit:
		// it is never put).
		if type_text_contains_typeof(typ) {
			return tc.parse_type_uncached(typ)
		}
		cache.parse_misses++
		_, result := tc.intern_type(tc.parse_type_uncached(typ))
		parse_type_cache_put(mut cache, tc.cur_file, tc.cur_module, typ,
			tc.fn_context.generic_params, tc.resolution_type_mode, result)
		return result
	}
	if type_text_contains_typeof(typ) {
		return tc.parse_type_uncached(typ)
	}
	_, result := tc.intern_type(tc.parse_type_uncached(typ))
	return result
}

fn (tc &TypeChecker) recursive_alias_reference(typ string) ?Type {
	if isnil(tc.type_cache) || tc.type_cache.alias_parse_stack.len == 0 {
		return none
	}
	clean := typ.trim_space()
	if clean.len == 0 || clean[0] in [`&`, `?`, `!`, `[`, `(`] || clean.starts_with('mut ')
		|| clean.starts_with('shared ') || clean.starts_with('atomic ')
		|| clean.starts_with('chan ') || clean.starts_with('map[') || clean.starts_with('fn(') {
		return none
	}
	mut qualified := clean
	if !clean.contains('.') {
		qualified = tc.qualify_name(clean)
	}
	for i := tc.type_cache.alias_parse_stack.len - 1; i >= 0; i-- {
		name := tc.type_cache.alias_parse_stack[i]
		if clean == name || qualified == name || clean == name.all_after_last('.') {
			return Type(Alias{
				name:      name
				base_type: Type(Unknown{
					reason: 'recursive alias `${name}`'
				})
			})
		}
	}
	return none
}

fn (tc &TypeChecker) parse_alias_type(name string, target string) Type {
	mut cache := unsafe { tc.type_cache }
	if isnil(cache) {
		return Type(Alias{
			name:      name
			base_type: tc.parse_type(target)
		})
	}
	cache.alias_parse_stack << name
	base_type := tc.parse_type(target)
	cache.alias_parse_stack.delete_last()
	return Type(Alias{
		name:      name
		base_type: base_type
	})
}

// parse_canonical_type parses compiler-produced type text while preserving an
// exact known qualified symbol before consulting the current file's import
// aliases. Source text must continue to use parse_type, where aliases take
// precedence; this entry point is for semantic names carried between phases.
pub fn (tc &TypeChecker) parse_canonical_type(typ string) Type {
	clean := trimmed_space(typ)
	if clean.starts_with('&') {
		_, result := tc.intern_type(Type(Pointer{
			base_type: tc.parse_canonical_type(clean[1..])
		}))
		return result
	}
	if clean.starts_with('mut ') {
		_, result := tc.intern_type(Type(Pointer{
			base_type: tc.parse_canonical_type(clean[4..])
		}))
		return result
	}
	if clean.starts_with('shared ') {
		return tc.parse_canonical_type(clean[7..])
	}
	if clean.starts_with('...') {
		_, result := tc.intern_type(Type(Array{
			elem_type: tc.parse_canonical_type(clean[3..])
		}))
		return result
	}
	if clean.starts_with('[]') {
		_, result := tc.intern_type(Type(Array{
			elem_type: tc.parse_canonical_type(clean[2..])
		}))
		return result
	}
	if clean.starts_with('?') {
		_, result := tc.intern_type(Type(OptionType{
			base_type: tc.parse_canonical_type(clean[1..])
		}))
		return result
	}
	if clean.starts_with('!') {
		_, result := tc.intern_type(Type(ResultType{
			base_type: tc.parse_canonical_type(clean[1..])
		}))
		return result
	}
	if known := tc.type_from_known_symbol(clean) {
		_, result := tc.intern_type(known)
		return result
	}
	return tc.parse_type(clean)
}

fn (tc &TypeChecker) probe_intern_type(t Type) ?Type {
	if isnil(tc.type_interner) {
		return none
	}
	return tc.type_interner.probe(t)
}

fn (tc &TypeChecker) intern_type(t Type) (TypeId, Type) {
	if isnil(tc.type_interner) {
		// Only hand-built compatibility checkers can reach this path. Production
		// checkers are created with one compilation-wide interner.
		return TypeId(0), t
	}
	mut interner := unsafe { tc.type_interner }
	return interner.canonicalize(t)
}

// type_count reports the number of unique canonical semantic types observed by
// this compilation.
pub fn (tc &TypeChecker) type_count() int {
	if isnil(tc.type_interner) {
		return 0
	}
	mut interner := unsafe { tc.type_interner }
	return interner.len()
}

// type_name lazily formats and memoizes the canonical spelling of a semantic
// type. Hot compiler paths should prefer this to repeated recursive Type.name
// construction.
pub fn (tc &TypeChecker) type_name(t Type) string {
	if isnil(tc.type_interner) {
		return t.name()
	}
	id, _ := tc.intern_type(t)
	mut interner := unsafe { tc.type_interner }
	return interner.name(id)
}

// type_cache_stats returns cache counters accumulated by this checker.
pub fn (tc &TypeChecker) type_cache_stats() TypeCacheStats {
	if isnil(tc.type_cache) {
		return TypeCacheStats{}
	}
	return TypeCacheStats{
		parse_hits:   tc.type_cache.parse_hits
		parse_misses: tc.type_cache.parse_misses
		c_hits:       tc.type_cache.c_hits
		c_misses:     tc.type_cache.c_misses
	}
}

fn parse_type_cache_context_hash(mut cache TypeCache, file string, module_name string, generic_params []string, resolution bool) u64 {
	if cache.parse_context_valid && cache.parse_context_resolution == resolution
		&& parse_type_cache_string_matches(cache.parse_context_file, file)
		&& parse_type_cache_string_matches(cache.parse_context_module, module_name)
		&& parse_type_cache_strings_match(cache.parse_context_generics, generic_params) {
		return cache.parse_context_hash
	}
	mut hash := u64(14_695_981_039_346_656_037)
	if resolution {
		hash = (hash ^ u64(1)) * u64(1_099_511_628_211)
	}
	hash = parse_type_cache_hash_part(hash, file)
	hash = parse_type_cache_hash_part(hash, module_name)
	hash = (hash ^ u64(generic_params.len)) * u64(1_099_511_628_211)
	for param in generic_params {
		hash = parse_type_cache_hash_part(hash, param)
	}
	cache.parse_context_file = file
	cache.parse_context_module = module_name
	cache.parse_context_generics = generic_params.clone()
	cache.parse_context_resolution = resolution
	cache.parse_context_hash = hash
	cache.parse_context_valid = true
	return hash
}

fn parse_type_cache_hash_part(initial u64, part string) u64 {
	mut hash := initial ^ u64(part.len)
	hash *= u64(1_099_511_628_211)
	for i in 0 .. part.len {
		hash ^= u64(part[i])
		hash *= u64(1_099_511_628_211)
	}
	return hash
}

fn parse_type_cache_next_key(key u64) u64 {
	return key * u64(2_862_933_555_777_941_757) + u64(3_037_000_493)
}

@[inline]
fn parse_type_cache_string_matches(a string, b string) bool {
	if a.len != b.len {
		return false
	}
	if unsafe { a.str == b.str } {
		return true
	}
	return a == b
}

fn parse_type_cache_strings_match(a []string, b []string) bool {
	if a.len != b.len {
		return false
	}
	for i in 0 .. a.len {
		if !parse_type_cache_string_matches(a[i], b[i]) {
			return false
		}
	}
	return true
}

fn parse_type_cache_entry_matches(entry ParseTypeCacheEntry, file string, module_name string, text string, generic_params []string, resolution bool) bool {
	return parse_type_cache_strings_match(entry.generic_params, generic_params)
		&& parse_type_cache_string_matches(entry.file, file)
		&& parse_type_cache_string_matches(entry.module, module_name)
		&& parse_type_cache_string_matches(entry.text, text) && entry.resolution == resolution
}

fn parse_type_cache_get(mut cache TypeCache, file string, module_name string, text string, generic_params []string, resolution bool) ?Type {
	if cache.parse_last_valid
		&& parse_type_cache_entry_matches(cache.parse_last_entry, file, module_name, text, generic_params, resolution) {
		return cache.parse_last_entry.typ
	}
	context_hash := parse_type_cache_context_hash(mut cache, file, module_name, generic_params,
		resolution)
	mut key := parse_type_cache_hash_part(context_hash, text)
	for {
		if entry := cache.parse_entries[key] {
			if parse_type_cache_entry_matches(entry, file, module_name, text, generic_params,
				resolution)
			{
				cache.parse_last_entry = entry
				cache.parse_last_valid = true
				return entry.typ
			}
			key = parse_type_cache_next_key(key)
			continue
		}
		mut fallback := cache.base
		mut fallback_collision := false
		for !isnil(fallback) {
			if entry := fallback.parse_entries[key] {
				if parse_type_cache_entry_matches(entry, file, module_name, text, generic_params,
					resolution)
				{
					cache.parse_last_entry = entry
					cache.parse_last_valid = true
					return entry.typ
				}
				fallback_collision = true
				break
			}
			fallback = fallback.base
		}
		if fallback_collision {
			key = parse_type_cache_next_key(key)
			continue
		}
		return none
	}
	return none
}

fn parse_type_cache_put(mut cache TypeCache, file string, module_name string, text string, generic_params []string, resolution bool, typ Type) {
	context_hash := parse_type_cache_context_hash(mut cache, file, module_name, generic_params,
		resolution)
	mut key := parse_type_cache_hash_part(context_hash, text)
	for {
		if entry := cache.parse_entries[key] {
			if parse_type_cache_entry_matches(entry, file, module_name, text, generic_params,
				resolution)
			{
				return
			}
			key = parse_type_cache_next_key(key)
			continue
		}
		mut fallback := cache.base
		mut fallback_collision := false
		for !isnil(fallback) {
			if entry := fallback.parse_entries[key] {
				if parse_type_cache_entry_matches(entry, file, module_name, text, generic_params,
					resolution)
				{
					return
				}
				fallback_collision = true
				break
			}
			fallback = fallback.base
		}
		if fallback_collision {
			key = parse_type_cache_next_key(key)
			continue
		}
		entry := ParseTypeCacheEntry{
			file:           file
			module:         module_name
			text:           text
			generic_params: generic_params.clone()
			resolution:     resolution
			typ:            typ
		}
		cache.parse_entries[key] = entry
		cache.parse_last_entry = entry
		cache.parse_last_valid = true
		return
	}
}

// parse_scope_param_type preserves open generic struct applications for local parameter
// lookup. The global parser deliberately collapses `Box[T]` to `Box` in signatures, but
// inside a generic function/method body the parameter still needs the open application so
// field lookup and generic receiver method resolution can substitute `T`.
fn (tc &TypeChecker) parse_scope_param_type(typ string) Type {
	clean := trimmed_space(typ)
	if clean.starts_with('...') {
		return Type(Array{
			elem_type: tc.parse_scope_param_type(clean[3..])
		})
	}
	if preserved := tc.parse_open_generic_struct_type(typ) {
		return preserved
	}
	return tc.parse_type(typ)
}

fn (tc &TypeChecker) parse_open_generic_struct_type(typ string) ?Type {
	clean := trimmed_space(typ)
	if clean.len == 0 {
		return none
	}
	if clean.starts_with('&') {
		base := tc.parse_open_generic_struct_type(clean[1..]) or { return none }
		return Type(Pointer{
			base_type: base
		})
	}
	if clean.starts_with('mut ') {
		base := tc.parse_open_generic_struct_type(clean[4..]) or { return none }
		return Type(Pointer{
			base_type: base
		})
	}
	if clean.starts_with('shared ') {
		return tc.parse_open_generic_struct_type(clean[7..])
	}
	if clean.starts_with('atomic ') {
		return tc.parse_open_generic_struct_type(clean[7..])
	}
	if clean.starts_with('?') {
		base := tc.parse_open_generic_struct_type(clean[1..]) or { return none }
		return Type(OptionType{
			base_type: base
		})
	}
	if clean.starts_with('!') {
		base := tc.parse_open_generic_struct_type(clean[1..]) or { return none }
		return Type(ResultType{
			base_type: base
		})
	}
	if clean.starts_with('...') {
		elem := tc.parse_open_generic_struct_type(clean[3..]) or { return none }
		return Type(Array{
			elem_type: elem
		})
	}
	if clean.starts_with('[]') {
		elem := tc.parse_open_generic_struct_type(clean[2..]) or { return none }
		return Type(Array{
			elem_type: elem
		})
	}
	if clean.starts_with('map[') {
		bracket_end := find_matching_bracket(clean, 3)
		if bracket_end < clean.len {
			key := tc.parse_scope_param_type(clean[4..bracket_end])
			value := tc.parse_open_generic_struct_type(clean[bracket_end + 1..]) or { return none }
			return Type(Map{
				key_type:   key
				value_type: value
			})
		}
	}
	if clean.starts_with('[') {
		bracket_end := find_matching_bracket(clean, 0)
		if bracket_end < clean.len {
			elem := tc.parse_open_generic_struct_type(clean[bracket_end + 1..]) or { return none }
			len_text := trimmed_space(clean[1..bracket_end])
			return Type(ArrayFixed{
				elem_type: elem
				len:       if is_decimal_int_literal(len_text) { len_text.int() } else { 0 }
				len_expr:  if is_decimal_int_literal(len_text) { '' } else { len_text }
			})
		}
	}
	base, args, ok := generic_type_application_parts(clean)
	if !ok || tc.generic_args_are_concrete(args) {
		return none
	}
	mut qbase := base
	if !base.contains('.') {
		resolved := tc.qualify_name(base)
		if resolved in tc.structs || resolved in tc.struct_generic_params {
			qbase = resolved
		}
	}
	if qbase !in tc.structs && qbase !in tc.struct_generic_params && base !in tc.structs
		&& base !in tc.struct_generic_params {
		return none
	}
	mut preserved_args := []string{cap: args.len}
	for arg in args {
		trimmed := trimmed_space(arg)
		preserved_args << if is_generic_placeholder_type(trimmed) {
			trimmed.all_after_last('.')
		} else {
			trimmed
		}
	}
	suffix := '[${preserved_args.join(', ')}]'
	return Type(Struct{
		name: qbase + suffix
	})
}

fn (tc &TypeChecker) parse_generic_alias_application(name string, args []string, suffix string) Type {
	target := tc.type_aliases[name]
	params := tc.type_alias_generic_params[name] or {
		tc.type_alias_generic_params[name.all_after_last('.')] or { []string{} }
	}
	if params.len == args.len && params.len > 0 {
		return Type(Alias{
			name:      name + suffix
			base_type: tc.parse_type(subst_generic_text(target, args, params))
		})
	}
	return Type(Alias{
		name:      name
		base_type: tc.parse_type(target)
	})
}

// parse_type_uncached reads parse type uncached input for types.
fn (tc &TypeChecker) parse_type_uncached(typ string) Type {
	if typ.len == 0 {
		return Type(void_)
	}
	if resolved := tc.type_from_typeof_type_text(typ) {
		return resolved
	}
	if trimmed_space(typ).starts_with('typeof(') {
		return unknown_type('unresolved typeof type `${typ}`')
	}
	// Preserve open generic struct applications wherever they occur in a signature or
	// expression type. Qualifying their placeholder (`T` -> `module.T`) makes it look
	// concrete to later stages and can emit invalid C types such as `Box_module__T`.
	if preserved := tc.parse_open_generic_struct_type(typ) {
		return preserved
	}
	if typ.ends_with('.typ') {
		return tc.parse_type(typ[..typ.len - 4])
	}
	if is_generic_placeholder_type(typ) && !tc.is_known_type_text(typ) {
		return unknown_type('generic placeholder `${typ}`')
	}
	// `main.Foo` is an explicit reference to a program-module type. It is used to
	// lock a bare concrete generic argument against being rebased into a callee
	// module that declares a same-named type (see explicit_generic_concrete_arg_text
	// / lock_colliding_main_generic_type_text). Resolve it directly to the bare-keyed
	// program symbol so the resulting type name matches the struct/method tables,
	// unless `main` is an actual import alias in this file.
	if typ.starts_with('main.') && !typ['main.'.len..].contains('.') {
		if _ := tc.resolve_import_alias('main') {
		} else if known := tc.type_from_known_symbol(typ['main.'.len..]) {
			return known
		}
	}
	if typ.starts_with('&') {
		return Type(Pointer{
			base_type: tc.parse_type(typ[1..])
		})
	}
	if typ.starts_with('mut ') {
		return Type(Pointer{
			base_type: tc.parse_type(typ[4..])
		})
	}
	if typ.starts_with('shared ') {
		return tc.parse_type(typ[7..])
	}
	if typ.starts_with('atomic ') {
		return tc.parse_type(typ[7..])
	}
	if typ.starts_with('?') {
		return Type(OptionType{
			base_type: tc.parse_type(typ[1..])
		})
	}
	if typ.starts_with('!') {
		return Type(ResultType{
			base_type: tc.parse_type(typ[1..])
		})
	}
	if typ.starts_with('chan ') {
		elem_text := typ[5..]
		return Type(Channel{
			elem_type: tc.parse_type(elem_text)
			is_mut:    elem_text.starts_with('mut ')
		})
	}
	if typ == 'chan' {
		return Type(Channel{
			elem_type: Type(void_)
		})
	}
	if typ.starts_with('thread ') || typ == 'thread' {
		// A thread handle. The element type (the spawned fn's return type) is kept
		// in the struct name (`thread T`) so `array_of_threads.wait()` can recover
		// `[]T`. The handle itself lowers to `void*` in C (see c_type).
		return Type(Struct{
			name: typ
		})
	}
	if typ.starts_with('...') {
		return Type(Array{
			elem_type: tc.parse_type(typ[3..])
		})
	}
	if typ.starts_with('[]') {
		return Type(Array{
			elem_type: tc.parse_type(typ[2..])
		})
	}
	if typ.starts_with('map[') {
		bracket_end := find_matching_bracket(typ, 3)
		if bracket_end >= typ.len {
			return Type(Unknown{
				reason: 'malformed map type'
			})
		}
		key_str := typ[4..bracket_end]
		val_str := typ[bracket_end + 1..]
		return Type(Map{
			key_type:   tc.parse_type(key_str)
			value_type: tc.parse_type(val_str)
		})
	}
	if fixed_array_type_name_may_be(typ) && !typ.starts_with('[') {
		bracket := typ.last_index_u8(`[`)
		bracket_end := typ.last_index_u8(`]`)
		len_text := trimmed_space(typ[bracket + 1..bracket_end])
		base_text := typ[..bracket]
		if is_decimal_int_literal(len_text) || base_text.contains('[') {
			return Type(ArrayFixed{
				elem_type: tc.parse_type(base_text)
				len:       if is_decimal_int_literal(len_text) { len_text.int() } else { 0 }
				len_expr:  if is_decimal_int_literal(len_text) { '' } else { len_text }
			})
		}
	}
	if typ.starts_with('[') {
		idx := typ.index_u8(`]`)
		if idx > 0 {
			len_text := trimmed_space(typ[1..idx])
			return Type(ArrayFixed{
				elem_type: tc.parse_type(typ[idx + 1..])
				len:       if is_decimal_int_literal(len_text) { len_text.int() } else { 0 }
				len_expr:  if is_decimal_int_literal(len_text) { '' } else { len_text }
			})
		}
	}
	if typ.starts_with('(') && typ.contains(',') {
		inner := typ[1..typ.len - 1]
		parts := split_params(inner)
		mut tuple_types := []Type{}
		for p in parts {
			tuple_types << tc.parse_type(trimmed_space(p))
		}
		return Type(MultiReturn{
			types: tuple_types
		})
	}
	if typ.starts_with('fn(') || typ.starts_with('fn (') {
		return tc.parse_fn_type(typ)
	}
	qtyp := if tc.resolution_type_mode {
		tc.qualify_resolution_type_name(typ)
	} else {
		tc.qualify_name(typ)
	}
	allow_bare_symbol := qtyp == typ
	if typ == 'array' && tc.has_builtins && typ in tc.structs {
		return Type(Struct{
			name: typ
		})
	}
	if typ == 'map' && tc.has_builtins {
		return Type(Struct{
			name: typ
		})
	}
	if typ == 'array' && tc.has_builtins {
		return Type(Struct{
			name: typ
		})
	}
	if is_builtin_type_name(typ) {
		return builtin_type_value(typ)
	}
	if typ == 'unknown' {
		return Type(Unknown{
			reason: 'unknown'
		})
	}
	if qtyp != typ {
		if scoped_type := tc.type_from_known_symbol(qtyp) {
			return scoped_type
		}
	}
	if !typ.contains('.') {
		if resolved := tc.resolve_selective_import_type_symbol(typ) {
			if resolved_type := tc.type_from_known_symbol(resolved) {
				return resolved_type
			}
		}
	}
	if builtin_error_name := tc.resolve_unqualified_builtin_error_struct_name(typ) {
		return Type(Struct{
			name: builtin_error_name
		})
	}
	if typ.starts_with('C.') {
		return Type(Struct{
			name: typ
		})
	}
	if qtyp in tc.type_aliases {
		return tc.parse_alias_type(qtyp, tc.type_aliases[qtyp])
	}
	if allow_bare_symbol && typ in tc.type_aliases {
		return tc.parse_alias_type(typ, tc.type_aliases[typ])
	}
	if qtyp in tc.interface_names {
		return Type(Interface{
			name: qtyp
		})
	}
	if allow_bare_symbol && typ in tc.interface_names {
		return Type(Interface{
			name: typ
		})
	}
	if qtyp in tc.structs {
		return Type(Struct{
			name: qtyp
		})
	}
	if allow_bare_symbol && typ in tc.structs {
		return Type(Struct{
			name: typ
		})
	}
	if qtyp in tc.flag_enums {
		return Type(Enum{
			name:    qtyp
			is_flag: true
		})
	}
	if allow_bare_symbol && typ in tc.flag_enums {
		return Type(Enum{
			name:    typ
			is_flag: true
		})
	}
	if typ.contains('.') {
		short := typ.all_after_last('.')
		if qtyp !in tc.flag_enums && typ !in tc.flag_enums && short in tc.flag_enums {
			return Type(Enum{
				name:    short
				is_flag: true
			})
		}
	}
	if qtyp in tc.enum_names {
		return Type(Enum{
			name: qtyp
		})
	}
	if allow_bare_symbol && typ in tc.enum_names {
		return Type(Enum{
			name: typ
		})
	}
	if typ.contains('.') {
		short := typ.all_after_last('.')
		if qtyp !in tc.enum_names && typ !in tc.enum_names && short in tc.enum_names {
			return Type(Enum{
				name: short
			})
		}
	}
	if qtyp in tc.sum_types {
		return Type(SumType{
			name: qtyp
		})
	}
	if allow_bare_symbol && typ in tc.sum_types {
		return Type(SumType{
			name: typ
		})
	}
	if !typ.contains('.') {
		if resolved := tc.resolve_selective_import_type_symbol(typ) {
			if resolved_type := tc.type_from_known_symbol(resolved) {
				return resolved_type
			}
		}
	}
	if allow_bare_symbol && !typ.contains('.') {
		if resolved := tc.unique_qualified_type_name(typ) {
			if resolved in tc.type_aliases {
				return Type(Alias{
					name:      resolved
					base_type: tc.parse_type(tc.type_aliases[resolved])
				})
			}
			if resolved in tc.structs {
				return Type(Struct{
					name: resolved
				})
			}
			if resolved in tc.interface_names {
				return Type(Interface{
					name: resolved
				})
			}
			if resolved in tc.flag_enums {
				return Type(Enum{
					name:    resolved
					is_flag: true
				})
			}
			if resolved in tc.enum_names {
				return Type(Enum{
					name: resolved
				})
			}
			if resolved in tc.sum_types {
				return Type(SumType{
					name: resolved
				})
			}
		}
	}
	if generic_type_application(typ) {
		bracket := typ.index_u8(`[`)
		base := typ[..bracket]
		resolved_base := tc.resolve_imported_type_text(base)
		generic_suffix := typ[bracket..]
		_, generic_args, _ := generic_type_application_parts(typ)
		is_concrete_generic := tc.generic_args_are_concrete(generic_args)
		struct_generic_suffix := if is_concrete_generic {
			tc.qualified_generic_suffix(generic_args)
		} else {
			generic_suffix
		}
		sum_generic_suffix := if is_concrete_generic {
			tc.qualified_generic_suffix(generic_args)
		} else {
			generic_suffix
		}
		mut qbase := if tc.resolution_type_mode {
			tc.qualify_resolution_type_name(resolved_base)
		} else {
			tc.qualify_name(resolved_base)
		}
		if !resolved_base.contains('.') {
			if resolved := tc.resolve_selective_import_type_symbol(resolved_base) {
				qbase = resolved
			}
		}
		if qbase == resolved_base && resolved_base.contains('.') {
			qbase = tc.resolve_imported_type_text(resolved_base)
		}
		allow_bare_generic_base := qbase == resolved_base
		if qbase in tc.struct_generic_params {
			mut sgp_base := qbase
			if allow_bare_generic_base && qbase !in tc.structs && !resolved_base.contains('.') {
				// The bare key is only a generic-params shadow of an imported struct
				// (e.g. main referencing `Vec2` from `import math.vec { Vec2 }`, which is
				// keyed `vec.Vec2`). Resolve it to the real qualified struct so field/method
				// lookup and c_type match `vec.Vec2[int]`, not a bogus bare `Vec2[int]`.
				if resolved := tc.resolve_selective_import_type_symbol(resolved_base) {
					sgp_base = resolved
				} else if resolved := tc.unique_qualified_type_name(resolved_base) {
					sgp_base = resolved
				}
			}
			return Type(Struct{
				name: sgp_base + struct_generic_suffix
			})
		}
		if qbase in tc.type_aliases {
			return tc.parse_generic_alias_application(qbase, generic_args, struct_generic_suffix)
		}
		if qbase in tc.structs {
			return Type(Struct{
				name: qbase + struct_generic_suffix
			})
		}
		if qbase in tc.interface_names {
			return Type(Interface{
				name: qbase
			})
		}
		if qbase in tc.sum_types {
			return Type(SumType{
				name: qbase + sum_generic_suffix
			})
		}
		if short := tc.imported_type_short_name(resolved_base) {
			// A colliding main-module alias can make legacy module collection retain
			// the imported generic declaration under its semantic short name. Prefer
			// that generic declaration over the same-named alias.
			if short in tc.struct_generic_params || short in tc.structs {
				return Type(Struct{
					name: short + struct_generic_suffix
				})
			}
			if short in tc.sum_generic_params || short in tc.sum_types {
				return Type(SumType{
					name: short + sum_generic_suffix
				})
			}
			if short in tc.interface_names {
				return Type(Interface{
					name: short
				})
			}
			if short in tc.type_aliases {
				return tc.parse_generic_alias_application(short, generic_args,
					struct_generic_suffix)
			}
		}
		if !resolved_base.contains('.') {
			if resolved := tc.resolve_selective_import_type_symbol(resolved_base) {
				if resolved in tc.type_aliases {
					return tc.parse_generic_alias_application(resolved, generic_args,
						struct_generic_suffix)
				}
				if resolved in tc.structs {
					return Type(Struct{
						name: resolved + struct_generic_suffix
					})
				}
				if resolved in tc.interface_names {
					return Type(Interface{
						name: resolved
					})
				}
				if resolved in tc.sum_types {
					return Type(SumType{
						name: resolved + sum_generic_suffix
					})
				}
			}
		}
		if allow_bare_generic_base && resolved_base in tc.type_aliases {
			return tc.parse_generic_alias_application(resolved_base, generic_args,
				struct_generic_suffix)
		}
		if allow_bare_generic_base && resolved_base in tc.structs {
			return Type(Struct{
				name: resolved_base + struct_generic_suffix
			})
		}
		if allow_bare_generic_base && resolved_base in tc.interface_names {
			return Type(Interface{
				name: resolved_base
			})
		}
		if allow_bare_generic_base && resolved_base in tc.sum_types {
			return Type(SumType{
				name: resolved_base + sum_generic_suffix
			})
		}
		if is_concrete_generic && !is_builtin_type_name(resolved_base) {
			// A concrete generic instance (`Vec4[f32]`) is a monomorphized struct, even
			// when the generic base decl has been erased after monomorphization. It is
			// never a fixed array, so don't fall through to the `[N]T` handler below.
			// Qualify an imported base (`Vec4` -> `vec.Vec4`) so its c_type matches the
			// materialized struct (`vec__Vec4_f32`) everywhere it appears. A builtin base
			// (`int[seg_count]`) cannot be a generic application, so let it fall through to
			// the fixed-array handler — its bracket is a const/expression length.
			mut full := qbase + generic_suffix
			if allow_bare_generic_base && !resolved_base.contains('.') {
				if resolved := tc.unique_qualified_type_name(resolved_base) {
					full = resolved + generic_suffix
				}
			}
			return Type(Struct{
				name: full
			})
		}
	}
	if is_generic_placeholder_type(typ) {
		return unknown_type('generic type parameter `${typ}`')
	}
	if typ.contains('[') && !typ.starts_with('[') {
		// Postfix fixed-array name (`ArrayFixed.name()`): the element comes first and
		// each dimension is appended, so the OUTERMOST dimension is the trailing `[N]`
		// (`int[3][2]` is `[2][3]int`). Split on the last bracket pair so a nested fixed
		// array recovers the outer length and recurses into the inner element, instead of
		// taking the first `[N]` and dropping the rest. For a single dimension the last
		// and first brackets coincide, so this matches the previous behaviour.
		bracket := typ.last_index_u8(`[`)
		bracket_end := typ.last_index_u8(`]`)
		if bracket >= 0 && bracket_end > bracket {
			len_text := trimmed_space(typ[bracket + 1..bracket_end])
			return Type(ArrayFixed{
				elem_type: tc.parse_type(typ[..bracket])
				len:       if is_decimal_int_literal(len_text) { len_text.int() } else { 0 }
				len_expr:  if is_decimal_int_literal(len_text) { '' } else { len_text }
			})
		}
	}
	if qtyp != typ {
		return Type(Struct{
			name: qtyp
		})
	}
	return Type(Struct{
		name: typ
	})
}

fn (tc &TypeChecker) type_from_typeof_type_text(typ string) ?Type {
	clean := trimmed_space(typ)
	if !clean.starts_with('typeof(') || !clean.ends_with(')') {
		return none
	}
	inner := trimmed_space(clean[7..clean.len - 1])
	if inner.len == 0 {
		return none
	}
	if inner.ends_with(']') {
		open := inner.last_index_u8(`[`)
		if open > 0 {
			base_text := trimmed_space(inner[..open])
			if base_type := tc.type_from_simple_expr_text(base_text) {
				return tc.resolve_index_base_value_type(unalias_type(base_type))
			}
		}
	}
	return tc.type_from_simple_expr_text(inner)
}

fn (tc &TypeChecker) type_from_simple_expr_text(expr string) ?Type {
	clean := trimmed_space(expr)
	if clean.len == 0 {
		return none
	}
	if typ := tc.cur_scope.lookup(clean) {
		return typ
	}
	if typ := tc.file_scope.lookup(clean) {
		return typ
	}
	qname := tc.qualify_name(clean)
	if qname != clean {
		if typ := tc.file_scope.lookup(qname) {
			return typ
		}
		if typ := tc.const_types[qname] {
			return typ
		}
	}
	if typ := tc.const_types[clean] {
		return typ
	}
	return none
}

fn (tc &TypeChecker) qualified_generic_suffix(args []string) string {
	mut qualified_args := []string{cap: args.len}
	for arg in args {
		// Generic application args may name types from the instantiating
		// module (main's `Foo` inside a json2 specialization).
		qualified_args << tc.qualify_resolution_type_text(arg)
	}
	return '[' + qualified_args.join(', ') + ']'
}

fn (tc &TypeChecker) array_literal_elem_type(node flat.Node) Type {
	if node.children_count == 0 {
		return Type(int_)
	}
	elem_type := tc.array_literal_child_elem_type(tc.a.child(&node, 0))
	mut all_numeric := true
	mut has_f32 := false
	mut has_f64 := false
	mut has_explicit_f64 := false
	for i in 0 .. node.children_count {
		child_id := tc.a.child(&node, i)
		child := tc.a.nodes[int(child_id)]
		child_type := tc.array_literal_child_elem_type(child_id)
		if !(child_type.is_integer() || child_type.is_float()) {
			all_numeric = false
		}
		if child_type.name() == 'f32' {
			has_f32 = true
		}
		if child_type.name() == 'f64' {
			has_f64 = true
			if !tc.is_untyped_float_literal_expr(child) {
				has_explicit_f64 = true
			}
		}
	}
	if all_numeric && has_explicit_f64 {
		return Type(f64_)
	}
	if all_numeric && has_f32 {
		return tc.parse_type('f32')
	}
	if all_numeric && has_f64 {
		return Type(f64_)
	}
	return elem_type
}

fn (tc &TypeChecker) array_literal_child_elem_type(child_id flat.NodeId) Type {
	child := tc.a.nodes[int(child_id)]
	if child.kind == .prefix && child.value == '...' && child.children_count > 0 {
		spread_type := unalias_type(tc.resolve_type(tc.a.child(&child, 0)))
		if spread_type is Array {
			return spread_type.elem_type
		}
		if spread_type is ArrayFixed {
			return spread_type.elem_type
		}
	}
	if alias_type := tc.explicit_alias_constructor_type(child_id) {
		return alias_type
	}
	return tc.array_literal_child_fn_value_type(child_id) or { tc.resolve_type(child_id) }
}

fn (tc &TypeChecker) array_literal_child_fn_value_type(child_id flat.NodeId) ?Type {
	if int(child_id) < 0 || int(child_id) >= tc.a.nodes.len {
		return none
	}
	child := tc.a.nodes[int(child_id)]
	if tc.fn_value_shadowed_by_value(child) {
		return none
	}
	key := tc.fn_value_key(child) or { return none }
	return tc.fn_type_from_key(key)
}

fn (tc &TypeChecker) explicit_alias_constructor_type(id flat.NodeId) ?Type {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return none
	}
	node := tc.a.nodes[int(id)]
	mut type_name := ''
	if node.kind == .cast_expr {
		type_name = node.value
	} else if node.kind == .call && node.children_count > 0 {
		fn_node_id := tc.a.child(&node, 0)
		type_name = tc.type_expr_name(fn_node_id)
	}
	if type_name.len == 0 {
		return none
	}
	qname := tc.qualify_name(type_name)
	if type_name in tc.sum_types {
		return tc.parse_type(type_name)
	}
	if qname in tc.sum_types {
		return tc.parse_type(qname)
	}
	if type_name in tc.type_aliases || qname in tc.type_aliases {
		return tc.parse_type(type_name)
	}
	return none
}

fn (tc &TypeChecker) is_untyped_float_literal_expr(node flat.Node) bool {
	match node.kind {
		.float_literal {
			return true
		}
		.prefix {
			if node.op !in [.plus, .minus] || node.children_count == 0 {
				return false
			}
			return tc.is_untyped_float_literal_expr(tc.a.child_node(&node, 0))
		}
		.paren, .expr_stmt {
			if node.children_count == 0 {
				return false
			}
			return tc.is_untyped_float_literal_expr(tc.a.child_node(&node, 0))
		}
		else {
			return false
		}
	}
}

fn (tc &TypeChecker) is_known_type_text(typ string) bool {
	qtyp := tc.qualify_name(typ)
	if !typ.contains('.') {
		if resolved := tc.resolve_selective_import_type_symbol(typ) {
			return tc.type_symbol_known(resolved)
		}
	}
	return qtyp in tc.structs || qtyp in tc.interface_names || qtyp in tc.enum_names
		|| qtyp in tc.sum_types || qtyp in tc.type_aliases
}

// canonical_qualified_type_name resolves a possibly bare or partially qualified
// type name (e.g. `PoolProcessor` or `pool.PoolProcessor`) to its unique fully
// qualified spelling (`sync.pool.PoolProcessor`). It returns none when the name
// is unknown or when the short name is ambiguous across modules. Backends use
// this to rebuild method/type C names when a receiver type carries only the
// import-local module qualifier instead of the full module path.
pub fn (tc &TypeChecker) canonical_qualified_type_name(name string) ?string {
	return tc.unique_qualified_type_name(name.all_after_last('.'))
}

// unique_qualified_type_name supports unique qualified type name handling for TypeChecker.
fn (tc &TypeChecker) unique_qualified_type_name(short_name string) ?string {
	if short_name.len == 0 {
		return none
	}
	// A full scan of the five type-name maps (with an all_after_last allocation
	// per entry) is far too expensive for a per-expression helper — this is
	// called from qualify_name and sum-variant pattern checks. Build the
	// short-name index once per checker (memoized in the heap-allocated
	// type_cache, so forked parallel workers each build their own).
	mut cache := tc.type_cache
	if isnil(cache) {
		return tc.unique_qualified_type_name_scan(short_name)
	}
	if !cache.short_type_name_index_built {
		mut fallback := cache.base
		for !isnil(fallback) {
			if fallback.short_type_name_index_built {
				found := fallback.short_type_name_index[short_name] or { return none }
				if found.len == 0 {
					return none
				}
				return found
			}
			fallback = fallback.base
		}
		cache.short_type_name_index_built = true
		tc.build_short_type_name_index(mut cache.short_type_name_index)
	}
	found := cache.short_type_name_index[short_name] or { return none }
	// An empty entry marks an ambiguous short name (several qualified types).
	if found.len == 0 {
		return none
	}
	return found
}

// invalidate_short_type_name_index drops memoized type-name-derived indexes;
// callers that add or remove entries in the type-name maps after the checker ran
// (the monomorphizer specializing generic structs/sum types) must invalidate them.
pub fn (tc &TypeChecker) invalidate_short_type_name_index() {
	mut cache := tc.type_cache
	if isnil(cache) {
		return
	}
	cache.ierror_compat_entries.clear()
	cache.ierror_impl_names.clear()
	cache.ierror_impl_names_set = false
	if cache.short_type_name_index_built {
		cache.short_type_name_index_built = false
		cache.short_type_name_index.clear()
	}
}

// register_short_type_name extends an already-built short-name index after
// monomorphization adds a concrete type. A scoped transform must not rebuild
// the entire index from maps whose strings may belong to the checked arena.
pub fn (tc &TypeChecker) register_short_type_name(name string) {
	mut cache := tc.type_cache
	if isnil(cache) {
		return
	}
	if !cache.short_type_name_index_built {
		mut fallback := cache.base
		for !isnil(fallback) && !fallback.short_type_name_index_built {
			fallback = fallback.base
		}
		if isnil(fallback) {
			return
		}
		cache.short_type_name_index = fallback.short_type_name_index.clone()
		cache.short_type_name_index_built = true
	}
	index_short_type_name(name, mut cache.short_type_name_index)
}

// unregister_short_type_name removes an exact cached entry when a generic
// template is erased. Ambiguous entries stay conservative until the next
// compilation-wide index build.
pub fn (tc &TypeChecker) unregister_short_type_name(name string) {
	mut cache := tc.type_cache
	if isnil(cache) {
		return
	}
	if !cache.short_type_name_index_built {
		mut fallback := cache.base
		for !isnil(fallback) && !fallback.short_type_name_index_built {
			fallback = fallback.base
		}
		if isnil(fallback) {
			return
		}
		cache.short_type_name_index = fallback.short_type_name_index.clone()
		cache.short_type_name_index_built = true
	}
	short := name.all_after_last('.')
	if cached := cache.short_type_name_index[short] {
		if cached == name {
			cache.short_type_name_index.delete(short)
		}
	}
}

fn (tc &TypeChecker) build_short_type_name_index(mut index map[string]string) {
	for name, _ in tc.type_aliases {
		index_short_type_name(name, mut index)
	}
	for name, _ in tc.structs {
		index_short_type_name(name, mut index)
	}
	for name, _ in tc.interface_names {
		index_short_type_name(name, mut index)
	}
	for name, _ in tc.enum_names {
		index_short_type_name(name, mut index)
	}
	for name, _ in tc.sum_types {
		index_short_type_name(name, mut index)
	}
}

fn index_short_type_name(name string, mut index map[string]string) {
	short := name.all_after_last('.')
	if short in index {
		prev := index[short]
		if prev != name {
			index[short] = ''
		}
	} else {
		index[short] = name
	}
}

// unique_qualified_type_name_scan is the uncached fallback used when no
// type_cache is attached to the checker.
fn (tc &TypeChecker) unique_qualified_type_name_scan(short_name string) ?string {
	mut found := ''
	for name, _ in tc.type_aliases {
		if name.all_after_last('.') == short_name {
			if found.len > 0 && found != name {
				return none
			}
			found = name
		}
	}
	for name, _ in tc.structs {
		if name.all_after_last('.') == short_name {
			if found.len > 0 && found != name {
				return none
			}
			found = name
		}
	}
	for name, _ in tc.interface_names {
		if name.all_after_last('.') == short_name {
			if found.len > 0 && found != name {
				return none
			}
			found = name
		}
	}
	for name, _ in tc.enum_names {
		if name.all_after_last('.') == short_name {
			if found.len > 0 && found != name {
				return none
			}
			found = name
		}
	}
	for name, _ in tc.sum_types {
		if name.all_after_last('.') == short_name {
			if found.len > 0 && found != name {
				return none
			}
			found = name
		}
	}
	if found.len == 0 {
		return none
	}
	return found
}

// is_generic_placeholder_type reports whether is generic placeholder type applies in types.
fn is_generic_placeholder_type(typ string) bool {
	if typ.contains('.') {
		last := typ.all_after_last('.')
		return is_generic_placeholder_type(last)
	}
	return is_bare_generic_param(typ)
}

// parse_fn_type reads parse fn type input for types.
fn (tc &TypeChecker) parse_fn_type(typ string) Type {
	params_start := typ.index_u8(`(`) + 1
	if params_start <= 0 || params_start >= typ.len {
		return unknown_type('malformed fn type `${typ}`')
	}
	mut depth := 1
	mut params_end := params_start
	for params_end < typ.len {
		if typ[params_end] == `(` {
			depth++
		} else if typ[params_end] == `)` {
			depth--
			if depth == 0 {
				break
			}
		}
		params_end++
	}
	if params_end >= typ.len || depth != 0 {
		return unknown_type('malformed fn type `${typ}`')
	}
	params_str := typ[params_start..params_end]
	ret_str := typ[params_end + 1..].trim_left(' ')
	mut params := []Type{}
	if params_str.trim_space().len > 0 {
		param_parts := split_params(params_str)
		for p in param_parts {
			trimmed := trimmed_space(p)
			param_type := normalize_fn_type_param_text(trimmed)
			params << tc.parse_type(param_type)
		}
	}
	mut ret_type := Type(Void{})
	if ret_str.len > 0 {
		ret_type = tc.parse_type(ret_str)
	}
	return Type(FnType{
		params:      params
		return_type: ret_type
	})
}

fn (tc &TypeChecker) c_abi_fn_ptr_type_from_text(typ string) ?string {
	clean := trimmed_space(typ)
	if !clean.starts_with('fn(') && !clean.starts_with('fn (') {
		return none
	}
	params_start := clean.index_u8(`(`) + 1
	mut depth := 1
	mut params_end := params_start
	for params_end < clean.len {
		if clean[params_end] == `(` {
			depth++
		} else if clean[params_end] == `)` {
			depth--
			if depth == 0 {
				break
			}
		}
		params_end++
	}
	if params_end >= clean.len {
		return none
	}
	params_str := clean[params_start..params_end]
	ret_str := clean[params_end + 1..].trim_left(' ')
	mut params := []string{}
	mut has_c_abi_param := false
	if trimmed_space(params_str).len > 0 {
		for part in split_params(params_str) {
			ct, is_c_abi := tc.c_abi_fn_param_type(part)
			params << ct
			if is_c_abi {
				has_c_abi_param = true
			}
		}
	}
	if !has_c_abi_param {
		return none
	}
	ret_type := if ret_str.len > 0 { tc.parse_type(ret_str) } else { Type(Void{}) }
	ret_ct := tc.fn_ptr_return_c_type(ret_type)
	params_ct := if params.len == 0 { 'void' } else { params.join(', ') }
	return 'fn_ptr:${ret_ct}|${params_ct}'
}

fn (tc &TypeChecker) c_abi_fn_ptr_type_for_type_text(typ string) ?string {
	mut seen := map[string]bool{}
	return tc.c_abi_fn_ptr_type_for_type_text_inner(trimmed_space(typ), mut seen)
}

fn (tc &TypeChecker) c_abi_fn_ptr_type_for_type_text_inner(typ string, mut seen map[string]bool) ?string {
	if typ.len == 0 || seen[typ] {
		return none
	}
	seen[typ] = true
	if c_abi_fn := tc.c_abi_fn_ptr_type_from_text(typ) {
		return c_abi_fn
	}
	for name in [tc.qualify_name(typ), typ] {
		if name.len == 0 {
			continue
		}
		if c_abi_fn := tc.type_alias_c_abi_fns[name] {
			return c_abi_fn
		}
		if target := tc.type_aliases[name] {
			if c_abi_fn := tc.c_abi_fn_ptr_type_for_type_text_inner(target, mut seen) {
				return c_abi_fn
			}
		}
	}
	return none
}

fn (tc &TypeChecker) c_abi_fn_param_type(param string) (string, bool) {
	clean := trimmed_space(param)
	param_type := normalize_fn_type_param_text(clean)
	if c_abi_fn_param_name(clean).starts_with('const_') && param_type.starts_with('&') {
		base_type := tc.parse_type(param_type[1..])
		return 'const ${tc.c_type(base_type)}*', true
	}
	if param_type.starts_with('&') {
		if ct := tc.c_abi_alias_pointer_param_c_type(param_type[1..]) {
			if clean.starts_with('mut ') {
				return '${ct}*', true
			}
			return 'const ${ct}*', true
		}
	}
	return tc.c_type(tc.parse_type(param_type)), false
}

fn (tc &TypeChecker) c_abi_alias_pointer_param_c_type(typ string) ?string {
	t := tc.parse_type(typ)
	if t is Alias {
		base := c_abi_alias_c_base_type(t.base_type) or { return none }
		return tc.c_type(base)
	}
	return none
}

fn c_abi_alias_c_base_type(t Type) ?Type {
	if t is Alias {
		return c_abi_alias_c_base_type(t.base_type)
	}
	if t is Struct && t.name.starts_with('C.') {
		return t
	}
	return none
}

fn c_abi_fn_param_name(param string) string {
	mut text := trimmed_space(param)
	if text.starts_with('mut ') {
		text = trimmed_space(text[4..])
	}
	space := top_level_space_index(text)
	if space <= 0 {
		return ''
	}
	head := trimmed_space(text[..space])
	tail := trimmed_space(text[space + 1..])
	if fn_type_param_head_is_name(head, tail) {
		return head
	}
	return ''
}

fn struct_field_c_abi_key(struct_name string, field_name string) string {
	return '${struct_name}\n${field_name}'
}

fn (tc &TypeChecker) comptime_static_type_expr_name(id flat.NodeId) ?string {
	if int(id) < 0 || int(id) >= tc.a.nodes.len {
		return none
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .array_init && node.value == '__v3_comptime_type_array'
		&& node.children_count == 1 {
		elem := tc.comptime_static_type_expr_name(tc.a.child(&node, 0)) or { return none }
		return '[]${elem}'
	}
	if node.kind != .ident || node.value.len == 0
		|| tc.type_text_has_generic_placeholder(node.value) {
		return none
	}
	return node.value
}

// resolve_type resolves resolve type information for types.
pub fn (tc &TypeChecker) resolve_type(id flat.NodeId) Type {
	if int(id) < 0 {
		return unknown_type('missing node')
	}
	node := tc.a.nodes[int(id)]
	if node.kind == .directive && node.value == '$res' {
		return_type := tc.fn_context.return_type
		if return_type is ResultType || return_type is Void {
			return Type(void_)
		}
		if return_type is MultiReturn {
			if node.children_count == 0 {
				return Type(void_)
			}
			index_node := tc.a.child_node(&node, 0)
			if index_node.kind != .int_literal {
				return Type(void_)
			}
			index := index_node.value.int()
			if index < 0 || index >= return_type.types.len {
				return Type(void_)
			}
			return return_type.types[index]
		}
		return return_type
	}
	if node.kind == .string_literal && node.children_count == 1
		&& node.value in ['__v3_comptime_zero', '__v3_comptime_new'] {
		if type_name := tc.comptime_static_type_expr_name(tc.a.child(&node, 0)) {
			target := tc.parse_type(type_name)
			if target !is Unknown {
				return if node.value == '__v3_comptime_new' {
					Type(Pointer{
						base_type: target
					})
				} else {
					target
				}
			}
		}
	}
	if node.kind == .paren && node.children_count > 0 {
		return tc.resolve_type(tc.a.child(&node, 0))
	}
	if node.kind == .expr_stmt {
		if node.children_count == 0 {
			return Type(void_)
		}
		if node.children_count == 1 {
			return tc.resolve_type(tc.a.child(&node, 0))
		}
		mut expr_types := []Type{cap: node.children_count}
		for i in 0 .. node.children_count {
			value_id := tc.a.child(&node, i)
			typ := tc.expr_type(value_id) or { tc.resolve_type(value_id) }
			expr_types << typ
		}
		return Type(MultiReturn{
			types: expr_types
		})
	}
	kind_id := node_kind_id(node)
	if kind_id == 1 {
		return Type(int_)
	}
	if kind_id == 2 {
		return Type(f64_)
	}
	if kind_id == 3 {
		return Type(bool_)
	}
	if kind_id == 4 {
		if node.value.starts_with('c:') {
			return Type(Pointer{
				base_type: Type(u8_)
			})
		}
		return Type(rune_)
	}
	if kind_id == 5 || kind_id == 6 {
		return Type(string_)
	}
	if kind_id == 28 {
		return Type(voidptr_)
	}
	if kind_id == 29 {
		return Type(OptionType{
			base_type: Type(void_)
		})
	}
	if kind_id == 21 {
		return tc.fn_literal_type(node)
	}
	if kind_id == 32 {
		return tc.lambda_expr_type(node)
	}
	if kind_id == 12 && node.typ.len > 0 && node.typ !in ['int', 'array', 'map', 'unknown'] {
		return tc.parse_type(node.typ)
	}
	if t := tc.resolved_call_type(id) {
		return t
	}
	if kind_id == 22 {
		if aggregate_type := tc.sql_aggregate_or_expr_type(node) {
			return aggregate_type
		}
		if payload := tc.or_expr_payload_type(tc.a.child(&node, 0)) {
			return payload
		}
		inner := tc.resolve_type(tc.a.child(&node, 0))
		if inner is OptionType {
			return inner.base_type
		}
		if inner is ResultType {
			return inner.base_type
		}
		return inner
	}
	if smart_type := tc.smartcast_type(id) {
		return smart_type
	}
	if kind_id == 14 {
		return tc.resolve_index_type(node)
	}
	if !(tc.smartcasts.len > 0 && (kind_id == 7 || kind_id == 13)) {
		if typ := tc.cached_expr_type(id) {
			// A resolution-only annotation can cache `void` for a method whose
			// receiver is a local alias that is only known during body checking.
			// Re-resolve calls in that case instead of hiding the real return type.
			if node.kind != .call || typ !is Void {
				return typ
			}
		}
	}
	if node.kind == .selector {
		if typ := tc.const_type_for_selector(node) {
			return typ
		}
	}
	if node.kind == .defer_result && node.typ == 'invalid' {
		return Type(void_)
	}
	if node.typ.len > 0 && node.typ != 'unknown' && !(kind_id == 12
		&& node.typ in ['int', 'array', 'map']) {
		return tc.parse_type(node.typ)
	}
	match node.kind {
		.int_literal {
			return Type(int_)
		}
		.float_literal {
			return Type(f64_)
		}
		.bool_literal {
			return Type(bool_)
		}
		.char_literal {
			return Type(rune_)
		}
		.string_literal, .string_interp {
			return Type(string_)
		}
		.nil_literal {
			return Type(voidptr_)
		}
		.none_expr {
			return Type(OptionType{
				base_type: Type(void_)
			})
		}
		.spawn_expr {
			if node.children_count == 0 {
				return tc.parse_type('thread')
			}
			child_id := tc.a.child(&node, 0)
			child_node := tc.a.nodes[int(child_id)]
			mut spawn_ret := if child_node.kind == .call {
				tc.spawn_child_call_return_type(child_node) or { tc.resolve_type(child_id) }
			} else {
				tc.resolve_type(child_id)
			}
			if spawn_ret is Unknown && child_node.kind == .call {
				spawn_ret = tc.resolve_type(child_id)
			}
			if spawn_ret is Void || spawn_ret is Unknown {
				return tc.parse_type('thread')
			}
			return tc.parse_type('thread ${spawn_ret.name()}')
		}
		.enum_val {
			return Type(int_)
		}
		.defer_result {
			return tc.defer_result_type(node) or { unknown_type('invalid `res` expression') }
		}
		.ident {
			if node.value == '_' {
				return Type(void_)
			}
			active_generic_ident := node.value in tc.fn_context.generic_params
				|| tc.active_generic_param(node.value)
				|| tc.node_has_enclosing_generic_param(id, node.value)
				|| tc.source_enclosing_fn_has_generic_param(id, node.value)
			if is_bare_generic_param(node.value) && active_generic_ident {
				return unknown_type('generic placeholder `${node.value}`')
			}
			if smart_type := tc.smartcast_type(id) {
				return smart_type
			}
			if typ := tc.non_file_scope_type(node.value) {
